INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (1, 'O SANGUE DE JESUS TEM PODER', 'O SANGUE DE JESUS TEM PODER', 'O SANGUE DE JESUS TEM PODER,\nPODER QUE A MIM PODE VALER,\nSE COMUNHÃO NÃO POSSO EU SENTIR, SENHOR,\nDERRAMA DO TEU SANGUE REMIDOR.\n\nCORO\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nSEI QUE ESTÁS AQUI E ISTO QUERO EU SENTIR,\nDERRAMA DO TEU SANGUE SOBRE MIM.\n\nEM TUA PRESENÇA ESTOU, SENHOR,\nDE TI NECESSITO MUITO AMOR,\nPELO PODER QUE HÁ EM TEU SANGUE REMIDOR,\nÓ VEM PURIFICAR-ME, MEU SENHOR.\n\nCORO\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nSEI QUE ESTÁS AQUI E ISTO QUERO EU SENTIR,\nDERRAMA DO TEU SANGUE SOBRE MIM.', 'O SANGUE DE JESUS TEM PODER,\nPODER QUE A MIM PODE VALER,\nSE COMUNHÃO NÃO POSSO EU SENTIR, SENHOR,\nDERRAMA DO TEU SANGUE REMIDOR.\n\n<coro>\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nSEI QUE ESTÁS AQUI E ISTO QUERO EU SENTIR,\nDERRAMA DO TEU SANGUE SOBRE MIM.\n\nEM TUA PRESENÇA ESTOU, SENHOR,\nDE TI NECESSITO MUITO AMOR,\nPELO PODER QUE HÁ EM TEU SANGUE REMIDOR,\nÓ VEM PURIFICAR-ME, MEU SENHOR.\n\n<coro>\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nDERRAMA DO TEU SANGUE SOBRE MIM, Ó SENHOR,\nSEI QUE ESTÁS AQUI E ISTO QUERO EU SENTIR,\nDERRAMA DO TEU SANGUE SOBRE MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (2, 'O SANGUE DE JESUS TEM PODER PARA SALVAR', 'O SANGUE DE JESUS TEM PODER PARA SALVAR', 'O SANGUE DE JESUS TEM PODER (2x)\nO SANGUE DE JESUS, O SANGUE DE JESUS,\nO SANGUE DE JESUS TEM PODER.\n\nO SANGUE DE JESUS TEM PODER PARA SALVAR,\nO SANGUE DE JESUS TEM PODER PARA CURAR,\nO SANGUE DE JESUS, O SANGUE DE JESUS\nTEM PODER PARA O OPRIMIDO LIBERTAR.', 'O SANGUE DE JESUS TEM PODER <bis tipo=''2''>\nO SANGUE DE JESUS, O SANGUE DE JESUS,\nO SANGUE DE JESUS TEM PODER.\n\nO SANGUE DE JESUS TEM PODER PARA SALVAR,\nO SANGUE DE JESUS TEM PODER PARA CURAR,\nO SANGUE DE JESUS, O SANGUE DE JESUS\nTEM PODER PARA O OPRIMIDO LIBERTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (3, 'CLAMO A TI', 'CLAMO A TI', 'CLAMO A TI, Ó MEU SENHOR,\nCLAMO A TI, MEU SALVADOR,\nPELO TEU SANGUE, QUE É VIDA,\nÓ BENDITO, VEM ME LIBERTAR. \n\nQUANDO ALÉM DO VÉU ENTRAR,\nIREI TE DAR TODO O MEU SER, \nEM TUA PRESENÇA, TE ADORAR,\nTE BENDIZER. \nREPETIR A 1a ESTROFE 1X', 'CLAMO A TI, Ó MEU SENHOR,<bis>\nCLAMO A TI, MEU SALVADOR,<bis>\nPELO TEU SANGUE, QUE É VIDA,<bis>\nÓ BENDITO, VEM ME LIBERTAR. <bis>\n\nQUANDO ALÉM DO VÉU ENTRAR,\nIREI TE DAR TODO O MEU SER,\nEM TUA PRESENÇA, TE ADORAR,\nTE BENDIZER.\n \n<repetir tipo=''A 1A ESTROFE 1X''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (4, 'QUANDO TE PROSTRARES', 'QUANDO TE PROSTRARES', 'QUANDO TE PROSTRARES DIANTE DE DEUS,\nLEMBRA QUE JESUS ESTÁ CONTIGO, \nPEDE SEU AUXÍLIO, PEDE SEU PERDÃO \nLEMBRA QUE JESUS É TEU ABRIGO. \n\nDEIXA QUE O SENHOR\nMUDE O TEU VIVER;\nLEMBRA QUE JESUS É TEU AMIGO.\n\nVENHA SOBRE NÓS, \n(Ó DEUS) VARÕES\nVENHA SOBRE NÓS, \nSEJA SOBRE NÓS A TUA GRAÇA.', 'QUANDO TE PROSTRARES DIANTE DE DEUS,<bis>\nLEMBRA QUE JESUS ESTÁ CONTIGO, <bis>\nPEDE SEU AUXÍLIO, PEDE SEU PERDÃO <bis>\nLEMBRA QUE JESUS É TEU ABRIGO. <bis>\n\nDEIXA QUE O SENHOR\nMUDE O TEU VIVER;\nLEMBRA QUE JESUS É TEU AMIGO.\n\nVENHA SOBRE NÓS, <bis>\n(Ó DEUS) <h><bis>\nVENHA SOBRE NÓS, <bis>\nSEJA SOBRE NÓS A TUA GRAÇA. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (5, 'CLAMANDO ESTOU', 'CLAMANDO ESTOU', 'CLAMANDO ESTOU, Ó MEU JESUS,\nPOR TEU SANGUE REMIDOR;\nSOCORRO EU SEI QUE MANDARÁS\nE LIVRAMENTO A MIM.\n\nTEU SANGUE PURO DERRAMASTE\nPARA ME PURIFICAR;\nENTÃO ADORAREI A TI,\nÓ MEU SENHOR.', 'CLAMANDO ESTOU, Ó MEU JESUS,\nPOR TEU SANGUE REMIDOR;\nSOCORRO EU SEI QUE MANDARÁS\nE LIVRAMENTO A MIM.\n\nTEU SANGUE PURO DERRAMASTE\nPARA ME PURIFICAR;\nENTÃO ADORAREI A TI,\nÓ MEU SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (6, 'JESUS, Ó MEU JESUS', 'JESUS, Ó MEU JESUS', 'JESUS, Ó MEU JESUS,\nNESTA HORA ME CHEGO A TI\nPRA CLAMAR PELO TEU SANGUE\nE SENTIR-TE PERTO DE MIM.\n\nÓ DÁ-ME LIBERTAÇÃO E MUITA COMUNHÃO, \nE PERMITE, Ó SENHOR,\nQUE EU SEJA USADO EM TUAS MÃOS.', 'JESUS, Ó MEU JESUS,\nNESTA HORA ME CHEGO A TI\nPRA CLAMAR PELO TEU SANGUE\nE SENTIR-TE PERTO DE MIM.\n\nÓ DÁ-ME LIBERTAÇÃO E MUITA COMUNHÃO, <bis>\nE PERMITE, Ó SENHOR,<bis>\nQUE EU SEJA USADO EM TUAS MÃOS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (7, 'NESTA HORA EM ORAÇÃO', 'NESTA HORA EM ORAÇÃO', 'NESTA HORA EM ORAÇÃO, \nPEDIMOS O PERDÃO NO SANGUE DE JESUS.\nNESTA HORA EM ORAÇÃO, \nBUSCAMOS COMUNHÃO, PRA ADORAR.\n\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TUA PAZ\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TEU AMOR.\n\nINSTRUMENTOS \n\nNESTA HORA EM ORAÇÃO, \nPEDIMOS O PERDÃO NO SANGUE DE JESUS.\nNESTA HORA EM ORAÇÃO, \nBUSCAMOS COMUNHÃO, PRA ADORAR.\n\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TUA PAZ\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TEU AMOR.', 'NESTA HORA EM ORAÇÃO, \nPEDIMOS O PERDÃO NO SANGUE DE JESUS.\nNESTA HORA EM ORAÇÃO, \nBUSCAMOS COMUNHÃO, PRA ADORAR.\n\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TUA PAZ\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TEU AMOR.\n<instrumentos>\n\n\nNESTA HORA EM ORAÇÃO, \nPEDIMOS O PERDÃO NO SANGUE DE JESUS.\nNESTA HORA EM ORAÇÃO, \nBUSCAMOS COMUNHÃO, PRA ADORAR.\n\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TUA PAZ\nABENÇOA-NOS SENHOR,\nDERRAMA SOBRE NÓS TEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (8, 'PELO SANGUE DE JESUS', 'PELO SANGUE DE JESUS', 'PELO SANGUE DE JESUS\nCLAMO A TI, MEU SENHOR;\nNELE HÁ PERDÃO, PAZ, COMUNHÃO,\nVIDA PARA O MEU SER!\n\nNOS TEUS ÁTRIOS QUERO ENTRAR\nCOBERTO POR ESTE SANGUE,\nPARA TUA GLÓRIA VER E TE ADORAR!\n\nPELO SANGUE DE JESUS\nCLAMO A TI, MEU SENHOR;\nNELE HÁ PERDÃO, PAZ, COMUNHÃO,\nVIDA PARA O MEU SER!\n\nNOS TEUS ÁTRIOS QUERO ENTRAR\nCOBERTO POR ESTE SANGUE,\nPARA TUA GLÓRIA VER E TE ADORAR!\n\nFINAL: \nPARA TUA GLÓRIA VER E TE ADORAR!', 'PELO SANGUE DE JESUS\nCLAMO A TI, MEU SENHOR;\nNELE HÁ PERDÃO, PAZ, COMUNHÃO,\nVIDA PARA O MEU SER!\n\nNOS TEUS ÁTRIOS QUERO ENTRAR\nCOBERTO POR ESTE SANGUE,\nPARA TUA GLÓRIA VER E TE ADORAR!\n\nPELO SANGUE DE JESUS\nCLAMO A TI, MEU SENHOR;\nNELE HÁ PERDÃO, PAZ, COMUNHÃO,\nVIDA PARA O MEU SER!\n\nNOS TEUS ÁTRIOS QUERO ENTRAR\nCOBERTO POR ESTE SANGUE,\nPARA TUA GLÓRIA VER E TE ADORAR!\n<final>PARA TUA GLÓRIA VER E TE ADORAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (9, 'SENHOR, ME CHEGO A TI', 'SENHOR, ME CHEGO A TI', 'SENHOR, ME CHEGO A TI,\nNESTA HORA DE ORAÇÃO;\nSENHOR, ME CHEGO A TI,\nPRA PEDIR-TE MAIS COMUNHÃO E AMOR.\n\nHUMILDE E FRACO SOU,\nFAZE-ME VIVER NA TUA LUZ;\nLIBERTA-ME, SENHOR,\nÓ VEM PASSAR O TEU SANGUE\nE PURIFICA-ME, SENHOR.', 'SENHOR, ME CHEGO A TI,\nNESTA HORA DE ORAÇÃO;\nSENHOR, ME CHEGO A TI,\nPRA PEDIR-TE MAIS COMUNHÃO E AMOR.\n\nHUMILDE E FRACO SOU,\nFAZE-ME VIVER NA TUA LUZ;\nLIBERTA-ME, SENHOR,\nÓ VEM PASSAR O TEU SANGUE\nE PURIFICA-ME, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (10, 'VAMOS LAVAR AS VESTES', 'VAMOS LAVAR AS VESTES', 'VAMOS LAVAR AS VESTES \nNO SANGUE DO CORDEIRO. \n\nQUANDO JESUS VIER NAQUELE GRANDE DIA,\nAS VESTES ESTANDO LIMPAS,\nTEMOS PAZ E ALEGRIA.', 'VAMOS LAVAR AS VESTES <bis>\nNO SANGUE DO CORDEIRO. <bis>\n\nQUANDO JESUS VIER NAQUELE GRANDE DIA,\nAS VESTES ESTANDO LIMPAS,\nTEMOS PAZ E ALEGRIA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (11, 'REVESTE, SENHOR, TEU POVO', 'REVESTE, SENHOR, TEU POVO', 'REVESTE, SENHOR, TEU POVO \n(SIM, REVESTE)\n\nCOM O SANGUE DA CRUZ,\nO SANGUE DE JESUS,\nREVESTE, SENHOR, TEU POVO.', 'REVESTE, SENHOR, TEU POVO <bis>\n(SIM, REVESTE)<bis>\n\nCOM O SANGUE DA CRUZ,\nO SANGUE DE JESUS,\nREVESTE, SENHOR, TEU POVO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (12, 'HÁ VITÓRIA PARA MIM', 'HÁ VITÓRIA PARA MIM', 'HÁ VITÓRIA PARA MIM, (BIS)\nPELO SANGUE DO CORDEIRO,\nHÁ VITÓRIA PARA MIM.\n\nVENCER! VENCER! VENCER! VENCER!\nPELO SANGUE DO CORDEIRO,\nEU IREI VENCER.', 'HÁ VITÓRIA PARA MIM, <bis>\nPELO SANGUE DO CORDEIRO,\nHÁ VITÓRIA PARA MIM.\n\nVENCER! VENCER! VENCER! VENCER!\nPELO SANGUE DO CORDEIRO,\nEU IREI VENCER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (13, 'PÕE TEU SANGUE SOBRE MIM', 'PÕE TEU SANGUE SOBRE MIM', 'PÕE TEU SANGUE SOBRE MIM, (BIS)\nPORÇÃO DOBRADA, Ó SENHOR, ME DÁ,\nPÕE TEU SANGUE SOBRE MIM.', 'PÕE TEU SANGUE SOBRE MIM, <bis>\nPORÇÃO DOBRADA, Ó SENHOR, ME DÁ,\nPÕE TEU SANGUE SOBRE MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (14, 'EM TEU ALTAR, SENHOR', 'EM TEU ALTAR, SENHOR', 'EM TEU ALTAR, SENHOR, ENTREGO MINHA VIDA,\nEM TEU ALTAR, SENHOR, PURIFICA MINHA VIDA,\nCOM O SANGUE DO CORDEIRO;\nMINHA VIDA ENTREGO EM TEU ALTAR.\n\nREPETIR O LOUVOR', 'EM TEU ALTAR, SENHOR, ENTREGO MINHA VIDA,\nEM TEU ALTAR, SENHOR, PURIFICA MINHA VIDA,\nCOM O SANGUE DO CORDEIRO;\nMINHA VIDA ENTREGO EM TEU ALTAR.\n\n<repetir tipo=''O LOUVOR''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (15, 'CLAMAREI, CLAMAREI', 'CLAMAREI, CLAMAREI', 'CLAMAREI, CLAMAREI\nPELO SANGUE DE JESUS;\nELE É PAZ E SEGURANÇA,\nALEGRIA, VIDA E LUZ.', 'CLAMAREI, CLAMAREI\nPELO SANGUE DE JESUS;\nELE É PAZ E SEGURANÇA,\nALEGRIA, VIDA E LUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (16, 'SE ANDARMOS NA LUZ', 'SE ANDARMOS NA LUZ', 'SE ANDARMOS NA LUZ, \nCOMO NA LUZ ELE ESTÁ, \n\nTEMOS COMUNHÃO COM O SENHOR\nE TAMBÉM COM OS IRMÃOS,\nSE ANDARMOS NA LUZ,\nCOMO NA LUZ ELE ESTÁ.\n\nE ASSIM O SANGUE DE JESUS \nTEM PODER PARA SALVAR, \nTEM PODER PARA CURAR, \nTEM PODER PARA PERDOAR \nE TAMBÉM PURIFICAR.', 'SE ANDARMOS NA LUZ, <bis>\nCOMO NA LUZ ELE ESTÁ, <bis>\n\nTEMOS COMUNHÃO COM O SENHOR\nE TAMBÉM COM OS IRMÃOS,\nSE ANDARMOS NA LUZ,\nCOMO NA LUZ ELE ESTÁ.\n\nE ASSIM O SANGUE DE JESUS <bis>\nTEM PODER PARA SALVAR, <bis>\nTEM PODER PARA CURAR, <bis>\nTEM PODER PARA PERDOAR <bis>\nE TAMBÉM PURIFICAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (17, 'EM TUA PRESENÇA ENTRAMOS', 'EM TUA PRESENÇA ENTRAMOS', 'EM TUA PRESENÇA ENTRAMOS\nCLAMANDO A TI, Ó SENHOR,\nLAVA-NOS COM O TEU SANGUE,\nRENOVA EM NÓS TEU AMOR.\n\nCOM TEU ESPÍRITO SANTO\nVEM ENTRE NÓS PRESIDIR.\nSEJA ESTE CULTO UM INCENSO\nQUE POSSA AOS CÉUS SUBIR.\n\nEM TEU ALTAR ENTREGAMOS\nAS NOSSAS VIDAS, SENHOR,\nDE CORAÇÃO OFERTAMOS\nA TI O NOSSO LOUVOR.\n\nÓ CRISTO VIVO, REVELA\nTUA PRESENÇA ENTRE NÓS,\nCOM TUA GRAÇA OPERA,\nFAZE-NOS OUVIR TUA VOZ.\n\nEM TUA PRESENÇA ENTRAMOS\nCLAMANDO A TI, Ó SENHOR,\nLAVA-NOS COM O TEU SANGUE,\nRENOVA EM NÓS TEU AMOR.', 'EM TUA PRESENÇA ENTRAMOS\nCLAMANDO A TI, Ó SENHOR,\nLAVA-NOS COM O TEU SANGUE,\nRENOVA EM NÓS TEU AMOR.\n\nCOM TEU ESPÍRITO SANTO\nVEM ENTRE NÓS PRESIDIR.\nSEJA ESTE CULTO UM INCENSO\nQUE POSSA AOS CÉUS SUBIR.\n\nEM TEU ALTAR ENTREGAMOS\nAS NOSSAS VIDAS, SENHOR,\nDE CORAÇÃO OFERTAMOS\nA TI O NOSSO LOUVOR.\n\nÓ CRISTO VIVO, REVELA\nTUA PRESENÇA ENTRE NÓS,\nCOM TUA GRAÇA OPERA,\nFAZE-NOS OUVIR TUA VOZ.\n\nEM TUA PRESENÇA ENTRAMOS\nCLAMANDO A TI, Ó SENHOR,\nLAVA-NOS COM O TEU SANGUE,\nRENOVA EM NÓS TEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (18, 'PROSTRADO ESTOU DIANTE DE TI', 'PROSTRADO ESTOU DIANTE DE TI', 'PROSTRADO ESTOU DIANTE DE TI;\nPERDÃO IMPLORO POR MEU PECAR.\nÉ GRANDE A MINHA CULPA, MAS ÉS AMOR!\nESCUTA A VOZ DO MEU CLAMOR.', 'PROSTRADO ESTOU DIANTE DE TI;\nPERDÃO IMPLORO POR MEU PECAR.\nÉ GRANDE A MINHA CULPA, MAS ÉS AMOR!\nESCUTA A VOZ DO MEU CLAMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (19, 'TEU POVO CLAMA', 'TEU POVO CLAMA', 'TEU POVO CLAMA EM ORAÇÃO \nPELO TEU SANGUE, LIBERTAÇÃO, \nPELO PECADO, MISERICÓRDIA, \nTEU POVO CLAMA, SENHOR JESUS.', 'TEU POVO CLAMA EM ORAÇÃO <bis>\nPELO TEU SANGUE, LIBERTAÇÃO, <bis>\nPELO PECADO, MISERICÓRDIA, <bis>\nTEU POVO CLAMA, SENHOR JESUS. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (20, 'O TEU PECADO TU QUERES DEIXAR?', 'O TEU PECADO TU QUERES DEIXAR?', 'O TEU PECADO TU QUERES DEIXAR?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nQUERES DO MAL A VITÓRIA GANHAR?\nSEU SANGUE TEM ESTE PODER.\n\nCORO\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.\n\nQUERES OS VÍCIOS ABANDONAR?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nCONFIA EM CRISTO PARA TE CURAR,\nSEU SANGUE TEM ESTE PODER.\n\nCORO\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.\n\nQUERES PUREZA PARA O TEU CORAÇÃO?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nMAIS LEALDADE, MAIS CONSAGRAÇÃO,\nSEU SANGUE TEM ESTE PODER.\n\nCORO\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.\n\nQUERES DE CRISTO A MENSAGEM LEVAR?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nQUERES COM OS ANJOS NA GLÓRIA CANTAR? \nSEU SANGUE TEM ESTE PODER.\n\nCORO\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.', 'O TEU PECADO TU QUERES DEIXAR?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nQUERES DO MAL A VITÓRIA GANHAR?\nSEU SANGUE TEM ESTE PODER.\n\n<coro>\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.\n\nQUERES OS VÍCIOS ABANDONAR?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nCONFIA EM CRISTO PARA TE CURAR,\nSEU SANGUE TEM ESTE PODER.\n\n<coro>\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.\n\nQUERES PUREZA PARA O TEU CORAÇÃO?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nMAIS LEALDADE, MAIS CONSAGRAÇÃO,\nSEU SANGUE TEM ESTE PODER.\n\n<coro>\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.\n\nQUERES DE CRISTO A MENSAGEM LEVAR?\nNO SANGUE HÁ PODER, SIM, HÁ PODER.\nQUERES COM OS ANJOS NA GLÓRIA CANTAR? \nSEU SANGUE TEM ESTE PODER.\n\n<coro>\nHÁ PODER, SIM, FORÇA E VIGOR,\nNESTE SANGUE DE JESUS;\nHÁ PODER, SIM, NO BOM SALVADOR,\nOH! CONFIA NO CRISTO DA CRUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (21, 'NESTA HORA DE CLAMOR', 'NESTA HORA DE CLAMOR', 'NESTA HORA DE CLAMOR\nPELO SANGUE DE JESUS (VARÕES)\nNECESSITADO, DEPENDENTE,\nME COLOCO AOS TEUS PÉS, Ó PAI.\n\nCORO\nDÁ-ME O PÃO COTIDIANO, \nESSE PÃO ÉS TU JESUS;\nTUA PAZ É O MEU ALIMENTO,\nDÁ-ME DE TI, SENHOR.\n\nAS RIQUEZAS QUE EU ENCONTRO EM TI,\nSÃO PRA MIM MEU BEM MAIOR.\nEM TI ESPERO, EM TI CONFIO.\nDE TI VEM MINHA SALVAÇÃO.\n\nCORO\nDÁ-ME O PÃO COTIDIANO, \nESSE PÃO ÉS TU JESUS;\nTUA PAZ É O MEU ALIMENTO,\nDÁ-ME DE TI, SENHOR.\n\nINSTRUMENTOS\n\nNA ETERNIDADE HABITAREI.\nLÁ VEREI O MEU GRANDE REI!\nRUAS DE OURO, RIOS DE CRISTAL.\nGLÓRIA AO TEU SANTO ESPÍRITO!', 'NESTA HORA DE CLAMOR\nPELO SANGUE DE JESUS <h>\nNECESSITADO, DEPENDENTE,\nME COLOCO AOS TEUS PÉS, Ó PAI.\n\n<coro>\nDÁ-ME O PÃO COTIDIANO, \nESSE PÃO ÉS TU JESUS;\nTUA PAZ É O MEU ALIMENTO,\nDÁ-ME DE TI, SENHOR.\n\nAS RIQUEZAS QUE EU ENCONTRO EM TI,\nSÃO PRA MIM MEU BEM MAIOR.\nEM TI ESPERO, EM TI CONFIO.\nDE TI VEM MINHA SALVAÇÃO.\n\n<coro>\nDÁ-ME O PÃO COTIDIANO, \nESSE PÃO ÉS TU JESUS;\nTUA PAZ É O MEU ALIMENTO,\nDÁ-ME DE TI, SENHOR.\n<instrumentos>\n\n\nNA ETERNIDADE HABITAREI.\nLÁ VEREI O MEU GRANDE REI!\nRUAS DE OURO, RIOS DE CRISTAL.<bis>\nGLÓRIA AO TEU SANTO ESPÍRITO!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (22, 'BENDITO SEJA O CORDEIRO', 'BENDITO SEJA O CORDEIRO', 'BENDITO SEJA O CORDEIRO\nQUE NA CRUZ POR NÓS PADECEU!\nBENDITO SEJA O SEU SANGUE\nQUE POR NÓS ALI ELE VERTEU!\nEIS NESSE SANGUE LAVADOS,\nCOM ROUPAS QUE TÃO ALVAS SÃO,\nOS PECADORES REMIDOS\nQUE PERANTE SEU DEUS JÁ ESTÃO!\n\nCORO\nALVO MAIS QUE A NEVE! (BIS)\nSIM, NESTE SANGUE LAVADO,\nMAIS ALVO QUE A NEVE SEREI!\n\nQUÃO ESPINHOSA COROA\nQUE JESUS POR NÓS SUPORTOU!\nOH! QUÃO PROFUNDAS AS CHAGAS\nQUE NOS PROVAM QUANTO ELE AMOU!\n\nEIS NESSAS CHAGAS PUREZA\nPARA O MAIOR PECADOR!\nPOIS QUE MAIS ALVOS QUE A NEVE,\nO TEU SANGUE NOS TORNA, SENHOR!\n\nCORO\nALVO MAIS QUE A NEVE! (BIS)\nSIM, NESTE SANGUE LAVADO,\nMAIS ALVO QUE A NEVE SEREI!\n\nSE NÓS A TI CONFESSARMOS\nE SEGUIRMOS NA TUA LUZ,\nTU NÃO SOMENTE PERDOAS,\nPURIFICAS TAMBÉM, Ó JESUS!\n\nSIM, E DE TODO O PECADO!\nQUE MARAVILHA DE AMOR!\nPOIS QUE MAIS ALVOS QUE A NEVE\nO TEU SANGUE NOS TORNA, SENHOR!\n\nCORO\nALVO MAIS QUE A NEVE! (BIS)\nSIM, NESTE SANGUE LAVADO,\nMAIS ALVO QUE A NEVE SEREI!', 'BENDITO SEJA O CORDEIRO\nQUE NA CRUZ POR NÓS PADECEU!\nBENDITO SEJA O SEU SANGUE\nQUE POR NÓS ALI ELE VERTEU!\nEIS NESSE SANGUE LAVADOS,\nCOM ROUPAS QUE TÃO ALVAS SÃO,\nOS PECADORES REMIDOS\nQUE PERANTE SEU DEUS JÁ ESTÃO!\n\n<coro>\nALVO MAIS QUE A NEVE! <bis>\nSIM, NESTE SANGUE LAVADO,\nMAIS ALVO QUE A NEVE SEREI!\n\nQUÃO ESPINHOSA COROA\nQUE JESUS POR NÓS SUPORTOU!\nOH! QUÃO PROFUNDAS AS CHAGAS\nQUE NOS PROVAM QUANTO ELE AMOU!\n\nEIS NESSAS CHAGAS PUREZA\nPARA O MAIOR PECADOR!\nPOIS QUE MAIS ALVOS QUE A NEVE,\nO TEU SANGUE NOS TORNA, SENHOR!\n\n<coro>\nALVO MAIS QUE A NEVE! <bis>\nSIM, NESTE SANGUE LAVADO,\nMAIS ALVO QUE A NEVE SEREI!\n\nSE NÓS A TI CONFESSARMOS\nE SEGUIRMOS NA TUA LUZ,\nTU NÃO SOMENTE PERDOAS,\nPURIFICAS TAMBÉM, Ó JESUS!\n\nSIM, E DE TODO O PECADO!\nQUE MARAVILHA DE AMOR!\nPOIS QUE MAIS ALVOS QUE A NEVE\nO TEU SANGUE NOS TORNA, SENHOR!\n\n<coro>\nALVO MAIS QUE A NEVE! <bis>\nSIM, NESTE SANGUE LAVADO,\nMAIS ALVO QUE A NEVE SEREI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (23, 'SENHOR, OUVE A MINHA ORAÇÃO', 'SENHOR, OUVE A MINHA ORAÇÃO', 'SENHOR, OUVE A MINHA ORAÇÃO\nE DÁ-ME PLENA COMUNHÃO,\nLIBERTA DO MEU VIL PECADO;\nSENHOR, OUVE A MINHA ORAÇÃO.\n\nTRANSBORDA, INUNDA O MEU SER,\nTRANSFORMA, FAZE EM MIM TEU QUERER,\nDERRAMA DO SANGUE DE CRISTO;\nSENHOR, OUVE A MINHA ORAÇÃO.', 'SENHOR, OUVE A MINHA ORAÇÃO\nE DÁ-ME PLENA COMUNHÃO,\nLIBERTA DO MEU VIL PECADO;\nSENHOR, OUVE A MINHA ORAÇÃO.\n\nTRANSBORDA, INUNDA O MEU SER,\nTRANSFORMA, FAZE EM MIM TEU QUERER,\nDERRAMA DO SANGUE DE CRISTO;\nSENHOR, OUVE A MINHA ORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (24, 'EIS O CORDEIRO DE DEUS', 'EIS O CORDEIRO DE DEUS', 'EIS O CORDEIRO DE DEUS\nQUE TIRA O PECADO DO MUNDO,\nQUE MORREU NO MEU LUGAR,\nENTÃO PODE ME PERDOAR.\n\nCORO\nCLAMO AGORA PEDINDO:\nVEM PERDOAR, (VEM PERDOAR) \nPURIFICAR, (PURIFICAR) \nVEM TRANSFORMAR E RENOVAR,\nVEM RESTAURAR.\n\nDIANTE DO TEU ALTAR\nDEIXO A MINHA ANSIEDADE,\nPELO SANGUE DE JESUS, \nTENHO VIDA. \n\nCORO\nCLAMO AGORA PEDINDO:\nVEM PERDOAR, (VEM PERDOAR) \nPURIFICAR, (PURIFICAR) \nVEM TRANSFORMAR E RENOVAR,\nVEM RESTAURAR.\n\nFINAL: VEM RESTAURAR.', 'EIS O CORDEIRO DE DEUS\nQUE TIRA O PECADO DO MUNDO,\nQUE MORREU NO MEU LUGAR,\nENTÃO PODE ME PERDOAR.\n\n<coro>\nCLAMO AGORA PEDINDO:\nVEM PERDOAR, (VEM PERDOAR) \nPURIFICAR, (PURIFICAR) \nVEM TRANSFORMAR E RENOVAR,\nVEM RESTAURAR.\n\nDIANTE DO TEU ALTAR\nDEIXO A MINHA ANSIEDADE,\nPELO SANGUE DE JESUS, \nTENHO VIDA. \n\n<coro>\nCLAMO AGORA PEDINDO:\nVEM PERDOAR, (VEM PERDOAR) \nPURIFICAR, (PURIFICAR) \nVEM TRANSFORMAR E RENOVAR,\nVEM RESTAURAR.\n<final>VEM RESTAURAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (25, 'SENHOR, A TI CLAMO', 'SENHOR, A TI CLAMO', 'SENHOR, A TI CLAMO,\nINCLINA OS TEUS OUVIDOS \nÀ MINHA VOZ; LAVA A MINH''ALMA \nCOM O SANGUE DE JESUS, \nSUPLICO, SENHOR! \n\nDÁ-ME UM CÂNTICO NOVO,\nFAZ MEU LOUVOR TOCAR JESUS;\nÓ DEUS, INCLINA OS TEUS \nOUVIDOS E OUVE A MINHA VOZ!', 'SENHOR, A TI CLAMO,<bis>\nINCLINA OS TEUS OUVIDOS <bis>\nÀ MINHA VOZ; LAVA A MINH''ALMA <bis>\nCOM O SANGUE DE JESUS, <bis>\nSUPLICO, SENHOR! <bis>\n\nDÁ-ME UM CÂNTICO NOVO,\nFAZ MEU LOUVOR TOCAR JESUS;\nÓ DEUS, INCLINA OS TEUS <bis>\nOUVIDOS E OUVE A MINHA VOZ! <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (26, 'SEJA SÓ O SENHOR LOUVADO AQUI', 'SEJA SÓ O SENHOR LOUVADO AQUI', 'SEJA SÓ O SENHOR LOUVADO AQUI, ALELUIA!\nNESTE ABENÇOADO MAANAIM, ALELUIA!\nPOIS PRESENTE ELE ESTÁ,\nQUER A TODOS ABENÇOAR,\nSUA GRAÇA DERRAMAR, ALELUIA!\n\nE PELO TEU SANGUE CLAMAMOS, SENHOR, ALELUIA!\nTEU PRECIOSO SANGUE REMIDOR, ALELUIA!\nPÕE TEU SANGUE SOBRE MIM,\nDE TODO O MAL LIVRA-ME E ASSIM,\nGOZO ENTÃO TEREI SEM FIM, ALELUIA!', 'SEJA SÓ O SENHOR LOUVADO AQUI, ALELUIA!\nNESTE ABENÇOADO MAANAIM, ALELUIA!\nPOIS PRESENTE ELE ESTÁ,\nQUER A TODOS ABENÇOAR,\nSUA GRAÇA DERRAMAR, ALELUIA!\n\nE PELO TEU SANGUE CLAMAMOS, SENHOR, ALELUIA!\nTEU PRECIOSO SANGUE REMIDOR, ALELUIA!\nPÕE TEU SANGUE SOBRE MIM,\nDE TODO O MAL LIVRA-ME E ASSIM,\nGOZO ENTÃO TEREI SEM FIM, ALELUIA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (27, 'CORDEIRO ETERNO', 'CORDEIRO ETERNO', 'CORDEIRO ETERNO, \nVIESTE PRA ME DAR\nTUA VIDA, TEU SANGUE, \nPRA QUE EU PUDESSE TER\nA VIDA ETERNA E O PERDÃO,\nA CURA, A PAZ, LIBERTAÇÃO,\nCORDEIRO ETERNO DE DEUS.\n\nE HOJE TEU SANGUE ESTÁ \nAGINDO EM MIM,\nLIMPANDO, CURANDO, \nMUDANDO O MEU SER;\nOH! QUE PODER E VIDA HÁ\nNO SANGUE QUE JESUS VERTEU, \nCORDEIRO ETERNO DE DEUS. \n\nFINAL: \nCORDEIRO ETERNO DE DEUS.', 'CORDEIRO ETERNO, \nVIESTE PRA ME DAR\nTUA VIDA, TEU SANGUE, \nPRA QUE EU PUDESSE TER\nA VIDA ETERNA E O PERDÃO,\nA CURA, A PAZ, LIBERTAÇÃO,\nCORDEIRO ETERNO DE DEUS.\n\nE HOJE TEU SANGUE ESTÁ \nAGINDO EM MIM,\nLIMPANDO, CURANDO, \nMUDANDO O MEU SER;<bis>\nOH! QUE PODER E VIDA HÁ<bis>\nNO SANGUE QUE JESUS VERTEU, <bis>\nCORDEIRO ETERNO DE DEUS. \n<final>CORDEIRO ETERNO DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (28, 'O PODER DO SANGUE DE JESUS', 'O PODER DO SANGUE DE JESUS', 'O PODER DO SANGUE DE JESUS\nHÁ DE ME PURIFICAR,\nMEU PECADO PERDOAR;\nO PODER DO SANGUE DE JESUS\nDÁ-ME PLENA COMUNHÃO,\nTRAZ-ME A REVELAÇÃO.\n\nCORO\nESTOU LIBERTO NA PRESENÇA DO SENHOR,\nNOS SEUS ÁTRIOS HEI DE ENTRAR,\nCOM LOUVOR GLORIFICAR;\nSUA GLÓRIA RESPLANDECE NO ALTAR,\nSEU ESPÍRITO ME ALCANÇA COM AMOR.\n\nO PODER DO SANGUE DE JESUS\nFAZ-ME CAMINHAR NA LUZ,\nBEM SEGURO ME CONDUZ.\n\nCORO\nESTOU LIBERTO NA PRESENÇA DO SENHOR,\nNOS SEUS ÁTRIOS HEI DE ENTRAR,\nCOM LOUVOR GLORIFICAR;\nSUA GLÓRIA RESPLANDECE NO ALTAR,\nSEU ESPÍRITO ME ALCANÇA COM AMOR.\n\nFINAL: \nHÁ PODER NO SANGUE DE JESUS (BIS)', 'O PODER DO SANGUE DE JESUS\nHÁ DE ME PURIFICAR,\nMEU PECADO PERDOAR;\nO PODER DO SANGUE DE JESUS\nDÁ-ME PLENA COMUNHÃO,\nTRAZ-ME A REVELAÇÃO.\n\n<coro>\nESTOU LIBERTO NA PRESENÇA DO SENHOR,\nNOS SEUS ÁTRIOS HEI DE ENTRAR,\nCOM LOUVOR GLORIFICAR;\nSUA GLÓRIA RESPLANDECE NO ALTAR,\nSEU ESPÍRITO ME ALCANÇA COM AMOR.\n\nO PODER DO SANGUE DE JESUS\nFAZ-ME CAMINHAR NA LUZ,\nBEM SEGURO ME CONDUZ.\n\n<coro>\nESTOU LIBERTO NA PRESENÇA DO SENHOR,\nNOS SEUS ÁTRIOS HEI DE ENTRAR,\nCOM LOUVOR GLORIFICAR;\nSUA GLÓRIA RESPLANDECE NO ALTAR,\nSEU ESPÍRITO ME ALCANÇA COM AMOR.\n<final>HÁ PODER NO SANGUE DE JESUS <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (29, 'TRANSBORDA-ME, SENHOR', 'TRANSBORDA-ME, SENHOR', 'TRANSBORDA-ME, SENHOR, DÁ-ME COMUNHÃO;\nSENTIR TUA PRESENÇA EU QUERO, Ó PAI;\nFALA AO MEU CORAÇÃO, NO SANGUE HÁ VIDA,\nHÁ LIBERTAÇÃO, SEGURANÇA E PAZ, \nTOCA-ME, SENHOR.\n\nTRANSBORDA-ME, SENHOR, DÁ-ME COMUNHÃO;\nSENTIR TUA PRESENÇA EU QUERO, Ó PAI;\nFALA AO MEU CORAÇÃO, NO SANGUE HÁ VIDA,\nHÁ LIBERTAÇÃO, SEGURANÇA E PAZ, \nTOCA-ME, SENHOR.', 'TRANSBORDA-ME, SENHOR, DÁ-ME COMUNHÃO;\nSENTIR TUA PRESENÇA EU QUERO, Ó PAI;\nFALA AO MEU CORAÇÃO, NO SANGUE HÁ VIDA,\nHÁ LIBERTAÇÃO, SEGURANÇA E PAZ, \nTOCA-ME, SENHOR.\n\nTRANSBORDA-ME, SENHOR, DÁ-ME COMUNHÃO;\nSENTIR TUA PRESENÇA EU QUERO, Ó PAI;\nFALA AO MEU CORAÇÃO, NO SANGUE HÁ VIDA,\nHÁ LIBERTAÇÃO, SEGURANÇA E PAZ, <bis>\nTOCA-ME, SENHOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (30, 'OH! QUE PRECIOSO SANGUE', 'OH! QUE PRECIOSO SANGUE', 'OH! QUE PRECIOSO SANGUE\nO SENHOR VERTEU,\nQUANDO PARA RESGATAR-NOS PADECEU!\n\nOH! QUE PRECIOSO SANGUE,\nSANGUE DE JESUS,\nQUE POR NÓS FOI DERRAMADO\nSOBRE A CRUZ!\n\nOH! QUE PRECIOSO SANGUE, SACRIFICIAL,\nPOIS APAGA DE NOSSA ALMA TODO O MAL!\n\nOH! QUE PRECIOSO SANGUE,\nFALA-NOS DE PAZ,\nTUDO QUANTO A LEI EXIGE SATISFAZ!', 'OH! QUE PRECIOSO SANGUE\nO SENHOR VERTEU,\nQUANDO PARA RESGATAR-NOS PADECEU!\n\nOH! QUE PRECIOSO SANGUE,\nSANGUE DE JESUS,\nQUE POR NÓS FOI DERRAMADO\nSOBRE A CRUZ!\n\nOH! QUE PRECIOSO SANGUE, SACRIFICIAL,\nPOIS APAGA DE NOSSA ALMA TODO O MAL!\n\nOH! QUE PRECIOSO SANGUE,\nFALA-NOS DE PAZ,\nTUDO QUANTO A LEI EXIGE SATISFAZ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (31, 'JUNTO A TI SUPLICO, Ó PAI', 'JUNTO A TI SUPLICO, Ó PAI', 'JUNTO A TI SUPLICO, Ó PAI,\nPELO SANGUE DE JESUS;\nCURVO-ME DIANTE DE TI,\nOUVE-ME, Ó MEU SENHOR.\n\nHÁ EM MIM SINCERIDADE\nEM QUERER LIBERTAÇÃO;\nLAVA-ME COM ESTE SANGUE,\nDÁ-ME PLENA COMUNHÃO.', 'JUNTO A TI SUPLICO, Ó PAI,\nPELO SANGUE DE JESUS;\nCURVO-ME DIANTE DE TI,\nOUVE-ME, Ó MEU SENHOR.\n\nHÁ EM MIM SINCERIDADE\nEM QUERER LIBERTAÇÃO;\nLAVA-ME COM ESTE SANGUE,\nDÁ-ME PLENA COMUNHÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (32, 'O SANGUE DE JESUS, VERTIDO ALI NA CRUZ', 'O SANGUE DE JESUS, VERTIDO ALI NA CRUZ', 'O SANGUE DE JESUS, VERTIDO ALI NA CRUZ, \nTEM PODER PARA ME PURIFICAR.\nO SANGUE DE JESUS, VERTIDO ALI NA CRUZ, \nTEM PODER PARA ME LIBERTAR.\n\nPÕE TEU SANGUE EM MIM, SENHOR,\nPÕE TEU SANGUE EM MIM!\nE DÁ-ME LIBERTAÇÃO\nE UMA PLENA COMUNHÃO.', 'O SANGUE DE JESUS, VERTIDO ALI NA CRUZ, \nTEM PODER PARA ME PURIFICAR.\nO SANGUE DE JESUS, VERTIDO ALI NA CRUZ, \nTEM PODER PARA ME LIBERTAR.\n\nPÕE TEU SANGUE EM MIM, SENHOR,\nPÕE TEU SANGUE EM MIM!\nE DÁ-ME LIBERTAÇÃO\nE UMA PLENA COMUNHÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (33, 'EU ME PROSTRO EM TEU ALTAR', 'EU ME PROSTRO EM TEU ALTAR', 'EU ME PROSTRO EM TEU ALTAR\nNESTA HORA DE CLAMOR,\nLEMBRO-ME DE TUA DOR\nQUE SOFRESTE POR ME AMAR,\nO TEU SANGUE TEM PODER\nPARA ME PURIFICAR.\n\nNESSE SANGUE HÁ COMUNHÃO,\nCURA E LIBERTAÇÃO;\nVISITA-ME COM TUA PAZ,\nTEU ESPÍRITO RELUZ, \nVIVIFICA-ME, JESUS, \nE MINH''ALMA SATISFAZ. \n\nFINAL: \nE MINH''ALMA SATISFAZ.', 'EU ME PROSTRO EM TEU ALTAR\nNESTA HORA DE CLAMOR,\nLEMBRO-ME DE TUA DOR\nQUE SOFRESTE POR ME AMAR,\nO TEU SANGUE TEM PODER\nPARA ME PURIFICAR.\n\nNESSE SANGUE HÁ COMUNHÃO,\nCURA E LIBERTAÇÃO;\nVISITA-ME COM TUA PAZ,\nTEU ESPÍRITO RELUZ, <bis>\nVIVIFICA-ME, JESUS, <bis>\nE MINH''ALMA SATISFAZ. <bis>\n<final>E MINH''ALMA SATISFAZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (34, 'QUANDO BUSCAMOS', 'QUANDO BUSCAMOS', 'QUANDO BUSCAMOS A TI, SENHOR,\nE COM FÉ PEDIMOS TEU PERDÃO,\nCONFESSAMOS NOSSOS PECADOS,\nVEM COM TEU SANGUE NOS PURIFICAR.\n\nCORO\nRENOVA A NOSSA COMUNHÃO\n(NOSSA COMUNHÃO) SERVAS\nRENOVA A FÉ EM NOSSOS CORAÇÕES\nPARA QUE SEJAMOS MAIS FIÉIS A TI\nE ENTREGUEMOS NOSSAS VIDAS \n(NOSSAS VIDAS) VARÕES\nCADA VEZ MAIS NO TEU ALTAR.\n\nOS CÉUS SE ABREM E COM PODER\nOS ANJOS TRAZEM RESPOSTAS DO SENHOR;\nGLORIFICAMOS AO NOSSO DEUS\nQUE ESTÁ VIVO E REINA ENTRE NÓS.\n\nCORO\nRENOVA A NOSSA COMUNHÃO\n(NOSSA COMUNHÃO) SERVAS\nRENOVA A FÉ EM NOSSOS CORAÇÕES\nPARA QUE SEJAMOS MAIS FIÉIS A TI\nE ENTREGUEMOS NOSSAS VIDAS \n(NOSSAS VIDAS) VARÕES\nCADA VEZ MAIS NO TEU ALTAR.\nFINAL:\nCADA VEZ MAIS NO TEU ALTAR.', 'QUANDO BUSCAMOS A TI, SENHOR,\nE COM FÉ PEDIMOS TEU PERDÃO,\nCONFESSAMOS NOSSOS PECADOS,\nVEM COM TEU SANGUE NOS PURIFICAR.\n\n<coro>\nRENOVA A NOSSA COMUNHÃO\n(NOSSA COMUNHÃO) <m>\nRENOVA A FÉ EM NOSSOS CORAÇÕES\nPARA QUE SEJAMOS MAIS FIÉIS A TI\nE ENTREGUEMOS NOSSAS VIDAS \n(NOSSAS VIDAS) <h>\nCADA VEZ MAIS NO TEU ALTAR.\n\nOS CÉUS SE ABREM E COM PODER\nOS ANJOS TRAZEM RESPOSTAS DO SENHOR;\nGLORIFICAMOS AO NOSSO DEUS\nQUE ESTÁ VIVO E REINA ENTRE NÓS.\n\n<coro>\nRENOVA A NOSSA COMUNHÃO\n(NOSSA COMUNHÃO) <m>\nRENOVA A FÉ EM NOSSOS CORAÇÕES\nPARA QUE SEJAMOS MAIS FIÉIS A TI\nE ENTREGUEMOS NOSSAS VIDAS \n(NOSSAS VIDAS) <h>\nCADA VEZ MAIS NO TEU ALTAR.\n<final>CADA VEZ MAIS NO TEU ALTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (35, 'A MEU SENHOR', 'A MEU SENHOR', 'A MEU SENHOR E CRISTO JESUS\nVENHO AGORA CLAMAR;\nVEM COM TEU SANGUE LAVAR \nMINHAS VESTES, VEM ME PURIFICAR.\n\nVEM LIBERTAR A MINH''ALMA, \nJESUS, DE MIM VEM CUIDAR;\nVEM COM TEU SANGUE \nLAVAR MINHAS VESTES,\nVEM ME PURIFICAR.\n\nFINAL: \nVEM ME PURIFICAR.', 'A MEU SENHOR E CRISTO JESUS\nVENHO AGORA CLAMAR;\nVEM COM TEU SANGUE LAVAR \nMINHAS VESTES, VEM ME PURIFICAR.\n\nVEM LIBERTAR A MINH''ALMA, <bis>\nJESUS, DE MIM VEM CUIDAR;<bis>\nVEM COM TEU SANGUE <bis>\nLAVAR MINHAS VESTES,<bis>\nVEM ME PURIFICAR.\n<final>VEM ME PURIFICAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (36, 'CRUCIFICADO FOI MEU JESUS', 'CRUCIFICADO FOI MEU JESUS', 'CRUCIFICADO FOI MEU JESUS,\nDOR E OPRÓBRIO SOFREU NA CRUZ,\nCAMINHO NOVO NOS CONSAGROU\nAO SANTUÁRIO DO REI SENHOR.\n\nCORO\nNA SUA PRESENÇA EU ENTRO ASSIM,\nCRENDO QUE O SANGUE VERTEU POR MIM;\nVEM SER PROPÍCIO AO PECADOR,\nJÁ ME ALCANÇASTE POR TEU AMOR.\n\nMEU TRISTE ESTADO ELE MUDOU,\nEM NOVA VIDA ME TRANSFORMOU,\nCONFESSO AGORA O SEU PERDÃO,\nCONFIANDO A ELE MEU CORAÇÃO.\n\nCORO\nNA SUA PRESENÇA EU ENTRO ASSIM,\nCRENDO QUE O SANGUE VERTEU POR MIM;\nVEM SER PROPÍCIO AO PECADOR,\nJÁ ME ALCANÇASTE POR TEU AMOR.', 'CRUCIFICADO FOI MEU JESUS,\nDOR E OPRÓBRIO SOFREU NA CRUZ,\nCAMINHO NOVO NOS CONSAGROU\nAO SANTUÁRIO DO REI SENHOR.\n\n<coro>\nNA SUA PRESENÇA EU ENTRO ASSIM,\nCRENDO QUE O SANGUE VERTEU POR MIM;\nVEM SER PROPÍCIO AO PECADOR,\nJÁ ME ALCANÇASTE POR TEU AMOR.\n\nMEU TRISTE ESTADO ELE MUDOU,\nEM NOVA VIDA ME TRANSFORMOU,\nCONFESSO AGORA O SEU PERDÃO,\nCONFIANDO A ELE MEU CORAÇÃO.\n\n<coro>\nNA SUA PRESENÇA EU ENTRO ASSIM,\nCRENDO QUE O SANGUE VERTEU POR MIM;\nVEM SER PROPÍCIO AO PECADOR,\nJÁ ME ALCANÇASTE POR TEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (37, 'NESTA HORA ESQUEÇO O MUNDO', 'NESTA HORA ESQUEÇO O MUNDO', 'NESTA HORA ESQUEÇO O MUNDO,\nTODA A PREOCUPAÇÃO,\nME COLOCO EM TUA PRESENÇA,\nSOU CARENTE DO TEU PERDÃO.\n\nCONSIDERO O MEU PECADO,\nRECONHEÇO O TEU AMOR,\nTEU ESPÍRITO ME TEM LEVADO\nA ADORAR-TE MEU SALVADOR.\n\nCORO\nOH! QUE SANGUE REMIDOR\nQUE RETIRA A MINHA DOR\nE ME LIVRA DO PECADO, \nÓ JESUS, TU ÉS AMADO. \n\nINSTRUMENTOS\n\nPOR TEU SANGUE ESTOU LIBERTO,\nPOSSO TE GLORIFICAR,\nDE MEU PAI, SIM, AGORA ESTOU PERTO,\nALELUIA, VOU TE LOUVAR.\n\nCORO\nOH! QUE SANGUE REMIDOR\nQUE RETIRA A MINHA DOR\nE ME LIVRA DO PECADO, \nÓ JESUS, TU ÉS AMADO.', 'NESTA HORA ESQUEÇO O MUNDO,\nTODA A PREOCUPAÇÃO,\nME COLOCO EM TUA PRESENÇA,\nSOU CARENTE DO TEU PERDÃO.\n\nCONSIDERO O MEU PECADO,\nRECONHEÇO O TEU AMOR,\nTEU ESPÍRITO ME TEM LEVADO\nA ADORAR-TE MEU SALVADOR.\n\n<coro>\nOH! QUE SANGUE REMIDOR\nQUE RETIRA A MINHA DOR\nE ME LIVRA DO PECADO, \nÓ JESUS, TU ÉS AMADO. \n<instrumentos>\n\n\nPOR TEU SANGUE ESTOU LIBERTO,\nPOSSO TE GLORIFICAR,\nDE MEU PAI, SIM, AGORA ESTOU PERTO,\nALELUIA, VOU TE LOUVAR.\n\n<coro>\nOH! QUE SANGUE REMIDOR\nQUE RETIRA A MINHA DOR\nE ME LIVRA DO PECADO, <bis>\nÓ JESUS, TU ÉS AMADO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (38, 'PELO SANGUE DE JESUS IREI CLAMAR', 'PELO SANGUE DE JESUS IREI CLAMAR', 'PELO SANGUE DE JESUS IREI CLAMAR,\nMEUS PECADOS NO ALTAR IREI DEIXAR;\nSEU PERDÃO QUE ME ALCANÇA\nEU JÁ POSSO CONTEMPLAR.\nALELUIA, EU TE AMO, MEU JESUS.\n\nTODA MINHA GRATIDÃO TE QUERO DAR,\nPELA PAZ E PELA FÉ EM TI, SENHOR;\nTEU ESPÍRITO TRANSBORDA\nE MEU SER QUER TE ADORAR\nCOM OS DONS MARAVILHOSOS DE JESUS.', 'PELO SANGUE DE JESUS IREI CLAMAR,\nMEUS PECADOS NO ALTAR IREI DEIXAR;\nSEU PERDÃO QUE ME ALCANÇA\nEU JÁ POSSO CONTEMPLAR.\nALELUIA, EU TE AMO, MEU JESUS.\n\nTODA MINHA GRATIDÃO TE QUERO DAR,\nPELA PAZ E PELA FÉ EM TI, SENHOR;\nTEU ESPÍRITO TRANSBORDA\nE MEU SER QUER TE ADORAR\nCOM OS DONS MARAVILHOSOS DE JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (39, 'JESUS, TU ÉS O MEU DEUS', 'JESUS, TU ÉS O MEU DEUS', 'JESUS, TU ÉS O MEU DEUS,\nA MINH''ALMA TEM SEDE DE TI,\nEU TE DESEJO, Ó DEUS,\nNECESSITADO ESTOU.\n\nNO TEU SANGUE HÁ RENOVO,\nPODER PARA TRANSFORMAR,\nPARA LIBERTAR E PERDOAR,\nDERRAMA DESTE SANGUE EM MIM. \n\nE ASSIM TE BENDIREI \nENQUANTO EU VIVER, \nEM TEU NOME FALAREI, \nOS MEUS LÁBIOS TE LOUVARÃO. \n\nALELUIA, AMÉM (2X)', 'JESUS, TU ÉS O MEU DEUS,\nA MINH''ALMA TEM SEDE DE TI,\nEU TE DESEJO, Ó DEUS,\nNECESSITADO ESTOU.\n\nNO TEU SANGUE HÁ RENOVO,\nPODER PARA TRANSFORMAR,\nPARA LIBERTAR E PERDOAR,\nDERRAMA DESTE SANGUE EM MIM. \n\nE ASSIM TE BENDIREI <bis>\nENQUANTO EU VIVER, <bis>\nEM TEU NOME FALAREI, <bis>\nOS MEUS LÁBIOS TE LOUVARÃO. <bis>\n\nALELUIA, AMÉM <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (40, 'OH! QUE SANGUE PODEROSO', 'OH! QUE SANGUE PODEROSO', 'OH! QUE SANGUE PODEROSO!\nOH! QUE SANGUE CHEIO DE VIRTUDE,\nSANGUE QUE POR NÓS FOI DERRAMADO;\nQUE NOS DÁ PLENO PERDÃO,\nCOMUNHÃO, TOTAL LIBERTAÇÃO,\nROMPENDO AS BARREIRAS DO PECADO.\n\nCLAMAMOS A TI, SENHOR, \nPELO PODER QUE HÁ NO \nSANGUE DE JESUS \nPARA PEDIR O TEU PERDÃO \nE TOTAL LIBERTAÇÃO.\n\nFINAL: E TOTAL LIBERTAÇÃO.', 'OH! QUE SANGUE PODEROSO!\nOH! QUE SANGUE CHEIO DE VIRTUDE,\nSANGUE QUE POR NÓS FOI DERRAMADO;\nQUE NOS DÁ PLENO PERDÃO,\nCOMUNHÃO, TOTAL LIBERTAÇÃO,\nROMPENDO AS BARREIRAS DO PECADO.\n\nCLAMAMOS A TI, SENHOR, <bis>\nPELO PODER QUE HÁ NO <bis>\nSANGUE DE JESUS <bis>\nPARA PEDIR O TEU PERDÃO <bis>\nE TOTAL LIBERTAÇÃO.<bis>\n<final>E TOTAL LIBERTAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (41, 'ALÉM DO VÉU EU QUERO ESTAR', 'ALÉM DO VÉU EU QUERO ESTAR', 'ALÉM DO VÉU EU QUERO ESTAR,\nALÉM DO VÉU COM JESUS,\nPELO CAMINHO QUE ELE \nABRIU NAQUELA CRUZ;\nCOM OUSADIA VOU ENTRAR \nE POR SEU SANGUE VOU CLAMAR,\nALÉM DO VÉU ONDE ELE QUER \nME ABENÇOAR.\n\nALÉM DO VÉU A SUA GLÓRIA \nPOSSO AGORA CONTEMPLAR;\nDO AMOR DE DEUS \nQUEM PODERÁ ME SEPARAR?\nCOM QUERUBINS E SERAFINS\nMIL ALELUIAS VOU CANTAR,\nALÉM DO VÉU, ONDE PRA \nSEMPRE QUERO ESTAR.', 'ALÉM DO VÉU EU QUERO ESTAR,\nALÉM DO VÉU COM JESUS,\nPELO CAMINHO QUE ELE \nABRIU NAQUELA CRUZ;\nCOM OUSADIA VOU ENTRAR \nE POR SEU SANGUE VOU CLAMAR,\nALÉM DO VÉU ONDE ELE QUER \nME ABENÇOAR.\n\nALÉM DO VÉU A SUA GLÓRIA \nPOSSO AGORA CONTEMPLAR;\nDO AMOR DE DEUS \nQUEM PODERÁ ME SEPARAR?\nCOM QUERUBINS E SERAFINS\nMIL ALELUIAS VOU CANTAR,\nALÉM DO VÉU, ONDE PRA <bis>\nSEMPRE QUERO ESTAR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (42, 'SENHOR, SUPLICO A TI EM ORAÇÃO', 'SENHOR, SUPLICO A TI EM ORAÇÃO', 'SENHOR, SUPLICO A TI EM ORAÇÃO:\nFAZE DE MIM UM VASO NOVO,\nDERRAMA O SANGUE DE JESUS EM MIM.\n\nCORO\nPERMITE-ME QUE ENTRE NO SANTO \nDOS SANTOS, PERDOA-ME DO VIL PECADO, \nESTENDE A TUA MÃO.\n\nPRECISO CONTEMPLAR A TUA GLÓRIA,\nCONCEDE-ME TUA VITÓRIA,\nDERRAMA O SANGUE DE JESUS EM MIM.\n\nCORO\nPERMITE-ME QUE ENTRE NO SANTO \nDOS SANTOS, PERDOA-ME DO VIL PECADO, \nESTENDE A TUA MÃO. \n\nFINAL: SENHOR (5X)', 'SENHOR, SUPLICO A TI EM ORAÇÃO:\nFAZE DE MIM UM VASO NOVO,\nDERRAMA O SANGUE DE JESUS EM MIM.\n\n<coro>\nPERMITE-ME QUE ENTRE NO SANTO \nDOS SANTOS, PERDOA-ME DO VIL PECADO, \nESTENDE A TUA MÃO.\n\nPRECISO CONTEMPLAR A TUA GLÓRIA,\nCONCEDE-ME TUA VITÓRIA,\nDERRAMA O SANGUE DE JESUS EM MIM.\n\n<coro>\nPERMITE-ME QUE ENTRE NO SANTO \nDOS SANTOS, PERDOA-ME DO VIL PECADO, \nESTENDE A TUA MÃO. \n<final>SENHOR <bis tipo=''5''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (43, 'VOU CLAMAR', 'VOU CLAMAR', 'VOU CLAMAR POR TEU SANGUE, Ó JESUS,\nPRA TE OFERECER A MINHA VIDA. \nVOU CLAMAR POR TEU SANGUE, Ó JESUS,\nPRA TE OFERECER A MINHA VIDA. \n\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS.\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS. \n\nINSTRUMENTOS \n\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS.\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS.', 'VOU CLAMAR POR TEU SANGUE, Ó JESUS,\nPRA TE OFERECER A MINHA VIDA. \nVOU CLAMAR POR TEU SANGUE, Ó JESUS,\nPRA TE OFERECER A MINHA VIDA. \n\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS.\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS. \n<instrumentos>\n\n\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS.\nE QUEM TIVER TEU SANGUE SOBRE SI \nTERÁ VITÓRIA, VITÓRIA EM TI, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (44, 'CONFORME A SUA INFINITA GRAÇA', 'CONFORME A SUA INFINITA GRAÇA', 'CONFORME A TUA INFINITA GRAÇA,\nÓ PAI PERDOA A MINHA TRANSGRESSÃO;\nFAZE-ME SENTIR MAIS UMA VEZ A GRAÇA\nE DÁ-ME TUA PAZ AO CORAÇÃO.\n\nCORO\nMAIS UMA VEZ EU SINTO O MEU PECADO\nQUE É CONTRA TI, Ó PAI, Ó PAI DE AMOR;\nMINH''ALMA PEDE A TUA ALEGRIA,\nRENOVA EM MIM O TEU AMOR,\nÓ MEU SENHOR.\n\nMEU CORAÇÃO A TI EU OFEREÇO,\nPERDÃO IMPLORO, MEU SENHOR E REI;\nCONFORME A TUA INFINITA GRAÇA,\nMISERICÓRDIA ASSIM ALCANÇAREI.\n\nCORO\nMAIS UMA VEZ EU SINTO O MEU PECADO\nQUE É CONTRA TI, Ó PAI, Ó PAI DE AMOR;\nMINH''ALMA PEDE A TUA ALEGRIA,\nRENOVA EM MIM O TEU AMOR,\nÓ MEU SENHOR.\n\nDEUS DE BONDADE A TI EU AGRADEÇO\nTEU PATERNAL CUIDADO SOBRE MIM;\nTODO MEU SER A TI EU OFEREÇO,\nLOUVAR-TE QUERO SEMPRE ATÉ O FIM.\n\nCORO\nMAIS UMA VEZ EU SINTO O MEU PECADO\nQUE É CONTRA TI, Ó PAI, Ó PAI DE AMOR;\nMINH''ALMA PEDE A TUA ALEGRIA,\nRENOVA EM MIM O TEU AMOR,\nÓ MEU SENHOR.', 'CONFORME A TUA INFINITA GRAÇA,\nÓ PAI PERDOA A MINHA TRANSGRESSÃO;\nFAZE-ME SENTIR MAIS UMA VEZ A GRAÇA\nE DÁ-ME TUA PAZ AO CORAÇÃO.\n\n<coro>\nMAIS UMA VEZ EU SINTO O MEU PECADO\nQUE É CONTRA TI, Ó PAI, Ó PAI DE AMOR;\nMINH''ALMA PEDE A TUA ALEGRIA,\nRENOVA EM MIM O TEU AMOR,\nÓ MEU SENHOR.\n\nMEU CORAÇÃO A TI EU OFEREÇO,\nPERDÃO IMPLORO, MEU SENHOR E REI;\nCONFORME A TUA INFINITA GRAÇA,\nMISERICÓRDIA ASSIM ALCANÇAREI.\n\n<coro>\nMAIS UMA VEZ EU SINTO O MEU PECADO\nQUE É CONTRA TI, Ó PAI, Ó PAI DE AMOR;\nMINH''ALMA PEDE A TUA ALEGRIA,\nRENOVA EM MIM O TEU AMOR,\nÓ MEU SENHOR.\n\nDEUS DE BONDADE A TI EU AGRADEÇO\nTEU PATERNAL CUIDADO SOBRE MIM;\nTODO MEU SER A TI EU OFEREÇO,\nLOUVAR-TE QUERO SEMPRE ATÉ O FIM.\n\n<coro>\nMAIS UMA VEZ EU SINTO O MEU PECADO\nQUE É CONTRA TI, Ó PAI, Ó PAI DE AMOR;\nMINH''ALMA PEDE A TUA ALEGRIA,\nRENOVA EM MIM O TEU AMOR,\nÓ MEU SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (45, 'NOS ÁTRIOS DO SENHOR ENTRAMOS', 'NOS ÁTRIOS DO SENHOR ENTRAMOS', 'NOS ÁTRIOS DO SENHOR ENTRAMOS,\nPURIFICADOS PELO SANGUE DE JESUS.\nVIMOS LOUVAR-TE E ADORAR-TE, \nÉS NOSSO DEUS!\nVIMOS TRAZER-TE O NOSSO INCENSO,\nOS NOSSOS HOLOCAUSTOS DE LOUVOR.\n\nCORO \nSÓ TU ÉS DIGNO DA NOSSA ADORAÇÃO,\nÉS NOSSO DEUS!\n\nQUANTA BELEZA EM TI ACHAMOS,\nAO CONTEMPLARMOS TUA SANTIDADE.\nÓ DEUS PERFEITO, Ó DEUS TRIUNO, \nÉS NOSSO DEUS!\nE COMO RESPLANDECE A TUA LUZ,\nINCOMPARÁVEL É TUA GLÓRIA.\n\nCORO \nSÓ TU ÉS DIGNO DA NOSSA ADORAÇÃO,\nÉS NOSSO DEUS!\n\nPERANTE A IMENSIDÃO DO TEU AMOR,\nQUEBRANTA-SE DE GRATIDÃO O NOSSO SER. \nÓ, QUANTO AMASTE, QUANTO SOFRESTE, \nÉS NOSSO DEUS!\nTUDO VENCESTE PELO TEU PODER,\nPRA SEMPRE FIRME ESTÁ TEU TRONO!\n\nCORO \nSÓ TU ÉS DIGNO DA NOSSA ADORAÇÃO,\nÉS NOSSO DEUS!', 'NOS ÁTRIOS DO SENHOR ENTRAMOS,\nPURIFICADOS PELO SANGUE DE JESUS.\nVIMOS LOUVAR-TE E ADORAR-TE, \nÉS NOSSO DEUS!\nVIMOS TRAZER-TE O NOSSO INCENSO,\nOS NOSSOS HOLOCAUSTOS DE LOUVOR.\n\n<coro>\nSÓ TU ÉS DIGNO DA NOSSA ADORAÇÃO,\nÉS NOSSO DEUS!\n\nQUANTA BELEZA EM TI ACHAMOS,\nAO CONTEMPLARMOS TUA SANTIDADE.\nÓ DEUS PERFEITO, Ó DEUS TRIUNO, \nÉS NOSSO DEUS!\nE COMO RESPLANDECE A TUA LUZ,\nINCOMPARÁVEL É TUA GLÓRIA.\n\n<coro>\nSÓ TU ÉS DIGNO DA NOSSA ADORAÇÃO,\nÉS NOSSO DEUS!\n\nPERANTE A IMENSIDÃO DO TEU AMOR,\nQUEBRANTA-SE DE GRATIDÃO O NOSSO SER. \nÓ, QUANTO AMASTE, QUANTO SOFRESTE, \nÉS NOSSO DEUS!\nTUDO VENCESTE PELO TEU PODER,\nPRA SEMPRE FIRME ESTÁ TEU TRONO!\n\n<coro>\nSÓ TU ÉS DIGNO DA NOSSA ADORAÇÃO,\nÉS NOSSO DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (46, 'AO SENTIR O TEU PERDÃO', 'AO SENTIR O TEU PERDÃO', 'AO SENTIR O TEU PERDÃO\nPOR TEU SANGUE REMIDOR,\nRECEBI LIBERTAÇÃO, \nALEGRIA DO SENHOR.\nALELUIA, GLÓRIA A JESUS.\nINSTRUMENTOS\n\nNESTA HORA DE LOUVOR,\nQUE TRAZ GOZO AO CORAÇÃO,\nQUERO DAR-TE, MEU SENHOR,\nTODA A MINHA GRATIDÃO.\nALELUIA, GLÓRIA A JESUS.\n\nINSTRUMENTOS\n\nQUERO ENTÃO TE ADORAR,\nPOIS EM COMUNHÃO ESTOU,\nEM MINH''ALMA TE EXALTAR,\nALELUIA, EU TE DOU.\nALELUIA, GLÓRIA A JESUS. (BIS)', 'AO SENTIR O TEU PERDÃO\nPOR TEU SANGUE REMIDOR,\nRECEBI LIBERTAÇÃO, \nALEGRIA DO SENHOR.\nALELUIA, GLÓRIA A JESUS.\n<instrumentos>\n\n\nNESTA HORA DE LOUVOR,\nQUE TRAZ GOZO AO CORAÇÃO,\nQUERO DAR-TE, MEU SENHOR,\nTODA A MINHA GRATIDÃO.\nALELUIA, GLÓRIA A JESUS.\n<instrumentos>\n\n\nQUERO ENTÃO TE ADORAR,\nPOIS EM COMUNHÃO ESTOU,\nEM MINH''ALMA TE EXALTAR,\nALELUIA, EU TE DOU.\nALELUIA, GLÓRIA A JESUS. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (47, 'É TEU SANGUE', 'É TEU SANGUE', 'É TEU SANGUE QUE ME LIMPA,\nÉ TEU SANGUE QUE VIDA ME DÁ,\nESTE SANGUE DO SACRIFÍCIO,\nDERRAMADO EM MEU LUGAR, \nE QUE ME TORNA ALVO MAIS QUE A NEVE, MEU JESUS, OFERTA PERFEITA NO ALTAR.\nINSTRUMENTOS\n\nPOR TEU SANGUE CLAMO AGORA,\nPOR TEU SANGUE EU OUSO ENTRAR\nNO SANTUÁRIO, ONDE O DEUS VIVO\nQUER A MIM SE REVELAR. \nCORDEIRO ETERNO!\nÉS O HOLOCAUSTO QUE ME SALVOU!\nOFERTA PERFEITA NO ALTAR.', 'É TEU SANGUE QUE ME LIMPA,\nÉ TEU SANGUE QUE VIDA ME DÁ,\nESTE SANGUE DO SACRIFÍCIO,\nDERRAMADO EM MEU LUGAR, \nE QUE ME TORNA ALVO MAIS QUE A NEVE, MEU JESUS, OFERTA PERFEITA NO ALTAR.\n<instrumentos>\n\n\nPOR TEU SANGUE CLAMO AGORA,\nPOR TEU SANGUE EU OUSO ENTRAR\nNO SANTUÁRIO, ONDE O DEUS VIVO\nQUER A MIM SE REVELAR. \nCORDEIRO ETERNO!\nÉS O HOLOCAUSTO QUE ME SALVOU!\nOFERTA PERFEITA NO ALTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (48, 'PELO SANGUE DE JESUS EU VOU CLAMAR', 'PELO SANGUE DE JESUS EU VOU CLAMAR', 'PELO SANGUE DE JESUS EU VOU CLAMAR\nE O PERDÃO DOS MEUS PECADOS ALCANÇAR,\nPOIS SÓ ASSIM A CADA DIA POSSO ENTRAR\nPERANTE A TUA FACE, Ó SENHOR.\n\nPURIFICA-ME E LIBERTA-ME, \nSENHOR COM O TEU PODER!\nPRA TE ADORAR E TE EXALTAR, OH SENHOR!\n\nFINAL: \nPURIFICA-ME E LIBERTA-ME, \nSENHOR COM O TEU PODER! \nAMÉM!', 'PELO SANGUE DE JESUS EU VOU CLAMAR\nE O PERDÃO DOS MEUS PECADOS ALCANÇAR,\nPOIS SÓ ASSIM A CADA DIA POSSO ENTRAR\nPERANTE A TUA FACE, Ó SENHOR.\n\nPURIFICA-ME E LIBERTA-ME, \nSENHOR COM O TEU PODER!\nPRA TE ADORAR E TE EXALTAR, OH SENHOR!\n<final>PURIFICA-ME E LIBERTA-ME, \nSENHOR COM O TEU PODER! \nAMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (49, 'NA HORA EM QUE EU QUISER FALAR COM DEUS', 'NA HORA EM QUE EU QUISER FALAR COM DEUS', 'NA HORA EM QUE EU QUISER FALAR COM DEUS,\nDOBRAR OS MEUS JOELHOS E ORAR,\n\nEU VOU CLAMAR PRIMEIRO \nPELO SANGUE DE JESUS, \nSÓ ELE PODE ME PURIFICAR. \n\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO.\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO. \n\nNA HORA EM QUE EU \nQUISER FALAR COM DEUS,\nDOBRAR OS MEUS JOELHOS E ORAR,\n\nEU VOU CLAMAR PRIMEIRO \nPELO SANGUE DE JESUS,\nSÓ ELE PODE ME PURIFICAR.\nEU VOU CLAMAR PRIMEIRO \nPELO SANGUE DE JESUS,\nSÓ ELE PODE ME PURIFICAR. \n\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO.\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO.', 'NA HORA EM QUE EU QUISER FALAR COM DEUS,\nDOBRAR OS MEUS JOELHOS E ORAR,\n\nEU VOU CLAMAR PRIMEIRO <bis>\nPELO SANGUE DE JESUS, <bis>\nSÓ ELE PODE ME PURIFICAR. <bis>\n\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO.\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO. \n\nNA HORA EM QUE EU \nQUISER FALAR COM DEUS,\nDOBRAR OS MEUS JOELHOS E ORAR,\n\nEU VOU CLAMAR PRIMEIRO \nPELO SANGUE DE JESUS,\nSÓ ELE PODE ME PURIFICAR.\nEU VOU CLAMAR PRIMEIRO \nPELO SANGUE DE JESUS,\nSÓ ELE PODE ME PURIFICAR. \n\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO.\nSANGUE PRECIOSO, \nQUE RENOVA A COMUNHÃO, \nDÁ VIDA E PLENA PAZ AO CORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (50, 'O SANGUE DE JESUS', 'O SANGUE DE JESUS', 'O SANGUE DE JESUS\nQUE POR NÓS FOI DERRAMADO\nPARA NOS CONCEDER\nO PERDÃO DOS NOSSOS PECADOS.\nESTE SANGUE TÃO PURO\nVEM TRAZER-NOS SALVAÇÃO,\nVITÓRIA, PAZ E LIBERTAÇÃO.\n\nO SANGUE DE JESUS\nQUE POR NÓS FOI DERRAMADO\nPARA NOS CONCEDER\nO PERDÃO DOS NOSSOS PECADOS.\nESTE SANGUE TÃO PURO\nVEM TRAZER-NOS SALVAÇÃO,\nVITÓRIA, PAZ E LIBERTAÇÃO.', 'O SANGUE DE JESUS\nQUE POR NÓS FOI DERRAMADO\nPARA NOS CONCEDER\nO PERDÃO DOS NOSSOS PECADOS.\nESTE SANGUE TÃO PURO\nVEM TRAZER-NOS SALVAÇÃO,\nVITÓRIA, PAZ E LIBERTAÇÃO.\n\nO SANGUE DE JESUS\nQUE POR NÓS FOI DERRAMADO\nPARA NOS CONCEDER\nO PERDÃO DOS NOSSOS PECADOS.\nESTE SANGUE TÃO PURO<bis>\nVEM TRAZER-NOS SALVAÇÃO,<bis>\nVITÓRIA, PAZ E LIBERTAÇÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (51, 'O CORDEIRO QUE NA CRUZ MORREU', 'O CORDEIRO QUE NA CRUZ MORREU', 'O CORDEIRO QUE NA CRUZ MORREU\nVIVO ESTÁ ENTRE NÓS,\nDERRAMOU SEU SANGUE INOCENTE\nPARA NOS PURIFICAR.\n\nCORO\nNÓS CLAMAMOS POR ESTE SANGUE,\nQUE É ESPÍRITO DE VIDA,\nÉ O NOSSO ESCUDO, NOSSA PROTEÇÃO.\nESTE SANGUE NOS TRAZ O PERDÃO.\n\nDE ALTO A BAIXO O VÉU SE RASGOU\nQUANDO JESUS EXPIROU,\nPERMITINDO A NOSSA ENTRADA\nNO SANTÍSSIMO LUGAR.\n\nCORO\nNÓS CLAMAMOS POR ESTE SANGUE,\nQUE É ESPÍRITO DE VIDA,\nÉ O NOSSO ESCUDO, NOSSA PROTEÇÃO.\nESTE SANGUE NOS TRAZ O PERDÃO.\n\nFINAL: \nÉ O NOSSO ESCUDO, \nNOSSA PROTEÇÃO.\nESTE SANGUE NOS TRAZ COMUNHÃO.', 'O CORDEIRO QUE NA CRUZ MORREU\nVIVO ESTÁ ENTRE NÓS,\nDERRAMOU SEU SANGUE INOCENTE\nPARA NOS PURIFICAR.\n\n<coro>\nNÓS CLAMAMOS POR ESTE SANGUE,\nQUE É ESPÍRITO DE VIDA,\nÉ O NOSSO ESCUDO, NOSSA PROTEÇÃO.\nESTE SANGUE NOS TRAZ O PERDÃO.\n\nDE ALTO A BAIXO O VÉU SE RASGOU\nQUANDO JESUS EXPIROU,\nPERMITINDO A NOSSA ENTRADA\nNO SANTÍSSIMO LUGAR.\n\n<coro>\nNÓS CLAMAMOS POR ESTE SANGUE,\nQUE É ESPÍRITO DE VIDA,\nÉ O NOSSO ESCUDO, NOSSA PROTEÇÃO.\nESTE SANGUE NOS TRAZ O PERDÃO.\n\n\n<final>É O NOSSO ESCUDO, \nNOSSA PROTEÇÃO.\nESTE SANGUE NOS TRAZ COMUNHÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (52, 'ESCUTA-ME, SENHOR', 'ESCUTA-ME, SENHOR', 'ESCUTA-ME, SENHOR, \nESCUTA AS MINHAS SÚPLICAS,\nINCLINA OS TEUS OUVIDOS À MINHA VOZ.\nCLAMO, Ó SENHOR, PELO SANGUE DE JESUS, \nVEM ME LIBERTAR E ME TRANSFORMAR.\n\nINSTRUMENTOS\n\nRENOVA A MINHA VIDA, \nENCHE-ME DE GOZO E PAZ,\nUNGE-ME A CABEÇA \nCOM O ÓLEO DO TEU ESPÍRITO\nE O MEU CÁLICE TRANSBORDA, \nRENOVA-ME, SENHOR.\n\nCLAMO, Ó SENHOR, \nPELO SANGUE DE JESUS,\nVEM ME LIBERTAR E ME TRANSFORMAR,\nRENOVA A MINHA VIDA,\nENCHE-ME DE GOZO E PAZ,\nTRANSBORDA EM MIM, SENHOR,\nA TUA GRAÇA E TEU AMOR.', 'ESCUTA-ME, SENHOR, \nESCUTA AS MINHAS SÚPLICAS,\nINCLINA OS TEUS OUVIDOS À MINHA VOZ.\nCLAMO, Ó SENHOR, PELO SANGUE DE JESUS, \nVEM ME LIBERTAR E ME TRANSFORMAR.\n<instrumentos>\n\n\nRENOVA A MINHA VIDA, \nENCHE-ME DE GOZO E PAZ,\nUNGE-ME A CABEÇA \nCOM O ÓLEO DO TEU ESPÍRITO\nE O MEU CÁLICE TRANSBORDA, \nRENOVA-ME, SENHOR.\n\nCLAMO, Ó SENHOR, \nPELO SANGUE DE JESUS,\nVEM ME LIBERTAR E ME TRANSFORMAR,\nRENOVA A MINHA VIDA,\nENCHE-ME DE GOZO E PAZ,\nTRANSBORDA EM MIM, SENHOR,\nA TUA GRAÇA E TEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (53, 'O SANGUE DO CORDEIRO DE DEUS', 'O SANGUE DO CORDEIRO DE DEUS', 'O SANGUE DO CORDEIRO DE DEUS\nFOI VERTIDO ALI NA CRUZ,\nNOS TRAZENDO REDENÇÃO \nE COMUNHÃO COM DEUS.\n\nCORO\nPURIFICA-NOS, SENHOR,\nSANTIFICA-NOS PELO SANGUE REMIDOR,\nSÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,\nPOIS COM FÉ NÓS CLAMAMOS.\n\nINSTRUMENTOS\n\nO SUMO SACERDOTE, JESUS,\nFOI PERFEITO NO SEU GESTO\nE PAGOU COM O SEU SANGUE \nA NOSSA SALVAÇÃO.\n\nFINAL: \nPURIFICA-NOS, SENHOR,\nSANTIFICA-NOS PELO SANGUE REMIDOR,\nSÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,\nPOIS COM FÉ (POIS COM FÉ)\nNÓS CLAMAMOS (NÓS CLAMAMOS)\nPOIS COM FÉ (POIS COM FÉ)\nNÓS CLAMAMOS.', 'O SANGUE DO CORDEIRO DE DEUS\nFOI VERTIDO ALI NA CRUZ,\nNOS TRAZENDO REDENÇÃO \nE COMUNHÃO COM DEUS.\n\n<coro>\nPURIFICA-NOS, SENHOR,\nSANTIFICA-NOS PELO SANGUE REMIDOR,\nSÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,\nPOIS COM FÉ NÓS CLAMAMOS.\n<instrumentos>\n\n\nO SUMO SACERDOTE, JESUS,\nFOI PERFEITO NO SEU GESTO\nE PAGOU COM O SEU SANGUE \nA NOSSA SALVAÇÃO.\n\n\n<final>PURIFICA-NOS, SENHOR,\nSANTIFICA-NOS PELO SANGUE REMIDOR,\nSÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,\nPOIS COM FÉ (POIS COM FÉ)\nNÓS CLAMAMOS (NÓS CLAMAMOS)\nPOIS COM FÉ (POIS COM FÉ)\nNÓS CLAMAMOS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (54, 'HÁ VITÓRIA SEMPRE EM TI, SENHOR', 'HÁ VITÓRIA SEMPRE EM TI, SENHOR', 'HÁ VITÓRIA SEMPRE EM TI, SENHOR, (BIS)\nPELO SANGUE DE JESUS DERRAMADO POR MIM,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR.\n\nHÁ VITÓRIA SEMPRE EM TI, SENHOR, (BIS)\nCONTRA AS TREVAS TENHO LUZ,\nSOU REMIDO POR JESUS,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR.\n\nHÁ VITÓRIA SEMPRE EM TI, SENHOR,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR,\nPELA VOLTA DE JESUS,\nPELA PAZ NO CORAÇÃO,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR.', 'HÁ VITÓRIA SEMPRE EM TI, SENHOR, <bis>\nPELO SANGUE DE JESUS DERRAMADO POR MIM,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR.\n\nHÁ VITÓRIA SEMPRE EM TI, SENHOR, <bis>\nCONTRA AS TREVAS TENHO LUZ,\nSOU REMIDO POR JESUS,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR.\n\nHÁ VITÓRIA SEMPRE EM TI, SENHOR,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR,\nPELA VOLTA DE JESUS,\nPELA PAZ NO CORAÇÃO,\nHÁ VITÓRIA SEMPRE EM TI, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (55, 'SENHOR, MEU DEUS E PAI', 'SENHOR, MEU DEUS E PAI', 'SENHOR, MEU DEUS E PAI\nEU ME PROSTRO DIANTE DE TI:\nPERDÃO TE PEÇO, AGORA,\nPELO SANGUE DE JESUS.\n\nLIBERTA-ME, SENHOR; \nPURIFICA-ME, Ó PAI \nPOR JESUS, QUE É O MEU REI, \nAMIGO E REMIDOR. \nINSTRUMENTOS\n\nSENHOR, MEU DEUS E PAI\nEU ME PROSTRO DIANTE DE TI:\nPERDÃO TE PEÇO, AGORA,\nPELO SANGUE DE JESUS.\n\nLIBERTA-ME, SENHOR; \nPURIFICA-ME, Ó PAI \nPOR JESUS, QUE É O MEU REI, \nAMIGO E REMIDOR.', 'SENHOR, MEU DEUS E PAI\nEU ME PROSTRO DIANTE DE TI:\nPERDÃO TE PEÇO, AGORA,\nPELO SANGUE DE JESUS.\n\nLIBERTA-ME, SENHOR; <bis>\nPURIFICA-ME, Ó PAI <bis>\nPOR JESUS, QUE É O MEU REI, <bis>\nAMIGO E REMIDOR. <bis>\n<instrumentos><bis>\n\n\nSENHOR, MEU DEUS E PAI\nEU ME PROSTRO DIANTE DE TI:\nPERDÃO TE PEÇO, AGORA,\nPELO SANGUE DE JESUS.\n\nLIBERTA-ME, SENHOR; <bis>\nPURIFICA-ME, Ó PAI <bis>\nPOR JESUS, QUE É O MEU REI, <bis>\nAMIGO E REMIDOR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (56, 'VITÓRIA SOBRE VITÓRIA', 'VITÓRIA SOBRE VITÓRIA', 'VITÓRIA SOBRE VITÓRIA A TI PERTENCE\nPOIS O PREÇO LÁ NA CRUZ TU JÁ PAGASTE;\nTEU SANGUE PURO DERRAMASTE,\nALELUIA, GLÓRIA AO REI!\nSANTO É O DEUS FORTE! (BIS)\n\nO ESPÍRITO ESTÁ LUTANDO CONTRA \nA CARNE, MAS A VITÓRIA JÁ FOI DECRETADA;\nTUA VONTADE PREVALECEU,\nALELUIA, GLÓRIA AO REI!\nSANTO É O DEUS FORTE! (BIS)', 'VITÓRIA SOBRE VITÓRIA A TI PERTENCE\nPOIS O PREÇO LÁ NA CRUZ TU JÁ PAGASTE;\nTEU SANGUE PURO DERRAMASTE,\nALELUIA, GLÓRIA AO REI!\nSANTO É O DEUS FORTE! <bis>\n\nO ESPÍRITO ESTÁ LUTANDO CONTRA \nA CARNE, MAS A VITÓRIA JÁ FOI DECRETADA;\nTUA VONTADE PREVALECEU,\nALELUIA, GLÓRIA AO REI!\nSANTO É O DEUS FORTE! <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (57, 'EM FERVENTE ORAÇÃO', 'EM FERVENTE ORAÇÃO', 'EM FERVENTE ORAÇÃO, \nVENS O TEU CORAÇÃO\nNA PRESENÇA DE DEUS DERRAMAR;\nMAS NÃO PODES FRUIR O QUE ESTÁS A PEDIR, \nSEM QUE TUDO ABANDONES NO ALTAR.\n\nCORO\nQUANDO TUDO PERANTE O SENHOR ESTIVER,\nE TODO O TEU SER ELE CONTROLAR,\nSÓ ENTÃO HÁS DE VER\nQUE O SENHOR TEM PODER,\nQUANDO TUDO DEIXARES NO ALTAR.\n\nMARAVILHAS DE AMOR TE FARÁ O SENHOR,\nATENDENDO A ORAÇÃO QUE ACEITAR;\nSEU IMENSO PODER TE VIRÁ SOCORRER,\nQUANDO TUDO DEIXARES NO ALTAR.\n\nCORO\nQUANDO TUDO PERANTE O SENHOR ESTIVER,\nE TODO O TEU SER ELE CONTROLAR,\nSÓ ENTÃO HÁS DE VER\nQUE O SENHOR TEM PODER,\nQUANDO TUDO DEIXARES NO ALTAR.\n\nSE ORARES, ENTÃO, SEM QUE O TEU CORAÇÃO\nGOZE A PAZ QUE O SENHOR PODE DAR,\nÉ QUE DEUS NÃO SENTIU\nQUE TUA ALMA SE ABRIU,\nTUDO, TUDO DEIXANDO NO ALTAR.\n\nCORO\nQUANDO TUDO PERANTE O SENHOR ESTIVER,\nE TODO O TEU SER ELE CONTROLAR,\nSÓ ENTÃO HÁS DE VER\nQUE O SENHOR TEM PODER,\nQUANDO TUDO DEIXARES NO ALTAR.', 'EM FERVENTE ORAÇÃO, \nVENS O TEU CORAÇÃO\nNA PRESENÇA DE DEUS DERRAMAR;\nMAS NÃO PODES FRUIR O QUE ESTÁS A PEDIR, \nSEM QUE TUDO ABANDONES NO ALTAR.\n\n<coro>\nQUANDO TUDO PERANTE O SENHOR ESTIVER,\nE TODO O TEU SER ELE CONTROLAR,\nSÓ ENTÃO HÁS DE VER\nQUE O SENHOR TEM PODER,\nQUANDO TUDO DEIXARES NO ALTAR.\n\nMARAVILHAS DE AMOR TE FARÁ O SENHOR,\nATENDENDO A ORAÇÃO QUE ACEITAR;\nSEU IMENSO PODER TE VIRÁ SOCORRER,\nQUANDO TUDO DEIXARES NO ALTAR.\n\n<coro>\nQUANDO TUDO PERANTE O SENHOR ESTIVER,\nE TODO O TEU SER ELE CONTROLAR,\nSÓ ENTÃO HÁS DE VER\nQUE O SENHOR TEM PODER,\nQUANDO TUDO DEIXARES NO ALTAR.\n\nSE ORARES, ENTÃO, SEM QUE O TEU CORAÇÃO\nGOZE A PAZ QUE O SENHOR PODE DAR,\nÉ QUE DEUS NÃO SENTIU\nQUE TUA ALMA SE ABRIU,\nTUDO, TUDO DEIXANDO NO ALTAR.\n\n<coro>\nQUANDO TUDO PERANTE O SENHOR ESTIVER,\nE TODO O TEU SER ELE CONTROLAR,\nSÓ ENTÃO HÁS DE VER\nQUE O SENHOR TEM PODER,\nQUANDO TUDO DEIXARES NO ALTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (58, 'ATENDE A VOZ DO MEU CLAMOR', 'ATENDE A VOZ DO MEU CLAMOR', 'ATENDE A VOZ DO MEU CLAMOR,\nÓ REI, DEUS MEU,\nPOIS EU A TI ORAREI COM MAIS FERVOR,\nDÁ OUVIDOS À VOZ DA MINHA ORAÇÃO,\nA MINHA MEDITAÇÃO ELEVO A TI.\n\nCORO\nPELA MANHÃ TU OUVIRÁS A MINHA \nVOZ, EM LONGAS NOITES EU A TI VIGIAREI;\nE O TEU REINO, Ó DEUS BENDITO, VENHA A NÓS,\nDERRAMA AS TUAS BÊNÇÃOS À TUA GREI.\n\nÓ DEUS BENDITO,\nNÃO TENS PRAZER NA INIQUIDADE;\nTUA PALAVRA É ESCUDO E BROQUEL;\nELA EXTERMINA DESTE MUNDO TODA A MALDADE \nE CONSERVA EM RETIDÃO QUEM FOR FIEL.\n\nCORO\nPELA MANHÃ TU OUVIRÁS A MINHA \nVOZ, EM LONGAS NOITES EU A TI VIGIAREI;\nE O TEU REINO, Ó DEUS BENDITO, VENHA A NÓS,\nDERRAMA AS TUAS BÊNÇÃOS À TUA GREI.\n\nEU ENTRAREI EM TUA CASA PELA GRANDEZA, \nE EM TEU TEMPLO ME INCLINAREI PERANTE TI,\nGUIA MEUS PASSOS EM TUA JUSTIÇA E REALEZA \nE VENCE O INIMIGO PARA MIM.', 'ATENDE A VOZ DO MEU CLAMOR,\nÓ REI, DEUS MEU,\nPOIS EU A TI ORAREI COM MAIS FERVOR,\nDÁ OUVIDOS À VOZ DA MINHA ORAÇÃO,\nA MINHA MEDITAÇÃO ELEVO A TI.\n\n<coro>\nPELA MANHÃ TU OUVIRÁS A MINHA \nVOZ, EM LONGAS NOITES EU A TI VIGIAREI;\nE O TEU REINO, Ó DEUS BENDITO, VENHA A NÓS,\nDERRAMA AS TUAS BÊNÇÃOS À TUA GREI.\n\nÓ DEUS BENDITO,\nNÃO TENS PRAZER NA INIQUIDADE;\nTUA PALAVRA É ESCUDO E BROQUEL;\nELA EXTERMINA DESTE MUNDO TODA A MALDADE \nE CONSERVA EM RETIDÃO QUEM FOR FIEL.\n\n<coro>\nPELA MANHÃ TU OUVIRÁS A MINHA \nVOZ, EM LONGAS NOITES EU A TI VIGIAREI;\nE O TEU REINO, Ó DEUS BENDITO, VENHA A NÓS,\nDERRAMA AS TUAS BÊNÇÃOS À TUA GREI.\n\nEU ENTRAREI EM TUA CASA PELA GRANDEZA, \nE EM TEU TEMPLO ME INCLINAREI PERANTE TI,\nGUIA MEUS PASSOS EM TUA JUSTIÇA E REALEZA \nE VENCE O INIMIGO PARA MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (59, 'SE ORARMOS AO SENHOR', 'SE ORARMOS AO SENHOR', 'SE ORARMOS AO SENHOR,\nSE CANTARMOS SEUS LOUVORES,\nSUA GLÓRIA ENCHERÁ\nESTE LUGAR, ESTE LUGAR.\nRIOS DE ÁGUAS VIVAS FLUIRÃO\nNO MEU, NO TEU CORAÇÃO.\nE O GRANDE AMOR DE DEUS,\nREVELADO EM JESUS,\nSIM, ENCHERÁ ESTE LUGAR.\nINSTRUMENTOS\n\nSE ORARMOS AO SENHOR,\nSE CANTARMOS SEUS LOUVORES,\nSUA GLÓRIA ENCHERÁ\nESTE LUGAR, ESTE LUGAR.\nRIOS DE ÁGUAS VIVAS FLUIRÃO\nNO MEU, NO TEU CORAÇÃO.\nE O GRANDE AMOR DE DEUS,\nREVELADO EM JESUS,\nSIM, ENCHERÁ ESTE LUGAR.\n\nFINAL: \nRIOS DE ÁGUAS VIVAS FLUIRÃO\nNO MEU, NO TEU CORAÇÃO.\nE O GRANDE AMOR DE DEUS,\nREVELADO EM JESUS, \nSIM, ENCHERÁ ESTE LUGAR. (3X)', 'SE ORARMOS AO SENHOR,\nSE CANTARMOS SEUS LOUVORES,\nSUA GLÓRIA ENCHERÁ\nESTE LUGAR, ESTE LUGAR.\nRIOS DE ÁGUAS VIVAS FLUIRÃO\nNO MEU, NO TEU CORAÇÃO.\nE O GRANDE AMOR DE DEUS,\nREVELADO EM JESUS,\nSIM, ENCHERÁ ESTE LUGAR.\n<instrumentos>\n\n\nSE ORARMOS AO SENHOR,\nSE CANTARMOS SEUS LOUVORES,\nSUA GLÓRIA ENCHERÁ\nESTE LUGAR, ESTE LUGAR.\nRIOS DE ÁGUAS VIVAS FLUIRÃO\nNO MEU, NO TEU CORAÇÃO.\nE O GRANDE AMOR DE DEUS,\nREVELADO EM JESUS,\nSIM, ENCHERÁ ESTE LUGAR.\n\n\n<final>RIOS DE ÁGUAS VIVAS FLUIRÃO\nNO MEU, NO TEU CORAÇÃO.\nE O GRANDE AMOR DE DEUS,\nREVELADO EM JESUS,\nSIM, ENCHERÁ ESTE LUGAR. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (60, 'BEM DE MANHÃ, EMBORA O CÉU SERENO', 'BEM DE MANHÃ, EMBORA O CÉU SERENO', 'BEM DE MANHÃ, EMBORA O CÉU SERENO\nPAREÇA UM DIA CALMO ANUNCIAR,\nVIGIA E ORA, O CORAÇÃO PEQUENO\nUM TEMPORAL PODE ABRIGAR.\n\nCORO\nBEM DE MANHÃ, E SEM CESSAR,\nVIGIAR E ORAR!\n\nAO MEIO DIA, E QUANDO OS SONS DA TERRA\nABAFAM MAIS DE DEUS A VOZ DE AMOR,\nRECORRE À ORAÇÃO, EVITA A GUERRA,\nE GOZA PAZ COM O SENHOR.\n\nCORO\nBEM DE MANHÃ, E SEM CESSAR,\nVIGIAR E ORAR!\n\nDO DIA AO FIM, APÓS OS TEUS LIDARES,\nRELEMBRA AS BÊNÇÃOS DO CELESTE AMOR,\nE CONTA A DEUS PRAZERES E PESARES,\nDEPONDO EM SUAS MÃOS A DOR.\n\nCORO\nBEM DE MANHÃ, E SEM CESSAR,\nVIGIAR E ORAR!\n\nE SEM CESSAR, VIGIA A TODO INSTANTE,\nQUE O INIMIGO ATACA SEM PARAR,\nSÓ COM JESUS EM COMUNHÃO CONSTANTE,\nPODE O MORTAL AO CÉU CHEGAR.', 'BEM DE MANHÃ, EMBORA O CÉU SERENO\nPAREÇA UM DIA CALMO ANUNCIAR,\nVIGIA E ORA, O CORAÇÃO PEQUENO\nUM TEMPORAL PODE ABRIGAR.\n\n<coro>\nBEM DE MANHÃ, E SEM CESSAR,\nVIGIAR E ORAR!\n\nAO MEIO DIA, E QUANDO OS SONS DA TERRA\nABAFAM MAIS DE DEUS A VOZ DE AMOR,\nRECORRE À ORAÇÃO, EVITA A GUERRA,\nE GOZA PAZ COM O SENHOR.\n\n<coro>\nBEM DE MANHÃ, E SEM CESSAR,\nVIGIAR E ORAR!\n\nDO DIA AO FIM, APÓS OS TEUS LIDARES,\nRELEMBRA AS BÊNÇÃOS DO CELESTE AMOR,\nE CONTA A DEUS PRAZERES E PESARES,\nDEPONDO EM SUAS MÃOS A DOR.\n\n<coro>\nBEM DE MANHÃ, E SEM CESSAR,\nVIGIAR E ORAR!\n\nE SEM CESSAR, VIGIA A TODO INSTANTE,\nQUE O INIMIGO ATACA SEM PARAR,\nSÓ COM JESUS EM COMUNHÃO CONSTANTE,\nPODE O MORTAL AO CÉU CHEGAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (61, 'SUBA A MINHA ORAÇÃO', 'SUBA A MINHA ORAÇÃO', 'SUBA A MINHA ORAÇÃO\nPERANTE A TUA FACE COMO INCENSO;\nSEJA O LEVANTAR DE MINHAS MÃOS\nCOMO SACRIFÍCIO DA TARDE.\n\nCORO \nESCUTA-ME, SENHOR!\nINCLINA OS TEUS OUVIDOS \nÀ MINHA VOZ QUANDO A TI CLAMAR.\n\nNÃO ME DEIXES CAMINHAR\nSEM TER TUA PRESENÇA,\nÓ SENHOR, MEU DEUS!\n''SIM, CONTIGO IRÁ MINHA PRESENÇA\nPARA TE FAZER DESCANSAR''.\n\nCORO (2X)\nESCUTA-ME, SENHOR!\nINCLINA OS TEUS OUVIDOS \nÀ MINHA VOZ QUANDO A TI CLAMAR.', 'SUBA A MINHA ORAÇÃO\nPERANTE A TUA FACE COMO INCENSO;\nSEJA O LEVANTAR DE MINHAS MÃOS\nCOMO SACRIFÍCIO DA TARDE.\n\n<coro>\nESCUTA-ME, SENHOR!\nINCLINA OS TEUS OUVIDOS \nÀ MINHA VOZ QUANDO A TI CLAMAR.\n\nNÃO ME DEIXES CAMINHAR\nSEM TER TUA PRESENÇA,\nÓ SENHOR, MEU DEUS!\n''SIM, CONTIGO IRÁ MINHA PRESENÇA\nPARA TE FAZER DESCANSAR''.\n\n<coro tipo=''2X''>\nESCUTA-ME, SENHOR!\nINCLINA OS TEUS OUVIDOS \nÀ MINHA VOZ QUANDO A TI CLAMAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (62, 'NO SILÊNCIO DA NOITE', 'NO SILÊNCIO DA NOITE', 'NO SILÊNCIO DA NOITE EU ORO AO SENHOR;\nNO SILÊNCIO DA NOITE SUPLICO AO SENHOR;\nMURMURO, BAIXINHO, ESTA LINDA CANÇÃO, \nNO SILÊNCIO DA NOITE\nEU FAÇO A MINHA ORAÇÃO.\n\nAS ESTRELAS DO CÉU ESTÃO A CINTILAR\nE EU, AO SENHOR, ESTOU A SUPLICAR;\nMURMURO, BAIXINHO, ESTA LINDA CANÇÃO; \nNO SILÊNCIO DA NOITE EU FAÇO A MINHA ORAÇÃO.\n\nE QUANDO PELA ALVORADA RETORNO AO SENHOR,\nDELE RECEBO BÊNÇÃOS E PODER PRA VENCER;\nENTREGO MINHA VIDA AO SERVIÇO DO REI; \nNO SILÊNCIO DA NOITE EU FAÇO A MINHA ORAÇÃO.', 'NO SILÊNCIO DA NOITE EU ORO AO SENHOR;\nNO SILÊNCIO DA NOITE SUPLICO AO SENHOR;\nMURMURO, BAIXINHO, ESTA LINDA CANÇÃO, \nNO SILÊNCIO DA NOITE\nEU FAÇO A MINHA ORAÇÃO.\n\nAS ESTRELAS DO CÉU ESTÃO A CINTILAR\nE EU, AO SENHOR, ESTOU A SUPLICAR;\nMURMURO, BAIXINHO, ESTA LINDA CANÇÃO; \nNO SILÊNCIO DA NOITE EU FAÇO A MINHA ORAÇÃO.\n\nE QUANDO PELA ALVORADA RETORNO AO SENHOR,\nDELE RECEBO BÊNÇÃOS E PODER PRA VENCER;\nENTREGO MINHA VIDA AO SERVIÇO DO REI; \nNO SILÊNCIO DA NOITE EU FAÇO A MINHA ORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (63, 'INVOCA-ME E TE RESPONDEREI', 'INVOCA-ME E TE RESPONDEREI', 'INVOCA-ME E TE RESPONDEREI, \nANUNCIAR-TE-EI COISAS GRANDES \nE OCULTAS QUE NÃO SABES, \nPORQUE ASSIM DIZ O SENHOR,\nO DEUS DE ISRAEL. \n\nINVOCA-ME E TE RESPONDEREI, \nANUNCIAR-TE-EI COISAS GRANDES \nE OCULTAS QUE NÃO SABES, \nPORQUE ASSIM DIZ O SENHOR,\nO DEUS DE ISRAEL. (3X)', 'INVOCA-ME E TE RESPONDEREI, \nANUNCIAR-TE-EI COISAS GRANDES \nE OCULTAS QUE NÃO SABES, \nPORQUE ASSIM DIZ O SENHOR,\nO DEUS DE ISRAEL. \n\nINVOCA-ME E TE RESPONDEREI, \nANUNCIAR-TE-EI COISAS GRANDES \nE OCULTAS QUE NÃO SABES, \nPORQUE ASSIM DIZ O SENHOR,\nO DEUS DE ISRAEL. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (64, 'BRILHE SOBRE MIM', 'BRILHE SOBRE MIM', 'BRILHE SOBRE MIM A TUA LUZ PRA TODO SEMPRE,\nPRA QUE EU POSSA COMPREENDER TEU CAMINHO.\nBRILHE SOBRE MIM A TUA LUZ\nPRA TODO SEMPRE, PRA QUE EU POSSA \nCOMPREENDER TEU FALAR.\n\n''CLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE NÃO SABES, MAS EU SEI.\nCLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE SÓ EU SEI.''\n\nINSTRUMENTOS\n\nBRILHE SOBRE MIM A TUA LUZ PRA TODO SEMPRE,\nPRA QUE EU POSSA COMPREENDER TEU CAMINHO.\nBRILHE SOBRE MIM A TUA LUZ\nPRA TODO SEMPRE, PRA QUE EU POSSA \nCOMPREENDER TEU FALAR.\n\n''CLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE NÃO SABES, MAS EU SEI.\nCLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE SÓ EU SEI.''', 'BRILHE SOBRE MIM A TUA LUZ PRA TODO SEMPRE,\nPRA QUE EU POSSA COMPREENDER TEU CAMINHO.\nBRILHE SOBRE MIM A TUA LUZ\nPRA TODO SEMPRE, PRA QUE EU POSSA \nCOMPREENDER TEU FALAR.\n\n''CLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE NÃO SABES, MAS EU SEI.\nCLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE SÓ EU SEI.''\n<instrumentos>\n\n\nBRILHE SOBRE MIM A TUA LUZ PRA TODO SEMPRE,\nPRA QUE EU POSSA COMPREENDER TEU CAMINHO.\nBRILHE SOBRE MIM A TUA LUZ\nPRA TODO SEMPRE, PRA QUE EU POSSA \nCOMPREENDER TEU FALAR.\n\n''CLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE NÃO SABES, MAS EU SEI.\nCLAMA A MIM E RESPONDER-TE-EI,\nANUNCIAR-TE-EI COISAS GRANDES\nE OCULTAS QUE SÓ EU SEI.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (65, 'QUANDO O DIA AMANHECE', 'QUANDO O DIA AMANHECE', 'QUANDO O DIA AMANHECE \nEU BUSCO AO SENHOR.\nELE ME FAZ SENTIR O SEU GRANDE AMOR;\nENSINA-ME, Ó SENHOR, CONTIGO CAMINHAR,\nOUVIR A TUA DOCE VOZ A ME CHAMAR.\n\nOUVE A MINHA ORAÇÃO, SENHOR,\nPOIS EU QUERO TE SERVIR, \nSENHOR DE AMOR, DE AMOR.\n\nQUANDO O DIA AMANHECE \nEU BUSCO AO SENHOR.\nELE ME FAZ SENTIR O SEU GRANDE AMOR;\nENSINA-ME, Ó SENHOR, CONTIGO CAMINHAR,\nOUVIR A TUA DOCE VOZ A ME CHAMAR.\n\nOUVE A MINHA ORAÇÃO, SENHOR,\nPOIS EU QUERO TE SERVIR, \nSENHOR DE AMOR, DE AMOR.\n\nFINAL: DE AMOR', 'QUANDO O DIA AMANHECE \nEU BUSCO AO SENHOR.\nELE ME FAZ SENTIR O SEU GRANDE AMOR;\nENSINA-ME, Ó SENHOR, CONTIGO CAMINHAR,\nOUVIR A TUA DOCE VOZ A ME CHAMAR.\n\nOUVE A MINHA ORAÇÃO, SENHOR,\nPOIS EU QUERO TE SERVIR,\nSENHOR DE AMOR, DE AMOR.\n\nQUANDO O DIA AMANHECE \nEU BUSCO AO SENHOR.\nELE ME FAZ SENTIR O SEU GRANDE AMOR;\nENSINA-ME, Ó SENHOR, CONTIGO CAMINHAR,\nOUVIR A TUA DOCE VOZ A ME CHAMAR.\n\nOUVE A MINHA ORAÇÃO, SENHOR,\nPOIS EU QUERO TE SERVIR,\nSENHOR DE AMOR, DE AMOR.\n<final>DE AMOR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (66, 'DE MADRUGADA EU BUSCO A FACE DO SENHOR', 'DE MADRUGADA EU BUSCO A FACE DO SENHOR', 'DE MADRUGADA EU BUSCO A FACE \nDO SENHOR PEDINDO BÊNÇÃOS \nE BATISMO COM AMOR;\nO GALO CANTA, \nMADRUGADA VAI CHEGAR, \nEU, DE JOELHOS, \nAO SENHOR VOU ADORAR.\n\nALELUIA, ALELUIA, MEU JESUS!\nTU ÉS A LUZ DO DIA QUE VAI COMEÇAR.\nALELUIA, ALELUIA, MEU JESUS!\nEU, DE JOELHOS, AO SENHOR VOU ADORAR.', 'DE MADRUGADA EU BUSCO A FACE \nDO SENHOR PEDINDO BÊNÇÃOS \nE BATISMO COM AMOR;\nO GALO CANTA, \nMADRUGADA VAI CHEGAR, \nEU, DE JOELHOS, \nAO SENHOR VOU ADORAR.\n\nALELUIA, ALELUIA, MEU JESUS!\nTU ÉS A LUZ DO DIA QUE VAI COMEÇAR.\nALELUIA, ALELUIA, MEU JESUS!\nEU, DE JOELHOS, AO SENHOR VOU ADORAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (67, 'TOCA PELA FÉ', 'TOCA PELA FÉ', 'TOCA PELA FÉ NO VESTIDO DE JESUS\nE DELE VAI SAIR VIRTUDE,\nPEDE SEM TEMER, ELE VAI TE OUVIR,\nTOCA PELA FÉ EM JESUS.\n\nCORO (2X)\nPOIS TODO O QUE PEDE, RECEBE, \nE O QUE BUSCA, ENCONTRA O SENHOR.\n \nINSTRUMENTOS\n\nPODE O PAI NEGAR AO FILHO SEU\nE DAR PEDRA AO INVÉS DE PÃO?\nQUANTO MAIS O PAI QUE ESTÁ NO CÉU, \nTUDO QUE PEDIRES TE DARÁ.\n\nCORO (2X)\nPOIS TODO O QUE PEDE, RECEBE, E \nO QUE BUSCA, ENCONTRA O SENHOR. \n\nFINAL: \nPEDE SEM TEMER, ELE VAI TE OUVIR, \nTOCA PELA FÉ EM JESUS.', 'TOCA PELA FÉ NO VESTIDO DE JESUS\nE DELE VAI SAIR VIRTUDE,\nPEDE SEM TEMER, ELE VAI TE OUVIR,\nTOCA PELA FÉ EM JESUS.\n\n<coro tipo=''2X''>\nPOIS TODO O QUE PEDE, RECEBE, \nE O QUE BUSCA, ENCONTRA O SENHOR.\n<instrumentos>\n\n\nPODE O PAI NEGAR AO FILHO SEU\nE DAR PEDRA AO INVÉS DE PÃO?\nQUANTO MAIS O PAI QUE ESTÁ NO CÉU, \nTUDO QUE PEDIRES TE DARÁ.\n\n<coro tipo=''2X''>\nPOIS TODO O QUE PEDE, RECEBE, E \nO QUE BUSCA, ENCONTRA O SENHOR. \n<final>PEDE SEM TEMER, ELE VAI TE OUVIR, \nTOCA PELA FÉ EM JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (68, 'LÁ NO CIMO DO MONTE', 'LÁ NO CIMO DO MONTE', 'LÁ NO CIMO DO MONTE EU ESTOU \nME ENCURVANDO,\nBUSCANDO TUA FACE, MEU DIVINO SENHOR;\nMEU FARDO É PESADO, ESTOU TÃO CANSADO, \nMAS SEI QUE TU ÉS AMOR.\nOH! VEM RENOVAR, EM MEU CORAÇÃO\nA FÉ, O PODER, ME DÁ TUA MÃO;\nRENOVA, SENHOR.\n\nCOMO TERRA SEDENTA, \nA MINH''ALMA ANSEIA POR TEU SANTO ESPÍRITO, \nQUE DÁ VIDA E PODER, E QUANDO ME ERGUER,\nEU SEI QUE VOU TER MAIS FORÇA E ALEGRIA;\nDE GLÓRIA EM GLÓRIA ME VAIS TRANSFORMANDO, \nQUANDO EU, LÁ NO MONTE, \nESTOU ME ENCURVANDO,\nBUSCANDO-TE, Ó DEUS!', 'LÁ NO CIMO DO MONTE EU ESTOU \nME ENCURVANDO,\nBUSCANDO TUA FACE, MEU DIVINO SENHOR;\nMEU FARDO É PESADO, ESTOU TÃO CANSADO, \nMAS SEI QUE TU ÉS AMOR.\nOH! VEM RENOVAR, EM MEU CORAÇÃO\nA FÉ, O PODER, ME DÁ TUA MÃO;\nRENOVA, SENHOR.\n\nCOMO TERRA SEDENTA, \nA MINH''ALMA ANSEIA POR TEU SANTO ESPÍRITO, \nQUE DÁ VIDA E PODER, E QUANDO ME ERGUER,\nEU SEI QUE VOU TER MAIS FORÇA E ALEGRIA;\nDE GLÓRIA EM GLÓRIA ME VAIS TRANSFORMANDO, \nQUANDO EU, LÁ NO MONTE, \nESTOU ME ENCURVANDO,\nBUSCANDO-TE, Ó DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (69, 'O ANJO DO SENHOR ESTÁ PASSEANDO', 'O ANJO DO SENHOR ESTÁ PASSEANDO', 'O ANJO DO SENHOR ESTÁ PASSEANDO,\nESTÁ PASSEANDO AQUI NESTE LUGAR. \n\nDÁ LUGAR, IRMÃO, DÁ LUGAR, IRMÃO, \nE DEIXA O ANJO DO SENHOR TE VISITAR.', 'O ANJO DO SENHOR ESTÁ PASSEANDO,<bis>\nESTÁ PASSEANDO AQUI NESTE LUGAR. <bis>\n\nDÁ LUGAR, IRMÃO, DÁ LUGAR, IRMÃO, <bis>\nE DEIXA O ANJO DO SENHOR TE VISITAR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (70, 'PRECIOSAS SÃO AS HORAS', 'PRECIOSAS SÃO AS HORAS', 'PRECIOSAS SÃO AS HORAS\nNA PRESENÇA DE JESUS!\nCOMUNHÃO DELICIOSA \nDA MINHA ALMA COM A LUZ!\nOS CUIDADOS DESTE MUNDO\nNUNCA PODEM ME ABALAR,\nPOIS É ELE O MEU ABRIGO,\nQUANDO O TENTADOR CHEGAR (BIS)\n\nAO SENTIR-ME RODEADO\nDE CUIDADOS TERREAIS,\nIRRITADO, ABATIDO OU EM DÚVIDAS FATAIS,\nA JESUS EU ME DIRIJO \nNESTES TEMPOS DE AFLIÇÃO;\nAS PALAVRAS QUE ELE FALA\nTRAZEM-ME CONSOLAÇÃO (BIS)\n\nSE CONFESSO MEUS TEMORES,\nTODA A MINHA IMPERFEIÇÃO,\nELE ESCUTA COM PACIÊNCIA\nESSA TRISTE CONFISSÃO; \nCOM TERNURA REPREENDE\nMEU PECADO E TODO MAL,\nELE É SEMPRE O MEU AMIGO,\nO MELHOR E MAIS LEAL (BIS)\n\nSE QUEREIS SABER QUÃO DOCE\nÉ A SECRETA COMUNHÃO,\nPODEREIS MUI BEM PROVÁ-LA\nE TEREIS COMPENSAÇÃO;\nPROCURAI ESTAR SOZINHOS\nEM CONVERSA COM JESUS,\nPROVAREIS NA VOSSA VIDA\nO ESPÍRITO DA CRUZ (BIS)', 'PRECIOSAS SÃO AS HORAS\nNA PRESENÇA DE JESUS!\nCOMUNHÃO DELICIOSA \nDA MINHA ALMA COM A LUZ!\nOS CUIDADOS DESTE MUNDO\nNUNCA PODEM ME ABALAR,\nPOIS É ELE O MEU ABRIGO,\nQUANDO O TENTADOR CHEGAR <bis>\n\nAO SENTIR-ME RODEADO\nDE CUIDADOS TERREAIS,\nIRRITADO, ABATIDO OU EM DÚVIDAS FATAIS,\nA JESUS EU ME DIRIJO\nNESTES TEMPOS DE AFLIÇÃO;\nAS PALAVRAS QUE ELE FALA\nTRAZEM-ME CONSOLAÇÃO <bis>\n\nSE CONFESSO MEUS TEMORES,\nTODA A MINHA IMPERFEIÇÃO,\nELE ESCUTA COM PACIÊNCIA\nESSA TRISTE CONFISSÃO;\nCOM TERNURA REPREENDE\nMEU PECADO E TODO MAL,\nELE É SEMPRE O MEU AMIGO,\nO MELHOR E MAIS LEAL <bis>\n\nSE QUEREIS SABER QUÃO DOCE\nÉ A SECRETA COMUNHÃO,\nPODEREIS MUI BEM PROVÁ-LA\nE TEREIS COMPENSAÇÃO;\nPROCURAI ESTAR SOZINHOS\nEM CONVERSA COM JESUS,\nPROVAREIS NA VOSSA VIDA\nO ESPÍRITO DA CRUZ <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (71, 'VEM, AMADO MEU', 'VEM, AMADO MEU', 'VEM, AMADO MEU,\nVEM VISITAR A TUA IGREJA;\nVEM, DEPRESSA, VEM, \nMINH''ALMA ANSEIA POR TUA PRESENÇA.\n\nPERTENÇO A TI, ÉS MEU AMADO,\nJUNTO A TI QUERO ESTAR\nPARA SEMPRE, VEM ME BUSCAR.\n\nREPETIR O LOUVOR', 'VEM, AMADO MEU,\nVEM VISITAR A TUA IGREJA;\nVEM, DEPRESSA, VEM, \nMINH''ALMA ANSEIA POR TUA PRESENÇA.\n\nPERTENÇO A TI, ÉS MEU AMADO,\nJUNTO A TI QUERO ESTAR\nPARA SEMPRE, VEM ME BUSCAR.\n\n<repetir tipo=''O LOUVOR''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (72, 'É PRECISO CONFIAR E BUSCAR A DEUS', 'É PRECISO CONFIAR E BUSCAR A DEUS', 'É PRECISO CONFIAR E BUSCAR A DEUS,\nE O SENHOR DOS EXÉRCITOS TE OUVIRÁ.\n\nO SENHOR TE GUIARÁ, \nÉ PRECISO CONFIAR,\nE O SENHOR DOS EXÉRCITOS TE GUIARÁ.\n\nCORO\nBUSCA A DEUS \n(BUSCA A DEUS) \nQUE ELE TE OUVIRÁ.\n\nBUSCAI AO SENHOR ENQUANTO \nSE PODE ACHAR, INVOCAI-O \nENQUANTO ESTÁ PERTO.\n\nFINAL: \nÉ PRECISO CONFIAR,\nE O SENHOR \nDOS EXÉRCITOS TE GUIARÁ.', 'É PRECISO CONFIAR E BUSCAR A DEUS,\nE O SENHOR DOS EXÉRCITOS TE OUVIRÁ.\n\nO SENHOR TE GUIARÁ, \nÉ PRECISO CONFIAR,\nE O SENHOR DOS EXÉRCITOS TE GUIARÁ.\n\n<coro>\nBUSCA A DEUS <bis>\n(BUSCA A DEUS) <bis>\nQUE ELE TE OUVIRÁ.<bis>\n<bis>\nBUSCAI AO SENHOR ENQUANTO <bis>\nSE PODE ACHAR, INVOCAI-O <bis>\nENQUANTO ESTÁ PERTO.\n<final>É PRECISO CONFIAR,\nE O SENHOR \nDOS EXÉRCITOS TE GUIARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (73, 'DEUS ESTÁ NO TEMPLO', 'DEUS ESTÁ NO TEMPLO', 'DEUS ESTÁ NO TEMPLO,\nPAI ONIPOTENTE,\nDIANTE DELE NOS PROSTREMOS!\nREVERENTEMENTE,\nSERVOS CONSAGRADOS,\nAO ALTÍSSIMO ADOREMOS!\nCOM FAVOR, COM AMOR,\nESPIRITUALMENTE,\nDEUS ESTÁ NO TEMPLO!\n\nCRISTO ESTÁ NO TEMPLO,\nSUMO BENEFÍCIO\nRECEBEMOS DE SEU SANGUE.\nO CORDEIRO ETERNO\nFOI O SACRIFÍCIO,\nQUE NA CRUZ MORREU EXANGUE;\nESCOLHEU E SOFREU\nO MORTAL SUPLÍCIO;\nCRISTO ESTÁ NO TEMPLO!\n\nVEM, OCUPA O TEMPLO,\nINSTRUTOR DIVINO,\nNOSSOS CORAÇÕES HABITA.\nMESTRE INCOMPARÁVEL,\nDÁ-NOS TEU ENSINO,\nACLARANDO A LEI BENDITA;\nCOM PRAZER E PODER,\nOH! FAVOR SUPINO!\nELE ESTÁ NO TEMPLO!', 'DEUS ESTÁ NO TEMPLO,\nPAI ONIPOTENTE,\nDIANTE DELE NOS PROSTREMOS!\nREVERENTEMENTE,\nSERVOS CONSAGRADOS,\nAO ALTÍSSIMO ADOREMOS!\nCOM FAVOR, COM AMOR,\nESPIRITUALMENTE,\nDEUS ESTÁ NO TEMPLO!\n\nCRISTO ESTÁ NO TEMPLO,\nSUMO BENEFÍCIO\nRECEBEMOS DE SEU SANGUE.\nO CORDEIRO ETERNO\nFOI O SACRIFÍCIO,\nQUE NA CRUZ MORREU EXANGUE;\nESCOLHEU E SOFREU\nO MORTAL SUPLÍCIO;\nCRISTO ESTÁ NO TEMPLO!\n\nVEM, OCUPA O TEMPLO,\nINSTRUTOR DIVINO,\nNOSSOS CORAÇÕES HABITA.\nMESTRE INCOMPARÁVEL,\nDÁ-NOS TEU ENSINO,\nACLARANDO A LEI BENDITA;\nCOM PRAZER E PODER,\nOH! FAVOR SUPINO!\nELE ESTÁ NO TEMPLO!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (74, 'SEI, SENHOR', 'SEI, SENHOR', 'SEI, SENHOR, QUE CARINHOSAMENTE\nME TROUXESTE AQUI\nE O MEU CORAÇÃO QUERO \nTE OFERTAR.\n\nSENTIR TUA PRESENÇA,\nGOZAR DE COMUNHÃO;\nVEM, SENHOR, ME ABRAÇA,\nME CONFORTA, ÉS AMOR;\nSOU TEU, SOMENTE TEU,\nÓ VEM ME ABENÇOAR.', 'SEI, SENHOR, QUE CARINHOSAMENTE\nME TROUXESTE AQUI\nE O MEU CORAÇÃO QUERO \nTE OFERTAR.\n\nSENTIR TUA PRESENÇA,<bis>\nGOZAR DE COMUNHÃO;<bis>\nVEM, SENHOR, ME ABRAÇA,<bis>\nME CONFORTA, ÉS AMOR;<bis>\nSOU TEU, SOMENTE TEU,<bis>\nÓ VEM ME ABENÇOAR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (75, 'SENTE EM TUA FACE O ROÇAR', 'SENTE EM TUA FACE O ROÇAR', 'SENTE EM TUA FACE O ROÇAR\nDA ORLA DO VESTIDO DE JESUS,\nSENTE QUE O SENHOR ESTÁ AQUI\nE QUER OUVIR O TEU LOUVOR.\n\nCANTEMOS COM ALEGRIA\nE OREMOS COM DEVOÇÃO;\nVEM, SENHOR, MORAR \nEM MEU CORAÇÃO.', 'SENTE EM TUA FACE O ROÇAR\nDA ORLA DO VESTIDO DE JESUS,\nSENTE QUE O SENHOR ESTÁ AQUI\nE QUER OUVIR O TEU LOUVOR.\n\nCANTEMOS COM ALEGRIA\nE OREMOS COM DEVOÇÃO;\nVEM, SENHOR, MORAR <bis>\nEM MEU CORAÇÃO. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (76, 'NESTA NOITE FELIZ', 'NESTA NOITE FELIZ', 'NESTA NOITE FELIZ, NESTE SANTO LUGAR,\nEU MARQUEI UM ENCONTRO COM DEUS;\nSEU AMOR É REAL, SUA PAZ GOZAREI,\nEU MARQUEI UM ENCONTRO COM DEUS.\n\nEU MARQUEI UM ENCONTRO COM DEUS\nNESTE SANTO LUGAR DE ORAÇÃO;\nNESTE ENCONTRO DE AMOR \nPEDIREI AO SENHOR\nUMA BÊNÇÃO PARA O MEU CORAÇÃO.', 'NESTA NOITE FELIZ, NESTE SANTO LUGAR,\nEU MARQUEI UM ENCONTRO COM DEUS;\nSEU AMOR É REAL, SUA PAZ GOZAREI,\nEU MARQUEI UM ENCONTRO COM DEUS.\n\nEU MARQUEI UM ENCONTRO COM DEUS\nNESTE SANTO LUGAR DE ORAÇÃO;\nNESTE ENCONTRO DE AMOR \nPEDIREI AO SENHOR\nUMA BÊNÇÃO PARA O MEU CORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (77, 'VEM, VISITA TUA IGREJA', 'VEM, VISITA TUA IGREJA', 'VEM, VISITA TUA IGREJA,\nÓ BENDITO SALVADOR! \nSEM TUA GRAÇA, \nELA MURCHA FICARÁ E SEM VIGOR.\n\nVIVIFICA, VIVIFICA \nNOSSAS ALMAS, Ó SENHOR!', 'VEM, VISITA TUA IGREJA,\nÓ BENDITO SALVADOR!\nSEM TUA GRAÇA, \nELA MURCHA FICARÁ E SEM VIGOR.\n\nVIVIFICA, VIVIFICA <bis>\nNOSSAS ALMAS, Ó SENHOR! <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (78, 'UMA VOZ MANSA E DELICADA', 'UMA VOZ MANSA E DELICADA', 'UMA VOZ MANSA E DELICADA\nFALA AO MEU CORAÇÃO,\nVOZ TÃO SUAVE, MARAVILHOSA,\nTRAZ PAZ E CONSOLAÇÃO.\nOH! QUE VOZ MANSA E DELICADA,\nQUE FALA AO MEU CORAÇÃO.\n\nESTA VOZ DOCE QUE EU ESCUTO,\nÉ A VOZ DO MEU SENHOR,\nELE ESTÁ VIVO, FALA COMIGO,\nELE É O MEU CONSOLADOR.\nOH! QUE VOZ MANSA E DELICADA, \nQUE FALA AO MEU CORAÇÃO.', 'UMA VOZ MANSA E DELICADA\nFALA AO MEU CORAÇÃO,\nVOZ TÃO SUAVE, MARAVILHOSA,\nTRAZ PAZ E CONSOLAÇÃO.\nOH! QUE VOZ MANSA E DELICADA,\nQUE FALA AO MEU CORAÇÃO.\n\nESTA VOZ DOCE QUE EU ESCUTO,\nÉ A VOZ DO MEU SENHOR,\nELE ESTÁ VIVO, FALA COMIGO,\nELE É O MEU CONSOLADOR.\nOH! QUE VOZ MANSA E DELICADA, <bis>\nQUE FALA AO MEU CORAÇÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (79, 'DEUS ESTÁ PRESENTE ENTRE PECADORES COMO NÓS', 'DEUS ESTÁ PRESENTE ENTRE PECADORES COMO NÓS', 'DEUS ESTÁ PRESENTE (BIS) \nENTRE PECADORES COMO NÓS.\nDEUS ESTÁ PRESENTE, (BIS) \nDEUS ESTÁ PRESENTE, \nPRONTO A PERDOAR. \n\nDEUS IRÁ OUVIR NOSSA ORAÇÃO,\nNOSSO FARDO VAI SOBRE SI LEVAR;\nPOIS DEUS ESTÁ PRESENTE, \nPRONTO PRA SALVAR,\nPRONTO PRA AJUDAR,\nDEUS ESTÁ PRESENTE.', 'DEUS ESTÁ PRESENTE <bis>\nENTRE PECADORES COMO NÓS.<bis>\nDEUS ESTÁ PRESENTE, <bis>\nDEUS ESTÁ PRESENTE, <bis>\nPRONTO A PERDOAR. <bis>\n\nDEUS IRÁ OUVIR NOSSA ORAÇÃO,\nNOSSO FARDO VAI SOBRE SI LEVAR;\nPOIS DEUS ESTÁ PRESENTE,\nPRONTO PRA SALVAR,\nPRONTO PRA AJUDAR,\nDEUS ESTÁ PRESENTE.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (80, 'VIVES MUITO ALÉM DO CÉU', 'VIVES MUITO ALÉM DO CÉU', 'VIVES MUITO ALÉM DO CÉU,\nMUITO ALÉM DO QUE MEUS OLHOS\nPODEM ALCANÇAR,\nMAS POSSO PELA FÉ TOCAR TUAS \nVESTES E RECEBER DE TI GRAÇA E PAZ;\nPOSSO SEMPRE QUE ORO A TI, JESUS\nPOSSO SEMPRE QUE ORO A TI, JESUS\n\nTU DEIXASTE TEU ESPÍRITO CONSOLADOR,\nTÃO AMIGO, TÃO FIEL, AJUDADOR,\nTÉ QUE VENHAS COM PODER PRA NOS BUSCAR\nPRA ENTÃO ETERNAMENTE CONTIGO ESTAR;\nJUNTO, SEMPRE, ESTAREI DE TI, JESUS, \nESTAREI DE TI, JESUS.', 'VIVES MUITO ALÉM DO CÉU,\nMUITO ALÉM DO QUE MEUS OLHOS\nPODEM ALCANÇAR,\nMAS POSSO PELA FÉ TOCAR TUAS \nVESTES E RECEBER DE TI GRAÇA E PAZ;\nPOSSO SEMPRE QUE ORO A TI, JESUS\nPOSSO SEMPRE QUE ORO A TI, JESUS\n\nTU DEIXASTE TEU ESPÍRITO CONSOLADOR,\nTÃO AMIGO, TÃO FIEL, AJUDADOR,\nTÉ QUE VENHAS COM PODER PRA NOS BUSCAR\nPRA ENTÃO ETERNAMENTE CONTIGO ESTAR;\nJUNTO, SEMPRE, ESTAREI DE TI, JESUS, <bis>\nESTAREI DE TI, JESUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (81, 'GRANDE DEUS, ÚNICO DEUS', 'GRANDE DEUS, ÚNICO DEUS', 'GRANDE DEUS, ÚNICO DEUS,\nCRIADOR DE TUDO QUANTO HÁ\nDE MAIS PROFUNDO, DE MAIS VALOR,\nO SENHOR, O MEU GRANDE DEUS.\n\nPAI, TU QUE ME OUVES\nMESMO QUANDO A VOZ NÃO SAI,\nMEU GRANDE PAI, TU ÉS AMIGO, \nPREFERIDO, MAIS QUE IRMÃO, \nMEU GRANDE PAI, \nTU ÉS AMIGO, MEU PREFERIDO, \nDÁ-ME A TUA PAZ.', 'GRANDE DEUS, ÚNICO DEUS,\nCRIADOR DE TUDO QUANTO HÁ\nDE MAIS PROFUNDO, DE MAIS VALOR,\nO SENHOR, O MEU GRANDE DEUS.\n\nPAI, TU QUE ME OUVES<bis>\nMESMO QUANDO A VOZ NÃO SAI,<bis>\nMEU GRANDE PAI, TU ÉS AMIGO, <bis>\nPREFERIDO, MAIS QUE IRMÃO, <bis>\nMEU GRANDE PAI, <bis>\nTU ÉS AMIGO, MEU PREFERIDO, <bis>\nDÁ-ME A TUA PAZ.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (82, 'CADA INSTANTE', 'CADA INSTANTE', 'CADA INSTANTE CONTIGO, SENHOR,\nQUE PASSO A TEUS PÉS,\nEU SOU MAIS FELIZ.\nCADA INSTANTE CONTIGO, JESUS,\nÉ PAZ EM MINH''ALMA,\nSUAVE HARMONIA,\nNO TEU GRANDE AMOR.', 'CADA INSTANTE CONTIGO, SENHOR,\nQUE PASSO A TEUS PÉS,\nEU SOU MAIS FELIZ.\nCADA INSTANTE CONTIGO, JESUS,\nÉ PAZ EM MINH''ALMA,<bis>\nSUAVE HARMONIA,<bis>\nNO TEU GRANDE AMOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (83, 'MAIS UMA VEZ', 'MAIS UMA VEZ', 'MAIS UMA VEZ, ESTAMOS AQUI, SENHOR\nMAIS UMA VEZ PEDINDO COMUNHÃO\nPARA TE LOUVAR, TE GLORIFICAR,\nPARA TE EXALTARMOS, SENHOR JESUS. \n\nMAIS UMA VEZ, ESTAMOS AQUI, SENHOR\nMAIS UMA VEZ PEDINDO COMUNHÃO\nPARA TE LOUVAR, TE GLORIFICAR,\nPARA TE EXALTARMOS, SENHOR JESUS. \n\nFINAL: \nPARA TE EXALTARMOS, \nSENHOR JESUS.', 'MAIS UMA VEZ, ESTAMOS AQUI, SENHOR\nMAIS UMA VEZ PEDINDO COMUNHÃO\nPARA TE LOUVAR, TE GLORIFICAR,\nPARA TE EXALTARMOS, SENHOR JESUS. \n\nMAIS UMA VEZ, ESTAMOS AQUI, SENHOR\nMAIS UMA VEZ PEDINDO COMUNHÃO\nPARA TE LOUVAR, TE GLORIFICAR,\nPARA TE EXALTARMOS, SENHOR JESUS. \n<final>PARA TE EXALTARMOS, \nSENHOR JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (84, 'ATENDE, SENHOR, A MINHA ORAÇÃO', 'ATENDE, SENHOR, A MINHA ORAÇÃO', 'ATENDE, SENHOR, A MINHA ORAÇÃO,\nA TI, LEVANTO MINHAS MÃOS;\nA MINHA ALMA ANSEIA POR TI,\nDÁ-TE PRESSA EM ME SOCORRER.\n\nFAZE-ME OUVIR NA MANHÃ, \nDA TUA GRAÇA,\nENSINA-ME A FAZER A TUA VONTADE\nPOIS EU SOU TEU E TU ÉS MEU, \nEM TI CONFIO, SENHOR. \n\nFINAL: \nPOIS EU SOU TEU E TU ÉS MEU,\nEM TI CONFIO, SENHOR (3X)', 'ATENDE, SENHOR, A MINHA ORAÇÃO,\nA TI, LEVANTO MINHAS MÃOS;\nA MINHA ALMA ANSEIA POR TI,\nDÁ-TE PRESSA EM ME SOCORRER.\n\nFAZE-ME OUVIR NA MANHÃ, <bis>\nDA TUA GRAÇA,<bis>\nENSINA-ME A FAZER A TUA VONTADE<bis>\nPOIS EU SOU TEU E TU ÉS MEU, <bis>\nEM TI CONFIO, SENHOR. \n<final>POIS EU SOU TEU E TU ÉS MEU,\nEM TI CONFIO, SENHOR <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (85, 'ENVIA A TUA LUZ', 'ENVIA A TUA LUZ', 'ENVIA A TUA LUZ, Ó DEUS,\nENVIA A TUA VERDADE, MEU SENHOR,\nPRA QUE ME GUIEM AO TEU SANTO MONTE,\nAOS TEUS TABERNÁCULOS, \nMEU SENHOR, MEU CRIADOR, \nMEU REI, Ó MEU SENHOR.\n\nENTÃO IREI AO ALTAR DE DEUS,\nDO DEUS QUE É MINHA GRANDE ALEGRIA. \n\nE COM HARPA LOUVAREI A DEUS,\nDEUS, MEU SENHOR.', 'ENVIA A TUA LUZ, Ó DEUS,\nENVIA A TUA VERDADE, MEU SENHOR,\nPRA QUE ME GUIEM AO TEU SANTO MONTE,\nAOS TEUS TABERNÁCULOS, \nMEU SENHOR, MEU CRIADOR, \nMEU REI, Ó MEU SENHOR.\n\nENTÃO IREI AO ALTAR DE DEUS,<bis>\nDO DEUS QUE É MINHA GRANDE ALEGRIA. <bis>\n\nE COM HARPA LOUVAREI A DEUS,\nDEUS, MEU SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (86, 'EM TEU NOME', 'EM TEU NOME', 'EM TEU NOME ESTAMOS REUNIDOS AQUI, \nNOSSA ALMA ANSEIA E TEM SEDE DE TI!\nQUEREMOS VER TUA GLÓRIA ENCHENDO ESTE LUGAR, \nTU ESTÁS PRESENTE, PRONTO A ABENÇOAR.\n\nCORO\nESTÁS AQUI, BOM SALVADOR,\nMEIGO E GENTIL, ABENÇOADOR;\nESTÁS AQUI COM TEU PODER\nPARA DAR LIBERDADE E MUDAR \nO NOSSO SER.\n\nINSTRUMENTOS\n\nTEU PERFUME É SUAVE COMO A ROSA E O JASMIM,\nTUA PRESENÇA ME ENCHE DE ALEGRIA SEM FIM,\nFONTE INESGOTÁVEL QUE DO CÉU VIDA TRAZ,\nFONTE DE ÁGUA VIVA QUE ME CURA E DÁ PAZ.\n\nCORO (2 X)\nESTÁS AQUI, BOM SALVADOR,\nMEIGO E GENTIL, ABENÇOADOR;\nESTÁS AQUI COM TEU PODER\nPARA DAR LIBERDADE E MUDAR \nO NOSSO SER.', 'EM TEU NOME ESTAMOS REUNIDOS AQUI, \nNOSSA ALMA ANSEIA E TEM SEDE DE TI!\nQUEREMOS VER TUA GLÓRIA ENCHENDO ESTE LUGAR, \nTU ESTÁS PRESENTE, PRONTO A ABENÇOAR.\n\n<coro>\nESTÁS AQUI, BOM SALVADOR,\nMEIGO E GENTIL, ABENÇOADOR;\nESTÁS AQUI COM TEU PODER\nPARA DAR LIBERDADE E MUDAR \nO NOSSO SER.\n<instrumentos>\n\n\nTEU PERFUME É SUAVE COMO A ROSA E O JASMIM,\nTUA PRESENÇA ME ENCHE DE ALEGRIA SEM FIM,\nFONTE INESGOTÁVEL QUE DO CÉU VIDA TRAZ,\nFONTE DE ÁGUA VIVA QUE ME CURA E DÁ PAZ.\n\n<coro tipo=''2 X''>\nESTÁS AQUI, BOM SALVADOR,\nMEIGO E GENTIL, ABENÇOADOR;\nESTÁS AQUI COM TEU PODER\nPARA DAR LIBERDADE E MUDAR \nO NOSSO SER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (87, 'MEU PECADO RESGATADO', 'MEU PECADO RESGATADO', 'MEU PECADO RESGATADO\nFOI NA CRUZ, POR TEU AMOR,\nE DA MORTE, TRISTE SORTE,\nME LIVRASTE TU, SENHOR!\n\nCORO\nVEM! INFLAMA VIVA CHAMA\nEM MEU PEITO, BEM SEM FIM!\nEU TE ADORO, SEMPRE IMPLORO:\nÓ JESUS, HABITA EM MIM!\n\nSE HESITANTE, VACILANTE,\nOUÇO A VOZ DO TENTADOR,\nTU ME GUIAS, ME AUXILIAS\nE ME TORNAS VENCEDOR.\n\nCORO\nVEM! INFLAMA VIVA CHAMA\nEM MEU PEITO, BEM SEM FIM!\nEU TE ADORO, SEMPRE IMPLORO:\nÓ JESUS, HABITA EM MIM!\n\nREDIMIDA, SÓ TEM VIDA\nA MINHA ALMA EM TEU AMOR;\nCOM APREÇO, RECONHEÇO\nQUANTO DEVO A TI, SENHOR!\n\nCORO\nVEM! INFLAMA VIVA CHAMA\nEM MEU PEITO, BEM SEM FIM!\nEU TE ADORO, SEMPRE IMPLORO:\nÓ JESUS, HABITA EM MIM!', 'MEU PECADO RESGATADO\nFOI NA CRUZ, POR TEU AMOR,\nE DA MORTE, TRISTE SORTE,\nME LIVRASTE TU, SENHOR!\n\n<coro>\nVEM! INFLAMA VIVA CHAMA\nEM MEU PEITO, BEM SEM FIM!\nEU TE ADORO, SEMPRE IMPLORO:\nÓ JESUS, HABITA EM MIM!\n\nSE HESITANTE, VACILANTE,\nOUÇO A VOZ DO TENTADOR,\nTU ME GUIAS, ME AUXILIAS\nE ME TORNAS VENCEDOR.\n\n<coro>\nVEM! INFLAMA VIVA CHAMA\nEM MEU PEITO, BEM SEM FIM!\nEU TE ADORO, SEMPRE IMPLORO:\nÓ JESUS, HABITA EM MIM!\n\nREDIMIDA, SÓ TEM VIDA\nA MINHA ALMA EM TEU AMOR;\nCOM APREÇO, RECONHEÇO\nQUANTO DEVO A TI, SENHOR!\n\n<coro>\nVEM! INFLAMA VIVA CHAMA\nEM MEU PEITO, BEM SEM FIM!\nEU TE ADORO, SEMPRE IMPLORO:\nÓ JESUS, HABITA EM MIM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (88, 'DAS PROFUNDEZAS', 'DAS PROFUNDEZAS', 'DAS PROFUNDEZAS \nCLAMO A TI, Ó SENHOR,\nÉS A MINHA FORÇA,\nÉS MINHA ROCHA E ALTO RETIRO MEU,\nEM TI EU CONFIAREI.', 'DAS PROFUNDEZAS <bis>\nCLAMO A TI, Ó SENHOR,<bis>\nÉS A MINHA FORÇA,<bis>\nÉS MINHA ROCHA E ALTO RETIRO MEU,<bis>\nEM TI EU CONFIAREI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (89, 'DAS PROFUNDEZAS CLAMO A TI, Ó SENHOR!', 'DAS PROFUNDEZAS CLAMO A TI, Ó SENHOR!', 'DAS PROFUNDEZAS CLAMO A TI, Ó SENHOR!\nESCUTA A MINHA VOZ, ESCUTA A MINHA SÚPLICA;\nESPERO EM TI, SENHOR, O TEU PERDÃO,\nESPERO EM TI, SENHOR, O TEU PERDÃO.\n\nAGUARDO EM TI, SENHOR, ESPERO NA TUA PALAVRA, A MINH''ALMA ANSEIA POR TI MAIS QUE OS GUARDAS \nPELO ROMPER DA MANHÃ. ESPERA, ISRAEL, (NO SENHOR) \nPORQUE NELE HÁ (MISERICÓRDIA)\nE REDENÇÃO.\n\nINSTRUMENTOS\n\nELE TE REMIRÁ DE TODA TRANSGRESSÃO\nPOIS O SENHOR QUE ESTÁ NOS CÉUS TE OUVIRÁ;\n''ESPERA, POVO MEU, POIS VENHO JÁ,\nESPERA, ISRAEL, NO TEU SENHOR E REI''.\n\nAGUARDO EM TI, SENHOR, ESPERO NA TUA PALAVRA, A MINH''ALMA ANSEIA POR TI MAIS QUE OS GUARDAS \nPELO ROMPER DA MANHÃ. ESPERA, ISRAEL, (NO SENHOR) \nPORQUE NELE HÁ (MISERICÓRDIA) \n\nAGUARDO EM TI, SENHOR, ESPERO NA TUA PALAVRA, \nA MINH''ALMA ANSEIA POR TI, MAIS QUE OS GUARDAS \nPELO ROMPER DA MANHÃ. ESPERA, ISRAEL, \n(ESPERA EM DEUS) \nESPERA, ISRAEL, (NO SENHOR) \nPORQUE NELE HÁ (MISERICÓRDIA) \nE REDENÇÃO.', 'DAS PROFUNDEZAS CLAMO A TI, Ó SENHOR!\nESCUTA A MINHA VOZ, ESCUTA A MINHA SÚPLICA;\nESPERO EM TI, SENHOR, O TEU PERDÃO,\nESPERO EM TI, SENHOR, O TEU PERDÃO.\n\nAGUARDO EM TI, SENHOR, ESPERO NA TUA PALAVRA, A MINH''ALMA ANSEIA POR TI MAIS QUE OS GUARDAS \nPELO ROMPER DA MANHÃ. ESPERA, ISRAEL, (NO SENHOR) \nPORQUE NELE HÁ (MISERICÓRDIA)\nE REDENÇÃO.\n<instrumentos>\n\n\nELE TE REMIRÁ DE TODA TRANSGRESSÃO\nPOIS O SENHOR QUE ESTÁ NOS CÉUS TE OUVIRÁ;\n''ESPERA, POVO MEU, POIS VENHO JÁ,\nESPERA, ISRAEL, NO TEU SENHOR E REI''.\n\nAGUARDO EM TI, SENHOR, ESPERO NA TUA PALAVRA, A MINH''ALMA ANSEIA POR TI MAIS QUE OS GUARDAS \nPELO ROMPER DA MANHÃ. ESPERA, ISRAEL, (NO SENHOR) \nPORQUE NELE HÁ (MISERICÓRDIA) \n\nAGUARDO EM TI, SENHOR, ESPERO NA TUA PALAVRA, \nA MINH''ALMA ANSEIA POR TI, MAIS QUE OS GUARDAS \nPELO ROMPER DA MANHÃ. ESPERA, ISRAEL, \n(ESPERA EM DEUS) \nESPERA, ISRAEL, (NO SENHOR) \nPORQUE NELE HÁ (MISERICÓRDIA) \nE REDENÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (90, 'EM TUAS MÃOS, SENHOR', 'EM TUAS MÃOS, SENHOR', 'EM TUAS MÃOS, SENHOR, EU ME COLOCO AGORA;\nFALA COMIGO, NESTA HORA EM QUE MEU CORAÇÃO \nSUPLICA O TEU AMOR.\nEU PEÇO SALVAÇÃO, PEÇO TEU PERDÃO, AGORA, \nVEM ME DIZER QUE A DOR FINDOU \nE QUE A FELICIDADE NÃO DEMORA.\nFALA COMIGO, AGORA (4X)', 'EM TUAS MÃOS, SENHOR, EU ME COLOCO AGORA;\nFALA COMIGO, NESTA HORA EM QUE MEU CORAÇÃO \nSUPLICA O TEU AMOR.\nEU PEÇO SALVAÇÃO, PEÇO TEU PERDÃO, AGORA, \nVEM ME DIZER QUE A DOR FINDOU \nE QUE A FELICIDADE NÃO DEMORA.\nFALA COMIGO, AGORA <bis tipo=''4''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (91, 'JESUS, A MINH''ALMA TEM SEDE DE TI', 'JESUS, A MINH''ALMA TEM SEDE DE TI', 'JESUS, A MINH''ALMA TEM SEDE DE TI,\nOUVE-ME QUANDO A TI CLAMO,\nLIVRA-ME DOS MEUS ADVERSÁRIOS,\nPOIS ELES ESTÃO QUERENDO ROUBAR\nA MINHA SALVAÇÃO.\n\nCOBRE-ME COM O TEU SANGUE,\nDÁ-ME ESTA PROTEÇÃO,\nJESUS, EU QUERO ESTAR \nEM PERFEITA COMUNHÃO,\nJESUS, EU QUERO ESTAR \nEM CONSTANTE COMUNHÃO.', 'JESUS, A MINH''ALMA TEM SEDE DE TI,\nOUVE-ME QUANDO A TI CLAMO,\nLIVRA-ME DOS MEUS ADVERSÁRIOS,\nPOIS ELES ESTÃO QUERENDO ROUBAR\nA MINHA SALVAÇÃO.\n\nCOBRE-ME COM O TEU SANGUE,\nDÁ-ME ESTA PROTEÇÃO,\nJESUS, EU QUERO ESTAR \nEM PERFEITA COMUNHÃO,\nJESUS, EU QUERO ESTAR \nEM CONSTANTE COMUNHÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (92, 'PAI CELESTE', 'PAI CELESTE', 'PAI CELESTE, PAI CELESTE,\nVEM FICAR COMIGO,\nPAI CELESTE.\n\nJESUS CRISTO, JESUS CRISTO,\nVEM FICAR COMIGO,\nJESUS CRISTO.\n\nSANTO ESPÍRITO, SANTO ESPÍRITO,\nVEM FICAR COMIGO,\nSANTO ESPÍRITO.', 'PAI CELESTE, PAI CELESTE,\nVEM FICAR COMIGO,\nPAI CELESTE.\n\nJESUS CRISTO, JESUS CRISTO,\nVEM FICAR COMIGO,\nJESUS CRISTO.\n\nSANTO ESPÍRITO, SANTO ESPÍRITO,\nVEM FICAR COMIGO,\nSANTO ESPÍRITO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (93, 'LOGO DE MANHÃ', 'LOGO DE MANHÃ', 'LOGO DE MANHÃ, QUERO TE BUSCAR,\nTUA VOZ OUVIR, TEU AMOR SENTIR.\nE ESTENDER AS MÃOS PARA TE LOUVAR,\nDERRAMAR MEU CORAÇÃO SOBRE TEU ALTAR.\n\nPOIS TU SABES BEM TUDO QUANDO HÁ EM MIM:\nQUE VOU TE SEGUIR E TE AMAR ATÉ O FIM.\n\nE, NO FIM DO DIA, QUANDO O SOL SE FOR,\nTE ADORAREI, TE DAREI LOUVOR.\nMESMA ESCURA A NOITE, BRILHA A TUA LUZ.\nE EM TEUS BRAÇOS EU DESCANSO,\nMEU SENHOR JESUS.', 'LOGO DE MANHÃ, QUERO TE BUSCAR,\nTUA VOZ OUVIR, TEU AMOR SENTIR.\nE ESTENDER AS MÃOS PARA TE LOUVAR,\nDERRAMAR MEU CORAÇÃO SOBRE TEU ALTAR.\n\nPOIS TU SABES BEM TUDO QUANDO HÁ EM MIM:\nQUE VOU TE SEGUIR E TE AMAR ATÉ O FIM.\n\nE, NO FIM DO DIA, QUANDO O SOL SE FOR,\nTE ADORAREI, TE DAREI LOUVOR.\nMESMA ESCURA A NOITE, BRILHA A TUA LUZ.\nE EM TEUS BRAÇOS EU DESCANSO,\nMEU SENHOR JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (94, 'BENDITA A HORA DE ORAÇÃO', 'BENDITA A HORA DE ORAÇÃO', 'BENDITA A HORA DE ORAÇÃO\nQUE ACALMA O AFLITO CORAÇÃO.\nQUE LEVA AO TRONO DE JESUS\nOS ROGOS PARA AUXÍLIO E LUZ!\nEM TEMPOS DE CUIDADO E DOR,\nREFÚGIO TENHO EM MEU SENHOR.\nVENCENDO O ARDIL E A TENTAÇÃO,\nBENDIGO A HORA DE ORAÇÃO.\n\nBENDITA A HORA DE ORAÇÃO,\nQUANDO A FERVENTE PETIÇÃO\nSOBE AO BENIGNO SALVADOR,\nQUE ATENDE A VOZ DO MEU CLAMOR!\nJESUS ME ORDENA A RECORRER\nAO SEU AMOR, AO SEU PODER.\nCONTENTE E SEM PERTURBAÇÃO\nEU BUSCO A HORA DE ORAÇÃO.\n\nBENDITA A HORA DE ORAÇÃO,\nDE SANTA PAZ E COMUNHÃO!\nDESEJO ENQUANTO AQUI ME ACHAR,\nCOM FÉ CONSTANTE HUMILDE ORAR.\nE ENFIM, NO RESPLENDOR DE DEUS,\nNA GLÓRIA DOS MAIS ALTOS CÉUS,\nLEMBRAR-ME-EI COM GRATIDÃO\nDAS HORAS SUAVES DE ORAÇÃO.\n\nFINAL: AMÉM', 'BENDITA A HORA DE ORAÇÃO\nQUE ACALMA O AFLITO CORAÇÃO.\nQUE LEVA AO TRONO DE JESUS\nOS ROGOS PARA AUXÍLIO E LUZ!\nEM TEMPOS DE CUIDADO E DOR,\nREFÚGIO TENHO EM MEU SENHOR.\nVENCENDO O ARDIL E A TENTAÇÃO,\nBENDIGO A HORA DE ORAÇÃO.\n\nBENDITA A HORA DE ORAÇÃO,\nQUANDO A FERVENTE PETIÇÃO\nSOBE AO BENIGNO SALVADOR,\nQUE ATENDE A VOZ DO MEU CLAMOR!\nJESUS ME ORDENA A RECORRER\nAO SEU AMOR, AO SEU PODER.\nCONTENTE E SEM PERTURBAÇÃO\nEU BUSCO A HORA DE ORAÇÃO.\n\nBENDITA A HORA DE ORAÇÃO,\nDE SANTA PAZ E COMUNHÃO!\nDESEJO ENQUANTO AQUI ME ACHAR,\nCOM FÉ CONSTANTE HUMILDE ORAR.\nE ENFIM, NO RESPLENDOR DE DEUS,\nNA GLÓRIA DOS MAIS ALTOS CÉUS,\nLEMBRAR-ME-EI COM GRATIDÃO\nDAS HORAS SUAVES DE ORAÇÃO.\n<final>AMÉM', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (95, 'BUSCAR-ME-EIS', 'BUSCAR-ME-EIS', 'BUSCAR-ME-EIS, E ME ACHAREIS, \nQUANDO ME BUSCARDES, \nQUANDO ME BUSCARDES, \nDE TODO O CORAÇÃO. \n\nCORO\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\n\nINSTRUMENTOS\n\nBUSCAR-ME-EIS, E ME ACHAREIS, \nQUANDO ME BUSCARDES, \nQUANDO ME BUSCARDES, \nDE TODO O CORAÇÃO. \n\nCORO\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\n\nFINAL: ASSIM DIZ O SENHOR.', 'BUSCAR-ME-EIS, E ME ACHAREIS, <bis>\nQUANDO ME BUSCARDES, <bis>\nQUANDO ME BUSCARDES, <bis>\nDE TODO O CORAÇÃO. <bis>\n\n<coro>\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\n<instrumentos>\n\n\nBUSCAR-ME-EIS, E ME ACHAREIS, \nQUANDO ME BUSCARDES, \nQUANDO ME BUSCARDES, \nDE TODO O CORAÇÃO. \n\n<coro>\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\nINVOCAR-ME-EIS, E ORAREIS A MIM,\nE EU VOS OUVIREI.\n<final>ASSIM DIZ O SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (96, 'COM A MINHA VOZ CLAMO AO SENHOR', 'COM A MINHA VOZ CLAMO AO SENHOR', 'CORO\nCOM A MINHA VOZ CLAMO AO SENHOR,\nCOM A MINHA VOZ AO SENHOR SUPLICO.\nDIANTE DELE A PROSTRAR-ME EU ESTOU,\nDIANTE DELE EXPONHO A MINHA AFLIÇÃO.\n\nQUANDO AQUI DENTRO DE MIM\nESMORECE O MEU ESPÍRITO,\nTU ENTÃO CONHECES MINHA VEREDA.\nOLHO À MÃO DIREITA E VEJO\nNÃO HÁ QUEM ME CONHEÇA,\nNÃO HÁ LUGAR ONDE ME REFUGIAR.\n\nCORO\nCOM A MINHA VOZ CLAMO AO SENHOR,\nCOM A MINHA VOZ AO SENHOR SUPLICO.\nDIANTE DELE A PROSTRAR-ME EU ESTOU,\nDIANTE DELE EXPONHO A MINHA AFLIÇÃO.\n\nÓ SENHOR A TI CLAMEI\nPOIS TU ÉS O MEU REFÚGIO,\nE O MEU TESOURO ENTRE OS VIVENTES.\nVEM, ATENDE AO MEU CLAMOR,\nESTOU MUITO ABATIDO.\nLIVRAR-ME VEM DO FORTE TENTADOR.\n\nCORO\nCOM A MINHA VOZ CLAMO AO SENHOR,\nCOM A MINHA VOZ AO SENHOR SUPLICO.\nDIANTE DELE A PROSTRAR-ME EU ESTOU,\nDIANTE DELE EXPONHO A MINHA AFLIÇÃO.\n\nFINAL:\nTIRA-ME DESTA PRISÃO\nE ASSIM LOUVAREI TEU NOME,\nE ENTÃO OS JUSTOS ME CERCARÃO.\nMEU SENHOR EU CLAMO A TI:\nÓ, VEM LIVRAR MINH''ALMA,\nE CANTAREI QUE ME FIZESTE BEM.', '<coro>\nCOM A MINHA VOZ CLAMO AO SENHOR,\nCOM A MINHA VOZ AO SENHOR SUPLICO.\nDIANTE DELE A PROSTRAR-ME EU ESTOU,\nDIANTE DELE EXPONHO A MINHA AFLIÇÃO.\n\nQUANDO AQUI DENTRO DE MIM\nESMORECE O MEU ESPÍRITO,\nTU ENTÃO CONHECES MINHA VEREDA.\nOLHO À MÃO DIREITA E VEJO\nNÃO HÁ QUEM ME CONHEÇA,\nNÃO HÁ LUGAR ONDE ME REFUGIAR.\n\n<coro>\nCOM A MINHA VOZ CLAMO AO SENHOR,\nCOM A MINHA VOZ AO SENHOR SUPLICO.\nDIANTE DELE A PROSTRAR-ME EU ESTOU,\nDIANTE DELE EXPONHO A MINHA AFLIÇÃO.\n\nÓ SENHOR A TI CLAMEI\nPOIS TU ÉS O MEU REFÚGIO,\nE O MEU TESOURO ENTRE OS VIVENTES.\nVEM, ATENDE AO MEU CLAMOR,\nESTOU MUITO ABATIDO.\nLIVRAR-ME VEM DO FORTE TENTADOR.\n\n<coro>\nCOM A MINHA VOZ CLAMO AO SENHOR,\nCOM A MINHA VOZ AO SENHOR SUPLICO.\nDIANTE DELE A PROSTRAR-ME EU ESTOU,\nDIANTE DELE EXPONHO A MINHA AFLIÇÃO.\n\n\n<final>TIRA-ME DESTA PRISÃO\nE ASSIM LOUVAREI TEU NOME,\nE ENTÃO OS JUSTOS ME CERCARÃO.\nMEU SENHOR EU CLAMO A TI:\nÓ, VEM LIVRAR MINH''ALMA,\nE CANTAREI QUE ME FIZESTE BEM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (97, 'BUSCOU-ME COM TERNURA', 'BUSCOU-ME COM TERNURA', 'BUSCOU-ME COM TERNURA\nJESUS, O BOM PASTOR;\nACHOU-ME NA MISÉRIA,\nSALVOU-ME COM AMOR;\nNO CÉU CANTARAM DE ALEGRIA\nOS ANJOS, SIM, EM HARMONIA.\n\nCORO\nOH! QUE AMOR GLORIOSO!\nPREÇO TÃO GRANDIOSO,\nQUE JESUS POR MIM NA CRUZ PAGOU;\nINAUDITA GRAÇA ME MOSTROU! \n\nFERIDO, ABANDONADO, \nJESUS ME SOCORREU; \nE SEGREDOU-ME: ''ACHEI-TE;\nDE AGORA EM DIANTE ÉS MEU''.\nTÃO MEIGA VOZ JAMAIS OUVI, \nPRAZER MAIOR JAMAIS SENTI.\n\nCORO\nOH! QUE AMOR GLORIOSO!\nPREÇO TÃO GRANDIOSO,\nQUE JESUS POR MIM NA CRUZ PAGOU;\nINAUDITA GRAÇA ME MOSTROU! \n\nJESUS MOSTROU-ME AS CHAGAS \nQUE EM MEU LUGAR SOFREU, COROA, \nMAS DE ESPINHOS, A CRUZ QUE PADECEU.\nQUE PODERIA EM MIM ACHAR,\nPRA TAIS AFRONTAS SUPORTAR?\n\nCORO\nOH! QUE AMOR GLORIOSO!\nPREÇO TÃO GRANDIOSO,\nQUE JESUS POR MIM NA CRUZ PAGOU;\nINAUDITA GRAÇA ME MOSTROU! \n\nENQUANTO AS HORAS PASSAM, \nEU TENHO GOZO E PAZ, E AGUARDO \nMEU BOM MESTRE, QUE TÃO FELIZ ME FAZ!\nJESUS A MIM VIRÁ BUSCAR,\nE ENTÃO PRA SEMPRE IREI GOZAR!', 'BUSCOU-ME COM TERNURA\nJESUS, O BOM PASTOR;\nACHOU-ME NA MISÉRIA,\nSALVOU-ME COM AMOR;\nNO CÉU CANTARAM DE ALEGRIA\nOS ANJOS, SIM, EM HARMONIA.\n\n<coro>\nOH! QUE AMOR GLORIOSO!\nPREÇO TÃO GRANDIOSO,\nQUE JESUS POR MIM NA CRUZ PAGOU;\nINAUDITA GRAÇA ME MOSTROU! \n\nFERIDO, ABANDONADO, \nJESUS ME SOCORREU; \nE SEGREDOU-ME: ''ACHEI-TE;\nDE AGORA EM DIANTE ÉS MEU''.\nTÃO MEIGA VOZ JAMAIS OUVI, \nPRAZER MAIOR JAMAIS SENTI.\n\n<coro>\nOH! QUE AMOR GLORIOSO!\nPREÇO TÃO GRANDIOSO,\nQUE JESUS POR MIM NA CRUZ PAGOU;\nINAUDITA GRAÇA ME MOSTROU! \n\nJESUS MOSTROU-ME AS CHAGAS \nQUE EM MEU LUGAR SOFREU, COROA, \nMAS DE ESPINHOS, A CRUZ QUE PADECEU.\nQUE PODERIA EM MIM ACHAR,\nPRA TAIS AFRONTAS SUPORTAR?\n\n<coro>\nOH! QUE AMOR GLORIOSO!\nPREÇO TÃO GRANDIOSO,\nQUE JESUS POR MIM NA CRUZ PAGOU;\nINAUDITA GRAÇA ME MOSTROU! \n\nENQUANTO AS HORAS PASSAM, \nEU TENHO GOZO E PAZ, E AGUARDO \nMEU BOM MESTRE, QUE TÃO FELIZ ME FAZ!\nJESUS A MIM VIRÁ BUSCAR,\nE ENTÃO PRA SEMPRE IREI GOZAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (98, 'ONDE ESTARIA EU?', 'ONDE ESTARIA EU?', 'ONDE ESTARIA EU,\nNÃO FOSSE A MÃO DO SENHOR?\nSOZINHO, SOLITÁRIO NO MUNDO,\nJESUS ME ALCANÇOU.\n\nCORO\nQUERO, CADA DIA MAIS,\nVIVER PRA TI, Ó MEU SENHOR,\nQUERO, CADA DIA MAIS,\nOUVIR A TUA VOZ DE AMOR. \n\nHOJE ME SINTO EM PAZ,\nSEGURO EM TUA MÃO ESTOU;\nCAMINHO PARA A ETERNIDADE,\nCANTANDO PARA O CÉU EU VOU.\n\nCORO (2X)\nQUERO, CADA DIA MAIS,\nVIVER PRA TI, Ó MEU SENHOR,\nQUERO, CADA DIA MAIS,\nOUVIR A TUA VOZ DE AMOR. (3X)', 'ONDE ESTARIA EU,\nNÃO FOSSE A MÃO DO SENHOR?\nSOZINHO, SOLITÁRIO NO MUNDO,\nJESUS ME ALCANÇOU.\n\n<coro>\nQUERO, CADA DIA MAIS,\nVIVER PRA TI, Ó MEU SENHOR,\nQUERO, CADA DIA MAIS,\nOUVIR A TUA VOZ DE AMOR. \n\nHOJE ME SINTO EM PAZ,\nSEGURO EM TUA MÃO ESTOU;\nCAMINHO PARA A ETERNIDADE,\nCANTANDO PARA O CÉU EU VOU.\n\n<coro tipo=''2X''>\nQUERO, CADA DIA MAIS,\nVIVER PRA TI, Ó MEU SENHOR,\nQUERO, CADA DIA MAIS,\nOUVIR A TUA VOZ DE AMOR. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (99, 'UM DIA JESUS ACHOU-ME', 'UM DIA JESUS ACHOU-ME', 'UM DIA JESUS ACHOU-ME\nTÃO LONGE DO MEU LAR,\nPERDIDO JÁ NO MUNDO\nSEM FORÇAS PRA VOLTAR;\nERGUENDO-ME COM OS BRAÇOS,\nLEVANTA AS MINHAS FORÇAS,\nE AGORA ANDAMOS JUNTOS\nVOLTANDO PARA O LAR.\n\nCORO \nA PRESENÇA DE JESUS\nENCHE O CORAÇÃO DE LUZ!\nMUI PRECIOSA FICA,\nCADA VEZ MAIS RICA,\nMINHA VIDA COM JESUS.\n\nPASSANDO PELOS VALES,\nPRA MINHA FÉ PROVAR;\nQUÃO DENSAS SÃO AS TREVAS\nQUE IMPEDEM, POIS, O ANDAR;\nNÃO HÁ NENHUM PERIGO,\nPOIS TENHO JÁ COMIGO,\nUM MUI PRECIOSO AMIGO\nVOLTANDO PARA O LAR.\n\nCORO \nA PRESENÇA DE JESUS\nENCHE O CORAÇÃO DE LUZ!\nMUI PRECIOSA FICA,\nCADA VEZ MAIS RICA,\nMINHA VIDA COM JESUS.\n\nENTRANDO NA ATMOSFERA\nQUE CERCA AQUELE LAR,\nALI MEU PAI ME ESPERA,\nTÃO LONGE HEI DE MORAR;\nNÃO HÁ NO MUNDO INTEIRO\nUM OUTRO COMPANHEIRO\nQUE MOSTRE TANTO ZELO\nVOLTANDO PARA O LAR.\n\nCORO \nA PRESENÇA DE JESUS\nENCHE O CORAÇÃO DE LUZ!\nMUI PRECIOSA FICA,\nCADA VEZ MAIS RICA,\nMINHA VIDA COM JESUS.', 'UM DIA JESUS ACHOU-ME\nTÃO LONGE DO MEU LAR,\nPERDIDO JÁ NO MUNDO\nSEM FORÇAS PRA VOLTAR;\nERGUENDO-ME COM OS BRAÇOS,\nLEVANTA AS MINHAS FORÇAS,\nE AGORA ANDAMOS JUNTOS\nVOLTANDO PARA O LAR.\n\n<coro>\nA PRESENÇA DE JESUS\nENCHE O CORAÇÃO DE LUZ!\nMUI PRECIOSA FICA,\nCADA VEZ MAIS RICA,\nMINHA VIDA COM JESUS.\n\nPASSANDO PELOS VALES,\nPRA MINHA FÉ PROVAR;\nQUÃO DENSAS SÃO AS TREVAS\nQUE IMPEDEM, POIS, O ANDAR;\nNÃO HÁ NENHUM PERIGO,\nPOIS TENHO JÁ COMIGO,\nUM MUI PRECIOSO AMIGO\nVOLTANDO PARA O LAR.\n\n<coro>\nA PRESENÇA DE JESUS\nENCHE O CORAÇÃO DE LUZ!\nMUI PRECIOSA FICA,\nCADA VEZ MAIS RICA,\nMINHA VIDA COM JESUS.\n\nENTRANDO NA ATMOSFERA\nQUE CERCA AQUELE LAR,\nALI MEU PAI ME ESPERA,\nTÃO LONGE HEI DE MORAR;\nNÃO HÁ NO MUNDO INTEIRO\nUM OUTRO COMPANHEIRO\nQUE MOSTRE TANTO ZELO\nVOLTANDO PARA O LAR.\n\n<coro>\nA PRESENÇA DE JESUS\nENCHE O CORAÇÃO DE LUZ!\nMUI PRECIOSA FICA,\nCADA VEZ MAIS RICA,\nMINHA VIDA COM JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (100, 'EU ME LEMBRO QUANDO JESUS ME TOCOU', 'EU ME LEMBRO QUANDO JESUS ME TOCOU', 'EU ME LEMBRO QUANDO JESUS ME TOCOU, \nFOI UM TOQUE DE ESPERANÇA E DE AMOR;\nCRISTO TRANSFORMOU A MORTE NO VIVER \nQUANDO A ELE ENTREGUEI TODO O MEU SER.\n\nCORO\nDEUS AMOU O MUNDO DE TAL MANEIRA\nQUE ENVIOU SEU FILHO JESUS, UNIGÊNITO,\nA MORRER NA CRUZ PRA NOS SALVAR E LIBERTAR-NOS.\nCRISTO VIVE EM MIM, \nPOSSO DIZER, O SEU TOQUE FEZ \nMINH''ALMA RENASCER.\n\nEU ME LEMBRO O QUE ELE FEZ POR MIM,\nFOI SEU BRAÇO FORTE QUE ME FEZ ASSIM,\nA CONHECER A ETERNA REDENÇÃO,\nDE BÊNÇÃOS CRISTO ENCHEU MEU CORAÇÃO.', 'EU ME LEMBRO QUANDO JESUS ME TOCOU, \nFOI UM TOQUE DE ESPERANÇA E DE AMOR;\nCRISTO TRANSFORMOU A MORTE NO VIVER \nQUANDO A ELE ENTREGUEI TODO O MEU SER.\n\n<coro>\nDEUS AMOU O MUNDO DE TAL MANEIRA\nQUE ENVIOU SEU FILHO JESUS, UNIGÊNITO,\nA MORRER NA CRUZ PRA NOS SALVAR E LIBERTAR-NOS.\nCRISTO VIVE EM MIM, <bis>\nPOSSO DIZER, O SEU TOQUE FEZ <bis>\nMINH''ALMA RENASCER.<bis>\n\nEU ME LEMBRO O QUE ELE FEZ POR MIM,\nFOI SEU BRAÇO FORTE QUE ME FEZ ASSIM,\nA CONHECER A ETERNA REDENÇÃO,\nDE BÊNÇÃOS CRISTO ENCHEU MEU CORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (101, 'QUEM ERA EU ANTES DE CONHECER', 'QUEM ERA EU ANTES DE CONHECER', 'QUEM ERA EU ANTES DE CONHECER\nA OBRA QUE DEUS OPEROU EM MEU SER?\nVIDA SEM DEUS, SEM A LUZ, SEM AMOR,\nANDAVA SEM RUMO, TÃO TRISTE E NA DOR.\nJESUS ME ENCONTROU E COM GRANDE AMOR, \nTOMOU-ME EM SEUS BRAÇOS E ME CARREGOU.\n\nVIVO FELIZ POIS JESUS ME MUDOU,\nA OBRA EM MIM O SENHOR REALIZOU;\nNOVA CRIATURA EU SOU EM JESUS,\nNÃO VIVO MAIS EU, VIVE EM MIM JESUS.\nJESUS É A MAIOR EXPRESSÃO DE AMOR, \nGLÓRIA, ALELUIA, É O NOSSO LOUVOR.', 'QUEM ERA EU ANTES DE CONHECER\nA OBRA QUE DEUS OPEROU EM MEU SER?\nVIDA SEM DEUS, SEM A LUZ, SEM AMOR,\nANDAVA SEM RUMO, TÃO TRISTE E NA DOR.\nJESUS ME ENCONTROU E COM GRANDE AMOR, \nTOMOU-ME EM SEUS BRAÇOS E ME CARREGOU.\n\nVIVO FELIZ POIS JESUS ME MUDOU,\nA OBRA EM MIM O SENHOR REALIZOU;\nNOVA CRIATURA EU SOU EM JESUS,\nNÃO VIVO MAIS EU, VIVE EM MIM JESUS.<bis>\nJESUS É A MAIOR EXPRESSÃO DE AMOR, <bis>\nGLÓRIA, ALELUIA, É O NOSSO LOUVOR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (102, 'MARAVILHOSO E SUBLIME PRA MIM', 'MARAVILHOSO E SUBLIME PRA MIM', 'MARAVILHOSO E SUBLIME PRA MIM,\nSIM, NUNCA ME ESQUECEREI,\nDIA GLORIOSO EM QUE A CRISTO EU VI\nE O CORAÇÃO LHE ENTREGUEI;\nOH! QUÃO PRECIOSO AMIGO ELE É,\nSALVOU-ME DA PERDIÇÃO,\nTIRANDO AS CULPAS E AS TREVAS,\nLIVRANDO E TRAZENDO-ME \nPLENO PERDÃO.\n\nCORO\nA PAZ DO CÉU ENCHEU MEU CORAÇÃO,\nQUANDO JESUS ME DEU A SALVAÇÃO;\nMINH''ALMA ENTÃO LAVOU\nE A LUZ EM MIM RAIOU;\nA PAZ DO CÉU ENCHEU \nMEU CORAÇÃO.\n\nGRANDE ESPERANÇA JESUS JÁ ME DEU,\nQUE NÃO DESVANECERÁ,\nHÁ UMA GLORIOSA MORADA NO CÉU,\nQUE BREVE MINHA SERÁ;\nTUDO PORQUE NESSE DIA FELIZ\nO MEU SENHOR ACEITEI,\nGRANDES RIQUEZAS E BÊNÇÃOS \nCELESTES DAS MÃOS \nDIVINAIS ALCANCEI.\n\nCORO\nA PAZ DO CÉU ENCHEU MEU CORAÇÃO,\nQUANDO JESUS ME DEU A SALVAÇÃO;\nMINH''ALMA ENTÃO LAVOU\nE A LUZ EM MIM RAIOU;\nA PAZ DO CÉU ENCHEU \nMEU CORAÇÃO.', 'MARAVILHOSO E SUBLIME PRA MIM,\nSIM, NUNCA ME ESQUECEREI,\nDIA GLORIOSO EM QUE A CRISTO EU VI\nE O CORAÇÃO LHE ENTREGUEI;\nOH! QUÃO PRECIOSO AMIGO ELE É,\nSALVOU-ME DA PERDIÇÃO,\nTIRANDO AS CULPAS E AS TREVAS,\nLIVRANDO E TRAZENDO-ME \nPLENO PERDÃO.\n\n<coro>\nA PAZ DO CÉU ENCHEU MEU CORAÇÃO,\nQUANDO JESUS ME DEU A SALVAÇÃO;\nMINH''ALMA ENTÃO LAVOU\nE A LUZ EM MIM RAIOU;\nA PAZ DO CÉU ENCHEU \nMEU CORAÇÃO.\n\nGRANDE ESPERANÇA JESUS JÁ ME DEU,\nQUE NÃO DESVANECERÁ,\nHÁ UMA GLORIOSA MORADA NO CÉU,\nQUE BREVE MINHA SERÁ;\nTUDO PORQUE NESSE DIA FELIZ\nO MEU SENHOR ACEITEI,\nGRANDES RIQUEZAS E BÊNÇÃOS \nCELESTES DAS MÃOS \nDIVINAIS ALCANCEI.\n\n<coro>\nA PAZ DO CÉU ENCHEU MEU CORAÇÃO,\nQUANDO JESUS ME DEU A SALVAÇÃO;\nMINH''ALMA ENTÃO LAVOU\nE A LUZ EM MIM RAIOU;\nA PAZ DO CÉU ENCHEU \nMEU CORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (103, 'A MINH''ALMA ESTAVA LONGE DO CAMINHO DO CÉU', 'A MINH''ALMA ESTAVA LONGE DO CAMINHO DO CÉU', 'A MINH''ALMA ESTAVA LONGE\nDO CAMINHO DO CÉU,\nEU ERA POBRE, DESPREZÍVEL PECADOR;\nMAS JESUS JÁ TRANSFORMOU\nMINHAS TREVAS EM LUZ, \nQUANDO ESTENDEU \nA SUA MÃO PARA MIM.\n\nCORO\nQUANDO JESUS ESTENDEU A SUA MÃO,\nQUANDO ESTENDEU A SUA MÃO PARA MIM, \nEU ERA POBRE, PERDIDO,\nSEM DEUS, SEM JESUS, \nQUANDO ESTENDEU \nA SUA MÃO PARA MIM.\n\nAGORA ME REGOZIJO DESDE QUE O \nACEITEI, E NA TEMPESTADE EU POSSO SOSSEGAR,\nPOIS COM ELE ESTOU LIBERTO DO \nPERIGO E DO MAL, DESDE QUE ESTENDEU\nA SUA MÃO PARA MIM.\n\nCORO\nQUANDO JESUS ESTENDEU A SUA MÃO,\nQUANDO ESTENDEU A SUA MÃO PARA MIM, \nEU ERA POBRE, PERDIDO,\nSEM DEUS, SEM JESUS, \nQUANDO ESTENDEU \nA SUA MÃO PARA MIM.', 'A MINH''ALMA ESTAVA LONGE\nDO CAMINHO DO CÉU,\nEU ERA POBRE, DESPREZÍVEL PECADOR;\nMAS JESUS JÁ TRANSFORMOU\nMINHAS TREVAS EM LUZ, \nQUANDO ESTENDEU \nA SUA MÃO PARA MIM.\n\n<coro>\nQUANDO JESUS ESTENDEU A SUA MÃO,\nQUANDO ESTENDEU A SUA MÃO PARA MIM, \nEU ERA POBRE, PERDIDO,\nSEM DEUS, SEM JESUS, \nQUANDO ESTENDEU \nA SUA MÃO PARA MIM.\n\nAGORA ME REGOZIJO DESDE QUE O \nACEITEI, E NA TEMPESTADE EU POSSO SOSSEGAR,\nPOIS COM ELE ESTOU LIBERTO DO \nPERIGO E DO MAL, DESDE QUE ESTENDEU\nA SUA MÃO PARA MIM.\n\n<coro>\nQUANDO JESUS ESTENDEU A SUA MÃO,\nQUANDO ESTENDEU A SUA MÃO PARA MIM, \nEU ERA POBRE, PERDIDO,\nSEM DEUS, SEM JESUS, \nQUANDO ESTENDEU \nA SUA MÃO PARA MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (104, 'VIVI TÃO LONGE DO SENHOR', 'VIVI TÃO LONGE DO SENHOR', 'VIVI TÃO LONGE DO SENHOR,\nASSIM EU QUIS ANDAR;\nATÉ QUE EU ENCONTREI O AMOR\nEM SEU GLORIOSO OLHAR.\n\nCORO\nSEU MARAVILHOSO OLHAR, (BIS)\nTRANSFORMOU MEU SER,\nTODO O MEU VIVER,\nSEU MARAVILHOSO OLHAR.\n\nSEU CORPO VI NA RUDE CRUZ\nSOFRENDO ASSIM POR MIM;\nE OUVI A VOZ DO MEU JESUS:\n''POR TI SOFRI ASSIM''.\n\nCORO\nSEU MARAVILHOSO OLHAR, (BIS)\nTRANSFORMOU MEU SER,\nTODO O MEU VIVER,\nSEU MARAVILHOSO OLHAR.\n\nEM CONTRIÇÃO, ENTÃO,\nVOLTEI À FONTE DESSE AMOR;\nPERDÃO E PAZ EM CRISTO ACHEI,\nPERTENÇO AO SALVADOR.\n\nCORO\nSEU MARAVILHOSO OLHAR, (BIS)\nTRANSFORMOU MEU SER,\nTODO O MEU VIVER,\nSEU MARAVILHOSO OLHAR.', 'VIVI TÃO LONGE DO SENHOR,\nASSIM EU QUIS ANDAR;\nATÉ QUE EU ENCONTREI O AMOR\nEM SEU GLORIOSO OLHAR.\n\n<coro>\nSEU MARAVILHOSO OLHAR, <bis>\nTRANSFORMOU MEU SER,\nTODO O MEU VIVER,\nSEU MARAVILHOSO OLHAR.\n\nSEU CORPO VI NA RUDE CRUZ\nSOFRENDO ASSIM POR MIM;\nE OUVI A VOZ DO MEU JESUS:\n''POR TI SOFRI ASSIM''.\n\n<coro>\nSEU MARAVILHOSO OLHAR, <bis>\nTRANSFORMOU MEU SER,\nTODO O MEU VIVER,\nSEU MARAVILHOSO OLHAR.\n\nEM CONTRIÇÃO, ENTÃO,\nVOLTEI À FONTE DESSE AMOR;\nPERDÃO E PAZ EM CRISTO ACHEI,\nPERTENÇO AO SALVADOR.\n\n<coro>\nSEU MARAVILHOSO OLHAR, <bis>\nTRANSFORMOU MEU SER,\nTODO O MEU VIVER,\nSEU MARAVILHOSO OLHAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (105, 'PERDIDO FOI QUE ELE ME ENCONTROU', 'PERDIDO FOI QUE ELE ME ENCONTROU', 'PERDIDO FOI QUE ELE ME ENCONTROU\nNESTE MUNDO VIL;\nTOMOU-ME E COM SEU SANGUE \nME LAVOU; HOJE SOU FELIZ.\n\nCORO\nHOJE SOU FELIZ, FOI-SE O MEU TEMOR,\nVOU PERMANECER JUNTO AO SALVADOR;\nFOI-SE A ESCURIDÃO, RAIA A LUZ DO SOL,\nHOJE EU SEI QUE SOU DO MEU SENHOR\nE ELE É MEU.\n\nSE NEGRA NOITE ASSUSTAR-ME VEM,\nOUÇO A SUA VOZ;\nAS TREVAS TORNAM-SE NA LUZ DO SOL\nCOM MEU SALVADOR.\n\nCORO\nHOJE SOU FELIZ, FOI-SE O MEU TEMOR,\nVOU PERMANECER JUNTO AO SALVADOR;\nFOI-SE A ESCURIDÃO, RAIA A LUZ DO SOL,\nHOJE EU SEI QUE SOU DO MEU SENHOR\nE ELE É MEU.\n\nSE MUITAS TENTAÇÕES ME SOBREVÊM, \nPARA ELE EU VOU;\nRECEBO FORÇAS QUE A MIM CONVÉM, \nSE COM ELE ESTOU.\n\nCORO\nHOJE SOU FELIZ, FOI-SE O MEU TEMOR,\nVOU PERMANECER JUNTO AO SALVADOR;\nFOI-SE A ESCURIDÃO, RAIA A LUZ DO SOL,\nHOJE EU SEI QUE SOU DO MEU SENHOR\nE ELE É MEU.', 'PERDIDO FOI QUE ELE ME ENCONTROU\nNESTE MUNDO VIL;\nTOMOU-ME E COM SEU SANGUE \nME LAVOU; HOJE SOU FELIZ.\n\n<coro>\nHOJE SOU FELIZ, FOI-SE O MEU TEMOR,\nVOU PERMANECER JUNTO AO SALVADOR;\nFOI-SE A ESCURIDÃO, RAIA A LUZ DO SOL,\nHOJE EU SEI QUE SOU DO MEU SENHOR\nE ELE É MEU.\n\nSE NEGRA NOITE ASSUSTAR-ME VEM,\nOUÇO A SUA VOZ;\nAS TREVAS TORNAM-SE NA LUZ DO SOL\nCOM MEU SALVADOR.\n\n<coro>\nHOJE SOU FELIZ, FOI-SE O MEU TEMOR,\nVOU PERMANECER JUNTO AO SALVADOR;\nFOI-SE A ESCURIDÃO, RAIA A LUZ DO SOL,\nHOJE EU SEI QUE SOU DO MEU SENHOR\nE ELE É MEU.\n\nSE MUITAS TENTAÇÕES ME SOBREVÊM, \nPARA ELE EU VOU;\nRECEBO FORÇAS QUE A MIM CONVÉM, \nSE COM ELE ESTOU.\n\n<coro>\nHOJE SOU FELIZ, FOI-SE O MEU TEMOR,\nVOU PERMANECER JUNTO AO SALVADOR;\nFOI-SE A ESCURIDÃO, RAIA A LUZ DO SOL,\nHOJE EU SEI QUE SOU DO MEU SENHOR\nE ELE É MEU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (106, 'PELA FÉ SOMOS SALVOS', 'PELA FÉ SOMOS SALVOS', 'PELA FÉ SOMOS SALVOS, \nPELA GRAÇA DE DEUS REVELADA EM JESUS;\nPELA FÉ NO SEU SANGUE VAMOS ALÉM DO VÉU, \nONDE BRILHA A DIVINA LUZ.\n\nCORO\nESTE É O FIRME FUNDAMENTO \nDA IGREJA, A FÉ, SOMENTE A FÉ!\nO INVISÍVEL NÓS JÁ VEMOS, \nPELA FÉ CHEGAREMOS À PÁTRIA \nCELESTIAL, PELA FÉ!\n\nPELA FÉ ENTENDEMOS OS MISTÉRIOS \nDE DEUS E ESCUTAMOS SUA VOZ;\nPELA FÉ A PALAVRA SE REVELA \nA NÓS, PELA FÉ, SOMENTE A FÉ!\n\nCORO\nESTE É O FIRME FUNDAMENTO \nDA IGREJA, A FÉ, SOMENTE A FÉ!\nO INVISÍVEL NÓS JÁ VEMOS, \nPELA FÉ CHEGAREMOS À PÁTRIA \nCELESTIAL, PELA FÉ!', 'PELA FÉ SOMOS SALVOS, \nPELA GRAÇA DE DEUS REVELADA EM JESUS;\nPELA FÉ NO SEU SANGUE VAMOS ALÉM DO VÉU, \nONDE BRILHA A DIVINA LUZ.\n\n<coro>\nESTE É O FIRME FUNDAMENTO \nDA IGREJA, A FÉ, SOMENTE A FÉ!\nO INVISÍVEL NÓS JÁ VEMOS, \nPELA FÉ CHEGAREMOS À PÁTRIA \nCELESTIAL, PELA FÉ!\n\nPELA FÉ ENTENDEMOS OS MISTÉRIOS \nDE DEUS E ESCUTAMOS SUA VOZ;\nPELA FÉ A PALAVRA SE REVELA \nA NÓS, PELA FÉ, SOMENTE A FÉ!\n\n<coro>\nESTE É O FIRME FUNDAMENTO \nDA IGREJA, A FÉ, SOMENTE A FÉ!\nO INVISÍVEL NÓS JÁ VEMOS, \nPELA FÉ CHEGAREMOS À PÁTRIA \nCELESTIAL, PELA FÉ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (107, 'QUANDO ANDAVA NO MUNDO ESCRAVIZADO', 'QUANDO ANDAVA NO MUNDO ESCRAVIZADO', 'QUANDO ANDAVA NO MUNDO ESCRAVIZADO, \nEU VIVIA PRESO NO PECADO, \nMAS UM HOMEM CERTO DIA \nME COMPROU E UM ALTO PREÇO \nPAGOU, E HOJE LIBERTO ESTOU.\n\nCORO\nHOJE EU NÃO SOU MAIS ESCRAVIZADO,\nUM HOMEM CHAMADO JESUS\nTEM ME LIBERTADO;\nLIBERDADE JESUS TEM PROCLAMADO,\nE VIDA NOVA TEM DADO,\nSOU FELIZ COM JESUS AO MEU LADO.\n\nERA ESCRAVO E VIVIA SEMPRE CANSADO,\nNA ANGÚSTIA E NA TRISTEZA SUBJUGADO,\nLIBERDADE EU NÃO TINHA, CRISTO DEU,\nNA CRUZ POR MIM JÁ MORREU\nE VIDA NOVA ME DEU.\n\nCORO\nHOJE EU NÃO SOU MAIS ESCRAVIZADO,\nUM HOMEM CHAMADO JESUS\nTEM ME LIBERTADO;\nLIBERDADE JESUS TEM PROCLAMADO,\nE VIDA NOVA TEM DADO,\nSOU FELIZ COM JESUS AO MEU LADO.', 'QUANDO ANDAVA NO MUNDO ESCRAVIZADO, \nEU VIVIA PRESO NO PECADO, \nMAS UM HOMEM CERTO DIA \nME COMPROU E UM ALTO PREÇO \nPAGOU, E HOJE LIBERTO ESTOU.\n\n<coro>\nHOJE EU NÃO SOU MAIS ESCRAVIZADO,\nUM HOMEM CHAMADO JESUS\nTEM ME LIBERTADO;\nLIBERDADE JESUS TEM PROCLAMADO,\nE VIDA NOVA TEM DADO,\nSOU FELIZ COM JESUS AO MEU LADO.\n\nERA ESCRAVO E VIVIA SEMPRE CANSADO,\nNA ANGÚSTIA E NA TRISTEZA SUBJUGADO,\nLIBERDADE EU NÃO TINHA, CRISTO DEU,\nNA CRUZ POR MIM JÁ MORREU\nE VIDA NOVA ME DEU.\n\n<coro>\nHOJE EU NÃO SOU MAIS ESCRAVIZADO,\nUM HOMEM CHAMADO JESUS\nTEM ME LIBERTADO;\nLIBERDADE JESUS TEM PROCLAMADO,<bis>\nE VIDA NOVA TEM DADO,<bis>\nSOU FELIZ COM JESUS AO MEU LADO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (108, 'ISRAEL SAIU DO EGITO', 'ISRAEL SAIU DO EGITO', 'ISRAEL SAIU DO EGITO,\nFOI ORDEM QUE DEUS LHE DEU,\nCHEGANDO AO MAR VERMELHO,\nTODO O ISRAEL TEMEU;\nMONTES ALTOS DE TODOS OS LADOS,\nMOISÉS LHES RESPONDEU:\nNÃO TEMAS, Ó ISRAEL,\nSÓ O SENHOR É DEUS.\n\nCORO\nSÓ O SENHOR É DEUS! (BIS)\nCANTEMOS COM MUITA ALEGRIA,\nDIZENDO QUE SÓ O SENHOR É DEUS. \n\nMOISÉS ORDENOU ÀS ÁGUAS DO MAR, \nQUE LHE OBEDECERAM, \nPOR TERRA SECA PASSARAM, \nPELO PODER DE DEUS;\nO EXÉRCITO DE FARAÓ, PORÉM, \nNO MAR PERECEU; MIRIÃ CANTOU DIZENDO:\nSÓ O SENHOR É DEUS.\n\nCORO\nSÓ O SENHOR É DEUS! (BIS)\nCANTEMOS COM MUITA ALEGRIA,\nDIZENDO QUE SÓ O SENHOR É DEUS. \n\nNO DESERTO FALTOU ÁGUA, \nISRAEL SE ENTRISTECEU, \nE TODOS SE REVOLTARAM\nCONTRA O SERVO DE DEUS;\nMOISÉS FEZ A ORAÇÃO, \nJEOVÁ LHE APARECEU, \nDA ROCHA BROTOU ÁGUA\nPELO PODER DE DEUS.\n\nCORO\nSÓ O SENHOR É DEUS! (BIS)\nCANTEMOS COM MUITA ALEGRIA,\nDIZENDO QUE SÓ O SENHOR É DEUS. \n\nOS PROFETAS DE BAAL, \nEM HOLOCAUSTOS SEUS, \nCLAMARAM ATÉ O MEIO DIA,\nBAAL NÃO LHES RESPONDEU;\nELIAS FEZ A ORAÇÃO, \nO FOGO DO CÉU DESCEU, \nQUEIMANDO TODO O HOLOCAUSTO, \nCOM O PODER DE DEUS.', 'ISRAEL SAIU DO EGITO,\nFOI ORDEM QUE DEUS LHE DEU,\nCHEGANDO AO MAR VERMELHO,\nTODO O ISRAEL TEMEU;\nMONTES ALTOS DE TODOS OS LADOS,\nMOISÉS LHES RESPONDEU:\nNÃO TEMAS, Ó ISRAEL,\nSÓ O SENHOR É DEUS.\n\n<coro>\nSÓ O SENHOR É DEUS! <bis>\nCANTEMOS COM MUITA ALEGRIA,\nDIZENDO QUE SÓ O SENHOR É DEUS. \n\nMOISÉS ORDENOU ÀS ÁGUAS DO MAR, \nQUE LHE OBEDECERAM, \nPOR TERRA SECA PASSARAM, \nPELO PODER DE DEUS;\nO EXÉRCITO DE FARAÓ, PORÉM, \nNO MAR PERECEU; MIRIÃ CANTOU DIZENDO:\nSÓ O SENHOR É DEUS.\n\n<coro>\nSÓ O SENHOR É DEUS! <bis>\nCANTEMOS COM MUITA ALEGRIA,\nDIZENDO QUE SÓ O SENHOR É DEUS. \n\nNO DESERTO FALTOU ÁGUA, \nISRAEL SE ENTRISTECEU, \nE TODOS SE REVOLTARAM\nCONTRA O SERVO DE DEUS;\nMOISÉS FEZ A ORAÇÃO, \nJEOVÁ LHE APARECEU, \nDA ROCHA BROTOU ÁGUA\nPELO PODER DE DEUS.\n\n<coro>\nSÓ O SENHOR É DEUS! <bis>\nCANTEMOS COM MUITA ALEGRIA,\nDIZENDO QUE SÓ O SENHOR É DEUS. \n\nOS PROFETAS DE BAAL, \nEM HOLOCAUSTOS SEUS, \nCLAMARAM ATÉ O MEIO DIA,\nBAAL NÃO LHES RESPONDEU;\nELIAS FEZ A ORAÇÃO, \nO FOGO DO CÉU DESCEU, \nQUEIMANDO TODO O HOLOCAUSTO, \nCOM O PODER DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (109, 'A MINHA VIDA TÃO VAZIA', 'A MINHA VIDA TÃO VAZIA', 'A MINHA VIDA TÃO VAZIA\nJESUS CRISTO TRANSFORMOU,\nNÃO TINHA PAZ NEM ALEGRIA\nTÉ QUE O SALVADOR ME ACHOU;\nTAL COMO A FLOR QUE NO JARDIM\nDESPONTA PARA A LUZ DO SOL,\nASSIM BRILHOU UM DIA EM MIM, JESUS.\nNASCI DE NOVO PRA ENTENDER\nO AMOR QUE CRISTO TEM POR MIM;\nJESUS ACHOU-ME, AGORA SOU FELIZ.\n\nPRA ME ENCONTRAR, PERDEU SUA VIDA,\nMEU JESUS, O BOM PASTOR;\nA MÃO QUE FOI NA CRUZ FERIDA\nME SALVOU, TÃO PECADOR.\nA TI, JESUS, CORDEIRO ETERNO,\nCONFESSO QUE ÉS MEU SALVADOR,\nJÁ ME LAVOU TEU SANGUE CARMESIM;\nTÃO FRÁGIL, TÃO PEQUENO SOU, \nCUIDA DE MIM COM TEU AMOR, \nCOMO UMA FLOR PEQUENA \nEM TEU JARDIM.', 'A MINHA VIDA TÃO VAZIA\nJESUS CRISTO TRANSFORMOU,\nNÃO TINHA PAZ NEM ALEGRIA\nTÉ QUE O SALVADOR ME ACHOU;\nTAL COMO A FLOR QUE NO JARDIM\nDESPONTA PARA A LUZ DO SOL,\nASSIM BRILHOU UM DIA EM MIM, JESUS.\nNASCI DE NOVO PRA ENTENDER\nO AMOR QUE CRISTO TEM POR MIM;\nJESUS ACHOU-ME, AGORA SOU FELIZ.\n\nPRA ME ENCONTRAR, PERDEU SUA VIDA,\nMEU JESUS, O BOM PASTOR;\nA MÃO QUE FOI NA CRUZ FERIDA\nME SALVOU, TÃO PECADOR.\nA TI, JESUS, CORDEIRO ETERNO,\nCONFESSO QUE ÉS MEU SALVADOR,\nJÁ ME LAVOU TEU SANGUE CARMESIM;\nTÃO FRÁGIL, TÃO PEQUENO SOU, \nCUIDA DE MIM COM TEU AMOR, \nCOMO UMA FLOR PEQUENA \nEM TEU JARDIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (110, 'OH! QUÃO CEGO ANDEI E PERDIDO VAGUEI', 'OH! QUÃO CEGO ANDEI E PERDIDO VAGUEI', 'OH! QUÃO CEGO ANDEI E PERDIDO VAGUEI\nLONGE, LONGE DO MEU SALVADOR;\nMAS DO CÉU ELE DESCEU E SEU SANGUE VERTEU\nPRA SALVAR UM TÃO POBRE PECADOR.\n\nCORO\nFOI NA CRUZ, FOI NA CRUZ ONDE UM DIA \nEU VI MEU PECADO CASTIGADO EM JESUS;\nFOI ALI PELA FÉ QUE MEUS OLHOS ABRI\nE AGORA ME ALEGRO EM SUA LUZ.\n\nEU OUVIA FALAR DESSA GRAÇA SEM PAR\nQUE DO CÉU TROUXE O NOSSO JESUS,\nMAS EU SURDO ME FIZ, \nCONVERTER-ME NÃO QUIS AO SENHOR \nQUE POR MIM MORREU NA CRUZ.\n\nCORO\nFOI NA CRUZ, FOI NA CRUZ ONDE UM DIA \nEU VI MEU PECADO CASTIGADO EM JESUS;\nFOI ALI PELA FÉ QUE MEUS OLHOS ABRI\nE AGORA ME ALEGRO EM SUA LUZ.\n\nMAS UM DIA SENTI MEU PECADO E VI\nSOBRE MIM A ESPADA DA LEI;\nAPRESSADO FUGI, \nEM JESUS ME ESCONDI E ABRIGO \nSEGURO NELE ACHEI.\n\nCORO\nFOI NA CRUZ, FOI NA CRUZ ONDE UM DIA \nEU VI MEU PECADO CASTIGADO EM JESUS;\nFOI ALI PELA FÉ QUE MEUS OLHOS ABRI\nE AGORA ME ALEGRO EM SUA LUZ.\n\nQUÃO DITOSO, ENTÃO, \nESSE MEU CORAÇÃO CONHECENDO \nO EXCELSO AMOR\nQUE LEVOU MEU JESUS A SOFRER \nLÁ NA CRUZ PRA SALVAR \nUM TÃO POBRE PECADOR.', 'OH! QUÃO CEGO ANDEI E PERDIDO VAGUEI\nLONGE, LONGE DO MEU SALVADOR;\nMAS DO CÉU ELE DESCEU E SEU SANGUE VERTEU\nPRA SALVAR UM TÃO POBRE PECADOR.\n\n<coro>\nFOI NA CRUZ, FOI NA CRUZ ONDE UM DIA \nEU VI MEU PECADO CASTIGADO EM JESUS;\nFOI ALI PELA FÉ QUE MEUS OLHOS ABRI\nE AGORA ME ALEGRO EM SUA LUZ.\n\nEU OUVIA FALAR DESSA GRAÇA SEM PAR\nQUE DO CÉU TROUXE O NOSSO JESUS,\nMAS EU SURDO ME FIZ, \nCONVERTER-ME NÃO QUIS AO SENHOR \nQUE POR MIM MORREU NA CRUZ.\n\n<coro>\nFOI NA CRUZ, FOI NA CRUZ ONDE UM DIA \nEU VI MEU PECADO CASTIGADO EM JESUS;\nFOI ALI PELA FÉ QUE MEUS OLHOS ABRI\nE AGORA ME ALEGRO EM SUA LUZ.\n\nMAS UM DIA SENTI MEU PECADO E VI\nSOBRE MIM A ESPADA DA LEI;\nAPRESSADO FUGI, \nEM JESUS ME ESCONDI E ABRIGO \nSEGURO NELE ACHEI.\n\n<coro>\nFOI NA CRUZ, FOI NA CRUZ ONDE UM DIA \nEU VI MEU PECADO CASTIGADO EM JESUS;\nFOI ALI PELA FÉ QUE MEUS OLHOS ABRI\nE AGORA ME ALEGRO EM SUA LUZ.\n\nQUÃO DITOSO, ENTÃO, \nESSE MEU CORAÇÃO CONHECENDO \nO EXCELSO AMOR\nQUE LEVOU MEU JESUS A SOFRER \nLÁ NA CRUZ PRA SALVAR \nUM TÃO POBRE PECADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (111, 'O POVO QUE ANDAVA EM TREVAS', 'O POVO QUE ANDAVA EM TREVAS', 'O POVO QUE ANDAVA EM TREVAS VIU\nUMA GRANDE LUZ, E SOBRE OS QUE ANDAVAM \nNA SOMBRA DA MORTE,\nRESPLANDECEU A LUZ;\nPORQUE UM MENINO NOS NASCEU,\nUM FILHO SE NOS DEU;\nO PRINCIPADO ESTÁ SOBRE OS SEUS OMBROS,\nELE É JESUS, JESUS, A LUZ DO MUNDO.\nINSTRUMENTOS\n\nMARAVILHOSO CONSELHEIRO, \nSEU NOME SERÁ,\nDEUS FORTE, PAI DA ETERNIDADE,\nPRÍNCIPE DA PAZ;\nDO PRINCIPADO E DA PAZ \nNÃO HAVERÁ FIM\nE SOBRE O TRONO DE DAVI REINARÁ JESUS,\nJESUS, A LUZ DO MUNDO.', 'O POVO QUE ANDAVA EM TREVAS VIU\nUMA GRANDE LUZ, E SOBRE OS QUE ANDAVAM \nNA SOMBRA DA MORTE,\nRESPLANDECEU A LUZ;\nPORQUE UM MENINO NOS NASCEU,\nUM FILHO SE NOS DEU;\nO PRINCIPADO ESTÁ SOBRE OS SEUS OMBROS,\nELE É JESUS, JESUS, A LUZ DO MUNDO.\n<instrumentos>\n\n\nMARAVILHOSO CONSELHEIRO, \nSEU NOME SERÁ,\nDEUS FORTE, PAI DA ETERNIDADE,\nPRÍNCIPE DA PAZ;\nDO PRINCIPADO E DA PAZ \nNÃO HAVERÁ FIM\nE SOBRE O TRONO DE DAVI REINARÁ JESUS,\nJESUS, A LUZ DO MUNDO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (112, 'UMA LUZ BRILHOU EM MEU CAMINHO', 'UMA LUZ BRILHOU EM MEU CAMINHO', 'UMA LUZ BRILHOU EM MEU CAMINHO,\nQUANDO EU IA TRISTE E SOZINHO;\nQUANDO EU OLHEI PRA CRUZ,\nNELA EU VI JESUS,\nFOI UM MINUTO SÓ DO SEU OLHAR.\n\nCORO\nFOI UM MINUTO SÓ, UM MINUTO SÓ,\nFOI UM MINUTO SÓ DO SEU OLHAR;\nTUDO EM MIM MUDOU, TUDO EM MIM CANTOU,\nFOI UM MINUTO SÓ DO SEU OLHAR.\n\nJESUS MARCOU A MINHA VIDA,\nNUNCA MAIS EU SEREI O MESMO;\nFOI SEU DIVINO OLHAR\nQUE ME ENSINOU A AMAR,\nFOI UM MINUTO SÓ DO SEU OLHAR.\n\nCORO\nFOI UM MINUTO SÓ, UM MINUTO SÓ,\nFOI UM MINUTO SÓ DO SEU OLHAR;\nTUDO EM MIM MUDOU, TUDO EM MIM CANTOU,\nFOI UM MINUTO SÓ DO SEU OLHAR.', 'UMA LUZ BRILHOU EM MEU CAMINHO,\nQUANDO EU IA TRISTE E SOZINHO;\nQUANDO EU OLHEI PRA CRUZ,\nNELA EU VI JESUS,\nFOI UM MINUTO SÓ DO SEU OLHAR.\n\n<coro>\nFOI UM MINUTO SÓ, UM MINUTO SÓ,\nFOI UM MINUTO SÓ DO SEU OLHAR;\nTUDO EM MIM MUDOU, TUDO EM MIM CANTOU,\nFOI UM MINUTO SÓ DO SEU OLHAR.\n\nJESUS MARCOU A MINHA VIDA,\nNUNCA MAIS EU SEREI O MESMO;\nFOI SEU DIVINO OLHAR\nQUE ME ENSINOU A AMAR,\nFOI UM MINUTO SÓ DO SEU OLHAR.\n\n<coro>\nFOI UM MINUTO SÓ, UM MINUTO SÓ,\nFOI UM MINUTO SÓ DO SEU OLHAR;\nTUDO EM MIM MUDOU, TUDO EM MIM CANTOU,\nFOI UM MINUTO SÓ DO SEU OLHAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (113, 'JESUS, A LUZ DIVINA', 'JESUS, A LUZ DIVINA', 'JESUS, A LUZ DIVINA\nQUE NÃO CESSA DE BRILHAR;\nDE DIA E DE NOITE E SEMPRE \nRELUZ SEM APAGAR.\n\nSÓ ELE É A LUZ QUE BRILHA,\nE PERMANECE SOBRE O ALTAR,\nE CONTINUA SEMPRE A ILUMINAR.\n\nJESUS, A LUZ QUE BRILHA\nEM NOSSOS CORAÇÕES,\nTIRANDO DAS NOSSAS MENTES\nAS NOSSAS ILUSÕES.\n\nSÓ ELE É A LUZ QUE BRILHA,\nEM TODO CÉU, NA TERRA E MAR,\nE CONTINUA SEMPRE A ILUMINAR.', 'JESUS, A LUZ DIVINA\nQUE NÃO CESSA DE BRILHAR;\nDE DIA E DE NOITE E SEMPRE \nRELUZ SEM APAGAR.\n\nSÓ ELE É A LUZ QUE BRILHA,<bis>\nE PERMANECE SOBRE O ALTAR,<bis>\nE CONTINUA SEMPRE A ILUMINAR.<bis>\n\nJESUS, A LUZ QUE BRILHA\nEM NOSSOS CORAÇÕES,\nTIRANDO DAS NOSSAS MENTES\nAS NOSSAS ILUSÕES.\n\nSÓ ELE É A LUZ QUE BRILHA,<bis>\nEM TODO CÉU, NA TERRA E MAR,<bis>\nE CONTINUA SEMPRE A ILUMINAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (114, 'AS RIQUEZAS DO MUNDO', 'AS RIQUEZAS DO MUNDO', 'AS RIQUEZAS DO MUNDO NADA VALEM PRA MIM,\nPOIS, JESUS, NO TEU REINO DÁS-ME VIDA SEM FIM;\nE NO LIVRO DA VIDA QUE CONSERVAS AÍ,\nCERTO ESTOU QUE MEU NOME FOI ESCRITO POR TI.\n\nCORO\nFOI ESCRITO POR TI O MEU NOME NO CÉU;\nSIM, NO LIVRO DA VIDA, \nFOI ESCRITO POR TI.\n\nMEUS PECADOS SÃO MUITOS, COMO A AREIA DO MAR;\nMAS JESUS ME REVELA SUA GRAÇA SEM PAR;\nVEIO PARA SALVAR-ME, O SEU SANGUE VERTEU,\nE AS DELÍCIAS ETERNAS ELE ME PROMETEU.\n\nCORO\nFOI ESCRITO POR TI O MEU NOME NO CÉU;\nSIM, NO LIVRO DA VIDA, \nFOI ESCRITO POR TI.\n\nÓ CIDADE FESTIVA, REFULGENTE DE LUZ,\nÉS MORADA DOS SANTOS E FIÉIS DE JESUS!\nSÓ VERÁ TUA GLÓRIA O QUE CRER NO SENHOR, \nCUJA VIDA FOI SALVA PELO SEU REDENTOR.\n\nCORO\nFOI ESCRITO POR TI O MEU NOME NO CÉU;\nSIM, NO LIVRO DA VIDA, \nFOI ESCRITO POR TI.', 'AS RIQUEZAS DO MUNDO NADA VALEM PRA MIM,\nPOIS, JESUS, NO TEU REINO DÁS-ME VIDA SEM FIM;\nE NO LIVRO DA VIDA QUE CON<m> AÍ,\nCERTO ESTOU QUE MEU NOME FOI ESCRITO POR TI.\n\n<coro>\nFOI ESCRITO POR TI O MEU NOME NO CÉU;\nSIM, NO LIVRO DA VIDA, \nFOI ESCRITO POR TI.\n\nMEUS PECADOS SÃO MUITOS, COMO A AREIA DO MAR;\nMAS JESUS ME REVELA SUA GRAÇA SEM PAR;\nVEIO PARA SALVAR-ME, O SEU SANGUE VERTEU,\nE AS DELÍCIAS ETERNAS ELE ME PROMETEU.\n\n<coro>\nFOI ESCRITO POR TI O MEU NOME NO CÉU;\nSIM, NO LIVRO DA VIDA, \nFOI ESCRITO POR TI.\n\nÓ CIDADE FESTIVA, REFULGENTE DE LUZ,\nÉS MORADA DOS SANTOS E FIÉIS DE JESUS!\nSÓ VERÁ TUA GLÓRIA O QUE CRER NO SENHOR, \nCUJA VIDA FOI SALVA PELO SEU REDENTOR.\n\n<coro>\nFOI ESCRITO POR TI O MEU NOME NO CÉU;\nSIM, NO LIVRO DA VIDA, \nFOI ESCRITO POR TI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (115, 'GRAÇAS DOU, Ó SENHOR', 'GRAÇAS DOU, Ó SENHOR', 'GRAÇAS DOU, Ó SENHOR, \nAINDA QUE TE IRASTE CONTRA MIM, \nTUA IRA SE RETIROU, TU ME CONSOLASTE.\nEIS QUE DEUS É SALVAÇÃO, \nCONFIAREI, E NÃO TEMEREI;\nO SENHOR, MINHA FORÇA E O MEU LOUVOR;\nSE TORNOU MINHA SALVAÇÃO.\n\nCORO (4X)\nCOM ALEGRIA TIRAREIS ÁGUAS\nDAS FONTES DA SALVAÇÃO.\n\nINSTRUMENTOS\nFINAL: GRAÇAS DOU, Ó SENHOR.', 'GRAÇAS DOU, Ó SENHOR, \nAINDA QUE TE IRASTE CONTRA MIM, \nTUA IRA SE RETIROU, TU ME CONSOLASTE.\nEIS QUE DEUS É SALVAÇÃO, \nCONFIAREI, E NÃO TEMEREI;\nO SENHOR, MINHA FORÇA E O MEU LOUVOR;\nSE TORNOU MINHA SALVAÇÃO.\n\n<coro tipo=''4X''>\nCOM ALEGRIA TIRAREIS ÁGUAS\nDAS FONTES DA SALVAÇÃO.\n<instrumentos>\n<final>GRAÇAS DOU, Ó SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (116, 'ACHEI SALVAÇÃO', 'ACHEI SALVAÇÃO', 'ACHEI SALVAÇÃO EM JESUS, \nMEU SENHOR,\nPERDÃO, LIBERDADE ENCONTREI;\nSUA ALMA RESIDE EM MEU CORAÇÃO\nE NO SEU AMOR TENHO PAZ.\n\nCORO\nPAZ DO SENHOR, CÉLICA PAZ,\nPAZ QUE ESTE MUNDO NÃO DÁ;\nQUANDO PENSO NA LUZ \nQUE CENTELHA DA CRUZ,\nTENHO PAZ, UMA CÉLICA PAZ.\n\nA CRISTO, MEU REI, EU DAREI UMA \nCANÇÃO TALENTO, SERVIÇO E LOUVOR;\nCONTENTE AOS SEUS PÉS, \nMEU FIEL CORAÇÃO DIRÁ: \nTENHO PAZ NO SENHOR.\n\nCORO\nPAZ DO SENHOR, CÉLICA PAZ,\nPAZ QUE ESTE MUNDO NÃO DÁ;\nQUANDO PENSO NA LUZ \nQUE CENTELHA DA CRUZ,\nTENHO PAZ, UMA CÉLICA PAZ.', 'ACHEI SALVAÇÃO EM JESUS, \nMEU SENHOR,\nPERDÃO, LIBERDADE ENCONTREI;\nSUA ALMA RESIDE EM MEU CORAÇÃO\nE NO SEU AMOR TENHO PAZ.\n\n<coro>\nPAZ DO SENHOR, CÉLICA PAZ,\nPAZ QUE ESTE MUNDO NÃO DÁ;\nQUANDO PENSO NA LUZ \nQUE CENTELHA DA CRUZ,\nTENHO PAZ, UMA CÉLICA PAZ.\n\nA CRISTO, MEU REI, EU DAREI UMA \nCANÇÃO TALENTO, SERVIÇO E LOUVOR;\nCONTENTE AOS SEUS PÉS, \nMEU FIEL CORAÇÃO DIRÁ: \nTENHO PAZ NO SENHOR.\n\n<coro>\nPAZ DO SENHOR, CÉLICA PAZ,\nPAZ QUE ESTE MUNDO NÃO DÁ;\nQUANDO PENSO NA LUZ \nQUE CENTELHA DA CRUZ,\nTENHO PAZ, UMA CÉLICA PAZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (117, 'COMO DESISTIR DESTE GRANDE AMOR?', 'COMO DESISTIR DESTE GRANDE AMOR?', 'COMO DESISTIR DESTE GRANDE AMOR?\nSE NÃO HÁ OUTRO AMOR IGUAL;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nNÃO POSSO PARAR NEM DESANIMAR,\nTENS ME DADO FORÇAS PRA VENCER;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nSENHOR, TU ÉS A PORÇÃO\nDA MINHA HERANÇA, DO MEU CÁLICE;\nSENHOR, ÉS MEU AMOR,\nPRA ONDE IREI, SE SÓ TU ÉS MEU SALVADOR?\n\nINSTRUMENTOS\n\nCOMO DESISTIR DESTE GRANDE AMOR?\nSE NÃO HÁ OUTRO AMOR IGUAL;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nNÃO POSSO PARAR NEM DESANIMAR,\nTENS ME DADO FORÇAS PRA VENCER;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nSENHOR, TU ÉS A PORÇÃO\nDA MINHA HERANÇA, DO MEU CÁLICE;\nSENHOR, ÉS MEU AMOR,\nPRA ONDE IREI, SE SÓ TU ÉS MEU SALVADOR?\n\nFINAL: ÉS MINHA HERANÇA, SENHOR.', 'COMO DESISTIR DESTE GRANDE AMOR?\nSE NÃO HÁ OUTRO AMOR IGUAL;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nNÃO POSSO PARAR NEM DESANIMAR,\nTENS ME DADO FORÇAS PRA VENCER;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nSENHOR, TU ÉS A PORÇÃO\nDA MINHA HERANÇA, DO MEU CÁLICE;\nSENHOR, ÉS MEU AMOR,\nPRA ONDE IREI, SE SÓ TU ÉS MEU SALVADOR?\n<instrumentos>\n\n\nCOMO DESISTIR DESTE GRANDE AMOR?\nSE NÃO HÁ OUTRO AMOR IGUAL;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nNÃO POSSO PARAR NEM DESANIMAR,\nTENS ME DADO FORÇAS PRA VENCER;\nNÃO DESISTIREI, PRA ONDE IREI?\n\nSENHOR, TU ÉS A PORÇÃO\nDA MINHA HERANÇA, DO MEU CÁLICE;\nSENHOR, ÉS MEU AMOR,\nPRA ONDE IREI, SE SÓ TU ÉS MEU SALVADOR?\n<final>ÉS MINHA HERANÇA, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (118, 'Ó SENHOR, DEUS DE ISRAEL (EDIFIQUEI UMA CASA)', 'Ó SENHOR, DEUS DE ISRAEL (EDIFIQUEI UMA CASA)', 'Ó SENHOR, DEUS DE ISRAEL!\nNO CÉU E NA TERRA (NÃO HÁ DEUS)\nNÃO HÁ DEUS COMO TU QUE GUARDAS \nA ALIANÇA E A MISERICÓRDIA\nAOS TEUS SERVOS QUE ANDAM DIANTE DE TI.\n\nCORO\nEDIFIQUEI UMA CASA \nPARA TUA MORADA, \nUM LUGAR PARA A TUA \nETERNA HABITAÇÃO.\n\nOUVE, POIS, DESDE O CÉU,\nA CADA ORAÇÃO\nE PERDOA (E PERDOA) \nO TEU POVO QUANDO, ARREPENDIDO, \nCONFESSAR O TEU NOME\nE BUSCAR TUA FACE NESTE LUGAR.\n\nCORO\nEDIFIQUEI UMA CASA \nPARA TUA MORADA, \nUM LUGAR PARA A TUA \nETERNA HABITAÇÃO.\n\nVEM, SENHOR, ACEITA E APERFEIÇOA\nA ADORAÇÃO QUE O TEU POVO\nSINCERAMENTE FAZ,\nCOMO OFERTA SUAVE DE LOUVOR.\n\nINSTRUMENTOS\n\nCOMO OFERTA SUAVE DE LOUVOR,\nCOMO OFERTA SUAVE DE LOUVOR.\n(COMO OFERTA DE LOUVOR)', 'Ó SENHOR, DEUS DE ISRAEL!\nNO CÉU E NA TERRA (NÃO HÁ DEUS)\nNÃO HÁ DEUS COMO TU QUE GUARDAS \nA ALIANÇA E A MISERICÓRDIA\nAOS TEUS SERVOS QUE ANDAM DIANTE DE TI.\n\n<coro>\nEDIFIQUEI UMA CASA \nPARA TUA MORADA, \nUM LUGAR PARA A TUA \nETERNA HABITAÇÃO.\n\nOUVE, POIS, DESDE O CÉU,\nA CADA ORAÇÃO\nE PERDOA (E PERDOA) \nO TEU POVO QUANDO, ARREPENDIDO, \nCONFESSAR O TEU NOME\nE BUSCAR TUA FACE NESTE LUGAR.\n\n<coro>\nEDIFIQUEI UMA CASA \nPARA TUA MORADA, \nUM LUGAR PARA A TUA \nETERNA HABITAÇÃO.\n\nVEM, SENHOR, ACEITA E APERFEIÇOA\nA ADORAÇÃO QUE O TEU POVO\nSINCERAMENTE FAZ,\nCOMO OFERTA SUAVE DE LOUVOR.\n<instrumentos>\nCOMO OFERTA SUAVE DE LOUVOR,\nCOMO OFERTA SUAVE DE LOUVOR.\n(COMO OFERTA DE LOUVOR)', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (119, 'JESUS, NOME PRECIOSO', 'JESUS, NOME PRECIOSO', 'JESUS, NOME PRECIOSO,\nJESUS, REI E SENHOR,\nJESUS, POR ESTE NOME\nSOU MAIS QUE VENCEDOR!\n\nJESUS, LÍRIO DOS VALES,\nJESUS, FLOR DO JARDIM,\nJESUS, COM TEU AMOR VEM\nHOJE TOCAR EM MIM!\n\nUMA PALAVRA SÓ BASTA, SENHOR,\nE TODO O MAL SE VAI E TODA A DOR;\nUMA PALAVRA SÓ DO TEU PODER\nE EM NOME DE JESUS EU VOU VENCER!\n\nJESUS, NOME DE VIDA,\nJESUS, FILHO DE DEUS,\nA TI TUDO SE INCLINA\nNA TERRA E NOS CÉUS! (BIS)', 'JESUS, NOME PRECIOSO,\nJESUS, REI E SENHOR,\nJESUS, POR ESTE NOME\nSOU MAIS QUE VENCEDOR!\n\nJESUS, LÍRIO DOS VALES,\nJESUS, FLOR DO JARDIM,\nJESUS, COM TEU AMOR VEM\nHOJE TOCAR EM MIM!\n\nUMA PALAVRA SÓ BASTA, SENHOR,\nE TODO O MAL SE VAI E TODA A DOR;\nUMA PALAVRA SÓ DO TEU PODER\nE EM NOME DE JESUS EU VOU VENCER!\n\nJESUS, NOME DE VIDA,\nJESUS, FILHO DE DEUS,\nA TI TUDO SE INCLINA\nNA TERRA E NOS CÉUS! <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (120, 'JESUS CRISTO MUDOU MEU VIVER', 'JESUS CRISTO MUDOU MEU VIVER', 'JESUS CRISTO MUDOU MEU VIVER (BIS)\nÉ A LUZ QUE ILUMINA MEU SER,\nSIM, JESUS CRISTO MUDOU MEU VIVER.\n\nDIFERENTE HOJE É O MEU CORAÇÃO (BIS)\nCRISTO DEU-ME PAZ E PERDÃO,\nSIM, DIFERENTE HOJE É O MEU CORAÇÃO.\n\nO AMOR QUE CONHECI EM CANÇÕES\nME FALAVA DE ILUSÕES;\nHOJE TUDO É DIFERENTE,\nISSO FALO A TODA A GENTE,\nQUE CRISTO SALVA O PECADOR.\n\nJESUS CRISTO MUDOU MEU VIVER (BIS)\nÉ A LUZ QUE ILUMINA MEU SER,\nSIM, JESUS CRISTO MUDOU MEU VIVER.', 'JESUS CRISTO MUDOU MEU VIVER <bis>\nÉ A LUZ QUE ILUMINA MEU SER,\nSIM, JESUS CRISTO MUDOU MEU VIVER.\n\nDIFERENTE HOJE É O MEU CORAÇÃO <bis>\nCRISTO DEU-ME PAZ E PERDÃO,\nSIM, DIFERENTE HOJE É O MEU CORAÇÃO.\n\nO AMOR QUE CONHECI EM CANÇÕES\nME FALAVA DE ILUSÕES;\nHOJE TUDO É DIFERENTE,\nISSO FALO A TODA A GENTE,\nQUE CRISTO SALVA O PECADOR.\n\nJESUS CRISTO MUDOU MEU VIVER <bis>\nÉ A LUZ QUE ILUMINA MEU SER,\nSIM, JESUS CRISTO MUDOU MEU VIVER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (121, 'TUDO, Ó CRISTO, A TI ENTREGO', 'TUDO, Ó CRISTO, A TI ENTREGO', 'TUDO, Ó CRISTO, A TI ENTREGO,\nTUDO, SIM, POR TI DAREI;\nRESOLUTO, MAS SUBMISSO,\nSEMPRE, SEMPRE SEGUIREI.\n\nCORO\nTUDO ENTREGAREI, \nTUDO ENTREGAREI;\nSIM, POR TI, JESUS BENDITO, \nTUDO DEIXAREI.\n\nTUDO, Ó CRISTO, A TI ENTREGO,\nCORPO E ALMA, EIS-ME AQUI;\nESTE MUNDO MAU RENEGO,\nÓ JESUS, ACEITA A MIM.\n\nCORO\nTUDO ENTREGAREI, \nTUDO ENTREGAREI;\nSIM, POR TI, JESUS BENDITO, \nTUDO DEIXAREI.\n\nTUDO, Ó CRISTO, A TI ENTREGO,\nOH! QUE GOZO MEU SENHOR!\nPAZ PERFEITA, PAZ COMPLETA,\nGLÓRIA, GLÓRIA AO SALVADOR.\n\nCORO\nTUDO ENTREGAREI, \nTUDO ENTREGAREI;\nSIM, POR TI, JESUS BENDITO, \nTUDO DEIXAREI.', 'TUDO, Ó CRISTO, A TI ENTREGO,\nTUDO, SIM, POR TI DAREI;\nRESOLUTO, MAS SUBMISSO,\nSEMPRE, SEMPRE SEGUIREI.\n\n<coro>\nTUDO ENTREGAREI, \nTUDO ENTREGAREI;\nSIM, POR TI, JESUS BENDITO, \nTUDO DEIXAREI.\n\nTUDO, Ó CRISTO, A TI ENTREGO,\nCORPO E ALMA, EIS-ME AQUI;\nESTE MUNDO MAU RENEGO,\nÓ JESUS, ACEITA A MIM.\n\n<coro>\nTUDO ENTREGAREI, \nTUDO ENTREGAREI;\nSIM, POR TI, JESUS BENDITO, \nTUDO DEIXAREI.\n\nTUDO, Ó CRISTO, A TI ENTREGO,\nOH! QUE GOZO MEU SENHOR!\nPAZ PERFEITA, PAZ COMPLETA,\nGLÓRIA, GLÓRIA AO SALVADOR.\n\n<coro>\nTUDO ENTREGAREI, \nTUDO ENTREGAREI;\nSIM, POR TI, JESUS BENDITO, \nTUDO DEIXAREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (122, 'AMO AO SENHOR PORQUE ELE ME OUVIU', 'AMO AO SENHOR PORQUE ELE ME OUVIU', 'AMO AO SENHOR PORQUE ELE ME OUVIU,\nINCLINOU OS SEUS OUVIDOS E ASSIM ME ATENDEU;\nO SENHOR, QUE É JUSTO E PIEDOSO,\nPOSSO NELE CONFIAR, CERTAMENTE ME GUIARÁ.\n\nANDAREI PERANTE A SUA FACE,\nSOU SEU SERVO, POIS ME LIBERTOU;\nLOUVÁ-LO-EI ETERNAMENTE \nNOS ÁTRIOS DA SUA CASA, \nFAREI A DEUS SACRIFÍCIOS DE LOUVOR.', 'AMO AO SENHOR PORQUE ELE ME OUVIU,\nINCLINOU OS SEUS OUVIDOS E ASSIM ME ATENDEU;\nO SENHOR, QUE É JUSTO E PIEDOSO,\nPOSSO NELE CONFIAR, CERTAMENTE ME GUIARÁ.\n\nANDAREI PERANTE A SUA FACE,\nSOU SEU SERVO, POIS ME LIBERTOU;<bis>\nLOUVÁ-LO-EI ETERNAMENTE <bis>\nNOS ÁTRIOS DA SUA CASA, <bis>\nFAREI A DEUS SACRIFÍCIOS DE LOUVOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (123, 'SEGUIR-TE-EI', 'SEGUIR-TE-EI', 'SEGUIR-TE-EI POR ONDE \nQUER QUE EU VÁ,\nLOUVAR-TE-EI DE TODO O CORAÇÃO;\nÉS PRECIOSO, AMADO E BOM JESUS, \nÉS MINHA VIDA, ÉS MINHA LUZ.\n\nTEU GRANDE AMOR POR MIM \nNÃO POSSO COMPARAR, \nPOR ISSO EU TE LOUVO,\nSOFRESTE EM MEU LUGAR, POR ISSO \nEU TE LOUVO, MORRESTE PRA ME SALVAR.\n\nINSTRUMENTOS\n\nSEGUIR-TE-EI POR ONDE \nQUER QUE EU VÁ\nLOUVAR-TE-EI DE TODO O CORAÇÃO;\nÉS PRECIOSO, AMADO E BOM JESUS,\nÉS MINHA VIDA, ÉS MINHA LUZ.', 'SEGUIR-TE-EI POR ONDE <bis>\nQUER QUE EU VÁ,<bis>\nLOUVAR-TE-EI DE TODO O CORAÇÃO;<bis>\nÉS PRECIOSO, AMADO E BOM JESUS, <bis>\nÉS MINHA VIDA, ÉS MINHA LUZ.<bis>\n\nTEU GRANDE AMOR POR MIM \nNÃO POSSO COMPARAR, \nPOR ISSO EU TE LOUVO,\nSOFRESTE EM MEU LUGAR, POR ISSO \nEU TE LOUVO, MORRESTE PRA ME SALVAR.\n<instrumentos>\n\n\nSEGUIR-TE-EI POR ONDE \nQUER QUE EU VÁ\nLOUVAR-TE-EI DE TODO O CORAÇÃO;\nÉS PRECIOSO, AMADO E BOM JESUS,\nÉS MINHA VIDA, ÉS MINHA LUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (124, 'PEREGRINANDO POR SOBRE OS MONTES', 'PEREGRINANDO POR SOBRE OS MONTES', 'PEREGRINANDO POR SOBRE OS MONTES\nE PELOS VALES, SEMPRE NA LUZ;\nCRISTO PROMETE NUNCA DEIXAR-ME:\n''EIS-ME CONVOSCO'', DISSE JESUS.\n\nCORO\nBRILHO CELESTE, BRILHO CELESTE,\nENCHE A MINH''ALMA A GLÓRIA DO CÉU!\nALELUIA! SIGO CANTANDO,\nDANDO LOUVORES, CRISTO É MEU.\n\nSOMBRAS À RODA, SOMBRAS EM CIMA,\nO SALVADOR NÃO HÃO DE OCULTAR;\nELE É A LUZ QUE NUNCA SE APAGA,\nJUNTO AO SEU LADO SEMPRE HEI DE ANDAR.\n\nCORO\nBRILHO CELESTE, BRILHO CELESTE,\nENCHE A MINH''ALMA A GLÓRIA DO CÉU!\nALELUIA! SIGO CANTANDO,\nDANDO LOUVORES, CRISTO É MEU.\n\nA LUZ BENDITA ME VAI CERCANDO,\nPASSOS AVANTE PARA A MANSÃO!\nMAIS E MAIS PERTO SEGUINDO O MESTRE,\nPOSSUO O GOZO DA SALVAÇÃO.\n\nCORO\nBRILHO CELESTE, BRILHO CELESTE,\nENCHE A MINH''ALMA A GLÓRIA DO CÉU!\nALELUIA! SIGO CANTANDO,\nDANDO LOUVORES, CRISTO É MEU.', 'PEREGRINANDO POR SOBRE OS MONTES\nE PELOS VALES, SEMPRE NA LUZ;\nCRISTO PROMETE NUNCA DEIXAR-ME:\n''EIS-ME CONVOSCO'', DISSE JESUS.\n\n<coro>\nBRILHO CELESTE, BRILHO CELESTE,\nENCHE A MINH''ALMA A GLÓRIA DO CÉU!\nALELUIA! SIGO CANTANDO,\nDANDO LOUVORES, CRISTO É MEU.\n\nSOMBRAS À RODA, SOMBRAS EM CIMA,\nO SALVADOR NÃO HÃO DE OCULTAR;\nELE É A LUZ QUE NUNCA SE APAGA,\nJUNTO AO SEU LADO SEMPRE HEI DE ANDAR.\n\n<coro>\nBRILHO CELESTE, BRILHO CELESTE,\nENCHE A MINH''ALMA A GLÓRIA DO CÉU!\nALELUIA! SIGO CANTANDO,\nDANDO LOUVORES, CRISTO É MEU.\n\nA LUZ BENDITA ME VAI CERCANDO,\nPASSOS AVANTE PARA A MANSÃO!\nMAIS E MAIS PERTO SEGUINDO O MESTRE,\nPOSSUO O GOZO DA SALVAÇÃO.\n\n<coro>\nBRILHO CELESTE, BRILHO CELESTE,\nENCHE A MINH''ALMA A GLÓRIA DO CÉU!\nALELUIA! SIGO CANTANDO,\nDANDO LOUVORES, CRISTO É MEU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (125, 'PELA FÉ EU CAMINHO', 'PELA FÉ EU CAMINHO', 'PELA FÉ EU CAMINHO OLHANDO SÓ PRA JESUS,\nMINHA MÃO PUS NA SUA E ASSIM SEGURO VOU.\nCOMO A LUZ DA AURORA, MINHA VEREDA VAI BRILHANDO MAIS E MAIS, ATÉ O DIA, \nDIA PERFEITO, CHEGAR.', 'PELA FÉ EU CAMINHO OLHANDO SÓ PRA JESUS,\nMINHA MÃO PUS NA SUA E ASSIM SEGURO VOU.\nCOMO A LUZ DA AURORA, MINHA VEREDA VAI BRILHANDO MAIS E MAIS, ATÉ O DIA, <bis>\nDIA PERFEITO, CHEGAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (126, 'QUERO PROSSEGUIR', 'QUERO PROSSEGUIR', 'QUERO PROSSEGUIR NESTA JORNADA,\nEU FUI CHAMADO,\nCOM LAÇOS DE AMOR ABENÇOADO,\nTENHO MEU JESUS SEMPRE AO MEU LADO.\n\nNÃO TEMER, PROSSEGUIR, E VENCER TODA LUTA, \nENFIM; MEU DEUS ESTÁ COMIGO, \nSINTO SUA PRESENÇA; DEU-ME CONFIANÇA,\nESTE É MEU SENHOR!\nAMIGO VERDADEIRO,\nSINCERO E AMOROSO,\nLEAL E COMPANHEIRO,\nJESUS, TENS MEU AMOR.', 'QUERO PROSSEGUIR NESTA JORNADA,\nEU FUI CHAMADO,\nCOM LAÇOS DE AMOR ABENÇOADO,\nTENHO MEU JESUS SEMPRE AO MEU LADO.\n\nNÃO TEMER, PROSSEGUIR, E VENCER TODA LUTA, \nENFIM; MEU DEUS ESTÁ COMIGO, \nSINTO SUA PRESENÇA; DEU-ME CONFIANÇA,\nESTE É MEU SENHOR!\nAMIGO VERDADEIRO,\nSINCERO E AMOROSO,<bis>\nLEAL E COMPANHEIRO,<bis>\nJESUS, TENS MEU AMOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (127, 'ESTOU A CAMINHAR', 'ESTOU A CAMINHAR', 'ESTOU A CAMINHAR PARA O MEU LAR NO CÉU;\nSOU PEREGRINO AQUI, O VIVER ETERNO É MEU.\nDE GRAÇA RECEBI DE DEUS A SALVAÇÃO,\nBENDITO O SANGUE QUE ME LAVOU,\nCREIO EM MEU CORAÇÃO.', 'ESTOU A CAMINHAR PARA O MEU LAR NO CÉU;\nSOU PEREGRINO AQUI, O VIVER ETERNO É MEU.\nDE GRAÇA RECEBI DE DEUS A SALVAÇÃO,\nBENDITO O SANGUE QUE ME LAVOU,\nCREIO EM MEU CORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (128, 'QUANDO A MÃO DE DEUS EM MIM VEIO TOCAR', 'QUANDO A MÃO DE DEUS EM MIM VEIO TOCAR', 'QUANDO A MÃO DE DEUS EM MIM VEIO TOCAR,\nALEGRIA TRANSBORDOU MEU VIVER;\nSUA VOZ SUAVE E MEIGA EM MIM SOOU, \nPUDE ENTÃO SENTIR O SEU IMENSO AMOR.\n\nCORO (2X) \nSOU FELIZ,\nSOU FELIZ EM JESUS,\nSIM, EU SOU FELIZ.\n\nQUANDO O TOQUE DO ESPÍRITO SENTI,\nDEU-ME PAZ E TRANSFORMOU A MINHA VIDA;\nCOMO O SOL NO SEU ALTO ESPLENDOR,\nCRISTO INUNDOU-ME COM O SEU AMOR.\n\nCORO (2X)\nSOU FELIZ,\nSOU FELIZ EM JESUS, \nSIM, EU SOU FELIZ.\n\nFINAL: \nSOU FELIZ EM JESUS,\nPOSSO ENTÃO DIZER: \nFELIZ, SOU FELIZ.', 'QUANDO A MÃO DE DEUS EM MIM VEIO TOCAR,\nALEGRIA TRANSBORDOU MEU VIVER;\nSUA VOZ SUAVE E MEIGA EM MIM SOOU, \nPUDE ENTÃO SENTIR O SEU IMENSO AMOR.\n\n<coro tipo=''2X''>\nSOU FELIZ,\nSOU FELIZ EM JESUS,\nSIM, EU SOU FELIZ.\n\nQUANDO O TOQUE DO ESPÍRITO SENTI,\nDEU-ME PAZ E TRANSFORMOU A MINHA VIDA;\nCOMO O SOL NO SEU ALTO ESPLENDOR,\nCRISTO INUNDOU-ME COM O SEU AMOR.\n\n<coro tipo=''2X''>\nSOU FELIZ,\nSOU FELIZ EM JESUS, \nSIM, EU SOU FELIZ.\n<final>SOU FELIZ EM JESUS,\nPOSSO ENTÃO DIZER: \nFELIZ, SOU FELIZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (129, 'FELICIDADE É TER CRISTO AO MEU LADO', 'FELICIDADE É TER CRISTO AO MEU LADO', 'FELICIDADE É TER CRISTO AO MEU \nLADO E POR ELE SER GUARDADO,\nTER MEU NOME ESCRITO NO CÉU;\nMEU NOME ESTÁ ESCRITO\nNAS MÃOS DO MEU JESUS,\nQUANDO MORREU ALI NA CRUZ,\nE ASSIM MUI FELIZ SOU EU.\n\nCORO\nFELICIDADE É POSSUIR O MEU JESUS\nE TODO DIA LEVAR A CRUZ\nATÉ O DIA EM QUE ELE VOLTAR;\nFELICIDADE É SER LAVADO\nNO SANGUE DE JESUS,\nE SEMPRE ANDAR NA SUA LUZ,\nATÉ O DIA EM QUE ELE VOLTAR.\n\nFELICIDADE É IR MORAR NUMA CIDADE,\nONDE HÁ PAZ E VERDADE,\nÉ JESUS QUEM MORA LÁ!\nEU SOU FELIZ E EM JESUS EU TENHO ALGO,\nE POR ELE JÁ SOU SALVO,\nELE PODE ME GUARDAR!\n\nCORO\nFELICIDADE É POSSUIR O MEU JESUS\nE TODO DIA LEVAR A CRUZ\nATÉ O DIA EM QUE ELE VOLTAR;\nFELICIDADE É SER LAVADO\nNO SANGUE DE JESUS,\nE SEMPRE ANDAR NA SUA LUZ,\nATÉ O DIA EM QUE ELE VOLTAR.', 'FELICIDADE É TER CRISTO AO MEU \nLADO E POR ELE SER GUARDADO,\nTER MEU NOME ESCRITO NO CÉU;\nMEU NOME ESTÁ ESCRITO\nNAS MÃOS DO MEU JESUS,\nQUANDO MORREU ALI NA CRUZ,\nE ASSIM MUI FELIZ SOU EU.\n\n<coro>\nFELICIDADE É POSSUIR O MEU JESUS\nE TODO DIA LEVAR A CRUZ\nATÉ O DIA EM QUE ELE VOLTAR;\nFELICIDADE É SER LAVADO\nNO SANGUE DE JESUS,\nE SEMPRE ANDAR NA SUA LUZ,\nATÉ O DIA EM QUE ELE VOLTAR.\n\nFELICIDADE É IR MORAR NUMA CIDADE,\nONDE HÁ PAZ E VERDADE,\nÉ JESUS QUEM MORA LÁ!\nEU SOU FELIZ E EM JESUS EU TENHO ALGO,\nE POR ELE JÁ SOU SALVO,\nELE PODE ME GUARDAR!\n\n<coro>\nFELICIDADE É POSSUIR O MEU JESUS\nE TODO DIA LEVAR A CRUZ\nATÉ O DIA EM QUE ELE VOLTAR;\nFELICIDADE É SER LAVADO\nNO SANGUE DE JESUS,\nE SEMPRE ANDAR NA SUA LUZ,\nATÉ O DIA EM QUE ELE VOLTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (130, 'TENHO GRANDE GOZO', 'TENHO GRANDE GOZO', 'TENHO GRANDE GOZO DESDE QUE REPOUSO\nNESTE CRISTO AMADO QUE POR MIM FOI DADO;\nQUE DESCEU DA GLÓRIA,\nSUPORTOU POBREZA\nPRA ME DAR VITÓRIA E ME \nDAR RIQUEZA.\n\nQUANTA DOR SENTIA LÁ NA CRUZ SOMBRIA\nQUANDO PENDURADO PELO MEU PECADO;\nNESSA CRUZ ERGUIDA,\nOH! QUE AMOR PROFUNDO!\nENTREGOU SUA VIDA\nPRA DAR VIDA AO MUNDO.\n\nMEU DESEJO AGORA, PELA VIDA AFORA,\nÉ SEGUIR AO LADO DESSE CRISTO AMADO;\nQUERO, DIA A DIA, MAIS E MAIS AMÁ-LO\nE, COM ALEGRIA, PARA SEMPRE HONRÁ-LO.', 'TENHO GRANDE GOZO DESDE QUE REPOUSO\nNESTE CRISTO AMADO QUE POR MIM FOI DADO;\nQUE DESCEU DA GLÓRIA,\nSUPORTOU POBREZA<bis>\nPRA ME DAR VITÓRIA E ME <bis>\nDAR RIQUEZA.<bis>\n\nQUANTA DOR SENTIA LÁ NA CRUZ SOMBRIA\nQUANDO PENDURADO PELO MEU PECADO;\nNESSA CRUZ ERGUIDA,<bis>\nOH! QUE AMOR PROFUNDO!<bis>\nENTREGOU SUA VIDA<bis>\nPRA DAR VIDA AO MUNDO.<bis>\n\nMEU DESEJO AGORA, PELA VIDA AFORA,\nÉ SEGUIR AO LADO DESSE CRISTO AMADO;\nQUERO, DIA A DIA, MAIS E MAIS AMÁ-LO<bis>\nE, COM ALEGRIA, PARA SEMPRE HONRÁ-LO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (131, 'ÀS VEZES, ALGUÉM ME PERGUNTA', 'ÀS VEZES, ALGUÉM ME PERGUNTA', 'ÀS VEZES, ALGUÉM ME PERGUNTA \nPORQUE VIVO ALEGRE E SEMPRE A CANTAR;\nRESPONDO: SOU MUITO FELIZ \nPORQUE JESUS CRISTO \nVEIO EM MIM MORAR.\n\nCORO\nACHEI A FELICIDADE,\nEU NÃO ESPERAVA QUE A FOSSE ENCONTRAR;\nMAS UM DIA ENCONTREI COM JESUS\nE A FELICIDADE VEIO EM MIM MORAR.\n\nÀS VEZES, O MEU CORAÇÃO\nFICA PERTURBADO, PERDENDO A PAZ;\nAOS PÉS DO MEU SALVADOR,\nACHEI O SEGREDO DA PERFEITA PAZ.', 'ÀS VEZES, ALGUÉM ME PERGUNTA \nPORQUE VIVO ALEGRE E SEMPRE A CANTAR;\nRESPONDO: SOU MUITO FELIZ \nPORQUE JESUS CRISTO \nVEIO EM MIM MORAR.\n\n<coro>\nACHEI A FELICIDADE,\nEU NÃO ESPERAVA QUE A FOSSE ENCONTRAR;\nMAS UM DIA ENCONTREI COM JESUS\nE A FELICIDADE VEIO EM MIM MORAR.\n\nÀS VEZES, O MEU CORAÇÃO\nFICA PERTURBADO, PERDENDO A PAZ;\nAOS PÉS DO MEU SALVADOR,\nACHEI O SEGREDO DA PERFEITA PAZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (132, 'JÁ NÃO ESTOU SOZINHO', 'JÁ NÃO ESTOU SOZINHO', 'JÁ NÃO ESTOU SOZINHO, AGORA SOU FELIZ\nCOM CRISTO NO MEU CORAÇÃO;\nELE É MEU GRANDE AMIGO, NÃO TEMO O PERIGO,\nCOM CRISTO NO MEU CORAÇÃO.\n\nCORO\nOH! EU SOU FELIZ, AGORA VOU CANTAR,\nPOIS CONTENTE ESTOU COM MEU SALVADOR,\nFELIZ AGORA ENTÃO EU VIVEREI. \n\nJESUS, HÁ MUITO TEMPO MORREU EM UMA CRUZ,\nMORREU SÓ PARA ME SALVAR;\nSEU SANGUE DERRAMOU,\nLAVANDO OS MEUS PECADOS,\nE DESTA FORMA AGORA SALVO ESTOU.\n\nCORO\nOH! EU SOU FELIZ, AGORA VOU CANTAR,\nPOIS CONTENTE ESTOU COM MEU SALVADOR,\nFELIZ AGORA ENTÃO EU VIVEREI. (BIS)', 'JÁ NÃO ESTOU SOZINHO, AGORA SOU FELIZ\nCOM CRISTO NO MEU CORAÇÃO;\nELE É MEU GRANDE AMIGO, NÃO TEMO O PERIGO,\nCOM CRISTO NO MEU CORAÇÃO.\n\n<coro>\nOH! EU SOU FELIZ, AGORA VOU CANTAR,\nPOIS CONTENTE ESTOU COM MEU SALVADOR,\nFELIZ AGORA ENTÃO EU VIVEREI. \n\nJESUS, HÁ MUITO TEMPO MORREU EM UMA CRUZ,\nMORREU SÓ PARA ME SALVAR;\nSEU SANGUE DERRAMOU,\nLAVANDO OS MEUS PECADOS,\nE DESTA FORMA AGORA SALVO ESTOU.\n\n<coro>\nOH! EU SOU FELIZ, AGORA VOU CANTAR,\nPOIS CONTENTE ESTOU COM MEU SALVADOR,\nFELIZ AGORA ENTÃO EU VIVEREI. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (133, 'EU ESTAVA SÓ, SEM O SENHOR', 'EU ESTAVA SÓ, SEM O SENHOR', 'EU ESTAVA SÓ, SEM O SENHOR,\nSEM PAZ E SEM NENHUM VALOR\nE NEM MESMO QUERIA COMPREENDER\nO TEU GRANDE AMOR; \nERA ASSIM O MEU VIVER.\n\nMAS UM DIA TUA VOZ OUVI,\nTUA PAZ EU PUDE SENTIR,\nO TEU AMOR ME TRANSFORMOU,\nNOVA CRIATURA SOU.\n\nINSTRUMENTOS\n\nMINHA VIDA ESTÁ NO SENHOR,\nPOIS DE TI DEPENDENTE SOU,\nANTES MESMO DE TUDO EXISTIR\nESCOLHESTE A MIM, \nE ASSIM ME ENTREGO A TI.\n\nTUA VOZ NÃO ESTRANHAREI,\nTÃO SUAVE EU A OUVIREI,\nPOIS DE TI SOU E TU ÉS MEU,\nALELUIA! GLÓRIA A DEUS!', 'EU ESTAVA SÓ, SEM O SENHOR,\nSEM PAZ E SEM NENHUM VALOR\nE NEM MESMO QUERIA COMPREENDER\nO TEU GRANDE AMOR; \nERA ASSIM O MEU VIVER.\n\nMAS UM DIA TUA VOZ OUVI,\nTUA PAZ EU PUDE SENTIR,\nO TEU AMOR ME TRANSFORMOU,\nNOVA CRIATURA SOU.\n<instrumentos>\n\n\nMINHA VIDA ESTÁ NO SENHOR,\nPOIS DE TI DEPENDENTE SOU,\nANTES MESMO DE TUDO EXISTIR\nESCOLHESTE A MIM, \nE ASSIM ME ENTREGO A TI.\n\nTUA VOZ NÃO ESTRANHAREI,\nTÃO SUAVE EU A OUVIREI,\nPOIS DE TI SOU E TU ÉS MEU,\nALELUIA! GLÓRIA A DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (134, 'QUE SEGURANÇA TENHO EM JESUS', 'QUE SEGURANÇA TENHO EM JESUS', 'QUE SEGURANÇA TENHO EM JESUS,\nHÁ NELE GOZO, PAZ, VIDA E LUZ;\nCOM CRISTO HERDEIRO, DEUS ME ACEITOU\nMEDIANTE O FILHO QUE ME SALVOU.\n\nCORO (2X)\nCONTO ESTA HISTÓRIA \nCANTANDO ASSIM: NA CRUZ \nFOI CRISTO MORTO POR MIM.\n\nINTEIRAMENTE ME SUBMETI,\nPLENA ALEGRIA NELE SENTI;\nANJOS DESCENDO TRAZEM DOS CÉUS\nPROVAS DA GRAÇA QUE VEM DE DEUS.\n\nCORO (2X)\nCONTO ESTA HISTÓRIA \nCANTANDO ASSIM: NA CRUZ \nFOI CRISTO MORTO POR MIM.\n\nFIRMADO EM CRISTO, NO SEU AMOR, \nESTOU CONTENTE EM MEU SALVADOR; \nESPERANÇOSO HEI DE VIVER \nPOR JESUS CRISTO, POR SEU PODER! \n\nCORO (2X)\nCONTO ESTA HISTÓRIA \nCANTANDO ASSIM: NA CRUZ \nFOI CRISTO MORTO POR MIM.', 'QUE SEGURANÇA TENHO EM JESUS,\nHÁ NELE GOZO, PAZ, VIDA E LUZ;\nCOM CRISTO HERDEIRO, DEUS ME ACEITOU\nMEDIANTE O FILHO QUE ME SALVOU.<coro tipo=''2X''>\nCONTO ESTA HISTÓRIA \nCANTANDO ASSIM: NA CRUZ \nFOI CRISTO MORTO POR MIM.\n\nINTEIRAMENTE ME SUBMETI,\nPLENA ALEGRIA NELE SENTI;\nANJOS DESCENDO TRAZEM DOS CÉUS\nPROVAS DA GRAÇA QUE VEM DE DEUS.<coro tipo=''2X''>\nCONTO ESTA HISTÓRIA \nCANTANDO ASSIM: NA CRUZ \nFOI CRISTO MORTO POR MIM.\n\nFIRMADO EM CRISTO, NO SEU AMOR, \nESTOU CONTENTE EM MEU SALVADOR; \nESPERANÇOSO HEI DE VIVER \nPOR JESUS CRISTO, POR SEU PODER!<coro tipo=''2X''>\nCONTO ESTA HISTÓRIA \nCANTANDO ASSIM: NA CRUZ \nFOI CRISTO MORTO POR MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (135, 'EM MEU CORAÇÃO', 'EM MEU CORAÇÃO', 'EM MEU CORAÇÃO REINA UMA DOCE PAZ\nDE ALGUÉM QUE POR MIM MORREU\nPRA ME DAR A SALVAÇÃO.\n\nESSE ALGUÉM, EU SEI, É JESUS, O REI,\nQUE SE FEZ PEQUENO EM MEU LUGAR\nPARA A VIDA ETERNA ME DAR.\n\nINSTRUMENTOS\n\nGLÓRIA E ALELUIA A JESUS CANTAREI\nCOM GRATIDÃO E LOUVOR,\nPARA TODO O SEMPRE, AMÉM!', 'EM MEU CORAÇÃO REINA UMA DOCE PAZ\nDE ALGUÉM QUE POR MIM MORREU\nPRA ME DAR A SALVAÇÃO.\n\nESSE ALGUÉM, EU SEI, É JESUS, O REI,\nQUE SE FEZ PEQUENO EM MEU LUGAR\nPARA A VIDA ETERNA ME DAR.\n<instrumentos>\nGLÓRIA E ALELUIA A JESUS CANTAREI\nCOM GRATIDÃO E LOUVOR,<bis>\nPARA TODO O SEMPRE, AMÉM!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (136, 'ESTA PAZ QUE SINTO EM MINH''ALMA', 'ESTA PAZ QUE SINTO EM MINH''ALMA', 'ESTA PAZ QUE SINTO EM MINH''ALMA\nNÃO É PORQUE TUDO EM MIM VAI BEM;\nESTA PAZ QUE SINTO EM MINH''ALMA\nÉ PORQUE EU AMO AO MEU SENHOR.\n\nCORO\nNÃO OLHO AS CIRCUNSTÂNCIAS,\n(NÃO, NÃO, NÃO) VARÕES\nSÓ OLHO SEU AMOR \n(SEU GRANDE AMOR) VARÕES\nNÃO ME GUIO POR VISTA,\nALEGRE ESTOU.\n\nESTE GOZO QUE SINTO EM MINH''ALMA\nNÃO É PORQUE OLHO AO MEU REDOR;\nESTE GOZO QUE SINTO EM MINH''ALMA\nÉ PORQUE EU AMO AO MEU SENHOR.\n\nCORO\nNÃO OLHO AS CIRCUNSTÂNCIAS,\n(NÃO, NÃO, NÃO) VARÕES\nSÓ OLHO SEU AMOR \n(SEU GRANDE AMOR) VARÕES\nNÃO ME GUIO POR VISTA,\nALEGRE ESTOU.\n\nAINDA QUE A TERRA NÃO FLORESÇA,\nE A VIDE NÃO DÊ O SEU FRUTO;\nAINDA QUE OS MONTES SE LANCEM AO MAR, \nE A TERRA TREMA, HEI DE CONFIAR.\n\nCORO\nNÃO OLHO AS CIRCUNSTÂNCIAS,\n(NÃO, NÃO, NÃO) VARÕES\nSÓ OLHO SEU AMOR \n(SEU GRANDE AMOR) VARÕES\nNÃO ME GUIO POR VISTA,\nALEGRE ESTOU.\n\nALELUIA, OH! GLÓRIA, ALELUIA,\nALELUIA DOU AO MEU SENHOR. \nALELUIA, OH! GLÓRIA, ALELUIA,\nALELUIA DOU AO MEU SENHOR. \n\nCORO\nNÃO OLHO AS CIRCUNSTÂNCIAS,\n(NÃO, NÃO, NÃO) VARÕES\nSÓ OLHO SEU AMOR \n(SEU GRANDE AMOR) VARÕES\nNÃO ME GUIO POR VISTA,\nALEGRE ESTOU.', 'ESTA PAZ QUE SINTO EM MINH''ALMA\nNÃO É PORQUE TUDO EM MIM VAI BEM;\nESTA PAZ QUE SINTO EM MINH''ALMA\nÉ PORQUE EU AMO AO MEU SENHOR.\n\n<coro>\nNÃO OLHO AS CIRCUNSTÂNCIAS,<bis>\n(NÃO, NÃO, NÃO) <h><bis>\nSÓ OLHO SEU AMOR <bis>\n(SEU GRANDE AMOR) <h><bis>\nNÃO ME GUIO POR VISTA,<bis>\nALEGRE ESTOU.<bis>\n\nESTE GOZO QUE SINTO EM MINH''ALMA\nNÃO É PORQUE OLHO AO MEU REDOR;\nESTE GOZO QUE SINTO EM MINH''ALMA\nÉ PORQUE EU AMO AO MEU SENHOR.\n\n<coro>\nNÃO OLHO AS CIRCUNSTÂNCIAS,<bis>\n(NÃO, NÃO, NÃO) <h><bis>\nSÓ OLHO SEU AMOR <bis>\n(SEU GRANDE AMOR) <h><bis>\nNÃO ME GUIO POR VISTA,<bis>\nALEGRE ESTOU.<bis>\n\nAINDA QUE A TERRA NÃO FLORESÇA,\nE A VIDE NÃO DÊ O SEU FRUTO;\nAINDA QUE OS MONTES SE LANCEM AO MAR, \nE A TERRA TREMA, HEI DE CONFIAR.\n\n<coro>\nNÃO OLHO AS CIRCUNSTÂNCIAS,<bis>\n(NÃO, NÃO, NÃO) <h><bis>\nSÓ OLHO SEU AMOR <bis>\n(SEU GRANDE AMOR) <h><bis>\nNÃO ME GUIO POR VISTA,<bis>\nALEGRE ESTOU.<bis>\n\nALELUIA, OH! GLÓRIA, ALELUIA,\nALELUIA DOU AO MEU SENHOR. \nALELUIA, OH! GLÓRIA, ALELUIA,\nALELUIA DOU AO MEU SENHOR. \n\n<coro>\nNÃO OLHO AS CIRCUNSTÂNCIAS,<bis>\n(NÃO, NÃO, NÃO) <h><bis>\nSÓ OLHO SEU AMOR <bis>\n(SEU GRANDE AMOR) <h><bis>\nNÃO ME GUIO POR VISTA,<bis>\nALEGRE ESTOU.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (137, 'QUE DOCE VOZ TEM MEU SENHOR', 'QUE DOCE VOZ TEM MEU SENHOR', 'QUE DOCE VOZ TEM MEU SENHOR!\nVOZ DE AMOR, TÃO TERNA E GRACIOSA,\nQUE ENCHE O CORAÇÃO, DÁ CONSOLAÇÃO \nQUE SÓ O CRENTE GOZA.\n\nCORO\nQUAL MAIOR PRAZER QUE LHE OUVIR DIZER: \n''VEM, MEU FILHO, VEM ESCUTAR\nO QUE EU FIZ POR TI, TUDO O QUE SOFRI\nNA CRUZ PRA TE RESGATAR''?\n\nCHAMOU-ME NÃO SÓ UMA VEZ,\nTANTAS TÉ QUE EU TRISTE, HUMILHADO,\nPUDE A VOZ OUVIR, PUDE ENTÃO SAIR\nDAS GARRAS DO PECADO.\n\nCORO\nQUAL MAIOR PRAZER QUE LHE OUVIR DIZER: \n''VEM, MEU FILHO, VEM ESCUTAR\nO QUE EU FIZ POR TI, TUDO O QUE SOFRI\nNA CRUZ PRA TE RESGATAR''?\n\nJESUS NÃO ME DEIXA SOFRER,\nSUA VOZ ME ENSINA O CAMINHO\nDE VENCER O MAL, COM FIRMEZA TAL,\nQUE NUNCA ESTOU SOZINHO.', 'QUE DOCE VOZ TEM MEU SENHOR!\nVOZ DE AMOR, TÃO TERNA E GRACIOSA,\nQUE ENCHE O CORAÇÃO, DÁ CONSOLAÇÃO \nQUE SÓ O CRENTE GOZA.\n\n<coro>\nQUAL MAIOR PRAZER QUE LHE OUVIR DIZER: \n''VEM, MEU FILHO, VEM ESCUTAR\nO QUE EU FIZ POR TI, TUDO O QUE SOFRI\nNA CRUZ PRA TE RESGATAR''?\n\nCHAMOU-ME NÃO SÓ UMA VEZ,\nTANTAS TÉ QUE EU TRISTE, HUMILHADO,\nPUDE A VOZ OUVIR, PUDE ENTÃO SAIR\nDAS GARRAS DO PECADO.\n\n<coro>\nQUAL MAIOR PRAZER QUE LHE OUVIR DIZER: \n''VEM, MEU FILHO, VEM ESCUTAR\nO QUE EU FIZ POR TI, TUDO O QUE SOFRI\nNA CRUZ PRA TE RESGATAR''?\n\nJESUS NÃO ME DEIXA SOFRER,\nSUA VOZ ME ENSINA O CAMINHO\nDE VENCER O MAL, COM FIRMEZA TAL,\nQUE NUNCA ESTOU SOZINHO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (138, 'HÁ SEMPRE ALGUÉM QUE NÃO PROVOU', 'HÁ SEMPRE ALGUÉM QUE NÃO PROVOU', 'HÁ SEMPRE ALGUÉM QUE NÃO PROVOU\nO GRANDE AMOR DO MEU SENHOR;\nPORÉM EU SEI, BEM CERTO ESTOU,\nQUE ELE ESTÁ SEMPRE AO MEU REDOR\nPRA ME GUIAR.\n\nCORO\nAO MEU REDOR DEUS SEMPRE ESTÁ,\nAO MEU REDOR, AO MEU REDOR, \nPRA ME GUIAR;\nCOM SEU AMOR TÃO PURO E BOM,\nELE ESTÁ SEMPRE \nAO MEU REDOR PRA ME GUIAR.\n\nPOSSO PERDER TODOS OS MEUS BENS\nE UM BOM AMIGO ME FALTAR,\nPODE MEU PAI ME ABANDONAR,\nQUE ELE ESTÁ SEMPRE AO MEU REDOR\nPRA ME GUIAR.\n\nCORO\nAO MEU REDOR DEUS SEMPRE ESTÁ,\nAO MEU REDOR, AO MEU REDOR, \nPRA ME GUIAR;\nCOM SEU AMOR TÃO PURO E BOM,\nELE ESTÁ SEMPRE \nAO MEU REDOR PRA ME GUIAR.\n\nNÃO SEI CONTAR O QUE SENTI\nQUANDO JESUS ME REDIMIU;\nDESDE ENTÃO EU DESCOBRI\nQUE ELE ESTARÁ AO MEU REDOR \nQUANDO EU PARTIR.\n\nCORO\nAO MEU REDOR DEUS SEMPRE ESTÁ,\nAO MEU REDOR, AO MEU REDOR, \nPRA ME GUIAR;\nCOM SEU AMOR TÃO PURO E BOM,\nELE ESTÁ SEMPRE \nAO MEU REDOR PRA ME GUIAR.', 'HÁ SEMPRE ALGUÉM QUE NÃO PROVOU\nO GRANDE AMOR DO MEU SENHOR;\nPORÉM EU SEI, BEM CERTO ESTOU,\nQUE ELE ESTÁ SEMPRE AO MEU REDOR\nPRA ME GUIAR.\n\n<coro>\nAO MEU REDOR DEUS SEMPRE ESTÁ,\nAO MEU REDOR, AO MEU REDOR, \nPRA ME GUIAR;\nCOM SEU AMOR TÃO PURO E BOM,\nELE ESTÁ SEMPRE \nAO MEU REDOR PRA ME GUIAR.\n\nPOSSO PERDER TODOS OS MEUS BENS\nE UM BOM AMIGO ME FALTAR,\nPODE MEU PAI ME ABANDONAR,\nQUE ELE ESTÁ SEMPRE AO MEU REDOR\nPRA ME GUIAR.\n\n<coro>\nAO MEU REDOR DEUS SEMPRE ESTÁ,\nAO MEU REDOR, AO MEU REDOR, \nPRA ME GUIAR;\nCOM SEU AMOR TÃO PURO E BOM,\nELE ESTÁ SEMPRE \nAO MEU REDOR PRA ME GUIAR.\n\nNÃO SEI CONTAR O QUE SENTI\nQUANDO JESUS ME REDIMIU;\nDESDE ENTÃO EU DESCOBRI\nQUE ELE ESTARÁ AO MEU REDOR \nQUANDO EU PARTIR.\n\n<coro>\nAO MEU REDOR DEUS SEMPRE ESTÁ,\nAO MEU REDOR, AO MEU REDOR, \nPRA ME GUIAR;\nCOM SEU AMOR TÃO PURO E BOM,\nELE ESTÁ SEMPRE \nAO MEU REDOR PRA ME GUIAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (139, 'NÃO SEI POR QUE DE DEUS O AMOR', 'NÃO SEI POR QUE DE DEUS O AMOR', 'NÃO SEI POR QUE DE DEUS O AMOR\nA MIM SE REVELOU,\nPORQUE, A MIM, O SALVADOR,\nPRA SI ME RESGATOU.\n\nCORO\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.\n\nIGNORO COMO O ESPÍRITO\nNOS CONVENCE DO MAL,\nREVELA A CRISTO, VERBO SEU,\nCONSOLADOR REAL.\n\nCORO\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.\n\nNÃO SEI O QUE DE MAL OU \nBEM É DESTINADO A MIM,\nSE MAUS OU ÁUREOS DIAS \nVÊM, ATÉ DA VIDA O FIM?\n\nCORO\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.\n\nE QUANDO VEM JESUS, NÃO SEI,\nSE BREVE OU TARDE VEM,\nMAS SEI QUE MEU SENHOR VIRÁ\nNA GLÓRIA QUE ELE TEM.\n\nCORO\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.', 'NÃO SEI POR QUE DE DEUS O AMOR\nA MIM SE REVELOU,\nPORQUE, A MIM, O SALVADOR,\nPRA SI ME RESGATOU.\n\n<coro>\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.\n\nIGNORO COMO O ESPÍRITO\nNOS CONVENCE DO MAL,\nREVELA A CRISTO, VERBO SEU,\nCONSOLADOR REAL.\n\n<coro>\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.\n\nNÃO SEI O QUE DE MAL OU \nBEM É DESTINADO A MIM,\nSE MAUS OU ÁUREOS DIAS \nVÊM, ATÉ DA VIDA O FIM?\n\n<coro>\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.\n\nE QUANDO VEM JESUS, NÃO SEI,\nSE BREVE OU TARDE VEM,\nMAS SEI QUE MEU SENHOR VIRÁ\nNA GLÓRIA QUE ELE TEM.\n\n<coro>\nMAS EU SEI EM QUEM TENHO CRIDO\nE ESTOU BEM CERTO QUE É PODEROSO\nPRA GUARDAR O MEU TESOURO\nATÉ O DIA FINAL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (140, 'AS MUITAS ÁGUAS', 'AS MUITAS ÁGUAS', 'AS MUITAS ÁGUAS NÃO \nPODEM APAGAR O AMOR,\nO AMOR COM QUE TE AMEI;\nNEM RIOS PROFUNDOS PODEM AFOGAR\nO AMOR COM QUE ME AMOU.\n\nCORO \nCOMO ENTÃO PODERIA ESQUECER\nESSE AMOR QUE DEU VIDA AO MEU SER?\n\nMEU AMOR POR TI NÃO PODE MUDAR,\nA TI ENTREGUEI TODO O MEU SER;\nHOJE VIVES DENTRO DO MEU CORAÇÃO,\nÉS MINHA VIDA, MINHA PORÇÃO.\n\nCORO \nCOMO ENTÃO PODERIA ESQUECER\nESSE AMOR QUE DEU VIDA AO MEU SER?\n\nFINAL: \nEM TUA PRESENÇA EU SOU TÃO FELIZ,\nTEU SACRIFÍCIO ME UNIU A TI;\nSEM O TEU AMOR O QUE SERIA EU?\nÉS MINHA VIDA, MEU JESUS,\nÉS MINHA VIDA, Ó MEU JESUS.', 'AS MUITAS ÁGUAS NÃO \nPODEM APAGAR O AMOR,\nO AMOR COM QUE TE AMEI;\nNEM RIOS PROFUNDOS PODEM AFOGAR\nO AMOR COM QUE ME AMOU.\n\n<coro>\nCOMO ENTÃO PODERIA ESQUECER\nESSE AMOR QUE DEU VIDA AO MEU SER?\n\nMEU AMOR POR TI NÃO PODE MUDAR,\nA TI ENTREGUEI TODO O MEU SER;\nHOJE VIVES DENTRO DO MEU CORAÇÃO,\nÉS MINHA VIDA, MINHA PORÇÃO.\n\n<coro>\nCOMO ENTÃO PODERIA ESQUECER\nESSE AMOR QUE DEU VIDA AO MEU SER?\n<final>EM TUA PRESENÇA EU SOU TÃO FELIZ,\nTEU SACRIFÍCIO ME UNIU A TI;\nSEM O TEU AMOR O QUE SERIA EU?\nÉS MINHA VIDA, MEU JESUS,\nÉS MINHA VIDA, Ó MEU JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (141, 'O AMOR DE DEUS POR NÓS', 'O AMOR DE DEUS POR NÓS', 'O AMOR DE DEUS POR NÓS\nÉ COMO O SOL QUE BRILHA EM SEU PODER;\nEM JESUS MOSTROU TODO \nO SEU AMOR REVELANDO \nASSIM O SEU QUERER.\n\nINSTRUMENTOS\n\nQUANDO DEUS TOCOU MEU SER,\nEU LHE ENTREGUEI TODO O MEU CORAÇÃO;\nSUA PAZ SENTI INUNDAR MEU SER\nE O SEU AMOR ME TRANSFORMAR.', 'O AMOR DE DEUS POR NÓS\nÉ COMO O SOL QUE BRILHA EM SEU PODER;\nEM JESUS MOSTROU TODO <bis>\nO SEU AMOR REVELANDO <bis>\nASSIM O SEU QUERER.<bis>\n<instrumentos>\n\n\nQUANDO DEUS TOCOU MEU SER,\nEU LHE ENTREGUEI TODO O MEU CORAÇÃO;\nSUA PAZ SENTI INUNDAR MEU SER<bis>\nE O SEU AMOR ME TRANSFORMAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (142, 'CRISTO, MEU MESTRE, SEMPRE HÁ DE AMAR-ME', 'CRISTO, MEU MESTRE, SEMPRE HÁ DE AMAR-ME', 'CRISTO, MEU MESTRE, SEMPRE HÁ DE AMAR-ME\nE DELE O MAL NÃO PODE AFASTAR-ME;\nDEU SUA VIDA PRA ME SALVAR\nE AGORA DELE SOU.\n\nCORO\nSOU DE JESUS, MEU MESTRE,\nCRISTO JESUS É MEU;\nNÃO SÓ NOS DIAS QUE SE VÃO,\nMAS, PARA SEMPRE, AMÉM.\n\nINSTRUMENTOS\n\nPERDIDO, AFEITO AO MAL, DEGRADADO,\nME CONCEDEU PERDÃO DO PECADO;\nNÃO ANDO TRISTE, JÁ SOU FELIZ\nE AGORA DELE SOU.\n\nCORO\nSOU DE JESUS, MEU MESTRE,\nCRISTO JESUS É MEU;\nNÃO SÓ NOS DIAS QUE SE VÃO,\nMAS, PARA SEMPRE, AMÉM.\n\nINSTRUMENTOS\n\nEU CANTO DE ALEGRIA DE SALVO,\nMEU CORAÇÃO JESUS DEIXOU ALVO,\nPOIS O SEU SANGUE ME PURIFICOU\nE AGORA DELE SOU.', 'CRISTO, MEU MESTRE, SEMPRE HÁ DE AMAR-ME\nE DELE O MAL NÃO PODE AFASTAR-ME;\nDEU SUA VIDA PRA ME SALVAR\nE AGORA DELE SOU.\n\n<coro>\nSOU DE JESUS, MEU MESTRE,\nCRISTO JESUS É MEU;\nNÃO SÓ NOS DIAS QUE SE VÃO,\nMAS, PARA SEMPRE, AMÉM.\n<instrumentos>\n\n\nPERDIDO, AFEITO AO MAL, DEGRADADO,\nME CONCEDEU PERDÃO DO PECADO;\nNÃO ANDO TRISTE, JÁ SOU FELIZ\nE AGORA DELE SOU.\n\n<coro>\nSOU DE JESUS, MEU MESTRE,\nCRISTO JESUS É MEU;\nNÃO SÓ NOS DIAS QUE SE VÃO,\nMAS, PARA SEMPRE, AMÉM.\n<instrumentos>\n\n\nEU CANTO DE ALEGRIA DE SALVO,\nMEU CORAÇÃO JESUS DEIXOU ALVO,\nPOIS O SEU SANGUE ME PURIFICOU\nE AGORA DELE SOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (143, 'SE NÃO FOSSE O AMOR', 'SE NÃO FOSSE O AMOR', 'SE NÃO FOSSE O AMOR QUE DEUS POR MIM REVELOU,\nEU NÃO ESTARIA AQUI; ELE INCLINOU SEUS OLHOS \nE PÔDE CONTEMPLAR TODO O SOFRIMENTO QUE PASSEI.\nSE NÃO FOSSE O AMOR QUE DEUS POR MIM MOSTROU, JAMAIS CONSEGUIRIA ENTENDER\nO GRANDE SACRIFÍCIO DE JESUS POR MIM E POR TI.\n\nA PAZ QUE TENHO EM JESUS\nNÃO SE PODE COMPARAR\nA TESOUROS DESTA VIDA AQUI,\nÀ PAZ QUE FOI COMPRADA\nCOM SANGUE E COM DOR;\nE HOJE É DADA A MIM E A TI,\nA MIM E A TI POR CRISTO JESUS.', 'SE NÃO FOSSE O AMOR QUE DEUS POR MIM REVELOU,<bis>\nEU NÃO ESTARIA AQUI; ELE INCLINOU SEUS OLHOS <bis>\nE PÔDE CONTEMPLAR TODO O SOFRIMENTO QUE PASSEI.<bis>\nSE NÃO FOSSE O AMOR QUE DEUS POR MIM MOSTROU, JAMAIS CONSEGUIRIA ENTENDER<bis>\nO GRANDE SACRIFÍCIO DE JESUS POR MIM E POR TI.<bis>\n\nA PAZ QUE TENHO EM JESUS<bis>\nNÃO SE PODE COMPARAR<bis>\nA TESOUROS DESTA VIDA AQUI,<bis>\nÀ PAZ QUE FOI COMPRADA<bis>\nCOM SANGUE E COM DOR;<bis>\nE HOJE É DADA A MIM E A TI,<bis>\nA MIM E A TI POR CRISTO JESUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (144, 'JESUS, AGORA EU BEM SEI', 'JESUS, AGORA EU BEM SEI', 'JESUS, AGORA EU BEM SEI\nQUÃO GRANDE É TEU AMOR,\nPOIS SALVAÇÃO EM TI ACHEI,\nA CRISTO DOU LOUVOR.\n\nCORO\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.\n\nDESCANSO NUNCA CONHECI,\nINÚTIL SEMPRE SOU;\nMAS CRISTO SE LEMBROU DE MIM,\nSUA GRAÇA ME CHAMOU.\n\nCORO\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.\n\nCOMIGO, CRENTES, EXALTAI\nO GRANDE SALVADOR,\nPOIS TUDO CRISTO ME SUPRIU\nEMBORA PECADOR.\n\nCORO\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.\n\nLOUVOR, LOUVOR A TI DAREI,\nÓ CRISTO, MEU SENHOR!\nPROFETA, SACERDOTE, REI,\nDO MUNDO, O SALVADOR.\n\nCORO\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.', 'JESUS, AGORA EU BEM SEI\nQUÃO GRANDE É TEU AMOR,\nPOIS SALVAÇÃO EM TI ACHEI,\nA CRISTO DOU LOUVOR.<coro>\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.\n\nDESCANSO NUNCA CONHECI,\nINÚTIL SEMPRE SOU;\nMAS CRISTO SE LEMBROU DE MIM,\nSUA GRAÇA ME CHAMOU.<coro>\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.\n\nCOMIGO, CRENTES, EXALTAI\nO GRANDE SALVADOR,\nPOIS TUDO CRISTO ME SUPRIU\nEMBORA PECADOR.<coro>\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.\n\nLOUVOR, LOUVOR A TI DAREI,\nÓ CRISTO, MEU SENHOR!\nPROFETA, SACERDOTE, REI,\nDO MUNDO, O SALVADOR.<coro>\nÉ CRISTO, SÓ, MEU SALVADOR,\nPOR ELE EU TENHO PAZ;\nJESUS, A TI LOUVOR DAREI,\nPOIS TUDO TU ME DÁS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (145, 'É O AMOR DE DEUS', 'É O AMOR DE DEUS', 'É O AMOR DE DEUS A CAUSA \nDE NÃO SERMOS CONSUMIDOS\nPOIS AINDA QUE FAÇAMOS PRA MERECER,\nNUNCA MERECEMOS ESSE AMOR\nQUE É LINDO E PURO, \nÉ O AMOR QUE DEUS \nTE OFERECE AGORA.\n\nÉ O AMOR DE DEUS QUE TE LIVRA\nDE TODA CILADA E INVESTIDA,\nESTÁ SEMPRE AO NOSSO LADO\nPRA CUIDAR DE NÓS EMBORA \nNÃO MEREÇAMOS ESSE AMOR.\nINSTRUMENTOS\n\nELE NOS GUARDA EM TODOS \nOS MOMENTOS DE NOSSAS VIDAS\nE ÀS VEZES SOMOS INGRATOS,\nMAS ELE NOS AMA \nE É POR CAUSA DESSE AMOR \nQUE NÃO SOMOS CONSUMIDOS.', 'É O AMOR DE DEUS A CAUSA <bis>\nDE NÃO SERMOS CONSUMIDOS<bis>\nPOIS AINDA QUE FAÇAMOS PRA MERECER,\nNUNCA MERECEMOS ESSE AMOR\nQUE É LINDO E PURO, \nÉ O AMOR QUE DEUS \nTE OFERECE AGORA.\n\nÉ O AMOR DE DEUS QUE TE LIVRA\nDE TODA CILADA E INVESTIDA,\nESTÁ SEMPRE AO NOSSO LADO\nPRA CUIDAR DE NÓS EMBORA \nNÃO MEREÇAMOS ESSE AMOR.\n<instrumentos>\n\n\nELE NOS GUARDA EM TODOS \nOS MOMENTOS DE NOSSAS VIDAS\nE ÀS VEZES SOMOS INGRATOS,\nMAS ELE NOS AMA <bis>\nE É POR CAUSA DESSE AMOR <bis>\nQUE NÃO SOMOS CONSUMIDOS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (146, 'EXISTE UM ALGUÉM QUE CUIDA DE MIM', 'EXISTE UM ALGUÉM QUE CUIDA DE MIM', 'EXISTE UM ALGUÉM QUE CUIDA DE MIM, \nTAMBÉM DE VOCÊ; SEU NOME É DEUS FORTE, \nREAL CONSELHEIRO, ELE É O PODER;\nELE É FIEL, EMANUEL, UM BRILHO \nDE LUZ, TRANSMITE A PAZ, \nTAMBÉM SATISFAZ, SEU NOME É JESUS.\n\nJESUS É A VIDA,\nA FLOR MAIS QUERIDA;\nNA HORA DA DOR,\nJESUS É AMOR,\nA FONTE DA VIDA.\n\nEXISTE UM ALGUÉM QUE CUIDA DE \nMIM, TAMBÉM DE VOCÊ;\nSEU NOME É DEUS FORTE, \nREAL CONSELHEIRO, ELE É O PODER;\nELE É FIEL, EMANUEL, UM BRILHO \nDE LUZ, TRANSMITE A PAZ, \nTAMBÉM SATISFAZ, \nSEU NOME É JESUS.\n\nJESUS É A VIDA,\nA FLOR MAIS QUERIDA;\nNA HORA DA DOR,\nJESUS É AMOR,\nA FONTE DA VIDA.\n\nFINAL: NA HORA DA DOR,\n JESUS É AMOR,\n A FONTE DA VIDA.', 'EXISTE UM ALGUÉM QUE CUIDA DE MIM, \nTAMBÉM DE VOCÊ; SEU NOME É DEUS FORTE, \nREAL CONSELHEIRO, ELE É O PODER;\nELE É FIEL, EMANUEL, UM BRILHO \nDE LUZ, TRANSMITE A PAZ, \nTAMBÉM SATISFAZ, SEU NOME É JESUS.\n\nJESUS É A VIDA,<bis>\nA FLOR MAIS QUERIDA;<bis>\nNA HORA DA DOR,<bis>\nJESUS É AMOR,<bis>\nA FONTE DA VIDA.<bis>\n\nEXISTE UM ALGUÉM QUE CUIDA DE \nMIM, TAMBÉM DE VOCÊ;\nSEU NOME É DEUS FORTE, \nREAL CONSELHEIRO, ELE É O PODER;\nELE É FIEL, EMANUEL, UM BRILHO \nDE LUZ, TRANSMITE A PAZ, \nTAMBÉM SATISFAZ, \nSEU NOME É JESUS.\n\nJESUS É A VIDA,<bis>\nA FLOR MAIS QUERIDA;<bis>\nNA HORA DA DOR,<bis>\nJESUS É AMOR,<bis>\nA FONTE DA VIDA.<bis>\n<final>NA HORA DA DOR,\n JESUS É AMOR,\n A FONTE DA VIDA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (147, 'CRISTO É TUDO PARA MIM', 'CRISTO É TUDO PARA MIM', 'CORO\nCRISTO É TUDO PARA MIM,\nAMOR E PAZ, PERDÃO SEM FIM;\nSEM ELE A VIDA É TÃO RUIM,\nCRISTO JESUS É TUDO PARA MIM.\n\nCEDINHO SINTO O SEU AMOR,\nDE NOITE SINTO TAMBÉM;\nCOM CRISTO ANDO SEM TEMOR,\nAS TREVAS NUNCA ME VÊM.\n\nCORO\nCRISTO É TUDO PARA MIM,\nAMOR E PAZ, PERDÃO SEM FIM;\nSEM ELE A VIDA É TÃO RUIM,\nCRISTO JESUS É TUDO PARA MIM.\n\nO MUNDO NÃO ME ATRAI,\nJESUS, TEU SER, JÁ ME ATRAIU;\nSEGURANÇA TENHO NO PAI,\nVIDA NESTE MUNDO VIL.\n\nCORO\nCRISTO É TUDO PARA MIM,\nAMOR E PAZ, PERDÃO SEM FIM;\nSEM ELE A VIDA É TÃO RUIM,\nCRISTO JESUS É TUDO PARA MIM.', '<coro>\nCRISTO É TUDO PARA MIM,\nAMOR E PAZ, PERDÃO SEM FIM;\nSEM ELE A VIDA É TÃO RUIM,\nCRISTO JESUS É TUDO PARA MIM.\n\nCEDINHO SINTO O SEU AMOR,\nDE NOITE SINTO TAMBÉM;\nCOM CRISTO ANDO SEM TEMOR,\nAS TREVAS NUNCA ME VÊM.\n\n<coro>\nCRISTO É TUDO PARA MIM,\nAMOR E PAZ, PERDÃO SEM FIM;\nSEM ELE A VIDA É TÃO RUIM,\nCRISTO JESUS É TUDO PARA MIM.\n\nO MUNDO NÃO ME ATRAI,\nJESUS, TEU SER, JÁ ME ATRAIU;\nSEGURANÇA TENHO NO PAI,\nVIDA NESTE MUNDO VIL.\n\n<coro>\nCRISTO É TUDO PARA MIM,\nAMOR E PAZ, PERDÃO SEM FIM;\nSEM ELE A VIDA É TÃO RUIM,\nCRISTO JESUS É TUDO PARA MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (148, 'UMA CERTA VEZ, JESUS CRISTO', 'UMA CERTA VEZ, JESUS CRISTO', 'UMA CERTA VEZ, JESUS CRISTO, \nPARA UMA GRANDE MULTIDÃO \nNA PRAIA DA GALILÉIA, \nFEZ UMA MULTIPLICAÇÃO:\nCOM DOIS PEIXES E CINCO PÃES,\nTODOS JULGAVAM QUE NÃO;\nA MAIS DE CINCO MIL PESSOAS \nDEU COMIDA BOA, \nDEU PEIXE E DEU PÃO.\n\nCORO\nESTE QUE É DEUS, DEUS PODEROSO,\nDO CELESTE LAR; ESTE QUE É DEUS, \nQUE VENDO O POVO TODO A PECAR MANDOU SEU FILHO PARA QUE O MUNDO VIESSE SALVAR, ESTE DEUS MARAVILHOSO\nDÁ PAZ E DÁ GOZO A QUEM O ACEITAR.\n\nJESUS ORDENOU AO POVO \nQUE SE ASSENTASSE NO CHÃO,\nE RECEBENDO UMA CESTA \nCOM DOIS PEIXES E CINCO PÃES, \nDEU GRAÇAS AO PAI DIVINO;\nDISSE: ''TENDE COMPAIXÃO''.\nOS DISCÍPULOS, NAQUELE MOMENTO,\nTIVERAM ALIMENTO PARA A MULTIDÃO.\n\nCORO\nESTE QUE É DEUS, DEUS PODEROSO,\nDO CELESTE LAR; ESTE QUE É DEUS, \nQUE VENDO O POVO TODO A PECAR MANDOU SEU FILHO PARA QUE O MUNDO VIESSE SALVAR, ESTE DEUS MARAVILHOSO\nDÁ PAZ E DÁ GOZO A QUEM O ACEITAR.\n\nPARA QUE NADA PERDESSE,\nMANDOU AS SOBRAS JUNTAR:\nDOZE CESTOS DE PEDAÇOS\nFOI O QUE VEIO A SOBRAR;\nJESUS AINDA É O MESMO,\nOH! QUE ALEGRIA SEM PAR;\nESTE JESUS PODEROSO,\nLÁ DO CÉU DE GOZO\nESTÁ A NOS CONTEMPLAR.\n\nCORO\nESTE QUE É DEUS, DEUS PODEROSO,\nDO CELESTE LAR; ESTE QUE É DEUS, \nQUE VENDO O POVO TODO A PECAR MANDOU SEU FILHO PARA QUE O MUNDO VIESSE SALVAR, ESTE DEUS MARAVILHOSO\nDÁ PAZ E DÁ GOZO A QUEM O ACEITAR.', 'UMA CERTA VEZ, JESUS CRISTO, \nPARA UMA GRANDE MULTIDÃO \nNA PRAIA DA GALILÉIA, \nFEZ UMA MULTIPLICAÇÃO:\nCOM DOIS PEIXES E CINCO PÃES,\nTODOS JULGAVAM QUE NÃO;\nA MAIS DE CINCO MIL PESSOAS \nDEU COMIDA BOA, \nDEU PEIXE E DEU PÃO.\n\n<coro>\nESTE QUE É DEUS, DEUS PODEROSO,\nDO CELESTE LAR; ESTE QUE É DEUS, \nQUE VENDO O POVO TODO A PECAR MANDOU SEU FILHO PARA QUE O MUNDO VIESSE SALVAR, ESTE DEUS MARAVILHOSO\nDÁ PAZ E DÁ GOZO A QUEM O ACEITAR.\n\nJESUS ORDENOU AO POVO \nQUE SE ASSENTASSE NO CHÃO,\nE RECEBENDO UMA CESTA \nCOM DOIS PEIXES E CINCO PÃES, \nDEU GRAÇAS AO PAI DIVINO;\nDISSE: ''TENDE COMPAIXÃO''.\nOS DISCÍPULOS, NAQUELE MOMENTO,\nTIVERAM ALIMENTO PARA A MULTIDÃO.\n\n<coro>\nESTE QUE É DEUS, DEUS PODEROSO,\nDO CELESTE LAR; ESTE QUE É DEUS, \nQUE VENDO O POVO TODO A PECAR MANDOU SEU FILHO PARA QUE O MUNDO VIESSE SALVAR, ESTE DEUS MARAVILHOSO\nDÁ PAZ E DÁ GOZO A QUEM O ACEITAR.\n\nPARA QUE NADA PERDESSE,\nMANDOU AS SOBRAS JUNTAR:\nDOZE CESTOS DE PEDAÇOS\nFOI O QUE VEIO A SOBRAR;\nJESUS AINDA É O MESMO,\nOH! QUE ALEGRIA SEM PAR;\nESTE JESUS PODEROSO,\nLÁ DO CÉU DE GOZO\nESTÁ A NOS CONTEMPLAR.\n\n<coro>\nESTE QUE É DEUS, DEUS PODEROSO,\nDO CELESTE LAR; ESTE QUE É DEUS, \nQUE VENDO O POVO TODO A PECAR MANDOU SEU FILHO PARA QUE O MUNDO VIESSE SALVAR, ESTE DEUS MARAVILHOSO\nDÁ PAZ E DÁ GOZO A QUEM O ACEITAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (149, 'JESUS FEZ A PROMESSA', 'JESUS FEZ A PROMESSA', 'JESUS FEZ A PROMESSA,\nCONOSCO ESTARIA ATÉ O FIM;\nE OS SINAIS SEGUIRIAM A TODOS \nQUE CRESSEM, ELE FALOU ASSIM.\nCAIAM OS MONTES E OS HOMENS,\nMAS SUA PROMESSA ESTÁ DE PÉ,\nELE NOS TEM PROVADO \nQUE NÃO MUDOU, \nPODEROSO ELE É!\n\nCORO\nPODEROSO ELE É\nE EM NADA MUDOU;\nNELE ESTÁ NOSSA FÉ,\nPODEROSO ELE É!\n\nELE DEU VISTA AOS CEGOS \nE OS OPRIMIDOS ELE LIBERTOU;\nCINCO PÃES E DOIS PEIXES, A MAIS \nDE DOIS MIL ELE ALIMENTOU.\nOPEROU NA JUDÉIA, \nEM CAFARNAUM E EM NAZARÉ;\nCONTINUA OPERANDO AQUI EM \nNOSSO MEIO, PODEROSO ELE É!\n\nCORO (2X)\nPODEROSO ELE É\nE EM NADA MUDOU;\nNELE ESTÁ NOSSA FÉ,\nPODEROSO ELE É!', 'JESUS FEZ A PROMESSA,\nCONOSCO ESTARIA ATÉ O FIM;\nE OS SINAIS SEGUIRIAM A TODOS \nQUE CRESSEM, ELE FALOU ASSIM.\nCAIAM OS MONTES E OS HOMENS,\nMAS SUA PROMESSA ESTÁ DE PÉ,\nELE NOS TEM PROVADO \nQUE NÃO MUDOU, \nPODEROSO ELE É!\n\n<coro>\nPODEROSO ELE É\nE EM NADA MUDOU;\nNELE ESTÁ NOSSA FÉ,\nPODEROSO ELE É!\n\nELE DEU VISTA AOS CEGOS \nE OS OPRIMIDOS ELE LIBERTOU;\nCINCO PÃES E DOIS PEIXES, A MAIS \nDE DOIS MIL ELE ALIMENTOU.\nOPEROU NA JUDÉIA, \nEM CAFARNAUM E EM NAZARÉ;\nCONTINUA OPERANDO AQUI EM \nNOSSO MEIO, PODEROSO ELE É!\n\n<coro tipo=''2X''>\nPODEROSO ELE É\nE EM NADA MUDOU;\nNELE ESTÁ NOSSA FÉ,\nPODEROSO ELE É!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (150, 'VOU CONTAR-VOS O QUE PENSO DO MEU MESTRE', 'VOU CONTAR-VOS O QUE PENSO DO MEU MESTRE', 'VOU CONTAR-VOS O QUE PENSO DO MEU MESTRE,\nCOMO DELE RECEBI A LUZ E A PAZ;\nELE MUDOU-ME, EU BEM SEI, COMPLETAMENTE, \nCOMO CRISTO NENHUM OUTRO SATISFAZ.\n\nCORO\nSEMPRE CUIDARÁ DE MIM, MEU MESTRE,\nCOM DESVELO E COMPAIXÃO SEM FIM;\nNENHUM OUTRO TIRA A CULPA DO PECADO. \nOH! COMO ELE AMA A MIM!\n\nCOM A VIDA TODA CHEIA DE PECADO,\nNA MISÉRIA E COM DOR NO CORAÇÃO,\nELE ERGUEU-ME COM BRAÇOS FORTES DE TERNURA, \nDEU-ME GOZO, DEU-ME PAZ, CONSOLAÇÃO.\n\nCORO\nSEMPRE CUIDARÁ DE MIM, MEU MESTRE,\nCOM DESVELO E COMPAIXÃO SEM FIM;\nNENHUM OUTRO TIRA A CULPA DO PECADO. \nOH! COMO ELE AMA A MIM!\n\nCADA DIA ELE VEM COM SEGURANÇA,\nMAIS E MAIS A REVELAR O SEU AMOR;\nCOMO ANELO COMPREENDER COMPLETAMENTE \nESTE AMOR TÃO DIVINAL, RESTAURADOR!\n\nCORO\nSEMPRE CUIDARÁ DE MIM, MEU MESTRE,\nCOM DESVELO E COMPAIXÃO SEM FIM;\nNENHUM OUTRO TIRA A CULPA DO PECADO. \nOH! COMO ELE AMA A MIM!\n\nMEU MAIOR DESEJO AGORA É AMÁ-LO,\nPROCLAMAR O QUE ELE FEZ PRA ME SALVAR;\nE CANTANDO ESSE AMOR INIGUALÁVEL,\nESPERO EM DEUS A MINHA VIDA TERMINAR.', 'VOU CONTAR-VOS O QUE PENSO DO MEU MESTRE,\nCOMO DELE RECEBI A LUZ E A PAZ;\nELE MUDOU-ME, EU BEM SEI, COMPLETAMENTE, \nCOMO CRISTO NENHUM OUTRO SATISFAZ.\n\n<coro>\nSEMPRE CUIDARÁ DE MIM, MEU MESTRE,\nCOM DESVELO E COMPAIXÃO SEM FIM;\nNENHUM OUTRO TIRA A CULPA DO PECADO. \nOH! COMO ELE AMA A MIM!\n\nCOM A VIDA TODA CHEIA DE PECADO,\nNA MISÉRIA E COM DOR NO CORAÇÃO,\nELE ERGUEU-ME COM BRAÇOS FORTES DE TERNURA, \nDEU-ME GOZO, DEU-ME PAZ, CONSOLAÇÃO.\n\n<coro>\nSEMPRE CUIDARÁ DE MIM, MEU MESTRE,\nCOM DESVELO E COMPAIXÃO SEM FIM;\nNENHUM OUTRO TIRA A CULPA DO PECADO. \nOH! COMO ELE AMA A MIM!\n\nCADA DIA ELE VEM COM SEGURANÇA,\nMAIS E MAIS A REVELAR O SEU AMOR;\nCOMO ANELO COMPREENDER COMPLETAMENTE \nESTE AMOR TÃO DIVINAL, RESTAURADOR!\n\n<coro>\nSEMPRE CUIDARÁ DE MIM, MEU MESTRE,\nCOM DESVELO E COMPAIXÃO SEM FIM;\nNENHUM OUTRO TIRA A CULPA DO PECADO. \nOH! COMO ELE AMA A MIM!\n\nMEU MAIOR DESEJO AGORA É AMÁ-LO,\nPROCLAMAR O QUE ELE FEZ PRA ME SALVAR;\nE CANTANDO ESSE AMOR INIGUALÁVEL,\nESPERO EM DEUS A MINHA VIDA TERMINAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (151, 'CRISTO JESUS É O MEU BOM SALVADOR', 'CRISTO JESUS É O MEU BOM SALVADOR', 'CRISTO JESUS É O MEU BOM SALVADOR;\nDESEJO AMÁ-LO MAIS,\nTODOS OS DIAS É MEU SENHOR.\n\nCORO\nA CRISTO EU AMO, OH! QUANTO \nEU AMO, POIS POR MIM MORREU;\nCOM O SEU SANGUE, JESUS SALVOU-ME,\nEM GRATIDÃO SOU SEU.\n\nINSTRUMENTOS\n\nBEM CEDO AO CÉU ELE ME LEVARÁ,\nDESEJO AMÁ-LO MAIS,\nETERNAMENTE ME GUIARÁ.', 'CRISTO JESUS É O MEU BOM SALVADOR;\nDESEJO AMÁ-LO MAIS,\nTODOS OS DIAS É MEU SENHOR.\n\n<coro>\nA CRISTO EU AMO, OH! QUANTO \nEU AMO, POIS POR MIM MORREU;\nCOM O SEU SANGUE, JESUS SALVOU-ME,\nEM GRATIDÃO SOU SEU.\n<instrumentos>\nBEM CEDO AO CÉU ELE ME LEVARÁ,\nDESEJO AMÁ-LO MAIS,\nETERNAMENTE ME GUIARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (152, 'MAIS PERTO DE JESUS', 'MAIS PERTO DE JESUS', 'MAIS PERTO DE JESUS PROCURO SEMPRE EU CHEGAR, \nMAIS BELO DO QUE O OURO DO SOL NADO É A TI MIRAR;\nEM PENSAMENTOS, SONHOS, TANTA GLÓRIA NUNCA VI!\nPOIS ELE É MAIS BELO DO QUE EU JAMAIS PREVI!\n\nCORO\nNÃO POSSO EXPLICAR QUÃO MEIGO \nÉS JESUS; MAS FACE A FACE NO TEU LAR,\nEU TE VEREI, JESUS!\n\nA ESTRELA RESPLENDENTE, DA MANHÃ, \nÉ MINHA LUZ, O LÍRIO DOS VALES \nÉ O BOM SENHOR JESUS;\nSUAVE E DOCE É O CHEIRO \nQUE SÓ VEM DE SI, \nPOIS ELE É MAIS BELO \nDO QUE EU JAMAIS PREVI!\n\nCORO\nNÃO POSSO EXPLICAR QUÃO MEIGO \nÉS JESUS; MAS FACE A FACE NO TEU LAR,\nEU TE VEREI, JESUS!\n\nSE MÁGOAS VÊM ME PERTURBAR, \nO BÁLSAMO ELE TEM, \nME TOMA NOS SEUS BRAÇOS \nE ASSIM DESCANSO BEM;\nNA CRUZ LEVOU JESUS \nO MEU PECADO SOBRE SI, \nPOIS ELE É MAIS BELO \nDO QUE EU JAMAIS PREVI!\n\nCORO\nNÃO POSSO EXPLICAR QUÃO MEIGO \nÉS JESUS; MAS FACE A FACE NO TEU LAR,\nEU TE VEREI, JESUS!', 'MAIS PERTO DE JESUS PROCURO SEMPRE EU CHEGAR, \nMAIS BELO DO QUE O OURO DO SOL NADO É A TI MIRAR;\nEM PENSAMENTOS, SONHOS, TANTA GLÓRIA NUNCA VI!\nPOIS ELE É MAIS BELO DO QUE EU JAMAIS PREVI!\n\n<coro>\nNÃO POSSO EXPLICAR QUÃO MEIGO \nÉS JESUS; MAS FACE A FACE NO TEU LAR,\nEU TE VEREI, JESUS!\n\nA ESTRELA RESPLENDENTE, DA MANHÃ, \nÉ MINHA LUZ, O LÍRIO DOS VALES \nÉ O BOM SENHOR JESUS;\nSUAVE E DOCE É O CHEIRO \nQUE SÓ VEM DE SI, \nPOIS ELE É MAIS BELO \nDO QUE EU JAMAIS PREVI!\n\n<coro>\nNÃO POSSO EXPLICAR QUÃO MEIGO \nÉS JESUS; MAS FACE A FACE NO TEU LAR,\nEU TE VEREI, JESUS!\n\nSE MÁGOAS VÊM ME PERTURBAR, \nO BÁLSAMO ELE TEM, \nME TOMA NOS SEUS BRAÇOS \nE ASSIM DESCANSO BEM;\nNA CRUZ LEVOU JESUS \nO MEU PECADO SOBRE SI, \nPOIS ELE É MAIS BELO \nDO QUE EU JAMAIS PREVI!\n\n<coro>\nNÃO POSSO EXPLICAR QUÃO MEIGO \nÉS JESUS; MAS FACE A FACE NO TEU LAR,\nEU TE VEREI, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (153, 'CRISTO, NOME MAIS ALTO', 'CRISTO, NOME MAIS ALTO', 'CRISTO, NOME MAIS ALTO,\nSALVADOR NOSSO, GLORIOSO SENHOR;\nEMANUEL É DEUS CONOSCO,\nNOME DE VIDA, DIVINO SENHOR.\n\nEMANUEL, EMANUEL,\nSEU NOME É EMANUEL!\nELE ME AMOU,\nME TRANSFORMOU\nE VIVE EM MIM, EMANUEL.', 'CRISTO, NOME MAIS ALTO,\nSALVADOR NOSSO, GLORIOSO SENHOR;\nEMANUEL É DEUS CONOSCO,\nNOME DE VIDA, DIVINO SENHOR.\n\nEMANUEL, EMANUEL,<bis>\nSEU NOME É EMANUEL!<bis>\nELE ME AMOU,<bis>\nME TRANSFORMOU<bis>\nE VIVE EM MIM, EMANUEL.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (154, 'Ó TU QUE HABITAS ENTRE OS QUERUBINS', 'Ó TU QUE HABITAS ENTRE OS QUERUBINS', 'Ó TU QUE HABITAS ENTRE OS QUERUBINS,\nRESPLANDECE TUA LUZ EM MIM;\nÓ DEUS EXCELSO, ETERNO CRIADOR,\nVEM TU, MEU DEUS, ME ENCHER DE AMOR.\n\nCORO\nÓ DEUS DE PAZ, Ó DEUS DE AMOR,\n(Ó DEUS DE AMOR) SERVAS\nÉS TU MEU DEUS, MEU SALVADOR;\nA MINHA VIDA ENTREGO A TI,\n(ENTREGO A TI) SERVAS\nDEIXA O ESPÍRITO EM MIM FLUIR.\n\nÓ TU QUE HABITAS NO MAIS ALTO CÉU,\nNO CALVÁRIO TU RASGASTE O VÉU\nDANDO-ME PAZ E COMUNHÃO,\nA TI ENTREGO MEU CORAÇÃO.\n\nCORO\nÓ DEUS DE PAZ, Ó DEUS DE AMOR,\n(Ó DEUS DE AMOR) SERVAS\nÉS TU MEU DEUS, MEU SALVADOR;\nA MINHA VIDA ENTREGO A TI,\n(ENTREGO A TI) SERVAS\nDEIXA O ESPÍRITO EM MIM FLUIR.\n\nÓ DEUS ETERNO, COMO EU TE AMO,\nPOIS TU MUDASTE A MINHA SORTE,\nPOR ISSO EU DIGO QUE ÉS SOBERANO\nPOIS ME AJUDASTE A VENCER A MORTE.\n\nCORO\nÓ DEUS DE PAZ, Ó DEUS DE AMOR,\n(Ó DEUS DE AMOR) SERVAS\nÉS TU MEU DEUS, MEU SALVADOR;\nA MINHA VIDA ENTREGO A TI,\n(ENTREGO A TI) SERVAS\nDEIXA O ESPÍRITO EM MIM FLUIR.', 'Ó TU QUE HABITAS ENTRE OS QUERUBINS,\nRESPLANDECE TUA LUZ EM MIM;\nÓ DEUS EXCELSO, ETERNO CRIADOR,\nVEM TU, MEU DEUS, ME ENCHER DE AMOR.\n\n<coro>\nÓ DEUS DE PAZ, Ó DEUS DE AMOR,\n(Ó DEUS DE AMOR) <m>\nÉS TU MEU DEUS, MEU SALVADOR;\nA MINHA VIDA ENTREGO A TI,\n(ENTREGO A TI) <m>\nDEIXA O ESPÍRITO EM MIM FLUIR.\n\nÓ TU QUE HABITAS NO MAIS ALTO CÉU,\nNO CALVÁRIO TU RASGASTE O VÉU\nDANDO-ME PAZ E COMUNHÃO,\nA TI ENTREGO MEU CORAÇÃO.\n\n<coro>\nÓ DEUS DE PAZ, Ó DEUS DE AMOR,\n(Ó DEUS DE AMOR) <m>\nÉS TU MEU DEUS, MEU SALVADOR;\nA MINHA VIDA ENTREGO A TI,\n(ENTREGO A TI) <m>\nDEIXA O ESPÍRITO EM MIM FLUIR.\n\nÓ DEUS ETERNO, COMO EU TE AMO,\nPOIS TU MUDASTE A MINHA SORTE,\nPOR ISSO EU DIGO QUE ÉS SOBERANO\nPOIS ME AJUDASTE A VENCER A MORTE.\n\n<coro>\nÓ DEUS DE PAZ, Ó DEUS DE AMOR,\n(Ó DEUS DE AMOR) <m>\nÉS TU MEU DEUS, MEU SALVADOR;\nA MINHA VIDA ENTREGO A TI,\n(ENTREGO A TI) <m>\nDEIXA O ESPÍRITO EM MIM FLUIR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (155, 'HÁ UM SER QUE VIVE EM MIM', 'HÁ UM SER QUE VIVE EM MIM', 'HÁ UM SER QUE VIVE EM MIM\nE SEMPRE ESTÁ COMIGO, SIM,\nPROPORCIONANDO PAZ E AMOR,\nALIVIANDO TODA A MINHA DOR.\n\nUM DIA MORREU PARA ME SALVAR,\nRESSUSCITOU E VAI VOLTAR,\nUM DIA ENTÃO VAI ME LEVAR\nPARA COM ELE ETERNAMENTE MORAR.\n\nO NOME DELE É SIMPLES\nE POR ISSO É SUBLIME,\nÉ O FILHO DE DEUS,\nELE É JESUS, ELE É JESUS (BIS)', 'HÁ UM SER QUE VIVE EM MIM\nE SEMPRE ESTÁ COMIGO, SIM,\nPROPORCIONANDO PAZ E AMOR,\nALIVIANDO TODA A MINHA DOR.\n\nUM DIA MORREU PARA ME SALVAR,\nRESSUSCITOU E VAI VOLTAR,\nUM DIA ENTÃO VAI ME LEVAR\nPARA COM ELE ETERNAMENTE MORAR.\n\nO NOME DELE É SIMPLES\nE POR ISSO É SUBLIME,\nÉ O FILHO DE DEUS,\nELE É JESUS, ELE É JESUS <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (156, 'TOTALMENTE DESEJÁVEL É MEU AMADO', 'TOTALMENTE DESEJÁVEL É MEU AMADO', 'TOTALMENTE DESEJÁVEL É O MEU AMADO,\nPRECIOSO PARA MIM ELE É;\nO SEU FALAR É MUITÍSSIMO SUAVE,\nASSIM ELE É, JESUS, O AMADO SALVADOR.\n\nTODO O SEU SER É DELEITÁVEL \nÀ MINH''ALMA, DELE QUERO \nSEMPRE MAIS CONHECER;\nNÃO HÁ PRAZER MAIS REAL\nQUE SUA PRESENÇA,\nTOTALMENTE DESEJÁVEL É JESUS.', 'TOTALMENTE DESEJÁVEL É O MEU AMADO,\nPRECIOSO PARA MIM ELE É;\nO SEU FALAR É MUITÍSSIMO SUAVE,\nASSIM ELE É, JESUS, O AMADO SALVADOR.\n\nTODO O SEU SER É DELEITÁVEL <bis>\nÀ MINH''ALMA, DELE QUERO <bis>\nSEMPRE MAIS CONHECER;<bis>\nNÃO HÁ PRAZER MAIS REAL<bis>\nQUE SUA PRESENÇA,<bis>\nTOTALMENTE DESEJÁVEL É JESUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (157, 'CRISTO É A ROSA MAIS BELA', 'CRISTO É A ROSA MAIS BELA', 'CRISTO É A ROSA MAIS BELA,\nO MAIS PURO LÍRIO DO VALE,\nCRISTO É A BRILHANTE ESTRELA\nQUE ANUNCIA A LUZ DA MANHÃ.\n\nCRISTO É A ROCHA FERIDA\nBROTANDO ÁGUAS DE SALVAÇÃO,\nCRISTO É A FONTE DA VIDA,\nDANDO A PAZ, A CURA E O PERDÃO.\n\nCRISTO É SUAVE ALEGRIA,\nDOCE AMOR ENCHENDO O MEU SER;\nCRISTO É O AMADO QUE UM DIA\nVEM NAS ASAS DO AMANHECER.', 'CRISTO É A ROSA MAIS BELA,\nO MAIS PURO LÍRIO DO VALE,\nCRISTO É A BRILHANTE ESTRELA\nQUE ANUNCIA A LUZ DA MANHÃ.\n\nCRISTO É A ROCHA FERIDA\nBROTANDO ÁGUAS DE SALVAÇÃO,\nCRISTO É A FONTE DA VIDA,\nDANDO A PAZ, A CURA E O PERDÃO.\n\nCRISTO É SUAVE ALEGRIA,\nDOCE AMOR ENCHENDO O MEU SER;\nCRISTO É O AMADO QUE UM DIA<bis>\nVEM NAS ASAS DO AMANHECER.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (158, 'JESUS, O LÍRIO DOS VALES', 'JESUS, O LÍRIO DOS VALES', 'JESUS, O LÍRIO DOS VALES,\nJESUS, O GRANDE AMOR,\nJESUS, O AMOR SUBLIME,\nJESUS, O NOSSO SENHOR.\n\nELE É A PUREZA,\nÉ O AMOR MAIOR,\nÉ VIDA EM ABUNDÂNCIA,\nÉ A PAZ SEM FIM.\n\nJESUS, A ESTRELA DA MANHÃ,\nA ROSA PERFUMADA,\nUM RIO QUE TRANSBORDA\nDE AMOR INFINITO.', 'JESUS, O LÍRIO DOS VALES,\nJESUS, O GRANDE AMOR,\nJESUS, O AMOR SUBLIME,\nJESUS, O NOSSO SENHOR.\n\nELE É A PUREZA,\nÉ O AMOR MAIOR,\nÉ VIDA EM ABUNDÂNCIA,\nÉ A PAZ SEM FIM.\n\nJESUS, A ESTRELA DA MANHÃ,\nA ROSA PERFUMADA,\nUM RIO QUE TRANSBORDA\nDE AMOR INFINITO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (159, 'ELE É A ROSA DE SAROM', 'ELE É A ROSA DE SAROM', 'ELE É A ROSA DE SAROM,\nSEU FRUTO É DOCE AO PALADAR;\nELE É O LÍRIO DOS VALES,\nÀ SUA SOMBRA QUERO DESCANSAR.\nLEVOU-ME À SALA DO BANQUETE,\nSEU ESTANDARTE ERA EM MIM O AMOR;\nÓ SUSTENTA-ME, CONFORTA-ME\nE ME AMPARE TUA MÃO, SENHOR.\n\nESTA É A VOZ DO AMADO MEU,\nQUE ME ORDENA A LEVANTAR,\nEI-LO QUE VEM POR SOBRE OS MONTES,\nELE TEM PRESSA DE AQUI CHEGAR;\nSURGEM AS FLORES SOBRE A TERRA,\nCHEGOU O TEMPO AGORA DE CANTAR;\nO INVERNO PASSA, A CHUVA CESSOU \nE A VOZ DA ROLA POSSO ESCUTAR.', 'ELE É A ROSA DE SAROM,\nSEU FRUTO É DOCE AO PALADAR;\nELE É O LÍRIO DOS VALES,\nÀ SUA SOMBRA QUERO DESCANSAR.\nLEVOU-ME À SALA DO BANQUETE,\nSEU ESTANDARTE ERA EM MIM O AMOR;\nÓ SUSTENTA-ME, CONFORTA-ME\nE ME AMPARE TUA MÃO, SENHOR.\n\nESTA É A VOZ DO AMADO MEU,\nQUE ME ORDENA A LEVANTAR,\nEI-LO QUE VEM POR SOBRE OS MONTES,\nELE TEM PRESSA DE AQUI CHEGAR;\nSURGEM AS FLORES SOBRE A TERRA,\nCHEGOU O TEMPO AGORA DE CANTAR;\nO INVERNO PASSA, A CHUVA CESSOU <bis>\nE A VOZ DA ROLA POSSO ESCUTAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (160, 'EU SOU DO MEU AMADO E ELE ME TEM AFEIÇÃO', 'EU SOU DO MEU AMADO E ELE ME TEM AFEIÇÃO', 'EU SOU DO MEU AMADO\nE ELE ME TEM AFEIÇÃO.\nVEM, Ó MEU AMADO, SAIAMOS AO CAMPO,\nPASSEMOS AS NOITES NAS ALDEIAS,\nLEVANTEMO-NOS DE MANHÃ PARA IR ÀS VINHAS, \nVEJAMOS SE FLORESCEM AS VIDES,\nSE SE ABRE A FLOR, SE JÁ BROTAM \nAS ROMEIRAS, ALI TE DAREI \nO MEU GRANDE AMOR.\n\nAS MANDRÁGORAS DÃO CHEIRO\nE ÀS NOSSAS PORTAS HÁ TODA SORTE \nDE EXCELENTES FRUTOS\nNOVOS E VELHOS, NOVOS E VELHOS,\nÓ AMADO MEU, \nEU OS GUARDEI PARA TI.', 'EU SOU DO MEU AMADO<bis>\nE ELE ME TEM AFEIÇÃO.<bis>\nVEM, Ó MEU AMADO, SAIAMOS AO CAMPO,\nPASSEMOS AS NOITES NAS ALDEIAS,\nLEVANTEMO-NOS DE MANHÃ PARA IR ÀS VINHAS, \nVEJAMOS SE FLORESCEM AS VIDES,\nSE SE ABRE A FLOR, SE JÁ BROTAM \nAS ROMEIRAS, ALI TE DAREI \nO MEU GRANDE AMOR.\n\nAS MANDRÁGORAS DÃO CHEIRO<bis>\nE ÀS NOSSAS PORTAS HÁ TODA SORTE <bis>\nDE EXCELENTES FRUTOS<bis>\nNOVOS E VELHOS, NOVOS E VELHOS,<bis>\nÓ AMADO MEU, <bis>\nEU OS GUARDEI PARA TI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (161, 'ERA UMA OLIVEIRA', 'ERA UMA OLIVEIRA', 'ERA UMA OLIVEIRA COM OS RAMOS QUEBRADOS,\nE UM ZAMBUJEIRO ALI FOI ENXERTADO;\nESSA OLIVEIRA É O MEU JESUS,\nFUI NELE ENXERTADO, HOJE TENHO LUZ.\n\nCORO\nOLIVEIRA VERDADEIRA, JESUS CRISTO É,\nNELE FUI ENXERTADO ATRAVÉS DA FÉ,\nPOSSO EU DAR FRUTO ENXERTADO ASSIM;\nCRISTO É OLIVEIRA, NÃO MAIS VIVO EU\nMAS CRISTO VIVE EM MIM.\n\nZAMBUJEIRO BRAVO NÃO DÁ FRUTO BOM,\nASSIM ERA EU NO MEU CORAÇÃO,\nMAS NUM BELO DIA TUDO TRANSFORMOU,\nEU FUI ENXERTADO NO MEU SALVADOR.\n\nCORO\nOLIVEIRA VERDADEIRA, JESUS CRISTO É,\nNELE FUI ENXERTADO ATRAVÉS DA FÉ,\nPOSSO EU DAR FRUTO ENXERTADO ASSIM;\nCRISTO É OLIVEIRA, NÃO MAIS VIVO EU\nMAS CRISTO VIVE EM MIM.\n\nCRISTO É OLIVEIRA, NELE SOU FELIZ,\nNELE ESTOU LIGADO NO TRONCO E NA RAIZ;\nFIRMADO NA OLIVEIRA DE TODO O CORAÇÃO, \nPOSSO EU DAR FRUTO E DAR FRUTO BOM.\n\nCORO\nOLIVEIRA VERDADEIRA, JESUS CRISTO É,\nNELE FUI ENXERTADO ATRAVÉS DA FÉ,\nPOSSO EU DAR FRUTO ENXERTADO ASSIM;\nCRISTO É OLIVEIRA, NÃO MAIS VIVO EU\nMAS CRISTO VIVE EM MIM.', 'ERA UMA OLIVEIRA COM OS RAMOS QUEBRADOS,\nE UM ZAMBUJEIRO ALI FOI ENXERTADO;\nESSA OLIVEIRA É O MEU JESUS,\nFUI NELE ENXERTADO, HOJE TENHO LUZ.\n\n<coro>\nOLIVEIRA VERDADEIRA, JESUS CRISTO É,\nNELE FUI ENXERTADO ATRAVÉS DA FÉ,\nPOSSO EU DAR FRUTO ENXERTADO ASSIM;\nCRISTO É OLIVEIRA, NÃO MAIS VIVO EU\nMAS CRISTO VIVE EM MIM.\n\nZAMBUJEIRO BRAVO NÃO DÁ FRUTO BOM,\nASSIM ERA EU NO MEU CORAÇÃO,\nMAS NUM BELO DIA TUDO TRANSFORMOU,\nEU FUI ENXERTADO NO MEU SALVADOR.\n\n<coro>\nOLIVEIRA VERDADEIRA, JESUS CRISTO É,\nNELE FUI ENXERTADO ATRAVÉS DA FÉ,\nPOSSO EU DAR FRUTO ENXERTADO ASSIM;\nCRISTO É OLIVEIRA, NÃO MAIS VIVO EU\nMAS CRISTO VIVE EM MIM.\n\nCRISTO É OLIVEIRA, NELE SOU FELIZ,\nNELE ESTOU LIGADO NO TRONCO E NA RAIZ;\nFIRMADO NA OLIVEIRA DE TODO O CORAÇÃO, \nPOSSO EU DAR FRUTO E DAR FRUTO BOM.\n\n<coro>\nOLIVEIRA VERDADEIRA, JESUS CRISTO É,\nNELE FUI ENXERTADO ATRAVÉS DA FÉ,\nPOSSO EU DAR FRUTO ENXERTADO ASSIM;\nCRISTO É OLIVEIRA, NÃO MAIS VIVO EU\nMAS CRISTO VIVE EM MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (162, 'GRANDIOSO PARA MIM', 'GRANDIOSO PARA MIM', 'GRANDIOSO PARA MIM\nÉ JESUS, MEU SALVADOR,\nSUA GRAÇA NÃO TEM FIM,\nCOM SEU DIVINAL FULGOR;\nSUA GRAÇA SE ESTENDEU,\nDANDO-ME A SALVAÇÃO;\nGRANDE PAZ E ALEGRIA\nEU DESFRUTAREI UM DIA\nNA CELESTIAL SIÃO.\n\nO TEU NOME É AMOR,\nEU CONFESSO A TI, SENHOR;\nO TEU NOME É PURO E BOM,\nPERDOADO AGORA ESTOU;\nNESTE MUNDO DE ILUSÃO,\nENQUANTO EU AQUI VIVER,\nMINHA BOCA ENTOARÁ\nALELUIA, SEM CESSAR\nEXALTANDO O TEU PODER.', 'GRANDIOSO PARA MIM\nÉ JESUS, MEU SALVADOR,\nSUA GRAÇA NÃO TEM FIM,\nCOM SEU DIVINAL FULGOR;\nSUA GRAÇA SE ESTENDEU,\nDANDO-ME A SALVAÇÃO;\nGRANDE PAZ E ALEGRIA\nEU DESFRUTAREI UM DIA\nNA CELESTIAL SIÃO.\n\nO TEU NOME É AMOR,\nEU CONFESSO A TI, SENHOR;\nO TEU NOME É PURO E BOM,\nPERDOADO AGORA ESTOU;\nNESTE MUNDO DE ILUSÃO,\nENQUANTO EU AQUI VIVER,\nMINHA BOCA ENTOARÁ<bis>\nALELUIA, SEM CESSAR<bis>\nEXALTANDO O TEU PODER.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (163, 'TENHO UMA PEDRA VIVA', 'TENHO UMA PEDRA VIVA', 'TENHO UMA PEDRA VIVA,\nPEDRA DE ESQUINA, \nPEDRA ANGULAR;\nCRISTO É ROCHA DURA,\nTODA CRIATURA PODE SEGURAR.\nESTA ROCHA É CRISTO \nTODO IMPREVISTO PODE RESOLVER,\nPORÉM TEUS PECADOS SERÃO \nPERDOADOS, CRISTO TEM PODER.\n\nCORO\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ;\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ.\n\nESTA ROCHA É ÁGUA \nE QUEM TEM SUAS MÁGOAS ELE VAI TIRAR;\nNUNCA ESTOU SOZINHO, \nCRISTO É MEU CAMINHO, NELE TENHO PAZ.\nTEM PAZ VERDADEIRA QUEM \nNESTA ROCHA FIRMADO ESTÁ;\nCRISTO É A VERDADE E, SE \nCRERES NELE, TE LIBERTARÁ.\n\nCORO\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ;\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ.\n\nFINAL: \nELE É PODEROSO, \nELE É O LEÃO \nDA TRIBO DE JUDÁ.', 'TENHO UMA PEDRA VIVA,\nPEDRA DE ESQUINA, \nPEDRA ANGULAR;\nCRISTO É ROCHA DURA,\nTODA CRIATURA PODE SEGURAR.\nESTA ROCHA É CRISTO <bis>\nTODO IMPREVISTO PODE RESOLVER,<bis>\nPORÉM TEUS PECADOS SERÃO <bis>\nPERDOADOS, CRISTO TEM PODER.<bis>\n\n<coro>\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ;\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ.\n\nESTA ROCHA É ÁGUA \nE QUEM TEM SUAS MÁGOAS ELE VAI TIRAR;\nNUNCA ESTOU SOZINHO, \nCRISTO É MEU CAMINHO, NELE TENHO PAZ.\nTEM PAZ VERDADEIRA QUEM <bis>\nNESTA ROCHA FIRMADO ESTÁ;<bis>\nCRISTO É A VERDADE E, SE <bis>\nCRERES NELE, TE LIBERTARÁ.<bis>\n\n<coro>\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ;\nCRISTO TEM PODER E SABE LUTAR,\nELE É PODEROSO,\nELE É O LEÃO DA TRIBO DE JUDÁ.\n\n\n<final>ELE É PODEROSO, \nELE É O LEÃO \nDA TRIBO DE JUDÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (164, 'É BASTANTE PARA MIM A TUA GRAÇA', 'É BASTANTE PARA MIM A TUA GRAÇA', 'É BASTANTE PARA MIM A TUA GRAÇA,\nRECEBER A SALVAÇÃO E TEU PERDÃO;\nÉ MARAVILHOSO SABER\nQUE, PARA SEMPRE, COM JESUS VOU VIVER;\nÉ BASTANTE, PARA MIM, A TUA GRAÇA.\n\nA TUA GRAÇA É MELHOR QUE A VIDA,\nA TUA GRAÇA É MELHOR QUE A VIDA;\nMEUS LÁBIOS TE LOUVAM,\nE ASSIM BENDIREI, EM TEU \nNOME MINHAS MÃOS \nLEVANTAREI.\n\nA TUA PRESENÇA ENCHE O MEU CORAÇÃO,\nA TUA PRESENÇA ENCHE O MEU CORAÇÃO;\nMEUS LÁBIOS TE LOUVAM,\nE ASSIM BENDIREI, \nEM TEU NOME MINHAS MÃOS \nLEVANTAREI.', 'É BASTANTE PARA MIM A TUA GRAÇA,\nRECEBER A SALVAÇÃO E TEU PERDÃO;\nÉ MARAVILHOSO SABER\nQUE, PARA SEMPRE, COM JESUS VOU VIVER;\nÉ BASTANTE, PARA MIM, A TUA GRAÇA.\n\nA TUA GRAÇA É MELHOR QUE A VIDA,\nA TUA GRAÇA É MELHOR QUE A VIDA;\nMEUS LÁBIOS TE LOUVAM,<bis>\nE ASSIM BENDIREI, EM TEU <bis>\nNOME MINHAS MÃOS <bis>\nLEVANTAREI.<bis>\n\nA TUA PRESENÇA ENCHE O MEU CORAÇÃO,\nA TUA PRESENÇA ENCHE O MEU CORAÇÃO;\nMEUS LÁBIOS TE LOUVAM,<bis>\nE ASSIM BENDIREI, <bis>\nEM TEU NOME MINHAS MÃOS <bis>\nLEVANTAREI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (165, 'MARAVILHOSA GRAÇA', 'MARAVILHOSA GRAÇA', 'MARAVILHOSA GRAÇA,\nMAIOR QUE O MEU PECAR,\nCOMO PODER CANTÁ-LA,\nCOMO HEI DE COMEÇAR?\nPOIS ALIVIA A MINH''ALMA\nE VIVO EM TODA A CALMA\nPELA MARAVILHOSA GRAÇA DE JESUS.\n\nCORO\nGRAÇA, QUÃO MARAVILHOSA A GRAÇA DE JESUS,\nALTA COMO O FIRMAMENTO, ALTA E SEM FIM,\nGRAÇA, QUÃO MARAVILHOSA, SUFICIENTE A MIM;\nÉ MAIOR QUE A MINHA VIDA INÚTIL,\nÉ MAIOR QUE O MEU PECADO VIL,\nO NOME DE JESUS ENGRANDECEI \nE GLÓRIA DAI!\n\nMARAVILHOSA GRAÇA,\nQUÃO RICAS BÊNÇÃOS TRAZ,\nO SEU PODER TRANSFORMA \nO PECADOR FALAZ;\nESTOU SALVO COM A VERDADE\nPOR TODA A ETERNIDADE,\nPELA MARAVILHOSA GRAÇA DE JESUS.\n\nCORO\nGRAÇA, QUÃO MARAVILHOSA A GRAÇA DE JESUS,\nALTA COMO O FIRMAMENTO, ALTA E SEM FIM,\nGRAÇA, QUÃO MARAVILHOSA, SUFICIENTE A MIM;\nÉ MAIOR QUE A MINHA VIDA INÚTIL,\nÉ MAIOR QUE O MEU PECADO VIL,\nO NOME DE JESUS ENGRANDECEI \nE GLÓRIA DAI!', 'MARAVILHOSA GRAÇA,\nMAIOR QUE O MEU PECAR,\nCOMO PODER CANTÁ-LA,\nCOMO HEI DE COMEÇAR?\nPOIS ALIVIA A MINH''ALMA\nE VIVO EM TODA A CALMA\nPELA MARAVILHOSA GRAÇA DE JESUS.\n\n<coro>\nGRAÇA, QUÃO MARAVILHOSA A GRAÇA DE JESUS,\nALTA COMO O FIRMAMENTO, ALTA E SEM FIM,\nGRAÇA, QUÃO MARAVILHOSA, SUFICIENTE A MIM;\nÉ MAIOR QUE A MINHA VIDA INÚTIL,\nÉ MAIOR QUE O MEU PECADO VIL,\nO NOME DE JESUS ENGRANDECEI \nE GLÓRIA DAI!\n\nMARAVILHOSA GRAÇA,\nQUÃO RICAS BÊNÇÃOS TRAZ,\nO SEU PODER TRANSFORMA \nO PECADOR FALAZ;\nESTOU SALVO COM A VERDADE\nPOR TODA A ETERNIDADE,\nPELA MARAVILHOSA GRAÇA DE JESUS.\n\n<coro>\nGRAÇA, QUÃO MARAVILHOSA A GRAÇA DE JESUS,\nALTA COMO O FIRMAMENTO, ALTA E SEM FIM,\nGRAÇA, QUÃO MARAVILHOSA, SUFICIENTE A MIM;\nÉ MAIOR QUE A MINHA VIDA INÚTIL,\nÉ MAIOR QUE O MEU PECADO VIL,\nO NOME DE JESUS ENGRANDECEI \nE GLÓRIA DAI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (166, 'Ó AMADO DE MINH ́ALMA', 'Ó AMADO DE MINH ́ALMA', 'Ó AMADO DE MINH''ALMA,\nONDE APASCENTAS O TEU REBANHO?\nENTRE OS LÍRIOS APASCENTAS, \nEU SOU TEU E TU ÉS MEU, \nÓ AMADO MEU.\n\nCORO\nVEM, AMADO, AO TEU JARDIM,\nENTRE OS LÍRIOS, PASTOREAR;\nÓ VEM, SIM, VEM,\nHÁ UM REBANHO A TE ESPERAR.\n\nÓ AMADO DE MINH''ALMA,\nOUÇO TUA VOZ, QUE É TÃO SUAVE,\nQUE ME DIZ: ''LEVANTA E VEM'';\nLEVANTAR-ME-EI E IREI, Ó AMADO MEU.\n\nCORO\nVEM, AMADO, AO TEU JARDIM,\nENTRE OS LÍRIOS, PASTOREAR;\nÓ VEM, SIM, VEM,\nHÁ UM REBANHO A TE ESPERAR.\n\nOUÇO A VOZ DO MEU AMADO, \nEI-LO GALGANDO POR SOBRE OS MONTES;\nQUERO ESTAR COM O MEU AMADO\nNO JARDIM DE FRUTOS BONS, \nÓ AMADO MEU.\n\nCORO\nVEM, AMADO, AO TEU JARDIM,\nENTRE OS LÍRIOS, PASTOREAR;\nÓ VEM, SIM, VEM,\nHÁ UM REBANHO A TE ESPERAR.', 'Ó AMADO DE MINH''ALMA,\nONDE APASCENTAS O TEU REBANHO?\nENTRE OS LÍRIOS APASCENTAS, \nEU SOU TEU E TU ÉS MEU, \nÓ AMADO MEU.\n\n<coro>\nVEM, AMADO, AO TEU JARDIM,\nENTRE OS LÍRIOS, PASTOREAR;\nÓ VEM, SIM, VEM,\nHÁ UM REBANHO A TE ESPERAR.\n\nÓ AMADO DE MINH''ALMA,\nOUÇO TUA VOZ, QUE É TÃO SUAVE,\nQUE ME DIZ: ''LEVANTA E VEM'';\nLEVANTAR-ME-EI E IREI, Ó AMADO MEU.\n\n<coro>\nVEM, AMADO, AO TEU JARDIM,\nENTRE OS LÍRIOS, PASTOREAR;\nÓ VEM, SIM, VEM,\nHÁ UM REBANHO A TE ESPERAR.\n\nOUÇO A VOZ DO MEU AMADO, \nEI-LO GALGANDO POR SOBRE OS MONTES;\nQUERO ESTAR COM O MEU AMADO\nNO JARDIM DE FRUTOS BONS, \nÓ AMADO MEU.\n\n<coro>\nVEM, AMADO, AO TEU JARDIM,\nENTRE OS LÍRIOS, PASTOREAR;\nÓ VEM, SIM, VEM,<bis>\nHÁ UM REBANHO A TE ESPERAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (167, 'AMO AO MEU SENHOR', 'AMO AO MEU SENHOR', 'AMO AO MEU SENHOR\nPORQUE ELE OUVE A MINHA VOZ\nE O MEU CLAMOR, REFÚGIO MEU;\nNAS DIFICULDADES DESTA VIDA\nSEI QUE ME OUVIRÁ;\nO SENHOR ME GUARDARÁ.\n\nPORQUE DA MORTE LIVRASTE \nA MINH''ALMA,\nREFÚGIO EM TI ENCONTREI,\nQUERO SEGUIR-TE, \nMEU SENHOR E REI,\nQUERO SEGUIR-TE, \nMEU SENHOR E REI.\n\nINSTRUMENTOS\n\nQUERO OUVIR TUA VOZ, \nQUE É SOBERANA, \nAUXILIANDO O MEU ANDAR,\nPARA O ALVO ALCANÇAR;\nMESMO QUE HAJA PROVAS E DIAS DIFÍCEIS,\nÓ SENHOR, SEI QUE TU ME CONDUZIRÁS.\nPORQUE DA MORTE LIVRASTE A MINH''ALMA,\nDANDO-ME ASSIM SALVAÇÃO\nE BENDIREI TEU NOME SEMPRE, AMÉM,\nE BENDIREI TEU NOME SEMPRE, AMÉM.', 'AMO AO MEU SENHOR\nPORQUE ELE OUVE A MINHA VOZ\nE O MEU CLAMOR, REFÚGIO MEU;\nNAS DIFICULDADES DESTA VIDA\nSEI QUE ME OUVIRÁ;\nO SENHOR ME GUARDARÁ.\n\nPORQUE DA MORTE LIVRASTE \nA MINH''ALMA,\nREFÚGIO EM TI ENCONTREI,\nQUERO SEGUIR-TE, \nMEU SENHOR E REI,\nQUERO SEGUIR-TE, \nMEU SENHOR E REI.\n<instrumentos>\n\n\nQUERO OUVIR TUA VOZ, \nQUE É SOBERANA, \nAUXILIANDO O MEU ANDAR,\nPARA O ALVO ALCANÇAR;\nMESMO QUE HAJA PROVAS E DIAS DIFÍCEIS,\nÓ SENHOR, SEI QUE TU ME CONDUZIRÁS.\nPORQUE DA MORTE LIVRASTE A MINH''ALMA,\nDANDO-ME ASSIM SALVAÇÃO\nE BENDIREI TEU NOME SEMPRE, AMÉM,\nE BENDIREI TEU NOME SEMPRE, AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (168, 'TU ÉS FIEL, SENHOR', 'TU ÉS FIEL, SENHOR', 'TU ÉS FIEL, SENHOR, MEU PAI CELESTE,\nPLENO PODER AOS TEUS FILHOS DARÁS;\nNUNCA MUDASTE, TU NUNCA FALTASTE:\nTAL COMO ERAS, TU SEMPRE SERÁS.\n\nCORO\nTU ÉS FIEL, SENHOR, TU ÉS FIEL, SENHOR,\nDIA APÓS DIA, COM BÊNÇÃOS SEM FIM;\nTUA MERCÊ ME SUSTENTA E ME GUARDA,\nTU ÉS FIEL, SENHOR, FIEL A MIM.\n\nFLORES E FRUTOS, MONTANHAS E MARES,\nSOL, LUA, ESTRELAS NO CÉU A BRILHAR,\nTUDO CRIASTE NA TERRA E NOS ARES,\nTODO O UNIVERSO VEM, POIS, TE LOUVAR!\n\nCORO\nTU ÉS FIEL, SENHOR, TU ÉS FIEL, SENHOR,\nDIA APÓS DIA, COM BÊNÇÃOS SEM FIM;\nTUA MERCÊ ME SUSTENTA E ME GUARDA,\nTU ÉS FIEL, SENHOR, FIEL A MIM.\n\nPLENO PERDÃO TU DÁS, PAZ, SEGURANÇA,\nCADA MOMENTO ME GUIAS, SENHOR;\nE NO PORVIR, OH! QUE DOCE ESPERANÇA,\nDESFRUTAREI DO TEU RICO FAVOR!\n\nCORO\nTU ÉS FIEL, SENHOR, TU ÉS FIEL, SENHOR,\nDIA APÓS DIA, COM BÊNÇÃOS SEM FIM;\nTUA MERCÊ ME SUSTENTA E ME GUARDA,\nTU ÉS FIEL, SENHOR, FIEL A MIM.', 'TU ÉS FIEL, SENHOR, MEU PAI CELESTE,\nPLENO PODER AOS TEUS FILHOS DARÁS;\nNUNCA MUDASTE, TU NUNCA FALTASTE:\nTAL COMO ERAS, TU SEMPRE SERÁS.\n\n<coro>\nTU ÉS FIEL, SENHOR, TU ÉS FIEL, SENHOR,\nDIA APÓS DIA, COM BÊNÇÃOS SEM FIM;\nTUA MERCÊ ME SUSTENTA E ME GUARDA,\nTU ÉS FIEL, SENHOR, FIEL A MIM.\n\nFLORES E FRUTOS, MONTANHAS E MARES,\nSOL, LUA, ESTRELAS NO CÉU A BRILHAR,\nTUDO CRIASTE NA TERRA E NOS ARES,\nTODO O UNIVERSO VEM, POIS, TE LOUVAR!\n\n<coro>\nTU ÉS FIEL, SENHOR, TU ÉS FIEL, SENHOR,\nDIA APÓS DIA, COM BÊNÇÃOS SEM FIM;\nTUA MERCÊ ME SUSTENTA E ME GUARDA,\nTU ÉS FIEL, SENHOR, FIEL A MIM.\n\nPLENO PERDÃO TU DÁS, PAZ, SEGURANÇA,\nCADA MOMENTO ME GUIAS, SENHOR;\nE NO PORVIR, OH! QUE DOCE ESPERANÇA,\nDESFRUTAREI DO TEU RICO FAVOR!\n\n<coro>\nTU ÉS FIEL, SENHOR, TU ÉS FIEL, SENHOR,\nDIA APÓS DIA, COM BÊNÇÃOS SEM FIM;\nTUA MERCÊ ME SUSTENTA E ME GUARDA,\nTU ÉS FIEL, SENHOR, FIEL A MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (169, 'COMO A FLOR DO CAMPO', 'COMO A FLOR DO CAMPO', 'COMO A FLOR DO CAMPO QUE FLORESCE,\nSOPRA O VENTO E JÁ DESAPARECE,\nCOMO A NÉVOA QUE SE DESVANECE,\nASSIM BREVES SÃO OS NOSSOS DIAS.\n\nMAS DE ETERNIDADE A ETERNIDADE\nÉ, Ó SENHOR DEUS, TUA BONDADE,\nTEU AMOR E TUA FIDELIDADE\nTU ESTENDES SOBRE OS QUE TE TEMEM.\n\nCORO (2X)\nTU ÉS FIEL, SENHOR,\nSIM, TU ÉS FIEL.\n\nCÉUS E TERRA ENVELHECERÃO,\nAS COISAS CRIADAS TODAS PASSARÃO,\nCOMO ROUPAS VELHAS ELAS CAIRÃO,\nPELO TEU PODER AS MUDARÁS.\n\nCORO (2X)\nTU ÉS FIEL, SENHOR,\nSIM, TU ÉS FIEL.', 'COMO A FLOR DO CAMPO QUE FLORESCE,\nSOPRA O VENTO E JÁ DESAPARECE,\nCOMO A NÉVOA QUE SE DESVANECE,\nASSIM BREVES SÃO OS NOSSOS DIAS.\n\nMAS DE ETERNIDADE A ETERNIDADE\nÉ, Ó SENHOR DEUS, TUA BONDADE,\nTEU AMOR E TUA FIDELIDADE\nTU ESTENDES SOBRE OS QUE TE TEMEM.<coro tipo=''2X''>\nTU ÉS FIEL, SENHOR,\nSIM, TU ÉS FIEL.\n\nCÉUS E TERRA ENVELHECERÃO,\nAS COISAS CRIADAS TODAS PASSARÃO,\nCOMO ROUPAS VELHAS ELAS CAIRÃO,\nPELO TEU PODER AS MUDARÁS.<coro tipo=''2X''>\nTU ÉS FIEL, SENHOR,\nSIM, TU ÉS FIEL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (170, 'EU SOU TÃO FELIZ COM O MEU JESUS', 'EU SOU TÃO FELIZ COM O MEU JESUS', 'EU SOU TÃO FELIZ COM O MEU JESUS,\nELE MORREU NUMA CRUZ\nPRA SALVAR O PECADOR;\nELE É O CAMINHO, \nA VERDADE E A VIDA\nELE É JESUS, O SENHOR, \nNOSSO ETERNO REDENTOR!\n\nCORO (2X)\nNOVA CRIATURA SOU, \nPELO SANGUE DE JESUS, \nREDIMIDO PARA HERDAR \nA VIDA ETERNA!\n\nEU SOU TÃO FELIZ \nCOM O MEU JESUS,\nELE MORREU NUMA CRUZ \nPRA SALVAR O PECADOR.\n\nCORO (2X)\nNOVA CRIATURA SOU, \nPELO SANGUE DE JESUS,\nREDIMIDO PARA HERDAR \nA VIDA ETERNA!\n\nFINAL:\nREDIMIDO PARA HERDAR \nA VIDA ETERNA.', 'EU SOU TÃO FELIZ COM O MEU JESUS,\nELE MORREU NUMA CRUZ\nPRA SALVAR O PECADOR;\nELE É O CAMINHO, \nA VERDADE E A VIDA\nELE É JESUS, O SENHOR, \nNOSSO ETERNO REDENTOR!\n\n<coro tipo=''2X''>\nNOVA CRIATURA SOU, \nPELO SANGUE DE JESUS, \nREDIMIDO PARA HERDAR \nA VIDA ETERNA!\n\nEU SOU TÃO FELIZ \nCOM O MEU JESUS,\nELE MORREU NUMA CRUZ \nPRA SALVAR O PECADOR.\n\n<coro tipo=''2X''>\nNOVA CRIATURA SOU, \nPELO SANGUE DE JESUS,\nREDIMIDO PARA HERDAR \nA VIDA ETERNA!\n<final>REDIMIDO PARA HERDAR \nA VIDA ETERNA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (171, 'O AMOR DE JESUS É GRANDE', 'O AMOR DE JESUS É GRANDE', 'O AMOR DE JESUS É GRANDE,\nIMENSURÁVEL ESSE AMOR,\nNÃO SE PODE COMPARAR, NEM MEDIR,\nO INFINITO AMOR DE DEUS.\n\nDEMONSTRADO LÁ NA CRUZ\nPOR JESUS, MEU REI,\nPRA SALVAR O POBRE PECADOR,\nOH! QUE GRANDE AMOR.\nINSTRUMENTOS\n\nO AMOR DE JESUS É GRANDE,\nIMENSURÁVEL ESSE AMOR,\nNÃO SE PODE COMPARAR, NEM MEDIR,\nO INFINITO AMOR DE DEUS.\n\nDEMONSTRADO LÁ NA CRUZ\nPOR JESUS, MEU REI,\nPRA SALVAR O POBRE PECADOR,\nOH! QUE GRANDE AMOR.\n\nFINAL: (2X) \nOH! QUE GRANDE AMOR.', 'O AMOR DE JESUS É GRANDE,<bis>\nIMENSURÁVEL ESSE AMOR,<bis>\nNÃO SE PODE COMPARAR, NEM MEDIR,<bis>\nO INFINITO AMOR DE DEUS.<bis>\n\nDEMONSTRADO LÁ NA CRUZ\nPOR JESUS, MEU REI,\nPRA SALVAR O POBRE PECADOR,\nOH! QUE GRANDE AMOR.\n<instrumentos>\n\n\nO AMOR DE JESUS É GRANDE,\nIMENSURÁVEL ESSE AMOR,\nNÃO SE PODE COMPARAR, NEM MEDIR,\nO INFINITO AMOR DE DEUS.\n\nDEMONSTRADO LÁ NA CRUZ<bis>\nPOR JESUS, MEU REI,<bis>\nPRA SALVAR O POBRE PECADOR,<bis>\nOH! QUE GRANDE AMOR.\n<final>(<bis tipo=''2''> \nOH! QUE GRANDE AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (172, 'SENHOR, TE AMO, TE AMO', 'SENHOR, TE AMO, TE AMO', 'CORO\nSENHOR, TE AMO, TE AMO,\nPORQUE SOFRESTE POR MIM,\nNA CRUZ MORRESTE, MEU MESTRE,\nEU TE AMO, TE AMO, JESUS.\n\nA DOR QUE ERA PARA MIM\nLEVOU JESUS, MEU SENHOR;\nCOMO É BOM TER CRISTO AO MEU LADO,\nOH! QUANTO AMO JESUS, MEU SENHOR.\n\nCORO\nSENHOR, TE AMO, TE AMO,\nPORQUE SOFRESTE POR MIM,\nNA CRUZ MORRESTE, MEU MESTRE,\nEU TE AMO, TE AMO, JESUS.\n\nA CRISTO ENTREGO MEU VIVER\nPORQUE EU SEI QUE CUIDA DE MIM;\nELE É O AMADO DE MINH''ALMA,\nOH! QUANTO AMO JESUS, MEU SENHOR.\n\nCORO\nSENHOR, TE AMO, TE AMO,\nPORQUE SOFRESTE POR MIM,\nNA CRUZ MORRESTE, MEU MESTRE,\nEU TE AMO, TE AMO, JESUS.', '<coro>\nSENHOR, TE AMO, TE AMO,\nPORQUE SOFRESTE POR MIM,\nNA CRUZ MORRESTE, MEU MESTRE,\nEU TE AMO, TE AMO, JESUS.\n\nA DOR QUE ERA PARA MIM\nLEVOU JESUS, MEU SENHOR;\nCOMO É BOM TER CRISTO AO MEU LADO,\nOH! QUANTO AMO JESUS, MEU SENHOR.\n\n<coro>\nSENHOR, TE AMO, TE AMO,\nPORQUE SOFRESTE POR MIM,\nNA CRUZ MORRESTE, MEU MESTRE,\nEU TE AMO, TE AMO, JESUS.\n\nA CRISTO ENTREGO MEU VIVER\nPORQUE EU SEI QUE CUIDA DE MIM;\nELE É O AMADO DE MINH''ALMA,\nOH! QUANTO AMO JESUS, MEU SENHOR.\n\n<coro>\nSENHOR, TE AMO, TE AMO,\nPORQUE SOFRESTE POR MIM,\nNA CRUZ MORRESTE, MEU MESTRE,\nEU TE AMO, TE AMO, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (173, 'QUANDO JESUS UM DIA', 'QUANDO JESUS UM DIA', 'QUANDO JESUS UM DIA\nMEU PECADO CARREGOU,\nPELO SANGUE DERRAMADO\nMINHA VIDA ELE LAVOU.\n\nALGO NOVO ACONTECEU,\nTÃO SUBLIME E TÃO REAL;\nCHORAR EU NÃO SABIA,\nSÓ DE AGONIA E DOR.\n\nCHORO AGORA DE ALEGRIA,\nALELUIA AO MEU SENHOR;\nMEU PECADO RESGATOU,\nMINHA VIDA TRANSFORMOU.\n\nALGO NOVO ACONTECEU,\nTÃO SUBLIME E TÃO REAL;\nCHORO AGORA DE ALEGRIA,\nALELUIA AO MEU SENHOR.', 'QUANDO JESUS UM DIA\nMEU PECADO CARREGOU,\nPELO SANGUE DERRAMADO\nMINHA VIDA ELE LAVOU.\n\nALGO NOVO ACONTECEU,\nTÃO SUBLIME E TÃO REAL;\nCHORAR EU NÃO SABIA,\nSÓ DE AGONIA E DOR.\n\nCHORO AGORA DE ALEGRIA,\nALELUIA AO MEU SENHOR;\nMEU PECADO RESGATOU,\nMINHA VIDA TRANSFORMOU.\n\nALGO NOVO ACONTECEU,\nTÃO SUBLIME E TÃO REAL;\nCHORO AGORA DE ALEGRIA,\nALELUIA AO MEU SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (174, 'A MINHA HERANÇA É O SENHOR', 'A MINHA HERANÇA É O SENHOR', 'A MINHA HERANÇA É O SENHOR (É O SENHOR),\nNÃO TENHO OUTRO BEM MAIOR;\nAINDA QUE ME OFEREÇAM.\n\nTODA RIQUEZA DESTE MUNDO, \nNÃO TROCAREI A MINHA HERANÇA, \nPOIS CUSTOU UM ALTO PREÇO \nE ESTE PREÇO FOI O SANGUE DE JESUS.\n\nA MINHA HERANÇA É O SENHOR (É O SENHOR),\nNÃO TENHO OUTRO BEM MAIOR;\nAINDA QUE ME OFEREÇAM.\n\nTODA RIQUEZA DESTE MUNDO, \nNÃO TROCAREI A MINHA HERANÇA, \nPOIS CUSTOU UM ALTO PREÇO \nE ESTE PREÇO FOI O SANGUE DE JESUS.\n\n\nFINAL: (2X)\nE ESTE ALTO PREÇO \nFOI SANGUE DE JESUS', 'A MINHA HERANÇA É O SENHOR (É O SENHOR),\nNÃO TENHO OUTRO BEM MAIOR;\nAINDA QUE ME OFEREÇAM.\n\nTODA RIQUEZA DESTE MUNDO, \nNÃO TROCAREI A MINHA HERANÇA, \nPOIS CUSTOU UM ALTO PREÇO \nE ESTE PREÇO FOI O SANGUE DE JESUS.\n\nA MINHA HERANÇA É O SENHOR (É O SENHOR),\nNÃO TENHO OUTRO BEM MAIOR;\nAINDA QUE ME OFEREÇAM.\n\nTODA RIQUEZA DESTE MUNDO, \nNÃO TROCAREI A MINHA HERANÇA, \nPOIS CUSTOU UM ALTO PREÇO \nE ESTE PREÇO FOI O SANGUE DE JESUS.\n\n\n<final>(<bis tipo=''2''>\nE ESTE ALTO PREÇO \nFOI SANGUE DE JESUS', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (175, 'DESDE O DIA EM QUE TE CONHECI', 'DESDE O DIA EM QUE TE CONHECI', 'DESDE O DIA EM QUE TE CONHECI,\nTODA A MINHA VIDA DEI A TI;\nOPERASTE EM MEU SER ALGO QUE NÃO SEI DIZER.\nEU SÓ SEI QUE TU ÉS MEU BEM QUERER.\n\nCORO\nMARANATA! VEM, JESUS!\nMARANATA! VEM, SENHOR JESUS!\nMEU DESEJO É TE VER, \nFACE A FACE TE ADORAR. \nORA VEM, SENHOR, ME BUSCAR.\n\nORA VEM, SENHOR, ME BUSCAR.\nMUITAS LUTAS EU PASSEI PRA TE SERVIR,\nMAS TEU CONSOLO E TEU AMOR ME SUSTENTARAM, \nAS PROMESSAS SE CUMPRIRAM, \nRENOVANDO MEU VIGOR.\nCOMO POSSO TE ESQUECER, \nÓ MEU SENHOR?\n\nCORO\nMARANATA! VEM, JESUS!\nMARANATA! VEM, SENHOR JESUS!\nMEU DESEJO É TE VER, \nFACE A FACE TE ADORAR. \nORA VEM, SENHOR, ME BUSCAR.\n\nTE SERVIR É TUDO QUE EU QUERO, \nSENHOR,TE EXALTAR, ENGRANDECER, \nTE BENDIZER;\nTU ME AMASTE, MEU SENHOR.\nMEU JESUS, MEU SALVADOR,\nMEU DESEJO É TE VER NA ETERNIDADE.\n\nCORO\nMARANATA! VEM, JESUS!\nMARANATA! VEM, SENHOR JESUS!\nMEU DESEJO É TE VER, \nFACE A FACE TE ADORAR. \nORA VEM, SENHOR, ME BUSCAR.\n\nFINAL: \nMEU DESEJO É TE VER,\nFACE A FACE TE ADORAR,\nEU ESTOU A TE ESPERAR.', 'DESDE O DIA EM QUE TE CONHECI,\nTODA A MINHA VIDA DEI A TI;\nOPERASTE EM MEU SER ALGO QUE NÃO SEI DIZER.\nEU SÓ SEI QUE TU ÉS MEU BEM QUERER.\n\n<coro>\nMARANATA! VEM, JESUS!\nMARANATA! VEM, SENHOR JESUS!\nMEU DESEJO É TE VER, \nFACE A FACE TE ADORAR. \nORA VEM, SENHOR, ME BUSCAR.\n\nORA VEM, SENHOR, ME BUSCAR.\nMUITAS LUTAS EU PASSEI PRA TE SERVIR,\nMAS TEU CONSOLO E TEU AMOR ME SUSTENTARAM, \nAS PROMESSAS SE CUMPRIRAM, \nRENOVANDO MEU VIGOR.\nCOMO POSSO TE ESQUECER, \nÓ MEU SENHOR?\n\n<coro>\nMARANATA! VEM, JESUS!\nMARANATA! VEM, SENHOR JESUS!\nMEU DESEJO É TE VER, \nFACE A FACE TE ADORAR. \nORA VEM, SENHOR, ME BUSCAR.\n\nTE SERVIR É TUDO QUE EU QUERO, \nSENHOR,TE EXALTAR, ENGRANDECER, \nTE BENDIZER;\nTU ME AMASTE, MEU SENHOR.\nMEU JESUS, MEU SALVADOR,\nMEU DESEJO É TE VER NA ETERNIDADE.\n\n<coro>\nMARANATA! VEM, JESUS!\nMARANATA! VEM, SENHOR JESUS!\nMEU DESEJO É TE VER, \nFACE A FACE TE ADORAR. \nORA VEM, SENHOR, ME BUSCAR.\n\n\n<final>MEU DESEJO É TE VER,\nFACE A FACE TE ADORAR,\nEU ESTOU A TE ESPERAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (176, 'NÃO EXISTE OUTRO AMOR IGUAL AO TEU, SENHOR', 'NÃO EXISTE OUTRO AMOR IGUAL AO TEU, SENHOR', 'NÃO EXISTE OUTRO AMOR IGUAL AO TEU, SENHOR,\nNÃO EXISTE COMPAIXÃO IGUAL À TUA COMPAIXÃO,\nNÃO HÁ OUTRO CAMINHO QUE NOS CONDUZ AO CÉU\nNÃO EXISTE OUTRO NOME QUE POSSA NOS SALVAR.\n\nJESUS, TU ÉS O ÚNICO SENHOR,\nÉS A LUZ, ÉS O CAMINHO, ÉS MEU AMOR;\nO TEU NOME É SOBRE OS NOMES.\nÉS JESUS, ÉS A RAZÃO DO MEU VIVER. \n\nNÃO EXISTE OUTRO AMOR IGUAL AO \nTEU SENHOR, NÃO EXISTE COMPAIXÃO \nIGUAL À TUA COMPAIXÃO,\nNÃO HÁ OUTRO CAMINHO \nQUE NOS CONDUZ AO CÉU \nNÃO EXISTE OUTRO NOME \nQUE POSSA NOS SALVAR.\n\nJESUS, TU ÉS O ÚNICO SENHOR,\nÉS A LUZ, ÉS O CAMINHO, \nÉS MEU AMOR;\nO TEU NOME É SOBRE OS NOMES.\nÉS JESUS, ÉS A RAZÃO DO MEU VIVER.\n\nFINAL: DO MEU VIVER.', 'NÃO EXISTE OUTRO AMOR IGUAL AO TEU, SENHOR,\nNÃO EXISTE COMPAIXÃO IGUAL À TUA COMPAIXÃO,\nNÃO HÁ OUTRO CAMINHO QUE NOS CONDUZ AO CÉU\nNÃO EXISTE OUTRO NOME QUE POSSA NOS SALVAR.\n\nJESUS, TU ÉS O ÚNICO SENHOR,\nÉS A LUZ, ÉS O CAMINHO, ÉS MEU AMOR;\nO TEU NOME É SOBRE OS NOMES.\nÉS JESUS, ÉS A RAZÃO DO MEU VIVER. \n\nNÃO EXISTE OUTRO AMOR IGUAL AO \nTEU SENHOR, NÃO EXISTE COMPAIXÃO \nIGUAL À TUA COMPAIXÃO,\nNÃO HÁ OUTRO CAMINHO \nQUE NOS CONDUZ AO CÉU \nNÃO EXISTE OUTRO NOME \nQUE POSSA NOS SALVAR.\n\nJESUS, TU ÉS O ÚNICO SENHOR,<bis>\nÉS A LUZ, ÉS O CAMINHO, <bis>\nÉS MEU AMOR;<bis>\nO TEU NOME É SOBRE OS NOMES.<bis>\nÉS JESUS, ÉS A RAZÃO DO MEU VIVER.\n<final>DO MEU VIVER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (177, 'SEMPRE VOU LEMBRAR O QUE FIZESTE POR MIM', 'SEMPRE VOU LEMBRAR O QUE FIZESTE POR MIM', 'SEMPRE VOU LEMBRAR O QUE FIZESTE POR MIM,\nNÃO ESQUECEREI TEU GRANDE AMOR POR MIM.\nSEMPRE VOU LEMBRAR O QUE FIZESTE POR MIM,\nNÃO ESQUECEREI TEU GRANDE AMOR POR MIM. \n\nCORO \nNÃO FOI EM VÃO \nO TEU SANGUE VERTIDO NA CRUZ, \nNÃO FOI EM VÃO, \nEU TE LOUVO PRA SEMPRE, JESUS.\n\nINSTRUMENTOS\n\nÉ TEU MEU LOUVOR, \nMINHA ADORAÇÃO, \nÉS TU MEU PASTOR, \nÉ TEU TODO O MEU CORAÇÃO.\n\nCORO \nNÃO FOI EM VÃO \nO TEU SANGUE VERTIDO NA CRUZ, \nNÃO FOI EM VÃO, \nEU TE LOUVO PRA SEMPRE, JESUS.\n\nFINAL: \nEU TE LOUVO PRA SEMPRE, JESUS,\nEU TE LOUVO PRA SEMPRE, JESUS.', 'SEMPRE VOU LEMBRAR O QUE FIZESTE POR MIM,\nNÃO ESQUECEREI TEU GRANDE AMOR POR MIM.\nSEMPRE VOU LEMBRAR O QUE FIZESTE POR MIM,\nNÃO ESQUECEREI TEU GRANDE AMOR POR MIM. \n\n<coro>\nNÃO FOI EM VÃO \nO TEU SANGUE VERTIDO NA CRUZ, \nNÃO FOI EM VÃO, \nEU TE LOUVO PRA SEMPRE, JESUS.\n<instrumentos>\n\n\nÉ TEU MEU LOUVOR, \nMINHA ADORAÇÃO, \nÉS TU MEU PASTOR, \nÉ TEU TODO O MEU CORAÇÃO.\n\n<coro>\nNÃO FOI EM VÃO \nO TEU SANGUE VERTIDO NA CRUZ, \nNÃO FOI EM VÃO, \nEU TE LOUVO PRA SEMPRE, JESUS.\n<final>EU TE LOUVO PRA SEMPRE, JESUS,\nEU TE LOUVO PRA SEMPRE, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (178, 'O DEUS A QUEM SERVIMOS', 'O DEUS A QUEM SERVIMOS', 'O DEUS A QUEM SERVIMOS \nÉ DEUS FORTE NA BATALHA, É DEUS FIEL;\nO DEUS A QUEM SERVIMOS \nNÃO NOS DESAMPARA JAMAIS.\nO DEUS A QUEM SERVIMOS \nÉ UM DEUS PERDOADOR, \nÉ DEUS DE AMOR;\nELE É O NOSSO GUARDADOR, \nÉ O BOM PASTOR.\n\nCORO\nNÓS PERTENCEMOS A TI, SENHOR,\nSOMOS TEUS SERVOS,\nDE QUEM TENS CUIDADO COM AMOR;\nNÓS PERTENCEMOS A TI, SENHOR,\nE PRA TEU LOUVOR ESTAMOS AQUI.\n\nO DEUS A QUEM SERVIMOS \nPÕE EM NOSSOS LÁBIOS UM NOVO LOUVOR,\nO DEUS A QUEM SERVIMOS \nNOS DÁ SEMPRE A VITÓRIA.\nO DEUS A QUEM SERVIMOS ESTÁ \nAQUI PRESENTE ENTRE NÓS.\nPODEMOS SENTIR SUA PRESENÇA,\nPODEMOS OUVIR SUA DOCE VOZ,\nPODEMOS CONTEMPLAR \nAS MARAVILHAS DAS SUAS MÃOS.\n\nCORO\nNÓS PERTENCEMOS A TI, SENHOR,\nSOMOS TEUS SERVOS,\nDE QUEM TENS CUIDADO COM AMOR;\nNÓS PERTENCEMOS A TI, SENHOR,\nE PRA TEU LOUVOR ESTAMOS AQUI.', 'O DEUS A QUEM SERVIMOS \nÉ DEUS FORTE NA BATALHA, É DEUS FIEL;\nO DEUS A QUEM SERVIMOS \nNÃO NOS DESAMPARA JAMAIS.\nO DEUS A QUEM SERVIMOS \nÉ UM DEUS PERDOADOR, \nÉ DEUS DE AMOR;\nELE É O NOSSO GUARDADOR, \nÉ O BOM PASTOR.\n\n<coro>\nNÓS PERTENCEMOS A TI, SENHOR,\nSOMOS TEUS SERVOS,\nDE QUEM TENS CUIDADO COM AMOR;\nNÓS PERTENCEMOS A TI, SENHOR,\nE PRA TEU LOUVOR ESTAMOS AQUI.\n\nO DEUS A QUEM SERVIMOS \nPÕE EM NOSSOS LÁBIOS UM NOVO LOUVOR,\nO DEUS A QUEM SERVIMOS \nNOS DÁ SEMPRE A VITÓRIA.\nO DEUS A QUEM SERVIMOS ESTÁ \nAQUI PRESENTE ENTRE NÓS.\nPODEMOS SENTIR SUA PRESENÇA,\nPODEMOS OUVIR SUA DOCE VOZ,\nPODEMOS CONTEMPLAR \nAS MARAVILHAS DAS SUAS MÃOS.\n\n<coro>\nNÓS PERTENCEMOS A TI, SENHOR,\nSOMOS TEUS SERVOS,\nDE QUEM TENS CUIDADO COM AMOR;\nNÓS PERTENCEMOS A TI, SENHOR,\nE PRA TEU LOUVOR ESTAMOS AQUI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (179, 'PELA FÉ EU POSSO CONTEMPLAR JESUS', 'PELA FÉ EU POSSO CONTEMPLAR JESUS', 'PELA FÉ EU POSSO CONTEMPLAR JESUS,\n(PELA FÉ EU POSSO VER)\nPELA FÉ EU VEJO O BRILHO DA SUA LUZ,\nPELA FÉ EU POSSO VER OS ANJOS CANTANDO, \nEXALTANDO O NOSSO REI, O SALVADOR.\n\nPELA FÉ EU SINTO NO MEU CORAÇÃO\n(PELA FÉ POSSO SENTIR)\nA PRESENÇA DO ESPÍRITO DE DEUS,\nPELA FÉ EU SINTO SUA MÃO TOCAR EM MIM\nPELA FÉ POSSO SENTIR SEU GRANDE AMOR.\n\nE PELA FÉ VOU CAMINHANDO\nATÉ CHEGAR À TERRA PROMETIDA,\nE PELA FÉ JÁ OUÇO O CANTO DE VITÓRIA: \nCRISTO REINANDO COM OS FIÉIS NA SUA GLÓRIA.', 'PELA FÉ EU POSSO CONTEMPLAR JESUS,\n(PELA FÉ EU POSSO VER)\nPELA FÉ EU VEJO O BRILHO DA SUA LUZ,\nPELA FÉ EU POSSO VER OS ANJOS CANTANDO, \nEXALTANDO O NOSSO REI, O SALVADOR.\n\nPELA FÉ EU SINTO NO MEU CORAÇÃO\n(PELA FÉ POSSO SENTIR)\nA PRESENÇA DO ESPÍRITO DE DEUS,\nPELA FÉ EU SINTO SUA MÃO TOCAR EM MIM\nPELA FÉ POSSO SENTIR SEU GRANDE AMOR.\n\nE PELA FÉ VOU CAMINHANDO<bis>\nATÉ CHEGAR À TERRA PROMETIDA,<bis>\nE PELA FÉ JÁ OUÇO O CANTO DE VITÓRIA: <bis>\nCRISTO REINANDO COM OS FIÉIS NA SUA GLÓRIA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (180, 'ENCONTREI O GRANDE AMOR', 'ENCONTREI O GRANDE AMOR', 'ENCONTREI O GRANDE AMOR, \nAMOR QUE SARA A DOR;\nQUE CURA AS FERIDAS. \nE TRAZ SENTIDO À VIDA;\nAMOR QUE AQUECE A ALMA, \nCONFORTA E ACALMA O CORAÇÃO \nAFLITO E O FAZ ALCANÇAR A PAZ.\n\nAMOR VERDADEIRO ENCONTREI EM TI, JESUS, \nQUE FOI DEMONSTRADO ALI NA CRUZ;\nAMOR LINDO E PURO, AMOR TÃO SINCERO, \nQUE NÃO SE MEDE, NEM SE PODE COMPARAR.\n\nAMOR INCOMPARÁVEL \nQUE FEZ MEU JESUS \nMORRER INOCENTE NAQUELA CRUZ.\nAMOR QUE É MAIS FORTE \nQUE A PRÓPRIA MORTE, \nQUE ME SALVOU;\n\nCOMO AGRADECER ESSE TÃO \nGRANDE AMOR?\nE COMO EXPRESSAR COM \nPALAVRAS, SENHOR,\nTEU SACRIFÍCIO MARCADO \nDE DOR, POR MIM PECADOR?', 'ENCONTREI O GRANDE AMOR, \nAMOR QUE SARA A DOR;\nQUE CURA AS FERIDAS. \nE TRAZ SENTIDO À VIDA;\nAMOR QUE AQUECE A ALMA, \nCONFORTA E ACALMA O CORAÇÃO \nAFLITO E O FAZ ALCANÇAR A PAZ.\n\nAMOR VERDADEIRO ENCONTREI EM TI, JESUS, \nQUE FOI DEMONSTRADO ALI NA CRUZ;\nAMOR LINDO E PURO, AMOR TÃO SINCERO, \nQUE NÃO SE MEDE, NEM SE PODE COMPARAR.\n\nAMOR INCOMPARÁVEL \nQUE FEZ MEU JESUS \nMORRER INOCENTE NAQUELA CRUZ.\nAMOR QUE É MAIS FORTE \nQUE A PRÓPRIA MORTE, \nQUE ME SALVOU;\n\nCOMO AGRADECER ESSE TÃO <bis>\nGRANDE AMOR?<bis>\nE COMO EXPRESSAR COM <bis>\nPALAVRAS, SENHOR,<bis>\nTEU SACRIFÍCIO MARCADO <bis>\nDE DOR, POR MIM PECADOR?<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (181, 'EM TI EU ENCONTRO, Ó DEUS, TODA A PAZ', 'EM TI EU ENCONTRO, Ó DEUS, TODA A PAZ', 'EM TI EU ENCONTRO, Ó DEUS, \nTODA A PAZ, E A VIDA QUE EU QUERO VIVER;\nMINHA VIDA TRANSBORDA DE GOZO E DE PAZ, \nJESUS ME TRANSPORTA AO CÉU.\nSENHOR, TE ADORO, ME ACHEGO A TI, \nEM TI ME ALEGRO, JESUS.\n\nCORO\nTU ÉS MINHA PAZ, A FONTE DA VIDA.\nSENHOR, SOU TEU, TU ÉS MINHA VIDA. \n\nINSTRUMENTOS\n\nJESUS ME TRANSPORTA ÀS MANSÕES CELESTIAIS, \nMINHA VIDA TRANSBORDA DE PAZ.\nME FAZ DESCANSAR EM TEU LINDO JARDIM \nENTRE OS LÍRIOS TE ADORO, SENHOR.\n\nPASSEIO ENTRE OS LÍRIOS, \nEM TEU LINDO JARDIM.\nJESUS ME TRANSPORTA AO CÉU;\nRENOVA MINHA FORÇA, \nSE FRACO ESTOU.\nEM TI REJUBILO, SENHOR.\n\nCORO (2X)\nTU ÉS MINHA PAZ, A FONTE DA VIDA.\nSENHOR, SOU TEU, TU ÉS MINHA VIDA.', 'EM TI EU ENCONTRO, Ó DEUS, \nTODA A PAZ, E A VIDA QUE EU QUERO VIVER;\nMINHA VIDA TRANSBORDA DE GOZO E DE PAZ, \nJESUS ME TRANSPORTA AO CÉU.\nSENHOR, TE ADORO, ME ACHEGO A TI, \nEM TI ME ALEGRO, JESUS.\n\n<coro>\nTU ÉS MINHA PAZ, A FONTE DA VIDA.\nSENHOR, SOU TEU, TU ÉS MINHA VIDA. \n<instrumentos>\n\n\nJESUS ME TRANSPORTA ÀS MANSÕES CELESTIAIS, \nMINHA VIDA TRANSBORDA DE PAZ.\nME FAZ DESCANSAR EM TEU LINDO JARDIM \nENTRE OS LÍRIOS TE ADORO, SENHOR.\n\nPASSEIO ENTRE OS LÍRIOS, \nEM TEU LINDO JARDIM.\nJESUS ME TRANSPORTA AO CÉU;\nRENOVA MINHA FORÇA, \nSE FRACO ESTOU.\nEM TI REJUBILO, SENHOR.\n\n<coro tipo=''2X''>\nTU ÉS MINHA PAZ, A FONTE DA VIDA.\nSENHOR, SOU TEU, TU ÉS MINHA VIDA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (182, 'COMO É BOM SERVIR AO SENHOR', 'COMO É BOM SERVIR AO SENHOR', 'COMO É BOM SERVIR AO SENHOR,\nOUVIR SUA VOZ A ORIENTAR:\n''VAI, MEU SERVO, FALAR DO MEU AMOR''\nE PODER DIZER DE TODO O CORAÇÃO: \nEIS-ME AQUI.\n\nE MELHOR AINDA É SABER\nQUE NÃO VOU SOZINHO.\nO SENHOR VAI ADIANTE, \nME DANDO CONDIÇÃO\nPARA A SUA OBRA REALIZAR.\n\nFINAL: \nPARA A SUA OBRA REALIZAR.', 'COMO É BOM SERVIR AO SENHOR,<bis>\nOUVIR SUA VOZ A ORIENTAR:<bis>\n''VAI, MEU SERVO, FALAR DO MEU AMOR''<bis>\nE PODER DIZER DE TODO O CORAÇÃO: <bis>\nEIS-ME AQUI.<bis>\n\nE MELHOR AINDA É SABER<bis>\nQUE NÃO VOU SOZINHO.<bis>\nO SENHOR VAI ADIANTE, <bis>\nME DANDO CONDIÇÃO<bis>\nPARA A SUA OBRA REALIZAR.\n<final>PARA A SUA OBRA REALIZAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (183, 'A MINHA ALEGRIA', 'A MINHA ALEGRIA', 'A MINHA ALEGRIA É PERTENCER \nAO GRANDE SALVADOR;\nSABER QUE MUITO EM BREVE O VEREI;\nSABER QUE COM OS ANJOS EU O LOUVAREI.\nA MINHA ALEGRIA É SABER \nQUE PARA SEMPRE \nCOM CRISTO VIVEREI.\n\nCORO\nEXISTE UM LUGAR DE PAZ CELESTIAL (CELESTIAL).\nQUANDO OS MEUS PÉS ALI TOCAREM,\nSEI QUE AS LUTAS VÃO CESSAR, POIS ALI \nÉ LUGAR SANTO, MORADA DO SENHOR.\nE AQUELE QUE VENCER DE JESUS IRÁ OUVIR: \n''VINDE, BENDITOS DE MEU PAI''.\n\nA FORÇA PARA PROSSEGUIR \nEU SEMPRE ENCONTRO QUANDO BUSCO A TI;\nSABER QUE ESTÁS COMIGO A ME GUARDAR\nSABER QUE TUDO TU FARÁS PRA ME PRESERVAR.\nA FORÇA PARA PROSSEGUIR É SABER \nQUE PARA SEMPRE CONTIGO VIVEREI.\n\nCORO (2X)\nEXISTE UM LUGAR DE PAZ CELESTIAL (CELESTIAL).\nQUANDO OS MEUS PÉS ALI TOCAREM,\nSEI QUE AS LUTAS VÃO CESSAR, POIS ALI \nÉ LUGAR SANTO, MORADA DO SENHOR.\nE AQUELE QUE VENCER DE JESUS IRÁ OUVIR: \n''VINDE, BENDITOS DE MEU PAI''.', 'A MINHA ALEGRIA É PERTENCER \nAO GRANDE SALVADOR;\nSABER QUE MUITO EM BREVE O VEREI;\nSABER QUE COM OS ANJOS EU O LOUVAREI.\nA MINHA ALEGRIA É SABER \nQUE PARA SEMPRE \nCOM CRISTO VIVEREI.\n\n<coro>\nEXISTE UM LUGAR DE PAZ CELESTIAL (CELESTIAL).\nQUANDO OS MEUS PÉS ALI TOCAREM,\nSEI QUE AS LUTAS VÃO CESSAR, POIS ALI \nÉ LUGAR SANTO, MORADA DO SENHOR.\nE AQUELE QUE VENCER DE JESUS IRÁ OUVIR: \n''VINDE, BENDITOS DE MEU PAI''.\n\nA FORÇA PARA PROSSEGUIR \nEU SEMPRE ENCONTRO QUANDO BUSCO A TI;\nSABER QUE ESTÁS COMIGO A ME GUARDAR\nSABER QUE TUDO TU FARÁS PRA ME PRESERVAR.\nA FORÇA PARA PROSSEGUIR É SABER \nQUE PARA SEMPRE CONTIGO VIVEREI.\n\n<coro tipo=''2X''>\nEXISTE UM LUGAR DE PAZ CELESTIAL (CELESTIAL).\nQUANDO OS MEUS PÉS ALI TOCAREM,\nSEI QUE AS LUTAS VÃO CESSAR, POIS ALI \nÉ LUGAR SANTO, MORADA DO SENHOR.\nE AQUELE QUE VENCER DE JESUS IRÁ OUVIR: \n''VINDE, BENDITOS DE MEU PAI''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (184, 'REDENTOR ONIPOTENTE', 'REDENTOR ONIPOTENTE', 'REDENTOR ONIPOTENTE,\nPODEROSO SALVADOR,\nREI DOS REIS, ONIPRESENTE\nÉ JESUS, MEU BOM SENHOR.\n\nCORO\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.\n\nÁGUA VIVA, PÃO DA VIDA!\nDOCE SOMBRA NO CALOR.\nE AO DESCANSO NOS CONVIDA\nÉ JESUS, MEU SALVADOR.\n\nCORO\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.\n\nO CORDEIRO IMACULADO,\nQUE SEU SANGUE DERRAMOU,\nMEUS PECADOS EXPIANDO,\nA MINH''ALMA RESGATOU.\n\nCORO\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.\n\nO CAMINHO QUE, SEGURO,\nSEMPRE PARA O CÉU CONDUZ\nQUEM A CRISTO PRONTO SEGUE,\nQUEM TOMAR A SUA CRUZ.\n\nCORO\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.', 'REDENTOR ONIPOTENTE,\nPODEROSO SALVADOR,\nREI DOS REIS, ONIPRESENTE\nÉ JESUS, MEU BOM SENHOR.\n\n<coro>\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.\n\nÁGUA VIVA, PÃO DA VIDA!\nDOCE SOMBRA NO CALOR.\nE AO DESCANSO NOS CONVIDA\nÉ JESUS, MEU SALVADOR.\n\n<coro>\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.\n\nO CORDEIRO IMACULADO,\nQUE SEU SANGUE DERRAMOU,\nMEUS PECADOS EXPIANDO,\nA MINH''ALMA RESGATOU.\n\n<coro>\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.\n\nO CAMINHO QUE, SEGURO,\nSEMPRE PARA O CÉU CONDUZ\nQUEM A CRISTO PRONTO SEGUE,\nQUEM TOMAR A SUA CRUZ.\n\n<coro>\nOH! REFÚGIO DA MINH''ALMA,\nTU ÉS TUDO PARA MIM!\nTUDO QUANTO EU CAREÇO,\nACHO, JESUS, SÓ EM TI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (185, 'JESUS, SENHOR, ME CHEGO A TI (EU VENHO COMO ESTOU)', 'JESUS, SENHOR, ME CHEGO A TI (EU VENHO COMO ESTOU)', 'JESUS, SENHOR, ME CHEGO A TI,\nPERDÃO SUPLICO AGORA A TI,\nOH! DÁ-ME ALÍVIO MESMO AQUI,\nACEITA UM PECADOR!\n\nCORO\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.\n\nEU NADA POSSO MERECER,\nTU VÊS-ME PRESTES A MORRER,\nOH! NÃO ME DEIXES PERECER,\nACEITA UM PECADOR!\n\nCORO\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.\n\nOH! SEM DEMORA, SALVADOR,\nSOCORRE-ME POR TEU AMOR,\nPOIS TU, Ó CRISTO, ÉS MEU SENHOR,\nACEITA UM PECADOR!\n\nCORO\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.\n\nNADA DE BOM SE ACHA EM MIM,\nDE MEUS ESFORÇOS BREVE HÁ FIM;\nSE NÃO ME ACEITAS, AI DE MIM,\nACEITA UM PECADOR!\n\nCORO\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.', 'JESUS, SENHOR, ME CHEGO A TI,\nPERDÃO SUPLICO AGORA A TI,\nOH! DÁ-ME ALÍVIO MESMO AQUI,\nACEITA UM PECADOR!\n\n<coro>\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.\n\nEU NADA POSSO MERECER,\nTU VÊS-ME PRESTES A MORRER,\nOH! NÃO ME DEIXES PERECER,\nACEITA UM PECADOR!\n\n<coro>\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.\n\nOH! SEM DEMORA, SALVADOR,\nSOCORRE-ME POR TEU AMOR,\nPOIS TU, Ó CRISTO, ÉS MEU SENHOR,\nACEITA UM PECADOR!\n\n<coro>\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.\n\nNADA DE BOM SE ACHA EM MIM,\nDE MEUS ESFORÇOS BREVE HÁ FIM;\nSE NÃO ME ACEITAS, AI DE MIM,\nACEITA UM PECADOR!\n\n<coro>\nEU VENHO COMO ESTOU;\nEU VENHO COMO ESTOU;\nPORQUE JESUS POR MIM MORREU;\nEU VENHO COMO ESTOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (186, 'PARA QUEM IREMOS NÓS?', 'PARA QUEM IREMOS NÓS?', 'PARA QUEM IREMOS NÓS?\nSÓ TU, SENHOR, \nTENS AS PALAVRAS DE VIDA ETERNA.\n\nNÃO HÁ OUTRO AMOR MAIOR\nQUE O TEU AMOR, JESUS,\nDEMONSTRADO ALI NA CRUZ\nPARA NOS SALVAR.\n\nINSTRUMENTOS\n\nMEU CORAÇÃO A TI ENTREGO,\nA MINHA VIDA \nDEPOSITO EM TEU ALTAR.\n\nTODA A MINHA ADORAÇÃO\nQUERO TE OFERTAR,\nEM SACRIFÍCIO (EM SACRIFÍCIO) \nVIVO EM TEU ALTAR (EM TEU ALTAR)\n\nEM SACRIFÍCIO (EM SACRIFÍCIO)\nVIVO EM TEU ALTAR.', 'PARA QUEM IREMOS NÓS?\nSÓ TU, SENHOR, \nTENS AS PALAVRAS DE VIDA ETERNA.\n\nNÃO HÁ OUTRO AMOR MAIOR<bis>\nQUE O TEU AMOR, JESUS,<bis>\nDEMONSTRADO ALI NA CRUZ<bis>\nPARA NOS SALVAR.<bis>\n<instrumentos>\n\n\nMEU CORAÇÃO A TI ENTREGO,\nA MINHA VIDA \nDEPOSITO EM TEU ALTAR.\n\nTODA A MINHA ADORAÇÃO<bis>\nQUERO TE OFERTAR,<bis>\nEM SACRIFÍCIO (EM SACRIFÍCIO) <bis>\nVIVO EM TEU ALTAR (EM TEU ALTAR)<bis>\n<bis>\nEM SACRIFÍCIO (EM SACRIFÍCIO)<bis>\nVIVO EM TEU ALTAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (187, 'MINH ́ALMA TEM SEDE DE TI', 'MINH ́ALMA TEM SEDE DE TI', 'MINH''ALMA TEM SEDE DE TI,\nTE QUERO COM TODO O MEU SER!\nNUMA TERRA SECA E SEM PAZ,\nMINHA VOZ CLAMA POR DEUS,\nSÓ TUA PRESENÇA, SENHOR,\nME SATISFAZ!\n\nPOR ISSO VENHO, SENHOR,\nAO TEU SANTUÁRIO\nTUA GLÓRIA CONTEMPLAR!\nTE DOU MEU LOUVOR,\nTE DOU MEU AMOR,\nMINHA VIDA PONHO EM TEU ALTAR,\nEU TE AMO, MEU SENHOR!\n\nFINAL: \nSENHOR, EU VENHO TE ADORAR!', 'MINH''ALMA TEM SEDE DE TI,\nTE QUERO COM TODO O MEU SER!\nNUMA TERRA SECA E SEM PAZ,\nMINHA VOZ CLAMA POR DEUS,\nSÓ TUA PRESENÇA, SENHOR,\nME SATISFAZ!\n\nPOR ISSO VENHO, SENHOR,<bis>\nAO TEU SANTUÁRIO<bis>\nTUA GLÓRIA CONTEMPLAR!<bis>\nTE DOU MEU LOUVOR,<bis>\nTE DOU MEU AMOR,<bis>\nMINHA VIDA PONHO EM TEU ALTAR,<bis>\nEU TE AMO, MEU SENHOR!\n<final>SENHOR, EU VENHO TE ADORAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (188, 'VENHO, SENHOR, MINHA VIDA OFERECER', 'VENHO, SENHOR, MINHA VIDA OFERECER', 'VENHO, SENHOR, \nMINHA VIDA OFERECER\nCOMO OFERTA DE AMOR \nE SACRIFÍCIO;\nQUERO MINHA VIDA A TI ENTREGAR\nCOMO OFERTA VIVA \nEM TEU ALTAR.\n\nPOIS, PRA TE ADORAR FOI QUE EU NASCI;\nCUMPRE EM MIM O TEU QUERER,\nFAÇA O QUE ESTÁ EM TEU CORAÇÃO,\nE QUE A CADA DIA EU QUEIRA MAIS \nE MAIS ESTAR AO TEU LADO, SENHOR\n\nE QUE A CADA DIA\nEU QUEIRA MAIS E MAIS\nESTAR AO TEU LADO, SENHOR.\n(ESTAR AO TEU LADO) SENHOR.', 'VENHO, SENHOR, <bis>\nMINHA VIDA OFERECER<bis>\nCOMO OFERTA DE AMOR <bis>\nE SACRIFÍCIO;<bis>\nQUERO MINHA VIDA A TI ENTREGAR<bis>\nCOMO OFERTA VIVA <bis>\nEM TEU ALTAR.<bis>\n\nPOIS, PRA TE ADORAR FOI QUE EU NASCI;<bis>\nCUMPRE EM MIM O TEU QUERER,<bis>\nFAÇA O QUE ESTÁ EM TEU CORAÇÃO,<bis>\nE QUE A CADA DIA EU QUEIRA MAIS <bis>\nE MAIS ESTAR AO TEU LADO, SENHOR<bis>\n\nE QUE A CADA DIA\nEU QUEIRA MAIS E MAIS\nESTAR AO TEU LADO, SENHOR.\n(ESTAR AO TEU LADO) SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (189, 'DEPENDO DE TI, SENHOR', 'DEPENDO DE TI, SENHOR', 'DEPENDO DE TI, SENHOR,\nQUE SEJAS ASSIM EM MEU VIVER:\nTOMA O MEU CORAÇÃO,\nTOTALMENTE DOMINA, Ó SENHOR!\n\nNÃO QUERO ANDAR INDEPENDENTE, \nSENHOR, POIS TUA VONTADE \nÉ VIDA PARA O MEU CORAÇÃO.\n\nDEPENDO DE TI, SENHOR,\nNÃO POSSO ANDAR SEM TEU BRAÇO FORTE;\nSEM TUA VONTADE HAVERÁ AGONIA,\nTRISTEZA E MORTE.\n\nFINAL: (2X)\nDEPENDO DE TI, SENHOR,\nDEPENDO DE TI,\nDEPENDO DE TI, AMÉM.', 'DEPENDO DE TI, SENHOR,\nQUE SEJAS ASSIM EM MEU VIVER:\nTOMA O MEU CORAÇÃO,\nTOTALMENTE DOMINA, Ó SENHOR!\n\nNÃO QUERO ANDAR INDEPENDENTE, \nSENHOR, POIS TUA VONTADE \nÉ VIDA PARA O MEU CORAÇÃO.\n\nDEPENDO DE TI, SENHOR,\nNÃO POSSO ANDAR SEM TEU BRAÇO FORTE;\nSEM TUA VONTADE HAVERÁ AGONIA,\nTRISTEZA E MORTE.\n<final>(<bis tipo=''2''>\nDEPENDO DE TI, SENHOR,\nDEPENDO DE TI,\nDEPENDO DE TI, AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (190, 'TODO O MEU SER TE AMA', 'TODO O MEU SER TE AMA', 'TODO O MEU SER TE AMA\nE MINH''ALMA TE ADORA,\nTU ÉS MEU PASTOR, SALVADOR, \nÉS O MEU VIVER\nE TE AMO MUITO \nMAIS QUE POSSA DIZER.\n\nTU ÉS REI ACIMA DE TODOS OS REIS,\nTUA MORADA É ETERNA, SENHOR;\nTU HABITAS DENTRO EM MIM,\nBEM MAIOR NÃO POSSO TER\nPOIS TU ÉS SANTO, ÉS PODEROSO,\nTU ÉS JESUS, SENHOR E REI.\n\nTODO O MEU SER TE AMA E MINH''ALMA \nTE ADORA, TU ÉS MEU PASTOR SALVADOR, \nÉS O MEU VIVER\nE TE AMO MUITO MAIS QUE POSSA DIZER.', 'TODO O MEU SER TE AMA<bis>\nE MINH''ALMA TE ADORA,<bis>\nTU ÉS MEU PASTOR, SALVADOR, <bis>\nÉS O MEU VIVER<bis>\nE TE AMO MUITO <bis>\nMAIS QUE POSSA DIZER.<bis>\n\nTU ÉS REI ACIMA DE TODOS OS REIS,\nTUA MORADA É ETERNA, SENHOR;\nTU HABITAS DENTRO EM MIM,\nBEM MAIOR NÃO POSSO TER\nPOIS TU ÉS SANTO, ÉS PODEROSO,\nTU ÉS JESUS, SENHOR E REI.\n\nTODO O MEU SER TE AMA E MINH''ALMA \nTE ADORA, TU ÉS MEU PASTOR SALVADOR, \nÉS O MEU VIVER\nE TE AMO MUITO MAIS QUE POSSA DIZER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (191, 'EU QUERO SENTIR', 'EU QUERO SENTIR', 'EU QUERO SENTIR MAIS UMA VEZ\nO AMOR DE DEUS AGINDO EM MINHA VIDA.\nVIM PRA DIZER: ME ARREPENDI,\nME PERDOA, SÓ AO TEU LADO \nEU SEI QUE POSSO SER FELIZ.\n\nME LEMBRO DE QUANDO OUVI A TUA VOZ\n(OUVI A TUA VOZ) \nFALANDO AO MEU CORAÇÃO \nPELA PRIMEIRA VEZ, FOI TÃO FORTE \n(FOI TÃO FORTE) \nMARAVILHOSO, SIM! QUEM UM DIA \nO CONHECEU NUNCA \nPODE SE ESQUECER.\n\nCORO\nVOLTEI PRA TI MEU PAI PROS BRAÇOS TEUS\nCOM O CORAÇÃO CARENTE E FERIDO;\nEU RECONHEÇO QUE SEM TI NADA SOU.\n\nINSTRUMENTOS\n\nME LEMBRO DE QUANDO OUVI A TUA VOZ\n(OUVI A TUA VOZ) \nFALANDO AO MEU CORAÇÃO \nPELA PRIMEIRA VEZ, FOI TÃO FORTE \n(FOI TÃO FORTE) \nMARAVILHOSO, SIM! QUEM UM DIA \nO CONHECEU NUNCA \nPODE SE ESQUECER.\n\nCORO\nVOLTEI PRA TI MEU PAI PROS BRAÇOS TEUS\nCOM O CORAÇÃO CARENTE E FERIDO;\nEU RECONHEÇO QUE SEM TI NADA SOU.', 'EU QUERO SENTIR MAIS UMA VEZ\nO AMOR DE DEUS AGINDO EM MINHA VIDA.\nVIM PRA DIZER: ME ARREPENDI,\nME PERDOA, SÓ AO TEU LADO \nEU SEI QUE POSSO SER FELIZ.\n\nME LEMBRO DE QUANDO OUVI A TUA VOZ\n(OUVI A TUA VOZ) \nFALANDO AO MEU CORAÇÃO \nPELA PRIMEIRA VEZ, FOI TÃO FORTE \n(FOI TÃO FORTE) \nMARAVILHOSO, SIM! QUEM UM DIA \nO CONHECEU NUNCA \nPODE SE ESQUECER.\n\n<coro>\nVOLTEI PRA TI MEU PAI PROS BRAÇOS TEUS\nCOM O CORAÇÃO CARENTE E FERIDO;\nEU RECONHEÇO QUE SEM TI NADA SOU.\n<instrumentos>\n\n\nME LEMBRO DE QUANDO OUVI A TUA VOZ\n(OUVI A TUA VOZ) \nFALANDO AO MEU CORAÇÃO \nPELA PRIMEIRA VEZ, FOI TÃO FORTE \n(FOI TÃO FORTE) \nMARAVILHOSO, SIM! QUEM UM DIA \nO CONHECEU NUNCA \nPODE SE ESQUECER.\n\n<coro>\nVOLTEI PRA TI MEU PAI PROS BRAÇOS TEUS\nCOM O CORAÇÃO CARENTE E FERIDO;\nEU RECONHEÇO QUE SEM TI NADA SOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (192, 'JESUS, JESUS, EU TE AMO', 'JESUS, JESUS, EU TE AMO', 'JESUS, JESUS, EU TE AMO,\nÓ MEU SALVADOR;\nEU TE QUERO, EU TE ESPERO, \nSENHOR, DEUS DE AMOR!', 'JESUS, JESUS, EU TE AMO,<bis>\nÓ MEU SALVADOR;<bis>\nEU TE QUERO, EU TE ESPERO, <bis>\nSENHOR, DEUS DE AMOR!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (193, 'AS MUITAS ÁGUAS NÃO PODERIAM APAGAR', 'AS MUITAS ÁGUAS NÃO PODERIAM APAGAR', 'AS MUITAS ÁGUAS NÃO PODERIAM \nAPAGAR ESTE AMOR,\nNEM OS RIOS O AFOGARÃO;\nAINDA QUE ALGUÉM \nDESSE OS BENS DE SUA CASA,\nPOR ESTE AMOR, \nOS DESPREZARIA.\n\nCORO (2X)\nE É ASSIM O AMOR DE DEUS,\nINDESCRITÍVEL, INSONDÁVEL \nÉ ESTE AMOR.\n\nINSTRUMENTOS\n\nAS MUITAS ÁGUAS NÃO PODERIAM \nAPAGAR ESTE AMOR,\nNEM OS RIOS O AFOGARÃO;\nAINDA QUE ALGUÉM \nDESSE OS BENS DE SUA CASA,\nPOR ESTE AMOR, \nOS DESPREZARIA.\n\nCORO (2X)\nE É ASSIM O AMOR DE DEUS,\nINDESCRITÍVEL, INSONDÁVEL \nÉ ESTE AMOR.\n\nFINAL: DO MEU JESUS.', 'AS MUITAS ÁGUAS NÃO PODERIAM \nAPAGAR ESTE AMOR,\nNEM OS RIOS O AFOGARÃO;\nAINDA QUE ALGUÉM \nDESSE OS BENS DE SUA CASA,\nPOR ESTE AMOR, \nOS DESPREZARIA.\n\n<coro tipo=''2X''>\nE É ASSIM O AMOR DE DEUS,\nINDESCRITÍVEL, INSONDÁVEL \nÉ ESTE AMOR.\n<instrumentos>\n\n\nAS MUITAS ÁGUAS NÃO PODERIAM \nAPAGAR ESTE AMOR,\nNEM OS RIOS O AFOGARÃO;\nAINDA QUE ALGUÉM \nDESSE OS BENS DE SUA CASA,\nPOR ESTE AMOR, \nOS DESPREZARIA.\n\n<coro tipo=''2X''>\nE É ASSIM O AMOR DE DEUS,\nINDESCRITÍVEL, INSONDÁVEL \nÉ ESTE AMOR.\n<final>DO MEU JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (194, 'QUERO ANDAR EM TEU CAMINHO, SENHOR', 'QUERO ANDAR EM TEU CAMINHO, SENHOR', 'QUERO ANDAR EM TEU CAMINHO, \nSENHOR, MAIS E MAIS TE CONHECER\nE FAZER TUA VONTADE, SENHOR;\nTUA VOZ OBEDECER E VIVER SOMENTE \nPRA TEU LOUVOR, DESFRUTANDO \nDO TEU GRANDE AMOR;\nQUERO SER FIEL, QUERO SER FIEL\nA TI, SENHOR.\n\nCORO\nTE AGRADEÇO POR PRIMEIRO ME AMAR,\nTE AGRADEÇO POR ME ESCOLHER,\nTE AGRADEÇO (TE AGRADEÇO, MEU SENHOR) \nTE AGRADEÇO, POIS NÃO SOU MERECEDOR.\n\nFAZE EM MIM (FAZE EM MIM) \nO TEU QUERER, Ó SENHOR (TEU QUERER) \nQUERO SER UM VENCEDOR (VENCEDOR) \nPRA QUE EU POSSA DIZER (PRA QUE EU POSSA DIZER) \nQUE TU VIVES EM MIM\nE DA MINHA VIDA TU ÉS O SENHOR.\n\nCORO\nTE AGRADEÇO POR PRIMEIRO ME AMAR,\nTE AGRADEÇO POR ME ESCOLHER,\nTE AGRADEÇO (TE AGRADEÇO, MEU SENHOR) \nTE AGRADEÇO, POIS NÃO SOU MERECEDOR.\n\nFINAL: \nTE AGRADEÇO \n(TE AGRADEÇO, MEU SENHOR) \nTE AGRADEÇO, POIS NÃO SOU MERECEDOR.', 'QUERO ANDAR EM TEU CAMINHO, \nSENHOR, MAIS E MAIS TE CONHECER\nE FAZER TUA VONTADE, SENHOR;\nTUA VOZ OBEDECER E VIVER SOMENTE \nPRA TEU LOUVOR, DESFRUTANDO \nDO TEU GRANDE AMOR;\nQUERO SER FIEL, QUERO SER FIEL\nA TI, SENHOR.\n\n<coro>\nTE AGRADEÇO POR PRIMEIRO ME AMAR,\nTE AGRADEÇO POR ME ESCOLHER,\nTE AGRADEÇO (TE AGRADEÇO, MEU SENHOR) \nTE AGRADEÇO, POIS NÃO SOU MERECEDOR.\n\nFAZE EM MIM (FAZE EM MIM) \nO TEU QUERER, Ó SENHOR (TEU QUERER) \nQUERO SER UM VENCEDOR (VENCEDOR) \nPRA QUE EU POSSA DIZER (PRA QUE EU POSSA DIZER) \nQUE TU VIVES EM MIM\nE DA MINHA VIDA TU ÉS O SENHOR.\n\n<coro>\nTE AGRADEÇO POR PRIMEIRO ME AMAR,\nTE AGRADEÇO POR ME ESCOLHER,\nTE AGRADEÇO (TE AGRADEÇO, MEU SENHOR) \nTE AGRADEÇO, POIS NÃO SOU MERECEDOR.\n\n\n<final>TE AGRADEÇO \n(TE AGRADEÇO, MEU SENHOR) \nTE AGRADEÇO, POIS NÃO SOU MERECEDOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (195, 'GRANDE AMOR, Ó GRANDE AMOR', 'GRANDE AMOR, Ó GRANDE AMOR', 'GRANDE AMOR, Ó GRANDE AMOR,\nÉ O AMOR DE DEUS.\nESTE AMOR QUE HABITA EM MIM,\nPELA FÉ EM DEUS.\nCOMO POSSO COMPREENDER\nA GRANDEZA DO AMOR DE DEUS.\nQUE PROFUNDO É ESSE GRANDE AMOR\nQUE PREENCHE TODO MEU SER.\n\nCORO\nGRANDE AMOR, É O AMOR DE DEUS\nQUE EXCEDE TODO SABER\nOH! QUE SUBLIME!\nNÃO POSSO COMPREENDER,\nPORQUE ME AMOU SEM MERECER.\n\nQUANDO TUDO PARECE ACABAR\nE A ESPERANÇA DESVANECER.\nQUANDO A FÉ PARECE NAUFRAGAR\nE O DIA ESCURECER.\nMESMO ASSIM CONFIO NESTE AMOR,\nQUE É MAIS FORTE QUE A PRÓPRIA MORTE.\nAS MUITAS ÁGUAS NÃO PODEM APAGAR,\nNEM OS RIOS O AFOGARÃO.\n\nCORO\nGRANDE AMOR, É O AMOR DE DEUS\nQUE EXCEDE TODO SABER\nOH! QUE SUBLIME!\nNÃO POSSO COMPREENDER,\nPORQUE ME AMOU SEM MERECER.\n\nFINAL: GRANDE AMOR DE DEUS.', 'GRANDE AMOR, Ó GRANDE AMOR,\nÉ O AMOR DE DEUS.\nESTE AMOR QUE HABITA EM MIM,\nPELA FÉ EM DEUS.\nCOMO POSSO COMPREENDER\nA GRANDEZA DO AMOR DE DEUS.\nQUE PROFUNDO É ESSE GRANDE AMOR\nQUE PREENCHE TODO MEU SER.\n\n<coro>\nGRANDE AMOR, É O AMOR DE DEUS\nQUE EXCEDE TODO SABER\nOH! QUE SUBLIME!\nNÃO POSSO COMPREENDER,\nPORQUE ME AMOU SEM MERECER.\n\nQUANDO TUDO PARECE ACABAR\nE A ESPERANÇA DESVANECER.\nQUANDO A FÉ PARECE NAUFRAGAR\nE O DIA ESCURECER.\nMESMO ASSIM CONFIO NESTE AMOR,\nQUE É MAIS FORTE QUE A PRÓPRIA MORTE.\nAS MUITAS ÁGUAS NÃO PODEM APAGAR,\nNEM OS RIOS O AFOGARÃO.\n\n<coro>\nGRANDE AMOR, É O AMOR DE DEUS\nQUE EXCEDE TODO SABER\nOH! QUE SUBLIME!\nNÃO POSSO COMPREENDER,\nPORQUE ME AMOU SEM MERECER.\n<final>GRANDE AMOR DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (196, 'O GRANDE AMOR DO MEU SENHOR', 'O GRANDE AMOR DO MEU SENHOR', 'O GRANDE AMOR DO MEU SENHOR (M)\nO REI DE TODO UNIVERSO! (H)\nJESUS, O SOBERANO DEUS,\nRESPLANDECENTE ESTRELA DA MANHÃ!\n\nCOMO ENTENDER QUE MEU JESUS,\nUM DIA OLHOU PRA MIM,\nE SEM QUERER NADA EM TROCA,\nTÃO GRANDE AMOR ME DEU, \nO MEU SENHOR VIDA ETERNA DEU, \nMEU SALVADOR!\n\nCORO\nABENÇOADOR, DEUS DE PAZ,\nCONSOLADOR, MEU REI E SENHOR.\nHOMEM SE FEZ, MORREU EM MEU LUGAR\nMEU REDENTOR, MINHA ESPERANÇA.\nMINHA ESPERANÇA É!\n\nCOMO ENTENDER QUE MEU JESUS\nUM DIA OLHOU PRA MIM, \nE SEM QUERER NADA EM TROCA, \nTÃO GRANDE AMOR ME DEU O MEU SENHOR!\nVIDA ETERNA DEU, MEU SALVADOR.\n\nCORO\nABENÇOADOR, DEUS DE PAZ,\nCONSOLADOR, MEU REI E SENHOR.\nHOMEM SE FEZ, MORREU EM MEU LUGAR\nMEU REDENTOR, MINHA ESPERANÇA.\nMINHA ESPERANÇA É!\n\nA ROCHA FIRME, (A ROCHA FIRME)\nREFÚGIO SEGURO, (REFÚGIO SEGURO)\nA MINHA ALEGRIA, MEU LOUVOR\nÉ SÓ PRA TI MEU GRANDE EU SOU!\n\nCORO\nABENÇOADOR, DEUS DE PAZ,\nCONSOLADOR, MEU REI E SENHOR.\nHOMEM SE FEZ, MORREU EM MEU LUGAR\nMEU REDENTOR, MINHA ESPERANÇA.\nMINHA ESPERANÇA É!\n\nFINAL:\nO REI DO UNIVERSO,\n(UM DIA OLHOU PRA MIM)\nO MEU GRANDE EU SOU, JESUS.', 'O GRANDE AMOR DO MEU SENHOR <m>\nO REI DE TODO UNIVERSO! <h>\nJESUS, O SOBERANO DEUS,\nRESPLANDECENTE ESTRELA DA MANHÃ!\n\nCOMO ENTENDER QUE MEU JESUS,\nUM DIA OLHOU PRA MIM,\nE SEM QUERER NADA EM TROCA,\nTÃO GRANDE AMOR ME DEU, \nO MEU SENHOR VIDA ETERNA DEU, \nMEU SALVADOR!\n\n<coro>\nABENÇOADOR, DEUS DE PAZ,\nCONSOLADOR, MEU REI E SENHOR.\nHOMEM SE FEZ, MORREU EM MEU LUGAR\nMEU REDENTOR, MINHA ESPERANÇA.\nMINHA ESPERANÇA É!\n\nCOMO ENTENDER QUE MEU JESUS\nUM DIA OLHOU PRA MIM, \nE SEM QUERER NADA EM TROCA, \nTÃO GRANDE AMOR ME DEU O MEU SENHOR!\nVIDA ETERNA DEU, MEU SALVADOR.\n\n<coro>\nABENÇOADOR, DEUS DE PAZ,\nCONSOLADOR, MEU REI E SENHOR.\nHOMEM SE FEZ, MORREU EM MEU LUGAR\nMEU REDENTOR, MINHA ESPERANÇA.\nMINHA ESPERANÇA É!\n\nA ROCHA FIRME, (A ROCHA FIRME)\nREFÚGIO SEGURO, (REFÚGIO SEGURO)\nA MINHA ALEGRIA, MEU LOUVOR\nÉ SÓ PRA TI MEU GRANDE EU SOU!\n\n<coro>\nABENÇOADOR, DEUS DE PAZ,\nCONSOLADOR, MEU REI E SENHOR.\nHOMEM SE FEZ, MORREU EM MEU LUGAR\nMEU REDENTOR, MINHA ESPERANÇA.\nMINHA ESPERANÇA É!\n\n\n<final>O REI DO UNIVERSO,\n(UM DIA OLHOU PRA MIM)\nO MEU GRANDE EU SOU, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (197, 'HOJE QUERO SOMENTE AGRADECER (SOMENTE AGRADECER)', 'HOJE QUERO SOMENTE AGRADECER (SOMENTE AGRADECER)', 'HOJE QUERO SOMENTE AGRADECER A TI.\nHOJE NADA QUERO TE PEDIR.\nRECEBE O MEU LOUVOR, MINHA GRATIDÃO.\n\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\n\nHOJE QUERO SOMENTE AGRADECER A TI.\nHOJE NADA QUERO TE PEDIR.\nRECEBE O MEU LOUVOR, MINHA GRATIDÃO.\n\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\n\nPELA FÉ EU VOU SEGURO EM TUAS MÃOS,\nPELA FÉ ALCANÇAREI A SALVAÇÃO.\nMOSTRA-ME A DIREÇÃO.\n\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS\nPRECISO DE TI, PAI (DIRIGE MEUS PASSOS).\nESTE MOMENTO É PRA TUA ADORAÇÃO\n\nFINAL: TUA ADORAÇÃO.', 'HOJE QUERO SOMENTE AGRADECER A TI.\nHOJE NADA QUERO TE PEDIR.\nRECEBE O MEU LOUVOR, MINHA GRATIDÃO.\n\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\n\nHOJE QUERO SOMENTE AGRADECER A TI.\nHOJE NADA QUERO TE PEDIR.\nRECEBE O MEU LOUVOR, MINHA GRATIDÃO.\n\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS.\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\nGUIA-ME, SENHOR (GUIA-ME, SENHOR)\n\nPELA FÉ EU VOU SEGURO EM TUAS MÃOS,\nPELA FÉ ALCANÇAREI A SALVAÇÃO.\nMOSTRA-ME A DIREÇÃO.\n\nESTOU AQUI, PAI (SÓ TU ME CONHECES).\nQUERO SERVIR-TE MAIS E MAIS\nPRECISO DE TI, PAI (DIRIGE MEUS PASSOS).\nESTE MOMENTO É PRA TUA ADORAÇÃO\n<final>TUA ADORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (197, 'HOJE QUERO SOMENTE AGRADECER (SOMENTE AGRADECER)', 'HOJE QUERO SOMENTE AGRADECER (SOMENTE AGRADECER)', 'HOJE QUERO SOMENTE AGRADECER A TI.\nHOJE NADA QUERO TE PEDIR.\nRECEBE O MEU LOUVOR, MINHA GRATIDÃO.\n\nELE É A MINHA ALEGRIA,\nMESMO EM MOMENTOS DIFÍCEIS,\nELE SEGURA MINHA MÃO.\nELE É A MINHA SEGURANÇA,\nMESMO EM TEMPOS DE GUERRA,\nELE É QUEM ME DÁ A PAZ.\n\n198 - ELE É A MINHA ALEGRIA\n\nSENHOR, TU ÉS A MINHA FORTALEZA.\nJESUS, TU ÉS A MINHA DEFESA,\nÉS MEU ESCUDO E PROTEÇÃO.\nSENHOR, TU ÉS A ROCHA FERIDA,\nTU ÉS A FONTE DA VIDA,\nBROTANDO ÁGUAS DA SALVAÇÃO.\nSENHOR, TU ÉS O MEU ALIMENTO,\nDE TI PROVÉM TODO SUSTENTO,\nÉS MINHA ÁGUA, ÉS MEU PÃO.\n\nINSTRUMENTOS\n\nELE É A MINHA ALEGRIA,\nMESMO EM MOMENTOS DIFÍCEIS,\nELE SEGURA MINHA MÃO.\nELE É A MINHA SEGURANÇA,\nMESMO EM TEMPOS DE GUERRA,\nELE É QUEM ME DÁ A PAZ.\n\nSENHOR, TU ÉS A MINHA FORTALEZA.\nJESUS, TU ÉS A MINHA DEFESA,\nÉS MEU ESCUDO E PROTEÇÃO.\nSENHOR, TU ÉS A ROCHA FERIDA,\nTU ÉS A FONTE DA VIDA,\nBROTANDO ÁGUAS DA SALVAÇÃO.\nSENHOR, TU ÉS O MEU ALIMENTO,\nDE TI PROVÉM TODO SUSTENTO,\nÉS MINHA ÁGUA, ÉS MEU PÃO.\n\nFINAL: \nSÓ TU ÉS, SENHOR, A VIDA DO TEU POVO.\nEM MEIO A TREVAS, A LUZ,\nÉS O CAMINHO, JESUS (BIS)', 'HOJE QUERO SOMENTE AGRADECER A TI.\nHOJE NADA QUERO TE PEDIR.\nRECEBE O MEU LOUVOR, MINHA GRATIDÃO.\n\nELE É A MINHA ALEGRIA,\nMESMO EM MOMENTOS DIFÍCEIS,\nELE SEGURA MINHA MÃO.\nELE É A MINHA SEGURANÇA,\nMESMO EM TEMPOS DE GUERRA,\nELE É QUEM ME DÁ A PAZ.\n\n198 - ELE É A MINHA ALEGRIA\n\nSENHOR, TU ÉS A MINHA FORTALEZA.\nJESUS, TU ÉS A MINHA DEFESA,\nÉS MEU ESCUDO E PROTEÇÃO.\nSENHOR, TU ÉS A ROCHA FERIDA,\nTU ÉS A FONTE DA VIDA,\nBROTANDO ÁGUAS DA SALVAÇÃO.\nSENHOR, TU ÉS O MEU ALIMENTO,\nDE TI PROVÉM TODO SUSTENTO,\nÉS MINHA ÁGUA, ÉS MEU PÃO.\n<instrumentos>\n\n\nELE É A MINHA ALEGRIA,\nMESMO EM MOMENTOS DIFÍCEIS,\nELE SEGURA MINHA MÃO.\nELE É A MINHA SEGURANÇA,\nMESMO EM TEMPOS DE GUERRA,\nELE É QUEM ME DÁ A PAZ.\n\nSENHOR, TU ÉS A MINHA FORTALEZA.\nJESUS, TU ÉS A MINHA DEFESA,\nÉS MEU ESCUDO E PROTEÇÃO.\nSENHOR, TU ÉS A ROCHA FERIDA,\nTU ÉS A FONTE DA VIDA,\nBROTANDO ÁGUAS DA SALVAÇÃO.\nSENHOR, TU ÉS O MEU ALIMENTO,\nDE TI PROVÉM TODO SUSTENTO,\nÉS MINHA ÁGUA, ÉS MEU PÃO.\n\n\n<final>SÓ TU ÉS, SENHOR, A VIDA DO TEU POVO.\nEM MEIO A TREVAS, A LUZ,\nÉS O CAMINHO, JESUS <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (199, 'COMO É BOM OUVIR TUA VOZ', 'COMO É BOM OUVIR TUA VOZ', 'COMO É BOM OUVIR TUA VOZ, SENHOR, \nCOMO É BOM SENTIR TUA PRESENÇA. \nO TEU AMOR NOS CONSOLA, \nNOS RENOVA A CADA DIA, \nSENHOR, GLORIOSO ÉS TU!\n\nCORO\nNÓS TE LOUVAMOS, SENHOR JESUS,\nPOR TEU AMOR DEMONSTRADO NA CRUZ.\nAMOR GRANDIOSO, PODEROSO,\nE QUE NOS DARÁ A VIDA ETERNA.\n\nINSTRUMENTOS\n\nCORO\nNÓS TE LOUVAMOS, SENHOR JESUS,\nPOR TEU AMOR DEMONSTRADO NA CRUZ.\nAMOR GRANDIOSO, PODEROSO,\nE QUE NOS DARÁ A VIDA ETERNA.\n\nFINAL: VIDA ETERNA.', 'COMO É BOM OUVIR TUA VOZ, SENHOR, <bis>\nCOMO É BOM SENTIR TUA PRESENÇA. <bis>\nO TEU AMOR NOS CONSOLA, <bis>\nNOS RENOVA A CADA DIA, <bis>\nSENHOR, GLORIOSO ÉS TU!<bis>\n\n<coro>\nNÓS TE LOUVAMOS, SENHOR JESUS,\nPOR TEU AMOR DEMONSTRADO NA CRUZ.\nAMOR GRANDIOSO, PODEROSO,\nE QUE NOS DARÁ A VIDA ETERNA.\n<instrumentos>\n\n\n<coro>\nNÓS TE LOUVAMOS, SENHOR JESUS,<bis>\nPOR TEU AMOR DEMONSTRADO NA CRUZ.<bis>\nAMOR GRANDIOSO, PODEROSO,<bis>\nE QUE NOS DARÁ A VIDA ETERNA.<bis>\n<final>VIDA ETERNA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (200, 'EU SIRVO UM DEUS', 'EU SIRVO UM DEUS', 'EU SIRVO UM DEUS QUE É TÃO BOM PRA MIM,\nEU SIRVO UM DEUS QUE É MEU TUDO ENFIM.\nEU SIRVO UM DEUS QUE AO MEU LADO ESTÁ,\nEU SIRVO UM DEUS QUE AO CÉU ME LEVARÁ.\n\nCORO\nOH! ALELUIA, NÓS SERVIMOS A UM DEUS VIVO,\nQUE NOS LIVRA DOS PERIGOS,E NOS FAZ ASSIM CANTAR. OH! ALELUIA, \nNÓS SERVIMOS A UM DEUS VIVO, ELE É REI, ELE É AMIGO, COMO NOSSO DEUS NÃO HÁ.\n\nEU SIRVO UM DEUS QUE ABRIU O MAR VERMELHO,\nEU SIRVO UM DEUS QUE AMOU O MUNDO INTEIRO.\nEU SIRVO UM DEUS QUE ENVIOU JESUS,\nEU SIRVO UM DEUS QUE É GRAÇA E LUZ.\n\nCORO\nOH! ALELUIA, NÓS SERVIMOS A UM DEUS VIVO,\nQUE NOS LIVRA DOS PERIGOS,E NOS FAZ ASSIM CANTAR. OH! ALELUIA, \nNÓS SERVIMOS A UM DEUS VIVO, ELE É REI, ELE É AMIGO, COMO NOSSO DEUS NÃO HÁ.\n\nFINAL: NÃO HÁ, NÃO HÁ.', 'EU SIRVO UM DEUS QUE É TÃO BOM PRA MIM,\nEU SIRVO UM DEUS QUE É MEU TUDO ENFIM.\nEU SIRVO UM DEUS QUE AO MEU LADO ESTÁ,\nEU SIRVO UM DEUS QUE AO CÉU ME LEVARÁ.\n\n<coro>\nOH! ALELUIA, NÓS SERVIMOS A UM DEUS VIVO,\nQUE NOS LIVRA DOS PERIGOS,E NOS FAZ ASSIM CANTAR. OH! ALELUIA, \nNÓS SERVIMOS A UM DEUS VIVO, ELE É REI, ELE É AMIGO, COMO NOSSO DEUS NÃO HÁ.\n\nEU SIRVO UM DEUS QUE ABRIU O MAR VERMELHO,\nEU SIRVO UM DEUS QUE AMOU O MUNDO INTEIRO.\nEU SIRVO UM DEUS QUE ENVIOU JESUS,\nEU SIRVO UM DEUS QUE É GRAÇA E LUZ.\n\n<coro>\nOH! ALELUIA, NÓS SERVIMOS A UM DEUS VIVO,\nQUE NOS LIVRA DOS PERIGOS,E NOS FAZ ASSIM CANTAR. OH! ALELUIA, \nNÓS SERVIMOS A UM DEUS VIVO, ELE É REI, ELE É AMIGO, COMO NOSSO DEUS NÃO HÁ.\n<final>NÃO HÁ, NÃO HÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (201, 'SEU CORPO CANSADO PELAS CAMINHADAS', 'SEU CORPO CANSADO PELAS CAMINHADAS', 'SEU CORPO CANSADO PELAS CAMINHADAS, PELAS MADRUGADAS PROSTRADO EM ORAÇÃO, MEU JESUS!\nCOM AMOR CURANDO, VIDAS LIBERTANDO, \nDANDO O PÃO DO CÉU À MULTIDÃO!\n\nCORO\nE SEM TER UM LUGAR PARA DESCANSAR,\nPERSEGUIDO COMO VIL MALFEITOR;\nPOR AMOR FOI À CRUZ SEM SE DEFENDER,\nPARA SER MEU SALVADOR!\n\nNÃO TINHA BELEZA PRA SER DESEJADO\nE FOI DESPREZADO POR UM POVO QUE ERA SEU, \nMEU JESUS!\nPOR DEUS AFLIGIDO, SOFREU O CASTIGO,\nPOR PECADO QUE NÃO COMETEU!\n\nCORO\nE SEM TER UM LUGAR PARA DESCANSAR,\nPERSEGUIDO COMO VIL MALFEITOR;\nPOR AMOR FOI À CRUZ SEM SE DEFENDER,\nPARA SER MEU SALVADOR!\n\nSEM TEMER A MORTE, SOB A DOR FOI FORTE, \nE BEBEU O CÁLICE QUE O PAI LHE PREPAROU, \nMEU JESUS!\nCOMO OVELHA MUDA FOI SACRIFICADO,\nSEU PRECIOSO SANGUE DERRAMOU!\n\nCORO\nE SEM TER UM LUGAR PARA DESCANSAR,\nPERSEGUIDO COMO VIL MALFEITOR;\nPOR AMOR FOI À CRUZ SEM SE DEFENDER,\nPARA SER MEU SALVADOR!', 'SEU CORPO CANSADO PELAS CAMINHADAS, PELAS MADRUGADAS PROSTRADO EM ORAÇÃO, MEU JESUS!\nCOM AMOR CURANDO, VIDAS LIBERTANDO, \nDANDO O PÃO DO CÉU À MULTIDÃO!\n\n<coro>\nE SEM TER UM LUGAR PARA DESCANSAR,\nPERSEGUIDO COMO VIL MALFEITOR;\nPOR AMOR FOI À CRUZ SEM SE DEFENDER,\nPARA SER MEU SALVADOR!\n\nNÃO TINHA BELEZA PRA SER DESEJADO\nE FOI DESPREZADO POR UM POVO QUE ERA SEU, \nMEU JESUS!\nPOR DEUS AFLIGIDO, SOFREU O CASTIGO,\nPOR PECADO QUE NÃO COMETEU!\n\n<coro>\nE SEM TER UM LUGAR PARA DESCANSAR,\nPERSEGUIDO COMO VIL MALFEITOR;\nPOR AMOR FOI À CRUZ SEM SE DEFENDER,\nPARA SER MEU SALVADOR!\n\nSEM TEMER A MORTE, SOB A DOR FOI FORTE, \nE BEBEU O CÁLICE QUE O PAI LHE PREPAROU, \nMEU JESUS!\nCOMO OVELHA MUDA FOI SACRIFICADO,\nSEU PRECIOSO SANGUE DERRAMOU!\n\n<coro>\nE SEM TER UM LUGAR PARA DESCANSAR,\nPERSEGUIDO COMO VIL MALFEITOR;\nPOR AMOR FOI À CRUZ SEM SE DEFENDER,\nPARA SER MEU SALVADOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (202, 'HÁ UMA FONTE ABERTA NO CALVÁRIO', 'HÁ UMA FONTE ABERTA NO CALVÁRIO', 'HÁ UMA FONTE ABERTA NO CALVÁRIO\nCONTRA A IMPUREZA E O PECADO;\nÁGUAS DE PERDÃO, PURIFICAÇÃO,\nFLUEM DE JESUS CRUCIFICADO.\n\nHÁ UMA FONTE ABERTA NO CALVÁRIO,\nONDE MEU SENHOR FOI TRASPASSADO,\nFONTE DE PODER PRA TODO O QUE CRER,\nPOR SUAS PISADURAS, SER CURADO.\n\nCORO\nTE AGRADEÇO, JESUS,\nPORQUE FOSTE À CRUZ\nPARA ABRIR ESTA FONTE DE VIDA E LUZ.\n\nPARA QUE EU VIVESSE, TU MORRESTE,\nPARA ME CURARES, ENFERMASTE!\nCORREM DO TEU LADO, Ó CRUCIFICADO,\nÁGUAS VIVAS COM QUE ME SALVASTE.', 'HÁ UMA FONTE ABERTA NO CALVÁRIO\nCONTRA A IMPUREZA E O PECADO;\nÁGUAS DE PERDÃO, PURIFICAÇÃO,\nFLUEM DE JESUS CRUCIFICADO.\n\nHÁ UMA FONTE ABERTA NO CALVÁRIO,\nONDE MEU SENHOR FOI TRASPASSADO,\nFONTE DE PODER PRA TODO O QUE CRER,\nPOR SUAS PISADURAS, SER CURADO.\n\n<coro>\nTE AGRADEÇO, JESUS,\nPORQUE FOSTE À CRUZ\nPARA ABRIR ESTA FONTE DE VIDA E LUZ.\n\nPARA QUE EU VIVESSE, TU MORRESTE,\nPARA ME CURARES, ENFERMASTE!\nCORREM DO TEU LADO, Ó CRUCIFICADO,\nÁGUAS VIVAS COM QUE ME SALVASTE.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (203, 'JESUS IA SUBINDO O MONTE', 'JESUS IA SUBINDO O MONTE', 'JESUS IA SUBINDO O MONTE,\nCARREGANDO A NOSSA CRUZ;\nNOSSO FARDO DE PECADO, \nSOBRE SI ELE LEVOU.\nELE NÃO TINHA PECADO,\nMAS POR NÓS JESUS MORREU,\nPRA NOS DAR A LIBERDADE, \nSUA VIDA ELE DEU.\n\nPOR NÓS JESUS MORREU, \nFOI POR AMOR\nQUE ELE SE ENTREGOU, \nAS NOSSAS DORES LEVOU\nE O PECADO PERDOOU.\n\nTODA LUZ SE ESCURECEU,\nO DIA EM TREVAS SE TORNOU,\nPOIS NAQUELA DURA CRUZ\nMORREU O FILHO DE DEUS.\n\nMAS ELE RESSUSCITOU,\nVENCEU A MORTE E A CRUZ, \nVENCEU O MAL, \nME LIBERTOU DO PESO\nQUE ANTES CARREGUEI,\nLEVOU AS NOSSAS DORES\nE A SALVAÇÃO NOS DEU.\n\nPOR NÓS JESUS MORREU, \nPOR NÓS RESSUSCITOU,\nO PREÇO DA LIBERDADE,\nCOM SEU SANGUE ELE PAGOU;\nPOR NÓS JESUS MORREU, \nPOR NÓS RESSUSCITOU,\nO PREÇO DA LIBERDADE,\nCOM SEU SANGUE ELE PAGOU.\nAMÉM! AMÉM!', 'JESUS IA SUBINDO O MONTE,\nCARREGANDO A NOSSA CRUZ;\nNOSSO FARDO DE PECADO, \nSOBRE SI ELE LEVOU.\nELE NÃO TINHA PECADO,\nMAS POR NÓS JESUS MORREU,\nPRA NOS DAR A LIBERDADE, \nSUA VIDA ELE DEU.\n\nPOR NÓS JESUS MORREU, \nFOI POR AMOR\nQUE ELE SE ENTREGOU, \nAS NOSSAS DORES LEVOU\nE O PECADO PERDOOU.\n\nTODA LUZ SE ESCURECEU,\nO DIA EM TREVAS SE TORNOU,\nPOIS NAQUELA DURA CRUZ\nMORREU O FILHO DE DEUS.\n\nMAS ELE RESSUSCITOU,<bis>\nVENCEU A MORTE E A CRUZ, <bis>\nVENCEU O MAL, <bis>\nME LIBERTOU DO PESO<bis>\nQUE ANTES CARREGUEI,<bis>\nLEVOU AS NOSSAS DORES<bis>\nE A SALVAÇÃO NOS DEU.<bis>\n\nPOR NÓS JESUS MORREU, \nPOR NÓS RESSUSCITOU,\nO PREÇO DA LIBERDADE,\nCOM SEU SANGUE ELE PAGOU;\nPOR NÓS JESUS MORREU, \nPOR NÓS RESSUSCITOU,\nO PREÇO DA LIBERDADE,\nCOM SEU SANGUE ELE PAGOU.\nAMÉM! AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (204, 'MORRI NA CRUZ POR TI', 'MORRI NA CRUZ POR TI', 'MORRI NA CRUZ POR TI,\nMORRI PRA TE LIVRAR;\nMEU SANGUE, SIM, VERTI\nE POSSO TE SALVAR.\n\nCORO (2X)\nMORRI, MORRI NA CRUZ POR TI, \nQUE FAZES TU POR MIM?\n\nVIVI ASSIM POR TI,\nCOM DOR, COM DISSABOR;\nSIM, TUDO FIZ AQUI\nPRA SER TEU SALVADOR.\n\nCORO (2X)\nMORRI, MORRI NA CRUZ POR TI, \nQUE FAZES TU POR MIM?\n\nEU TROUXE A SALVAÇÃO,\nDOS ALTOS CÉUS LOUVOR,\nÉ LIVRE MEU PERDÃO,\nÉ GRANDE MEU AMOR.\n\nCORO (2X)\nMORRI, MORRI NA CRUZ POR TI,\nQUE FAZES TU POR MIM', 'MORRI NA CRUZ POR TI,\nMORRI PRA TE LIVRAR;\nMEU SANGUE, SIM, VERTI\nE POSSO TE SALVAR.<coro tipo=''2X''>\nMORRI, MORRI NA CRUZ POR TI, \nQUE FAZES TU POR MIM?\n\nVIVI ASSIM POR TI,\nCOM DOR, COM DISSABOR;\nSIM, TUDO FIZ AQUI\nPRA SER TEU SALVADOR.<coro tipo=''2X''>\nMORRI, MORRI NA CRUZ POR TI, \nQUE FAZES TU POR MIM?\n\nEU TROUXE A SALVAÇÃO,\nDOS ALTOS CÉUS LOUVOR,\nÉ LIVRE MEU PERDÃO,\nÉ GRANDE MEU AMOR.<coro tipo=''2X''>\nMORRI, MORRI NA CRUZ POR TI,\nQUE FAZES TU POR MIM', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (205, 'JESUS IA SEGUINDO', 'JESUS IA SEGUINDO', 'JESUS IA SEGUINDO PELA ESTRADA DE JERUSALÉM,\nELE IA SUBIR AO MONTE PARA AO PAI ORAR,\nQUANDO PRESTES A TOMAR NA CRUZ \nOS MEUS PECADOS, E AS MINHAS CULPAS \nSOBRE SI LEVAR.\n\nINSTRUMENTOS\n\nDO SEU ROSTO LÁGRIMAS COMEÇAM A DESCER,\nMOSTRANDO A TRISTEZA QUE VEM DO CORAÇÃO;\nTRISTEZA ESSA QUE REVELA TODO O SEU SOFRER,\nESTE FOI O PREÇO PELO MEU PERDÃO.\n\nO SOL SE PÕE E A NOITE \nVEM TRAZENDO A SOLIDÃO,\nENVOLVENDO TUDO \nNO SEU DENSO E ESCURO VÉU;\nNAS MÃOS DO PAI TUDO ENTREGOU, \nDIZENDO, ENTÃO:\n''SEJA FEITA A TUA VONTADE AQUI, \nCOMO NO CÉU''.\n\nDEPOIS QUE ELE CUMPRIU A SUA PARTE,\nDEPOIS QUE ELE ASSUMIU TUDO O \nQUE ERA MEU, MOSTRANDO O CAMINHO\nQUE ME LEVA ATÉ DEUS PAI,\nQUE POSSO EU FAZER,\nALÉM DA MINHA VIDA LHE ENTREGAR?\n\nINSTRUMENTOS\n\nDEPOIS QUE ELE CUMPRIU A SUA PARTE,\nDEPOIS QUE ELE ASSUMIU TUDO O \nQUE ERA MEU, MOSTRANDO O CAMINHO\nQUE ME LEVA ATÉ DEUS PAI,\nQUE POSSO EU FAZER,\nALÉM DA MINHA VIDA LHE ENTREGAR?', 'JESUS IA SEGUINDO PELA ESTRADA DE JERUSALÉM,\nELE IA SUBIR AO MONTE PARA AO PAI ORAR,\nQUANDO PRESTES A TOMAR NA CRUZ \nOS MEUS PECADOS, E AS MINHAS CULPAS \nSOBRE SI LEVAR.\n<instrumentos>\n\n\nDO SEU ROSTO LÁGRIMAS COMEÇAM A DESCER,\nMOSTRANDO A TRISTEZA QUE VEM DO CORAÇÃO;\nTRISTEZA ESSA QUE REVELA TODO O SEU SOFRER,\nESTE FOI O PREÇO PELO MEU PERDÃO.\n\nO SOL SE PÕE E A NOITE \nVEM TRAZENDO A SOLIDÃO,\nENVOLVENDO TUDO \nNO SEU DENSO E ESCURO VÉU;\nNAS MÃOS DO PAI TUDO ENTREGOU, \nDIZENDO, ENTÃO:\n''SEJA FEITA A TUA VONTADE AQUI, \nCOMO NO CÉU''.\n\nDEPOIS QUE ELE CUMPRIU A SUA PARTE,\nDEPOIS QUE ELE ASSUMIU TUDO O \nQUE ERA MEU, MOSTRANDO O CAMINHO\nQUE ME LEVA ATÉ DEUS PAI,\nQUE POSSO EU FAZER,\nALÉM DA MINHA VIDA LHE ENTREGAR?\n<instrumentos>\n\n\nDEPOIS QUE ELE CUMPRIU A SUA PARTE,\nDEPOIS QUE ELE ASSUMIU TUDO O \nQUE ERA MEU, MOSTRANDO O CAMINHO\nQUE ME LEVA ATÉ DEUS PAI,\nQUE POSSO EU FAZER,\nALÉM DA MINHA VIDA LHE ENTREGAR?', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (206, 'PAI, A TI ENTREGO O MEU ESPÍRITO', 'PAI, A TI ENTREGO O MEU ESPÍRITO', '''PAI, A TI ENTREGO O MEU ESPÍRITO,\nTRAGO CONSOLO AO PECADOR\nPARA UMA VIDA MUITO ALÉM,\nMUITO ALÉM DESTE MUNDO MAU.\n\nSEI QUE É DIFÍCIL ESTE MEU SOFRER,\nMAS POR AMOR VOU ATÉ MORRER,\nLEVANDO AS MARCAS DO MOMENTO\nE DO SOFRIMENTO QUE AQUI PASSEI;\nPAI, A TI ENTREGO O MEU ESPÍRITO.\n\nMAS SEI QUE VOU RESSURGIR \nEM UM CORPO GLORIOSO\nE SEI QUE VOLTAREI \nPRA BUSCAR A MINHA IGREJA GLORIOSA, \nRESPLANDECENTE DE LUZ. \n\nFINAL: GLORIOSA, RESPLANDECENTE DE LUZ.''', '''PAI, A TI ENTREGO O MEU ESPÍRITO,\nTRAGO CONSOLO AO PECADOR\nPARA UMA VIDA MUITO ALÉM,\nMUITO ALÉM DESTE MUNDO MAU.\n\nSEI QUE É DIFÍCIL ESTE MEU SOFRER,\nMAS POR AMOR VOU ATÉ MORRER,\nLEVANDO AS MARCAS DO MOMENTO\nE DO SOFRIMENTO QUE AQUI PASSEI;\nPAI, A TI ENTREGO O MEU ESPÍRITO.\n\nMAS SEI QUE VOU RESSURGIR <bis>\nEM UM CORPO GLORIOSO<bis>\nE SEI QUE VOLTAREI <bis>\nPRA BUSCAR A MINHA IGREJA GLORIOSA, <bis>\nRESPLANDECENTE DE LUZ. \n<final>GLORIOSA, RESPLANDECENTE DE LUZ.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (207, 'DEUS ENVIOU SEU FILHO AMADO', 'DEUS ENVIOU SEU FILHO AMADO', 'DEUS ENVIOU SEU FILHO AMADO\nPARA MORRER EM MEU LUGAR;\nNA CRUZ SOFREU POR MEUS PECADOS,\nMAS O SEPULCRO VAZIO ESTÁ\nPORQUE ELE VIVE. \n\nCORO\nPORQUE ELE VIVE, \nPOSSO CRER NO AMANHÃ; \nPORQUE ELE VIVE, \nTEMOR NÃO HÁ. MAS EU BEM SEI (EU SEI)\nQUE A MINHA VIDA \nESTÁ NAS MÃOS DO MEU JESUS, \nQUE VIVO ESTÁ.\n\nE QUANDO, ENFIM, CHEGAR A HORA\nEM QUE A MORTE ENFRENTAREI;\nSEM MEDO, ENTÃO, TEREI VITÓRIA, VEREI \nNA GLÓRIA O MEU JESUS QUE VIVO ESTÁ.\n\nCORO\nPORQUE ELE VIVE, \nPOSSO CRER NO AMANHÃ; \nPORQUE ELE VIVE, \nTEMOR NÃO HÁ. MAS EU BEM SEI (EU SEI)\nQUE A MINHA VIDA \nESTÁ NAS MÃOS DO MEU JESUS, \nQUE VIVO ESTÁ.', 'DEUS ENVIOU SEU FILHO AMADO\nPARA MORRER EM MEU LUGAR;\nNA CRUZ SOFREU POR MEUS PECADOS,\nMAS O SEPULCRO VAZIO ESTÁ\nPORQUE ELE VIVE.\n\n\n<coro>\nPORQUE ELE VIVE, \nPOSSO CRER NO AMANHÃ; \nPORQUE ELE VIVE, \nTEMOR NÃO HÁ. MAS EU BEM SEI (EU SEI)\nQUE A MINHA VIDA \nESTÁ NAS MÃOS DO MEU JESUS, \nQUE VIVO ESTÁ.\n\nE QUANDO, ENFIM, CHEGAR A HORA\nEM QUE A MORTE ENFRENTAREI;\nSEM MEDO, ENTÃO, TEREI VITÓRIA, VEREI \nNA GLÓRIA O MEU JESUS QUE VIVO ESTÁ.\n\n<coro>\nPORQUE ELE VIVE, \nPOSSO CRER NO AMANHÃ; \nPORQUE ELE VIVE, \nTEMOR NÃO HÁ. MAS EU BEM SEI (EU SEI)\nQUE A MINHA VIDA \nESTÁ NAS MÃOS DO MEU JESUS, \nQUE VIVO ESTÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (208, 'DEUS AMOU O MUNDO DE TAL MANEIRA', 'DEUS AMOU O MUNDO DE TAL MANEIRA', 'DEUS AMOU O MUNDO DE TAL MANEIRA, \nQUE SEU FILHO JESUS ENVIOU. \nVEIO PRA LIVRAR-NOS DA CONDENAÇÃO,\nVIDA ETERNA E TAMBÉM PAZ NOS PROPORCIONOU;\n\nJESUS, MESMO SENDO DEUS, OBEDECEU,\nME AMOU, TE AMOU, POR NÓS PADECEU;\nE DERRAMOU SEU SANGUE EM PURIFICAÇÃO, \nCUMPRIU O DIVINO PLANO DA REDENÇÃO.\n\nASSIM PODEMOS TER DIRETO ACESSO AO PAI, \nEM COMUNHÃO VIVER ATÉ JESUS VOLTAR. \nEXAMINA A TI MESMO:\nTENS GOZADO DESTA SALVAÇÃO?\nOU AINDA ESTÁS PRESO\nEM MEIO À TUA PRÓPRIA ILUSÃO?\nINSTRUMENTOS\n\nRENDE AGORA A TUA VIDA \nE ENTREGA SOBRE O SEU ALTAR; \nCADA HORA É DECISIVA, \nJESUS DISSE: ''LOGO VOU VOLTAR''. \nINSTRUMENTOS\nFINAL: ELE DISSE: ''LOGO VOU VOLTAR''.', 'DEUS AMOU O MUNDO DE TAL MANEIRA, \nQUE SEU FILHO JESUS ENVIOU. \nVEIO PRA LIVRAR-NOS DA CONDENAÇÃO,\nVIDA ETERNA E TAMBÉM PAZ NOS PROPORCIONOU;\n\nJESUS, MESMO SENDO DEUS, OBEDECEU,\nME AMOU, TE AMOU, POR NÓS PADECEU;\nE DERRAMOU SEU SANGUE EM PURIFICAÇÃO, \nCUMPRIU O DIVINO PLANO DA REDENÇÃO.\n\nASSIM PODEMOS TER DIRETO ACESSO AO PAI, \nEM COMUNHÃO VIVER ATÉ JESUS VOLTAR. \nEXAMINA A TI MESMO:\nTENS GOZADO DESTA SALVAÇÃO?\nOU AINDA ESTÁS PRESO\nEM MEIO À TUA PRÓPRIA ILUSÃO?\n<instrumentos>\n\n\nRENDE AGORA A TUA VIDA <bis>\nE ENTREGA SOBRE O SEU ALTAR; <bis>\nCADA HORA É DECISIVA, <bis>\nJESUS DISSE: ''LOGO VOU VOLTAR''. <bis>\n<instrumentos>\n<final>ELE DISSE: ''LOGO VOU VOLTAR''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (209, 'DEUS O SEU FILHO ENVIOU', 'DEUS O SEU FILHO ENVIOU', 'DEUS O SEU FILHO ENVIOU\nPARA MORRER NUMA CRUZ;\nNUM DESEJO PROFUNDO\nDO SEU CORAÇÃO,\nQUIS O HOMEM SALVAR.\n\nNESTE CAMINHO DA VIDA, ACONTECE \nQUE, SE DE DEUS, LONGE ESTOU,\nTENHO QUE IR A JESUS;\nLEMBRO QUE ELE SOFREU LÁ NA CRUZ.\n\nPARA RESGATAR MINHA VIDA,\nPARA TRANSFORMAR MEU CORAÇÃO,\nDANDO-ME PERDÃO, VIDA ETERNA, \nSEU AMOR.\n\nFINAL: SEU AMOR.', 'DEUS O SEU FILHO ENVIOU<bis>\nPARA MORRER NUMA CRUZ;<bis>\nNUM DESEJO PROFUNDO<bis>\nDO SEU CORAÇÃO,<bis>\nQUIS O HOMEM SALVAR.<bis>\n\nNESTE CAMINHO DA VIDA, ACONTECE \nQUE, SE DE DEUS, LONGE ESTOU,\nTENHO QUE IR A JESUS;\nLEMBRO QUE ELE SOFREU LÁ NA CRUZ.\n\nPARA RESGATAR MINHA VIDA,<bis>\nPARA TRANSFORMAR MEU CORAÇÃO,<bis>\nDANDO-ME PERDÃO, VIDA ETERNA, <bis>\nSEU AMOR.\n<final>SEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (210, 'UM DIA JESUS DESCEU DA SUA GLÓRIA', 'UM DIA JESUS DESCEU DA SUA GLÓRIA', 'UM DIA JESUS DESCEU DA SUA GLÓRIA\nE AQUI VIVEU, ENTRE NÓS, COM AMOR,\nFEZ MARAVILHAS, NOS DEU A VITÓRIA,\nE COM SEU SANGUE NOS PURIFICOU.\n\nHOSANA, HOSANA AO REI NAS ALTURAS, \nHOSANA, HOSANA A JESUS, \nO SENHOR.\n\nMORREU NA CRUZ PELOS NOSSOS PECADOS,\nSOFREU DEMAIS, SÓ PARA NOS SALVAR,\nE, NA TRISTEZA, NOS TEM CONSOLADO,\nSUBIU AO PAI, MAS VIRÁ NOS BUSCAR,\nSUBIU AO PAI, MAS VIRÁ NOS BUSCAR.\n\nHOSANA, HOSANA AO REI NAS ALTURAS, \nHOSANA, HOSANA A JESUS, \nO SENHOR.', 'UM DIA JESUS DESCEU DA SUA GLÓRIA\nE AQUI VIVEU, ENTRE NÓS, COM AMOR,\nFEZ MARAVILHAS, NOS DEU A VITÓRIA,\nE COM SEU SANGUE NOS PURIFICOU.\n\nHOSANA, HOSANA AO REI NAS ALTURAS, <bis>\nHOSANA, HOSANA A JESUS, <bis>\nO SENHOR.<bis>\n\nMORREU NA CRUZ PELOS NOSSOS PECADOS,\nSOFREU DEMAIS, SÓ PARA NOS SALVAR,\nE, NA TRISTEZA, NOS TEM CONSOLADO,\nSUBIU AO PAI, MAS VIRÁ NOS BUSCAR,\nSUBIU AO PAI, MAS VIRÁ NOS BUSCAR.\n\nHOSANA, HOSANA AO REI NAS ALTURAS, <bis>\nHOSANA, HOSANA A JESUS, <bis>\nO SENHOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (211, 'CORTARAM O MADEIRO', 'CORTARAM O MADEIRO', 'CORTARAM O MADEIRO, FIZERAM UMA CRUZ \nPARA O MEU SALVADOR; MADEIRO LAVRADO, \nCOM PREGOS CRAVADOS, PESADA FICOU.\nELE CARREGOU A CRUZ, NO CAMINHO CAIU, \nMAS DEUS DEU-LHE GRAÇA\nMORRENDO NA CRUZ POR TI E POR MIM.\n\nCORO\nFOI FEITA ASSIM A CRUZ DO SALVADOR;\nMADEIRO LAVRADO, COM PREGOS CRAVADOS, \nPESADA FICOU.\n\nPERANTE PILATOS JESUS FOI LEVADO\nCOMO UM MALFEITOR;\nCHEGANDO A ELE, OLHANDO O MESTRE,\nASSIM PERGUNTOU: ÉS O REI DOS JUDEUS? \nDISSE JESUS: ''NA VERDADE EU SOU, \nO MEU REINO É ETERNO, \nNÃO É DESTE MUNDO, \nDAQUI EU NÃO SOU''.\n\nCORO\nFOI FEITA ASSIM A CRUZ DO SALVADOR;\nMADEIRO LAVRADO, COM PREGOS CRAVADOS, \nPESADA FICOU.\n\nCHEGANDO AO CALVÁRIO, \nPREGARAM NA CRUZ O MEU SALVADOR;\nUMA COROA DE ESPINHOS, \nNA FRONTE SANGRANDO, AO PAI SUPLICOU;\nTRANSPASSADO DE DOR FICOU O MEU SALVADOR, \nÀS TRÊS HORAS DA TARDE,\nINCLINOU A CABEÇA E ALI EXPIROU.\n\nCORO\nFOI FEITA ASSIM A CRUZ DO SALVADOR;\nMADEIRO LAVRADO, COM PREGOS CRAVADOS, \nPESADA FICOU.', 'CORTARAM O MADEIRO, FIZERAM UMA CRUZ \nPARA O MEU SALVADOR; MADEIRO LAVRADO, \nCOM PREGOS CRAVADOS, PESADA FICOU.\nELE CARREGOU A CRUZ, NO CAMINHO CAIU, \nMAS DEUS DEU-LHE GRAÇA\nMORRENDO NA CRUZ POR TI E POR MIM.\n\n<coro>\nFOI FEITA ASSIM A CRUZ DO SALVADOR;\nMADEIRO LAVRADO, COM PREGOS CRAVADOS, \nPESADA FICOU.\n\nPERANTE PILATOS JESUS FOI LEVADO\nCOMO UM MALFEITOR;\nCHEGANDO A ELE, OLHANDO O MESTRE,\nASSIM PERGUNTOU: ÉS O REI DOS JUDEUS? \nDISSE JESUS: ''NA VERDADE EU SOU, \nO MEU REINO É ETERNO, \nNÃO É DESTE MUNDO, \nDAQUI EU NÃO SOU''.\n\n<coro>\nFOI FEITA ASSIM A CRUZ DO SALVADOR;\nMADEIRO LAVRADO, COM PREGOS CRAVADOS, \nPESADA FICOU.\n\nCHEGANDO AO CALVÁRIO, \nPREGARAM NA CRUZ O MEU SALVADOR;\nUMA COROA DE ESPINHOS, \nNA FRONTE SANGRANDO, AO PAI SUPLICOU;\nTRANSPASSADO DE DOR FICOU O MEU SALVADOR, \nÀS TRÊS HORAS DA TARDE,\nINCLINOU A CABEÇA E ALI EXPIROU.\n\n<coro>\nFOI FEITA ASSIM A CRUZ DO SALVADOR;\nMADEIRO LAVRADO, COM PREGOS CRAVADOS, \nPESADA FICOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (212, 'RUDE CRUZ', 'RUDE CRUZ', 'RUDE CRUZ SE ERIGIU, DELA O DIA FUGIU,\nCOMO EMBLEMA DE VERGONHA E DOR;\nMAS EU AMO ESSA CRUZ PORQUE NELA, \nJESUS, DEU A VIDA POR MIM, PECADOR.\n\nCORO\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.\n\nDESDE A GLÓRIA DOS CÉUS, \nO CORDEIRO DE DEUS \nAO CALVÁRIO HUMILHANTE BAIXOU;\nTEM A CRUZ PARA MIM ATRATIVOS SEM FIM, \nPORQUE NELA JESUS ME SALVOU.\n\nCORO\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.\n\nLÁ NA CRUZ PADECEU, \nDESPREZADO MORREU MEU JESUS \nPARA DAR-ME O PERDÃO;\nDELA AGORA PROVÉM PARA MIM TODO \nO BEM, TENHO NELA REAL SALVAÇÃO.\n\nCORO\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.\n\nEU AQUI COM JESUS, A VERGONHA DA CRUZ \nQUERO SEMPRE LEVAR E SOFRER;\nQUANDO CRISTO VOLTAR, \nPARA AQUI ME BUSCAR, \nSUA GLÓRIA EU IREI RECEBER.\n\nCORO\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.', 'RUDE CRUZ SE ERIGIU, DELA O DIA FUGIU,\nCOMO EMBLEMA DE VERGONHA E DOR;\nMAS EU AMO ESSA CRUZ PORQUE NELA, \nJESUS, DEU A VIDA POR MIM, PECADOR.\n\n<coro>\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.\n\nDESDE A GLÓRIA DOS CÉUS, \nO CORDEIRO DE DEUS \nAO CALVÁRIO HUMILHANTE BAIXOU;\nTEM A CRUZ PARA MIM ATRATIVOS SEM FIM, \nPORQUE NELA JESUS ME SALVOU.\n\n<coro>\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.\n\nLÁ NA CRUZ PADECEU, \nDESPREZADO MORREU MEU JESUS \nPARA DAR-ME O PERDÃO;\nDELA AGORA PROVÉM PARA MIM TODO \nO BEM, TENHO NELA REAL SALVAÇÃO.\n\n<coro>\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.\n\nEU AQUI COM JESUS, A VERGONHA DA CRUZ \nQUERO SEMPRE LEVAR E SOFRER;\nQUANDO CRISTO VOLTAR, \nPARA AQUI ME BUSCAR, \nSUA GLÓRIA EU IREI RECEBER.\n\n<coro>\nSIM, EU AMO A MENSAGEM DA CRUZ,\nTÉ MORRER EU A VOU PROCLAMAR;\nLEVAREI EU TAMBÉM MINHA CRUZ,\nTÉ POR UMA COROA TROCAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (213, 'CRISTO CAMINHAVA EM DIREÇÃO À CRUZ', 'CRISTO CAMINHAVA EM DIREÇÃO À CRUZ', 'CRISTO CAMINHAVA EM DIREÇÃO À CRUZ,\nSABENDO QUE ESTAVA PRA MORRER,\nENFERMO E CANSADO, SOZINHO E DESPREZADO, CARREGAVA A CRUZ.\n\nNOSSOS PECADOS ELE SUPORTOU,\nSENTINDO SOLIDÃO AO PAI CLAMOU:\n''NÃO SABEM O QUE FAZEM,\nPERDOA-LHES, SENHOR, EU VIM POR AMOR.''\n\nNO CALVÁRIO PREGARAM SUAS MÃOS E PÉS,\nSENDO REI, COROADO DE ESPINHOS;\nO CÉU SE ESCURECEU, \nPRA BEBER LHE DERAM FEL, \nRASGOU-SE O VÉU E EXPIROU.\n\nAO TERCEIRO DIA ELE RESSURGIU\nDANDO-NOS VITÓRIA, \nO SEU SANGUE É GARANTIA!\nGESTO DE AMOR, GESTO DO SENHOR,\nMORRENDO EM UMA CRUZ,\nSENDO NOSSO SALVADOR.\nINSTRUMENTOS\n\nGESTO DE AMOR, \nGESTO DO SENHOR,\nMORRENDO EM UMA CRUZ, \nSENDO NOSSO SALVADOR.\n\nFINAL: GESTO DE AMOR!', 'CRISTO CAMINHAVA EM DIREÇÃO À CRUZ,\nSABENDO QUE ESTAVA PRA MORRER,\nENFERMO E CANSADO, SOZINHO E DESPREZADO, CARREGAVA A CRUZ.\n\nNOSSOS PECADOS ELE SUPORTOU,\nSENTINDO SOLIDÃO AO PAI CLAMOU:\n''NÃO SABEM O QUE FAZEM,\nPERDOA-LHES, SENHOR, EU VIM POR AMOR.''\n\nNO CALVÁRIO PREGARAM SUAS MÃOS E PÉS,\nSENDO REI, COROADO DE ESPINHOS;\nO CÉU SE ESCURECEU, \nPRA BEBER LHE DERAM FEL, \nRASGOU-SE O VÉU E EXPIROU.\n\nAO TERCEIRO DIA ELE RESSURGIU\nDANDO-NOS VITÓRIA, \nO SEU SANGUE É GARANTIA!\nGESTO DE AMOR, GESTO DO SENHOR,\nMORRENDO EM UMA CRUZ,\nSENDO NOSSO SALVADOR.\n<instrumentos>\n\n\nGESTO DE AMOR, <bis>\nGESTO DO SENHOR,<bis>\nMORRENDO EM UMA CRUZ, <bis>\nSENDO NOSSO SALVADOR.\n<final>GESTO DE AMOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (214, 'DOIS DISCÍPULOS NO CAMINHO DE EMAÚS', 'DOIS DISCÍPULOS NO CAMINHO DE EMAÚS', 'DOIS DISCÍPULOS NO CAMINHO DE EMAÚS\nIAM FALANDO A RESPEITO DE JESUS;\nUM VIAJANTE DELES SE APROXIMOU,\nNÃO PERCEBERAM QUE ERA O MEIGO SALVADOR.\n\nCORO\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.\n\nELES FALAVAM A RESPEITO DE JESUS,\nVARÃO PROFETA QUE FOI PODEROSO EM OBRAS, \nDIANTE DE DEUS E TODO O POVO, ALELUIA, \nESTE JESUS QUE AINDA HOJE NOS CONDUZ.\n\nCORO\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.\n\nELES FALAVAM A RESPEITO DE JESUS,\nVARÃO PROFETA QUE FOI PODEROSO EM OBRAS, \nDIANTE DE DEUS E TODO O POVO, ALELUIA, \nESTE JESUS QUE AINDA HOJE NOS CONDUZ.\n\nCORO\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.\n\nSENTADO À MESA, TOMANDO O PÃO, \nABENÇOOU, PARTIU E DEU, \nELES ENTÃO RECONHECERAM;\nCHEIOS DE GOZO EM VER \nO FILHO DE DEUS NO MESMO INSTANTE \nELE DESAPARECEU.\n\nCORO\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.', 'DOIS DISCÍPULOS NO CAMINHO DE EMAÚS\nIAM FALANDO A RESPEITO DE JESUS;\nUM VIAJANTE DELES SE APROXIMOU,\nNÃO PERCEBERAM QUE ERA O MEIGO SALVADOR.\n\n<coro>\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.\n\nELES FALAVAM A RESPEITO DE JESUS,\nVARÃO PROFETA QUE FOI PODEROSO EM OBRAS, \nDIANTE DE DEUS E TODO O POVO, ALELUIA, \nESTE JESUS QUE AINDA HOJE NOS CONDUZ.\n\n<coro>\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.\n\nELES FALAVAM A RESPEITO DE JESUS,\nVARÃO PROFETA QUE FOI PODEROSO EM OBRAS, \nDIANTE DE DEUS E TODO O POVO, ALELUIA, \nESTE JESUS QUE AINDA HOJE NOS CONDUZ.\n\n<coro>\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.\n\nSENTADO À MESA, TOMANDO O PÃO, \nABENÇOOU, PARTIU E DEU, \nELES ENTÃO RECONHECERAM;\nCHEIOS DE GOZO EM VER \nO FILHO DE DEUS NO MESMO INSTANTE \nELE DESAPARECEU.\n\n<coro>\nFICA CONOSCO, NOSSO AMADO SALVADOR,\nFICA CONOSCO PELO TEU IMENSO AMOR,\nCOMO OS DISCÍPULOS TE PEDIRAM \nNO CAMINHO DE EMAÚS, FICA CONOSCO, \nNOSSO AMADO E BOM JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (215, 'CERTO HOMEM TÃO NOBRE', 'CERTO HOMEM TÃO NOBRE', 'CERTO HOMEM TÃO NOBRE NESTE MUNDO DESCEU, CARREGOU MEUS PECADOS SÓ PORQUE ME AMOU;\nO SEU SANGUE TÃO PURO NA CRUZ DERRAMOU, \nESTE HOMEM TÃO NOBRE É JESUS.\n\nCORO (2X)\nNOBRE E REI, ELE É NOBRE E REI,\nESTE HOMEM TÃO NOBRE É JESUS. \n\nRESSURGIU DENTRE OS MORTOS\nPORQUE É VENCEDOR, \nHOJE À DESTRA DO PAI ESTÁ, CRISTO, \nMEU SALVADOR;\nPROMETEU QUE UM DIA VIRÁ ME BUSCAR, \nPARA SEMPRE O SEU NOME VOU LOUVAR.\n\nCORO (2X)\nNOBRE E REI, ELE É NOBRE E REI,\nESTE HOMEM TÃO NOBRE É JESUS.\n\nFINAL: \nESTE HOMEM TÃO NOBRE É JESUS.', 'CERTO HOMEM TÃO NOBRE NESTE MUNDO DESCEU, CARREGOU MEUS PECADOS SÓ PORQUE ME AMOU;\nO SEU SANGUE TÃO PURO NA CRUZ DERRAMOU, \nESTE HOMEM TÃO NOBRE É JESUS.\n\n<coro tipo=''2X''>\nNOBRE E REI, ELE É NOBRE E REI,\nESTE HOMEM TÃO NOBRE É JESUS. \n\nRESSURGIU DENTRE OS MORTOS\nPORQUE É VENCEDOR, \nHOJE À DESTRA DO PAI ESTÁ, CRISTO, \nMEU SALVADOR;\nPROMETEU QUE UM DIA VIRÁ ME BUSCAR, \nPARA SEMPRE O SEU NOME VOU LOUVAR.\n\n<coro tipo=''2X''>\nNOBRE E REI, ELE É NOBRE E REI,\nESTE HOMEM TÃO NOBRE É JESUS.\n<final>ESTE HOMEM TÃO NOBRE É JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (216, 'SOMOS TEU POVO', 'SOMOS TEU POVO', 'SOMOS TEU POVO, TUA IGREJA,\nMORRESTE POR NÓS, SENDO REI, SENHOR!\nQUISESTE SALVAR O MUNDO,\nMAS O MUNDO NÃO QUIS.\n\nA TUA IGREJA TE AMA\nE FAZ DO TEU SANGUE ESCUDO FORTE,\nA TUA PALAVRA É ALIMENTO FORTE\nQUE FAZ NOSSA VIDA FELIZ!\n\nA TUA IGREJA TE ESPERA, NÃO SE APRESSA, \nPORQUE TU, JESUS, VOLTARÁS E A LEVARÁS \nPARA UM LAR DE PAZ, ONDE REINA O AMOR.', 'SOMOS TEU POVO, TUA IGREJA,\nMORRESTE POR NÓS, SENDO REI, SENHOR!\nQUISESTE SALVAR O MUNDO,\nMAS O MUNDO NÃO QUIS.\n\nA TUA IGREJA TE AMA\nE FAZ DO TEU SANGUE ESCUDO FORTE,\nA TUA PALAVRA É ALIMENTO FORTE\nQUE FAZ NOSSA VIDA FELIZ!\n\nA TUA IGREJA TE ESPERA, NÃO SE APRESSA, <bis>\nPORQUE TU, JESUS, VOLTARÁS E A LEVARÁS <bis>\nPARA UM LAR DE PAZ, ONDE REINA O AMOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (217, 'DEIXOU O ESPLENDOR DE SUA GLÓRIA', 'DEIXOU O ESPLENDOR DE SUA GLÓRIA', 'DEIXOU O ESPLENDOR DE SUA GLÓRIA\nSABENDO O DESTINO AQUI;\nESTAVA SÓ E FERIDO NO GÓLGOTA\nPARA DAR SUA VIDA POR MIM.\n\nCORO\nSE ISTO NÃO FOR AMOR, O OCEANO SECOU, \nNÃO HÁ ESTRELAS NO CÉU,\nAS ANDORINHAS NÃO VOAM MAIS;\nSE ISTO NÃO FOR AMOR, O CÉU NÃO \nÉ REAL, TUDO PERDE O VALOR \nSE ISTO NÃO FOR AMOR.\n\nMESMO NA MORTE LEMBROU-SE\nDE UM LADRÃO QUE A SEU LADO ESTAVA;\nCOM AMOR E TERNURA FALOU-LHE:\n''AO PARAÍSO COMIGO IRÁS''.\n\nCORO\nSE ISTO NÃO FOR AMOR, O OCEANO SECOU, \nNÃO HÁ ESTRELAS NO CÉU,\nAS ANDORINHAS NÃO VOAM MAIS;\nSE ISTO NÃO FOR AMOR, O CÉU NÃO \nÉ REAL, TUDO PERDE O VALOR \nSE ISTO NÃO FOR AMOR.', 'DEIXOU O ESPLENDOR DE SUA GLÓRIA\nSABENDO O DESTINO AQUI;\nESTAVA SÓ E FERIDO NO GÓLGOTA\nPARA DAR SUA VIDA POR MIM.\n\n<coro>\nSE ISTO NÃO FOR AMOR, O OCEANO SECOU, \nNÃO HÁ ESTRELAS NO CÉU,\nAS ANDORINHAS NÃO VOAM MAIS;\nSE ISTO NÃO FOR AMOR, O CÉU NÃO \nÉ REAL, TUDO PERDE O VALOR \nSE ISTO NÃO FOR AMOR.\n\nMESMO NA MORTE LEMBROU-SE\nDE UM LADRÃO QUE A SEU LADO ESTAVA;\nCOM AMOR E TERNURA FALOU-LHE:\n''AO PARAÍSO COMIGO IRÁS''.\n\n<coro>\nSE ISTO NÃO FOR AMOR, O OCEANO SECOU, \nNÃO HÁ ESTRELAS NO CÉU,\nAS ANDORINHAS NÃO VOAM MAIS;\nSE ISTO NÃO FOR AMOR, O CÉU NÃO \nÉ REAL, TUDO PERDE O VALOR \nSE ISTO NÃO FOR AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (218, 'POR AMOR JESUS MORREU', 'POR AMOR JESUS MORREU', 'POR AMOR JESUS MORREU,\nVEIO PARA ME SALVAR,\nPOR AMOR SEU SANGUE VERTEU,\nNAQUELA AMARGA CRUZ,\nPOR AMOR SE FEZ MEU PRESENTE,\nTORNANDO-SE AMIGO \nME FEZ SEU PARENTE.\n\nPOR AMOR SE FEZ MEU PRESENTE,\nTORNANDO-SE AMIGO\nME FEZ SEU PARENTE.\nVIVA O REI, (JESUS) \nVIVA O REI, (VIVA O REI) (BIS)\nVIVA O REI.', 'POR AMOR JESUS MORREU,<bis>\nVEIO PARA ME SALVAR,<bis>\nPOR AMOR SEU SANGUE VERTEU,<bis>\nNAQUELA AMARGA CRUZ,<bis>\nPOR AMOR SE FEZ MEU PRESENTE,<bis>\nTORNANDO-SE AMIGO <bis>\nME FEZ SEU PARENTE.<bis>\n\nPOR AMOR SE FEZ MEU PRESENTE,\nTORNANDO-SE AMIGO\nME FEZ SEU PARENTE.\nVIVA O REI, (JESUS) \nVIVA O REI, (VIVA O REI) <bis>\nVIVA O REI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (219, 'POR AMOR', 'POR AMOR', 'POR AMOR, POR AMOR JESUS ME SALVOU,\nFOI NA CRUZ, FOI NA CRUZ QUE O PREÇO PAGOU,\nNÃO COM PRATA, NEM OURO, MAS \nCOM SANGUE MOSTROU O INFINITO \nAMOR COM QUE AO MUNDO AMOU.\n\nCORO\nTÃO GRANDE AMOR ME TRANSFORMOU;\nBASTA CRER E ACEITAR, POR SEU SANGUE CLAMAR\nE O AMOR DE MEU DEUS VAI TUA VIDA INUNDAR.\nINSTRUMENTOS\n\nDO IMENSO AMOR NINGUÉM VAI SEPARAR,\nÉ MAIS FORTE QUE A MORTE,\nARDE EM MIM SEM CESSAR;\nTUDO CRÊ E SUPORTA ATÉ O DIA CHEGAR,\nE O AMOR DE MEU DEUS LÁ NO CÉU VOU GOZAR.\n\nCORO\nTÃO GRANDE AMOR ME TRANSFORMOU;\nBASTA CRER E ACEITAR, POR SEU SANGUE CLAMAR\nE O AMOR DE MEU DEUS VAI TUA VIDA INUNDAR.', 'POR AMOR, POR AMOR JESUS ME SALVOU,\nFOI NA CRUZ, FOI NA CRUZ QUE O PREÇO PAGOU,\nNÃO COM PRATA, NEM OURO, MAS \nCOM SANGUE MOSTROU O INFINITO \nAMOR COM QUE AO MUNDO AMOU.\n\n<coro>\nTÃO GRANDE AMOR ME TRANSFORMOU;\nBASTA CRER E ACEITAR, POR SEU SANGUE CLAMAR\nE O AMOR DE MEU DEUS VAI TUA VIDA INUNDAR.\n<instrumentos>\n\n\nDO IMENSO AMOR NINGUÉM VAI SEPARAR,\nÉ MAIS FORTE QUE A MORTE,\nARDE EM MIM SEM CESSAR;\nTUDO CRÊ E SUPORTA ATÉ O DIA CHEGAR,\nE O AMOR DE MEU DEUS LÁ NO CÉU VOU GOZAR.\n\n<coro>\nTÃO GRANDE AMOR ME TRANSFORMOU;\nBASTA CRER E ACEITAR, POR SEU SANGUE CLAMAR\nE O AMOR DE MEU DEUS VAI TUA VIDA INUNDAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (220, 'NÃO HÁ AMOR IGUAL', 'NÃO HÁ AMOR IGUAL', 'NÃO HÁ AMOR IGUAL AO AMOR DE JESUS,\nPOR MIM MORREU NAQUELA CRUZ;\nDEIXOU A SUA GLÓRIA, SOFREU HUMILHAÇÃO\nSÓ PRA ME DAR A SALVAÇÃO.\n\nCORO\nPOR ISSO DEI-LHE O MEU CORAÇÃO\nE LHE ENTREGUEI TODO O MEU SER\nE UM TRONO LEVANTEI PARA O MEU JESUS \nSER REI EM TODO O MEU VIVER.\n\nO QUE ELE VIU EM MIM \nPARA SE DAR ASSIM POR MIM, \nTÃO POBRE PECADOR?\nDESCEU DA SUA GLÓRIA, \nSOFREU HUMILHAÇÃO \nPARA ME DAR A SALVAÇÃO.', 'NÃO HÁ AMOR IGUAL AO AMOR DE JESUS,\nPOR MIM MORREU NAQUELA CRUZ;\nDEIXOU A SUA GLÓRIA, SOFREU HUMILHAÇÃO\nSÓ PRA ME DAR A SALVAÇÃO.\n\n<coro>\nPOR ISSO DEI-LHE O MEU CORAÇÃO\nE LHE ENTREGUEI TODO O MEU SER\nE UM TRONO LEVANTEI PARA O MEU JESUS \nSER REI EM TODO O MEU VIVER.\n\nO QUE ELE VIU EM MIM \nPARA SE DAR ASSIM POR MIM, \nTÃO POBRE PECADOR?\nDESCEU DA SUA GLÓRIA, \nSOFREU HUMILHAÇÃO \nPARA ME DAR A SALVAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (221, 'JESUS, EM TUA PRESENÇA', 'JESUS, EM TUA PRESENÇA', 'JESUS, EM TUA PRESENÇA,\nREUNIMO-NOS AQUI,\nCONTEMPLAMOS TUA FACE\nE RENDEMO-NOS A TI;\nPOIS UM DIA A TUA MORTE\nTROUXE VIDA A TODOS NÓS\nE NOS DEU COMPLETO ACESSO\nAO CORAÇÃO DO PAI.\nINSTRUMENTOS\n\nJESUS, EM TUA PRESENÇA,\nREUNIMO-NOS AQUI,\nCONTEMPLAMOS TUA FACE\nE RENDEMO-NOS A TI;\nPOIS UM DIA A TUA MORTE\nTROUXE VIDA A TODOS NÓS\nE NOS DEU COMPLETO ACESSO\nAO CORAÇÃO DO PAI.\n\nO VÉU QUE SEPARAVA JÁ NÃO SEPARA MAIS,\nA LUZ, QUE OUTRORA APAGADA, AGORA BRILHA\nE CADA DIA BRILHA MAIS.\n\nSÓ PRA TE ADORAR\nE FAZER TEU NOME GRANDE\nE TE DAR O LOUVOR QUE É \nDEVIDO, ESTAMOS NÓS AQUI.', 'JESUS, EM TUA PRESENÇA,\nREUNIMO-NOS AQUI,\nCONTEMPLAMOS TUA FACE\nE RENDEMO-NOS A TI;\nPOIS UM DIA A TUA MORTE\nTROUXE VIDA A TODOS NÓS\nE NOS DEU COMPLETO ACESSO\nAO CORAÇÃO DO PAI.\n<instrumentos>\n\n\nJESUS, EM TUA PRESENÇA,\nREUNIMO-NOS AQUI,\nCONTEMPLAMOS TUA FACE\nE RENDEMO-NOS A TI;\nPOIS UM DIA A TUA MORTE\nTROUXE VIDA A TODOS NÓS\nE NOS DEU COMPLETO ACESSO\nAO CORAÇÃO DO PAI.\n\nO VÉU QUE SEPARAVA JÁ NÃO SEPARA MAIS,\nA LUZ, QUE OUTRORA APAGADA, AGORA BRILHA\nE CADA DIA BRILHA MAIS.\n\nSÓ PRA TE ADORAR<bis>\nE FAZER TEU NOME GRANDE<bis>\nE TE DAR O LOUVOR QUE É <bis>\nDEVIDO, ESTAMOS NÓS AQUI. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (222, 'EIS QUE ESTOU À PORTA', 'EIS QUE ESTOU À PORTA', 'EIS QUE ESTOU À PORTA E BATO,\nSE ALGUÉM OUVIR MINHA VOZ\nE ABRIR A PORTA,\nENTRAREI EM SEU CORAÇÃO.\n\nE COM ELE CEAREI E ELE COMIGO;\nBASTA ABRIR A PORTA,\nENTRAREI EM SEU CORAÇÃO.', 'EIS QUE ESTOU À PORTA E BATO,<bis>\nSE ALGUÉM OUVIR MINHA VOZ<bis>\nE ABRIR A PORTA,<bis>\nENTRAREI EM SEU CORAÇÃO.<bis>\n\nE COM ELE CEAREI E ELE COMIGO;<bis>\nBASTA ABRIR A PORTA,<bis>\nENTRAREI EM SEU CORAÇÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (223, 'ONDE ESTÁ O CORDEIRO?', 'ONDE ESTÁ O CORDEIRO?', 'ONDE ESTÁ O CORDEIRO?\nA PERGUNTA DE TODAS AS NAÇÕES\nECOA NO MUNDO INTEIRO;\nONDE ESTÁ O CORDEIRO\nQUE FOI MORTO EM MEU LUGAR\nPARA A VIDA ETERNA ME DAR?\nINSTRUMENTOS\n\nEIS AQUI O CORDEIRO DE DEUS,\nTROUXE A MIM VIDA, PAZ E LUZ,\nREVELOU-ME O PLANO ETERNO,\nO CORDEIRO SE CHAMA JESUS,\n(ONDE ESTÁ O CORDEIRO?)\nO CORDEIRO SE CHAMA JESUS. \nINSTRUMENTOS\n\nOUVI UMA VOZ LÁ DO CÉU\nA CHAMAR: ''POVO MEU, SOBE AQUI'';\nVI UM TRONO CELESTE \nE O CORDEIRO ASSENTADO ALI;\nEM CORO OS ANJOS CANTAVAM:\nGLÓRIA, GLÓRIA AO CORDEIRO, AMÉM.\n\nGLÓRIA AO CORDEIRO, AMÉM, (GLÓRIA)\nGLÓRIA AO CORDEIRO, AMÉM, (GLÓRIA)\nGLÓRIA AO CORDEIRO, AMÉM, (GLÓRIA)\nAMÉM!', 'ONDE ESTÁ O CORDEIRO?\nA PERGUNTA DE TODAS AS NAÇÕES\nECOA NO MUNDO INTEIRO;\nONDE ESTÁ O CORDEIRO\nQUE FOI MORTO EM MEU LUGAR\nPARA A VIDA ETERNA ME DAR?\n<instrumentos>\n\n\nEIS AQUI O CORDEIRO DE DEUS,\nTROUXE A MIM VIDA, PAZ E LUZ,\nREVELOU-ME O PLANO ETERNO,\nO CORDEIRO SE CHAMA JESUS,\n(ONDE ESTÁ O CORDEIRO?)\nO CORDEIRO SE CHAMA JESUS. \n<instrumentos>\n\n\nOUVI UMA VOZ LÁ DO CÉU\nA CHAMAR: ''POVO MEU, SOBE AQUI'';\nVI UM TRONO CELESTE \nE O CORDEIRO ASSENTADO ALI;\nEM CORO OS ANJOS CANTAVAM:\nGLÓRIA, GLÓRIA AO CORDEIRO, AMÉM.\n\nGLÓRIA AO CORDEIRO, AMÉM, (GLÓRIA)\nGLÓRIA AO CORDEIRO, AMÉM, (GLÓRIA)\nGLÓRIA AO CORDEIRO, AMÉM, (GLÓRIA)\nAMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (224, 'ERA UM PECADOR, ANDAVA SEM JESUS', 'ERA UM PECADOR, ANDAVA SEM JESUS', 'ERA UM PECADOR, ANDAVA SEM JESUS,\nNÃO TINHA ESPERANÇA NEM DIVINA LUZ,\nHOJE SOU REMIDO, CRISTO ME SALVOU,\nCOM SEU SANGUE ME LAVOU.\n\nCORO\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.\n\nO CONSOLADOR JÁ VEIO EM MIM MORAR,\nA PALAVRA SANTA VEIO ILUMINAR;\nQUERO SER GUIADO POR TÃO CLARA LUZ\nQUE A CRISTO ME CONDUZ.\n\nCORO\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.\n\nVEM, JESUS AMADO, VEM SEM DEMORAR,\nEU ESTOU ANSIOSO PRA NO CÉU ENTRAR,\nVEM SEM MAIS TARDANÇA, FAZ RAIAR A LUZ; \n''ORA VEM, SENHOR JESUS''.\n\nCORO\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.\n\nQUERES, PECADOR, GOZAR A SALVAÇÃO?\nVEM A CRISTO HOJE RECEBER PERDÃO;\nCRISTO TE ACEITA, POBRE PECADOR,\nNOS SEUS BRAÇOS DE AMOR.\n\nCORO\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.', 'ERA UM PECADOR, ANDAVA SEM JESUS,\nNÃO TINHA ESPERANÇA NEM DIVINA LUZ,\nHOJE SOU REMIDO, CRISTO ME SALVOU,\nCOM SEU SANGUE ME LAVOU.\n\n<coro>\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.\n\nO CONSOLADOR JÁ VEIO EM MIM MORAR,\nA PALAVRA SANTA VEIO ILUMINAR;\nQUERO SER GUIADO POR TÃO CLARA LUZ\nQUE A CRISTO ME CONDUZ.\n\n<coro>\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.\n\nVEM, JESUS AMADO, VEM SEM DEMORAR,\nEU ESTOU ANSIOSO PRA NO CÉU ENTRAR,\nVEM SEM MAIS TARDANÇA, FAZ RAIAR A LUZ; \n''ORA VEM, SENHOR JESUS''.\n\n<coro>\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.\n\nQUERES, PECADOR, GOZAR A SALVAÇÃO?\nVEM A CRISTO HOJE RECEBER PERDÃO;\nCRISTO TE ACEITA, POBRE PECADOR,\nNOS SEUS BRAÇOS DE AMOR.\n\n<coro>\nQUE AMOR ME CONCEDEU JESUS,\nGOZO SANTO E CELESTE LUZ;\nCRISTO EM BREVE DO CÉU DESCERÁ\nE CONSIGO, ENTÃO, ME LEVARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (225, 'JESUS É MELHOR, SIM, QUE OURO E BENS', 'JESUS É MELHOR, SIM, QUE OURO E BENS', 'JESUS É MELHOR, SIM, QUE OURO E BENS,\nJESUS É MELHOR DO QUE TUDO QUE TENS,\nMELHOR QUE RIQUEZAS E POSIÇÕES,\nMELHOR, MUITO MAIS DO QUE MILHÕES.\n\nCORO\nPODE SER UM REI COM PODER NAS \nMÃOS, MAS DO MAL, ESCRAVO, SIM;\nMIL VEZES PREFIRO O MEU JESUS\nE SERVI-LO ATÉ O FIM.\n\nJESUS É MELHOR QUE QUALQUER VALOR,\nAMIGO LEAL NO PRAZER E NA DOR,\nMELHOR DO QUE TUDO ELE É PRA MIM,\nMELHOR QUE QUALQUER BOM AMIGO ENFIM.\n\nCORO\nPODE SER UM REI COM PODER NAS \nMÃOS, MAS DO MAL, ESCRAVO, SIM;\nMIL VEZES PREFIRO O MEU JESUS\nE SERVI-LO ATÉ O FIM.\n\nJESUS É MAIS PURO QUE A LINDA FLOR,\nJESUS É MELHOR, ELE, SIM, SATISFAZ,\nJESUS É MELHOR, SIM, ELE É AMOR,\nCAMINHO, LUZ, VERDADE E PAZ.\n\nCORO\nPODE SER UM REI COM PODER NAS \nMÃOS, MAS DO MAL, ESCRAVO, SIM;\nMIL VEZES PREFIRO O MEU JESUS\nE SERVI-LO ATÉ O FIM.', 'JESUS É MELHOR, SIM, QUE OURO E BENS,\nJESUS É MELHOR DO QUE TUDO QUE TENS,\nMELHOR QUE RIQUEZAS E POSIÇÕES,\nMELHOR, MUITO MAIS DO QUE MILHÕES.\n\n<coro>\nPODE SER UM REI COM PODER NAS \nMÃOS, MAS DO MAL, ESCRAVO, SIM;\nMIL VEZES PREFIRO O MEU JESUS\nE SERVI-LO ATÉ O FIM.\n\nJESUS É MELHOR QUE QUALQUER VALOR,\nAMIGO LEAL NO PRAZER E NA DOR,\nMELHOR DO QUE TUDO ELE É PRA MIM,\nMELHOR QUE QUALQUER BOM AMIGO ENFIM.\n\n<coro>\nPODE SER UM REI COM PODER NAS \nMÃOS, MAS DO MAL, ESCRAVO, SIM;\nMIL VEZES PREFIRO O MEU JESUS\nE SERVI-LO ATÉ O FIM.\n\nJESUS É MAIS PURO QUE A LINDA FLOR,\nJESUS É MELHOR, ELE, SIM, SATISFAZ,\nJESUS É MELHOR, SIM, ELE É AMOR,\nCAMINHO, LUZ, VERDADE E PAZ.\n\n<coro>\nPODE SER UM REI COM PODER NAS \nMÃOS, MAS DO MAL, ESCRAVO, SIM;\nMIL VEZES PREFIRO O MEU JESUS\nE SERVI-LO ATÉ O FIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (226, 'O SENTIDO DE VIVER', 'O SENTIDO DE VIVER', 'O SENTIDO DE VIVER ENCONTRAMOS \nEM JESUS, ELE É A SALVAÇÃO QUE \nHOJE PODES TER;\nÉ SÓ ABRIR TEU CORAÇÃO, \nDEIXAR CRISTO HABITAR, \nA PAZ E A ALEGRIA\nEM TI IRÃO REINAR.\n\nCORO (2X)\nJESUS, O SENTIDO DE VIVER,\n(DE VIVER SÓ PRA JESUS) VARÕES\nJESUS, O AMOR, A PAZ REAL,\nNÃO HÁ OUTRO AMOR IGUAL. \n\nJESUS CRISTO VAI VOLTAR, \nELE UM DIA PROMETEU, \nE SEREMOS TRANSFORMADOS \nPARA O ENCONTRO COM O SENHOR;\nESTAREMOS PARA SEMPRE COM JESUS, \nO REDENTOR, \nONDE SÓ HAVERÁ PAZ, \nNUNCA HAVERÁ DOR.\n\nCORO (2X)\nJESUS, O SENTIDO DE VIVER,\n(DE VIVER SÓ PRA JESUS) VARÕES\nJESUS, O AMOR, A PAZ REAL,\nNÃO HÁ OUTRO AMOR IGUAL. \n\nFINAL: JESUS.', 'O SENTIDO DE VIVER ENCONTRAMOS \nEM JESUS, ELE É A SALVAÇÃO QUE \nHOJE PODES TER;\nÉ SÓ ABRIR TEU CORAÇÃO, \nDEIXAR CRISTO HABITAR, \nA PAZ E A ALEGRIA\nEM TI IRÃO REINAR.\n\n<coro tipo=''2X''>\nJESUS, O SENTIDO DE VIVER,\n(DE VIVER SÓ PRA JESUS) <h>\nJESUS, O AMOR, A PAZ REAL,\nNÃO HÁ OUTRO AMOR IGUAL. \n\nJESUS CRISTO VAI VOLTAR, \nELE UM DIA PROMETEU, \nE SEREMOS TRANSFORMADOS \nPARA O ENCONTRO COM O SENHOR;\nESTAREMOS PARA SEMPRE COM JESUS, \nO REDENTOR, \nONDE SÓ HAVERÁ PAZ, \nNUNCA HAVERÁ DOR.\n\n<coro tipo=''2X''>\nJESUS, O SENTIDO DE VIVER,\n(DE VIVER SÓ PRA JESUS) <h>\nJESUS, O AMOR, A PAZ REAL,\nNÃO HÁ OUTRO AMOR IGUAL. \n<final>JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (227, 'SÓ JESUS TE PODE DAR O QUE PROCURAS', 'SÓ JESUS TE PODE DAR O QUE PROCURAS', 'SÓ JESUS TE PODE DAR O QUE PROCURAS,\nELE É A PORTA QUE SE ABRE PARA O CÉU;\nBATE AGORA E A PORTA SE ABRIRÁ PRA TI,\nE SABERÁS QUE ELE SEMPRE TE ESPEROU. \n\nCORO\nENTRA E VÊ A GLÓRIA, ENTRA E VÊ O AMOR,\nA FARTURA QUE HÁ NA CASA DO SENHOR;\nNADA SE COMPARA AO QUE VÊS AQUI,\nTUDO ISTO DEUS PREPAROU PARA TI.\n\nTANTAS VEZES PERDESTE O RUMO EM TEU VIVER,\nPORTAS FECHADAS QUE NÃO PUDESTE ABRIR;\nMAS JESUS É A PORTA QUE ABRE PARA TI\nUM NOVO DIA PARA TU SERES FELIZ.\n\nCORO\nENTRA E VÊ A GLÓRIA, ENTRA E VÊ O AMOR,\nA FARTURA QUE HÁ NA CASA DO SENHOR;\nNADA SE COMPARA AO QUE VÊS AQUI,\nTUDO ISTO DEUS PREPAROU PARA TI.\n\nFINAL: PREPAROU PARA TI.', 'SÓ JESUS TE PODE DAR O QUE PROCURAS,\nELE É A PORTA QUE SE ABRE PARA O CÉU;\nBATE AGORA E A PORTA SE ABRIRÁ PRA TI,\nE SABERÁS QUE ELE SEMPRE TE ESPEROU. \n\n<coro>\nENTRA E VÊ A GLÓRIA, ENTRA E VÊ O AMOR,\nA FARTURA QUE HÁ NA CASA DO SENHOR;\nNADA SE COMPARA AO QUE VÊS AQUI,\nTUDO ISTO DEUS PREPAROU PARA TI.\n\nTANTAS VEZES PERDESTE O RUMO EM TEU VIVER,\nPORTAS FECHADAS QUE NÃO PUDESTE ABRIR;\nMAS JESUS É A PORTA QUE ABRE PARA TI\nUM NOVO DIA PARA TU SERES FELIZ.\n\n<coro>\nENTRA E VÊ A GLÓRIA, ENTRA E VÊ O AMOR,\nA FARTURA QUE HÁ NA CASA DO SENHOR;\nNADA SE COMPARA AO QUE VÊS AQUI,\nTUDO ISTO DEUS PREPAROU PARA TI.\n<final>PREPAROU PARA TI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (228, 'ENTREGA O TEU CAMINHO AO SENHOR', 'ENTREGA O TEU CAMINHO AO SENHOR', 'ENTREGA O TEU CAMINHO AO SENHOR \nE O MAIS ELE FARÁ, FARÁ SOBRESSAIR A SUA JUSTIÇA \nCOMO A LUZ E O SEU JUÍZO; \nCUMPRIRÁ O TEU DESEJO, \nELE TE MOSTRARÁ O SEU PERDÃO, A SALVAÇÃO,\nA REVELAÇÃO DA PALAVRA DE JESUS (EM TEU SER).\n\nENTREGA O TEU CAMINHO AO \nSENHOR E O MAIS ELE FARÁ,\nFARÁ SOBRESSAIR A SUA JUSTIÇA \nCOMO A LUZ E O SEU JUÍZO, \nO SEU PERDÃO, A SALVAÇÃO,\nA REVELAÇÃO DA PALAVRA DE JESUS (EM TEU SER).\n\nENTREGA O TEU CAMINHO AO SENHOR,\n(ENTREGA O TEU CAMINHO AO SENHOR)\nAO SENHOR.', 'ENTREGA O TEU CAMINHO AO SENHOR \nE O MAIS ELE FARÁ, FARÁ SOBRESSAIR A SUA JUSTIÇA \nCOMO A LUZ E O SEU JUÍZO; \nCUMPRIRÁ O TEU DESEJO, \nELE TE MOSTRARÁ O SEU PERDÃO, A SALVAÇÃO,\nA REVELAÇÃO DA PALAVRA DE JESUS (EM TEU SER).\n\nENTREGA O TEU CAMINHO AO <bis>\nSENHOR E O MAIS ELE FARÁ,<bis>\nFARÁ SOBRESSAIR A SUA JUSTIÇA \nCOMO A LUZ E O SEU JUÍZO, \nO SEU PERDÃO, A SALVAÇÃO,\nA REVELAÇÃO DA PALAVRA DE JESUS (EM TEU SER).\n\nENTREGA O TEU CAMINHO AO SENHOR,\n(ENTREGA O TEU CAMINHO AO SENHOR)\nAO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (229, 'AO POÇO DE JACÓ CHEGOU JESUS', 'AO POÇO DE JACÓ CHEGOU JESUS', 'AO POÇO DE JACÓ CHEGOU JESUS,\nESTAVA CANSADO, ALI CHEGOU PRA DESCANSAR;\nCHEGOU TAMBÉM ALI UMA MULHER,\nCOM SEU CÂNTARO ÁGUA FOI BUSCAR.\nJESUS PEDIU-LHE ÁGUA PRA BEBER, MAS A MULHER FEZ EXCEÇÃO E NÃO LHE DEU, \nPOR SER SAMARITANA, JESUS ERA JUDEU, \nMAS DA ÁGUA QUE JESUS DIZIA, ELA BEBEU.\n\nCORO\nSE TU CONHECERAS O DOM DE DEUS,\nTU PEDIRIAS, ELE DARIA PRA BEBER\nDA ÁGUA MUI SUPERNA,\nQUE SALTA PARA A VIDA ETERNA,\nDESTA ÁGUA SÓ JESUS TEM PARA DAR.\n\nJESUS É MAIS QUE O POÇO DE JACÓ,\nELE É A FONTE DE BASTANTE ÁGUA, É SÓ TOMAR;\nTODOS QUE TÊM PECADO É SÓ CHEGAR,\nESTA ÁGUA TEM PODER PRA LIBERTAR.\nA ÁGUA QUE JESUS DÁ, ELA É SUAVE,\nACONSELHÁVEL, E JESUS MANDA BEBER;\nQUEM TOMA DESTA ÁGUA VIDA ETERNA TEM,\nVIVER COM CRISTO, AQUI E NO ALÉM.\n\nCORO\nSE TU CONHECERAS O DOM DE DEUS,\nTU PEDIRIAS, ELE DARIA PRA BEBER\nDA ÁGUA MUI SUPERNA,\nQUE SALTA PARA A VIDA ETERNA,\nDESTA ÁGUA SÓ JESUS TEM PARA DAR.', 'AO POÇO DE JACÓ CHEGOU JESUS,\nESTAVA CANSADO, ALI CHEGOU PRA DESCANSAR;\nCHEGOU TAMBÉM ALI UMA MULHER,\nCOM SEU CÂNTARO ÁGUA FOI BUSCAR.\nJESUS PEDIU-LHE ÁGUA PRA BEBER, MAS A MULHER FEZ EXCEÇÃO E NÃO LHE DEU, \nPOR SER SAMARITANA, JESUS ERA JUDEU, \nMAS DA ÁGUA QUE JESUS DIZIA, ELA BEBEU.\n\n<coro>\nSE TU CONHECERAS O DOM DE DEUS,\nTU PEDIRIAS, ELE DARIA PRA BEBER\nDA ÁGUA MUI SUPERNA,\nQUE SALTA PARA A VIDA ETERNA,\nDESTA ÁGUA SÓ JESUS TEM PARA DAR.\n\nJESUS É MAIS QUE O POÇO DE JACÓ,\nELE É A FONTE DE BASTANTE ÁGUA, É SÓ TOMAR;\nTODOS QUE TÊM PECADO É SÓ CHEGAR,\nESTA ÁGUA TEM PODER PRA LIBERTAR.\nA ÁGUA QUE JESUS DÁ, ELA É SUAVE,\nACONSELHÁVEL, E JESUS MANDA BEBER;\nQUEM TOMA DESTA ÁGUA VIDA ETERNA TEM,\nVIVER COM CRISTO, AQUI E NO ALÉM.\n\n<coro>\nSE TU CONHECERAS O DOM DE DEUS,\nTU PEDIRIAS, ELE DARIA PRA BEBER\nDA ÁGUA MUI SUPERNA,\nQUE SALTA PARA A VIDA ETERNA,\nDESTA ÁGUA SÓ JESUS TEM PARA DAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (230, 'FONTE DE ÁGUAS VIVAS', 'FONTE DE ÁGUAS VIVAS', 'FONTE DE ÁGUAS VIVAS,\nCRISTO JESUS NOS CONCEDE A PAZ,\nPAZ CELESTIAL;\nSACIA A NOSSA SEDE,\nCONSOLA A ALMA, LIVRA-NOS DO MAL.\n\nQUEM TIVER SEDE, SEDE DE ÁGUAS VIVAS,\n(DE GRAÇA LHE DAREI DA FONTE DA VIDA)\nDE GRAÇA LHE DAREI DA FONTE DA VIDA\n(FONTE DA VIDA).\n\nO CAMINHO DO SENHOR\nÉ VERDADEIRO, RETO E PURO,\nJUSTO E PERFEITO.\nGUARDA OS SEUS SERVOS,\nCOM SEGURANÇA ESTENDE SUA MÃO.\n\nNA HORA DA ANGÚSTIA OU MESMO NA TRISTEZA,\n(JESUS NOSSO REFÚGIO, NOSSA FORTALEZA)\nJESUS NOSSO REFÚGIO, NOSSA FORTALEZA\n(FORTALEZA).\n\nSABEMOS QUE EM BREVE (ALELUIA)\nJESUS VOLTARÁ PARA A SUA GLÓRIA \nA IGREJA LEVAR;\nCOM ELE HABITAREMOS (ALELUIA),\nSEREMOS SEU POVO E ELE O NOSSO DEUS.\n\nNÃO HAVERÁ MAIS MORTE,\nNEM PRANTO OU CLAMOR,\nVIVENDO PARA SEMPRE \nCOM O SALVADOR.\n\nNÃO HAVERÁ MAIS MORTE, \nNEM PRANTO OU CLAMOR\n(VIVENDO PARA SEMPRE COM O SALVADOR)\nVIVENDO PARA SEMPRE COM O SALVADOR\n(COM O SALVADOR).', 'FONTE DE ÁGUAS VIVAS,\nCRISTO JESUS NOS CONCEDE A PAZ,\nPAZ CELESTIAL;\nSACIA A NOSSA SEDE,\nCONSOLA A ALMA, LIVRA-NOS DO MAL.\n\nQUEM TIVER SEDE, SEDE DE ÁGUAS VIVAS,\n(DE GRAÇA LHE DAREI DA FONTE DA VIDA)\nDE GRAÇA LHE DAREI DA FONTE DA VIDA\n(FONTE DA VIDA).\n\nO CAMINHO DO SENHOR\nÉ VERDADEIRO, RETO E PURO,\nJUSTO E PERFEITO.\nGUARDA OS SEUS SERVOS,\nCOM SEGURANÇA ESTENDE SUA MÃO.\n\nNA HORA DA ANGÚSTIA OU MESMO NA TRISTEZA,\n(JESUS NOSSO REFÚGIO, NOSSA FORTALEZA)\nJESUS NOSSO REFÚGIO, NOSSA FORTALEZA\n(FORTALEZA).\n\nSABEMOS QUE EM BREVE (ALELUIA)\nJESUS VOLTARÁ PARA A SUA GLÓRIA \nA IGREJA LEVAR;\nCOM ELE HABITAREMOS (ALELUIA),\nSEREMOS SEU POVO E ELE O NOSSO DEUS.\n\nNÃO HAVERÁ MAIS MORTE,\nNEM PRANTO OU CLAMOR,\nVIVENDO PARA SEMPRE \nCOM O SALVADOR.\n\nNÃO HAVERÁ MAIS MORTE, \nNEM PRANTO OU CLAMOR\n(VIVENDO PARA SEMPRE COM O SALVADOR)\nVIVENDO PARA SEMPRE COM O SALVADOR\n(COM O SALVADOR).', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (231, 'QUEM ME DÁ ÁGUA', 'QUEM ME DÁ ÁGUA', 'QUEM ME DÁ ÁGUA QUANDO ESTOU SEDENTO,\nE TRAZ A PAZ QUANDO ME ENCONTRO AFLITO,\nTIRANDO A ANGÚSTIA DENTRO DA MINH''ALMA,\nME ALEGRANDO COM O SEU PRECIOSO AMOR?\n\nELE É JESUS, O REI, \n(O REI) VARÕES\nNELE ENCONTRO PAZ, \n(A PAZ) VARÕES\nELE É MEU SALVADOR,\n(MEU REDENTOR) VARÕES\nDEUS FORTE, REDENTOR.\n\nQUERES DESCANSO DENTRO DO TEU SER?\nCONFIA EM CRISTO, ELE TEM PODER,\nVENCEU A MORTE LÁ NA CRUZ.\nVIDA É JESUS, VIDA É JESUS.', 'QUEM ME DÁ ÁGUA QUANDO ESTOU SEDENTO,\nE TRAZ A PAZ QUANDO ME ENCONTRO AFLITO,\nTIRANDO A ANGÚSTIA DENTRO DA MINH''ALMA,\nME ALEGRANDO COM O SEU PRECIOSO AMOR?\n\nELE É JESUS, O REI, <bis>\n(O REI) <h><bis>\nNELE ENCONTRO PAZ, <bis>\n(A PAZ) <h><bis>\nELE É MEU SALVADOR,<bis>\n(MEU REDENTOR) <h><bis>\nDEUS FORTE, REDENTOR.<bis>\n\nQUERES DESCANSO DENTRO DO TEU SER?\nCONFIA EM CRISTO, ELE TEM PODER,\nVENCEU A MORTE LÁ NA CRUZ.\nVIDA É JESUS, VIDA É JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (232, 'QUEM BEBER DA ÁGUA QUE EU LHE DER', 'QUEM BEBER DA ÁGUA QUE EU LHE DER', '''QUEM BEBER DA ÁGUA QUE EU LHE DER, \nJAMAIS TERÁ SEDE DE NOVO,\nPOIS DA ÁGUA QUE EU LHE DER\nSE FARÁ UMA FONTE PRA VIDA ETERNA''.\n\nO SENHOR ESTÁ JUNTO A TI,\nPODEROSO PARA TE SALVAR,\nSE HOJE OUVIRES SUA DOCE VOZ,\nNÃO ENDUREÇAS O TEU CORAÇÃO,\nNÃO DIGAS NÃO.\n\n''MAS VEM A MIM,\nÓ TU QUE ESTÁS CANSADO,\nE DESCANSO EU TE DAREI,\nPOIS DA ÁGUA QUE EU TE DER\nSE FARÁ UMA FONTE PRA VIDA ETERNA''.', '''QUEM BEBER DA ÁGUA QUE EU LHE DER, <bis>\nJAMAIS TERÁ SEDE DE NOVO,<bis>\nPOIS DA ÁGUA QUE EU LHE DER<bis>\nSE FARÁ UMA FONTE PRA VIDA ETERNA''.<bis>\n\nO SENHOR ESTÁ JUNTO A TI,\nPODEROSO PARA TE SALVAR,\nSE HOJE OUVIRES SUA DOCE VOZ,\nNÃO ENDUREÇAS O TEU CORAÇÃO,\nNÃO DIGAS NÃO.\n\n''MAS VEM A MIM,\nÓ TU QUE ESTÁS CANSADO,\nE DESCANSO EU TE DAREI,\nPOIS DA ÁGUA QUE EU TE DER<bis>\nSE FARÁ UMA FONTE PRA VIDA ETERNA''. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (233, 'VOU GUIAR-TE A UMA RICA FONTE', 'VOU GUIAR-TE A UMA RICA FONTE', 'VOU GUIAR-TE A UMA RICA FONTE\nDE ÁGUAS CRISTALINAS,\nMATARÁS A TUA SEDE,\nSUBIRÁS MUITAS COLINAS,\nVOU LEVAR-TE AOS ALTOS MONTES.\n\nSOU O SENHOR, SOU A ROCHA \nFONTE QUE JORRA O AMOR,\nSOU A FÉ QUE DESABROCHA\nNAQUELE QUE DESSEDENTO.\nSOU REAL, SOU O SENHOR!\n\nVENHAM, Ó FILHOS QUERIDOS,\nMORAR ALÉM DO HORIZONTE,\nSALTAR PARA A ETERNIDADE,\nBEBER DA ÁGUA DA VIDA. \n\nONDE EU, JESUS, SOU A FONTE \nONDE EU, JESUS, SOU A FONTE\nONDE EU, JESUS, SOU A FONTE', 'VOU GUIAR-TE A UMA RICA FONTE\nDE ÁGUAS CRISTALINAS,\nMATARÁS A TUA SEDE,\nSUBIRÁS MUITAS COLINAS,\nVOU LEVAR-TE AOS ALTOS MONTES.\n\nSOU O SENHOR, SOU A ROCHA \nFONTE QUE JORRA O AMOR,\nSOU A FÉ QUE DESABROCHA\nNAQUELE QUE DESSEDENTO.\nSOU REAL, SOU O SENHOR!\n\nVENHAM, Ó FILHOS QUERIDOS,<bis>\nMORAR ALÉM DO HORIZONTE,<bis>\nSALTAR PARA A ETERNIDADE,<bis>\nBEBER DA ÁGUA DA VIDA. <bis>\n\nONDE EU, JESUS, SOU A FONTE \nONDE EU, JESUS, SOU A FONTE\nONDE EU, JESUS, SOU A FONTE', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (234, 'DEUS HOJE QUER TE FALAR', 'DEUS HOJE QUER TE FALAR', 'DEUS HOJE QUER TE FALAR,\nELE BATE AO TEU CORAÇÃO;\nSE TU ABRIRES, ELE VAI ENTRAR\nE TE DARÁ SALVAÇÃO.\n\nVOZ TÃO SUAVE ELE TEM,\nFALANDO COM TANTO AMOR;\nPOR TI JESUS MORREU NA CRUZ,\nELE É O TEU SALVADOR.\n\nSE HOJE OUVIRES SUA VOZ,\nABRE-LHE TEU CORAÇÃO;\nENTÃO TERÁS AMOR E PAZ\nQUE JAMAIS TERMINARÃO.', 'DEUS HOJE QUER TE FALAR,\nELE BATE AO TEU CORAÇÃO;\nSE TU ABRIRES, ELE VAI ENTRAR\nE TE DARÁ SALVAÇÃO.\n\nVOZ TÃO SUAVE ELE TEM,\nFALANDO COM TANTO AMOR;\nPOR TI JESUS MORREU NA CRUZ,\nELE É O TEU SALVADOR.\n\nSE HOJE OUVIRES SUA VOZ,\nABRE-LHE TEU CORAÇÃO;\nENTÃO TERÁS AMOR E PAZ<bis>\nQUE JAMAIS TERMINARÃO. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (235, 'MANSO E SUAVE JESUS ESTÁ CHAMANDO', 'MANSO E SUAVE JESUS ESTÁ CHAMANDO', 'MANSO E SUAVE JESUS ESTÁ CHAMANDO,\nCHAMA POR TI E POR MIM;\nEIS QUE À PORTA ESPERA VELANDO,\nVELA POR TI E POR MIM.\n\nCORO\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''\n\nO TEMPO CORRE, AS HORAS SE PASSAM,\nPASSAM PRA TI E PRA MIM;\nMORTE E LEITO DE DOR PRESTO CHAMAM,\nCHAMAM POR TI E POR MIM.\n\nCORO\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''\n\nQUE ESPERAMOS? JESUS \nCONVIDANDO,\nCONVIDA A TI E A MIM.\nPOR QUE DESPREZAS MERCÊ \nQUE ESTÁ DANDO, \nDANDO A TI E A MIM?\n\nCORO\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''\n\nOH! QUE AMOR QUE JESUS NOS TEM DADO,\nDADO PRA TI E PRA MIM!\nMORREU PRA SALVAR-NOS DO VIL PECADO, \nSALVAR A TI E A MIM.\n\nCORO\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''', 'MANSO E SUAVE JESUS ESTÁ CHAMANDO,\nCHAMA POR TI E POR MIM;\nEIS QUE À PORTA ESPERA VELANDO,\nVELA POR TI E POR MIM.\n\n<coro>\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''\n\nO TEMPO CORRE, AS HORAS SE PASSAM,\nPASSAM PRA TI E PRA MIM;\nMORTE E LEITO DE DOR PRESTO CHAMAM,\nCHAMAM POR TI E POR MIM.\n\n<coro>\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''\n\nQUE ESPERAMOS? JESUS \nCONVIDANDO,\nCONVIDA A TI E A MIM.\nPOR QUE DESPREZAS MERCÊ \nQUE ESTÁ DANDO, \nDANDO A TI E A MIM?\n\n<coro>\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''\n\nOH! QUE AMOR QUE JESUS NOS TEM DADO,\nDADO PRA TI E PRA MIM!\nMORREU PRA SALVAR-NOS DO VIL PECADO, \nSALVAR A TI E A MIM.\n\n<coro>\nVEM JÁ, VEM JÁ! \nESTÁS CANSADO, VEM JÁ!\nMANSO E SUAVE JESUS ESTÁ CHAMANDO;\nCHAMA: ''Ó PECADOR, VEM!''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (236, 'OUVE A VOZ DE JESUS', 'OUVE A VOZ DE JESUS', 'OUVE A VOZ DE JESUS\nQUE É TÃO LINDA E TÃO CALMA\nE ESTÁ CHAMANDO: ''VEM JÁ!''\nSE ESTÁS CANSADO, DISSE ELE ASSIM:\n''MEU FILHO, VEM HOJE A MIM!''\nINSTRUMENTOS\n\nSE ESTÁS CANSADO, DISSE ELE ASSIM:\n''MEU FILHO, VEM HOJE A MIM!''\n\nMANSO E SUAVE É JESUS,\nQUÃO DOCE E MEIGO É OUVI-LO!\nVEM JÁ OUVIR SUA VOZ;\nSE ESTÁS CANSADO, DISSE JESUS: \n''EU SOU O CAMINHO E A LUZ.''', 'OUVE A VOZ DE JESUS\nQUE É TÃO LINDA E TÃO CALMA\nE ESTÁ CHAMANDO: ''VEM JÁ!''\nSE ESTÁS CANSADO, DISSE ELE ASSIM:\n''MEU FILHO, VEM HOJE A MIM!''\n<instrumentos>\n\n\nSE ESTÁS CANSADO, DISSE ELE ASSIM:\n''MEU FILHO, VEM HOJE A MIM!''\n\nMANSO E SUAVE É JESUS,\nQUÃO DOCE E MEIGO É OUVI-LO!\nVEM JÁ OUVIR SUA VOZ;\nSE ESTÁS CANSADO, DISSE JESUS: <bis>\n''EU SOU O CAMINHO E A LUZ.''<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (237, 'EIS MENSAGEM DO SENHOR', 'EIS MENSAGEM DO SENHOR', 'EIS MENSAGEM DO SENHOR; ALELUIA!\nPALAVRAS DO BOM DEUS DE AMOR!\nCRISTO SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR.\n\nCORO\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!\n\nVOSSA DÍVIDA PAGOU; ALELUIA!\nJESUS A SATISFEZ NA CRUZ.\nSUA VIDA ENTREGOU; ALELUIA!\nPARA VOS APRESENTAR A DEUS!\n\nCORO\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!\n\nESTA OFERTA É FEITA A VÓS; ALELUIA!\nETERNA VIDA LÁ NOS CÉUS!\nOH! OLHAI PRA CRISTO SÓ; ALELUIA!\nCONVERTEI-VOS JÁ AO VOSSO DEUS.\n\nCORO\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!\n\nACEITAI A SALVAÇÃO; ALELUIA!\nSEGUI NOS PASSOS DO SENHOR;\nPUBLICAI O SEU PERDÃO; ALELUIA!\nPROCLAMAI O GRANDE REDENTOR!\n\nCORO\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!', 'EIS MENSAGEM DO SENHOR; ALELUIA!\nPALAVRAS DO BOM DEUS DE AMOR!\nCRISTO SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR.\n\n<coro>\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!\n\nVOSSA DÍVIDA PAGOU; ALELUIA!\nJESUS A SATISFEZ NA CRUZ.\nSUA VIDA ENTREGOU; ALELUIA!\nPARA VOS APRESENTAR A DEUS!\n\n<coro>\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!\n\nESTA OFERTA É FEITA A VÓS; ALELUIA!\nETERNA VIDA LÁ NOS CÉUS!\nOH! OLHAI PRA CRISTO SÓ; ALELUIA!\nCONVERTEI-VOS JÁ AO VOSSO DEUS.\n\n<coro>\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!\n\nACEITAI A SALVAÇÃO; ALELUIA!\nSEGUI NOS PASSOS DO SENHOR;\nPUBLICAI O SEU PERDÃO; ALELUIA!\nPROCLAMAI O GRANDE REDENTOR!\n\n<coro>\nOH! OLHAI, IRMÃOS, OLHAI,\nOH! OLHAI SÓ PRA JESUS.\nELE SALVA O PECADOR; ALELUIA!\nSALVA-O ATÉ POR MEIO DE UM OLHAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (238, 'TANTO TEMPO JÁ FAZ QUE O CHAMADO DIVINAL', 'TANTO TEMPO JÁ FAZ QUE O CHAMADO DIVINAL', 'TANTO TEMPO JÁ FAZ QUE O CHAMADO DIVINAL\nTEM CHEGADO AO VIL PECADOR;\n''SE ESTÁS OPRIMIDO, VEM A MIM SEM TARDAR,\nPOIS EU TE AMO, REPOUSO TE DAREI''.\n\nCORO\nEU PERTENÇO AO REI DO UNIVERSO,\nPARTICIPO DA HERANÇA REAL;\nAO FINDAR O LABUTAR,\nTÉ O FIM DA NOSSA HISTÓRIA\nVIVEREI AOS CUIDADOS DO REI. \n\nPROCURAVA ACHAR UM LUGAR PARA \nMIM, ALMEJAVA JESUS ENCONTRAR;\nTÃO LOGO ELE ACHOU-ME E DEU-ME UM LAR,\nUM NOVO HINO AGORA VOU CANTAR.\n\nCORO\nEU PERTENÇO AO REI DO UNIVERSO,\nPARTICIPO DA HERANÇA REAL;\nAO FINDAR O LABUTAR,\nTÉ O FIM DA NOSSA HISTÓRIA\nVIVEREI AOS CUIDADOS DO REI. (2X)', 'TANTO TEMPO JÁ FAZ QUE O CHAMADO DIVINAL\nTEM CHEGADO AO VIL PECADOR;\n''SE ESTÁS OPRIMIDO, VEM A MIM SEM TARDAR,\nPOIS EU TE AMO, REPOUSO TE DAREI''.\n\n<coro>\nEU PERTENÇO AO REI DO UNIVERSO,\nPARTICIPO DA HERANÇA REAL;\nAO FINDAR O LABUTAR,\nTÉ O FIM DA NOSSA HISTÓRIA\nVIVEREI AOS CUIDADOS DO REI. \n\nPROCURAVA ACHAR UM LUGAR PARA \nMIM, ALMEJAVA JESUS ENCONTRAR;\nTÃO LOGO ELE ACHOU-ME E DEU-ME UM LAR,\nUM NOVO HINO AGORA VOU CANTAR.\n\n<coro>\nEU PERTENÇO AO REI DO UNIVERSO,\nPARTICIPO DA HERANÇA REAL;\nAO FINDAR O LABUTAR,\nTÉ O FIM DA NOSSA HISTÓRIA\nVIVEREI AOS CUIDADOS DO REI. <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (239, 'DEIXA DEUS FALAR AO TEU CORAÇÃO', 'DEIXA DEUS FALAR AO TEU CORAÇÃO', 'DEIXA DEUS FALAR AO TEU CORAÇÃO,\nELE QUER SE REVELAR A TI,\nSUA VOZ APRENDE A ESCUTAR,\nDEIXA DEUS TE FALAR;\nBUSCA MAIS SUA PRESENÇA,\nVIGIANDO EM ORAÇÃO,\nSUA VOZ IRÁS, ENTÃO, OUVIR\nFALANDO AO TEU CORAÇÃO.\n\nTEUS PROBLEMAS DEUS PODE RESOLVER,\nDÁ-LHE TUA VIDA SEM TEMER,\nSE TEUS PASSOS DEIXAS DEUS GUIAR,\nPAZ IRÁS EXPERIMENTAR;\nELE TEM UM PLANO PARA TI\nE TE GUIA COM SUA MÃO,\nSIM, ESCUTA O QUE ELE AGORA DIZ,\nFALANDO AO TEU CORAÇÃO. (BIS)', 'DEIXA DEUS FALAR AO TEU CORAÇÃO,\nELE QUER SE REVELAR A TI,\nSUA VOZ APRENDE A ESCUTAR,\nDEIXA DEUS TE FALAR;\nBUSCA MAIS SUA PRESENÇA,\nVIGIANDO EM ORAÇÃO,\nSUA VOZ IRÁS, ENTÃO, OUVIR\nFALANDO AO TEU CORAÇÃO.\n\nTEUS PROBLEMAS DEUS PODE RESOLVER,\nDÁ-LHE TUA VIDA SEM TEMER,\nSE TEUS PASSOS DEIXAS DEUS GUIAR,\nPAZ IRÁS EXPERIMENTAR;\nELE TEM UM PLANO PARA TI\nE TE GUIA COM SUA MÃO,\nSIM, ESCUTA O QUE ELE AGORA DIZ,\nFALANDO AO TEU CORAÇÃO. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (240, 'SE CANSADO TU ESTÁS', 'SE CANSADO TU ESTÁS', 'SE CANSADO TU ESTÁS, \nSOBRECARREGADO SIM, \nDEIXA TUDO AGORA, DIGO: \nVEM A MIM!\nEU TE ALIVIAREI, PÕE TEU FARDO \nSOBRE MIM, DEIXA TUDO AGORA, \nDIGO: VEM A MIM!\n\nVEM A MIM, Ó PECADOR,\nQUERO SER TEU SALVADOR,\nPOIS SOU MANSO \nE HUMILDE DE CORAÇÃO;\nVEM A MIM, DESCANSARÁS,\nTUA ALMA REPOUSARÁ,\nQUE SUAVE É MEU JUGO \nE LEVE O MEU FARDO.', 'SE CANSADO TU ESTÁS, \nSOBRECARREGADO SIM, \nDEIXA TUDO AGORA, DIGO: \nVEM A MIM!\nEU TE ALIVIAREI, PÕE TEU FARDO \nSOBRE MIM, DEIXA TUDO AGORA, \nDIGO: VEM A MIM!\n\nVEM A MIM, Ó PECADOR,<bis>\nQUERO SER TEU SALVADOR,<bis>\nPOIS SOU MANSO <bis>\nE HUMILDE DE CORAÇÃO;<bis>\nVEM A MIM, DESCANSARÁS,<bis>\nTUA ALMA REPOUSARÁ,<bis>\nQUE SUAVE É MEU JUGO <bis>\nE LEVE O MEU FARDO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (241, 'MEU AMADO FILHO', 'MEU AMADO FILHO', 'MEU AMADO FILHO, TE ESCOLHI,\nNÃO TEMAS, MAS ESFORÇA-TE,\nASSIM DIZ O SENHOR;\nMINHA MÃO ESTENDIDA PARA TI, \nPOR ONDE QUER QUE FORES, \nNÃO TE DEIXAREI.\n\nCORO (2X)\nMINHA PAZ EU TE DOU,\nNÃO TE DEIXAREI, DIZ O SENHOR.\n\nA TERRA PROMETIDA TE DAREI,\nA ÁRVORE DA VIDA TE CONCEDEREI;\nRIOS DE ÁGUA VIVA FLUIRÃO\nE O MEU IMENSO AMOR NO TEU CORAÇÃO.\n\nCORO (2X)\nMINHA PAZ EU TE DOU,\nNÃO TE DEIXAREI, DIZ O SENHOR.\n\nNÃO TE DEIXAREI, DIZ O SENHOR. (3X)', 'MEU AMADO FILHO, TE ESCOLHI,\nNÃO TEMAS, MAS ESFORÇA-TE,\nASSIM DIZ O SENHOR;\nMINHA MÃO ESTENDIDA PARA TI, \nPOR ONDE QUER QUE FORES, \nNÃO TE DEIXAREI.\n\n<coro tipo=''2X''>\nMINHA PAZ EU TE DOU,\nNÃO TE DEIXAREI, DIZ O SENHOR.\n\nA TERRA PROMETIDA TE DAREI,\nA ÁRVORE DA VIDA TE CONCEDEREI;\nRIOS DE ÁGUA VIVA FLUIRÃO\nE O MEU IMENSO AMOR NO TEU CORAÇÃO.\n\n<coro tipo=''2X''>\nMINHA PAZ EU TE DOU,\nNÃO TE DEIXAREI, DIZ O SENHOR.\n\nNÃO TE DEIXAREI, DIZ O SENHOR. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (242, 'SE ESTA NOITE DEUS PEDIR TUA ALMA', 'SE ESTA NOITE DEUS PEDIR TUA ALMA', 'SE ESTA NOITE DEUS PEDIR TUA ALMA,\nO QUE TENS PREPARADO, PRA QUEM SERÁ?\nDE QUE SERVE CIÊNCIA OU RIQUEZA\nSE TUA ALMA PRA SEMPRE PERDERÁS?\n\nCORO\nVEM A JESUS, HOJE, SEM TARDAR,\nDOS FARDOS TEUS ELE QUER TE LIBERTAR;\nSE ESTA NOITE DEUS PEDIR TUA ALMA,\nPODES CRER: O CÉU SERÁ TEU LAR.\n\nINSTRUMENTOS\n\nDE QUE VALE TER TUDO NESTA VIDA\nE NÃO TER A CERTEZA DA SALVAÇÃO?\nTU PRECISAS VIR HOJE AO SALVADOR,\nPELA FÉ NO SEU SANGUE, TER PERDÃO.\n\nCORO\nVEM A JESUS, HOJE, SEM TARDAR,\nDOS FARDOS TEUS ELE QUER TE LIBERTAR;\nSE ESTA NOITE DEUS PEDIR TUA ALMA,\nPODES CRER: O CÉU SERÁ TEU LAR.', 'SE ESTA NOITE DEUS PEDIR TUA ALMA,\nO QUE TENS PREPARADO, PRA QUEM SERÁ?\nDE QUE SERVE CIÊNCIA OU RIQUEZA\nSE TUA ALMA PRA SEMPRE PERDERÁS?\n\n<coro>\nVEM A JESUS, HOJE, SEM TARDAR,\nDOS FARDOS TEUS ELE QUER TE LIBERTAR;\nSE ESTA NOITE DEUS PEDIR TUA ALMA,\nPODES CRER: O CÉU SERÁ TEU LAR.\n<instrumentos>\n\n\nDE QUE VALE TER TUDO NESTA VIDA\nE NÃO TER A CERTEZA DA SALVAÇÃO?\nTU PRECISAS VIR HOJE AO SALVADOR,\nPELA FÉ NO SEU SANGUE, TER PERDÃO.\n\n<coro>\nVEM A JESUS, HOJE, SEM TARDAR,\nDOS FARDOS TEUS ELE QUER TE LIBERTAR;\nSE ESTA NOITE DEUS PEDIR TUA ALMA,\nPODES CRER: O CÉU SERÁ TEU LAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (243, 'JÁ ACHEI UMA FLOR GLORIOSA', 'JÁ ACHEI UMA FLOR GLORIOSA', 'JÁ ACHEI UMA FLOR GLORIOSA\nE QUEM DESEJA A MESMA TERÁ;\nA ROSA DE SAROM PRECIOSA\nENTRE MIL A MAIS BELA SERÁ;\nNO VALE DE SOMBRA E MORTE,\nNAS ALTURAS DE GLÓRIA E DE LUZ,\nESTA ROSA SERÁ A MINHA SORTE,\nPRECIOSO PRA MIM É JESUS!\n\nCORO\nPRECIOSO PRA MIM É JESUS! (BIS)\nEU CONFESSO NA VIDA E NA MORTE\nQUE TUDO PRA MIM É JESUS!\n\nJÁ DE MUITOS FOI ACHADA A ROSA\nE PROVADO O EXCELENTE ODOR\nE O PODER DESTA FLOR GLORIOSA\nQUE DÁ VIDA AO VIL PECADOR;\nMUI ZELOSO PELA LEI FOI SAULO,\nPERSEGUIA O POVO DE DEUS,\nMAS TRANSFORMADO FOI EM UM PAULO\nPOIS ACHOU ELE A ROSA DOS CÉUS.\n\nCORO\nPRECIOSO PRA MIM É JESUS! (BIS)\nEU CONFESSO NA VIDA E NA MORTE\nQUE TUDO PRA MIM É JESUS!\n\nVAI BUSCAR A JESUS PRECIOSO,\nVAI DEPRESSA, A NOITE JÁ VEM,\nE SE PERDES O AMOR GLORIOSO,\nSERÁ TRISTE PRA TI O ALÉM;\nESTA FLOR HOJE É OFERTADA\nA QUEM HUMILDEMENTE A BUSCAR,\nSERÁ LOGO DA TERRA TIRADA\nPARA BRILHAR EM OUTRO LUGAR.\n\nCORO\nPRECIOSO PRA MIM É JESUS! (BIS)\nEU CONFESSO NA VIDA E NA MORTE\nQUE TUDO PRA MIM É JESUS!', 'JÁ ACHEI UMA FLOR GLORIOSA\nE QUEM DESEJA A MESMA TERÁ;\nA ROSA DE SAROM PRECIOSA\nENTRE MIL A MAIS BELA SERÁ;\nNO VALE DE SOMBRA E MORTE,\nNAS ALTURAS DE GLÓRIA E DE LUZ,\nESTA ROSA SERÁ A MINHA SORTE,\nPRECIOSO PRA MIM É JESUS!\n\n<coro>\nPRECIOSO PRA MIM É JESUS! <bis>\nEU CONFESSO NA VIDA E NA MORTE\nQUE TUDO PRA MIM É JESUS!\n\nJÁ DE MUITOS FOI ACHADA A ROSA\nE PROVADO O EXCELENTE ODOR\nE O PODER DESTA FLOR GLORIOSA\nQUE DÁ VIDA AO VIL PECADOR;\nMUI ZELOSO PELA LEI FOI SAULO,\nPERSEGUIA O POVO DE DEUS,\nMAS TRANSFORMADO FOI EM UM PAULO\nPOIS ACHOU ELE A ROSA DOS CÉUS.\n\n<coro>\nPRECIOSO PRA MIM É JESUS! <bis>\nEU CONFESSO NA VIDA E NA MORTE\nQUE TUDO PRA MIM É JESUS!\n\nVAI BUSCAR A JESUS PRECIOSO,\nVAI DEPRESSA, A NOITE JÁ VEM,\nE SE PERDES O AMOR GLORIOSO,\nSERÁ TRISTE PRA TI O ALÉM;\nESTA FLOR HOJE É OFERTADA\nA QUEM HUMILDEMENTE A BUSCAR,\nSERÁ LOGO DA TERRA TIRADA\nPARA BRILHAR EM OUTRO LUGAR.\n\n<coro>\nPRECIOSO PRA MIM É JESUS! <bis>\nEU CONFESSO NA VIDA E NA MORTE\nQUE TUDO PRA MIM É JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (244, 'EU DESCI PARA O VALE DE BÊNÇÃO E PAZ', 'EU DESCI PARA O VALE DE BÊNÇÃO E PAZ', 'EU DESCI PARA O VALE DE BÊNÇÃO E PAZ\nE SINTO COMIGO JESUS;\nSEU SANGUE, AOS HUMILDES, \nGARANTE O PERDÃO,\nSEU ESPÍRITO OS ENCHE DE LUZ.\n\nCORO\nENTRAI NESSE VALE DE BÊNÇÃO E \nPAZ ONDE CRISTO REVELA AFEIÇÃO;\nACEITAI, ABRAÇAI, CONFESSAI-O,\nPUBLICAI QUE NELE HÁ SALVAÇÃO.\n\nHÁ FESTIM NESSE VALE DE BÊNÇÃO \nE PAZ E RIQUEZA DE INCRÍVEL VALOR;\nMAS SOMENTE OS FIÉIS \nÉ QUE PODEM CONTAR \nCOM A GRAÇA DO BOM SALVADOR.\n\nCORO\nENTRAI NESSE VALE DE BÊNÇÃO E \nPAZ ONDE CRISTO REVELA AFEIÇÃO;\nACEITAI, ABRAÇAI, CONFESSAI-O,\nPUBLICAI QUE NELE HÁ SALVAÇÃO.\n\nHÁ SALMOS NO VALE DE BÊNÇÃO \nE PAZ E OS ANJOS DESEJAM \nSE UNIR A CANTAR COM OS HOMENS \nO EXCELSO LOUVOR DE JESUS \nQUE NOS VEIO REMIR.\n\nCORO\nENTRAI NESSE VALE DE BÊNÇÃO E \nPAZ ONDE CRISTO REVELA AFEIÇÃO;\nACEITAI, ABRAÇAI, CONFESSAI-O,\nPUBLICAI QUE NELE HÁ SALVAÇÃO.', 'EU DESCI PARA O VALE DE BÊNÇÃO E PAZ\nE SINTO COMIGO JESUS;\nSEU SANGUE, AOS HUMILDES, \nGARANTE O PERDÃO,\nSEU ESPÍRITO OS ENCHE DE LUZ.\n\n<coro>\nENTRAI NESSE VALE DE BÊNÇÃO E \nPAZ ONDE CRISTO REVELA AFEIÇÃO;\nACEITAI, ABRAÇAI, CONFESSAI-O,\nPUBLICAI QUE NELE HÁ SALVAÇÃO.\n\nHÁ FESTIM NESSE VALE DE BÊNÇÃO \nE PAZ E RIQUEZA DE INCRÍVEL VALOR;\nMAS SOMENTE OS FIÉIS \nÉ QUE PODEM CONTAR \nCOM A GRAÇA DO BOM SALVADOR.\n\n<coro>\nENTRAI NESSE VALE DE BÊNÇÃO E \nPAZ ONDE CRISTO REVELA AFEIÇÃO;\nACEITAI, ABRAÇAI, CONFESSAI-O,\nPUBLICAI QUE NELE HÁ SALVAÇÃO.\n\nHÁ SALMOS NO VALE DE BÊNÇÃO \nE PAZ E OS ANJOS DESEJAM \nSE UNIR A CANTAR COM OS HOMENS \nO EXCELSO LOUVOR DE JESUS \nQUE NOS VEIO REMIR.\n\n<coro>\nENTRAI NESSE VALE DE BÊNÇÃO E \nPAZ ONDE CRISTO REVELA AFEIÇÃO;\nACEITAI, ABRAÇAI, CONFESSAI-O,\nPUBLICAI QUE NELE HÁ SALVAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (245, 'POR ONDE QUER QUE EU VÁ', 'POR ONDE QUER QUE EU VÁ', 'POR ONDE QUER QUE EU VÁ\nCOM CRISTO ESTAREI,\nNÃO IMPORTA O QUE VIER,\nELE ME AJUDARÁ;\nMESMO QUE MINHA VIDA\nNO MUNDO CHEGUE AO FIM,\nTEREI UMA NOVA VIDA,\nETERNA, COM JESUS.\n\nCORO \nQUERES SER FELIZ? \nCANTA COMO EU, SABE QUE JESUS POR TI MORREU.\nQUERES NESTE MUNDO SER UM VENCEDOR?\nENTREGA-TE A JESUS, O SALVADOR.\n\nINSTRUMENTOS\n\nJESUS DISSE: ''VINDE A MIM\nVÓS QUE ESTAIS CANSADOS,\nQUE EU VOS ALIVIAREI\nE TAMBÉM VOS SALVAREI''.\nJESUS, EU QUERO OUVIR\nO TOQUE DA TROMBETA,\nNESSE DIA EU QUERO IR\nAOS CÉUS TE ENCONTRAR.\n\nCORO (2X)\nQUERES SER FELIZ? \nCANTA COMO EU, SABE QUE JESUS POR TI MORREU.\nQUERES NESTE MUNDO SER UM VENCEDOR?\nENTREGA-TE A JESUS, O SALVADOR.', 'POR ONDE QUER QUE EU VÁ\nCOM CRISTO ESTAREI,\nNÃO IMPORTA O QUE VIER,\nELE ME AJUDARÁ;\nMESMO QUE MINHA VIDA\nNO MUNDO CHEGUE AO FIM,\nTEREI UMA NOVA VIDA,\nETERNA, COM JESUS.\n\n<coro>\nQUERES SER FELIZ? \nCANTA COMO EU, SABE QUE JESUS POR TI MORREU.\nQUERES NESTE MUNDO SER UM VENCEDOR?\nENTREGA-TE A JESUS, O SALVADOR.\n<instrumentos>\n\n\nJESUS DISSE: ''VINDE A MIM\nVÓS QUE ESTAIS CANSADOS,\nQUE EU VOS ALIVIAREI\nE TAMBÉM VOS SALVAREI''.\nJESUS, EU QUERO OUVIR\nO TOQUE DA TROMBETA,\nNESSE DIA EU QUERO IR\nAOS CÉUS TE ENCONTRAR.\n\n<coro tipo=''2X''>\nQUERES SER FELIZ? \nCANTA COMO EU, SABE QUE JESUS POR TI MORREU.\nQUERES NESTE MUNDO SER UM VENCEDOR?\nENTREGA-TE A JESUS, O SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (246, 'SE EM TEU VIVER', 'SE EM TEU VIVER', 'SE EM TEU VIVER EXISTE UM VAZIO,\nSE TU NÃO PODES CANTAR\nCOM OS QUE CANTAM PRA JESUS,\nNÃO TE DETENHAS, NÃO CHORES, \nMEU AMIGO,\nCRISTO TRANSFORMA AS TREVAS \nEM PLENA LUZ.\n\nCORO\nFELIZ SERÁS, JAMAIS VERÁS\nTUA VIDA EM PRANTO SE FINDAR;\nFELIZ SERÁS SE AO SENHOR\nTEU CORAÇÃO ENTREGAR.\n\nCONTEMPLA AGORA AS BÊNÇÃOS DE CRISTO, \nQUANDO, EM SORRISOS, \nTUAS LÁGRIMAS ELE VAI TRANSFORMAR,\nPRA SEMPRE GUIARÁ OS TEUS CAMINHOS\nE COM AMOR AO CÉU TE LEVARÁ.\n\nCORO\nFELIZ SERÁS, JAMAIS VERÁS\nTUA VIDA EM PRANTO SE FINDAR;\nFELIZ SERÁS SE AO SENHOR\nTEU CORAÇÃO ENTREGAR.', 'SE EM TEU VIVER EXISTE UM VAZIO,\nSE TU NÃO PODES CANTAR\nCOM OS QUE CANTAM PRA JESUS,\nNÃO TE DETENHAS, NÃO CHORES, \nMEU AMIGO,\nCRISTO TRANSFORMA AS TREVAS \nEM PLENA LUZ.\n\n<coro>\nFELIZ SERÁS, JAMAIS VERÁS\nTUA VIDA EM PRANTO SE FINDAR;\nFELIZ SERÁS SE AO SENHOR\nTEU CORAÇÃO ENTREGAR.\n\nCONTEMPLA AGORA AS BÊNÇÃOS DE CRISTO, \nQUANDO, EM SORRISOS, \nTUAS LÁGRIMAS ELE VAI TRANSFORMAR,\nPRA SEMPRE GUIARÁ OS TEUS CAMINHOS\nE COM AMOR AO CÉU TE LEVARÁ.\n\n<coro>\nFELIZ SERÁS, JAMAIS VERÁS\nTUA VIDA EM PRANTO SE FINDAR;\nFELIZ SERÁS SE AO SENHOR\nTEU CORAÇÃO ENTREGAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (247, 'SE ANDA TRISTE O TEU VIVER', 'SE ANDA TRISTE O TEU VIVER', 'SE ANDA TRISTE O TEU VIVER,\nSE ESTÁ VAZIO O TEU CORAÇÃO,\nEXISTE ALGUÉM QUE PODE DAR\nA PAZ QUE TANTO VENS A PROCURAR.\n\nCORO \nJESUS, ESSE ALGUÉM!\nJESUS, PODE DAR ALGO QUE VENS A PROCURAR,\nJESUS, BOM AMIGO QUE NÃO PODE FALTAR.\n\nSE ANDAS SEM A SOLUÇÃO,\nANGÚSTIA INVADE O TEU CORAÇÃO,\nEXISTE ALGUÉM QUE PODE DAR\nA PAZ QUE TANTO VENS A PROCURAR.\n\nCORO (2X)\nJESUS, ESSE ALGUÉM!\nJESUS, PODE DAR ALGO QUE VENS A PROCURAR,\nJESUS, BOM AMIGO QUE NÃO PODE FALTAR.', 'SE ANDA TRISTE O TEU VIVER,\nSE ESTÁ VAZIO O TEU CORAÇÃO,\nEXISTE ALGUÉM QUE PODE DAR\nA PAZ QUE TANTO VENS A PROCURAR.\n\n<coro>\nJESUS, ESSE ALGUÉM!\nJESUS, PODE DAR ALGO QUE VENS A PROCURAR,\nJESUS, BOM AMIGO QUE NÃO PODE FALTAR.\n\nSE ANDAS SEM A SOLUÇÃO,\nANGÚSTIA INVADE O TEU CORAÇÃO,\nEXISTE ALGUÉM QUE PODE DAR\nA PAZ QUE TANTO VENS A PROCURAR.\n\n<coro tipo=''2X''>\nJESUS, ESSE ALGUÉM!\nJESUS, PODE DAR ALGO QUE VENS A PROCURAR,\nJESUS, BOM AMIGO QUE NÃO PODE FALTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (248, 'SE VOCÊ QUISER SABER', 'SE VOCÊ QUISER SABER', 'SE VOCÊ QUISER SABER COMO PODE SER FELIZ,\nBASTA ABRIR SEU CORAÇÃO E ACEITAR JESUS.\n\nSE VOCÊ QUER CONHECER\nESTE DEUS MARAVILHOSO\nQUE DE BÊNÇÃOS VAI ENCHER SEU CORAÇÃO.\n\nCORO\nNELE HÁ TANTA VIDA,\nCERTEZAS E ESPERANÇAS,\nVIDA ETERNA E PAZ SEM FIM;\nNELE HÁ SALVAÇÃO.\n\nSE VOCÊ QUISER GOZAR\nDESTA GRANDE SALVAÇÃO,\nVENHA HOJE A JESUS SE ENTREGAR.\n\nCORO\nNELE HÁ TANTA VIDA,\nCERTEZAS E ESPERANÇAS,\nVIDA ETERNA E PAZ SEM FIM;\nNELE HÁ SALVAÇÃO.\n\nFINAL: \nSE VOCÊ QUISER SABER \nCOMO PODE SER FELIZ,\nBASTA ABRIR SEU CORAÇÃO \nE ACEITAR JESUS.', 'SE VOCÊ QUISER SABER COMO PODE SER FELIZ,\nBASTA ABRIR SEU CORAÇÃO E ACEITAR JESUS.\n\nSE VOCÊ QUER CONHECER\nESTE DEUS MARAVILHOSO\nQUE DE BÊNÇÃOS VAI ENCHER SEU CORAÇÃO.\n\n<coro>\nNELE HÁ TANTA VIDA,\nCERTEZAS E ESPERANÇAS,\nVIDA ETERNA E PAZ SEM FIM;\nNELE HÁ SALVAÇÃO.\n\nSE VOCÊ QUISER GOZAR\nDESTA GRANDE SALVAÇÃO,\nVENHA HOJE A JESUS SE ENTREGAR.\n\n<coro>\nNELE HÁ TANTA VIDA,\nCERTEZAS E ESPERANÇAS,\nVIDA ETERNA E PAZ SEM FIM;\nNELE HÁ SALVAÇÃO.\n\n\n<final>SE VOCÊ QUISER SABER \nCOMO PODE SER FELIZ,\nBASTA ABRIR SEU CORAÇÃO \nE ACEITAR JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (249, 'SE EM TUA VIDA FALTA PAZ', 'SE EM TUA VIDA FALTA PAZ', 'SE EM TUA VIDA FALTA PAZ,\nSE EM TEU VIVER NÃO EXISTE AMOR,\nQUERO TE FALAR DO MEU SENHOR,\nE UMA VIDA NOVA ENCONTRARÁS.\n\nCORO\nCRISTO É A VIDA, ELE É A PAZ,\nFONTE DE ÁGUA VIVA\nQUE A TODOS SATISFAZ.\n\nSÊ UMA NOVA CRIATURA,\nENTREGA OS TEUS PECADOS A JESUS,\nARREPENDE-TE E COMEÇA A VIVER,\nANUNCIANDO QUE JESUS É A SALVAÇÃO.\n\nCORO\nCRISTO É A VIDA, ELE É A PAZ,\nFONTE DE ÁGUA VIVA\nQUE A TODOS SATISFAZ.', 'SE EM TUA VIDA FALTA PAZ,\nSE EM TEU VIVER NÃO EXISTE AMOR,\nQUERO TE FALAR DO MEU SENHOR,\nE UMA VIDA NOVA ENCONTRARÁS.\n\n<coro>\nCRISTO É A VIDA, ELE É A PAZ,\nFONTE DE ÁGUA VIVA\nQUE A TODOS SATISFAZ.\n\nSÊ UMA NOVA CRIATURA,\nENTREGA OS TEUS PECADOS A JESUS,\nARREPENDE-TE E COMEÇA A VIVER,\nANUNCIANDO QUE JESUS É A SALVAÇÃO.\n\n<coro>\nCRISTO É A VIDA, ELE É A PAZ,\nFONTE DE ÁGUA VIVA\nQUE A TODOS SATISFAZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (250, 'SE TU PROCURAS PELA PAZ', 'SE TU PROCURAS PELA PAZ', 'SE TU PROCURAS PELA PAZ,\nSE VAZIO ESTÁ TEU SER,\nNUNCA O MUNDO BUSCARÁS,\nMAS DEVES A JESUS TEMER;\nSE PROCURARES MAIS A CRISTO,\nSÓ VERDADE ENCONTRARÁS,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ. \n\nCORO\nCRISTO SATISFAZ,\nSÓ CRISTO A ALMA SATISFAZ,\nE ELE PODE COMPLETAR TEU CORAÇÃO;\nDARÁ A PAZ, TÃO DOCE AMOR,\nENFIM NOS CÉUS HABITARÁS,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ.\n\nSE FAMA E BENS ALMEJAS TER,\nTÃO EM VÃO É O TEU VIVER,\nPOIS A CRISTO NÃO TERÁS,\nA REDENÇÃO SÓ ELE DÁ;\nJAMAIS EM BENS CONFIARÁS,\nSALVAÇÃO ALI NÃO HÁ,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ.\n\nCORO\nCRISTO SATISFAZ,\nSÓ CRISTO A ALMA SATISFAZ,\nE ELE PODE COMPLETAR TEU CORAÇÃO;\nDARÁ A PAZ, TÃO DOCE AMOR,\nENFIM NOS CÉUS HABITARÁS,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ.\n\nFINAL: CRISTO SATISFAZ!', 'SE TU PROCURAS PELA PAZ,\nSE VAZIO ESTÁ TEU SER,\nNUNCA O MUNDO BUSCARÁS,\nMAS DEVES A JESUS TEMER;\nSE PROCURARES MAIS A CRISTO,\nSÓ VERDADE ENCONTRARÁS,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ. \n\n<coro>\nCRISTO SATISFAZ,\nSÓ CRISTO A ALMA SATISFAZ,\nE ELE PODE COMPLETAR TEU CORAÇÃO;\nDARÁ A PAZ, TÃO DOCE AMOR,\nENFIM NOS CÉUS HABITARÁS,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ.\n\nSE FAMA E BENS ALMEJAS TER,\nTÃO EM VÃO É O TEU VIVER,\nPOIS A CRISTO NÃO TERÁS,\nA REDENÇÃO SÓ ELE DÁ;\nJAMAIS EM BENS CONFIARÁS,\nSALVAÇÃO ALI NÃO HÁ,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ.\n\n<coro>\nCRISTO SATISFAZ,\nSÓ CRISTO A ALMA SATISFAZ,\nE ELE PODE COMPLETAR TEU CORAÇÃO;\nDARÁ A PAZ, TÃO DOCE AMOR,\nENFIM NOS CÉUS HABITARÁS,\nPOIS SÓ MEU CRISTO \nA ALMA SATISFAZ.\n<final>CRISTO SATISFAZ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (251, 'A PAZ QUE TU PROCURAS', 'A PAZ QUE TU PROCURAS', 'A PAZ QUE TU PROCURAS, \nA ALEGRIA QUE ALMEJAS\nHOJE PODES ENCONTRAR,\nAQUELE QUE POR TI MORREU\nHOJE AQUI ESTÁ E QUER TE SALVAR.\n\nCORO \nLOUVAI A JESUS\nE JUNTOS EXALTEMOS O SEU NOME,\nPROCLAMAI, (MARANATA!) \nPROCLAMAI: ELE VOLTARÁ! \n\nINSTRUMENTOS\n\nELE ESTÁ A TE CONTEMPLAR\nE COM SUA DOCE VOZ IRÁ FALAR\nAO TEU CORAÇÃO:\n''VEM, FILHO MEU, RECEBE A VIDA\nQUE ESTAVAS A PROCURAR.''\n\nCORO (2X)\nLOUVAI A JESUS\nE JUNTOS EXALTEMOS O SEU NOME,\nPROCLAMAI, (MARANATA!) \nPROCLAMAI: ELE VOLTARÁ! \n\nFINAL: \nPROCLAMAI (MARANATA!) \nPROCLAMAI: ELE VOLTARÁ!', 'A PAZ QUE TU PROCURAS, \nA ALEGRIA QUE ALMEJAS\nHOJE PODES ENCONTRAR,\nAQUELE QUE POR TI MORREU\nHOJE AQUI ESTÁ E QUER TE SALVAR.\n\n<coro>\nLOUVAI A JESUS\nE JUNTOS EXALTEMOS O SEU NOME,\nPROCLAMAI, (MARANATA!) \nPROCLAMAI: ELE VOLTARÁ! \n<instrumentos>\n\n\nELE ESTÁ A TE CONTEMPLAR\nE COM SUA DOCE VOZ IRÁ FALAR\nAO TEU CORAÇÃO:\n''VEM, FILHO MEU, RECEBE A VIDA\nQUE ESTAVAS A PROCURAR.''\n\n<coro tipo=''2X''>\nLOUVAI A JESUS\nE JUNTOS EXALTEMOS O SEU NOME,\nPROCLAMAI, (MARANATA!) \nPROCLAMAI: ELE VOLTARÁ! \n<final>PROCLAMAI (MARANATA!) \nPROCLAMAI: ELE VOLTARÁ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (252, 'SE DISPUSERES O TEU CORAÇÃO (JÓ 11:13-19)', 'SE DISPUSERES O TEU CORAÇÃO (JÓ 11:13-19)', 'SE DISPUSERES O TEU CORAÇÃO\nE ESTENDERES AS MÃOS A DEUS,\nSE LANÇARES LONGE DE TUAS MÃOS \nTODA A INIQÜIDADE,\nSE NÃO PERMITIRES HABITAR\nEM TUA TENDA A INJUSTIÇA.\n\nCORO\nENTÃO LEVANTARÁS \nO TEU ROSTO SEM MÁCULA,\nESTARÁS SEGURO E NÃO TEMERÁS,\nPOIS TE ESQUECERÁS \nDOS TEUS SOFRIMENTOS,\nDELES TE LEMBRARÁS\nCOMO ÁGUAS QUE PASSARAM.\n\nTUA VIDA SERÁ MAIS CLARA QUE O MEIO DIA,\nAINDA QUE HAJA TREVAS, SERÁ COMO A MANHÃ,\nSENTIR-TE-ÁS SEGURO PORQUE HAVERÁ ESPERANÇA.\n\nCORO\nENTÃO LEVANTARÁS \nO TEU ROSTO SEM MÁCULA,\nESTARÁS SEGURO E NÃO TEMERÁS,\nPOIS TE ESQUECERÁS \nDOS TEUS SOFRIMENTOS,\nDELES TE LEMBRARÁS\nCOMO ÁGUAS QUE PASSARAM.\n\nOLHARÁS AO REDOR E DORMIRÁS TRANQUILO,\nDEITAR-TE-ÁS E NINGUÉM TE ESPANTARÁ,\nMUITOS PROCURARÃO OBTER O TEU FAVOR.\n\nCORO\nENTÃO LEVANTARÁS \nO TEU ROSTO SEM MÁCULA,\nESTARÁS SEGURO E NÃO TEMERÁS,\nPOIS TE ESQUECERÁS \nDOS TEUS SOFRIMENTOS,\nDELES TE LEMBRARÁS\nCOMO ÁGUAS QUE PASSARAM.\nSE DISPUSERES O TEU CORAÇÃO. (BIS)', 'SE DISPUSERES O TEU CORAÇÃO\nE ESTENDERES AS MÃOS A DEUS,\nSE LANÇARES LONGE DE TUAS MÃOS \nTODA A INIQÜIDADE,\nSE NÃO PERMITIRES HABITAR\nEM TUA TENDA A INJUSTIÇA.\n\n<coro>\nENTÃO LEVANTARÁS \nO TEU ROSTO SEM MÁCULA,\nESTARÁS SEGURO E NÃO TEMERÁS,\nPOIS TE ESQUECERÁS \nDOS TEUS SOFRIMENTOS,\nDELES TE LEMBRARÁS\nCOMO ÁGUAS QUE PASSARAM.\n\nTUA VIDA SERÁ MAIS CLARA QUE O MEIO DIA,\nAINDA QUE HAJA TREVAS, SERÁ COMO A MANHÃ,\nSENTIR-TE-ÁS SEGURO PORQUE HAVERÁ ESPERANÇA.\n\n<coro>\nENTÃO LEVANTARÁS \nO TEU ROSTO SEM MÁCULA,\nESTARÁS SEGURO E NÃO TEMERÁS,\nPOIS TE ESQUECERÁS \nDOS TEUS SOFRIMENTOS,\nDELES TE LEMBRARÁS\nCOMO ÁGUAS QUE PASSARAM.\n\nOLHARÁS AO REDOR E DORMIRÁS TRANQUILO,\nDEITAR-TE-ÁS E NINGUÉM TE ESPANTARÁ,\nMUITOS PROCURARÃO OBTER O TEU FAVOR.\n\n<coro>\nENTÃO LEVANTARÁS \nO TEU ROSTO SEM MÁCULA,\nESTARÁS SEGURO E NÃO TEMERÁS,\nPOIS TE ESQUECERÁS \nDOS TEUS SOFRIMENTOS,\nDELES TE LEMBRARÁS\nCOMO ÁGUAS QUE PASSARAM.\nSE DISPUSERES O TEU CORAÇÃO. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (253, 'SE DISPUSERES O TEU CORAÇÃO', 'SE DISPUSERES O TEU CORAÇÃO', 'SE DISPUSERES O TEU CORAÇÃO\nE ESTENDERES TUA MÃO PRA DEUS,\nSE LANÇARES PARA LONGE\nA INIQUIDADE DE TUA MÃO,\nESTARÁS SEGURO E NÃO TEMERÁS.\n\nSE TU NÃO PERMITIRES QUE A INJUSTIÇA,\nEM TUA TENDA FAÇA HABITAÇÃO,\nSE LANÇARES PARA LONGE\nA INIQUIDADE DE TUA MÃO,\nESTARÁS SEGURO E NÃO TEMERÁS.\n\nTUA VIDA ENTÃO SERÁ MAIS CLARA QUE A MANHÃ,\nOLHARÁS EM VOLTA E DORMIRÁS TRANQUILO,\nMAS OS OLHOS DOS PERVERSOS DESFALECERÃO,\nSEU REFÚGIO PERECERÁ.', 'SE DISPUSERES O TEU CORAÇÃO\nE ESTENDERES TUA MÃO PRA DEUS,\nSE LANÇARES PARA LONGE\nA INIQUIDADE DE TUA MÃO,\nESTARÁS SEGURO E NÃO TEMERÁS.\n\nSE TU NÃO PERMITIRES QUE A INJUSTIÇA,\nEM TUA TENDA FAÇA HABITAÇÃO,\nSE LANÇARES PARA LONGE\nA INIQUIDADE DE TUA MÃO,\nESTARÁS SEGURO E NÃO TEMERÁS.\n\nTUA VIDA ENTÃO SERÁ MAIS CLARA QUE A MANHÃ,\nOLHARÁS EM VOLTA E DORMIRÁS TRANQUILO,\nMAS OS OLHOS DOS PERVERSOS DESFALECERÃO,\nSEU REFÚGIO PERECERÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (254, 'OLHAI PARA O ALTO', 'OLHAI PARA O ALTO', 'CORO (2X)\nOLHAI PARA O ALTO\nDE ONDE VEM A SALVAÇÃO,\nSEGUI PARA O ALVO, À ETERNA VOCAÇÃO.\n\nTODO JUSTO PELA FÉ VIVERÁ,\nSEU OLHAR ESTÁ FIRME NO SENHOR,\nESPERANDO ENCONTRÁ-LO EM RESPLENDOR, \nPORQUE BREVE A TROMBETA SOARÁ. \nÓ OLHAI!\n\nCORO (2X)\nOLHAI PARA O ALTO\nDE ONDE VEM A SALVAÇÃO,\nSEGUI PARA O ALVO, À ETERNA VOCAÇÃO.\n\nESQUECENDO O QUE FICOU PARA TRÁS,\nSEGUE O JUSTO SEU CAMINHO COM JESUS,\nDIA A DIA CARREGANDO A SUA CRUZ,\nPORQUE BREVE JESUS CRISTO VOLTARÁ. \nÓ OLHAI!\n\nCORO (2X)\nOLHAI PARA O ALTO\nDE ONDE VEM A SALVAÇÃO,\nSEGUI PARA O ALVO, À ETERNA VOCAÇÃO.', '<coro tipo=''2X''>\nOLHAI PARA O ALTO\nDE ONDE VEM A SALVAÇÃO,\nSEGUI PARA O ALVO, À ETERNA VOCAÇÃO.\n\nTODO JUSTO PELA FÉ VIVERÁ,\nSEU OLHAR ESTÁ FIRME NO SENHOR,\nESPERANDO ENCONTRÁ-LO EM RESPLENDOR, \nPORQUE BREVE A TROMBETA SOARÁ. \nÓ OLHAI!\n\n<coro tipo=''2X''>\nOLHAI PARA O ALTO\nDE ONDE VEM A SALVAÇÃO,\nSEGUI PARA O ALVO, À ETERNA VOCAÇÃO.\n\nESQUECENDO O QUE FICOU PARA TRÁS,\nSEGUE O JUSTO SEU CAMINHO COM JESUS,\nDIA A DIA CARREGANDO A SUA CRUZ,\nPORQUE BREVE JESUS CRISTO VOLTARÁ. \nÓ OLHAI!\n\n<coro tipo=''2X''>\nOLHAI PARA O ALTO\nDE ONDE VEM A SALVAÇÃO,\nSEGUI PARA O ALVO, À ETERNA VOCAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (255, 'MEU CORAÇÃO ENGRANDECE (CÂNTICO DE VITÓRIA)', 'MEU CORAÇÃO ENGRANDECE (CÂNTICO DE VITÓRIA)', 'MEU CORAÇÃO ENGRANDECE AO SENHOR PORQUE ELE MUDOU \nTODO O MEU SER,\nFEZ-ME ANDAR EM VEREDAS\nQUE EU NÃO CONHECIA.\n\nILUMINOU OS MEUS PÉS\nPARA QUE EU NÃO TROPEÇASSE,\nMEU CORAÇÃO JUBILOU DE ALEGRIA\nQUANDO EM MIM VEIO MORAR,\nFEZ EM MIM HABITAÇÃO PRO SEU ESPÍRITO.\nCOLOCOU UM CÂNTICO NOVO EM MEUS LÁBIOS, \nAQUELE QUE EU NÃO CONHECIA,\nPELO SEU ESPÍRITO, ME FEZ CONHECER.\n\n''DESPERTA,\n(DESPERTA) SERVAS\nTU QUE DORMES, \n(TU QUE DORMES) SERVAS\nDEIXA O SOL \n(DEIXA O SOL) SERVAS\nRESPLANDECER SOBRE TUA VIDA.''\nINSTRUMENTOS\n\n''O SOL DESPONTA SOBRE A CIDADE\nQUANDO OS CONVOCO A ME ADORAR;\nJERUSALÉM, MORADA DO DEUS VIVO,\nCRIADOR DO UNIVERSO.\nMINHA MÃO ESTÁ SOBRE O MEU POVO,\nPOIS EU O TENHO ESCOLHIDO,\nCOM MINHAS MÃOS PODEROSAS\nFAÇO MORADA EM SEUS CORAÇÕES.''\n\n''REJUBILA, POVO MEU! \n(REJUBILA) SERVAS\nPORQUE EM BREVE VIRÁ \nMINHA GLÓRIA E VÓS \nPODEREIS LEVANTAR UM ESTANDARTE \nENTRE AS NAÇÕES \nE PROCLAMAR QUE SOU REI.''', 'MEU CORAÇÃO ENGRANDECE AO SENHOR PORQUE ELE MUDOU \nTODO O MEU SER,\nFEZ-ME ANDAR EM VEREDAS\nQUE EU NÃO CONHECIA.\n\nILUMINOU OS MEUS PÉS\nPARA QUE EU NÃO TROPEÇASSE,\nMEU CORAÇÃO JUBILOU DE ALEGRIA\nQUANDO EM MIM VEIO MORAR,\nFEZ EM MIM HABITAÇÃO PRO SEU ESPÍRITO.\nCOLOCOU UM CÂNTICO NOVO EM MEUS LÁBIOS, \nAQUELE QUE EU NÃO CONHECIA,\nPELO SEU ESPÍRITO, ME FEZ CONHECER.\n\n''DESPERTA,\n(DESPERTA) <m>\nTU QUE DORMES, \n(TU QUE DORMES) <m>\nDEIXA O SOL \n(DEIXA O SOL) <m>\nRESPLANDECER SOBRE TUA VIDA.''\n<instrumentos>\n\n\n''O SOL DESPONTA SOBRE A CIDADE\nQUANDO OS CONVOCO A ME ADORAR;\nJERUSALÉM, MORADA DO DEUS VIVO,\nCRIADOR DO UNIVERSO.\nMINHA MÃO ESTÁ SOBRE O MEU POVO,\nPOIS EU O TENHO ESCOLHIDO,\nCOM MINHAS MÃOS PODEROSAS\nFAÇO MORADA EM SEUS CORAÇÕES.''\n\n''REJUBILA, POVO MEU! <bis>\n(REJUBILA) <m><bis>\nPORQUE EM BREVE VIRÁ <bis>\nMINHA GLÓRIA E VÓS <bis>\nPODEREIS LEVANTAR UM ESTANDARTE <bis>\nENTRE AS NAÇÕES <bis>\nE PROCLAMAR QUE SOU REI.'' <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (256, 'NÃO MAIS VIVO EU MAS CRISTO VIVE EM MIM', 'NÃO MAIS VIVO EU MAS CRISTO VIVE EM MIM', 'NÃO MAIS VIVO EU,\nMAS CRISTO VIVE EM MIM\nDESDE O DIA EM QUE ACEITEI\nA JESUS, O SALVADOR;\nA MINHA VIDA SE TRANSFORMOU\nE O SEU AMOR A MIM SE REVELOU;\n\nBUSCAI A DEUS ENQUANTO SE PODE ACHAR\nE INVOCAI SEU NOME POIS ELE ESTÁ PERTO;\nJESUS VIVE EM MIM E QUER VIVER EM TI\nE REVELAR AS MARAVILHAS DO SEU ESPÍRITO.\n\nCORO\nSÃO TANTAS BÊNÇÃOS, SENHOR!\nSÃO TANTAS BÊNÇÃOS, SENHOR! \n(SÃO TANTAS BÊNÇÃOS) VARÕES\nBÊNÇÃOS QUE NÃO SE PODEM CONTAR;\n(NÃO SE PODEM CONTAR) VARÕES\nCANTEMOS GLÓRIA AO SENHOR,\nHONRA E PODER AO REI DOS REIS POIS \nELE VOLTARÁ PRA NOS LEVAR E REINARÁ.\n\nDEUS QUER TE DAR PAZ,\nBÊNÇÃOS E O GOZO CELESTIAL,\nSE ASSIM QUISERES, ELE O FARÁ.\n\nCORO\nSÃO TANTAS BÊNÇÃOS, SENHOR!\nSÃO TANTAS BÊNÇÃOS, SENHOR! \n(SÃO TANTAS BÊNÇÃOS) VARÕES\nBÊNÇÃOS QUE NÃO SE PODEM CONTAR;\n(NÃO SE PODEM CONTAR) VARÕES\nCANTEMOS GLÓRIA AO SENHOR,\nHONRA E PODER AO REI DOS REIS POIS \nELE VOLTARÁ PRA NOS LEVAR E REINARÁ.', 'NÃO MAIS VIVO EU,\nMAS CRISTO VIVE EM MIM\nDESDE O DIA EM QUE ACEITEI\nA JESUS, O SALVADOR;\nA MINHA VIDA SE TRANSFORMOU\nE O SEU AMOR A MIM SE REVELOU;\n\nBUSCAI A DEUS ENQUANTO SE PODE ACHAR\nE INVOCAI SEU NOME POIS ELE ESTÁ PERTO;\nJESUS VIVE EM MIM E QUER VIVER EM TI\nE REVELAR AS MARAVILHAS DO SEU ESPÍRITO.\n\n<coro>\nSÃO TANTAS BÊNÇÃOS, SENHOR!\nSÃO TANTAS BÊNÇÃOS, SENHOR! \n(SÃO TANTAS BÊNÇÃOS) <h>\nBÊNÇÃOS QUE NÃO SE PODEM CONTAR;\n(NÃO SE PODEM CONTAR) <h>\nCANTEMOS GLÓRIA AO SENHOR,\nHONRA E PODER AO REI DOS REIS POIS \nELE VOLTARÁ PRA NOS LEVAR E REINARÁ.\n\nDEUS QUER TE DAR PAZ,\nBÊNÇÃOS E O GOZO CELESTIAL,\nSE ASSIM QUISERES, ELE O FARÁ.\n\n<coro>\nSÃO TANTAS BÊNÇÃOS, SENHOR!\nSÃO TANTAS BÊNÇÃOS, SENHOR! \n(SÃO TANTAS BÊNÇÃOS) <h>\nBÊNÇÃOS QUE NÃO SE PODEM CONTAR;\n(NÃO SE PODEM CONTAR) <h>\nCANTEMOS GLÓRIA AO SENHOR,\nHONRA E PODER AO REI DOS REIS POIS \nELE VOLTARÁ PRA NOS LEVAR E REINARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (257, 'TUDO SE FEZ NOVO', 'TUDO SE FEZ NOVO', 'TUDO SE FEZ NOVO\nE AS COISAS VELHAS JÁ SE PASSARAM\nPOIS O SENHOR FARÁ CONTIGO\nUMA ALIANÇA ETERNA QUE JAMAIS SE ACABARÁ.\n\nDOS TEUS PECADOS DEUS\nNÃO MAIS SE LEMBRARÁ,\nTUA VIDA ELE VAI TRANSFORMAR,\nO TEU FARDO SOBRE SI ELE VAI LEVAR\nE AS TUAS LÁGRIMAS ELE VAI ENXUGAR.\n\nCORO (2X)\nNÃO SOU EU MAIS QUEM VIVE\nMAS CRISTO VIVE EM MIM,\nE A VIDA QUE AGORA VIVO\nEU A VIVO PELA FÉ. \n\nESTE CHAMADO VEM DE DEUS,\nNÃO VEM DO HOMEM MAS VEM DO SENHOR; \nNÃO TEMAS POIS FOI DEUS QUEM TE ESCOLHEU, \nNÃO TEMAS POIS É ELE QUEM DÁ FORÇAS PRA VENCER; NÃO TEMAS PORQUE ELE NÃO TE DEIXARÁ, \nNÃO TEMAS POIS O SEU AMOR É GRANDE.\n\nCORO (2X)\nNÃO SOU EU MAIS QUEM VIVE\nMAS CRISTO VIVE EM MIM,\nE A VIDA QUE AGORA VIVO\nEU A VIVO PELA FÉ. (2X)', 'TUDO SE FEZ NOVO\nE AS COISAS VELHAS JÁ SE PASSARAM\nPOIS O SENHOR FARÁ CONTIGO\nUMA ALIANÇA ETERNA QUE JAMAIS SE ACABARÁ.\n\nDOS TEUS PECADOS DEUS\nNÃO MAIS SE LEMBRARÁ,\nTUA VIDA ELE VAI TRANSFORMAR,\nO TEU FARDO SOBRE SI ELE VAI LEVAR\nE AS TUAS LÁGRIMAS ELE VAI ENXUGAR.\n\n<coro tipo=''2X''>\nNÃO SOU EU MAIS QUEM VIVE\nMAS CRISTO VIVE EM MIM,\nE A VIDA QUE AGORA VIVO\nEU A VIVO PELA FÉ. \n\nESTE CHAMADO VEM DE DEUS,\nNÃO VEM DO HOMEM MAS VEM DO SENHOR; \nNÃO TEMAS POIS FOI DEUS QUEM TE ESCOLHEU, \nNÃO TEMAS POIS É ELE QUEM DÁ FORÇAS PRA VENCER; NÃO TEMAS PORQUE ELE NÃO TE DEIXARÁ, \nNÃO TEMAS POIS O SEU AMOR É GRANDE.\n\n<coro tipo=''2X''>\nNÃO SOU EU MAIS QUEM VIVE\nMAS CRISTO VIVE EM MIM,\nE A VIDA QUE AGORA VIVO\nEU A VIVO PELA FÉ. <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (258, 'SE TU ESTÁS TÃO LONGE DO SENHOR', 'SE TU ESTÁS TÃO LONGE DO SENHOR', 'SE TU ESTÁS TÃO LONGE DO SENHOR,\nSE ESQUECESTE DE TUDO O QUE ELE FEZ POR TI,\nAINDA HÁ TEMPO PARA VOLTARES\nAOS BRAÇOS DAQUELE QUE TE AMA.\n\nCORO\n''VOLTA, FILHO MEU, \nPARA OS BRAÇOS MEUS \nPORQUE JAMAIS ME ESQUECI DE TI, \nO TEU NOME TENHO GRAVADO \nEM MINHAS MÃOS.''\n\n''EU SOU JESUS QUEM FALA CONTIGO,\nO TEU CONSOLO QUANDO ESTÁS ABATIDO,\nO REFÚGIO EM MOMENTOS DIFÍCEIS,\nEU TE LEVANTO QUANDO ESTÁS CAÍDO.''\n\nCORO (2X)\n''VOLTA, FILHO MEU, \nPARA OS BRAÇOS MEUS \nPORQUE JAMAIS ME ESQUECI DE TI, \nO TEU NOME TENHO GRAVADO \nEM MINHAS MÃOS.''\n\nFINAL: ''EM MINHAS MÃOS.''', 'SE TU ESTÁS TÃO LONGE DO SENHOR,\nSE ESQUECESTE DE TUDO O QUE ELE FEZ POR TI,\nAINDA HÁ TEMPO PARA VOLTARES\nAOS BRAÇOS DAQUELE QUE TE AMA.\n\n<coro>\n''VOLTA, FILHO MEU, \nPARA OS BRAÇOS MEUS \nPORQUE JAMAIS ME ESQUECI DE TI, \nO TEU NOME TENHO GRAVADO \nEM MINHAS MÃOS.''\n\n''EU SOU JESUS QUEM FALA CONTIGO,\nO TEU CONSOLO QUANDO ESTÁS ABATIDO,\nO REFÚGIO EM MOMENTOS DIFÍCEIS,\nEU TE LEVANTO QUANDO ESTÁS CAÍDO.''\n\n<coro tipo=''2X''>\n''VOLTA, FILHO MEU, \nPARA OS BRAÇOS MEUS \nPORQUE JAMAIS ME ESQUECI DE TI, \nO TEU NOME TENHO GRAVADO \nEM MINHAS MÃOS.''\n<final>''EM MINHAS MÃOS.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (259, 'COMO UM BOM PASTOR', 'COMO UM BOM PASTOR', 'COMO UM BOM PASTOR \nPROCURA UMA OVELHA PERDIDA, \nJESUS ME BUSCOU E DEU LUZ À MINHA VIDA;\nCOM TANTO AMOR FALOU AO MEU CORAÇÃO,\nLIVROU-ME DO MAL, \nCUROU MINHAS CHAGAS,\nDEU-ME SALVAÇÃO!\n\nEM SEUS FORTES BRAÇOS \nDESCANSO E REFÚGIO ACHEI,\nELE É MEU PASTOR E CUIDA DE MIM, EU SEI!\nCOMO UMA OVELHA, NO PASTO SEU, CAMINHO;\nSEGUINDO A JESUS, \nOUVINDO SUA VOZ,\nSENTINDO SEU AMOR!\n\nAMIGO, POR QUE, SEM RUMO, VIVER NESTE MUNDO?\nPOR QUE TANTA DOR, SE EXISTE \nESSE AMOR PROFUNDO?\nÓ VEM A JESUS, TU ÉS UMA OVELHA PERDIDA;\nSÓ CRISTO TE PODE DAR SALVAÇÃO,\nENTREGA-LHE TUA VIDA!', 'COMO UM BOM PASTOR \nPROCURA UMA OVELHA PERDIDA, \nJESUS ME BUSCOU E DEU LUZ À MINHA VIDA;\nCOM TANTO AMOR FALOU AO MEU CORAÇÃO,\nLIVROU-ME DO MAL, <bis>\nCUROU MINHAS CHAGAS,<bis>\nDEU-ME SALVAÇÃO!<bis>\n\nEM SEUS FORTES BRAÇOS \nDESCANSO E REFÚGIO ACHEI,\nELE É MEU PASTOR E CUIDA DE MIM, EU SEI!\nCOMO UMA OVELHA, NO PASTO SEU, CAMINHO;\nSEGUINDO A JESUS, <bis>\nOUVINDO SUA VOZ,<bis>\nSENTINDO SEU AMOR!<bis>\n\nAMIGO, POR QUE, SEM RUMO, VIVER NESTE MUNDO?\nPOR QUE TANTA DOR, SE EXISTE \nESSE AMOR PROFUNDO?\nÓ VEM A JESUS, TU ÉS UMA OVELHA PERDIDA;\nSÓ CRISTO TE PODE DAR SALVAÇÃO,<bis>\nENTREGA-LHE TUA VIDA! <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (260, 'DEUS ESTÁ PRESENTE AQUI NESTE LUGAR', 'DEUS ESTÁ PRESENTE AQUI NESTE LUGAR', 'DEUS ESTÁ PRESENTE AQUI NESTE LUGAR,\nELE QUER O SEU AMOR NOS REVELAR,\nTUDO ELE CONHECE, TUDO ELE PODE,\nMESMO TRANSFORMAR A TREVA EM LUZ.\n\nABRE O TEU CORAÇÃO A JESUS,\nDEIXA SOBRE TI BRILHAR SUA LUZ,\nTUDO ELE CONHECE, TUDO ELE PODE,\nDEUS ESTÁ AQUI NESTE LUGAR.\n\nINSTRUMENTOS\n\nABRE O TEU CORAÇÃO A JESUS,\nDEIXA SOBRE TI BRILHAR SUA LUZ,\nTUDO ELE CONHECE, TUDO ELE PODE,\nDEUS ESTÁ AQUI NESTE LUGAR.\n\nFINAL: DEUS ESTÁ AQUI NESTE LUGAR.', 'DEUS ESTÁ PRESENTE AQUI NESTE LUGAR,\nELE QUER O SEU AMOR NOS REVELAR,\nTUDO ELE CONHECE, TUDO ELE PODE,\nMESMO TRANSFORMAR A TREVA EM LUZ.\n\nABRE O TEU CORAÇÃO A JESUS,\nDEIXA SOBRE TI BRILHAR SUA LUZ,\nTUDO ELE CONHECE, TUDO ELE PODE,\nDEUS ESTÁ AQUI NESTE LUGAR.\n<instrumentos>\n\n\nABRE O TEU CORAÇÃO A JESUS,\nDEIXA SOBRE TI BRILHAR SUA LUZ,\nTUDO ELE CONHECE, TUDO ELE PODE,\nDEUS ESTÁ AQUI NESTE LUGAR.\n<final>DEUS ESTÁ AQUI NESTE LUGAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (261, 'CRISTO CAMINHAVA LENTAMENTE', 'CRISTO CAMINHAVA LENTAMENTE', 'CRISTO CAMINHAVA LENTAMENTE,\nPASSO A PASSO COM DECISÃO;\nDE REPENTE ELE FALOU: ''ALGUÉM TOCOU-ME, \nALGUÉM NO MEIO DA MULTIDÃO''.\n''MESTRE, A MULTIDÃO TE OPRIME\nDE TODOS OS LADOS, ASSIM'';\nCRISTO DISSE: ''ALGUÉM TOCOU-ME DIFERENTE, \nPOIS EU SENTI SAIR VIRTUDE DE MIM''.\n\nCORO\nTOCA PELA FÉ AGORA EM JESUS\nPOIS ELE VAI TE CONCEDER A LUZ,\nESTENDE A MÃO, JESUS VAI TE TOCAR;\nTOCA PELA FÉ AGORA, É SÓ PEDIR,\nQUE DE JESUS VIRTUDE VAI SAIR, \nESTENDE A MÃO, JESUS VAI TE TOCAR. \nINSTRUMENTOS\n\nENTÃO UMA MULHER APROXIMOU-SE\nE DISSE: ''FUI EU, SENHOR, QUEM TE TOCOU'';\nCRISTO ALI FALOU-LHE MUI SUAVEMENTE:\n''VAI EM PAZ, A TUA FÉ TE SALVOU.''\nSE QUERES A ALEGRIA EM TUA VIDA,\nSE QUERES A VITÓRIA EM TEU LAR,\nSENTE AGORA A MORTE TRANSFORMAR-SE \nEM VIDA QUANDO A MÃO \nDE DEUS TE TOCAR.\n\nCORO\nTOCA PELA FÉ AGORA EM JESUS\nPOIS ELE VAI TE CONCEDER A LUZ,\nESTENDE A MÃO, JESUS VAI TE TOCAR;\nTOCA PELA FÉ AGORA, É SÓ PEDIR,\nQUE DE JESUS VIRTUDE VAI SAIR, \nESTENDE A MÃO, JESUS VAI TE TOCAR.', 'CRISTO CAMINHAVA LENTAMENTE,\nPASSO A PASSO COM DECISÃO;\nDE REPENTE ELE FALOU: ''ALGUÉM TOCOU-ME, \nALGUÉM NO MEIO DA MULTIDÃO''.\n''MESTRE, A MULTIDÃO TE OPRIME\nDE TODOS OS LADOS, ASSIM'';\nCRISTO DISSE: ''ALGUÉM TOCOU-ME DIFERENTE, \nPOIS EU SENTI SAIR VIRTUDE DE MIM''.\n\n<coro>\nTOCA PELA FÉ AGORA EM JESUS\nPOIS ELE VAI TE CONCEDER A LUZ,\nESTENDE A MÃO, JESUS VAI TE TOCAR;\nTOCA PELA FÉ AGORA, É SÓ PEDIR,\nQUE DE JESUS VIRTUDE VAI SAIR, \nESTENDE A MÃO, JESUS VAI TE TOCAR. \n<instrumentos>\n\n\nENTÃO UMA MULHER APROXIMOU-SE\nE DISSE: ''FUI EU, SENHOR, QUEM TE TOCOU'';\nCRISTO ALI FALOU-LHE MUI SUAVEMENTE:\n''VAI EM PAZ, A TUA FÉ TE SALVOU.''\nSE QUERES A ALEGRIA EM TUA VIDA,\nSE QUERES A VITÓRIA EM TEU LAR,\nSENTE AGORA A MORTE TRANSFORMAR-SE \nEM VIDA QUANDO A MÃO \nDE DEUS TE TOCAR.\n\n<coro>\nTOCA PELA FÉ AGORA EM JESUS\nPOIS ELE VAI TE CONCEDER A LUZ,\nESTENDE A MÃO, JESUS VAI TE TOCAR;\nTOCA PELA FÉ AGORA, É SÓ PEDIR,<bis>\nQUE DE JESUS VIRTUDE VAI SAIR, <bis>\nESTENDE A MÃO, JESUS VAI TE TOCAR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (262, 'QUERO QUE VOCÊ CONHEÇA', 'QUERO QUE VOCÊ CONHEÇA', 'QUERO QUE VOCÊ CONHEÇA\n(QUERO QUE VOCÊ CONHEÇA) VARÕES\nJESUS, O AUTOR DA NOSSA FÉ;\nQUERO QUE VOCÊ CONHEÇA\n(QUERO QUE VOCÊ CONHEÇA) VARÕES\nTODO O SEU AMOR QUE TEM.\n\nCORO\nELE SALVA, ELE CURA, \nELE DÁ VIDA ETERNA,\nE TUDO O QUE ELE FAZ É POR AMOR.\nABRE A BOCA DO MUDO, \n(DÁ VISTA AO CEGO) VARÕES\nDÁ PALAVRA AO UNGIDO.\n\nOH! JESUS MARAVILHOSO,\n(OH! JESUS MARAVILHOSO) VARÕES\nJESUS, O AUTOR DA NOSSA FÉ\nE TUDO QUE ELE FAZ É POR AMOR.\n\nCORO\nELE SALVA, ELE CURA, \nELE DÁ VIDA ETERNA,\nE TUDO O QUE ELE FAZ É POR AMOR.\nABRE A BOCA DO MUDO, \n(DÁ VISTA AO CEGO) VARÕES\nDÁ PALAVRA AO UNGIDO.\n\nFINAL: (3X)\nOH! JESUS MARAVILHOSO, \n(OH! JESUS MARAVILHOSO) VARÕES\nJESUS, O AUTOR DA NOSSA FÉ.', 'QUERO QUE VOCÊ CONHEÇA\n(QUERO QUE VOCÊ CONHEÇA) <h>\nJESUS, O AUTOR DA NOSSA FÉ;\nQUERO QUE VOCÊ CONHEÇA\n(QUERO QUE VOCÊ CONHEÇA) <h>\nTODO O SEU AMOR QUE TEM.\n\n<coro>\nELE SALVA, ELE CURA, \nELE DÁ VIDA ETERNA,\nE TUDO O QUE ELE FAZ É POR AMOR.\nABRE A BOCA DO MUDO, <bis>\n(DÁ VISTA AO CEGO) <h><bis>\nDÁ PALAVRA AO UNGIDO.<bis>\n\nOH! JESUS MARAVILHOSO,\n(OH! JESUS MARAVILHOSO) <h>\nJESUS, O AUTOR DA NOSSA FÉ\nE TUDO QUE ELE FAZ É POR AMOR.\n\n<coro>\nELE SALVA, ELE CURA, \nELE DÁ VIDA ETERNA,\nE TUDO O QUE ELE FAZ É POR AMOR.\nABRE A BOCA DO MUDO, <bis>\n(DÁ VISTA AO CEGO) <h><bis>\nDÁ PALAVRA AO UNGIDO.<bis>\n\n\n<final>(<bis tipo=''3''>\nOH! JESUS MARAVILHOSO, \n(OH! JESUS MARAVILHOSO) <h>\nJESUS, O AUTOR DA NOSSA FÉ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (263, 'QUERES IR PARA GLÓRIA?', 'QUERES IR PARA GLÓRIA?', 'QUERES IR PRA GLÓRIA? PÁRA UM MOMENTO,\nESCUTA ESTA HISTÓRIA, VEM HOJE MESMO,\nQUE, DO NAZARENO, FAÇO A DESCRIÇÃO;\nCRISTO SEM PECADO, \nFOI TRASPASSADO PRA TE DAR PERDÃO, \nVEM A CRISTO AGORA, NESTA MESMA HORA, \nTEM A SALVAÇÃO. \n\nCORO\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO,\nCRÊ EM CRISTO, AGORA, ELE É A SALVAÇÃO!\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO, \nCRÊ EM CRISTO, AGORA,\nELE É A CONDUÇÃO!\nINSTRUMENTOS\n\nMEU DISTINTO AMIGO,HÁ UM GRANDE PERIGO,\nQUEM NÃO ESTÁ NA LUZ, PARA UM POUQUINHO,\nENTRA NO CAMINHO, ENTREGA-TE A JESUS;\nSE ESTÁS CANSADO, CRISTO JÁ SOFREU \nPOR TI NA CRUZ, VEM A CRISTO AGORA \nE TERÁS VITÓRIA \n\nCORO\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO,\nCRÊ EM CRISTO, AGORA, ELE É A SALVAÇÃO!\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO, \nCRÊ EM CRISTO, AGORA,\nELE É A CONDUÇÃO!', 'QUERES IR PRA GLÓRIA? PÁRA UM MOMENTO,\nESCUTA ESTA HISTÓRIA, VEM HOJE MESMO,\nQUE, DO NAZARENO, FAÇO A DESCRIÇÃO;\nCRISTO SEM PECADO, \nFOI TRASPASSADO PRA TE DAR PERDÃO, <bis>\nVEM A CRISTO AGORA, NESTA MESMA HORA, <bis>\nTEM A SALVAÇÃO. <bis>\n\n<coro>\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO,\nCRÊ EM CRISTO, AGORA, ELE É A SALVAÇÃO!\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO, \nCRÊ EM CRISTO, AGORA,\nELE É A CONDUÇÃO!\n<instrumentos>\n\n\nMEU DISTINTO AMIGO,HÁ UM GRANDE PERIGO,\nQUEM NÃO ESTÁ NA LUZ, PARA UM POUQUINHO,\nENTRA NO CAMINHO, ENTREGA-TE A JESUS;\nSE ESTÁS CANSADO, CRISTO JÁ SOFREU <bis>\nPOR TI NA CRUZ, VEM A CRISTO AGORA <bis>\nE TERÁS VITÓRIA <bis>\n\n<coro>\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO,\nCRÊ EM CRISTO, AGORA, ELE É A SALVAÇÃO!\nQUERES IR PRA GLÓRIA? DÁ TEU CORAÇÃO, <bis>\nCRÊ EM CRISTO, AGORA,<bis>\nELE É A CONDUÇÃO!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (264, 'OH! QUE BELOS HINOS HOJE LÁ NO CÉU', 'OH! QUE BELOS HINOS HOJE LÁ NO CÉU', 'OH! QUE BELOS HINOS HOJE LÁ NO CÉU,\nJÁ DO MUNDO O PECADOR VOLTOU;\nVEDE NO CAMINHO O PAI ABRAÇAR\nESSE FILHO QUE ELE TANTO AMOU.\n\nCORO\nGLÓRIA, GLÓRIA, OS ANJOS CANTAM LÁ!\nGLORIA, GLÓRIA, AS HARPAS TOCAM JÁ!\nÉ O SANTO CORO DANDO GLÓRIA A DEUS\nPOR MAIS UM REMIDO ENTRAR NOS CÉUS.\n\nOH! QUE BELOS HINOS HOJE LÁ NO CÉU,\nÉ QUE JÁ SE RECONCILIOU \nA ALMA ARREPENDIDA QUE, \nRENDIDA A DEUS,\nRENASCIDA PARA O LAR VOLTOU.\n\nCORO\nGLÓRIA, GLÓRIA, OS ANJOS CANTAM LÁ!\nGLORIA, GLÓRIA, AS HARPAS TOCAM JÁ!\nÉ O SANTO CORO DANDO GLÓRIA A DEUS\nPOR MAIS UM REMIDO ENTRAR NOS CÉUS.\n\nESSE ARREPENDIDO, VINDE, FESTEJAR\nCOMO OS ANJOS FAZEM COM FERVOR;\nIDE, POIS, ALEGRES, IDE, ANUNCIAI,\nQUE SE RESGATOU UM PECADOR.', 'OH! QUE BELOS HINOS HOJE LÁ NO CÉU,\nJÁ DO MUNDO O PECADOR VOLTOU;\nVEDE NO CAMINHO O PAI ABRAÇAR\nESSE FILHO QUE ELE TANTO AMOU.\n\n<coro>\nGLÓRIA, GLÓRIA, OS ANJOS CANTAM LÁ!\nGLORIA, GLÓRIA, AS HARPAS TOCAM JÁ!\nÉ O SANTO CORO DANDO GLÓRIA A DEUS\nPOR MAIS UM REMIDO ENTRAR NOS CÉUS.\n\nOH! QUE BELOS HINOS HOJE LÁ NO CÉU,\nÉ QUE JÁ SE RECONCILIOU \nA ALMA ARREPENDIDA QUE, \nRENDIDA A DEUS,\nRENASCIDA PARA O LAR VOLTOU.\n\n<coro>\nGLÓRIA, GLÓRIA, OS ANJOS CANTAM LÁ!\nGLORIA, GLÓRIA, AS HARPAS TOCAM JÁ!\nÉ O SANTO CORO DANDO GLÓRIA A DEUS\nPOR MAIS UM REMIDO ENTRAR NOS CÉUS.\n\nESSE ARREPENDIDO, VINDE, FESTEJAR\nCOMO OS ANJOS FAZEM COM FERVOR;\nIDE, POIS, ALEGRES, IDE, ANUNCIAI,\nQUE SE RESGATOU UM PECADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (265, 'LEVA TU CONTIGO O NOME', 'LEVA TU CONTIGO O NOME', 'LEVA TU CONTIGO O NOME\nDE JESUS, O SALVADOR;\nESTE NOME DÁ CONFORTO\nSEMPRE, SEJA ONDE FOR.\n\nCORO (2X)\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.\n\nESSE NOME LEVA SEMPRE\nPARA BEM TE DEFENDER,\nELE É A ARMA AO TEU ALCANCE\nQUANDO O MAL TE APARECER.\n\nCORO (2X)\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.\n\nOH! QUE NOME PRECIOSO!\nGOZO TRAZ AO CORAÇÃO;\nSENDO POR JESUS ACEITO,\nTU TERÁS O SEU PERDÃO.\n\nCORO (2X)\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.\n\nSANTO NOME, ADORÁVEL,\nTEM JESUS, O AMADO TEU;\n''REI DOS REIS, SENHOR ETERNO'',\nTU O ACLAMARÁS NO CÉU.\n\nCORO (2X)\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.', 'LEVA TU CONTIGO O NOME\nDE JESUS, O SALVADOR;\nESTE NOME DÁ CONFORTO\nSEMPRE, SEJA ONDE FOR.<coro tipo=''2X''>\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.\n\nESSE NOME LEVA SEMPRE\nPARA BEM TE DEFENDER,\nELE É A ARMA AO TEU ALCANCE\nQUANDO O MAL TE APARECER.<coro tipo=''2X''>\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.\n\nOH! QUE NOME PRECIOSO!\nGOZO TRAZ AO CORAÇÃO;\nSENDO POR JESUS ACEITO,\nTU TERÁS O SEU PERDÃO.<coro tipo=''2X''>\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.\n\nSANTO NOME, ADORÁVEL,\nTEM JESUS, O AMADO TEU;\n''REI DOS REIS, SENHOR ETERNO'',\nTU O ACLAMARÁS NO CÉU.<coro tipo=''2X''>\nNOME BOM, DOCE À FÉ,\nA ESPERANÇA DO PORVIR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (266, 'TODOS OS POVOS', 'TODOS OS POVOS', 'TODOS OS POVOS SABERÃO \nQUE O SENHOR JESUS É O ÚNICO SALVADOR,\nTODAS AS NAÇÕES SE PROSTRARÃO DIANTE DELE \nE CONFESSARÃO QUE JESUS CRISTO É O SENHOR.\n\nCORO\nJESUS É O CORDEIRO DE DEUS\nQUE TIRA O PECADO DO MUNDO,\nELE TE TROUXE AQUI PRA TE REVELAR\nA VIDA ETERNA QUE NELE HÁ.\nINSTRUMENTOS\n\nTU QUE PROCURAS ENCONTRAR A DOCE PAZ,\nSABE QUE JESUS É O PRÍNCIPE DA PAZ;\nTU QUE ESTÁS SEM ALEGRIA NO VIVER,\nEM CRISTO ENCONTRARÁS\nTUDO O QUE PRECISAS EM TEU SER.\n\nCORO (2X)\nJESUS É O CORDEIRO DE DEUS\nQUE TIRA O PECADO DO MUNDO,\nELE TE TROUXE AQUI PRA TE REVELAR\nA VIDA ETERNA QUE NELE HÁ.\n\nFINAL: A VIDA ETERNA QUE NELE HÁ.', 'TODOS OS POVOS SABERÃO \nQUE O SENHOR JESUS É O ÚNICO SALVADOR,\nTODAS AS NAÇÕES SE PROSTRARÃO DIANTE DELE \nE CONFESSARÃO QUE JESUS CRISTO É O SENHOR.\n\n<coro>\nJESUS É O CORDEIRO DE DEUS\nQUE TIRA O PECADO DO MUNDO,\nELE TE TROUXE AQUI PRA TE REVELAR\nA VIDA ETERNA QUE NELE HÁ.\n<instrumentos>\n\n\nTU QUE PROCURAS ENCONTRAR A DOCE PAZ,\nSABE QUE JESUS É O PRÍNCIPE DA PAZ;\nTU QUE ESTÁS SEM ALEGRIA NO VIVER,\nEM CRISTO ENCONTRARÁS\nTUDO O QUE PRECISAS EM TEU SER.\n\n<coro tipo=''2X''>\nJESUS É O CORDEIRO DE DEUS\nQUE TIRA O PECADO DO MUNDO,\nELE TE TROUXE AQUI PRA TE REVELAR\nA VIDA ETERNA QUE NELE HÁ.\n<final>A VIDA ETERNA QUE NELE HÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (267, 'QUANDO JESUS SEU SANGUE VERTEU', 'QUANDO JESUS SEU SANGUE VERTEU', 'QUANDO JESUS SEU SANGUE VERTEU,\nTUDO SE FEZ NOVO,\nO VÉU SE RASGOU, A TERRA TREMEU,\nMORREU NA CRUZ O FILHO DE DEUS.\n\nINSTRUMENTOS\n\nELE RESTAUROU O MEU CORAÇÃO,\nDEU-ME UMA NOVA VIDA;\nOH! QUANTO ME AMOU, \nMEU MESTRE E SENHOR,\nPERTENCE A ELE TODO MEU LOUVOR.\n\nINSTRUMENTOS\n\nFOI POR AMAR-ME QUE JESUS SOFREU,\nTUDO DEVO A CRISTO;\nO QUE DAREI AO MEU SALVADOR?\nLOUVÁ-LO-EI POR SEU INFINITO AMOR.', 'QUANDO JESUS SEU SANGUE VERTEU,\nTUDO SE FEZ NOVO,\nO VÉU SE RASGOU, A TERRA TREMEU,\nMORREU NA CRUZ O FILHO DE DEUS.\n<instrumentos>\n\n\nELE RESTAUROU O MEU CORAÇÃO,\nDEU-ME UMA NOVA VIDA;\nOH! QUANTO ME AMOU, \nMEU MESTRE E SENHOR,\nPERTENCE A ELE TODO MEU LOUVOR.\n<instrumentos>\n\n\nFOI POR AMAR-ME QUE JESUS SOFREU,\nTUDO DEVO A CRISTO;\nO QUE DAREI AO MEU SALVADOR?\nLOUVÁ-LO-EI POR SEU INFINITO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (268, 'JESUS É O CORDEIRO', 'JESUS É O CORDEIRO', 'JESUS É O CORDEIRO ETERNO E IMACULADO\nQUE FOI SACRIFICADO PARA NOS SALVAR,\nO SUMO SACERDOTE QUE DEUS CONSTITUIU,\nLEVOU A NOSSA CRUZ PROVANDO O SEU AMOR.\n\nCORO\nJESUS RESSUSCITOU TRAZENDO VIDA ETERNA,\nNÃO HÁ OUTRO ALÉM DELE QUE POSSA TE SALVAR,\nJESUS É O AMIGO FIEL, CONSOLADOR,\nENTREGA A TUA VIDA A QUEM TANTO TE AMA.\n\nO FARDO QUE CARREGAS TE TRAZ DESILUSÃO,\nO MUNDO QUE TU VIVES SÓ TEM DECEPÇÃO?\nA VIDA EM JESUS É LEVE E SUAVE,\nDESCANSO PARA ALMA NELE ENCONTRARÁS.\n\nCORO\nJESUS RESSUSCITOU TRAZENDO VIDA ETERNA,\nNÃO HÁ OUTRO ALÉM DELE QUE POSSA TE SALVAR,\nJESUS É O AMIGO FIEL, CONSOLADOR,\nENTREGA A TUA VIDA A QUEM TANTO TE AMA.\n\nSEU NOME É CONSELHEIRO, \nPAI DA ETERNIDADE,\nMARAVILHOSO, \nELE É DEUS FORTE.\n\nCORO\nJESUS RESSUSCITOU TRAZENDO VIDA ETERNA,\nNÃO HÁ OUTRO ALÉM DELE QUE POSSA TE SALVAR,\nJESUS É O AMIGO FIEL, CONSOLADOR,\nENTREGA A TUA VIDA A QUEM TANTO TE AMA.\n\nFINAL: JESUS TE AMA.', 'JESUS É O CORDEIRO ETERNO E IMACULADO\nQUE FOI SACRIFICADO PARA NOS SALVAR,\nO SUMO SACERDOTE QUE DEUS CONSTITUIU,\nLEVOU A NOSSA CRUZ PROVANDO O SEU AMOR.\n\n<coro>\nJESUS RESSUSCITOU TRAZENDO VIDA ETERNA,\nNÃO HÁ OUTRO ALÉM DELE QUE POSSA TE SALVAR,\nJESUS É O AMIGO FIEL, CONSOLADOR,\nENTREGA A TUA VIDA A QUEM TANTO TE AMA.\n\nO FARDO QUE CARREGAS TE TRAZ DESILUSÃO,\nO MUNDO QUE TU VIVES SÓ TEM DECEPÇÃO?\nA VIDA EM JESUS É LEVE E SUAVE,\nDESCANSO PARA ALMA NELE ENCONTRARÁS.\n\n<coro>\nJESUS RESSUSCITOU TRAZENDO VIDA ETERNA,\nNÃO HÁ OUTRO ALÉM DELE QUE POSSA TE SALVAR,\nJESUS É O AMIGO FIEL, CONSOLADOR,\nENTREGA A TUA VIDA A QUEM TANTO TE AMA.\n\nSEU NOME É CONSELHEIRO, \nPAI DA ETERNIDADE,\nMARAVILHOSO, \nELE É DEUS FORTE.\n\n<coro>\nJESUS RESSUSCITOU TRAZENDO VIDA ETERNA,\nNÃO HÁ OUTRO ALÉM DELE QUE POSSA TE SALVAR,\nJESUS É O AMIGO FIEL, CONSOLADOR,\nENTREGA A TUA VIDA A QUEM TANTO TE AMA.\n<final>JESUS TE AMA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (269, 'NÃO SEI SE OUVISTE FALAR', 'NÃO SEI SE OUVISTE FALAR', 'NÃO SEI SE OUVISTE FALAR DE UM REI\nQUE MORREU PRA TE SALVAR;\nO SEU SANGUE PURO DERRAMOU,\nCOMO HOLOCAUSTO FOI ENTREGUE POR AMOR.\n\nCORO\nELE VIVE E QUER TE SALVAR,\nENTREGA A TUA VIDA E ELA IRÁ MUDAR;\nELE É JESUS, NOSSO ETERNO REDENTOR,\nELE É O REI DA GLÓRIA, \nELE É O MEU SENHOR.\n\nSE PROCURAS A ALEGRIA \nE NÃO CONSEGUES ENCONTRAR, \nSÓ JESUS PODE DAR A ALEGRIA \nQUE NUNCA CESSARÁ;\nSE SERVIRES A JESUS \nUM NOVO DIA IRÁ SURGIR,\nELE TE CONDUZIRÁ AO SANTO \nE ETERNO LAR.\n\nCORO\nELE VIVE E QUER TE SALVAR,\nENTREGA A TUA VIDA E ELA IRÁ MUDAR;\nELE É JESUS, NOSSO ETERNO REDENTOR,\nELE É O REI DA GLÓRIA, \nELE É O MEU SENHOR.\n\nINSTRUMENTOS\n\nCORO\nELE VIVE E QUER TE SALVAR,\nENTREGA A TUA VIDA E ELA IRÁ MUDAR;\nELE É JESUS, NOSSO ETERNO REDENTOR,\nELE É O REI DA GLÓRIA, \nELE É O MEU SENHOR.', 'NÃO SEI SE OUVISTE FALAR DE UM REI\nQUE MORREU PRA TE SALVAR;\nO SEU SANGUE PURO DERRAMOU,\nCOMO HOLOCAUSTO FOI ENTREGUE POR AMOR.\n\n<coro>\nELE VIVE E QUER TE SALVAR,\nENTREGA A TUA VIDA E ELA IRÁ MUDAR;\nELE É JESUS, NOSSO ETERNO REDENTOR,\nELE É O REI DA GLÓRIA, \nELE É O MEU SENHOR.\n\nSE PROCURAS A ALEGRIA \nE NÃO CONSEGUES ENCONTRAR, \nSÓ JESUS PODE DAR A ALEGRIA \nQUE NUNCA CESSARÁ;\nSE SERVIRES A JESUS \nUM NOVO DIA IRÁ SURGIR,\nELE TE CONDUZIRÁ AO SANTO \nE ETERNO LAR.\n\n<coro>\nELE VIVE E QUER TE SALVAR,\nENTREGA A TUA VIDA E ELA IRÁ MUDAR;\nELE É JESUS, NOSSO ETERNO REDENTOR,\nELE É O REI DA GLÓRIA, \nELE É O MEU SENHOR.\n<instrumentos>\n\n\n<coro>\nELE VIVE E QUER TE SALVAR,\nENTREGA A TUA VIDA E ELA IRÁ MUDAR;\nELE É JESUS, NOSSO ETERNO REDENTOR,\nELE É O REI DA GLÓRIA, \nELE É O MEU SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (270, 'SE TU PEDISTE UM SINAL', 'SE TU PEDISTE UM SINAL', 'CORO\nSE TU PEDISTE UM SINAL, \nDEUS OUVIU TUA VOZ \nE TE TROUXE AQUI PARA ABENÇOAR.\nSE TUA VIDA É VAZIA, DEUS PODE MUDAR\nELE TE TROUXE AQUI PARA ABENÇOAR.\n\nENTREGA A TUA VIDA A JESUS\nE A SALVAÇÃO TERÁS;\nELE DIZ: ''EU SOU O SENHOR,\nO REI DOS REIS, O REI DAS NAÇÕES''.\n\nINSTRUMENTOS\n\nCORO\nSE TU PEDISTE UM SINAL, \nDEUS OUVIU TUA VOZ \nE TE TROUXE AQUI PARA ABENÇOAR.\nSE TUA VIDA É VAZIA, DEUS PODE MUDAR\nELE TE TROUXE AQUI PARA ABENÇOAR.\n\nFINAL:\nENTREGA A TUA VIDA A JESUS,\nELE VAI TE TRANSFORMAR.\nELE DIZ: ''EU SOU O SENHOR,\nO REI DOS REIS, O REI DAS NAÇÕES ''.', '<coro>\nSE TU PEDISTE UM SINAL, \nDEUS OUVIU TUA VOZ \nE TE TROUXE AQUI PARA ABENÇOAR.\nSE TUA VIDA É VAZIA, DEUS PODE MUDAR\nELE TE TROUXE AQUI PARA ABENÇOAR.\n\nENTREGA A TUA VIDA A JESUS\nE A SALVAÇÃO TERÁS;\nELE DIZ: ''EU SOU O SENHOR,\nO REI DOS REIS, O REI DAS NAÇÕES''.\n<instrumentos>\n\n\n<coro>\nSE TU PEDISTE UM SINAL, \nDEUS OUVIU TUA VOZ \nE TE TROUXE AQUI PARA ABENÇOAR.\nSE TUA VIDA É VAZIA, DEUS PODE MUDAR\nELE TE TROUXE AQUI PARA ABENÇOAR.\n\n\n<final>ENTREGA A TUA VIDA A JESUS,\nELE VAI TE TRANSFORMAR.<bis>\nELE DIZ: ''EU SOU O SENHOR,<bis>\nO REI DOS REIS, O REI DAS NAÇÕES ''.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (271, 'O CAMINHO QUE NOS LEVA AO CÉU É JESUS', 'O CAMINHO QUE NOS LEVA AO CÉU É JESUS', 'O CAMINHO QUE NOS LEVA AO CÉU É JESUS,\nO ÚNICO MEDIADOR ENTRE DEUS E OS HOMENS.\n\nCORO\nFOI ELE QUEM SE DEU A MORRER \nNA CRUZ, ELE É O NOSSO SALVADOR\nO SEU NOME É MARAVILHOSO,\nCONSELHEIRO, NOBRE, PRÍNCIPE DA PAZ,\nELE ERA, É, SEMPRE SERÁ\nO AUTOR DA NOSSA REDENÇÃO.\n\nO AMIGO QUE NUNCA FALHA É JESUS,\nAQUELE QUE NOS GARANTE A VIDA ETERNA.\n\nCORO\nFOI ELE QUEM SE DEU A MORRER \nNA CRUZ, ELE É O NOSSO SALVADOR\nO SEU NOME É MARAVILHOSO,\nCONSELHEIRO, NOBRE, PRÍNCIPE DA PAZ,\nELE ERA, É, SEMPRE SERÁ\nO AUTOR DA NOSSA REDENÇÃO.\n\nFINAL: (2X)\n(O AUTOR DA NOSSA REDENÇÃO)\nO AUTOR DA NOSSA REDENÇÃO.', 'O CAMINHO QUE NOS LEVA AO CÉU É JESUS,\nO ÚNICO MEDIADOR ENTRE DEUS E OS HOMENS.\n\n<coro>\nFOI ELE QUEM SE DEU A MORRER \nNA CRUZ, ELE É O NOSSO SALVADOR\nO SEU NOME É MARAVILHOSO,\nCONSELHEIRO, NOBRE, PRÍNCIPE DA PAZ,\nELE ERA, É, SEMPRE SERÁ\nO AUTOR DA NOSSA REDENÇÃO.\n\nO AMIGO QUE NUNCA FALHA É JESUS,\nAQUELE QUE NOS GARANTE A VIDA ETERNA.\n\n<coro>\nFOI ELE QUEM SE DEU A MORRER \nNA CRUZ, ELE É O NOSSO SALVADOR\nO SEU NOME É MARAVILHOSO,\nCONSELHEIRO, NOBRE, PRÍNCIPE DA PAZ,\nELE ERA, É, SEMPRE SERÁ\nO AUTOR DA NOSSA REDENÇÃO.\n\n\n<final>(<bis tipo=''2''>\n(O AUTOR DA NOSSA REDENÇÃO)\nO AUTOR DA NOSSA REDENÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (272, 'NOVO CAMINHO', 'NOVO CAMINHO', 'NOVO CAMINHO É O MEU JESUS,\nOUTRO CAMINHO NÃO PODES ENCONTRAR.\nPODES ENCONTRAR A PAZ, VIDA EM JESUS.\nSEGUE ESTE CAMINHO E TERÁS A LUZ.\n\nCORO\nPAZ, PAZ, VIDA, AMOR E LUZ,\nSE NÃO HÁ PAZ, PEDE A JESUS.\n\nDEIXA CRISTO SE REVELAR EM TEU CORAÇÃO,\nELE TE DARÁ A PAZ, VIDA E SALVAÇÃO.\n\nCORO\nPAZ, PAZ, VIDA, AMOR E LUZ,\nSE NÃO HÁ PAZ, PEDE A JESUS.\nPAZ, PAZ, VIDA, AMOR E LUZ,\nSE NÃO HÁ PAZ, PEDE A JESUS.', 'NOVO CAMINHO É O MEU JESUS,\nOUTRO CAMINHO NÃO PODES ENCONTRAR.\nPODES ENCONTRAR A PAZ, VIDA EM JESUS.\nSEGUE ESTE CAMINHO E TERÁS A LUZ.\n\n<coro>\nPAZ, PAZ, VIDA, AMOR E LUZ,\nSE NÃO HÁ PAZ, PEDE A JESUS.\n\nDEIXA CRISTO SE REVELAR EM TEU CORAÇÃO,\nELE TE DARÁ A PAZ, VIDA E SALVAÇÃO.<coro>\nPAZ, PAZ, VIDA, AMOR E LUZ,\nSE NÃO HÁ PAZ, PEDE A JESUS.\nPAZ, PAZ, VIDA, AMOR E LUZ,\nSE NÃO HÁ PAZ, PEDE A JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (273, 'O SENHOR É A ALEGRIA', 'O SENHOR É A ALEGRIA', 'O SENHOR É A ALEGRIA,\nÉ A PAZ E A REDENÇÃO,\nELE É O AUTOR DA SALVAÇÃO;\nO SENHOR É A FORTALEZA\nDOS QUE CRÊEM NELE ASSIM;\nE A VOCÊ ESTÁ CHAMANDO: \n''VENHA A MIM''.\nPODE TUDO CONFIAR A \nJESUS SE ENTREGAR SUA \nVIDA ELE PODERÁ MUDAR.\n\n''VINDE A MIM'', DISSE JESUS,\n''VÓS TODOS QUE ESTAIS CANSADOS, \nÓ VINDE A MIM''.\n\nFINAL: DISSE JESUS.', 'O SENHOR É A ALEGRIA,<bis>\nÉ A PAZ E A REDENÇÃO,<bis>\nELE É O AUTOR DA SALVAÇÃO;<bis>\nO SENHOR É A FORTALEZA<bis>\nDOS QUE CRÊEM NELE ASSIM;<bis>\nE A VOCÊ ESTÁ CHAMANDO: <bis>\n''VENHA A MIM''.<bis>\nPODE TUDO CONFIAR A <bis>\nJESUS SE ENTREGAR SUA <bis>\nVIDA ELE PODERÁ MUDAR.<bis>\n\n''VINDE A MIM'', DISSE JESUS,<bis>\n''VÓS TODOS QUE ESTAIS CANSADOS, <bis>\nÓ VINDE A MIM''.<bis>\n<final>DISSE JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (274, 'SE EM TUA VIDA NÃO ENCONTRAS PAZ E LUZ', 'SE EM TUA VIDA NÃO ENCONTRAS PAZ E LUZ', 'SE EM TUA VIDA NÃO ENCONTRAS PAZ E LUZ,\nSE O CAMINHO É DIFÍCIL E DE DOR,\nABRE O TEU CORAÇÃO HOJE A JESUS,\nELE VAI TE REVELAR O SEU AMOR;\n\nSE NO MUNDO TU ENFRENTAS MUITAS LUTAS,\nE AS LÁGRIMAS JÁ TOMAM O TEU SER,\nVEM A CRISTO, ELE JÁ VENCEU O MUNDO\nE COM ELE TAMBÉM HOJE VAIS VENCER.\n\nCORO\nLIMPA TUAS LÁGRIMAS, ALEGRIA E PAZ TE DÁ,\nVEM PARA CRISTO E A VITÓRIA TERÁS;\nEXISTE ESPERANÇA, DEUS PROVERÁ,\nENTREGA O TEU CAMINHO \nE TUDO ELE FARÁ.\n\nINSTRUMENTOS\n\nELE UM DIA TRANSFORMOU O MEU VIVER\nE PASSOU A HABITAR MEU CORAÇÃO,\nHOJE POSSO CONTEMPLAR O SEU PODER\nE JESUS SEGURA FORTE A MINHA MÃO;\n\nNESTE MUNDO ENFRENTAMOS MUITAS LUTAS,\nMAS COM CRISTO É MAIS FÁCIL DE VENCER.\nÉ SÓ ENTREGAR A ELE OS TEUS PROBLEMAS\nE UMA NOVA VIDA HOJE VAIS VIVER.\n\nCORO (2X)\nLIMPA TUAS LÁGRIMAS, ALEGRIA E PAZ TE DÁ,\nVEM PARA CRISTO E A VITÓRIA TERÁS;\nEXISTE ESPERANÇA, DEUS PROVERÁ,\nENTREGA O TEU CAMINHO \nE TUDO ELE FARÁ.\n\nFINAL: \nENTREGA O TEU CAMINHO \nE TUDO ELE FARÁ.', 'SE EM TUA VIDA NÃO ENCONTRAS PAZ E LUZ,\nSE O CAMINHO É DIFÍCIL E DE DOR,\nABRE O TEU CORAÇÃO HOJE A JESUS,\nELE VAI TE REVELAR O SEU AMOR;\n\nSE NO MUNDO TU ENFRENTAS MUITAS LUTAS,\nE AS LÁGRIMAS JÁ TOMAM O TEU SER,\nVEM A CRISTO, ELE JÁ VENCEU O MUNDO\nE COM ELE TAMBÉM HOJE VAIS VENCER.\n\n<coro>\nLIMPA TUAS LÁGRIMAS, ALEGRIA E PAZ TE DÁ,\nVEM PARA CRISTO E A VITÓRIA TERÁS;\nEXISTE ESPERANÇA, DEUS PROVERÁ,\nENTREGA O TEU CAMINHO \nE TUDO ELE FARÁ.\n<instrumentos>\n\n\nELE UM DIA TRANSFORMOU O MEU VIVER\nE PASSOU A HABITAR MEU CORAÇÃO,\nHOJE POSSO CONTEMPLAR O SEU PODER\nE JESUS SEGURA FORTE A MINHA MÃO;\n\nNESTE MUNDO ENFRENTAMOS MUITAS LUTAS,\nMAS COM CRISTO É MAIS FÁCIL DE VENCER.\nÉ SÓ ENTREGAR A ELE OS TEUS PROBLEMAS\nE UMA NOVA VIDA HOJE VAIS VIVER.\n\n<coro tipo=''2X''>\nLIMPA TUAS LÁGRIMAS, ALEGRIA E PAZ TE DÁ,\nVEM PARA CRISTO E A VITÓRIA TERÁS;\nEXISTE ESPERANÇA, DEUS PROVERÁ,\nENTREGA O TEU CAMINHO \nE TUDO ELE FARÁ.\n<final>ENTREGA O TEU CAMINHO \nE TUDO ELE FARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (275, 'UM MILAGRE É', 'UM MILAGRE É', 'UM MILAGRE É A MINHA VIDA AQUI,\nNESTE LUGAR, SEMPRE A TEUS PÉS.\nDESDE AQUELE DIA EM QUE ME\nALCANÇOU, EU VIVO PARA\nAGRADECER O TEU GRANDE AMOR.\n\nCORO\nESSE MILAGRE É, A TUA MORTE LÁ NA CRUZ, \nJESUS, DANDO-ME A VIDA,\nCURANDO TODAS AS MINHAS FERIDAS.\n\nHOJE POSSO OUVIR A TUA VOZ EM MIM,\nEU POSSO TER A TUA DIREÇÃO.\nSE VOCÊ QUISER TAMBÉM O PODE TER,\nÉ SÓ ABRIR SEU CORAÇÃO E O RECEBER.\n\nCORO\nESSE MILAGRE É, A TUA MORTE LÁ NA CRUZ, \nJESUS, DANDO-ME A VIDA,\nCURANDO TODAS AS MINHAS FERIDAS.\n\nINSTRUMENTOS\n\nESSE MILAGRE É, \nA TUA MORTE LÁ NA CRUZ, \nJESUS, DANDO-ME A VIDA,\nCURANDO TODAS AS MINHAS FERIDAS.\n\nFINAL: \nDANDO-ME A VIDA, \nCURANDO TODAS AS MINHAS FERIDAS.', 'UM MILAGRE É A MINHA VIDA AQUI,\nNESTE LUGAR, SEMPRE A TEUS PÉS.\nDESDE AQUELE DIA EM QUE ME\nALCANÇOU, EU VIVO PARA\nAGRADECER O TEU GRANDE AMOR.\n\n<coro>\nESSE MILAGRE É, A TUA MORTE LÁ NA CRUZ, \nJESUS, DANDO-ME A VIDA,\nCURANDO TODAS AS MINHAS FERIDAS.\n\nHOJE POSSO OUVIR A TUA VOZ EM MIM,\nEU POSSO TER A TUA DIREÇÃO.\nSE VOCÊ QUISER TAMBÉM O PODE TER,\nÉ SÓ ABRIR SEU CORAÇÃO E O RECEBER.\n\n<coro>\nESSE MILAGRE É, A TUA MORTE LÁ NA CRUZ, \nJESUS, DANDO-ME A VIDA,\nCURANDO TODAS AS MINHAS FERIDAS.\n<instrumentos>\n\n\nESSE MILAGRE É, \nA TUA MORTE LÁ NA CRUZ, \nJESUS, DANDO-ME A VIDA,\nCURANDO TODAS AS MINHAS FERIDAS.\n<final>DANDO-ME A VIDA, \nCURANDO TODAS AS MINHAS FERIDAS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (276, 'AINDA QUE OS SEUS SONHOS', 'AINDA QUE OS SEUS SONHOS', 'AINDA QUE OS SEUS SONHOS CAIAM PELO CHÃO\nE NÃO ENCONTRE UMA SAÍDA, UMA SOLUÇÃO,\nA VIDA PODE SER DIFÍCIL DE RESOLVER,\nE NESTA HORA QUE VOCÊ PRECISA RECONHECER.\n\nINSTRUMENTOS\n\nO MUNDO NÃO O CONHECE, \nPOR ISSO ELE PERECE, \nJESUS QUER SE DAR A CONHECER.\nVENHA A VERDADE RECEBER.\n\nCORO\nO FILHO DO DEUS ETERNO É JESUS.\nELE VEIO TE RESGATAR DAS TREVAS \nPARA A LUZ, DAS TREVAS PARA A LUZ.\nABRA AGORA O TEU CORAÇÃO A JESUS.\n\nINSTRUMENTOS\n\nO MUNDO NÃO O CONHECE, \nPOR ISSO ELE PERECE, \nJESUS QUER SE DAR A CONHECER.\nVENHA A VERDADE RECEBER.\n\nCORO (2X)\nO FILHO DO DEUS ETERNO É JESUS.\nELE VEIO TE RESGATAR DAS TREVAS \nPARA A LUZ, DAS TREVAS PARA A LUZ.\nABRA AGORA O TEU CORAÇÃO A JESUS.', 'AINDA QUE OS SEUS SONHOS CAIAM PELO CHÃO\nE NÃO ENCONTRE UMA SAÍDA, UMA SOLUÇÃO,\nA VIDA PODE SER DIFÍCIL DE RESOLVER,\nE NESTA HORA QUE VOCÊ PRECISA RECONHECER.\n<instrumentos>\n\n\nO MUNDO NÃO O CONHECE, \nPOR ISSO ELE PERECE, \nJESUS QUER SE DAR A CONHECER.\nVENHA A VERDADE RECEBER.\n\n<coro>\nO FILHO DO DEUS ETERNO É JESUS.\nELE VEIO TE RESGATAR DAS TREVAS \nPARA A LUZ, DAS TREVAS PARA A LUZ.\nABRA AGORA O TEU CORAÇÃO A JESUS.\n<instrumentos>\n\n\nO MUNDO NÃO O CONHECE, \nPOR ISSO ELE PERECE, \nJESUS QUER SE DAR A CONHECER.\nVENHA A VERDADE RECEBER.\n\n<coro tipo=''2X''>\nO FILHO DO DEUS ETERNO É JESUS.\nELE VEIO TE RESGATAR DAS TREVAS \nPARA A LUZ, DAS TREVAS PARA A LUZ.\nABRA AGORA O TEU CORAÇÃO A JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (277, 'ROCHA ETERNA', 'ROCHA ETERNA', 'ROCHA ETERNA, FOI NA CRUZ\nQUE MORRESTE TU, JESUS;\nVEM DE TI UM SANGUE TAL\nQUE ME LIMPA TODO O MAL.\nTRAZ AS BÊNÇÃOS DO PERDÃO:\nGOZO, PAZ E SALVAÇÃO.\n\nNEM TRABALHO, NEM PENAR\nPODE O PECADOR SALVAR;\nSÓ TU PODES, BOM JESUS,\nDAR-ME VIDA, PAZ E LUZ.\nPEÇO-TE PERDÃO, SENHOR,\nPOIS CONFIO EM TEU AMOR.\n\nEIS QUE VEM A MORTE ATRÁS\nDESTA VIDA TÃO FUGAZ.\nQUANDO EU AO MEU LAR SUBIR,\nE TEU ROSTO EM GLÓRIA VIR,\nROCHA ETERNA, QUE PRAZER\nEU TEREI DE EM TI VIVER!', 'ROCHA ETERNA, FOI NA CRUZ\nQUE MORRESTE TU, JESUS;\nVEM DE TI UM SANGUE TAL\nQUE ME LIMPA TODO O MAL.\nTRAZ AS BÊNÇÃOS DO PERDÃO:\nGOZO, PAZ E SALVAÇÃO.\n\nNEM TRABALHO, NEM PENAR\nPODE O PECADOR SALVAR;\nSÓ TU PODES, BOM JESUS,\nDAR-ME VIDA, PAZ E LUZ.\nPEÇO-TE PERDÃO, SENHOR,\nPOIS CONFIO EM TEU AMOR.\n\nEIS QUE VEM A MORTE ATRÁS\nDESTA VIDA TÃO FUGAZ.\nQUANDO EU AO MEU LAR SUBIR,\nE TEU ROSTO EM GLÓRIA VIR,\nROCHA ETERNA, QUE PRAZER\nEU TEREI DE EM TI VIVER!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (278, 'A NOVA DO EVANGELHO', 'A NOVA DO EVANGELHO', 'A NOVA DO EVANGELHO\nJÁ SE FEZ OUVIR AQUI;\nBOAS NOVAS, TÃO ALEGRES,\nELAS SÃO PRA QUEM OUVIR:\nASSIM DEUS NOS AMOU,\nSIM, A CADA PECADOR,\nQUE NOS DEU SEU FILHO AMADO\nPRA SOFRER A NOSSA DOR.\n\nCORO\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!\n\nA NOVA DO EVANGELHO\nDÁ-NOS TODOS A SABER\nQUE FARTURA HÁ PARA TODOS,\nVEM, DE GRAÇA, RECEBER.\nDA VIDA O PÃO EU SOU; \nSATISFEITO FICARÁS;\nTEUS PECADOS E TUA ALMA\nLAVAREI, E PAZ TERÁS.\n\nCORO\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!\n\nA NOVA DO EVANGELHO\nORA VEM NOS AVISAR\nDO PERIGO GRANDE E GRAVE,\nPARA QUEM SE DESCUIDAR:\nSALVAI-VOS DESDE JÁ;\nNÃO VOS DEMOREIS, ENTÃO,\nNÃO VIREIS OS VOSSOS OLHOS,\nOH! FUGI DA PERDIÇÃO!\n\nCORO\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!\n\nA NOVA DO EVANGELHO \nJUBILOSO SOM NOS É,\nPOIS O AMOR DE JESUS CRISTO\nDÁ PERDÃO MEDIANTE A FÉ.\nAS NOVAS SE VOS DÃO\nQUE JÁ VEIO O SALVADOR,\nTÃO BONDOSO E PODEROSO,\nQUE PERDOA AO PECADOR.\n\nCORO\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!', 'A NOVA DO EVANGELHO\nJÁ SE FEZ OUVIR AQUI;\nBOAS NOVAS, TÃO ALEGRES,\nELAS SÃO PRA QUEM OUVIR:\nASSIM DEUS NOS AMOU,\nSIM, A CADA PECADOR,\nQUE NOS DEU SEU FILHO AMADO\nPRA SOFRER A NOSSA DOR.\n\n<coro>\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!\n\nA NOVA DO EVANGELHO\nDÁ-NOS TODOS A SABER\nQUE FARTURA HÁ PARA TODOS,\nVEM, DE GRAÇA, RECEBER.\nDA VIDA O PÃO EU SOU; \nSATISFEITO FICARÁS;\nTEUS PECADOS E TUA ALMA\nLAVAREI, E PAZ TERÁS.\n\n<coro>\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!\n\nA NOVA DO EVANGELHO\nORA VEM NOS AVISAR\nDO PERIGO GRANDE E GRAVE,\nPARA QUEM SE DESCUIDAR:\nSALVAI-VOS DESDE JÁ;\nNÃO VOS DEMOREIS, ENTÃO,\nNÃO VIREIS OS VOSSOS OLHOS,\nOH! FUGI DA PERDIÇÃO!\n\n<coro>\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!\n\nA NOVA DO EVANGELHO \nJUBILOSO SOM NOS É,\nPOIS O AMOR DE JESUS CRISTO\nDÁ PERDÃO MEDIANTE A FÉ.\nAS NOVAS SE VOS DÃO\nQUE JÁ VEIO O SALVADOR,\nTÃO BONDOSO E PODEROSO,\nQUE PERDOA AO PECADOR.\n\n<coro>\nSANTA PAZ (SANTA PAZ)\nE PERDÃO! (E PERDÃO!)\nSÃO AS NOVAS LÁ DOS CÉUS!\nSANTA PAZ (SANTA PAZ) \nE PERDÃO! (E PERDÃO!)\nÉ BENDITO O NOSSO DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (279, 'QUERO ESTAR AO PÉ DA CRUZ', 'QUERO ESTAR AO PÉ DA CRUZ', 'QUERO ESTAR AO PÉ DA CRUZ,\nDE ONDE RICA FONTE\nCORRE FRANCA, SALUTAR,\nDO CALVÁRIO, MONTE.\n\nCORO\nSIM, NA CRUZ, SIM, NA CRUZ,\nSEMPRE ME GLORIO E ENFIM \nVOU DESCANSAR SALVO, \nALÉM DO RIO.\n\nA TREMER AO PÉ DA CRUZ, \nGRAÇA ETERNA ACHOU-ME;\nMATUTINA ESTRELA ALI RAIOS \nSEUS MANDOU-ME.\n\nCORO\nSIM, NA CRUZ, SIM, NA CRUZ,\nSEMPRE ME GLORIO E ENFIM \nVOU DESCANSAR SALVO, \nALÉM DO RIO.\n\nSEMPRE A CRUZ, JESUS, MEU DEUS,\nQUEIRAS RECORDAR-ME;\nDELA À SOMBRA, SALVADOR,\nQUEIRAS ABRIGAR-ME.\n\nCORO\nSIM, NA CRUZ, SIM, NA CRUZ,\nSEMPRE ME GLORIO E ENFIM \nVOU DESCANSAR SALVO, \nALÉM DO RIO.\n\nJUNTO À CRUZ, ARDENDO EM FÉ,\nSEM TEMOR VIGIO, \nPOIS À TERRA SANTA IREI, \nSALVO, ALÉM DO RIO.', 'QUERO ESTAR AO PÉ DA CRUZ,\nDE ONDE RICA FONTE\nCORRE FRANCA, SALUTAR,\nDO CALVÁRIO, MONTE.\n\n<coro>\nSIM, NA CRUZ, SIM, NA CRUZ,\nSEMPRE ME GLORIO E ENFIM \nVOU DESCANSAR SALVO, \nALÉM DO RIO.\n\nA TREMER AO PÉ DA CRUZ, \nGRAÇA ETERNA ACHOU-ME;\nMATUTINA ESTRELA ALI RAIOS \nSEUS MANDOU-ME.\n\n<coro>\nSIM, NA CRUZ, SIM, NA CRUZ,\nSEMPRE ME GLORIO E ENFIM \nVOU DESCANSAR SALVO, \nALÉM DO RIO.\n\nSEMPRE A CRUZ, JESUS, MEU DEUS,\nQUEIRAS RECORDAR-ME;\nDELA À SOMBRA, SALVADOR,\nQUEIRAS ABRIGAR-ME.\n\n<coro>\nSIM, NA CRUZ, SIM, NA CRUZ,\nSEMPRE ME GLORIO E ENFIM \nVOU DESCANSAR SALVO, \nALÉM DO RIO.\n\nJUNTO À CRUZ, ARDENDO EM FÉ,\nSEM TEMOR VIGIO, \nPOIS À TERRA SANTA IREI, \nSALVO, ALÉM DO RIO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (280, 'HÁ HOJE ALGUÉM ESPERANDO', 'HÁ HOJE ALGUÉM ESPERANDO', 'HÁ HOJE ALGUÉM ESPERANDO\nPARA JESUS ENCONTRAR?\nVENHA, SEM MAIS DEMORAR-SE,\nCRISTO VAI HOJE PASSAR!\nEI-LO DE MÃOS ESTENDIDAS,\nCHEIO DE GRAÇA SEM PAR.\nOH! QUE VENTURA INAUDITA,\nCRISTO VAI HOJE PASSAR!\n\nCORO\nCRISTO VAI HOJE PASSAR, PASSAR, PASSAR!\nCRISTO VAI HOJE PASSAR, \nPASSAR, VAI HOJE PASSAR!\nPASSA DE AMOR TRANSBORDANDO,\nTODOS A SI CONVIDANDO.\nO MESTRE VAI HOJE PASSAR (PASSAR) VARÕES\nSIM, HOJE ELE VAI PASSAR!\n\nVARÕES\n\nHÁ INDA ALGUÉM DUVIDANDO\nDO SEU PODER DE SALVAR?\nPOIS VENHA EXPERIMENTÁ-LO,\nCRISTO VAI HOJE PASSAR!\nO SEU PODER É DIVINO,\nO SEU AMOR É SEM PAR.\nÓ CORAÇÃO QUEBRANTADO!\nCRISTO VAI HOJE PASSAR!\n\nCORO\nCRISTO VAI HOJE PASSAR, PASSAR, PASSAR!\nCRISTO VAI HOJE PASSAR, \nPASSAR, VAI HOJE PASSAR!\nPASSA DE AMOR TRANSBORDANDO,\nTODOS A SI CONVIDANDO.\nO MESTRE VAI HOJE PASSAR (PASSAR) VARÕES\nSIM, HOJE ELE VAI PASSAR!\n\nVARÕES\n\nHÁ INDA ALGUÉM DEMORANDO\nPARA JESUS ACEITAR?\nEIS QUE O SENHOR ESTÁ PERTO,\nELE VAI HOJE PASSAR!\nÓ PECADOR DESDITOSO,\nNÃO CESSES POIS DE CLAMAR!\nVEM TUAS CULPAS CHORANDO;\nCRISTO VAI HOJE PASSAR!\n\nCORO\nCRISTO VAI HOJE PASSAR, PASSAR, PASSAR!\nCRISTO VAI HOJE PASSAR, \nPASSAR, VAI HOJE PASSAR!\nPASSA DE AMOR TRANSBORDANDO,\nTODOS A SI CONVIDANDO.\nO MESTRE VAI HOJE PASSAR (PASSAR) VARÕES\nSIM, HOJE ELE VAI PASSAR!\n\nVARÕES', 'HÁ HOJE ALGUÉM ESPERANDO\nPARA JESUS ENCONTRAR?\nVENHA, SEM MAIS DEMORAR-SE,\nCRISTO VAI HOJE PASSAR!\nEI-LO DE MÃOS ESTENDIDAS,\nCHEIO DE GRAÇA SEM PAR.\nOH! QUE VENTURA INAUDITA,\nCRISTO VAI HOJE PASSAR!\n\n<coro>\nCRISTO VAI HOJE PASSAR, PASSAR, PASSAR!\nCRISTO VAI HOJE PASSAR, \nPASSAR, VAI HOJE PASSAR!\nPASSA DE AMOR TRANSBORDANDO,\nTODOS A SI CONVIDANDO.\nO MESTRE VAI HOJE PASSAR (PASSAR) <h>\nSIM, HOJE ELE VAI PASSAR!\n\n<h>\n\n\nHÁ INDA ALGUÉM DUVIDANDO\nDO SEU PODER DE SALVAR?\nPOIS VENHA EXPERIMENTÁ-LO,\nCRISTO VAI HOJE PASSAR!\nO SEU PODER É DIVINO,\nO SEU AMOR É SEM PAR.\nÓ CORAÇÃO QUEBRANTADO!\nCRISTO VAI HOJE PASSAR!\n\n<coro>\nCRISTO VAI HOJE PASSAR, PASSAR, PASSAR!\nCRISTO VAI HOJE PASSAR, \nPASSAR, VAI HOJE PASSAR!\nPASSA DE AMOR TRANSBORDANDO,\nTODOS A SI CONVIDANDO.\nO MESTRE VAI HOJE PASSAR (PASSAR) <h>\nSIM, HOJE ELE VAI PASSAR!\n\n<h>\n\n\nHÁ INDA ALGUÉM DEMORANDO\nPARA JESUS ACEITAR?\nEIS QUE O SENHOR ESTÁ PERTO,\nELE VAI HOJE PASSAR!\nÓ PECADOR DESDITOSO,\nNÃO CESSES POIS DE CLAMAR!\nVEM TUAS CULPAS CHORANDO;\nCRISTO VAI HOJE PASSAR!\n\n<coro>\nCRISTO VAI HOJE PASSAR, PASSAR, PASSAR!\nCRISTO VAI HOJE PASSAR, \nPASSAR, VAI HOJE PASSAR!\nPASSA DE AMOR TRANSBORDANDO,\nTODOS A SI CONVIDANDO.\nO MESTRE VAI HOJE PASSAR (PASSAR) <h>\nSIM, HOJE ELE VAI PASSAR!\n\n<h>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (281, 'ESTE MUNDO NÃO TEM A SUA PAZ', 'ESTE MUNDO NÃO TEM A SUA PAZ', 'ESTE MUNDO NÃO TEM A SUA PAZ,\nESTE MUNDO NÃO CONHECE O QUE É AMOR,\nESTE MUNDO NÃO SABE O QUE É SER FELIZ,\nEU TAMBÉM NÃO SABIA,\nMAS JESUS UM DIA ME ENCONTROU.\n\nJESUS BUSCOU-ME COM SEUS BRAÇOS \nDE TERNURA, FALOU-ME DE UM AMOR \nQUE JAMAIS CONHECI,\nFEZ-ME ENTENDER O QUE É A SALVAÇÃO,\nENTÃO, ABRI O MEU CORAÇÃO.\n\nCORO \nELE É JESUS (ELE É JESUS) (BIS)\nO AMOR VERDADEIRO \nQUE O HOMEM PODE TER.\n\nINSTRUMENTOS\n\nJESUS BUSCOU-ME COM SEUS BRAÇOS \nDE TERNURA, FALOU-ME DE UM AMOR \nQUE JAMAIS CONHECI,\nFEZ-ME ENTENDER O QUE É A SALVAÇÃO,\nENTÃO, ABRI O MEU CORAÇÃO.\n\nCORO (2X)\nELE É JESUS (ELE É JESUS) (BIS)\nO AMOR VERDADEIRO \nQUE O HOMEM PODE TER.', 'ESTE MUNDO NÃO TEM A SUA PAZ,\nESTE MUNDO NÃO CONHECE O QUE É AMOR,\nESTE MUNDO NÃO SABE O QUE É SER FELIZ,\nEU TAMBÉM NÃO SABIA,\nMAS JESUS UM DIA ME ENCONTROU.\n\nJESUS BUSCOU-ME COM SEUS BRAÇOS \nDE TERNURA, FALOU-ME DE UM AMOR \nQUE JAMAIS CONHECI,\nFEZ-ME ENTENDER O QUE É A SALVAÇÃO,\nENTÃO, ABRI O MEU CORAÇÃO.\n\n<coro>\nELE É JESUS (ELE É JESUS) <bis>\nO AMOR VERDADEIRO \nQUE O HOMEM PODE TER.\n<instrumentos>\n\n\nJESUS BUSCOU-ME COM SEUS BRAÇOS \nDE TERNURA, FALOU-ME DE UM AMOR \nQUE JAMAIS CONHECI,\nFEZ-ME ENTENDER O QUE É A SALVAÇÃO,\nENTÃO, ABRI O MEU CORAÇÃO.\n\n<coro tipo=''2X''>\nELE É JESUS (ELE É JESUS) <bis>\nO AMOR VERDADEIRO \nQUE O HOMEM PODE TER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (282, 'QUEM É QUE DÁ ÁGUA AO SEDENTO?', 'QUEM É QUE DÁ ÁGUA AO SEDENTO?', 'QUEM É QUE DÁ ÁGUA AO SEDENTO \nE UMA SOMBRA FRESCA?\nQUEM É QUE RETIRA DO HOMEM TODO ARDOR?\nQUEM É QUE ABRIU NO CALVÁRIO \nUM NOVO CAMINHO?\nQUEM É A FONTE DA VIDA, \nO GRANDE AMOR?\n\nCORO\nÉ O FILHO DE DEUS, É JESUS, O SENHOR,\nÉ O GRANDE EU SOU, \nELE É O CORDEIRO DE DEUS,\nO AUTOR DA ETERNA VIDA, ELE É JESUS.\n\nINSTRUMENTOS\n\nQUEM É QUE DÁ ÁGUA AO SEDENTO\nNUMA TERRA SECA?\nQUEM É A FLOR MAIS QUERIDA \nDO LINDO JARDIM?\nQUEM É QUE TRAZ PAZ \nE CONSOLO DENTRO DA ALMA?\nQUEM É O AMIGO EXCELENTE, \nO SALVADOR?\n\nCORO\nÉ O FILHO DE DEUS, É JESUS, O SENHOR,\nÉ O GRANDE EU SOU, \nELE É O CORDEIRO DE DEUS,\nO AUTOR DA ETERNA VIDA, ELE É JESUS.\n\nINSTRUMENTOS\n\nCORO\nÉ O FILHO DE DEUS, É JESUS, O SENHOR,\nÉ O GRANDE EU SOU, \nELE É O CORDEIRO DE DEUS,\nO AUTOR DA ETERNA VIDA, ELE É JESUS.', 'QUEM É QUE DÁ ÁGUA AO SEDENTO \nE UMA SOMBRA FRESCA?\nQUEM É QUE RETIRA DO HOMEM TODO ARDOR?\nQUEM É QUE ABRIU NO CALVÁRIO \nUM NOVO CAMINHO?\nQUEM É A FONTE DA VIDA, \nO GRANDE AMOR?\n\n<coro>\nÉ O FILHO DE DEUS, É JESUS, O SENHOR,\nÉ O GRANDE EU SOU, \nELE É O CORDEIRO DE DEUS,\nO AUTOR DA ETERNA VIDA, ELE É JESUS.\n<instrumentos>\n\n\nQUEM É QUE DÁ ÁGUA AO SEDENTO\nNUMA TERRA SECA?\nQUEM É A FLOR MAIS QUERIDA \nDO LINDO JARDIM?\nQUEM É QUE TRAZ PAZ \nE CONSOLO DENTRO DA ALMA?\nQUEM É O AMIGO EXCELENTE, \nO SALVADOR?\n\n<coro>\nÉ O FILHO DE DEUS, É JESUS, O SENHOR,\nÉ O GRANDE EU SOU, \nELE É O CORDEIRO DE DEUS,\nO AUTOR DA ETERNA VIDA, ELE É JESUS.\n<instrumentos>\n\n\n<coro>\nÉ O FILHO DE DEUS, É JESUS, O SENHOR,\nÉ O GRANDE EU SOU, \nELE É O CORDEIRO DE DEUS,\nO AUTOR DA ETERNA VIDA, ELE É JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (283, 'O MUNDO NÃO SABE', 'O MUNDO NÃO SABE', 'O MUNDO NÃO SABE A HISTÓRIA DE JESUS \nE PENSA QUE TUDO TERMINOU NA CRUZ,\nMAS EU SEI QUE A HISTÓRIA NÃO CHEGOU AO FIM, \nJESUS ESTÁ VIVO PARA MIM!\n\nNAQUELA MANHÃ QUANDO O SOL RAIOU,\nA PORTA DA SEPULTURA SE ABRIU\nE O MESTRE AOS DISCÍPULOS SE APRESENTOU,\nO CORDEIRO QUE FOI MORTO RESSURGIU!\n\nCORO (2X)\nALELUIA, RESSUSCITOU! \nCRISTO RESSUSCITOU\nE ELE VIVO HOJE ESTÁ, \nE BREVE VOLTARÁ!\n\nO MUNDO NÃO MAIS O VIU NEM IRÁ VER\nMAS HOJE À SUA IGREJA DÁ-SE A CONHECER \nCOM MUITOS SINAIS E PROVAS DE AMOR, \nJESUS CRISTO ESTÁ VIVO E É SENHOR!\n\nCORO (2X)\nALELUIA, RESSUSCITOU! \nCRISTO RESSUSCITOU\nE ELE VIVO HOJE ESTÁ, \nE BREVE VOLTARÁ!', 'O MUNDO NÃO SABE A HISTÓRIA DE JESUS \nE PENSA QUE TUDO TERMINOU NA CRUZ,\nMAS EU SEI QUE A HISTÓRIA NÃO CHEGOU AO FIM, \nJESUS ESTÁ VIVO PARA MIM!\n\nNAQUELA MANHÃ QUANDO O SOL RAIOU,\nA PORTA DA SEPULTURA SE ABRIU\nE O MESTRE AOS DISCÍPULOS SE APRESENTOU,\nO CORDEIRO QUE FOI MORTO RESSURGIU!\n\n<coro tipo=''2X''>\nALELUIA, RESSUSCITOU! \nCRISTO RESSUSCITOU\nE ELE VIVO HOJE ESTÁ, \nE BREVE VOLTARÁ!\n\nO MUNDO NÃO MAIS O VIU NEM IRÁ VER\nMAS HOJE À SUA IGREJA DÁ-SE A CONHECER \nCOM MUITOS SINAIS E PROVAS DE AMOR, \nJESUS CRISTO ESTÁ VIVO E É SENHOR!\n\n<coro tipo=''2X''>\nALELUIA, RESSUSCITOU! \nCRISTO RESSUSCITOU\nE ELE VIVO HOJE ESTÁ, \nE BREVE VOLTARÁ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (284, 'O AMOR DE DEUS É GRANDE', 'O AMOR DE DEUS É GRANDE', 'O AMOR DE DEUS É GRANDE,\nMANDOU SEU FILHO À CRUZ\nA MORRER POR MIM E POR TI\nE TAMBÉM PARA VENCER,\nVENCER A MORTE, VENCER A DOR;\nELE É JESUS, UNIGÊNITO FILHO,\nREI, SENHOR, SALVADOR.\n\nCORO\nTE CHAMA PRA VIDA, \nTE CHAMA PRA LUZ,\nVENCEU A MORTE, ELE É JESUS,\nQUER TE SALVAR, VIDA TE DAR,\nVEM A JESUS.\n\nUM ALTO PREÇO ELE PAGOU\nSÓ POR AMOR AO PECADOR,\nALI NA CRUZ JESUS MORREU\nE DEPOIS RESSUSCITOU,\nVENCEU A MORTE, VENCEU A DOR;\nELE É JESUS, UNIGÊNITO FILHO,\nREI, SENHOR, SALVADOR.\n\nCORO\nTE CHAMA PRA VIDA, \nTE CHAMA PRA LUZ,\nVENCEU A MORTE, ELE É JESUS,\nQUER TE SALVAR, VIDA TE DAR,\nVEM A JESUS.\n\nFINAL:\nTE CHAMA PRA VIDA (TE CHAMA PRA VIDA) \nTE CHAMA PRA LUZ (TE CHAMA PRA LUZ) \nVENCEU A MORTE(ELE VENCEU) \nELE É JESUS (ELE É JESUS) \nQUER TE SALVAR (QUER TE SALVAR) \nVIDA TE DAR, \nVEM A JESUS. (BIS)', 'O AMOR DE DEUS É GRANDE,\nMANDOU SEU FILHO À CRUZ\nA MORRER POR MIM E POR TI\nE TAMBÉM PARA VENCER,\nVENCER A MORTE, VENCER A DOR;\nELE É JESUS, UNIGÊNITO FILHO,\nREI, SENHOR, SALVADOR.\n\n<coro>\nTE CHAMA PRA VIDA, \nTE CHAMA PRA LUZ,\nVENCEU A MORTE, ELE É JESUS,\nQUER TE SALVAR, VIDA TE DAR,\nVEM A JESUS.\n\nUM ALTO PREÇO ELE PAGOU\nSÓ POR AMOR AO PECADOR,\nALI NA CRUZ JESUS MORREU\nE DEPOIS RESSUSCITOU,\nVENCEU A MORTE, VENCEU A DOR;\nELE É JESUS, UNIGÊNITO FILHO,\nREI, SENHOR, SALVADOR.\n\n<coro>\nTE CHAMA PRA VIDA, \nTE CHAMA PRA LUZ,\nVENCEU A MORTE, ELE É JESUS,\nQUER TE SALVAR, VIDA TE DAR,\nVEM A JESUS.\n\n\n<final>TE CHAMA PRA VIDA (TE CHAMA PRA VIDA) \nTE CHAMA PRA LUZ (TE CHAMA PRA LUZ) \nVENCEU A MORTE(ELE VENCEU) \nELE É JESUS (ELE É JESUS) \nQUER TE SALVAR (QUER TE SALVAR) \nVIDA TE DAR, \nVEM A JESUS. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (285, 'TU QUE ANDAS SÓ E TRISTE SEM SABER O CAMINHO', 'TU QUE ANDAS SÓ E TRISTE SEM SABER O CAMINHO', 'TU QUE ANDAS SÓ E TRISTE SEM SABER \nO CAMINHO, EXISTE ALGUÉM \nQUE PODE TUA FOME E TUA SEDE SACIAR;\nELE ESTÁ À PORTA DO TEU CORAÇÃO\nE INSISTENTE BATE AGORA, DEIXA-O ENTRAR, \nDEIXA-O FLUIR EM TEU SER.\n\nQUEM É JESUS? \n''EU SOU AQUELE QUE NA CRUZ MORRI POR TI, \nMEU SANGUE ALI VERTI PRA TE SALVAR, (PRA TE SALVAR) \nPOR TE AMAR, (POR TE AMAR) \nE QUERO TUA VIDA MUDAR.''\n\nINSTRUMENTOS\n\nTU QUE ANDAS SÓ E TRISTE SEM SABER \nO CAMINHO, EXISTE ALGUÉM \nQUE PODE TE AJUDAR E UMA VIDA NOVA TE DAR;\nELE ESTÁ À PORTA DO TEU CORAÇÃO\nE INSISTENTE BATE AGORA, DEIXA-O ENTRAR, \nDEIXA-O FLUIR EM TEU SER.\n\nQUERO JESUS! (SERVAS)\nPOIS SEI QUE NUMA CRUZ \nPOR MIM MORREU,\nSEU SANGUE ALI VERTEU\nPRA ME SALVAR, \n(PRA ME SALVAR) SERVAS\nPOR ME AMAR, \n(POR ME AMAR) SERVAS\nE PODE MINHA VIDA MUDAR.\n\nQUERO JESUS!\nE RENDEREI A ELE O MEU LOUVOR\nPOR TUDO QUE A MIM FEZ, \nQUERO SEMPRE A TI, JESUS, SER FIEL.', 'TU QUE ANDAS SÓ E TRISTE SEM SABER \nO CAMINHO, EXISTE ALGUÉM \nQUE PODE TUA FOME E TUA SEDE SACIAR;\nELE ESTÁ À PORTA DO TEU CORAÇÃO\nE INSISTENTE BATE AGORA, DEIXA-O ENTRAR, \nDEIXA-O FLUIR EM TEU SER.\n\nQUEM É JESUS? \n''EU SOU AQUELE QUE NA CRUZ MORRI POR TI, \nMEU SANGUE ALI VERTI PRA TE SALVAR, (PRA TE SALVAR) \nPOR TE AMAR, (POR TE AMAR) \nE QUERO TUA VIDA MUDAR.''\n<instrumentos>\n\n\nTU QUE ANDAS SÓ E TRISTE SEM SABER \nO CAMINHO, EXISTE ALGUÉM \nQUE PODE TE AJUDAR E UMA VIDA NOVA TE DAR;\nELE ESTÁ À PORTA DO TEU CORAÇÃO\nE INSISTENTE BATE AGORA, DEIXA-O ENTRAR, \nDEIXA-O FLUIR EM TEU SER.\n\nQUERO JESUS! <m>\nPOIS SEI QUE NUMA CRUZ \nPOR MIM MORREU,\nSEU SANGUE ALI VERTEU\nPRA ME SALVAR, \n(PRA ME SALVAR) <m>\nPOR ME AMAR, \n(POR ME AMAR) <m>\nE PODE MINHA VIDA MUDAR.\n\nQUERO JESUS!\nE RENDEREI A ELE O MEU LOUVOR\nPOR TUDO QUE A MIM FEZ, \nQUERO SEMPRE A TI, JESUS, SER FIEL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (286, 'UM DIA EU QUIS TE DEIXAR', 'UM DIA EU QUIS TE DEIXAR', 'UM DIA EU QUIS TE DEIXAR,\nPARTIR E SER LIVRE PARA VIVER;\nABANDONEI-TE, TÃO CEGO NÃO VI\nCOMO ENTÃO FERI TEU CORAÇÃO DE PAI.\nBEM CEDO TUDO PERDI,\nA SOLIDÃO TOMOU CONTA DE MIM;\nENTÃO LEMBREI-ME DA CASA DO PAI\nE CONTRITO VIM, VOLTANDO PARA TI.\n\nCORO\nVOLTEI, MEU PAI,\nAO TEU AMOR INCONDICIONAL!\nÉS MINHA HERANÇA,\nCONTIGO SOU TÃO FELIZ, MEU DEUS!\n\nDE LONGE VISTE CHEGAR\nE ME ABRAÇASTE COM TANTO AMOR,\nE HOUVE CÂNTICOS, FESTA NOS CÉUS,\nPOIS VOLTOU À CASA UM POBRE PECADOR.\n\nFINAL: TÃO FELIZ!', 'UM DIA EU QUIS TE DEIXAR,\nPARTIR E SER LIVRE PARA VIVER;\nABANDONEI-TE, TÃO CEGO NÃO VI\nCOMO ENTÃO FERI TEU CORAÇÃO DE PAI.\nBEM CEDO TUDO PERDI,\nA SOLIDÃO TOMOU CONTA DE MIM;\nENTÃO LEMBREI-ME DA CASA DO PAI\nE CONTRITO VIM, VOLTANDO PARA TI.\n\n<coro>\nVOLTEI, MEU PAI,\nAO TEU AMOR INCONDICIONAL!\nÉS MINHA HERANÇA,\nCONTIGO SOU TÃO FELIZ, MEU DEUS!\n\nDE LONGE VISTE CHEGAR\nE ME ABRAÇASTE COM TANTO AMOR,\nE HOUVE CÂNTICOS, FESTA NOS CÉUS,\nPOIS VOLTOU À CASA UM POBRE PECADOR.\n<final>TÃO FELIZ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (287, 'NÃO TINHA PARECER', 'NÃO TINHA PARECER', 'NÃO TINHA PARECER NEM FORMOSURA,\nERA DESPREZADO ENTRE OS HOMENS,\nCOMO OVELHA MUDA FOI SACRIFICADO,\nELE VENCEU O MUNDO, SIM,\nELE VENCEU A MORTE.\n\nCORO\nLÁ NA CRUZ, LÁ NA CRUZ\nO SEU SANGUE DERRAMOU,\nLÁ NA CRUZ, LÁ NA CRUZ\nSUA VIDA ENTREGOU;\nÉ POR ISSO QUE CANTO ALELUIA,\nÉ POR ISSO QUE AMO A JESUS,\nNÃO POSSO VIVER SEM O SEU AMOR,\nJESUS É TUDO PRA MIM.\n\nINSTRUMENTOS\n\nJESUS MORREU AQUI POR NOSSAS VIDAS,\nSEU AMOR É INCOMPARÁVEL,\nFOI SUBINDO COMO UM RENOVO\nE RAIZ DE UMA TERRA SECA,\nCONCEDENDO-NOS SEU PERDÃO,\nCONCEDENDO-NOS SALVAÇÃO.\n\nCORO\nLÁ NA CRUZ, LÁ NA CRUZ\nO SEU SANGUE DERRAMOU,\nLÁ NA CRUZ, LÁ NA CRUZ\nSUA VIDA ENTREGOU;\nÉ POR ISSO QUE CANTO ALELUIA,\nÉ POR ISSO QUE AMO A JESUS,\nNÃO POSSO VIVER SEM O SEU AMOR,\nJESUS É TUDO PRA MIM.', 'NÃO TINHA PARECER NEM FORMOSURA,\nERA DESPREZADO ENTRE OS HOMENS,\nCOMO OVELHA MUDA FOI SACRIFICADO,\nELE VENCEU O MUNDO, SIM,\nELE VENCEU A MORTE.\n\n<coro>\nLÁ NA CRUZ, LÁ NA CRUZ\nO SEU SANGUE DERRAMOU,\nLÁ NA CRUZ, LÁ NA CRUZ\nSUA VIDA ENTREGOU;\nÉ POR ISSO QUE CANTO ALELUIA,\nÉ POR ISSO QUE AMO A JESUS,\nNÃO POSSO VIVER SEM O SEU AMOR,\nJESUS É TUDO PRA MIM.\n<instrumentos>\n\n\nJESUS MORREU AQUI POR NOSSAS VIDAS,\nSEU AMOR É INCOMPARÁVEL,\nFOI SUBINDO COMO UM RENOVO\nE RAIZ DE UMA TERRA SECA,\nCONCEDENDO-NOS SEU PERDÃO,\nCONCEDENDO-NOS SALVAÇÃO.\n\n<coro>\nLÁ NA CRUZ, LÁ NA CRUZ\nO SEU SANGUE DERRAMOU,\nLÁ NA CRUZ, LÁ NA CRUZ\nSUA VIDA ENTREGOU;\nÉ POR ISSO QUE CANTO ALELUIA,\nÉ POR ISSO QUE AMO A JESUS,\nNÃO POSSO VIVER SEM O SEU AMOR,\nJESUS É TUDO PRA MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (288, 'BASTA DIZERES O QUE QUERES', 'BASTA DIZERES O QUE QUERES', 'BASTA DIZERES O QUE QUERES\nJESUS PRONTO ESTÁ A TE OUVIR,\nBASTA COM O SENHOR SERES SINCERO \nE ELE TE RESPONDERÁ.\n\nA ALEGRIA QUE NO MUNDO \nJAMAIS PUDESTE ENCONTRAR, \nEM CRISTO TERÁS O PRAZER, \nSIM, DELA GOZAR.\n\nCORO\nSENTE OS BRAÇOS DE JESUS\nQUERENDO TE SOCORRER,\nOUVE A VOZ SUAVE DO FILHO DE DEUS\nDIZENDO: ''TE AMO E QUERO TE SALVAR.'' \n\nCRISTO QUER QUE ESTEJAS CONOSCO\nQUANDO VIER NOS BUSCAR\nPROCLAMANDO: \n''VINDE BENDITOS DE MEU PAI \nCOMIGO NO CÉU MORAR''.\n\nCORO\nSENTE OS BRAÇOS DE JESUS\nQUERENDO TE SOCORRER,\nOUVE A VOZ SUAVE DO FILHO DE DEUS\nDIZENDO: ''TE AMO E QUERO TE SALVAR.''\n\n''TE AMO E QUERO TE SALVAR.''', 'BASTA DIZERES O QUE QUERES\nJESUS PRONTO ESTÁ A TE OUVIR,\nBASTA COM O SENHOR SERES SINCERO \nE ELE TE RESPONDERÁ.\n\nA ALEGRIA QUE NO MUNDO \nJAMAIS PUDESTE ENCONTRAR, \nEM CRISTO TERÁS O PRAZER, \nSIM, DELA GOZAR.\n\n<coro>\nSENTE OS BRAÇOS DE JESUS\nQUERENDO TE SOCORRER,\nOUVE A VOZ SUAVE DO FILHO DE DEUS\nDIZENDO: ''TE AMO E QUERO TE SALVAR.'' \n\nCRISTO QUER QUE ESTEJAS CONOSCO\nQUANDO VIER NOS BUSCAR\nPROCLAMANDO: \n''VINDE BENDITOS DE MEU PAI \nCOMIGO NO CÉU MORAR''.\n\n<coro>\nSENTE OS BRAÇOS DE JESUS\nQUERENDO TE SOCORRER,\nOUVE A VOZ SUAVE DO FILHO DE DEUS\nDIZENDO: ''TE AMO E QUERO TE SALVAR.''\n\n''TE AMO E QUERO TE SALVAR.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (289, 'ESTENDE TUA MÃO', 'ESTENDE TUA MÃO', 'ESTENDE TUA MÃO AO DEUS QUE TE AMA,\nABRE O CORAÇÃO AO DEUS QUE TE GUARDA;\nSÓ ELE SABERÁ TEUS PROBLEMAS RESOLVER,\nÓ ABRE O TEU CORAÇÃO A DEUS.\n\nELE SERÁ TEU PASTOR, SÓ ELE TE GUIARÁ\nJUNTO ÀS ÁGUAS TRANQÜILAS,\nREFRIGERA TUA VIDA,\nELE TE MOSTRARÁ A SALVAÇÃO.\n\nSÓ ESTENDE TUA MÃO AO DEUS QUE \nTE AMA, ABRE O CORAÇÃO AO DEUS QUE TE GUARDA;\nSÓ ELE SABERÁ TEUS PROBLEMAS RESOLVER\nÓ ABRE O TEU CORAÇÃO A DEUS. (2X)', 'ESTENDE TUA MÃO AO DEUS QUE TE AMA,<bis>\nABRE O CORAÇÃO AO DEUS QUE TE GUARDA;<bis>\nSÓ ELE SABERÁ TEUS PROBLEMAS RESOLVER,<bis>\nÓ ABRE O TEU CORAÇÃO A DEUS.<bis>\n\nELE SERÁ TEU PASTOR, SÓ ELE TE GUIARÁ\nJUNTO ÀS ÁGUAS TRANQÜILAS,\nREFRIGERA TUA VIDA,\nELE TE MOSTRARÁ A SALVAÇÃO.\n\nSÓ ESTENDE TUA MÃO AO DEUS QUE \nTE AMA, ABRE O CORAÇÃO AO DEUS QUE TE GUARDA;\nSÓ ELE SABERÁ TEUS PROBLEMAS RESOLVER\nÓ ABRE O TEU CORAÇÃO A DEUS. <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (290, 'O QUE OS OLHOS NUNCA VIRAM', 'O QUE OS OLHOS NUNCA VIRAM', 'O QUE OS OLHOS NUNCA VIRAM,\nE O CORAÇÃO NUNCA SENTIU,\nDEUS PREPAROU EM SEU FAVOR,\nPARA O ABENÇOAR\nABRA SEU CORAÇÃO E DEIXE QUE A LUZ,\nVENHA BRILHAR EM SEU VIVER, \nETERNAMENTE.\n\nCORO\nENTÃO COMECE A GLORIFICAR\nPELO QUE AINDA NÃO VIU.\nSE DEUS PROMETEU, VAI SE CUMPRIR\nSUA BÊNÇÃO VAI CHEGAR.\n\nABRA SEU CORAÇÃO \nE DEIXE QUE A LUZ,\nVENHA BRILHAR EM SEU VIVER, \nETERNAMENTE\n\nCORO (2X)\nENTÃO COMECE A GLORIFICAR\nPELO QUE AINDA NÃO VIU.\nSE DEUS PROMETEU, VAI SE CUMPRIR\nSUA BÊNÇÃO VAI CHEGAR.\n\nFINAL: (2X)\nDEUS TEM SEMPRE O MELHOR, \nMESMO QUE A LUZ \nNÃO BRILHE EM SEUS OLHOS. \nVÊ, DEUS AMA VOCÊ! \nJÁ DECRETOU A SUA VITÓRIA. \n\nBASTA CRER, BASTA CRER.', 'O QUE OS OLHOS NUNCA VIRAM,\nE O CORAÇÃO NUNCA SENTIU,\nDEUS PREPAROU EM SEU FAVOR,\nPARA O ABENÇOAR\nABRA SEU CORAÇÃO E DEIXE QUE A LUZ,\nVENHA BRILHAR EM SEU VIVER, \nETERNAMENTE.\n\n<coro>\nENTÃO COMECE A GLORIFICAR\nPELO QUE AINDA NÃO VIU.\nSE DEUS PROMETEU, VAI SE CUMPRIR\nSUA BÊNÇÃO VAI CHEGAR.\n\nABRA SEU CORAÇÃO \nE DEIXE QUE A LUZ,\nVENHA BRILHAR EM SEU VIVER, \nETERNAMENTE\n\n<coro tipo=''2X''>\nENTÃO COMECE A GLORIFICAR\nPELO QUE AINDA NÃO VIU.\nSE DEUS PROMETEU, VAI SE CUMPRIR\nSUA BÊNÇÃO VAI CHEGAR.\n\n\n<final>(<bis tipo=''2''>\nDEUS TEM SEMPRE O MELHOR, \nMESMO QUE A LUZ \nNÃO BRILHE EM SEUS OLHOS. \nVÊ, DEUS AMA VOCÊ! \nJÁ DECRETOU A SUA VITÓRIA. \n\nBASTA CRER, BASTA CRER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (291, 'SEMPRE QUE QUISERES FALAREI CONTIGO', 'SEMPRE QUE QUISERES FALAREI CONTIGO', 'SEMPRE QUE QUISERES FALAREI CONTIGO, \nSEMPRE QUE PRECISARES, \nESTAREI À DISPOSIÇÃO \nPRA MOSTRAR A TI O MEU AMOR \nE DAR-TE A MINHA SALVAÇÃO.\n\nO MEU AMOR POR TI, Ó FILHO É MUITO GRANDE \nTÃO GRANDE QUE NÃO PODES NEM IMAGINAR \nPOR VOCÊ EU DEI MEU ÚNICO FILHO, \nPRA MORRER NAQUELA CRUZ, \nPRA QUE VOCÊ TENHA VIDA EM ABUNDÂNCIA.\nPRA QUE VOCÊ TENHA VIDA ETERNA.\n\nO MEU AMOR POR TI, Ó FILHO É MUITO GRANDE \nTÃO GRANDE QUE NÃO PODES NEM IMAGINAR \nPOR VOCÊ EU DEI MEU ÚNICO FILHO, \nPRA MORRER NAQUELA CRUZ, \nPRA QUE VOCÊ TENHA VIDA EM ABUNDÂNCIA.\nPRA QUE VOCÊ TENHA VIDA ETERNA.', 'SEMPRE QUE QUISERES FALAREI CONTIGO, <bis>\nSEMPRE QUE PRECISARES, <bis>\nESTAREI À DISPOSIÇÃO <bis>\nPRA MOSTRAR A TI O MEU AMOR <bis>\nE DAR-TE A MINHA SALVAÇÃO.<bis>\n\nO MEU AMOR POR TI, Ó FILHO É MUITO GRANDE \nTÃO GRANDE QUE NÃO PODES NEM IMAGINAR \nPOR VOCÊ EU DEI MEU ÚNICO FILHO, \nPRA MORRER NAQUELA CRUZ, \nPRA QUE VOCÊ TENHA VIDA EM ABUNDÂNCIA.\nPRA QUE VOCÊ TENHA VIDA ETERNA.\n\nO MEU AMOR POR TI, Ó FILHO É MUITO GRANDE \nTÃO GRANDE QUE NÃO PODES NEM IMAGINAR \nPOR VOCÊ EU DEI MEU ÚNICO FILHO, \nPRA MORRER NAQUELA CRUZ, \nPRA QUE VOCÊ TENHA VIDA EM ABUNDÂNCIA.\nPRA QUE VOCÊ TENHA VIDA ETERNA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (292, 'AO SENTIR O MUNDO AO MEU REDOR', 'AO SENTIR O MUNDO AO MEU REDOR', 'AO SENTIR O MUNDO AO MEU REDOR,\nNADA VI QUE PUDESSE SER REAL.\nPERCEBI QUE TODOS BUSCAM PAZ, PORÉM EM VÃO,\nPOIS NAQUILO QUE PROCURAM NÃO HÁ SOLUÇÃO.\nNÃO HÁ SOLUÇÃO.\n\nSÓ EM JESUS, A PAZ REAL EU PUDE ENCONTRAR.\nO SEU AMOR PUDE EXPERIMENTAR.\nME ENTREGUEI A CRISTO,\nE A VIDA ETERNA VOU GOZAR.\n\nINSTRUMENTOS \n\nPOSSO VER QUE VOCÊ NÃO É FELIZ,\nVOU DIZER QUE NÃO PODE SER FELIZ,\nSE CONTINUAR A PROCURAR EM VÃO,\nPOR CAMINHOS QUE NÃO TRAZEM SOLUÇÃO.\nNÃO TRAZEM SOLUÇÃO.\n\nSÓ EM JESUS, A PAZ REAL VOCÊ VAI ENCONTRAR.\nO SEU AMOR VAI EXPERIMENTAR.\nVENHA A JESUS CRISTO,\nE A VIDA ETERNA VAI GOZAR.\n\nINSTRUMENTOS \n\nSÓ EM JESUS, A PAZ REAL VOCÊ VAI ENCONTRAR.\nO SEU AMOR VAI EXPERIMENTAR.\nVENHA A JESUS CRISTO,\nE A VIDA ETERNA VAI GOZAR.', 'AO SENTIR O MUNDO AO MEU REDOR,\nNADA VI QUE PUDESSE SER REAL.\nPERCEBI QUE TODOS BUSCAM PAZ, PORÉM EM VÃO,\nPOIS NAQUILO QUE PROCURAM NÃO HÁ SOLUÇÃO.\nNÃO HÁ SOLUÇÃO.\n\nSÓ EM JESUS, A PAZ REAL EU PUDE ENCONTRAR.\nO SEU AMOR PUDE EXPERIMENTAR.\nME ENTREGUEI A CRISTO,\nE A VIDA ETERNA VOU GOZAR.\n<instrumentos>\n\n\nPOSSO VER QUE VOCÊ NÃO É FELIZ,\nVOU DIZER QUE NÃO PODE SER FELIZ,\nSE CONTINUAR A PROCURAR EM VÃO,\nPOR CAMINHOS QUE NÃO TRAZEM SOLUÇÃO.\nNÃO TRAZEM SOLUÇÃO.\n\nSÓ EM JESUS, A PAZ REAL VOCÊ VAI ENCONTRAR.\nO SEU AMOR VAI EXPERIMENTAR.\nVENHA A JESUS CRISTO,\nE A VIDA ETERNA VAI GOZAR.\n<instrumentos>\n\n\nSÓ EM JESUS, A PAZ REAL VOCÊ VAI ENCONTRAR.\nO SEU AMOR VAI EXPERIMENTAR.\nVENHA A JESUS CRISTO,\nE A VIDA ETERNA VAI GOZAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (293, 'ALMA CANSADA', 'ALMA CANSADA', 'ALMA CANSADA, NÃO DESESPERES, ESPERA EM DEUS.\nQUE ELE VEM, QUE ELE VEM, TE SOCORRER\nALMA CANSADA, NÃO DESESPERES, ESPERA EM DEUS,\nESPERA EM DEUS, ESPERA EM DEUS\nE NO SEU PODER.\n\nCORO\nÓ ALMA CANSADA, ESPERA EM DEUS\nE NO SEU AMOR.\nVEM, ALMA CANSADA, ESPERA EM DEUS,\nCONFIA SOMENTE NO SEU AMOR.\n\nINSTRUMENTOS\n\nALMA CANSADA, O TEU LAMENTO NÃO RESOLVERÁ.\nA HORA É TRISTE, COM FÉ INSISTE, DEUS TE OUVIRÁ.\nSE TEUS MOMENTOS TRAZEM TORMENTOS\nQUE FAZEM CHORAR, DEUS TE CHAMA AGORA,\nÓ VEM, SEM DEMORA EM PAZ DESCANSAR.\n\nCORO\nÓ ALMA CANSADA, ESPERA EM DEUS\nE NO SEU AMOR.\nVEM, ALMA CANSADA, ESPERA EM DEUS,\nCONFIA SOMENTE NO SEU AMOR.', 'ALMA CANSADA, NÃO DESESPERES, ESPERA EM DEUS.\nQUE ELE VEM, QUE ELE VEM, TE SOCORRER\nALMA CANSADA, NÃO DESESPERES, ESPERA EM DEUS,\nESPERA EM DEUS, ESPERA EM DEUS\nE NO SEU PODER.\n\n<coro>\nÓ ALMA CANSADA, ESPERA EM DEUS\nE NO SEU AMOR.\nVEM, ALMA CANSADA, ESPERA EM DEUS,\nCONFIA SOMENTE NO SEU AMOR.\n<instrumentos>\n\n\nALMA CANSADA, O TEU LAMENTO NÃO RESOLVERÁ.\nA HORA É TRISTE, COM FÉ INSISTE, DEUS TE OUVIRÁ.\nSE TEUS MOMENTOS TRAZEM TORMENTOS\nQUE FAZEM CHORAR, DEUS TE CHAMA AGORA,\nÓ VEM, SEM DEMORA EM PAZ DESCANSAR.\n\n<coro>\nÓ ALMA CANSADA, ESPERA EM DEUS\nE NO SEU AMOR.\nVEM, ALMA CANSADA, ESPERA EM DEUS,\nCONFIA SOMENTE NO SEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (294, 'JESUS IA CAMINHANDO (CANTA MEU POVO)', 'JESUS IA CAMINHANDO (CANTA MEU POVO)', 'JESUS IA CAMINHANDO,\nSUBINDO PRA JERUSALÉM.\nCOM ELE IAM OS SEUS DISCÍPULOS\nE OS FARISEUS TAMBÉM.\nOS DISCÍPULOS SE ALEGRAVAM,\nCANTAVAM E DAVAM LOUVOR,\nDIZENDO: BENDITO É O REI\nQUE VEM EM NOME DO SENHOR.\n\nCORO\nCANTA MEU POVO, ALEGRA MEU POVO,\nQUE A FESTA NÃO VAI ACABAR\nQUANDO FINDAR NA TERRA, \nNO CÉU VAI CONTINUAR.\n\nOS FARISEUS MURMURAVAM,\nFALAVAM COM ANSIEDADE\nMANDE QUE O POVO SE CALE,\nNÃO PERTURBE A CIDADE.\nJESUS OLHANDO PARA ELES,\nLHES DISSE COM SATISFAÇÃO:\nSE ELES SE CALAREM,\nLOGO AS PEDRAS CLAMARÃO.\n\nCORO\nCANTA MEU POVO, ALEGRA MEU POVO,\nQUE A FESTA NÃO VAI ACABAR\nQUANDO FINDAR NA TERRA, \nNO CÉU VAI CONTINUAR.\n\nE NÓS QUE SABEMOS ISTO,\nQUE FOI JESUS QUEM FALOU,\nANTES QUE AS PEDRAS CLAMEM,\nNÓS CLAMAMOS AO SENHOR.\nJESUS DESCEU DA SUA GLÓRIA\nPRA NOS TRAZER SALVAÇÃO,\nNÃO HÁ NINGUÉM QUE TIRE\nO GOZO DO MEU CORAÇÃO.\n\nCORO (2X)\nCANTA MEU POVO, ALEGRA MEU POVO,\nQUE A FESTA NÃO VAI ACABAR\nQUANDO FINDAR NA TERRA, \nNO CÉU VAI CONTINUAR.', 'JESUS IA CAMINHANDO,\nSUBINDO PRA JERUSALÉM.\nCOM ELE IAM OS SEUS DISCÍPULOS\nE OS FARISEUS TAMBÉM.\nOS DISCÍPULOS SE ALEGRAVAM,\nCANTAVAM E DAVAM LOUVOR,\nDIZENDO: BENDITO É O REI\nQUE VEM EM NOME DO SENHOR.\n\n<coro>\nCANTA MEU POVO, ALEGRA MEU POVO,\nQUE A FESTA NÃO VAI ACABAR\nQUANDO FINDAR NA TERRA, \nNO CÉU VAI CONTINUAR.\n\nOS FARISEUS MURMURAVAM,\nFALAVAM COM ANSIEDADE\nMANDE QUE O POVO SE CALE,\nNÃO PERTURBE A CIDADE.\nJESUS OLHANDO PARA ELES,\nLHES DISSE COM SATISFAÇÃO:\nSE ELES SE CALAREM,\nLOGO AS PEDRAS CLAMARÃO.\n\n<coro>\nCANTA MEU POVO, ALEGRA MEU POVO,\nQUE A FESTA NÃO VAI ACABAR\nQUANDO FINDAR NA TERRA, \nNO CÉU VAI CONTINUAR.\n\nE NÓS QUE SABEMOS ISTO,\nQUE FOI JESUS QUEM FALOU,\nANTES QUE AS PEDRAS CLAMEM,\nNÓS CLAMAMOS AO SENHOR.\nJESUS DESCEU DA SUA GLÓRIA\nPRA NOS TRAZER SALVAÇÃO,\nNÃO HÁ NINGUÉM QUE TIRE\nO GOZO DO MEU CORAÇÃO.\n\n<coro tipo=''2X''>\nCANTA MEU POVO, ALEGRA MEU POVO,\nQUE A FESTA NÃO VAI ACABAR\nQUANDO FINDAR NA TERRA, \nNO CÉU VAI CONTINUAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (295, 'DAS PROFUNDEZAS A TI CLAMO, Ó SENHOR', 'DAS PROFUNDEZAS A TI CLAMO, Ó SENHOR', 'DAS PROFUNDEZAS A TI CLAMO, Ó SENHOR, ESCUTA A MINHA VOZ;\nSEJAM OS TEUS OUVIDOS ATENTOS \nÀ VOZ DAS MINHAS SÚPLICAS; SE TU, SENHOR,\nOBSERVARES AS INIQÜIDADES, \nSENHOR, QUEM SUBSISTIRÁ?\nMAS CONTIGO ESTÁ O PERDÃO \nPARA QUE SEJAS TEMIDO, \nAGUARDO O SENHOR,\nA MINHA ALMA O AGUARDA.\n\nE ESPERO NA SUA PALAVRA,\nA MINH''ALMA ANSEIA PELO SENHOR\nMAIS DO QUE OS GUARDAS\nPELO ROMPER DA MANHÃ,\nSIM, DO QUE AQUELES\nQUE ESPERAM PELA MANHÃ.\n\nESPERA, ISRAEL, NO SENHOR,\nPORQUE NO SENHOR HÁ MISERICÓRDIA\nE NELE HÁ ABUNDANTE REDENÇÃO,\nE ELE REMIRÁ A ISRAEL\nDE TODAS AS SUAS INIQÜIDADES.', 'DAS PROFUNDEZAS A TI CLAMO, Ó SENHOR, ESCUTA A MINHA VOZ;\nSEJAM OS TEUS OUVIDOS ATENTOS \nÀ VOZ DAS MINHAS SÚPLICAS; SE TU, SENHOR,\nOBSERVARES AS INIQÜIDADES, \nSENHOR, QUEM SUBSISTIRÁ?\nMAS CONTIGO ESTÁ O PERDÃO \nPARA QUE SEJAS TEMIDO, \nAGUARDO O SENHOR,\nA MINHA ALMA O AGUARDA.\n\nE ESPERO NA SUA PALAVRA,\nA MINH''ALMA ANSEIA PELO SENHOR\nMAIS DO QUE OS GUARDAS\nPELO ROMPER DA MANHÃ,\nSIM, DO QUE AQUELES\nQUE ESPERAM PELA MANHÃ.\n\nESPERA, ISRAEL, NO SENHOR,\nPORQUE NO SENHOR HÁ MISERICÓRDIA\nE NELE HÁ ABUNDANTE REDENÇÃO,<bis>\nE ELE REMIRÁ A ISRAEL<bis>\nDE TODAS AS SUAS INIQÜIDADES.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (296, 'TODA A MINHA DOR JESUS LEVOU', 'TODA A MINHA DOR JESUS LEVOU', 'TODA A MINHA DOR JESUS LEVOU\nE A TRISTEZA E O PRANTO ELE ENXUGOU,\nHOJE SOU FELIZ PORQUE O SENHOR\nDE TODO O PECADO ME LAVOU.\n\nCORO\nDEIXA-ME CHORAR A TEUS PÉS, SENHOR,\nQUERO AGRADECER TEU GRANDE AMOR;\nE JUNTO DA CRUZ QUERO ESTAR,\nA TEUS PÉS, JESUS, DEIXA CHORAR.\n\nO SEU SANGUE PURO DERRAMOU,\nTODO O MAL DO MUNDO ELE VENCEU;\nPOR SEU DIVINAL E EXCELSO AMOR\nA TODOS PERDÃO QUIS CONCEDER.\n\nCORO\nDEIXA-ME CHORAR A TEUS PÉS, SENHOR,\nQUERO AGRADECER TEU GRANDE AMOR;\nE JUNTO DA CRUZ QUERO ESTAR,\nA TEUS PÉS, JESUS, DEIXA CHORAR.\n\nPARA TI JESUS ESTÁ OLHANDO,\nCOM MAIOR TERNURA ESTÁ PEDINDO:\n''DÁ-ME, FILHO MEU, TEU CORAÇÃO\nE UM DIA TERÁS UM GALARDÃO!''\n\nCORO\nDEIXA-ME CHORAR A TEUS PÉS, SENHOR,\nQUERO AGRADECER TEU GRANDE AMOR;\nE JUNTO DA CRUZ QUERO ESTAR,\nA TEUS PÉS, JESUS, DEIXA CHORAR.', 'TODA A MINHA DOR JESUS LEVOU\nE A TRISTEZA E O PRANTO ELE ENXUGOU,\nHOJE SOU FELIZ PORQUE O SENHOR\nDE TODO O PECADO ME LAVOU.\n\n<coro>\nDEIXA-ME CHORAR A TEUS PÉS, SENHOR,\nQUERO AGRADECER TEU GRANDE AMOR;\nE JUNTO DA CRUZ QUERO ESTAR,\nA TEUS PÉS, JESUS, DEIXA CHORAR.\n\nO SEU SANGUE PURO DERRAMOU,\nTODO O MAL DO MUNDO ELE VENCEU;\nPOR SEU DIVINAL E EXCELSO AMOR\nA TODOS PERDÃO QUIS CONCEDER.\n\n<coro>\nDEIXA-ME CHORAR A TEUS PÉS, SENHOR,\nQUERO AGRADECER TEU GRANDE AMOR;\nE JUNTO DA CRUZ QUERO ESTAR,\nA TEUS PÉS, JESUS, DEIXA CHORAR.\n\nPARA TI JESUS ESTÁ OLHANDO,\nCOM MAIOR TERNURA ESTÁ PEDINDO:\n''DÁ-ME, FILHO MEU, TEU CORAÇÃO\nE UM DIA TERÁS UM GALARDÃO!''\n\n<coro>\nDEIXA-ME CHORAR A TEUS PÉS, SENHOR,\nQUERO AGRADECER TEU GRANDE AMOR;\nE JUNTO DA CRUZ QUERO ESTAR,\nA TEUS PÉS, JESUS, DEIXA CHORAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (297, 'EM ME VINDO O TEMOR', 'EM ME VINDO O TEMOR', 'EM ME VINDO O TEMOR HEI DE CONFIAR EM TI,\nEM ME VINDO A DOR DESCANSAREI EM TI;\nPOR QUE TEMER SE COMIGO ESTÁS?\nTE SINTO TÃO PERTO, SEGURO ME FAZES.\n\nTU ME ENSINASTE A EM TI CONFIAR,\nTU ME AJUDASTE A EM TI ESPERAR;\nDÁ-ME MAIS FÉ PARA PROSSEGUIR\nE NUNCA TEMER O QUE HÁ DE VIR.\n\nEM TI EU SOU FORTE, CONHEÇO TUA PAZ,\nCONTIGO AO MEU LADO O TEMOR SE DESFAZ;\nPOR QUE TEMER SE COMIGO ESTÁS?\nTE SINTO TÃO PERTO, SEGURO ME FAZES.', 'EM ME VINDO O TEMOR HEI DE CONFIAR EM TI,\nEM ME VINDO A DOR DESCANSAREI EM TI;\nPOR QUE TEMER SE COMIGO ESTÁS?\nTE SINTO TÃO PERTO, SEGURO ME FAZES.\n\nTU ME ENSINASTE A EM TI CONFIAR,\nTU ME AJUDASTE A EM TI ESPERAR;\nDÁ-ME MAIS FÉ PARA PROSSEGUIR\nE NUNCA TEMER O QUE HÁ DE VIR.\n\nEM TI EU SOU FORTE, CONHEÇO TUA PAZ,\nCONTIGO AO MEU LADO O TEMOR SE DESFAZ;\nPOR QUE TEMER SE COMIGO ESTÁS?\nTE SINTO TÃO PERTO, SEGURO ME FAZES.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (298, 'NEM SEMPRE ENTENDEMOS', 'NEM SEMPRE ENTENDEMOS', 'NEM SEMPRE ENTENDEMOS \nPORQUE DEUS AGE ASSIM,\nO ESPINHO QUE A BELA ROSA TEM;\nMAS PELA FÉ SABEMOS \nQUE TUDO QUE ELE FAZ É SEMPRE, \nSEMPRE PARA O NOSSO BEM.\n\nCORO\nNADA ME SEPARA DESSE AMOR,\nSEMPRE CONFIAREI NO MEU SENHOR;\nSEI QUE CUIDARÁ DE MIM, \nCOM DESVELO ATÉ O FIM, \nNADA ME SEPARARÁ DO AMOR DE DEUS.\n\nA DOR E O SOFRIMENTO, \nA MORTE TÃO CRUEL,\nVENCEU NA CRUZ O NOSSO EMANUEL;\nDE CINZAS AS VESTES TROCA \nPOR VESTES DE LOUVOR \nE ÓLEO DE ALEGRIA DÁ-NOS O SENHOR.\n\nCORO\nNADA ME SEPARA DESSE AMOR,\nSEMPRE CONFIAREI NO MEU SENHOR;\nSEI QUE CUIDARÁ DE MIM, \nCOM DESVELO ATÉ O FIM, \nNADA ME SEPARARÁ DO AMOR DE DEUS. (BIS)', 'NEM SEMPRE ENTENDEMOS \nPORQUE DEUS AGE ASSIM,\nO ESPINHO QUE A BELA ROSA TEM;\nMAS PELA FÉ SABEMOS \nQUE TUDO QUE ELE FAZ É SEMPRE, \nSEMPRE PARA O NOSSO BEM.\n\n<coro>\nNADA ME SEPARA DESSE AMOR,\nSEMPRE CONFIAREI NO MEU SENHOR;\nSEI QUE CUIDARÁ DE MIM, \nCOM DESVELO ATÉ O FIM, \nNADA ME SEPARARÁ DO AMOR DE DEUS.\n\nA DOR E O SOFRIMENTO, \nA MORTE TÃO CRUEL,\nVENCEU NA CRUZ O NOSSO EMANUEL;\nDE CINZAS AS VESTES TROCA \nPOR VESTES DE LOUVOR \nE ÓLEO DE ALEGRIA DÁ-NOS O SENHOR.\n\n<coro>\nNADA ME SEPARA DESSE AMOR,\nSEMPRE CONFIAREI NO MEU SENHOR;\nSEI QUE CUIDARÁ DE MIM, \nCOM DESVELO ATÉ O FIM, \nNADA ME SEPARARÁ DO AMOR DE DEUS. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (299, 'HÁ MOMENTOS QUE AS PALAVRAS NÃO RESOLVEM', 'HÁ MOMENTOS QUE AS PALAVRAS NÃO RESOLVEM', 'HÁ MOMENTOS QUE AS PALAVRAS \nNÃO RESOLVEM,\nMAS O GESTO DE JESUS, NA CRUZ, \nDEMONSTRA AMOR POR NÓS.\n\nCORO (2X)\nFOI NO CALVÁRIO\nQUE ELE SEM FALAR,\nMOSTROU AO MUNDO \nINTEIRO O QUE É AMAR.\n\nAQUI NO MUNDO \nAS DESILUSÕES SÃO TANTAS,\nMAS EXISTE UMA ESPERANÇA:\nQUE CRISTO VAI VOLTAR.\n\nCORO (2X)\nFOI NO CALVÁRIO\nQUE ELE SEM FALAR,\nMOSTROU AO MUNDO \nINTEIRO O QUE É AMAR.', 'HÁ MOMENTOS QUE AS PALAVRAS <bis>\nNÃO RESOLVEM,<bis>\nMAS O GESTO DE JESUS, NA CRUZ, <bis>\nDEMONSTRA AMOR POR NÓS.<bis>\n\n<coro tipo=''2X''>\nFOI NO CALVÁRIO\nQUE ELE SEM FALAR,\nMOSTROU AO MUNDO \nINTEIRO O QUE É AMAR.\n\nAQUI NO MUNDO <bis>\nAS DESILUSÕES SÃO TANTAS,<bis>\nMAS EXISTE UMA ESPERANÇA:<bis>\nQUE CRISTO VAI VOLTAR.<bis>\n\n<coro tipo=''2X''>\nFOI NO CALVÁRIO\nQUE ELE SEM FALAR,\nMOSTROU AO MUNDO \nINTEIRO O QUE É AMAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (300, 'QUANDO PARECE QUE TUDO ACABOU', 'QUANDO PARECE QUE TUDO ACABOU', 'QUANDO PARECE QUE TUDO ACABOU\nE NÃO HÁ MAIS ESPERANÇA EM TEU VIVER,\nERGUE TEU OLHAR E CLAMA A JESUS,\nCRÊ SOMENTE: ELE TEM PODER.\n\nCORO\nOH! NÃO TEMAS, MAS CONFIA EM JESUS,\nTEUS PROBLEMAS DEUS CONHECE E TUDO VÊ;\nNÃO CHORES MAIS, JESUS TE AMA,\nNÃO TEMAS, SOMENTE CRÊ.\n\nNÃO TEMAS, CRÊ SOMENTE EM JESUS,\nIMPOSSÍVEIS NÃO HÁ PARA O SENHOR,\nPEDE EM ORAÇÃO E TÃO SOMENTE CRÊ,\nGRANDE É, POR TI, O SEU AMOR.\n\nCORO\nOH! NÃO TEMAS, MAS CONFIA EM JESUS,\nTEUS PROBLEMAS DEUS CONHECE E TUDO VÊ;\nNÃO CHORES MAIS, JESUS TE AMA,\nNÃO TEMAS, SOMENTE CRÊ.\n\nFINAL: \nNÃO CHORES MAIS, JESUS TE AMA,\nNÃO TEMAS, SOMENTE CRÊ.', 'QUANDO PARECE QUE TUDO ACABOU\nE NÃO HÁ MAIS ESPERANÇA EM TEU VIVER,\nERGUE TEU OLHAR E CLAMA A JESUS,\nCRÊ SOMENTE: ELE TEM PODER.\n\n<coro>\nOH! NÃO TEMAS, MAS CONFIA EM JESUS,\nTEUS PROBLEMAS DEUS CONHECE E TUDO VÊ;\nNÃO CHORES MAIS, JESUS TE AMA,\nNÃO TEMAS, SOMENTE CRÊ.\n\nNÃO TEMAS, CRÊ SOMENTE EM JESUS,\nIMPOSSÍVEIS NÃO HÁ PARA O SENHOR,\nPEDE EM ORAÇÃO E TÃO SOMENTE CRÊ,\nGRANDE É, POR TI, O SEU AMOR.\n\n<coro>\nOH! NÃO TEMAS, MAS CONFIA EM JESUS,\nTEUS PROBLEMAS DEUS CONHECE E TUDO VÊ;\nNÃO CHORES MAIS, JESUS TE AMA,\nNÃO TEMAS, SOMENTE CRÊ.\n\n\n<final>NÃO CHORES MAIS, JESUS TE AMA,\nNÃO TEMAS, SOMENTE CRÊ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (301, 'QUANDO A TRISTEZA SURGIR', 'QUANDO A TRISTEZA SURGIR', 'QUANDO A TRISTEZA SURGIR\nE O MUNDO TE ENGANAR,\nLEMBRA-TE QUE JESUS CRISTO\nCOM SEU SANGUE TE PODE SALVAR.\n\nCORO (2X)\nCANTA FELIZ E ORA COM FERVOR,\nO SANGUE DE JESUS\nMOSTROU-NOS SEU AMOR.\n\nQUANDO A ALEGRIA VOLTAR\nE A PAZ INVADIR O TEU SER,\nDIZE ALELUIA A JESUS\nPOIS SEU SANGUE TEM ESSE PODER.\n\nCORO (2X)\nCANTA FELIZ E ORA COM FERVOR,\nO SANGUE DE JESUS\nMOSTROU-NOS SEU AMOR.', 'QUANDO A TRISTEZA SURGIR\nE O MUNDO TE ENGANAR,\nLEMBRA-TE QUE JESUS CRISTO\nCOM SEU SANGUE TE PODE SALVAR.\n\n<coro tipo=''2X''>\nCANTA FELIZ E ORA COM FERVOR,\nO SANGUE DE JESUS\nMOSTROU-NOS SEU AMOR.\n\nQUANDO A ALEGRIA VOLTAR\nE A PAZ INVADIR O TEU SER,\nDIZE ALELUIA A JESUS\nPOIS SEU SANGUE TEM ESSE PODER.\n\n<coro tipo=''2X''>\nCANTA FELIZ E ORA COM FERVOR,\nO SANGUE DE JESUS\nMOSTROU-NOS SEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (302, 'SE A VIDA PARECE PESADA', 'SE A VIDA PARECE PESADA', 'SE A VIDA PARECE PESADA\nE ACHAS QUE CHEGOU AO FIM;\nÓ VEM A JESUS SEM DEMORA,\nPORQUE ELE DISSE ASSIM:\n\nCORO\n''VINDE A MIM, CANSADOS, \nSOBRECARREGADOS, E EU VOS ALIVIAREI;\nVINDE A MIM, ENTREGAI O VOSSO CORAÇÃO, \nE VIDA ETERNA VOS DAREI.''\n\nTÃO CEDO A TRISTEZA TE ABATE\nE ENTRA EM TEU CORAÇÃO;\nNÃO TEMAS, CONFIA EM CRISTO,\nTERÁS PLENA PAZ, SALVAÇÃO.\n\nCORO (2X)\n''VINDE A MIM, CANSADOS, \nSOBRECARREGADOS, E EU VOS ALIVIAREI;\nVINDE A MIM, ENTREGAI O VOSSO CORAÇÃO, \nE VIDA ETERNA VOS DAREI.''\n\nFINAL: ''E VIDA ETERNA VOS DAREI.''', 'SE A VIDA PARECE PESADA\nE ACHAS QUE CHEGOU AO FIM;\nÓ VEM A JESUS SEM DEMORA,\nPORQUE ELE DISSE ASSIM:\n\n<coro>\n''VINDE A MIM, CANSADOS, \nSOBRECARREGADOS, E EU VOS ALIVIAREI;\nVINDE A MIM, ENTREGAI O VOSSO CORAÇÃO, \nE VIDA ETERNA VOS DAREI.''\n\nTÃO CEDO A TRISTEZA TE ABATE\nE ENTRA EM TEU CORAÇÃO;\nNÃO TEMAS, CONFIA EM CRISTO,\nTERÁS PLENA PAZ, SALVAÇÃO.\n\n<coro tipo=''2X''>\n''VINDE A MIM, CANSADOS, \nSOBRECARREGADOS, E EU VOS ALIVIAREI;\nVINDE A MIM, ENTREGAI O VOSSO CORAÇÃO, \nE VIDA ETERNA VOS DAREI.''\n<final>''E VIDA ETERNA VOS DAREI.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (303, 'SE NÃO PUDERES MAIS', 'SE NÃO PUDERES MAIS', 'SE NÃO PUDERES MAIS\nSENTIR O TOQUE DO SENHOR JESUS,\nÉ PORQUE TUA ALMA NÃO SE ABRIU,\nTEU CORAÇÃO NÃO SENTIU\nA PRESENÇA DO SENHOR JESUS.\n\nCORO \nSE HOJE OUVIRDES \nA SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES A JESUS.\n\nINSTRUMENTOS\n\nQUANDO A LUTA SE TRAVAR, \nDO CÉU DEUS OUVIRÁ E ENVIARÁ \nUM ANJO PRA TE LIVRAR;\nCONFIA SOMENTE NO SENHOR, \nO MESMO DEUS DE ONTEM \nE HOJE JAMAIS TE ABANDONARÁ.\n\nCORO (2X)\nSE HOJE OUVIRDES \nA SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES A JESUS.', 'SE NÃO PUDERES MAIS\nSENTIR O TOQUE DO SENHOR JESUS,\nÉ PORQUE TUA ALMA NÃO SE ABRIU,\nTEU CORAÇÃO NÃO SENTIU\nA PRESENÇA DO SENHOR JESUS.\n\n<coro>\nSE HOJE OUVIRDES \nA SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES A JESUS.\n<instrumentos>\n\n\nQUANDO A LUTA SE TRAVAR, \nDO CÉU DEUS OUVIRÁ E ENVIARÁ \nUM ANJO PRA TE LIVRAR;\nCONFIA SOMENTE NO SENHOR, \nO MESMO DEUS DE ONTEM \nE HOJE JAMAIS TE ABANDONARÁ.\n\n<coro tipo=''2X''>\nSE HOJE OUVIRDES \nA SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES A JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (304, 'BASTA QUE ME TOQUES, SENHOR', 'BASTA QUE ME TOQUES, SENHOR', 'BASTA QUE ME TOQUES, SENHOR,\nE MINH''ALMA PROVADA SERÁ.\n\nSE A NOITE ESCURA ESTÁ,\nTUA LUZ ME GUIARÁ,\nBASTA QUE ME TOQUES, SENHOR.', 'BASTA QUE ME TOQUES, SENHOR,<bis>\nE MINH''ALMA PROVADA SERÁ.<bis>\n\nSE A NOITE ESCURA ESTÁ,\nTUA LUZ ME GUIARÁ,\nBASTA QUE ME TOQUES, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (305, 'O SENHOR É A MINHA LUZ', 'O SENHOR É A MINHA LUZ', 'O SENHOR É A MINHA LUZ, A MINHA SALVAÇÃO, \nA QUEM TEMEREI, A QUEM TEMEREI?\nO SENHOR É O MEU REFÚGIO E PAZ,\nA QUEM ENTÃO EU PRECISO TEMER?\nO SENHOR É A MINHA LUZ, A MINHA SALVAÇÃO,\nA QUEM TEMEREI, A QUEM TEMEREI?', 'O SENHOR É A MINHA LUZ, A MINHA SALVAÇÃO, <bis>\nA QUEM TEMEREI, A QUEM TEMEREI?<bis>\nO SENHOR É O MEU REFÚGIO E PAZ,\nA QUEM ENTÃO EU PRECISO TEMER?\nO SENHOR É A MINHA LUZ, A MINHA SALVAÇÃO,\nA QUEM TEMEREI, A QUEM TEMEREI?', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (306, 'MEDO TENS QUE O TENTADOR TE VÁ VENCER?', 'MEDO TENS QUE O TENTADOR TE VÁ VENCER?', 'MEDO TENS QUE O TENTADOR TE VÁ VENCER?\nLUZ TE FALTA E ONDE ESTÁS NÃO PODES VER?\nABRE O CORAÇÃO E DEIXA CRISTO ENTRAR \nE O SOL EM TI RAIAR.\n\nCORO\nDEIXA A LUZ DO CÉU ENTRAR,\nDEIXA O SOL EM TI NASCER;\nABRE O CORAÇÃO E DEIXA \nCRISTO ENTRAR E O SOL EM TI NASCER.\n\nFRACA ESTÁ A TUA FÉ NO SALVADOR?\nDEUS NÃO OUVE AS TUAS PRECES COM FAVOR?\nABRE O CORAÇÃO E DEIXA CRISTO ENTRAR \nE O SOL EM TI RAIAR.\n\nCORO\nDEIXA A LUZ DO CÉU ENTRAR,\nDEIXA O SOL EM TI NASCER;\nABRE O CORAÇÃO E DEIXA \nCRISTO ENTRAR E O SOL EM TI NASCER.\n\nQUERES IR ANDANDO ALEGRE PARA O CÉU,\nIGNORANDO TODO O NEGRO E DENSO VÉU?\nABRE O CORAÇÃO E DEIXA CRISTO ENTRAR\nE O SOL EM TI RAIAR.\n\nCORO\nDEIXA A LUZ DO CÉU ENTRAR,\nDEIXA O SOL EM TI NASCER;\nABRE O CORAÇÃO E DEIXA \nCRISTO ENTRAR E O SOL EM TI NASCER.', 'MEDO TENS QUE O TENTADOR TE VÁ VENCER?\nLUZ TE FALTA E ONDE ESTÁS NÃO PODES VER?\nABRE O CORAÇÃO E DEIXA CRISTO ENTRAR \nE O SOL EM TI RAIAR.\n\n<coro>\nDEIXA A LUZ DO CÉU ENTRAR,\nDEIXA O SOL EM TI NASCER;\nABRE O CORAÇÃO E DEIXA \nCRISTO ENTRAR E O SOL EM TI NASCER.\n\nFRACA ESTÁ A TUA FÉ NO SALVADOR?\nDEUS NÃO OUVE AS TUAS PRECES COM FAVOR?\nABRE O CORAÇÃO E DEIXA CRISTO ENTRAR \nE O SOL EM TI RAIAR.\n\n<coro>\nDEIXA A LUZ DO CÉU ENTRAR,\nDEIXA O SOL EM TI NASCER;\nABRE O CORAÇÃO E DEIXA \nCRISTO ENTRAR E O SOL EM TI NASCER.\n\nQUERES IR ANDANDO ALEGRE PARA O CÉU,\nIGNORANDO TODO O NEGRO E DENSO VÉU?\nABRE O CORAÇÃO E DEIXA CRISTO ENTRAR\nE O SOL EM TI RAIAR.\n\n<coro>\nDEIXA A LUZ DO CÉU ENTRAR,\nDEIXA O SOL EM TI NASCER;\nABRE O CORAÇÃO E DEIXA \nCRISTO ENTRAR E O SOL EM TI NASCER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (307, 'PELO VALE ESCURO SEGUIREI JESUS', 'PELO VALE ESCURO SEGUIREI JESUS', 'PELO VALE ESCURO SEGUIREI JESUS,\nMAS POR TI SEGURO, VENDO A TUA LUZ;\nMEUS PASSOS INCERTOS TU DIRIGIRÁS\nE AO SENTIR-TE PERTO NUNCA PERCO A PAZ.\n\nCORO\nBREVE A NOITE DESCE, NOITE DE EMAÚS,\nE MEU SER CARECE DE TE VER, JESUS,\nCOMPANHEIRO AMIGO, \nAO MEU LADO VEM FICA, \nÓ DEUS, COMIGO, INFINITO BEM.\n\nOS ESPINHOS, TANTOS, \nQUE VEM NOS SANGRAR \nSÃO REMÉDIOS SANTOS PARA NOS CURAR;\nONDE EXISTE A GRAÇA DO BONDOSO DEUS \nTUDO O QUE SE PASSA NOS CONDUZ AOS CÉUS.\n\nCORO\nBREVE A NOITE DESCE, NOITE DE EMAÚS,\nE MEU SER CARECE DE TE VER, JESUS,\nCOMPANHEIRO AMIGO, \nAO MEU LADO VEM FICA, \nÓ DEUS, COMIGO, INFINITO BEM.\n\nNÃO HÁ DOR QUE SEJA SEM \nDIVINO FIM, FAZE, Ó DEUS,\nQUE A IGREJA COMPREENDA ASSIM;\nE, APESAR DAS TREVAS, POSSA VER, SENHOR, \nQUE TU MESMO A LEVAS COM IMENSO AMOR.\n\nCORO\nBREVE A NOITE DESCE, NOITE DE EMAÚS,\nE MEU SER CARECE DE TE VER, JESUS,\nCOMPANHEIRO AMIGO, \nAO MEU LADO VEM FICA, \nÓ DEUS, COMIGO, INFINITO BEM.', 'PELO VALE ESCURO SEGUIREI JESUS,\nMAS POR TI SEGURO, VENDO A TUA LUZ;\nMEUS PASSOS INCERTOS TU DIRIGIRÁS\nE AO SENTIR-TE PERTO NUNCA PERCO A PAZ.\n\n<coro>\nBREVE A NOITE DESCE, NOITE DE EMAÚS,\nE MEU SER CARECE DE TE VER, JESUS,\nCOMPANHEIRO AMIGO, \nAO MEU LADO VEM FICA, \nÓ DEUS, COMIGO, INFINITO BEM.\n\nOS ESPINHOS, TANTOS, \nQUE VEM NOS SANGRAR \nSÃO REMÉDIOS SANTOS PARA NOS CURAR;\nONDE EXISTE A GRAÇA DO BONDOSO DEUS \nTUDO O QUE SE PASSA NOS CONDUZ AOS CÉUS.\n\n<coro>\nBREVE A NOITE DESCE, NOITE DE EMAÚS,\nE MEU SER CARECE DE TE VER, JESUS,\nCOMPANHEIRO AMIGO, \nAO MEU LADO VEM FICA, \nÓ DEUS, COMIGO, INFINITO BEM.\n\nNÃO HÁ DOR QUE SEJA SEM \nDIVINO FIM, FAZE, Ó DEUS,\nQUE A IGREJA COMPREENDA ASSIM;\nE, APESAR DAS TREVAS, POSSA VER, SENHOR, \nQUE TU MESMO A LEVAS COM IMENSO AMOR.\n\n<coro>\nBREVE A NOITE DESCE, NOITE DE EMAÚS,\nE MEU SER CARECE DE TE VER, JESUS,\nCOMPANHEIRO AMIGO, \nAO MEU LADO VEM FICA, \nÓ DEUS, COMIGO, INFINITO BEM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (308, 'PROFUNDOS VALES EU TEREI DE PASSAR', 'PROFUNDOS VALES EU TEREI DE PASSAR', 'PROFUNDOS VALES EU TEREI DE PASSAR\nE MUITAS LUTAS EU TEREI DE VENCER,\nMAS SEI QUE SÓ EU NÃO ESTOU,\nCOMIGO ESTÁS AO MEU REDOR,\nA TUA GRAÇA ME SATISFAZ.\n\nSE UM DIA, ACASO, TRISTE EU ME ENCONTRAR, \nSE SOLITÁRIO NO DESERTO A CAMINHAR, \nENTÃO ALI ME FALARÁS\nE A TUA MÃO ME ESTENDERÁS;\nMOSTRAR-ME-ÁS A CELESTE MANSÃO.\n\nA TUA GRAÇA ME SUSTERÁ POIS FRACO SOU, \nSEM TI NÃO POSSO CAMINHAR;\nREVELA-ME O TEU AMOR, COM \nTUA MÃO VEM ME GUIAR POIS \nJUNTO A TI SEMPRE QUERO ESTAR.', 'PROFUNDOS VALES EU TEREI DE PASSAR\nE MUITAS LUTAS EU TEREI DE VENCER,\nMAS SEI QUE SÓ EU NÃO ESTOU,\nCOMIGO ESTÁS AO MEU REDOR,\nA TUA GRAÇA ME SATISFAZ.\n\nSE UM DIA, ACASO, TRISTE EU ME ENCONTRAR, \nSE SOLITÁRIO NO DESERTO A CAMINHAR, \nENTÃO ALI ME FALARÁS\nE A TUA MÃO ME ESTENDERÁS;\nMOSTRAR-ME-ÁS A CELESTE MANSÃO.\n\nA TUA GRAÇA ME SUSTERÁ POIS FRACO SOU, \nSEM TI NÃO POSSO CAMINHAR;\nREVELA-ME O TEU AMOR, COM <bis>\nTUA MÃO VEM ME GUIAR POIS <bis>\nJUNTO A TI SEMPRE QUERO ESTAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (309, 'OH! POR QUE DUVIDAR?', 'OH! POR QUE DUVIDAR?', 'OH! POR QUE DUVIDAR SOBRE AS ONDAS DO MAR\nQUANDO CRISTO CAMINHO ABRIU?\nQUANDO FORÇADO ÉS CONTRA AS ONDAS LUTAR,\nSEU AMOR A TI QUER REVELAR.\n\nCORO\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.\n\nTREVAS VEM TE ASSUSTAR,\nTEMPESTADES NO MAR?\nDA MONTANHA O MESTRE TE VÊ,\nE NA TRIBULAÇÃO ELE VEM SOCORRER,\nSUA MÃO BEM TE PODE SUSTER.\n\nCORO\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.\n\nPODES TU RECORDAR, MARAVILHAS SEM PAR?\nNO DESERTO AO POVO FARTOU;\nE O MESMO PODER ELE SEMPRE TERÁ\nPOIS NÃO MUDA E NÃO FALHARÁ.\n\nCORO\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.\n\nQUANDO PEDES MAIS FÉ, ELE OUVE, \nOH! CRÊ! MESMO SENDO EM TRIBULAÇÃO;\nQUANDO A MÃO DE PODER \nO TEU EGO TIRAR SOBRE AS ONDAS \nPODERÁS ANDAR.\n\nCORO\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.', 'OH! POR QUE DUVIDAR SOBRE AS ONDAS DO MAR\nQUANDO CRISTO CAMINHO ABRIU?\nQUANDO FORÇADO ÉS CONTRA AS ONDAS LUTAR,\nSEU AMOR A TI QUER REVELAR.\n\n<coro>\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.\n\nTREVAS VEM TE ASSUSTAR,\nTEMPESTADES NO MAR?\nDA MONTANHA O MESTRE TE VÊ,\nE NA TRIBULAÇÃO ELE VEM SOCORRER,\nSUA MÃO BEM TE PODE SUSTER.\n\n<coro>\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.\n\nPODES TU RECORDAR, MARAVILHAS SEM PAR?\nNO DESERTO AO POVO FARTOU;\nE O MESMO PODER ELE SEMPRE TERÁ\nPOIS NÃO MUDA E NÃO FALHARÁ.\n\n<coro>\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.\n\nQUANDO PEDES MAIS FÉ, ELE OUVE, \nOH! CRÊ! MESMO SENDO EM TRIBULAÇÃO;\nQUANDO A MÃO DE PODER \nO TEU EGO TIRAR SOBRE AS ONDAS \nPODERÁS ANDAR.\n\n<coro>\nSOLTA O CABO DA NAU,\nTOMA O REMO NAS MÃOS\nE NAVEGA COM FÉ EM JESUS;\nE ENTÃO TU VERÁS QUE BONANÇA SE FAZ\nPOIS COM ELE SEGURO SERÁS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (310, 'MESTRE O MAR SE REVOLTA', 'MESTRE O MAR SE REVOLTA', 'MESTRE, O MAR SE REVOLTA,\nAS ONDAS NOS DÃO PAVOR!\nO CÉU SE REVESTE DE TREVAS,\nNÃO TEMOS UM SALVADOR!\nNÃO SE TE DÁ QUE MORRAMOS?\nPODES ASSIM DORMIR?\nSE A CADA MOMENTO NOS VEMOS\nJÁ PRESTES A SUBMERGIR?\n\nCORO\n''AS ONDAS ATENDEM AO MEU MANDAR: SOSSEGAI!''\nSEJA O ENCAPELADO MAR, A IRA DOS HOMENS, \nO GÊNIO DO MAL, TAIS ÁGUAS NÃO PODEM \nA NAU TRAGAR QUE LEVA O MESTRE DO CÉU E MAR!\n''POIS TODOS OUVEM O MEU MANDAR:\nSOSSEGAI! SOSSEGAI!\nCONVOSCO ESTOU \nPARA VOS SALVAR: SOSSEGAI!''\n\nMESTRE, TÃO GRANDE TRISTEZA\nME QUER HOJE CONSUMIR!\nE A DOR QUE PERTURBA MINH''ALMA\nTE IMPLORA: VEM ME ACUDIR!\nDE ONDAS DO MAL QUE ME ENCOBREM\nQUEM ME FARÁ SAIR?\nPEREÇO, PEREÇO, Ó MESTRE,\nTE ROGO, VEM ME ACUDIR!\n\nCORO\n''AS ONDAS ATENDEM AO MEU MANDAR: SOSSEGAI!''\nSEJA O ENCAPELADO MAR, A IRA DOS HOMENS, \nO GÊNIO DO MAL, TAIS ÁGUAS NÃO PODEM \nA NAU TRAGAR QUE LEVA O MESTRE DO CÉU E MAR!\n''POIS TODOS OUVEM O MEU MANDAR:\nSOSSEGAI! SOSSEGAI!\nCONVOSCO ESTOU \nPARA VOS SALVAR: SOSSEGAI!''\n\nMESTRE, CHEGOU A BONANÇA,\nEM PAZ VEJO O CÉU E O MAR,\nO MEU CORAÇÃO GOZA CALMA\nQUE NÃO PODERÁ FINDAR;\nFICA COMIGO, Ó MESTRE, \nDONO DA TERRA E CÉU,\nE ASSIM CHEGAREI BEM SEGURO,\nAO PORTO, DESTINO MEU.\n\nCORO\n''AS ONDAS ATENDEM AO MEU MANDAR: SOSSEGAI!''\nSEJA O ENCAPELADO MAR, A IRA DOS HOMENS, \nO GÊNIO DO MAL, TAIS ÁGUAS NÃO PODEM \nA NAU TRAGAR QUE LEVA O MESTRE DO CÉU E MAR!\n''POIS TODOS OUVEM O MEU MANDAR:\nSOSSEGAI! SOSSEGAI!\nCONVOSCO ESTOU \nPARA VOS SALVAR: SOSSEGAI!''', 'MESTRE, O MAR SE REVOLTA,\nAS ONDAS NOS DÃO PAVOR!\nO CÉU SE REVESTE DE TREVAS,\nNÃO TEMOS UM SALVADOR!\nNÃO SE TE DÁ QUE MORRAMOS?\nPODES ASSIM DORMIR?\nSE A CADA MOMENTO NOS VEMOS\nJÁ PRESTES A SUBMERGIR?\n\n<coro>\n''AS ONDAS ATENDEM AO MEU MANDAR: SOSSEGAI!''\nSEJA O ENCAPELADO MAR, A IRA DOS HOMENS, \nO GÊNIO DO MAL, TAIS ÁGUAS NÃO PODEM \nA NAU TRAGAR QUE LEVA O MESTRE DO CÉU E MAR!\n''POIS TODOS OUVEM O MEU MANDAR:\nSOSSEGAI! SOSSEGAI!\nCONVOSCO ESTOU \nPARA VOS SALVAR: SOSSEGAI!''\n\nMESTRE, TÃO GRANDE TRISTEZA\nME QUER HOJE CONSUMIR!\nE A DOR QUE PERTURBA MINH''ALMA\nTE IMPLORA: VEM ME ACUDIR!\nDE ONDAS DO MAL QUE ME ENCOBREM\nQUEM ME FARÁ SAIR?\nPEREÇO, PEREÇO, Ó MESTRE,\nTE ROGO, VEM ME ACUDIR!\n\n<coro>\n''AS ONDAS ATENDEM AO MEU MANDAR: SOSSEGAI!''\nSEJA O ENCAPELADO MAR, A IRA DOS HOMENS, \nO GÊNIO DO MAL, TAIS ÁGUAS NÃO PODEM \nA NAU TRAGAR QUE LEVA O MESTRE DO CÉU E MAR!\n''POIS TODOS OUVEM O MEU MANDAR:\nSOSSEGAI! SOSSEGAI!\nCONVOSCO ESTOU \nPARA VOS SALVAR: SOSSEGAI!''\n\nMESTRE, CHEGOU A BONANÇA,\nEM PAZ VEJO O CÉU E O MAR,\nO MEU CORAÇÃO GOZA CALMA\nQUE NÃO PODERÁ FINDAR;\nFICA COMIGO, Ó MESTRE, \nDONO DA TERRA E CÉU,\nE ASSIM CHEGAREI BEM SEGURO,\nAO PORTO, DESTINO MEU.\n\n<coro>\n''AS ONDAS ATENDEM AO MEU MANDAR: SOSSEGAI!''\nSEJA O ENCAPELADO MAR, A IRA DOS HOMENS, \nO GÊNIO DO MAL, TAIS ÁGUAS NÃO PODEM \nA NAU TRAGAR QUE LEVA O MESTRE DO CÉU E MAR!\n''POIS TODOS OUVEM O MEU MANDAR:\nSOSSEGAI! SOSSEGAI!\nCONVOSCO ESTOU \nPARA VOS SALVAR: SOSSEGAI!''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (311, 'SÓ UMA VOZ ME BASTA', 'SÓ UMA VOZ ME BASTA', 'SÓ UMA VOZ ME BASTA\nNA HORA DA TRISTEZA E DOR;\nSÓ UMA VOZ ME CONSOLA,\nÉ A VOZ DO MEU SENHOR.\n\nELE TIRA A ESCURIDÃO,\nELE FAZ NASCER A LUZ, \nELE DÁ A SOLUÇÃO\nREVELADA EM JESUS.\n\nSÓ UMA VOZ ME BASTA\nNA HORA DA TRISTEZA E DOR;\nSÓ UMA VOZ ME CONSOLA,\nÉ A VOZ DO MEU SENHOR.\n\nELE TIRA A ESCURIDÃO, \nELE FAZ NASCER A LUZ,\nELE DÁ A SOLUÇÃO\nREVELADA EM JESUS.', 'SÓ UMA VOZ ME BASTA\nNA HORA DA TRISTEZA E DOR;\nSÓ UMA VOZ ME CONSOLA,\nÉ A VOZ DO MEU SENHOR.\n\nELE TIRA A ESCURIDÃO,\nELE FAZ NASCER A LUZ, \nELE DÁ A SOLUÇÃO\nREVELADA EM JESUS.\n\nSÓ UMA VOZ ME BASTA\nNA HORA DA TRISTEZA E DOR;\nSÓ UMA VOZ ME CONSOLA,\nÉ A VOZ DO MEU SENHOR.\n\nELE TIRA A ESCURIDÃO, <bis>\nELE FAZ NASCER A LUZ,<bis>\nELE DÁ A SOLUÇÃO<bis>\nREVELADA EM JESUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (312, 'SE, DA VIDA, AS VAGAS PROCELOSAS SÃO', 'SE, DA VIDA, AS VAGAS PROCELOSAS SÃO', 'SE, DA VIDA, AS VAGAS PROCELOSAS SÃO,\nSE, COM DESALENTO, JULGAS TUDO VÃO,\nCONTA AS MUITAS BÊNÇÃOS, DIZE-AS DE UMA VEZ,\nVERÁS, COM SURPRESA, QUANTO DEUS JÁ FEZ.\n\nCORO\nCONTA AS BÊNÇÃOS, CONTA QUANTAS \nSÃO RECEBIDAS DA DIVINA MÃO;\nVEM DIZÊ-LAS, TODAS DE UMA VEZ,\nE VERÁS SURPRESO QUANTO DEUS JÁ FEZ.\n\nTENS ACASO MÁGOA? TRISTE É O TEU LIDAR?\nÉ A CRUZ PESADA QUE TENS DE LEVAR?\nCONTA AS MUITAS BÊNÇÃOS, NÃO DUVIDARÁS,\nE EM CANTO ALEGRE OS DIAS PASSARÁS.\n\nCORO\nCONTA AS BÊNÇÃOS, CONTA QUANTAS \nSÃO RECEBIDAS DA DIVINA MÃO;\nVEM DIZÊ-LAS, TODAS DE UMA VEZ,\nE VERÁS SURPRESO QUANTO DEUS JÁ FEZ.\n\nQUANDO VIRES OUTROS COM SEU OURO E BENS, \nLEMBRA QUE TESOUROS PROMETIDOS TENS;\nNUNCA OS BENS DA TERRA PODERÃO COMPRAR\nA MANSÃO CELESTE QUE VAIS HABITAR.\n\nCORO\nCONTA AS BÊNÇÃOS, CONTA QUANTAS \nSÃO RECEBIDAS DA DIVINA MÃO;\nVEM DIZÊ-LAS, TODAS DE UMA VEZ,\nE VERÁS SURPRESO QUANTO DEUS JÁ FEZ.', 'SE, DA VIDA, AS VAGAS PROCELOSAS SÃO,\nSE, COM DESALENTO, JULGAS TUDO VÃO,\nCONTA AS MUITAS BÊNÇÃOS, DIZE-AS DE UMA VEZ,\nVERÁS, COM SURPRESA, QUANTO DEUS JÁ FEZ.\n\n<coro>\nCONTA AS BÊNÇÃOS, CONTA QUANTAS \nSÃO RECEBIDAS DA DIVINA MÃO;\nVEM DIZÊ-LAS, TODAS DE UMA VEZ,\nE VERÁS SURPRESO QUANTO DEUS JÁ FEZ.\n\nTENS ACASO MÁGOA? TRISTE É O TEU LIDAR?\nÉ A CRUZ PESADA QUE TENS DE LEVAR?\nCONTA AS MUITAS BÊNÇÃOS, NÃO DUVIDARÁS,\nE EM CANTO ALEGRE OS DIAS PASSARÁS.\n\n<coro>\nCONTA AS BÊNÇÃOS, CONTA QUANTAS \nSÃO RECEBIDAS DA DIVINA MÃO;\nVEM DIZÊ-LAS, TODAS DE UMA VEZ,\nE VERÁS SURPRESO QUANTO DEUS JÁ FEZ.\n\nQUANDO VIRES OUTROS COM SEU OURO E BENS, \nLEMBRA QUE TESOUROS PROMETIDOS TENS;\nNUNCA OS BENS DA TERRA PODERÃO COMPRAR\nA MANSÃO CELESTE QUE VAIS HABITAR.\n\n<coro>\nCONTA AS BÊNÇÃOS, CONTA QUANTAS \nSÃO RECEBIDAS DA DIVINA MÃO;\nVEM DIZÊ-LAS, TODAS DE UMA VEZ,\nE VERÁS SURPRESO QUANTO DEUS JÁ FEZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (313, 'O QUE HABITA NO ABRIGO DE DEUS', 'O QUE HABITA NO ABRIGO DE DEUS', 'O QUE HABITA NO ABRIGO DE DEUS \nMORARÁ SOB SOMBRAS DE AMOR,\nSOBRE ELE NÃO VIRÁ NENHUM MAL, \nEM SUAS ASAS FELIZ VIVERÁ.\n\nOH! EU QUERO HABITAR NO ABRIGO DE DEUS, \nSÓ ALI ACHAREI PAZ E PROFUNDO AMOR;\nMEU DESEJO É COM ELE COMUNHÃO \nDESFRUTAR E PRA SEMPRE O SEU NOME LOUVAR.', 'O QUE HABITA NO ABRIGO DE DEUS \nMORARÁ SOB SOMBRAS DE AMOR,\nSOBRE ELE NÃO VIRÁ NENHUM MAL, \nEM SUAS ASAS FELIZ VIVERÁ.\n\nOH! EU QUERO HABITAR NO ABRIGO DE DEUS, \nSÓ ALI ACHAREI PAZ E PROFUNDO AMOR;\nMEU DESEJO É COM ELE COMUNHÃO \nDESFRUTAR E PRA SEMPRE O SEU NOME LOUVAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (314, 'QUE IMPORTA', 'QUE IMPORTA', 'QUE IMPORTA SE O SOL NÃO BRILHAR,\nQUE IMPORTA SE DAS ESTRELAS O BRILHO CESSAR;\nO QUE IMPORTA PARA MIM, É DE JESUS NÃO ESQUECER;\nELE É A RAZÃO DE TODO O MEU VIVER.\n\nÉ JESUS MINHA PAZ, É JESUS MINHA FORÇA,\nÉ JESUS MEU AMIGO, É JESUS A MINHA ALEGRIA,\nÉ JESUS MEU COMPANHEIRO,\nÉ JESUS MEU AMOR VERDADEIRO,\nELE É A RAZÃO DE TODO O MEU VIVER.', 'QUE IMPORTA SE O SOL NÃO BRILHAR,\nQUE IMPORTA SE DAS ESTRELAS O BRILHO CESSAR;\nO QUE IMPORTA PARA MIM, É DE JESUS NÃO ESQUECER;\nELE É A RAZÃO DE TODO O MEU VIVER.\n\nÉ JESUS MINHA PAZ, É JESUS MINHA FORÇA,\nÉ JESUS MEU AMIGO, É JESUS A MINHA ALEGRIA,\nÉ JESUS MEU COMPANHEIRO,\nÉ JESUS MEU AMOR VERDADEIRO,\nELE É A RAZÃO DE TODO O MEU VIVER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (315, 'SE EM PROFUNDO ABISMO TE ENCONTRAS', 'SE EM PROFUNDO ABISMO TE ENCONTRAS', 'SE EM PROFUNDO ABISMO TE ENCONTRAS \nE CAMINHAS SEM TERES DIREÇÃO,\nNA ESTRADA NÃO TENS O AUXÍLIO,\nNÃO ENCONTRAS QUEM TE DÊ A MÃO;\nSE A TRISTEZA SEMPRE TE DOMINA,\nSE O TEU FARDO É PESADO, ENTÃO,\nMESMO QUE TUDO VENHA A PERECER,\nNÃO, NÃO TEMAS, DEUS TE DÁ A MÃO.\n\nCORO\nDEUS SEGURA EM TUA MÃO (BIS)\nMESMO QUE, COM LUTAS, NA ESTRADA,\nDEUS SEGURA EM TUA MÃO.\n\nINSTRUMENTOS\n\nSE O SOL PARA TI JÁ NÃO BRILHA\nE OS SEUS RAIOS NÃO REFLETEM MAIS;\nSE O AMOR EM TUA VIDA NÃO HÁ\nE CAMINHAS EM BUSCA DE PAZ;\nSE A TRISTEZA SEMPRE TE DOMINA,\nSE O TEU FARDO É PESADO, ENTÃO,\nMESMO QUE TUDO VENHA A PERECER,\nNÃO, NÃO TEMAS, DEUS TE DÁ A MÃO.\n\nCORO\nDEUS SEGURA EM TUA MÃO (BIS)\nMESMO QUE, COM LUTAS, NA ESTRADA,\nDEUS SEGURA EM TUA MÃO.', 'SE EM PROFUNDO ABISMO TE ENCONTRAS \nE CAMINHAS SEM TERES DIREÇÃO,\nNA ESTRADA NÃO TENS O AUXÍLIO,\nNÃO ENCONTRAS QUEM TE DÊ A MÃO;\nSE A TRISTEZA SEMPRE TE DOMINA,\nSE O TEU FARDO É PESADO, ENTÃO,\nMESMO QUE TUDO VENHA A PERECER,\nNÃO, NÃO TEMAS, DEUS TE DÁ A MÃO.\n\n<coro>\nDEUS SEGURA EM TUA MÃO <bis>\nMESMO QUE, COM LUTAS, NA ESTRADA,<bis>\nDEUS SEGURA EM TUA MÃO.<bis>\n<instrumentos><bis>\n\n\nSE O SOL PARA TI JÁ NÃO BRILHA\nE OS SEUS RAIOS NÃO REFLETEM MAIS;\nSE O AMOR EM TUA VIDA NÃO HÁ\nE CAMINHAS EM BUSCA DE PAZ;\nSE A TRISTEZA SEMPRE TE DOMINA,\nSE O TEU FARDO É PESADO, ENTÃO,\nMESMO QUE TUDO VENHA A PERECER,\nNÃO, NÃO TEMAS, DEUS TE DÁ A MÃO.\n\n<coro>\nDEUS SEGURA EM TUA MÃO <bis>\nMESMO QUE, COM LUTAS, NA ESTRADA,<bis>\nDEUS SEGURA EM TUA MÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (316, 'A VIDA NO MUNDO É CRUEL', 'A VIDA NO MUNDO É CRUEL', 'A VIDA NO MUNDO É CRUEL,\nTORMENTOS E LUTAS SEM FIM;\nCAMINHO ALMEJANDO O CÉU;\nJESUS, TU TE LEMBRAS DE MIM!\n\nCORO\nJESUS, TU TE LEMBRAS DE MIM! (BIS)\nNA VIDA, NA MORTE E NA DOR:\nJESUS, TU TE LEMBRAS DE MIM!\n\nNAVEGANDO VAI MINHA NAU\nNO MAR DESTA VIDA AQUI;\nABRIGA-ME NO TEMPORAL;\nJESUS, TU TE LEMBRAS DE MIM!\n\nCORO\nJESUS, TU TE LEMBRAS DE MIM! (BIS)\nNA VIDA, NA MORTE E NA DOR:\nJESUS, TU TE LEMBRAS DE MIM!\n\nJESUS, O QUE HEI DE FAZER\nSE O MUNDO ESTÁ CONTRA MIM?\nENVIA-ME O TEU PODER;\nJESUS, TU TE LEMBRAS DE MIM!', 'A VIDA NO MUNDO É CRUEL,\nTORMENTOS E LUTAS SEM FIM;\nCAMINHO ALMEJANDO O CÉU;\nJESUS, TU TE LEMBRAS DE MIM!\n\n<coro>\nJESUS, TU TE LEMBRAS DE MIM! <bis>\nNA VIDA, NA MORTE E NA DOR:\nJESUS, TU TE LEMBRAS DE MIM!\n\nNAVEGANDO VAI MINHA NAU\nNO MAR DESTA VIDA AQUI;\nABRIGA-ME NO TEMPORAL;\nJESUS, TU TE LEMBRAS DE MIM!\n\n<coro>\nJESUS, TU TE LEMBRAS DE MIM! <bis>\nNA VIDA, NA MORTE E NA DOR:\nJESUS, TU TE LEMBRAS DE MIM!\n\nJESUS, O QUE HEI DE FAZER\nSE O MUNDO ESTÁ CONTRA MIM?\nENVIA-ME O TEU PODER;\nJESUS, TU TE LEMBRAS DE MIM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (317, 'QUANDO VEM NOS OLHOS UMA LÁGRIMA', 'QUANDO VEM NOS OLHOS UMA LÁGRIMA', 'QUANDO VEM NOS OLHOS UMA LÁGRIMA,\nQUANDO NÃO CONSIGO MAIS SORRIR,\nDÁ-ME, MEU SENHOR, O TEU OLHAR,\nDÁ-ME, MEU SENHOR, O TEU PERDÃO.\n\nCORO (2X)\nMARANATA, ORA VEM, MEU SENHOR,\nMARANATA, VEM VENCER A MINHA DOR.\n\nSINTO ENTÃO A TUA MÃO ME TOCAR\nAPLACANDO O FUROR DA TRIBULAÇÃO,\nMAIS UM POUCO E NÃO MAIS CHORAREI,\nMAIS UM POUCO E NAS NUVENS TE VEREI.', 'QUANDO VEM NOS OLHOS UMA LÁGRIMA,\nQUANDO NÃO CONSIGO MAIS SORRIR,\nDÁ-ME, MEU SENHOR, O TEU OLHAR,\nDÁ-ME, MEU SENHOR, O TEU PERDÃO.\n\n<coro tipo=''2X''>\nMARANATA, ORA VEM, MEU SENHOR,\nMARANATA, VEM VENCER A MINHA DOR.\n\nSINTO ENTÃO A TUA MÃO ME TOCAR\nAPLACANDO O FUROR DA TRIBULAÇÃO,\nMAIS UM POUCO E NÃO MAIS CHORAREI,\nMAIS UM POUCO E NAS NUVENS TE VEREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (318, 'QUANDO A ANGÚSTIA VEM', 'QUANDO A ANGÚSTIA VEM', 'QUANDO A ANGÚSTIA VEM E NOS OLHOS LÁGRIMAS, PARECE, ENTÃO, QUE TU NÃO PODES SUPORTAR;\nJESUS TE AJUDARÁ E TUDO ELE VERÁ,\nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.\n\nCORO\nDEUS VÊ NOS OLHOS O AFLITO CORAÇÃO,\nÉ O SENHOR QUEM VÊ AS LÁGRIMAS EM ORAÇÃO; \nCOM O HOMEM ELE VIVERÁ,\nPELAS MÃOS O TOMARÁ.\nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.\n\nQUANDO NÃO PUDERES MAIS SONHO ALGUM \nREALIZAR, E TUDO, ENFIM, DIANTE DE TI \nDESMORONAR, MEU DEUS NÃO TE ESQUECERÁ, \nPROMESSAS CUMPRIRÁ, \nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.\n\nCORO\nDEUS VÊ NOS OLHOS O AFLITO CORAÇÃO,\nÉ O SENHOR QUEM VÊ AS LÁGRIMAS EM ORAÇÃO; \nCOM O HOMEM ELE VIVERÁ,\nPELAS MÃOS O TOMARÁ.\nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.', 'QUANDO A ANGÚSTIA VEM E NOS OLHOS LÁGRIMAS, PARECE, ENTÃO, QUE TU NÃO PODES SUPORTAR;\nJESUS TE AJUDARÁ E TUDO ELE VERÁ,\nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.\n\n<coro>\nDEUS VÊ NOS OLHOS O AFLITO CORAÇÃO,\nÉ O SENHOR QUEM VÊ AS LÁGRIMAS EM ORAÇÃO; \nCOM O HOMEM ELE VIVERÁ,\nPELAS MÃOS O TOMARÁ.\nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.\n\nQUANDO NÃO PUDERES MAIS SONHO ALGUM \nREALIZAR, E TUDO, ENFIM, DIANTE DE TI \nDESMORONAR, MEU DEUS NÃO TE ESQUECERÁ, \nPROMESSAS CUMPRIRÁ, \nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.\n\n<coro>\nDEUS VÊ NOS OLHOS O AFLITO CORAÇÃO,\nÉ O SENHOR QUEM VÊ AS LÁGRIMAS EM ORAÇÃO; \nCOM O HOMEM ELE VIVERÁ,\nPELAS MÃOS O TOMARÁ.\nAS LÁGRIMAS FALAM, DEUS OUVIRÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (319, 'MAIS PERTO QUERO ESTAR', 'MAIS PERTO QUERO ESTAR', 'MAIS PERTO QUERO ESTAR, MEU DEUS DE TI,\nINDA QUE SEJA A DOR QUE ME UNA A TI!\nSEMPRE HEI DE SUPLICAR: MAIS PERTO QUERO ESTAR, \nMAIS PERTO QUERO ESTAR, MEU DEUS, DE TI!\n\nANDANDO TRISTE AQUI, NA SOLIDÃO,\nPAZ E DESCANSO A MIM TEUS BRAÇOS DÃO.\nSEMPRE HEI DE SUPLICAR: MAIS PERTO QUERO ESTAR, \nMAIS PERTO QUERO ESTAR, MEU DEUS, DE TI!\n\nMINH''ALMA CANTARÁ A TI, SENHOR,\nCHEIA DE GRATIDÃO POR TEU AMOR.\nSEMPRE HEI DE SUPLICAR: MAIS PERTO QUERO ESTAR, \nMAIS PERTO QUERO ESTAR, MEU DEUS, DE TI!\n\nE QUANDO CRISTO, ENFIM, ME VIER CHAMAR,\nNOS CÉUS COM O SENHOR IREI MORAR.\nENTÃO ME ALEGRAREI, PERTO DE TI, MEU REI,\nPERTO DE TI, MEU REI, MEU DEUS, DE TI!', 'MAIS PERTO QUERO ESTAR, MEU DEUS DE TI,\nINDA QUE SEJA A DOR QUE ME UNA A TI!\nSEMPRE HEI DE SUPLICAR: MAIS PERTO QUERO ESTAR, \nMAIS PERTO QUERO ESTAR, MEU DEUS, DE TI!\n\nANDANDO TRISTE AQUI, NA SOLIDÃO,\nPAZ E DESCANSO A MIM TEUS BRAÇOS DÃO.\nSEMPRE HEI DE SUPLICAR: MAIS PERTO QUERO ESTAR, \nMAIS PERTO QUERO ESTAR, MEU DEUS, DE TI!\n\nMINH''ALMA CANTARÁ A TI, SENHOR,\nCHEIA DE GRATIDÃO POR TEU AMOR.\nSEMPRE HEI DE SUPLICAR: MAIS PERTO QUERO ESTAR, \nMAIS PERTO QUERO ESTAR, MEU DEUS, DE TI!\n\nE QUANDO CRISTO, ENFIM, ME VIER CHAMAR,\nNOS CÉUS COM O SENHOR IREI MORAR.\nENTÃO ME ALEGRAREI, PERTO DE TI, MEU REI,\nPERTO DE TI, MEU REI, MEU DEUS, DE TI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (320, 'BOM É O SENHOR', 'BOM É O SENHOR', 'BOM É O SENHOR PARA AQUELE QUE O BUSCA \nE QUE ESPERA EM SILÊNCIO A SUA SALVAÇÃO.\n\nCORO \nPORQUE O SENHOR NÃO REJEITARÁ PRA SEMPRE,\nNEM TEM PRAZER NA NOSSA DOR;\nBOM É O SENHOR. \n\nPOIS AINDA QUE ENTRISTEÇA\nUSARÁ DE COMPAIXÃO, \nSEGUNDO A SUA MISERICÓRDIA.\n\nCORO \nPORQUE O SENHOR NÃO REJEITARÁ PRA SEMPRE,\nNEM TEM PRAZER NA NOSSA DOR;\nBOM É O SENHOR (3X)', 'BOM É O SENHOR PARA AQUELE QUE O BUSCA <bis>\nE QUE ESPERA EM SILÊNCIO A SUA SALVAÇÃO.<coro><bis>\nPORQUE O SENHOR NÃO REJEITARÁ PRA SEMPRE,\nNEM TEM PRAZER NA NOSSA DOR;\nBOM É O SENHOR. \n\nPOIS AINDA QUE ENTRISTEÇA<bis>\nUSARÁ DE COMPAIXÃO, <bis>\nSEGUNDO A SUA MISERICÓRDIA.<coro><bis>\nPORQUE O SENHOR NÃO REJEITARÁ PRA SEMPRE,\nNEM TEM PRAZER NA NOSSA DOR;\nBOM É O SENHOR <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (321, 'QUÃO BONDOSO AMIGO É CRISTO', 'QUÃO BONDOSO AMIGO É CRISTO', 'QUÃO BONDOSO AMIGO É CRISTO!\nCARREGOU A NOSSA DOR\nE NOS MANDA QUE LEVEMOS\nOS CUIDADOS AO SENHOR;\nFALTA AO CORAÇÃO DORIDO\nGOZO, PAZ, CONSOLAÇÃO?\nISSO É PORQUE NÃO LEVAMOS\nTUDO A DEUS EM ORAÇÃO.\n\nESTÁS FRACO E CARREGADO\nDE CUIDADOS E TEMOR?\nA JESUS, REFÚGIO ETERNO,\nVAI COM FÉ TEU MAL EXPOR.\nTEUS AMIGOS TE DESPREZAM?\nCONTA-LHE ISSO EM ORAÇÃO\nE COM SEU AMOR TÃO TERNO\nPAZ TERÁS NO CORAÇÃO. \n\nCRISTO É VERDADEIRO AMIGO,\nDISTO PROVA NOS MOSTROU\nQUANDO, PRA LEVAR CONSIGO,\nAO CULPADO, ENCARNOU;\nDERRAMOU SEU SANGUE PURO,\nNOSSA MANCHA PRA LAVAR,\nGOZO EM VIDA E NO FUTURO\nNELE PODEMOS ALCANÇAR.', 'QUÃO BONDOSO AMIGO É CRISTO!\nCARREGOU A NOSSA DOR\nE NOS MANDA QUE LEVEMOS\nOS CUIDADOS AO SENHOR;\nFALTA AO CORAÇÃO DORIDO\nGOZO, PAZ, CONSOLAÇÃO?\nISSO É PORQUE NÃO LEVAMOS\nTUDO A DEUS EM ORAÇÃO.\n\nESTÁS FRACO E CARREGADO\nDE CUIDADOS E TEMOR?\nA JESUS, REFÚGIO ETERNO,\nVAI COM FÉ TEU MAL EXPOR.\nTEUS AMIGOS TE DESPREZAM?\nCONTA-LHE ISSO EM ORAÇÃO\nE COM SEU AMOR TÃO TERNO\nPAZ TERÁS NO CORAÇÃO. \n\nCRISTO É VERDADEIRO AMIGO,\nDISTO PROVA NOS MOSTROU\nQUANDO, PRA LEVAR CONSIGO,\nAO CULPADO, ENCARNOU;\nDERRAMOU SEU SANGUE PURO,\nNOSSA MANCHA PRA LAVAR,\nGOZO EM VIDA E NO FUTURO\nNELE PODEMOS ALCANÇAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (322, 'HÁ UM AMIGO SEMPRE JUNTO', 'HÁ UM AMIGO SEMPRE JUNTO', 'HÁ UM AMIGO SEMPRE JUNTO A MIM,\nHÁ UM AMIGO QUE ME OUVE,\nHÁ UM AMIGO TÃO QUERIDO, SIM,\nPRECIOSO ELE É.\n\nCORO\nQUANDO OUÇO A VOZ DO VENTO,\nQUANDO TODA A AFLIÇÃO ME SOBREVEM, ELE DIZ: \n''ESTOU CONTIGO'', PRECIOSO É JESUS.\n\nSUAS PROMESSAS ELE CUMPRE,\nNÃO HÁ COMO ELE FALHAR;\nMINHA PARTE QUERO EU FAZER,\nPRECIOSO ELE É.', 'HÁ UM AMIGO SEMPRE JUNTO A MIM,\nHÁ UM AMIGO QUE ME OUVE,\nHÁ UM AMIGO TÃO QUERIDO, SIM,\nPRECIOSO ELE É.\n\n<coro>\nQUANDO OUÇO A VOZ DO VENTO,\nQUANDO TODA A AFLIÇÃO ME SOBREVEM, ELE DIZ: \n''ESTOU CONTIGO'', PRECIOSO É JESUS.\n\nSUAS PROMESSAS ELE CUMPRE,\nNÃO HÁ COMO ELE FALHAR;\nMINHA PARTE QUERO EU FAZER,\nPRECIOSO ELE É.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (323, 'DEUS ESTÁ PRESENTE SEMPRE PRONTO A NOS AJUDAR', 'DEUS ESTÁ PRESENTE SEMPRE PRONTO A NOS AJUDAR', 'DEUS ESTÁ PRESENTE SEMPRE PRONTO A NOS AJUDAR, \nCOM SEUS OUVIDOS SEMPRE VOLTADOS A NOS ESCUTAR;\nBUSCA A JESUS PARA O TEU CORAÇÃO ALEGRAR, \nPARA ENCHER TEU CORAÇÃO DE GOZO E PAZ.\n\nCORO\nAGORA SOMOS POVO TRANSFORMADO\nPELA GRAÇA DE CRISTO JESUS,\nPELO SEU GRANDIOSO AMOR,\nSOMOS POVO DE CRISTO JESUS, O SENHOR. \n\nINSTRUMENTOS\n\nESTAMOS CONSCIENTES \nDE SUA SANTA PRESENÇA AQUI,\nCOM SEU PODER E COM GRAÇA ELE VAI OPERAR;\nNÃO FICARÁ QUALQUER LUTA \nOU TRISTEZA AQUI POIS O SENHOR \nNOS LEVARÁ A SENTIR O SEU AMOR.\n\nCORO\nAGORA SOMOS POVO TRANSFORMADO\nPELA GRAÇA DE CRISTO JESUS,\nPELO SEU GRANDIOSO AMOR,\nSOMOS POVO DE CRISTO JESUS, O SENHOR. \n\nFINAL: \nSOMOS POVO DE CRISTO JESUS, O SENHOR.', 'DEUS ESTÁ PRESENTE SEMPRE PRONTO A NOS AJUDAR, \nCOM SEUS OUVIDOS SEMPRE VOLTADOS A NOS ESCUTAR;\nBUSCA A JESUS PARA O TEU CORAÇÃO ALEGRAR, \nPARA ENCHER TEU CORAÇÃO DE GOZO E PAZ.\n\n<coro>\nAGORA SOMOS POVO TRANSFORMADO\nPELA GRAÇA DE CRISTO JESUS,\nPELO SEU GRANDIOSO AMOR,\nSOMOS POVO DE CRISTO JESUS, O SENHOR. \n<instrumentos>\n\n\nESTAMOS CONSCIENTES \nDE SUA SANTA PRESENÇA AQUI,\nCOM SEU PODER E COM GRAÇA ELE VAI OPERAR;\nNÃO FICARÁ QUALQUER LUTA \nOU TRISTEZA AQUI POIS O SENHOR \nNOS LEVARÁ A SENTIR O SEU AMOR.\n\n<coro>\nAGORA SOMOS POVO TRANSFORMADO\nPELA GRAÇA DE CRISTO JESUS,\nPELO SEU GRANDIOSO AMOR,\nSOMOS POVO DE CRISTO JESUS, O SENHOR. \n<final>SOMOS POVO DE CRISTO JESUS, O SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (324, 'EU SOU POBRE E NECESSITADO', 'EU SOU POBRE E NECESSITADO', 'EU SOU POBRE E NECESSITADO\nMAS O SENHOR CUIDA DE MIM;\nEU SOU POBRE E NECESSITADO\nMAS O SENHOR CUIDA DE MIM.\n\nTU ÉS MEU AUXÍLIO \nE O MEU LIBERTADOR!\nNÃO TE DETENHAS, Ó MEU DEUS! (BIS)', 'EU SOU POBRE E NECESSITADO\nMAS O SENHOR CUIDA DE MIM;\nEU SOU POBRE E NECESSITADO\nMAS O SENHOR CUIDA DE MIM.\n\nTU ÉS MEU AUXÍLIO \nE O MEU LIBERTADOR!\nNÃO TE DETENHAS, Ó MEU DEUS! <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (325, 'SE HOJE ESCUTARES', 'SE HOJE ESCUTARES', 'SE HOJE ESCUTARES\nA VOZ MANSA E SUAVE DE DEUS,\nO TEU CORAÇÃO ABRE A ELE SEM HESITAÇÃO.\n\nCORO\nE DIZE: EIS-ME AQUI, SENHOR, COMO ESTOU, \nTÃO NECESSITADO DE TI;\nE PODES CONFIAR, DEUS VAI OPERAR\nMUITO ACIMA DO QUE PODES PENSAR.\n\nINSTRUMENTOS\n\nDEPENDE DE TI ELE AGORA \nEM TUA VIDA ENTRAR;\nESCUTA SUA VOZ E ABRE A PORTA HOJE, \nSEM HESITAR.\n\nCORO\nE DIZE: EIS-ME AQUI, SENHOR, COMO ESTOU, \nTÃO NECESSITADO DE TI;\nE PODES CONFIAR, DEUS VAI OPERAR\nMUITO ACIMA DO QUE PODES PENSAR', 'SE HOJE ESCUTARES\nA VOZ MANSA E SUAVE DE DEUS,\nO TEU CORAÇÃO ABRE A ELE SEM HESITAÇÃO.\n\n<coro>\nE DIZE: EIS-ME AQUI, SENHOR, COMO ESTOU, \nTÃO NECESSITADO DE TI;\nE PODES CONFIAR, DEUS VAI OPERAR\nMUITO ACIMA DO QUE PODES PENSAR.\n<instrumentos>\n\n\nDEPENDE DE TI ELE AGORA \nEM TUA VIDA ENTRAR;\nESCUTA SUA VOZ E ABRE A PORTA HOJE, \nSEM HESITAR.\n\n<coro>\nE DIZE: EIS-ME AQUI, SENHOR, COMO ESTOU, \nTÃO NECESSITADO DE TI;\nE PODES CONFIAR, DEUS VAI OPERAR\nMUITO ACIMA DO QUE PODES PENSAR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (326, 'EU NÃO SABERIA CAMINHAR', 'EU NÃO SABERIA CAMINHAR', 'EU NÃO SABERIA CAMINHAR SEM TI, SENHOR,\nPORQUE TU ÉS O MEU AUXÍLIO E FORTALEZA;\nREFÚGIO NA TRIBULAÇÃO\nQUANDO OS MEUS JOELHOS\nDOBRAM EM ORAÇÃO.\n\nSENHOR, TU ÉS O MEU AUXÍLIO NA TRIBULAÇÃO, \nAMIGO BEM PRESENTE QUE NÃO FALHA;\nTENHO DESEJADO A TUA \nSALVAÇÃO, Ó SENHOR,\nO TEU QUERER É TODO O \nMEU PRAZER.\n\nREFÚGIO NA TRIBULAÇÃO\nQUANDO OS MEUS JOELHOS\nDOBRAM EM ORAÇÃO.', 'EU NÃO SABERIA CAMINHAR SEM TI, SENHOR,\nPORQUE TU ÉS O MEU AUXÍLIO E FORTALEZA;\nREFÚGIO NA TRIBULAÇÃO<bis>\nQUANDO OS MEUS JOELHOS<bis>\nDOBRAM EM ORAÇÃO.<bis>\n\nSENHOR, TU ÉS O MEU AUXÍLIO NA TRIBULAÇÃO, \nAMIGO BEM PRESENTE QUE NÃO FALHA;\nTENHO DESEJADO A TUA <bis>\nSALVAÇÃO, Ó SENHOR,<bis>\nO TEU QUERER É TODO O <bis>\nMEU PRAZER.<bis>\n\nREFÚGIO NA TRIBULAÇÃO<bis>\nQUANDO OS MEUS JOELHOS<bis>\nDOBRAM EM ORAÇÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (327, 'DEUS É CONTIGO', 'DEUS É CONTIGO', 'DEUS É CONTIGO, É SÓ A ELE ORAR,\nDEUS É CONTIGO, DO MAL TE LIVRARÁ;\nMISERICÓRDIA A TI VIRÁ,\nDEUS É CONTIGO, SE A ELE ORAR.\n\nDEUS É CONTIGO, TUDO ELE VÊ DOS CÉUS,\nE TE PROTEGE DOS INIMIGOS TEUS;\nA CADA DIA RENOVA O AMOR,\nDEUS É CONTIGO, ELE É O SENHOR.\n\nDEUS É CONTIGO, TUDO ELE VÊ DOS CÉUS,\nE TE PROTEGE DOS INIMIGOS TEUS;\nA CADA DIA RENOVA O AMOR,\nDEUS É CONTIGO, ELE É O SENHOR.\n\nDEUS É CONTIGO, \nDEUS É CONTIGO ATÉ O FIM.', 'DEUS É CONTIGO, É SÓ A ELE ORAR,\nDEUS É CONTIGO, DO MAL TE LIVRARÁ;\nMISERICÓRDIA A TI VIRÁ,\nDEUS É CONTIGO, SE A ELE ORAR.\n\nDEUS É CONTIGO, TUDO ELE VÊ DOS CÉUS,\nE TE PROTEGE DOS INIMIGOS TEUS;\nA CADA DIA RENOVA O AMOR,\nDEUS É CONTIGO, ELE É O SENHOR.\n\nDEUS É CONTIGO, TUDO ELE VÊ DOS CÉUS,\nE TE PROTEGE DOS INIMIGOS TEUS;\nA CADA DIA RENOVA O AMOR,\nDEUS É CONTIGO, ELE É O SENHOR.\n\nDEUS É CONTIGO, \nDEUS É CONTIGO ATÉ O FIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (328, 'CONSOLAI, CONSOLAI O MEU POVO', 'CONSOLAI, CONSOLAI O MEU POVO', 'CORO\n''CONSOLAI, CONSOLAI O MEU POVO,''\nDIZ O VOSSO DEUS;\n''PREPARAI, PREPARAI O CAMINHO DO SENHOR.''\n\nFALAI BENIGNAMENTE A JERUSALÉM:\nSUA INIQÜIDADE PERDOADA ESTÁ\nE JÁ RECEBEU EM DOBRO DO SENHOR\nPOR TODOS OS SEUS PECADOS.\n\nCORO\n''CONSOLAI, CONSOLAI O MEU POVO,''\nDIZ O VOSSO DEUS;\n''PREPARAI, PREPARAI O CAMINHO DO SENHOR.''\n\nENDIREITAI NO ERMO VEREDA \nAO NOSSO DEUS E A GLÓRIA \nDO SENHOR SE MANIFESTARÁ, \nLEVANTA A TUA VOZ, \nPROCLAMA FORTEMENTE: \nEIS AQUI ESTÁ O VOSSO DEUS.\n\nCORO\n''CONSOLAI, CONSOLAI O MEU POVO,''\nDIZ O VOSSO DEUS;\n''PREPARAI, PREPARAI O CAMINHO DO SENHOR.''', '<coro>\n''CONSOLAI, CONSOLAI O MEU POVO,''\nDIZ O VOSSO DEUS;\n''PREPARAI, PREPARAI O CAMINHO DO SENHOR.''\n\nFALAI BENIGNAMENTE A JERUSALÉM:\nSUA INIQÜIDADE PERDOADA ESTÁ\nE JÁ RECEBEU EM DOBRO DO SENHOR\nPOR TODOS OS SEUS PECADOS.\n\n<coro>\n''CONSOLAI, CONSOLAI O MEU POVO,''\nDIZ O VOSSO DEUS;\n''PREPARAI, PREPARAI O CAMINHO DO SENHOR.''\n\nENDIREITAI NO ERMO VEREDA \nAO NOSSO DEUS E A GLÓRIA \nDO SENHOR SE MANIFESTARÁ, \nLEVANTA A TUA VOZ, \nPROCLAMA FORTEMENTE: \nEIS AQUI ESTÁ O VOSSO DEUS.\n\n<coro>\n''CONSOLAI, CONSOLAI O MEU POVO,''\nDIZ O VOSSO DEUS;\n''PREPARAI, PREPARAI O CAMINHO DO SENHOR.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (329, 'ATUA EM NOSSO MEIO', 'ATUA EM NOSSO MEIO', 'ATUA EM NOSSO MEIO, Ó SENHOR,\nMANIFESTA O TEU PODER CONSOLADOR, \nCONFORTA OS CORAÇÕES AFLITOS \nE NECESSITADOS DA TUA SALVAÇÃO.\n\nQUEREMOS SEMPRE TE LOUVAR, \nÓ SENHOR, REI DOS EXÉRCITOS, \nMOSTRAR O TEU AMOR\nATRAVÉS DA NOSSA ADORAÇÃO.\n\nINSTRUMENTOS\n\nATUA EM NOSSO MEIO, Ó SENHOR,\n(GLÓRIA AO SENHOR NAS ALTURAS) VARÕES\nMANIFESTA O TEU PODER CONSOLADOR,\n(GLÓRIA AO SENHOR) VARÕES\nGLÓRIA AO SENHOR NAS ALTURAS!', 'ATUA EM NOSSO MEIO, Ó SENHOR,<bis>\nMANIFESTA O TEU PODER CONSOLADOR, <bis>\nCONFORTA OS CORAÇÕES AFLITOS <bis>\nE NECESSITADOS DA TUA SALVAÇÃO.<bis>\n\nQUEREMOS SEMPRE TE LOUVAR, <bis>\nÓ SENHOR, REI DOS EXÉRCITOS, <bis>\nMOSTRAR O TEU AMOR<bis>\nATRAVÉS DA NOSSA ADORAÇÃO.<bis>\n<instrumentos>\n\n\nATUA EM NOSSO MEIO, Ó SENHOR,\n(GLÓRIA AO SENHOR NAS ALTURAS) <h>\nMANIFESTA O TEU PODER CONSOLADOR,\n(GLÓRIA AO SENHOR) <h>\nGLÓRIA AO SENHOR NAS ALTURAS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (330, 'EIS AÍ O DIA ACEITÁVEL', 'EIS AÍ O DIA ACEITÁVEL', 'EIS AÍ O DIA ACEITÁVEL DO SENHOR!\nELE VEIO CONSOLAR TODOS \nOS QUE CHORAM E OS CONTRITOS DE CORAÇÃO;\nELE VAI TE DAR VESTES DE LOUVOR\nAO INVÉS DE ESPÍRITO ANGUSTIADO,\nÓLEO DE ALEGRIA AO INVÉS DE PRANTO.\n\nCORO (2X)\nOUVI A VOZ DO SENHOR,\nEU VI OS ANJOS ANUNCIAREM,\nSENTI A SUA MÃO A ME TOCAR,\nSEU AMOR SOBRE O MEU SER.\n\nAINDA QUE OS TEUS PECADOS \nFOSSEM COMO CARMESIM,\nO SENHOR PODE OS TORNAR ALVOS COMO A BRANCA LÃ;\nE COMO O NOIVO QUE SE ALEGRA DA NOIVA, \nO SENHOR SE ALEGRARÁ DE TI,\nELE VAI TE DAR UMA COROA AO INVÉS DE PRANTO.\n\nCORO (2X)\nOUVI A VOZ DO SENHOR,\nEU VI OS ANJOS ANUNCIAREM,\nSENTI A SUA MÃO A ME TOCAR,\nSEU AMOR SOBRE O MEU SER.', 'EIS AÍ O DIA ACEITÁVEL DO SENHOR!\nELE VEIO CONSOLAR TODOS \nOS QUE CHORAM E OS CONTRITOS DE CORAÇÃO;\nELE VAI TE DAR VESTES DE LOUVOR\nAO INVÉS DE ESPÍRITO ANGUSTIADO,\nÓLEO DE ALEGRIA AO INVÉS DE PRANTO.\n\n<coro tipo=''2X''>\nOUVI A VOZ DO SENHOR,\nEU VI OS ANJOS ANUNCIAREM,\nSENTI A SUA MÃO A ME TOCAR,\nSEU AMOR SOBRE O MEU SER.\n\nAINDA QUE OS TEUS PECADOS \nFOSSEM COMO CARMESIM,\nO SENHOR PODE OS TORNAR ALVOS COMO A BRANCA LÃ;\nE COMO O NOIVO QUE SE ALEGRA DA NOIVA, \nO SENHOR SE ALEGRARÁ DE TI,\nELE VAI TE DAR UMA COROA AO INVÉS DE PRANTO.\n\n<coro tipo=''2X''>\nOUVI A VOZ DO SENHOR,\nEU VI OS ANJOS ANUNCIAREM,\nSENTI A SUA MÃO A ME TOCAR,\nSEU AMOR SOBRE O MEU SER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (331, 'SE DEUS É POR NÓS', 'SE DEUS É POR NÓS', 'SE DEUS É POR NÓS, QUEM SERÁ CONTRA NÓS?\nAQUELE QUE NEM MESMO O SEU FILHO POUPOU, \nANTES O ENTREGOU À CRUZ.\n\nSE O SENHOR CONOSCO ESTÁ,\nQUEM NOS CONDENARÁ?\nAQUELE QUE NOS ESCOLHEU\nÉ QUEM NOS JUSTIFICA.\n\nCORO\nJESUS RESSUSCITOU, RESSUSCITOU,\nVIVO ESTÁ AQUI ENTRE NÓS;\nQUEM IRÁ NOS SEPARAR DO AMOR DE DEUS?\nNEM A MORTE OU TRIBULAÇÃO,\nNEM ALTURA OU PROFUNDIDADE\nPODEM NOS SEPARAR DO AMOR DE DEUS,\nQUE ESTÁ EM CRISTO JESUS, CRISTO JESUS, \nNOSSO SENHOR, CRISTO JESUS.\n\nMAS EM TODAS ESTAS COISAS\nSOMOS MAIS DO QUE VENCEDORES\nPOR AQUELE QUE NOS AMOU\nE A JESUS NOS REVELOU.\n\nCORO\nJESUS RESSUSCITOU, RESSUSCITOU,\nVIVO ESTÁ AQUI ENTRE NÓS;\nQUEM IRÁ NOS SEPARAR DO AMOR DE DEUS?\nNEM A MORTE OU TRIBULAÇÃO,\nNEM ALTURA OU PROFUNDIDADE\nPODEM NOS SEPARAR DO AMOR DE DEUS,\nQUE ESTÁ EM CRISTO JESUS, CRISTO JESUS, \nNOSSO SENHOR, CRISTO JESUS.\n\nFINAL: \nNOSSO SALVADOR, \nCRISTO JESUS,\nNOSSO SALVADOR.', 'SE DEUS É POR NÓS, QUEM SERÁ CONTRA NÓS?\nAQUELE QUE NEM MESMO O SEU FILHO POUPOU, \nANTES O ENTREGOU À CRUZ.\n\nSE O SENHOR CONOSCO ESTÁ,\nQUEM NOS CONDENARÁ?\nAQUELE QUE NOS ESCOLHEU\nÉ QUEM NOS JUSTIFICA.\n\n<coro>\nJESUS RESSUSCITOU, RESSUSCITOU,\nVIVO ESTÁ AQUI ENTRE NÓS;\nQUEM IRÁ NOS SEPARAR DO AMOR DE DEUS?\nNEM A MORTE OU TRIBULAÇÃO,\nNEM ALTURA OU PROFUNDIDADE\nPODEM NOS SEPARAR DO AMOR DE DEUS,\nQUE ESTÁ EM CRISTO JESUS, CRISTO JESUS, \nNOSSO SENHOR, CRISTO JESUS.\n\nMAS EM TODAS ESTAS COISAS\nSOMOS MAIS DO QUE VENCEDORES\nPOR AQUELE QUE NOS AMOU\nE A JESUS NOS REVELOU.\n\n<coro>\nJESUS RESSUSCITOU, RESSUSCITOU,\nVIVO ESTÁ AQUI ENTRE NÓS;\nQUEM IRÁ NOS SEPARAR DO AMOR DE DEUS?\nNEM A MORTE OU TRIBULAÇÃO,\nNEM ALTURA OU PROFUNDIDADE\nPODEM NOS SEPARAR DO AMOR DE DEUS,\nQUE ESTÁ EM CRISTO JESUS, CRISTO JESUS, \nNOSSO SENHOR, CRISTO JESUS.\n\n\n<final>NOSSO SALVADOR, \nCRISTO JESUS,\nNOSSO SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (332, 'O REI E EU', 'O REI E EU', 'O REI E EU TRILHAMOS NA ESTRADA \nDA VIDA ONDE MUITAS ALMAS PASSANDO VÃO;\nO GRANDE SER E EU, UM POBRE MENDIGO, \nANDAMOS JUNTOS, O REI E EU.\n\nCORO\nPORQUE ELE CUIDA DE MIM É UM MISTÉRIO,\nELE TEM O MUNDO EM SUAS MÃOS,\nMAS QUEM SOU EU?\nASSIM MINH''ALMA MUITO SE MARAVILHA\nDE ESTARMOS JUNTOS, O REI E EU.\n\nO REI E EU, ERA MUITO ESTRANHO,\nEU ANDAVA SÓ SEM SABER POR QUE;\nATÉ QUE UM DIA SUAS MÃOS ME ABRAÇARAM,\nNÃO MAIS ESTRANHOS, JESUS E EU.\n\nCORO\nPORQUE ELE CUIDA DE MIM É UM MISTÉRIO,\nELE TEM O MUNDO EM SUAS MÃOS,\nMAS QUEM SOU EU?\nASSIM MINH''ALMA MUITO SE MARAVILHA\nDE ESTARMOS JUNTOS, O REI E EU.', 'O REI E EU TRILHAMOS NA ESTRADA \nDA VIDA ONDE MUITAS ALMAS PASSANDO VÃO;\nO GRANDE SER E EU, UM POBRE MENDIGO, \nANDAMOS JUNTOS, O REI E EU.\n\n<coro>\nPORQUE ELE CUIDA DE MIM É UM MISTÉRIO,\nELE TEM O MUNDO EM SUAS MÃOS,\nMAS QUEM SOU EU?\nASSIM MINH''ALMA MUITO SE MARAVILHA\nDE ESTARMOS JUNTOS, O REI E EU.\n\nO REI E EU, ERA MUITO ESTRANHO,\nEU ANDAVA SÓ SEM SABER POR QUE;\nATÉ QUE UM DIA SUAS MÃOS ME ABRAÇARAM,\nNÃO MAIS ESTRANHOS, JESUS E EU.\n\n<coro>\nPORQUE ELE CUIDA DE MIM É UM MISTÉRIO,\nELE TEM O MUNDO EM SUAS MÃOS,\nMAS QUEM SOU EU?\nASSIM MINH''ALMA MUITO SE MARAVILHA\nDE ESTARMOS JUNTOS, O REI E EU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (333, 'SE TE ENCONTRARES TRISTE', 'SE TE ENCONTRARES TRISTE', 'SE TE ENCONTRARES TRISTE E CANSADO\nE SE VACILARES NO TEU CAMINHAR, \nNÃO TE DETENHAS, POIS NOS TEUS PASSOS, \nEM TEUS CAMINHOS, DEUS PROVERÁ;\nNÃO DESANIMES, À TUA VOLTA ELE ESTARÁ, \nDEUS PROVERÁ.\n\nCORO\nCONFIA E ANDA, \nSEMPRE ORANDO,\nSEMPRE CANTANDO, \nDEUS PROVERÁ.\n\nNÃO TE DETENHAS, (DEUS PROVERÁ) VARÕES\nPOIS NOS TEUS PASSOS, (DEUS PROVERÁ) VARÕES\nEM TEUS CAMINHOS, DEUS PROVERÁ;\nNÃO DESANIMES, (DEUS PROVERÁ) VARÕES\nÀ TUA VOLTA (DEUS PROVERÁ) VARÕES\nELE ESTARÁ, DEUS PROVERÁ.\n\nINSTRUMENTOS\n\nCORO\nCONFIA E ANDA, \nSEMPRE ORANDO,\nSEMPRE CANTANDO, \nDEUS PROVERÁ.', 'SE TE ENCONTRARES TRISTE E CANSADO\nE SE VACILARES NO TEU CAMINHAR, \nNÃO TE DETENHAS, POIS NOS TEUS PASSOS, \nEM TEUS CAMINHOS, DEUS PROVERÁ;\nNÃO DESANIMES, À TUA VOLTA ELE ESTARÁ, \nDEUS PROVERÁ.\n\n<coro>\nCONFIA E ANDA, <bis>\nSEMPRE ORANDO,<bis>\nSEMPRE CANTANDO, <bis>\nDEUS PROVERÁ.<bis>\n\nNÃO TE DETENHAS, (DEUS PROVERÁ) <h>\nPOIS NOS TEUS PASSOS, (DEUS PROVERÁ) <h>\nEM TEUS CAMINHOS, DEUS PROVERÁ;\nNÃO DESANIMES, (DEUS PROVERÁ) <h>\nÀ TUA VOLTA (DEUS PROVERÁ) <h>\nELE ESTARÁ, DEUS PROVERÁ.\n<instrumentos>\n\n\n<coro>\nCONFIA E ANDA, <bis>\nSEMPRE ORANDO,<bis>\nSEMPRE CANTANDO, <bis>\nDEUS PROVERÁ.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (334, 'DEUS CUIDA DE TI', 'DEUS CUIDA DE TI', 'DEUS CUIDA DE TI, (BIS)\nQUANDO TUDO PARECE FALHAR,\nOUVE A VOZ DO SENHOR TE FALAR:\n''NÃO FALHAREI, POIS EU TE AMEI,\nE SEMPRE CUIDO DE TI,\nCUIDO DE TI''.', 'DEUS CUIDA DE TI, <bis>\nQUANDO TUDO PARECE FALHAR,<bis>\nOUVE A VOZ DO SENHOR TE FALAR:<bis>\n''NÃO FALHAREI, POIS EU TE AMEI,<bis>\nE SEMPRE CUIDO DE TI,<bis>\nCUIDO DE TI''.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (335, 'NÃO DESANIMES! DEUS PROVERÁ', 'NÃO DESANIMES! DEUS PROVERÁ', 'NÃO DESANIMES! DEUS PROVERÁ,\nDEUS VELARÁ POR TI;\nSOB SUAS ASAS TE ACOLHERÁ,\nDEUS VELARÁ POR TI.\n\nCORO\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.\n\nSE NO TEU PEITO VIBRAR A DOR,\nDEUS VELARÁ POR TI;\nTU JÁ PROVASTE SEU GRANDE AMOR,\nDEUS VELARÁ POR TI.\n\nCORO\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.\n\nNOS DESALENTOS, NAS PROVAÇÕES,\nDEUS VELARÁ POR TI;\nNAS DESVENTURAS, NAS TENTAÇÕES,\nDEUS VELARÁ POR TI.\n\nCORO\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.\n\nCOMO ESTIVERES, NÃO TEMAS, VEM!\nDEUS VELARÁ POR TI;\nTEU PAI BONDOSO TE ESPERA ALÉM,\nDEUS VELARÁ POR TI.\n\nCORO\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.', 'NÃO DESANIMES! DEUS PROVERÁ,\nDEUS VELARÁ POR TI;\nSOB SUAS ASAS TE ACOLHERÁ,\nDEUS VELARÁ POR TI.\n\n<coro>\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.\n\nSE NO TEU PEITO VIBRAR A DOR,\nDEUS VELARÁ POR TI;\nTU JÁ PROVASTE SEU GRANDE AMOR,\nDEUS VELARÁ POR TI.\n\n<coro>\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.\n\nNOS DESALENTOS, NAS PROVAÇÕES,\nDEUS VELARÁ POR TI;\nNAS DESVENTURAS, NAS TENTAÇÕES,\nDEUS VELARÁ POR TI.\n\n<coro>\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.\n\nCOMO ESTIVERES, NÃO TEMAS, VEM!\nDEUS VELARÁ POR TI;\nTEU PAI BONDOSO TE ESPERA ALÉM,\nDEUS VELARÁ POR TI.\n\n<coro>\nDEUS CUIDARÁ DE TI,\nNA TUA DOR, COM TODO AMOR;\nJAMAIS TE DEIXARÁ, DEUS VELARÁ POR TI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (336, 'HÁ ALGUÉM QUE CUIDA DE TI', 'HÁ ALGUÉM QUE CUIDA DE TI', 'CORO\nHÁ ALGUÉM QUE CUIDA DE TI, (BIS)\nE QUANDO SENTES SOLIDÃO\nE UM VAZIO NO CORAÇÃO,\nLEMBRA QUE ALGUÉM CUIDA DE TI.\n\nSE AS NUVENS TE ENCOBREM E NÃO QUEREM PASSAR, \nSE O TEU BARCO SE AGITA COM AS ONDAS DO MAR,\nNÃO TE ESQUEÇAS:\nALGUÉM CUIDA DE TI SEM CESSAR,\nCOM SEU AMOR ELE VEM TE AJUDAR.\n\nCORO\nHÁ ALGUÉM QUE CUIDA DE TI, (BIS)\nE QUANDO SENTES SOLIDÃO\nE UM VAZIO NO CORAÇÃO,\nLEMBRA QUE ALGUÉM CUIDA DE TI.\n\nQUANDO LEVAS TUDO A ELE EM ORAÇÃO\nE COM LÁGRIMAS SINCERAS NO CORAÇÃO,\nCRISTO VÊ E SE ALEGRA DE TE AJUDAR\nE SUA PAZ ELE VEM DERRAMAR.\n\nCORO\nHÁ ALGUÉM QUE CUIDA DE TI, (BIS)\nE QUANDO SENTES SOLIDÃO\nE UM VAZIO NO CORAÇÃO,\nLEMBRA QUE ALGUÉM CUIDA DE TI.', '<coro>\nHÁ ALGUÉM QUE CUIDA DE TI, <bis>\nE QUANDO SENTES SOLIDÃO\nE UM VAZIO NO CORAÇÃO,\nLEMBRA QUE ALGUÉM CUIDA DE TI.\n\nSE AS NUVENS TE ENCOBREM E NÃO QUEREM PASSAR, \nSE O TEU BARCO SE AGITA COM AS ONDAS DO MAR,\nNÃO TE ESQUEÇAS:\nALGUÉM CUIDA DE TI SEM CESSAR,\nCOM SEU AMOR ELE VEM TE AJUDAR.\n\n<coro>\nHÁ ALGUÉM QUE CUIDA DE TI, <bis>\nE QUANDO SENTES SOLIDÃO\nE UM VAZIO NO CORAÇÃO,\nLEMBRA QUE ALGUÉM CUIDA DE TI.\n\nQUANDO LEVAS TUDO A ELE EM ORAÇÃO\nE COM LÁGRIMAS SINCERAS NO CORAÇÃO,\nCRISTO VÊ E SE ALEGRA DE TE AJUDAR\nE SUA PAZ ELE VEM DERRAMAR.\n\n<coro>\nHÁ ALGUÉM QUE CUIDA DE TI, <bis>\nE QUANDO SENTES SOLIDÃO\nE UM VAZIO NO CORAÇÃO,\nLEMBRA QUE ALGUÉM CUIDA DE TI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (337, 'O MESMO DEUS', 'O MESMO DEUS', 'O MESMO DEUS QUE ONTEM DE MIM CUIDOU, \nVIVO ESTÁ HOJE EM MEU VIVER, MISERICÓRDIAS ME SEGUIRÃO CADA DIA DO MEU VIVER;\nNADA TENHO QUE TEMER POIS JESUS ME GUARDARÁ, \nNADA TENHO QUE TEMER POIS JESUS ME GUIARÁ;\nE ME LEVARÁ À FONTE DA VIDA \nE NO CÉU ME RECEBERÁ.\n\nO MESMO DEUS QUE ONTEM DE MIM CUIDOU, \nVIVO ESTÁ HOJE EM MEU VIVER, MISERICÓRDIAS ME SEGUIRÃO CADA DIA DO MEU VIVER;\nNADA TENHO QUE TEMER POIS JESUS ME GUARDARÁ, \nNADA TENHO QUE TEMER POIS JESUS ME GUIARÁ;\nE ME LEVARÁ À FONTE DA VIDA \nE NO CÉU ME RECEBERÁ (3X NO FINAL)', 'O MESMO DEUS QUE ONTEM DE MIM CUIDOU, \nVIVO ESTÁ HOJE EM MEU VIVER, MISERICÓRDIAS ME SEGUIRÃO CADA DIA DO MEU VIVER;\nNADA TENHO QUE TEMER POIS JESUS ME GUARDARÁ, \nNADA TENHO QUE TEMER POIS JESUS ME GUIARÁ;\nE ME LEVARÁ À FONTE DA VIDA \nE NO CÉU ME RECEBERÁ.\n\nO MESMO DEUS QUE ONTEM DE MIM CUIDOU, \nVIVO ESTÁ HOJE EM MEU VIVER, MISERICÓRDIAS ME SEGUIRÃO CADA DIA DO MEU VIVER;\nNADA TENHO QUE TEMER POIS JESUS ME GUARDARÁ, \nNADA TENHO QUE TEMER POIS JESUS ME GUIARÁ;\nE ME LEVARÁ À FONTE DA VIDA \nE NO CÉU ME RECEBERÁ <bis tipo=''3''> NO FINAL)', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (338, 'DIVINO COMPANHEIRO', 'DIVINO COMPANHEIRO', 'DIVINO COMPANHEIRO NO CAMINHO,\nTUA PRESENÇA SINTO LOGO AO TRANSITAR,\nEIS QUE DISSIPASTE TODA SOMBRA,\nJÁ TENHO LUZ, A LUZ BENDITA DO AMOR.\n\nCORO\nFICA, SENHOR, JÁ SE FAZ TARDE,\nTENS MEU CORAÇÃO PARA POUSAR;\nFAZE EM MIM MORADA PERMANENTE,\nFICA, SENHOR, FICA, SENHOR, MEU SALVADOR.\n\nA SOMBRA DA NOITE SE APROXIMA,\nE NELA O TENTADOR PODE ATACAR;\nNÃO, NÃO ME DEIXES SÓ, NO CAMINHO,\nAJUDA-ME, AJUDA-ME AO CÉU CHEGAR.\n\nCORO\nFICA, SENHOR, JÁ SE FAZ TARDE,\nTENS MEU CORAÇÃO PARA POUSAR;\nFAZE EM MIM MORADA PERMANENTE,\nFICA, SENHOR, FICA, SENHOR, MEU SALVADOR.', 'DIVINO COMPANHEIRO NO CAMINHO,\nTUA PRESENÇA SINTO LOGO AO TRANSITAR,\nEIS QUE DISSIPASTE TODA SOMBRA,\nJÁ TENHO LUZ, A LUZ BENDITA DO AMOR.\n\n<coro>\nFICA, SENHOR, JÁ SE FAZ TARDE,\nTENS MEU CORAÇÃO PARA POUSAR;\nFAZE EM MIM MORADA PERMANENTE,\nFICA, SENHOR, FICA, SENHOR, MEU SALVADOR.\n\nA SOMBRA DA NOITE SE APROXIMA,\nE NELA O TENTADOR PODE ATACAR;\nNÃO, NÃO ME DEIXES SÓ, NO CAMINHO,\nAJUDA-ME, AJUDA-ME AO CÉU CHEGAR.\n\n<coro>\nFICA, SENHOR, JÁ SE FAZ TARDE,\nTENS MEU CORAÇÃO PARA POUSAR;\nFAZE EM MIM MORADA PERMANENTE,\nFICA, SENHOR, FICA, SENHOR, MEU SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (339, 'PARA OS MONTES OLHAREI', 'PARA OS MONTES OLHAREI', 'PARA OS MONTES OLHAREI,\nDE ONDE VEM A SALVAÇÃO?\nMEU SOCORRO VEM DE DEUS,\nO SENHOR DA CRIAÇÃO.\n\nCORO\nO SENHOR É QUEM TE GUARDA,\nGUARDARÁ DE TODO MAL;\nTUA ENTRADA E SAÍDA,\nDESDE AGORA ATÉ O FINAL.\n\nO SENHOR É QUEM TE GUARDA,\nSEMPRE À TUA DESTRA ESTÁ;\nNEM DE DIA, NEM DE NOITE,\nMAL ALGUM TE OFENDERÁ.\n\nCORO\nO SENHOR É QUEM TE GUARDA,\nGUARDARÁ DE TODO MAL;\nTUA ENTRADA E SAÍDA,\nDESDE AGORA ATÉ O FINAL.\n\nO SENHOR É QUEM TE GUARDA,\nNÃO TE DEIXARÁ CAIR;\nCOMO A ISRAEL GUARDAVA,\nNÃO DORMIU NEM VAI DORMIR.', 'PARA OS MONTES OLHAREI,\nDE ONDE VEM A SALVAÇÃO?\nMEU SOCORRO VEM DE DEUS,\nO SENHOR DA CRIAÇÃO.\n\n<coro>\nO SENHOR É QUEM TE GUARDA,\nGUARDARÁ DE TODO MAL;\nTUA ENTRADA E SAÍDA,\nDESDE AGORA ATÉ O FINAL.\n\nO SENHOR É QUEM TE GUARDA,\nSEMPRE À TUA DESTRA ESTÁ;\nNEM DE DIA, NEM DE NOITE,\nMAL ALGUM TE OFENDERÁ.\n\n<coro>\nO SENHOR É QUEM TE GUARDA,\nGUARDARÁ DE TODO MAL;\nTUA ENTRADA E SAÍDA,\nDESDE AGORA ATÉ O FINAL.\n\nO SENHOR É QUEM TE GUARDA,\nNÃO TE DEIXARÁ CAIR;\nCOMO A ISRAEL GUARDAVA,\nNÃO DORMIU NEM VAI DORMIR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (340, 'DEUS TE GUARDARÁ', 'DEUS TE GUARDARÁ', 'DEUS TE GUARDARÁ, DEUS TE GUARDARÁ,\nELE PROMETE E NUNCA FALHARÁ,\nDEUS TE GUARDARÁ.\n\nDEUS TE GUIARÁ, DEUS TE ABENÇOARÁ\nE SOBRE TI O SEU ROSTO BRILHARÁ;\nDEUS TE GUARDARÁ.\n\nDEUS TE GUARDARÁ, DEUS TE GUARDARÁ,\nELE PROMETE E NUNCA FALHARÁ,\nDEUS TE GUARDARÁ.\n\nDEUS TE GUIARÁ, DEUS TE ABENÇOARÁ\nE SOBRE TI O SEU ROSTO BRILHARÁ;\nDEUS TE GUARDARÁ.\n\nFINAL: DEUS TE GUIARÁ,\n DEUS TE ABENÇOARÁ.', 'DEUS TE GUARDARÁ, DEUS TE GUARDARÁ,\nELE PROMETE E NUNCA FALHARÁ,\nDEUS TE GUARDARÁ.\n\nDEUS TE GUIARÁ, DEUS TE ABENÇOARÁ\nE SOBRE TI O SEU ROSTO BRILHARÁ;\nDEUS TE GUARDARÁ.\n\nDEUS TE GUARDARÁ, DEUS TE GUARDARÁ,\nELE PROMETE E NUNCA FALHARÁ,\nDEUS TE GUARDARÁ.\n\nDEUS TE GUIARÁ, DEUS TE ABENÇOARÁ\nE SOBRE TI O SEU ROSTO BRILHARÁ;\nDEUS TE GUARDARÁ.\n<final>DEUS TE GUIARÁ,\n DEUS TE ABENÇOARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (341, 'QUE CONSOLAÇÃO', 'QUE CONSOLAÇÃO', 'QUE CONSOLAÇÃO TEM MEU CORAÇÃO,\nDESCANSANDO NO PODER DE DEUS;\nELE TEM PRAZER EM ME PROTEGER,\nDESCANSANDO NO PODER DE DEUS.\n\nCORO\nDESCANSANDO\nNOS ETERNOS BRAÇOS DO MEU DEUS;\nVOU SEGURO,\nDESCANSANDO NO PODER DE DEUS.\n\nSEMPRE AVANTE VOU, BEM CONTENTE ESTOU,\nDESCANSANDO NO PODER DE DEUS;\nTUDO HEI DE VENCER PELO SEU PODER,\nDESCANSANDO NO PODER DE DEUS.\n\nCORO\nDESCANSANDO\nNOS ETERNOS BRAÇOS DO MEU DEUS;\nVOU SEGURO,\nDESCANSANDO NO PODER DE DEUS.\n\nNÃO RECEAREI, NADA TEMEREI,\nDESCANSANDO NO PODER DE DEUS;\nGOZO, PAZ E AMOR JUNTO A MEU SENHOR\nDESCANSANDO NO PODER DE DEUS.', 'QUE CONSOLAÇÃO TEM MEU CORAÇÃO,\nDESCANSANDO NO PODER DE DEUS;\nELE TEM PRAZER EM ME PROTEGER,\nDESCANSANDO NO PODER DE DEUS.\n\n<coro>\nDESCANSANDO\nNOS ETERNOS BRAÇOS DO MEU DEUS;\nVOU SEGURO,\nDESCANSANDO NO PODER DE DEUS.\n\nSEMPRE AVANTE VOU, BEM CONTENTE ESTOU,\nDESCANSANDO NO PODER DE DEUS;\nTUDO HEI DE VENCER PELO SEU PODER,\nDESCANSANDO NO PODER DE DEUS.\n\n<coro>\nDESCANSANDO\nNOS ETERNOS BRAÇOS DO MEU DEUS;\nVOU SEGURO,\nDESCANSANDO NO PODER DE DEUS.\n\nNÃO RECEAREI, NADA TEMEREI,\nDESCANSANDO NO PODER DE DEUS;\nGOZO, PAZ E AMOR JUNTO A MEU SENHOR\nDESCANSANDO NO PODER DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (342, 'ROCHA MINHA', 'ROCHA MINHA', 'ROCHA MINHA, LIBERTADOR MEU,\nEM TI EU CONFIAREI;\nO PODER NA TERRA E NO CÉU\nSÓ A TI PERTENCE, MEU DEUS E REI.\n\nCORO\nESPERO EM TI, Ó MEU DEUS,\nTUDO ESTÁ EM TUAS MÃOS!\nROCHA MINHA, LIBERTADOR MEU,\nSÓ TU ÉS, SENHOR, MINHA SALVAÇÃO\n\nCOM LOUVOR EM TUA CASA ENTRAREI\nE CANTAREI AO SENHOR,\nNA ALEGRIA OU TRISTEZA, EU SEI,\nSEMPRE ESTÁS COMIGO, MEU GRANDE AMOR.\n\nCORO\nESPERO EM TI, Ó MEU DEUS,\nTUDO ESTÁ EM TUAS MÃOS!\nROCHA MINHA, LIBERTADOR MEU,\nSÓ TU ÉS, SENHOR, MINHA SALVAÇÃO', 'ROCHA MINHA, LIBERTADOR MEU,\nEM TI EU CONFIAREI;\nO PODER NA TERRA E NO CÉU\nSÓ A TI PERTENCE, MEU DEUS E REI.\n\n<coro>\nESPERO EM TI, Ó MEU DEUS,\nTUDO ESTÁ EM TUAS MÃOS!\nROCHA MINHA, LIBERTADOR MEU,\nSÓ TU ÉS, SENHOR, MINHA SALVAÇÃO\n\nCOM LOUVOR EM TUA CASA ENTRAREI\nE CANTAREI AO SENHOR,\nNA ALEGRIA OU TRISTEZA, EU SEI,\nSEMPRE ESTÁS COMIGO, MEU GRANDE AMOR.\n\n<coro>\nESPERO EM TI, Ó MEU DEUS,\nTUDO ESTÁ EM TUAS MÃOS!\nROCHA MINHA, LIBERTADOR MEU,\nSÓ TU ÉS, SENHOR, MINHA SALVAÇÃO', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (343, 'OS QUE CONFIAM NO SENHOR', 'OS QUE CONFIAM NO SENHOR', 'OS QUE CONFIAM NO SENHOR\nSERÃO FORTES E INABALÁVEIS,\nNÃO SERÃO CONFUNDIDOS\nE EM SEUS BRAÇOS DESCANSARÃO.\n\nO SENHOR CUMPRIRÁ SEUS DESEJOS,\nOUVIRÁ SEU CLAMOR E OS SALVARÁ,\nELE SERÁ SEU AUXÍLIO\nE EM SEUS BRAÇOS DESCANSARÃO.', 'OS QUE CONFIAM NO SENHOR\nSERÃO FORTES E INABALÁVEIS,\nNÃO SERÃO CONFUNDIDOS\nE EM SEUS BRAÇOS DESCANSARÃO.\n\nO SENHOR CUMPRIRÁ SEUS DESEJOS,<bis>\nOUVIRÁ SEU CLAMOR E OS SALVARÁ,<bis>\nELE SERÁ SEU AUXÍLIO<bis>\nE EM SEUS BRAÇOS DESCANSARÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (344, 'CONFIO EM DEUS', 'CONFIO EM DEUS', 'CONFIO EM DEUS AONDE QUER QUE EU VÁ,\nEM TERRA FIRME OU SOBRE O IRADO MAR;\nE SEJA POIS, POR ONDE FOR, \nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\nCORO\nCONFIO EM DEUS, EU SEI QUE ME AMARÁ\nE PELA SUA MÃO ME GUIARÁ;\nE SEJA, POIS, POR ONDE FOR, \nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\nA LINDA FLOR RECEBE O SEU CUIDAR,\nELE GUIA OS ANJOS NO ESPAÇOSO AR;\nSE ELE ASSIM, CUIDA DE MIM,\nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\nCORO\nCONFIO EM DEUS, EU SEI QUE ME AMARÁ\nE PELA SUA MÃO ME GUIARÁ;\nE SEJA, POIS, POR ONDE FOR, \nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\nPOR VALES OU DESERTO ABRASADOR\nCOM ELE IREI E SEM NENHUM TEMOR;\nE PELA MÃO ME CONDUZIRÁ,\nCONFIO EM DEUS E EM SEU EXCELSO AMOR.', 'CONFIO EM DEUS AONDE QUER QUE EU VÁ,\nEM TERRA FIRME OU SOBRE O IRADO MAR;\nE SEJA POIS, POR ONDE FOR, \nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\n<coro>\nCONFIO EM DEUS, EU SEI QUE ME AMARÁ\nE PELA SUA MÃO ME GUIARÁ;\nE SEJA, POIS, POR ONDE FOR, \nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\nA LINDA FLOR RECEBE O SEU CUIDAR,\nELE GUIA OS ANJOS NO ESPAÇOSO AR;\nSE ELE ASSIM, CUIDA DE MIM,\nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\n<coro>\nCONFIO EM DEUS, EU SEI QUE ME AMARÁ\nE PELA SUA MÃO ME GUIARÁ;\nE SEJA, POIS, POR ONDE FOR, \nCONFIO EM DEUS E EM SEU EXCELSO AMOR.\n\nPOR VALES OU DESERTO ABRASADOR\nCOM ELE IREI E SEM NENHUM TEMOR;\nE PELA MÃO ME CONDUZIRÁ,\nCONFIO EM DEUS E EM SEU EXCELSO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (345, 'EM NADA PONHO A MINHA FÉ', 'EM NADA PONHO A MINHA FÉ', 'EM NADA PONHO A MINHA FÉ,\nSENÃO NA GRAÇA DE JESUS;\nNO SACRIFÍCIO REMIDOR,\nNO SANGUE DO BOM REDENTOR.\nCORO\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. (BIS)\n\nSE NÃO LHE POSSO A FACE VER,\nNA SUA GRAÇA VOU VIVER;\nA CADA DIA, SEM FALHAR,\nSEMPRE HEI DE NELE CONFIAR.\nCORO\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. (BIS)\n\nSEU JURAMENTO É MUI LEAL,\nABRIGA-ME NO TEMPORAL;\nAO VIR CERCAR-ME A TENTAÇÃO\nÉ CRISTO A MINHA SALVAÇÃO.\nCORO\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. (BIS)\n\nASSIM QUE O SEU CLARIM SOAR,\nIREI COM ELE ME ENCONTRAR\nE GOZAREI DA REDENÇÃO\nCOM TODOS QUE NO CÉU ESTÃO.\nCORO\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. (BIS)', 'EM NADA PONHO A MINHA FÉ,\nSENÃO NA GRAÇA DE JESUS;\nNO SACRIFÍCIO REMIDOR,\nNO SANGUE DO BOM REDENTOR.<coro>\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. <bis>\n\nSE NÃO LHE POSSO A FACE VER,\nNA SUA GRAÇA VOU VIVER;\nA CADA DIA, SEM FALHAR,\nSEMPRE HEI DE NELE CONFIAR.<coro>\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. <bis>\n\nSEU JURAMENTO É MUI LEAL,\nABRIGA-ME NO TEMPORAL;\nAO VIR CERCAR-ME A TENTAÇÃO\nÉ CRISTO A MINHA SALVAÇÃO.<coro>\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. <bis>\n\nASSIM QUE O SEU CLARIM SOAR,\nIREI COM ELE ME ENCONTRAR\nE GOZAREI DA REDENÇÃO\nCOM TODOS QUE NO CÉU ESTÃO.<coro>\nA MINHA FÉ E O MEU AMOR\nESTÃO FIRMADOS NO SENHOR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (346, 'SE A FÉ POR VEZES FALTA', 'SE A FÉ POR VEZES FALTA', 'SE A FÉ POR VEZES FALTA,\nQUANDO O SOL NÃO POSSO VER,\nA JESUS EU DIGO HUMILDE:\nÓ VEM MEU PILOTO SER.\n\nCORO\n''Ó NÃO TEMAS, SOU CONTIGO,\nTEU PILOTO ATÉ O FIM!\nNÃO TE IMPORTES COM O PERIGO,\nEIS A MÃO, CONFIA EM MIM.''\n\nQUANDO A TENTAÇÃO ME ENVOLVE\nE NÃO POSSO A CRISTO VER,\nEIS QUE EM MEIO À TEMPESTADE,\nOUÇO O SALVADOR DIZER:\n\nCORO\n''Ó NÃO TEMAS, SOU CONTIGO,\nTEU PILOTO ATÉ O FIM!\nNÃO TE IMPORTES COM O PERIGO,\nEIS A MÃO, CONFIA EM MIM.''\n\nQUANDO A ALMA SE ABATE,\nQUANDO OS DIAS LONGOS SÃO,\nVOLVO O OLHAR AO MEU PILOTO\nE ESSE CANTO ESCUTO ENTÃO:\n\nCORO\n''Ó NÃO TEMAS, SOU CONTIGO,\nTEU PILOTO ATÉ O FIM!\nNÃO TE IMPORTES COM O PERIGO,\nEIS A MÃO, CONFIA EM MIM.''', 'SE A FÉ POR VEZES FALTA,\nQUANDO O SOL NÃO POSSO VER,\nA JESUS EU DIGO HUMILDE:\nÓ VEM MEU PILOTO SER.\n\n<coro>\n''Ó NÃO TEMAS, SOU CONTIGO,\nTEU PILOTO ATÉ O FIM!\nNÃO TE IMPORTES COM O PERIGO,\nEIS A MÃO, CONFIA EM MIM.''\n\nQUANDO A TENTAÇÃO ME ENVOLVE\nE NÃO POSSO A CRISTO VER,\nEIS QUE EM MEIO À TEMPESTADE,\nOUÇO O SALVADOR DIZER:\n\n<coro>\n''Ó NÃO TEMAS, SOU CONTIGO,\nTEU PILOTO ATÉ O FIM!\nNÃO TE IMPORTES COM O PERIGO,\nEIS A MÃO, CONFIA EM MIM.''\n\nQUANDO A ALMA SE ABATE,\nQUANDO OS DIAS LONGOS SÃO,\nVOLVO O OLHAR AO MEU PILOTO\nE ESSE CANTO ESCUTO ENTÃO:\n\n<coro>\n''Ó NÃO TEMAS, SOU CONTIGO,\nTEU PILOTO ATÉ O FIM!\nNÃO TE IMPORTES COM O PERIGO,\nEIS A MÃO, CONFIA EM MIM.''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (347, 'FIRME NAS PROMESSAS', 'FIRME NAS PROMESSAS', 'FIRME NAS PROMESSAS DO MEU SALVADOR,\nCANTAREI LOUVORES AO MEU CRIADOR,\nFICO NA DISPENSAÇÃO DO SEU AMOR,\nFIRME NAS PROMESSAS DE JESUS.\n\nCORO\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nFIRME NAS PROMESSAS, NÃO IREI FALHAR\nQUANDO AS TEMPESTADES VÊM ME ASSOLAR,\nPELO VERBO VIVO HEI DE BATALHAR,\nFIRME NAS PROMESSAS DE JESUS.\n\nCORO\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nFIRME NAS PROMESSAS, SEMPRE VEJO ASSIM,\nPURIFICAÇÃO NO SANGUE PARA MIM,\nPLENA LIBERDADE EM JESUS, SEM FIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nCORO\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nFIRME NAS PROMESSAS DO SENHOR JESUS\nEM AMOR LIGADO COM A SUA CRUZ,\nCADA DIA MAIS ALEGRO-ME NA LUZ,\nFIRME NAS PROMESSAS DE JESUS.\n\nCORO\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.', 'FIRME NAS PROMESSAS DO MEU SALVADOR,\nCANTAREI LOUVORES AO MEU CRIADOR,\nFICO NA DISPENSAÇÃO DO SEU AMOR,\nFIRME NAS PROMESSAS DE JESUS.\n\n<coro>\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nFIRME NAS PROMESSAS, NÃO IREI FALHAR\nQUANDO AS TEMPESTADES VÊM ME ASSOLAR,\nPELO VERBO VIVO HEI DE BATALHAR,\nFIRME NAS PROMESSAS DE JESUS.\n\n<coro>\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nFIRME NAS PROMESSAS, SEMPRE VEJO ASSIM,\nPURIFICAÇÃO NO SANGUE PARA MIM,\nPLENA LIBERDADE EM JESUS, SEM FIM,\nFIRME NAS PROMESSAS DE JESUS.\n\n<coro>\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.\n\nFIRME NAS PROMESSAS DO SENHOR JESUS\nEM AMOR LIGADO COM A SUA CRUZ,\nCADA DIA MAIS ALEGRO-ME NA LUZ,\nFIRME NAS PROMESSAS DE JESUS.\n\n<coro>\nFIRME, FIRME, FIRME \nNAS PROMESSAS DE JESUS, MEU MESTRE;\nFIRME, FIRME, SIM,\nFIRME NAS PROMESSAS DE JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (348, 'ESPERA NO SENHOR, ANIMA-TE', 'ESPERA NO SENHOR, ANIMA-TE', 'ESPERA NO SENHOR, ANIMA-TE,\nE ELE FORTALECERÁ TEU CORAÇÃO;\nO SENHOR É A FORÇA \nDO SEU POVO,\nO SENHOR É A FORÇA \nDO SEU POVO.\n\nCONHECES MINHA ALMA NAS ANGÚSTIAS\nE AS ÂNSIAS DO MEU CORAÇÃO;\nEM TI PONHO MINHA CONFIANÇA\nPOIS TU, SENHOR, \nÉS A FORÇA DO TEU POVO.\n\nO SENHOR É A FORÇA \nDO SEU POVO. \n\n4x', 'ESPERA NO SENHOR, ANIMA-TE,\nE ELE FORTALECERÁ TEU CORAÇÃO;\nO SENHOR É A FORÇA <bis>\nDO SEU POVO,<bis>\nO SENHOR É A FORÇA <bis>\nDO SEU POVO.<bis>\n\nCONHECES MINHA ALMA NAS ANGÚSTIAS\nE AS ÂNSIAS DO MEU CORAÇÃO;\nEM TI PONHO MINHA CONFIANÇA\nPOIS TU, SENHOR, \nÉS A FORÇA DO TEU POVO.\n\nO SENHOR É A FORÇA \nDO SEU POVO. \n\n<bis tipo=''4''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (349, 'SE NÃO FOSSE O SENHOR', 'SE NÃO FOSSE O SENHOR', 'SE NÃO FOSSE O SENHOR\n(SE NÃO FOSSE O SENHOR) VARÕES\nQUE ESTIVESSE AO NOSSO LADO\nQUANDO OS HOMENS SE LEVANTARAM,\nSE LEVANTARAM CONTRA NÓS.\n\nO SOCORRO ESTÁ NO SENHOR\nQUE FEZ O CÉU E A TERRA.\nOS LAÇOS SÃO QUEBRADOS\nE NÓS ESCAPAMOS.\nBENDITO SEJA O SENHOR\nQUE FEZ O CÉU E A TERRA.\n\nINSTRUMENTOS\n\nSE NÃO FOSSE O SENHOR\n(SE NÃO FOSSE O SENHOR) VARÕES\nQUE ESTIVESSE AO NOSSO LADO\nQUANDO OS HOMENS SE LEVANTARAM,\nSE LEVANTARAM CONTRA NÓS.\n\nO SOCORRO ESTÁ NO SENHOR\nQUE FEZ O CÉU E A TERRA.\nOS LAÇOS SÃO QUEBRADOS\nE NÓS ESCAPAMOS.\n\nBENDITO SEJA O SENHOR\nQUE FEZ O CÉU E A TERRA.\n\nINSTRUMENTOS\n\nFINAL: \nSE NÃO FOSSE O SENHOR,\n(SE NÃO FOSSE O SENHOR)\n(SE NÃO FOSSE O SENHOR)\nO SENHOR!', 'SE NÃO FOSSE O SENHOR\n(SE NÃO FOSSE O SENHOR) <h>\nQUE ESTIVESSE AO NOSSO LADO\nQUANDO OS HOMENS SE LEVANTARAM,\nSE LEVANTARAM CONTRA NÓS.\n\nO SOCORRO ESTÁ NO SENHOR\nQUE FEZ O CÉU E A TERRA.\nOS LAÇOS SÃO QUEBRADOS\nE NÓS ESCAPAMOS.\nBENDITO SEJA O SENHOR\nQUE FEZ O CÉU E A TERRA.\n<instrumentos>\n\n\nSE NÃO FOSSE O SENHOR\n(SE NÃO FOSSE O SENHOR) <h>\nQUE ESTIVESSE AO NOSSO LADO\nQUANDO OS HOMENS SE LEVANTARAM,\nSE LEVANTARAM CONTRA NÓS.\n\nO SOCORRO ESTÁ NO SENHOR\nQUE FEZ O CÉU E A TERRA.\nOS LAÇOS SÃO QUEBRADOS\nE NÓS ESCAPAMOS.\n\nBENDITO SEJA O SENHOR\nQUE FEZ O CÉU E A TERRA.\n<instrumentos>\n<final>SE NÃO FOSSE O SENHOR,\n(SE NÃO FOSSE O SENHOR)<bis>\n(SE NÃO FOSSE O SENHOR)<bis>\nO SENHOR!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (350, 'FAZ-ME INABALÁVEL', 'FAZ-ME INABALÁVEL', 'FAZ-ME INABALÁVEL,\nSENHOR, EM TEU CAMINHO,\nFIRMA OS MEUS PASSOS\nE NÃO TRIUNFE O INIMIGO;\nOUVE A MINHA ORAÇÃO \nE SEJA EU SOCORRIDO.\n\nPOR QUE TE ABATES DENTRO EM MIM,\nÓ MINH''ALMA? ESPERA EM TEU DEUS,\nELE É TUA FORÇA E GLÓRIA;\nNÃO TE DESAMPAROU,\nSEMPRE ESTEVE AO TEU LADO.\n\nA DEUS TODA A GLÓRIA,\nELE NOS FAZ TRIUNFANTES,\nSUA GRAÇA É FORTE\nE SUA PALAVRA É VERDADE, AMÉM!', 'FAZ-ME INABALÁVEL,\nSENHOR, EM TEU CAMINHO,\nFIRMA OS MEUS PASSOS\nE NÃO TRIUNFE O INIMIGO;\nOUVE A MINHA ORAÇÃO \nE SEJA EU SOCORRIDO.\n\nPOR QUE TE ABATES DENTRO EM MIM,\nÓ MINH''ALMA? ESPERA EM TEU DEUS,\nELE É TUA FORÇA E GLÓRIA;\nNÃO TE DESAMPAROU,\nSEMPRE ESTEVE AO TEU LADO.\n\nA DEUS TODA A GLÓRIA,\nELE NOS FAZ TRIUNFANTES,\nSUA GRAÇA É FORTE\nE SUA PALAVRA É VERDADE, AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (351, 'TU ÉS MEU REI', 'TU ÉS MEU REI', 'TU ÉS MEU REI, Ó DEUS, \nORDENA SALVAÇÃO.\nPOIS, POR TI, VENCEREMOS\nTODOS OS INIMIGOS MEUS;\nPELO TEU NOME VENCEDOR SEREI.\n\nPOIS NÃO CONFIAREI \nNO MEU ARCO NEM \nNA MINHA ESPADA.', 'TU ÉS MEU REI, Ó DEUS, <bis>\nORDENA SALVAÇÃO.<bis>\nPOIS, POR TI, VENCEREMOS<bis>\nTODOS OS INIMIGOS MEUS;\nPELO TEU NOME VENCEDOR SEREI.\n\nPOIS NÃO CONFIAREI \nNO MEU ARCO NEM \nNA MINHA ESPADA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (352, 'QUERES NESTE MUNDO SER UM VENCEDOR', 'QUERES NESTE MUNDO SER UM VENCEDOR', 'QUERES NESTE MUNDO SER UM VENCEDOR?\nQUERES TU CANTAR NAS LUTAS E NA DOR?\nQUERES SER ALEGRE, QUAL BOM LUTADOR?\nGUARDA O CONTATO COM TEU SALVADOR.\n\nCORO\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.\n\nNESTE MUNDO VIVEM MUITOS A PENAR,\nCUJOS CORAÇÕES TRANSBORDAM DE PESAR, \nDÁ-LHES A MENSAGEM DE AMOR SEM PAR, \nCOM DEUS O CONTATO DEVES TU GUARDAR.\n\nCORO\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.\n\nQUERES TU COM DEUS A COMUNHÃO OBTER?\nSUA GLÓRIA EM TI SEMPRE PERMANECER?\nQUE O MUNDO POSSA CRISTO EM TI VER?\nGUARDA O CONTATO COM O SUPREMO SER.\n\nCORO\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.\n\nDEIXA QUE O ESPÍRITO IMPLANTE \nEM TEU SER O AMOR DE CRISTO, DIVINAL PRAZER;\nQUERES NESTE MUNDO TODO O MAL VENCER?\nGUARDA O CONTATO E TERÁS PODER.\n\nCORO\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.', 'QUERES NESTE MUNDO SER UM VENCEDOR?\nQUERES TU CANTAR NAS LUTAS E NA DOR?\nQUERES SER ALEGRE, QUAL BOM LUTADOR?\nGUARDA O CONTATO COM TEU SALVADOR.\n\n<coro>\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.\n\nNESTE MUNDO VIVEM MUITOS A PENAR,\nCUJOS CORAÇÕES TRANSBORDAM DE PESAR, \nDÁ-LHES A MENSAGEM DE AMOR SEM PAR, \nCOM DEUS O CONTATO DEVES TU GUARDAR.\n\n<coro>\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.\n\nQUERES TU COM DEUS A COMUNHÃO OBTER?\nSUA GLÓRIA EM TI SEMPRE PERMANECER?\nQUE O MUNDO POSSA CRISTO EM TI VER?\nGUARDA O CONTATO COM O SUPREMO SER.\n\n<coro>\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.\n\nDEIXA QUE O ESPÍRITO IMPLANTE \nEM TEU SER O AMOR DE CRISTO, DIVINAL PRAZER;\nQUERES NESTE MUNDO TODO O MAL VENCER?\nGUARDA O CONTATO E TERÁS PODER.\n\n<coro>\nGUARDA O CONTATO COM TEU SALVADOR\nE A NUVEM DO MAL NÃO TE COBRIRÁ;\nPELA SENDA ALEGRE TU CAMINHARÁS\nINDO EM CONTATO COM TEU SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (353, 'DEIXA-ME CHORAR', 'DEIXA-ME CHORAR', 'DEIXA-ME CHORAR AOS TEUS PÉS,\nDEIXA-ME SENTIR O TEU AMOR,\nSENHOR, SENHOR.\n\nSEM O TEU AMOR NÃO SEI VIVER,\nSEM A TUA GRAÇA EU NÃO SOU\nFELIZ, FELIZ.\n\nTE AMO, Ó SENHOR,\nAUTOR DA MINHA FÉ.\nPOIS CONSOLAS MINH''ALMA,\nO TEU SER ME ACALMA, Ó SENHOR.\n\nDEIXA-ME CHORAR AOS TEUS PÉS,\nDEIXA-ME SENTIR O TEU AMOR,\nSENHOR, SENHOR.\n\nSEM O TEU AMOR NÃO SEI VIVER,\nSEM A TUA GRAÇA EU NÃO SOU\nFELIZ, FELIZ.\n\nTE AMO, Ó SENHOR,\nAUTOR DA MINHA FÉ.\nPOIS CONSOLAS MINH''ALMA,\nO TEU SER ME ACALMA, Ó SENHOR.\n\nFINAL: \nDEIXA-ME CHORAR AOS TEUS PÉS.', 'DEIXA-ME CHORAR AOS TEUS PÉS,\nDEIXA-ME SENTIR O TEU AMOR,\nSENHOR, SENHOR.\n\nSEM O TEU AMOR NÃO SEI VIVER,\nSEM A TUA GRAÇA EU NÃO SOU\nFELIZ, FELIZ.\n\nTE AMO, Ó SENHOR,\nAUTOR DA MINHA FÉ.\nPOIS CONSOLAS MINH''ALMA,\nO TEU SER ME ACALMA, Ó SENHOR.\n\nDEIXA-ME CHORAR AOS TEUS PÉS,\nDEIXA-ME SENTIR O TEU AMOR,\nSENHOR, SENHOR.\n\nSEM O TEU AMOR NÃO SEI VIVER,\nSEM A TUA GRAÇA EU NÃO SOU\nFELIZ, FELIZ.\n\nTE AMO, Ó SENHOR,\nAUTOR DA MINHA FÉ.\nPOIS CONSOLAS MINH''ALMA,\nO TEU SER ME ACALMA, Ó SENHOR.\n<final>DEIXA-ME CHORAR AOS TEUS PÉS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (354, 'CRISTO ME DARÁ', 'CRISTO ME DARÁ', 'CRISTO ME DARÁ A SUA PAZ,\nSIM, GUARDARÁ MEU CAMINHO;\nPOR ONDE QUER QUE EU ANDAR, \nSENHOR, A TUA LUZ ME GUIARÁ.\n\nCORO\nSÓ EM JESUS (SÓ EM JESUS)\nEU POSSO CONFIAR, (EU POSSO CONFIAR)\nETERNAMENTE E EXALTAR (E EXALTAR)\nCOM ALEGRIA SEU SANTO NOME, (GLORIOSO JESUS)\nCOMO É BOM VIVER O AMOR DE DEUS,\nQUE PRECIOSO É TER JESUS EM MIM.\n\nJESUS ME DARÁ O SEU AMOR,\nMESMO EM LUTAS OU PROVAÇÕES,\nCOM SEU ESPÍRITO EM MINHA VIDA\nNADA TEMEREI, SEMPRE O LOUVAREI, \nATÉ O FIM.\n\nCORO\nSÓ EM JESUS (SÓ EM JESUS)\nEU POSSO CONFIAR, (EU POSSO CONFIAR)\nETERNAMENTE E EXALTAR (E EXALTAR)\nCOM ALEGRIA SEU SANTO NOME, (GLORIOSO JESUS)\nCOMO É BOM VIVER O AMOR DE DEUS,\nQUE PRECIOSO É TER JESUS EM MIM.\n\nFINAL: \nAMO AO SENHOR, \nLOUVO A JESUS! \nCRISTO ESTÁ EM MIM!', 'CRISTO ME DARÁ A SUA PAZ,\nSIM, GUARDARÁ MEU CAMINHO;\nPOR ONDE QUER QUE EU ANDAR, \nSENHOR, A TUA LUZ ME GUIARÁ.\n\n<coro>\nSÓ EM JESUS (SÓ EM JESUS)\nEU POSSO CONFIAR, (EU POSSO CONFIAR)\nETERNAMENTE E EXALTAR (E EXALTAR)\nCOM ALEGRIA SEU SANTO NOME, (GLORIOSO JESUS)\nCOMO É BOM VIVER O AMOR DE DEUS,\nQUE PRECIOSO É TER JESUS EM MIM.\n\nJESUS ME DARÁ O SEU AMOR,\nMESMO EM LUTAS OU PROVAÇÕES,\nCOM SEU ESPÍRITO EM MINHA VIDA\nNADA TEMEREI, SEMPRE O LOUVAREI, \nATÉ O FIM.\n\n<coro>\nSÓ EM JESUS (SÓ EM JESUS)\nEU POSSO CONFIAR, (EU POSSO CONFIAR)\nETERNAMENTE E EXALTAR (E EXALTAR)\nCOM ALEGRIA SEU SANTO NOME, (GLORIOSO JESUS)\nCOMO É BOM VIVER O AMOR DE DEUS,\nQUE PRECIOSO É TER JESUS EM MIM.\n\n\n<final>AMO AO SENHOR, \nLOUVO A JESUS! \nCRISTO ESTÁ EM MIM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (355, 'VENCER, VENCER', 'VENCER, VENCER', 'VENCER, VENCER, EU FUI CHAMADO PRA VENCER;\nVENCER O MAL, VENCER O MUNDO\nPOR AMOR AO MEU DEUS. (BIS)\n\nPORQUE SEREI, \nSEREI COMO OS ANJOS QUE LOUVAM\nA CRISTO JESUS, O MEU REI, E ESTAREI NAS LINDAS MANSÕES CELESTIAIS,\nPELAS RUAS DE OURO ANDAREI.\n\nVENCER, VENCER, \nEU FUI CHAMADO PRA VENCER\nATÉ CHEGAR O LINDO DIA\nONDE O MAL CESSARÁ,\nONDE A PAZ REINARÁ.\n\nPORQUE JESUS \nJÁ VENCEU A MORTE NA CRUZ\nE DEU SUA GRAÇA, SUA LUZ;\nPORQUE SEREI, \nSEREI COMO OS ANJOS QUE LOUVAM \nA CRISTO JESUS, O MEU REI.\n\nVENCER, VENCER, \nEU FUI CHAMADO PRA VENCER,\nVENCER O MAL, VENCER O MUNDO\nPOR AMOR AO MEU DEUS. (3X)', 'VENCER, VENCER, EU FUI CHAMADO PRA VENCER;\nVENCER O MAL, VENCER O MUNDO\nPOR AMOR AO MEU DEUS. <bis>\n\nPORQUE SEREI, \nSEREI COMO OS ANJOS QUE LOUVAM\nA CRISTO JESUS, O MEU REI, E ESTAREI NAS LINDAS MANSÕES CELESTIAIS,\nPELAS RUAS DE OURO ANDAREI.\n\nVENCER, VENCER, \nEU FUI CHAMADO PRA VENCER\nATÉ CHEGAR O LINDO DIA\nONDE O MAL CESSARÁ,\nONDE A PAZ REINARÁ.\n\nPORQUE JESUS \nJÁ VENCEU A MORTE NA CRUZ\nE DEU SUA GRAÇA, SUA LUZ;\nPORQUE SEREI, \nSEREI COMO OS ANJOS QUE LOUVAM \nA CRISTO JESUS, O MEU REI.\n\nVENCER, VENCER, \nEU FUI CHAMADO PRA VENCER,\nVENCER O MAL, VENCER O MUNDO\nPOR AMOR AO MEU DEUS. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (356, 'O SENHOR É O MEU PASTOR (REFRIGERA A MINHA ALMA)', 'O SENHOR É O MEU PASTOR (REFRIGERA A MINHA ALMA)', 'O SENHOR É O MEU PASTOR, \nNADA ME FALTARÁ,\nDEITAR-ME FAZ EM VERDES PASTOS,\nE ÀS ÁGUAS, MANSAMENTE,\nMINHA ALMA GUIARÁ.\n\nCORO\nREFRIGERA A MINHA ALMA, (BIS)\nÓ SENHOR, TEU SER ME ACALMA,\nREFRIGERA A MINHA ALMA;\nGUIA-ME PELAS VEREDAS,\nAS VEREDAS DA JUSTIÇA\nE SENTIR SOMENTE O AMOR,\nO AMOR DE DEUS.\n\nSE SOZINHO EU ESTOU\nE NÃO POSSO MAIS LUTAR,\nO SENHOR ESTÁ COMIGO,\nCOM SUA VARA E SEU CAJADO\nNÃO VAI ME DESAMPARAR.\n\nCORO\nREFRIGERA A MINHA ALMA, (BIS)\nÓ SENHOR, TEU SER ME ACALMA,\nREFRIGERA A MINHA ALMA;\nGUIA-ME PELAS VEREDAS,\nAS VEREDAS DA JUSTIÇA\nE SENTIR SOMENTE O AMOR,\nO AMOR DE DEUS.', 'O SENHOR É O MEU PASTOR, \nNADA ME FALTARÁ,\nDEITAR-ME FAZ EM VERDES PASTOS,\nE ÀS ÁGUAS, MANSAMENTE,\nMINHA ALMA GUIARÁ.\n\n<coro>\nREFRIGERA A MINHA ALMA, <bis>\nÓ SENHOR, TEU SER ME ACALMA,\nREFRIGERA A MINHA ALMA;\nGUIA-ME PELAS VEREDAS,\nAS VEREDAS DA JUSTIÇA\nE SENTIR SOMENTE O AMOR,\nO AMOR DE DEUS.\n\nSE SOZINHO EU ESTOU\nE NÃO POSSO MAIS LUTAR,\nO SENHOR ESTÁ COMIGO,\nCOM SUA VARA E SEU CAJADO\nNÃO VAI ME DESAMPARAR.\n\n<coro>\nREFRIGERA A MINHA ALMA, <bis>\nÓ SENHOR, TEU SER ME ACALMA,\nREFRIGERA A MINHA ALMA;\nGUIA-ME PELAS VEREDAS,\nAS VEREDAS DA JUSTIÇA\nE SENTIR SOMENTE O AMOR,\nO AMOR DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (357, 'O SENHOR É O MEU PASTOR (BONDADE E MISERICÓRDIA)', 'O SENHOR É O MEU PASTOR (BONDADE E MISERICÓRDIA)', 'O SENHOR É O MEU PASTOR, \nNADA ME FALTARÁ,\nPOR VERDES CAMPOS ME CONDUZIRÁ,\nEM PLANAS CAMPINAS,\nJUNTO ÀS ÁGUAS TRANQÜILAS\nDO SEU AMOR ELE ME DARÁ.\n\nCORO\nBONDADE E MISERICÓRDIA\nCERTAMENTE ME SEGUIRÃO\nE HABITAREI COM MEU SENHOR\nPRA TODO O SEMPRE;\nAINDA QUE EU ANDASSE\nPELO VALE DA SOMBRA DA MORTE,\nNÃO TEMERIA MAL \nALGUM PORQUE COMIGO ESTÁS.\n\nME UNGES COM ÓLEO DA ALEGRIA,\nEM TUA PRESENÇA ME ALEGRO, SENHOR;\nUMA MESA FARTA TU ME DARÁS,\nTUA DESTRA EM VERDADE ME SUSTENTARÁ.\n\nCORO\nBONDADE E MISERICÓRDIA\nCERTAMENTE ME SEGUIRÃO\nE HABITAREI COM MEU SENHOR\nPRA TODO O SEMPRE;\nAINDA QUE EU ANDASSE\nPELO VALE DA SOMBRA DA MORTE,\nNÃO TEMERIA MAL \nALGUM PORQUE COMIGO ESTÁS.\n\nFINAL: \nO SENHOR É O MEU PASTOR,\nNADA ME FALTARÁ,\nPOR VERDES CAMPOS ME CONDUZIRÁ.', 'O SENHOR É O MEU PASTOR, \nNADA ME FALTARÁ,\nPOR VERDES CAMPOS ME CONDUZIRÁ,\nEM PLANAS CAMPINAS,\nJUNTO ÀS ÁGUAS TRANQÜILAS\nDO SEU AMOR ELE ME DARÁ.\n\n<coro>\nBONDADE E MISERICÓRDIA\nCERTAMENTE ME SEGUIRÃO\nE HABITAREI COM MEU SENHOR\nPRA TODO O SEMPRE;\nAINDA QUE EU ANDASSE\nPELO VALE DA SOMBRA DA MORTE,\nNÃO TEMERIA MAL \nALGUM PORQUE COMIGO ESTÁS.\n\nME UNGES COM ÓLEO DA ALEGRIA,\nEM TUA PRESENÇA ME ALEGRO, SENHOR;\nUMA MESA FARTA TU ME DARÁS,\nTUA DESTRA EM VERDADE ME SUSTENTARÁ.\n\n<coro>\nBONDADE E MISERICÓRDIA\nCERTAMENTE ME SEGUIRÃO\nE HABITAREI COM MEU SENHOR\nPRA TODO O SEMPRE;\nAINDA QUE EU ANDASSE\nPELO VALE DA SOMBRA DA MORTE,\nNÃO TEMERIA MAL \nALGUM PORQUE COMIGO ESTÁS.\n\n\n<final>O SENHOR É O MEU PASTOR,\nNADA ME FALTARÁ,\nPOR VERDES CAMPOS ME CONDUZIRÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (358, 'O SENHOR É O MEU PASTOR (SALMO 23)', 'O SENHOR É O MEU PASTOR (SALMO 23)', 'O SENHOR É O MEU PASTOR,\nNADA ME FALTARÁ;\nPELOS PASTOS VERDEJANTES\nELE ME CONDUZIRÁ.\n\nREFRIGERA A MINHA ALMA\nCOM SUA PAZ E SEU AMOR,\nSEU CAJADO ME CONSOLA,\nELE É O MEU PASTOR.\n\nQUANDO NO VALE DA MORTE\nMAL ALGUM EU TEMEREI,\nO SENHOR É O MEU PASTOR,\nEM SUA CASA HABITAREI.', 'O SENHOR É O MEU PASTOR,<bis>\nNADA ME FALTARÁ;<bis>\nPELOS PASTOS VERDEJANTES<bis>\nELE ME CONDUZIRÁ.<bis>\n\nREFRIGERA A MINHA ALMA\nCOM SUA PAZ E SEU AMOR,\nSEU CAJADO ME CONSOLA,\nELE É O MEU PASTOR.\n\nQUANDO NO VALE DA MORTE\nMAL ALGUM EU TEMEREI,\nO SENHOR É O MEU PASTOR,<bis>\nEM SUA CASA HABITAREI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (359, 'DEUS É NOSSO AMPARO, NOSSA FORTALEZA', 'DEUS É NOSSO AMPARO, NOSSA FORTALEZA', 'DEUS É NOSSO AMPARO, NOSSA FORTALEZA,\nNOSSO PRONTO AUXÍLIO NA TRIBULAÇÃO,\nAINDA QUE SE MUDEM OS MONTES PARA O MAR,\nAINDA QUE A TERRA TREMA,\nTEREMOS QUE CONFIAR.\n\nCÉUS E TERRA PODERÃO PASSAR,\nMAS SUA PALAVRA NÃO PASSARÁ.\n\nNÃO, NÃO, NÃO PASSARÁ. (BIS)\n\nSANTO, SANTO, SANTO, DIZ O SERAFIM,\nSANTO, SANTO, SANTO, É O SENHOR JEOVÁ,\nSANTO, SANTO, SANTO, É O DEUS QUE NOS REDIME,\nPORQUE TRÊS VEZES SANTO,\nA TERRA TREME ONDE DEUS ESTÁ.\n\nCÉUS E TERRA PODERÃO PASSAR,\nMAS SUA PALAVRA NÃO PASSARÁ.\n\nNÃO, NÃO, NÃO PASSARÁ. (BIS)', 'DEUS É NOSSO AMPARO, NOSSA FORTALEZA,\nNOSSO PRONTO AUXÍLIO NA TRIBULAÇÃO,\nAINDA QUE SE MUDEM OS MONTES PARA O MAR,\nAINDA QUE A TERRA TREMA,<bis>\nTEREMOS QUE CONFIAR.<bis>\n\nCÉUS E TERRA PODERÃO PASSAR,<bis>\nMAS SUA PALAVRA NÃO PASSARÁ.<bis>\n\nNÃO, NÃO, NÃO PASSARÁ. <bis>\nSANTO, SANTO, SANTO, DIZ O SERAFIM,\nSANTO, SANTO, SANTO, É O SENHOR JEOVÁ,\nSANTO, SANTO, SANTO, É O DEUS QUE NOS REDIME,\nPORQUE TRÊS VEZES SANTO,<bis>\nA TERRA TREME ONDE DEUS ESTÁ.<bis>\n\nCÉUS E TERRA PODERÃO PASSAR,<bis>\nMAS SUA PALAVRA NÃO PASSARÁ.<bis>\n\nNÃO, NÃO, NÃO PASSARÁ. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (360, 'ROCHEDO FORTE É O SENHOR', 'ROCHEDO FORTE É O SENHOR', 'ROCHEDO FORTE É O SENHOR,\nREFÚGIO NA TRIBULAÇÃO!\nCONSTANTE E FIRME, AMPARADOR,\nREFÚGIO NA TRIBULAÇÃO!\n\nCORO\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.\n\nLUGAR DE SOMBRA NO VERÃO,\nDESCANSO NA TRIBULAÇÃO!\nVIGIA FIEL NA ESCURIDÃO,\nDESCANSO NA TRIBULAÇÃO!\n\nCORO\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.\n\nPILOTO BOM NO BRAVO MAR,\nCONSOLO NA TRIBULAÇÃO!\nANCORADOURO SINGULAR,\nCONSOLO NA TRIBULAÇÃO!\n\nCORO\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.\n\nJESUS É O NOSSO BENFEITOR,\nAUXÍLIO NA TRIBULAÇÃO!\nPRESENTE, ETERNO SALVADOR,\nAUXÍLIO NA TRIBULAÇÃO!\n\nCORO\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.', 'ROCHEDO FORTE É O SENHOR,\nREFÚGIO NA TRIBULAÇÃO!\nCONSTANTE E FIRME, AMPARADOR,\nREFÚGIO NA TRIBULAÇÃO!\n\n<coro>\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.\n\nLUGAR DE SOMBRA NO VERÃO,\nDESCANSO NA TRIBULAÇÃO!\nVIGIA FIEL NA ESCURIDÃO,\nDESCANSO NA TRIBULAÇÃO!\n\n<coro>\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.\n\nPILOTO BOM NO BRAVO MAR,\nCONSOLO NA TRIBULAÇÃO!\nANCORADOURO SINGULAR,\nCONSOLO NA TRIBULAÇÃO!\n\n<coro>\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.\n\nJESUS É O NOSSO BENFEITOR,\nAUXÍLIO NA TRIBULAÇÃO!\nPRESENTE, ETERNO SALVADOR,\nAUXÍLIO NA TRIBULAÇÃO!\n\n<coro>\nOH! CRISTO É NOSSO ABRIGO NO TEMPORAL, \nNO TEMPORAL, NO TEMPORAL!\nOH! CRISTO É NOSSO ABRIGO \nNO TEMPORAL! REFÚGIO NA TRIBULAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (361, 'NÃO HÁ DEUS ACIMA DO SENHOR', 'NÃO HÁ DEUS ACIMA DO SENHOR', 'NÃO HÁ DEUS ACIMA DO SENHOR,\nNÃO HÁ ROCHA COMO NOSSO DEUS;\nÉ FORÇA E PROTEÇÃO, \nELE É A TORRE DE LIBERTAÇÃO\nAOS QUE CONFIAM NO SENHOR. \n\nNÃO HÁ DEUS ACIMA DO SENHOR,\nNÃO HÁ ROCHA COMO NOSSO DEUS;\nME TREINA PRA LUTAR,\nME MOSTRA ONDE DEVO EU ANDAR,\nGLÓRIA AO NOME DE JESUS.\n\nME TREINA PRA LUTAR,\nME MOSTRA ONDE DEVO EU ANDAR,\nGLÓRIA AO NOME DE JESUS.\nGLÓRIA AO NOME DE JESUS.', 'NÃO HÁ DEUS ACIMA DO SENHOR,\nNÃO HÁ ROCHA COMO NOSSO DEUS;\nÉ FORÇA E PROTEÇÃO, <bis>\nELE É A TORRE DE LIBERTAÇÃO<bis>\nAOS QUE CONFIAM NO SENHOR. <bis>\n\nNÃO HÁ DEUS ACIMA DO SENHOR,\nNÃO HÁ ROCHA COMO NOSSO DEUS;\nME TREINA PRA LUTAR,\nME MOSTRA ONDE DEVO EU ANDAR,\nGLÓRIA AO NOME DE JESUS.\n\nME TREINA PRA LUTAR,\nME MOSTRA ONDE DEVO EU ANDAR,\nGLÓRIA AO NOME DE JESUS.\nGLÓRIA AO NOME DE JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (362, 'DEUS PROVERÁ', 'DEUS PROVERÁ', 'CORO (2X)\nDEUS PROVERÁ TUDO PARA O SEU POVO,\nPAZ, ALEGRIA, CONSOLO E GOZO,\nCANTANDO E LOUVANDO AO DEUS CRIADOR,\nAQUELE QUE REINA E QUE É O SENHOR,\nMESMO NAS LUTAS E AFLIÇÕES,\nDEUS PROVERÁ PARA NÓS A VITÓRIA.\n\n''QUANDO PASSARES PELAS ÁGUAS\nESTAREI CONTIGO,\nQUANDO PASSARES PELOS \nRIOS ELES NÃO TE COBRIRÃO\nQUANDO PASSARES PELO FOGO\nELE NÃO TE QUEIMARÁ,\nPORQUE EU SOU O TEU \nDEUS, O SANTO DE ISRAEL\nO TEU SALVADOR''.\n\nVARÕES\n\nVARÕES\n\nCORO\nDEUS PROVERÁ TUDO PARA O SEU POVO,\nPAZ, ALEGRIA, CONSOLO E GOZO,\nCANTANDO E LOUVANDO AO DEUS CRIADOR,\nAQUELE QUE REINA E QUE É O SENHOR,\nMESMO NAS LUTAS E AFLIÇÕES,\nDEUS PROVERÁ PARA NÓS A VITÓRIA.\n\n''QUANDO PASSARES PELAS ÁGUAS\nESTAREI CONTIGO,\nQUANDO PASSARES PELOS \nRIOS ELES NÃO TE COBRIRÃO\nACHASTE GRAÇA AOS MEUS OLHOS,\nDIGNO DE HONRA E EU TE AMEI,\nNÃO TEMAS, EU SOU CONTIGO,\nO SANTO DE ISRAEL,\nO TEU SALVADOR''.\n\nVARÕES\n\nVARÕES\n\nCORO\nDEUS PROVERÁ TUDO PARA O SEU POVO,\nPAZ, ALEGRIA, CONSOLO E GOZO,\nCANTANDO E LOUVANDO AO DEUS CRIADOR,\nAQUELE QUE REINA E QUE É O SENHOR,\nMESMO NAS LUTAS E AFLIÇÕES,\nDEUS PROVERÁ PARA NÓS A VITÓRIA.', '<coro tipo=''2X''>\nDEUS PROVERÁ TUDO PARA O SEU POVO,\nPAZ, ALEGRIA, CONSOLO E GOZO,\nCANTANDO E LOUVANDO AO DEUS CRIADOR,\nAQUELE QUE REINA E QUE É O SENHOR,\nMESMO NAS LUTAS E AFLIÇÕES,\nDEUS PROVERÁ PARA NÓS A VITÓRIA.\n\n''QUANDO PASSARES PELAS ÁGUAS\nESTAREI CONTIGO,\nQUANDO PASSARES PELOS \nRIOS ELES NÃO TE COBRIRÃO\nQUANDO PASSARES PELO FOGO\nELE NÃO TE QUEIMARÁ,\nPORQUE EU SOU O TEU \nDEUS, O SANTO DE ISRAEL\nO TEU SALVADOR''.\n\n<h>\n\n\n<h>\n\n\n<coro>\nDEUS PROVERÁ TUDO PARA O SEU POVO,\nPAZ, ALEGRIA, CONSOLO E GOZO,\nCANTANDO E LOUVANDO AO DEUS CRIADOR,\nAQUELE QUE REINA E QUE É O SENHOR,\nMESMO NAS LUTAS E AFLIÇÕES,\nDEUS PROVERÁ PARA NÓS A VITÓRIA.\n\n''QUANDO PASSARES PELAS ÁGUAS\nESTAREI CONTIGO,\nQUANDO PASSARES PELOS \nRIOS ELES NÃO TE COBRIRÃO\nACHASTE GRAÇA AOS MEUS OLHOS,\nDIGNO DE HONRA E EU TE AMEI,\nNÃO TEMAS, EU SOU CONTIGO,\nO SANTO DE ISRAEL,\nO TEU SALVADOR''.\n\n<h>\n\n\n<h>\n\n\n<coro>\nDEUS PROVERÁ TUDO PARA O SEU POVO,\nPAZ, ALEGRIA, CONSOLO E GOZO,\nCANTANDO E LOUVANDO AO DEUS CRIADOR,<bis>\nAQUELE QUE REINA E QUE É O SENHOR,<bis>\nMESMO NAS LUTAS E AFLIÇÕES,<bis>\nDEUS PROVERÁ PARA NÓS A VITÓRIA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (363, 'QUANDO AS LUTAS ME CERCAM', 'QUANDO AS LUTAS ME CERCAM', 'QUANDO AS LUTAS ME CERCAM,\nME ENTRISTECEM E ME FAZEM CHORAR,\nEU CORRO PARA O TEU ALTAR. \n\nCORO (2X)\nDE JOELHOS COMEÇO A ORAR\nSINTO A MÃO DE JESUS ME TOCAR. \n\nINSTRUMENTOS \n\nO RENOVO ASSIM VEM,\nTEU ESPÍRITO A ME CONSOLAR.\nDE ALEGRIA, QUERO TE LOUVAR.\n\nCORO (2X)\nDE JOELHOS COMEÇO A ORAR\nSINTO A MÃO DE JESUS ME TOCAR. \n\nFINAL: \nDE ALEGRIA, \nQUERO TE LOUVAR.', 'QUANDO AS LUTAS ME CERCAM,\nME ENTRISTECEM E ME FAZEM CHORAR,\nEU CORRO PARA O TEU ALTAR. \n\n<coro tipo=''2X''>\nDE JOELHOS COMEÇO A ORAR\nSINTO A MÃO DE JESUS ME TOCAR. \n<instrumentos>\n\n\nO RENOVO ASSIM VEM,\nTEU ESPÍRITO A ME CONSOLAR.\nDE ALEGRIA, QUERO TE LOUVAR.\n\n<coro tipo=''2X''>\nDE JOELHOS COMEÇO A ORAR\nSINTO A MÃO DE JESUS ME TOCAR. \n<final>DE ALEGRIA, \nQUERO TE LOUVAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (364, 'DÁ-ME MAIS FÉ', 'DÁ-ME MAIS FÉ', 'DÁ-ME MAIS FÉ PRA QUE O MEU CHORO\nSOMENTE ESTA NOITE POSSA DURAR\nE A TUA ALEGRIA, QUE É A MINHA FORÇA, \nBEM CEDO POSSA CHEGAR;\n\nDÁ-ME MAIS FÉ E A CERTEZA \nDE QUE EU POSSO ESPERAR \nBÊNÇÃOS QUE HOJE EU NÃO POSSO VER, \nMAS EM TI ESPERAREI,\nSEI QUE UM DIA VÃO CHEGAR \nE PELA FÉ EU VENCEREI.\n\nCORO\nO IMPOSSÍVEL NÃO DEVO TEMER,\nTUDO É POSSÍVEL AO HOMEM QUE CRÊ;\nDEUS TEM PRAZER NO HOMEM DE FÉ\nQUE CRÊ QUE DEUS NUNCA FALHA,\nQUE MILAGRES E MARAVILHAS OPERARÁ, \nPOR AMOR ÀQUELE QUE DE DEUS \nNÃO DUVIDAR.\n\nDÁ-ME MAIS FÉ E A FORÇA DE LUTAR\nSEM, DO CAMINHO, EU ME DESVIAR,\nMESMO TENDO AFLIÇÕES NÃO \nQUERO JAMAIS PECAR,\nÓ VEM, SENHOR, ME SUSTENTAR;\n\nDÁ-ME MAIS FÉ PARA ENTENDER\nQUE O QUE ME ACONTECER\nÉ SOMENTE PRA EU CRESCER,\nE SEGUINDO SEMPRE EM FRENTE,\nCOM A TUA SALVAÇÃO\nREPOUSO O MEU CORAÇÃO.\n\nCORO\nO IMPOSSÍVEL NÃO DEVO TEMER,\nTUDO É POSSÍVEL AO HOMEM QUE CRÊ;\nDEUS TEM PRAZER NO HOMEM DE FÉ\nQUE CRÊ QUE DEUS NUNCA FALHA,\nQUE MILAGRES E MARAVILHAS OPERARÁ, \nPOR AMOR ÀQUELE QUE DE DEUS \nNÃO DUVIDAR.\nINSTRUMENTOS\n\nCORO\nO IMPOSSÍVEL NÃO DEVO TEMER,\nTUDO É POSSÍVEL AO HOMEM QUE CRÊ;\nDEUS TEM PRAZER NO HOMEM DE FÉ\nQUE CRÊ QUE DEUS NUNCA FALHA,\nQUE MILAGRES E MARAVILHAS OPERARÁ, \nPOR AMOR ÀQUELE QUE DE DEUS \nNÃO DUVIDAR.\n\nFINAL: DÁ-ME MAIS FÉ', 'DÁ-ME MAIS FÉ PRA QUE O MEU CHORO\nSOMENTE ESTA NOITE POSSA DURAR\nE A TUA ALEGRIA, QUE É A MINHA FORÇA, \nBEM CEDO POSSA CHEGAR;\n\nDÁ-ME MAIS FÉ E A CERTEZA \nDE QUE EU POSSO ESPERAR \nBÊNÇÃOS QUE HOJE EU NÃO POSSO VER, \nMAS EM TI ESPERAREI,\nSEI QUE UM DIA VÃO CHEGAR \nE PELA FÉ EU VENCEREI.\n\n<coro>\nO IMPOSSÍVEL NÃO DEVO TEMER,\nTUDO É POSSÍVEL AO HOMEM QUE CRÊ;\nDEUS TEM PRAZER NO HOMEM DE FÉ\nQUE CRÊ QUE DEUS NUNCA FALHA,\nQUE MILAGRES E MARAVILHAS OPERARÁ, \nPOR AMOR ÀQUELE QUE DE DEUS \nNÃO DUVIDAR.\n\nDÁ-ME MAIS FÉ E A FORÇA DE LUTAR\nSEM, DO CAMINHO, EU ME DESVIAR,\nMESMO TENDO AFLIÇÕES NÃO \nQUERO JAMAIS PECAR,\nÓ VEM, SENHOR, ME SUSTENTAR;\n\nDÁ-ME MAIS FÉ PARA ENTENDER\nQUE O QUE ME ACONTECER\nÉ SOMENTE PRA EU CRESCER,\nE SEGUINDO SEMPRE EM FRENTE,\nCOM A TUA SALVAÇÃO\nREPOUSO O MEU CORAÇÃO.\n\n<coro>\nO IMPOSSÍVEL NÃO DEVO TEMER,\nTUDO É POSSÍVEL AO HOMEM QUE CRÊ;\nDEUS TEM PRAZER NO HOMEM DE FÉ\nQUE CRÊ QUE DEUS NUNCA FALHA,\nQUE MILAGRES E MARAVILHAS OPERARÁ, \nPOR AMOR ÀQUELE QUE DE DEUS \nNÃO DUVIDAR.\n<instrumentos>\n\n\n<coro>\nO IMPOSSÍVEL NÃO DEVO TEMER,\nTUDO É POSSÍVEL AO HOMEM QUE CRÊ;\nDEUS TEM PRAZER NO HOMEM DE FÉ\nQUE CRÊ QUE DEUS NUNCA FALHA,\nQUE MILAGRES E MARAVILHAS OPERARÁ, \nPOR AMOR ÀQUELE QUE DE DEUS \nNÃO DUVIDAR.\n<final>DÁ-ME MAIS FÉ', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (365, 'NÃO TEMAS, POIS TE ESCOLHI (QUANDO PELAS ÁGUAS)', 'NÃO TEMAS, POIS TE ESCOLHI (QUANDO PELAS ÁGUAS)', '''NÃO TEMAS, POIS TE ESCOLHI, TE REMI,\nNÃO TEMAS, POIS, PORQUE CONTIGO ESTOU;\nAS COISAS PASSADAS TU NÃO DEVES LEMBRAR,\nPOIS NOVO CAMINHO O TEU DEUS ABRIRÁ.\n\nCORO\nQUANDO PELAS ÁGUAS PASSARES\nCONTIGO ESTAREI,\nQUANDO PELO FOGO TU PASSARES\nNÃO TE QUEIMARÁS,\nEU SOU TEU DEUS, TEU SENHOR, \nO SALVADOR.\n\nINSTRUMENTOS\n\nEU ANUNCIEI E SALVEI, FIZ OUVIR\nQUE NÃO HÁ DEUS SALVADOR FORA DE MIM;\nFOSTE PRECIOSO AOS MEUS OLHOS, EU TE AMEI.\nQUANDO O TEU DEUS OPERAR, QUEM IMPEDIRÁ?\n\nCORO\nQUANDO PELAS ÁGUAS PASSARES\nCONTIGO ESTAREI,\nQUANDO PELO FOGO TU PASSARES\nNÃO TE QUEIMARÁS,\nEU SOU TEU DEUS, TEU SENHOR, \nO SALVADOR.\n\nFINAL: \nQUANDO PELAS ÁGUAS \n(O SALVADOR)\nESTAREI CONTIGO \n(O SALVADOR).''', '''NÃO TEMAS, POIS TE ESCOLHI, TE REMI,\nNÃO TEMAS, POIS, PORQUE CONTIGO ESTOU;\nAS COISAS PASSADAS TU NÃO DEVES LEMBRAR,\nPOIS NOVO CAMINHO O TEU DEUS ABRIRÁ.\n\n<coro>\nQUANDO PELAS ÁGUAS PASSARES\nCONTIGO ESTAREI,\nQUANDO PELO FOGO TU PASSARES\nNÃO TE QUEIMARÁS,\nEU SOU TEU DEUS, TEU SENHOR, \nO SALVADOR.\n<instrumentos>\n\n\nEU ANUNCIEI E SALVEI, FIZ OUVIR\nQUE NÃO HÁ DEUS SALVADOR FORA DE MIM;\nFOSTE PRECIOSO AOS MEUS OLHOS, EU TE AMEI.\nQUANDO O TEU DEUS OPERAR, QUEM IMPEDIRÁ?\n\n<coro>\nQUANDO PELAS ÁGUAS PASSARES\nCONTIGO ESTAREI,\nQUANDO PELO FOGO TU PASSARES\nNÃO TE QUEIMARÁS,\nEU SOU TEU DEUS, TEU SENHOR, \nO SALVADOR.\n\n\n<final>QUANDO PELAS ÁGUAS \n(O SALVADOR)\nESTAREI CONTIGO \n(O SALVADOR).''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (366, 'AS LÁGRIMAS FALAM, JESUS TE ESCUTA', 'AS LÁGRIMAS FALAM, JESUS TE ESCUTA', 'AS LÁGRIMAS FALAM, JESUS TE ESCUTA\nAS LÁGRIMAS FALAM PRA JESUS A TUA DOR.\n''BEM-AVENTURADO É O HOMEM QUE CHORA, \nSERÁ CONSOLADO'', \nPOIS ASSIM DIZ O SENHOR.\n\nDOBRA OS TEUS JOELHOS PERANTE \nO ALTAR DO SENHOR E A VITÓRIA VIRÁ.\nENTREGA TUA ALMA, \nCONFIA EM CRISTO JESUS \nE AS TUAS LÁGRIMAS \nJESUS ENXUGARÁ.\n\nINSTRUMENTOS\n\nAS LÁGRIMAS FALAM, JESUS TE ESCUTA\nAS LÁGRIMAS FALAM PRA JESUS A TUA DOR.\n''BEM-AVENTURADO É O HOMEM QUE CHORA, \nSERÁ CONSOLADO'', \nPOIS ASSIM DIZ O SENHOR.\n\nDOBRA OS TEUS JOELHOS \nPERANTE O ALTAR DO SENHOR E A VITÓRIA VIRÁ.\nENTREGA TUA ALMA, CONFIA EM CRISTO JESUS \nE AS TUAS LÁGRIMAS JESUS ENXUGARÁ.\n\nFINAL: \n(ENXUGARÁ)\nE AS TUAS LÁGRIMAS \nJESUS ENXUGARÁ.', 'AS LÁGRIMAS FALAM, JESUS TE ESCUTA\nAS LÁGRIMAS FALAM PRA JESUS A TUA DOR.\n''BEM-AVENTURADO É O HOMEM QUE CHORA, \nSERÁ CONSOLADO'', \nPOIS ASSIM DIZ O SENHOR.\n\nDOBRA OS TEUS JOELHOS PERANTE \nO ALTAR DO SENHOR E A VITÓRIA VIRÁ.\nENTREGA TUA ALMA, \nCONFIA EM CRISTO JESUS \nE AS TUAS LÁGRIMAS \nJESUS ENXUGARÁ.\n<instrumentos>\n\n\nAS LÁGRIMAS FALAM, JESUS TE ESCUTA\nAS LÁGRIMAS FALAM PRA JESUS A TUA DOR.\n''BEM-AVENTURADO É O HOMEM QUE CHORA, \nSERÁ CONSOLADO'', \nPOIS ASSIM DIZ O SENHOR.\n\nDOBRA OS TEUS JOELHOS \nPERANTE O ALTAR DO SENHOR E A VITÓRIA VIRÁ.\nENTREGA TUA ALMA, CONFIA EM CRISTO JESUS \nE AS TUAS LÁGRIMAS JESUS ENXUGARÁ.\n<final>(ENXUGARÁ)\nE AS TUAS LÁGRIMAS \nJESUS ENXUGARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (367, 'SE AS LUTAS DA VIDA', 'SE AS LUTAS DA VIDA', 'SE AS LUTAS DA VIDA TE FAZEM CHORAR \nE ÀS VEZES TE FALTAM FORÇAS PRA VENCER,\nEXISTE UM DEUS QUE AO TEU LADO ESTÁ,\nELE É DEUS FORTE, POR TI VENCERÁ;\nEXISTE UM DEUS QUE AO TEU LADO ESTÁ, \nELE É FIEL E NÃO FALHARÁ.\n\nDEUS CUIDA DE TI (BIS)\nÉ TEU AMIGO, ESTÁ CONTIGO, \nDEUS CUIDA DE TI.\n\nSÓ EXISTE UM DEUS E AO TEU LADO ESTÁ, \nELE É DEUS FORTE, POR TI VENCERÁ;\nSIM, EXISTE UM DEUS E AO TEU LADO ESTÁ,\nELE É FIEL E NÃO FALHARÁ. (BIS)', 'SE AS LUTAS DA VIDA TE FAZEM CHORAR \nE ÀS VEZES TE FALTAM FORÇAS PRA VENCER,\nEXISTE UM DEUS QUE AO TEU LADO ESTÁ,\nELE É DEUS FORTE, POR TI VENCERÁ;\nEXISTE UM DEUS QUE AO TEU LADO ESTÁ, \nELE É FIEL E NÃO FALHARÁ.\n\nDEUS CUIDA DE TI <bis>\nÉ TEU AMIGO, ESTÁ CONTIGO, \nDEUS CUIDA DE TI.\n\nSÓ EXISTE UM DEUS E AO TEU LADO ESTÁ, \nELE É DEUS FORTE, POR TI VENCERÁ;\nSIM, EXISTE UM DEUS E AO TEU LADO ESTÁ,\nELE É FIEL E NÃO FALHARÁ. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (368, 'ESFORÇA-TE, TEM BOM ÂNIMO!', 'ESFORÇA-TE, TEM BOM ÂNIMO!', '''ESFORÇA-TE, TEM BOM ÂNIMO!''\nASSIM DIZ O SENHOR TEU DEUS,\nO DEUS DE ISRAEL, O DEUS QUE TE AMA,\nO DEUS QUE CONTIGO SEMPRE ESTÁ;\nTÃO-SOMENTE ESFORÇA-TE.\n\nCORO (2X)\nELE CONTIGO IRÁ\nPOR ONDE QUER QUE VÁS,\nSUA BOA MÃO TE SUSTERÁ;\nO SENHOR CONTIGO ESTARÁ.\n\nNÃO TEMAS, NÃO TE APAVORES\nQUANDO A LUTA SURGIR,\nLEMBRA QUE O TEU DEUS\nÉ MAIS FORTE E PODE TE AJUDAR;\nTÃO-SOMENTE ESFORÇA-TE.\n\nCORO (2X)\nELE CONTIGO IRÁ\nPOR ONDE QUER QUE VÁS,\nSUA BOA MÃO TE SUSTERÁ;\nO SENHOR CONTIGO ESTARÁ.\n\nFINAL: \nTÃO-SOMENTE ESFORÇA-TE.', '''ESFORÇA-TE, TEM BOM ÂNIMO!''\nASSIM DIZ O SENHOR TEU DEUS,\nO DEUS DE ISRAEL, O DEUS QUE TE AMA,\nO DEUS QUE CONTIGO SEMPRE ESTÁ;\nTÃO-SOMENTE ESFORÇA-TE.\n\n<coro tipo=''2X''>\nELE CONTIGO IRÁ\nPOR ONDE QUER QUE VÁS,\nSUA BOA MÃO TE SUSTERÁ;\nO SENHOR CONTIGO ESTARÁ.\n\nNÃO TEMAS, NÃO TE APAVORES\nQUANDO A LUTA SURGIR,\nLEMBRA QUE O TEU DEUS\nÉ MAIS FORTE E PODE TE AJUDAR;\nTÃO-SOMENTE ESFORÇA-TE.\n\n<coro tipo=''2X''>\nELE CONTIGO IRÁ\nPOR ONDE QUER QUE VÁS,\nSUA BOA MÃO TE SUSTERÁ;\nO SENHOR CONTIGO ESTARÁ.\n<final>TÃO-SOMENTE ESFORÇA-TE.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (369, 'QUANDO MAIS NINGUÉM TE COMPREENDE', 'QUANDO MAIS NINGUÉM TE COMPREENDE', 'QUANDO MAIS NINGUÉM TE COMPREENDE,\nTEUS AMIGOS TE ABANDONARAM,\nJESUS TE ABRAÇA E DIZ:\n''ESTOU AQUI PRA TE OUVIR''.\n\nCORO\n''FALA, FILHO MEU,\nCONTA PARA MIM OS TEUS PROBLEMAS,\nCLAMA A MIM EM ORAÇÃO, \nCOM SINCERIDADE E RESPONDER-TE-EI.\nFALAREI CONTIGO, SOU O DEUS DA PROVISÃO, \nSOU JESUS, A TUA SOLUÇÃO''.\n\nINSTRUMENTOS\n\n''QUANDO INVOCARES O MEU NOME,\nDE MADRUGADA ME BUSCARES\nE DE JOELHOS TU ORARES, \nESTAREI ATENTO A TE OUVIR.''\n\nCORO (2X)\n''FALA, FILHO MEU,\nCONTA PARA MIM OS TEUS PROBLEMAS,\nCLAMA A MIM EM ORAÇÃO, \nCOM SINCERIDADE E RESPONDER-TE-EI.\nFALAREI CONTIGO, SOU O DEUS DA PROVISÃO, \nSOU JESUS, A TUA SOLUÇÃO''.\n\nFINAL: \n''SOU JESUS, A TUA SOLUÇÃO''.', 'QUANDO MAIS NINGUÉM TE COMPREENDE,\nTEUS AMIGOS TE ABANDONARAM,\nJESUS TE ABRAÇA E DIZ:\n''ESTOU AQUI PRA TE OUVIR''.\n\n<coro>\n''FALA, FILHO MEU,\nCONTA PARA MIM OS TEUS PROBLEMAS,\nCLAMA A MIM EM ORAÇÃO, \nCOM SINCERIDADE E RESPONDER-TE-EI.\nFALAREI CONTIGO, SOU O DEUS DA PROVISÃO, \nSOU JESUS, A TUA SOLUÇÃO''.\n<instrumentos>\n\n\n''QUANDO INVOCARES O MEU NOME,\nDE MADRUGADA ME BUSCARES\nE DE JOELHOS TU ORARES, \nESTAREI ATENTO A TE OUVIR.''\n\n<coro tipo=''2X''>\n''FALA, FILHO MEU,\nCONTA PARA MIM OS TEUS PROBLEMAS,\nCLAMA A MIM EM ORAÇÃO, \nCOM SINCERIDADE E RESPONDER-TE-EI.\nFALAREI CONTIGO, SOU O DEUS DA PROVISÃO, \nSOU JESUS, A TUA SOLUÇÃO''.\n<final>''SOU JESUS, A TUA SOLUÇÃO''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (370, 'JESUS É A ROCHA INABALÁVEL', 'JESUS É A ROCHA INABALÁVEL', 'JESUS É A ROCHA INABALÁVEL,\nREFÚGIO E FORTALEZA DOS FIÉIS;\nMESMO QUE TEU CHORO \nDURE TODA A NOITE, \nMAS AO AMANHECER A ALEGRIA\nENCHERÁ TEU CORAÇÃO, \nPORQUE JESUS TE FALARÁ: \n''NÃO CHORES, ÉS MEU FILHO \nMUITO AMADO''.\n\nAINDA QUE AS PROVAS SEJAM MUITAS,\nNÃO TEMAS, CONFIA EM JESUS;\nMESMO QUE TEU PRANTO SE CONVERTA EM DOR,\nMAS AO ROMPER O DIA A FELICIDADE\nENCHERÁ TEU CORAÇÃO,\nPORQUE JESUS TE FALARÁ: \n''NÃO CHORES, ÉS MEU FILHO \nMUITO AMADO''.\n\nJESUS É A ROCHA INABALÁVEL,\nREFÚGIO E FORTALEZA DOS FIÉIS;\nAINDA QUE AS PROVAS SEJAM MUITAS,\nNÃO TEMAS, CONFIA EM JESUS. \n\nFINAL: NÃO TEMAS, CONFIA EM JESUS.', 'JESUS É A ROCHA INABALÁVEL,\nREFÚGIO E FORTALEZA DOS FIÉIS;\nMESMO QUE TEU CHORO \nDURE TODA A NOITE, \nMAS AO AMANHECER A ALEGRIA\nENCHERÁ TEU CORAÇÃO, \nPORQUE JESUS TE FALARÁ: \n''NÃO CHORES, ÉS MEU FILHO \nMUITO AMADO''.\n\nAINDA QUE AS PROVAS SEJAM MUITAS,\nNÃO TEMAS, CONFIA EM JESUS;\nMESMO QUE TEU PRANTO SE CONVERTA EM DOR,\nMAS AO ROMPER O DIA A FELICIDADE\nENCHERÁ TEU CORAÇÃO,\nPORQUE JESUS TE FALARÁ: \n''NÃO CHORES, ÉS MEU FILHO \nMUITO AMADO''.\n\nJESUS É A ROCHA INABALÁVEL,\nREFÚGIO E FORTALEZA DOS FIÉIS;\nAINDA QUE AS PROVAS SEJAM MUITAS,\nNÃO TEMAS, CONFIA EM JESUS. \n<final>NÃO TEMAS, CONFIA EM JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (371, 'TODA PROMESSA', 'TODA PROMESSA', 'TODA PROMESSA, TODA PALAVRA QUE O SENHOR FALOU \nSE CUMPRIRÁ, EM BREVE VIRÁ O MEU SALVADOR; \nNAS NUVENS DESCENDO, COM PODER E GRAÇA \nVEREI JESUS, MOLDADO O MEU CORPO, \nCOMO O DOS ANJOS SERÁ.\nEM BREVE ESTAREMOS NO CÉU, COM OS ANJOS E O SALVADOR E JUNTOS UNIDOS, \nLOUVAREMOS AO SENHOR.\n\nCORO\nESPERA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL) \nE AS TUAS FORÇAS SE RENOVARÃO (SIM, RENOVARÃO)\nCONFIA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL)\nE SERÁS COMO O MONTE DE SIÃO\nQUE NÃO SE ABALA.\n\nA SUA PALAVRA É DIGNA DE TODA ACEITAÇÃO \nE NÃO VOLTARÁ VAZIA, ANTES TUDO CUMPRIRÁ, \nPOIS O SENHOR DISSE E FARÁ.\nBEM-AVENTURADOS VÓS QUE AGORA CHORAIS, \nPOIS É GRANDE A ALEGRIA\nQUE O SENHOR HÁ DE VOS DAR;\nBEM-AVENTURADOS VÓS QUE AGORA \nSOFREIS POIS SEREIS CONSOLADOS\nPELO GRANDE AMOR DO DEUS DE ISRAEL.\n\nCORO (2X)\nESPERA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL) \nE AS TUAS FORÇAS SE RENOVARÃO (SIM, RENOVARÃO)\nCONFIA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL)\nE SERÁS COMO O MONTE DE SIÃO\nQUE NÃO SE ABALA.\n\nFINAL: \nCOMO O MONTE DE SIÃO \nQUE NÃO SE ABALA.', 'TODA PROMESSA, TODA PALAVRA QUE O SENHOR FALOU \nSE CUMPRIRÁ, EM BREVE VIRÁ O MEU SALVADOR; \nNAS NUVENS DESCENDO, COM PODER E GRAÇA \nVEREI JESUS, MOLDADO O MEU CORPO, \nCOMO O DOS ANJOS SERÁ.\nEM BREVE ESTAREMOS NO CÉU, COM OS ANJOS E O SALVADOR E JUNTOS UNIDOS, \nLOUVAREMOS AO SENHOR.\n\n<coro>\nESPERA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL) \nE AS TUAS FORÇAS SE RENOVARÃO (SIM, RENOVARÃO)\nCONFIA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL)\nE SERÁS COMO O MONTE DE SIÃO\nQUE NÃO SE ABALA.\n\nA SUA PALAVRA É DIGNA DE TODA ACEITAÇÃO \nE NÃO VOLTARÁ VAZIA, ANTES TUDO CUMPRIRÁ, \nPOIS O SENHOR DISSE E FARÁ.\nBEM-AVENTURADOS VÓS QUE AGORA CHORAIS, \nPOIS É GRANDE A ALEGRIA\nQUE O SENHOR HÁ DE VOS DAR;\nBEM-AVENTURADOS VÓS QUE AGORA \nSOFREIS POIS SEREIS CONSOLADOS\nPELO GRANDE AMOR DO DEUS DE ISRAEL.\n\n<coro tipo=''2X''>\nESPERA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL) \nE AS TUAS FORÇAS SE RENOVARÃO (SIM, RENOVARÃO)\nCONFIA NO DEUS DE ISRAEL (NO DEUS DE ISRAEL)\nE SERÁS COMO O MONTE DE SIÃO\nQUE NÃO SE ABALA.\n<final>COMO O MONTE DE SIÃO \nQUE NÃO SE ABALA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (372, 'MUITOS SÃO OS QUE CONFIAM', 'MUITOS SÃO OS QUE CONFIAM', 'MUITOS SÃO OS QUE CONFIAM EM SUA FORÇA \nE SEU SABER E POR ISSO SE ENCURVAM, \nCAEM SEM PODER VENCER;\nMAS EU FAÇO MENÇÃO DO TEU NOME,\nSÓ EM TI CONFIAREI, E NO DIA DA PELEJA \nE ANGÚSTIA COMIGO ESTARÁS, MEU REI!\n\nLEMBRA-TE DA MINHA OFERTA,\nOUVE A MINHA PETIÇÃO\nE EU ME ALEGRAREI COM JÚBILO\nPELA TUA SALVAÇÃO;\nEM TEU NOME ARVORAREI BANDEIRAS, \nPOIS COMIGO ESTÁS, SENHOR, EM TEU \nNOME SALTAREI BARREIRAS\nE SEREI UM VENCEDOR!', 'MUITOS SÃO OS QUE CONFIAM EM SUA FORÇA \nE SEU SABER E POR ISSO SE ENCURVAM, \nCAEM SEM PODER VENCER;\nMAS EU FAÇO MENÇÃO DO TEU NOME,\nSÓ EM TI CONFIAREI, E NO DIA DA PELEJA \nE ANGÚSTIA COMIGO ESTARÁS, MEU REI!\n\nLEMBRA-TE DA MINHA OFERTA,\nOUVE A MINHA PETIÇÃO\nE EU ME ALEGRAREI COM JÚBILO\nPELA TUA SALVAÇÃO;\nEM TEU NOME ARVORAREI BANDEIRAS, <bis>\nPOIS COMIGO ESTÁS, SENHOR, EM TEU <bis>\nNOME SALTAREI BARREIRAS<bis>\nE SEREI UM VENCEDOR!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (373, 'SE UM DIA DEUS PROMETEU', 'SE UM DIA DEUS PROMETEU', 'SE UM DIA DEUS PROMETEU \nA VITÓRIA TE CONCEDER, \nSE IMPOSSÍVEL PARECE \nSER TUA BÊNÇÃO ACONTECER,\nSABE QUE O QUE ELE PROMETEU \nÉ PODEROSO PRA CUMPRIR, \nO TEMPO DE DEUS VAI CHEGAR, \nELE NÃO FALHARÁ.\n\nCORO\nSOMENTE CRER (SOMENTE CRER)\nE DESCANSAR (E DESCANSAR)\nCONFIA EM DEUS E TUDO MAIS (E TUDO MAIS)\nELE FARÁ, NÃO TARDARÁ.\n\nSE NÃO PODES IMAGINAR \nCOMO DEUS PODE OPERAR, \nDEIXA DIANTE DO ALTAR\nPRA QUE DEUS POSSA TE PROVAR \nQUE NÃO HÁ NADA IMPOSSÍVEL \nQUE DEUS NÃO POSSA RESOLVER, \nO SEU ANJO ENVIARÁ \nE A VITÓRIA ELE TRARÁ.\n\nCORO\nSOMENTE CRER (SOMENTE CRER)\nE DESCANSAR (E DESCANSAR)\nCONFIA EM DEUS E TUDO MAIS (E TUDO MAIS)\nELE FARÁ, NÃO TARDARÁ.\n\nFINAL: ELE FARÁ.', 'SE UM DIA DEUS PROMETEU \nA VITÓRIA TE CONCEDER, \nSE IMPOSSÍVEL PARECE \nSER TUA BÊNÇÃO ACONTECER,\nSABE QUE O QUE ELE PROMETEU \nÉ PODEROSO PRA CUMPRIR, \nO TEMPO DE DEUS VAI CHEGAR, \nELE NÃO FALHARÁ.\n\n<coro>\nSOMENTE CRER (SOMENTE CRER)\nE DESCANSAR (E DESCANSAR)\nCONFIA EM DEUS E TUDO MAIS (E TUDO MAIS)\nELE FARÁ, NÃO TARDARÁ.\n\nSE NÃO PODES IMAGINAR \nCOMO DEUS PODE OPERAR, \nDEIXA DIANTE DO ALTAR\nPRA QUE DEUS POSSA TE PROVAR \nQUE NÃO HÁ NADA IMPOSSÍVEL \nQUE DEUS NÃO POSSA RESOLVER, \nO SEU ANJO ENVIARÁ \nE A VITÓRIA ELE TRARÁ.\n\n<coro>\nSOMENTE CRER (SOMENTE CRER)\nE DESCANSAR (E DESCANSAR)\nCONFIA EM DEUS E TUDO MAIS (E TUDO MAIS)\nELE FARÁ, NÃO TARDARÁ.\n<final>ELE FARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (374, 'QUERO TOCAR EM TUAS VESTES, SENHOR', 'QUERO TOCAR EM TUAS VESTES, SENHOR', 'QUERO TOCAR EM TUAS VESTES, SENHOR,\nCOMO AQUELA MULHER TOCOU.\nE QUE SAIA, SENHOR, VIRTUDE,\nPRA QUE EU VEJA O TEU PODER.\n\nCORO\nCREIO, SENHOR (CREIO, SENHOR)\nQUE ESTÁS AQUI E NÃO HÁ IMPOSSÍVEL PRA TI,\n(IMPOSSÍVEL NÃO HÁ)\nBASTA, SENHOR, UMA PALAVRA DIZER (UMA SÓ)\nPRA QUE EU VEJA O TEU PODER.\n\nINSTRUMENTOS \n\nSE VOCÊ ESTÁ EM AFLIÇÕES\nE VÊ SEUS PROBLEMAS SEM SOLUÇÃO,\nO SENHOR AGORA AO SEU LADO ESTÁ,\nBASTA EM SUAS VESTES TOCAR.\n\nCORO (2X)\nCREIO, SENHOR (CREIO, SENHOR)\nQUE ESTÁS AQUI E NÃO HÁ IMPOSSÍVEL PRA TI,\n(IMPOSSÍVEL NÃO HÁ)\nBASTA, SENHOR, UMA PALAVRA DIZER (UMA SÓ)\nPRA QUE EU VEJA O TEU PODER.\n\nFINAL: \nBASTA, SENHOR, \nUMA PALAVRA DIZER (UMA SÓ) \nPRA QUE EU VEJA O TEU PODER.', 'QUERO TOCAR EM TUAS VESTES, SENHOR,\nCOMO AQUELA MULHER TOCOU.\nE QUE SAIA, SENHOR, VIRTUDE,<bis>\nPRA QUE EU VEJA O TEU PODER.<bis>\n\n<coro>\nCREIO, SENHOR (CREIO, SENHOR)\nQUE ESTÁS AQUI E NÃO HÁ IMPOSSÍVEL PRA TI,\n(IMPOSSÍVEL NÃO HÁ)\nBASTA, SENHOR, UMA PALAVRA DIZER (UMA SÓ)\nPRA QUE EU VEJA O TEU PODER.\n<instrumentos>\n\n\nSE VOCÊ ESTÁ EM AFLIÇÕES\nE VÊ SEUS PROBLEMAS SEM SOLUÇÃO,\nO SENHOR AGORA AO SEU LADO ESTÁ,\nBASTA EM SUAS VESTES TOCAR.\n\n<coro tipo=''2X''>\nCREIO, SENHOR (CREIO, SENHOR)\nQUE ESTÁS AQUI E NÃO HÁ IMPOSSÍVEL PRA TI,\n(IMPOSSÍVEL NÃO HÁ)\nBASTA, SENHOR, UMA PALAVRA DIZER (UMA SÓ)\nPRA QUE EU VEJA O TEU PODER.\n\n\n<final>BASTA, SENHOR, \nUMA PALAVRA DIZER (UMA SÓ) \nPRA QUE EU VEJA O TEU PODER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (375, 'OS SEGREDOS DO TEU CORAÇÃO', 'OS SEGREDOS DO TEU CORAÇÃO', 'OS SEGREDOS DO TEU CORAÇÃO\nDEUS CONHECE, DEUS CONHECE;\nTUA DOR, TUA INDAGAÇÃO DEUS CONHECE, \nSIM, DEUS CONHECE.\n\nCORO\nCRISTO QUER SEU AMOR REVELAR,\nOPERAR MARAVILHAS NESTE LUGAR;\nVIVO ESTÁ JESUS, PRONTO A AJUDAR\nAQUELE QUE QUER SUA LUZ.\n\nO QUE TU NÃO CONSEGUES FAZER\nCRISTO PODE, TUDO PODE;\nIMPOSSÍVEIS NÃO HÁ PRA QUEM CRER,\nCRISTO PODE, SIM, TUDO PODE.\n\nCORO\nCRISTO QUER SEU AMOR REVELAR,\nOPERAR MARAVILHAS NESTE LUGAR;\nVIVO ESTÁ JESUS, PRONTO A AJUDAR\nAQUELE QUE QUER SUA LUZ.', 'OS SEGREDOS DO TEU CORAÇÃO\nDEUS CONHECE, DEUS CONHECE;\nTUA DOR, TUA INDAGAÇÃO DEUS CONHECE, \nSIM, DEUS CONHECE.\n\n<coro>\nCRISTO QUER SEU AMOR REVELAR,\nOPERAR MARAVILHAS NESTE LUGAR;\nVIVO ESTÁ JESUS, PRONTO A AJUDAR\nAQUELE QUE QUER SUA LUZ.\n\nO QUE TU NÃO CONSEGUES FAZER\nCRISTO PODE, TUDO PODE;\nIMPOSSÍVEIS NÃO HÁ PRA QUEM CRER,\nCRISTO PODE, SIM, TUDO PODE.\n\n<coro>\nCRISTO QUER SEU AMOR REVELAR,\nOPERAR MARAVILHAS NESTE LUGAR;\nVIVO ESTÁ JESUS, PRONTO A AJUDAR\nAQUELE QUE QUER SUA LUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (376, 'O SENHOR TE GUIARÁ', 'O SENHOR TE GUIARÁ', 'O SENHOR TE GUIARÁ CONTINUAMENTE \nE FARTARÁ TUA ALMA EM LUGARES \nSECOS E FORTIFICARÁ TEUS OSSOS.\n\nE SERÁS COMO UM JARDIM REGADO\nE COMO UM MANANCIAL CUJAS ÁGUAS \nNUNCA FALTAM, NUNCA FALTAM,\nE SERÁS COMO UM MANANCIAL\nCUJAS ÁGUAS NUNCA FALTAM.\n\nO SENHOR TE GUIARÁ CONTINUAMENTE \nE FARTARÁ TUA ALMA EM LUGARES \nSECOS E FORTIFICARÁ TEUS OSSOS.\n\nE SERÁS COMO UM JARDIM REGADO\nE COMO UM MANANCIAL CUJAS ÁGUAS \nNUNCA FALTAM, NUNCA FALTAM,\nE SERÁS COMO UM MANANCIAL\nCUJAS ÁGUAS NUNCA FALTAM.', 'O SENHOR TE GUIARÁ CONTINUAMENTE \nE FARTARÁ TUA ALMA EM LUGARES \nSECOS E FORTIFICARÁ TEUS OSSOS.\n\nE SERÁS COMO UM JARDIM REGADO\nE COMO UM MANANCIAL CUJAS ÁGUAS \nNUNCA FALTAM, NUNCA FALTAM,\nE SERÁS COMO UM MANANCIAL\nCUJAS ÁGUAS NUNCA FALTAM.\n\nO SENHOR TE GUIARÁ CONTINUAMENTE \nE FARTARÁ TUA ALMA EM LUGARES \nSECOS E FORTIFICARÁ TEUS OSSOS.\n\nE SERÁS COMO UM JARDIM REGADO\nE COMO UM MANANCIAL CUJAS ÁGUAS \nNUNCA FALTAM, NUNCA FALTAM,\nE SERÁS COMO UM MANANCIAL\nCUJAS ÁGUAS NUNCA FALTAM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (377, 'DEUS É MINHA ROCHA', 'DEUS É MINHA ROCHA', 'DEUS É MINHA ROCHA, MEU REFÚGIO E FORTALEZA.\nDO ALTÍSSIMO SE OUVIU UMA GRANDE VOZ.\nFLECHAS DISPARADAS E O INIMIGO EM RETIRADA.\nESTENDEU DO ALTO A SUA PODEROSA MÃO.\nPOIS QUEM É DEUS, SENÃO NOSSO DEUS?\nPOIS QUEM É DEUS, SENÃO O SENHOR?\n\nCONDUZIU-ME PARA UM LUGAR MAIS ESPAÇOSO,\nE RETRIBUI-ME SEGUNDO A SUA JUSTIÇA.\nCELEBRAREI, POIS, ENTRE AS NAÇÕES Ó SENHOR,\nE CANTAREI LOUVOR AO TEU NOME.\nPOIS QUEM É DEUS, SENÃO NOSSO DEUS?\nPOIS QUEM É DEUS, SENÃO O SENHOR?\n\nROCHA ETERNA (ROCHA ETERNA) \nQUE FIRMA MEUS PASSOS (TU ÉS) \nPEDRA DE ESQUINA, ABRIGO SEGURO.', 'DEUS É MINHA ROCHA, MEU REFÚGIO E FORTALEZA.\nDO ALTÍSSIMO SE OUVIU UMA GRANDE VOZ.\nFLECHAS DISPARADAS E O INIMIGO EM RETIRADA.\nESTENDEU DO ALTO A SUA PODEROSA MÃO.\nPOIS QUEM É DEUS, SENÃO NOSSO DEUS?\nPOIS QUEM É DEUS, SENÃO O SENHOR?\n\nCONDUZIU-ME PARA UM LUGAR MAIS ESPAÇOSO,\nE RETRIBUI-ME SEGUNDO A SUA JUSTIÇA.\nCELEBRAREI, POIS, ENTRE AS NAÇÕES Ó SENHOR,\nE CANTAREI LOUVOR AO TEU NOME.\nPOIS QUEM É DEUS, SENÃO NOSSO DEUS?\nPOIS QUEM É DEUS, SENÃO O SENHOR?\n\nROCHA ETERNA (ROCHA ETERNA) <bis>\nQUE FIRMA MEUS PASSOS (TU ÉS) <bis>\nPEDRA DE ESQUINA, ABRIGO SEGURO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (378, 'CONFIA E ORA', 'CONFIA E ORA', 'CONFIA E ORA, CERTAMENTE\nO SENHOR TE OUVIRÁ.\nENTREGA AGORA, EM SUAS MÃOS,\nE TUDO VAI PASSAR, TUDO ELE MUDARÁ.\nE TUDO VAI PASSAR, TUDO ELE MUDARÁ.\n\nO TEU DEUS PODEROSO É\nEM SUAS MÃOS VOCÊ AGORA ESTÁ.\nMESMO EM TEMPESTADES,\nOU NA FÚRIA DO MAR,\nO SENHOR TE ESCONDERÁ.\n\nO TEU DEUS ESTARÁ CONTIGO \nONDE QUER QUE FOR\nELE É FIEL E NÃO FALHARÁ. \nCONFIA NO SENHOR,\nELE É FIEL E NÃO FALHARÁ,\nCONFIA NO SENHOR.\n\nINSTRUMENTOS\n\nFINAL: \nCONFIA E ORA,\nCERTAMENTE O SENHOR TE OUVIRÁ.\nENTREGA AGORA, EM SUAS MÃOS,\nE TUDO VAI PASSAR, \nTUDO ELE MUDARÁ. \nE TUDO VAI PASSAR.', 'CONFIA E ORA, CERTAMENTE\nO SENHOR TE OUVIRÁ.\nENTREGA AGORA, EM SUAS MÃOS,\nE TUDO VAI PASSAR, TUDO ELE MUDARÁ.\nE TUDO VAI PASSAR, TUDO ELE MUDARÁ.\n\nO TEU DEUS PODEROSO É\nEM SUAS MÃOS VOCÊ AGORA ESTÁ.\nMESMO EM TEMPESTADES,\nOU NA FÚRIA DO MAR,\nO SENHOR TE ESCONDERÁ.\n\nO TEU DEUS ESTARÁ CONTIGO \nONDE QUER QUE FOR\nELE É FIEL E NÃO FALHARÁ. \nCONFIA NO SENHOR,\nELE É FIEL E NÃO FALHARÁ,\nCONFIA NO SENHOR.\n<instrumentos>\n\n\n\n<final>CONFIA E ORA,\nCERTAMENTE O SENHOR TE OUVIRÁ.\nENTREGA AGORA, EM SUAS MÃOS,\nE TUDO VAI PASSAR, <bis>\nTUDO ELE MUDARÁ. <bis>\nE TUDO VAI PASSAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (379, 'ALGEMADO POR UM PESO', 'ALGEMADO POR UM PESO', 'ALGEMADO POR UM PESO,\nOH! QUÃO TRISTE EU ANDEI,\nTÉ SENTIR A MÃO DE CRISTO,\nNÃO SOU MAIS COMO ERA, EU SEI.\n\nCORO\nTOCOU-ME, JESUS, TOCOU-ME,\nDE PAZ ELE ENCHEU MEU CORAÇÃO.\nQUANDO O SENHOR JESUS ME TOCOU,\nLIVROU-ME DA ESCURIDÃO.\n\nDESDE QUE ENCONTREI A CRISTO,\nE SENTI SEU TERNO AMOR,\nTENHO ACHADO PAZ E VIDA,\nPRA SEMPRE CANTAREI EM SEU LOUVOR.\n\nCORO\nTOCOU-ME, JESUS, TOCOU-ME,\nDE PAZ ELE ENCHEU MEU CORAÇÃO.\nQUANDO O SENHOR JESUS ME TOCOU,\nLIVROU-ME DA ESCURIDÃO.', 'ALGEMADO POR UM PESO,\nOH! QUÃO TRISTE EU ANDEI,\nTÉ SENTIR A MÃO DE CRISTO,\nNÃO SOU MAIS COMO ERA, EU SEI.\n\n<coro>\nTOCOU-ME, JESUS, TOCOU-ME,\nDE PAZ ELE ENCHEU MEU CORAÇÃO.\nQUANDO O SENHOR JESUS ME TOCOU,\nLIVROU-ME DA ESCURIDÃO.\n\nDESDE QUE ENCONTREI A CRISTO,\nE SENTI SEU TERNO AMOR,\nTENHO ACHADO PAZ E VIDA,\nPRA SEMPRE CANTAREI EM SEU LOUVOR.\n\n<coro>\nTOCOU-ME, JESUS, TOCOU-ME,\nDE PAZ ELE ENCHEU MEU CORAÇÃO.\nQUANDO O SENHOR JESUS ME TOCOU,\nLIVROU-ME DA ESCURIDÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (380, 'POSSO SENTIR O SEU TOQUE EM MIM (GLORIFICA)', 'POSSO SENTIR O SEU TOQUE EM MIM (GLORIFICA)', 'POSSO SENTIR O SEU TOQUE EM MIM,\nSINTO O SEU CALOR AQUECENDO O CORAÇÃO.\nPOSSO OUVIR SUA VOZ A SOAR:\n''MEU SERVO, NÃO TEMAS!\nVOU TE AJUDAR. QUANDO AS LUTAS CHEGAREM, \nNÃO OLHES PARA TRÁS OLHA PARA O ALTO E A VITÓRIA ALCANÇARÁS!''\n\nCORO \nÉ DO ALTO QUE VÊM NOSSAS VITÓRIAS,\nCRISTO ESTÁ PRONTO A TE ESCUTAR.\nNÃO ACHES QUE TUDO TERMINOU,\nPOIS DEUS TRAVA UMA BATALHA EM TEU FAVOR!\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\n\nCORO \nÉ DO ALTO QUE VÊM NOSSAS VITÓRIAS,\nCRISTO ESTÁ PRONTO A TE ESCUTAR.\nNÃO ACHES QUE TUDO TERMINOU,\nPOIS DEUS TRAVA UMA BATALHA EM TEU FAVOR!\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\n\nFINAL: GLORIFICA!', 'POSSO SENTIR O SEU TOQUE EM MIM,\nSINTO O SEU CALOR AQUECENDO O CORAÇÃO.\nPOSSO OUVIR SUA VOZ A SOAR:\n''MEU SERVO, NÃO TEMAS!\nVOU TE AJUDAR. QUANDO AS LUTAS CHEGAREM, \nNÃO OLHES PARA TRÁS OLHA PARA O ALTO E A VITÓRIA ALCANÇARÁS!''\n\n<coro>\nÉ DO ALTO QUE VÊM NOSSAS VITÓRIAS,\nCRISTO ESTÁ PRONTO A TE ESCUTAR.\nNÃO ACHES QUE TUDO TERMINOU,\nPOIS DEUS TRAVA UMA BATALHA EM TEU FAVOR!\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\n\n<coro>\nÉ DO ALTO QUE VÊM NOSSAS VITÓRIAS,\nCRISTO ESTÁ PRONTO A TE ESCUTAR.\nNÃO ACHES QUE TUDO TERMINOU,\nPOIS DEUS TRAVA UMA BATALHA EM TEU FAVOR!\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\nGLORIFICA, SÓ GLORIFICA!\nERGUE A VOZ E AGRADECE AO REI SENHOR.\n<final>GLORIFICA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (381, 'MEU DEUS VENCE BATALHAS', 'MEU DEUS VENCE BATALHAS', 'MEU DEUS VENCE BATALHAS,\nMEU DEUS QUEBRA MURALHAS,\nE QUANDO EU ESTOU A FRAQUEJAR,\nSUAS MÃOS ESTÃO A ME SUSTENTAR.\n\nMEU DEUS É MUITO FORTE,\nO SEU NOME É EMANUEL,\nE QUANDO TUDO PARECE MAL,\nA VITÓRIA EU SEI QUE ELE ME DARÁ.\n\nCORO\nCLAMEI NA ANGÚSTIA,\nE OUVIU O MEU CLAMOR.\nMEU DEUS ESTÁ COMIGO,\nNÃO TEMO O PERIGO,\nELE É O MEU SALVADOR.\nNÃO SE COMPARA A PRATA,\nNEM SE COMPARA O OURO,\nJESUS É O MEU TESOURO,\nCOM ELE VOU VENCER.\n\nMEU DEUS VENCE BATALHAS,\nMEU DEUS QUEBRA MURALHAS,\nE QUANDO EU ESTOU A FRAQUEJAR,\nSUAS MÃOS ESTÃO A ME SUSTENTAR.\n\nMEU DEUS É MUITO FORTE,\nO SEU NOME É EMANUEL,\nE QUANDO TUDO PARECE MAL,\nA VITÓRIA EU SEI QUE ELE ME DARÁ.\n\nCORO \nCLAMEI NA ANGÚSTIA,\nE OUVIU O MEU CLAMOR.\nMEU DEUS ESTÁ COMIGO,\nNÃO TEMO O PERIGO,\nELE É O MEU SALVADOR.\nNÃO SE COMPARA A PRATA,\nNEM SE COMPARA O OURO,\nJESUS É O MEU TESOURO,\nCOM ELE VOU VENCER.\n\nCORO \nCLAMEI NA ANGÚSTIA, E OUVIU O MEU CLAMOR.\nMEU DEUS ESTÁ COMIGO, NÃO TEMO O PERIGO,\nELE É O MEU SALVADOR.\nNÃO SE COMPARA A PRATA, NEM SE COMPARA O OURO,\nJESUS É O MEU TESOURO, COM ELE VOU VENCER.\n\nFINAL: \nMEU DEUS VENCE BATALHAS.', 'MEU DEUS VENCE BATALHAS,\nMEU DEUS QUEBRA MURALHAS,\nE QUANDO EU ESTOU A FRAQUEJAR,\nSUAS MÃOS ESTÃO A ME SUSTENTAR.\n\nMEU DEUS É MUITO FORTE,\nO SEU NOME É EMANUEL,\nE QUANDO TUDO PARECE MAL,\nA VITÓRIA EU SEI QUE ELE ME DARÁ.\n\n<coro>\nCLAMEI NA ANGÚSTIA,\nE OUVIU O MEU CLAMOR.\nMEU DEUS ESTÁ COMIGO,\nNÃO TEMO O PERIGO,\nELE É O MEU SALVADOR.\nNÃO SE COMPARA A PRATA,\nNEM SE COMPARA O OURO,\nJESUS É O MEU TESOURO,\nCOM ELE VOU VENCER.\n\nMEU DEUS VENCE BATALHAS,\nMEU DEUS QUEBRA MURALHAS,\nE QUANDO EU ESTOU A FRAQUEJAR,\nSUAS MÃOS ESTÃO A ME SUSTENTAR.\n\nMEU DEUS É MUITO FORTE,\nO SEU NOME É EMANUEL,\nE QUANDO TUDO PARECE MAL,\nA VITÓRIA EU SEI QUE ELE ME DARÁ.\n\n<coro>\nCLAMEI NA ANGÚSTIA,\nE OUVIU O MEU CLAMOR.\nMEU DEUS ESTÁ COMIGO,\nNÃO TEMO O PERIGO,\nELE É O MEU SALVADOR.\nNÃO SE COMPARA A PRATA,\nNEM SE COMPARA O OURO,\nJESUS É O MEU TESOURO,\nCOM ELE VOU VENCER.\n\n<coro>\nCLAMEI NA ANGÚSTIA, E OUVIU O MEU CLAMOR.\nMEU DEUS ESTÁ COMIGO, NÃO TEMO O PERIGO,\nELE É O MEU SALVADOR.\nNÃO SE COMPARA A PRATA, NEM SE COMPARA O OURO,\nJESUS É O MEU TESOURO, COM ELE VOU VENCER.\n<final>MEU DEUS VENCE BATALHAS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (382, 'JÁ CHEGUEI ATÉ AQUI (VITÓRIAS)', 'JÁ CHEGUEI ATÉ AQUI (VITÓRIAS)', 'JÁ CHEGUEI ATÉ AQUI, EU NÃO POSSO DESISTIR,\nDEVO ACHAR FORÇAS PRA ANDAR.\nAS LUTAS VIERAM, MAS TAMBÉM PASSARAM,\nVENDAVAIS TENTARAM ME DERRUBAR.\n\nMAS BUSQUEI A CRISTO, MEU FIEL AMIGO,\nQUE ESTEVE COMIGO TODO DIA\nMESMO QUE CHORANDO, \nMESMO QUE SOFRENDO, JÁ ESTAVA CERTO\nQUE A VITÓRIA GANHARIA NO AMANHÃ.\n\nINSTRUMENTOS\n\nJÁ CHEGAMOS ATÉ AQUI, \nNÃO PODEMOS DESISTIR,\nVAMOS ACHAR FORÇAS PRA ANDAR.\nAS LUTAS VIERAM, MAS TAMBÉM PASSARAM,\nVENDAVAIS TENTARAM NOS DERRUBAR.\n\nNADA NOS FALTOU, TUDO DEUS PROVEU, \nNOS DEU COROA PRA GUARDAR. \nE FEZ TUDO NOVO COM AMOR GLORIOSO, \nE NOS DEU VITÓRIA ONTEM, \nHOJE E NOS DARÁ NO AMANHÃ.', 'JÁ CHEGUEI ATÉ AQUI, EU NÃO POSSO DESISTIR,\nDEVO ACHAR FORÇAS PRA ANDAR.\nAS LUTAS VIERAM, MAS TAMBÉM PASSARAM,\nVENDAVAIS TENTARAM ME DERRUBAR.\n\nMAS BUSQUEI A CRISTO, MEU FIEL AMIGO,\nQUE ESTEVE COMIGO TODO DIA\nMESMO QUE CHORANDO, \nMESMO QUE SOFRENDO, JÁ ESTAVA CERTO\nQUE A VITÓRIA GANHARIA NO AMANHÃ.\n<instrumentos>\n\n\nJÁ CHEGAMOS ATÉ AQUI, \nNÃO PODEMOS DESISTIR,\nVAMOS ACHAR FORÇAS PRA ANDAR.\nAS LUTAS VIERAM, MAS TAMBÉM PASSARAM,\nVENDAVAIS TENTARAM NOS DERRUBAR.\n\nNADA NOS FALTOU, TUDO DEUS PROVEU, <bis>\nNOS DEU COROA PRA GUARDAR. <bis>\nE FEZ TUDO NOVO COM AMOR GLORIOSO, <bis>\nE NOS DEU VITÓRIA ONTEM, <bis>\nHOJE E NOS DARÁ NO AMANHÃ. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (383, 'LÁ ONDE EU NÃO POSSO VER (A ORAÇÃO)', 'LÁ ONDE EU NÃO POSSO VER (A ORAÇÃO)', 'LÁ ONDE EU NÃO POSSO VER, \nONDE NÃO POSSO ESTAR, \nTEM PESSOAS QUE EU NÃO \nPOSSO AJUDAR, \n\nSEUS PROBLEMAS RESOLVER, \nMAS EU SEI QUE POSSO ORAR. \n\nM\n\nT\n\nMEUS TEMORES E AFLIÇÕES, \nMINHA DOR, DECEPÇÕES. \n\nAPRENDI A COLOCAR \nMINHA VIDA SOBRE O ALTAR, \nENTÃO SEI QUE POSSO ORAR \nE EM DEUS POSSO CONFIAR. \n\nH\n\nT\n\nCORO\nA ORAÇÃO VAI AONDE EU NÃO POSSO IR,\nDEUS PROMETEU ME SOCORRER \nQUANDO EU PEDIR.\nA ORAÇÃO DOS QUE AMAM A DEUS\nPODE MUITO EM SEU PODER,\nE QUANDO ESTOU EM ORAÇÃO,\nTUDO PODE ACONTECER.\n\nSOU LAVADO E REMIDO, \nNÃO PRECISO TEMER \n\nPOIS O SANGUE DE JESUS \nÉ QUE TEM O PODER, \nDE ME FAZER ENTRAR \nNA PRESENÇA DE DEUS,\nNÃO HÁ MAIS IMPEDIMENTO\nDE FICAR MAIS PERTO DE DEUS.\n\nM\n\nH\n\nT\n\nCORO (2X)\nA ORAÇÃO VAI AONDE EU NÃO POSSO IR,\nDEUS PROMETEU ME SOCORRER \nQUANDO EU PEDIR.\nA ORAÇÃO DOS QUE AMAM A DEUS\nPODE MUITO EM SEU PODER,\nE QUANDO ESTOU EM ORAÇÃO,\nTUDO PODE ACONTECER.', 'LÁ ONDE EU NÃO POSSO VER, \nONDE NÃO POSSO ESTAR, \nTEM PESSOAS QUE EU NÃO \nPOSSO AJUDAR, \n\nSEUS PROBLEMAS RESOLVER, \nMAS EU SEI QUE POSSO ORAR. \n\n<m>\n\n<t>\n\nMEUS TEMORES E AFLIÇÕES, \nMINHA DOR, DECEPÇÕES. \n\nAPRENDI A COLOCAR \nMINHA VIDA SOBRE O ALTAR, \nENTÃO SEI QUE POSSO ORAR \nE EM DEUS POSSO CONFIAR. \n\n<h>\n\n<t>\n\n<coro>\nA ORAÇÃO VAI AONDE EU NÃO POSSO IR,\nDEUS PROMETEU ME SOCORRER \nQUANDO EU PEDIR.\nA ORAÇÃO DOS QUE AMAM A DEUS\nPODE MUITO EM SEU PODER,\nE QUANDO ESTOU EM ORAÇÃO,\nTUDO PODE ACONTECER.\n\nSOU LAVADO E REMIDO, \nNÃO PRECISO TEMER \n\nPOIS O SANGUE DE JESUS \nÉ QUE TEM O PODER, \nDE ME FAZER ENTRAR \nNA PRESENÇA DE DEUS,\nNÃO HÁ MAIS IMPEDIMENTO\nDE FICAR MAIS PERTO DE DEUS.\n\n<m>\n\n<h>\n\n<t>\n\n<coro tipo=''2X''>\nA ORAÇÃO VAI AONDE EU NÃO POSSO IR,\nDEUS PROMETEU ME SOCORRER \nQUANDO EU PEDIR.\nA ORAÇÃO DOS QUE AMAM A DEUS\nPODE MUITO EM SEU PODER,\nE QUANDO ESTOU EM ORAÇÃO,\nTUDO PODE ACONTECER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (384, 'BEM SEI QUE TUDO PODES', 'BEM SEI QUE TUDO PODES', 'BEM SEI QUE TUDO PODES, MEU AMADO.\nNENHUM DOS TEUS PLANOS É FRUSTRADO.\nAINDA QUE COM PERDAS E COM DOR\nEU SEMPRE SEGUIREI A TI, SENHOR.\n\nOS TEUS CAMINHOS POSSO\nNÃO ENTENDER, SENHOR,\nMAS SEI QUE TUDO\nÉ VISANDO O MEU CRESCER.\nSE LUTAS E TRIBULAÇÕES\nEU TENHO QUE PASSAR,\nTE PEÇO FORÇAS PRA CONTINUAR.\n\nCONTINUAR A CRER E A CONFIAR,\nNO GRANDE AMOR QUE TENS, \nMEU PAI, POR MIM.\nO MEU DESEJO ETERNO É TE ADORAR,\nE AOS TEUS PÉS ME DERRAMAR SEM FIM.\n\nBEM SEI QUE TUDO PODES, MEU AMADO.\nNENHUM DOS TEUS PLANOS É FRUSTRADO.\nAINDA QUE COM PERDAS E COM DOR\nEU SEMPRE SEGUIREI A TI, SENHOR.\n\nOS TEUS CAMINHOS POSSO\nNÃO ENTENDER, SENHOR,\nMAS SEI QUE TUDO\nÉ VISANDO O MEU CRESCER.\nSE LUTAS E TRIBULAÇÕES\nEU TENHO QUE PASSAR,\nTE PEÇO FORÇAS PRA CONTINUAR.\n\nCONTINUAR A CRER E A CONFIAR,\nNO GRANDE AMOR QUE TENS, \nMEU PAI, POR MIM.\nO MEU DESEJO ETERNO É TE ADORAR,\nE AOS TEUS PÉS ME DERRAMAR SEM FIM.\n\nFINAL: \nE AOS TEUS PÉS ME DERRAMAR SEM FIM.', 'BEM SEI QUE TUDO PODES, MEU AMADO.\nNENHUM DOS TEUS PLANOS É FRUSTRADO.\nAINDA QUE COM PERDAS E COM DOR\nEU SEMPRE SEGUIREI A TI, SENHOR.\n\nOS TEUS CAMINHOS POSSO\nNÃO ENTENDER, SENHOR,\nMAS SEI QUE TUDO\nÉ VISANDO O MEU CRESCER.\nSE LUTAS E TRIBULAÇÕES\nEU TENHO QUE PASSAR,\nTE PEÇO FORÇAS PRA CONTINUAR.\n\nCONTINUAR A CRER E A CONFIAR,\nNO GRANDE AMOR QUE TENS, \nMEU PAI, POR MIM.\nO MEU DESEJO ETERNO É TE ADORAR,\nE AOS TEUS PÉS ME DERRAMAR SEM FIM.\n\nBEM SEI QUE TUDO PODES, MEU AMADO.\nNENHUM DOS TEUS PLANOS É FRUSTRADO.\nAINDA QUE COM PERDAS E COM DOR\nEU SEMPRE SEGUIREI A TI, SENHOR.\n\nOS TEUS CAMINHOS POSSO\nNÃO ENTENDER, SENHOR,\nMAS SEI QUE TUDO\nÉ VISANDO O MEU CRESCER.\nSE LUTAS E TRIBULAÇÕES\nEU TENHO QUE PASSAR,\nTE PEÇO FORÇAS PRA CONTINUAR.\n\nCONTINUAR A CRER E A CONFIAR,\nNO GRANDE AMOR QUE TENS, \nMEU PAI, POR MIM.\nO MEU DESEJO ETERNO É TE ADORAR,\nE AOS TEUS PÉS ME DERRAMAR SEM FIM.\n<final>E AOS TEUS PÉS ME DERRAMAR SEM FIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (385, 'QUÃO DIFÍCIL É, SENHOR (FAZE-ME UM VENCEDOR)', 'QUÃO DIFÍCIL É, SENHOR (FAZE-ME UM VENCEDOR)', 'QUÃO DIFÍCIL É, SENHOR,\nVIVER NESTE MUNDO DE AFLIÇÕES.\nÉ TEU AMOR QUE ME SUSTÉM\nE PELO TEU PODER.\n\nCORO (BIS)\nFAZE-ME UM VENCEDOR,\nFAZE-ME, SENHOR,\nUM INSTRUMENTO PRA TEU LOUVOR.\n\nE ADORAÇÃO ÀQUELE \nQUE É MAIS QUE VENCEDOR!\n\nINSTRUMENTOS\n\nSE PROVADO EU ESTOU\nE ESTAS PROVAÇÕES \nTENHO QUE PASSAR;\nEIS-ME AQUI, AJUDA-ME,\nAPROVADO QUERO SER.\n\nCORO (BIS)\nFAZE-ME UM VENCEDOR,\nFAZE-ME, SENHOR,\nUM INSTRUMENTO PRA TEU LOUVOR.\n\nFINAL: \nAQUELE QUE É MAIS \nQUE VENCEDOR!', 'QUÃO DIFÍCIL É, SENHOR,\nVIVER NESTE MUNDO DE AFLIÇÕES.\nÉ TEU AMOR QUE ME SUSTÉM\nE PELO TEU PODER.\n\n<coro tipo=''BIS''>\nFAZE-ME UM VENCEDOR,\nFAZE-ME, SENHOR,\nUM INSTRUMENTO PRA TEU LOUVOR.\n\nE ADORAÇÃO ÀQUELE \nQUE É MAIS QUE VENCEDOR!\n<instrumentos>\n\n\nSE PROVADO EU ESTOU\nE ESTAS PROVAÇÕES \nTENHO QUE PASSAR;\nEIS-ME AQUI, AJUDA-ME,\nAPROVADO QUERO SER.\n\n<coro tipo=''BIS''>\nFAZE-ME UM VENCEDOR,\nFAZE-ME, SENHOR,\nUM INSTRUMENTO PRA TEU LOUVOR.\n<final>AQUELE QUE É MAIS \nQUE VENCEDOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (386, 'QUAL O ADORNO DESTA VIDA?', 'QUAL O ADORNO DESTA VIDA?', 'QUAL O ADORNO DESTA VIDA?\nÉ O AMOR, É O AMOR;\nALEGRIA É CONCEDIDA\nPELO AMOR, PELO AMOR;\nÉ BENIGNO, É PACIENTE,\nNÃO SE TORNA MALDIZENTE, (BIS)\nESTE MEIGO AMOR.\n\nCOM SUSPEITAS NÃO SE ALCANÇA\nDOCE AMOR, DOCE AMOR;\nONDE HOUVER DESCONFIANÇA,\nAI DO AMOR, AI DO AMOR;\nPOIS AMEMOS A VERDADE,\nONDE REINA A FALSIDADE, (BIS)\nNÃO PERDURA O AMOR.\n\nNÃO TE IRRITES, MAS TOLERA\nCOM AMOR, COM AMOR;\nTUDO SOFRE, TUDO ESPERA\nPELO AMOR, PELO AMOR;\nPOIS MOSTREMOS TOLERÂNCIA,\nMUITAS VEZES A ARROGÂNCIA, (BIS)\nMURCHA E MATA O AMOR.\n\nÓ CRISTÃO, AO TEU VIZINHO\nMOSTRA AMOR, MOSTRA AMOR;\nO VALOR NÃO É MESQUINHO\nDESTE AMOR, DESTE AMOR;\nO SUPREMO DEUS NOS AMA;\nCRISTO PARA O CÉU NOS CHAMA, (BIS)\nONDE REINA O AMOR!', 'QUAL O ADORNO DESTA VIDA?\nÉ O AMOR, É O AMOR;\nALEGRIA É CONCEDIDA\nPELO AMOR, PELO AMOR;\nÉ BENIGNO, É PACIENTE,\nNÃO SE TORNA MALDIZENTE, <bis>\nESTE MEIGO AMOR.\n\nCOM SUSPEITAS NÃO SE ALCANÇA\nDOCE AMOR, DOCE AMOR;\nONDE HOUVER DESCONFIANÇA,\nAI DO AMOR, AI DO AMOR;\nPOIS AMEMOS A VERDADE,\nONDE REINA A FALSIDADE, <bis>\nNÃO PERDURA O AMOR.\n\nNÃO TE IRRITES, MAS TOLERA\nCOM AMOR, COM AMOR;\nTUDO SOFRE, TUDO ESPERA\nPELO AMOR, PELO AMOR;\nPOIS MOSTREMOS TOLERÂNCIA,\nMUITAS VEZES A ARROGÂNCIA, <bis>\nMURCHA E MATA O AMOR.\n\nÓ CRISTÃO, AO TEU VIZINHO\nMOSTRA AMOR, MOSTRA AMOR;\nO VALOR NÃO É MESQUINHO\nDESTE AMOR, DESTE AMOR;\nO SUPREMO DEUS NOS AMA;\nCRISTO PARA O CÉU NOS CHAMA, <bis>\nONDE REINA O AMOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (387, 'SONDA-ME, Ó DEUS', 'SONDA-ME, Ó DEUS', 'SONDA-ME, Ó DEUS, \nPOIS VÊS MEU CORAÇÃO, \nPROVA-ME, Ó PAI, \nTE PEÇO EM ORAÇÃO;\nDE TODO O MAL LIBERTA-ME, \nSENHOR,TAMBÉM DA TRANSGRESSÃO \nQUE OCULTA FOR.\n\nTODO O MEU SER QUE JÁ NÃO CHAMO MEU, \nQUERO GASTÁ-LO NO SERVIÇO TEU;\nMINHAS PAIXÕES TU PODES DOMINAR,\nEU ME SUBMETO, EM MIM VEM SEMPRE ESTAR.\n\nLÁ DO ALTO CÉU O AVIVAMENTO VEM\nA COMEÇAR EM MIM E INDO ALÉM;\nO TEU PODER, TUAS BÊNÇÃOS, TEU FAVOR,\nCONCEDE AOS FILHOS TEUS, \nÓ PAI DE AMOR.', 'SONDA-ME, Ó DEUS, \nPOIS VÊS MEU CORAÇÃO, \nPROVA-ME, Ó PAI, \nTE PEÇO EM ORAÇÃO;\nDE TODO O MAL LIBERTA-ME, \nSENHOR,TAMBÉM DA TRANSGRESSÃO \nQUE OCULTA FOR.\n\nTODO O MEU SER QUE JÁ NÃO CHAMO MEU, \nQUERO GASTÁ-LO NO SERVIÇO TEU;\nMINHAS PAIXÕES TU PODES DOMINAR,\nEU ME SUBMETO, EM MIM VEM SEMPRE ESTAR.\n\nLÁ DO ALTO CÉU O AVIVAMENTO VEM\nA COMEÇAR EM MIM E INDO ALÉM;\nO TEU PODER, TUAS BÊNÇÃOS, TEU FAVOR,\nCONCEDE AOS FILHOS TEUS, \nÓ PAI DE AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (388, 'SÓ TU ÉS, SENHOR', 'SÓ TU ÉS, SENHOR', 'SÓ TU ÉS, SENHOR, SÓ TU ÉS, SENHOR,\nA RAZÃO DO MEU VIVER.\n\nSONDA, Ó PAI, TODO O MEU CORAÇÃO,\nFAZ-ME OUVIR TUA DOCE VOZ, SENHOR.\n\nCORO\nDO TEU SANTO ESPÍRITO EM MIM,\nÓ VEM TRANSBORDAR,\nVEM EM MIM REALIZAR\nTODO O TEU QUERER.\n\nVEM, Ó JESUS, \nDERRAMAR TUA PAZ,\nENCHE-ME DE GOZO, \nTUA LUZ ME SATISFAZ.\n\nCORO\nDO TEU SANTO ESPÍRITO EM MIM,\nÓ VEM TRANSBORDAR,\nVEM EM MIM REALIZAR\nTODO O TEU QUERER.\n\nFINAL: (2X)\nSEM TEU AMOR NÃO SEI VIVER, SENHOR;\nSEM TUA GRAÇA EU NÃO SOU FELIZ,\nPOIS TU ÉS TODA A RAZÃO\nE O SENTIDO DE VIVER.\n\nINSTRUMENTOS\n\nSÓ TU ÉS, SENHOR, \nSÓ TU ÉS, SENHOR,\nA RAZÃO DO MEU VIVER.', 'SÓ TU ÉS, SENHOR, SÓ TU ÉS, SENHOR,<bis>\nA RAZÃO DO MEU VIVER.<bis>\n\nSONDA, Ó PAI, TODO O MEU CORAÇÃO,\nFAZ-ME OUVIR TUA DOCE VOZ, SENHOR.\n\n<coro>\nDO TEU SANTO ESPÍRITO EM MIM,\nÓ VEM TRANSBORDAR,\nVEM EM MIM REALIZAR\nTODO O TEU QUERER.\n\nVEM, Ó JESUS, \nDERRAMAR TUA PAZ,\nENCHE-ME DE GOZO, \nTUA LUZ ME SATISFAZ.\n\n<coro>\nDO TEU SANTO ESPÍRITO EM MIM,\nÓ VEM TRANSBORDAR,\nVEM EM MIM REALIZAR\nTODO O TEU QUERER.\n\n\n<final>(<bis tipo=''2''>\nSEM TEU AMOR NÃO SEI VIVER, SENHOR;\nSEM TUA GRAÇA EU NÃO SOU FELIZ,<bis>\nPOIS TU ÉS TODA A RAZÃO<bis>\nE O SENTIDO DE VIVER.\n<instrumentos>\nSÓ TU ÉS, SENHOR, <bis>\nSÓ TU ÉS, SENHOR,<bis>\nA RAZÃO DO MEU VIVER.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (389, 'SENHOR, O QUE É A NOSSA VIDA?', 'SENHOR, O QUE É A NOSSA VIDA?', 'SENHOR, O QUE É A NOSSA VIDA?\nÉ COMO A VIGÍLIA DA NOITE:\nCOMO A RELVA, CEDO FLORESCE,\nMAS À TARDE MURCHA E PERECE, SENHOR!\n\nINSTRUMENTOS\n\nSENHOR, NOSSOS DIAS SE PASSAM,\nNOSSOS ANOS LOGO SE ACABAM;\nSÃO COMO BREVE PENSAMENTO,\nASSIM SÃO OS HOMENS NO TEMPO, SENHOR!\n\nINSTRUMENTOS\n\nCORO\nENSINA-NOS A CONTAR \nOS NOSSOS DIAS \nPARA QUE UM SÁBIO CORAÇÃO\nPOSSAMOS TER.\n\nINSTRUMENTOS\n\nSENHOR, DÁ-NOS UM NOVO DIA,\nSACIA-NOS DA ETERNA VIDA\nPARA QUE CANTEMOS DE JÚBILO;\nÓ PAI, ÉS O ETERNO REFÚGIO, SENHOR!\n\nINSTRUMENTOS\n\nCORO (2X)\nENSINA-NOS A CONTAR \nOS NOSSOS DIAS \nPARA QUE UM SÁBIO CORAÇÃO\nPOSSAMOS TER.\n\nINSTRUMENTOS\n\nFINAL: SENHOR!', 'SENHOR, O QUE É A NOSSA VIDA?\nÉ COMO A VIGÍLIA DA NOITE:\nCOMO A RELVA, CEDO FLORESCE,\nMAS À TARDE MURCHA E PERECE, SENHOR!\n<instrumentos>\n\n\nSENHOR, NOSSOS DIAS SE PASSAM,\nNOSSOS ANOS LOGO SE ACABAM;\nSÃO COMO BREVE PENSAMENTO,\nASSIM SÃO OS HOMENS NO TEMPO, SENHOR!\n<instrumentos>\n\n\n<coro>\nENSINA-NOS A CONTAR \nOS NOSSOS DIAS \nPARA QUE UM SÁBIO CORAÇÃO\nPOSSAMOS TER.\n<instrumentos>\n\n\nSENHOR, DÁ-NOS UM NOVO DIA,\nSACIA-NOS DA ETERNA VIDA\nPARA QUE CANTEMOS DE JÚBILO;\nÓ PAI, ÉS O ETERNO REFÚGIO, SENHOR!\n<instrumentos>\n\n\n<coro tipo=''2X''>\nENSINA-NOS A CONTAR \nOS NOSSOS DIAS \nPARA QUE UM SÁBIO CORAÇÃO\nPOSSAMOS TER.\n<instrumentos>\n<final>SENHOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (390, 'CANTAREI A MISERICÓRDIA', 'CANTAREI A MISERICÓRDIA', 'CANTAREI A MISERICÓRDIA E O JUÍZO A TI, \nSENHOR, CANTAREI;\nANDAREI NO CAMINHO RETO,\nQUANDO VIRÁS A MIM, Ó SENHOR?\n\nCORO\nNÃO POREI COISA MÁ DIANTE DE MIM,\nNEM A MENTIRA NEM O ENGANO SEGUIREI;\nSEI QUE NÃO SUPORTARÁS TODO O SOBERBO,\nGUARDA-ME, POIS, EM TI, SENHOR.\n\nO QUE ANDA RETAMENTE\nTE SERVIRÁ, OS FIÉIS TE PROCURARÃO;\nE ESTARÃO JUNTO DE TI\nEM TUA CASA, SENHOR, ETERNAMENTE.\n\nCORO\nNÃO POREI COISA MÁ DIANTE DE MIM,\nNEM A MENTIRA NEM O ENGANO SEGUIREI;\nSEI QUE NÃO SUPORTARÁS TODO O SOBERBO,\nGUARDA-ME, POIS, EM TI, SENHOR.', 'CANTAREI A MISERICÓRDIA E O JUÍZO A TI, \nSENHOR, CANTAREI;\nANDAREI NO CAMINHO RETO,\nQUANDO VIRÁS A MIM, Ó SENHOR?\n\n<coro>\nNÃO POREI COISA MÁ DIANTE DE MIM,\nNEM A MENTIRA NEM O ENGANO SEGUIREI;\nSEI QUE NÃO SUPORTARÁS TODO O SOBERBO,\nGUARDA-ME, POIS, EM TI, SENHOR.\n\nO QUE ANDA RETAMENTE\nTE SERVIRÁ, OS FIÉIS TE PROCURARÃO;\nE ESTARÃO JUNTO DE TI\nEM TUA CASA, SENHOR, ETERNAMENTE.\n\n<coro>\nNÃO POREI COISA MÁ DIANTE DE MIM,\nNEM A MENTIRA NEM O ENGANO SEGUIREI;\nSEI QUE NÃO SUPORTARÁS TODO O SOBERBO,\nGUARDA-ME, POIS, EM TI, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (391, 'CANTAREI A BONDADE E A JUSTIÇA', 'CANTAREI A BONDADE E A JUSTIÇA', 'CANTAREI A BONDADE E A JUSTIÇA, \nA TI, SENHOR,\nCANTAREI, CANTAREI, CANTAREI,\nCANTAREI, CANTAREI.\n\nATENTAREI SABIAMENTE\nAO TEU CAMINHO, SENHOR,\nATENTAREI, ATENTAREI;\nÓ, QUANDO VIRÁS TER COMIGO, SENHOR?\nÓ, QUANDO, SENHOR?\nMAS CANTAREI, CANTAREI\nCANTAREI, CANTAREI. BIS NO FINAL', 'CANTAREI A BONDADE E A JUSTIÇA, \nA TI, SENHOR,\nCANTAREI, CANTAREI, CANTAREI,\nCANTAREI, CANTAREI.\n\nATENTAREI SABIAMENTE<bis>\nAO TEU CAMINHO, SENHOR,<bis>\nATENTAREI, ATENTAREI;<bis>\nÓ, QUANDO VIRÁS TER COMIGO, SENHOR?<bis>\nÓ, QUANDO, SENHOR?<bis>\nMAS CANTAREI, CANTAREI<bis>\nCANTAREI, CANTAREI. <bis tipo=''NO FINAL''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (392, 'EU SÓ QUERO SER SENHOR', 'EU SÓ QUERO SER SENHOR', 'EU SÓ QUERO SER, SENHOR,\nUM REMIDO DO TEU GRANDE AMOR;\nQUERO SÓ ANDAR NA LUZ\nE NO CÉU A CONTEMPLAR JESUS;\nPOIS NA CRUZ ELE MORREU\nE O SEU SANGUE ASSIM VERTEU POR MIM;\nQUANTO EU AMO AO MEU SENHOR,\nMEU ETERNO SALVADOR, JESUS.\n\nEU SÓ QUERO TER\nUM LUGAR NO CÉU, SENHOR;\nESTENDE A TUA MÃO,\nDERRAMA O TEU PODER EM \nMIM; OUVIR A TUA VOZ\nALMEJA O MEU CORAÇÃO,\nEU SÓ QUERO SERVIR A TI.\n\nEU SÓ QUERO SER, SENHOR,\nUM REMIDO DO TEU GRANDE AMOR;\nQUERO SÓ ANDAR NA LUZ\nE NO CÉU A CONTEMPLAR JESUS;\nPOIS NA CRUZ ELE MORREU\nE O SEU SANGUE ASSIM VERTEU POR MIM;\nQUANTO EU AMO AO MEU SENHOR,\nMEU ETERNO SALVADOR, JESUS.\n\nEU SÓ QUERO TER\nUM LUGAR NO CÉU, SENHOR;\nESTENDE A TUA MÃO,\nDERRAMA O TEU PODER EM \nMIM; OUVIR A TUA VOZ\nALMEJA O MEU CORAÇÃO,\nEU SÓ QUERO SERVIR A TI.\n\nEU SÓ QUERO TER\nUM LUGAR NO CÉU, SENHOR;\nESTENDE A TUA MÃO,\nDERRAMA O TEU PODER EM \nMIM; OUVIR A TUA VOZ\nALMEJA O MEU CORAÇÃO,\nEU SÓ QUERO SERVIR A TI.\n\nFINAL: EU SÓ QUERO SERVIR A TI.', 'EU SÓ QUERO SER, SENHOR,\nUM REMIDO DO TEU GRANDE AMOR;\nQUERO SÓ ANDAR NA LUZ\nE NO CÉU A CONTEMPLAR JESUS;\nPOIS NA CRUZ ELE MORREU\nE O SEU SANGUE ASSIM VERTEU POR MIM;\nQUANTO EU AMO AO MEU SENHOR,\nMEU ETERNO SALVADOR, JESUS.\n\nEU SÓ QUERO TER\nUM LUGAR NO CÉU, SENHOR;\nESTENDE A TUA MÃO,\nDERRAMA O TEU PODER EM \nMIM; OUVIR A TUA VOZ\nALMEJA O MEU CORAÇÃO,\nEU SÓ QUERO SERVIR A TI.\n\nEU SÓ QUERO SER, SENHOR,\nUM REMIDO DO TEU GRANDE AMOR;\nQUERO SÓ ANDAR NA LUZ\nE NO CÉU A CONTEMPLAR JESUS;\nPOIS NA CRUZ ELE MORREU\nE O SEU SANGUE ASSIM VERTEU POR MIM;\nQUANTO EU AMO AO MEU SENHOR,\nMEU ETERNO SALVADOR, JESUS.\n\nEU SÓ QUERO TER\nUM LUGAR NO CÉU, SENHOR;\nESTENDE A TUA MÃO,\nDERRAMA O TEU PODER EM \nMIM; OUVIR A TUA VOZ\nALMEJA O MEU CORAÇÃO,\nEU SÓ QUERO SERVIR A TI.\n\nEU SÓ QUERO TER\nUM LUGAR NO CÉU, SENHOR;\nESTENDE A TUA MÃO,\nDERRAMA O TEU PODER EM \nMIM; OUVIR A TUA VOZ\nALMEJA O MEU CORAÇÃO,\nEU SÓ QUERO SERVIR A TI.\n<final>EU SÓ QUERO SERVIR A TI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (393, 'QUERO SER FIEL AO MEU SENHOR', 'QUERO SER FIEL AO MEU SENHOR', 'QUERO SER FIEL AO MEU SENHOR,\nSEGUIR COMO ENSINOU ESTE CAMINHO,\nLEVAR ESTA MENSAGEM DE AMOR,\nSEGUIR AO SALVADOR.\n\nCORO\nQUERO TER A PAZ QUE CRISTO DÁ,\nSENTIR O SEU AMOR POR MIM ASSIM,\nNÃO TEMER A LUTA QUE VIER,\nSENHOR, AJUDA-ME.\n\nE QUANDO ME ENCONTRAR AFLITO ASSIM, \nLEMBRAR QUE MEU JESUS\nTANTO SOFREU POR MIM,\nE VIVO ANSIOSO A ESPERAR\nMORAR LÁ NO PORVIR.\n\nCORO (2X)\nQUERO TER A PAZ QUE CRISTO DÁ,\nSENTIR O SEU AMOR POR MIM ASSIM,\nNÃO TEMER A LUTA QUE VIER,\nSENHOR, AJUDA-ME.\n\nFINAL: SENHOR, AJUDA-ME.', 'QUERO SER FIEL AO MEU SENHOR,\nSEGUIR COMO ENSINOU ESTE CAMINHO,\nLEVAR ESTA MENSAGEM DE AMOR,\nSEGUIR AO SALVADOR.\n\n<coro>\nQUERO TER A PAZ QUE CRISTO DÁ,\nSENTIR O SEU AMOR POR MIM ASSIM,\nNÃO TEMER A LUTA QUE VIER,\nSENHOR, AJUDA-ME.\n\nE QUANDO ME ENCONTRAR AFLITO ASSIM, \nLEMBRAR QUE MEU JESUS\nTANTO SOFREU POR MIM,\nE VIVO ANSIOSO A ESPERAR\nMORAR LÁ NO PORVIR.\n\n<coro tipo=''2X''>\nQUERO TER A PAZ QUE CRISTO DÁ,\nSENTIR O SEU AMOR POR MIM ASSIM,\nNÃO TEMER A LUTA QUE VIER,\nSENHOR, AJUDA-ME.\n<final>SENHOR, AJUDA-ME.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (394, 'UMA VOZ ME DISSE LÁ DO CÉU', 'UMA VOZ ME DISSE LÁ DO CÉU', 'UMA VOZ ME DISSE LÁ DO CÉU:\n''CANTA, CANTA, CANTA PARA MIM;\nORA, ORA, ORA UMA VEZ MAIS,\nSEGUE, SEGUE, SEGUE APÓS MIM;\nÓ VEM SER FIEL ATÉ À MORTE,\nE EU SEREI CONTIGO ATÉ O FIM;\nLOGO ESTARÁS AQUI NO CÉU\nONDE TENS UMA COROA\nPREPARADA PARA TI''.', 'UMA VOZ ME DISSE LÁ DO CÉU:\n''CANTA, CANTA, CANTA PARA MIM;\nORA, ORA, ORA UMA VEZ MAIS,\nSEGUE, SEGUE, SEGUE APÓS MIM;\nÓ VEM SER FIEL ATÉ À MORTE,\nE EU SEREI CONTIGO ATÉ O FIM;\nLOGO ESTARÁS AQUI NO CÉU<bis>\nONDE TENS UMA COROA<bis>\nPREPARADA PARA TI''. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (395, 'FALA, JESUS QUERIDO', 'FALA, JESUS QUERIDO', 'FALA, JESUS QUERIDO, FALA-ME, HOJE, SIM!\nFALA COM TUA BONDADE, FICA BEM JUNTO A MIM;\nMEU CORAÇÃO ABERTO ESTÁ PRA TUA VOZ OUVIR,\nENCHE-ME DE LOUVORES E GOZO PRA TE SERVIR.\n\nCORO\nFALA-ME SUAVEMENTE! FALA COM MUITO AMOR!\nVENCEDOR PARA SEMPRE, LIVRE TE HEI DE PÔR;\nFALA-ME CADA DIA, SEMPRE EM TERNO TOM;\nOUVIR TUA VOZ EU QUERO E NESTE MESMO SOM.\n\nPARA TEUS FILHOS FALA, E, NO CAMINHO BOM,\nPELA BONDADE OS GUIA A PEDIR O SANTO DOM;\nQUERERÃO CONSAGRAR-SE PARA SUAS VIDAS DAR,\nOBEDECENDO A CRISTO E COM FERVOR O AMAR.\n\nCORO\nFALA-ME SUAVEMENTE! FALA COM MUITO AMOR!\nVENCEDOR PARA SEMPRE, LIVRE TE HEI DE PÔR;\nFALA-ME CADA DIA, SEMPRE EM TERNO TOM;\nOUVIR TUA VOZ EU QUERO E NESTE MESMO SOM.\n\nCOMO NO TEMPO ANTIGO, TU REVELASTE A LEI,\nMOSTRA-ME TUA VONTADE E À TUA SANTA GREI;\nDEIXA-ME GLORIAR-TE, QUERO A TI LOUVAR,\nCANTAR ALEGREMENTE E SEMPRE TE HONRAR.\n\nCORO\nFALA-ME SUAVEMENTE! FALA COM MUITO AMOR!\nVENCEDOR PARA SEMPRE, LIVRE TE HEI DE PÔR;\nFALA-ME CADA DIA, SEMPRE EM TERNO TOM;\nOUVIR TUA VOZ EU QUERO E NESTE MESMO SOM.', 'FALA, JESUS QUERIDO, FALA-ME, HOJE, SIM!\nFALA COM TUA BONDADE, FICA BEM JUNTO A MIM;\nMEU CORAÇÃO ABERTO ESTÁ PRA TUA VOZ OUVIR,\nENCHE-ME DE LOUVORES E GOZO PRA TE SERVIR.\n\n<coro>\nFALA-ME SUAVEMENTE! FALA COM MUITO AMOR!\nVENCEDOR PARA SEMPRE, LIVRE TE HEI DE PÔR;\nFALA-ME CADA DIA, SEMPRE EM TERNO TOM;\nOUVIR TUA VOZ EU QUERO E NESTE MESMO SOM.\n\nPARA TEUS FILHOS FALA, E, NO CAMINHO BOM,\nPELA BONDADE OS GUIA A PEDIR O SANTO DOM;\nQUERERÃO CONSAGRAR-SE PARA SUAS VIDAS DAR,\nOBEDECENDO A CRISTO E COM FERVOR O AMAR.\n\n<coro>\nFALA-ME SUAVEMENTE! FALA COM MUITO AMOR!\nVENCEDOR PARA SEMPRE, LIVRE TE HEI DE PÔR;\nFALA-ME CADA DIA, SEMPRE EM TERNO TOM;\nOUVIR TUA VOZ EU QUERO E NESTE MESMO SOM.\n\nCOMO NO TEMPO ANTIGO, TU REVELASTE A LEI,\nMOSTRA-ME TUA VONTADE E À TUA SANTA GREI;\nDEIXA-ME GLORIAR-TE, QUERO A TI LOUVAR,\nCANTAR ALEGREMENTE E SEMPRE TE HONRAR.\n\n<coro>\nFALA-ME SUAVEMENTE! FALA COM MUITO AMOR!\nVENCEDOR PARA SEMPRE, LIVRE TE HEI DE PÔR;\nFALA-ME CADA DIA, SEMPRE EM TERNO TOM;\nOUVIR TUA VOZ EU QUERO E NESTE MESMO SOM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (396, 'ABBA PAI', 'ABBA PAI', 'ABBA PAI, \nFAZE-ME SER SOMENTE TEU,\nMEUS DESEJOS POSSAM \nSER MAIS E MAIS OS TEUS.\nNUNCA A MINHA VIDA ESFRIE,\nNUNCA ME DEIXES CAIR!\nABBA PAI, FAZE-ME SER\nSOMENTE TEU.', 'ABBA PAI, \nFAZE-ME SER SOMENTE TEU,\nMEUS DESEJOS POSSAM \nSER MAIS E MAIS OS TEUS.\nNUNCA A MINHA VIDA ESFRIE,\nNUNCA ME DEIXES CAIR!\nABBA PAI, FAZE-ME SER\nSOMENTE TEU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (397, 'HÁ UMA LUZ A BRILHAR', 'HÁ UMA LUZ A BRILHAR', 'HÁ UMA LUZ A BRILHAR,\nUMA ESTRELA A CINTILAR\nGUIANDO O CRENTE EM JESUS;\nHÁ UMA VOZ A SOAR\nPELOS SÉCULOS SEM CESSAR,\nQUE À VIDA ETERNA CONDUZ.\n\nCORO\nOH! EU QUERO ANDAR NESSA LUZ DIVINAL, \nNA REVELAÇÃO QUE VEM DESDE OS CÉUS;\nSÓ ASSIM VIVEREI, NÃO NO TEMPO MORTAL, \nMAS NA ETERNIDADE DE DEUS.\n\nNÃO MAIS PELA RAZÃO QUE DITAR MEU CORAÇÃO, \nMAS POR TUA PALAVRA IREI;\nSEJA MEU TEU QUERER, MINHA MENTE A DE JESUS, \nNO TEMPO DE DEUS VIVEREI.\n\nCORO\nOH! EU QUERO ANDAR NESSA LUZ DIVINAL, \nNA REVELAÇÃO QUE VEM DESDE OS CÉUS;\nSÓ ASSIM VIVEREI, NÃO NO TEMPO MORTAL, \nMAS NA ETERNIDADE DE DEUS.\n\nFINAL: \nSÓ ASSIM VIVEREI,\nNÃO NO TEMPO MORTAL,\nMAS NA ETERNIDADE DE DEUS.', 'HÁ UMA LUZ A BRILHAR,\nUMA ESTRELA A CINTILAR\nGUIANDO O CRENTE EM JESUS;\nHÁ UMA VOZ A SOAR\nPELOS SÉCULOS SEM CESSAR,\nQUE À VIDA ETERNA CONDUZ.\n\n<coro>\nOH! EU QUERO ANDAR NESSA LUZ DIVINAL, \nNA REVELAÇÃO QUE VEM DESDE OS CÉUS;\nSÓ ASSIM VIVEREI, NÃO NO TEMPO MORTAL, \nMAS NA ETERNIDADE DE DEUS.\n\nNÃO MAIS PELA RAZÃO QUE DITAR MEU CORAÇÃO, \nMAS POR TUA PALAVRA IREI;\nSEJA MEU TEU QUERER, MINHA MENTE A DE JESUS, \nNO TEMPO DE DEUS VIVEREI.\n\n<coro>\nOH! EU QUERO ANDAR NESSA LUZ DIVINAL, \nNA REVELAÇÃO QUE VEM DESDE OS CÉUS;\nSÓ ASSIM VIVEREI, NÃO NO TEMPO MORTAL, \nMAS NA ETERNIDADE DE DEUS.\n\n\n<final>SÓ ASSIM VIVEREI,\nNÃO NO TEMPO MORTAL,\nMAS NA ETERNIDADE DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (398, 'ENTREI NO TEMPO DE DEUS', 'ENTREI NO TEMPO DE DEUS', 'ENTREI NO TEMPO DE DEUS,\nJÁ VIVO A ETERNIDADE,\nVOCÊ TAMBÉM PODE ENTRAR, (PODE ENTRAR)\nSER PARTICIPANTE COMO EU,\nO PAI LHE REVELARÁ A ETERNIDADE.\n\nO MEU TEMPO ERA CONTADO \nPARA A MORTE, MAS APROUVE \nAO PAI ENVIAR SEU FILHO\nE HOJE EU VIVO JÁ A ETERNIDADE.\n\nFINAL: A ETERNIDADE.', 'ENTREI NO TEMPO DE DEUS,<bis>\nJÁ VIVO A ETERNIDADE,<bis>\nVOCÊ TAMBÉM PODE ENTRAR, (PODE ENTRAR)<bis>\nSER PARTICIPANTE COMO EU,<bis>\nO PAI LHE REVELARÁ A ETERNIDADE.<bis>\n\nO MEU TEMPO ERA CONTADO <bis>\nPARA A MORTE, MAS APROUVE <bis>\nAO PAI ENVIAR SEU FILHO<bis>\nE HOJE EU VIVO JÁ A ETERNIDADE.<bis>\n<final>A ETERNIDADE.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (399, 'QUAL MADEIRA', 'QUAL MADEIRA', 'QUAL MADEIRA INÚTIL ASSIM, FUI PLANTADO,\nNO DESERTO DO MUNDO CRUEL FUI DEIXADO;\nMAS JESUS ME ENCONTROU E ME LIBERTOU \nDE UMA VIDA VAZIA, SEM PAZ, SEM AMOR.\n\nINSTRUMENTOS\n\nDE MINH''ALMA TIROU O MEU FARDO TÃO PESADO,\nQUAL A CASCA NA DURA MADEIRA, MEU PECADO.\nTRABALHOU-ME POR INTEIRO,\nCOMO UM BOM CARPINTEIRO,\nFEZ-ME VASO DE HONRA,\nDE GLÓRIA E LOUVOR.', 'QUAL MADEIRA INÚTIL ASSIM, FUI PLANTADO,\nNO DESERTO DO MUNDO CRUEL FUI DEIXADO;\nMAS JESUS ME ENCONTROU E ME LIBERTOU \nDE UMA VIDA VAZIA, SEM PAZ, SEM AMOR.\n<instrumentos>\n\n\nDE MINH''ALMA TIROU O MEU FARDO TÃO PESADO,\nQUAL A CASCA NA DURA MADEIRA, MEU PECADO.\nTRABALHOU-ME POR INTEIRO,<bis>\nCOMO UM BOM CARPINTEIRO,<bis>\nFEZ-ME VASO DE HONRA,<bis>\nDE GLÓRIA E LOUVOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (400, 'EU QUERO SER, SENHOR AMADO', 'EU QUERO SER, SENHOR AMADO', 'EU QUERO SER, SENHOR AMADO,\nCOMO UM VASO NAS MÃOS DO OLEIRO;\nQUEBRA A MINHA VIDA E FAZE-A DE NOVO, \nEU QUERO SER, EU QUERO SER,\nUM VASO NOVO.', 'EU QUERO SER, SENHOR AMADO,\nCOMO UM VASO NAS MÃOS DO OLEIRO;\nQUEBRA A MINHA VIDA E FAZE-A DE NOVO, \nEU QUERO SER, EU QUERO SER,\nUM VASO NOVO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (401, 'COMO TU QUERES', 'COMO TU QUERES', 'COMO TU QUERES, SENHOR, SOU TEU\nTU ÉS OLEIRO, VASO SOU EU;\nQUEBRA E TRANSFORMA ATÉ QUE, \nENFIM TUA VONTADE SE CUMPRA EM MIM.', 'COMO TU QUERES, SENHOR, SOU TEU\nTU ÉS OLEIRO, VASO SOU EU;\nQUEBRA E TRANSFORMA ATÉ QUE, \nENFIM TUA VONTADE SE CUMPRA EM MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (402, 'A LEI DO SENHOR É PERFEITA', 'A LEI DO SENHOR É PERFEITA', 'A LEI DO SENHOR É PERFEITA\nE RESTAURA A ALMA;\nO TESTEMUNHO DO SENHOR É FIEL\nE DÁ SABEDORIA AOS SÍMPLICES.\n\nCORO\nSÃO MAIS DESEJÁVEIS\nDO QUE O OURO DEPURADO,\nSÃO MAIS DOCES DO QUE O MEL\nE O DESTILAR DOS FAVOS.\n\nOS PRECEITOS DO SENHOR SÃO RETOS\nE ALEGRAM O CORAÇÃO;\nO MANDAMENTO DO SENHOR É PURO\nE ILUMINA OS OLHOS.\n\nCORO\nSÃO MAIS DESEJÁVEIS\nDO QUE O OURO DEPURADO,\nSÃO MAIS DOCES DO QUE O MEL\nE O DESTILAR DOS FAVOS.\n\nO TEMOR DO SENHOR É LÍMPIDO\nE PERMANECE PARA SEMPRE;\nOS JUÍZOS DO SENHOR SÃO VERDADEIROS\nE TODOS IGUALMENTE JUSTOS.\n\nCORO\nSÃO MAIS DESEJÁVEIS\nDO QUE O OURO DEPURADO,\nSÃO MAIS DOCES DO QUE O MEL\nE O DESTILAR DOS FAVOS.', 'A LEI DO SENHOR É PERFEITA\nE RESTAURA A ALMA;\nO TESTEMUNHO DO SENHOR É FIEL\nE DÁ SABEDORIA AOS SÍMPLICES.\n\n<coro>\nSÃO MAIS DESEJÁVEIS\nDO QUE O OURO DEPURADO,\nSÃO MAIS DOCES DO QUE O MEL\nE O DESTILAR DOS FAVOS.\n\nOS PRECEITOS DO SENHOR SÃO RETOS\nE ALEGRAM O CORAÇÃO;\nO MANDAMENTO DO SENHOR É PURO\nE ILUMINA OS OLHOS.\n\n<coro>\nSÃO MAIS DESEJÁVEIS\nDO QUE O OURO DEPURADO,\nSÃO MAIS DOCES DO QUE O MEL\nE O DESTILAR DOS FAVOS.\n\nO TEMOR DO SENHOR É LÍMPIDO\nE PERMANECE PARA SEMPRE;\nOS JUÍZOS DO SENHOR SÃO VERDADEIROS\nE TODOS IGUALMENTE JUSTOS.\n\n<coro>\nSÃO MAIS DESEJÁVEIS\nDO QUE O OURO DEPURADO,\nSÃO MAIS DOCES DO QUE O MEL\nE O DESTILAR DOS FAVOS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (403, 'AQUELE QUE TEM OS MEUS MANDAMENTOS', 'AQUELE QUE TEM OS MEUS MANDAMENTOS', 'AQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA. \nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA. \n\nE AQUELE QUE ME AMA\nSERÁ AMADO POR MEU PAI,\nE EU TAMBÉM O AMAREI,\nE ME MANIFESTAREI A ELE.\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA.\n\nINSTRUMENTOS\n\nE AQUELE QUE ME AMA\nSERÁ AMADO POR MEU PAI,\nE EU TAMBÉM O AMAREI,\nE ME MANIFESTAREI A ELE.\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA.\n\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA.\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA. \n\nFINAL: ESSE É O QUE ME AMA. (BIS)', 'AQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA. \nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA. \n\nE AQUELE QUE ME AMA\nSERÁ AMADO POR MEU PAI,\nE EU TAMBÉM O AMAREI,\nE ME MANIFESTAREI A ELE.\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA.\n<instrumentos>\n\n\nE AQUELE QUE ME AMA\nSERÁ AMADO POR MEU PAI,\nE EU TAMBÉM O AMAREI,\nE ME MANIFESTAREI A ELE.\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA.\n\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA.\nAQUELE QUE TEM OS MEUS MANDAMENTOS \nE OS GUARDA, ESSE É O QUE ME AMA. \n<final>ESSE É O QUE ME AMA. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (404, 'JESUS, QUERO AMAR-TE', 'JESUS, QUERO AMAR-TE', 'JESUS, QUERO AMAR-TE ATÉ MORRER\nQUERO SEGUIR-TE EM MEU VIVER,\nPARA O CÉU DE AMOR GANHAR. \n\nCORO (2X)\nOH! ALELUIA, AMÉM, AMÉM! (3X)\nSENHOR!\n\nJESUS, TODO O MEU SER QUERO TE DAR,\nSE FOR PRECISO ATÉ MORRER \nPARA O CÉU DE AMOR GANHAR;\nPARA TE DEDICAR AQUILO \nQUE ME CONCEDESTE \nE A TUA OBRA REALIZAR.\n\nCORO (2X)\nOH! ALELUIA, AMÉM, AMÉM! (3X)\nSENHOR!', 'JESUS, QUERO AMAR-TE ATÉ MORRER<bis>\nQUERO SEGUIR-TE EM MEU VIVER,<bis>\nPARA O CÉU DE AMOR GANHAR.<coro tipo=''2X''>\nOH! ALELUIA, AMÉM, AMÉM! <bis tipo=''3''>\nSENHOR!\n\nJESUS, TODO O MEU SER QUERO TE DAR,\nSE FOR PRECISO ATÉ MORRER \nPARA O CÉU DE AMOR GANHAR;\nPARA TE DEDICAR AQUILO \nQUE ME CONCEDESTE \nE A TUA OBRA REALIZAR.<coro tipo=''2X''>\nOH! ALELUIA, AMÉM, AMÉM! <bis tipo=''3''>\nSENHOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (405, 'AMO AO SENHOR DE TODO O MEU CORAÇÃO', 'AMO AO SENHOR DE TODO O MEU CORAÇÃO', 'AMO AO SENHOR DE TODO O MEU CORAÇÃO;\nNA PRESENÇA DE TODOS OS POVOS\nA TI, SENHOR, LOUVAREI.\n\nA TI SERVIREI, SIM, SERVIREI,\nENQUANTO EU VIVER, SENHOR,\nA TI SERVIREI.\n\nNÃO ME DEIXES CAIR,\nSEGURA EM MINHAS MÃOS,\nFAZE DE MIM UM VENCEDOR\nPRA QUE EU POSSA TE LOUVAR.\n\nA TI LOUVAREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI LOUVAREI;\nA TI SERVIREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI SERVIREI, SERVIREI.\n\nINSTRUMENTOS\n\nA TI LOUVAREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI LOUVAREI;\nA TI SERVIREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI SERVIREI, SERVIREI.', 'AMO AO SENHOR DE TODO O MEU CORAÇÃO;\nNA PRESENÇA DE TODOS OS POVOS\nA TI, SENHOR, LOUVAREI.\n\nA TI SERVIREI, SIM, SERVIREI,\nENQUANTO EU VIVER, SENHOR,\nA TI SERVIREI.\n\nNÃO ME DEIXES CAIR,\nSEGURA EM MINHAS MÃOS,\nFAZE DE MIM UM VENCEDOR\nPRA QUE EU POSSA TE LOUVAR.\n\nA TI LOUVAREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI LOUVAREI;\nA TI SERVIREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI SERVIREI, SERVIREI.\n<instrumentos>\n\n\nA TI LOUVAREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI LOUVAREI;\nA TI SERVIREI, SIM, LOUVAREI,\nENQUANTO EU VIVER, SENHOR,\nA TI SERVIREI, SERVIREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (406, 'JESUS, O QUE MAIS QUERO NO MUNDO', 'JESUS, O QUE MAIS QUERO NO MUNDO', 'JESUS, O QUE EU MAIS QUERO \nNO MUNDO É VIVER PARA TI, \nTE SERVIR POIS FIZESTE JÁ TUDO POR MIM;\nMINHA VIDA MUDASTE E TEU AMOR ME MOSTRASTE, \nMUITAS COISAS EU PUDE, ENTÃO, VER, \nGRANDE AMOR INUNDOU O MEU SER, \nNÃO REJEITASTE O MEU CORAÇÃO \nQUANDO CURVEI-ME A TI EM ORAÇÃO.\n\nCORO\nTUDO NA VIDA DEPENDE DE FÉ,\nDE CONFIARMOS EM TI, COMO ÉS;\nSEMPRE ME GUIAS, ÉS DEUS DE AMOR;\nCRISTO, ÉS TUDO PARA MIM.\n\nINSTRUMENTOS\n\nCORO\nTUDO NA VIDA DEPENDE DE FÉ,\nDE CONFIARMOS EM TI, COMO ÉS;\nSEMPRE ME GUIAS, ÉS DEUS DE AMOR;\nCRISTO, ÉS TUDO PARA MIM.\n\nFINAL: CRISTO, ÉS TUDO PARA MIM.', 'JESUS, O QUE EU MAIS QUERO \nNO MUNDO É VIVER PARA TI, \nTE SERVIR POIS FIZESTE JÁ TUDO POR MIM;\nMINHA VIDA MUDASTE E TEU AMOR ME MOSTRASTE, \nMUITAS COISAS EU PUDE, ENTÃO, VER, \nGRANDE AMOR INUNDOU O MEU SER, \nNÃO REJEITASTE O MEU CORAÇÃO \nQUANDO CURVEI-ME A TI EM ORAÇÃO.\n\n<coro>\nTUDO NA VIDA DEPENDE DE FÉ,\nDE CONFIARMOS EM TI, COMO ÉS;\nSEMPRE ME GUIAS, ÉS DEUS DE AMOR;\nCRISTO, ÉS TUDO PARA MIM.\n<instrumentos>\n\n\n<coro>\nTUDO NA VIDA DEPENDE DE FÉ,\nDE CONFIARMOS EM TI, COMO ÉS;\nSEMPRE ME GUIAS, ÉS DEUS DE AMOR;\nCRISTO, ÉS TUDO PARA MIM.\n<final>CRISTO, ÉS TUDO PARA MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (407, 'EU VI O SENHOR', 'EU VI O SENHOR', 'EU VI O SENHOR NUM ALTO E SUBLIME TRONO\nE AS ABAS DE SUAS VESTES ENCHIAM O TEMPLO;\nOS ANJOS VOAVAM POR SOBRE O SEU TRONO, COBRIAM O ROSTO E OS PÉS,\nUNS AOS OUTROS CLAMAVAM:\n\nCORO (2X)\nSANTO, SANTO, SANTO,\nÉ O SENHOR DOS EXÉRCITOS,\nTODA A TERRA ESTÁ CHEIA \nDA SUA GLÓRIA!\n\nINSTRUMENTOS\n\nENTÃO DISSE EU: SOU UM HOMEM IMPURO \nE OS MEUS OLHOS VIRAM O REI, \nO SENHOR DOS EXÉRCITOS!\nCOM UMA BRASA DO ALTAR\nOS MEUS LÁBIOS FORAM TOCADOS,\nMEU PECADO FOI PERDOADO \nE OUVI A VOZ DO SENHOR:\n\n''A QUEM ENVIAREI, \nE QUEM HÁ DE IR POR NÓS?''\nDISSE EU: EIS-ME AQUI, \nENVIA-ME A MIM.\n\nCORO (2X)\nSANTO, SANTO, SANTO,\nÉ O SENHOR DOS EXÉRCITOS,\nTODA A TERRA ESTÁ CHEIA \nDA SUA GLÓRIA!', 'EU VI O SENHOR NUM ALTO E SUBLIME TRONO\nE AS ABAS DE SUAS VESTES ENCHIAM O TEMPLO;\nOS ANJOS VOAVAM POR SOBRE O SEU TRONO, COBRIAM O ROSTO E OS PÉS,\nUNS AOS OUTROS CLAMAVAM:\n\n<coro tipo=''2X''>\nSANTO, SANTO, SANTO,\nÉ O SENHOR DOS EXÉRCITOS,\nTODA A TERRA ESTÁ CHEIA \nDA SUA GLÓRIA!\n<instrumentos>\n\n\nENTÃO DISSE EU: SOU UM HOMEM IMPURO \nE OS MEUS OLHOS VIRAM O REI, \nO SENHOR DOS EXÉRCITOS!\nCOM UMA BRASA DO ALTAR\nOS MEUS LÁBIOS FORAM TOCADOS,\nMEU PECADO FOI PERDOADO \nE OUVI A VOZ DO SENHOR:\n\n''A QUEM ENVIAREI, <bis>\nE QUEM HÁ DE IR POR NÓS?''<bis>\nDISSE EU: EIS-ME AQUI, <bis>\nENVIA-ME A MIM.<bis>\n\n<coro tipo=''2X''>\nSANTO, SANTO, SANTO,\nÉ O SENHOR DOS EXÉRCITOS,\nTODA A TERRA ESTÁ CHEIA \nDA SUA GLÓRIA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (408, 'EIS QUE SURGE UM POVO FORTE', 'EIS QUE SURGE UM POVO FORTE', 'EIS QUE SURGE UM POVO FORTE,\nREVESTIDO DE PODER;\nE NÃO TEME NEM A MORTE,\nQUEM A ELE PERTENCER,\nE TERÁ SUBLIME SORTE,\nPOIS COM CRISTO AO CÉU VAI,\nPODES TU DIZER TAMBÉM:\nSOU UM DOS TAIS?\n\nCORO (2X)\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?\n\nNO CENÁCULO REUNIDOS, \nO PODER BUSCAVAM ENTÃO, \nPELO AMOR DE DEUS UNIDOS \nA CLAMAR EM ORAÇÃO;\nEIS QUE UM VENTO É DESCIDO \nE O FOGO DO CÉU CAI; \nPODES TU DIZER TAMBÉM:\nSOU UM DOS TAIS?\n\nCORO (2X)\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?\n\nESTE POVO DESTEMIDO, \nSÃO DISCÍPULOS DE JESUS \nPELO MUNDO PERSEGUIDO, \nPOR LEVAR A SUA CRUZ,\nE AGORA REVESTIDO COM PODER,\nAO MUNDO SAI; PODES TU DIZER TAMBÉM: \nSOU UM DOS TAIS?\n\nCORO (2X)\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?\n\nOH! NÃO SEJAS DESCUIDOSO \nPRA BUSCAR O DOM DE DEUS, \nDOM QUE TE FARÁ DITOSO, \nDAR-TE-Á VISÕES DO CÉU,\nE JESUS MARAVILHOSO \nPROCLAMANDO AOS OUTROS VAI; \nPODERÁS ENTÃO DIZER: \nSOU UM DOS TAIS.\n\nCORO (2X)\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?', 'EIS QUE SURGE UM POVO FORTE,\nREVESTIDO DE PODER;\nE NÃO TEME NEM A MORTE,\nQUEM A ELE PERTENCER,\nE TERÁ SUBLIME SORTE,\nPOIS COM CRISTO AO CÉU VAI,\nPODES TU DIZER TAMBÉM:\nSOU UM DOS TAIS?\n\n<coro tipo=''2X''>\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?\n\nNO CENÁCULO REUNIDOS, \nO PODER BUSCAVAM ENTÃO, \nPELO AMOR DE DEUS UNIDOS \nA CLAMAR EM ORAÇÃO;\nEIS QUE UM VENTO É DESCIDO \nE O FOGO DO CÉU CAI; \nPODES TU DIZER TAMBÉM:\nSOU UM DOS TAIS?\n\n<coro tipo=''2X''>\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?\n\nESTE POVO DESTEMIDO, \nSÃO DISCÍPULOS DE JESUS \nPELO MUNDO PERSEGUIDO, \nPOR LEVAR A SUA CRUZ,\nE AGORA REVESTIDO COM PODER,\nAO MUNDO SAI; PODES TU DIZER TAMBÉM: \nSOU UM DOS TAIS?\n\n<coro tipo=''2X''>\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?\n\nOH! NÃO SEJAS DESCUIDOSO \nPRA BUSCAR O DOM DE DEUS, \nDOM QUE TE FARÁ DITOSO, \nDAR-TE-Á VISÕES DO CÉU,\nE JESUS MARAVILHOSO \nPROCLAMANDO AOS OUTROS VAI; \nPODERÁS ENTÃO DIZER: \nSOU UM DOS TAIS.\n\n<coro tipo=''2X''>\nUM DOS TAIS, UM DOS TAIS,\nPODES TU TAMBÉM DIZER:\nSOU UM DOS TAIS?', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (409, 'EIS MARCHAMOS PARA AQUELE BOM PAÍS', 'EIS MARCHAMOS PARA AQUELE BOM PAÍS', 'EIS MARCHAMOS PARA AQUELE BOM PAÍS, \nONDE O CRENTE, SIM, \nÉ CRISTO QUEM O DIZ COM SEU SALVADOR, \nPRA SEMPRE ALI FELIZ, VAI COM ELE DESCANSAR;\n\nTRABALHEMOS POIS, COM ZELO E COM VIGOR, CONSTRANGIDOS PELO SEU IMENSO AMOR;\nTRABALHEMOS PELO NOSSO SALVADOR,\nEIS QUE A VIDA VAI FINDAR!\n\nCORO\nACORDAI! ACORDAI! DESPERTAI! DESPERTAI!\nE CANTAI! SIM, CANTAI! O SENHOR NÃO TARDARÁ!\nEIS MARCHAMOS PARA AQUELE BOM PAÍS,\nONDE O CRENTE SIM, É CRISTO QUEM O DIZ, \nCOM SEU SALVADOR, PRA SEMPRE ALI FELIZ, \nVAI COM ELE DESCANSAR.\n\nEIS CONOSCO NOSSO INSIGNE CAPITÃO\nQUE NOS ASSEGURA ETERNA SALVAÇÃO,\nEIS DA SANTA FÉ O INVICTO PAVILHÃO,\nVAMOS, VAMOS TRABALHAR!\nEIA, AVANTE! NADA TEMOS QUE TEMER,\nPOR JESUS HAVEMOS SEMPRE DE VENCER;\nTRABALHEMOS, POIS, ATÉ O AMANHECER\nE O TRABALHO AQUI FINDAR!\n\nCORO\nACORDAI! ACORDAI! DESPERTAI! DESPERTAI!\nE CANTAI! SIM, CANTAI! O SENHOR NÃO TARDARÁ!\nEIS MARCHAMOS PARA AQUELE BOM PAÍS,\nONDE O CRENTE SIM, É CRISTO QUEM O DIZ, \nCOM SEU SALVADOR, PRA SEMPRE ALI FELIZ, \nVAI COM ELE DESCANSAR.\n\nREVESTIDOS DA CONFIANÇA DE JESUS,\nCOMO SERVOS SEUS E FILHOS, SIM, DA LUZ,\nGLORIANDO-NOS EM CRISTO E SUA CRUZ,\nVAMOS, VAMOS TRABALHAR!\nOS PERDIDOS, VAMOS COM AMOR BUSCAR,\nAOS DESESPERADOS VAMOS DECLARAR\nQUE JESUS ESTÁ PRONTO TODOS A SALVAR!\nOH! SIM, VAMOS TRABALHAR!\n\nCORO\nACORDAI! ACORDAI! DESPERTAI! DESPERTAI!\nE CANTAI! SIM, CANTAI! O SENHOR NÃO TARDARÁ!\nEIS MARCHAMOS PARA AQUELE BOM PAÍS,\nONDE O CRENTE SIM, É CRISTO QUEM O DIZ, \nCOM SEU SALVADOR, PRA SEMPRE ALI FELIZ, \nVAI COM ELE DESCANSAR.', 'EIS MARCHAMOS PARA AQUELE BOM PAÍS, \nONDE O CRENTE, SIM, \nÉ CRISTO QUEM O DIZ COM SEU SALVADOR, \nPRA SEMPRE ALI FELIZ, VAI COM ELE DESCANSAR;\n\nTRABALHEMOS POIS, COM ZELO E COM VIGOR, CONSTRANGIDOS PELO SEU IMENSO AMOR;\nTRABALHEMOS PELO NOSSO SALVADOR,\nEIS QUE A VIDA VAI FINDAR!\n\n<coro>\nACORDAI! ACORDAI! DESPERTAI! DESPERTAI!\nE CANTAI! SIM, CANTAI! O SENHOR NÃO TARDARÁ!\nEIS MARCHAMOS PARA AQUELE BOM PAÍS,\nONDE O CRENTE SIM, É CRISTO QUEM O DIZ, \nCOM SEU SALVADOR, PRA SEMPRE ALI FELIZ, \nVAI COM ELE DESCANSAR.\n\nEIS CONOSCO NOSSO INSIGNE CAPITÃO\nQUE NOS ASSEGURA ETERNA SALVAÇÃO,\nEIS DA SANTA FÉ O INVICTO PAVILHÃO,\nVAMOS, VAMOS TRABALHAR!\nEIA, AVANTE! NADA TEMOS QUE TEMER,\nPOR JESUS HAVEMOS SEMPRE DE VENCER;\nTRABALHEMOS, POIS, ATÉ O AMANHECER\nE O TRABALHO AQUI FINDAR!\n\n<coro>\nACORDAI! ACORDAI! DESPERTAI! DESPERTAI!\nE CANTAI! SIM, CANTAI! O SENHOR NÃO TARDARÁ!\nEIS MARCHAMOS PARA AQUELE BOM PAÍS,\nONDE O CRENTE SIM, É CRISTO QUEM O DIZ, \nCOM SEU SALVADOR, PRA SEMPRE ALI FELIZ, \nVAI COM ELE DESCANSAR.\n\nREVESTIDOS DA CONFIANÇA DE JESUS,\nCOMO SERVOS SEUS E FILHOS, SIM, DA LUZ,\nGLORIANDO-NOS EM CRISTO E SUA CRUZ,\nVAMOS, VAMOS TRABALHAR!\nOS PERDIDOS, VAMOS COM AMOR BUSCAR,\nAOS DESESPERADOS VAMOS DECLARAR\nQUE JESUS ESTÁ PRONTO TODOS A SALVAR!\nOH! SIM, VAMOS TRABALHAR!\n\n<coro>\nACORDAI! ACORDAI! DESPERTAI! DESPERTAI!\nE CANTAI! SIM, CANTAI! O SENHOR NÃO TARDARÁ!\nEIS MARCHAMOS PARA AQUELE BOM PAÍS,\nONDE O CRENTE SIM, É CRISTO QUEM O DIZ, \nCOM SEU SALVADOR, PRA SEMPRE ALI FELIZ, \nVAI COM ELE DESCANSAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (410, 'UM PENDÃO REAL VOS ENTREGOU O REI', 'UM PENDÃO REAL VOS ENTREGOU O REI', 'UM PENDÃO REAL VOS ENTREGOU \nO REI A VÓS, SOLDADOS SEUS;\nCORAJOSOS, POIS, EM TUDO O DEFENDEI\nMARCHANDO PARA OS CÉUS.\n\nCORO\nCOM VALOR! SEM TEMOR!\nPOR CRISTO PRONTOS A SOFRER;\nBEM ALTO ERGUEI O SEU PENDÃO,\nFIRMES SEMPRE ATÉ MORRER!\n\nEIS FORMADOS JÁ OS NEGROS BATALHÕES\nDO GRANDE USURPADOR;\nDECLARAI-VOS, HOJE, \nBRAVOS CAMPEÕES, \nAVANTE, SEM TEMOR!\n\nCORO\nCOM VALOR! SEM TEMOR!\nPOR CRISTO PRONTOS A SOFRER;\nBEM ALTO ERGUEI O SEU PENDÃO,\nFIRMES SEMPRE ATÉ MORRER!\n\nQUEM RECEIO SENTE NO SEU CORAÇÃO \nE FRACO SE MOSTRAR,\nNÃO RECEBERÁ O ETERNO \nGALARDÃO QUE CRISTO TEM PRA DAR.\n\nCORO\nCOM VALOR! SEM TEMOR!\nPOR CRISTO PRONTOS A SOFRER;\nBEM ALTO ERGUEI O SEU PENDÃO,\nFIRMES SEMPRE ATÉ MORRER!\n\nPOIS SEJAMOS TODOS A JESUS \nLEAIS E AO SEU REAL PENDÃO;\nOS QUE NA BATALHA SEMPRE \nSÃO FIÉIS COM ELE REINARÃO.', 'UM PENDÃO REAL VOS ENTREGOU \nO REI A VÓS, SOLDADOS SEUS;\nCORAJOSOS, POIS, EM TUDO O DEFENDEI\nMARCHANDO PARA OS CÉUS.\n\n<coro>\nCOM VALOR! SEM TEMOR!\nPOR CRISTO PRONTOS A SOFRER;\nBEM ALTO ERGUEI O SEU PENDÃO,\nFIRMES SEMPRE ATÉ MORRER!\n\nEIS FORMADOS JÁ OS NEGROS BATALHÕES\nDO GRANDE USURPADOR;\nDECLARAI-VOS, HOJE, \nBRAVOS CAMPEÕES, \nAVANTE, SEM TEMOR!\n\n<coro>\nCOM VALOR! SEM TEMOR!\nPOR CRISTO PRONTOS A SOFRER;\nBEM ALTO ERGUEI O SEU PENDÃO,\nFIRMES SEMPRE ATÉ MORRER!\n\nQUEM RECEIO SENTE NO SEU CORAÇÃO \nE FRACO SE MOSTRAR,\nNÃO RECEBERÁ O ETERNO \nGALARDÃO QUE CRISTO TEM PRA DAR.\n\n<coro>\nCOM VALOR! SEM TEMOR!\nPOR CRISTO PRONTOS A SOFRER;\nBEM ALTO ERGUEI O SEU PENDÃO,\nFIRMES SEMPRE ATÉ MORRER!\n\nPOIS SEJAMOS TODOS A JESUS \nLEAIS E AO SEU REAL PENDÃO;\nOS QUE NA BATALHA SEMPRE \nSÃO FIÉIS COM ELE REINARÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (411, 'O SENHOR DA CEIFA ESTÁ CHAMANDO', 'O SENHOR DA CEIFA ESTÁ CHAMANDO', 'O SENHOR DA CEIFA ESTÁ CHAMANDO:\n''QUEM QUER IR POR MIM A PROCURAR\nALMAS QUE NO MUNDO VÃO CHORANDO\nSEM DA SALVAÇÃO PARTICIPAR?''\n\nCORO\nFALA DEUS! FALA DEUS!\nTOCA-ME COM BRASAS DO ALTAR;\nFALA DEUS! FALA DEUS!\nSIM, ALEGRE ATENDO AO TEU MANDAR.\n\nMUITOS SÃO OS QUE VÃO EXPIRANDO\nSEM TER ESPERANÇA DE VER DEUS;\nVAI, DEPRESSA, LHES ANUNCIANDO\nQUE JESUS OS LEVA PARA OS CÉUS.\n\nCORO\nFALA DEUS! FALA DEUS! \nTOCA-ME COM BRASAS DO ALTAR;\nFALA DEUS! FALA DEUS!\nSIM, ALEGRE ATENDO AO TEU MANDAR.\n\nO PROFETA A DEUS SE APROXIMANDO,\nCONSIDERA-SE UM PECADOR,\nMAS, O FOGO SANTO O QUEIMANDO,\nTORNA-O ÚTIL PARA SEU SENHOR.\n\nCORO\nFALA DEUS! FALA DEUS! \nTOCA-ME COM BRASAS DO ALTAR;\nFALA DEUS! FALA DEUS!\nSIM, ALEGRE ATENDO AO TEU MANDAR.\n\nBREVE OS TRABALHOS SERÃO FINDOS,\nBÊNÇÃOS VÃO OS SERVOS DESFRUTAR,\nE JESUS OS SAUDARÁ: ''BEM-VINDOS'',\nESTA GLÓRIA ESPERO ALCANÇAR!', 'O SENHOR DA CEIFA ESTÁ CHAMANDO:\n''QUEM QUER IR POR MIM A PROCURAR\nALMAS QUE NO MUNDO VÃO CHORANDO\nSEM DA SALVAÇÃO PARTICIPAR?''\n\n<coro>\nFALA DEUS! FALA DEUS!\nTOCA-ME COM BRASAS DO ALTAR;\nFALA DEUS! FALA DEUS!\nSIM, ALEGRE ATENDO AO TEU MANDAR.\n\nMUITOS SÃO OS QUE VÃO EXPIRANDO\nSEM TER ESPERANÇA DE VER DEUS;\nVAI, DEPRESSA, LHES ANUNCIANDO\nQUE JESUS OS LEVA PARA OS CÉUS.\n\n<coro>\nFALA DEUS! FALA DEUS!\nTOCA-ME COM BRASAS DO ALTAR;\nFALA DEUS! FALA DEUS!\nSIM, ALEGRE ATENDO AO TEU MANDAR.\n\nO PROFETA A DEUS SE APROXIMANDO,\nCONSIDERA-SE UM PECADOR,\nMAS, O FOGO SANTO O QUEIMANDO,\nTORNA-O ÚTIL PARA SEU SENHOR.\n\n<coro>\nFALA DEUS! FALA DEUS!\nTOCA-ME COM BRASAS DO ALTAR;\nFALA DEUS! FALA DEUS!\nSIM, ALEGRE ATENDO AO TEU MANDAR.\n\nBREVE OS TRABALHOS SERÃO FINDOS,\nBÊNÇÃOS VÃO OS SERVOS DESFRUTAR,\nE JESUS OS SAUDARÁ: ''BEM-VINDOS'',\nESTA GLÓRIA ESPERO ALCANÇAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (412, 'SOU FORASTEIRO AQUI', 'SOU FORASTEIRO AQUI', 'SOU FORASTEIRO AQUI, \nEM TERRA ESTRANHA ESTOU, \nCELESTE PÁTRIA, \nSIM, É PARA ONDE VOU;\nEMBAIXADOR, POR DEUS, \nDE REINOS D''ALÉM CÉUS, \nVENHO A SERVIÇO DO MEU REI.\n\nCORO\nEIS A MENSAGEM QUE ME DEU, \nQUE OS ANJOS CANTAM LÁ NO CÉU:\n''RECONCILIAI-VOS JÁ'', DIZ O SENHOR, \nREI MEU, ''RECONCILIAI-VOS JÁ COM DEUS''.\n\nPOR DEUS MANDADO ESTÁ QUE O HOMEM PECADOR, ARREPENDIDO JÁ, SE CHEGUE AO SALVADOR;\nPOIS QUEM O RECEBER NO REINO VAI VIVER, \nVENHO A SERVIÇO DO MEU REI.\n\nCORO\nEIS A MENSAGEM QUE ME DEU, \nQUE OS ANJOS CANTAM LÁ NO CÉU:\n''RECONCILIAI-VOS JÁ'', DIZ O SENHOR, \nREI MEU, ''RECONCILIAI-VOS JÁ COM DEUS''.\n\nMAIS BELO QUE O ROSAL, \nO LAR CELESTE TEM A BÊNÇÃO PRO MORTAL, \nO GOZO ETERNO ALÉM;\nALI SÓ HÁ PRAZER, VOS MANDA O REI DIZER;\nVENHO A SERVIÇO DO MEU REI.\n\nCORO\nEIS A MENSAGEM QUE ME DEU, \nQUE OS ANJOS CANTAM LÁ NO CÉU:\n''RECONCILIAI-VOS JÁ'', DIZ O SENHOR, \nREI MEU, ''RECONCILIAI-VOS JÁ COM DEUS''.', 'SOU FORASTEIRO AQUI, \nEM TERRA ESTRANHA ESTOU, \nCELESTE PÁTRIA, \nSIM, É PARA ONDE VOU;\nEMBAIXADOR, POR DEUS, \nDE REINOS D''ALÉM CÉUS, \nVENHO A SERVIÇO DO MEU REI.\n\n<coro>\nEIS A MENSAGEM QUE ME DEU, \nQUE OS ANJOS CANTAM LÁ NO CÉU:\n''RECONCILIAI-VOS JÁ'', DIZ O SENHOR, \nREI MEU, ''RECONCILIAI-VOS JÁ COM DEUS''.\n\nPOR DEUS MANDADO ESTÁ QUE O HOMEM PECADOR, ARREPENDIDO JÁ, SE CHEGUE AO SALVADOR;\nPOIS QUEM O RECEBER NO REINO VAI VIVER, \nVENHO A SERVIÇO DO MEU REI.\n\n<coro>\nEIS A MENSAGEM QUE ME DEU, \nQUE OS ANJOS CANTAM LÁ NO CÉU:\n''RECONCILIAI-VOS JÁ'', DIZ O SENHOR, \nREI MEU, ''RECONCILIAI-VOS JÁ COM DEUS''.\n\nMAIS BELO QUE O ROSAL, \nO LAR CELESTE TEM A BÊNÇÃO PRO MORTAL, \nO GOZO ETERNO ALÉM;\nALI SÓ HÁ PRAZER, VOS MANDA O REI DIZER;\nVENHO A SERVIÇO DO MEU REI.\n\n<coro>\nEIS A MENSAGEM QUE ME DEU, \nQUE OS ANJOS CANTAM LÁ NO CÉU:\n''RECONCILIAI-VOS JÁ'', DIZ O SENHOR, \nREI MEU, ''RECONCILIAI-VOS JÁ COM DEUS''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (413, 'OUVI, Ó CÉUS, E FALAREI', 'OUVI, Ó CÉUS, E FALAREI', 'OUVI, Ó CÉUS, E FALAREI E OUÇA \nA TERRA A MINHA VOZ, ESCUTAI, POVO MEU!\n\nGOTEJE A MINHA DOUTRINA COMO A CHUVA,\nDESTILE A MINHA PALAVRA COMO O ORVALHO;\nTAL COMO SUAVE CHUVISCO SOBRE \nA RELVA E COMO AS GOTAS \nDE ÁGUA SOBRE A ERVA.\n\nCORO\nENTÃO PROCLAMAREI O NOME DO SENHOR! \nENGRANDECEI O NOSSO DEUS!\n\nINSTRUMENTOS\n\nDEUS É MINHA ROCHA, SUA OBRA É PERFEITA, \nPORQUE TODOS OS SEUS CAMINHOS SÃO JUÍZO;\nDEUS É A VERDADE, NÃO HÁ NELE INJUSTIÇA, \nÉ JUSTO E RETO O SENHOR MEU, ALELUIA!\n\nCORO (2X)\nENTÃO PROCLAMAREI O NOME DO SENHOR!\nENGRANDECEI O NOSSO DEUS!\n\nFINAL:\nENGRANDECEI O NOSSO DEUS!', 'OUVI, Ó CÉUS, E FALAREI E OUÇA \nA TERRA A MINHA VOZ, ESCUTAI, POVO MEU!\n\nGOTEJE A MINHA DOUTRINA COMO A CHUVA,\nDESTILE A MINHA PALAVRA COMO O ORVALHO;\nTAL COMO SUAVE CHUVISCO SOBRE \nA RELVA E COMO AS GOTAS \nDE ÁGUA SOBRE A ERVA.\n\n<coro>\nENTÃO PROCLAMAREI O NOME DO SENHOR! \nENGRANDECEI O NOSSO DEUS!\n<instrumentos>\n\n\nDEUS É MINHA ROCHA, SUA OBRA É PERFEITA, \nPORQUE TODOS OS SEUS CAMINHOS SÃO JUÍZO;\nDEUS É A VERDADE, NÃO HÁ NELE INJUSTIÇA, \nÉ JUSTO E RETO O SENHOR MEU, ALELUIA!\n\n<coro tipo=''2X''>\nENTÃO PROCLAMAREI O NOME DO SENHOR!\nENGRANDECEI O NOSSO DEUS!\n<final>ENGRANDECEI O NOSSO DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (414, 'MEU DEUS, MEU BOM PASTOR', 'MEU DEUS, MEU BOM PASTOR', 'MEU DEUS, MEU BOM PASTOR,\nGUIAR-ME VEM PELA MÃO\nPORQUE SOU FRACO, SENHOR;\nDÁ-ME TUA PROTEÇÃO!\nJESUS, MEU SALVADOR,\nTRANSBORDA-ME DE AMOR\nE EU SEREI TEU FIEL SERVIDOR!\n\nDE MANHÃ, LOGO CEDO, \nTUA FACE BUSCAR QUERO, \nSENHOR, E EM SEGREDO,\nMINHA VIDA TE DAR; E QUANDO \nO DIA FINDAR POR TEU SANGUE \nVOU CLAMAR, QUERO TORNAR-ME \nUM FIEL SERVIDOR!\n\nSENDO AGORA TEU SOMENTE,\nVEM DE PODER E AMOR\nENCHER-ME, Ó ONIPOTENTE,\nE GLÓRIA TE DOU, MEU SENHOR;\nMEU DEUS, MEU GUARDADOR,\nGLÓRIA E ALELUIA COM ARDOR,\nEIS-ME TORNADO UM FIEL SERVIDOR!\nGLÓRIA E ALELUIA COM ARDOR,\nEIS-ME TORNADO UM FIEL SERVIDOR!', 'MEU DEUS, MEU BOM PASTOR,\nGUIAR-ME VEM PELA MÃO\nPORQUE SOU FRACO, SENHOR;\nDÁ-ME TUA PROTEÇÃO!\nJESUS, MEU SALVADOR,\nTRANSBORDA-ME DE AMOR\nE EU SEREI TEU FIEL SERVIDOR!\n\nDE MANHÃ, LOGO CEDO, \nTUA FACE BUSCAR QUERO, \nSENHOR, E EM SEGREDO,\nMINHA VIDA TE DAR; E QUANDO \nO DIA FINDAR POR TEU SANGUE \nVOU CLAMAR, QUERO TORNAR-ME \nUM FIEL SERVIDOR!\n\nSENDO AGORA TEU SOMENTE,\nVEM DE PODER E AMOR\nENCHER-ME, Ó ONIPOTENTE,\nE GLÓRIA TE DOU, MEU SENHOR;\nMEU DEUS, MEU GUARDADOR,\nGLÓRIA E ALELUIA COM ARDOR,\nEIS-ME TORNADO UM FIEL SERVIDOR!\nGLÓRIA E ALELUIA COM ARDOR,\nEIS-ME TORNADO UM FIEL SERVIDOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (415, 'QUERO SER UM VASO DE BÊNÇÃO', 'QUERO SER UM VASO DE BÊNÇÃO', 'QUERO SER UM VASO DE BÊNÇÃO,\nSIM, UM VASO ESCOLHIDO DE DEUS,\nPARA AS NOVAS LEVAR AOS PERDIDOS,\nBOAS NOVAS QUE VÊM LÁ DOS CÉUS.\n\nCORO\nFAZE-ME VASO DE BÊNÇÃO, SENHOR,\nVASO QUE LEVE A MENSAGEM DE AMOR!\nEIS-ME SUBMISSO AO TEU SERVIÇO;\nEU ME CONSAGRO, BENDITO SENHOR.\n\nQUERO SER UM VASO DE BÊNÇÃO\nPARA TODOS OS DIAS FAZER,\nAOS CULPADOS QUE VIVEM NAS TREVAS,\nO PERDÃO DE JESUS CONHECER.\n\nCORO\nFAZE-ME VASO DE BÊNÇÃO, SENHOR,\nVASO QUE LEVE A MENSAGEM DE AMOR!\nEIS-ME SUBMISSO AO TEU SERVIÇO;\nEU ME CONSAGRO, BENDITO SENHOR.\n\nQUERO SER UM VASO DE BÊNÇÃO,\nSIM, UM VASO DE BÊNÇÃO SEM PAR,\nANUNCIANDO QUE OS CRENTES EM CRISTO\nJUBILOSOS NO CÉU HÃO DE ENTRAR.\n\nCORO\nFAZE-ME VASO DE BÊNÇÃO, SENHOR,\nVASO QUE LEVE A MENSAGEM DE AMOR!\nEIS-ME SUBMISSO AO TEU SERVIÇO;\nEU ME CONSAGRO, BENDITO SENHOR.', 'QUERO SER UM VASO DE BÊNÇÃO,\nSIM, UM VASO ESCOLHIDO DE DEUS,\nPARA AS NOVAS LEVAR AOS PERDIDOS,\nBOAS NOVAS QUE VÊM LÁ DOS CÉUS.\n\n<coro>\nFAZE-ME VASO DE BÊNÇÃO, SENHOR,\nVASO QUE LEVE A MENSAGEM DE AMOR!\nEIS-ME SUBMISSO AO TEU SERVIÇO;\nEU ME CONSAGRO, BENDITO SENHOR.\n\nQUERO SER UM VASO DE BÊNÇÃO\nPARA TODOS OS DIAS FAZER,\nAOS CULPADOS QUE VIVEM NAS TREVAS,\nO PERDÃO DE JESUS CONHECER.\n\n<coro>\nFAZE-ME VASO DE BÊNÇÃO, SENHOR,\nVASO QUE LEVE A MENSAGEM DE AMOR!\nEIS-ME SUBMISSO AO TEU SERVIÇO;\nEU ME CONSAGRO, BENDITO SENHOR.\n\nQUERO SER UM VASO DE BÊNÇÃO,\nSIM, UM VASO DE BÊNÇÃO SEM PAR,\nANUNCIANDO QUE OS CRENTES EM CRISTO\nJUBILOSOS NO CÉU HÃO DE ENTRAR.\n\n<coro>\nFAZE-ME VASO DE BÊNÇÃO, SENHOR,\nVASO QUE LEVE A MENSAGEM DE AMOR!\nEIS-ME SUBMISSO AO TEU SERVIÇO;\nEU ME CONSAGRO, BENDITO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (416, 'PELAS PRAIAS GALILÉIAS VEM JESUS', 'PELAS PRAIAS GALILÉIAS VEM JESUS', 'PELAS PRAIAS GALILÉIAS VEM JESUS, (BIS)\nJUNTO ÀS REDES, OS PESCADORES,\nPRA O SEGUIREM VAI CHAMAR\nE SEGUIRAM A JESUS SEM VACILAR.\n\nTODA A NOITE DE VIGÍLIA TUDO EM VÃO, (BIS)\nDIZ JESUS: ''LANÇAI ALÉM VOSSAS REDES \nE ACHAREIS, E DE PEIXES ENCHEREIS \nLOGO OS BATÉIS''.\n\nASSENTADOS, MUI CANSADOS E FAMINTOS, (BIS)\nCRISTO TOMA O PÃO E O PEIXE, \nORA AO PAI E PARTE O PÃO, E ALIMENTA, \nCOM SOBEJO, A MULTIDÃO.\n\nEU TAMBÉM SEGUIR-TE QUERO, MEU SENHOR, (BIS)\nSÓ EM TI PODE ENCONTRAR,\nMEU FAMINTO CORAÇÃO,\nALEGRIA COM REAL SATISFAÇÃO.', 'PELAS PRAIAS GALILÉIAS VEM JESUS, <bis>\nJUNTO ÀS REDES, OS PESCADORES,\nPRA O SEGUIREM VAI CHAMAR\nE SEGUIRAM A JESUS SEM VACILAR.\n\nTODA A NOITE DE VIGÍLIA TUDO EM VÃO, <bis>\nDIZ JESUS: ''LANÇAI ALÉM VOSSAS REDES \nE ACHAREIS, E DE PEIXES ENCHEREIS \nLOGO OS BATÉIS''.\n\nASSENTADOS, MUI CANSADOS E FAMINTOS, <bis>\nCRISTO TOMA O PÃO E O PEIXE, \nORA AO PAI E PARTE O PÃO, E ALIMENTA, \nCOM SOBEJO, A MULTIDÃO.\n\nEU TAMBÉM SEGUIR-TE QUERO, MEU SENHOR, <bis>\nSÓ EM TI PODE ENCONTRAR,\nMEU FAMINTO CORAÇÃO,\nALEGRIA COM REAL SATISFAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (417, 'MINHA DEDICAÇÃO', 'MINHA DEDICAÇÃO', 'MINHA DEDICAÇÃO EU VIM TE OFERECER,\nTU ÉS O MEU AMADO SALVADOR;\nPEDISTE MAIS DE MIM EIS-ME AQUI SENHOR\nTENS A MINHA VIDA E MEU LOUVOR.\n\nVIVER SÓ PARA TI COM TODO O MEU AMOR, \nOBEDECER TUA VOZ EM TODO \nO MEU VIVER, SEGUINDO OS TEUS PASSOS\nOBSERVANDO OS MEUS, \nEM TUDO AGRADANDO A TI, \nMEU TERNO DEUS.\n\nÓ VINDE, ADOREMOS AO SENHOR,\nO GRANDE REI,\nJUSTO E PODEROSO, EXCELSO DEUS,\nMEU REDENTOR,\nTEMEI DIANTE DELE TODA A TERRA,\nADORAI AO REI.\nALELUIA, ALELUIA, ALELUIA, ALELUIA (BIS)\nTEMEI DIANTE DELE TODA A TERRA,\nADORAI AO REI.', 'MINHA DEDICAÇÃO EU VIM TE OFERECER,\nTU ÉS O MEU AMADO SALVADOR;\nPEDISTE MAIS DE MIM EIS-ME AQUI SENHOR\nTENS A MINHA VIDA E MEU LOUVOR.\n\nVIVER SÓ PARA TI COM TODO O MEU AMOR, \nOBEDECER TUA VOZ EM TODO \nO MEU VIVER, SEGUINDO OS TEUS PASSOS\nOBSERVANDO OS MEUS, \nEM TUDO AGRADANDO A TI, \nMEU TERNO DEUS.\n\nÓ VINDE, ADOREMOS AO SENHOR,\nO GRANDE REI,\nJUSTO E PODEROSO, EXCELSO DEUS,\nMEU REDENTOR,\nTEMEI DIANTE DELE TODA A TERRA,\nADORAI AO REI.\nALELUIA, ALELUIA, ALELUIA, ALELUIA <bis>\nTEMEI DIANTE DELE TODA A TERRA,\nADORAI AO REI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (418, 'HÁ UM POVO QUE TE ADORA', 'HÁ UM POVO QUE TE ADORA', 'HÁ UM POVO QUE TE ADORA EM ESPÍRITO,\nATENDENDO À TUA VOZ, SENHOR,\nQUE TEM UMA NOVA FORMA DE VIDA,\nLUTA COM AS ARMAS CELESTIAIS\nE VENCE PELO PODER DE JESUS.\n\nCORO\nO SENHOR É QUEM DIRIGE,\nO SENHOR É QUEM CONDUZ,\nDEPENDENTE SOU DO SEU AMOR\nQUERO VIVER UMA NOVA FORMA DE VIDA\nNO AMOR, NO AMOR DE JESUS.\n\nVARÕES\n\nNO PROJETO DE DEUS ESTOU\nLUTANDO COM AS ARMAS CELESTIAIS,\nVENCENDO PELO PODER DO SENHOR JESUS, \nCOM SEU PERDÃO, NA SALVAÇÃO, \nNA REVELAÇÃO DE JESUS.\n\nCORO\nO SENHOR É QUEM DIRIGE,\nO SENHOR É QUEM CONDUZ,\nDEPENDENTE SOU DO SEU AMOR\nQUERO VIVER UMA NOVA FORMA DE VIDA\nNO AMOR, NO AMOR DE JESUS.\n\nINSTRUMENTOS\n\nVARÕES\n\nFINAL:\nQUERO VIVER UMA NOVA FORMA DE VIDA \nNO AMOR, NO AMOR DE JESUS.', 'HÁ UM POVO QUE TE ADORA EM ESPÍRITO,\nATENDENDO À TUA VOZ, SENHOR,\nQUE TEM UMA NOVA FORMA DE VIDA,\nLUTA COM AS ARMAS CELESTIAIS\nE VENCE PELO PODER DE JESUS.\n\n<coro>\nO SENHOR É QUEM DIRIGE,\nO SENHOR É QUEM CONDUZ,\nDEPENDENTE SOU DO SEU AMOR\nQUERO VIVER UMA NOVA FORMA DE VIDA\nNO AMOR, NO AMOR DE JESUS.\n\n<h>\n\n\nNO PROJETO DE DEUS ESTOU\nLUTANDO COM AS ARMAS CELESTIAIS,\nVENCENDO PELO PODER DO SENHOR JESUS, \nCOM SEU PERDÃO, NA SALVAÇÃO, \nNA REVELAÇÃO DE JESUS.\n\n<coro>\nO SENHOR É QUEM DIRIGE,\nO SENHOR É QUEM CONDUZ,\nDEPENDENTE SOU DO SEU AMOR\nQUERO VIVER UMA NOVA FORMA DE VIDA\nNO AMOR, NO AMOR DE JESUS.\n<instrumentos>\n\n\n<h>\n\n\n\n<final>QUERO VIVER UMA NOVA FORMA DE VIDA \nNO AMOR, NO AMOR DE JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (419, 'HÁ UMA OBRA QUE DEUS QUER FAZER', 'HÁ UMA OBRA QUE DEUS QUER FAZER', 'HÁ UMA OBRA QUE DEUS QUER FAZER,\nOBRA DE SANTIDADE E DE PODER;\nQUEM ESTÁ DISPOSTO A SE CONSAGRAR \nE A ARCA DE DEUS AOS OMBROS CARREGAR?\n\nCORO\nO ESPÍRITO DE DEUS QUER A TI,\nCOMO ELE UM DIA POSSUIU DAVI, SIM,\nHÁ UMA OBRA A REALIZAR\nANTES QUE VENHA O FIM.\n\nDESCE AO RIBEIRO E ENCHE O CORAÇÃO,\nTERÁS VITÓRIA NA REVELAÇÃO;\nCOM ÓLEO DE PODER DEUS TE UNGIRÁ,\nJAMAIS VAZIA A ESPADA VOLTARÁ.\n\nCORO\nO ESPÍRITO DE DEUS QUER A TI,\nCOMO ELE UM DIA POSSUIU DAVI, SIM,\nHÁ UMA OBRA A REALIZAR\nANTES QUE VENHA O FIM.', 'HÁ UMA OBRA QUE DEUS QUER FAZER,\nOBRA DE SANTIDADE E DE PODER;\nQUEM ESTÁ DISPOSTO A SE CONSAGRAR \nE A ARCA DE DEUS AOS OMBROS CARREGAR?\n\n<coro>\nO ESPÍRITO DE DEUS QUER A TI,\nCOMO ELE UM DIA POSSUIU DAVI, SIM,\nHÁ UMA OBRA A REALIZAR\nANTES QUE VENHA O FIM.\n\nDESCE AO RIBEIRO E ENCHE O CORAÇÃO,\nTERÁS VITÓRIA NA REVELAÇÃO;\nCOM ÓLEO DE PODER DEUS TE UNGIRÁ,\nJAMAIS VAZIA A ESPADA VOLTARÁ.\n\n<coro>\nO ESPÍRITO DE DEUS QUER A TI,\nCOMO ELE UM DIA POSSUIU DAVI, SIM,\nHÁ UMA OBRA A REALIZAR\nANTES QUE VENHA O FIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (420, 'SOMOS TEU POVO E QUEREMOS', 'SOMOS TEU POVO E QUEREMOS', 'SOMOS TEU POVO E QUEREMOS\nTUA VONTADE FAZER;\nLIVRA-NOS DO VELHO HOMEM\nE CONCEDE-NOS UM NOVO VIVER,\nPARA QUE POSSAMOS SEMPRE TE OBEDECER.\nE DEFINIR NOSSAS VIDAS EM \nTI E SERMOS TUA IGREJA FIEL.\n\nESTA É UMA OBRA ETERNA\nQUE O TEU ESPÍRITO NOS TRAZ,\nTODOS EM UM SÓ LOUVOR CANTARÃO: MARANATA! JESUS VOLTARÁ!', 'SOMOS TEU POVO E QUEREMOS\nTUA VONTADE FAZER;\nLIVRA-NOS DO VELHO HOMEM\nE CONCEDE-NOS UM NOVO VIVER,\nPARA QUE POSSAMOS SEMPRE TE OBEDECER.\nE DEFINIR NOSSAS VIDAS EM <bis>\nTI E SERMOS TUA IGREJA FIEL.<bis>\n\nESTA É UMA OBRA ETERNA\nQUE O TEU ESPÍRITO NOS TRAZ,\nTODOS EM UM SÓ LOUVOR CANTARÃO: MARANATA! JESUS VOLTARÁ!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (421, 'A OBRA DO SENHOR É PERFEITA', 'A OBRA DO SENHOR É PERFEITA', 'A OBRA DO SENHOR É PERFEITA,\nÉ COMO A LUZ DO SOL\nEM SEU ESPLENDOR,\nÉ CHUVA SOBRE A TERRA,\nSEMENTE QUE PROSPERA,\nA OBRA DO SENHOR. (BIS)\n\nA OBRA DO SENHOR É PERFEITA,\nÉ COMO A LUZ DO SOL\nEM SEU ESPLENDOR,\nÉ CHUVA SOBRE A TERRA,\nSEMENTE QUE PROSPERA,\nA OBRA DO SENHOR.\nA OBRA DO SENHOR É PERFEITA,\nA OBRA DO SENHOR É PRECIOSA.', 'A OBRA DO SENHOR É PERFEITA,\nÉ COMO A LUZ DO SOL\nEM SEU ESPLENDOR,\nÉ CHUVA SOBRE A TERRA,\nSEMENTE QUE PROSPERA,\nA OBRA DO SENHOR. <bis>\n\nA OBRA DO SENHOR É PERFEITA,\nÉ COMO A LUZ DO SOL\nEM SEU ESPLENDOR,\nÉ CHUVA SOBRE A TERRA,\nSEMENTE QUE PROSPERA,\nA OBRA DO SENHOR.\nA OBRA DO SENHOR É PERFEITA,\nA OBRA DO SENHOR É PRECIOSA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (422, 'A MINHA HERANÇA', 'A MINHA HERANÇA', 'A MINHA HERANÇA ÉS TU, SENHOR,\nE TUA OBRA É PARA MIM MEU BEM MAIOR;\nEM CADA DIA TE CONHECER E DESCOBRIR \nTEU PLANO PARA O MEU VIVER.\n\nCORO\nDAS MÃOS DO MEU JESUS HERANÇA RECEBI, \nESTA VINHA QUE ME DEU PARA GUARDAR;\nPOR OUTRO BEM QUALQUER DO \nMUNDO AQUI JAMAIS EU PODEREI \nMINHA HERANÇA TROCAR.\n\nE SE VIER A TENTAÇÃO RESISTIREI \nFIRMADO EM TUA SALVAÇÃO;\nA VIDA AQUI POSSO PERDER \nMAS UMA HERANÇA ETERNA \nVOU NO CÉU RECEBER.\n\nCORO\nDAS MÃOS DO MEU JESUS HERANÇA RECEBI, \nESTA VINHA QUE ME DEU PARA GUARDAR;\nPOR OUTRO BEM QUALQUER DO \nMUNDO AQUI JAMAIS EU PODEREI \nMINHA HERANÇA TROCAR.', 'A MINHA HERANÇA ÉS TU, SENHOR,\nE TUA OBRA É PARA MIM MEU BEM MAIOR;\nEM CADA DIA TE CONHECER E DESCOBRIR \nTEU PLANO PARA O MEU VIVER.\n\n<coro>\nDAS MÃOS DO MEU JESUS HERANÇA RECEBI, \nESTA VINHA QUE ME DEU PARA GUARDAR;\nPOR OUTRO BEM QUALQUER DO \nMUNDO AQUI JAMAIS EU PODEREI \nMINHA HERANÇA TROCAR.\n\nE SE VIER A TENTAÇÃO RESISTIREI \nFIRMADO EM TUA SALVAÇÃO;\nA VIDA AQUI POSSO PERDER \nMAS UMA HERANÇA ETERNA \nVOU NO CÉU RECEBER.\n\n<coro>\nDAS MÃOS DO MEU JESUS HERANÇA RECEBI, \nESTA VINHA QUE ME DEU PARA GUARDAR;\nPOR OUTRO BEM QUALQUER DO \nMUNDO AQUI JAMAIS EU PODEREI \nMINHA HERANÇA TROCAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (423, 'Ó PASTOR DE ISRAEL', 'Ó PASTOR DE ISRAEL', 'Ó PASTOR DE ISRAEL, QUE GUIAS TEU POVO\nE TE ASSENTAS ENTRE OS QUERUBINS, \nRESPLANDECE!\n\nCORO\nVEM, VISITA A TUA VINHA QUE PLANTASTE \nCOM TUA DESTRA, RESPLANDECE \nSOBRE NÓS O TEU ROSTO; \nDOS QUE A QUEREM DEVORAR, \nTUA VINHA VEM GUARDAR, \nRESPLANDECE SOBRE NÓS O TEU ROSTO!\n\nÓ PASTOR DE ISRAEL, \nFAZE BRILHAR TUA GLÓRIA \nE DESPERTA O TEU PODER \nNO MEIO DO TEU POVO.\n\nCORO\nVEM, VISITA A TUA VINHA QUE PLANTASTE \nCOM TUA DESTRA, RESPLANDECE \nSOBRE NÓS O TEU ROSTO; \nDOS QUE A QUEREM DEVORAR, \nTUA VINHA VEM GUARDAR, \nRESPLANDECE SOBRE NÓS O TEU ROSTO!\n\nINSTRUMENTOS\n\nCORO\nVEM, VISITA A TUA VINHA QUE PLANTASTE \nCOM TUA DESTRA, RESPLANDECE \nSOBRE NÓS O TEU ROSTO; \nDOS QUE A QUEREM DEVORAR, \nTUA VINHA VEM GUARDAR, \nRESPLANDECE SOBRE NÓS O TEU ROSTO!\n\nFINAL: O TEU ROSTO!', 'Ó PASTOR DE ISRAEL, QUE GUIAS TEU POVO\nE TE ASSENTAS ENTRE OS QUERUBINS, \nRESPLANDECE!\n\n<coro>\nVEM, VISITA A TUA VINHA QUE PLANTASTE \nCOM TUA DESTRA, RESPLANDECE \nSOBRE NÓS O TEU ROSTO; \nDOS QUE A QUEREM DEVORAR, \nTUA VINHA VEM GUARDAR, \nRESPLANDECE SOBRE NÓS O TEU ROSTO!\n\nÓ PASTOR DE ISRAEL, \nFAZE BRILHAR TUA GLÓRIA \nE DESPERTA O TEU PODER \nNO MEIO DO TEU POVO.\n\n<coro>\nVEM, VISITA A TUA VINHA QUE PLANTASTE \nCOM TUA DESTRA, RESPLANDECE \nSOBRE NÓS O TEU ROSTO; \nDOS QUE A QUEREM DEVORAR, \nTUA VINHA VEM GUARDAR, \nRESPLANDECE SOBRE NÓS O TEU ROSTO!\n<instrumentos>\n\n\n<coro>\nVEM, VISITA A TUA VINHA QUE PLANTASTE \nCOM TUA DESTRA, RESPLANDECE \nSOBRE NÓS O TEU ROSTO; \nDOS QUE A QUEREM DEVORAR, \nTUA VINHA VEM GUARDAR, \nRESPLANDECE SOBRE NÓS O TEU ROSTO!\n<final>O TEU ROSTO!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (424, 'O MEU AMADO DESCEU AO SEU JARDIM', 'O MEU AMADO DESCEU AO SEU JARDIM', 'O MEU AMADO DESCEU AO \nSEU JARDIM, AOS CANTEIROS DE BÁLSAMO.\n\nPARA PASTOREAR NO JARDIM\nPARA COLHER OS LÍRIOS.\n\nEU SOU DO MEU AMADO\nE O MEU AMADO É MEU;\nELE PASTOREIA ENTRE OS LÍRIOS, \nELE PASTOREIA ENTRE OS LÍRIOS.', 'O MEU AMADO DESCEU AO <bis>\nSEU JARDIM, AOS CANTEIROS DE BÁLSAMO.<bis>\n\nPARA PASTOREAR NO JARDIM<bis>\nPARA COLHER OS LÍRIOS.<bis>\n\nEU SOU DO MEU AMADO<bis>\nE O MEU AMADO É MEU;<bis>\nELE PASTOREIA ENTRE OS LÍRIOS, <bis>\nELE PASTOREIA ENTRE OS LÍRIOS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (425, 'QUE VISTA AMÁVEL É (SALMO 132)', 'QUE VISTA AMÁVEL É (SALMO 132)', 'QUE VISTA AMÁVEL É\nQUANDO, COM SANTO AMOR,\nIRMÃOS UNIDOS PELA FÉ,\nADORAM O SENHOR.\n\nO MUNDO OBSERVARÁ\nAQUELA SANTA PAZ,\nCOMO UM PERFUME SENTIRÁ\nO GOZO QUE ELA TRAZ.\n\nENVIA-NOS, JESUS,\nDO TEU MONTE SIÃO,\nO SANTO ESPÍRITO QUE PRODUZ\nAQUELA DOCE UNIÃO.', 'QUE VISTA AMÁVEL É\nQUANDO, COM SANTO AMOR,\nIRMÃOS UNIDOS PELA FÉ,\nADORAM O SENHOR.\n\nO MUNDO OBSERVARÁ\nAQUELA SANTA PAZ,\nCOMO UM PERFUME SENTIRÁ\nO GOZO QUE ELA TRAZ.\n\nENVIA-NOS, JESUS,\nDO TEU MONTE SIÃO,\nO SANTO ESPÍRITO QUE PRODUZ\nAQUELA DOCE UNIÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (426, 'UM CORPO SÓ, UM SÓ ESPÍRITO', 'UM CORPO SÓ, UM SÓ ESPÍRITO', 'UM CORPO SÓ, UM SÓ ESPÍRITO,\nUMA ESPERANÇA, UM SÓ SENHOR, UMA FÉ,\nUM SÓ BATISMO E UM SÓ DEUS E PAI,\nUM CORPO SÓ, UM SÓ ESPÍRITO. (BIS)\n\nCRISTO É A CABEÇA, O CORPO É A SUA IGREJA, \nCOM SEU PODER NOS BATIZOU O SENHOR;\nNÃO HÁ NO MUNDO UM POVO UNIDO ASSIM,\nUM CORPO SÓ, UM SÓ ESPÍRITO. (BIS)\n\nDE SUA GRAÇA CRISTO DERRAMOU,\nEM MINISTÉRIOS, DONS E MUITO AMOR,\nMAS SOMOS TODOS UM SÓ EM JESUS,\nUM CORPO SÓ, UM SÓ ESPÍRITO. (BIS)', 'UM CORPO SÓ, UM SÓ ESPÍRITO,\nUMA ESPERANÇA, UM SÓ SENHOR, UMA FÉ,\nUM SÓ BATISMO E UM SÓ DEUS E PAI,\nUM CORPO SÓ, UM SÓ ESPÍRITO. <bis>\n\nCRISTO É A CABEÇA, O CORPO É A SUA IGREJA, \nCOM SEU PODER NOS BATIZOU O SENHOR;\nNÃO HÁ NO MUNDO UM POVO UNIDO ASSIM,\nUM CORPO SÓ, UM SÓ ESPÍRITO. <bis>\n\nDE SUA GRAÇA CRISTO DERRAMOU,\nEM MINISTÉRIOS, DONS E MUITO AMOR,\nMAS SOMOS TODOS UM SÓ EM JESUS,\nUM CORPO SÓ, UM SÓ ESPÍRITO. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (427, 'OH! QUÃO BOM E QUÃO SUAVE É', 'OH! QUÃO BOM E QUÃO SUAVE É', 'OH! QUÃO BOM E QUÃO SUAVE \nÉ A UNIÃO ENTRE OS IRMÃOS,\nÉ COMO ÓLEO PRECIOSO\nSOBRE A CABEÇA DE ARÃO,\nÉ COMO ÓLEO PRECIOSO\nSOBRE O CORPO DE ARÃO.\n\nCOMO O ORVALHO DE HERMOM\nQUE DESCE SOBRE OS MONTES \nDE SIÃO PORQUE ALI O SENHOR\nORDENA A BÊNÇÃO PARA SEMPRE, \nORDENA A VIDA PARA SEMPRE. \n\nINSTRUMENTOS\n\nOH! QUÃO BOM E QUÃO SUAVE \nÉ A UNIÃO ENTRE OS IRMÃOS,\nÉ COMO ÓLEO PRECIOSO\nSOBRE A CABEÇA DE ARÃO,\nÉ COMO ÓLEO PRECIOSO\nSOBRE O CORPO DE ARÃO.\n\nCOMO O ORVALHO DE HERMOM\nQUE DESCE SOBRE OS MONTES \nDE SIÃO PORQUE ALI O SENHOR\nORDENA A BÊNÇÃO PARA SEMPRE, \nORDENA A VIDA PARA SEMPRE.', 'OH! QUÃO BOM E QUÃO SUAVE \nÉ A UNIÃO ENTRE OS IRMÃOS,\nÉ COMO ÓLEO PRECIOSO\nSOBRE A CABEÇA DE ARÃO,\nÉ COMO ÓLEO PRECIOSO\nSOBRE O CORPO DE ARÃO.\n\nCOMO O ORVALHO DE HERMOM\nQUE DESCE SOBRE OS MONTES \nDE SIÃO PORQUE ALI O SENHOR\nORDENA A BÊNÇÃO PARA SEMPRE, <bis>\nORDENA A VIDA PARA SEMPRE. <bis>\n<instrumentos>\n\n\nOH! QUÃO BOM E QUÃO SUAVE \nÉ A UNIÃO ENTRE OS IRMÃOS,\nÉ COMO ÓLEO PRECIOSO\nSOBRE A CABEÇA DE ARÃO,\nÉ COMO ÓLEO PRECIOSO\nSOBRE O CORPO DE ARÃO.\n\nCOMO O ORVALHO DE HERMOM\nQUE DESCE SOBRE OS MONTES \nDE SIÃO PORQUE ALI O SENHOR\nORDENA A BÊNÇÃO PARA SEMPRE, <bis>\nORDENA A VIDA PARA SEMPRE. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (428, 'VEM, Ó CRISTO, ENCHER MEU CÁLICE', 'VEM, Ó CRISTO, ENCHER MEU CÁLICE', 'VEM, Ó CRISTO, ENCHER MEU CÁLICE, \nSACIAR A SEDE DO MEU CORAÇÃO;\nPÃO DA VIDA, VEM ALIMENTAR MEU SER, \nVEM MEU CÁLICE DE GOZO TRANSBORDAR.', 'VEM, Ó CRISTO, ENCHER MEU CÁLICE, \nSACIAR A SEDE DO MEU CORAÇÃO;\nPÃO DA VIDA, VEM ALIMENTAR MEU SER, \nVEM MEU CÁLICE DE GOZO TRANSBORDAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (429, 'ÉS O PÃO DA VIDA', 'ÉS O PÃO DA VIDA', 'ÉS O PÃO DA VIDA, CELESTIAL MANÁ,\nDELE, QUEM COMER, PRA SEMPRE VIVERÁ;\nEM TEU CORPO REPARTIDO, \nSOMOS UM SÓ POVO UNIDO \nPELOS LAÇOS DE AMOR \nNO TEU SANTO ESPÍRITO.\n\nÉS JESUS, DA VIDE, O DOCE FRUTO,\nVIDA ABUNDANTE QUE NOS SATISFAZ;\nPELO SANGUE DA TUA CRUZ\nALCANÇAMOS VIDA E LUZ,\nCÁLICE TRANSBORDANTE DE \nALEGRIA E DE PAZ.', 'ÉS O PÃO DA VIDA, CELESTIAL MANÁ,\nDELE, QUEM COMER, PRA SEMPRE VIVERÁ;\nEM TEU CORPO REPARTIDO, \nSOMOS UM SÓ POVO UNIDO \nPELOS LAÇOS DE AMOR \nNO TEU SANTO ESPÍRITO.\n\nÉS JESUS, DA VIDE, O DOCE FRUTO,\nVIDA ABUNDANTE QUE NOS SATISFAZ;\nPELO SANGUE DA TUA CRUZ<bis>\nALCANÇAMOS VIDA E LUZ,<bis>\nCÁLICE TRANSBORDANTE DE <bis>\nALEGRIA E DE PAZ. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (430, 'COMO CRISTO ENSINOU', 'COMO CRISTO ENSINOU', 'COMO CRISTO ENSINOU \nPARTILHAMOS DESTE PÃO, \nO SEU CORPO REPARTIDO \nEM COMUNHÃO; E DO CÁLICE BEBAMOS,\nQUE É SEU SANGUE DERRAMADO,\nPREÇO PAGO PELA NOSSA SALVAÇÃO;\n\nE LEMBRAMOS ESSE DIA, \nESSA NOITE TÃO SOMBRIA \nEM QUE ELE NO JARDIM \nAO PAI CLAMOU; \nE TRAÍDO E ABANDONADO\nFOI NA CRUZ SACRIFICADO,\nO CORDEIRO NOSSA CULPA EXPIOU.\n\nDO SEU LADO TRASPASSADO PELO NOSSO VIL PECADO, \nNOS GEROU PRA SERMOS SUA POSSESSÃO;\nUM SÓ CORPO FEZ DE NÓS, UM SÓ POVO, \nUM SÓ PÃO BATIZOU-NOS COM A MESMA SANTA UNÇÃO;\nNO LUGAR DA SUA DOR HÁ PRA NÓS GOZO E LOUVOR, \nNOSSO CÁLICE TRANSBORDA DE ALEGRIA;\nPOIS A VIDA NOS FOI DADA, \nA VITÓRIA ALCANÇADA POR JESUS, \nO NOSSO AMADO SALVADOR. \n\nPOR ESPELHO NÓS JÁ VEMOS, \nPOR ENIGMA PERCEBEMOS \nMARAVILHAS QUE ELE VAI NOS REVELAR, \nAS MORADAS ETERNAIS \nNOS LUGARES CELESTIAIS \nQUE JESUS JUNTO \nDO PAI FOI PREPARAR.', 'COMO CRISTO ENSINOU \nPARTILHAMOS DESTE PÃO, \nO SEU CORPO REPARTIDO \nEM COMUNHÃO; E DO CÁLICE BEBAMOS,\nQUE É SEU SANGUE DERRAMADO,\nPREÇO PAGO PELA NOSSA SALVAÇÃO;\n\nE LEMBRAMOS ESSE DIA, \nESSA NOITE TÃO SOMBRIA \nEM QUE ELE NO JARDIM \nAO PAI CLAMOU; \nE TRAÍDO E ABANDONADO\nFOI NA CRUZ SACRIFICADO,\nO CORDEIRO NOSSA CULPA EXPIOU.\n\nDO SEU LADO TRASPASSADO PELO NOSSO VIL PECADO, \nNOS GEROU PRA SERMOS SUA POSSESSÃO;\nUM SÓ CORPO FEZ DE NÓS, UM SÓ POVO, \nUM SÓ PÃO BATIZOU-NOS COM A MESMA SANTA UNÇÃO;\nNO LUGAR DA SUA DOR HÁ PRA NÓS GOZO E LOUVOR, \nNOSSO CÁLICE TRANSBORDA DE ALEGRIA;\nPOIS A VIDA NOS FOI DADA, \nA VITÓRIA ALCANÇADA POR JESUS, \nO NOSSO AMADO SALVADOR. \n\nPOR ESPELHO NÓS JÁ VEMOS, \nPOR ENIGMA PERCEBEMOS \nMARAVILHAS QUE ELE VAI NOS REVELAR, \nAS MORADAS ETERNAIS \nNOS LUGARES CELESTIAIS \nQUE JESUS JUNTO \nDO PAI FOI PREPARAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (431, 'CRISTO JÁ NOS PREPAROU', 'CRISTO JÁ NOS PREPAROU', 'CRISTO JÁ NOS PREPAROU\nUM MANJAR QUE NOS COMPROU\nE AGORA NOS CONVIDA A CEAR;\nCOM CELESTIAL MANÁ\nQUE DE GRAÇA DEUS TE DÁ,\nVEM FAMINTO, TUA ALMA SACIAR.\n\nCORO\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''\n\nEIS DISCÍPULOS A VOLTAR, \nSEM OS PEIXES APANHAR, \nMAS JESUS OS MANDA OUTRA VEZ PARTIR; \nAO TORNAR À PRAIA, ENTÃO, \nVÊEM NO FOGO PEIXE E PÃO \nE JESUS QUE OS CONVIDA À CEIA VIR.\n\nCORO\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''\n\nQUEM SEDENTO SE ACHAR, \nVENHA A CRISTO SEM TARDAR POIS UM VINHO \nSEM MISTURA ELE DÁ, E TAMBÉM DA VIDA, O PÃO, QUE NOS TRAZ CONSOLAÇÃO; \nEIS QUE TUDO PREPARADO JÁ ESTÁ.\n\nCORO\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''\n\nBREVE CRISTO VAI DESCER \nE A NOIVA RECEBER SEU LUGAR \nAO LADO DO SENHOR JESUS; \nQUEM A FOME SUPORTOU\nE A SEDE JÁ PASSOU, \nLÁ NO CÉU IRÁ REINAR EM SANTA LUZ.\n\nCORO\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''', 'CRISTO JÁ NOS PREPAROU\nUM MANJAR QUE NOS COMPROU\nE AGORA NOS CONVIDA A CEAR;\nCOM CELESTIAL MANÁ\nQUE DE GRAÇA DEUS TE DÁ,\nVEM FAMINTO, TUA ALMA SACIAR.\n\n<coro>\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''\n\nEIS DISCÍPULOS A VOLTAR, \nSEM OS PEIXES APANHAR, \nMAS JESUS OS MANDA OUTRA VEZ PARTIR; \nAO TORNAR À PRAIA, ENTÃO, \nVÊEM NO FOGO PEIXE E PÃO \nE JESUS QUE OS CONVIDA À CEIA VIR.\n\n<coro>\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''\n\nQUEM SEDENTO SE ACHAR, \nVENHA A CRISTO SEM TARDAR POIS UM VINHO \nSEM MISTURA ELE DÁ, E TAMBÉM DA VIDA, O PÃO, QUE NOS TRAZ CONSOLAÇÃO; \nEIS QUE TUDO PREPARADO JÁ ESTÁ.\n\n<coro>\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''\n\nBREVE CRISTO VAI DESCER \nE A NOIVA RECEBER SEU LUGAR \nAO LADO DO SENHOR JESUS; \nQUEM A FOME SUPORTOU\nE A SEDE JÁ PASSOU, \nLÁ NO CÉU IRÁ REINAR EM SANTA LUZ.\n\n<coro>\n''VEM CEAR'', O MESTRE CHAMA: ''VEM CEAR'', \nMESMO HOJE TU TE PODES SACIAR;\nPOUCOS PÃES MULTIPLICOU, \nÁGUA EM VINHO TRANSFORMOU, \nVEM, FAMINTO, A JESUS, ''VEM CEAR!''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (432, 'OUÇO A VOZ DO MEU AMADO ME CHAMAR', 'OUÇO A VOZ DO MEU AMADO ME CHAMAR', 'CORO\nOUÇO A VOZ DO MEU AMADO ME CHAMAR\n''FILHO, VEM COMIGO À MESA A CEAR;\nTUDO FIZ, NA CRUZ MORRI POR AMOR,\nPRA DAR VIDA AO PERDIDO PECADOR''.\n\n''ESTE PÃO QUE EU VOS DOU REPRESENTA \nO MEU CORPO QUE ENTREGUEI \nNA CRUZ POR AMOR''.\n\nCORO\nOUÇO A VOZ DO MEU AMADO ME CHAMAR\n''FILHO, VEM COMIGO À MESA A CEAR;\nTUDO FIZ, NA CRUZ MORRI POR AMOR,\nPRA DAR VIDA AO PERDIDO PECADOR''.\n\n''ESTE CÁLICE VOS DOU, REPRESENTA O \nMEU SANGUE QUE DERRAMEI NA CRUZ POR AMOR''.\n\nFINAL:\nOUÇO A VOZ DO MEU AMADO ME CHAMAR\n''FILHO, VEM COMIGO À MESA A CEAR''.', '<coro>\nOUÇO A VOZ DO MEU AMADO ME CHAMAR\n''FILHO, VEM COMIGO À MESA A CEAR;\nTUDO FIZ, NA CRUZ MORRI POR AMOR,\nPRA DAR VIDA AO PERDIDO PECADOR''.\n\n''ESTE PÃO QUE EU VOS DOU REPRESENTA \nO MEU CORPO QUE ENTREGUEI \nNA CRUZ POR AMOR''.\n\n<coro>\nOUÇO A VOZ DO MEU AMADO ME CHAMAR\n''FILHO, VEM COMIGO À MESA A CEAR;\nTUDO FIZ, NA CRUZ MORRI POR AMOR,\nPRA DAR VIDA AO PERDIDO PECADOR''.\n\n''ESTE CÁLICE VOS DOU, REPRESENTA O \nMEU SANGUE QUE DERRAMEI NA CRUZ POR AMOR''.\n<final>OUÇO A VOZ DO MEU AMADO ME CHAMAR\n''FILHO, VEM COMIGO À MESA A CEAR''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (433, 'TOMAI AGORA O PÃO', 'TOMAI AGORA O PÃO', 'TOMAI AGORA O PÃO, EU O PARTI POR VÓS, \nE AO FAZERDES, LEMBRAI-VOS DE MIM;\nFAZEI ISTO E COMEI-O, QUANDO O FIZERDES, \nLEMBRAI-VOS DE MIM.\nESTE PÃO É O MEU CORPO, \nPARTIDO SOMENTE POR VÓS, \nTOMAI-O, COMEI-O, \nFAZEI-O EM MEMÓRIA DE MIM.\n\nTOMAI O CÁLICE, EU O ENCHI POR VÓS,\nE AO FAZERDES, LEMBRAI-VOS DE MIM;\nFAZEI ISTO E BEBEI-O, QUANDO O FIZERDES, \nLEMBRAI-VOS DE MIM.\nESTE É O NOVO CONCERTO \nQUE FAÇO SOMENTE POR VÓS, \nTOMAI-O, BEBEI-O, FAZEI-O,\nEM MEMÓRIA DE MIM. (3X)', 'TOMAI AGORA O PÃO, EU O PARTI POR VÓS, \nE AO FAZERDES, LEMBRAI-VOS DE MIM;\nFAZEI ISTO E COMEI-O, QUANDO O FIZERDES, \nLEMBRAI-VOS DE MIM.\nESTE PÃO É O MEU CORPO, \nPARTIDO SOMENTE POR VÓS, \nTOMAI-O, COMEI-O, \nFAZEI-O EM MEMÓRIA DE MIM.\n\nTOMAI O CÁLICE, EU O ENCHI POR VÓS,\nE AO FAZERDES, LEMBRAI-VOS DE MIM;\nFAZEI ISTO E BEBEI-O, QUANDO O FIZERDES, \nLEMBRAI-VOS DE MIM.\nESTE É O NOVO CONCERTO \nQUE FAÇO SOMENTE POR VÓS, \nTOMAI-O, BEBEI-O, FAZEI-O,\nEM MEMÓRIA DE MIM. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (434, 'HÁ UM DOCE ESPÍRITO AQUI', 'HÁ UM DOCE ESPÍRITO AQUI', 'HÁ UM DOCE ESPÍRITO AQUI\nE EU SEI QUE É O ESPÍRITO DE DEUS;\nJÁ PODEMOS TODOS PERCEBER\nA PRESENÇA DE JESUS, O SALVADOR.\n\nCORO\nDOCE PRESENÇA, PRESENÇA SANTA, \nVEM SOBRE NÓS, ENCHENDO-NOS \nDO TEU PODER;\nTE ADORAREMOS POR TUA PRESENÇA \nAQUI E QUE RENOVARÁ \nOS NOSSOS CORAÇÕES, \nLOUVADO SEJA O SENHOR \n\nSE TE ACHAS SALVO, E AO INVÉS,\nESTÁS DÉBIL, OPRIMIDO E SEM VIGOR,\nRENDE-TE À PRESENÇA DE JESUS\nE O ESPÍRITO TE ENCHERÁ DE AMOR.\n\nCORO\nDOCE PRESENÇA, PRESENÇA SANTA, \nVEM SOBRE NÓS, ENCHENDO-NOS \nDO TEU PODER;\nTE ADORAREMOS POR TUA PRESENÇA \nAQUI E QUE RENOVARÁ \nOS NOSSOS CORAÇÕES, \nLOUVADO SEJA O SENHOR (BIS)', 'HÁ UM DOCE ESPÍRITO AQUI\nE EU SEI QUE É O ESPÍRITO DE DEUS;\nJÁ PODEMOS TODOS PERCEBER\nA PRESENÇA DE JESUS, O SALVADOR.\n\n<coro>\nDOCE PRESENÇA, PRESENÇA SANTA, \nVEM SOBRE NÓS, ENCHENDO-NOS \nDO TEU PODER;\nTE ADORAREMOS POR TUA PRESENÇA \nAQUI E QUE RENOVARÁ \nOS NOSSOS CORAÇÕES, \nLOUVADO SEJA O SENHOR \n\nSE TE ACHAS SALVO, E AO INVÉS,\nESTÁS DÉBIL, OPRIMIDO E SEM VIGOR,\nRENDE-TE À PRESENÇA DE JESUS\nE O ESPÍRITO TE ENCHERÁ DE AMOR.\n\n<coro>\nDOCE PRESENÇA, PRESENÇA SANTA, \nVEM SOBRE NÓS, ENCHENDO-NOS \nDO TEU PODER;\nTE ADORAREMOS POR TUA PRESENÇA \nAQUI E QUE RENOVARÁ \nOS NOSSOS CORAÇÕES, \nLOUVADO SEJA O SENHOR <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (435, 'FLUIRÁ COMO UM RIO', 'FLUIRÁ COMO UM RIO', 'FLUIRÁ COMO UM RIO, COMO A CHUVA CAIRÁ, \nCOMO ORVALHO, SOBRE OS MONTES E VALES COBRIRÁ!\nE A GLÓRIA DO SENHOR TODA TERRA ENCHERÁ \nE O ESPÍRITO DE DEUS VIRÁ!\nE O ESPÍRITO DE DEUS, E O ESPÍRITO DE DEUS, \nE O ESPÍRITO DE DEUS VIRÁ!', 'FLUIRÁ COMO UM RIO, COMO A CHUVA CAIRÁ, \nCOMO ORVALHO, SOBRE OS MONTES E VALES COBRIRÁ!\nE A GLÓRIA DO SENHOR TODA TERRA ENCHERÁ \nE O ESPÍRITO DE DEUS VIRÁ!\nE O ESPÍRITO DE DEUS, E O ESPÍRITO DE DEUS, \nE O ESPÍRITO DE DEUS VIRÁ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (436, 'ESPÍRITO DO TRINO DEUS', 'ESPÍRITO DO TRINO DEUS', 'ESPÍRITO DO TRINO DEUS, VEM SOBRE MIM,\nESPÍRITO DO TRINO DEUS, VEM SOBRE MIM.\nQUEBRANTA-ME, CONSOLA-ME,\nTRANSFORMA-ME, TRANSBORDA-ME;\nESPÍRITO DO TRINO DEUS VEM SOBRE MIM.\n\nREPETE O LOUVOR', 'ESPÍRITO DO TRINO DEUS, VEM SOBRE MIM,\nESPÍRITO DO TRINO DEUS, VEM SOBRE MIM.\nQUEBRANTA-ME, CONSOLA-ME,\nTRANSFORMA-ME, TRANSBORDA-ME;\nESPÍRITO DO TRINO DEUS VEM SOBRE MIM.\n\nREPETE O LOUVOR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (437, 'VEM SOBRE MIM, ESPÍRITO DE DEUS', 'VEM SOBRE MIM, ESPÍRITO DE DEUS', 'VEM SOBRE MIM, ESPÍRITO DE DEUS,\nA TI ME RENDO EM COMPLETA SUBMISSÃO\nVEM COM PODER, COM GRAÇA DOS CÉUS,\nVEM HOJE ENCHER MEU CORAÇÃO.\n\nCORO\nVEM, SIM, VEM, COMO A BRISA DA \nMANHÃ TRAZENDO O AROMA \nDOS JARDINS CELESTIAIS;\nVEM, SIM, VEM, COMO UM FORTE VENTO \nVEM, DE TI EU QUERO MAIS E MAIS.\n\nSEM TEU PODER NÃO PODEREI VIVER,\nVEM SOBRE MIM, Ó ESPÍRITO DE DEUS;\nSEM TUA UNÇÃO NÃO PODEREI VENCER,\nVEM HOJE ENCHER MEU CORAÇÃO.\n\nCORO\nVEM, SIM, VEM, COMO A BRISA DA \nMANHÃ TRAZENDO O AROMA \nDOS JARDINS CELESTIAIS;\nVEM, SIM, VEM, COMO UM FORTE VENTO \nVEM, DE TI EU QUERO MAIS E MAIS.\n\nFINAL: DE TI EU QUERO MAIS E MAIS.', 'VEM SOBRE MIM, ESPÍRITO DE DEUS,\nA TI ME RENDO EM COMPLETA SUBMISSÃO\nVEM COM PODER, COM GRAÇA DOS CÉUS,\nVEM HOJE ENCHER MEU CORAÇÃO.\n\n<coro>\nVEM, SIM, VEM, COMO A BRISA DA \nMANHÃ TRAZENDO O AROMA \nDOS JARDINS CELESTIAIS;\nVEM, SIM, VEM, COMO UM FORTE VENTO \nVEM, DE TI EU QUERO MAIS E MAIS.\n\nSEM TEU PODER NÃO PODEREI VIVER,\nVEM SOBRE MIM, Ó ESPÍRITO DE DEUS;\nSEM TUA UNÇÃO NÃO PODEREI VENCER,\nVEM HOJE ENCHER MEU CORAÇÃO.\n\n<coro>\nVEM, SIM, VEM, COMO A BRISA DA \nMANHÃ TRAZENDO O AROMA \nDOS JARDINS CELESTIAIS;\nVEM, SIM, VEM, COMO UM FORTE VENTO \nVEM, DE TI EU QUERO MAIS E MAIS.\n<final>DE TI EU QUERO MAIS E MAIS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (438, 'O ESPÍRITO DO SENHOR ESTÁ SENDO DERRAMADO', 'O ESPÍRITO DO SENHOR ESTÁ SENDO DERRAMADO', 'O ESPÍRITO DO SENHOR \nESTÁ SENDO DERRAMADO,\nPREPARANDO A NOIVA AMADA \nPARA AS BODAS DO CORDEIRO!\nMARANATA! MARANATA!\nORA VEM, JESUS!\nMARANATA! MARANATA!\nORA VEM, JESUS!', 'O ESPÍRITO DO SENHOR \nESTÁ SENDO DERRAMADO,\nPREPARANDO A NOIVA AMADA \nPARA AS BODAS DO CORDEIRO!\nMARANATA! MARANATA!\nORA VEM, JESUS!\nMARANATA! MARANATA!\nORA VEM, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (439, 'Ó VEM DERRAMAR', 'Ó VEM DERRAMAR', 'Ó VEM DERRAMAR, MEU SENHOR,\nA PORÇÃO DO TEU SANTO ESPÍRITO\nSOBRE MIM, SOBRE MIM.\n\nCORO\nPERMITE ENTRAR NA TUA GLÓRIA,\nSENTIR O TOQUE DE JESUS\nE EM MISTÉRIO ENTÃO FALAR,\nLOUVAR O NOME DE JESUS.\n\nQUERO EM COMUNHÃO TE ADORAR,\nTE EXALTAR, Ó TRIUNO DEUS,\nTEU AMOR PROCLAMAR.\n\nCORO (2X)\nPERMITE ENTRAR NA TUA GLÓRIA,\nSENTIR O TOQUE DE JESUS\nE EM MISTÉRIO ENTÃO FALAR,\nLOUVAR O NOME DE JESUS.\n\nFINAL: LOUVAR O NOME DE JESUS. (2X)', 'Ó VEM DERRAMAR, MEU SENHOR,\nA PORÇÃO DO TEU SANTO ESPÍRITO\nSOBRE MIM, SOBRE MIM.<coro>\nPERMITE ENTRAR NA TUA GLÓRIA,\nSENTIR O TOQUE DE JESUS\nE EM MISTÉRIO ENTÃO FALAR,\nLOUVAR O NOME DE JESUS.\n\nQUERO EM COMUNHÃO TE ADORAR,\nTE EXALTAR, Ó TRIUNO DEUS,\nTEU AMOR PROCLAMAR.<coro tipo=''2X''>\nPERMITE ENTRAR NA TUA GLÓRIA,\nSENTIR O TOQUE DE JESUS\nE EM MISTÉRIO ENTÃO FALAR,\nLOUVAR O NOME DE JESUS.\n<final>LOUVAR O NOME DE JESUS. <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (440, 'DERRAMAREI MEU ESPÍRITO', 'DERRAMAREI MEU ESPÍRITO', 'DERRAMAREI MEU ESPÍRITO\nSOBRE TODA A CARNE \nE VOSSOS FILHOS E VOSSAS \nFILHAS PROFETIZARÃO, \nOS VOSSOS VELHOS TERÃO SONHOS,\nVOSSOS MANCEBOS, VISÕES.\n\nCORO (2X)\nPOIS DERRAMAREI MEU ESPÍRITO\nSOBRE TODA A CARNE.\n\nESPERAI, POIS, A PROMESSA\nQUE DE MIM OUVISTES:\nJOÃO BATIZOU COM ÁGUA\nMAS EU VOS BATIZO\nCOM MEU ESPÍRITO, COM MEU PODER,\nDE MIM SEREIS TESTEMUNHAS.', 'DERRAMAREI MEU ESPÍRITO\nSOBRE TODA A CARNE \nE VOSSOS FILHOS E VOSSAS \nFILHAS PROFETIZARÃO, \nOS VOSSOS VELHOS TERÃO SONHOS,\nVOSSOS MANCEBOS, VISÕES.\n\n<coro tipo=''2X''>\nPOIS DERRAMAREI MEU ESPÍRITO\nSOBRE TODA A CARNE.\n\nESPERAI, POIS, A PROMESSA\nQUE DE MIM OUVISTES:\nJOÃO BATIZOU COM ÁGUA\nMAS EU VOS BATIZO\nCOM MEU ESPÍRITO, COM MEU PODER,\nDE MIM SEREIS TESTEMUNHAS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (441, 'ESPÍRITO SANTO, Ó CONSOLADOR', 'ESPÍRITO SANTO, Ó CONSOLADOR', 'ESPÍRITO SANTO, Ó CONSOLADOR,\nVISITA O TEU POVO COM GRAÇA E AMOR;\nÓ VENTO QUE SOPRAS NOS JARDINS DE DEUS, \nDERRAMA PODER,\nESPALHA ENTRE NÓS O AROMA DOS CÉUS!\n\nESPÍRITO SANTO, Ó CONSOLADOR,\nVISITA O TEU POVO COM GRAÇA E AMOR;\nÓ VENTO QUE SOPRAS NOS JARDINS DE DEUS, \nDERRAMA PODER,\nESPALHA ENTRE NÓS O AROMA DOS CÉUS!\n\n\nFINAL: \nDERRAMA PODER, ESPALHA ENTRE NÓS \nO AROMA DOS CÉUS.', 'ESPÍRITO SANTO, Ó CONSOLADOR,\nVISITA O TEU POVO COM GRAÇA E AMOR;\nÓ VENTO QUE SOPRAS NOS JARDINS DE DEUS, \nDERRAMA PODER,\nESPALHA ENTRE NÓS O AROMA DOS CÉUS!\n\nESPÍRITO SANTO, Ó CONSOLADOR,\nVISITA O TEU POVO COM GRAÇA E AMOR;\nÓ VENTO QUE SOPRAS NOS JARDINS DE DEUS, \nDERRAMA PODER,\nESPALHA ENTRE NÓS O AROMA DOS CÉUS!\n<final>DERRAMA PODER, ESPALHA ENTRE NÓS \nO AROMA DOS CÉUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (442, 'MAIS DO TEU SANTO ESPÍRITO', 'MAIS DO TEU SANTO ESPÍRITO', 'MAIS DO TEU SANTO ESPÍRITO, DÁ-NOS, SENHOR,\nMAIS DOS TESOUROS ESCONDIDOS DO TEU AMOR;\nMAIS, MUITO MAIS TU TENS PARA NOS \nDAR SE TEU POVO TE BUSCAR, MAIS, \nMUITO MAIS, TU QUERES ABENÇOAR.\n\nCORO\nPOR ISSO TE ROGAMOS, COM FÉ ORAMOS, \nMANIFESTA TUA GRAÇA HOJE AQUI; \nDÁ-NOS PORÇÃO DOBRADA \nDO TEU SANTO ESPÍRITO,\nPARA QUE MAIS, MUITO MAIS,\nPOSSAMOS TE SERVIR.\n\nVEM REVELAR A ESTA GERAÇÃO\nAS MARAVILHAS E SINAIS DA SALVAÇÃO;\nTAL COMO A NOSSOS PAIS MOSTRASTE \nABUNDANTE GRAÇA E AMOR, MAIS, \nMUITO MAIS, CONCEDE-NOS, SENHOR.\n\nCORO\nPOR ISSO TE ROGAMOS, COM FÉ ORAMOS, \nMANIFESTA TUA GRAÇA HOJE AQUI; \nDÁ-NOS PORÇÃO DOBRADA \nDO TEU SANTO ESPÍRITO,\nPARA QUE MAIS, MUITO MAIS,\nPOSSAMOS TE SERVIR.', 'MAIS DO TEU SANTO ESPÍRITO, DÁ-NOS, SENHOR,\nMAIS DOS TESOUROS ESCONDIDOS DO TEU AMOR;\nMAIS, MUITO MAIS TU TENS PARA NOS \nDAR SE TEU POVO TE BUSCAR, MAIS, \nMUITO MAIS, TU QUERES ABENÇOAR.\n\n<coro>\nPOR ISSO TE ROGAMOS, COM FÉ ORAMOS, \nMANIFESTA TUA GRAÇA HOJE AQUI; \nDÁ-NOS PORÇÃO DOBRADA \nDO TEU SANTO ESPÍRITO,\nPARA QUE MAIS, MUITO MAIS,<bis>\nPOSSAMOS TE SERVIR.<bis>\n\nVEM REVELAR A ESTA GERAÇÃO\nAS MARAVILHAS E SINAIS DA SALVAÇÃO;\nTAL COMO A NOSSOS PAIS MOSTRASTE \nABUNDANTE GRAÇA E AMOR, MAIS, \nMUITO MAIS, CONCEDE-NOS, SENHOR.\n\n<coro>\nPOR ISSO TE ROGAMOS, COM FÉ ORAMOS, \nMANIFESTA TUA GRAÇA HOJE AQUI; \nDÁ-NOS PORÇÃO DOBRADA \nDO TEU SANTO ESPÍRITO,\nPARA QUE MAIS, MUITO MAIS,<bis>\nPOSSAMOS TE SERVIR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (443, 'HÁ UM RIO DE ÁGUAS VIVAS', 'HÁ UM RIO DE ÁGUAS VIVAS', 'HÁ UM RIO DE ÁGUAS VIVAS\nQUE PROCEDEM DO TRONO DO SENHOR,\nONDE PASSAM NASCE A VIDA, \nDOS DESERTOS FAZEM JARDINS DE AMOR.\n\nCORO\nOH! EU QUERO ESTAR ONDE CORREM\nESSAS ÁGUAS DE PROFUNDA PAZ.\n\nESSE RIO É O ESPÍRITO\nDERRAMADO SOBRE TODO O QUE CRÊ;\nELE PASSA HOJE POR AQUI\nE TE QUER ENCHER DE GOZO E PODER.\n\nCORO\nOH! EU QUERO ESTAR ONDE CORREM\nESSAS ÁGUAS DE PROFUNDA PAZ.\n\nSE QUERES JUBILAR POR TUA SALVAÇÃO,\nENTRA NESSE RIO E VEM SEM TEMOR;\nDEIXA SUBMERGIR TODO O TEU SER\nNAS PROFUNDAS ÁGUAS DO SEU AMOR.', 'HÁ UM RIO DE ÁGUAS VIVAS\nQUE PROCEDEM DO TRONO DO SENHOR,\nONDE PASSAM NASCE A VIDA, \nDOS DESERTOS FAZEM JARDINS DE AMOR.\n\n<coro>\nOH! EU QUERO ESTAR ONDE CORREM\nESSAS ÁGUAS DE PROFUNDA PAZ.\n\nESSE RIO É O ESPÍRITO\nDERRAMADO SOBRE TODO O QUE CRÊ;\nELE PASSA HOJE POR AQUI\nE TE QUER ENCHER DE GOZO E PODER.\n\n<coro>\nOH! EU QUERO ESTAR ONDE CORREM\nESSAS ÁGUAS DE PROFUNDA PAZ.\n\nSE QUERES JUBILAR POR TUA SALVAÇÃO,\nENTRA NESSE RIO E VEM SEM TEMOR;\nDEIXA SUBMERGIR TODO O TEU SER\nNAS PROFUNDAS ÁGUAS DO SEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (444, 'DESEJEI ARDENTEMENTE', 'DESEJEI ARDENTEMENTE', 'DESEJEI ARDENTEMENTE\nCONVOSCO CEAR, POVO MEU.\n\nTOMAI AGORA O PÃO QUE REPRESENTA\nO MEU CORPO QUE É DADO POR VÓS (BIS)\n\nCORO\nALEGRAI-VOS\nREGOZIJAI-VOS\nVÓS QUE ESTAIS À MESA.\n\nINSTRUMENTOS\n\nDESEJEI ARDENTEMENTE\nCONVOSCO CEAR, POVO MEU\n\nTOMAI O CÁLICE QUE REPRESENTA\nO MEU SANGUE VERTIDO POR VÓS (BIS)\n\nCORO\nALEGRAI-VOS \nREGOZIJAI-VOS \nVÓS QUE ESTAIS À MESA.\n\nINSTRUMENTOS\n\nFINAL: \nALEGRAI-VOS, VÓS QUE ESTAIS À MESA.', 'DESEJEI ARDENTEMENTE<bis>\nCONVOSCO CEAR, POVO MEU.<bis>\n\nTOMAI AGORA O PÃO QUE REPRESENTA\nO MEU CORPO QUE É DADO POR VÓS <bis>\n\n<coro>\nALEGRAI-VOS<bis>\nREGOZIJAI-VOS<bis>\nVÓS QUE ESTAIS À MESA.<bis>\n<instrumentos>\nDESEJEI ARDENTEMENTE\nCONVOSCO CEAR, POVO MEU<bis>\n\nTOMAI O CÁLICE QUE REPRESENTA\nO MEU SANGUE VERTIDO POR VÓS (BIS)<coro>\nALEGRAI-VOS <bis>\nREGOZIJAI-VOS <bis>\nVÓS QUE ESTAIS À MESA.\n<instrumentos>\n<final>ALEGRAI-VOS, VÓS QUE ESTAIS À MESA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (445, 'DIRIGE-ME, SENHOR', 'DIRIGE-ME, SENHOR', 'DIRIGE-ME, SENHOR, FAZ ESTA CANDEIA ILUMINAR, \nQUE A ENCHAS COM TEU ÓLEO PARA NUNCA APAGAR;\nNO TEU TABERNÁCULO EU TE ENCONTRO, AGORA, \nALÉM DO VÉU RASGADO PRA MIM, TE ENCONTRAREI\nETERNAMENTE, DA TARDE ATÉ O AMANHECER,\nCUIDANDO DA CANDEIA QUE É O MEU SER,\nNA TUA PRESENÇA EU QUERO VIVER.', 'DIRIGE-ME, SENHOR, FAZ ESTA CANDEIA ILUMINAR, <bis>\nQUE A ENCHAS COM TEU ÓLEO PARA NUNCA APAGAR;<bis>\nNO TEU TABERNÁCULO EU TE ENCONTRO, AGORA, <bis>\nALÉM DO VÉU RASGADO PRA MIM, TE ENCONTRAREI<bis>\nETERNAMENTE, DA TARDE ATÉ O AMANHECER,<bis>\nCUIDANDO DA CANDEIA QUE É O MEU SER,<bis>\nNA TUA PRESENÇA EU QUERO VIVER.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (446, 'A TUA PALAVRA', 'A TUA PALAVRA', 'A TUA PALAVRA É TESOURO ESCONDIDO\nQUE ALGUÉM ENCONTROU;\nMISTÉRIOS SELADOS QUE O ESPÍRITO SANTO \nA NÓS REVELOU. \nA TUA PALAVRA É TRIGO GUARDADO,\nMALHADO NO LAGAR DE DEUS,\nNOSSO PÃO DO CÉU!\n\nCORO\nBENDITA PALAVRA \nQUE CURA E SALVA\nA QUEM NELA CRÊ, \nPALAVRA DE DEUS!\n\nA TUA PALAVRA É ABRIGO SEGURO \nQUE VIDA NOS TRAZ, \nA ROCHA DOS SÉCULOS, \nBEM FIRME ALICERCE, ETERNA E VERAZ; \nFELIZ QUEM SOBRE ELA EDIFICA SUA CASA,\nTORMENTAS ELA VENCERÁ, NÃO VACILARÁ!\n\nCORO\nBENDITA PALAVRA \nQUE CURA E SALVA\nA QUEM NELA CRÊ, \nPALAVRA DE DEUS!\n\nFINAL: PALAVRA DE DEUS!', 'A TUA PALAVRA É TESOURO ESCONDIDO\nQUE ALGUÉM ENCONTROU;\nMISTÉRIOS SELADOS QUE O ESPÍRITO SANTO \nA NÓS REVELOU. \nA TUA PALAVRA É TRIGO GUARDADO,\nMALHADO NO LAGAR DE DEUS,\nNOSSO PÃO DO CÉU!\n\n<coro>\nBENDITA PALAVRA \nQUE CURA E SALVA\nA QUEM NELA CRÊ, \nPALAVRA DE DEUS!\n\nA TUA PALAVRA É ABRIGO SEGURO \nQUE VIDA NOS TRAZ, \nA ROCHA DOS SÉCULOS, \nBEM FIRME ALICERCE, ETERNA E VERAZ; \nFELIZ QUEM SOBRE ELA EDIFICA SUA CASA,\nTORMENTAS ELA VENCERÁ, NÃO VACILARÁ!\n\n<coro>\nBENDITA PALAVRA \nQUE CURA E SALVA\nA QUEM NELA CRÊ, \nPALAVRA DE DEUS!\n<final>PALAVRA DE DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (447, 'SENHOR, GUIA-NOS', 'SENHOR, GUIA-NOS', 'SENHOR, GUIA-NOS À TUA PRESENÇA \nONDE O TEU SANGUE PURIFICA;\nFAZE-NOS UM, UM SÓ CORPO, \nUMA SÓ MENTE, UM CORAÇÃO.\n\nCORO\nSOMOS TEUS, REUNIDOS PRA LOUVAR TEU SANTO \nNOME, ADORAMOS SÓ A TI; GUIA-NOS À TUA GLÓRIA, \nTEU ESPÍRITO DERRAMADO REVELANDO O TEU QUERER;\nGUIA-NOS À TUA GLÓRIA, NÃO HÁ NADA \nMAIS PRECIOSO, NADA QUE QUEIRAMOS MAIS, \nGUIA-NOS. \n\nJÁ SOMOS UM, UM SÓ CORPO, \nUMA SÓ MENTE, UM CORAÇÃO, \nPRA TE OFERTAR TÃO SOMENTE \nNOSSO AMOR E GRATIDÃO.\n\nCORO\nSOMOS TEUS, REUNIDOS PRA LOUVAR TEU SANTO \nNOME, ADORAMOS SÓ A TI; GUIA-NOS À TUA GLÓRIA, \nTEU ESPÍRITO DERRAMADO REVELANDO O TEU QUERER;\nGUIA-NOS À TUA GLÓRIA, NÃO HÁ NADA \nMAIS PRECIOSO, NADA QUE QUEIRAMOS MAIS, \nGUIA-NOS. \n\nFINAL: GUIA-NOS.', 'SENHOR, GUIA-NOS À TUA PRESENÇA \nONDE O TEU SANGUE PURIFICA;\nFAZE-NOS UM, UM SÓ CORPO, \nUMA SÓ MENTE, UM CORAÇÃO.\n\n<coro>\nSOMOS TEUS, REUNIDOS PRA LOUVAR TEU SANTO \nNOME, ADORAMOS SÓ A TI; GUIA-NOS À TUA GLÓRIA, \nTEU ESPÍRITO DERRAMADO REVELANDO O TEU QUERER;\nGUIA-NOS À TUA GLÓRIA, NÃO HÁ NADA \nMAIS PRECIOSO, NADA QUE QUEIRAMOS MAIS, \nGUIA-NOS. \n\nJÁ SOMOS UM, UM SÓ CORPO, \nUMA SÓ MENTE, UM CORAÇÃO, \nPRA TE OFERTAR TÃO SOMENTE \nNOSSO AMOR E GRATIDÃO.\n\n<coro>\nSOMOS TEUS, REUNIDOS PRA LOUVAR TEU SANTO \nNOME, ADORAMOS SÓ A TI; GUIA-NOS À TUA GLÓRIA, \nTEU ESPÍRITO DERRAMADO REVELANDO O TEU QUERER;\nGUIA-NOS À TUA GLÓRIA, NÃO HÁ NADA \nMAIS PRECIOSO, NADA QUE QUEIRAMOS MAIS, \nGUIA-NOS. \n<final>GUIA-NOS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (448, 'SENHOR, EU QUERO SERVIR-TE', 'SENHOR, EU QUERO SERVIR-TE', 'SENHOR, EU QUERO SERVIR-TE,\nSERVIR-TE COM TODO O MEU SER,\nCANTANDO, SEMPRE CANTANDO,\nLOUVANDO COM TODO O PRAZER.\n\nCORO\nJESUS, JESUS,\nFIRMADO EM TI QUERO ESTAR,\nJESUS, JESUS,\nNÃO QUERO, NÃO QUERO FALHAR.\n\nPERMITE QUE EU FALE SOMENTE\nDA GRAÇA E DO AMOR DIVINAL,\nPROCLAME AS TUAS VERDADES\nATÉ A VITÓRIA FINAL.', 'SENHOR, EU QUERO SERVIR-TE,\nSERVIR-TE COM TODO O MEU SER,\nCANTANDO, SEMPRE CANTANDO,\nLOUVANDO COM TODO O PRAZER.\n\n<coro>\nJESUS, JESUS,\nFIRMADO EM TI QUERO ESTAR,\nJESUS, JESUS,\nNÃO QUERO, NÃO QUERO FALHAR.\n\nPERMITE QUE EU FALE SOMENTE\nDA GRAÇA E DO AMOR DIVINAL,\nPROCLAME AS TUAS VERDADES\nATÉ A VITÓRIA FINAL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (449, 'A MINHA VIDA ENTREGO', 'A MINHA VIDA ENTREGO', 'A MINHA VIDA ENTREGO EM TUAS MÃOS, \nSENHOR, TUDO O QUE SOU A TI EU DOU,\nTODO O MEU SER; O QUE NA ETERNIDADE \nPLANEJASTE PRA MIM DESEJO EXPERIMENTAR EM MEU VIVER.\n\nNÃO PEÇO PARA MIM RIQUEZAS SEM VALOR, \nSÓ PEÇO CADA DIA A LUZ DO TEU AMOR, \nBEM SEI QUE ÉS FIEL, DE MIM TU CUIDARÁS, \nA TEMPESTADE ACALMAS, DÁ-ME PAZ.\n\nCORO\n''EU CUIDAREI DE TI \n(EU CUIDAREI DE TI) VARÕES\nNÃO FALHARÁ O MEU AMOR'',\nOS DIAS PASSARÃO MAS PERMANECERÁ\nEM TI A BÊNÇÃO DO SENHOR.\n\nCOM TEU OLHAR DIRIGES OS PASSOS MEUS, \nSENHOR, AJUDA-ME A GUARDAR \nA HERANÇA, BEM MAIOR, \nPOIS QUERO TE SERVIR, \nTUA OBRA REALIZAR;\nÓ PAI BENDITO, ENTREGO-ME NO ALTAR.\n\nCORO\n''EU CUIDAREI DE TI \n(EU CUIDAREI DE TI) VARÕES\nNÃO FALHARÁ O MEU AMOR'',\nOS DIAS PASSARÃO MAS PERMANECERÁ\nEM TI A BÊNÇÃO DO SENHOR.', 'A MINHA VIDA ENTREGO EM TUAS MÃOS, \nSENHOR, TUDO O QUE SOU A TI EU DOU,\nTODO O MEU SER; O QUE NA ETERNIDADE \nPLANEJASTE PRA MIM DESEJO EXPERIMENTAR EM MEU VIVER.\n\nNÃO PEÇO PARA MIM RIQUEZAS SEM VALOR, \nSÓ PEÇO CADA DIA A LUZ DO TEU AMOR, \nBEM SEI QUE ÉS FIEL, DE MIM TU CUIDARÁS, \nA TEMPESTADE ACALMAS, DÁ-ME PAZ.\n\n<coro>\n''EU CUIDAREI DE TI \n(EU CUIDAREI DE TI) <h>\nNÃO FALHARÁ O MEU AMOR'',\nOS DIAS PASSARÃO MAS PERMANECERÁ\nEM TI A BÊNÇÃO DO SENHOR.\n\nCOM TEU OLHAR DIRIGES OS PASSOS MEUS, \nSENHOR, AJUDA-ME A GUARDAR \nA HERANÇA, BEM MAIOR, \nPOIS QUERO TE SERVIR, \nTUA OBRA REALIZAR;\nÓ PAI BENDITO, ENTREGO-ME NO ALTAR.\n\n<coro>\n''EU CUIDAREI DE TI \n(EU CUIDAREI DE TI) <h>\nNÃO FALHARÁ O MEU AMOR'',\nOS DIAS PASSARÃO MAS PERMANECERÁ\nEM TI A BÊNÇÃO DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (450, 'A TUA JUSTIÇA', 'A TUA JUSTIÇA', 'A TUA JUSTIÇA, Ó DEUS,\nESTÁ MUITO ACIMA DOS CÉUS,\nPOIS FIZESTE GRANDES COISAS Ó DEUS,\nQUEM É SEMELHANTE A TI?\n\n3X\n\nTU QUE ME TENS FEITO VER\nMUITOS MALES E ANGÚSTIAS,\nME DARÁS AINDA A VIDA\nE ME LIVRARÁS DOS ABISMOS DA TERRA, \nAUMENTARÁS A MINHA GRANDEZA,\nNOVAMENTE ME CONSOLARÁS,\nNOVAMENTE ME CONSOLARÁS.\n\nTAMBÉM EU TE LOUVAREI \nCOM O SALTÉRIO,\nBEM COMO À TUA VERDADE, \nÓ MEU DEUS,\nCANTAR-TE-EI COM HARPA,\nÓ SANTO DE ISRAEL, \n(SANTO DE ISRAEL) VARÕES\nÓ SANTO DE ISRAEL,\nÓ SANTO DE ISRAEL, SENHOR.\n\nOS MEUS LÁBIOS EXULTARÃO \nQUANDO A TI CANTAR, \nASSIM COMO A MINHA ALMA\nQUE TU REMISTE, SENHOR;\nA MINHA LÍNGUA FALARÁ \nDA TUA JUSTIÇA TODO DIA.\nPOIS CONFUNDIDOS ESTÃO \nMEUS INIMIGOS. \n\nA TUA JUSTIÇA, Ó DEUS,\nESTÁ MUITO ACIMA DOS CÉUS,\nPOIS FIZESTE GRANDES COISAS Ó DEUS,\nQUEM É SEMELHANTE A TI?\n\nTU QUE ME TENS FEITO VER\nMUITOS MALES E ANGÚSTIAS,\nME DARÁS AINDA A VIDA \nE ME LIVRARÁS DOS ABISMOS DA TERRA,\nAUMENTARÁS A MINHA GRANDEZA,\nNOVAMENTE ME CONSOLARÁS,\nNOVAMENTE ME CONSOLARÁS.\n\nFINAL: NOVAMENTE ME CONSOLARÁS.', 'A TUA JUSTIÇA, Ó DEUS,\nESTÁ MUITO ACIMA DOS CÉUS,\nPOIS FIZESTE GRANDES COISAS Ó DEUS,\nQUEM É SEMELHANTE A TI?\n\n<bis tipo=''3''>\n\nTU QUE ME TENS FEITO VER\nMUITOS MALES E ANGÚSTIAS,\nME DARÁS AINDA A VIDA\nE ME LIVRARÁS DOS ABISMOS DA TERRA, \nAUMENTARÁS A MINHA GRANDEZA,\nNOVAMENTE ME CONSOLARÁS,\nNOVAMENTE ME CONSOLARÁS.\n\nTAMBÉM EU TE LOUVAREI \nCOM O SALTÉRIO,\nBEM COMO À TUA VERDADE, \nÓ MEU DEUS,\nCANTAR-TE-EI COM HARPA,\nÓ SANTO DE ISRAEL, \n(SANTO DE ISRAEL) <h>\nÓ SANTO DE ISRAEL,\nÓ SANTO DE ISRAEL, SENHOR.\n\nOS MEUS LÁBIOS EXULTARÃO \nQUANDO A TI CANTAR, \nASSIM COMO A MINHA ALMA\nQUE TU REMISTE, SENHOR;\nA MINHA LÍNGUA FALARÁ \nDA TUA JUSTIÇA TODO DIA.\nPOIS CONFUNDIDOS ESTÃO <bis>\nMEUS INIMIGOS. <bis>\n\nA TUA JUSTIÇA, Ó DEUS,\nESTÁ MUITO ACIMA DOS CÉUS,\nPOIS FIZESTE GRANDES COISAS Ó DEUS,\nQUEM É SEMELHANTE A TI?\n\nTU QUE ME TENS FEITO VER\nMUITOS MALES E ANGÚSTIAS,\nME DARÁS AINDA A VIDA \nE ME LIVRARÁS DOS ABISMOS DA TERRA,\nAUMENTARÁS A MINHA GRANDEZA,\nNOVAMENTE ME CONSOLARÁS,\nNOVAMENTE ME CONSOLARÁS.\n<final>NOVAMENTE ME CONSOLARÁS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (451, 'NO SERVIÇO DO MEU REI EU SOU FELIZ', 'NO SERVIÇO DO MEU REI EU SOU FELIZ', 'NO SERVIÇO DO MEU REI EU SOU FELIZ,\nSATISFEITO, ABENÇOADO,\nPROCLAMANDO DO MEU REI \nA SALVAÇÃO,\nNO SERVIÇO DO MEU REI.\n\nCORO\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.\n\nNO SERVIÇO DO MEU REI EU SOU FELIZ,\nOBEDIENTE E CORAJOSO,\nNA TRISTEZA OU NA ALEGRIA SEI SORRIR, \nNO SERVIÇO DO MEU REI.\n\nCORO\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.\n\nNO SERVIÇO DO MEU REI EU SOU FELIZ,\nJUBILOSO E CONSAGRADO,\nAO SEU LADO VENCEREI TODO MAL,\nNO SERVIÇO DO MEU REI.\n\nCORO\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.\n\nNO SERVIÇO DO MEU REI EU SOU FELIZ, \nVENTUROSO E DECIDIDO,\nMINHA VIDA AO SERVIÇO ENTREGAREI, \nNO SERVIÇO DO MEU REI.\n\nCORO\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.', 'NO SERVIÇO DO MEU REI EU SOU FELIZ,\nSATISFEITO, ABENÇOADO,\nPROCLAMANDO DO MEU REI \nA SALVAÇÃO,\nNO SERVIÇO DO MEU REI.\n\n<coro>\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.\n\nNO SERVIÇO DO MEU REI EU SOU FELIZ,\nOBEDIENTE E CORAJOSO,\nNA TRISTEZA OU NA ALEGRIA SEI SORRIR, \nNO SERVIÇO DO MEU REI.\n\n<coro>\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.\n\nNO SERVIÇO DO MEU REI EU SOU FELIZ,\nJUBILOSO E CONSAGRADO,\nAO SEU LADO VENCEREI TODO MAL,\nNO SERVIÇO DO MEU REI.\n\n<coro>\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.\n\nNO SERVIÇO DO MEU REI EU SOU FELIZ, \nVENTUROSO E DECIDIDO,\nMINHA VIDA AO SERVIÇO ENTREGAREI, \nNO SERVIÇO DO MEU REI.\n\n<coro>\nNO SERVIÇO DO MEU REI\nMINHA VIDA ENTREGAREI,\nGOZO, PAZ, FELICIDADE\nTEM QUEM SERVE A MEU BOM REI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (452, 'QUERO QUE ME TOQUES, SENHOR', 'QUERO QUE ME TOQUES, SENHOR', 'QUERO QUE ME TOQUES, SENHOR,\nCOM O TOQUE DO TEU SANTO ESPÍRITO.\n\nCORO\nEIS-ME AQUI, SENHOR (2X)\nFALA-ME, SENHOR, USA-ME, SENHOR.\n\nQUERO QUE ME FALES, SENHOR,\nO QUE DEVO FAZER PRA TUA OBRA REALIZAR.\nESTOU PRONTO A TE OUVIR VEM, \nSENHOR JESUS, MINHA VIDA USAR.\n\nCORO\nEIS-ME AQUI, SENHOR (2X)\nFALA-ME, SENHOR, USA-ME, SENHOR.\n\nFINAL: \nESTOU PRONTO A TE OUVIR\nVEM, SENHOR JESUS, \nMINHA VIDA USAR.', 'QUERO QUE ME TOQUES, SENHOR,<bis>\nCOM O TOQUE DO TEU SANTO ESPÍRITO.<coro><bis>\nEIS-ME AQUI, SENHOR <bis tipo=''2''>\nFALA-ME, SENHOR, USA-ME, SENHOR.\n\nQUERO QUE ME FALES, SENHOR,\nO QUE DEVO FAZER PRA TUA OBRA REALIZAR.\nESTOU PRONTO A TE OUVIR VEM, \nSENHOR JESUS, MINHA VIDA USAR.\n\n<coro>\nEIS-ME AQUI, SENHOR <bis tipo=''2''><bis>\nFALA-ME, SENHOR, USA-ME, SENHOR.<bis>\n<final>ESTOU PRONTO A TE OUVIR\nVEM, SENHOR JESUS, \nMINHA VIDA USAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (453, 'QUANDO DOBRO OS MEUS JOELHOS EM ORAÇÃO', 'QUANDO DOBRO OS MEUS JOELHOS EM ORAÇÃO', 'QUANDO DOBRO OS MEUS JOELHOS EM ORAÇÃO, VEJO QUÃO PEQUENO SOU DIANTE DO TEU PODER,\nSEI QUE POSSO DERRAMAR MEU CORAÇÃO EM TEU ALTAR POIS DE TI VEM A RESPOSTA, VEM O PERDÃO.\n\nCORO\nEU QUERO VOLTAR, VOLTAR AO PRIMEIRO AMOR.\nEU QUERO TE SERVIR, SENHOR,\nCOM TODO O MEU VIGOR POIS \nSE CHEGUEI ATÉ AQUI NÃO POSSO MAIS OLHAR \nPRA TRÁS EU QUERO PROSSEGUIR \nCONTIGO ATÉ O FIM.\n\nQUANDO VEJO O QUE FIZESTE EM MEU VIVER, \nTANTAS BÊNÇÃOS RECEBIDAS SEM MERECER,\nO MEU CORAÇÃO TRANSBORDA DE GRATIDÃO; \nQUE DAREI A TI, SENHOR, SENÃO O MEU LOUVOR?\n\nCORO\nEU QUERO VOLTAR, VOLTAR AO PRIMEIRO AMOR.\nEU QUERO TE SERVIR, SENHOR,\nCOM TODO O MEU VIGOR POIS \nSE CHEGUEI ATÉ AQUI NÃO POSSO MAIS OLHAR \nPRA TRÁS EU QUERO PROSSEGUIR \nCONTIGO ATÉ O FIM.\n\nFINAL: \nEU QUERO PROSSEGUIR \nCONTIGO ATÉ O FIM.', 'QUANDO DOBRO OS MEUS JOELHOS EM ORAÇÃO, VEJO QUÃO PEQUENO SOU DIANTE DO TEU PODER,\nSEI QUE POSSO DERRAMAR MEU CORAÇÃO EM TEU ALTAR POIS DE TI VEM A RESPOSTA, VEM O PERDÃO.\n\n<coro>\nEU QUERO VOLTAR, VOLTAR AO PRIMEIRO AMOR.\nEU QUERO TE SERVIR, SENHOR,\nCOM TODO O MEU VIGOR POIS \nSE CHEGUEI ATÉ AQUI NÃO POSSO MAIS OLHAR \nPRA TRÁS EU QUERO PROSSEGUIR \nCONTIGO ATÉ O FIM.\n\nQUANDO VEJO O QUE FIZESTE EM MEU VIVER, \nTANTAS BÊNÇÃOS RECEBIDAS SEM MERECER,\nO MEU CORAÇÃO TRANSBORDA DE GRATIDÃO; \nQUE DAREI A TI, SENHOR, SENÃO O MEU LOUVOR?\n\n<coro>\nEU QUERO VOLTAR, VOLTAR AO PRIMEIRO AMOR.<bis>\nEU QUERO TE SERVIR, SENHOR,<bis>\nCOM TODO O MEU VIGOR POIS <bis>\nSE CHEGUEI ATÉ AQUI NÃO POSSO MAIS OLHAR <bis>\nPRA TRÁS EU QUERO PROSSEGUIR <bis>\nCONTIGO ATÉ O FIM.\n<final>EU QUERO PROSSEGUIR \nCONTIGO ATÉ O FIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (454, 'SENHOR, MEU DEUS, O QUE DIREI DE TI? (SAÚDE ESPIRITUAL)', 'SENHOR, MEU DEUS, O QUE DIREI DE TI? (SAÚDE ESPIRITUAL)', 'SENHOR, MEU DEUS, O QUE DIREI DE TI?\nTU ÉS AQUELE QUE ME AMOU PRIMEIRO!\nMAS HOJE FRACO ESTOU, SINTO SAUDADES DE TI, \nSENHOR, E VIM CHORAR DIANTE AOS TEUS PÉS, \nEM ORAÇÃO.\n\nRENOVA EM MIM VALORES TEUS,\nORDENA OS PENSAMENTOS MEUS\nE DÁ-ME, Ó PAI, SAÚDE ESPIRITUAL;\nPRA COM PRIMEIRO AMOR TE AMAR,\nO AMOR QUE UM DIA CONHECI \nQUANDO TOCASTE EM MIM \nPELA PRIMEIRA VEZ.\n\nINSTRUMENTOS\n\nSENHOR, MEU DEUS, O QUE DIREI DE TI?\nTU ÉS AQUELE QUE ME AMOU PRIMEIRO!\nMAS HOJE FRACO ESTOU, SINTO SAUDADES DE TI, \nSENHOR, E VIM CHORAR DIANTE AOS TEUS PÉS, \nEM ORAÇÃO.\n\nRENOVA EM MIM VALORES TEUS, \nORDENA OS PENSAMENTOS MEUS E DÁ-ME, \nÓ PAI, SAÚDE ESPIRITUAL;\nPRA COM PRIMEIRO AMOR TE AMAR, \nO AMOR QUE UM DIA CONHECI \nQUANDO TOCASTE EM MIM \nPELA PRIMEIRA VEZ.', 'SENHOR, MEU DEUS, O QUE DIREI DE TI?\nTU ÉS AQUELE QUE ME AMOU PRIMEIRO!\nMAS HOJE FRACO ESTOU, SINTO SAUDADES DE TI, \nSENHOR, E VIM CHORAR DIANTE AOS TEUS PÉS, \nEM ORAÇÃO.\n\nRENOVA EM MIM VALORES TEUS,\nORDENA OS PENSAMENTOS MEUS\nE DÁ-ME, Ó PAI, SAÚDE ESPIRITUAL;\nPRA COM PRIMEIRO AMOR TE AMAR,\nO AMOR QUE UM DIA CONHECI \nQUANDO TOCASTE EM MIM \nPELA PRIMEIRA VEZ.\n<instrumentos>\n\n\nSENHOR, MEU DEUS, O QUE DIREI DE TI?\nTU ÉS AQUELE QUE ME AMOU PRIMEIRO!\nMAS HOJE FRACO ESTOU, SINTO SAUDADES DE TI, \nSENHOR, E VIM CHORAR DIANTE AOS TEUS PÉS, \nEM ORAÇÃO.\n\nRENOVA EM MIM VALORES TEUS, \nORDENA OS PENSAMENTOS MEUS E DÁ-ME, \nÓ PAI, SAÚDE ESPIRITUAL;\nPRA COM PRIMEIRO AMOR TE AMAR, \nO AMOR QUE UM DIA CONHECI \nQUANDO TOCASTE EM MIM <bis>\nPELA PRIMEIRA VEZ.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (455, 'QUANTO MAIS EU TE CONHEÇO (CAMINHO FELIZ)', 'QUANTO MAIS EU TE CONHEÇO (CAMINHO FELIZ)', 'QUANTO MAIS EU TE CONHEÇO,\nMAIS EU QUERO TE SERVIR;\nQUANDO FALAS, OBEDEÇO,\nA BÊNÇÃO ESTÁ EM TE OUVIR.\nTU ÉS FOGO QUE CONSOME,\nBRISA SUAVE DE AMOR, TU ÉS \nDEUS QUE MUDA O HOMEM,\nÉS O MEU AJUDADOR!\n\nCORO\nQUE MARAVILHA, SENHOR, É ESTAR\nNESTE CAMINHO QUE LEVA AO CÉU!\nCAMINHO FELIZ, INDO PRA TE ENCONTRAR \nE VER O TEU ROSTO SERÁ COMO UM SONHO,\nPELA FÉ EU JÁ SEI, VAI SE REALIZAR.\n\nO QUE GUARDA A TUA LEI\nNÃO SE ARREPENDERÁ;\nSE A GLÓRIA DE DEUS EU BUSCO,\nELA EU IREI ALCANÇAR;\nSE ESPINHOS NO CAMINHO\nEU TIVER DE ENFRENTAR,\nEU NÃO LIGO, MAS PROSSIGO,\nPARA CRISTO VOU OLHAR!\n\nCORO (2X)\nQUE MARAVILHA, SENHOR, É ESTAR\nNESTE CAMINHO QUE LEVA AO CÉU!\nCAMINHO FELIZ, INDO PRA TE ENCONTRAR \nE VER O TEU ROSTO SERÁ COMO UM SONHO,\nPELA FÉ EU JÁ SEI, VAI SE REALIZAR.\n\nFINAL: VAI SE REALIZAR.', 'QUANTO MAIS EU TE CONHEÇO,<bis>\nMAIS EU QUERO TE SERVIR;<bis>\nQUANDO FALAS, OBEDEÇO,<bis>\nA BÊNÇÃO ESTÁ EM TE OUVIR.<bis>\nTU ÉS FOGO QUE CONSOME,<bis>\nBRISA SUAVE DE AMOR, TU ÉS <bis>\nDEUS QUE MUDA O HOMEM,<bis>\nÉS O MEU AJUDADOR!<bis>\n\n<coro>\nQUE MARAVILHA, SENHOR, É ESTAR\nNESTE CAMINHO QUE LEVA AO CÉU!\nCAMINHO FELIZ, INDO PRA TE ENCONTRAR \nE VER O TEU ROSTO SERÁ COMO UM SONHO,\nPELA FÉ EU JÁ SEI, VAI SE REALIZAR.\n\nO QUE GUARDA A TUA LEI\nNÃO SE ARREPENDERÁ;\nSE A GLÓRIA DE DEUS EU BUSCO,\nELA EU IREI ALCANÇAR;\nSE ESPINHOS NO CAMINHO\nEU TIVER DE ENFRENTAR,\nEU NÃO LIGO, MAS PROSSIGO,\nPARA CRISTO VOU OLHAR!\n\n<coro tipo=''2X''>\nQUE MARAVILHA, SENHOR, É ESTAR\nNESTE CAMINHO QUE LEVA AO CÉU!\nCAMINHO FELIZ, INDO PRA TE ENCONTRAR \nE VER O TEU ROSTO SERÁ COMO UM SONHO,\nPELA FÉ EU JÁ SEI, VAI SE REALIZAR.\n<final>VAI SE REALIZAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (456, 'CHUVAS DE BÊNÇÃOS TEREMOS', 'CHUVAS DE BÊNÇÃOS TEREMOS', 'CHUVAS DE BÊNÇÃOS TEREMOS;\nÉ A PROMESSA DE DEUS.\nTEMPOS BENDITOS TRAZENDO,\nCHUVAS DE BÊNÇÃOS DOS CÉUS.\n\nCORO\nCHUVAS DE BÊNÇÃOS,\nCHUVAS DE BÊNÇÃOS DOS CÉUS;\nGOTAS BENDITAS JÁ TEMOS,\nCHUVAS ROGAMOS A DEUS.\n\nCHUVAS DE BÊNÇÃOS TEREMOS,\nDE VIDA PAZ E PERDÃO.\nOS PECADORES INDIGNOS\nGRAÇA DOS CÉUS OBTERÃO.\n\nSERVAS\n\nCORO\nCHUVAS DE BÊNÇÃOS,\nCHUVAS DE BÊNÇÃOS DOS CÉUS;\nGOTAS BENDITAS JÁ TEMOS,\nCHUVAS ROGAMOS A DEUS.\n\nCHUVAS DE BÊNÇÃOS TEREMOS,\nMANDA-NOS JÁ, Ó SENHOR!\nDÁ-NOS O GOZO DOS FRUTOS\nDOS TEUS ENSINOS DE AMOR.\n\n\nVARÕES\n\nCORO\nCHUVAS DE BÊNÇÃOS,\nCHUVAS DE BÊNÇÃOS DOS CÉUS;\nGOTAS BENDITAS JÁ TEMOS,\nCHUVAS ROGAMOS A DEUS.\n\nFINAL: AMÉM!', 'CHUVAS DE BÊNÇÃOS TEREMOS;\nÉ A PROMESSA DE DEUS.\nTEMPOS BENDITOS TRAZENDO,\nCHUVAS DE BÊNÇÃOS DOS CÉUS.\n\n<coro>\nCHUVAS DE BÊNÇÃOS,\nCHUVAS DE BÊNÇÃOS DOS CÉUS;\nGOTAS BENDITAS JÁ TEMOS,\nCHUVAS ROGAMOS A DEUS.\n\nCHUVAS DE BÊNÇÃOS TEREMOS,\nDE VIDA PAZ E PERDÃO.\nOS PECADORES INDIGNOS\nGRAÇA DOS CÉUS OBTERÃO.\n\n<m>\n\n<coro>\nCHUVAS DE BÊNÇÃOS,\nCHUVAS DE BÊNÇÃOS DOS CÉUS;\nGOTAS BENDITAS JÁ TEMOS,\nCHUVAS ROGAMOS A DEUS.\n\nCHUVAS DE BÊNÇÃOS TEREMOS,\nMANDA-NOS JÁ, Ó SENHOR!\nDÁ-NOS O GOZO DOS FRUTOS\nDOS TEUS ENSINOS DE AMOR.\n\n\n<h>\n\n\n<coro>\nCHUVAS DE BÊNÇÃOS,\nCHUVAS DE BÊNÇÃOS DOS CÉUS;\nGOTAS BENDITAS JÁ TEMOS,\nCHUVAS ROGAMOS A DEUS.\n<final>AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (457, 'INSTRUMENTO EM TUAS MÃOS', 'INSTRUMENTO EM TUAS MÃOS', 'INSTRUMENTO EM TUAS MÃOS\nQUERO SER, PARA TEU LOUVOR,\nUM VASO DE HONRA E BÊNÇÃOS\nPARA TU USARES, SENHOR. BREVE OU LONGA, \nA MINHA VIDASÓ TERÁ SENTIDO ASSIM, \nPOR ISSO PEÇO: FAZE DE MIM \nINSTRUMENTO EM TUAS MÃOS.\n\nCORO\nUM VASO PARA TI,FRÁGIL BARRO EM TUAS MÃOS,\nPARA TU MOLDARES E REVESTIRES \nDO OURO MAIS PRECIOSO. UM INSTRUMENTO TEU, SEM VALOR, MAS TEU SENHOR, \nSEPARADO PARA TI, \nPRA TE SERVIR CONFORME \nTE APROUVER EM TEU LOUVOR.\n\nCOM A ÁGUA DA PALAVRA\nMINHA MENTE VEM LIMPAR\nE PURIFICA A MINHA VIDA\nCOM O SANGUE DE JESUS.\nCOM O ÓLEO DO ESPÍRITO,\nME REVESTE DE PODER, PRA SER UM VASO \nDE HONRA E GLÓRIA EM TUAS MÃOS, \nÓ MEU JESUS.\n\nCORO\nUM VASO PARA TI,FRÁGIL BARRO EM TUAS MÃOS,\nPARA TU MOLDARES E REVESTIRES \nDO OURO MAIS PRECIOSO. UM INSTRUMENTO TEU, SEM VALOR, MAS TEU SENHOR, \nSEPARADO PARA TI, \nPRA TE SERVIR CONFORME \nTE APROUVER EM TEU LOUVOR.\n\nFINAL: TEU LOUVOR', 'INSTRUMENTO EM TUAS MÃOS\nQUERO SER, PARA TEU LOUVOR,\nUM VASO DE HONRA E BÊNÇÃOS\nPARA TU USARES, SENHOR. BREVE OU LONGA, \nA MINHA VIDASÓ TERÁ SENTIDO ASSIM, \nPOR ISSO PEÇO: FAZE DE MIM \nINSTRUMENTO EM TUAS MÃOS.\n\n<coro>\nUM VASO PARA TI,FRÁGIL BARRO EM TUAS MÃOS,\nPARA TU MOLDARES E REVESTIRES \nDO OURO MAIS PRECIOSO. UM INSTRUMENTO TEU, SEM VALOR, MAS TEU SENHOR, \nSEPARADO PARA TI, \nPRA TE SERVIR CONFORME \nTE APROUVER EM TEU LOUVOR.\n\nCOM A ÁGUA DA PALAVRA\nMINHA MENTE VEM LIMPAR\nE PURIFICA A MINHA VIDA\nCOM O SANGUE DE JESUS.\nCOM O ÓLEO DO ESPÍRITO,\nME REVESTE DE PODER, PRA SER UM VASO \nDE HONRA E GLÓRIA EM TUAS MÃOS, \nÓ MEU JESUS.\n\n<coro>\nUM VASO PARA TI,FRÁGIL BARRO EM TUAS MÃOS,\nPARA TU MOLDARES E REVESTIRES \nDO OURO MAIS PRECIOSO. UM INSTRUMENTO TEU, SEM VALOR, MAS TEU SENHOR, \nSEPARADO PARA TI, \nPRA TE SERVIR CONFORME \nTE APROUVER EM TEU LOUVOR.\n<final>TEU LOUVOR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (458, 'Ó CRISTO! PÃO DA VIDA', 'Ó CRISTO! PÃO DA VIDA', 'Ó CRISTO! PÃO DA VIDA, \nDESCIDO LÁ DO CÉU.\nO PÃO DE NOSSAS ALMAS,\nQUE O PAI DE AMOR NOS DEU!\nEM TI NOS ALEGRAMOS, \nPROVANDO MESMO AQUI\nDO ALENTO E DA DOÇURA,\nQUE ACHAMOS SEMPRE EM TI.\n\nDA ETERNA E SANTA VIDA,\nDA QUAL TU ÉS O AUTOR,\nSUSTENTO E FORTALEZA \nÉS TU TAMBÉM, SENHOR.\nSEM TI NÃO NOS ASSISTEM\nNEM FORÇAS, NEM PODER;\nDE TI, NOSSO ALIMENTO, \nQUEREMOS NÓS VIVER.\n\nÓ CRISTO! PÃO DA VIDA! \nA TI LOUVAMOS NÓS,\nE AO PAI TAMBÉM ERGUEMOS \nA NOSSA ALEGRE VOZ.\nAGRADECEMOS SEMPRE \nO AMOR QUE AQUI NOS DEU,\nSUSTENTO VERDADEIRO \nNO SANTO PÃO DO CÉU.\nAMÉM.', 'Ó CRISTO! PÃO DA VIDA, \nDESCIDO LÁ DO CÉU.\nO PÃO DE NOSSAS ALMAS,\nQUE O PAI DE AMOR NOS DEU!\nEM TI NOS ALEGRAMOS, \nPROVANDO MESMO AQUI\nDO ALENTO E DA DOÇURA,\nQUE ACHAMOS SEMPRE EM TI.\n\nDA ETERNA E SANTA VIDA,\nDA QUAL TU ÉS O AUTOR,\nSUSTENTO E FORTALEZA \nÉS TU TAMBÉM, SENHOR.\nSEM TI NÃO NOS ASSISTEM\nNEM FORÇAS, NEM PODER;\nDE TI, NOSSO ALIMENTO, \nQUEREMOS NÓS VIVER.\n\nÓ CRISTO! PÃO DA VIDA! \nA TI LOUVAMOS NÓS,\nE AO PAI TAMBÉM ERGUEMOS \nA NOSSA ALEGRE VOZ.\nAGRADECEMOS SEMPRE \nO AMOR QUE AQUI NOS DEU,\nSUSTENTO VERDADEIRO \nNO SANTO PÃO DO CÉU.\nAMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (459, 'É TEMPO, É TEMPO', 'É TEMPO, É TEMPO', 'É TEMPO, É TEMPO, \nO MESTRE ESTÁ CHAMANDO JÁ!\nMARCHAR, MARCHAR, \nCONFIANDO EM SEU AMOR!\nPARTIR, PARTIR, A SALVAÇÃO \nA PROCLAMAR, COM A PALAVRA \nSANTA DO BOM SALVADOR.\n\nCORO\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\n''QUEREMOS LUZ'', É O GRITO DAS NAÇÕES PAGÃS, QUE VEM ATRAVESSANDO O IMENSO MAR.\nIR JÁ, SIM, JÁ, LEVANDO NOVAS DE AMOR, \nSEM ESQUECER TAMBÉM AQUI DE SEMEAR.\n\nCORO\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\nDESPERTA, IGREJA!\nO TEU PODER VEM EXERCER,\nA TODOS FAZE CRISTO CONHECER;\nA TUA MÃO ESTENDE COM PACIENTE AMOR; ESFORÇA-TE DA MORTE ETERNA A OS DETER.\n\nCORO\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\nIGREJA, ALERTA!\nO DIA PROMETIDO VEM,\nQUANDO ACLAMADO O SALVADOR SERÁ;\nPOR TODA A PARTE O BEM AMADO REDENTOR ETERNA GLÓRIA, HONRA E LOUVOR TERÁ.\n\nCORO\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\nCORO\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.', 'É TEMPO, É TEMPO, \nO MESTRE ESTÁ CHAMANDO JÁ!\nMARCHAR, MARCHAR, \nCONFIANDO EM SEU AMOR!\nPARTIR, PARTIR, A SALVAÇÃO \nA PROCLAMAR, COM A PALAVRA \nSANTA DO BOM SALVADOR.\n\n<coro>\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\n''QUEREMOS LUZ'', É O GRITO DAS NAÇÕES PAGÃS, QUE VEM ATRAVESSANDO O IMENSO MAR.\nIR JÁ, SIM, JÁ, LEVANDO NOVAS DE AMOR, \nSEM ESQUECER TAMBÉM AQUI DE SEMEAR.\n\n<coro>\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\nDESPERTA, IGREJA!\nO TEU PODER VEM EXERCER,\nA TODOS FAZE CRISTO CONHECER;\nA TUA MÃO ESTENDE COM PACIENTE AMOR; ESFORÇA-TE DA MORTE ETERNA A OS DETER.\n\n<coro>\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\nIGREJA, ALERTA!\nO DIA PROMETIDO VEM,\nQUANDO ACLAMADO O SALVADOR SERÁ;\nPOR TODA A PARTE O BEM AMADO REDENTOR ETERNA GLÓRIA, HONRA E LOUVOR TERÁ.\n\n<coro>\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.\n\nGLÓRIA! GLÓRIA! EIS QUE CANTA A MULTIDÃO! \nCONSAGRANDO TODO O VOSSO CORAÇÃO, \nPRA A JESUS OBEDECER, SEU QUERER EXECUTAR,\nENTOAI, LOUVORES ALTOS! AVANÇAR!\n\n<coro>\nMARCHAR, (MARCHAR, MARCHAR)\nSIM, AVANTE! (SIM, AVANTE!)\nMARCHAR, ERGUENDO O PENDÃO REAL!\n(MARCHAR, ERGUENDO O PENDÃO REAL!)\nAVANTE! (AVANTE, SIM)\nSIM, AVANTE, (SEMPRE, SIM)\nUNIDOS, FIRMES SEMPRE AO AVANÇAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (460, 'Ó JESUS! Ó VERA PÁSCOA', 'Ó JESUS! Ó VERA PÁSCOA', 'Ó JESUS! Ó VERA PÁSCOA!\nSUSPIRADA DOS ANTIGOS!\nÓ CORDEIRO ETERNO E MEIGO,\nDIGNA-TE ASSISTIR AQUI!\n\nBOM JESUS, Ó PÃO DIVINO!\nPELA FÉ TE RECEBEMOS;\nÉS NAS ALMAS O ALIMENTO\nQUE SUSTENTA O NOSSO AMOR.\n\nBOM JESUS, Ó VINHO PURO!\nDE PERENE GOZO A FONTE!\nQUE NOSSA ALMA VIVA SEMPRE\nPARA TI, DE TI, EM TI. AMÉM.', 'Ó JESUS! Ó VERA PÁSCOA!\nSUSPIRADA DOS ANTIGOS!\nÓ CORDEIRO ETERNO E MEIGO,\nDIGNA-TE ASSISTIR AQUI!\n\nBOM JESUS, Ó PÃO DIVINO!\nPELA FÉ TE RECEBEMOS;\nÉS NAS ALMAS O ALIMENTO\nQUE SUSTENTA O NOSSO AMOR.\n\nBOM JESUS, Ó VINHO PURO!\nDE PERENE GOZO A FONTE!\nQUE NOSSA ALMA VIVA SEMPRE\nPARA TI, DE TI, EM TI. AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (461, 'TU, Ó SENHOR, TU ÉS TÃO PURO (AVIVA A TUA OBRA)', 'TU, Ó SENHOR, TU ÉS TÃO PURO (AVIVA A TUA OBRA)', 'TU, Ó SENHOR, TU ÉS TÃO PURO DE OLHOS \nE NÃO PODES VER O MAL,\nNEM INJUSTIÇA PODES CONTEMPLAR.\nESCUTA, SENHOR, A NOSSA ORAÇÃO VEM OUVIR\nE AVIVA, SENHOR, A TUA OBRA!\n\nA TUA VOZ ESCUTAMOS COM TEMOR,\nPOIS SABEMOS QUE O TEU\nJUÍZO BREVE VEM A TODA TERRA.\nNA IRA, Ó DEUS, VEM TER MISERICÓRDIA \nDE NÓS E AVIVA, SENHOR, A TUA OBRA!\n\nSENHOR, NA TUA IRA, Ó DEUS,\nVEM TER MISERICÓRDIA DE NÓS\nE AVIVA, SENHOR, A TUA OBRA!\nE AVIVA, SENHOR, A TUA OBRA!', 'TU, Ó SENHOR, TU ÉS TÃO PURO DE OLHOS \nE NÃO PODES VER O MAL,\nNEM INJUSTIÇA PODES CONTEMPLAR.\nESCUTA, SENHOR, A NOSSA ORAÇÃO VEM OUVIR\nE AVIVA, SENHOR, A TUA OBRA!\n\nA TUA VOZ ESCUTAMOS COM TEMOR,\nPOIS SABEMOS QUE O TEU\nJUÍZO BREVE VEM A TODA TERRA.\nNA IRA, Ó DEUS, VEM TER MISERICÓRDIA \nDE NÓS E AVIVA, SENHOR, A TUA OBRA!\n\nSENHOR, NA TUA IRA, Ó DEUS,\nVEM TER MISERICÓRDIA DE NÓS\nE AVIVA, SENHOR, A TUA OBRA!\nE AVIVA, SENHOR, A TUA OBRA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (462, 'QUANTOS FIÉIS, SENHOR', 'QUANTOS FIÉIS, SENHOR', 'QUANTOS FIÉIS, SENHOR, \nMÁRTIRES E HERÓIS DA FÉ, \nDERAM SUA VIDA, POR TUA VINHA, \nTOMBARAM, MAS DE PÉ.\nOUVIU-SE NAS ARENAS SEU CANTO DE LOUVOR; \nMAIS QUE AS FOGUEIRAS,\nNELES ARDIA O AMOR DO SALVADOR.\n\nCORO\nGRAÇAS DOU POR TANTOS FIÉIS, SENHOR\nQUE FORAM MAIS FORTES DO QUE A MORTE \nE NOS LEGARAM DA FÉ A HERANÇA,\nFAZ DE NÓS VALENTES EM TUAS MÃOS \nE AVIVA TUA OBRA, Ó DEUS, \nREVELA O TEU PODER NESTA GERAÇÃO.\n\nRAMOS DE MIRRA FOSTE PRA TEUS FIÉIS, JESUS; \nFAMÍLIA, AMIGOS, BENS, MESMO A VIDA, \nTROCARAM PELA CRUZ;\nNUVENS DE TESTEMUNHAS QUE O CÉU \nVAI RECEBER COM PALMAS DE OURO, \nCOROA E GLÓRIA A TODO O QUE VENCER.\n\nCORO\nGRAÇAS DOU POR TANTOS FIÉIS, SENHOR\nQUE FORAM MAIS FORTES DO QUE A MORTE \nE NOS LEGARAM DA FÉ A HERANÇA,\nFAZ DE NÓS VALENTES EM TUAS MÃOS \nE AVIVA TUA OBRA, Ó DEUS, \nREVELA O TEU PODER NESTA GERAÇÃO.', 'QUANTOS FIÉIS, SENHOR, \nMÁRTIRES E HERÓIS DA FÉ, \nDERAM SUA VIDA, POR TUA VINHA, \nTOMBARAM, MAS DE PÉ.\nOUVIU-SE NAS ARENAS SEU CANTO DE LOUVOR; \nMAIS QUE AS FOGUEIRAS,\nNELES ARDIA O AMOR DO SALVADOR.\n\n<coro>\nGRAÇAS DOU POR TANTOS FIÉIS, SENHOR\nQUE FORAM MAIS FORTES DO QUE A MORTE \nE NOS LEGARAM DA FÉ A HERANÇA,\nFAZ DE NÓS VALENTES EM TUAS MÃOS \nE AVIVA TUA OBRA, Ó DEUS, \nREVELA O TEU PODER NESTA GERAÇÃO.\n\nRAMOS DE MIRRA FOSTE PRA TEUS FIÉIS, JESUS; \nFAMÍLIA, AMIGOS, BENS, MESMO A VIDA, \nTROCARAM PELA CRUZ;\nNUVENS DE TESTEMUNHAS QUE O CÉU \nVAI RECEBER COM PALMAS DE OURO, \nCOROA E GLÓRIA A TODO O QUE VENCER.\n\n<coro>\nGRAÇAS DOU POR TANTOS FIÉIS, SENHOR\nQUE FORAM MAIS FORTES DO QUE A MORTE \nE NOS LEGARAM DA FÉ A HERANÇA,\nFAZ DE NÓS VALENTES EM TUAS MÃOS \nE AVIVA TUA OBRA, Ó DEUS, \nREVELA O TEU PODER NESTA GERAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (463, 'VEM, SENHOR, VISITA TUA VINHA', 'VEM, SENHOR, VISITA TUA VINHA', 'VEM, SENHOR, VISITA TUA VINHA,\nQUE PLANTASTE EM NOSSAS VIDAS\nCOM TUA DESTRA.\nVEM, SENHOR, VISITA TUA VINHA,\nQUE COMPRASTE COM TEU \nPRECIOSO SANGUE.\n\nCORO\nVEM, VISITA-ME; Ó VEM, PURIFICA-ME,\nSONDA O MEU CORAÇÃO\nE DÁ-ME O TEU SANTO PERDÃO\nE FAZE-ME REPOUSAR EM TI, SENHOR.\n\nQUERO SER, SENHOR, \nTEU SERVO AMADO POIS CONFIO \nEM TEU PODER Ó MEU JESUS.\nPODER QUE PARA MIM É INFINITO E \nÉ DADO A TODO AQUELE QUE EM TI CRER.\n\nCORO\nVEM, VISITA-ME; Ó VEM, PURIFICA-ME,\nSONDA O MEU CORAÇÃO\nE DÁ-ME O TEU SANTO PERDÃO\nE FAZE-ME REPOUSAR EM TI, SENHOR.\n\nFINAL:\nE FAZE-ME REPOUSAR EM TI, SENHOR.', 'VEM, SENHOR, VISITA TUA VINHA,\nQUE PLANTASTE EM NOSSAS VIDAS\nCOM TUA DESTRA.\nVEM, SENHOR, VISITA TUA VINHA,\nQUE COMPRASTE COM TEU \nPRECIOSO SANGUE.\n\n<coro>\nVEM, VISITA-ME; Ó VEM, PURIFICA-ME,\nSONDA O MEU CORAÇÃO\nE DÁ-ME O TEU SANTO PERDÃO\nE FAZE-ME REPOUSAR EM TI, SENHOR.\n\nQUERO SER, SENHOR, \nTEU SERVO AMADO POIS CONFIO \nEM TEU PODER Ó MEU JESUS.\nPODER QUE PARA MIM É INFINITO E \nÉ DADO A TODO AQUELE QUE EM TI CRER.\n\n<coro>\nVEM, VISITA-ME; Ó VEM, PURIFICA-ME,\nSONDA O MEU CORAÇÃO\nE DÁ-ME O TEU SANTO PERDÃO\nE FAZE-ME REPOUSAR EM TI, SENHOR.\n<final>E FAZE-ME REPOUSAR EM TI, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (464, 'TU QUE SOBRE A AMARGA CRUZ', 'TU QUE SOBRE A AMARGA CRUZ', 'TU, QUE SOBRE A AMARGA CRUZ\nREVELASTE TEU AMOR;\nTU, QUE VIVES, Ó JESUS,\nVIVIFICA-NOS, SENHOR!\n\nCORO\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!\n\nEIS O MUNDO TENTADOR\nA QUERER NOS ATRAIR;\nSEM TEU FOGO ABRASADOR\nNÃO PODEMOS RESISTIR.\n\nCORO\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!\n\nQUANTOS QUE CORRIAM BEM\nDE TI LONGE AGORA VÃO!\nOUTROS SEGUEM, MAS TAMBÉM\nSEM FERVOR VIVENDO ESTÃO.\n\nCORO\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!\n\nVEM AGORA CONSUMIR\nTUDO QUANTO, Ó SALVADOR,\nQUER, ALTIVO, RESISTIR\nAO TEU BRANDO E SANTO AMOR.\n\nCORO\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!', 'TU, QUE SOBRE A AMARGA CRUZ\nREVELASTE TEU AMOR;\nTU, QUE VIVES, Ó JESUS,\nVIVIFICA-NOS, SENHOR!\n\n<coro>\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!\n\nEIS O MUNDO TENTADOR\nA QUERER NOS ATRAIR;\nSEM TEU FOGO ABRASADOR\nNÃO PODEMOS RESISTIR.\n\n<coro>\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!\n\nQUANTOS QUE CORRIAM BEM\nDE TI LONGE AGORA VÃO!\nOUTROS SEGUEM, MAS TAMBÉM\nSEM FERVOR VIVENDO ESTÃO.\n\n<coro>\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!\n\nVEM AGORA CONSUMIR\nTUDO QUANTO, Ó SALVADOR,\nQUER, ALTIVO, RESISTIR\nAO TEU BRANDO E SANTO AMOR.\n\n<coro>\nVEM, Ó VEM, JESUS, SENHOR,\nNOSSAS ALMAS DESPERTAR!\nCOM TEU SANTO E PURO AMOR\nVEM, SENHOR, NOS INFLAMAR,\nOH! VEM, OH! VEM, \nNOSSAS ALMAS INFLAMAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (465, 'O ESTANDARTE DESTA IGREJA', 'O ESTANDARTE DESTA IGREJA', 'O ESTANDARTE DESTA IGREJA\nLEVANTEMOS SEM TEMOR!\nELA É A MUITO AMADA ESPOSA\nDO BENDITO SALVADOR;\nÉ JESUS O COMANDANTE\nVERDADEIRO QUE A CONDUZ,\nSOMOS, NÓS, OS SEUS SOLDADOS\nNESTA IGREJA DE JESUS.\n\nCORO\nRESOLUTOS, AVANÇAI, \nTRABALHANDO POR JESUS! \nO ESTANDARTE LEVANTAI,\nESPALHANDO A SUA LUZ.\n\nÓ IGREJA DEDIQUEMOS \nNOSSOS CORPOS AO SENHOR! \nNÃO DEVEMOS SER ESCRAVOS\nDO SAGAZ ENGANADOR.\nAS RIQUEZAS NOS SÃO DADAS \nPELA TERNA MÃO REAL, \nE O SENHOR DO CÉU OBSERVA\nSE FAZEMOS BEM OU MAL.\n\nCORO\nRESOLUTOS, AVANÇAI, \nTRABALHANDO POR JESUS! \nO ESTANDARTE LEVANTAI,\nESPALHANDO A SUA LUZ.\n\nGRAÇA E GLÓRIA A TI PERTENCEM, \nÓ ESPOSA DO SENHOR! SÊ, ENTÃO, \nUM INSTRUMENTO DE SALVAR O PECADOR;\nPOIS ATÉ OS FINS DO MUNDO CRISTO \nMESMO REINARÁ E O DOMÍNIO \nDO EVANGELHO TODA A TERRA ABRANGERÁ.\n\nCORO\nRESOLUTOS, AVANÇAI, \nTRABALHANDO POR JESUS! \nO ESTANDARTE LEVANTAI,\nESPALHANDO A SUA LUZ.', 'O ESTANDARTE DESTA IGREJA\nLEVANTEMOS SEM TEMOR!\nELA É A MUITO AMADA ESPOSA\nDO BENDITO SALVADOR;\nÉ JESUS O COMANDANTE\nVERDADEIRO QUE A CONDUZ,\nSOMOS, NÓS, OS SEUS SOLDADOS\nNESTA IGREJA DE JESUS.\n\n<coro>\nRESOLUTOS, AVANÇAI, \nTRABALHANDO POR JESUS! \nO ESTANDARTE LEVANTAI,\nESPALHANDO A SUA LUZ.\n\nÓ IGREJA DEDIQUEMOS \nNOSSOS CORPOS AO SENHOR! \nNÃO DEVEMOS SER ESCRAVOS\nDO SAGAZ ENGANADOR.\nAS RIQUEZAS NOS SÃO DADAS \nPELA TERNA MÃO REAL, \nE O SENHOR DO CÉU OBSERVA\nSE FAZEMOS BEM OU MAL.\n\n<coro>\nRESOLUTOS, AVANÇAI, \nTRABALHANDO POR JESUS! \nO ESTANDARTE LEVANTAI,\nESPALHANDO A SUA LUZ.\n\nGRAÇA E GLÓRIA A TI PERTENCEM, \nÓ ESPOSA DO SENHOR! SÊ, ENTÃO, \nUM INSTRUMENTO DE SALVAR O PECADOR;\nPOIS ATÉ OS FINS DO MUNDO CRISTO \nMESMO REINARÁ E O DOMÍNIO \nDO EVANGELHO TODA A TERRA ABRANGERÁ.\n\n<coro>\nRESOLUTOS, AVANÇAI, \nTRABALHANDO POR JESUS! \nO ESTANDARTE LEVANTAI,\nESPALHANDO A SUA LUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (466, 'EIS O ESTANDARTE', 'EIS O ESTANDARTE', 'EIS O ESTANDARTE TREMULANDO À LUZ,\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\nPARA A SANTA GUERRA ELE VOS CONDUZ;\nQUEM QUER ALISTAR-SE SOB O REI JESUS?\n\nCORO\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nGUERRA CONTRA AS TREVAS! \nGUERRA CONTRA O MAL!\nE CONTRA O PECADO! GUERRA DIVINAL!\nGUERRA CONTRA O MUNDO! \nNELA QUEM ENTRAR HÁ DE, \nSEM RESERVAS, TUDO ABANDONAR.\n\nCORO\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nTUDO! SOA DURO? RECEAIS A CRUZ?\nNÃO VOS ENVERGONHE A GRAÇA DE JESUS!\nÓ IRMÃOS, LEMBRAI-VOS, \nQUEM POR ELE SOFRER A COROA \nDA SUA MÃO HÁ DE RECEBER!\n\nCORO\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nNESTA SANTA GUERRA DESEJAIS LUTAR\nE A C''ROA DE GLÓRIA LÁ NO CÉU GANHAR?\nA QUEM QUER SEGUI-LO, \nEIS QUE DIZ JESUS: ''NEGUE-SE A SI \nMESMO E TOME A SUA CRUZ''.\n\nCORO\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nSALVADOR, EU HOJE VENHO ME RENDER,\nSÓ POR TI VENCIDO PODEREI VENCER;\nSÓ CONTIGO MORTO SEMPRE VIVEREI,\nTOMO AGORA MINHA CRUZ, \nMEU BONDOSO REI!\n\nCORO\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nSOB TEU ESTANDARTE MARCHAREI, JESUS,\nTUA DIVISA É MINHA: C''ROA SOBRE CRUZ!', 'EIS O ESTANDARTE TREMULANDO À LUZ,\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\nPARA A SANTA GUERRA ELE VOS CONDUZ;\nQUEM QUER ALISTAR-SE SOB O REI JESUS?\n\n<coro>\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nGUERRA CONTRA AS TREVAS! \nGUERRA CONTRA O MAL!\nE CONTRA O PECADO! GUERRA DIVINAL!\nGUERRA CONTRA O MUNDO! \nNELA QUEM ENTRAR HÁ DE, \nSEM RE<m>, TUDO ABANDONAR.\n\n<coro>\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nTUDO! SOA DURO? RECEAIS A CRUZ?\nNÃO VOS ENVERGONHE A GRAÇA DE JESUS!\nÓ IRMÃOS, LEMBRAI-VOS, \nQUEM POR ELE SOFRER A COROA \nDA SUA MÃO HÁ DE RECEBER!\n\n<coro>\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nNESTA SANTA GUERRA DESEJAIS LUTAR\nE A C''ROA DE GLÓRIA LÁ NO CÉU GANHAR?\nA QUEM QUER SEGUI-LO, \nEIS QUE DIZ JESUS: ''NEGUE-SE A SI \nMESMO E TOME A SUA CRUZ''.\n\n<coro>\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nSALVADOR, EU HOJE VENHO ME RENDER,\nSÓ POR TI VENCIDO PODEREI VENCER;\nSÓ CONTIGO MORTO SEMPRE VIVEREI,\nTOMO AGORA MINHA CRUZ, \nMEU BONDOSO REI!\n\n<coro>\nEIS O ESTANDARTE TREMULANDO À LUZ;\nEIS A SUA DIVISA: C''ROA SOBRE CRUZ!\n\nSOB TEU ESTANDARTE MARCHAREI, JESUS,\nTUA DIVISA É MINHA: C''ROA SOBRE CRUZ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (467, 'OS GUERREIROS SE PREPARAM', 'OS GUERREIROS SE PREPARAM', 'OS GUERREIROS SE PREPARAM\nPARA A GRANDE LUTA,\nÉ JESUS O CAPITÃO QUE AVANTE OS LEVARÁ;\nA MILÍCIA DOS REMIDOS MARCHA IMPOLUTA\nCERTA QUE A VITÓRIA ALCANÇARÁ.\n\nCORO\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.\n\nEIS OS BATALHÕES DE CRISTO\nPROSSEGUINDO AVANTE!\nNÃO OS VÊS COM QUE VALOR\nCOMBATEM CONTRA O MAL?\nPODES TU FICAR DORMINDO, \nMESMO VACILANTE,\nQUANDO ATACAM OUTROS A BELIAL?\n\nCORO\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.\n\nDÁ-TE PRESSA, NÃO VACILES,\nHOJE DEUS TE CHAMA\nPARA VIRES PELEJAR AO LADO DO SENHOR;\nENTRA NA BATALHA ONDE MAIS O FOGO \nINFLAMA E PELEJA CONTRA O VIL TENTADOR.\n\nCORO\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.\n\nA PELEJA É TREMENDA, TORNA-SE RENHIDA,\nMAS SÃO POUCOS OS SOLDADOS PARA BATALHAR;\nÓ VEM LIBERTAR AS POBRES ALMAS OPRIMIDAS\nDE QUEM, FURIOSO, AS QUER TRAGAR.\n\nCORO\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.', 'OS GUERREIROS SE PREPARAM\nPARA A GRANDE LUTA,\nÉ JESUS O CAPITÃO QUE AVANTE OS LEVARÁ;\nA MILÍCIA DOS REMIDOS MARCHA IMPOLUTA\nCERTA QUE A VITÓRIA ALCANÇARÁ.\n\n<coro>\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.\n\nEIS OS BATALHÕES DE CRISTO\nPROSSEGUINDO AVANTE!\nNÃO OS VÊS COM QUE VALOR\nCOMBATEM CONTRA O MAL?\nPODES TU FICAR DORMINDO, \nMESMO VACILANTE,\nQUANDO ATACAM OUTROS A BELIAL?\n\n<coro>\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.\n\nDÁ-TE PRESSA, NÃO VACILES,\nHOJE DEUS TE CHAMA\nPARA VIRES PELEJAR AO LADO DO SENHOR;\nENTRA NA BATALHA ONDE MAIS O FOGO \nINFLAMA E PELEJA CONTRA O VIL TENTADOR.\n\n<coro>\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.\n\nA PELEJA É TREMENDA, TORNA-SE RENHIDA,\nMAS SÃO POUCOS OS SOLDADOS PARA BATALHAR;\nÓ VEM LIBERTAR AS POBRES ALMAS OPRIMIDAS\nDE QUEM, FURIOSO, AS QUER TRAGAR.\n\n<coro>\nEU QUERO ESTAR COM CRISTO\nONDE A LUTA SE TRAVAR,\nNO LANCE IMPREVISTO\nNA FRENTE ME ENCONTRAR;\nATÉ QUE O POSSA VER NA GLÓRIA,\nME ALEGRANDO DA VITÓRIA\nONDE DEUS VAI ME COROAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (468, 'HÁ TANTA TERRA', 'HÁ TANTA TERRA', 'HÁ TANTA TERRA PRA POSSUIR,\nMAS NA BATALHA NÃO ESTAMOS SÓS;\nMUITAS PROMESSAS SE VÃO CUMPRIR\nSE O SENHOR SE AGRADAR DE NÓS.\n\nCORO (2X)\nASSIM NÓS VAMOS COM FÉ \nNO TEU PODER, SE FORES CONOSCO, \nSENHOR, IREMOS VENCER!\n\nINSTRUMENTOS\n\nCERCA A CIDADE COM ORAÇÃO,\nLEVANTA, IGREJA, A TUA VOZ;\nDIANTE DE TI MUROS RUIRÃO\nSE O SENHOR SE AGRADAR DE NÓS.\n\nCORO (2X)\nASSIM NÓS VAMOS COM FÉ \nNO TEU PODER, SE FORES CONOSCO, \nSENHOR, IREMOS VENCER!', 'HÁ TANTA TERRA PRA POSSUIR,\nMAS NA BATALHA NÃO ESTAMOS SÓS;\nMUITAS PROMESSAS SE VÃO CUMPRIR\nSE O SENHOR SE AGRADAR DE NÓS.\n\n<coro tipo=''2X''>\nASSIM NÓS VAMOS COM FÉ \nNO TEU PODER, SE FORES CONOSCO, \nSENHOR, IREMOS VENCER!\n<instrumentos>\n\n\nCERCA A CIDADE COM ORAÇÃO,\nLEVANTA, IGREJA, A TUA VOZ;\nDIANTE DE TI MUROS RUIRÃO\nSE O SENHOR SE AGRADAR DE NÓS.\n\n<coro tipo=''2X''>\nASSIM NÓS VAMOS COM FÉ \nNO TEU PODER, SE FORES CONOSCO, \nSENHOR, IREMOS VENCER!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (469, 'CASTELO FORTE', 'CASTELO FORTE', 'CASTELO FORTE É O NOSSO DEUS,\nESPADA E BOM ESCUDO;\nCOM SEU PODER DEFENDE OS SEUS,\nSOCORRO TRAZ E PROTEÇÃO.\nSABEIS QUEM É JESUS?\nO QUE VENCEU NA CRUZ,\nSENHOR DOS ALTOS CÉUS\nE SENDO O PRÓPRIO DEUS,\nTRIUNFA NA BATALHA.\n\nA NOSSA FORÇA NADA FAZ,\nESTAMOS CONVENCIDOS;\nMAS NOSSO DEUS SOCORRO TRAZ\nE SOMOS PROTEGIDOS.\nSE TEMOS DE PERDER\nRIQUEZAS, BENS QUE HOUVER,\nEMBORA A VIDA VÁ,\nPOR NÓS JESUS ESTÁ\nE DAR-NOS-Á SEU REINO.\n\nSIM, QUE A PALAVRA FICARÁ\nSABEMOS COM CERTEZA;\nE NADA NOS ASSUSTARÁ\nCOM CRISTO POR DEFESA.\nSABEIS QUEM É JESUS?\nO QUE VENCEU NA CRUZ,\nSENHOR DOS ALTOS CÉUS\nE SENDO O PRÓPRIO DEUS,\nTRIUNFA NA BATALHA.', 'CASTELO FORTE É O NOSSO DEUS,\nESPADA E BOM ESCUDO;\nCOM SEU PODER DEFENDE OS SEUS,\nSOCORRO TRAZ E PROTEÇÃO.\nSABEIS QUEM É JESUS?\nO QUE VENCEU NA CRUZ,\nSENHOR DOS ALTOS CÉUS\nE SENDO O PRÓPRIO DEUS,\nTRIUNFA NA BATALHA.\n\nA NOSSA FORÇA NADA FAZ,\nESTAMOS CONVENCIDOS;\nMAS NOSSO DEUS SOCORRO TRAZ\nE SOMOS PROTEGIDOS.\nSE TEMOS DE PERDER\nRIQUEZAS, BENS QUE HOUVER,\nEMBORA A VIDA VÁ,\nPOR NÓS JESUS ESTÁ\nE DAR-NOS-Á SEU REINO.\n\nSIM, QUE A PALAVRA FICARÁ\nSABEMOS COM CERTEZA;\nE NADA NOS ASSUSTARÁ\nCOM CRISTO POR DEFESA.\nSABEIS QUEM É JESUS?\nO QUE VENCEU NA CRUZ,\nSENHOR DOS ALTOS CÉUS\nE SENDO O PRÓPRIO DEUS,\nTRIUNFA NA BATALHA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (470, 'NO GETSÊMANI', 'NO GETSÊMANI', 'NO GETSÊMANI JESUS OROU: \n''PASSA DE MIM ESTE CÁLICE'', \nMAS O ALTAR ESTAVA PRONTO PARA O RECEBER;\nO CUTELO, A LENHA E O FOGO \nAGUARDAVAM O CORDEIRO\nQUE DARIA A SUA VIDA PELO MUNDO.\n\nCORO\nAO LAGAR DESCEU O FRUTO \nDA VIDEIRA E CORREU DA COR \nDO SANGUE O SEU MOSTO\nPRA QUE EU PUDESSE ENCHER \nMEU CÁLICE DE SALVAÇÃO.\n\nINSTRUMENTOS\n\nHOJE AQUI NÓS CELEBRAMOS \nESTA PÁSCOA VERDADEIRA \nPOIS DO JUGO LIBERTADOS \nTEMOS PAZ COM DEUS;\nCOMO MEMBROS DE UM SÓ CORPO\nPARTILHAMOS DE UM MESMO PÃO\nE BEBEMOS DESTE CÁLICE \nDO SEU SANGUE.\n\nCORO\nAO LAGAR DESCEU O FRUTO \nDA VIDEIRA E CORREU DA COR \nDO SANGUE O SEU MOSTO\nPRA QUE EU PUDESSE ENCHER \nMEU CÁLICE DE SALVAÇÃO.', 'NO GETSÊMANI JESUS OROU: \n''PASSA DE MIM ESTE CÁLICE'', \nMAS O ALTAR ESTAVA PRONTO PARA O RECEBER;\nO CUTELO, A LENHA E O FOGO \nAGUARDAVAM O CORDEIRO\nQUE DARIA A SUA VIDA PELO MUNDO.\n\n<coro>\nAO LAGAR DESCEU O FRUTO \nDA VIDEIRA E CORREU DA COR \nDO SANGUE O SEU MOSTO\nPRA QUE EU PUDESSE ENCHER <bis>\nMEU CÁLICE DE SALVAÇÃO.<bis>\n<instrumentos>\n\n\nHOJE AQUI NÓS CELEBRAMOS \nESTA PÁSCOA VERDADEIRA \nPOIS DO JUGO LIBERTADOS \nTEMOS PAZ COM DEUS;\nCOMO MEMBROS DE UM SÓ CORPO\nPARTILHAMOS DE UM MESMO PÃO\nE BEBEMOS DESTE CÁLICE \nDO SEU SANGUE.\n\n<coro>\nAO LAGAR DESCEU O FRUTO \nDA VIDEIRA E CORREU DA COR \nDO SANGUE O SEU MOSTO\nPRA QUE EU PUDESSE ENCHER <bis>\nMEU CÁLICE DE SALVAÇÃO.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (471, 'VEM, ESPÍRITO DE DEUS', 'VEM, ESPÍRITO DE DEUS', 'VEM, ESPÍRITO DE DEUS,\nEU PRECISO DE TI. \n\nCORO\nDE JESUS SERÁ A GLÓRIA E DELE SERÁ \nO LOUVOR, VEM, ESPÍRITO DE DEUS, \nEU PRECISO DE TI.\n\nMESMO SENDO PEQUENINO \nEU PRECISO DE TI.', 'VEM, ESPÍRITO DE DEUS,<bis>\nEU PRECISO DE TI.<coro><bis>\nDE JESUS SERÁ A GLÓRIA E DELE SERÁ \nO LOUVOR, VEM, ESPÍRITO DE DEUS, \nEU PRECISO DE TI.\n\nMESMO SENDO PEQUENINO <bis>\nEU PRECISO DE TI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (472, 'VINDE, CANTAI E ENTOAI LOUVORES A JESUS', 'VINDE, CANTAI E ENTOAI LOUVORES A JESUS', 'VINDE, CANTAI E ENTOAI LOUVORES A JESUS,\nQUE PARA A NOSSA SALVAÇÃO\nMORREU NA AMARGA CRUZ;\nSEU SANGUE DERRAMOU, \nDE TUDO ME LAVOU, MAIS ALVO \nDO QUE A NEVE ME TORNOU.\n\nCORO\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nALEGRE CANTAREI LOUVORES AO MEU REI,\nA MEU SENHOR JESUS QUE ME SALVOU.\n\nVINDE CONOSCO VOS UNIR NA \nGUERRA CONTRA O MAL\nE COM O NOSSO SALVADOR EM MARCHA TRIUNFAL,\nA TODOS PROCLAMAR SUA GRAÇA E SEU PODER,\nSEU SANGUE DERRAMOU PRA NOS SALVAR.\n\nCORO\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nALEGRE CANTAREI LOUVORES AO MEU REI,\nA MEU SENHOR JESUS QUE ME SALVOU.\n\nO CAPITÃO DA SALVAÇÃO É CRISTO, O SALVADOR;\nO REI DOS REIS, O REDENTOR, JESUS, NOSSO SENHOR;\nELE TUDO VENCERÁ, VITÓRIA NOS DARÁ,\nÀ GLÓRIA, SALVOS, NOS CONDUZIRÁ.\n\nCORO\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nALEGRE CANTAREI LOUVORES AO MEU REI,\nA MEU SENHOR JESUS QUE ME SALVOU.', 'VINDE, CANTAI E ENTOAI LOUVORES A JESUS,\nQUE PARA A NOSSA SALVAÇÃO\nMORREU NA AMARGA CRUZ;\nSEU SANGUE DERRAMOU, \nDE TUDO ME LAVOU, MAIS ALVO \nDO QUE A NEVE ME TORNOU.\n\n<coro>\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nALEGRE CANTAREI LOUVORES AO MEU REI,\nA MEU SENHOR JESUS QUE ME SALVOU.\n\nVINDE CONOSCO VOS UNIR NA \nGUERRA CONTRA O MAL\nE COM O NOSSO SALVADOR EM MARCHA TRIUNFAL,\nA TODOS PROCLAMAR SUA GRAÇA E SEU PODER,\nSEU SANGUE DERRAMOU PRA NOS SALVAR.\n\n<coro>\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nALEGRE CANTAREI LOUVORES AO MEU REI,\nA MEU SENHOR JESUS QUE ME SALVOU.\n\nO CAPITÃO DA SALVAÇÃO É CRISTO, O SALVADOR;\nO REI DOS REIS, O REDENTOR, JESUS, NOSSO SENHOR;\nELE TUDO VENCERÁ, VITÓRIA NOS DARÁ,\nÀ GLÓRIA, SALVOS, NOS CONDUZIRÁ.\n\n<coro>\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nO SANGUE DE JESUS ME LAVOU, ME LAVOU,\nALEGRE CANTAREI LOUVORES AO MEU REI,\nA MEU SENHOR JESUS QUE ME SALVOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (473, 'MINHA PORÇÃO', 'MINHA PORÇÃO', 'MINHA PORÇÃO ÉS TU, SENHOR,\nE TODO MEU SER TE DAREI COM AMOR.\nFOI NO TEU FALAR QUE DESCOBRI,\nQUE ÉS TUDO, TUDO PRA MIM!\n\nCORO\nÉS MEU AUXÍLIO, MEU GRANDE AMOR,\nE O MEU TESOURO, ÉS TU MEU SENHOR.\nNA TUA OBRA VOU ME DEDICAR, \nE SEMPRE TE AMAR.\n\nQUERO OUVIR TUA VOZ EM MEU VIVER,\nPOIS QUANDO TU FALAS \nSINTO GOZO EM MEU SER.\nTUA DESTRA É A LUZ QUE ME CONDUZ,\nAOS TEUS BRAÇOS, MEU PAI E SENHOR.\n\nCORO (BIS)\nÉS MEU AUXÍLIO, MEU GRANDE AMOR,\nE O MEU TESOURO, ÉS TU MEU SENHOR.\nNA TUA OBRA VOU ME DEDICAR, \nE SEMPRE TE AMAR.\n\nFINAL: E SEMPRE TE AMAR.', 'MINHA PORÇÃO ÉS TU, SENHOR,\nE TODO MEU SER TE DAREI COM AMOR.\nFOI NO TEU FALAR QUE DESCOBRI,\nQUE ÉS TUDO, TUDO PRA MIM!\n\n<coro>\nÉS MEU AUXÍLIO, MEU GRANDE AMOR,\nE O MEU TESOURO, ÉS TU MEU SENHOR.\nNA TUA OBRA VOU ME DEDICAR, \nE SEMPRE TE AMAR.\n\nQUERO OUVIR TUA VOZ EM MEU VIVER,\nPOIS QUANDO TU FALAS \nSINTO GOZO EM MEU SER.\nTUA DESTRA É A LUZ QUE ME CONDUZ,\nAOS TEUS BRAÇOS, MEU PAI E SENHOR.\n\n<coro tipo=''BIS''>\nÉS MEU AUXÍLIO, MEU GRANDE AMOR,\nE O MEU TESOURO, ÉS TU MEU SENHOR.\nNA TUA OBRA VOU ME DEDICAR, \nE SEMPRE TE AMAR.\n<final>E SEMPRE TE AMAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (474, 'QUEM SOU EU, SENHOR?', 'QUEM SOU EU, SENHOR?', 'QUEM SOU EU, SENHOR?\nPRA TE LEMBRARES DE MIM,\nPRA ME TRAZERES ATÉ AQUI\nE ME DIZER COISAS TÃO LINDAS.\n\nTU SABES QUEM EU SOU,\nO MENOR DE MINHA CASA,\nE NO TEU AMOR, SENHOR, \nPROFETIZASTE A MIM\nUM CAMINHO NOVO A TRILHAR.\n\nCORO (2X)\nME TOMASTE, SENHOR, DA TUA MALHADA,\nDE TRÁS DAS TUAS OVELHAS ME TIRASTE Ó DEUS,\nPOR ONDE QUER QUE EU FOR, PARA O TEU LOUVOR,\nA TUA PRESENÇA COMIGO IRÁ.\n\nFINAL: \nSE MINHA VIDA ABENÇOARES,\nPARA SEMPRE ABENÇOADA SERÁ.', 'QUEM SOU EU, SENHOR?\nPRA TE LEMBRARES DE MIM,\nPRA ME TRAZERES ATÉ AQUI\nE ME DIZER COISAS TÃO LINDAS.\n\nTU SABES QUEM EU SOU,\nO MENOR DE MINHA CASA,\nE NO TEU AMOR, SENHOR, \nPROFETIZASTE A MIM\nUM CAMINHO NOVO A TRILHAR.\n\n<coro tipo=''2X''>\nME TOMASTE, SENHOR, DA TUA MALHADA,\nDE TRÁS DAS TUAS OVELHAS ME TIRASTE Ó DEUS,\nPOR ONDE QUER QUE EU FOR, PARA O TEU LOUVOR,\nA TUA PRESENÇA COMIGO IRÁ.\n<final>SE MINHA VIDA ABENÇOARES,\nPARA SEMPRE ABENÇOADA SERÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (475, 'AINDA UMA VEZ (AGEU)', 'AINDA UMA VEZ (AGEU)', '''AINDA UMA VEZ, DAQUI A POUCO,\nE FAREI TREMER OS CÉUS,\nE TODA A TERRA, TODO MAR E A TERRA SECA,\nFAREI TREMER NAÇÕES,\nE ENFIM VIRÁ O DESEJADO DAS NAÇÕES.''\n\nCORO\n''E EU ENCHEREI ASSIM ESTE LUGAR, (EU ENCHEREI)\nCOM MINHA GLÓRIA ENCHEREI ESTE LUGAR (ESTE LUGAR),''\nDIZ O SENHOR DOS EXÉRCITOS (DIZ O SENHOR),\nDIZ O SENHOR.\n\n''MINHA É A PRATA E MEU O OURO'',\nASSIM DIZ O SENHOR,\n''E A GLÓRIA DESTA CASA ENFIM EXCEDERÁ,\nA GLÓRIA DA PRIMEIRA,\nE NESTE LUGAR, DAREI A MINHA PAZ.''\n\nCORO\n''E EU ENCHEREI ASSIM ESTE LUGAR, (EU ENCHEREI)\nCOM MINHA GLÓRIA ENCHEREI ESTE LUGAR (ESTE LUGAR),''\nDIZ O SENHOR DOS EXÉRCITOS (DIZ O SENHOR),\nDIZ O SENHOR DOS EXÉRCITOS!\n\nFINAL:\n''SIM ESTE LUGAR (EU ENCHEREI)\nCOM MINHA GLÓRIA ENCHEREI ESTE LUGAR (ESTE LUGAR)''\nDIZ O SENHOR DOS EXÉRCITOS (DIZ O SENHOR),\nDIZ O SENHOR JESUS.', '''AINDA UMA VEZ, DAQUI A POUCO,\nE FAREI TREMER OS CÉUS,\nE TODA A TERRA, TODO MAR E A TERRA SECA,\nFAREI TREMER NAÇÕES,\nE ENFIM VIRÁ O DESEJADO DAS NAÇÕES.''\n\n<coro>\n''E EU ENCHEREI ASSIM ESTE LUGAR, (EU ENCHEREI)\nCOM MINHA GLÓRIA ENCHEREI ESTE LUGAR (ESTE LUGAR),''\nDIZ O SENHOR DOS EXÉRCITOS (DIZ O SENHOR),\nDIZ O SENHOR.\n\n''MINHA É A PRATA E MEU O OURO'',\nASSIM DIZ O SENHOR,\n''E A GLÓRIA DESTA CASA ENFIM EXCEDERÁ,\nA GLÓRIA DA PRIMEIRA,\nE NESTE LUGAR, DAREI A MINHA PAZ.''\n\n<coro>\n''E EU ENCHEREI ASSIM ESTE LUGAR, (EU ENCHEREI)\nCOM MINHA GLÓRIA ENCHEREI ESTE LUGAR (ESTE LUGAR),''\nDIZ O SENHOR DOS EXÉRCITOS (DIZ O SENHOR),\nDIZ O SENHOR DOS EXÉRCITOS!\n\n\n<final>''SIM ESTE LUGAR (EU ENCHEREI)\nCOM MINHA GLÓRIA ENCHEREI ESTE LUGAR (ESTE LUGAR)''\nDIZ O SENHOR DOS EXÉRCITOS (DIZ O SENHOR),\nDIZ O SENHOR JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (476, 'ESTA OBRA É DE DEUS', 'ESTA OBRA É DE DEUS', 'ESTA OBRA É DE DEUS, \nNINGUÉM A PODE IMPEDIR, \nFOI JESUS QUEM CONVOCOU \nESTÁ NA HORA DE AGIR.\n\nVAMOS TODOS! VAMOS TODOS!\nTRABALHAR PARA A GLÓRIA DE JESUS.\nALELUIA! ALELUIA!\nLOUVANDO AQUELE QUE POR NÓS\nMORREU NA CRUZ, GLÓRIA A JESUS!\nALELUIA! ALELUIA!\nGLORIFICADO SEJA O NOME DO SENHOR.\n\nVIVO CONTENTE, VIVO ALEGRE, \nPORQUE JESUS JÁ ME LIBERTOU.\nVIVO CONTENTE, VIVO ALEGRE, \nPORQUE JESUS JÁ ME LIBERTOU.', 'ESTA OBRA É DE DEUS, <bis>\nNINGUÉM A PODE IMPEDIR, <bis>\nFOI JESUS QUEM CONVOCOU <bis>\nESTÁ NA HORA DE AGIR.<bis>\n\nVAMOS TODOS! VAMOS TODOS!\nTRABALHAR PARA A GLÓRIA DE JESUS.\nALELUIA! ALELUIA!\nLOUVANDO AQUELE QUE POR NÓS\nMORREU NA CRUZ, GLÓRIA A JESUS!\nALELUIA! ALELUIA!\nGLORIFICADO SEJA O NOME DO SENHOR.\n\nVIVO CONTENTE, VIVO ALEGRE, \nPORQUE JESUS JÁ ME LIBERTOU.\nVIVO CONTENTE, VIVO ALEGRE, \nPORQUE JESUS JÁ ME LIBERTOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (477, 'SEMPRE VOU LEMBRAR', 'SEMPRE VOU LEMBRAR', 'SEMPRE VOU LEMBRAR DA CORAGEM E DO AMOR, \nDA FIRMEZA E VONTADE, DA FÉ E DEVOÇÃO. \nDA IGREJA DO TEMPO DE PAULO, DE PEDRO E JOÃO. \nENFRENTARAM A FÚRIA DE ROMA,\nMAS NUNCA NEGARAM SUA FÉ DE CRISTÃO \nÉ UM EXEMPLO PRA MIM, VERDADEIRA LIÇÃO.\n\nSEMPRE VOU LEMBRAR DA BRAVURA DOS SANTOS,\nEM PLENA ARENA ENFRENTANDO OS LEÕES. \nQUANTO MAIS A FOGUEIRA QUEIMAVA, \nMAIS SE OUVIA O LOUVOR DOS NOSSOS IRMÃOS.\nSOBRE O SANGUE TOMBAVAM NAS RUAS,\nCHEGAVAM NOS CÉUS COM A VITÓRIA NAS MÃOS. \nÉ UM EXEMPLO PRA MIM, VERDADEIRA LIÇÃO.\n\nCORO\nÓ MEU DEUS, REAVIVA A TUA IGREJA DE NOVO.\nFAZ A CHAMA ARDER NESTE POVO,\nCOMO FORAM OS PRIMEIROS CRISTÃOS.\nÓ MEU DEUS, REAVIVA TUA IGREJA DE NOVO. \nFAZ A CHAMA ARDER NESTE POVO, \nCOMEÇANDO EM MEU CORAÇÃO.\n\nINSTRUMENTOS\n\nSEMPRE VOU LEMBRAR DA BRAVURA DOS SANTOS,\nEM PLENA ARENA ENFRENTANDO OS LEÕES. \nQUANTO MAIS A FOGUEIRA QUEIMAVA, \nMAIS SE OUVIA O LOUVOR DOS NOSSOS IRMÃOS.\nSOBRE O SANGUE TOMBAVAM NAS RUAS,\nCHEGAVAM NOS CÉUS COM A VITÓRIA NAS MÃOS. \nÉ UM EXEMPLO PRA MIM, VERDADEIRA LIÇÃO.\n\nCORO\nÓ MEU DEUS, REAVIVA A TUA IGREJA DE NOVO.\nFAZ A CHAMA ARDER NESTE POVO,\nCOMO FORAM OS PRIMEIROS CRISTÃOS.\nÓ MEU DEUS, REAVIVA TUA IGREJA DE NOVO. \nFAZ A CHAMA ARDER NESTE POVO, \nCOMEÇANDO EM MEU CORAÇÃO.\n\nFINAL:\nÓ MEU DEUS, REAVIVA TUA IGREJA DE NOVO. \nFAZ A CHAMA ARDER NESTE POVO, \nCOMEÇANDO EM MEU CORAÇÃO.', 'SEMPRE VOU LEMBRAR DA CORAGEM E DO AMOR, \nDA FIRMEZA E VONTADE, DA FÉ E DEVOÇÃO. \nDA IGREJA DO TEMPO DE PAULO, DE PEDRO E JOÃO. \nENFRENTARAM A FÚRIA DE ROMA,\nMAS NUNCA NEGARAM SUA FÉ DE CRISTÃO \nÉ UM EXEMPLO PRA MIM, VERDADEIRA LIÇÃO.\n\nSEMPRE VOU LEMBRAR DA BRAVURA DOS SANTOS,\nEM PLENA ARENA ENFRENTANDO OS LEÕES. \nQUANTO MAIS A FOGUEIRA QUEIMAVA, \nMAIS SE OUVIA O LOUVOR DOS NOSSOS IRMÃOS.\nSOBRE O SANGUE TOMBAVAM NAS RUAS,\nCHEGAVAM NOS CÉUS COM A VITÓRIA NAS MÃOS. \nÉ UM EXEMPLO PRA MIM, VERDADEIRA LIÇÃO.\n\n<coro>\nÓ MEU DEUS, REAVIVA A TUA IGREJA DE NOVO.\nFAZ A CHAMA ARDER NESTE POVO,\nCOMO FORAM OS PRIMEIROS CRISTÃOS.\nÓ MEU DEUS, REAVIVA TUA IGREJA DE NOVO. \nFAZ A CHAMA ARDER NESTE POVO, \nCOMEÇANDO EM MEU CORAÇÃO.\n<instrumentos>\n\n\nSEMPRE VOU LEMBRAR DA BRAVURA DOS SANTOS,\nEM PLENA ARENA ENFRENTANDO OS LEÕES. \nQUANTO MAIS A FOGUEIRA QUEIMAVA, \nMAIS SE OUVIA O LOUVOR DOS NOSSOS IRMÃOS.\nSOBRE O SANGUE TOMBAVAM NAS RUAS,\nCHEGAVAM NOS CÉUS COM A VITÓRIA NAS MÃOS. \nÉ UM EXEMPLO PRA MIM, VERDADEIRA LIÇÃO.\n\n<coro>\nÓ MEU DEUS, REAVIVA A TUA IGREJA DE NOVO.\nFAZ A CHAMA ARDER NESTE POVO,\nCOMO FORAM OS PRIMEIROS CRISTÃOS.\nÓ MEU DEUS, REAVIVA TUA IGREJA DE NOVO. \nFAZ A CHAMA ARDER NESTE POVO, \nCOMEÇANDO EM MEU CORAÇÃO.\n\n\n<final>Ó MEU DEUS, REAVIVA TUA IGREJA DE NOVO. \nFAZ A CHAMA ARDER NESTE POVO, \nCOMEÇANDO EM MEU CORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (478, 'VI UM NOVO CÉU', 'VI UM NOVO CÉU', 'VI UM NOVO CÉU, UMA NOVA TERRA, \nEU VI A NOVA JERUSALÉM.\n\nVI UM TRONO BRANCO E SOBRE \nELE UM SER,\nCUJO ROSTO EU NÃO PUDE VER\nMAS EU SEI QUE ERA O MEU JESUS.\n\nVI UM CORO CELESTIAL, \nVI OS ANJOS DE DEUS\nQUE CANTAVAM EM UMA SÓ VOZ:\nVIVA O REI JESUS!\n\nINSTRUMENTOS\n\nEM BREVE ESTAREMOS NESSE NOVO LAR, \nCANTANDO: VIVA O REI JESUS!\nEM RUAS DE OURO NÓS VAMOS ANDAR,\nDA ÁRVORE DA VIDA DESFRUTAR.\n\nE COM JESUS PARA SEMPRE MORAR, \n(VOU MORAR) (VARÕES)\nE COM JESUS PARA SEMPRE MORAR, \n(VOU LOUVAR) (VARÕES)\nE COM JESUS PARA SEMPRE MORAR.', 'VI UM NOVO CÉU, UMA NOVA TERRA, <bis>\nEU VI A NOVA JERUSALÉM.<bis>\n\nVI UM TRONO BRANCO E SOBRE \nELE UM SER,\nCUJO ROSTO EU NÃO PUDE VER\nMAS EU SEI QUE ERA O MEU JESUS.\n\nVI UM CORO CELESTIAL, \nVI OS ANJOS DE DEUS\nQUE CANTAVAM EM UMA SÓ VOZ:\nVIVA O REI JESUS!\n<instrumentos>\nEM BREVE ESTAREMOS NESSE NOVO LAR, <bis>\nCANTANDO: VIVA O REI JESUS!<bis>\nEM RUAS DE OURO NÓS VAMOS ANDAR,\nDA ÁRVORE DA VIDA DESFRUTAR.\n\nE COM JESUS PARA SEMPRE MORAR, \n(VOU MORAR) <h>\nE COM JESUS PARA SEMPRE MORAR, \n(VOU LOUVAR) <h>\nE COM JESUS PARA SEMPRE MORAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (479, 'QUEM ME DERA', 'QUEM ME DERA', 'QUEM ME DERA FOSSEM AGORA\nESCRITAS AS MINHAS PALAVRAS,\nCOM PENA DE FERRO GRAVADAS,\nPRA SEMPRE ESCULPIDAS NA ROCHA.\n\nCORO\nEU SEI QUE VIVE MEU REDENTOR\nE POR FIM SOBRE A TERRA VIRÁ;\nO MEU CORPO SE LEVANTARÁ\nREVESTIDO DE GLÓRIA E LOUVOR. \n\nINSTRUMENTOS\n\nFACE A FACE VEREI MEU SENHOR,\nOS MEUS OLHOS O CONTEMPLARÃO;\nDE SAUDADE PULSA O CORAÇÃO,\nMINH''ALMA CLAMA: VEM, REDENTOR!\n\nCORO (2X)\nEU SEI QUE VIVE MEU REDENTOR\nE POR FIM SOBRE A TERRA VIRÁ;\nO MEU CORPO SE LEVANTARÁ\nREVESTIDO DE GLÓRIA E LOUVOR. \n\nREVESTIDO DE GLÓRIA E LOUVOR.\nREVESTIDO DE GLÓRIA E LOUVOR.', 'QUEM ME DERA FOSSEM AGORA\nESCRITAS AS MINHAS PALAVRAS,\nCOM PENA DE FERRO GRAVADAS,\nPRA SEMPRE ESCULPIDAS NA ROCHA.\n\n<coro>\nEU SEI QUE VIVE MEU REDENTOR\nE POR FIM SOBRE A TERRA VIRÁ;\nO MEU CORPO SE LEVANTARÁ\nREVESTIDO DE GLÓRIA E LOUVOR. \n<instrumentos>\n\n\nFACE A FACE VEREI MEU SENHOR,\nOS MEUS OLHOS O CONTEMPLARÃO;\nDE SAUDADE PULSA O CORAÇÃO,\nMINH''ALMA CLAMA: VEM, REDENTOR!\n\n<coro tipo=''2X''>\nEU SEI QUE VIVE MEU REDENTOR\nE POR FIM SOBRE A TERRA VIRÁ;\nO MEU CORPO SE LEVANTARÁ\nREVESTIDO DE GLÓRIA E LOUVOR. \n\nREVESTIDO DE GLÓRIA E LOUVOR.\nREVESTIDO DE GLÓRIA E LOUVOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (480, 'EU ESPERO, ANSIOSO, POR MEU DEUS', 'EU ESPERO, ANSIOSO, POR MEU DEUS', 'EU ESPERO, ANSIOSO, POR MEU DEUS\nEU ESPERO, ANSIOSO, POR MEU DEUS\nDE, COM ELE, ESTAR PARA SEMPRE LÁ NO CÉU,\nCOM MEU DEUS QUERO ESTAR PARA SEMPRE.\n\nMUITAS LUTAS EU TEREI DE ENFRENTAR,\nMUITAS LUTAS EU TEREI DE SUPORTAR,\nMAS SEI QUE O MEU SENHOR \nNUNCA MAIS VAI ME DEIXAR, \nCOM MEU DEUS QUERO ESTAR PARA SEMPRE.\n\nCOM MEU DEUS EU SOU MUITO FELIZ (2X)\nPOIS SEI QUE O MEU SENHOR \nNUNCA MAIS VAI ME DEIXAR, \nCOM MEU DEUS QUERO ESTAR PARA SEMPRE, \nPARA SEMPRE VOU ESTAR.', 'EU ESPERO, ANSIOSO, POR MEU DEUS\nEU ESPERO, ANSIOSO, POR MEU DEUS\nDE, COM ELE, ESTAR PARA SEMPRE LÁ NO CÉU,\nCOM MEU DEUS QUERO ESTAR PARA SEMPRE.\n\nMUITAS LUTAS EU TEREI DE ENFRENTAR,\nMUITAS LUTAS EU TEREI DE SUPORTAR,\nMAS SEI QUE O MEU SENHOR \nNUNCA MAIS VAI ME DEIXAR, \nCOM MEU DEUS QUERO ESTAR PARA SEMPRE.\n\nCOM MEU DEUS EU SOU MUITO FELIZ <bis tipo=''2''>\nPOIS SEI QUE O MEU SENHOR \nNUNCA MAIS VAI ME DEIXAR, \nCOM MEU DEUS QUERO ESTAR PARA SEMPRE, \nPARA SEMPRE VOU ESTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (481, 'ASSIM COMO A NOITE ESPERA PELO DIA', 'ASSIM COMO A NOITE ESPERA PELO DIA', 'ASSIM COMO A NOITE ESPERA PELO DIA,\nASSIM COMO A PRAIA ESPERA PELO MAR\nASSIM COMO AS NUVENS ESPERAM PELO VENTO, \nCOM MAIS ANSIEDADE EU ESTOU A TE ESPERAR.\n\nCORO\nTE ESPERO, CHORANDO, TE ESPERO, \nMESTRE QUERIDO, ESTOU ME ENCURVANDO \nANTE O PESO DA CRUZ;\nME AJUDA A CHEGAR AO MEU LAR PROMETIDO, \nSEM TI NÃO CONSIGO VIVER, MEU JESUS.\n\nBEM MAIS QUE AS FLORES ESPERAM PELO ORVALHO,\nBEM MAIS QUE O PERDIDO ESPERA SE ENCONTRAR,\nBEM MAIS QUE O FILHO ESPERA A MÃE QUERIDA, \nCOM MAIS ANSIEDADE EU ESTOU A TE ESPERAR.\n\nCORO\nTE ESPERO, CHORANDO, TE ESPERO, \nMESTRE QUERIDO, ESTOU ME ENCURVANDO \nANTE O PESO DA CRUZ;\nME AJUDA A CHEGAR AO MEU LAR PROMETIDO, \nSEM TI NÃO CONSIGO VIVER, MEU JESUS.\n\nFINAL: Ó, MEU JESUS.', 'ASSIM COMO A NOITE ESPERA PELO DIA,\nASSIM COMO A PRAIA ESPERA PELO MAR\nASSIM COMO AS NUVENS ESPERAM PELO VENTO, \nCOM MAIS ANSIEDADE EU ESTOU A TE ESPERAR.\n\n<coro>\nTE ESPERO, CHORANDO, TE ESPERO, \nMESTRE QUERIDO, ESTOU ME ENCURVANDO \nANTE O PESO DA CRUZ;\nME AJUDA A CHEGAR AO MEU LAR PROMETIDO, \nSEM TI NÃO CONSIGO VIVER, MEU JESUS.\n\nBEM MAIS QUE AS FLORES ESPERAM PELO ORVALHO,\nBEM MAIS QUE O PERDIDO ESPERA SE ENCONTRAR,\nBEM MAIS QUE O FILHO ESPERA A MÃE QUERIDA, \nCOM MAIS ANSIEDADE EU ESTOU A TE ESPERAR.\n\n<coro>\nTE ESPERO, CHORANDO, TE ESPERO, \nMESTRE QUERIDO, ESTOU ME ENCURVANDO \nANTE O PESO DA CRUZ;\nME AJUDA A CHEGAR AO MEU LAR PROMETIDO, \nSEM TI NÃO CONSIGO VIVER, MEU JESUS.\n<final>Ó, MEU JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (482, 'OS SINAIS DO FIM SE CUMPREM', 'OS SINAIS DO FIM SE CUMPREM', 'OS SINAIS DO FIM SE CUMPREM EM NOSSA GERAÇÃO,\nTODA A TERRA SE ANGUSTIA, GEME A CRIAÇÃO;\nTREVAS CAEM SOBRE O MUNDO, \nSÓ UM POVO TEM A LUZ,\nQUEM TEM SEDE VENHA E BEBA, ÁGUA VIVA É JESUS.\n\nCORO\nDEUS É POR NÓS, \nQUEM SERÁ CONTRA NÓS?\nQUEM PODERÁ SEPARAR-NOS \nDO AMOR QUE HÁ EM JESUS?\n\nNÓS TAMBÉM JUNTOS GEMEMOS ANSIANDO A PARTIDA, \nNÃO GEMEMOS PARA A MORTE MAS PELA ETERNA VIDA,\nPOIS JÁ A LUZ A VISTA ALCANÇA, NOVO DIA VAI RAIAR, \nCUMPRE-SE NOSSA ESPERANÇA, \nJESUS CRISTO VAI VOLTAR!\n\nCORO\nDEUS É POR NÓS, \nQUEM SERÁ CONTRA NÓS?\nQUEM PODERÁ SEPARAR-NOS\nDO AMOR QUE HÁ EM JESUS?', 'OS SINAIS DO FIM SE CUMPREM EM NOSSA GERAÇÃO,\nTODA A TERRA SE ANGUSTIA, GEME A CRIAÇÃO;\nTREVAS CAEM SOBRE O MUNDO, \nSÓ UM POVO TEM A LUZ,\nQUEM TEM SEDE VENHA E BEBA, ÁGUA VIVA É JESUS.\n\n<coro>\nDEUS É POR NÓS, \nQUEM SERÁ CONTRA NÓS?\nQUEM PODERÁ SEPARAR-NOS \nDO AMOR QUE HÁ EM JESUS?\n\nNÓS TAMBÉM JUNTOS GEMEMOS ANSIANDO A PARTIDA, \nNÃO GEMEMOS PARA A MORTE MAS PELA ETERNA VIDA,\nPOIS JÁ A LUZ A VISTA ALCANÇA, NOVO DIA VAI RAIAR, \nCUMPRE-SE NOSSA ESPERANÇA, \nJESUS CRISTO VAI VOLTAR!\n\n<coro>\nDEUS É POR NÓS, \nQUEM SERÁ CONTRA NÓS?\nQUEM PODERÁ SEPARAR-NOS\nDO AMOR QUE HÁ EM JESUS?', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (483, 'CHEGOU O TEMPO DE PENSAR', 'CHEGOU O TEMPO DE PENSAR', 'CHEGOU O TEMPO DE PENSAR\nNAS COISAS QUE SÃO LÁ DO CÉU,\nDEIXANDO ESTE MUNDO MAU,\nCOM TODOS OS PECADOS SEUS;\nPENSAI NAS COISAS LÁ DE CIMA,\nQUE SE APROXIMA O REINO DE DEUS.\n\nCORO\nÓ BUSCAI AS BÊNÇÃOS DO SENHOR,\nCONFIAI NO SEU IMENSO AMOR;\nOS SINAIS ESTÃO NOS DECLARANDO\nQUE VAI SE PASSANDO O QUE JESUS FALOU;\nVEM A CRISTO QUE ELE TE REVESTE \nCOM O DOM CELESTE DO CONSOLADOR.\n\nCOMO FOI NOS DIAS DE NOÉ,\nCOM O DILÚVIO TUDO SE ACABOU,\nTAMBÉM NOS DIAS DE GOMORRA\nO FOGO TUDO DEVOROU;\nPORÉM NÃO HOUVE AGONIA\nCOMO NESSE DIA, DIA DO SENHOR.\n\nCORO\nÓ BUSCAI AS BÊNÇÃOS DO SENHOR,\nCONFIAI NO SEU IMENSO AMOR;\nOS SINAIS ESTÃO NOS DECLARANDO\nQUE VAI SE PASSANDO O QUE JESUS FALOU;\nVEM A CRISTO QUE ELE TE REVESTE \nCOM O DOM CELESTE DO CONSOLADOR.', 'CHEGOU O TEMPO DE PENSAR\nNAS COISAS QUE SÃO LÁ DO CÉU,\nDEIXANDO ESTE MUNDO MAU,\nCOM TODOS OS PECADOS SEUS;\nPENSAI NAS COISAS LÁ DE CIMA,<bis>\nQUE SE APROXIMA O REINO DE DEUS.<bis>\n\n<coro>\nÓ BUSCAI AS BÊNÇÃOS DO SENHOR,\nCONFIAI NO SEU IMENSO AMOR;\nOS SINAIS ESTÃO NOS DECLARANDO\nQUE VAI SE PASSANDO O QUE JESUS FALOU;\nVEM A CRISTO QUE ELE TE REVESTE <bis>\nCOM O DOM CELESTE DO CONSOLADOR.<bis>\n\nCOMO FOI NOS DIAS DE NOÉ,\nCOM O DILÚVIO TUDO SE ACABOU,\nTAMBÉM NOS DIAS DE GOMORRA\nO FOGO TUDO DEVOROU;\nPORÉM NÃO HOUVE AGONIA<bis>\nCOMO NESSE DIA, DIA DO SENHOR.<bis>\n\n<coro>\nÓ BUSCAI AS BÊNÇÃOS DO SENHOR,\nCONFIAI NO SEU IMENSO AMOR;\nOS SINAIS ESTÃO NOS DECLARANDO\nQUE VAI SE PASSANDO O QUE JESUS FALOU;\nVEM A CRISTO QUE ELE TE REVESTE <bis>\nCOM O DOM CELESTE DO CONSOLADOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (484, 'TEMEI A DEUS', 'TEMEI A DEUS', 'TEMEI A DEUS E DAI-LHE GLÓRIA\nPOIS É CHEGADA A HORA DO SEU JUÍZO;\nE ADORAI AQUELE QUE FEZ O CÉU E A TERRA\nE O MAR E AS FONTES DAS ÁGUAS.\n\nTUA IGREJA TE ESPERA, \nTODOS OS SINAIS SÃO CUMPRIDOS,\nDO FIRMAMENTO TU NOS OUVES\nVEM JÁ, JESUS!\n\nFINAL: VEM JÁ, JESUS!', 'TEMEI A DEUS E DAI-LHE GLÓRIA\nPOIS É CHEGADA A HORA DO SEU JUÍZO;\nE ADORAI AQUELE QUE FEZ O CÉU E A TERRA\nE O MAR E AS FONTES DAS ÁGUAS.\n\nTUA IGREJA TE ESPERA, <bis>\nTODOS OS SINAIS SÃO CUMPRIDOS,<bis>\nDO FIRMAMENTO TU NOS OUVES<bis>\nVEM JÁ, JESUS!<bis>\n<final>VEM JÁ, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (485, 'SETE CASTIÇAIS', 'SETE CASTIÇAIS', 'SETE CASTIÇAIS O ESPÍRITO ACENDEU\nE DO MEIO DA IGREJA NOS FALOU;\nTODO O MUNDO OUVIU A VOZ DO CORDEIRO QUE VENCEU,\nVAI CUMPRIR-SE AGORA O QUE ELE PROMETEU: CRISTO VAI VOLTAR!\n\nO QUE É DIGNO JÁ OS SELOS DESATOU,\nA TROMBETA DA VITÓRIA VAI SOAR;\nA VIDEIRA FLORESCEU, A FIGUEIRA JÁ BROTOU, \nVAI CUMPRIR-SE O QUE ELE UM DIA NOS FALOU: \nCRISTO VAI VOLTAR!\n\nCORO\nMARANATA! CRISTO VAI VOLTAR!\nO ESPÍRITO E A ESPOSA DIZEM:\nVEM! ORA VEM, JESUS!\n\nHÁ SINAIS NO CÉU, NA TERRA E NO MAR,\nO JUÍZO DO SENHOR NÃO VAI TARDAR;\nESTÁS PRONTO MEU IRMÃO, SE DEUS HOJE TE CHAMAR? SÓ NO SANGUE DO CORDEIRO HÁ SALVAÇÃO, CRISTO VAI VOLTAR!\n\nCORO (2X)\nMARANATA! CRISTO VAI VOLTAR!\nO ESPÍRITO E A ESPOSA DIZEM:\nVEM! ORA VEM, JESUS!', 'SETE CASTIÇAIS O ESPÍRITO ACENDEU\nE DO MEIO DA IGREJA NOS FALOU;\nTODO O MUNDO OUVIU A VOZ DO CORDEIRO QUE VENCEU,\nVAI CUMPRIR-SE AGORA O QUE ELE PROMETEU: CRISTO VAI VOLTAR!\n\nO QUE É DIGNO JÁ OS SELOS DESATOU,\nA TROMBETA DA VITÓRIA VAI SOAR;\nA VIDEIRA FLORESCEU, A FIGUEIRA JÁ BROTOU, \nVAI CUMPRIR-SE O QUE ELE UM DIA NOS FALOU: \nCRISTO VAI VOLTAR!\n\n<coro>\nMARANATA! CRISTO VAI VOLTAR!\nO ESPÍRITO E A ESPOSA DIZEM:\nVEM! ORA VEM, JESUS!\n\nHÁ SINAIS NO CÉU, NA TERRA E NO MAR,\nO JUÍZO DO SENHOR NÃO VAI TARDAR;\nESTÁS PRONTO MEU IRMÃO, SE DEUS HOJE TE CHAMAR? SÓ NO SANGUE DO CORDEIRO HÁ SALVAÇÃO, CRISTO VAI VOLTAR!\n\n<coro tipo=''2X''>\nMARANATA! CRISTO VAI VOLTAR!\nO ESPÍRITO E A ESPOSA DIZEM:\nVEM! ORA VEM, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (486, 'DO NORTE VEM O ÁUREO ESPLENDOR', 'DO NORTE VEM O ÁUREO ESPLENDOR', 'DO NORTE VEM O ÁUREO ESPLENDOR,\nO AZUL DO CÉU TAMBÉM ME FAZ SONHAR \nCOM UMA NOVA TERRA, UM NOVO CÉU, \nONDE OS JUSTOS VIVERÃO EM PLENA PAZ E PARA SEMPRE, ONDE UNIDOS VIVERÃO \nE PARA SEMPRE ESTARÃO \nNA PRESENÇA DE JESUS.\n\nINSTRUMENTOS\n\nSEI QUE UM DIA OS PRÉDIOS CAIRÃO\nE OS MOINHOS NÃO MAIS ROLARÃO;\nAPENAS FICARÁ DE PÉ O QUE NA ROCHA \nSE FIRMOU, O QUE ANDOU NA CLARA LUZ, \nO QUE OUVINDO UM DIA CREU \nE QUE OUVINDO OBEDECEU \nA PALAVRA DE JESUS.\n\nINSTRUMENTOS\n\nBREVE A VIDA FINDA O SEU LABOR E SABEREI \nQUE NADA FOI EM VÃO, SE EU SORRI, LUTEI, \nCHOREI, SE CONSEGUI, PERDI, ACHEI, \nO QUE SENTI, TUDO PASSOU;\nIMPORTA AGORA, SIM, ESTAR,\nJUNTO A QUEM POR QUEM VIVI\nJUNTO A TI, Ó MEU SENHOR.', 'DO NORTE VEM O ÁUREO ESPLENDOR,\nO AZUL DO CÉU TAMBÉM ME FAZ SONHAR \nCOM UMA NOVA TERRA, UM NOVO CÉU, \nONDE OS JUSTOS VIVERÃO EM PLENA PAZ E PARA SEMPRE, ONDE UNIDOS VIVERÃO \nE PARA SEMPRE ESTARÃO \nNA PRESENÇA DE JESUS.\n<instrumentos>\n\n\nSEI QUE UM DIA OS PRÉDIOS CAIRÃO\nE OS MOINHOS NÃO MAIS ROLARÃO;\nAPENAS FICARÁ DE PÉ O QUE NA ROCHA \nSE FIRMOU, O QUE ANDOU NA CLARA LUZ, \nO QUE OUVINDO UM DIA CREU \nE QUE OUVINDO OBEDECEU \nA PALAVRA DE JESUS.\n<instrumentos>\n\n\nBREVE A VIDA FINDA O SEU LABOR E SABEREI \nQUE NADA FOI EM VÃO, SE EU SORRI, LUTEI, \nCHOREI, SE CONSEGUI, PERDI, ACHEI, \nO QUE SENTI, TUDO PASSOU;\nIMPORTA AGORA, SIM, ESTAR,<bis>\nJUNTO A QUEM POR QUEM VIVI<bis>\nJUNTO A TI, Ó MEU SENHOR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (487, 'VIGIAI E SEMPRE ORAI, Ó CRENTES', 'VIGIAI E SEMPRE ORAI, Ó CRENTES', 'VIGIAI E SEMPRE ORAI, Ó CRENTES,\nBREVE CRISTO VOLTARÁ;\nPARA O CÉU, O SEU DESCANSO ETERNO, \nOS REMIDOS LEVARÁ.\n\nCORO\nVIGIAI! É ORDEM SANTA,\nVIGIAI EM ORAÇÃO!\nBREVE CRISTO VOLTARÁ,\nPARA O CÉU NOS LEVARÁ!\n\nVIGIAI, GUARDANDO SEMPRE LIMPO,\nDO PECADO, O CORAÇÃO;\nCONFIANDO NO DIVINO MESTRE,\nVENCEREIS A TENTAÇÃO.\n\nCORO\nVIGIAI! É ORDEM SANTA,\nVIGIAI EM ORAÇÃO!\nBREVE CRISTO VOLTARÁ,\nPARA O CÉU NOS LEVARÁ!\n\nVIGIANDO E SEMPRE TRABALHANDO,\nNESTE MUNDO VIL LUTAI,\nAGUARDANDO A VOZ DE JESUS CRISTO: \n''NO MEU DOCE LAR ENTRAI!''', 'VIGIAI E SEMPRE ORAI, Ó CRENTES,\nBREVE CRISTO VOLTARÁ;\nPARA O CÉU, O SEU DESCANSO ETERNO, \nOS REMIDOS LEVARÁ.\n\n<coro>\nVIGIAI! É ORDEM SANTA,\nVIGIAI EM ORAÇÃO!\nBREVE CRISTO VOLTARÁ,\nPARA O CÉU NOS LEVARÁ!\n\nVIGIAI, GUARDANDO SEMPRE LIMPO,\nDO PECADO, O CORAÇÃO;\nCONFIANDO NO DIVINO MESTRE,\nVENCEREIS A TENTAÇÃO.\n\n<coro>\nVIGIAI! É ORDEM SANTA,\nVIGIAI EM ORAÇÃO!\nBREVE CRISTO VOLTARÁ,\nPARA O CÉU NOS LEVARÁ!\n\nVIGIANDO E SEMPRE TRABALHANDO,\nNESTE MUNDO VIL LUTAI,\nAGUARDANDO A VOZ DE JESUS CRISTO: \n''NO MEU DOCE LAR ENTRAI!''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (488, 'CERTA VEZ, AO ORAR', 'CERTA VEZ, AO ORAR', 'CERTA VEZ, AO ORAR, \nPENSEI QUANTO FALTARÁ \nPARA REGRESSAR O NOSSO REI?\nSUA VOZ OUÇO, ENTÃO, \nREVELANDO AO CORAÇÃO: \n''MINHA IGREJA, BREVE VOLTAREI!''\n\nCORO\n''BREVE VENHO VOS BUSCAR \nPARA TER-VOS JUNTO A MIM \nSEDE FORTES E FIÉIS ATÉ O FIM!\nQUE ALEGRIA SINTO, ENTÃO, \nEM MEU CORAÇÃO EU SEI, \nBREVE VIRÁ JESUS, MEU REI!\n\nQUE RIQUEZAS SEM PAR ELE FOI NOS PREPARAR, \nLÁ NO CÉU ONDE NÃO HÁ MAIS DOR; \nMEU DESEJO É PARTIR, PARA SUA VOZ OUVIR: \n''ENTRA NO GOZO DO TEU SENHOR''\n\nCORO\n''BREVE VENHO VOS BUSCAR \nPARA TER-VOS JUNTO A MIM \nSEDE FORTES E FIÉIS ATÉ O FIM!\nQUE ALEGRIA SINTO, ENTÃO, \nEM MEU CORAÇÃO EU SEI, \nBREVE VIRÁ JESUS, MEU REI!', 'CERTA VEZ, AO ORAR, \nPENSEI QUANTO FALTARÁ \nPARA REGRESSAR O NOSSO REI?\nSUA VOZ OUÇO, ENTÃO, \nREVELANDO AO CORAÇÃO: \n''MINHA IGREJA, BREVE VOLTAREI!''\n\n<coro>\n''BREVE VENHO VOS BUSCAR \nPARA TER-VOS JUNTO A MIM \nSEDE FORTES E FIÉIS ATÉ O FIM!\nQUE ALEGRIA SINTO, ENTÃO, \nEM MEU CORAÇÃO EU SEI, \nBREVE VIRÁ JESUS, MEU REI!\n\nQUE RIQUEZAS SEM PAR ELE FOI NOS PREPARAR, \nLÁ NO CÉU ONDE NÃO HÁ MAIS DOR; \nMEU DESEJO É PARTIR, PARA SUA VOZ OUVIR: \n''ENTRA NO GOZO DO TEU SENHOR''\n\n<coro>\n''BREVE VENHO VOS BUSCAR \nPARA TER-VOS JUNTO A MIM \nSEDE FORTES E FIÉIS ATÉ O FIM!\nQUE ALEGRIA SINTO, ENTÃO, \nEM MEU CORAÇÃO EU SEI, \nBREVE VIRÁ JESUS, MEU REI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (489, 'EM BREVE ESCUTAREI', 'EM BREVE ESCUTAREI', 'EM BREVE ESCUTAREI O TOQUE TRIUNFAL\nDA ÚLTIMA TROMBETA CELESTIAL,\nE TODOS OS FIÉIS DO SONO ACORDARÃO\nE AO CÉU CONOSCO JUNTOS SUBIRÃO.\n\nCORO\nALI JESUS VEREI, DE JOELHOS CAIREI\nAOS PÉS DO AMADO SALVADOR!\nE ENTRE A MULTIDÃO CANTAREI A CANÇÃO\nDO MAIS SUBLIME E BELO AMOR!\n\nQUE IMPORTA A DOR AQUI, A BREVE PROVAÇÃO, \nSE VÊ-LO ALI SERÁ MEU GALARDÃO?\nSUA VOZ EU OUVIREI: ''BENDITOS DE MEU PAI, \nNO LAR QUE PREPAREI AGORA ENTRAI!''\n\nCORO\nALI JESUS VEREI, DE JOELHOS CAIREI\nAOS PÉS DO AMADO SALVADOR!\nE ENTRE A MULTIDÃO CANTAREI A CANÇÃO\nDO MAIS SUBLIME E BELO AMOR!', 'EM BREVE ESCUTAREI O TOQUE TRIUNFAL\nDA ÚLTIMA TROMBETA CELESTIAL,\nE TODOS OS FIÉIS DO SONO ACORDARÃO\nE AO CÉU CONOSCO JUNTOS SUBIRÃO.\n\n<coro>\nALI JESUS VEREI, DE JOELHOS CAIREI\nAOS PÉS DO AMADO SALVADOR!\nE ENTRE A MULTIDÃO CANTAREI A CANÇÃO\nDO MAIS SUBLIME E BELO AMOR!\n\nQUE IMPORTA A DOR AQUI, A BREVE PROVAÇÃO, \nSE VÊ-LO ALI SERÁ MEU GALARDÃO?\nSUA VOZ EU OUVIREI: ''BENDITOS DE MEU PAI, \nNO LAR QUE PREPAREI AGORA ENTRAI!''\n\n<coro>\nALI JESUS VEREI, DE JOELHOS CAIREI\nAOS PÉS DO AMADO SALVADOR!\nE ENTRE A MULTIDÃO CANTAREI A CANÇÃO\nDO MAIS SUBLIME E BELO AMOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (490, 'ELE VOLTARÁ PRA BUSCAR A SUA IGREJA', 'ELE VOLTARÁ PRA BUSCAR A SUA IGREJA', 'ELE VOLTARÁ PRA BUSCAR A SUA IGREJA,\nQUE AQUI NO MUNDO FOI FIEL;\nELE VOLTARÁ E MUITOS NÃO ACREDITAM,\nESSES TAIS FICARÃO,\nSOFRENDO, SEM TER SALVAÇÃO.\n\nCORO\nELE PODE VOLTAR AGORA, \nNINGUÉM SABE O DIA NEM A HORA QUE ELE VOLTARÁ;\nELE PODE VOLTAR HOJE MESMO,\nPREPARA-TE, IRMÃO, PRA NÃO FICAR.\n\nELE VOLTARÁ, POIS ASSIM NOS AFIRMA \nA BÍBLIA, MAIS PERTO DE DEUS DEVEMOS FICAR;\nELE VOLTARÁ, ACERTA A TUA VIDA,\nDIANTE DE DEUS, DE SEU SANTO ALTAR.\n\nCORO\nELE PODE VOLTAR AGORA, \nNINGUÉM SABE O DIA NEM A HORA \nQUE ELE VOLTARÁ;\nELE PODE VOLTAR HOJE MESMO,\nPREPARA-TE, IRMÃO, PRA NÃO FICAR.\n\nFINAL: PREPARA-TE IRMÃO PRA NÃO FICAR.', 'ELE VOLTARÁ PRA BUSCAR A SUA IGREJA,\nQUE AQUI NO MUNDO FOI FIEL;\nELE VOLTARÁ E MUITOS NÃO ACREDITAM,\nESSES TAIS FICARÃO,\nSOFRENDO, SEM TER SALVAÇÃO.\n\n<coro>\nELE PODE VOLTAR AGORA, \nNINGUÉM SABE O DIA NEM A HORA QUE ELE VOLTARÁ;\nELE PODE VOLTAR HOJE MESMO,\nPREPARA-TE, IRMÃO, PRA NÃO FICAR.\n\nELE VOLTARÁ, POIS ASSIM NOS AFIRMA \nA BÍBLIA, MAIS PERTO DE DEUS DEVEMOS FICAR;\nELE VOLTARÁ, ACERTA A TUA VIDA,\nDIANTE DE DEUS, DE SEU SANTO ALTAR.\n\n<coro>\nELE PODE VOLTAR AGORA, \nNINGUÉM SABE O DIA NEM A HORA \nQUE ELE VOLTARÁ;\nELE PODE VOLTAR HOJE MESMO,\nPREPARA-TE, IRMÃO, PRA NÃO FICAR.\n<final>PREPARA-TE IRMÃO PRA NÃO FICAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (491, 'ELE UM DIA VOLTARÁ', 'ELE UM DIA VOLTARÁ', 'ELE UM DIA VOLTARÁ,\nVEM BUSCAR A SUA IGREJA,\nMEU JESUS, MEU JESUS VOLTARÁ;\nTODA A TERRA ESTREMECEU\nNO DIA DA SUA PARTIDA,\nMEU JESUS, MEU JESUS, \nMINHA VIDA.\n\nNOSSO FARDO ELE CARREGOU,\nTODO O SEU AMOR NOS DEU,\nNOSSAS DORES CONSIGO LEVOU,\nVIDA NOVA NOS OFERECEU;\nCOMO É BOM SERVIR AO MEU JESUS,\nSEU NOME GLORIFICAR;\nSUA GLÓRIA NOS CONDUZ\nA ANDAR NA SUA LUZ, \nA JESUS QUERO LOUVAR!\n\nFINAL: LOUVAR, LOUVAR.', 'ELE UM DIA VOLTARÁ,\nVEM BUSCAR A SUA IGREJA,\nMEU JESUS, MEU JESUS VOLTARÁ;\nTODA A TERRA ESTREMECEU\nNO DIA DA SUA PARTIDA,\nMEU JESUS, MEU JESUS, \nMINHA VIDA.\n\nNOSSO FARDO ELE CARREGOU,<bis>\nTODO O SEU AMOR NOS DEU,<bis>\nNOSSAS DORES CONSIGO LEVOU,<bis>\nVIDA NOVA NOS OFERECEU;<bis>\nCOMO É BOM SERVIR AO MEU JESUS,<bis>\nSEU NOME GLORIFICAR;<bis>\nSUA GLÓRIA NOS CONDUZ<bis>\nA ANDAR NA SUA LUZ, <bis>\nA JESUS QUERO LOUVAR!\n<final>LOUVAR, LOUVAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (492, 'ELE VOLTARÁ, SIM, ELE VOLTARÁ', 'ELE VOLTARÁ, SIM, ELE VOLTARÁ', 'ELE VOLTARÁ \n(SIM, ELE VOLTARÁ) SERVAS\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) SERVAS\nPARA BUSCAR UMA IGREJA \nA QUAL ESTÁ PREPARADA.\n\nELE VOLTARÁ \n(SIM, ELE VOLTARÁ) SERVAS\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) SERVAS\nPOVO ESCOLHIDO LUTANDO \nCOM CRISTO NESTA BATALHA.\n\nMAS ESTA LUTA AGORA JÁ É O FIM,\nSOMOS FELIZES PORQUE \nNÃO ESTAREMOS AQUI;\nAS TROMBETAS IRÃO SOAR\nE CRISTO EM BREVE VEM NOS BUSCAR\nPARA A GLÓRIA ETERNA HERDAR.\n\nINSTRUMENTOS\n\nELE VOLTARÁ \n(SIM, ELE VOLTARÁ) SERVAS\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) SERVAS\nPARA BUSCAR UMA IGREJA \nA QUAL ESTÁ PREPARADA.\n\nELE VOLTARÁ \n(SIM, ELE VOLTARÁ) SERVAS\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) SERVAS\nPOVO ESCOLHIDO LUTANDO \nCOM CRISTO NESTA BATALHA.\n\nMAS ESTA LUTA AGORA JÁ É O FIM,\nSOMOS FELIZES PORQUE \nNÃO ESTAREMOS AQUI;\nAS TROMBETAS IRÃO SOAR \nE CRISTO EM BREVE VEM \nNOS BUSCAR PARA A \nGLÓRIA ETERNA HERDAR.', 'ELE VOLTARÁ \n(SIM, ELE VOLTARÁ) <m>\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) <m>\nPARA BUSCAR UMA IGREJA \nA QUAL ESTÁ PREPARADA.\n\nELE VOLTARÁ \n(SIM, ELE VOLTARÁ) <m>\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) <m>\nPOVO ESCOLHIDO LUTANDO \nCOM CRISTO NESTA BATALHA.\n\nMAS ESTA LUTA AGORA JÁ É O FIM,\nSOMOS FELIZES PORQUE \nNÃO ESTAREMOS AQUI;\nAS TROMBETAS IRÃO SOAR\nE CRISTO EM BREVE VEM NOS BUSCAR\nPARA A GLÓRIA ETERNA HERDAR.\n<instrumentos>\n\n\nELE VOLTARÁ \n(SIM, ELE VOLTARÁ) <m>\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) <m>\nPARA BUSCAR UMA IGREJA \nA QUAL ESTÁ PREPARADA.\n\nELE VOLTARÁ \n(SIM, ELE VOLTARÁ) <m>\nELE VOLTARÁ\n(SIM, ELE VOLTARÁ) <m>\nPOVO ESCOLHIDO LUTANDO \nCOM CRISTO NESTA BATALHA.\n\nMAS ESTA LUTA AGORA JÁ É O FIM,\nSOMOS FELIZES PORQUE \nNÃO ESTAREMOS AQUI;\nAS TROMBETAS IRÃO SOAR <bis>\nE CRISTO EM BREVE VEM <bis>\nNOS BUSCAR PARA A <bis>\nGLÓRIA ETERNA HERDAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (493, 'COMO FOI PARA O CÉU, JESUS CRISTO HÁ DE VIR', 'COMO FOI PARA O CÉU, JESUS CRISTO HÁ DE VIR', 'COMO FOI PARA O CÉU, JESUS CRISTO HÁ DE VIR,\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO A VOZ DE UM ARCANJO NO \nCÉU ESTRUGIR EU IREI \nCOM JESUS ME ENCONTRAR.\n\nCORO\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nNESSE DIA DE GLÓRIA O MEU CORPO MORTAL, \nSEMELHANTE AO DE CRISTO HÁ DE SER;\nE JÁ LIVRE DA MORTE E JÁ LIVRE DO MAL,\nO MILÊNIO DE CRISTO HEI DE VER.\n\nCORO\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nEU AQUI, PELA CRUZ, PARA O MUNDO MORRI, \nMUITA DOR INDA AQUI SOFREREI;\nMINHA VIDA COM CRISTO, \nEM MEU DEUS ESCONDI \nE COM CRISTO EU AQUI REINAREI.\n\nCORO\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nVEM, JESUS, Ó SENHOR, \nVEM DEPRESSA REINAR, \nVEM A PAZ E A JUSTIÇA TRAZER;\nCRIAÇÃO, POVO TEU, \nTUDO ALMEJA O RAIAR \nDESSE DIA DE GLÓRIA E PODER.\n\nCORO\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nESTE IMPÉRIO DO MAL, VEM, SENHOR, \nDESTRUIR, VEM ESPOSO CELESTE, REINAR!\nVEM Ó SOL DA JUSTIÇA NO MUNDO LUZIR\nÓ MEU REI, VEM MEU PRANTO ESTANCAR!\n\nCORO\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!', 'COMO FOI PARA O CÉU, JESUS CRISTO HÁ DE VIR,\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO A VOZ DE UM ARCANJO NO \nCÉU ESTRUGIR EU IREI \nCOM JESUS ME ENCONTRAR.\n\n<coro>\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nNESSE DIA DE GLÓRIA O MEU CORPO MORTAL, \nSEMELHANTE AO DE CRISTO HÁ DE SER;\nE JÁ LIVRE DA MORTE E JÁ LIVRE DO MAL,\nO MILÊNIO DE CRISTO HEI DE VER.\n\n<coro>\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nEU AQUI, PELA CRUZ, PARA O MUNDO MORRI, \nMUITA DOR INDA AQUI SOFREREI;\nMINHA VIDA COM CRISTO, \nEM MEU DEUS ESCONDI \nE COM CRISTO EU AQUI REINAREI.\n\n<coro>\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nVEM, JESUS, Ó SENHOR, \nVEM DEPRESSA REINAR, \nVEM A PAZ E A JUSTIÇA TRAZER;\nCRIAÇÃO, POVO TEU, \nTUDO ALMEJA O RAIAR \nDESSE DIA DE GLÓRIA E PODER.\n\n<coro>\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!\n\nESTE IMPÉRIO DO MAL, VEM, SENHOR, \nDESTRUIR, VEM ESPOSO CELESTE, REINAR!\nVEM Ó SOL DA JUSTIÇA NO MUNDO LUZIR\nÓ MEU REI, VEM MEU PRANTO ESTANCAR!\n\n<coro>\nOH! QUE DIA FAUSTOSO ESSE DIA HÁ DE SER!\nQUANDO O SOM DA TROMBETA ECOAR;\nQUANDO CRISTO, NAS NUVENS, TIVER \nDE DESCER, TRIUNFANTE, ENTRE NÓS, HABITAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (494, 'NÃO SEI QUANDO CRISTO JESUS HÁ DE VIR', 'NÃO SEI QUANDO CRISTO JESUS HÁ DE VIR', 'NÃO SEI QUANDO CRISTO JESUS \nHÁ DE VIR E NEM QUAL O DIA \nEM QUE EU HEI DE PARTIR, \nMAS EU SEI QUANDO A SUA PRESENÇA LUZIR\nSERÁ GRANDE GLÓRIA PRA MIM (3X)\nMAS EU SEI QUANDO A SUA PRESENÇA \nLUZIR, SERÁ GRANDE GLÓRIA PRA MIM.\n\nNÃO SEI QUE MORADA JESUS VAI ME DAR, \nE NEM QUAL O NOME QUE EU HEI \nDE GANHAR, MAS EU SEI QUE O BEM \nVINDO DELE HEI DE ESCUTAR,\nSÓ ISSO SERÁ CÉU PRA MIM (3X)\nMAS EU SEI QUE O BEM-VINDO \nDELE HEI DE ESCUTAR, \nSÓ ISSO SERÁ CÉU PRA MIM.\n\nO CANTO DOS ANJOS AINDA NÃO SEI \nNEM QUE SINFONIAS EU LÁ OUVIREI, \nMAS EU SEI QUE O FALAR DE JESUS, \nO MEU REI \nSERÁ SINFONIA PRA MIM (3X)\nMAS EU SEI QUE O FALAR DE JESUS, \nO MEU REI, SERÁ SINFONIA PRA MIM.', 'NÃO SEI QUANDO CRISTO JESUS \nHÁ DE VIR E NEM QUAL O DIA \nEM QUE EU HEI DE PARTIR, \nMAS EU SEI QUANDO A SUA PRESENÇA LUZIR\nSERÁ GRANDE GLÓRIA PRA MIM <bis tipo=''3''>\nMAS EU SEI QUANDO A SUA PRESENÇA \nLUZIR, SERÁ GRANDE GLÓRIA PRA MIM.\n\nNÃO SEI QUE MORADA JESUS VAI ME DAR, \nE NEM QUAL O NOME QUE EU HEI \nDE GANHAR, MAS EU SEI QUE O BEM \nVINDO DELE HEI DE ESCUTAR,\nSÓ ISSO SERÁ CÉU PRA MIM <bis tipo=''3''>\nMAS EU SEI QUE O BEM-VINDO \nDELE HEI DE ESCUTAR, \nSÓ ISSO SERÁ CÉU PRA MIM.\n\nO CANTO DOS ANJOS AINDA NÃO SEI \nNEM QUE SINFONIAS EU LÁ OUVIREI, \nMAS EU SEI QUE O FALAR DE JESUS, \nO MEU REI \nSERÁ SINFONIA PRA MIM <bis tipo=''3''>\nMAS EU SEI QUE O FALAR DE JESUS, \nO MEU REI, SERÁ SINFONIA PRA MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (495, 'O QUE HÁ DE VIR, VIRÁ', 'O QUE HÁ DE VIR, VIRÁ', 'O QUE HÁ DE VIR, VIRÁ, (BIS)\nNÃO TARDARÁ, NÃO TARDARÁ,\nJESUS COM PODER VIRÁ.\nINSTRUMENTOS\n\nSÓ OS FIÉIS SUBIRÃO (BIS)\nNÃO TARDARÁ, NÃO TARDARÁ,\nJESUS COM PODER VIRÁ.\n\nINSTRUMENTOS\n\nO QUE HÁ DE VIR, VIRÁ, (2X)\nNÃO TARDARÁ, NÃO TARDARÁ,\nJESUS COM PODER VIRÁ.\n\nINSTRUMENTOS\n\nFINAL: O QUE HÁ DE VIR, VIRÁ (3X)', 'O QUE HÁ DE VIR, VIRÁ, <bis>\nNÃO TARDARÁ, NÃO TARDARÁ,\nJESUS COM PODER VIRÁ.\n<instrumentos>\nSÓ OS FIÉIS SUBIRÃO <bis>\nNÃO TARDARÁ, NÃO TARDARÁ,\nJESUS COM PODER VIRÁ.\n<instrumentos>\n\n\nO QUE HÁ DE VIR, VIRÁ, <bis tipo=''2''>\nNÃO TARDARÁ, NÃO TARDARÁ,\nJESUS COM PODER VIRÁ.\n<instrumentos>\n<final>O QUE HÁ DE VIR, VIRÁ <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (496, 'NÃO VAI TARDAR', 'NÃO VAI TARDAR', 'NÃO VAI TARDAR E CRISTO HÁ DE VOLTAR;\nNÃO VAI TARDAR E VEREMOS JESUS.\nEU QUERO ME PREPARAR,\nPOIS QUERO LOGO SUBIR;\nE QUERO JUNTO A VOCÊ, LÁ NO CÉU,\nCONVERSAR COM JESUS.', 'NÃO VAI TARDAR E CRISTO HÁ DE VOLTAR;<bis>\nNÃO VAI TARDAR E VEREMOS JESUS.<bis>\nEU QUERO ME PREPARAR,<bis>\nPOIS QUERO LOGO SUBIR;<bis>\nE QUERO JUNTO A VOCÊ, LÁ NO CÉU,<bis>\nCONVERSAR COM JESUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (497, 'JESUS, SIM, VEM, DO CÉU EM GLÓRIA ELE VEM', 'JESUS, SIM, VEM, DO CÉU EM GLÓRIA ELE VEM', 'JESUS, SIM, VEM, DO CÉU EM GLÓRIA ELE VEM, \nECOA A NOVA PELO MUNDO ALÉM!\nOH! ESPERANÇA QUE A SUA IGREJA TEM!\nDAI GLÓRIA A DEUS JESUS EM BREVE VEM\n\nCORO (2X)\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.\n\nJESUS SIM, VEM, OS MORTOS \nESPERANDO ESTÃO O GRAN \nMOMENTO DA RESSURREIÇÃO \nE DO SEPULCRO EM BREVE \nSE LEVANTARÃO DAI GLÓRIA A DEUS, \nJESUS EM BREVE VEM!\n\nCORO (2X)\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.\n\nJESUS, SIM, VEM, DO CÉU CERCADO DE ESPLENDOR, \nANIQUILANDO A CORRUPÇÃO E A DOR, \nQUEBRANDO OS LAÇOS DO ASTUTO USURPADOR!\nDAI GLÓRIA A DEUS, JESUS EM BREVE VEM!\n\nCORO (2X)\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.\n\nJESUS, SIM, VEM, COMPLETAMENTE RESTAURAR \nO MUNDO QUE SE ARRUÍNA SEM PARAR SIM, \nTODAS AS COISAS VEM DEPRESSA TRANSFORMAR!\nDAI GLÓRIA A DEUS JESUS EM BREVE VEM!\n\nCORO (2X)\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.', 'JESUS, SIM, VEM, DO CÉU EM GLÓRIA ELE VEM, \nECOA A NOVA PELO MUNDO ALÉM!\nOH! ESPERANÇA QUE A SUA IGREJA TEM!\nDAI GLÓRIA A DEUS JESUS EM BREVE VEM\n\n<coro tipo=''2X''>\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.\n\nJESUS SIM, VEM, OS MORTOS \nESPERANDO ESTÃO O GRAN \nMOMENTO DA RESSURREIÇÃO \nE DO SEPULCRO EM BREVE \nSE LEVANTARÃO DAI GLÓRIA A DEUS, \nJESUS EM BREVE VEM!\n\n<coro tipo=''2X''>\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.\n\nJESUS, SIM, VEM, DO CÉU CERCADO DE ESPLENDOR, \nANIQUILANDO A CORRUPÇÃO E A DOR, \nQUEBRANDO OS LAÇOS DO ASTUTO USURPADOR!\nDAI GLÓRIA A DEUS, JESUS EM BREVE VEM!\n\n<coro tipo=''2X''>\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.\n\nJESUS, SIM, VEM, COMPLETAMENTE RESTAURAR \nO MUNDO QUE SE ARRUÍNA SEM PARAR SIM, \nTODAS AS COISAS VEM DEPRESSA TRANSFORMAR!\nDAI GLÓRIA A DEUS JESUS EM BREVE VEM!\n\n<coro tipo=''2X''>\nNOSSA ESPERANÇA É SUA VINDA,\nO REI DOS REIS VEM NOS BUSCAR;\nNÓS AGUARDAMOS JESUS AINDA,\nTÉ A LUZ DA MANHÃ RAIAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (498, 'CRISTO VEM ME BUSCAR', 'CRISTO VEM ME BUSCAR', 'CRISTO VEM ME BUSCAR,\nPARA O CÉU ME LEVARÁ,\nO CORDEIRO PROMETIDO VOLTARÁ.\n\nCORO\nOH! GLÓRIA, ALELUIA! MARANATA, \nVEM JESUS! ESTOU COBERTO \nPELO SANGUE DESSA CRUZ \nTENHO O CONSOLADOR SUA GLÓRIA \nE ESPLENDOR SOU LIBERTO\nPELO PODER DO SENHOR.\n\nELE MANDA ATENTO ESTAR,\nVIGIAR E SEMPRE ORAR \nPARA O TOQUE DA TROMBETA ESCUTAR.\n\nCORO\nOH! GLÓRIA, ALELUIA! MARANATA, \nVEM JESUS! ESTOU COBERTO \nPELO SANGUE DESSA CRUZ \nTENHO O CONSOLADOR SUA GLÓRIA \nE ESPLENDOR SOU LIBERTO\nPELO PODER DO SENHOR.\n\nOH! QUE GOZO VOU SENTIR\nCOM OS ANJOS A CANTAR,\nPOIS COM CRISTO\nPARA SEMPRE VOU MORAR.\n\nCORO\nOH! GLÓRIA, ALELUIA! MARANATA, \nVEM JESUS! ESTOU COBERTO \nPELO SANGUE DESSA CRUZ \nTENHO O CONSOLADOR SUA GLÓRIA \nE ESPLENDOR SOU LIBERTO\nPELO PODER DO SENHOR.', 'CRISTO VEM ME BUSCAR,<bis>\nPARA O CÉU ME LEVARÁ,<bis>\nO CORDEIRO PROMETIDO VOLTARÁ.<bis>\n\n<coro>\nOH! GLÓRIA, ALELUIA! MARANATA, \nVEM JESUS! ESTOU COBERTO \nPELO SANGUE DESSA CRUZ \nTENHO O CONSOLADOR SUA GLÓRIA \nE ESPLENDOR SOU LIBERTO\nPELO PODER DO SENHOR.\n\nELE MANDA ATENTO ESTAR,<bis>\nVIGIAR E SEMPRE ORAR <bis>\nPARA O TOQUE DA TROMBETA ESCUTAR.<bis>\n\n<coro>\nOH! GLÓRIA, ALELUIA! MARANATA, \nVEM JESUS! ESTOU COBERTO \nPELO SANGUE DESSA CRUZ \nTENHO O CONSOLADOR SUA GLÓRIA \nE ESPLENDOR SOU LIBERTO\nPELO PODER DO SENHOR.\n\nOH! QUE GOZO VOU SENTIR<bis>\nCOM OS ANJOS A CANTAR,<bis>\nPOIS COM CRISTO<bis>\nPARA SEMPRE VOU MORAR.<bis>\n\n<coro>\nOH! GLÓRIA, ALELUIA! MARANATA, \nVEM JESUS! ESTOU COBERTO \nPELO SANGUE DESSA CRUZ \nTENHO O CONSOLADOR SUA GLÓRIA \nE ESPLENDOR SOU LIBERTO\nPELO PODER DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (499, 'OUÇO UMA VOZ TÃO SUAVE', 'OUÇO UMA VOZ TÃO SUAVE', 'OUÇO UMA VOZ TÃO SUAVE,\nUMA VOZ COMO DAS ÁGUAS\nQUE SAI DO TRONO DO SENHOR\nDIZENDO ASSIM COM AMOR:\n\nCORO\n''IGREJA, BREVEMENTE VOLTAREI,\nTUAS LÁGRIMAS EU ENXUGAREI,\nTENHO OUVIDO O TEU CLAMOR,\nTENHO ACEITO O TEU LOUVOR'';\nCOMO EU TE AMO, TU ÉS O MEU AMOR.\n\nINSTRUMENTOS\n\n''ESTOU À DESTRA DE MEU PAI\nINTERCEDENDO POR TODOS VÓS'';\nE QUERO OUVI-LO DIZER:\n''EIS O MOMENTO DA IGREJA SUBIR.''\n\nCORO\n''IGREJA, BREVEMENTE VOLTAREI,\nTUAS LÁGRIMAS EU ENXUGAREI,\nTENHO OUVIDO O TEU CLAMOR,\nTENHO ACEITO O TEU LOUVOR'';\nCOMO EU TE AMO, TU ÉS O MEU AMOR.\n\nFINAL: \nCOMO EU TE AMO, TU ÉS O MEU AMOR.', 'OUÇO UMA VOZ TÃO SUAVE,\nUMA VOZ COMO DAS ÁGUAS\nQUE SAI DO TRONO DO SENHOR\nDIZENDO ASSIM COM AMOR:\n\n<coro>\n''IGREJA, BREVEMENTE VOLTAREI,\nTUAS LÁGRIMAS EU ENXUGAREI,\nTENHO OUVIDO O TEU CLAMOR,\nTENHO ACEITO O TEU LOUVOR'';\nCOMO EU TE AMO, TU ÉS O MEU AMOR.\n<instrumentos>\n\n\n''ESTOU À DESTRA DE MEU PAI\nINTERCEDENDO POR TODOS VÓS'';\nE QUERO OUVI-LO DIZER:\n''EIS O MOMENTO DA IGREJA SUBIR.''\n\n<coro>\n''IGREJA, BREVEMENTE VOLTAREI,\nTUAS LÁGRIMAS EU ENXUGAREI,\nTENHO OUVIDO O TEU CLAMOR,\nTENHO ACEITO O TEU LOUVOR'';\nCOMO EU TE AMO, TU ÉS O MEU AMOR.\n<final>COMO EU TE AMO, TU ÉS O MEU AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (500, 'SEI QUE O SENHOR', 'SEI QUE O SENHOR', 'SEI QUE O SENHOR AO MEU LADO ESTÁ,\nSEI QUE UM DIA ENCONTRÁ-LO-EI.\n\nCORO\nNESSE DIA ALEGRAR-ME-EI, \nCOM OS ANJOS CANTAREI \nLOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.\n\nSEI QUE ESTA VIDA LOGO PASSARÁ,\nSEI QUE O SENHOR TAMBÉM ME LEVARÁ,\nSEI QUE AMANHÃ HÁ UM NOVO ALVORECER\nQUE APAGARÁ AS DORES NO AMANHECER.\n\nCORO\nNESSE DIA ALEGRAR-ME-EI, \nCOM OS ANJOS CANTAREI \nLOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.\n\nSEI QUE A ALEGRIA LOGO VOLTARÁ, \nO AMOR DO SENHOR EM MIM FLORESCERÁ.\n\nCORO\nNESSE DIA ALEGRAR-ME-EI, \nCOM OS ANJOS CANTAREI \nLOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.\n\nINSTRUMENTOS\n\nALEGRAR-ME-EI, COM OS ANJOS \nCANTAREI LOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.', 'SEI QUE O SENHOR AO MEU LADO ESTÁ,\nSEI QUE UM DIA ENCONTRÁ-LO-EI.<coro>\nNESSE DIA ALEGRAR-ME-EI, \nCOM OS ANJOS CANTAREI \nLOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.\n\nSEI QUE ESTA VIDA LOGO PASSARÁ,\nSEI QUE O SENHOR TAMBÉM ME LEVARÁ,\nSEI QUE AMANHÃ HÁ UM NOVO ALVORECER\nQUE APAGARÁ AS DORES NO AMANHECER.<coro>\nNESSE DIA ALEGRAR-ME-EI, \nCOM OS ANJOS CANTAREI \nLOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.\n\nSEI QUE A ALEGRIA LOGO VOLTARÁ, \nO AMOR DO SENHOR EM MIM FLORESCERÁ.<coro>\nNESSE DIA ALEGRAR-ME-EI, \nCOM OS ANJOS CANTAREI \nLOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.\n<instrumentos>\n\n\nALEGRAR-ME-EI, COM OS ANJOS \nCANTAREI LOUVOR E ADORAREI \nPROSTRADO DIANTE DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (501, 'O ESPÍRITO DE DEUS FALA À SUA IGREJA', 'O ESPÍRITO DE DEUS FALA À SUA IGREJA', 'O ESPÍRITO DE DEUS FALA À SUA IGREJA:\n''VIREI BUSCAR OS REMIDOS QUE FORAM LAVADOS \nNO SANGUE DO CORDEIRO, \nNO SANGUE DO FILHO JESUS;\n\nINSTRUMENTOS\n\nCEDO VENHO MUITO EM BREVE, \nEIS QUE ESTOU À PORTA E BATO, \nSE ABRIRES ENTRAREI, \nCUMPRIREI MINHA PROMESSA \nE UM REMIDO TU SERÁS''.\n\nCORO\nEIS O CANTO DE VITÓRIA (DE VITÓRIA)\nVEREMOS O REI DA GLÓRIA (O REI DA GLÓRIA)\nVEREMOS O REI JESUS (O REI JESUS)\nQUE FOI MORTO ALI NA CRUZ;\nRESSUSCITOU DANDO VIDA AO PECADOR.\n\n''BREVE CRISTO VOLTARÁ,\nQUEM VENCER TUDO HERDARÁ\nE EU SEREI SEU DEUS E ELE SERÁ MEU FILHO,\nESSAS PALAVRAS SÃO FIÉIS''.\n\nCORO\nEIS O CANTO DE VITÓRIA (DE VITÓRIA)\nVEREMOS O REI DA GLÓRIA (O REI DA GLÓRIA)\nVEREMOS O REI JESUS (O REI JESUS)\nQUE FOI MORTO ALI NA CRUZ;\nRESSUSCITOU DANDO VIDA AO PECADOR.\n\nFINAL: \nO ESPÍRITO DE DEUS FALA À SUA IGREJA: \n''JESUS VIRÁ, O CORDEIRO VIVO,\nJESUS EM BREVE VIRÁ''.', 'O ESPÍRITO DE DEUS FALA À SUA IGREJA:\n''VIREI BUSCAR OS REMIDOS QUE FORAM LAVADOS \nNO SANGUE DO CORDEIRO, \nNO SANGUE DO FILHO JESUS;\n<instrumentos>\n\n\nCEDO VENHO MUITO EM BREVE, \nEIS QUE ESTOU À PORTA E BATO, \nSE ABRIRES ENTRAREI, \nCUMPRIREI MINHA PROMESSA \nE UM REMIDO TU SERÁS''.\n\n<coro>\nEIS O CANTO DE VITÓRIA (DE VITÓRIA)\nVEREMOS O REI DA GLÓRIA (O REI DA GLÓRIA)\nVEREMOS O REI JESUS (O REI JESUS)\nQUE FOI MORTO ALI NA CRUZ;\nRESSUSCITOU DANDO VIDA AO PECADOR.\n\n''BREVE CRISTO VOLTARÁ,\nQUEM VENCER TUDO HERDARÁ\nE EU SEREI SEU DEUS E ELE SERÁ MEU FILHO,\nESSAS PALAVRAS SÃO FIÉIS''.\n\n<coro>\nEIS O CANTO DE VITÓRIA (DE VITÓRIA)\nVEREMOS O REI DA GLÓRIA (O REI DA GLÓRIA)\nVEREMOS O REI JESUS (O REI JESUS)\nQUE FOI MORTO ALI NA CRUZ;\nRESSUSCITOU DANDO VIDA AO PECADOR.\n\n\n<final>O ESPÍRITO DE DEUS FALA À SUA IGREJA: \n''JESUS VIRÁ, O CORDEIRO VIVO,\nJESUS EM BREVE VIRÁ''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (502, 'QUANDO LÁ DO CÉU DESCENDO', 'QUANDO LÁ DO CÉU DESCENDO', 'QUANDO LÁ DO CÉU DESCENDO,\nPARA OS SEUS, JESUS VOLTAR,\nE O CLARIM DE DEUS A TODOS PROCLAMAR QUE CHEGOU O GRANDE DIA DA VITÓRIA DO MEU REI, EU, POR SUA IMENSA GRAÇA, LÁ ESTAREI.\n\nCORO\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.\n\nNESSE DIA, QUANDO OS MORTOS \nHÃO DE A VOZ DE CRISTO OUVIR, \nE DE SEUS SEPULCROS HÃO DE RESSURGIR, \nOS REMIDOS, TRANSFORMADOS, \nLOGO ACLAMARÃO SEU REI \nE, POR SUA IMENSA GRAÇA, LÁ ESTAREI.\n\nCORO\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.\n\nPELO MUNDO, REJEITADO, FOI JESUS, \nMEU SALVADOR; DESPREZARAM, INSULTARAM \nMEU SENHOR, MAS, FAUSTOSO VEM O DIA \nDA VITÓRIA DO MEU REI E, POR SUA \nIMENSA GRAÇA, LÁ ESTAREI.\n\nCORO\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.\n\nEM MIM MESMO, NADA TENHO EM QUE POSSA CONFIAR, MAS JESUS MORREU NA CRUZ \nPRA ME SALVAR; TÃO-SOMENTE NELE ESPERO, SIM, E SEMPRE ESPERAREI POIS, POR SUA \nIMENSA GRAÇA, LÁ ESTAREI.\n\nCORO\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.', 'QUANDO LÁ DO CÉU DESCENDO,\nPARA OS SEUS, JESUS VOLTAR,\nE O CLARIM DE DEUS A TODOS PROCLAMAR QUE CHEGOU O GRANDE DIA DA VITÓRIA DO MEU REI, EU, POR SUA IMENSA GRAÇA, LÁ ESTAREI.\n\n<coro>\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.\n\nNESSE DIA, QUANDO OS MORTOS \nHÃO DE A VOZ DE CRISTO OUVIR, \nE DE SEUS SEPULCROS HÃO DE RESSURGIR, \nOS REMIDOS, TRANSFORMADOS, \nLOGO ACLAMARÃO SEU REI \nE, POR SUA IMENSA GRAÇA, LÁ ESTAREI.\n\n<coro>\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.\n\nPELO MUNDO, REJEITADO, FOI JESUS, \nMEU SALVADOR; DESPREZARAM, INSULTARAM \nMEU SENHOR, MAS, FAUSTOSO VEM O DIA \nDA VITÓRIA DO MEU REI E, POR SUA \nIMENSA GRAÇA, LÁ ESTAREI.\n\n<coro>\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.\n\nEM MIM MESMO, NADA TENHO EM QUE POSSA CONFIAR, MAS JESUS MORREU NA CRUZ \nPRA ME SALVAR; TÃO-SOMENTE NELE ESPERO, SIM, E SEMPRE ESPERAREI POIS, POR SUA \nIMENSA GRAÇA, LÁ ESTAREI.\n\n<coro>\nQUANDO, ENFIM, CHEGAR O DIA\nDA VITÓRIA DO MEU REI,\nQUANDO, ENFIM, CHEGAR O DIA,\nPELA GRAÇA DE JESUS, EU LÁ ESTAREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (503, 'TENHO SAUDADES DE JESUS, MEU MESTRE', 'TENHO SAUDADES DE JESUS, MEU MESTRE', 'TENHO SAUDADES DE JESUS, MEU MESTRE,\nTENHO SAUDADES DE JESUS, MEU REI,\nMAS AO FINDAR O MEU LABOR TERRESTRE\nME ENCONTRAREI COM ELE, SIM, EU SEI.\n\nCORO\nSAUDADES, TENHO SAUDADES\nDE TI, JESUS, MEU SALVADOR E REI;\nQUERO SENTIR A TUA PRESENÇA,\nPOIS SEI QUE SÓ ASSIM FELIZ SEREI.\n\nTENHO VONTADE DE VIVER PRA CRISTO,\nDE NOS SEUS BRAÇOS SEMPRE ME ABRIGAR;\nSIM, QUERO A ELE SEMPRE SER SUBMISSO\nE CONFIAR NO SEU AMOR SEM PAR.\n\nCORO\nSAUDADES, TENHO SAUDADES\nDE TI, JESUS, MEU SALVADOR E REI;\nQUERO SENTIR A TUA PRESENÇA,\nPOIS SEI QUE SÓ ASSIM FELIZ SEREI.\n\nNÃO QUERES TU TAMBÉM VIVER COM CRISTO \nE NELE SEMPRE CONFIAR?\nSUA PRESENÇA TE DARÁ CONFORTO,\nE SEU AMOR TE LEVARÁ AO LAR.\n\nCORO\nSAUDADES, TENHO SAUDADES\nDE TI, JESUS, MEU SALVADOR E REI;\nQUERO SENTIR A TUA PRESENÇA,\nPOIS SEI QUE SÓ ASSIM FELIZ SEREI.', 'TENHO SAUDADES DE JESUS, MEU MESTRE,\nTENHO SAUDADES DE JESUS, MEU REI,\nMAS AO FINDAR O MEU LABOR TERRESTRE\nME ENCONTRAREI COM ELE, SIM, EU SEI.\n\n<coro>\nSAUDADES, TENHO SAUDADES\nDE TI, JESUS, MEU SALVADOR E REI;\nQUERO SENTIR A TUA PRESENÇA,\nPOIS SEI QUE SÓ ASSIM FELIZ SEREI.\n\nTENHO VONTADE DE VIVER PRA CRISTO,\nDE NOS SEUS BRAÇOS SEMPRE ME ABRIGAR;\nSIM, QUERO A ELE SEMPRE SER SUBMISSO\nE CONFIAR NO SEU AMOR SEM PAR.\n\n<coro>\nSAUDADES, TENHO SAUDADES\nDE TI, JESUS, MEU SALVADOR E REI;\nQUERO SENTIR A TUA PRESENÇA,\nPOIS SEI QUE SÓ ASSIM FELIZ SEREI.\n\nNÃO QUERES TU TAMBÉM VIVER COM CRISTO \nE NELE SEMPRE CONFIAR?\nSUA PRESENÇA TE DARÁ CONFORTO,\nE SEU AMOR TE LEVARÁ AO LAR.\n\n<coro>\nSAUDADES, TENHO SAUDADES\nDE TI, JESUS, MEU SALVADOR E REI;\nQUERO SENTIR A TUA PRESENÇA,\nPOIS SEI QUE SÓ ASSIM FELIZ SEREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (504, 'EU SEI QUE JESUS', 'EU SEI QUE JESUS', 'EU SEI QUE JESUS NÃO TARDA EM VIR,\nO MEU CORAÇÃO PREPARADO ESTÁ.\n\nINSTRUMENTOS\n\nEM CRISTO JESUS, A GLÓRIA POR VIR,\nJESUS É A ESPERANÇA DO MEU CORAÇÃO.\n\nCORO\nJESUS, TU ÉS O MEU REI, \nJESUS É A ESPERANÇA DA GLÓRIA POR VIR,\nPOR VIR, DA GLÓRIA POR VIR,\nJESUS É A ESPERANÇA DO MEU CORAÇÃO.\n\nINSTRUMENTOS\n\nEM BREVE HÁ DE VIR, JESUS, O SENHOR,\nETERNA ESPERANÇA DO MEU CORAÇÃO,\nA GLÓRIA POR VIR, REVELADA, ENTÃO,\nIREI COM JESUS PARA SEMPRE MORAR.\n\nCORO\nJESUS, TU ÉS O MEU REI, \nJESUS É A ESPERANÇA DA GLÓRIA POR VIR,\nPOR VIR, DA GLÓRIA POR VIR,\nJESUS É A ESPERANÇA DO MEU CORAÇÃO.\n\nFINAL: \nJESUS É A ESPERANÇA \nDO MEU CORAÇÃO', 'EU SEI QUE JESUS NÃO TARDA EM VIR,\nO MEU CORAÇÃO PREPARADO ESTÁ.\n<instrumentos>\nEM CRISTO JESUS, A GLÓRIA POR VIR,\nJESUS É A ESPERANÇA DO MEU CORAÇÃO.\n\n<coro>\nJESUS, TU ÉS O MEU REI, \nJESUS É A ESPERANÇA DA GLÓRIA POR VIR,\nPOR VIR, DA GLÓRIA POR VIR,\nJESUS É A ESPERANÇA DO MEU CORAÇÃO.\n<instrumentos>\n\n\nEM BREVE HÁ DE VIR, JESUS, O SENHOR,\nETERNA ESPERANÇA DO MEU CORAÇÃO,\nA GLÓRIA POR VIR, REVELADA, ENTÃO,\nIREI COM JESUS PARA SEMPRE MORAR.\n\n<coro>\nJESUS, TU ÉS O MEU REI, \nJESUS É A ESPERANÇA DA GLÓRIA POR VIR,\nPOR VIR, DA GLÓRIA POR VIR,\nJESUS É A ESPERANÇA DO MEU CORAÇÃO.\n<final>JESUS É A ESPERANÇA \nDO MEU CORAÇÃO', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (505, 'OS SEUS CABELOS', 'OS SEUS CABELOS', 'OS SEUS CABELOS BRANCOS \nSÃO COMO A NEVE E A BRANCA LÃ, \nE OS SEUS OLHOS COMO UMA CHAMA \nFORTE NO ROSTO A BRILHAR;\nRUMOR DE MUITAS ÁGUAS É SUA VOZ \nTAMBÉM, COMO UMA ESPADA AGUDA \nÉ O SEU FALAR.\n\nCORO\nJESUS! JESUS! SENHOR DOS SENHORES!\nPRINCÍPIO E FIM, O QUE ERA E É,\nE O QUE HÁ DE VIR!\nSEU NOME É JESUS! SEU NOME É JESUS!\n\nELE É O CORDEIRO DIGNO DE ABRIR \nO LIVRO POIS NA CRUZ MORREU,\nE COM SEU SANGUE HOMENS DE TODA \nA TRIBO PARA O PAI COMPROU;\nDIGNO É DE RECEBER TODA A ETERNIDADE, \nAÇÕES DE GRAÇAS, \nGLÓRIA E TODO O PODER.\n\nCORO\nJESUS! JESUS! SENHOR DOS SENHORES!\nPRINCÍPIO E FIM, O QUE ERA E É,\nE O QUE HÁ DE VIR!\nSEU NOME É JESUS! SEU NOME É JESUS!\n\nELE É O QUE VEM NAS NUVENS\nBUSCAR A ESPOSA, PREPARADA JÁ,\nCOM SUAS VESTES BRANCAS,\nCANDEIA ACESA E CHEIA DE AMOR;\nELE É A RESPLANDECENTE ESTRELA DA MANHÃ.\n''CEDO VIREI!'' VEM JÁ, Ó SENHOR JESUS!\n\nCORO\nJESUS! JESUS! SENHOR DOS SENHORES!\nPRINCÍPIO E FIM, O QUE ERA E É,\nE O QUE HÁ DE VIR!\nSEU NOME É JESUS! SEU NOME É JESUS!', 'OS SEUS CABELOS BRANCOS \nSÃO COMO A NEVE E A BRANCA LÃ, \nE OS SEUS OLHOS COMO UMA CHAMA \nFORTE NO ROSTO A BRILHAR;\nRUMOR DE MUITAS ÁGUAS É SUA VOZ \nTAMBÉM, COMO UMA ESPADA AGUDA \nÉ O SEU FALAR.\n\n<coro>\nJESUS! JESUS! SENHOR DOS SENHORES!\nPRINCÍPIO E FIM, O QUE ERA E É,\nE O QUE HÁ DE VIR!\nSEU NOME É JESUS! SEU NOME É JESUS!\n\nELE É O CORDEIRO DIGNO DE ABRIR \nO LIVRO POIS NA CRUZ MORREU,\nE COM SEU SANGUE HOMENS DE TODA \nA TRIBO PARA O PAI COMPROU;\nDIGNO É DE RECEBER TODA A ETERNIDADE, \nAÇÕES DE GRAÇAS, \nGLÓRIA E TODO O PODER.\n\n<coro>\nJESUS! JESUS! SENHOR DOS SENHORES!\nPRINCÍPIO E FIM, O QUE ERA E É,\nE O QUE HÁ DE VIR!\nSEU NOME É JESUS! SEU NOME É JESUS!\n\nELE É O QUE VEM NAS NUVENS\nBUSCAR A ESPOSA, PREPARADA JÁ,\nCOM SUAS VESTES BRANCAS,\nCANDEIA ACESA E CHEIA DE AMOR;\nELE É A RESPLANDECENTE ESTRELA DA MANHÃ.\n''CEDO VIREI!'' VEM JÁ, Ó SENHOR JESUS!\n\n<coro>\nJESUS! JESUS! SENHOR DOS SENHORES!\nPRINCÍPIO E FIM, O QUE ERA E É,\nE O QUE HÁ DE VIR!\nSEU NOME É JESUS! SEU NOME É JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (506, 'TU QUE ESTÁS ASSENTADO', 'TU QUE ESTÁS ASSENTADO', 'TU QUE ESTÁS ASSENTADO NO TRONO,\nSEMPRE REINANDO, SOBERANO;\nANJOS CANTANDO, HOMENS LOUVANDO,\nDEUS REUNIDO COM SEU POVO.\n\nÓ, ALFA, ÔMEGA, CRISTO, FILHO,\nÓ VEM, Ó VEM, Ó VEM SENHOR JESUS!\n\nANSIOSO ESPERO A TUA VOLTA,\nNO GRANDE DIA EM QUE TU VIRÁS;\nENTÃO SUBIREMOS, COM CRISTO ESTAREMOS \nPARA SEMPRE, ALELUIA!\n\nMARANATA, CRISTO, FILHO, \nMESTRE,Ó VEM, Ó VEM, Ó VEM,\nSENHOR JESUS!', 'TU QUE ESTÁS ASSENTADO NO TRONO,\nSEMPRE REINANDO, SOBERANO;\nANJOS CANTANDO, HOMENS LOUVANDO,\nDEUS REUNIDO COM SEU POVO.\n\nÓ, ALFA, ÔMEGA, CRISTO, FILHO,\nÓ VEM, Ó VEM, Ó VEM SENHOR JESUS!\n\nANSIOSO ESPERO A TUA VOLTA,\nNO GRANDE DIA EM QUE TU VIRÁS;\nENTÃO SUBIREMOS, COM CRISTO ESTAREMOS \nPARA SEMPRE, ALELUIA!\n\nMARANATA, CRISTO, FILHO, <bis>\nMESTRE,Ó VEM, Ó VEM, Ó VEM,<bis>\nSENHOR JESUS!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (507, 'O SOL ESCURECERÁ', 'O SOL ESCURECERÁ', 'O SOL ESCURECERÁ, A LUA NÃO MAIS BRILHARÁ \nE APARECERÁ NO CÉU COM PODER E GLÓRIA \nO FILHO DO HOMEM.\n\nDIA DE DORES, DIA DE TREVAS, O JUÍZO \nDO SENHOR VIRÁ SOBRE A TERRA;\nDIA GLORIOSO, MARAVILHOSO, \nA IGREJA REINARÁ COM CRISTO NA GLÓRIA.\n\nCANTAREMOS AO SENHOR \nLOUVORES DE VITÓRIA\nPOIS A IGREJA VENCERÁ,\nJESUS VOLTARÁ.\n\nFINAL: JESUS, JESUS VOLTARÁ.', 'O SOL ESCURECERÁ, A LUA NÃO MAIS BRILHARÁ \nE APARECERÁ NO CÉU COM PODER E GLÓRIA \nO FILHO DO HOMEM.\n\nDIA DE DORES, DIA DE TREVAS, O JUÍZO \nDO SENHOR VIRÁ SOBRE A TERRA;\nDIA GLORIOSO, MARAVILHOSO, \nA IGREJA REINARÁ COM CRISTO NA GLÓRIA.\n\nCANTAREMOS AO SENHOR <bis>\nLOUVORES DE VITÓRIA<bis>\nPOIS A IGREJA VENCERÁ,<bis>\nJESUS VOLTARÁ.\n<final>JESUS, JESUS VOLTARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (508, 'BREVE NO CÉU JESUS HÁ DE APARECER', 'BREVE NO CÉU JESUS HÁ DE APARECER', 'BREVE NO CÉU JESUS HÁ DE APARECER,\nEM GLORIOSA LUZ TODOS O HÃO DE VER;\nNAQUELE DIA, ENTÃO, EU HEI DE RECEBER\nDE CRISTO O GALARDÃO OH QUE PRAZER!\n\nCORO\nBREVE VEREI O BOM JESUS\nE VIVEREI EM PLENA LUZ;\nNO LINDO CÉU, EU GOZAREI, \nDE TODA A DOR, POR DEUS, \nLIVRE SEREI.\n\nNA VINDA DO SENHOR DESFRUTAREI PRAZER, \nQUANDO MEU SALVADOR EM GLÓRIA APARECER;\nEIS QUE ELE BREVE VEM, OS SANTOS \nLEVARÁ PARA A MANSÃO DE ALÉM, \nDONDE VIRÁ.\n\nCORO\nBREVE VEREI O BOM JESUS\nE VIVEREI EM PLENA LUZ;\nNO LINDO CÉU, EU GOZAREI, \nDE TODA A DOR, POR DEUS, \nLIVRE SEREI.', 'BREVE NO CÉU JESUS HÁ DE APARECER,\nEM GLORIOSA LUZ TODOS O HÃO DE VER;\nNAQUELE DIA, ENTÃO, EU HEI DE RECEBER\nDE CRISTO O GALARDÃO OH QUE PRAZER!\n\n<coro>\nBREVE VEREI O BOM JESUS\nE VIVEREI EM PLENA LUZ;\nNO LINDO CÉU, EU GOZAREI, \nDE TODA A DOR, POR DEUS, \nLIVRE SEREI.\n\nNA VINDA DO SENHOR DESFRUTAREI PRAZER, \nQUANDO MEU SALVADOR EM GLÓRIA APARECER;\nEIS QUE ELE BREVE VEM, OS SANTOS \nLEVARÁ PARA A MANSÃO DE ALÉM, \nDONDE VIRÁ.\n\n<coro>\nBREVE VEREI O BOM JESUS\nE VIVEREI EM PLENA LUZ;\nNO LINDO CÉU, EU GOZAREI, \nDE TODA A DOR, POR DEUS, \nLIVRE SEREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (509, 'EM BREVE, MUI BREVE', 'EM BREVE, MUI BREVE', 'EM BREVE, MUI BREVE IREMOS VER\nAS PORTAS DO CÉU SE ABRIREM,\nO CORDEIRO DESCENDO EM GLÓRIA\nNO MONTE DAS OLIVEIRAS.\nCORO (2X)\nHOSANA, HOSANA,\nHOSANA AO FILHO DE DAVI\n\nJUNTOS COM OS ANJOS\nLOUVAREMOS O SEU SANTO NOME,\nTODOS OS SEUS REMIDOS\nEXALTARÃO O REI NA SUA GLÓRIA.\nCORO (2X)\nHOSANA, HOSANA,\nHOSANA AO FILHO DE DAVI.\n\nFINAL: HOSANA AO FILHO DE DAVI.', 'EM BREVE, MUI BREVE IREMOS VER\nAS PORTAS DO CÉU SE ABRIREM,\nO CORDEIRO DESCENDO EM GLÓRIA\nNO MONTE DAS OLIVEIRAS.<coro tipo=''2X''>\nHOSANA, HOSANA,\nHOSANA AO FILHO DE DAVI\n\nJUNTOS COM OS ANJOS\nLOUVAREMOS O SEU SANTO NOME,\nTODOS OS SEUS REMIDOS\nEXALTARÃO O REI NA SUA GLÓRIA.<coro tipo=''2X''>\nHOSANA, HOSANA,\nHOSANA AO FILHO DE DAVI.\n<final>HOSANA AO FILHO DE DAVI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (510, 'ALERTA POVO, ESTÁ CHEGANDO A NOSSA HORA', 'ALERTA POVO, ESTÁ CHEGANDO A NOSSA HORA', 'ALERTA POVO, ESTÁ CHEGANDO A NOSSA HORA \nDA VITÓRIA QUE JESUS TEM PRA NOS DAR;\nELE VEM COM PODER E GRANDE GLÓRIA,\nDESCENDO AO MUNDO PARA NOS ARREBATAR.\n\nCORO\nE NUM ABRIR E FECHAR DE OLHOS\nNÓS ESTAREMOS NAS MANSÕES CELESTIAIS, \nE SÓ SE OUVE: GLÓRIA A DEUS E ALELUIA! \nDOS REMIDOS QUE NO CÉU TÊM SEU LUGAR.\n\nALI NÃO HÁ MAIS PRANTO NEM DORES,\nAS NOSSAS LÁGRIMAS JESUS VAI ENXUGAR, \nE BEM NO MEIO ESTÁ A ÁRVORE DA VIDA \nQUE TEM SEUS FRUTOS PARA NOS ALIMENTAR.\n\nCORO\nE NUM ABRIR E FECHAR DE OLHOS\nNÓS ESTAREMOS NAS MANSÕES CELESTIAIS, \nE SÓ SE OUVE: GLÓRIA A DEUS E ALELUIA! \nDOS REMIDOS QUE NO CÉU TÊM SEU LUGAR.', 'ALERTA POVO, ESTÁ CHEGANDO A NOSSA HORA \nDA VITÓRIA QUE JESUS TEM PRA NOS DAR;\nELE VEM COM PODER E GRANDE GLÓRIA,\nDESCENDO AO MUNDO PARA NOS ARREBATAR.\n\n<coro>\nE NUM ABRIR E FECHAR DE OLHOS\nNÓS ESTAREMOS NAS MANSÕES CELESTIAIS, \nE SÓ SE OUVE: GLÓRIA A DEUS E ALELUIA! \nDOS REMIDOS QUE NO CÉU TÊM SEU LUGAR.\n\nALI NÃO HÁ MAIS PRANTO NEM DORES,\nAS NOSSAS LÁGRIMAS JESUS VAI ENXUGAR, \nE BEM NO MEIO ESTÁ A ÁRVORE DA VIDA \nQUE TEM SEUS FRUTOS PARA NOS ALIMENTAR.\n\n<coro>\nE NUM ABRIR E FECHAR DE OLHOS\nNÓS ESTAREMOS NAS MANSÕES CELESTIAIS, \nE SÓ SE OUVE: GLÓRIA A DEUS E ALELUIA! \nDOS REMIDOS QUE NO CÉU TÊM SEU LUGAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (511, 'JESUS CRISTO VOLTARÁ COM SEU GRANDE ESPLENDOR', 'JESUS CRISTO VOLTARÁ COM SEU GRANDE ESPLENDOR', 'JESUS CRISTO VOLTARÁ COM SEU \nGRANDE ESPLENDOR, A IGREJA SUBIRÁ AO ENCONTRO DO SENHOR.\n\nCORO\nMARANATA, MARANATA, VEM, JESUS!\nMARANATA, MARANATA, VEM, JESUS!\n\nESSE DIA CHEGARÁ, ESTAREMOS \nNAS MANSÕES, TUDO AQUI HÁ DE FINDAR, \nJESUS CRISTO VOLTARÁ.\n\nCORO\nMARANATA, MARANATA, VEM, JESUS!\nMARANATA, MARANATA, VEM, JESUS!\n\nCANTAREMOS LOUVORES JUNTO \nCOM OS ANJOS A JESUS, O REI.\nTODOS OS SEUS REMIDOS NO CÉU \nESTARÃO LOUVANDO A CRISTO, O REI.\nCORO\nMARANATA, MARANATA, VEM, JESUS!\nMARANATA, MARANATA, VEM, JESUS!\nFINAL: \nMARANATA, MARANATA, VEM, JESUS!', 'JESUS CRISTO VOLTARÁ COM SEU \nGRANDE ESPLENDOR, A IGREJA SUBIRÁ AO ENCONTRO DO SENHOR.<coro>\nMARANATA, MARANATA, VEM, JESUS!\nMARANATA, MARANATA, VEM, JESUS!\n\nESSE DIA CHEGARÁ, ESTAREMOS \nNAS MANSÕES, TUDO AQUI HÁ DE FINDAR, \nJESUS CRISTO VOLTARÁ.<coro>\nMARANATA, MARANATA, VEM, JESUS!\nMARANATA, MARANATA, VEM, JESUS!\n\nCANTAREMOS LOUVORES JUNTO \nCOM OS ANJOS A JESUS, O REI.\nTODOS OS SEUS REMIDOS NO CÉU \nESTARÃO LOUVANDO A CRISTO, O REI.<coro>\nMARANATA, MARANATA, VEM, JESUS!\nMARANATA, MARANATA, VEM, JESUS!\n<final>MARANATA, MARANATA, VEM, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (512, 'O MEU AMADO FALA E ME DIZ', 'O MEU AMADO FALA E ME DIZ', 'O MEU AMADO FALA E ME DIZ:\n''LEVANTA-TE QUERIDA MINHA FORMOSA \nMINHA E VEM, E VEM, VEM, VEM'';\nPORQUE EIS QUE PASSOU O INVERNO,\nCESSOU A CHUVA E SE FOI,\nAPARECEM AS FLORES NA TERRA,\nCHEGOU O TEMPO DE CANTAREM AS AVES.\n\nA VOZ DA ROLA OUVE-SE EM NOSSA TERRA\nA FIGUEIRA COMEÇOU A DAR SEUS FIGOS\nE AS VIDES EM FLOR EXALAM SEU AROMA;\nLEVANTA-TE, QUERIDA MINHA,\nFORMOSA MINHA E VEM.\n\nPOMBA MINHA QUE ANDAS PELAS FENDAS \nDOS PENHASCOS, NO ESCONDERIJO DAS ROCHAS \nESCARPADAS, MOSTRA-ME O TEU ROSTO, \nFAZE-ME OUVIR A TUA VOZ,\nA TUA VOZ É DOCE E TEU ROSTO AMÁVEL. \n\nA VOZ DA ROLA OUVE-SE EM NOSSA TERRA\nA FIGUEIRA COMEÇOU A DAR SEUS FIGOS\nE AS VIDES EM FLOR EXALAM SEU AROMA;\nLEVANTA-TE, QUERIDA MINHA,\nFORMOSA MINHA E VEM.\n\nPOMBA MINHA QUE ANDAS PELAS FENDAS \nDOS PENHASCOS, NO ESCONDERIJO DAS ROCHAS \nESCARPADAS, MOSTRA-ME O TEU ROSTO, \nFAZE-ME OUVIR A TUA VOZ,\nA TUA VOZ É DOCE E TEU ROSTO AMÁVEL. (3X)', 'O MEU AMADO FALA E ME DIZ:\n''LEVANTA-TE QUERIDA MINHA FORMOSA \nMINHA E VEM, E VEM, VEM, VEM'';\nPORQUE EIS QUE PASSOU O INVERNO,\nCESSOU A CHUVA E SE FOI,\nAPARECEM AS FLORES NA TERRA,\nCHEGOU O TEMPO DE CANTAREM AS AVES.\n\nA VOZ DA ROLA OUVE-SE EM NOSSA TERRA\nA FIGUEIRA COMEÇOU A DAR SEUS FIGOS\nE AS VIDES EM FLOR EXALAM SEU AROMA;\nLEVANTA-TE, QUERIDA MINHA,\nFORMOSA MINHA E VEM.\n\nPOMBA MINHA QUE ANDAS PELAS FENDAS \nDOS PENHASCOS, NO ESCONDERIJO DAS ROCHAS \nESCARPADAS, MOSTRA-ME O TEU ROSTO, \nFAZE-ME OUVIR A TUA VOZ,\nA TUA VOZ É DOCE E TEU ROSTO AMÁVEL. \n\nA VOZ DA ROLA OUVE-SE EM NOSSA TERRA\nA FIGUEIRA COMEÇOU A DAR SEUS FIGOS\nE AS VIDES EM FLOR EXALAM SEU AROMA;\nLEVANTA-TE, QUERIDA MINHA,\nFORMOSA MINHA E VEM.\n\nPOMBA MINHA QUE ANDAS PELAS FENDAS \nDOS PENHASCOS, NO ESCONDERIJO DAS ROCHAS \nESCARPADAS, MOSTRA-ME O TEU ROSTO, \nFAZE-ME OUVIR A TUA VOZ,\nA TUA VOZ É DOCE E TEU ROSTO AMÁVEL. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (513, 'QUEM É ESTA QUE APARECE', 'QUEM É ESTA QUE APARECE', 'QUEM É ESTA QUE APARECE COMO A ALVA DO DIA,\nFORMOSA COMO A LUA, PURA COMO O SOL, \nFORMIDÁVEL COMO UM EXÉRCITO COM BANDEIRAS!\n\nDESCI AO JARDIM DAS NOGUEIRAS,\nPARA MIRAR OS RENOVOS DO VALE,\nPARA VER SE BROTAVAM AS VIDES,\nSE FLORESCIAM AS ROMEIRAS.\nNÃO SEI COMO, IMAGINEI-ME NO CARRO \nDO MEU NOBRE POVO!\n\nVOLTA, VOLTA, Ó, SULAMITA,\nVOLTA, VOLTA\nPRA QUE NÓS TE CONTEMPLEMOS;\nPOR QUE QUEREIS CONTEMPLAR A SULAMITA,\nNA DANÇA DE MAANAIM? (BIS)', 'QUEM É ESTA QUE APARECE COMO A ALVA DO DIA,\nFORMOSA COMO A LUA, PURA COMO O SOL, \nFORMIDÁVEL COMO UM EXÉRCITO COM BANDEIRAS!\n\nDESCI AO JARDIM DAS NOGUEIRAS,\nPARA MIRAR OS RENOVOS DO VALE,\nPARA VER SE BROTAVAM AS VIDES,\nSE FLORESCIAM AS ROMEIRAS.\nNÃO SEI COMO, IMAGINEI-ME NO CARRO \nDO MEU NOBRE POVO!\n\nVOLTA, VOLTA, Ó, SULAMITA,<bis>\nVOLTA, VOLTA<bis>\nPRA QUE NÓS TE CONTEMPLEMOS;<bis>\nPOR QUE QUEREIS CONTEMPLAR A SULAMITA,<bis>\nNA DANÇA DE MAANAIM? <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (514, 'ESTA É A VOZ, A VOZ DO MEU AMADO', 'ESTA É A VOZ, A VOZ DO MEU AMADO', 'ESTA É A VOZ, A VOZ DO MEU AMADO,\nÉS PARA MIM RAMALHETE DE MIRRA;\nTEU PERFUME, UNGUENTO DERRAMADO,\nTU ÉS GENTIL, AGRADÁVEL É O TEU AROMA.\n\nCORO\nVEM COMIGO, (VEM COMIGO) SERVAS\nVEM COMIGO AO CAMPO, (SIM, AO CAMPO) SERVAS\nÓ, VEM! (Ó, VEM!) SERVAS\nMEU AMADO!\n\nTU ÉS TODA FORMOSA, AMIGA MINHA,\nEM TI NÃO HÁ MANCHAS, ESPOSA MINHA;\nFAVOS DE MEL MANAM DOS TEUS LÁBIOS, \nOS TEUS VESTIDOS TÊM CHEIRO AROMÁTICO.\n\nCORO\nVEM COMIGO, (VEM COMIGO) SERVAS\nVEM COMIGO AO CAMPO, (SIM, AO CAMPO) SERVAS\nÓ, VEM! (Ó, VEM!) SERVAS\nMEU AMADO!\n\nTU ÉS FORMOSA, FORMOSA ENTRE AS MULHERES,\nOS TEUS OLHOS SÃO COMO OS DAS POMBAS;\nQUE BELOS SÃO OS TEUS AMORES,\nBEM DE MANHÃ IREMOS ÀS VINHAS.\n\nCORO (2X)\nVEM COMIGO, (VEM COMIGO) SERVAS\nVEM COMIGO AO CAMPO, (SIM, AO CAMPO) SERVAS\nÓ, VEM! (Ó, VEM!) SERVAS\nMEU AMADO!\n\nFINAL: Ó, VEM! (Ó, VEM!) SERVAS\n MEU AMADO!', 'ESTA É A VOZ, A VOZ DO MEU AMADO,\nÉS PARA MIM RAMALHETE DE MIRRA;\nTEU PERFUME, UNGUENTO DERRAMADO,\nTU ÉS GENTIL, AGRADÁVEL É O TEU AROMA.\n\n<coro>\nVEM COMIGO, (VEM COMIGO) <m>\nVEM COMIGO AO CAMPO, (SIM, AO CAMPO) <m>\nÓ, VEM! (Ó, VEM!) <m>\nMEU AMADO!\n\nTU ÉS TODA FORMOSA, AMIGA MINHA,\nEM TI NÃO HÁ MANCHAS, ESPOSA MINHA;\nFAVOS DE MEL MANAM DOS TEUS LÁBIOS, \nOS TEUS VESTIDOS TÊM CHEIRO AROMÁTICO.\n\n<coro>\nVEM COMIGO, (VEM COMIGO) <m>\nVEM COMIGO AO CAMPO, (SIM, AO CAMPO) <m>\nÓ, VEM! (Ó, VEM!) <m>\nMEU AMADO!\n\nTU ÉS FORMOSA, FORMOSA ENTRE AS MULHERES,\nOS TEUS OLHOS SÃO COMO OS DAS POMBAS;\nQUE BELOS SÃO OS TEUS AMORES,\nBEM DE MANHÃ IREMOS ÀS VINHAS.\n\n<coro tipo=''2X''>\nVEM COMIGO, (VEM COMIGO) <m>\nVEM COMIGO AO CAMPO, (SIM, AO CAMPO) <m>\nÓ, VEM! (Ó, VEM!) <m>\nMEU AMADO!\n<final>Ó, VEM! (Ó, VEM!) <m>\n MEU AMADO!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (515, 'QUANDO A ÚLTIMA TROMBETA ECOAR', 'QUANDO A ÚLTIMA TROMBETA ECOAR', 'QUANDO A ÚLTIMA TROMBETA ECOAR\nO MEU NOME OUVIREI JESUS CHAMAR,\nREVESTIDO EM NOVO CORPO ELE ME TRANSFORMARÁ, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n\nCORO\nALELUIA, ALELUIA, ALELUIA, \nELE ME TRANSFORMARÁ;\nALELUIA, ALELUIA, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n\nINSTRUMENTOS\n\nQUANDO A ÚLTIMA TROMBETA ECOAR\nO MEU NOME OUVIREI JESUS CHAMAR,\nREVESTIDO EM NOVO CORPO \nELE ME TRANSFORMARÁ, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n\nCORO\nALELUIA, ALELUIA, ALELUIA, \nELE ME TRANSFORMARÁ;\nALELUIA, ALELUIA, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n\nFINAL: \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.', 'QUANDO A ÚLTIMA TROMBETA ECOAR\nO MEU NOME OUVIREI JESUS CHAMAR,\nREVESTIDO EM NOVO CORPO ELE ME TRANSFORMARÁ, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n\n<coro>\nALELUIA, ALELUIA, ALELUIA, \nELE ME TRANSFORMARÁ;\nALELUIA, ALELUIA, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n<instrumentos>\n\n\nQUANDO A ÚLTIMA TROMBETA ECOAR\nO MEU NOME OUVIREI JESUS CHAMAR,\nREVESTIDO EM NOVO CORPO \nELE ME TRANSFORMARÁ, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n\n<coro>\nALELUIA, ALELUIA, ALELUIA, \nELE ME TRANSFORMARÁ;\nALELUIA, ALELUIA, \nPODEREI ENTÃO SEU ROSTO CONTEMPLAR.\n<final>PODEREI ENTÃO SEU ROSTO CONTEMPLAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (516, 'QUANDO A ANGELICAL TROMBETA', 'QUANDO A ANGELICAL TROMBETA', 'QUANDO A ANGELICAL TROMBETA \nNESTE MUNDO ESTRUGIR, \nO MEU NOME OUVIREI JESUS CHAMAR;\nPOIS EU CREIO NA PROMESSA \nE QUE DEUS A VAI CUMPRIR, QUANDO\nOUVIR JESUS MEU NOME PROCLAMAR.\n\nCORO\nGLÓRIA, GLÓRIA, ALELUIA!\nO MEU NOME OUVIREI JESUS CHAMAR;\nGLÓRIA, GLÓRIA, ALELUIA!\nEU ESPERO OUVIR JESUS A ME CHAMAR.\n\nQUANDO O CÉU FOR ENROLADO \nE O SOL NÃO DER MAIS LUZ, \nO MEU NOME OUVIREI JESUS CHAMAR;\nPASSARÃO A TERRA, O MAR, \nMAS PERMANECERÁ JESUS, QUE MEU\nNOME VAI, NA GLÓRIA, PRONUNCIAR.\n\nCORO\nGLÓRIA, GLÓRIA, ALELUIA!\nO MEU NOME OUVIREI JESUS CHAMAR;\nGLÓRIA, GLÓRIA, ALELUIA!\nEU ESPERO OUVIR JESUS A ME CHAMAR.\n\nOH! QUE MÚSICA SUAVE LÁ NO CÉU IREI OUVIR;\nO MEU NOME JESUS CRISTO ANUNCIAR;\nOH! QUE GOZO VAI MINH''ALMA \nLÁ NOS ALTOS CÉUS FLUIR, QUANDO CRISTO\nO MEU NOME PROCLAMAR.\n\nCORO\nGLÓRIA, GLÓRIA, ALELUIA!\nO MEU NOME OUVIREI JESUS CHAMAR;\nGLÓRIA, GLÓRIA, ALELUIA!\nEU ESPERO OUVIR JESUS A ME CHAMAR.', 'QUANDO A ANGELICAL TROMBETA \nNESTE MUNDO ESTRUGIR, \nO MEU NOME OUVIREI JESUS CHAMAR;\nPOIS EU CREIO NA PROMESSA \nE QUE DEUS A VAI CUMPRIR, QUANDO\nOUVIR JESUS MEU NOME PROCLAMAR.\n\n<coro>\nGLÓRIA, GLÓRIA, ALELUIA!\nO MEU NOME OUVIREI JESUS CHAMAR;\nGLÓRIA, GLÓRIA, ALELUIA!\nEU ESPERO OUVIR JESUS A ME CHAMAR.\n\nQUANDO O CÉU FOR ENROLADO \nE O SOL NÃO DER MAIS LUZ, \nO MEU NOME OUVIREI JESUS CHAMAR;\nPASSARÃO A TERRA, O MAR, \nMAS PERMANECERÁ JESUS, QUE MEU\nNOME VAI, NA GLÓRIA, PRONUNCIAR.\n\n<coro>\nGLÓRIA, GLÓRIA, ALELUIA!\nO MEU NOME OUVIREI JESUS CHAMAR;\nGLÓRIA, GLÓRIA, ALELUIA!\nEU ESPERO OUVIR JESUS A ME CHAMAR.\n\nOH! QUE MÚSICA SUAVE LÁ NO CÉU IREI OUVIR;\nO MEU NOME JESUS CRISTO ANUNCIAR;\nOH! QUE GOZO VAI MINH''ALMA \nLÁ NOS ALTOS CÉUS FLUIR, QUANDO CRISTO\nO MEU NOME PROCLAMAR.\n\n<coro>\nGLÓRIA, GLÓRIA, ALELUIA!\nO MEU NOME OUVIREI JESUS CHAMAR;\nGLÓRIA, GLÓRIA, ALELUIA!\nEU ESPERO OUVIR JESUS A ME CHAMAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (517, 'JÁ NÃO TARDA O AMANHECER', 'JÁ NÃO TARDA O AMANHECER', 'JÁ NÃO TARDA O AMANHECER,\nA ALVORADA DE UM NOVO SER;\nPELOS MONTES DE LUZ JÁ VEM O MEU JESUS!\nELE MANDA ME LEVANTAR,\nHÁ UMA FESTA A CELEBRAR; COM AMOR EU IREI CANTAR LOUVORES AO REI!\nALELUIA, ALELUIA, ALELUIA,\nNÃO TARDA O AMANHECER!\n\nA FIGUEIRA SEUS FRUTOS DÁ,\nA VIDEIRA EM FLOR ESTÁ,\nO INVERNO PASSOU E A CHUVA JÁ CESSOU; \nTODA A TERRA RENASCE EM FLOR,\nPRIMAVERA, CANTANDO AMOR; \nESTÁ TÃO PERTO DE NÓS, JÁ OUÇO A SUA VOZ!\nALELUIA, ALELUIA, ALELUIA,\nJÁ OUÇO A SUA VOZ.\n\nSOPRA O VENTO NO MEU JARDIM,\nQUERO A TEMPO TER FLOR EM MIM,\nSEU PERFUME SEM PAR DESEJO DERRAMAR;\nSE DESCESSES DO ALTO CÉU\nE VIESSES, AMADO MEU, E COMESSES DO FRUTO\nQUE TE QUERO DAR!\nALELUIA, ALELUIA, ALELUIA,\nO MEU AMADO VEM!', 'JÁ NÃO TARDA O AMANHECER,\nA ALVORADA DE UM NOVO SER;\nPELOS MONTES DE LUZ JÁ VEM O MEU JESUS!\nELE MANDA ME LEVANTAR,\nHÁ UMA FESTA A CELEBRAR; COM AMOR EU IREI CANTAR LOUVORES AO REI!\nALELUIA, ALELUIA, ALELUIA,\nNÃO TARDA O AMANHECER!\n\nA FIGUEIRA SEUS FRUTOS DÁ,\nA VIDEIRA EM FLOR ESTÁ,\nO INVERNO PASSOU E A CHUVA JÁ CESSOU; \nTODA A TERRA RENASCE EM FLOR,\nPRIMAVERA, CANTANDO AMOR; \nESTÁ TÃO PERTO DE NÓS, JÁ OUÇO A SUA VOZ!\nALELUIA, ALELUIA, ALELUIA,\nJÁ OUÇO A SUA VOZ.\n\nSOPRA O VENTO NO MEU JARDIM,\nQUERO A TEMPO TER FLOR EM MIM,\nSEU PERFUME SEM PAR DESEJO DERRAMAR;\nSE DESCESSES DO ALTO CÉU\nE VIESSES, AMADO MEU, E COMESSES DO FRUTO\nQUE TE QUERO DAR!\nALELUIA, ALELUIA, ALELUIA,\nO MEU AMADO VEM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (518, 'NÃO TEREI MAIS TRISTEZAS', 'NÃO TEREI MAIS TRISTEZAS', 'NÃO TEREI MAIS TRISTEZAS\nNEM MAIS FARDOS EU LEVAREI,\nNEM MAIS MORTE NEM MAIS DOR,\nEU JAMAIS ME SEPARAREI\nDE MEU MESTRE, MEU SENHOR;\nPARA SEMPRE ALI ESTAREI\nE FELIZ, COM JESUS, EU SEREI.\n\nCORO\nEU VOU COM CRISTO PARA O CÉU \nEM GLÓRIA ANJOS CANTANDO AO MEU REDOR, \nQUERO, COM CRISTO, SUBIR LÁ PRA GLÓRIA, \nCOM CRISTO FELIZ EU SEREI.\n\nOH! QUE DIA TÃO LINDO DO ENCONTRO \nCOM CRISTO E LOUVORES A ELE DAREI.\nOH! QUE ALEGRIA O DIA QUE TEREI A COROA, \nCOM CRISTO FELIZ EU SEREI.\n\nCORO\nEU VOU COM CRISTO PARA O CÉU \nEM GLÓRIA ANJOS CANTANDO AO MEU REDOR, \nQUERO, COM CRISTO, SUBIR LÁ PRA GLÓRIA, \nCOM CRISTO FELIZ EU SEREI.\n\nFINAL: COM CRISTO FELIZ EU SEREI.', 'NÃO TEREI MAIS TRISTEZAS\nNEM MAIS FARDOS EU LEVAREI,\nNEM MAIS MORTE NEM MAIS DOR,\nEU JAMAIS ME SEPARAREI\nDE MEU MESTRE, MEU SENHOR;\nPARA SEMPRE ALI ESTAREI\nE FELIZ, COM JESUS, EU SEREI.\n\n<coro>\nEU VOU COM CRISTO PARA O CÉU \nEM GLÓRIA ANJOS CANTANDO AO MEU REDOR, \nQUERO, COM CRISTO, SUBIR LÁ PRA GLÓRIA, \nCOM CRISTO FELIZ EU SEREI.\n\nOH! QUE DIA TÃO LINDO DO ENCONTRO \nCOM CRISTO E LOUVORES A ELE DAREI.\nOH! QUE ALEGRIA O DIA QUE TEREI A COROA, \nCOM CRISTO FELIZ EU SEREI.\n\n<coro>\nEU VOU COM CRISTO PARA O CÉU \nEM GLÓRIA ANJOS CANTANDO AO MEU REDOR, \nQUERO, COM CRISTO, SUBIR LÁ PRA GLÓRIA, \nCOM CRISTO FELIZ EU SEREI.\n<final>COM CRISTO FELIZ EU SEREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (519, 'UM NOVO LAR ME ESPERA', 'UM NOVO LAR ME ESPERA', 'UM NOVO LAR ME ESPERA,\nVOU COM JESUS MORAR;\nQUE ALEGRIA SEM PAR,\nVOU PRA GLÓRIA, É A VITÓRIA.\nANDAR PELAS RUAS DE OURO\nCOM OS ANJOS E O REI JESUS,\nA QUEM ENTREGUEI A MINHA VIDA\nPOIS POR MIM MORREU NA CRUZ.', 'UM NOVO LAR ME ESPERA,\nVOU COM JESUS MORAR;\nQUE ALEGRIA SEM PAR,\nVOU PRA GLÓRIA, É A VITÓRIA.\nANDAR PELAS RUAS DE OURO<bis>\nCOM OS ANJOS E O REI JESUS,<bis>\nA QUEM ENTREGUEI A MINHA VIDA<bis>\nPOIS POR MIM MORREU NA CRUZ. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (520, 'NO TRONO DA CIDADE DE DEUS', 'NO TRONO DA CIDADE DE DEUS', 'NO TRONO DA CIDADE DE DEUS, JERUSALÉM,\nOS ANJOS CANTAM ALELUIA,\nLOUVANDO A JESUS, REI DOS REIS,\nO SALVADOR, O LEÃO DE JUDÁ.\n\nCORO\nGLÓRIA AO QUE VENCEU E VIVO ESTÁ ENTRE NÓS, \nGLÓRIA, MILHARES DE VOZES NO CÉU \nPROCLAMAM EM UMA SÓ VOZ: SANTO, SANTO.\n\nINSTRUMENTOS\n\nEM BREVE O MEU JESUS VOLTARÁ\nPARA LEVAR A IGREJA FIEL\nE TODOS JUNTOS NA ETERNIDADE,\nCOM O SALVADOR NA ETERNA SIÃO!\n\nCORO\nGLÓRIA AO QUE VENCEU E VIVO ESTÁ ENTRE NÓS, \nGLÓRIA, MILHARES DE VOZES NO CÉU \nPROCLAMAM EM UMA SÓ VOZ: SANTO, SANTO.\n\nFINAL: \n(SANTO) SANTO, SANTO,\n(SANTO) SANTO, SANTO.', 'NO TRONO DA CIDADE DE DEUS, JERUSALÉM,\nOS ANJOS CANTAM ALELUIA,\nLOUVANDO A JESUS, REI DOS REIS,\nO SALVADOR, O LEÃO DE JUDÁ.\n\n<coro>\nGLÓRIA AO QUE VENCEU E VIVO ESTÁ ENTRE NÓS, \nGLÓRIA, MILHARES DE VOZES NO CÉU \nPROCLAMAM EM UMA SÓ VOZ: SANTO, SANTO.\n<instrumentos>\n\n\nEM BREVE O MEU JESUS VOLTARÁ\nPARA LEVAR A IGREJA FIEL\nE TODOS JUNTOS NA ETERNIDADE,\nCOM O SALVADOR NA ETERNA SIÃO!\n\n<coro>\nGLÓRIA AO QUE VENCEU E VIVO ESTÁ ENTRE NÓS, \nGLÓRIA, MILHARES DE VOZES NO CÉU \nPROCLAMAM EM UMA SÓ VOZ: SANTO, SANTO.\n<final>(SANTO) SANTO, SANTO,\n(SANTO) SANTO, SANTO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (521, 'AO CHEGAR AO CÉU GOZO EU TEREI', 'AO CHEGAR AO CÉU GOZO EU TEREI', 'AO CHEGAR AO CÉU GOZO EU TEREI,\nNAS RUAS DE OURO SEI QUE ANDAREI;\nÁGUAS CRISTALINAS LÁ DESFRUTAREI\nE UM CORO CELESTIAL OUVIREI.\n\nCORO\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS;\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS, JESUS.\n\nNÃO HAVERÁ MAIS DOR NA BELA SIÃO,\nOS SALVOS DO SENHOR REINARÃO;\nSÓ EXISTE A PAZ E O GRANDE AMOR \nDE DEUS QUE PREPAROU \nPARA OS SEUS FIÉIS.\n\nCORO \nSANTO, SANTO, SANTO, SANTO, SANTO ÉS;\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS, JESUS.\n\nNOVA JERUSALÉM, CIDADE ETERNAL,\nRESPLANDECE A LUZ DO MEU REI;\nAO MEU TRIUNO DEUS PRA SEMPRE ADORAR\nCOM OS ANJOS EU TAMBÉM LOUVAREI.\n\nCORO (2X)\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS;\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS, JESUS.', 'AO CHEGAR AO CÉU GOZO EU TEREI,\nNAS RUAS DE OURO SEI QUE ANDAREI;\nÁGUAS CRISTALINAS LÁ DESFRUTAREI\nE UM CORO CELESTIAL OUVIREI.\n\n<coro>\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS;\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS, JESUS.\n\nNÃO HAVERÁ MAIS DOR NA BELA SIÃO,\nOS SALVOS DO SENHOR REINARÃO;\nSÓ EXISTE A PAZ E O GRANDE AMOR \nDE DEUS QUE PREPAROU \nPARA OS SEUS FIÉIS.\n\n<coro>\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS;\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS, JESUS.\n\nNOVA JERUSALÉM, CIDADE ETERNAL,\nRESPLANDECE A LUZ DO MEU REI;\nAO MEU TRIUNO DEUS PRA SEMPRE ADORAR\nCOM OS ANJOS EU TAMBÉM LOUVAREI.\n\n<coro tipo=''2X''>\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS;\nSANTO, SANTO, SANTO, SANTO, SANTO ÉS, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (522, 'EXISTE UM LAR', 'EXISTE UM LAR', 'EXISTE UM LAR QUE COM GRANDE AMOR \nFOI PREPARADO,DELE DESFRUTARÁ \nTODO AQUELE QUE A JESUS SE ENTREGOU.\nCORO\nNOVO CÉU, NOVA TERRA, NOVO LAR;\nDE FILHO, O MEU DEUS ME CHAMARÁ.\n\nMORTE, NEM LUTO,\nPRANTO, NEM DOR, \nSÓ PORTAS ABERTAS, \nLUZ E AMOR. \n\nCORO\nNOVO CÉU, NOVA TERRA, NOVO LAR;\nDE FILHO, O MEU DEUS ME CHAMARÁ.', 'EXISTE UM LAR QUE COM GRANDE AMOR \nFOI PREPARADO,DELE DESFRUTARÁ \nTODO AQUELE QUE A JESUS SE ENTREGOU.<coro>\nNOVO CÉU, NOVA TERRA, NOVO LAR;\nDE FILHO, O MEU DEUS ME CHAMARÁ.\n\nMORTE, NEM LUTO,<bis>\nPRANTO, NEM DOR, <bis>\nSÓ PORTAS ABERTAS, <bis>\nLUZ E AMOR.<coro>\nNOVO CÉU, NOVA TERRA, NOVO LAR;\nDE FILHO, O MEU DEUS ME CHAMARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (523, 'LÁ NO CÉU OS ANJOS CANTAM', 'LÁ NO CÉU OS ANJOS CANTAM', 'LÁ NO CÉU OS ANJOS CANTAM:\nVIVA, VIVA O REI;\nLINDO CORO CELESTIAL\nNA BELA CIDADE ETERNAL.\n\nCORO \nEM BREVE TAMBÉM ESTAREI\nNA SANTA CIDADE DE LUZ,\nLOUVANDO SEMPRE O MEU REI,\nO MEU PRECIOSO JESUS. \n\nLINDO RIO PURO DE ÁGUA VIVA\nQUE VEM DE DEUS PAI;\nLÁ NÃO HÁ TRISTEZA E DOR,\nSÓ PAZ, ALEGRIA E AMOR.\n\nCORO (2X)\nEM BREVE TAMBÉM ESTAREI\nNA SANTA CIDADE DE LUZ,\nLOUVANDO SEMPRE O MEU REI,\nO MEU PRECIOSO JESUS. (2X NO FINAL)', 'LÁ NO CÉU OS ANJOS CANTAM:\nVIVA, VIVA O REI;\nLINDO CORO CELESTIAL\nNA BELA CIDADE ETERNAL.\n\n<coro>\nEM BREVE TAMBÉM ESTAREI\nNA SANTA CIDADE DE LUZ,\nLOUVANDO SEMPRE O MEU REI,\nO MEU PRECIOSO JESUS. \n\nLINDO RIO PURO DE ÁGUA VIVA\nQUE VEM DE DEUS PAI;\nLÁ NÃO HÁ TRISTEZA E DOR,\nSÓ PAZ, ALEGRIA E AMOR.\n\n<coro tipo=''2X''>\nEM BREVE TAMBÉM ESTAREI\nNA SANTA CIDADE DE LUZ,\nLOUVANDO SEMPRE O MEU REI,\nO MEU PRECIOSO JESUS. <bis tipo=''2''> NO FINAL)', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (524, 'SE EU TIVESSE NA ALVORADA', 'SE EU TIVESSE NA ALVORADA', 'SE EU ESTIVESSE NA ALVORADA\nCOM AS ASAS ALVAS PARA VOAR,\nEU, MUI CONTENTE, ME TRANSLADAVA\nPARA AS FRONTEIRAS DE CANAÃ.\n\nCORO\nANJOS DE BRANCO ME LEVARIAM\nJUNTO À PRESENÇA DO MEU SENHOR,\nE EU, COM JÚBILO, CANTARIA\nCOM OS JÁ SALVOS POR SEU AMOR.\nLÁ NÃO HÁ PRANTO, NEM AMARGURA,\nLÁ NÃO SE SABE O QUE É DOR,\nALI É GOZO E ALEGRIA,\nALI É TUDO PURO AMOR.\n\nVESTIDOS BRANCOS, PALMA E COROA\nCADA UM DELES RECEBERÁ;\nE SE AGORA A CRISTO EU SIGO,\nJUNTO A ELE HEI DE VENCER.\n\nCORO\nANJOS DE BRANCO ME LEVARIAM\nJUNTO À PRESENÇA DO MEU SENHOR,\nE EU, COM JÚBILO, CANTARIA\nCOM OS JÁ SALVOS POR SEU AMOR.\nLÁ NÃO HÁ PRANTO, NEM AMARGURA,\nLÁ NÃO SE SABE O QUE É DOR,\nALI É GOZO E ALEGRIA,\nALI É TUDO PURO AMOR.', 'SE EU ESTIVESSE NA ALVORADA\nCOM AS ASAS ALVAS PARA VOAR,\nEU, MUI CONTENTE, ME TRANSLADAVA\nPARA AS FRONTEIRAS DE CANAÃ.\n\n<coro>\nANJOS DE BRANCO ME LEVARIAM\nJUNTO À PRESENÇA DO MEU SENHOR,\nE EU, COM JÚBILO, CANTARIA\nCOM OS JÁ SALVOS POR SEU AMOR.\nLÁ NÃO HÁ PRANTO, NEM AMARGURA,\nLÁ NÃO SE SABE O QUE É DOR,\nALI É GOZO E ALEGRIA,\nALI É TUDO PURO AMOR.\n\nVESTIDOS BRANCOS, PALMA E COROA\nCADA UM DELES RECEBERÁ;\nE SE AGORA A CRISTO EU SIGO,\nJUNTO A ELE HEI DE VENCER.\n\n<coro>\nANJOS DE BRANCO ME LEVARIAM\nJUNTO À PRESENÇA DO MEU SENHOR,\nE EU, COM JÚBILO, CANTARIA\nCOM OS JÁ SALVOS POR SEU AMOR.\nLÁ NÃO HÁ PRANTO, NEM AMARGURA,\nLÁ NÃO SE SABE O QUE É DOR,\nALI É GOZO E ALEGRIA,\nALI É TUDO PURO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (525, 'HÁ UM LINDO PAÍS', 'HÁ UM LINDO PAÍS', 'HÁ UM LINDO PAÍS\nONDE OS ANJOS NÃO CESSAM\nDE ENTOAR LOUVORES AO GRANDE REI.\n\nCORO\nUM CORO CELESTIAL ÀQUELE \nQUE É DIGNO DE ABRIR O LIVRO,\nA JESUS, O LEÃO DA TRIBO DE JUDÁ.\n\nNO MEU NOVO LAR AS LÁGRIMAS \nJÁ NÃO CORREM POIS O SENHOR\nCOM SEU AMOR ENXUGOU.\n\nCORO\nUM CORO CELESTIAL ÀQUELE \nQUE É DIGNO DE ABRIR O LIVRO,\nA JESUS, O LEÃO DA TRIBO DE JUDÁ.\n\nNO MEU NOVO LAR AS LÁGRIMAS \nJÁ NÃO CORREM POIS O SENHOR\nCOM SEU AMOR ENXUGOU.\n\nCORO\nUM CORO CELESTIAL ÀQUELE \nQUE É DIGNO DE ABRIR O LIVRO,\nA JESUS, O LEÃO DA TRIBO DE JUDÁ.\n\nFINAL: (2X)\n(UM CORO CELESTIAL)\nA JESUS, O LEÃO DA TRIBO DE JUDÁ', 'HÁ UM LINDO PAÍS\nONDE OS ANJOS NÃO CESSAM\nDE ENTOAR LOUVORES AO GRANDE REI.<coro>\nUM CORO CELESTIAL ÀQUELE \nQUE É DIGNO DE ABRIR O LIVRO,\nA JESUS, O LEÃO DA TRIBO DE JUDÁ.\n\nNO MEU NOVO LAR AS LÁGRIMAS \nJÁ NÃO CORREM POIS O SENHOR\nCOM SEU AMOR ENXUGOU.<coro>\nUM CORO CELESTIAL ÀQUELE \nQUE É DIGNO DE ABRIR O LIVRO,\nA JESUS, O LEÃO DA TRIBO DE JUDÁ.\n\nNO MEU NOVO LAR AS LÁGRIMAS \nJÁ NÃO CORREM POIS O SENHOR\nCOM SEU AMOR ENXUGOU.<coro>\nUM CORO CELESTIAL ÀQUELE \nQUE É DIGNO DE ABRIR O LIVRO,\nA JESUS, O LEÃO DA TRIBO DE JUDÁ.\n<final>(<bis tipo=''2''>\n(UM CORO CELESTIAL)\nA JESUS, O LEÃO DA TRIBO DE JUDÁ', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (526, 'LINDO! LINDO! LINDO!', 'LINDO! LINDO! LINDO!', 'CORO (2X)\nLINDO! LINDO! LINDO! \nÉ NOVA JERUSALÉM. \n\nCIDADE SANTA DO MEU REI E SENHOR,\nANJOS E ARCANJOS HABITAM ALI;\nA MORTE E A DOR JAMAIS ENTRARÃO\nNESSA CIDADE ETERNA DE GOZO E DE PAZ.\n\nCORO (2X)\nLINDO! LINDO! LINDO! \nÉ NOVA JERUSALÉM.\n\nINSTRUMENTOS\n\nOH! QUANTO ALMEJO ESTAR ALI\nNESSA CIDADE DE BRILHO ETERNAL,\nPARA CONTEMPLAR O REI JESUS,\nAQUELE QUE REVELOU A MIM SUA LUZ.\n\nCORO (2X)\nLINDO! LINDO! LINDO! \nÉ NOVA JERUSALÉM.', '<coro tipo=''2X''>\nLINDO! LINDO! LINDO! \nÉ NOVA JERUSALÉM. \n\nCIDADE SANTA DO MEU REI E SENHOR,\nANJOS E ARCANJOS HABITAM ALI;\nA MORTE E A DOR JAMAIS ENTRARÃO\nNESSA CIDADE ETERNA DE GOZO E DE PAZ.<coro tipo=''2X''>\nLINDO! LINDO! LINDO! \nÉ NOVA JERUSALÉM.\n<instrumentos>\n\n\nOH! QUANTO ALMEJO ESTAR ALI\nNESSA CIDADE DE BRILHO ETERNAL,\nPARA CONTEMPLAR O REI JESUS,\nAQUELE QUE REVELOU A MIM SUA LUZ.<coro tipo=''2X''>\nLINDO! LINDO! LINDO! \nÉ NOVA JERUSALÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (527, 'REGOZIJAI-VOS', 'REGOZIJAI-VOS', '''REGOZIJAI-VOS, Ó MEUS AMADOS,\nESPERAI UM POUCO MAIS,\nO MEU FILHO VIRÁ EM BREVE,\nSOBRE AS NUVENS ELE VIRÁ,\nJESUS VIRÁ!''\n\nCORO\nDESPERTAI (DESPERTAI) \nÓ FILHOS DE SIÃO, CONFIAI (CONFIAI)\nNO DEUS DE ABRAÃO,\nDEUS PROVERÁ, DEUS DE ISRAEL; EXULTAI (EXULTAI)\nNA VOSSA SALVAÇÃO POIS JESUS VIRÁ!\n\nINSTRUMENTOS\n\n''SANTIFICAI-VOS COMO EU SOU SANTO, \nRENOVAI VOSSAS CANDEIAS\nCOM O ÓLEO DO MEU ESPÍRITO;\nPREPARAI-VOS, ELE VIRÁ,\nJESUS VIRÁ!''\n\nCORO (2X)\nDESPERTAI (DESPERTAI) \nÓ FILHOS DE SIÃO, CONFIAI (CONFIAI)\nNO DEUS DE ABRAÃO,\nDEUS PROVERÁ, DEUS DE ISRAEL; EXULTAI (EXULTAI)\nNA VOSSA SALVAÇÃO POIS JESUS VIRÁ!\n\nFINAL: ELE VIRÁ, JESUS VIRÁ!', '''REGOZIJAI-VOS, Ó MEUS AMADOS,\nESPERAI UM POUCO MAIS,\nO MEU FILHO VIRÁ EM BREVE,\nSOBRE AS NUVENS ELE VIRÁ,\nJESUS VIRÁ!''\n\n<coro>\nDESPERTAI (DESPERTAI) \nÓ FILHOS DE SIÃO, CONFIAI (CONFIAI)\nNO DEUS DE ABRAÃO,\nDEUS PROVERÁ, DEUS DE ISRAEL; EXULTAI (EXULTAI)\nNA VOSSA SALVAÇÃO POIS JESUS VIRÁ!\n<instrumentos>\n\n\n''SANTIFICAI-VOS COMO EU SOU SANTO, \nRENOVAI VOSSAS CANDEIAS\nCOM O ÓLEO DO MEU ESPÍRITO;\nPREPARAI-VOS, ELE VIRÁ,\nJESUS VIRÁ!''\n\n<coro tipo=''2X''>\nDESPERTAI (DESPERTAI) \nÓ FILHOS DE SIÃO, CONFIAI (CONFIAI)\nNO DEUS DE ABRAÃO,\nDEUS PROVERÁ, DEUS DE ISRAEL; EXULTAI (EXULTAI)\nNA VOSSA SALVAÇÃO POIS JESUS VIRÁ!\n<final>ELE VIRÁ, JESUS VIRÁ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (528, 'EU AVISTO UMA TERRA FELIZ', 'EU AVISTO UMA TERRA FELIZ', 'EU AVISTO UMA TERRA FELIZ,\nONDE IREI PARA SEMPRE MORAR;\nHÁ MANSÕES NESSE LINDO PAÍS\nQUE JESUS FOI AO CÉU PREPARAR.\n\nVOU MORAR, VOU MORAR\nNESSA TERRA CELESTE PORVIR.\n\nCANTAREI NESSE LINDO PAÍS,\nBELOS HINOS AO MEU SALVADOR\nPOIS ALI VIVEREI BEM FELIZ,\nSEM TRISTEZAS, VEXAMES NEM DOR.\n\nVOU CANTAR, VOU CANTAR\nNESSA TERRA CELESTE PORVIR.\n\nDEIXAREI ESTE MUNDO AFINAL,\nPARA IR A JESUS ADORAR;\nNESSA BELA CIDADE FESTAL,\nMIL VENTURAS SEM FIM VOU GOZAR.\n\nVOU GOZAR, VOU GOZAR\nNESSA TERRA CELESTE PORVIR.', 'EU AVISTO UMA TERRA FELIZ,\nONDE IREI PARA SEMPRE MORAR;\nHÁ MANSÕES NESSE LINDO PAÍS\nQUE JESUS FOI AO CÉU PREPARAR.\n\nVOU MORAR, VOU MORAR<bis>\nNESSA TERRA CELESTE PORVIR.<bis>\n\nCANTAREI NESSE LINDO PAÍS,\nBELOS HINOS AO MEU SALVADOR\nPOIS ALI VIVEREI BEM FELIZ,\nSEM TRISTEZAS, VEXAMES NEM DOR.\n\nVOU CANTAR, VOU CANTAR<bis>\nNESSA TERRA CELESTE PORVIR.<bis>\n\nDEIXAREI ESTE MUNDO AFINAL,\nPARA IR A JESUS ADORAR;\nNESSA BELA CIDADE FESTAL,\nMIL VENTURAS SEM FIM VOU GOZAR.\n\nVOU GOZAR, VOU GOZAR<bis>\nNESSA TERRA CELESTE PORVIR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (529, 'EU OUVI DA FORMOSA CIDADE', 'EU OUVI DA FORMOSA CIDADE', 'EU OUVI DA FORMOSA CIDADE,\nMUITO ACIMA DE TUDO NO MUNDO,\nEU SENTI UM DESEJO PROFUNDO\nDE UM DIA ESTAR COM JESUS.\nALELUIA, EM VOZ TRIUNFANTE,\nJÁ ESCUTO O CORO CELESTE,\nTERMINADA A MÁGOA TERRESTRE\nESTAREI COM JESUS LÁ NO CÉU.\n\nEU OUVI DE UM VESTIDO TÃO ALVO,\nDA COROA ORNADA DE ESTRELAS,\nDOS IRMÃOS, DA FELIZ PARENTELA,\nQUE UM DIA VEREI EU ALI.\nALELUIA, ALI TUDO É GOZO\nCADA DÚVIDA FOI DISSIPADA,\nPARA SEMPRE A MALÍCIA É TIRADA,\nESTOU NO ALVO, \nNO CÉU COM JESUS.\n\nEU OUVI DE UM PAÍS TÃO DISTANTE,\nONDE NÃO HÁ DOENÇAS NEM DORES,\nNÃO HÁ MAIS ESTES VIS TENTADORES,\nQUE PERTURBAM A VIDA AQUI.\nALELUIA, FELIZ ESPERANÇA,\nJÁ ESCUTO O CANTO CELESTE,\nTERMINADA A MÁGOA TERRESTRE\nESTAREI COM JESUS LÁ NO CÉU.', 'EU OUVI DA FORMOSA CIDADE,\nMUITO ACIMA DE TUDO NO MUNDO,\nEU SENTI UM DESEJO PROFUNDO\nDE UM DIA ESTAR COM JESUS.\nALELUIA, EM VOZ TRIUNFANTE,\nJÁ ESCUTO O CORO CELESTE,\nTERMINADA A MÁGOA TERRESTRE\nESTAREI COM JESUS LÁ NO CÉU.\n\nEU OUVI DE UM VESTIDO TÃO ALVO,\nDA COROA ORNADA DE ESTRELAS,\nDOS IRMÃOS, DA FELIZ PARENTELA,\nQUE UM DIA VEREI EU ALI.\nALELUIA, ALI TUDO É GOZO\nCADA DÚVIDA FOI DISSIPADA,\nPARA SEMPRE A MALÍCIA É TIRADA,\nESTOU NO ALVO, \nNO CÉU COM JESUS.\n\nEU OUVI DE UM PAÍS TÃO DISTANTE,\nONDE NÃO HÁ DOENÇAS NEM DORES,\nNÃO HÁ MAIS ESTES VIS TENTADORES,\nQUE PERTURBAM A VIDA AQUI.\nALELUIA, FELIZ ESPERANÇA,\nJÁ ESCUTO O CANTO CELESTE,\nTERMINADA A MÁGOA TERRESTRE\nESTAREI COM JESUS LÁ NO CÉU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (530, 'OH! QUE SAUDOSA LEMBRANÇA', 'OH! QUE SAUDOSA LEMBRANÇA', 'OH! QUE SAUDOSA LEMBRANÇA\nTENHO DE TI, Ó SIÃO,\nTERRA QUE EU TANTO AMO\nPOIS ÉS DO MEU CORAÇÃO;\nEU PARA TI VOAREI\nQUANDO O SENHOR MEU VOLTAR\nPOIS ELE FOI PARA O CÉU\nE BREVE VEM ME BUSCAR.\n\nCORO\nSIM, EU PORFIAREI POR ESSA TERRA DE ALÉM\nE LÁ TERMINAREI AS MUITAS LUTAS DE AQUÉM;\nLÁ ESTÁ MEU BOM SENHOR, AO QUAL EU DESEJO VER,\nELE É TUDO PRA MIM,\nE SEM ELE EU NÃO POSSO VIVER.\n\nBELA, MUI BELA, É A ESPERANÇA\nDOS QUE VIGIAM POR TI,\nPOIS ELES RECEBEM FORÇAS\nQUE SÓ SE ENCONTRAM ALI;\nOS QUE PROCURAM CHEGAR\nAO TEU REGAÇO, Ó SIÃO,\nLIVRES SERÃO DE PECAR\nE DE TODA A TENTAÇÃO.\n\nCORO\nSIM, EU PORFIAREI POR ESSA TERRA DE ALÉM\nE LÁ TERMINAREI AS MUITAS LUTAS DE AQUÉM;\nLÁ ESTÁ MEU BOM SENHOR, AO QUAL EU DESEJO VER,\nELE É TUDO PRA MIM,\nE SEM ELE EU NÃO POSSO VIVER.\n\nDIZ A SAGRADA ESCRITURA\nQUE SÃO FORMOSOS OS PÉS\nDAQUELES QUE BOAS NOVAS\nLEVAM PARA OS INFIÉIS;\nE SE TÃO BELO É FALAR\nDESSAS GRANDEZAS AQUI,\nQUE NÃO SERÁ O GOZAR,\nA GRAÇA QUE EXISTE ALI?\n\nCORO\nSIM, EU PORFIAREI POR ESSA TERRA DE ALÉM\nE LÁ TERMINAREI AS MUITAS LUTAS DE AQUÉM;\nLÁ ESTÁ MEU BOM SENHOR, AO QUAL EU DESEJO VER,\nELE É TUDO PRA MIM,\nE SEM ELE EU NÃO POSSO VIVER.', 'OH! QUE SAUDOSA LEMBRANÇA\nTENHO DE TI, Ó SIÃO,\nTERRA QUE EU TANTO AMO\nPOIS ÉS DO MEU CORAÇÃO;\nEU PARA TI VOAREI\nQUANDO O SENHOR MEU VOLTAR\nPOIS ELE FOI PARA O CÉU\nE BREVE VEM ME BUSCAR.\n\n<coro>\nSIM, EU PORFIAREI POR ESSA TERRA DE ALÉM\nE LÁ TERMINAREI AS MUITAS LUTAS DE AQUÉM;\nLÁ ESTÁ MEU BOM SENHOR, AO QUAL EU DESEJO VER,\nELE É TUDO PRA MIM,\nE SEM ELE EU NÃO POSSO VIVER.\n\nBELA, MUI BELA, É A ESPERANÇA\nDOS QUE VIGIAM POR TI,\nPOIS ELES RECEBEM FORÇAS\nQUE SÓ SE ENCONTRAM ALI;\nOS QUE PROCURAM CHEGAR\nAO TEU REGAÇO, Ó SIÃO,\nLIVRES SERÃO DE PECAR\nE DE TODA A TENTAÇÃO.\n\n<coro>\nSIM, EU PORFIAREI POR ESSA TERRA DE ALÉM\nE LÁ TERMINAREI AS MUITAS LUTAS DE AQUÉM;\nLÁ ESTÁ MEU BOM SENHOR, AO QUAL EU DESEJO VER,\nELE É TUDO PRA MIM,\nE SEM ELE EU NÃO POSSO VIVER.\n\nDIZ A SAGRADA ESCRITURA\nQUE SÃO FORMOSOS OS PÉS\nDAQUELES QUE BOAS NOVAS\nLEVAM PARA OS INFIÉIS;\nE SE TÃO BELO É FALAR\nDESSAS GRANDEZAS AQUI,\nQUE NÃO SERÁ O GOZAR,\nA GRAÇA QUE EXISTE ALI?\n\n<coro>\nSIM, EU PORFIAREI POR ESSA TERRA DE ALÉM\nE LÁ TERMINAREI AS MUITAS LUTAS DE AQUÉM;\nLÁ ESTÁ MEU BOM SENHOR, AO QUAL EU DESEJO VER,\nELE É TUDO PRA MIM,\nE SEM ELE EU NÃO POSSO VIVER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (531, 'JERUSALÉM, JERUSALÉM', 'JERUSALÉM, JERUSALÉM', 'JERUSALÉM, JERUSALÉM,\nDO POVO SANTO DO SENHOR,\nCOM FÉ UM DIA LÁ ESTAREI\nRENDENDO GLÓRIA \nAO MEU SALVADOR.\n\nCORO\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nCOM OS ANJOS CANTAREI TODO O LOUVOR;\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nJERUSALÉM DO POVO DO SENHOR.\n\nJERUSALÉM, CIDADE SANTA,\nILUMINADA COM A GLÓRIA DE DEUS,\nEM SUAS RUAS EU ANDAREI \nCOM O CORDEIRO E OS REMIDOS SEUS.\n\nCORO\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nCOM OS ANJOS CANTAREI TODO O LOUVOR;\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nJERUSALÉM DO POVO DO SENHOR.', 'JERUSALÉM, JERUSALÉM,\nDO POVO SANTO DO SENHOR,\nCOM FÉ UM DIA LÁ ESTAREI\nRENDENDO GLÓRIA \nAO MEU SALVADOR.\n\n<coro>\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nCOM OS ANJOS CANTAREI TODO O LOUVOR;\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nJERUSALÉM DO POVO DO SENHOR.\n\nJERUSALÉM, CIDADE SANTA,\nILUMINADA COM A GLÓRIA DE DEUS,\nEM SUAS RUAS EU ANDAREI \nCOM O CORDEIRO E OS REMIDOS SEUS.\n\n<coro>\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nCOM OS ANJOS CANTAREI TODO O LOUVOR;\nALELUIA, GLÓRIA A DEUS, \nALELUIA, AMÉM, AMÉM, \nJERUSALÉM DO POVO DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (532, 'QUANDO O MUNDO AQUI DEIXAR', 'QUANDO O MUNDO AQUI DEIXAR', 'QUANDO O MUNDO AQUI DEIXAR\nTRISTEZAS NÃO TEREI, POIS COMO \nOS ANJOS SEREI, NÃO HÁ DOR, \nANGÚSTIAS NEM AFLIÇÕES, \nNOS BRAÇOS DO SALVADOR \nDESCANSAREI LÁ NO CÉU.\n\nCORO\nJERUSALÉM ANSEIO ENCONTRAR,\n(JERUSALÉM ANSEIO ENCONTRAR) \nRUAS DE OURO EM MEU NOVO LAR,\n(RUAS DE OURO EM MEU NOVO LAR) \nOH! QUE PRAZER, (OH! QUE PRAZER) \nVEREI MEU REI, (VEREI MEU REI) \nPRA SEMPRE ESTAR COM JESUS. \n\nRIO DE ÁGUA VIVA, CLARO COMO CRISTAL, \nNO LINDO CÉU GOZAREI,\nNÃO HÁ DOR, ANGÚSTIAS NEM AFLIÇÕES, \nNOS BRAÇOS DO SALVADOR \nDESCANSAREI LÁ NO CÉU.\n\nCORO (2X)\nJERUSALÉM ANSEIO ENCONTRAR,\n(JERUSALÉM ANSEIO ENCONTRAR) \nRUAS DE OURO EM MEU NOVO LAR,\n(RUAS DE OURO EM MEU NOVO LAR) \nOH! QUE PRAZER, (OH! QUE PRAZER) \nVEREI MEU REI, (VEREI MEU REI) \nPRA SEMPRE ESTAR COM JESUS\n\nPRA SEMPRE ESTAR COM JESUS (2X)', 'QUANDO O MUNDO AQUI DEIXAR\nTRISTEZAS NÃO TEREI, POIS COMO \nOS ANJOS SEREI, NÃO HÁ DOR, \nANGÚSTIAS NEM AFLIÇÕES, \nNOS BRAÇOS DO SALVADOR \nDESCANSAREI LÁ NO CÉU.\n\n<coro>\nJERUSALÉM ANSEIO ENCONTRAR,\n(JERUSALÉM ANSEIO ENCONTRAR) \nRUAS DE OURO EM MEU NOVO LAR,\n(RUAS DE OURO EM MEU NOVO LAR) \nOH! QUE PRAZER, (OH! QUE PRAZER) \nVEREI MEU REI, (VEREI MEU REI) \nPRA SEMPRE ESTAR COM JESUS. \n\nRIO DE ÁGUA VIVA, CLARO COMO CRISTAL, \nNO LINDO CÉU GOZAREI,\nNÃO HÁ DOR, ANGÚSTIAS NEM AFLIÇÕES, \nNOS BRAÇOS DO SALVADOR \nDESCANSAREI LÁ NO CÉU.\n\n<coro tipo=''2X''>\nJERUSALÉM ANSEIO ENCONTRAR,\n(JERUSALÉM ANSEIO ENCONTRAR) \nRUAS DE OURO EM MEU NOVO LAR,\n(RUAS DE OURO EM MEU NOVO LAR) \nOH! QUE PRAZER, (OH! QUE PRAZER) \nVEREI MEU REI, (VEREI MEU REI) \nPRA SEMPRE ESTAR COM JESUS\n\nPRA SEMPRE ESTAR COM JESUS <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (533, 'MINHA ALMA, POIS, ALEGRE CANTA', 'MINHA ALMA, POIS, ALEGRE CANTA', 'MINHA ALMA, POIS, \nALEGRE CANTA:\nVOU PRA JERUSALÉM;\nÉ UMA CIDADE SANTA, \nNOVA JERUSALÉM.\n\nCORO\nSE VOCÊ QUISER A VIDA\nE CAMINHAR TAMBÉM,\nSEGURA NA MÃO DE CRISTO \nE VAI PRA NOVA JERUSALÉM. \n\nINSTRUMENTOS\n\nLÁ NÃO HÁ PRANTO,\nTRISTEZAS E NEM DOR,\nSÓ HÁ A PAZ DE CRISTO,\nALEGRIA E MUITO AMOR.', 'MINHA ALMA, POIS, \nALEGRE CANTA:\nVOU PRA JERUSALÉM;\nÉ UMA CIDADE SANTA, \nNOVA JERUSALÉM.\n\n<coro>\nSE VOCÊ QUISER A VIDA\nE CAMINHAR TAMBÉM,\nSEGURA NA MÃO DE CRISTO <bis>\nE VAI PRA NOVA JERUSALÉM. <bis>\n<instrumentos>\nLÁ NÃO HÁ PRANTO,\nTRISTEZAS E NEM DOR,\nSÓ HÁ A PAZ DE CRISTO,\nALEGRIA E MUITO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (534, 'BREVE VOLTARÁ O MESSIAS', 'BREVE VOLTARÁ O MESSIAS', 'BREVE VOLTARÁ O MESSIAS, \nO UNGIDO DE DEUS, O REI, O SENHOR,\nO QUE É DIGNO DE TODO O LOUVOR.\n\nO SOL PERDERÁ O SEU BRILHO E A LUA \nNÃO DARÁ MAIS A SUA LUZ\nQUANDO O FILHO DO HOMEM VOLTAR.\n\nTODOS OS POVOS DA TERRA O VERÃO\nVINDO SOBRE AS NUVENS DO CÉU,\nCOM GLÓRIA, COM GLÓRIA,\nCOM GLÓRIA JESUS VOLTARÁ!', 'BREVE VOLTARÁ O MESSIAS, \nO UNGIDO DE DEUS, O REI, O SENHOR,\nO QUE É DIGNO DE TODO O LOUVOR.\n\nO SOL PERDERÁ O SEU BRILHO E A LUA \nNÃO DARÁ MAIS A SUA LUZ\nQUANDO O FILHO DO HOMEM VOLTAR.\n\nTODOS OS POVOS DA TERRA O VERÃO\nVINDO SOBRE AS NUVENS DO CÉU,\nCOM GLÓRIA, COM GLÓRIA,<bis>\nCOM GLÓRIA JESUS VOLTARÁ!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (535, 'ALÉM DO CÉU AZUL', 'ALÉM DO CÉU AZUL', 'ALÉM DO CÉU AZUL FOI JESUS PREPARAR \nUM LAR PRA DAR A QUEM \nA VITÓRIA ALCANÇAR;\nANELO CONSEGUIR A VIDA NO PORVIR, \nCOM FÉ NO MEU SENHOR JESUS.\n\nBEM SEI QUE EU, DE MIM,\nNADA TENHO PRA DAR,\nMAS SEI QUE MEU JESUS\nJÁ ME VEIO SALVAR;\nAGORA QUERO EU TER \nFÉ NO CORAÇÃO,\nATÉ SEU ROSTO VER ALÉM.', 'ALÉM DO CÉU AZUL FOI JESUS PREPARAR \nUM LAR PRA DAR A QUEM \nA VITÓRIA ALCANÇAR;\nANELO CONSEGUIR A VIDA NO PORVIR, \nCOM FÉ NO MEU SENHOR JESUS.\n\nBEM SEI QUE EU, DE MIM,\nNADA TENHO PRA DAR,\nMAS SEI QUE MEU JESUS\nJÁ ME VEIO SALVAR;\nAGORA QUERO EU TER \nFÉ NO CORAÇÃO,\nATÉ SEU ROSTO VER ALÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (536, 'FINDA A LIDA TERREAL', 'FINDA A LIDA TERREAL', 'FINDA A LIDA TERREAL, \nQUANDO JÁ DO RIO ALÉM, \nNESSA VIDA GLORIOSA ME ENCONTRAR;\nSEI QUE LÁ MEU REDENTOR SORRIDENTE \nHEI DE VER, ENTRE A TURBA, \nO PRIMEIRO A ME CHAMAR.\n\nCORO\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.\n\nOH! DA ALMA MEU ENLEVO É SEU ROSTO \nCONTEMPLAR NESSA AURORA DO DIA ETERNAL;\nCOMO ENTÃO MEU CORAÇÃO O NÃO \nHÁ DE ALI LOUVAR PELA GRAÇA E FAVOR CELESTIAL?\n\nCORO\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.\n\nNESSA PÁTRIA RESPLENDENTE HEI DE AMIGOS \nENCONTRAR, SIM, AMIGOS \nMAIS PREZADOS HEI DE TER;\nMAS PRIMEIRO QUE TUDO, \nQUANDO EU ALI CHEGAR, \nMEU JESUS É QUEM EU MAIS ANSEIO VER.\n\nCORO\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.\n\nPELAS PORTAS DA CIDADE, EM VESTES \nA ALVEJAR, ALI, ONDE NOITE E PRANTO NÃO ESTARÃO;\nENTRE CANTO ANGELICAL HÁ MEUS PASSOS DE GUIAR, \nPERTO, SIM, MUI PERTO O HEI DE VER, ENTÃO.\n\nCORO\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.', 'FINDA A LIDA TERREAL, \nQUANDO JÁ DO RIO ALÉM, \nNESSA VIDA GLORIOSA ME ENCONTRAR;\nSEI QUE LÁ MEU REDENTOR SORRIDENTE \nHEI DE VER, ENTRE A TURBA, \nO PRIMEIRO A ME CHAMAR.\n\n<coro>\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.\n\nOH! DA ALMA MEU ENLEVO É SEU ROSTO \nCONTEMPLAR NESSA AURORA DO DIA ETERNAL;\nCOMO ENTÃO MEU CORAÇÃO O NÃO \nHÁ DE ALI LOUVAR PELA GRAÇA E FAVOR CELESTIAL?\n\n<coro>\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.\n\nNESSA PÁTRIA RESPLENDENTE HEI DE AMIGOS \nENCONTRAR, SIM, AMIGOS \nMAIS PREZADOS HEI DE TER;\nMAS PRIMEIRO QUE TUDO, \nQUANDO EU ALI CHEGAR, \nMEU JESUS É QUEM EU MAIS ANSEIO VER.\n\n<coro>\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.\n\nPELAS PORTAS DA CIDADE, EM VESTES \nA ALVEJAR, ALI, ONDE NOITE E PRANTO NÃO ESTARÃO;\nENTRE CANTO ANGELICAL HÁ MEUS PASSOS DE GUIAR, \nPERTO, SIM, MUI PERTO O HEI DE VER, ENTÃO.\n\n<coro>\nHEI DE VER MEU REDENTOR,\nREDIMIDO AO SEU LADO HEI DE ESTAR;\nHEI DE VER MEU SALVADOR,\nEM GLORIOSA E SANTA LUZ CELESTIAL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (537, 'QUANDO O JORDÃO PASSARMOS UNIDOS', 'QUANDO O JORDÃO PASSARMOS UNIDOS', 'QUANDO O JORDÃO PASSARMOS UNIDOS\nE ENTRARMOS NO CÉU, VEREMOS LÁ,\nCOMO A AREIA DA PRAIA, OS REMIDOS,\nOH! QUE GLORIOSA VISTA SERÁ!\n\nCORO\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!\n\nQUANDO VIRMOS OS SALVOS DO MUNDO\nQUE A MORTE JAMAIS ALCANÇARÁ,\nSE SAUDAREM COM GOZO PROFUNDO,\nOH! QUE GLORIOSA VISTA SERÁ!\n\nCORO\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!\n\nLÁ NA MARGEM DO RIO DA VIDA\nONDE PAZ E JUSTIÇA HAVERÁ,\nNÓS VEREMOS A TERRA PROMETIDA,\nOH! QUE GLORIOSA VISTA SERÁ!\n\nCORO\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!\n\nQUANDO CRISTO JESUS CONTEMPLARMOS\nCOROADO NO CÉU, COMO ESTÁ, \nE PROSTRADOS AOS SEUS PÉS ADORARMOS\nOH! QUE GLORIOSA VISTA SERÁ!\n\nCORO\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!', 'QUANDO O JORDÃO PASSARMOS UNIDOS\nE ENTRARMOS NO CÉU, VEREMOS LÁ,\nCOMO A AREIA DA PRAIA, OS REMIDOS,\nOH! QUE GLORIOSA VISTA SERÁ!\n\n<coro>\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!\n\nQUANDO VIRMOS OS SALVOS DO MUNDO\nQUE A MORTE JAMAIS ALCANÇARÁ,\nSE SAUDAREM COM GOZO PROFUNDO,\nOH! QUE GLORIOSA VISTA SERÁ!\n\n<coro>\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!\n\nLÁ NA MARGEM DO RIO DA VIDA\nONDE PAZ E JUSTIÇA HAVERÁ,\nNÓS VEREMOS A TERRA PROMETIDA,\nOH! QUE GLORIOSA VISTA SERÁ!\n\n<coro>\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!\n\nQUANDO CRISTO JESUS CONTEMPLARMOS\nCOROADO NO CÉU, COMO ESTÁ, \nE PROSTRADOS AOS SEUS PÉS ADORARMOS\nOH! QUE GLORIOSA VISTA SERÁ!\n\n<coro>\nTANTOS COMO A AREIA DA PRAIA!\nTANTOS COMO A AREIA DO MAR!\nQUE GOZO SENTIRÁ TODO O SALVO, POIS VERÁ,\nSIM,TANTOS COMO A AREIA DA PRAIA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (538, 'HÁ UM LUGAR PRA MIM', 'HÁ UM LUGAR PRA MIM', 'HÁ UM LUGAR PRA MIM\nCHEIO DE AMOR,\nCOM O MEU JESUS MORAR,\nCOM OS ANJOS HABITAR.\n\nCORO\nLÁ NÃO TEREI MAIS DOR, (LÁ NÃO TEREI MAIS DOR) \nSÓ GOZO E ALEGRIA, (VEREI MEU SALVADOR) \nESPERO ANSIOSO (ESPERO ANSIOSO) \nPOR VER JESUS UM DIA.\n\nNESSE LUGAR PRA MIM,\nDE ETERNA REDENÇÃO,\nENCONTRO PAZ SEM FIM\nEM MEU CORAÇÃO.\n\nCORO (2X)\nLÁ NÃO TEREI MAIS DOR, (LÁ NÃO TEREI MAIS DOR) \nSÓ GOZO E ALEGRIA, (VEREI MEU SALVADOR) \nESPERO ANSIOSO (ESPERO ANSIOSO) \nPOR VER JESUS UM DIA.\n\nFINAL: \nESPERO ANSIOSO (ESPERO ANSIOSO) \nPOR VER JESUS UM DIA.', 'HÁ UM LUGAR PRA MIM\nCHEIO DE AMOR,\nCOM O MEU JESUS MORAR,\nCOM OS ANJOS HABITAR.\n\n<coro>\nLÁ NÃO TEREI MAIS DOR, (LÁ NÃO TEREI MAIS DOR) \nSÓ GOZO E ALEGRIA, (VEREI MEU SALVADOR) \nESPERO ANSIOSO (ESPERO ANSIOSO) \nPOR VER JESUS UM DIA.\n\nNESSE LUGAR PRA MIM,\nDE ETERNA REDENÇÃO,\nENCONTRO PAZ SEM FIM\nEM MEU CORAÇÃO.\n\n<coro tipo=''2X''>\nLÁ NÃO TEREI MAIS DOR, (LÁ NÃO TEREI MAIS DOR) \nSÓ GOZO E ALEGRIA, (VEREI MEU SALVADOR) \nESPERO ANSIOSO (ESPERO ANSIOSO) \nPOR VER JESUS UM DIA.\n<final>ESPERO ANSIOSO (ESPERO ANSIOSO) \nPOR VER JESUS UM DIA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (539, 'JUNTO AO TRONO DE DEUS, PREPARADO', 'JUNTO AO TRONO DE DEUS, PREPARADO', 'JUNTO AO TRONO DE DEUS PREPARADO\nHÁ, CRISTÃO, UM LUGAR PARA TI;\nHÁ ALEGRIAS, HÁ GOZO EXALTADO,\nHÁ DELÍCIAS PROFUSAS ALI;\nSIM, ALI, SIM, ALI, DE SEUS ANJOS FIÉIS RODEADO, \nNUMA ESFERA DE GLÓRIA E DE LUZ, \nJUNTO A DEUS NOS ESPERA JESUS.\n\nOS ENCANTOS DA TERRA NÃO PODEM\nDAR IDÉIA DO GOZO DALI,\nSE NA TERRA OS PRAZERES ACODEM,\nSÃO PRAZERES QUE FINDAM AQUI;\nMAS DALI, MAS DALI,\nAS VENTURAS ETERNAS CONCORREM\nCOM O BRILHO PERPÉTUO DA LUZ,\nA TORNAR-TE FELIZ COM JESUS.\n\nCONSERVEMOS EM NOSSA LEMBRANÇA\nAS RIQUEZAS DO LINDO PAÍS,\nE GUARDEMOS CONOSCO A ESPERANÇA\nDUMA VIDA MELHOR, MAIS FELIZ;\nPOIS DALI, POIS DALI,\nUMA VOZ VERDADEIRA NÃO CANSA\nDE FALAR-NOS DO REINO DA LUZ\nE DO AMOR PROTETOR DE JESUS.\n\nSE QUISERMOS GOZAR DA VENTURA\nQUE NO BELO PAÍS HAVERÁ,\nÉ SOMENTE PEDIR DE ALMA PURA\nE ESSA GRAÇA JESUS NOS DARÁ;\nPOIS DALI, POIS DALI,\nTODO CHEIO DE AMOR, DE TERNURA,\nDESSE AMOR QUE MOSTROU LÁ NA CRUZ, \nNOS ATENDE, NOS OUVE, JESUS.', 'JUNTO AO TRONO DE DEUS PREPARADO\nHÁ, CRISTÃO, UM LUGAR PARA TI;\nHÁ ALEGRIAS, HÁ GOZO EXALTADO,\nHÁ DELÍCIAS PROFUSAS ALI;\nSIM, ALI, SIM, ALI, DE SEUS ANJOS FIÉIS RODEADO, \nNUMA ESFERA DE GLÓRIA E DE LUZ, \nJUNTO A DEUS NOS ESPERA JESUS.\n\nOS ENCANTOS DA TERRA NÃO PODEM\nDAR IDÉIA DO GOZO DALI,\nSE NA TERRA OS PRAZERES ACODEM,\nSÃO PRAZERES QUE FINDAM AQUI;\nMAS DALI, MAS DALI,\nAS VENTURAS ETERNAS CONCORREM\nCOM O BRILHO PERPÉTUO DA LUZ,\nA TORNAR-TE FELIZ COM JESUS.\n\nCONSERVEMOS EM NOSSA LEMBRANÇA\nAS RIQUEZAS DO LINDO PAÍS,\nE GUARDEMOS CONOSCO A ESPERANÇA\nDUMA VIDA MELHOR, MAIS FELIZ;\nPOIS DALI, POIS DALI,\nUMA VOZ VERDADEIRA NÃO CANSA\nDE FALAR-NOS DO REINO DA LUZ\nE DO AMOR PROTETOR DE JESUS.\n\nSE QUISERMOS GOZAR DA VENTURA\nQUE NO BELO PAÍS HAVERÁ,\nÉ SOMENTE PEDIR DE ALMA PURA\nE ESSA GRAÇA JESUS NOS DARÁ;\nPOIS DALI, POIS DALI,\nTODO CHEIO DE AMOR, DE TERNURA,\nDESSE AMOR QUE MOSTROU LÁ NA CRUZ, \nNOS ATENDE, NOS OUVE, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (540, 'OH! PENSAI NESSE LAR LÁ DO CÉU', 'OH! PENSAI NESSE LAR LÁ DO CÉU', 'OH! PENSAI NESSE LAR LÁ DO CÉU,\nBEM AO LADO DO RIO DE LUZ,\nONDE OS SANTOS PRA SEMPRE JÁ GOZAM \nDA PRESENÇA DO NOSSO JESUS.\n\nCORO (2X)\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!\n\nOH! PENSAI NOS AMIGOS DO CÉU\nQUE A JORNADA JÁ TÊM ACABADO\nE NOS CANTOS QUE SOAM NOS ARES,\nNO PALÁCIO POR DEUS PREPARADO.\n\nCORO (2X)\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!\n \nHEI DE VER LÁ NO CÉU MEU JESUS,\nFACE A FACE SEU ROSTO MIRAR;\nLONGE, LONGE, CUIDADOS TRISTEZAS!\nCOM JESUS VOU PRA SEMPRE MORAR.\n\nCORO (2X)\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!\n\nCEDO, CEDO NO CÉU LÁ ESTAREI,\nVEJO O FIM DA JORNADA CHEGAR;\nMEU JESUS ALI ESTÁ ME ESPERANDO,\nÉ MELHOR ESTAR ALI QUE AQUI ESTAR.\n\nCORO (2X)\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!', 'OH! PENSAI NESSE LAR LÁ DO CÉU,\nBEM AO LADO DO RIO DE LUZ,\nONDE OS SANTOS PRA SEMPRE JÁ GOZAM \nDA PRESENÇA DO NOSSO JESUS.\n\n<coro tipo=''2X''>\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!\n\nOH! PENSAI NOS AMIGOS DO CÉU\nQUE A JORNADA JÁ TÊM ACABADO\nE NOS CANTOS QUE SOAM NOS ARES,\nNO PALÁCIO POR DEUS PREPARADO.\n\n<coro tipo=''2X''>\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!\n \nHEI DE VER LÁ NO CÉU MEU JESUS,\nFACE A FACE SEU ROSTO MIRAR;\nLONGE, LONGE, CUIDADOS TRISTEZAS!\nCOM JESUS VOU PRA SEMPRE MORAR.\n\n<coro tipo=''2X''>\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!\n\nCEDO, CEDO NO CÉU LÁ ESTAREI,\nVEJO O FIM DA JORNADA CHEGAR;\nMEU JESUS ALI ESTÁ ME ESPERANDO,\nÉ MELHOR ESTAR ALI QUE AQUI ESTAR.\n\n<coro tipo=''2X''>\nLÁ DO CÉU! LÁ DO CÉU!\nOH! PENSAI NESSE LAR LÁ DO CÉU!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (541, 'ARREBATADO FUI NO DIA DO SENHOR', 'ARREBATADO FUI NO DIA DO SENHOR', 'ARREBATADO FUI NO DIA DO SENHOR,\nOUVI UMA GRANDE VOZ, A VOZ DO MEU JESUS;\nE AOS SEUS PÉS CAÍ, AOS PÉS DO SALVADOR, \nAQUELE QUE POR MIM MORREU NA CRUZ.\n\nCORO\nE VI UM NOVO CÉU, UMA NOVA TERRA VI,\nUMA GRANDE VOZ NO CÉU SE FEZ ENTÃO OUVIR;\nNÃO HAVERÁ MAIS DOR, NEM PRANTO E NEM CLAMOR, \nSÓ HAVERÁ DE DEUS UM GRANDE AMOR.\n\nONIPOTENTE DEUS, A QUEM VENCER, \nDARÁ TUDO O QUE É SEU, NO CÉU,\nTUDO HERDARÁ DE DEUS;\n''SEREI TEU ETERNO PAI, SERÁS MEU FILHO, \nENTÃO, POIS QUEM VENCER \nALCANÇARÁ PERDÃO''.\n\nCORO\nE VI UM NOVO CÉU, UMA NOVA TERRA VI,\nUMA GRANDE VOZ NO CÉU SE FEZ ENTÃO OUVIR;\nNÃO HAVERÁ MAIS DOR, NEM PRANTO E NEM CLAMOR, \nSÓ HAVERÁ DE DEUS UM GRANDE AMOR.', 'ARREBATADO FUI NO DIA DO SENHOR,\nOUVI UMA GRANDE VOZ, A VOZ DO MEU JESUS;\nE AOS SEUS PÉS CAÍ, AOS PÉS DO SALVADOR, \nAQUELE QUE POR MIM MORREU NA CRUZ.\n\n<coro>\nE VI UM NOVO CÉU, UMA NOVA TERRA VI,\nUMA GRANDE VOZ NO CÉU SE FEZ ENTÃO OUVIR;\nNÃO HAVERÁ MAIS DOR, NEM PRANTO E NEM CLAMOR, \nSÓ HAVERÁ DE DEUS UM GRANDE AMOR.\n\nONIPOTENTE DEUS, A QUEM VENCER, \nDARÁ TUDO O QUE É SEU, NO CÉU,\nTUDO HERDARÁ DE DEUS;\n''SEREI TEU ETERNO PAI, SERÁS MEU FILHO, \nENTÃO, POIS QUEM VENCER \nALCANÇARÁ PERDÃO''.\n\n<coro>\nE VI UM NOVO CÉU, UMA NOVA TERRA VI,\nUMA GRANDE VOZ NO CÉU SE FEZ ENTÃO OUVIR;\nNÃO HAVERÁ MAIS DOR, NEM PRANTO E NEM CLAMOR, \nSÓ HAVERÁ DE DEUS UM GRANDE AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (542, 'AO LADO DE JESUS QUERO ESTAR', 'AO LADO DE JESUS QUERO ESTAR', 'AO LADO DE JESUS EU QUERO ESTAR\nE O SEU AMOR AO MUNDO ANUNCIAR;\nEM GRAÇA, ATINGIR A GLÓRIA DO PORVIR;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nCOROA MUI BRILHANTE EU HEI DE TER\nE A GLÓRIA DA CIDADE EU HEI DE VER,\nE LÁ HEI DE CANTAR UM HINO TRIUNFAL;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nCANSADO, MUITAS VEZES, DE LUTAR\nE DE UMA CRUZ PESADA CARREGAR,\nUM DIA A DEIXAREI, COROA GANHAREI;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nO ROSTO DE JESUS VOU CONTEMPLAR,\nPRA SEMPRE LÁ NO CÉU IREI MORAR,\nCOM ANJOS, QUERUBINS, TAMBÉM OS SERAFINS;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nCOM CRISTO EU ESTAREI LÁ NA MANSÃO,\nA ELE EU ENTREGUEI MEU CORAÇÃO,\nELE É MEU SALVADOR, O ETERNO REDENTOR;\nAO LADO DE JESUS EU QUERO ESTAR.', 'AO LADO DE JESUS EU QUERO ESTAR\nE O SEU AMOR AO MUNDO ANUNCIAR;\nEM GRAÇA, ATINGIR A GLÓRIA DO PORVIR;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nCOROA MUI BRILHANTE EU HEI DE TER\nE A GLÓRIA DA CIDADE EU HEI DE VER,\nE LÁ HEI DE CANTAR UM HINO TRIUNFAL;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nCANSADO, MUITAS VEZES, DE LUTAR\nE DE UMA CRUZ PESADA CARREGAR,\nUM DIA A DEIXAREI, COROA GANHAREI;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nO ROSTO DE JESUS VOU CONTEMPLAR,\nPRA SEMPRE LÁ NO CÉU IREI MORAR,\nCOM ANJOS, QUERUBINS, TAMBÉM OS SERAFINS;\nAO LADO DE JESUS EU QUERO ESTAR.\n\nCOM CRISTO EU ESTAREI LÁ NA MANSÃO,\nA ELE EU ENTREGUEI MEU CORAÇÃO,\nELE É MEU SALVADOR, O ETERNO REDENTOR;\nAO LADO DE JESUS EU QUERO ESTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (543, 'AO LADO DE DEUS', 'AO LADO DE DEUS', 'AO LADO DE DEUS QUERO ESTAR,\nNAS MANSÕES QUE ELE MESMO PREPAROU,\nVER, FACE A FACE, O MEU SENHOR JESUS, \nREI DOS REIS;\nNAS RUAS DE OURO SEI QUE ANDAREI,\nNO TOQUE DA TROMBETA SUBIREI.\n\nCORO (2X)\nOUVIREI (OUVIREI) \nJESUS CHAMAR (PELO MEU NOME) \nE COM OS ANJOS (CANTAREI) \nVIVA O REI (VIVA O REI)\nJESUS!\n\nINSTRUMENTOS\n\nNA ETERNIDADE EU VOU MORAR,\nPARA SEMPRE COM OS ANJOS VOU CANTAR;\nCOM QUERUBINS E SERAFINS A JESUS ADORAREI;\nNAS RUAS DE OURO SEI QUE ANDAREI,\nNO TOQUE DA TROMBETA SUBIREI.\n\nCORO (2X)\nOUVIREI (OUVIREI) \nJESUS CHAMAR (PELO MEU NOME) \nE COM OS ANJOS (CANTAREI) \nVIVA O REI (VIVA O REI)\nJESUS!\n\nINSTRUMENTOS\n\nFINAL:\nVIVA O REI JESUS!\n\nINSTRUMENTOS\n\nJESUS!', 'AO LADO DE DEUS QUERO ESTAR,\nNAS MANSÕES QUE ELE MESMO PREPAROU,\nVER, FACE A FACE, O MEU SENHOR JESUS, \nREI DOS REIS;\nNAS RUAS DE OURO SEI QUE ANDAREI,\nNO TOQUE DA TROMBETA SUBIREI.\n\n<coro tipo=''2X''>\nOUVIREI (OUVIREI) \nJESUS CHAMAR (PELO MEU NOME) \nE COM OS ANJOS (CANTAREI) \nVIVA O REI (VIVA O REI)\nJESUS!\n<instrumentos>\n\n\nNA ETERNIDADE EU VOU MORAR,\nPARA SEMPRE COM OS ANJOS VOU CANTAR;\nCOM QUERUBINS E SERAFINS A JESUS ADORAREI;\nNAS RUAS DE OURO SEI QUE ANDAREI,\nNO TOQUE DA TROMBETA SUBIREI.\n\n<coro tipo=''2X''>\nOUVIREI (OUVIREI) \nJESUS CHAMAR (PELO MEU NOME) \nE COM OS ANJOS (CANTAREI) \nVIVA O REI (VIVA O REI)\nJESUS!\n<instrumentos>\n\n\n\n<final>VIVA O REI JESUS!\n<instrumentos>\nJESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (544, 'EM BREVE O DIA CHEGARÁ', 'EM BREVE O DIA CHEGARÁ', 'EM BREVE O DIA CHEGARÁ,\nJESUS NAS NUVENS VIRÁ\nE NOS LEVARÁ PARA UM NOVO LAR, \nA NOVA JERUSALÉM.\n\nCORO\nE NOS MOSTRARÁ UM RIO DE ÁGUAS VIVAS \nQUE PROCEDE DO TRONO DO SENHOR \nE PARA SEMPRE LOUVAREMOS\nO CORDEIRO QUE VENCEU,\nO ALFA E O ÔMEGA, O NOSSO REI.\n\nINSTRUMENTOS\n\nTODA DOR CESSARÁ, O DIA E NOITE NÃO HAVERÁ \nPORQUE O SENHOR SERÁ A NOSSA LUZ \nE PARA SEMPRE REINAREMOS COM JESUS.\n\nCORO (2X)\nE NOS MOSTRARÁ UM RIO DE ÁGUAS VIVAS \nQUE PROCEDE DO TRONO DO SENHOR \nE PARA SEMPRE LOUVAREMOS\nO CORDEIRO QUE VENCEU,\nO ALFA E O ÔMEGA, O NOSSO REI.', 'EM BREVE O DIA CHEGARÁ,\nJESUS NAS NUVENS VIRÁ\nE NOS LEVARÁ PARA UM NOVO LAR, \nA NOVA JERUSALÉM.\n\n<coro>\nE NOS MOSTRARÁ UM RIO DE ÁGUAS VIVAS \nQUE PROCEDE DO TRONO DO SENHOR \nE PARA SEMPRE LOUVAREMOS\nO CORDEIRO QUE VENCEU,\nO ALFA E O ÔMEGA, O NOSSO REI.\n<instrumentos>\n\n\nTODA DOR CESSARÁ, O DIA E NOITE NÃO HAVERÁ \nPORQUE O SENHOR SERÁ A NOSSA LUZ \nE PARA SEMPRE REINAREMOS COM JESUS.\n\n<coro tipo=''2X''>\nE NOS MOSTRARÁ UM RIO DE ÁGUAS VIVAS \nQUE PROCEDE DO TRONO DO SENHOR \nE PARA SEMPRE LOUVAREMOS\nO CORDEIRO QUE VENCEU,\nO ALFA E O ÔMEGA, O NOSSO REI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (545, 'JESUS ESTÁ ÀS PORTAS', 'JESUS ESTÁ ÀS PORTAS', 'JESUS ESTÁ ÀS PORTAS,\nJESUS EM BREVE VEM\nNAS NUVENS COM OS ANJOS,\nEM GLÓRIA E ESPLENDOR.\n\nVEM (VEM), AMADO JESUS,\nTUA IGREJA ESPERA\nANSIOSA POR VER \nTUA FACE EM ESPLENDOR,\nESTAMOS A TE ESPERAR (JESUS)\n \nFINAL: \n(JESUS) ESTAMOS A TE ESPERAR. (BIS)', 'JESUS ESTÁ ÀS PORTAS,<bis>\nJESUS EM BREVE VEM<bis>\nNAS NUVENS COM OS ANJOS,<bis>\nEM GLÓRIA E ESPLENDOR.<bis>\n\nVEM (VEM), AMADO JESUS,<bis>\nTUA IGREJA ESPERA<bis>\nANSIOSA POR VER <bis>\nTUA FACE EM ESPLENDOR,<bis>\nESTAMOS A TE ESPERAR (JESUS)\n<final>(JESUS) ESTAMOS A TE ESPERAR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (546, 'OH! QUANTO ALMEJO ESTAR', 'OH! QUANTO ALMEJO ESTAR', 'OH! QUANTO ALMEJO ESTAR PERANTE A TUA FACE\nE CONTEMPLAR A TUA MAJESTADE;\nSEI QUE A VIDA AQUI LOGO VAI PASSAR\nE TODA LÁGRIMA DEUS ENXUGARÁ.\n\nCORO\nJERUSALÉM, CIDADE CELESTIAL (JERUSALÉM)\nOH! QUANTO ANSEIO ESTAR\nJUNTO AO MEU AMIGO E REI,\nQUE POR AMOR VERTEU SEU SANGUE\nPARA NOS SALVAR.\nMARANATA! (MARANATA)\nORA VEM, SENHOR JESUS!\n\nINSTRUMENTOS\n\nEM BREVE IREI MORAR NA BELA CIDADE, \nEM RUAS DE OURO SEI QUE VOU ANDAR;\nJERUSALÉM, ONDE CRISTO REINARÁ\nE PARA SEMPRE COM ELE IREI ESTAR.\n\nCORO\nJERUSALÉM, CIDADE CELESTIAL (JERUSALÉM)\nOH! QUANTO ANSEIO ESTAR JUNTO \nAO MEU AMIGO E REI, QUE POR AMOR \nVERTEU SEU SANGUE PARA NOS SALVAR.\nMARANATA! (MARANATA)\nORA VEM, SENHOR JESUS!\n\n\nFINAL: MARANATA! ORA VEM SENHOR JESUS!', 'OH! QUANTO ALMEJO ESTAR PERANTE A TUA FACE\nE CONTEMPLAR A TUA MAJESTADE;\nSEI QUE A VIDA AQUI LOGO VAI PASSAR\nE TODA LÁGRIMA DEUS ENXUGARÁ.\n\n<coro>\nJERUSALÉM, CIDADE CELESTIAL (JERUSALÉM)\nOH! QUANTO ANSEIO ESTAR\nJUNTO AO MEU AMIGO E REI,\nQUE POR AMOR VERTEU SEU SANGUE\nPARA NOS SALVAR.\nMARANATA! (MARANATA)\nORA VEM, SENHOR JESUS!\n<instrumentos>\n\n\nEM BREVE IREI MORAR NA BELA CIDADE, \nEM RUAS DE OURO SEI QUE VOU ANDAR;\nJERUSALÉM, ONDE CRISTO REINARÁ\nE PARA SEMPRE COM ELE IREI ESTAR.\n\n<coro>\nJERUSALÉM, CIDADE CELESTIAL (JERUSALÉM)\nOH! QUANTO ANSEIO ESTAR JUNTO \nAO MEU AMIGO E REI, QUE POR AMOR \nVERTEU SEU SANGUE PARA NOS SALVAR.\nMARANATA! (MARANATA)\nORA VEM, SENHOR JESUS!\n<final>MARANATA! ORA VEM SENHOR JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (547, 'Ó VEM LOGO, JESUS', 'Ó VEM LOGO, JESUS', 'Ó VEM LOGO, JESUS!\nÓ VEM LOGO, JESUS!\nA MINH''ALMA TE ESPERA,\nÓ VEM LOGO, JESUS!\n\nINSTRUMENTOS\n\nQUANTO ALMEJO TE VER, \nMEU AMADO JESUS, \nO TEU ROSTO TÃO LINDO\nBRILHANDO TUA LUZ. \nORA VEM (VEM) \nVEM (VEM), JESUS!\n\nINSTRUMENTOS\n\nA MINH''ALMA TE ESPERA, \nGLORIOSO JESUS, \nCOROADO DE GLÓRIA,\nBRILHANDO TUA LUZ. \nORA VEM (VEM) \nVEM (VEM), JESUS!\n\nINSTRUMENTOS\n\nÓ VEM LOGO, JESUS!\nÓ VEM LOGO, JESUS!\nA MINH''ALMA TE ESPERA,\nÓ VEM LOGO, JESUS!\n\nÓ VEM LOGO, JESUS!\nVEM, VEM, VEM!\nÓ VEM LOGO, JESUS!\nVEM, VEM, VEM!\nA MINH''ALMA TE ESPERA,\nVEM, VEM, VEM!\nÓ VEM LOGO, JESUS!\n\nFINAL: VEM JESUS!\n\n3X', 'Ó VEM LOGO, JESUS!\nÓ VEM LOGO, JESUS!\nA MINH''ALMA TE ESPERA,\nÓ VEM LOGO, JESUS!\n<instrumentos>\n\n\nQUANTO ALMEJO TE VER, \nMEU AMADO JESUS, \nO TEU ROSTO TÃO LINDO\nBRILHANDO TUA LUZ. \nORA VEM (VEM) \nVEM (VEM), JESUS!\n<instrumentos>\n\n\nA MINH''ALMA TE ESPERA, \nGLORIOSO JESUS, \nCOROADO DE GLÓRIA,\nBRILHANDO TUA LUZ. \nORA VEM (VEM) \nVEM (VEM), JESUS!\n<instrumentos>\n\n\nÓ VEM LOGO, JESUS!\nÓ VEM LOGO, JESUS!\nA MINH''ALMA TE ESPERA,\nÓ VEM LOGO, JESUS!\n\nÓ VEM LOGO, JESUS!\nVEM, VEM, VEM!\nÓ VEM LOGO, JESUS!\nVEM, VEM, VEM!\nA MINH''ALMA TE ESPERA,\nVEM, VEM, VEM!\nÓ VEM LOGO, JESUS!\n<final>VEM JESUS!\n\n<bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (548, 'NAS LINDAS MORADAS', 'NAS LINDAS MORADAS', 'NAS LINDAS MORADAS EM BREVE ESTAREI \nLOUVANDO PRA SEMPRE \nA JESUS, MEU GRANDE REI;\nNAS RUAS DE OURO SEI QUE VOU \nANDAR E JUNTO COM OS ANJOS LOUVAR.\n\nCORO\nA JESUS, O REI, \nO LEÃO DA TRIBO DE JUDÁ, \nQUE VENCEU E O LIVRO ABRIRÁ.\n\nO SEU ROSTO LINDO NO CÉU HEI DE VER, \nNO SEU MEIGO OLHAR SENTIREI QUANTO ME AMOU;\nSUAS MARAVILHAS IREI CONTEMPLAR\nE JUNTO COM OS ANJOS LOUVAR.\n\nCORO (2X)\nA JESUS, O REI, \nO LEÃO DA TRIBO DE JUDÁ, \nQUE VENCEU E O LIVRO ABRIRÁ.\n\nFINAL: \nE O LIVRO ABRIRÁ, \nE O LIVRO ABRIRÁ.', 'NAS LINDAS MORADAS EM BREVE ESTAREI \nLOUVANDO PRA SEMPRE \nA JESUS, MEU GRANDE REI;\nNAS RUAS DE OURO SEI QUE VOU \nANDAR E JUNTO COM OS ANJOS LOUVAR.\n\n<coro>\nA JESUS, O REI, \nO LEÃO DA TRIBO DE JUDÁ, \nQUE VENCEU E O LIVRO ABRIRÁ.\n\nO SEU ROSTO LINDO NO CÉU HEI DE VER, \nNO SEU MEIGO OLHAR SENTIREI QUANTO ME AMOU;\nSUAS MARAVILHAS IREI CONTEMPLAR\nE JUNTO COM OS ANJOS LOUVAR.\n\n<coro tipo=''2X''>\nA JESUS, O REI, \nO LEÃO DA TRIBO DE JUDÁ, \nQUE VENCEU E O LIVRO ABRIRÁ.\n<final>E O LIVRO ABRIRÁ, \nE O LIVRO ABRIRÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (549, 'MARAVILHOSO SERÁ', 'MARAVILHOSO SERÁ', 'MARAVILHOSO SERÁ \nQUANDO JESUS VOLTAR, \nMARAVILHOSO SERÁ.\n\nINSTRUMENTOS\n\nOH! QUE ALEGRIA SERÁ QUANDO JESUS VOLTAR, \nANJOS LOUVANDO SEU NOME,\nOS CÉUS SE ABRINDO EM ESPLENDOR.\n\nCORO (2X)\nMARAVILHOSO SERÁ \n(MARAVILHOSO)\nQUE DIA GLORIOSO SERÁ.\n\nTODA LUTA CESSARÁ, TODO PRANTO, \nTODA DOR, A IGREJA SUBIRÁ LOUVANDO \nAO SENHOR.\n\nCORO (2X)\nMARAVILHOSO SERÁ \n(MARAVILHOSO)\nQUE DIA GLORIOSO SERÁ.\n\nORA VEM, ORA VEM, SENHOR JESUS,\nTUA IGREJA TE ESPERA, TUA IGREJA PROCLAMA:\nMARANATA! ORA VEM, SENHOR JESUS.\n\nCORO (2X)\nMARAVILHOSO SERÁ \n(MARAVILHOSO)\nQUE DIA GLORIOSO SERÁ.\n\nFINAL: \nMARANATA! ORA VEM,\n(MARANATA! ORA VEM)\nMARANATA! ORA VEM,\n(MARANATA! ORA VEM)\nVEM, JESUS!', 'MARAVILHOSO SERÁ \nQUANDO JESUS VOLTAR, \nMARAVILHOSO SERÁ.\n<instrumentos>\n\n\nOH! QUE ALEGRIA SERÁ QUANDO JESUS VOLTAR, \nANJOS LOUVANDO SEU NOME,\nOS CÉUS SE ABRINDO EM ESPLENDOR.\n\n<coro tipo=''2X''>\nMARAVILHOSO SERÁ \n(MARAVILHOSO)\nQUE DIA GLORIOSO SERÁ.\n\nTODA LUTA CESSARÁ, TODO PRANTO, \nTODA DOR, A IGREJA SUBIRÁ LOUVANDO \nAO SENHOR.\n\n<coro tipo=''2X''>\nMARAVILHOSO SERÁ \n(MARAVILHOSO)\nQUE DIA GLORIOSO SERÁ.\n\nORA VEM, ORA VEM, SENHOR JESUS,\nTUA IGREJA TE ESPERA, TUA IGREJA PROCLAMA:\nMARANATA! ORA VEM, SENHOR JESUS.\n\n<coro tipo=''2X''>\nMARAVILHOSO SERÁ \n(MARAVILHOSO)\nQUE DIA GLORIOSO SERÁ.\n<final>MARANATA! ORA VEM,\n(MARANATA! ORA VEM)\nMARANATA! ORA VEM,\n(MARANATA! ORA VEM)\nVEM, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (550, 'CANTAI, Ó IGREJA', 'CANTAI, Ó IGREJA', 'CANTAI, Ó IGREJA \n(CANTAI, Ó IGREJA),\nO DIA CHEGARÁ, \nO NOIVO ENTRE AS NUVENS \nA TI RECEBERÁ.\n\nCORO (2X)\nALEGRAI-VOS, Ó FILHOS (ALEGRAI-VOS, IRMÃOS),\nALEGRAI-VOS, IRMÃOS, EM BREVE A IGREJA \nCANTARÁ EM SIÃO.\n\nMESMO EM LUTAS \n(MESMO EM LUTAS)\nQUE PROVAM NOSSO AMOR, \nA IGREJA, TRIUNFANTE, \nESPERA NO SENHOR.\n\nCORO (2X)\nALEGRAI-VOS, Ó FILHOS (ALEGRAI-VOS, IRMÃOS),\nALEGRAI-VOS, IRMÃOS, EM BREVE A IGREJA \nCANTARÁ EM SIÃO.\n\nFINAL: ALEGRAI-VOS.', 'CANTAI, Ó IGREJA \n(CANTAI, Ó IGREJA),\nO DIA CHEGARÁ, \nO NOIVO ENTRE AS NUVENS \nA TI RECEBERÁ.\n\n<coro tipo=''2X''>\nALEGRAI-VOS, Ó FILHOS (ALEGRAI-VOS, IRMÃOS),\nALEGRAI-VOS, IRMÃOS, EM BREVE A IGREJA \nCANTARÁ EM SIÃO.\n\nMESMO EM LUTAS \n(MESMO EM LUTAS)\nQUE PROVAM NOSSO AMOR, \nA IGREJA, TRIUNFANTE, \nESPERA NO SENHOR.\n\n<coro tipo=''2X''>\nALEGRAI-VOS, Ó FILHOS (ALEGRAI-VOS, IRMÃOS),\nALEGRAI-VOS, IRMÃOS, EM BREVE A IGREJA \nCANTARÁ EM SIÃO.\n<final>ALEGRAI-VOS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (551, 'TENHO LIDO DA BELA CIDADE (A BELA CIDADE)', 'TENHO LIDO DA BELA CIDADE (A BELA CIDADE)', 'TENHO LIDO DA BELA CIDADE,\nCONSTRUÍDA POR CRISTO NOS CÉUS;\nÉ MURADA DE JASPE LUZENTE\nE JUNCADA COM ÁUREOS TROFÉUS.\nE NO MEIO DA PRAÇA EIS O RIO\nDO VIGOR E DA VIDA ETERNAL;\nMAS METADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nCORO\nJAMAIS SE CONTOU AO MORTAL (BIS)\nMETADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nTENHO LIDO DAS BELAS MORADAS\nQUE JESUS FOI NO CÉU PREPARAR,\nONDE OS CRENTES FIÉIS PARA SEMPRE,\nMUI FELIZES, IRÃO HABITAR;\nNEM TRISTEZA, NEM DOR, NEM GEMIDOS\nENTRARÃO NA MANSÃO PATERNAL;\nMAS METADE DO GOZO CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nCORO\nJAMAIS SE CONTOU AO MORTAL (BIS)\nMETADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nTENHO LIDO DAS VESTES BRILHANTES,\nDAS COROAS QUE OS SANTOS TERÃO\nQUANDO O PAI OS CHAMAR E DISSER-LHES:\n''RECEBEI O ETERNAL GALARDÃO''.\nTENHO LIDO QUE OS SANTOS NA GLÓRIA\nPISARÃO RUAS DE OURO E CRISTAL;\nMAS METADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nCORO\nJAMAIS SE CONTOU AO MORTAL (BIS)\nMETADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.', 'TENHO LIDO DA BELA CIDADE,\nCONSTRUÍDA POR CRISTO NOS CÉUS;\nÉ MURADA DE JASPE LUZENTE\nE JUNCADA COM ÁUREOS TROFÉUS.\nE NO MEIO DA PRAÇA EIS O RIO\nDO VIGOR E DA VIDA ETERNAL;\nMAS METADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\n<coro>\nJAMAIS SE CONTOU AO MORTAL <bis>\nMETADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nTENHO LIDO DAS BELAS MORADAS\nQUE JESUS FOI NO CÉU PREPARAR,\nONDE OS CRENTES FIÉIS PARA SEMPRE,\nMUI FELIZES, IRÃO HABITAR;\nNEM TRISTEZA, NEM DOR, NEM GEMIDOS\nENTRARÃO NA MANSÃO PATERNAL;\nMAS METADE DO GOZO CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\n<coro>\nJAMAIS SE CONTOU AO MORTAL <bis>\nMETADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\nTENHO LIDO DAS VESTES BRILHANTES,\nDAS COROAS QUE OS SANTOS TERÃO\nQUANDO O PAI OS CHAMAR E DISSER-LHES:\n''RECEBEI O ETERNAL GALARDÃO''.\nTENHO LIDO QUE OS SANTOS NA GLÓRIA\nPISARÃO RUAS DE OURO E CRISTAL;\nMAS METADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.\n\n<coro>\nJAMAIS SE CONTOU AO MORTAL <bis>\nMETADE DA GLÓRIA CELESTE\nJAMAIS SE CONTOU AO MORTAL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (552, 'PÁTRIA MINHA', 'PÁTRIA MINHA', 'PÁTRIA MINHA, POR TI SUSPIRO \nQUANDO NO TEU BOM DESCANSO CHEGAREI?\nOS PATRIARCAS, DE DEUS AMIGOS,\nE OS BONS PROFETAS, FIÉIS, ANTIGOS,\nJÁ ENTRARAM NA TUA GLÓRIA,\nCONTEMPLANDO, EM ESPLENDOR, \nO GRANDE REI.\n\nOS REMIDOS, TÃO PERSEGUIDOS,\nPELO SANGUE JÁ VENCERAM O DRAGÃO;\nPOR JESUS CRISTO SÃO VENCEDORES,\nE AGORA CANTAM OS SEUS LOUVORES;\nPÁTRIA SANTA, DESEJO VER-TE,\nVER COM CRISTO A REDIMIDA MULTIDÃO.\n\nLÁ O RIO DAS ÁGUAS VIVAS \nSAI DO TRONO DO CORDEIRO E DO SENHOR;\nÉ LUMINOSO DESDE A NASCENTE,\nCOMO CRISTAL É RESPLANDECENTE;\nPELA MARGEM DAQUELE RIO ANDAM \nOS REMIDOS COM O SALVADOR.\n\nINSTRUMENTOS\n\nNÃO HÁ PRANTO NA MINHA PÁTRIA,\nNELA NUNCA SE DARÁ SEPARAÇÃO.\nALI O TRONO DE DEUS DESCANSA,\nALI TEREMOS REAL BONANÇA;\nOS REMIDOS DA MINHA PÁTRIA\nCOM JESUS ETERNAMENTE REINARÃO.', 'PÁTRIA MINHA, POR TI SUSPIRO \nQUANDO NO TEU BOM DESCANSO CHEGAREI?\nOS PATRIARCAS, DE DEUS AMIGOS,\nE OS BONS PROFETAS, FIÉIS, ANTIGOS,\nJÁ ENTRARAM NA TUA GLÓRIA,\nCONTEMPLANDO, EM ESPLENDOR, \nO GRANDE REI.\n\nOS REMIDOS, TÃO PERSEGUIDOS,\nPELO SANGUE JÁ VENCERAM O DRAGÃO;\nPOR JESUS CRISTO SÃO VENCEDORES,\nE AGORA CANTAM OS SEUS LOUVORES;\nPÁTRIA SANTA, DESEJO VER-TE,\nVER COM CRISTO A REDIMIDA MULTIDÃO.\n\nLÁ O RIO DAS ÁGUAS VIVAS \nSAI DO TRONO DO CORDEIRO E DO SENHOR;\nÉ LUMINOSO DESDE A NASCENTE,\nCOMO CRISTAL É RESPLANDECENTE;\nPELA MARGEM DAQUELE RIO ANDAM \nOS REMIDOS COM O SALVADOR.\n<instrumentos>\n\n\nNÃO HÁ PRANTO NA MINHA PÁTRIA,\nNELA NUNCA SE DARÁ SEPARAÇÃO.\nALI O TRONO DE DEUS DESCANSA,\nALI TEREMOS REAL BONANÇA;\nOS REMIDOS DA MINHA PÁTRIA\nCOM JESUS ETERNAMENTE REINARÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (553, 'VEM! MARANATA! JESUS VEM!', 'VEM! MARANATA! JESUS VEM!', 'VEM! MARANATA! JESUS VEM!\nESTE DIA CHEGARÁ, SUA IGREJA SUBIRÁ.\nVAMOS MORAR NA CIDADE ETERNAL,\nNA NOVA JERUSALÉM, \nONDE AS RUAS SÃO DE OURO.\n\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR A JESUS CRISTO.\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR (SÓ ELE É DIGNO)\nJUNTOS COM OS ANJOS NO CÉU.\n\nVEM! MARANATA! JESUS VEM!\nESTE DIA CHEGARÁ, SUA IGREJA SUBIRÁ.\nVAMOS MORAR NA CIDADE ETERNAL,\nNA NOVA JERUSALÉM, \nONDE AS RUAS SÃO DE OURO.\n\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR A JESUS CRISTO.\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR (SÓ ELE É DIGNO)\nJUNTOS COM OS ANJOS NO CÉU.\n\nFINAL: \nTODOS LOUVANDO A JESUS, \nNO CÉU, NO CÉU.', 'VEM! MARANATA! JESUS VEM!\nESTE DIA CHEGARÁ, SUA IGREJA SUBIRÁ.\nVAMOS MORAR NA CIDADE ETERNAL,\nNA NOVA JERUSALÉM, \nONDE AS RUAS SÃO DE OURO.\n\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR A JESUS CRISTO.\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR (SÓ ELE É DIGNO)\nJUNTOS COM OS ANJOS NO CÉU.\n\nVEM! MARANATA! JESUS VEM!\nESTE DIA CHEGARÁ, SUA IGREJA SUBIRÁ.\nVAMOS MORAR NA CIDADE ETERNAL,\nNA NOVA JERUSALÉM, \nONDE AS RUAS SÃO DE OURO.\n\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR A JESUS CRISTO.\nLÁ VAMOS CANTAR, \nVAMOS LOUVAR (SÓ ELE É DIGNO)\nJUNTOS COM OS ANJOS NO CÉU.\n<final>TODOS LOUVANDO A JESUS, \nNO CÉU, NO CÉU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (554, 'JERUSALÉM (SUAS RUAS DE OURO)', 'JERUSALÉM (SUAS RUAS DE OURO)', 'JERUSALÉM, JERUSALÉM, \nSUAS RUAS DE OURO, MEU GRANDE BEM.\nJERUSALÉM, JERUSALÉM,\nCIDADE TÃO LINDA, IGUAL NÃO TEM.\n\nINSTRUMENTOS\n\nDAS LINDAS MORADAS, Ó PÁTRIA QUERIDA, \nDO PERFUME DAS FLORES, \nESSÊNCIA DA VIDA, A MINH''ALMA ESPERA, \nESPERA POR TI, Ó JERUSALÉM!\n\nJERUSALÉM, JERUSALÉM, SUAS RUAS \nDE OURO, MEU GRANDE BEM;\nJERUSALÉM, JERUSALÉM,\nCIDADE TÃO LINDA, IGUAL NÃO TEM.\n\nINSTRUMENTOS\n\nDAS LINDAS MORADAS, Ó PÁTRIA QUERIDA, \nDO PERFUME DAS FLORES, \nESSÊNCIA DA VIDA, A MINH''ALMA ESPERA, \nESPERA POR TI, Ó JERUSALÉM!\n\nJERUSALÉM (JERUSALÉM)\nJERUSALÉM (JERUSALÉM)\nSUAS RUAS DE OURO, MEU GRANDE BEM;\nJERUSALÉM (JERUSALÉM)\nJERUSALÉM (JERUSALÉM)\nCIDADE TÃO LINDA, IGUAL NÃO TEM.', 'JERUSALÉM, JERUSALÉM, \nSUAS RUAS DE OURO, MEU GRANDE BEM.\nJERUSALÉM, JERUSALÉM,\nCIDADE TÃO LINDA, IGUAL NÃO TEM.\n<instrumentos>\n\n\nDAS LINDAS MORADAS, Ó PÁTRIA QUERIDA, \nDO PERFUME DAS FLORES, \nESSÊNCIA DA VIDA, A MINH''ALMA ESPERA, \nESPERA POR TI, Ó JERUSALÉM!\n\nJERUSALÉM, JERUSALÉM, SUAS RUAS \nDE OURO, MEU GRANDE BEM;\nJERUSALÉM, JERUSALÉM,\nCIDADE TÃO LINDA, IGUAL NÃO TEM.\n<instrumentos>\n\n\nDAS LINDAS MORADAS, Ó PÁTRIA QUERIDA, \nDO PERFUME DAS FLORES, \nESSÊNCIA DA VIDA, A MINH''ALMA ESPERA, \nESPERA POR TI, Ó JERUSALÉM!\n\nJERUSALÉM (JERUSALÉM)\nJERUSALÉM (JERUSALÉM)\nSUAS RUAS DE OURO, MEU GRANDE BEM;\nJERUSALÉM (JERUSALÉM)\nJERUSALÉM (JERUSALÉM)\nCIDADE TÃO LINDA, IGUAL NÃO TEM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (555, 'DA LINDA PÁTRIA', 'DA LINDA PÁTRIA', 'DA LINDA PÁTRIA ESTOU MUI LONGE,\nTRISTE EU ESTOU;\nEU TENHO DE JESUS SAUDADE;\nQUANDO SERÁ QUE VOU?\nPASSARINHOS, BELAS FLORES,\nQUEREM ME ENCANTAR,\nOH! VÃOS TERRESTRES ESPLENDORES,\nNÃO QUERO AQUI FICAR!\n\nJESUS ME DEU FIEL PROMESSA,\nVEM ME BUSCAR;\nMEU CORAÇÃO ESTÁ COM PRESSA,\nEU QUERO AO CÉU VOAR.\nMEUS PECADOS SÃO MUI GRANDES\nE CULPADO SOU;\nMAS O SEU SANGUE PÕE-ME LIMPO\nE PARA A PÁTRIA VOU.\n\nQUAL FILHO DO SEU LAR SAUDOSO,\nEU QUERO IR;\nQUAL PASSARINHO PARA O NINHO,\nEU QUERO AO CÉU SUBIR.\nSUA VINDA AO MUNDO É CERTA,\nQUANDO NÃO O SEI,\nMAS ELE ME ACHARÁ ALERTA\nE PARA O CÉU IREI.', 'DA LINDA PÁTRIA ESTOU MUI LONGE,\nTRISTE EU ESTOU;\nEU TENHO DE JESUS SAUDADE;\nQUANDO SERÁ QUE VOU?\nPASSARINHOS, BELAS FLORES,\nQUEREM ME ENCANTAR,\nOH! VÃOS TERRESTRES ESPLENDORES,\nNÃO QUERO AQUI FICAR!\n\nJESUS ME DEU FIEL PROMESSA,\nVEM ME BUSCAR;\nMEU CORAÇÃO ESTÁ COM PRESSA,\nEU QUERO AO CÉU VOAR.\nMEUS PECADOS SÃO MUI GRANDES\nE CULPADO SOU;\nMAS O SEU SANGUE PÕE-ME LIMPO\nE PARA A PÁTRIA VOU.\n\nQUAL FILHO DO SEU LAR SAUDOSO,\nEU QUERO IR;\nQUAL PASSARINHO PARA O NINHO,\nEU QUERO AO CÉU SUBIR.\nSUA VINDA AO MUNDO É CERTA,\nQUANDO NÃO O SEI,\nMAS ELE ME ACHARÁ ALERTA\nE PARA O CÉU IREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (556, 'NA NOVA JERUSALÉM IREI MORAR', 'NA NOVA JERUSALÉM IREI MORAR', 'NA NOVA JERUSALÉM IREI MORAR,\nONDE MORA O MEU JESUS, LÁ ESTAREI,\nNA CIDADE ETERNAL IREI GOZAR,\nNAS RUAS DE OURO SEI QUE ANDAREI.\n\nCORO\nLÁ CANTAREI LOUVORES A JESUS,\nLÁ LOUVAREI COM OS ANJOS AO MEU REI\nNA CIDADE DE LUZ EM BREVE ESTAREI.\n\nINSTRUMENTOS\n\nAQUI NÃO FICAREI, NÃO É MEU LUGAR,\nPRA SEMPRE COM JESUS IREI MORAR, \nCOM OS ANJOS, QUERUBINS, \nTAMBÉM SERAFINS A FACE DE JESUS \nVOU CONTEMPLAR.\n\nCORO (2X)\nLÁ CANTAREI LOUVORES A JESUS,\nLÁ LOUVAREI COM OS ANJOS AO MEU REI,\nNA CIDADE DE LUZ EM BREVE ESTAREI.\n\nFINAL: \nNA CIDADE DE LUZ EM BREVE ESTAREI.', 'NA NOVA JERUSALÉM IREI MORAR,\nONDE MORA O MEU JESUS, LÁ ESTAREI,\nNA CIDADE ETERNAL IREI GOZAR,\nNAS RUAS DE OURO SEI QUE ANDAREI.\n\n<coro>\nLÁ CANTAREI LOUVORES A JESUS,\nLÁ LOUVAREI COM OS ANJOS AO MEU REI\nNA CIDADE DE LUZ EM BREVE ESTAREI.\n<instrumentos>\n\n\nAQUI NÃO FICAREI, NÃO É MEU LUGAR,\nPRA SEMPRE COM JESUS IREI MORAR, \nCOM OS ANJOS, QUERUBINS, \nTAMBÉM SERAFINS A FACE DE JESUS \nVOU CONTEMPLAR.\n\n<coro tipo=''2X''>\nLÁ CANTAREI LOUVORES A JESUS,\nLÁ LOUVAREI COM OS ANJOS AO MEU REI,\nNA CIDADE DE LUZ EM BREVE ESTAREI.\n<final>NA CIDADE DE LUZ EM BREVE ESTAREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (557, 'ESTE MUNDO JAMAIS PODE ME SEPARAR', 'ESTE MUNDO JAMAIS PODE ME SEPARAR', 'ESTE MUNDO JAMAIS\nPODE ME SEPARAR\nDOS VALORES CELESTIAIS\nQUE EU VOU RECEBER;\nMEU TESOURO E ESPERANÇA\nESTÃO NO MEU NOVO LAR,\nSOU HERDEIRO COM CRISTO,\nVOU COM ELE MORAR.\n\nCORO\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nHÁ MANSÕES CELESTIAIS,\nTODAS FEITAS POR DEUS!\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nEU VOU PRO CÉU, LINDO CÉU,\nCOM CRISTO VOU MORAR \nNO LINDO CÉU!\n\nJÁ ESTANDO ALÉM RIO,\nMINHA LUTA FINDOU,\nEU NÃO TEMO MAIS PECADO\nPOIS JESUS ME LAVOU;\nOH! QUE GLÓRIA NA SUBIDA\nPRAS ALTURAS DOS CÉUS,\nCANTAREI A LINDA HISTÓRIA\nDO CORDEIRO DE DEUS!\n\nCORO\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nHÁ MANSÕES CELESTIAIS,\nTODAS FEITAS POR DEUS!\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nEU VOU PRO CÉU, LINDO CÉU,\nCOM CRISTO VOU MORAR \nNO LINDO CÉU!', 'ESTE MUNDO JAMAIS\nPODE ME SEPARAR\nDOS VALORES CELESTIAIS\nQUE EU VOU RECEBER;\nMEU TESOURO E ESPERANÇA\nESTÃO NO MEU NOVO LAR,\nSOU HERDEIRO COM CRISTO,\nVOU COM ELE MORAR.\n\n<coro>\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nHÁ MANSÕES CELESTIAIS,\nTODAS FEITAS POR DEUS!\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nEU VOU PRO CÉU, LINDO CÉU,\nCOM CRISTO VOU MORAR \nNO LINDO CÉU!\n\nJÁ ESTANDO ALÉM RIO,\nMINHA LUTA FINDOU,\nEU NÃO TEMO MAIS PECADO\nPOIS JESUS ME LAVOU;\nOH! QUE GLÓRIA NA SUBIDA\nPRAS ALTURAS DOS CÉUS,\nCANTAREI A LINDA HISTÓRIA\nDO CORDEIRO DE DEUS!\n\n<coro>\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nHÁ MANSÕES CELESTIAIS,\nTODAS FEITAS POR DEUS!\nCÉU, LINDO CÉU! CÉU, LINDO CÉU!\nEU VOU PRO CÉU, LINDO CÉU,\nCOM CRISTO VOU MORAR \nNO LINDO CÉU!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (558, 'VEM, JESUS CRISTO JÁ VEM', 'VEM, JESUS CRISTO JÁ VEM', 'VEM, JESUS CRISTO JÁ VEM, \nEM BREVE ELE VEM, VEM NOS BUSCAR,\nQUE DIA GLORIOSO SERÁ\nQUANDO OS SALVOS SUBIREM\nPRA COM ELE ESTAR.\n\nEM BREVE JESUS CRISTO VEM,\nIREMOS COM ELE SUBIR, \nVEREMOS NOSSO SENHOR.\n\nVARÕES\n\nEM BREVE JESUS CRISTO VEM, (DE GLÓRIA)\nIREMOS COM ELE SUBIR, (EM GLÓRIA)\nVEREMOS NOSSO REDENTOR.\n\nINSTRUMENTOS\n\nVEM, JESUS CRISTO JÁ VEM, \nEM BREVE ELE VEM, VEM NOS BUSCAR,\nQUE DIA GLORIOSO SERÁ\nQUANDO OS SALVOS SUBIREM\nPRA COM ELE ESTAR.\n\nEM BREVE JESUS CRISTO VEM,\nIREMOS COM ELE SUBIR, \nVEREMOS NOSSO SENHOR.\n\nVARÕES\n\nEM BREVE JESUS CRISTO VEM, (DE GLÓRIA)\nIREMOS COM ELE SUBIR, (EM GLÓRIA)\nVEREMOS NOSSO REDENTOR.\n\nINSTRUMENTOS\n\nVEM, \n(SIM, JESUS VEM)\nVEM, \n(SIM, JESUS VEM)\nVEM, SIM, JESUS VEM.', 'VEM, JESUS CRISTO JÁ VEM, \nEM BREVE ELE VEM, VEM NOS BUSCAR,\nQUE DIA GLORIOSO SERÁ\nQUANDO OS SALVOS SUBIREM\nPRA COM ELE ESTAR.\n\nEM BREVE JESUS CRISTO VEM,\nIREMOS COM ELE SUBIR, \nVEREMOS NOSSO SENHOR.\n\n<h>\n\n\nEM BREVE JESUS CRISTO VEM, (DE GLÓRIA)\nIREMOS COM ELE SUBIR, (EM GLÓRIA)\nVEREMOS NOSSO REDENTOR.\n<instrumentos>\n\n\nVEM, JESUS CRISTO JÁ VEM, \nEM BREVE ELE VEM, VEM NOS BUSCAR,\nQUE DIA GLORIOSO SERÁ\nQUANDO OS SALVOS SUBIREM\nPRA COM ELE ESTAR.\n\nEM BREVE JESUS CRISTO VEM,\nIREMOS COM ELE SUBIR, \nVEREMOS NOSSO SENHOR.\n\n<h>\n\n\nEM BREVE JESUS CRISTO VEM, (DE GLÓRIA)\nIREMOS COM ELE SUBIR, (EM GLÓRIA)\nVEREMOS NOSSO REDENTOR.\n<instrumentos>\n\n\nVEM, \n(SIM, JESUS VEM)\nVEM, \n(SIM, JESUS VEM)\nVEM, SIM, JESUS VEM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (559, 'A ÚLTIMA TROMBETA SOARÁ', 'A ÚLTIMA TROMBETA SOARÁ', 'A ÚLTIMA TROMBETA SOARÁ,\nJESUS ENTÃO VIRÁ;\nQUÃO TERRÍVEL DIA SERÁ,\nMAS ASSIM APROUVE A DEUS REALIZAR.\n\nAMADOS, PREPARAI VOSSOS CAMINHOS,\nCONVERTEI-VOS A DEUS, \nO ÚNICO SALVADOR E DOMINADOR, \nPARA QUE NÃO SOFRAIS \nNO GRANDE DIA DO SENHOR\n\nCORO\nOUVI, Ó CÉUS,\nOUVI, Ó MORADORES DA TERRA\nO QUE O ESPÍRITO SANTO DIZ:\n''JESUS, O DESEJADO DAS NAÇÕES\nVEM BUSCAR SUA IGREJA FIEL''.\n\nINSTRUMENTOS\n\n''EU, JESUS, ENVIEI O MEU ANJO \nPARA VOS TESTIFICAR ESTAS COISAS NAS IGREJAS,\nEU SOU A RAIZ E A GERAÇÃO DE DAVI,\nA RESPLANDECENTE ESTRELA DA MANHÃ''.\n\nO ESPÍRITO E A ESPOSA DIZEM: VEM!\nE QUEM OUVE DIGA: VEM!\nQUEM TEM SEDE VENHA E QUEM QUISER\nBEBA DE GRAÇA DA ÁGUA DA VIDA.\n\nCORO (2X)\nOUVI, Ó CÉUS,\nOUVI, Ó MORADORES DA TERRA\nO QUE O ESPÍRITO SANTO DIZ:\n''JESUS, O DESEJADO DAS NAÇÕES\nVEM BUSCAR SUA IGREJA FIEL''.\n\nFINAL: \nVEM BUSCAR SUA IGREJA FIEL.', 'A ÚLTIMA TROMBETA SOARÁ,\nJESUS ENTÃO VIRÁ;\nQUÃO TERRÍVEL DIA SERÁ,\nMAS ASSIM APROUVE A DEUS REALIZAR.\n\nAMADOS, PREPARAI VOSSOS CAMINHOS,\nCONVERTEI-VOS A DEUS, \nO ÚNICO SALVADOR E DOMINADOR, \nPARA QUE NÃO SOFRAIS \nNO GRANDE DIA DO SENHOR\n\n<coro>\nOUVI, Ó CÉUS,\nOUVI, Ó MORADORES DA TERRA\nO QUE O ESPÍRITO SANTO DIZ:\n''JESUS, O DESEJADO DAS NAÇÕES\nVEM BUSCAR SUA IGREJA FIEL''.\n<instrumentos>\n\n\n''EU, JESUS, ENVIEI O MEU ANJO \nPARA VOS TESTIFICAR ESTAS COISAS NAS IGREJAS,\nEU SOU A RAIZ E A GERAÇÃO DE DAVI,\nA RESPLANDECENTE ESTRELA DA MANHÃ''.\n\nO ESPÍRITO E A ESPOSA DIZEM: VEM!\nE QUEM OUVE DIGA: VEM!\nQUEM TEM SEDE VENHA E QUEM QUISER\nBEBA DE GRAÇA DA ÁGUA DA VIDA.\n\n<coro tipo=''2X''>\nOUVI, Ó CÉUS,\nOUVI, Ó MORADORES DA TERRA\nO QUE O ESPÍRITO SANTO DIZ:\n''JESUS, O DESEJADO DAS NAÇÕES\nVEM BUSCAR SUA IGREJA FIEL''.\n<final>VEM BUSCAR SUA IGREJA FIEL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (560, 'EIS QUE ESTOU A PORTA E BATO', 'EIS QUE ESTOU A PORTA E BATO', '''EIS QUE ESTOU À PORTA E BATO,\nSE ABRIRES, ENTRAREI E CONTIGO VIVEREI,\nABRE A PORTA DO TEU CORAÇÃO.\n\nO MEU NOME É JESUS,\nO AUTOR DA PRÓPRIA VIDA,\nSOU O TEU LIBERTADOR,\nO CORDEIRO QUE RESSUSCITOU.\n\nEIS QUE VENHO SOBRE AS NUVENS,\nEIS QUE VENHO VENCEDOR,\nNADA MAIS ME DETERÁ,\nO MEU POVO VOU ARREBATAR,\nA TROMBETA BREVE SOARÁ;\nTUDO NOVO SE FARÁ\nNO MEU REINO DE JUSTIÇA E PAZ''.\nMARANATA, JESUS VEM!\n\nINSTRUMENTOS\n\n''ESTE DIA ESTÁ CHEGANDO,\nA FIGUEIRA JÁ BROTOU E A IGREJA FIEL\nORA E VIGIA SEM CESSAR.\n\nO MEU NOME É JESUS,\nSOU A FONTE DE ÁGUA VIVA,\nQUEM TEM SEDE VEM A MIM,\nVEM BEBER DE GRAÇA DESTA ÁGUA.\n\nEIS QUE VENHO SOBRE AS NUVENS,\nEIS QUE VENHO VENCEDOR,\nNADA MAIS ME DETERÁ,\nO MEU POVO VOU ARREBATAR,\nA TROMBETA BREVE SOARÁ;\nTUDO NOVO SE FARÁ\nNO MEU REINO DE JUSTIÇA E PAZ''.\nMARANATA, JESUS VEM!\n\nFINAL: \n(MARANATA, JESUS)\nMARANATA, JESUS VEM!', '''EIS QUE ESTOU À PORTA E BATO,\nSE ABRIRES, ENTRAREI E CONTIGO VIVEREI,\nABRE A PORTA DO TEU CORAÇÃO.\n\nO MEU NOME É JESUS,\nO AUTOR DA PRÓPRIA VIDA,\nSOU O TEU LIBERTADOR,\nO CORDEIRO QUE RESSUSCITOU.\n\nEIS QUE VENHO SOBRE AS NUVENS,\nEIS QUE VENHO VENCEDOR,\nNADA MAIS ME DETERÁ,\nO MEU POVO VOU ARREBATAR,\nA TROMBETA BREVE SOARÁ;\nTUDO NOVO SE FARÁ\nNO MEU REINO DE JUSTIÇA E PAZ''.\nMARANATA, JESUS VEM!\n<instrumentos>\n\n\n''ESTE DIA ESTÁ CHEGANDO,\nA FIGUEIRA JÁ BROTOU E A IGREJA FIEL\nORA E VIGIA SEM CESSAR.\n\nO MEU NOME É JESUS,\nSOU A FONTE DE ÁGUA VIVA,\nQUEM TEM SEDE VEM A MIM,\nVEM BEBER DE GRAÇA DESTA ÁGUA.\n\nEIS QUE VENHO SOBRE AS NUVENS,\nEIS QUE VENHO VENCEDOR,\nNADA MAIS ME DETERÁ,<bis>\nO MEU POVO VOU ARREBATAR,<bis>\nA TROMBETA BREVE SOARÁ;<bis>\nTUDO NOVO SE FARÁ<bis>\nNO MEU REINO DE JUSTIÇA E PAZ''.<bis>\nMARANATA, JESUS VEM!<bis>\n\n\n<final>(MARANATA, JESUS)\nMARANATA, JESUS VEM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (561, 'OUVI COMO QUE A VOZ DE UMA GRANDE MULTIDÃO', 'OUVI COMO QUE A VOZ DE UMA GRANDE MULTIDÃO', 'OUVI COMO QUE A VOZ \nDE UMA GRANDE MULTIDÃO, \nCOMO VOZ DE MUITAS ÁGUAS, \nCOMO VOZ DE GRANDES TROVÕES;\nQUE DIZIA: ALELUIA!\nO SENHOR TODO PODEROSO \nREINA, REINA, REINA!\n\nREGOZIJEMO-NOS, ALEGREMO-NOS,\nDEMOS-LHE GLÓRIA!\nPORQUE VINDAS SÃO AS BODAS \nDO CORDEIRO E SUA ESPOSA SE PREPAROU.\n\nINSTRUMENTOS\n\nOUVI COMO QUE A VOZ \nDE UMA GRANDE MULTIDÃO, \nCOMO VOZ DE MUITAS ÁGUAS,\nCOMO VOZ DE GRANDES TROVÕES;\nQUE DIZIA: ALELUIA!\nO SENHOR TODO PODEROSO \nREINA, REINA, REINA!\n\nFINAL: AMÉM.', 'OUVI COMO QUE A VOZ \nDE UMA GRANDE MULTIDÃO, \nCOMO VOZ DE MUITAS ÁGUAS, \nCOMO VOZ DE GRANDES TROVÕES;\nQUE DIZIA: ALELUIA!\nO SENHOR TODO PODEROSO \nREINA, REINA, REINA!\n\nREGOZIJEMO-NOS, ALEGREMO-NOS,\nDEMOS-LHE GLÓRIA!\nPORQUE VINDAS SÃO AS BODAS \nDO CORDEIRO E SUA ESPOSA SE PREPAROU.\n<instrumentos>\n\n\nOUVI COMO QUE A VOZ \nDE UMA GRANDE MULTIDÃO, \nCOMO VOZ DE MUITAS ÁGUAS,\nCOMO VOZ DE GRANDES TROVÕES;\nQUE DIZIA: ALELUIA!\nO SENHOR TODO PODEROSO \nREINA, REINA, REINA!\n<final>AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (562, 'QUANDO MEU TEMPO DE LUTA PASSAR', 'QUANDO MEU TEMPO DE LUTA PASSAR', 'QUANDO MEU TEMPO DE LUTA PASSAR,\nQUANDO MEU DEUS PARA SI ME CHAMAR,\nGRATO, PERANTE JESUS HEI DE ESTAR;\nGLÓRIA PERENE SERÁ PARA MIM!\n\nCORO\nSIM, HÁ DE SER GLÓRIA PRA MIM,\nGLÓRIA PRA MIM, GLÓRIA PRA MIM;\nQUANDO PUDER O SEU ROSTO MIRAR,\nOH! HÁ DE SER GRANDE GLÓRIA PRA MIM!\n\nQUANDO POR GRAÇA DO SEU GRANDE AMOR \nEU ALCANÇAR O INFINITO FAVOR,\nDE IR PARA PERTO DO MEU SALVADOR,\nGLÓRIA PERENE SERÁ PARA MIM!\n\nCORO\nSIM, HÁ DE SER GLÓRIA PRA MIM,\nGLÓRIA PRA MIM, GLÓRIA PRA MIM;\nQUANDO PUDER O SEU ROSTO MIRAR,\nOH! HÁ DE SER GRANDE GLÓRIA PRA MIM!\n\nMUITOS AMIGOS ALI HEI DE ACHAR,\nPAZ, A ALEGRIA ETERNAL, BEM ESTAR;\nMAS QUANDO MEU SALVADOR ME SAUDAR, \nGLÓRIA PERENE SERÁ PARA MIM!\n\nCORO\nSIM, HÁ DE SER GLÓRIA PRA MIM,\nGLÓRIA PRA MIM, GLÓRIA PRA MIM;\nQUANDO PUDER O SEU ROSTO MIRAR,\nOH! HÁ DE SER GRANDE GLÓRIA PRA MIM!', 'QUANDO MEU TEMPO DE LUTA PASSAR,\nQUANDO MEU DEUS PARA SI ME CHAMAR,\nGRATO, PERANTE JESUS HEI DE ESTAR;\nGLÓRIA PERENE SERÁ PARA MIM!\n\n<coro>\nSIM, HÁ DE SER GLÓRIA PRA MIM,\nGLÓRIA PRA MIM, GLÓRIA PRA MIM;\nQUANDO PUDER O SEU ROSTO MIRAR,\nOH! HÁ DE SER GRANDE GLÓRIA PRA MIM!\n\nQUANDO POR GRAÇA DO SEU GRANDE AMOR \nEU ALCANÇAR O INFINITO FAVOR,\nDE IR PARA PERTO DO MEU SALVADOR,\nGLÓRIA PERENE SERÁ PARA MIM!\n\n<coro>\nSIM, HÁ DE SER GLÓRIA PRA MIM,\nGLÓRIA PRA MIM, GLÓRIA PRA MIM;\nQUANDO PUDER O SEU ROSTO MIRAR,\nOH! HÁ DE SER GRANDE GLÓRIA PRA MIM!\n\nMUITOS AMIGOS ALI HEI DE ACHAR,\nPAZ, A ALEGRIA ETERNAL, BEM ESTAR;\nMAS QUANDO MEU SALVADOR ME SAUDAR, \nGLÓRIA PERENE SERÁ PARA MIM!\n\n<coro>\nSIM, HÁ DE SER GLÓRIA PRA MIM,\nGLÓRIA PRA MIM, GLÓRIA PRA MIM;\nQUANDO PUDER O SEU ROSTO MIRAR,\nOH! HÁ DE SER GRANDE GLÓRIA PRA MIM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (563, 'NÃO SE TURBEM OS VOSSOS CORAÇÕES', 'NÃO SE TURBEM OS VOSSOS CORAÇÕES', 'NÃO SE TURBEM OS VOSSOS CORAÇÕES,\nBREVE SE CUMPRIRÁ A PROMESSA DE JESUS;\nTODO PRANTO CESSARÁ E OS SANTOS SUBIRÃO \nLEVADOS PELOS ANJOS AO SENHOR.\n\nCORO\nERGUEI VOSSAS CABEÇAS E CONTEMPLAI\nOS ANJOS LOUVANDO A DEUS, O PAI;\nO DIA DA VITÓRIA BREVE VAI CHEGAR,\nREGOZIJAI-VOS Ó ESCOLHIDOS DO SENHOR.\n\nANTES MESMO QUE NASCESSEIS VOS ESCOLHI \nE VOS CONSAGREI, PARA ANUNCIARDES \nAS MINHAS PALAVRAS PORQUE VOLTAREI \nE SOMENTE OS FIÉIS LEVAREI.\n\nCORO\nERGUEI VOSSAS CABEÇAS E CONTEMPLAI\nOS ANJOS LOUVANDO A DEUS, O PAI;\nO DIA DA VITÓRIA BREVE VAI CHEGAR,\nREGOZIJAI-VOS Ó ESCOLHIDOS DO SENHOR.\n\nFINAL: \nREGOZIJAI-VOS, \nÓ ESCOLHIDOS DO SENHOR.', 'NÃO SE TURBEM OS VOSSOS CORAÇÕES,\nBREVE SE CUMPRIRÁ A PROMESSA DE JESUS;\nTODO PRANTO CESSARÁ E OS SANTOS SUBIRÃO \nLEVADOS PELOS ANJOS AO SENHOR.\n\n<coro>\nERGUEI VOSSAS CABEÇAS E CONTEMPLAI\nOS ANJOS LOUVANDO A DEUS, O PAI;\nO DIA DA VITÓRIA BREVE VAI CHEGAR,\nREGOZIJAI-VOS Ó ESCOLHIDOS DO SENHOR.\n\nANTES MESMO QUE NASCESSEIS VOS ESCOLHI \nE VOS CONSAGREI, PARA ANUNCIARDES \nAS MINHAS PALAVRAS PORQUE VOLTAREI \nE SOMENTE OS FIÉIS LEVAREI.\n\n<coro>\nERGUEI VOSSAS CABEÇAS E CONTEMPLAI\nOS ANJOS LOUVANDO A DEUS, O PAI;\nO DIA DA VITÓRIA BREVE VAI CHEGAR,\nREGOZIJAI-VOS Ó ESCOLHIDOS DO SENHOR.\n<final>REGOZIJAI-VOS, \nÓ ESCOLHIDOS DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (564, 'DISPÕE-TE, RESPLANDECE', 'DISPÕE-TE, RESPLANDECE', 'DISPÕE-TE, RESPLANDECE, \nPORQUE VEM A TUA LUZ E A GLÓRIA \nDO SENHOR JESUS NASCE SOBRE TI.\n\nPORQUE EIS QUE AS TREVAS COBREM A TERRA \nE A ESCURIDÃO OS POVOS MAS SOBRE TI APARECE RESPLENDENTE O SENHOR JESUS E A SUA GLÓRIA \nSE VÊ SOBRE TI, NOVA JERUSALÉM.\n\nAS NAÇÕES SE ENCAMINHAM PARA A TUA LUZ, \nE OS REIS PARA O RESPLENDOR\nQUE TE NASCEU.\n\nLEVANTA EM REDOR OS TEUS OLHOS E VÊ, TODOS ESTES SE AJUNTAM E VÊM TER CONTIGO, TEUS FILHOS CHEGAM DE LONGE E TUAS FILHAS SÃO TRAZIDAS NOS BRAÇOS, NOVA JERUSALÉM.\n\nENTÃO O VERÁS E SERÁS\nRADIANTE DE ALEGRIA,\nO TEU CORAÇÃO ESTREMECERÁ\nE SE DILATARÁ DE JÚBILO.\n\nPORQUE A ABUNDÂNCIA DO MAR\nSE TORNARÁ A TI\nE AS RIQUEZAS DAS NAÇÕES\nVIRÃO A TER CONTIGO,\nNOVA JERUSALÉM, NOVA JERUSALÉM.', 'DISPÕE-TE, RESPLANDECE, \nPORQUE VEM A TUA LUZ E A GLÓRIA \nDO SENHOR JESUS NASCE SOBRE TI.\n\nPORQUE EIS QUE AS TREVAS COBREM A TERRA \nE A ESCURIDÃO OS POVOS MAS SOBRE TI APARECE RESPLENDENTE O SENHOR JESUS E A SUA GLÓRIA \nSE VÊ SOBRE TI, NOVA JERUSALÉM.\n\nAS NAÇÕES SE ENCAMINHAM PARA A TUA LUZ, \nE OS REIS PARA O RESPLENDOR\nQUE TE NASCEU.\n\nLEVANTA EM REDOR OS TEUS OLHOS E VÊ, TODOS ESTES SE AJUNTAM E VÊM TER CONTIGO, TEUS FILHOS CHEGAM DE LONGE E TUAS FILHAS SÃO TRAZIDAS NOS BRAÇOS, NOVA JERUSALÉM.\n\nENTÃO O VERÁS E SERÁS\nRADIANTE DE ALEGRIA,\nO TEU CORAÇÃO ESTREMECERÁ\nE SE DILATARÁ DE JÚBILO.\n\nPORQUE A ABUNDÂNCIA DO MAR\nSE TORNARÁ A TI\nE AS RIQUEZAS DAS NAÇÕES\nVIRÃO A TER CONTIGO,\nNOVA JERUSALÉM, NOVA JERUSALÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (565, 'LÁ ESTÁ O MEU TESOURO', 'LÁ ESTÁ O MEU TESOURO', 'LÁ ESTÁ O MEU TESOURO,\nLÁ ONDE NÃO HÁ CHORO,\nONDE TODOS CANTAREMOS JUNTOS,\nHINOS DE LOUVOR.\n\nALELUIA, ALELUIA, ALELUIA, ALELUIA,\nHINOS DE LOUVOR AO SENHOR.\n\nINSTRUMENTOS\n\nALELUIA, ALELUIA, ALELUIA, ALELUIA,\nHINOS DE LOUVOR AO SENHOR.', 'LÁ ESTÁ O MEU TESOURO,\nLÁ ONDE NÃO HÁ CHORO,\nONDE TODOS CANTAREMOS JUNTOS,\nHINOS DE LOUVOR.\n\nALELUIA, ALELUIA, ALELUIA, ALELUIA,\nHINOS DE LOUVOR AO SENHOR.\n<instrumentos>\nALELUIA, ALELUIA, ALELUIA, ALELUIA,\nHINOS DE LOUVOR AO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (566, 'O SENHOR É O MEU PASTOR (MARANATA, JESUS VEM)', 'O SENHOR É O MEU PASTOR (MARANATA, JESUS VEM)', 'O SENHOR É O MEU PASTOR, NADA ME FALTARÁ,\nJESUS CRISTO É O MEU SENHOR,\nNA SUA GLÓRIA VOU ESTAR.\nLOUVORES AO SEU NOME,\nE ME GUIA EM SEUS PASSOS DE LUZ (DE LUZ),\nNA SUA GLÓRIA VOU ESTAR.\n\nO SENHOR É O MEU PASTOR, NADA ME FALTARÁ,\nJESUS CRISTO É O MEU SENHOR,\nNA SUA GLÓRIA VOU ESTAR.\nLOUVORES AO SEU NOME,\nE ME GUIA EM SEUS PASSOS DE LUZ (DE LUZ),\nTODA A IGREJA CANTARÁ.\n\nCORO \nMARANATA, JESUS VEM!\nMARANATA, VEM BUSCAR!\nMARANATA, TODOS SEUS,\nCOM O SENHOR VÃO MORAR.\n\nINSTRUMENTOS\n\nDE LUZ (DE LUZ).\n\nO SENHOR É O MEU PASTOR, NADA ME FALTARÁ,\nJESUS CRISTO É O MEU SENHOR,\nNA SUA GLÓRIA VOU ESTAR.\nLOUVORES AO SEU NOME,\nE ME GUIA EM SEUS PASSOS DE LUZ (DE LUZ),\nTODA A IGREJA CANTARÁ.\n\nCORO (2X) \nMARANATA, JESUS VEM!\nMARANATA, VEM BUSCAR!\nMARANATA, TODOS SEUS,\nCOM O SENHOR VÃO MORAR.', 'O SENHOR É O MEU PASTOR, NADA ME FALTARÁ,\nJESUS CRISTO É O MEU SENHOR,\nNA SUA GLÓRIA VOU ESTAR.\nLOUVORES AO SEU NOME,\nE ME GUIA EM SEUS PASSOS DE LUZ (DE LUZ),\nNA SUA GLÓRIA VOU ESTAR.\n\nO SENHOR É O MEU PASTOR, NADA ME FALTARÁ,\nJESUS CRISTO É O MEU SENHOR,\nNA SUA GLÓRIA VOU ESTAR.\nLOUVORES AO SEU NOME,\nE ME GUIA EM SEUS PASSOS DE LUZ (DE LUZ),\nTODA A IGREJA CANTARÁ.\n\n<coro>\nMARANATA, JESUS VEM!\nMARANATA, VEM BUSCAR!\nMARANATA, TODOS SEUS,\nCOM O SENHOR VÃO MORAR.\n<instrumentos>\nDE LUZ (DE LUZ).\n\nO SENHOR É O MEU PASTOR, NADA ME FALTARÁ,\nJESUS CRISTO É O MEU SENHOR,\nNA SUA GLÓRIA VOU ESTAR.\nLOUVORES AO SEU NOME,\nE ME GUIA EM SEUS PASSOS DE LUZ (DE LUZ),\nTODA A IGREJA CANTARÁ.\n\n<coro tipo=''2X''>\nMARANATA, JESUS VEM!\nMARANATA, VEM BUSCAR!\nMARANATA, TODOS SEUS,\nCOM O SENHOR VÃO MORAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (567, 'QUANDO SERÁ O GRANDE DIA', 'QUANDO SERÁ O GRANDE DIA', 'QUANDO SERÁ O GRANDE DIA,\nEM QUE O SENHOR VIRÁ NOS BUSCAR?\nNINGUÉM SABE O DIA, NINGUÉM SABE A HORA,\nMAS A TROMBETA ESTÁ PRA SOAR.\n\nEIS QUE OS SINAIS JÁ SE CUMPRIRAM,\nEM TODA TERRA, RIOS E MARES.\nA SUA IGREJA OUVE A VOZ DO ESPÍRITO:\nMARANATA! JESUS VOLTARÁ! SIM, VOLTARÁ!\n\nCORO\nMARANATA, MARANATA,\nA IGREJA CLAMA, MARANATA!\nO SENHOR VEM! O SENHOR VEM!\n\nINSTRUMENTOS\n\nDIAS DIFÍCEIS, DIAS DE DORES,\nDIAS DE LUTAS, ESTÃO SE PASSANDO.\nA SUA IGREJA OLHA PRO ALTO,\nMARANATA! JESUS VOLTARÁ! SIM, VOLTARÁ!\n\nCORO\nMARANATA, MARANATA,\nA IGREJA CLAMA, MARANATA!\nO SENHOR VEM! O SENHOR VEM!', 'QUANDO SERÁ O GRANDE DIA,\nEM QUE O SENHOR VIRÁ NOS BUSCAR?\nNINGUÉM SABE O DIA, NINGUÉM SABE A HORA,\nMAS A TROMBETA ESTÁ PRA SOAR.\n\nEIS QUE OS SINAIS JÁ SE CUMPRIRAM,\nEM TODA TERRA, RIOS E MARES.\nA SUA IGREJA OUVE A VOZ DO ESPÍRITO:\nMARANATA! JESUS VOLTARÁ! SIM, VOLTARÁ!\n\n<coro>\nMARANATA, MARANATA,\nA IGREJA CLAMA, MARANATA!\nO SENHOR VEM! O SENHOR VEM!\n<instrumentos>\n\n\nDIAS DIFÍCEIS, DIAS DE DORES,\nDIAS DE LUTAS, ESTÃO SE PASSANDO.\nA SUA IGREJA OLHA PRO ALTO,\nMARANATA! JESUS VOLTARÁ! SIM, VOLTARÁ!\n\n<coro>\nMARANATA, MARANATA,\nA IGREJA CLAMA, MARANATA!\nO SENHOR VEM! O SENHOR VEM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (568, 'SENHOR, QUEM SÃO AQUELES', 'SENHOR, QUEM SÃO AQUELES', 'SENHOR, QUEM SÃO AQUELES,\nQUE VEM SUBINDO PELO CAMINHO?\nCANTANDO ALEGREMENTE COMO AS AVES\nQUE VÃO PARA O NINHO.\n\nCORO\nSENHOR, QUEM SÃO AQUELES,\nQUE EM VESTES BRANCAS VÃO PROSSEGUINDO?\nSENHOR, EU QUERO SEGUI-LOS,\nTU NÃO ME DEIXES FICAR SOZINHO.\n\nO MUNDO JÁ NÃO ME SERVE,\nA MINHA ALMA ESTÁ SOLUÇANDO.\nSENHOR, TU NÃO ME DEIXES,\nFICAR NO MUNDO SEMPRE SOFRENDO.\n\nCORO\nSENHOR, QUEM SÃO AQUELES,\nQUE EM VESTES BRANCAS VÃO PROSSEGUINDO?\nSENHOR, EU QUERO SEGUI-LOS,\nTU NÃO ME DEIXES FICAR SOZINHO.\n\nEU QUERO TAMBÉM SER UM DELES,\nTER FELICIDADE NO CORAÇÃO.\nSEGUIR AQUELE CAMINHO,\nSEM SOFRIMENTO E DE SALVAÇÃO.\n\nCORO\nSENHOR, QUEM SÃO AQUELES,\nQUE EM VESTES BRANCAS VÃO PROSSEGUINDO?\nSENHOR, EU QUERO SEGUI-LOS,\nTU NÃO ME DEIXES FICAR SOZINHO.\n\nFINAL: (2X)\nTU NÃO ME DEIXES FICAR SOZINHO.', 'SENHOR, QUEM SÃO AQUELES,\nQUE VEM SUBINDO PELO CAMINHO?\nCANTANDO ALEGREMENTE COMO AS AVES\nQUE VÃO PARA O NINHO.\n\n<coro>\nSENHOR, QUEM SÃO AQUELES,\nQUE EM VESTES BRANCAS VÃO PROSSEGUINDO?\nSENHOR, EU QUERO SEGUI-LOS,\nTU NÃO ME DEIXES FICAR SOZINHO.\n\nO MUNDO JÁ NÃO ME SERVE,\nA MINHA ALMA ESTÁ SOLUÇANDO.\nSENHOR, TU NÃO ME DEIXES,\nFICAR NO MUNDO SEMPRE SOFRENDO.\n\n<coro>\nSENHOR, QUEM SÃO AQUELES,\nQUE EM VESTES BRANCAS VÃO PROSSEGUINDO?\nSENHOR, EU QUERO SEGUI-LOS,\nTU NÃO ME DEIXES FICAR SOZINHO.\n\nEU QUERO TAMBÉM SER UM DELES,\nTER FELICIDADE NO CORAÇÃO.\nSEGUIR AQUELE CAMINHO,\nSEM SOFRIMENTO E DE SALVAÇÃO.\n\n<coro>\nSENHOR, QUEM SÃO AQUELES,\nQUE EM VESTES BRANCAS VÃO PROSSEGUINDO?\nSENHOR, EU QUERO SEGUI-LOS,\nTU NÃO ME DEIXES FICAR SOZINHO.\n<final>(<bis tipo=''2''>\nTU NÃO ME DEIXES FICAR SOZINHO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (569, 'JESUS VEM, VEM NOS BUSCAR', 'JESUS VEM, VEM NOS BUSCAR', 'CORO\nJESUS VEM! VEM NOS BUSCAR!\nLEVAR-NOS PARA A ETERNIDADE.\nJESUS VEM! VEM NOS BUSCAR!\nCOM MAJESTADE E PODER.\n\nO SEU PODER É DIVINO,\nA SUA GRAÇA É SEM PAR;\nTODOS OS SEUS FIÉIS HÃO DE SUBIR,\nVAMOS PRA SEMPRE MORAR,\nNA ETERNIDADE, \nJUNTOS COM O SALVADOR.\n\nCORO\nJESUS VEM! VEM NOS BUSCAR!\nLEVAR-NOS PARA A ETERNIDADE.\nJESUS VEM! VEM NOS BUSCAR!\nCOM MAJESTADE E PODER.\n\nOS SINAIS ESTÃO SE CUMPRINDO,\nA SUA PALAVRA É FIEL;\nPREPARA-TE IGREJA,\nCINJA OS TEUS LOMBOS!\nMANTENHA ACESA A CANDEIA!\nPARA O ENCONTRO COM O NOIVO,\nNAS BODAS DO CORDEIRO.\n\nCORO\nJESUS VEM! VEM NOS BUSCAR!\nLEVAR-NOS PARA A ETERNIDADE.\nJESUS VEM! VEM NOS BUSCAR!\nCOM MAJESTADE E PODER.\n\nFINAL: \nJESUS VEM! DA SUA GLÓRIA!\nJESUS VEM! COM PODER E GLÓRIA!\nCOM MAJESTADE E PODER;\nVEM, VEM, VEM, JESUS!', '<coro>\nJESUS VEM! VEM NOS BUSCAR!\nLEVAR-NOS PARA A ETERNIDADE.\nJESUS VEM! VEM NOS BUSCAR!\nCOM MAJESTADE E PODER.\n\nO SEU PODER É DIVINO,\nA SUA GRAÇA É SEM PAR;\nTODOS OS SEUS FIÉIS HÃO DE SUBIR,\nVAMOS PRA SEMPRE MORAR,\nNA ETERNIDADE, \nJUNTOS COM O SALVADOR.\n\n<coro>\nJESUS VEM! VEM NOS BUSCAR!\nLEVAR-NOS PARA A ETERNIDADE.\nJESUS VEM! VEM NOS BUSCAR!\nCOM MAJESTADE E PODER.\n\nOS SINAIS ESTÃO SE CUMPRINDO,\nA SUA PALAVRA É FIEL;\nPREPARA-TE IGREJA,\nCINJA OS TEUS LOMBOS!\nMANTENHA ACESA A CANDEIA!\nPARA O ENCONTRO COM O NOIVO,\nNAS BODAS DO CORDEIRO.\n\n<coro>\nJESUS VEM! VEM NOS BUSCAR!\nLEVAR-NOS PARA A ETERNIDADE.\nJESUS VEM! VEM NOS BUSCAR!\nCOM MAJESTADE E PODER.\n\n\n<final>JESUS VEM! DA SUA GLÓRIA!\nJESUS VEM! COM PODER E GLÓRIA!\nCOM MAJESTADE E PODER;\nVEM, VEM, VEM, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (570, 'JÁ REFULGE A GLÓRIA ETERNA (VENCENDO VEM JESUS)', 'JÁ REFULGE A GLÓRIA ETERNA (VENCENDO VEM JESUS)', 'JÁ REFULGE A GLÓRIA ETERNA DE JESUS,\nO REI DOS REIS.\nBREVE OS REINOS DESTE MUNDO\nSEGUIRÃO AS SUAS LEIS!\nOS SINAIS DA SUA VINDA\nMAIS SE MOSTRAM CADA VEZ.\nVENCENDO VEM JESUS!\n\nCORO\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCENDO VEM JESUS!\n\nO CLARIM QUE CHAMA OS CRENTES\nÀ BATALHA, JÁ SOOU.\nCRISTO, À FRENTE DO SEU POVO,\nMULTIDÕES JÁ CONQUISTOU.\nO INIMIGO EM RETIRADA\nSEU FUROR PATENTEOU.\nVENCENDO VEM JESUS!\n\nCORO\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCENDO VEM JESUS!\n\nEIS QUE EM GLÓRIA REFULGENTE\nSOBRE AS NUVENS DESCERÁ.\nE AS NAÇÕES E OS REIS DA TERRA\nCOM PODER GOVERNARÁ.\nSIM, EM PAZ E SANTIDADE\nTODA A TERRA REGERÁ.\nVENCENDO VEM JESUS!\n\nCORO\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCENDO VEM JESUS!\n\nE, POR FIM ENTRONIZADO\nAS NAÇÕES HÁ DE JULGAR.\nTODOS, GRANDES E PEQUENOS,\nO JUIZ, HÃO DE ENCARAR.\nE OS REMIDOS TRIUNFANTES,\nEM FULGOR HÃO DE CANTAR.\nVENCIDO TEM JESUS!\n\nCORO\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCIDO TEM JESUS!', 'JÁ REFULGE A GLÓRIA ETERNA DE JESUS,\nO REI DOS REIS.\nBREVE OS REINOS DESTE MUNDO\nSEGUIRÃO AS SUAS LEIS!\nOS SINAIS DA SUA VINDA\nMAIS SE MOSTRAM CADA VEZ.\nVENCENDO VEM JESUS!\n\n<coro>\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCENDO VEM JESUS!\n\nO CLARIM QUE CHAMA OS CRENTES\nÀ BATALHA, JÁ SOOU.\nCRISTO, À FRENTE DO SEU POVO,\nMULTIDÕES JÁ CONQUISTOU.\nO INIMIGO EM RETIRADA\nSEU FUROR PATENTEOU.\nVENCENDO VEM JESUS!\n\n<coro>\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCENDO VEM JESUS!\n\nEIS QUE EM GLÓRIA REFULGENTE\nSOBRE AS NUVENS DESCERÁ.\nE AS NAÇÕES E OS REIS DA TERRA\nCOM PODER GOVERNARÁ.\nSIM, EM PAZ E SANTIDADE\nTODA A TERRA REGERÁ.\nVENCENDO VEM JESUS!\n\n<coro>\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCENDO VEM JESUS!\n\nE, POR FIM ENTRONIZADO\nAS NAÇÕES HÁ DE JULGAR.\nTODOS, GRANDES E PEQUENOS,\nO JUIZ, HÃO DE ENCARAR.\nE OS REMIDOS TRIUNFANTES,\nEM FULGOR HÃO DE CANTAR.\nVENCIDO TEM JESUS!\n\n<coro>\nGLÓRIA, GLÓRIA ALELUIA!\nGLÓRIA, GLÓRIA ALELUIA! \nGLÓRIA, GLÓRIA ALELUIA! \nVENCIDO TEM JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (571, 'O GRANDE DIA ESTÁ CHEGANDO', 'O GRANDE DIA ESTÁ CHEGANDO', 'O GRANDE DIA ESTÁ CHEGANDO, FALTA TÃO POUCO\nPARA O ENCONTRO COM MEU REI.\nPOSSO ATÉ IMAGINAR O QUE VOU SENTIR\nQUANDO EU PASSAR PELOS PORTAIS CELESTIAIS\nOUVINDO A MAIS BELA CANÇÃO DE LOUVOR!\nLÁ PODEREI DIZER ASSIM:\n\nCORO\nJERUSALÉM, COMO ÉS LINDA!\nJERUSALÉM, QUANTO TEMPO,\nEU ESPEREI PARA VER A TUA BELEZA!\nJERUSALÉM, NA CIDADE DO MEU REI EU ESTOU!\nPOSSO AGORA MEU MESTRE JESUS ABRAÇAR!\n\nO GRANDE DIA ESTÁ CHEGANDO, FALTA TÃO POUCO\nPARA O ENCONTRO COM MEU REI.\nPOSSO ATÉ IMAGINAR O QUE VOU SENTIR\nQUANDO EU PASSAR PELOS PORTAIS CELESTIAIS\nOUVINDO A MAIS BELA CANÇÃO DE LOUVOR!\nLÁ PODEREI DIZER ASSIM:\n\nCORO (BIS)\nJERUSALÉM, COMO ÉS LINDA!\nJERUSALÉM, QUANTO TEMPO,\nEU ESPEREI PARA VER A TUA BELEZA!\nJERUSALÉM, NA CIDADE DO MEU REI EU ESTOU!\nPOSSO AGORA MEU MESTRE JESUS ABRAÇAR!\n\nFINAL: \nPOSSO AGORA MEU MESTRE JESUS ABRAÇAR!', 'O GRANDE DIA ESTÁ CHEGANDO, FALTA TÃO POUCO\nPARA O ENCONTRO COM MEU REI.\nPOSSO ATÉ IMAGINAR O QUE VOU SENTIR\nQUANDO EU PASSAR PELOS PORTAIS CELESTIAIS\nOUVINDO A MAIS BELA CANÇÃO DE LOUVOR!\nLÁ PODEREI DIZER ASSIM:\n\n<coro>\nJERUSALÉM, COMO ÉS LINDA!\nJERUSALÉM, QUANTO TEMPO,\nEU ESPEREI PARA VER A TUA BELEZA!\nJERUSALÉM, NA CIDADE DO MEU REI EU ESTOU!\nPOSSO AGORA MEU MESTRE JESUS ABRAÇAR!\n\nO GRANDE DIA ESTÁ CHEGANDO, FALTA TÃO POUCO\nPARA O ENCONTRO COM MEU REI.\nPOSSO ATÉ IMAGINAR O QUE VOU SENTIR\nQUANDO EU PASSAR PELOS PORTAIS CELESTIAIS\nOUVINDO A MAIS BELA CANÇÃO DE LOUVOR!\nLÁ PODEREI DIZER ASSIM:\n\n<coro tipo=''BIS''>\nJERUSALÉM, COMO ÉS LINDA!\nJERUSALÉM, QUANTO TEMPO,\nEU ESPEREI PARA VER A TUA BELEZA!\nJERUSALÉM, NA CIDADE DO MEU REI EU ESTOU!\nPOSSO AGORA MEU MESTRE JESUS ABRAÇAR!\n<final>POSSO AGORA MEU MESTRE JESUS ABRAÇAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (572, 'CHEGUEMOS AO ALTAR DE DEUS', 'CHEGUEMOS AO ALTAR DE DEUS', 'CHEGUEMOS AO ALTAR DE DEUS\nCOM A NOSSA ADORAÇÃO;\nNA SUA MÃO HÁ FORÇA E PODER.\n\nCORO (2X)\nADOREMOS, ADOREMOS E CANTEMOS \nAO AUTOR DA NOSSA SALVAÇÃO. \n\nINSTRUMENTOS\n\nCHEGUEMOS AO ALTAR DE DEUS\nCOM A NOSSA ADORAÇÃO;\nTUA É, SENHOR, A HONRA E A MAJESTADE, \nPORQUE TEU É TUDO QUANTO \nHÁ NOS CÉUS E NA TERRA;\nTEU, SENHOR, É O REINO E TU TE EXALTASTE;\nNA TUA MÃO HÁ FORÇA E PODER. (BIS)\n\nCORO (2X)\nADOREMOS, ADOREMOS E CANTEMOS \nAO AUTOR DA NOSSA SALVAÇÃO. \n\nINSTRUMENTOS\n\nFINAL: \nE CANTEMOS AO AUTOR\nDA NOSSA SALVAÇÃO.', 'CHEGUEMOS AO ALTAR DE DEUS\nCOM A NOSSA ADORAÇÃO;\nNA SUA MÃO HÁ FORÇA E PODER.<coro tipo=''2X''>\nADOREMOS, ADOREMOS E CANTEMOS \nAO AUTOR DA NOSSA SALVAÇÃO. \n<instrumentos>\n\n\nCHEGUEMOS AO ALTAR DE DEUS\nCOM A NOSSA ADORAÇÃO;\nTUA É, SENHOR, A HONRA E A MAJESTADE, \nPORQUE TEU É TUDO QUANTO \nHÁ NOS CÉUS E NA TERRA;\nTEU, SENHOR, É O REINO E TU TE EXALTASTE;\nNA TUA MÃO HÁ FORÇA E PODER. <bis>\n\n<coro tipo=''2X''>\nADOREMOS, ADOREMOS E CANTEMOS \nAO AUTOR DA NOSSA SALVAÇÃO. \n<instrumentos>\n<final>E CANTEMOS AO AUTOR\nDA NOSSA SALVAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (573, 'COMO É BOM TE ADORAR', 'COMO É BOM TE ADORAR', 'COMO É BOM TE ADORAR SENHOR JESUS\nCOMO É BOM ESTAR NA TUA PRESENÇA,\nCANTAR LOUVORES E BENDIZER\nDE TODO O MEU CORAÇÃO.\n\nCORO\nOH! SENHOR, \n(OH! SENHOR) (VARÕES)\nGRANDIOSO É O TEU NOME;\nOH! SENHOR, (VARÕES)\n(OH! SENHOR) (SERVAS)\nTEU ESPÍRITO SANTO \nNOS TEM CONSOLADO.\n\nTENS ABENÇOADO O TEU POVO,\nTENS ABENÇOADO, Ó DEUS,\nTENS ALEGRADO OS CORAÇÕES,\nTENS NOS DADO A LIBERTAÇÃO.\n\nCORO\nOH! SENHOR, \n(OH! SENHOR) (VARÕES)\nGRANDIOSO É O TEU NOME;\nOH! SENHOR, (VARÕES)\n(OH! SENHOR) (SERVAS)\nTEU ESPÍRITO SANTO \nNOS TEM CONSOLADO.\n\nFINAL: (2X)\nLOUVAREI AO SENHOR, (LOUVAREI)\nCOM GRANDE ALEGRIA, (LOUVAREI) \nLOUVAREI AO SENHOR,\nLOUVAREI AO SENHOR JESUS.\nLOUVAREI AO SENHOR JESUS.', 'COMO É BOM TE ADORAR SENHOR JESUS\nCOMO É BOM ESTAR NA TUA PRESENÇA,\nCANTAR LOUVORES E BENDIZER\nDE TODO O MEU CORAÇÃO.\n\n<coro>\nOH! SENHOR, \n(OH! SENHOR) <h>\nGRANDIOSO É O TEU NOME;\nOH! SENHOR, <h>\n(OH! SENHOR) <m>\nTEU ESPÍRITO SANTO \nNOS TEM CONSOLADO.\n\nTENS ABENÇOADO O TEU POVO,\nTENS ABENÇOADO, Ó DEUS,\nTENS ALEGRADO OS CORAÇÕES,\nTENS NOS DADO A LIBERTAÇÃO.\n\n<coro>\nOH! SENHOR, \n(OH! SENHOR) <h>\nGRANDIOSO É O TEU NOME;\nOH! SENHOR, <h>\n(OH! SENHOR) <m>\nTEU ESPÍRITO SANTO \nNOS TEM CONSOLADO.\n\n\n<final>(<bis tipo=''2''>\nLOUVAREI AO SENHOR, (LOUVAREI)\nCOM GRANDE ALEGRIA, (LOUVAREI) \nLOUVAREI AO SENHOR,\nLOUVAREI AO SENHOR JESUS.\nLOUVAREI AO SENHOR JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (574, 'ADORAREI', 'ADORAREI', 'ADORAREI O GRANDE EU SOU,\nDEUS SEM PRINCÍPIO, DEUS SEM FIM\nEXALTAREI O REI QUE VIVE EM MIM.\n\nA DEUS DE PRATA E OURO\nJAMAIS EU ME ENCURVAREI,\nSÓ TU ÉS MEU TESOURO,\nA TI SOMENTE SERVIREI,\nACEITA O MEU SACRIFÍCIO DE LOUVOR.', 'ADORAREI O GRANDE EU SOU,<bis>\nDEUS SEM PRINCÍPIO, DEUS SEM FIM<bis>\nEXALTAREI O REI QUE VIVE EM MIM.<bis>\n\nA DEUS DE PRATA E OURO<bis>\nJAMAIS EU ME ENCURVAREI,<bis>\nSÓ TU ÉS MEU TESOURO,<bis>\nA TI SOMENTE SERVIREI,<bis>\nACEITA O MEU SACRIFÍCIO DE LOUVOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (575, 'TE ADORAMOS', 'TE ADORAMOS', 'TE ADORAMOS, Ó SENHOR,\nPELAS GRANDES MARAVILHAS\nQUE TENS FEITO;\nNOSSA VIDA TENS GUARDADO,\nCADA DIA NOS REVELAS TEU AMOR.\n\nCORO\nÉS O DEUS EM QUEM PODEMOS CONFIAR,\nDEUS FIEL E FORTE QUE NÃO VAI MUDAR;\nCOM O NOSSO CORAÇÃO CHEIO DE AMOR\nTE OFERTAMOS NOSSA ADORAÇÃO, \nNOSSO LOUVOR.\n\nINSTRUMENTOS\n\nÉS REFÚGIO BEM SEGURO \nNOSSO ABRIGO CONTRA \nA TEMPESTADE E O VENTO;\nCOMO SOMBRA DE UMA ROCHA \nE CORRENTES DE ÁGUA \nEM LUGAR SEDENTO.\n\nCORO\nÉS O DEUS EM QUEM PODEMOS CONFIAR,\nDEUS FIEL E FORTE QUE NÃO VAI MUDAR;\nCOM O NOSSO CORAÇÃO CHEIO DE AMOR\nTE OFERTAMOS NOSSA ADORAÇÃO, \nNOSSO LOUVOR.\n\nFINAL: \nNOSSA ADORAÇÃO, NOSSO LOUVOR', 'TE ADORAMOS, Ó SENHOR,\nPELAS GRANDES MARAVILHAS\nQUE TENS FEITO;\nNOSSA VIDA TENS GUARDADO,\nCADA DIA NOS REVELAS TEU AMOR.\n\n<coro>\nÉS O DEUS EM QUEM PODEMOS CONFIAR,\nDEUS FIEL E FORTE QUE NÃO VAI MUDAR;\nCOM O NOSSO CORAÇÃO CHEIO DE AMOR\nTE OFERTAMOS NOSSA ADORAÇÃO, \nNOSSO LOUVOR.\n<instrumentos>\n\n\nÉS REFÚGIO BEM SEGURO \nNOSSO ABRIGO CONTRA \nA TEMPESTADE E O VENTO;\nCOMO SOMBRA DE UMA ROCHA \nE CORRENTES DE ÁGUA \nEM LUGAR SEDENTO.\n\n<coro>\nÉS O DEUS EM QUEM PODEMOS CONFIAR,\nDEUS FIEL E FORTE QUE NÃO VAI MUDAR;\nCOM O NOSSO CORAÇÃO CHEIO DE AMOR\nTE OFERTAMOS NOSSA ADORAÇÃO, \nNOSSO LOUVOR.\n<final>NOSSA ADORAÇÃO, NOSSO LOUVOR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (576, 'REUNIMO-NOS AQUI PRA TE ADORAR', 'REUNIMO-NOS AQUI PRA TE ADORAR', 'REUNIMO-NOS AQUI PRA TE ADORAR, SENHOR,\nPARA TE OFERTAR O NOSSO CORAÇÃO,\nTODO O NOSSO SER SE RENDE A TI;\nNOSSA ALMA EXALTA O TEU AMOR\nEM PERFEITA E PLENA COMUNHÃO.\n\nHONRA AO PAI DE LUZ, \nAO SENHOR JESUS E AO ESPÍRITO SANTO; \nTODA GLÓRIA, PODER, VITÓRIA, \nHOJE E ETERNAMENTE.\n\nINSTRUMENTOS\n\nREUNIMO-NOS AQUI PRA TE ADORAR, \nSENHOR, PARA TE OFERTAR \nO NOSSO CORAÇÃO, \nTODO O NOSSO SER SE RENDE A TI;\nNOSSA ALMA EXALTA O TEU AMOR \nEM PERFEITA E PLENA COMUNHÃO.\n\nHONRA AO PAI DE LUZ,\nAO SENHOR JESUS\nE AO ESPÍRITO SANTO;\nTODA GLÓRIA, PODER, VITÓRIA,\nHOJE E ETERNAMENTE.', 'REUNIMO-NOS AQUI PRA TE ADORAR, SENHOR,\nPARA TE OFERTAR O NOSSO CORAÇÃO,\nTODO O NOSSO SER SE RENDE A TI;\nNOSSA ALMA EXALTA O TEU AMOR\nEM PERFEITA E PLENA COMUNHÃO.\n\nHONRA AO PAI DE LUZ, \nAO SENHOR JESUS E AO ESPÍRITO SANTO; \nTODA GLÓRIA, PODER, VITÓRIA, \nHOJE E ETERNAMENTE.\n<instrumentos>\n\n\nREUNIMO-NOS AQUI PRA TE ADORAR, \nSENHOR, PARA TE OFERTAR \nO NOSSO CORAÇÃO, \nTODO O NOSSO SER SE RENDE A TI;\nNOSSA ALMA EXALTA O TEU AMOR \nEM PERFEITA E PLENA COMUNHÃO.\n\nHONRA AO PAI DE LUZ,\nAO SENHOR JESUS\nE AO ESPÍRITO SANTO;\nTODA GLÓRIA, PODER, VITÓRIA,\nHOJE E ETERNAMENTE.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (577, 'GLÓRIA E ALELUIA', 'GLÓRIA E ALELUIA', 'GLÓRIA E ALELUIA NÓS TE DAMOS SENHOR\nBENDITO SEJA O TEU SANTO NOME (VARÕES)\nGRAÇAS E LOUVORES TE RENDEMOS SENHOR\nEXALTADA SEJA A TUA SALVAÇÃO. (VARÕES)\n\nPOIS O SENHOR É MINHA ROCHA \nE MINHA FORÇA E O MEU ALTO REFÚGIO;\nA ELE CLAMAREI E ELE ME SALVARÁ,\nÉ ELE QUEM ME TEM DADO A VITÓRIA.\n\nGLÓRIA E ALELUIA NÓS TE DAMOS SENHOR\nBENDITO SEJA O TEU SANTO NOME (VARÕES)\nGRAÇAS E LOUVORES TE RENDEMOS SENHOR\nEXALTADA SEJA A TUA SALVAÇÃO. (VARÕES)\n\nPOIS O SENHOR É MINHA ROCHA \nE MINHA FORÇA E O MEU ALTO REFÚGIO;\nA ELE CLAMAREI E ELE ME SALVARÁ,\nÉ ELE QUEM ME TEM DADO A VITÓRIA.\n\nGLÓRIA E ALELUIA NÓS TE DAMOS SENHOR\nBENDITO SEJA O TEU SANTO NOME (VARÕES)\nGRAÇAS E LOUVORES TE RENDEMOS SENHOR\nEXALTADA SEJA A TUA SALVAÇÃO. (VARÕES)\n\nFINAL: \nEXALTADA SEJA A TUA SALVAÇÃO.', 'GLÓRIA E ALELUIA NÓS TE DAMOS SENHOR\nBENDITO SEJA O TEU SANTO NOME <h>\nGRAÇAS E LOUVORES TE RENDEMOS SENHOR\nEXALTADA SEJA A TUA SALVAÇÃO. <h>\n\n\nPOIS O SENHOR É MINHA ROCHA \nE MINHA FORÇA E O MEU ALTO REFÚGIO;\nA ELE CLAMAREI E ELE ME SALVARÁ,\nÉ ELE QUEM ME TEM DADO A VITÓRIA.\n\nGLÓRIA E ALELUIA NÓS TE DAMOS SENHOR\nBENDITO SEJA O TEU SANTO NOME <h>\nGRAÇAS E LOUVORES TE RENDEMOS SENHOR\nEXALTADA SEJA A TUA SALVAÇÃO. <h>\n\n\nPOIS O SENHOR É MINHA ROCHA \nE MINHA FORÇA E O MEU ALTO REFÚGIO;\nA ELE CLAMAREI E ELE ME SALVARÁ,\nÉ ELE QUEM ME TEM DADO A VITÓRIA.\n\nGLÓRIA E ALELUIA NÓS TE DAMOS SENHOR\nBENDITO SEJA O TEU SANTO NOME <h>\nGRAÇAS E LOUVORES TE RENDEMOS SENHOR\nEXALTADA SEJA A TUA SALVAÇÃO. <h>\n<final>EXALTADA SEJA A TUA SALVAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (578, 'HOJE O SENHOR DERRAMOU', 'HOJE O SENHOR DERRAMOU', 'HOJE O SENHOR DERRAMOU \nDO SEU PODER SOBRE NÓS,\nCOMO A CADA MANHÃ E ENTARDECER \nSENTIMOS SEU AMOR;\nPOR ISSO DAMOS GRAÇAS \nPOR TUDO O QUE TEM FEITO A NÓS, \nLOUVORES E HONRAS \nAO GRANDE SALVADOR.\n\nCORO\nMEU SENHOR, A TI LOUVAMOS \nPOR TUA MÃO QUE NOS SUSTÉM, \nE APESAR DAS LUTAS E PROVAS SENHOR \nSABEMOS QUE CONOSCO SEMPRE ESTARÁS.\n\nO QUE TE DAR, MEU SENHOR, \nPOR TANTAS BÊNÇÃOS CELESTIAIS?\nEM SANTIDADE Ó SENHOR TE OFERECEMOS \nCORAÇÕES FIÉIS, PURIFICADOS EM JESUS, \nBUSCANDO A SALVAÇÃO POIS BEM SABEMOS \nQUE O SANGUE DE CRISTO TRAZ PERDÃO.\n\nCORO (2X)\nMEU SENHOR, A TI LOUVAMOS \nPOR TUA MÃO QUE NOS SUSTÉM, \nE APESAR DAS LUTAS E PROVAS SENHOR \nSABEMOS QUE CONOSCO SEMPRE ESTARÁS.\n\nFINAL: \nCONOSCO SEMPRE ESTARÁS.', 'HOJE O SENHOR DERRAMOU \nDO SEU PODER SOBRE NÓS,\nCOMO A CADA MANHÃ E ENTARDECER \nSENTIMOS SEU AMOR;\nPOR ISSO DAMOS GRAÇAS \nPOR TUDO O QUE TEM FEITO A NÓS, \nLOUVORES E HONRAS \nAO GRANDE SALVADOR.\n\n<coro>\nMEU SENHOR, A TI LOUVAMOS \nPOR TUA MÃO QUE NOS SUSTÉM, \nE APESAR DAS LUTAS E PROVAS SENHOR \nSABEMOS QUE CONOSCO SEMPRE ESTARÁS.\n\nO QUE TE DAR, MEU SENHOR, \nPOR TANTAS BÊNÇÃOS CELESTIAIS?\nEM SANTIDADE Ó SENHOR TE OFERECEMOS \nCORAÇÕES FIÉIS, PURIFICADOS EM JESUS, \nBUSCANDO A SALVAÇÃO POIS BEM SABEMOS \nQUE O SANGUE DE CRISTO TRAZ PERDÃO.\n\n<coro tipo=''2X''>\nMEU SENHOR, A TI LOUVAMOS \nPOR TUA MÃO QUE NOS SUSTÉM, \nE APESAR DAS LUTAS E PROVAS SENHOR \nSABEMOS QUE CONOSCO SEMPRE ESTARÁS.\n<final>CONOSCO SEMPRE ESTARÁS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (579, 'SENHOR, EU NEM SEI CONTAR', 'SENHOR, EU NEM SEI CONTAR', 'SENHOR, EU NEM SEI CONTAR\nAS GRANDES BÊNÇÃOS\nQUE TENS DADO AO MEU CORAÇÃO,\nPOIS O TEU AMOR ME FAZ TÃO FELIZ\nE A TUA GRAÇA ME SATISFAZ\nEM SABER QUE A CADA MANHÃ\nEU POSSO SENTIR JESUS\nTÃO PERTO DE MIM.\n\nCORO\nEU QUERO AGRADECER (VARÕES)\nAO MEU SENHOR,\nEU QUERO AGRADECER (VARÕES)\nPOR SEU AMOR,\nQUE ME FAZ SER VENCEDOR E ME FAZ FELIZ\nQUE ME FAZ SER UM SERVO DO SENHOR.\n\nINSTRUMENTOS\n\nTÃO PERTO DE MIM...\n\nCORO\nEU QUERO AGRADECER (VARÕES)\nAO MEU SENHOR,\nEU QUERO AGRADECER (VARÕES)\nPOR SEU AMOR,\nQUE ME FAZ SER VENCEDOR E ME FAZ FELIZ\nQUE ME FAZ SER UM SERVO DO SENHOR.\n\nFINAL: \nQUE ME FAZ SER UM SERVO DO SENHOR.', 'SENHOR, EU NEM SEI CONTAR\nAS GRANDES BÊNÇÃOS\nQUE TENS DADO AO MEU CORAÇÃO,\nPOIS O TEU AMOR ME FAZ TÃO FELIZ\nE A TUA GRAÇA ME SATISFAZ\nEM SABER QUE A CADA MANHÃ<bis>\nEU POSSO SENTIR JESUS<bis>\nTÃO PERTO DE MIM.<bis>\n\n<coro>\nEU QUERO AGRADECER <h>\nAO MEU SENHOR,\nEU QUERO AGRADECER <h>\nPOR SEU AMOR,\nQUE ME FAZ SER VENCEDOR E ME FAZ FELIZ\nQUE ME FAZ SER UM SERVO DO SENHOR.\n<instrumentos>\nTÃO PERTO DE MIM...\n\n<coro>\nEU QUERO AGRADECER <h>\nAO MEU SENHOR,\nEU QUERO AGRADECER <h>\nPOR SEU AMOR,\nQUE ME FAZ SER VENCEDOR E ME FAZ FELIZ\nQUE ME FAZ SER UM SERVO DO SENHOR.\n<final>QUE ME FAZ SER UM SERVO DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (580, 'NOS PROSTEMOS AOS SEUS PÉS', 'NOS PROSTEMOS AOS SEUS PÉS', 'NOS PROSTREMOS AOS SEUS PÉS\nADORANDO A JESUS,\nEXALTANDO A SUA GLÓRIA E MAJESTADE.\n\nCORO\nCOROAI A JESUS MINISTRANDO \nO SEU LOUVOR EM SUA CASA, \nCOROAI A JESUS\nBENDIZENDO E LOUVANDO O SEU NOME.\n\nINSTRUMENTOS\n\nENTRONIZADO ESTÁS ENTRE OS LOUVORES,\nASSENTADO NO TEU TRONO,\nE TODOS OS ANJOS DE DEUS TE ADORANDO.\n\nCORO (2X)\nCOROAI A JESUS MINISTRANDO \nO SEU LOUVOR EM SUA CASA,\nCOROAI A JESUS BENDIZENDO \nE LOUVANDO O SEU NOME.\n\nFINAL: (2X) \nO SEU NOME (VARÕES)\nBENDIZENDO E LOUVANDO O SEU NOME.', 'NOS PROSTREMOS AOS SEUS PÉS<bis>\nADORANDO A JESUS,<bis>\nEXALTANDO A SUA GLÓRIA E MAJESTADE.<bis>\n\n<coro>\nCOROAI A JESUS MINISTRANDO \nO SEU LOUVOR EM SUA CASA, \nCOROAI A JESUS\nBENDIZENDO E LOUVANDO O SEU NOME.\n<instrumentos>\n\n\nENTRONIZADO ESTÁS ENTRE OS LOUVORES,<bis>\nASSENTADO NO TEU TRONO,<bis>\nE TODOS OS ANJOS DE DEUS TE ADORANDO.<bis>\n\n<coro tipo=''2X''>\nCOROAI A JESUS MINISTRANDO \nO SEU LOUVOR EM SUA CASA,\nCOROAI A JESUS BENDIZENDO \nE LOUVANDO O SEU NOME.\n<final>(<bis tipo=''2''> \nO SEU NOME <h>\nBENDIZENDO E LOUVANDO O SEU NOME.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (581, 'PAI DE AMOR, GOSTO TANTO DE TI', 'PAI DE AMOR, GOSTO TANTO DE TI', 'PAI DE AMOR, GOSTO TANTO DE TI!\nPAI DE AMOR, GOSTO TANTO DE TI!\nTE AMO, TE QUERO E PROSTRADO TE ADORO!\nPAI DE AMOR, GOSTO TANTO DE TI!\n\nMEU JESUS, AMOROSO TU ÉS! (BIS)\nMINH''ALMA LIMPASTE\nE O ESPÍRITO ENVIASTE!\nMEU JESUS, AMOROSO TU ÉS!\n\nSANTO ESPÍRITO CONSOLADOR! (BIS)\nTU NOS SANTIFICAS\nE EM NÓS SEMPRE HABITAS!\nSANTO ESPÍRITO CONSOLADOR!', 'PAI DE AMOR, GOSTO TANTO DE TI!\nPAI DE AMOR, GOSTO TANTO DE TI!\nTE AMO, TE QUERO E PROSTRADO TE ADORO!\nPAI DE AMOR, GOSTO TANTO DE TI!\n\nMEU JESUS, AMOROSO TU ÉS! <bis>\nMINH''ALMA LIMPASTE\nE O ESPÍRITO ENVIASTE!\nMEU JESUS, AMOROSO TU ÉS!\n\nSANTO ESPÍRITO CONSOLADOR! <bis>\nTU NOS SANTIFICAS\nE EM NÓS SEMPRE HABITAS!\nSANTO ESPÍRITO CONSOLADOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (582, 'CANTAREI AO AMOR DOS AMORES', 'CANTAREI AO AMOR DOS AMORES', 'CANTAREI AO AMOR DOS AMORES,\nO AMOR, DOCE AMOR, O AMOR DE DEUS.\nNÃO HÁ MAIS DÚVIDAS EM MIM,\nTODO O MEU MUNDO MUDOU,\nAO AMOR DOS AMORES CANTAREI.\n\nO INVERNO PASSOU, SE FOI A CHUVA,\nE COM LÍRIOS A TERRA SE COBRIU.\nÉ TEMPO DE NOVA CANÇÃO,\nA FIGUEIRA REVERDECEU,\nAO AMOR DOS AMORES CANTAREI.\n\nMINHA VIDA HOJE É DIFERENTE,\nDE ALEGRIA CANTA E BATE O CORAÇÃO.\nILUMINOU TODO O MEU SER,\nQUERO DE NOVO VIVER,\nAO AMOR DOS AMORES CANTAREI.', 'CANTAREI AO AMOR DOS AMORES,\nO AMOR, DOCE AMOR, O AMOR DE DEUS.\nNÃO HÁ MAIS DÚVIDAS EM MIM,<bis>\nTODO O MEU MUNDO MUDOU,<bis>\nAO AMOR DOS AMORES CANTAREI.<bis>\n\nO INVERNO PASSOU, SE FOI A CHUVA,\nE COM LÍRIOS A TERRA SE COBRIU.\nÉ TEMPO DE NOVA CANÇÃO,<bis>\nA FIGUEIRA REVERDECEU,<bis>\nAO AMOR DOS AMORES CANTAREI.<bis>\n\nMINHA VIDA HOJE É DIFERENTE,\nDE ALEGRIA CANTA E BATE O CORAÇÃO.\nILUMINOU TODO O MEU SER,<bis>\nQUERO DE NOVO VIVER,<bis>\nAO AMOR DOS AMORES CANTAREI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (583, 'Ó GRANDE DEUS', 'Ó GRANDE DEUS', 'Ó GRANDE DEUS, A TUA GRAÇA\nENCHE O MEU CORAÇÃO;\nTEU É O CÉU E NA TERRA TU ÉS SALVAÇÃO\nTEU É O MAR E AS FONTES DAS ÁGUAS TAMBÉM, \nSÓ TU, SENHOR, ÉS A LUZ, ÉS A VIDA TAMBÉM.\n\nCORO\nNÃO SE ENCONTRA ENTRE OS POVOS \nDA TERRA TÃO GRANDE AMOR,\nNEM TAMBÉM NAS ESCARPAS \nDAS SERRAS TÃO RICO AMOR,\nNEM NAS NUVENS QUE PASSAM \nNOS ARES HÁ TANTO AMOR, \nMAS NO TRONO DA GLÓRIA \nSE ENCONTRA ESTE SANTO AMOR.\n\nÓ GRANDE DEUS, ME AJUDA NA TRIBULAÇÃO,\nDÁ-ME PODER PRA PREGAR E FAZER ORAÇÃO,\nDÁ-ME SABER PARA AQUI NESTA VIDA TRILHAR\nE COMPREENDER TEU AMOR, \nTUA GRAÇA SEM PAR.\n\nCORO\nNÃO SE ENCONTRA ENTRE OS POVOS \nDA TERRA TÃO GRANDE AMOR,\nNEM TAMBÉM NAS ESCARPAS \nDAS SERRAS TÃO RICO AMOR,\nNEM NAS NUVENS QUE PASSAM \nNOS ARES HÁ TANTO AMOR, \nMAS NO TRONO DA GLÓRIA \nSE ENCONTRA ESTE SANTO AMOR.', 'Ó GRANDE DEUS, A TUA GRAÇA\nENCHE O MEU CORAÇÃO;\nTEU É O CÉU E NA TERRA TU ÉS SALVAÇÃO\nTEU É O MAR E AS FONTES DAS ÁGUAS TAMBÉM, \nSÓ TU, SENHOR, ÉS A LUZ, ÉS A VIDA TAMBÉM.\n\n<coro>\nNÃO SE ENCONTRA ENTRE OS POVOS \nDA TERRA TÃO GRANDE AMOR,\nNEM TAMBÉM NAS ESCARPAS \nDAS SERRAS TÃO RICO AMOR,\nNEM NAS NUVENS QUE PASSAM \nNOS ARES HÁ TANTO AMOR, \nMAS NO TRONO DA GLÓRIA \nSE ENCONTRA ESTE SANTO AMOR.\n\nÓ GRANDE DEUS, ME AJUDA NA TRIBULAÇÃO,\nDÁ-ME PODER PRA PREGAR E FAZER ORAÇÃO,\nDÁ-ME SABER PARA AQUI NESTA VIDA TRILHAR\nE COMPREENDER TEU AMOR, \nTUA GRAÇA SEM PAR.\n\n<coro>\nNÃO SE ENCONTRA ENTRE OS POVOS \nDA TERRA TÃO GRANDE AMOR,\nNEM TAMBÉM NAS ESCARPAS \nDAS SERRAS TÃO RICO AMOR,\nNEM NAS NUVENS QUE PASSAM \nNOS ARES HÁ TANTO AMOR, \nMAS NO TRONO DA GLÓRIA \nSE ENCONTRA ESTE SANTO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (584, 'EU TE AMO, MEU JESUS', 'EU TE AMO, MEU JESUS', 'EU TE AMO, MEU JESUS,\nPOIS TU ÉS O REMIDOR,\nRESGATASTE A MINHA ALMA\nDA TRISTEZA E DA DOR,\nEU TE AMO, MEU JESUS,\nCOMO É FORTE O MEU AMOR,\nALEGRASTE A MINHA ALMA\nCOM TUA PAZ E O TEU AMOR.\n\nCORO\nEU TE AMO, MEU JESUS, POIS ABRISTE PARA MIM\nA PORTA DO JARDIM DA VIDA QUE É SEM FIM;\nA MINH''ALMA CANTA AGORA O AMOR \nQUE VIVE EM MIM, POIS MUDASTE O MEU SER,\nNÃO MAIS EU, CRISTO EM MIM.\n\nINSTRUMENTOS\n\nEU TE AMO, MEU JESUS,\nPOIS TU ÉS O MEU PASTOR,\nLEVA-ME COM ALEGRIA\nAO BANQUETE DO AMOR;\nA MINH''ALMA REJUBILA\nPOIS ÉS TUDO PARA MIM,\nSOU HERDEIRO DE UM REINO,\nDE UM REINO QUE É SEM FIM.\n\nCORO\nEU TE AMO, MEU JESUS, POIS ABRISTE PARA MIM\nA PORTA DO JARDIM DA VIDA QUE É SEM FIM;\nA MINH''ALMA CANTA AGORA O AMOR \nQUE VIVE EM MIM, POIS MUDASTE O MEU SER,\nNÃO MAIS EU, CRISTO EM MIM. (3X)', 'EU TE AMO, MEU JESUS,\nPOIS TU ÉS O REMIDOR,\nRESGATASTE A MINHA ALMA\nDA TRISTEZA E DA DOR,\nEU TE AMO, MEU JESUS,\nCOMO É FORTE O MEU AMOR,\nALEGRASTE A MINHA ALMA\nCOM TUA PAZ E O TEU AMOR.\n\n<coro>\nEU TE AMO, MEU JESUS, POIS ABRISTE PARA MIM\nA PORTA DO JARDIM DA VIDA QUE É SEM FIM;\nA MINH''ALMA CANTA AGORA O AMOR \nQUE VIVE EM MIM, POIS MUDASTE O MEU SER,\nNÃO MAIS EU, CRISTO EM MIM.\n<instrumentos>\n\n\nEU TE AMO, MEU JESUS,\nPOIS TU ÉS O MEU PASTOR,\nLEVA-ME COM ALEGRIA\nAO BANQUETE DO AMOR;\nA MINH''ALMA REJUBILA\nPOIS ÉS TUDO PARA MIM,\nSOU HERDEIRO DE UM REINO,\nDE UM REINO QUE É SEM FIM.\n\n<coro>\nEU TE AMO, MEU JESUS, POIS ABRISTE PARA MIM\nA PORTA DO JARDIM DA VIDA QUE É SEM FIM;\nA MINH''ALMA CANTA AGORA O AMOR \nQUE VIVE EM MIM, POIS MUDASTE O MEU SER,\nNÃO MAIS EU, CRISTO EM MIM. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (585, 'FONTE DA VIDA', 'FONTE DA VIDA', 'FONTE DA VIDA, ESTRELA DA MANHÃ,\nJESUS, O REI DOS REIS,\nSENHOR, EMANUEL!\nCORDEIRO DE DEUS, O LEÃO DE JUDÁ,\nCRISTO JESUS.\n\nTE ADORAMOS POIS TU ESTÁS AQUI,\nOS NOSSOS CORAÇÕES ESTÃO CHEIOS DE LOUVOR;\nTU ÉS TUDO PRA NÓS, TU ÉS O SENHOR,\nCRISTO JESUS. CRISTO JESUS.', 'FONTE DA VIDA, ESTRELA DA MANHÃ,\nJESUS, O REI DOS REIS,\nSENHOR, EMANUEL!\nCORDEIRO DE DEUS, O LEÃO DE JUDÁ,\nCRISTO JESUS.\n\nTE ADORAMOS POIS TU ESTÁS AQUI,\nOS NOSSOS CORAÇÕES ESTÃO CHEIOS DE LOUVOR;\nTU ÉS TUDO PRA NÓS, TU ÉS O SENHOR,<bis>\nCRISTO JESUS. CRISTO JESUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (586, 'Ó PROFUNDIDADE DAS RIQUEZAS', 'Ó PROFUNDIDADE DAS RIQUEZAS', 'Ó PROFUNDIDADE DAS RIQUEZAS, \nTANTO DA SABEDORIA \nCOMO DO CONHECIMENTO DE DEUS, \nQUÃO INSONDÁVEIS SÃO SEUS JUÍZOS, \nQUÃO INESCRUTÁVEIS OS SEUS CAMINHOS!\n\nINSTRUMENTOS\n\nAH! POR QUE QUEM COMPREENDEU\nOS INTENTOS DO SENHOR?\nOU QUEM FOI SEU CONSELHEIRO?\nOU QUEM LHE DEU PRIMEIRO A ELE?\nPRA QUE LHE SEJA RECOMPENSADO.\n\nPORQUE DELE E POR ELE \nE PARA ELE SÃO TODAS AS COISAS;\nGLÓRIA, GLÓRIA, GLÓRIA POIS \nA ELE ETERNAMENTE, AMÉM.\n\nFINAL: AMÉM!', 'Ó PROFUNDIDADE DAS RIQUEZAS, \nTANTO DA SABEDORIA \nCOMO DO CONHECIMENTO DE DEUS, \nQUÃO INSONDÁVEIS SÃO SEUS JUÍZOS, \nQUÃO INESCRUTÁVEIS OS SEUS CAMINHOS!\n<instrumentos>\n\n\nAH! POR QUE QUEM COMPREENDEU\nOS INTENTOS DO SENHOR?\nOU QUEM FOI SEU CONSELHEIRO?\nOU QUEM LHE DEU PRIMEIRO A ELE?\nPRA QUE LHE SEJA RECOMPENSADO.\n\nPORQUE DELE E POR ELE <bis>\nE PARA ELE SÃO TODAS AS COISAS;<bis>\nGLÓRIA, GLÓRIA, GLÓRIA POIS <bis>\nA ELE ETERNAMENTE, AMÉM.<bis>\n<final>AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (587, 'Ó JESUS, EXALTAR-TE-EI', 'Ó JESUS, EXALTAR-TE-EI', 'Ó JESUS, EXALTAR-TE-EI!\nÓ JESUS, EXALTAR-TE-EI!\n\nA MINH''ALMA TE ENALTECE,\nA MINH''ALMA E TODO O MEU SER\nTE GLORIFICAM.\n\nÓ JESUS, EXALTAR-TE-EI!\nÓ JESUS, EXALTAR-TE-EI!\n\nA MINH''ALMA TE ENALTECE,\nA MINH''ALMA E TODO O MEU \nSER TE GLORIFICAM.', 'Ó JESUS, EXALTAR-TE-EI!\nÓ JESUS, EXALTAR-TE-EI!\n\nA MINH''ALMA TE ENALTECE,\nA MINH''ALMA E TODO O MEU SER\nTE GLORIFICAM.\n\nÓ JESUS, EXALTAR-TE-EI!\nÓ JESUS, EXALTAR-TE-EI!\n\nA MINH''ALMA TE ENALTECE,<bis>\nA MINH''ALMA E TODO O MEU <bis>\nSER TE GLORIFICAM.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (588, 'HÁ UM NOME QUE RELUZ', 'HÁ UM NOME QUE RELUZ', 'HÁ UM NOME QUE RELUZ\nMAIS QUE MIL SÓIS EM SEU FULGOR,\nSERES CELESTIAIS SE INCLINAM \nDIANTE DELE COM TEMOR;\nNEM MIL ANOS BASTARIAM\nEM MIL CANTOS DE LOUVOR\nPARA CELEBRAR A GLÓRIA DE JESUS!\n\nFOI NA CRUZ QUE POR SEU SANGUE\nPRINCIPADOS DESPOJOU, \nFOI NA CRUZ QUE A MALDIÇÃO DA LEI \nPOR NÓS ALI CRAVOU;\nAO TERCEIRO DIA A MORTE \nPARA SEMPRE CONQUISTOU, \nOH! QUE GLÓRIA \nTEM O NOME DE JESUS!\n\nCORO\nNOME SANTO DE JESUS, \nO MISTÉRIO REVELADO LÁ NA CRUZ, \nO QUE PRÍNCIPES E SÁBIOS \nNÃO PUDERAM ENTENDER\nTEMOS PELA FÉ NO NOME DE JESUS!\n\nAO SEU NOME OBEDECE TUDO \nO QUE HÁ NA CRIAÇÃO, \nA UMA SÓ PALAVRA SUA\nCESSA TODA A OPOSIÇÃO;\nAQUI HOJE PROCLAMAMOS \nA ETERNA SALVAÇÃO, \nHAJA PAZ E CURA EM NOME DE JESUS!\n\nCORO\nNOME SANTO DE JESUS, \nO MISTÉRIO REVELADO LÁ NA CRUZ, \nO QUE PRÍNCIPES E SÁBIOS \nNÃO PUDERAM ENTENDER\nTEMOS PELA FÉ NO NOME DE JESUS!', 'HÁ UM NOME QUE RELUZ\nMAIS QUE MIL SÓIS EM SEU FULGOR,\nSERES CELESTIAIS SE INCLINAM \nDIANTE DELE COM TEMOR;\nNEM MIL ANOS BASTARIAM\nEM MIL CANTOS DE LOUVOR\nPARA CELEBRAR A GLÓRIA DE JESUS!\n\nFOI NA CRUZ QUE POR SEU SANGUE\nPRINCIPADOS DESPOJOU, \nFOI NA CRUZ QUE A MALDIÇÃO DA LEI \nPOR NÓS ALI CRAVOU;\nAO TERCEIRO DIA A MORTE \nPARA SEMPRE CONQUISTOU, \nOH! QUE GLÓRIA \nTEM O NOME DE JESUS!\n\n<coro>\nNOME SANTO DE JESUS, \nO MISTÉRIO REVELADO LÁ NA CRUZ, \nO QUE PRÍNCIPES E SÁBIOS \nNÃO PUDERAM ENTENDER\nTEMOS PELA FÉ NO NOME DE JESUS!\n\nAO SEU NOME OBEDECE TUDO \nO QUE HÁ NA CRIAÇÃO, \nA UMA SÓ PALAVRA SUA\nCESSA TODA A OPOSIÇÃO;\nAQUI HOJE PROCLAMAMOS \nA ETERNA SALVAÇÃO, \nHAJA PAZ E CURA EM NOME DE JESUS!\n\n<coro>\nNOME SANTO DE JESUS, \nO MISTÉRIO REVELADO LÁ NA CRUZ, \nO QUE PRÍNCIPES E SÁBIOS \nNÃO PUDERAM ENTENDER\nTEMOS PELA FÉ NO NOME DE JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (589, 'JESUS TÃO BELO', 'JESUS TÃO BELO', 'JESUS TÃO BELO, Ó REI DA TERRA,\nNASCESTE IGUAL A DEUS SENHOR,\nÉS DE MINH''ALMA, SOL, ALEGRIA,\nCOROA, GLÓRIA, LUZ, AMOR.\n\nDOS CÉUS A GLÓRIA, A MAJESTADE,\nEM TI, SENHOR, EU POSSO VER,\nDE MIM MAIS PERTO OU MAIS QUERIDO,\nÓ MEU JESUS, NINGUÉM VOU TER.\n\nJESUS AMADO, Ó REI GLORIOSO,\nAO PECADOR SÓ QUERES BEM,\nPOIS SEJA SEMPRE, \nLOUVOR E GLÓRIA A TI, \nÓ SALVADOR, AMÉM.', 'JESUS TÃO BELO, Ó REI DA TERRA,\nNASCESTE IGUAL A DEUS SENHOR,\nÉS DE MINH''ALMA, SOL, ALEGRIA,\nCOROA, GLÓRIA, LUZ, AMOR.\n\nDOS CÉUS A GLÓRIA, A MAJESTADE,\nEM TI, SENHOR, EU POSSO VER,\nDE MIM MAIS PERTO OU MAIS QUERIDO,\nÓ MEU JESUS, NINGUÉM VOU TER.\n\nJESUS AMADO, Ó REI GLORIOSO,\nAO PECADOR SÓ QUERES BEM,\nPOIS SEJA SEMPRE, \nLOUVOR E GLÓRIA A TI, \nÓ SALVADOR, AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (590, 'AO CORDEIRO', 'AO CORDEIRO', 'AO CORDEIRO QUE FOI MORTO\nE DA MORTE É VENCEDOR,\nAO QUE É SANTO, SANTO, SANTO,\nTRIUNFANTE REDENTOR,\nTODA HONRA, TODA GLÓRIA,\nPARA TODO O SEMPRE DAI,\nHOMENS E ANJOS, ADORAI O REI!\nADORAI!\n\nINSTRUMENTOS\n\nAO CORDEIRO QUE FOI MORTO\nE DA MORTE É VENCEDOR,\nAO QUE É SANTO, SANTO, SANTO,\nTRIUNFANTE REDENTOR,\nTODA HONRA, TODA GLÓRIA,\nPARA TODO O SEMPRE DAI,\nHOMENS E ANJOS, ADORAI O REI!\nADORAI!', 'AO CORDEIRO QUE FOI MORTO\nE DA MORTE É VENCEDOR,\nAO QUE É SANTO, SANTO, SANTO,\nTRIUNFANTE REDENTOR,\nTODA HONRA, TODA GLÓRIA,\nPARA TODO O SEMPRE DAI,\nHOMENS E ANJOS, ADORAI O REI!\nADORAI!\n<instrumentos>\n\n\nAO CORDEIRO QUE FOI MORTO\nE DA MORTE É VENCEDOR,\nAO QUE É SANTO, SANTO, SANTO,\nTRIUNFANTE REDENTOR,\nTODA HONRA, TODA GLÓRIA,\nPARA TODO O SEMPRE DAI,\nHOMENS E ANJOS, ADORAI O REI!\nADORAI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (591, 'GLÓRIA PRA SEMPRE AO CORDEIRO DE DEUS', 'GLÓRIA PRA SEMPRE AO CORDEIRO DE DEUS', 'GLÓRIA PRA SEMPRE \nAO CORDEIRO DE DEUS, \nA JESUS, O SENHOR, \nAO LEÃO DE JUDÁ,\nÀ RAIZ DE DAVI QUE VENCEU\nE O LIVRO ABRIRÁ.\n\nO CÉU, A TERRA E O MAR,\nE TUDO O QUE NELES HÁ,\nO ADORARÃO E CONFESSARÃO:\nJESUS CRISTO É O SENHOR.\n\nELE É O SENHOR, ELE É O SENHOR;\nRESSURRETO DENTRE OS MORTOS,\nELE É O SENHOR;\nTODO JOELHO SE DOBRARÁ,\nTODA LÍNGUA CONFESSARÁ\nQUE JESUS CRISTO É O SENHOR.\n\nGLÓRIA PRA SEMPRE AO CORDEIRO \nDE DEUS, A JESUS, O SENHOR, \nAO LEÃO DE JUDÁ,\nÀ RAIZ DE DAVI QUE VENCEU\nE O LIVRO ABRIRÁ.\n\nO CÉU, A TERRA E O MAR,\nE TUDO O QUE NELES HÁ,\nO ADORARÃO E CONFESSARÃO:\nJESUS CRISTO É O SENHOR.', 'GLÓRIA PRA SEMPRE \nAO CORDEIRO DE DEUS, \nA JESUS, O SENHOR, \nAO LEÃO DE JUDÁ,\nÀ RAIZ DE DAVI QUE VENCEU\nE O LIVRO ABRIRÁ.\n\nO CÉU, A TERRA E O MAR,\nE TUDO O QUE NELES HÁ,\nO ADORARÃO E CONFESSARÃO:\nJESUS CRISTO É O SENHOR.\n\nELE É O SENHOR, ELE É O SENHOR;\nRESSURRETO DENTRE OS MORTOS,\nELE É O SENHOR;\nTODO JOELHO SE DOBRARÁ,\nTODA LÍNGUA CONFESSARÁ\nQUE JESUS CRISTO É O SENHOR.\n\nGLÓRIA PRA SEMPRE AO CORDEIRO \nDE DEUS, A JESUS, O SENHOR, \nAO LEÃO DE JUDÁ,\nÀ RAIZ DE DAVI QUE VENCEU\nE O LIVRO ABRIRÁ.\n\nO CÉU, A TERRA E O MAR,\nE TUDO O QUE NELES HÁ,\nO ADORARÃO E CONFESSARÃO:\nJESUS CRISTO É O SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (592, 'ALELUIA! MUITAS VOZES DE ANJOS', 'ALELUIA! MUITAS VOZES DE ANJOS', 'ALELUIA!\nMUITAS VOZES DE ANJOS EXALTAM \nO NOME DO CORDEIRO VIVO, JESUS;\nAQUELE QUE UM DIA NA AMARGA \nCRUZ MORREU COMO PROVA DE AMOR.\n\nCORO\nE SÓ ELE É DIGNO DE TODO O LOUVOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO REDENTOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO SALVADOR!\n\nINSTRUMENTOS\n\nALELUIA! NÓS TAMBÉM ESTAREMOS \nNAS LINDAS MANSÕES \nLOUVANDO PRA SEMPRE AO SENHOR;\nE COM GRANDE ALEGRIA VEREMOS JESUS, \nQUE DIA TÃO LINDO SERÁ.\n\nCORO\nE SÓ ELE É DIGNO DE TODO O LOUVOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO REDENTOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO SALVADOR! (2X)', 'ALELUIA!\nMUITAS VOZES DE ANJOS EXALTAM \nO NOME DO CORDEIRO VIVO, JESUS;\nAQUELE QUE UM DIA NA AMARGA \nCRUZ MORREU COMO PROVA DE AMOR.\n\n<coro>\nE SÓ ELE É DIGNO DE TODO O LOUVOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO REDENTOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO SALVADOR!\n<instrumentos>\n\n\nALELUIA! NÓS TAMBÉM ESTAREMOS \nNAS LINDAS MANSÕES \nLOUVANDO PRA SEMPRE AO SENHOR;\nE COM GRANDE ALEGRIA VEREMOS JESUS, \nQUE DIA TÃO LINDO SERÁ.\n\n<coro>\nE SÓ ELE É DIGNO DE TODO O LOUVOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO REDENTOR!\nGLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,\nGLÓRIA AO SALVADOR! <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (593, 'A CRISTO COROAI', 'A CRISTO COROAI', 'A CRISTO COROAI, CORDEIRO VENCEDOR!\nOUVI, DAS HOSTES CELESTIAIS\nDOS ANJOS, O LOUVOR!\nELEVA A TUA VOZ\nE ENTOA, CORAÇÃO,\nLOUVANDO AQUELE QUE MORREU\nE DEU-TE A SALVAÇÃO.\n\nA CRISTO COROAI, SEU LADO E MÃOS OLHAI!\nDAS SUAS CHAGAS O ESPLENDOR\nE A GLÓRIA CONTEMPLAI;\nNEM ANJOS LÁ DO CÉU\nO PODEM SUPORTAR,\nPERANTE O EXCELSO ESPLENDOR\nABAIXAM SEU OLHAR.\n\nA CRISTO COROAI, A VIDA NOS DOOU!\nE, A FIM DE DAR-NOS SALVAÇÃO,\nDA MORTE TRIUNFOU.\nCANTEMOS SEU PODER;\nMORREU, MAS RESSURGIU,\nA VIDA ETERNA ALI NOS DEU\nE A MORTE DESTRUIU.\n\nA CRISTO COROAI, DAS ERAS, O SENHOR!\nDOS MUNDOS E ASTROS DA AMPLIDÃO\nETERNO CRIADOR!\nAO GRANDE REDENTOR,\nQUE NOS DEU SALVAÇÃO,\nETERNAMENTE TRIBUTAI\nLOUVOR E ADORAÇÃO.', 'A CRISTO COROAI, CORDEIRO VENCEDOR!\nOUVI, DAS HOSTES CELESTIAIS\nDOS ANJOS, O LOUVOR!\nELEVA A TUA VOZ\nE ENTOA, CORAÇÃO,\nLOUVANDO AQUELE QUE MORREU\nE DEU-TE A SALVAÇÃO.\n\nA CRISTO COROAI, SEU LADO E MÃOS OLHAI!\nDAS SUAS CHAGAS O ESPLENDOR\nE A GLÓRIA CONTEMPLAI;\nNEM ANJOS LÁ DO CÉU\nO PODEM SUPORTAR,\nPERANTE O EXCELSO ESPLENDOR\nABAIXAM SEU OLHAR.\n\nA CRISTO COROAI, A VIDA NOS DOOU!\nE, A FIM DE DAR-NOS SALVAÇÃO,\nDA MORTE TRIUNFOU.\nCANTEMOS SEU PODER;\nMORREU, MAS RESSURGIU,\nA VIDA ETERNA ALI NOS DEU\nE A MORTE DESTRUIU.\n\nA CRISTO COROAI, DAS ERAS, O SENHOR!\nDOS MUNDOS E ASTROS DA AMPLIDÃO\nETERNO CRIADOR!\nAO GRANDE REDENTOR,\nQUE NOS DEU SALVAÇÃO,\nETERNAMENTE TRIBUTAI\nLOUVOR E ADORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (594, 'NA EXPRESSÃO DESTE LOUVOR', 'NA EXPRESSÃO DESTE LOUVOR', 'NA EXPRESSÃO DESTE LOUVOR\nQUERO DAR AO MEU SENHOR\nTODA A MINHA GRATIDÃO\nPOR SER MUI FELIZ.\n\nDEVO MUITO AO SALVADOR,\nNELE TENHO O PERDÃO,\nNELE TENHO A SALVAÇÃO,\nEU SOU TÃO FELIZ.\n\nCORO\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE VENCESTE NA CRUZ,\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE TU HÁS DE VOLTAR;\nNÓS TE ADORAMOS, MEU SENHOR,\nPOIS TU ÉS A RAZÃO\nE O MOTIVO DA NOSSA ADORAÇÃO.\n\nLÁ NA CRUZ MORREU JESUS,\nO SEU SANGUE DERRAMOU,\nO MEU FARDO ELE LEVOU\nE HOJE LIVRE SOU.\n\nCORO (2X)\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE VENCESTE NA CRUZ,\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE TU HÁS DE VOLTAR;\nNÓS TE ADORAMOS, MEU SENHOR,\nPOIS TU ÉS A RAZÃO\nE O MOTIVO DA NOSSA ADORAÇÃO.', 'NA EXPRESSÃO DESTE LOUVOR\nQUERO DAR AO MEU SENHOR\nTODA A MINHA GRATIDÃO\nPOR SER MUI FELIZ.\n\nDEVO MUITO AO SALVADOR,\nNELE TENHO O PERDÃO,\nNELE TENHO A SALVAÇÃO,\nEU SOU TÃO FELIZ.\n\n<coro>\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE VENCESTE NA CRUZ,\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE TU HÁS DE VOLTAR;\nNÓS TE ADORAMOS, MEU SENHOR,\nPOIS TU ÉS A RAZÃO\nE O MOTIVO DA NOSSA ADORAÇÃO.\n\nLÁ NA CRUZ MORREU JESUS,\nO SEU SANGUE DERRAMOU,\nO MEU FARDO ELE LEVOU\nE HOJE LIVRE SOU.\n\n<coro tipo=''2X''>\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE VENCESTE NA CRUZ,\nNÓS TE ADORAMOS, MEU SENHOR,\nPORQUE TU HÁS DE VOLTAR;\nNÓS TE ADORAMOS, MEU SENHOR,\nPOIS TU ÉS A RAZÃO\nE O MOTIVO DA NOSSA ADORAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (595, 'MAJESTADE, GLÓRIA E MAJESTADE', 'MAJESTADE, GLÓRIA E MAJESTADE', 'MAJESTADE, GLÓRIA E MAJESTADE,\nJESUS CRISTO MERECE TODO LOUVOR;\nMAJESTADE, GLÓRIA E MAJESTADE, \nSEU É O LOUVOR, \nSEU É O PODER GLÓRIA A ELE!\n\nEXALTAI, ENGRANDECEI SEU SANTO NOME!\nADORAI, MAGNIFICAI A CRISTO REI!\nMAJESTADE, GLÓRIA E MAJESTADE, \nCRISTO MORREU, \nRESSUSCITOU E HOJE É SENHOR.', 'MAJESTADE, GLÓRIA E MAJESTADE,\nJESUS CRISTO MERECE TODO LOUVOR;\nMAJESTADE, GLÓRIA E MAJESTADE, \nSEU É O LOUVOR, \nSEU É O PODER GLÓRIA A ELE!\n\nEXALTAI, ENGRANDECEI SEU SANTO NOME!\nADORAI, MAGNIFICAI A CRISTO REI!\nMAJESTADE, GLÓRIA E MAJESTADE, \nCRISTO MORREU, \nRESSUSCITOU E HOJE É SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (596, 'ÉS MAJESTADE', 'ÉS MAJESTADE', 'ÉS MAJESTADE, Ó REI DA GLÓRIA,\nÉS O SENHOR, O REI DOS REIS;\nTUA É SENHOR A MAGNIFICÊNCIA\nE O PODER E A HONRA E A VITÓRIA.\n\nCORO (2X)\nJESUS, JESUS, ÉS O SENHOR,\nO REI DOS REIS. \n\nDIGNO ÉS DE ABRIR O LIVRO DA VIDA,\nDIGNO É O CORDEIRO QUE FOI MORTO\nDE RECEBER PODER E RIQUEZAS,\nSABEDORIA, GLÓRIA E LOUVOR.\n\nCORO (2X)\nJESUS, JESUS, ÉS O SENHOR,\nO REI DOS REIS.', 'ÉS MAJESTADE, Ó REI DA GLÓRIA,\nÉS O SENHOR, O REI DOS REIS;\nTUA É SENHOR A MAGNIFICÊNCIA\nE O PODER E A HONRA E A VITÓRIA.<coro tipo=''2X''>\nJESUS, JESUS, ÉS O SENHOR,\nO REI DOS REIS. \n\nDIGNO ÉS DE ABRIR O LIVRO DA VIDA,\nDIGNO É O CORDEIRO QUE FOI MORTO\nDE RECEBER PODER E RIQUEZAS,\nSABEDORIA, GLÓRIA E LOUVOR.<coro tipo=''2X''>\nJESUS, JESUS, ÉS O SENHOR,\nO REI DOS REIS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (597, 'CANTAREI, CANTAREI HOSANA (VIVA O REI)', 'CANTAREI, CANTAREI HOSANA (VIVA O REI)', 'CANTAREI, CANTAREI HOSANA,\nCANTAREI HOSANA AO SALVADOR;\nLOUVAREI SEU SANTO NOME \nE COM TODA ALEGRIA NO CÉU OUVIREI:\n\nCORO\nAS VOZES DE MILHÕES DE ANJOS CANTANDO,\nCOM TODOS OS FIÉIS FALAREI:\nVIVA O REI, VIVA O REI, \nVIVA O REI JESUS!\n\nENTRAREI NO SANTO DOS SANTOS\nCOM UM CÂNTICO NOVO DE GRATIDÃO;\nVIVEREI PRA SEMPRE NA GLÓRIA,\nLOUVANDO A JESUS E LÁ OUVIREI:\n\nCORO \nAS VOZES DE MILHÕES DE ANJOS CANTANDO,\nCOM TODOS OS FIÉIS FALAREI: \nVIVA O REI, VIVA O REI, \nVIVA O REI JESUS!\n\nGOZO, PAZ, PERFEITO AMOR,\nPLENA ALEGRIA NO MEU SENHOR;\nESTE MUNDO DEIXAREI, NA LINDA PÁTRIA \nBREVE ESTAREI E OUVIREI:\n\nCORO (2X)\nAS VOZES DE MILHÕES DE ANJOS CANTANDO,\nCOM TODOS OS FIÉIS FALAREI: \nVIVA O REI, VIVA O REI, \nVIVA O REI JESUS!', 'CANTAREI, CANTAREI HOSANA,\nCANTAREI HOSANA AO SALVADOR;\nLOUVAREI SEU SANTO NOME \nE COM TODA ALEGRIA NO CÉU OUVIREI:\n\n<coro>\nAS VOZES DE MILHÕES DE ANJOS CANTANDO,\nCOM TODOS OS FIÉIS FALAREI:\nVIVA O REI, VIVA O REI, \nVIVA O REI JESUS!\n\nENTRAREI NO SANTO DOS SANTOS\nCOM UM CÂNTICO NOVO DE GRATIDÃO;\nVIVEREI PRA SEMPRE NA GLÓRIA,\nLOUVANDO A JESUS E LÁ OUVIREI:\n\n<coro>\nAS VOZES DE MILHÕES DE ANJOS CANTANDO,\nCOM TODOS OS FIÉIS FALAREI: \nVIVA O REI, VIVA O REI, \nVIVA O REI JESUS!\n\nGOZO, PAZ, PERFEITO AMOR,\nPLENA ALEGRIA NO MEU SENHOR;\nESTE MUNDO DEIXAREI, NA LINDA PÁTRIA \nBREVE ESTAREI E OUVIREI:\n\n<coro tipo=''2X''>\nAS VOZES DE MILHÕES DE ANJOS CANTANDO,\nCOM TODOS OS FIÉIS FALAREI: \nVIVA O REI, VIVA O REI, \nVIVA O REI JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (598, 'HÁ UM SÓ QUE É DIGNO', 'HÁ UM SÓ QUE É DIGNO', 'HÁ UM SÓ QUE É DIGNO \nDE SOBRE NÓS REINAR \nE NO TRONO DE DAVI COM GLÓRIA SE SENTAR;\nO QUE ELE FALA PRA NÓS É SANTA LEI,\nA ELE ACLAMAMOS: VIVA O NOSSO REI!\n\nCORO\nVIVA O REI! VIVA O REI! \nO FILHO DE DAVI, O LEÃO DE JUDÁ,\nO REI DOS REIS QUE BREVE VOLTARÁ.\n\nMUITOS SE LEVANTAM QUERENDO SE IMPOR, \nCOM SEUS VÃOS PROJETOS, \nAO POVO DO SENHOR;\nMAS DEUS TEM SUA OBRA E NELA SERVIREI; \nFRACO SOU, MAS CLAMO: \nVIVA O NOSSO REI!\n\nCORO\nVIVA O REI! VIVA O REI! \nO FILHO DE DAVI, O LEÃO DE JUDÁ,\nO REI DOS REIS QUE BREVE VOLTARÁ.\n\nEIS AQUI QUEM REINA, \nMAIOR QUE SALOMÃO, COMO ESPADA AGUDA \nSÃO OS CONSELHOS SEUS;\nE A NÓS, IGREJA, DEU GRAÇA E SALVAÇÃO\nFEZ-NOS SEUS VALENTES, EXÉRCITO DE DEUS.\n\nCORO\nVIVA O REI! VIVA O REI! \nO FILHO DE DAVI, O LEÃO DE JUDÁ,\nO REI DOS REIS QUE BREVE VOLTARÁ.', 'HÁ UM SÓ QUE É DIGNO \nDE SOBRE NÓS REINAR \nE NO TRONO DE DAVI COM GLÓRIA SE SENTAR;\nO QUE ELE FALA PRA NÓS É SANTA LEI,\nA ELE ACLAMAMOS: VIVA O NOSSO REI!\n\n<coro>\nVIVA O REI! VIVA O REI! \nO FILHO DE DAVI, O LEÃO DE JUDÁ,\nO REI DOS REIS QUE BREVE VOLTARÁ.\n\nMUITOS SE LEVANTAM QUERENDO SE IMPOR, \nCOM SEUS VÃOS PROJETOS, \nAO POVO DO SENHOR;\nMAS DEUS TEM SUA OBRA E NELA SERVIREI; \nFRACO SOU, MAS CLAMO: \nVIVA O NOSSO REI!\n\n<coro>\nVIVA O REI! VIVA O REI! \nO FILHO DE DAVI, O LEÃO DE JUDÁ,\nO REI DOS REIS QUE BREVE VOLTARÁ.\n\nEIS AQUI QUEM REINA, \nMAIOR QUE SALOMÃO, COMO ESPADA AGUDA \nSÃO OS CONSELHOS SEUS;\nE A NÓS, IGREJA, DEU GRAÇA E SALVAÇÃO\nFEZ-NOS SEUS VALENTES, EXÉRCITO DE DEUS.\n\n<coro>\nVIVA O REI! VIVA O REI! \nO FILHO DE DAVI, O LEÃO DE JUDÁ,\nO REI DOS REIS QUE BREVE VOLTARÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (599, 'JESUS, TE ENTRONIZAMOS AQUI ENTRE NÓS', 'JESUS, TE ENTRONIZAMOS AQUI ENTRE NÓS', 'JESUS, TE ENTRONIZAMOS AQUI ENTRE NÓS \nPARA TRIBUTARMOS NOSSA ADORAÇÃO;\nA TI RENDEMOS GLÓRIA, HONRA E LOUVOR, EXPRESSÃO DE TODA A GRATIDÃO.\n\nCORO\nCOROAMOS A CRISTO,\n(COROAMOS A CRISTO NOSSO REI) VARÕES\nELE É O NOSSO REI, SIM, O NOSSO REI;\nERGUEMOS AS VOZES EM CORO,\n(HOSANA A TI, JESUS) VARÕES\nCANTANDO HOSANA A JESUS,\nE OS ANJOS PROCLAMAM NO CÉU: VIVA O REI.\n\nINSTRUMENTOS\n\nTU ÉS DEUS FILHO, O VERBO CRIADOR,\nESTÁS REVESTIDO DE GLÓRIA E ESPLENDOR;\nSANTO, SANTO, SANTO, ÉS TU, JESUS,\nTODA HONRA SEJA PARA TI.\n\nCORO (2X)\nCOROAMOS A CRISTO,\n(COROAMOS A CRISTO NOSSO REI) VARÕES\nELE É O NOSSO REI, SIM, O NOSSO REI;\nERGUEMOS AS VOZES EM CORO,\n(HOSANA A TI, JESUS) VARÕES\nCANTANDO HOSANA A JESUS,\nE OS ANJOS PROCLAMAM NO CÉU: VIVA O REI.\n\nFINAL: VIVA O REI.', 'JESUS, TE ENTRONIZAMOS AQUI ENTRE NÓS \nPARA TRIBUTARMOS NOSSA ADORAÇÃO;\nA TI RENDEMOS GLÓRIA, HONRA E LOUVOR, EXPRESSÃO DE TODA A GRATIDÃO.\n\n<coro>\nCOROAMOS A CRISTO,\n(COROAMOS A CRISTO NOSSO REI) <h>\nELE É O NOSSO REI, SIM, O NOSSO REI;\nERGUEMOS AS VOZES EM CORO,\n(HOSANA A TI, JESUS) <h>\nCANTANDO HOSANA A JESUS,\nE OS ANJOS PROCLAMAM NO CÉU: VIVA O REI.\n<instrumentos>\n\n\nTU ÉS DEUS FILHO, O VERBO CRIADOR,\nESTÁS REVESTIDO DE GLÓRIA E ESPLENDOR;\nSANTO, SANTO, SANTO, ÉS TU, JESUS,\nTODA HONRA SEJA PARA TI.\n\n<coro tipo=''2X''>\nCOROAMOS A CRISTO,\n(COROAMOS A CRISTO NOSSO REI) <h>\nELE É O NOSSO REI, SIM, O NOSSO REI;\nERGUEMOS AS VOZES EM CORO,\n(HOSANA A TI, JESUS) <h>\nCANTANDO HOSANA A JESUS,\nE OS ANJOS PROCLAMAM NO CÉU: VIVA O REI.\n<final>VIVA O REI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (600, 'JESUS, TE ENTRONIZAMOS', 'JESUS, TE ENTRONIZAMOS', 'JESUS, TE ENTRONIZAMOS,\nDECLARAMOS QUE ÉS REI,\nTU ESTÁS NO MEIO DE NÓS,\nTE EXALTAMOS COM LOUVORES.\n\nA TI FAZEMOS UM TRONO DE LOUVORES (3X)\nÓ VEM, JESUS, E TOMA O TEU LUGAR,\nÓ VEM, JESUS, E TOMA O TEU LUGAR.\n\nINSTRUMENTOS\n\nJESUS, TE ENTRONIZAMOS,\nDECLARAMOS QUE ÉS REI,\nTU ESTÁS NO MEIO DE NÓS,\nTE EXALTAMOS COM LOUVORES.\n\nA TI FAZEMOS UM TRONO DE LOUVORES, (3X)\nÓ VEM, JESUS, E TOMA O TEU LUGAR,\nÓ VEM, JESUS, E TOMA O TEU LUGAR.\n\nFINAL: \nÓ VEM, JESUS, E TOMA O TEU LUGAR.', 'JESUS, TE ENTRONIZAMOS,\nDECLARAMOS QUE ÉS REI,\nTU ESTÁS NO MEIO DE NÓS,\nTE EXALTAMOS COM LOUVORES.\n\nA TI FAZEMOS UM TRONO DE LOUVORES <bis tipo=''3''>\nÓ VEM, JESUS, E TOMA O TEU LUGAR,\nÓ VEM, JESUS, E TOMA O TEU LUGAR.\n<instrumentos>\n\n\nJESUS, TE ENTRONIZAMOS,\nDECLARAMOS QUE ÉS REI,\nTU ESTÁS NO MEIO DE NÓS,\nTE EXALTAMOS COM LOUVORES.\n\nA TI FAZEMOS UM TRONO DE LOUVORES, <bis tipo=''3''>\nÓ VEM, JESUS, E TOMA O TEU LUGAR,\nÓ VEM, JESUS, E TOMA O TEU LUGAR.\n<final>Ó VEM, JESUS, E TOMA O TEU LUGAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (601, 'AO QUE ESTÁ NO TRONO', 'AO QUE ESTÁ NO TRONO', 'AO QUE ESTÁ NO TRONO ENTRE OS QUERUBINS, \nAO QUE RESPLANDECE E É FOGO CONSUMIDOR;\nDIANTE DELE VOAM ANJOS, SERAFINS \nQUE SEUS ROSTOS COBREM PERANTE \nA FACE DO SENHOR.\n\nCORO\nGLÓRIA, FORÇA, GRAÇA E PODER,\nSABEDORIA, HONRA E LOUVOR\n\nAO CORDEIRO MORTO QUE RESSUSCITOU \nE QUE AO CÉU SUBIU,\nAO REI QUE TÃO BREVE VEM;\nÀ PALAVRA VIVA QUE SE REVELOU,\nÀ LUZ QUE ILUMINA A NOVA JERUSALÉM.\n\nCORO (2X)\nGLÓRIA, FORÇA, GRAÇA E PODER,\nSABEDORIA, HONRA E LOUVOR\n\nFINAL: \nSANTO É O SENHOR! (3X)', 'AO QUE ESTÁ NO TRONO ENTRE OS QUERUBINS, \nAO QUE RESPLANDECE E É FOGO CONSUMIDOR;\nDIANTE DELE VOAM ANJOS, SERAFINS \nQUE SEUS ROSTOS COBREM PERANTE \nA FACE DO SENHOR.\n\n<coro>\nGLÓRIA, FORÇA, GRAÇA E PODER,\nSABEDORIA, HONRA E LOUVOR\n\nAO CORDEIRO MORTO QUE RESSUSCITOU \nE QUE AO CÉU SUBIU,\nAO REI QUE TÃO BREVE VEM;\nÀ PALAVRA VIVA QUE SE REVELOU,\nÀ LUZ QUE ILUMINA A NOVA JERUSALÉM.\n\n<coro tipo=''2X''>\nGLÓRIA, FORÇA, GRAÇA E PODER,\nSABEDORIA, HONRA E LOUVOR\n<final>SANTO É O SENHOR! <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (602, 'SANTO É O QUE ESTÁ NO TRONO', 'SANTO É O QUE ESTÁ NO TRONO', 'SANTO, SANTO, SANTO\nÉ O QUE ESTÁ NO TRONO,\nO QUE É REI E SENHOR;\nDIGNO, SÓ ELE É DIGNO\nDE RECEBER A GLÓRIA E LOUVOR! \n\nQUEM É O QUE BRILHA MAIS QUE O SOL?\nÉ O SENHOR! (SERVAS)\nQUEM É O QUE BRAMA COMO O LEÃO? \nÉ O SENHOR! (SERVAS)\nQUEM É O QUE PASSEIA \nENTRE OS SETE CASTIÇAIS? \nÉ O CORDEIRO, É O LEÃO DE JUDÁ! \n\nQUEM É O QUE A MORTE CONQUISTOU? \nÉ O SENHOR! (VARÕES)\nQUEM É O QUE O MUNDO VAI JULGAR? \nÉ O SENHOR! (VARÕES)\nQUEM É O QUE VIRÁ A ESPOSA ARREBATAR? \nÉ O CORDEIRO, É O LEÃO DE JUDÁ. \n\nSANTO, SANTO, SANTO\nÉ O QUE ESTÁ NO TRONO,\nO QUE É REI E SENHOR;\nDIGNO, SÓ ELE É DIGNO\nDE RECEBER A GLÓRIA E LOUVOR! (3X)', 'SANTO, SANTO, SANTO\nÉ O QUE ESTÁ NO TRONO,\nO QUE É REI E SENHOR;\nDIGNO, SÓ ELE É DIGNO\nDE RECEBER A GLÓRIA E LOUVOR! \n\nQUEM É O QUE BRILHA MAIS QUE O SOL?\nÉ O SENHOR! <m>\nQUEM É O QUE BRAMA COMO O LEÃO? \nÉ O SENHOR! <m>\nQUEM É O QUE PASSEIA \nENTRE OS SETE CASTIÇAIS? \nÉ O CORDEIRO, É O LEÃO DE JUDÁ! \n\nQUEM É O QUE A MORTE CONQUISTOU? \nÉ O SENHOR! <h>\nQUEM É O QUE O MUNDO VAI JULGAR? \nÉ O SENHOR! <h>\nQUEM É O QUE VIRÁ A ESPOSA ARREBATAR? \nÉ O CORDEIRO, É O LEÃO DE JUDÁ. \n\nSANTO, SANTO, SANTO\nÉ O QUE ESTÁ NO TRONO,\nO QUE É REI E SENHOR;\nDIGNO, SÓ ELE É DIGNO\nDE RECEBER A GLÓRIA E LOUVOR! <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (603, 'LOUVAREI AO MEU SENHOR', 'LOUVAREI AO MEU SENHOR', 'LOUVAREI AO MEU SENHOR ENQUANTO EU VIVER,\nSEU LOUVOR PRA SEMPRE ESTARÁ COMIGO;\nSUA GRAÇA ME SUSTÉM, SEU AMOR É TÃO PROFUNDO, \nSEU ESPÍRITO ME DÁ FORÇAS PRA LUTAR.\n\nCORO (2X)\nSIM, LOUVAREI AO MEU SENHOR,\nPOIS É DIGNO DE LOUVOR,\nSUA GRAÇA ME SUSTÉM,\nLOUVAREI PRA SEMPRE, AMÉM.\n\nLOUVAREI AO MEU SENHOR,\nSUA GRAÇA ME SALVOU,\n(SIM, LOUVAREI)\nPÔS UM NOVO CÂNTICO EM MEUS LÁBIOS.\n(SIM, LOUVAREI)\nSUA GRAÇA ME SUSTÉM,\nSEU AMOR É TÃO PROFUNDO,\n(SIM, LOUVAREI)\nSEU ESPÍRITO ME DÁ FORÇAS PRA LUTAR.\n\nCORO (2X)\nSIM, LOUVAREI AO MEU SENHOR,\nPOIS É DIGNO DE LOUVOR,\nSUA GRAÇA ME SUSTÉM,\nLOUVAREI PRA SEMPRE, AMÉM.\n\nFINAL: SIM, LOUVAREI.', 'LOUVAREI AO MEU SENHOR ENQUANTO EU VIVER,\nSEU LOUVOR PRA SEMPRE ESTARÁ COMIGO;\nSUA GRAÇA ME SUSTÉM, SEU AMOR É TÃO PROFUNDO, \nSEU ESPÍRITO ME DÁ FORÇAS PRA LUTAR.\n\n<coro tipo=''2X''>\nSIM, LOUVAREI AO MEU SENHOR,\nPOIS É DIGNO DE LOUVOR,\nSUA GRAÇA ME SUSTÉM,\nLOUVAREI PRA SEMPRE, AMÉM.\n\nLOUVAREI AO MEU SENHOR,\nSUA GRAÇA ME SALVOU,\n(SIM, LOUVAREI)\nPÔS UM NOVO CÂNTICO EM MEUS LÁBIOS.\n(SIM, LOUVAREI)\nSUA GRAÇA ME SUSTÉM,\nSEU AMOR É TÃO PROFUNDO,\n(SIM, LOUVAREI)\nSEU ESPÍRITO ME DÁ FORÇAS PRA LUTAR.\n\n<coro tipo=''2X''>\nSIM, LOUVAREI AO MEU SENHOR,\nPOIS É DIGNO DE LOUVOR,\nSUA GRAÇA ME SUSTÉM,\nLOUVAREI PRA SEMPRE, AMÉM.\n<final>SIM, LOUVAREI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (604, 'O MEU LOUVOR É FRUTO', 'O MEU LOUVOR É FRUTO', 'CORO (2X)\nO MEU LOUVOR É FRUTO DO MEU AMOR POR TI, JESUS, DE LÁBIOS QUE CONFESSAM O TEU NOME;\nÉ FRUTO DE TUA GRAÇA E DA PAZ QUE ENCONTRO \nEM TI E DO TEU ESPÍRITO QUE HABITA EM MIM,\nQUE HABITA EM MIM.\n\nAINDA QUE AS TREVAS VENHAM \nME CERCAR AINDA QUE OS MONTES \nDESABEM SOBRE MIM, \nMEUS LÁBIOS NÃO SE FECHARÃO \nPRA SEMPRE HEI DE TE LOUVAR!\n\nCORO\nO MEU LOUVOR É FRUTO DO MEU AMOR POR TI, JESUS, DE LÁBIOS QUE CONFESSAM O TEU NOME;\nÉ FRUTO DE TUA GRAÇA E DA PAZ QUE ENCONTRO \nEM TI E DO TEU ESPÍRITO QUE HABITA EM MIM,\nQUE HABITA EM MIM.\n\nAINDA QUE CADEIAS VENHAM \nME PRENDER AINDA QUE OS HOMENS \nSE LEVANTEM CONTRA MIM, \nMEUS LÁBIOS NÃO SE FECHARÃO,\nPRA SEMPRE HEI DE TE LOUVAR!\n\nCORO\nO MEU LOUVOR É FRUTO DO MEU AMOR POR TI, JESUS, DE LÁBIOS QUE CONFESSAM O TEU NOME;\nÉ FRUTO DE TUA GRAÇA E DA PAZ QUE ENCONTRO \nEM TI E DO TEU ESPÍRITO QUE HABITA EM MIM,\nQUE HABITA EM MIM.', '<coro tipo=''2X''>\nO MEU LOUVOR É FRUTO DO MEU AMOR POR TI, JESUS, DE LÁBIOS QUE CONFESSAM O TEU NOME;\nÉ FRUTO DE TUA GRAÇA E DA PAZ QUE ENCONTRO \nEM TI E DO TEU ESPÍRITO QUE HABITA EM MIM,\nQUE HABITA EM MIM.\n\nAINDA QUE AS TREVAS VENHAM \nME CERCAR AINDA QUE OS MONTES \nDESABEM SOBRE MIM, \nMEUS LÁBIOS NÃO SE FECHARÃO \nPRA SEMPRE HEI DE TE LOUVAR!\n\n<coro>\nO MEU LOUVOR É FRUTO DO MEU AMOR POR TI, JESUS, DE LÁBIOS QUE CONFESSAM O TEU NOME;\nÉ FRUTO DE TUA GRAÇA E DA PAZ QUE ENCONTRO \nEM TI E DO TEU ESPÍRITO QUE HABITA EM MIM,\nQUE HABITA EM MIM.\n\nAINDA QUE CADEIAS VENHAM \nME PRENDER AINDA QUE OS HOMENS \nSE LEVANTEM CONTRA MIM, \nMEUS LÁBIOS NÃO SE FECHARÃO,\nPRA SEMPRE HEI DE TE LOUVAR!\n\n<coro>\nO MEU LOUVOR É FRUTO DO MEU AMOR POR TI, JESUS, DE LÁBIOS QUE CONFESSAM O TEU NOME;\nÉ FRUTO DE TUA GRAÇA E DA PAZ QUE ENCONTRO \nEM TI E DO TEU ESPÍRITO QUE HABITA EM MIM,\nQUE HABITA EM MIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (605, 'NOSSO DEUS É SOBERANO', 'NOSSO DEUS É SOBERANO', 'NOSSO DEUS É SOBERANO, \nELE REINA ANTES DA FUNDAÇÃO DO MUNDO. \nNOSSO DEUS É SOBERANO, \nELE REINA ANTES DA FUNDAÇÃO DO MUNDO. \n\nA TERRA ERA SEM FORMA E VAZIA\nE O ESPÍRITO DO NOSSO DEUS\nSE MOVIA SOBRE A FACE DAS ÁGUAS;\nFOI ELE QUEM CRIOU O CÉU DOS CÉUS \nE FEZ SEPARAÇÃO DAS ÁGUAS DA TERRA SECA;\nFOI ELE QUEM CRIOU OS LUMINARES,\nCRIOU A NATUREZA \nE FORMOU O HOMEM.\n\nGLÓRIA A DEUS POR SUAS MARAVILHAS,\nPELA SUA GRANDEZA, GLÓRIA A DEUS!\nGLÓRIA A DEUS POR SUAS MARAVILHAS,\nPELA SUA GRANDEZA, GLÓRIA A DEUS!\nGLÓRIA A DEUS!', 'NOSSO DEUS É SOBERANO, \nELE REINA ANTES DA FUNDAÇÃO DO MUNDO. \nNOSSO DEUS É SOBERANO, \nELE REINA ANTES DA FUNDAÇÃO DO MUNDO. \n\nA TERRA ERA SEM FORMA E VAZIA\nE O ESPÍRITO DO NOSSO DEUS\nSE MOVIA SOBRE A FACE DAS ÁGUAS;\nFOI ELE QUEM CRIOU O CÉU DOS CÉUS \nE FEZ SEPARAÇÃO DAS ÁGUAS DA TERRA SECA;\nFOI ELE QUEM CRIOU OS LUMINARES,\nCRIOU A NATUREZA \nE FORMOU O HOMEM.\n\nGLÓRIA A DEUS POR SUAS MARAVILHAS,\nPELA SUA GRANDEZA, GLÓRIA A DEUS!\nGLÓRIA A DEUS POR SUAS MARAVILHAS,\nPELA SUA GRANDEZA, GLÓRIA A DEUS!\nGLÓRIA A DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (606, 'O CRIADOR DO UNIVERSO', 'O CRIADOR DO UNIVERSO', 'O CRIADOR DO UNIVERSO,\nQUE FEZ DO NADA TUDO NASCER,\nO QUE SUSTENTA TODAS AS COISAS\nPELA PALAVRA DO SEU PODER;\nO VERBO ETERNO QUE SE FEZ CARNE,\nO DEUS EM HOMEM REVELADO,\nO DEUS QUE É PAI, FILHO E ESPÍRITO,\nPARA SEMPRE SEJA ADORADO.\n\nCORO\nSEJA ADORADO, SEJA EXALTADO,\nSEJA LOUVADO O TEU NOME, Ó DEUS!\n\nO PAI, A QUEM ABANDONAMOS,\nMAS QUE JAMAIS NOS ESQUECEU,\nATÉ QUE UM DIA REGRESSAMOS\nE COM PERDÃO NOS RECEBEU;\nO FILHO QUE NA CRUZ FOI DADO,\nO QUE HOJE VIVE E ORA POR NÓS,\nO ESPÍRITO QUE NÃO NOS DEIXA SÓS;\nPARA SEMPRE SEJA ADORADO.\n\nCORO\nSEJA ADORADO, SEJA EXALTADO,\nSEJA LOUVADO O TEU NOME, Ó DEUS!\n\nFINAL: \nSEJA ADORADO, SEJA EXALTADO,\nSEJA LOUVADO O TEU NOME, \nÓ DEUS! SEJA EXALTADO O TEU NOME, \nÓ DEUS!', 'O CRIADOR DO UNIVERSO,\nQUE FEZ DO NADA TUDO NASCER,\nO QUE SUSTENTA TODAS AS COISAS\nPELA PALAVRA DO SEU PODER;\nO VERBO ETERNO QUE SE FEZ CARNE,\nO DEUS EM HOMEM REVELADO,\nO DEUS QUE É PAI, FILHO E ESPÍRITO,\nPARA SEMPRE SEJA ADORADO.\n\n<coro>\nSEJA ADORADO, SEJA EXALTADO,\nSEJA LOUVADO O TEU NOME, Ó DEUS!\n\nO PAI, A QUEM ABANDONAMOS,\nMAS QUE JAMAIS NOS ESQUECEU,\nATÉ QUE UM DIA REGRESSAMOS\nE COM PERDÃO NOS RECEBEU;\nO FILHO QUE NA CRUZ FOI DADO,\nO QUE HOJE VIVE E ORA POR NÓS,\nO ESPÍRITO QUE NÃO NOS DEIXA SÓS;\nPARA SEMPRE SEJA ADORADO.\n\n<coro>\nSEJA ADORADO, SEJA EXALTADO,\nSEJA LOUVADO O TEU NOME, Ó DEUS!\n<final>SEJA ADORADO, SEJA EXALTADO,\nSEJA LOUVADO O TEU NOME, \nÓ DEUS! SEJA EXALTADO O TEU NOME, \nÓ DEUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (607, 'A DEUS SEJA O LOUVOR', 'A DEUS SEJA O LOUVOR', 'A DEUS SEJA O LOUVOR\nPOR TUDO O QUE ELE É,\nPERFEIÇÃO ABSOLUTA\nEM SANTIDADE E AMOR!\nE DAI AO FILHO A GLÓRIA\nPOIS ALCANÇOU VITÓRIA,\nELE É VENCEDOR, \nDE TUDO É O SENHOR!\n\nPOR TODO O SEMPRE SE FALARÁ DAS MARAVILHAS \nDO SEU AMOR E TODO SER SE ENCURVARÁ \nPRA O ADORAR!\nO REI QUE SERVO SE TORNOU, \nO DEUS QUE ÀQUELA CRUZ BAIXOU PARA, \nPOR SEU SANGUE, O PECADOR RESGATAR.\n\nÀQUELA CRUZ BAIXOU PARA, \nPOR SEU SANGUE, \nO PECADOR RESGATAR.', 'A DEUS SEJA O LOUVOR\nPOR TUDO O QUE ELE É,\nPERFEIÇÃO ABSOLUTA\nEM SANTIDADE E AMOR!\nE DAI AO FILHO A GLÓRIA\nPOIS ALCANÇOU VITÓRIA,\nELE É VENCEDOR, \nDE TUDO É O SENHOR!\n\nPOR TODO O SEMPRE SE FALARÁ DAS MARAVILHAS \nDO SEU AMOR E TODO SER SE ENCURVARÁ \nPRA O ADORAR!\nO REI QUE SERVO SE TORNOU, \nO DEUS QUE ÀQUELA CRUZ BAIXOU PARA, \nPOR SEU SANGUE, O PECADOR RESGATAR.\n\nÀQUELA CRUZ BAIXOU PARA, \nPOR SEU SANGUE, \nO PECADOR RESGATAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (608, 'DEUS DOS EXÉRCITOS DE ISRAEL', 'DEUS DOS EXÉRCITOS DE ISRAEL', 'DEUS DOS EXÉRCITOS DE ISRAEL,\nCRIADOR DA TERRA E DO CÉU,\nTU ÉS DEUS DOS PROFETAS,\nSOBERANO CRIADOR;\nTU ÉS DEUS E DA VIDA ÉS AUTOR.\nÉS CRIADOR! ÉS CRIADOR!\n\nJESUS, ETERNO SALVADOR,\nNA CRUZ DEMONSTRASTE TEU AMOR,\nCOM GRAÇA E VERDADE,\nCOM TEU SANGUE ME ALCANÇASTE;\nJESUS, TU ÉS DEUS, TU ÉS SENHOR.\nTU ÉS SENHOR! TU ÉS SENHOR!\n\nÓ ESPÍRITO SANTO CONSOLADOR,\nEM TEUS SERVOS OPERAS COM FAVOR,\nTU ESTÁS SEMPRE CONOSCO,\nÉS O NOSSO INTERCESSOR;\nTU ÉS DEUS, Ó ESPÍRITO DE AMOR.\nCONSOLADOR! CONSOLADOR!', 'DEUS DOS EXÉRCITOS DE ISRAEL,\nCRIADOR DA TERRA E DO CÉU,\nTU ÉS DEUS DOS PROFETAS,\nSOBERANO CRIADOR;\nTU ÉS DEUS E DA VIDA ÉS AUTOR.\nÉS CRIADOR! ÉS CRIADOR!\n\nJESUS, ETERNO SALVADOR,\nNA CRUZ DEMONSTRASTE TEU AMOR,\nCOM GRAÇA E VERDADE,\nCOM TEU SANGUE ME ALCANÇASTE;\nJESUS, TU ÉS DEUS, TU ÉS SENHOR.\nTU ÉS SENHOR! TU ÉS SENHOR!\n\nÓ ESPÍRITO SANTO CONSOLADOR,\nEM TEUS SERVOS OPERAS COM FAVOR,\nTU ESTÁS SEMPRE CONOSCO,\nÉS O NOSSO INTERCESSOR;\nTU ÉS DEUS, Ó ESPÍRITO DE AMOR.\nCONSOLADOR! CONSOLADOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (609, 'SENHOR, MEU DEUS, QUANDO EU MARAVILHADO', 'SENHOR, MEU DEUS, QUANDO EU MARAVILHADO', 'SENHOR, MEU DEUS, \nQUANDO EU MARAVILHADO \nFICO A PENSAR NAS OBRAS DE TUAS MÃOS,\nO CÉU AZUL DE ESTRELAS PONTILHADO,\nO TEU PODER MOSTRANDO A CRIAÇÃO.\n\nCORO (2X)\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!\n\nQUANDO A VAGAR NAS MATAS E FLORESTAS, \nO PASSAREDO ALEGRE OUÇO A CANTAR;\nOLHANDO OS MONTES VALES E CAMPINAS\nEM TUDO VEJO O TEU PODER SEM PAR.\n\nCORO (2X)\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!\n\nQUANDO EU MEDITO EM TEU AMOR TÃO GRANDE, \nTEU FILHO DANDO AO MUNDO PRA SALVAR;\nNA CRUZ VERTENDO O SEU PRECIOSO SANGUE,\nMINH''ALMA PÔDE ASSIM PURIFICAR.\n\nCORO (2X)\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!\n\nE QUANDO ENFIM JESUS VIER EM GLÓRIA\nE AO LAR CELESTE ENTÃO ME TRANSPORTAR, \nADORAREI, PROSTRADO E PARA SEMPRE, \nQUÃO GRANDE ÉS TU, MEU DEUS, HEI DE CANTAR.\n\nCORO (2X)\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!', 'SENHOR, MEU DEUS, \nQUANDO EU MARAVILHADO \nFICO A PENSAR NAS OBRAS DE TUAS MÃOS,\nO CÉU AZUL DE ESTRELAS PONTILHADO,\nO TEU PODER MOSTRANDO A CRIAÇÃO.\n\n<coro tipo=''2X''>\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!\n\nQUANDO A VAGAR NAS MATAS E FLORESTAS, \nO PASSAREDO ALEGRE OUÇO A CANTAR;\nOLHANDO OS MONTES VALES E CAMPINAS\nEM TUDO VEJO O TEU PODER SEM PAR.\n\n<coro tipo=''2X''>\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!\n\nQUANDO EU MEDITO EM TEU AMOR TÃO GRANDE, \nTEU FILHO DANDO AO MUNDO PRA SALVAR;\nNA CRUZ VERTENDO O SEU PRECIOSO SANGUE,\nMINH''ALMA PÔDE ASSIM PURIFICAR.\n\n<coro tipo=''2X''>\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!\n\nE QUANDO ENFIM JESUS VIER EM GLÓRIA\nE AO LAR CELESTE ENTÃO ME TRANSPORTAR, \nADORAREI, PROSTRADO E PARA SEMPRE, \nQUÃO GRANDE ÉS TU, MEU DEUS, HEI DE CANTAR.\n\n<coro tipo=''2X''>\nENTÃO MINH''ALMA CANTA A TI, \nSENHOR: QUÃO GRANDE ÉS TU,\nQUÃO GRANDE ÉS TU!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (610, 'SANTO! SANTO! SANTO! DEUS ONIPOTENTE!', 'SANTO! SANTO! SANTO! DEUS ONIPOTENTE!', 'SANTO! SANTO! SANTO! DEUS ONIPOTENTE!\nCEDO DE MANHÃ CANTAREMOS TEU LOUVOR!\nSANTO! SANTO! SANTO! DEUS, JEOVÁ, TRIUNO,\nÉS UM SÓ DEUS, EXCELSO CRIADOR!\n\nSANTO! SANTO! SANTO! \nTODOS OS REMIDOS, JUNTOS COM OS ANJOS, \nPROCLAMAM TEU LOUVOR; ANTES DE \nFORMAR-SE O FIRMAMENTO E A TERRA, \nERAS E SEMPRE ÉS E HÁS DE SER, SENHOR!\n\nSANTO! SANTO! SANTO! NÓS OS PECADORES \nNÃO PODEMOS VER TUA GLÓRIA SEM TREMOR;\nTU SOMENTE ÉS SANTO, NÃO HÁ NENHUM \nOUTRO PURO E PERFEITO, EXCELSO BENFEITOR!\n\nINSTRUMENTOS\n\nSANTO! SANTO! SANTO! DEUS ONIPOTENTE!\nTUAS OBRAS LOUVAM TEU NOME COM FERVOR;\nSANTO! SANTO! SANTO! JUSTO E COMPASSIVO!\nÉS UM SÓ DEUS, SUPREMO CRIADOR.', 'SANTO! SANTO! SANTO! DEUS ONIPOTENTE!\nCEDO DE MANHÃ CANTAREMOS TEU LOUVOR!\nSANTO! SANTO! SANTO! DEUS, JEOVÁ, TRIUNO,\nÉS UM SÓ DEUS, EXCELSO CRIADOR!\n\nSANTO! SANTO! SANTO! \nTODOS OS REMIDOS, JUNTOS COM OS ANJOS, \nPROCLAMAM TEU LOUVOR; ANTES DE \nFORMAR-SE O FIRMAMENTO E A TERRA, \nERAS E SEMPRE ÉS E HÁS DE SER, SENHOR!\n\nSANTO! SANTO! SANTO! NÓS OS PECADORES \nNÃO PODEMOS VER TUA GLÓRIA SEM TREMOR;\nTU SOMENTE ÉS SANTO, NÃO HÁ NENHUM \nOUTRO PURO E PERFEITO, EXCELSO BENFEITOR!\n<instrumentos>\n\n\nSANTO! SANTO! SANTO! DEUS ONIPOTENTE!\nTUAS OBRAS LOUVAM TEU NOME COM FERVOR;\nSANTO! SANTO! SANTO! JUSTO E COMPASSIVO!\nÉS UM SÓ DEUS, SUPREMO CRIADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (611, 'JESUS DEUS SANTO, SANTO, SANTO!', 'JESUS DEUS SANTO, SANTO, SANTO!', 'JESUS, DEUS SANTO, SANTO, SANTO!\nDEUS DE PERDÃO E AMOR,\nDEUS DE PAZ, EMANUEL!\nÓ FILHO DE DAVI, ESTRELA DA MANHÃ,\nREI DOS REIS, EU TE ADORO, LOUVO,\nTE ESPERO, AMADO MEU, MEU JESUS!', 'JESUS, DEUS SANTO, SANTO, SANTO!<bis>\nDEUS DE PERDÃO E AMOR,<bis>\nDEUS DE PAZ, EMANUEL!<bis>\nÓ FILHO DE DAVI, ESTRELA DA MANHÃ,<bis>\nREI DOS REIS, EU TE ADORO, LOUVO,<bis>\nTE ESPERO, AMADO MEU, MEU JESUS!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (612, 'SANTO, SANTO, SANTO, Ó DEUS DE GLÓRIA E PODER', 'SANTO, SANTO, SANTO, Ó DEUS DE GLÓRIA E PODER', 'SANTO, SANTO, SANTO,\nÓ DEUS DE GLÓRIA E PODER;\nCÉUS E TERRA ESTÃO PLENOS DE TI,\nHOSANA, HOSANA,\nHOSANA AO NOSSO DEUS.\n\nBENDITO AQUELE QUE VEM\nEM NOME DO SENHOR,\nHOSANA, HOSANA,\nHOSANA AO NOSSO DEUS.', 'SANTO, SANTO, SANTO,\nÓ DEUS DE GLÓRIA E PODER;\nCÉUS E TERRA ESTÃO PLENOS DE TI,\nHOSANA, HOSANA,\nHOSANA AO NOSSO DEUS.\n\nBENDITO AQUELE QUE VEM\nEM NOME DO SENHOR,\nHOSANA, HOSANA,\nHOSANA AO NOSSO DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (613, 'DAI GLÓRIA A DEUS', 'DAI GLÓRIA A DEUS', 'DAI GLÓRIA A DEUS!\nQUEM NÃO O TEMERÁ?\nGLÓRIA E PODER SEM FIM\nDIANTE DELE HÁ!\n\nEIS O LEÃO\nDA TRIBO DE JUDÁ,\nAQUELE QUE ERA E É,\nE QUE VOLTARÁ!\n\nANJOS E QUERUBINS,\nARCANJOS E SERAFINS,\nDIA E NOITE ADORAM O QUE FOI MORTO \nMAS HOJE VIVE E É REI DOS REIS!\n\nDAI GLÓRIA A DEUS,\nDAI GLÓRIA A DEUS PAI,\nAO FILHO ADORAI,\nDAI GLÓRIA A DEUS! (3X)', 'DAI GLÓRIA A DEUS!\nQUEM NÃO O TEMERÁ?\nGLÓRIA E PODER SEM FIM\nDIANTE DELE HÁ!\n\nEIS O LEÃO\nDA TRIBO DE JUDÁ,\nAQUELE QUE ERA E É,\nE QUE VOLTARÁ!\n\nANJOS E QUERUBINS,\nARCANJOS E SERAFINS,\nDIA E NOITE ADORAM O QUE FOI MORTO \nMAS HOJE VIVE E É REI DOS REIS!\n\nDAI GLÓRIA A DEUS,\nDAI GLÓRIA A DEUS PAI,\nAO FILHO ADORAI,\nDAI GLÓRIA A DEUS! <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (614, 'A DEUS DEMOS GLÓRIA', 'A DEUS DEMOS GLÓRIA', 'A DEUS DEMOS GLÓRIA COM GRANDE FERVOR, \nSEU FILHO BENDITO POR NÓS TODOS DEU;\nA GRAÇA CONCEDE A QUALQUER PECADOR \nABRINDO-LHE A PORTA DE ENTRADA NO CÉU.\n\nCORO\nEXULTAI! EXULTAI! VINDE TODOS LOUVAR\nA JESUS SALVADOR, A JESUS REDENTOR!\nA DEUS DEMOS GLÓRIA PORQUANTO DO CÉU\nSEU FILHO BENDITO POR NÓS TODOS DEU.\n\nOH! GRAÇA REAL! FOI ASSIM QUE JESUS\nMORRENDO, SEU SANGUE POR NÓS DERRAMOU; \nHERANÇA NOS CÉUS, COM OS SANTOS EM LUZ, \nCOMPROU-NOS, JESUS, POIS O PREÇO PAGOU.\n\nCORO\nEXULTAI! EXULTAI! VINDE TODOS LOUVAR\nA JESUS SALVADOR, A JESUS REDENTOR!\nA DEUS DEMOS GLÓRIA PORQUANTO DO CÉU\nSEU FILHO BENDITO POR NÓS TODOS DEU.\n\nA CRER NOS CONVIDA TAL PROVA DE AMOR, \nNOS MERECIMENTOS DO FILHO DE DEUS; E QUEM, \nPOIS, CONFIA EM JESUS, SALVADOR, \nVAI VÊ-LO EXALTADO NA GLÓRIA DOS CÉUS.\n\nCORO\nEXULTAI! EXULTAI! VINDE TODOS LOUVAR\nA JESUS SALVADOR, A JESUS REDENTOR!\nA DEUS DEMOS GLÓRIA PORQUANTO DO CÉU\nSEU FILHO BENDITO POR NÓS TODOS DEU.', 'A DEUS DEMOS GLÓRIA COM GRANDE FERVOR, \nSEU FILHO BENDITO POR NÓS TODOS DEU;\nA GRAÇA CONCEDE A QUALQUER PECADOR \nABRINDO-LHE A PORTA DE ENTRADA NO CÉU.\n\n<coro>\nEXULTAI! EXULTAI! VINDE TODOS LOUVAR\nA JESUS SALVADOR, A JESUS REDENTOR!\nA DEUS DEMOS GLÓRIA PORQUANTO DO CÉU\nSEU FILHO BENDITO POR NÓS TODOS DEU.\n\nOH! GRAÇA REAL! FOI ASSIM QUE JESUS\nMORRENDO, SEU SANGUE POR NÓS DERRAMOU; \nHERANÇA NOS CÉUS, COM OS SANTOS EM LUZ, \nCOMPROU-NOS, JESUS, POIS O PREÇO PAGOU.\n\n<coro>\nEXULTAI! EXULTAI! VINDE TODOS LOUVAR\nA JESUS SALVADOR, A JESUS REDENTOR!\nA DEUS DEMOS GLÓRIA PORQUANTO DO CÉU\nSEU FILHO BENDITO POR NÓS TODOS DEU.\n\nA CRER NOS CONVIDA TAL PROVA DE AMOR, \nNOS MERECIMENTOS DO FILHO DE DEUS; E QUEM, \nPOIS, CONFIA EM JESUS, SALVADOR, \nVAI VÊ-LO EXALTADO NA GLÓRIA DOS CÉUS.\n\n<coro>\nEXULTAI! EXULTAI! VINDE TODOS LOUVAR\nA JESUS SALVADOR, A JESUS REDENTOR!\nA DEUS DEMOS GLÓRIA PORQUANTO DO CÉU\nSEU FILHO BENDITO POR NÓS TODOS DEU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (615, 'LOUVOR E GLÓRIA', 'LOUVOR E GLÓRIA', 'LOUVOR E GLÓRIA E SABEDORIA\nE AÇÕES DE GRAÇA E HONRA E PODER\nE FORÇA AO NOSSO DEUS, AO NOSSO DEUS,\nPRA TODO O SEMPRE, AMÉM.\n\nREPETE O LOUVOR', 'LOUVOR E GLÓRIA E SABEDORIA\nE AÇÕES DE GRAÇA E HONRA E PODER\nE FORÇA AO NOSSO DEUS, AO NOSSO DEUS,\nPRA TODO O SEMPRE, AMÉM.\n\nREPETE O LOUVOR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (616, 'AO DEUS DE AMOR E DE IMENSA BONDADE', 'AO DEUS DE AMOR E DE IMENSA BONDADE', 'AO DEUS DE AMOR E DE IMENSA BONDADE,\nCOM VOZ DE JÚBILO VINDE E ACLAMAI!\nCOM O CORAÇÃO TRANSBORDANTE DE GRAÇAS,\nSEU GRANDE AMOR, TODOS VINDE E LOUVAI!\n\nCORO\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!\n\nJÁ NOSSOS PAIS NOS CONTARAM \nA GLÓRIA DE DEUS, FALANDO COM MUITO PRAZER,\nQUE NAS TRISTEZAS, NOS GRANDES PERIGOS, \nELE OS SALVOU POR SEU GRANDE PODER!\n\nCORO\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!\n\nHOJE TAMBÉM NÓS BEM ALTO CANTAMOS\nQUE AS ORAÇÕES ELE NOS ATENDEU!\nSEU FORTE BRAÇO, QUE É TÃO COMPASSIVO, \nEM NOSSO AUXÍLIO ELE SEMPRE ESTENDEU!\n\nCORO\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!\n\nCOMO ATÉ HOJE E DAQUI PARA SEMPRE\nELE SERÁ NOSSO ETERNO PODER!\nNOSSO CASTELO BEM FORTE E SEGURO\nE NOSSA FONTE DE EXCELSO PRAZER!\n\nCORO\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!', 'AO DEUS DE AMOR E DE IMENSA BONDADE,\nCOM VOZ DE JÚBILO VINDE E ACLAMAI!\nCOM O CORAÇÃO TRANSBORDANTE DE GRAÇAS,\nSEU GRANDE AMOR, TODOS VINDE E LOUVAI!\n\n<coro>\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!\n\nJÁ NOSSOS PAIS NOS CONTARAM \nA GLÓRIA DE DEUS, FALANDO COM MUITO PRAZER,\nQUE NAS TRISTEZAS, NOS GRANDES PERIGOS, \nELE OS SALVOU POR SEU GRANDE PODER!\n\n<coro>\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!\n\nHOJE TAMBÉM NÓS BEM ALTO CANTAMOS\nQUE AS ORAÇÕES ELE NOS ATENDEU!\nSEU FORTE BRAÇO, QUE É TÃO COMPASSIVO, \nEM NOSSO AUXÍLIO ELE SEMPRE ESTENDEU!\n\n<coro>\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!\n\nCOMO ATÉ HOJE E DAQUI PARA SEMPRE\nELE SERÁ NOSSO ETERNO PODER!\nNOSSO CASTELO BEM FORTE E SEGURO\nE NOSSA FONTE DE EXCELSO PRAZER!\n\n<coro>\nNO CÉU, NA TERRA, QUE MARAVILHAS\nVAI OPERANDO O PODER DO SENHOR!\nMAS SEU AMOR AOS HOMENS PERDIDOS,\nDAS MARAVILHAS É SEMPRE A MAIOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (617, 'O MEU CORAÇÃO SE REGOZIJA NO SENHOR', 'O MEU CORAÇÃO SE REGOZIJA NO SENHOR', 'O MEU CORAÇÃO SE REGOZIJA NO SENHOR, \nO MEU PODER ESTÁ EXALTADO NO SENHOR;\nA MINHA BOCA SE ABRIRÁ EM GLORIFICAÇÃO \nPORQUE ME ALEGRO NA SUA SALVAÇÃO.\n\nCORO\nNÃO HÁ SANTO COMO O SENHOR,\nNÃO HÁ OUTRO ALÉM DE TI;\nROCHA INABALÁVEL É O NOSSO DEUS.\n\nINSTRUMENTOS\n\nO SENHOR É O QUE TIRA A VIDA E A DÁ\nE OS SEUS SANTOS ETERNAMENTE GUARDARÁ;\nELE EXALTARÁ DO SEU UNGIDO O PODER\nPORQUE O SENHOR É O NOSSO DEUS.\n\nCORO (2X)\nNÃO HÁ SANTO COMO O SENHOR,\nNÃO HÁ OUTRO ALÉM DE TI;\nROCHA INABALÁVEL É O NOSSO DEUS.', 'O MEU CORAÇÃO SE REGOZIJA NO SENHOR, \nO MEU PODER ESTÁ EXALTADO NO SENHOR;\nA MINHA BOCA SE ABRIRÁ EM GLORIFICAÇÃO \nPORQUE ME ALEGRO NA SUA SALVAÇÃO.\n\n<coro>\nNÃO HÁ SANTO COMO O SENHOR,\nNÃO HÁ OUTRO ALÉM DE TI;\nROCHA INABALÁVEL É O NOSSO DEUS.\n<instrumentos>\n\n\nO SENHOR É O QUE TIRA A VIDA E A DÁ\nE OS SEUS SANTOS ETERNAMENTE GUARDARÁ;\nELE EXALTARÁ DO SEU UNGIDO O PODER\nPORQUE O SENHOR É O NOSSO DEUS.\n\n<coro tipo=''2X''>\nNÃO HÁ SANTO COMO O SENHOR,\nNÃO HÁ OUTRO ALÉM DE TI;\nROCHA INABALÁVEL É O NOSSO DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (618, 'CANTAREI AO MEU SENHOR ENQUANTO EU VIVER', 'CANTAREI AO MEU SENHOR ENQUANTO EU VIVER', 'CANTAREI AO MEU SENHOR ENQUANTO EU VIVER,\nCANTAREI LOUVORES ENQUANTO EXISTIR;\nENTÃO ME ALEGRAREI NO MEU SENHOR,\nMUI SUAVE SERÁ A MINHA MEDITAÇÃO.\n\nLOUVA, MINH''ALMA, \nAO SENHOR, BENDIZE-O JÁ.\n\n4X', 'CANTAREI AO MEU SENHOR ENQUANTO EU VIVER,\nCANTAREI LOUVORES ENQUANTO EXISTIR;\nENTÃO ME ALEGRAREI NO MEU SENHOR,\nMUI SUAVE SERÁ A MINHA MEDITAÇÃO.\n\nLOUVA, MINH''ALMA, \nAO SENHOR, BENDIZE-O JÁ.\n\n<bis tipo=''4''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (619, 'VEM, DERRAMA A PAZ', 'VEM, DERRAMA A PAZ', 'VEM, DERRAMA A PAZ,\nVEM, DERRAMA AS BÊNÇÃOS SOBRE ESTE POVO\nQUE SE CHAMA POVO TEU;\nDÁ-NOS TEU AMOR, DÁ-NOS TUA FORÇA \nPRA QUE TENTAÇÕES NÃO VENHAM \nA NOS DESVIAR.\n\nE A GLÓRIA SEJA DADA A TI PELO \nQUE TENS FEITO, PELO QUE TENS SIDO,\nPELO QUE FARÁS EM NÓS.\n\nINSTRUMENTOS\n\nVEM, DERRAMA A PAZ, VEM, DERRAMA \nAS BÊNÇÃOS SOBRE ESTE POVO \nQUE SE CHAMA POVO TEU;\nDÁ-NOS TEU AMOR, DÁ-NOS TUA FORÇA \nPRA QUE TENTAÇÕES NÃO VENHAM \nA NOS DESVIAR.\n\nE A GLÓRIA SEJA DADA A TI\nPELO QUE TENS FEITO,\nPELO QUE TENS SIDO,\nPELO QUE FARÁS EM NÓS.\n\nFINAL: \nPELO QUE FARÁS EM NÓS.', 'VEM, DERRAMA A PAZ,\nVEM, DERRAMA AS BÊNÇÃOS SOBRE ESTE POVO\nQUE SE CHAMA POVO TEU;\nDÁ-NOS TEU AMOR, DÁ-NOS TUA FORÇA \nPRA QUE TENTAÇÕES NÃO VENHAM \nA NOS DESVIAR.\n\nE A GLÓRIA SEJA DADA A TI PELO \nQUE TENS FEITO, PELO QUE TENS SIDO,\nPELO QUE FARÁS EM NÓS.\n<instrumentos>\n\n\nVEM, DERRAMA A PAZ, VEM, DERRAMA \nAS BÊNÇÃOS SOBRE ESTE POVO \nQUE SE CHAMA POVO TEU;\nDÁ-NOS TEU AMOR, DÁ-NOS TUA FORÇA \nPRA QUE TENTAÇÕES NÃO VENHAM \nA NOS DESVIAR.\n\nE A GLÓRIA SEJA DADA A TI\nPELO QUE TENS FEITO,\nPELO QUE TENS SIDO,\nPELO QUE FARÁS EM NÓS.\n<final>PELO QUE FARÁS EM NÓS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (620, 'ESTAMOS AQUI, Ó DEUS', 'ESTAMOS AQUI, Ó DEUS', 'ESTAMOS AQUI, Ó DEUS, PRA LOUVAR \nO TEU NOME, POIS TU NOS TORNASTE \nSERVOS TEUS. LOUVEMOS A DEUS!\nA CAMINHO ESTAMOS DA NOVA JERUSALÉM, \nCIDADE ETERNAL QUE O PAI NOS PREPAROU.\nMARANATA! ORA VEM, SENHOR JESUS,\nVEM NOS BUSCAR.\n\nINSTRUMENTOS\n\nESTAMOS AQUI, Ó DEUS, PRA LOUVAR \nO TEU NOME, POIS TU NOS TORNASTE \nSERVOS TEUS. LOUVEMOS A DEUS!\nA CAMINHO ESTAMOS DA NOVA JERUSALÉM, \nCIDADE ETERNAL QUE O PAI NOS PREPAROU.\nMARANATA! ORA VEM, SENHOR JESUS,\nVEM NOS BUSCAR.\n\nFINAL: (2X)\nMARANATA! \nLOUVEMOS A DEUS,\nLOUVEMOS A DEUS, \nLOUVEMOS A DEUS.\nMARANATA!', 'ESTAMOS AQUI, Ó DEUS, PRA LOUVAR \nO TEU NOME, POIS TU NOS TORNASTE \nSERVOS TEUS. LOUVEMOS A DEUS!\nA CAMINHO ESTAMOS DA NOVA JERUSALÉM, \nCIDADE ETERNAL QUE O PAI NOS PREPAROU.\nMARANATA! ORA VEM, SENHOR JESUS,\nVEM NOS BUSCAR.\n<instrumentos>\n\n\nESTAMOS AQUI, Ó DEUS, PRA LOUVAR \nO TEU NOME, POIS TU NOS TORNASTE \nSERVOS TEUS. LOUVEMOS A DEUS!\nA CAMINHO ESTAMOS DA NOVA JERUSALÉM, \nCIDADE ETERNAL QUE O PAI NOS PREPAROU.\nMARANATA! ORA VEM, SENHOR JESUS,\nVEM NOS BUSCAR.\n\n\n<final>(<bis tipo=''2''>\nMARANATA! \nLOUVEMOS A DEUS,\nLOUVEMOS A DEUS, \nLOUVEMOS A DEUS.\nMARANATA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (621, 'ADORAR-TE', 'ADORAR-TE', 'ADORAR-TE É O MEU MAIOR PRAZER,\nSEGUIR-TE É O MEU VIVER.\n\nINSTRUMENTOS\n\nMEU CORAÇÃO TRANSBORDA, SENHOR,\nDA TUA GRAÇA E DO TEU AMOR;\nADORAR-TE É O MEU MAIOR PRAZER,\nSEGUIR-TE É O MEU VIVER.\n\nCORO\nNÃO HÁ DEUS COMO TU, Ó SENHOR,\nDEUS FORTE, PRÍNCIPE DA PAZ;\nTEU DOMÍNIO É ETERNO, SENHOR,\nTU REINAS SOBRE TERRA, CÉU E MAR,\nTU REINAS EM NÓS.\n\nINSTRUMENTOS\n\nNOS TEUS ÁTRIOS ENTRAMOS, SENHOR,\nCOM OS LÁBIOS CHEIOS DE LOUVOR,\nGRAÇAS TE DAMOS PELA PAZ, (PELA PAZ) \nPELAS BÊNÇÃOS, (PELAS BÊNÇÃOS, SENHOR)\nPOR TÃO GRANDE SALVAÇÃO,\nPOR JESUS ENTRE NÓS.\n\nCORO (2X)\nNÃO HÁ DEUS COMO TU, Ó SENHOR,\nDEUS FORTE, PRÍNCIPE DA PAZ;\nTEU DOMÍNIO É ETERNO, SENHOR,\nTU REINAS SOBRE TERRA, CÉU E MAR,\nTU REINAS EM NÓS.', 'ADORAR-TE É O MEU MAIOR PRAZER,\nSEGUIR-TE É O MEU VIVER.\n<instrumentos>\nMEU CORAÇÃO TRANSBORDA, SENHOR,\nDA TUA GRAÇA E DO TEU AMOR;\nADORAR-TE É O MEU MAIOR PRAZER,\nSEGUIR-TE É O MEU VIVER.\n\n<coro>\nNÃO HÁ DEUS COMO TU, Ó SENHOR,\nDEUS FORTE, PRÍNCIPE DA PAZ;\nTEU DOMÍNIO É ETERNO, SENHOR,\nTU REINAS SOBRE TERRA, CÉU E MAR,\nTU REINAS EM NÓS.\n<instrumentos>\n\n\nNOS TEUS ÁTRIOS ENTRAMOS, SENHOR,\nCOM OS LÁBIOS CHEIOS DE LOUVOR,\nGRAÇAS TE DAMOS PELA PAZ, (PELA PAZ) \nPELAS BÊNÇÃOS, (PELAS BÊNÇÃOS, SENHOR)\nPOR TÃO GRANDE SALVAÇÃO,\nPOR JESUS ENTRE NÓS.\n\n<coro tipo=''2X''>\nNÃO HÁ DEUS COMO TU, Ó SENHOR,\nDEUS FORTE, PRÍNCIPE DA PAZ;\nTEU DOMÍNIO É ETERNO, SENHOR,\nTU REINAS SOBRE TERRA, CÉU E MAR,\nTU REINAS EM NÓS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (622, 'A BELEZA DA TUA SANTIDADE', 'A BELEZA DA TUA SANTIDADE', 'A BELEZA DA TUA SANTIDADE É MAIOR\nQUE AS MARAVILHAS DA TERRA,\nPOIS AQUI CADA UMA SE ENCERRA;\nTUA BELEZA, PORÉM, \nPOR TODA A ETERNIDADE É.\n\nCÉUS E TERRA PASSARÃO,\nTUA PALAVRA PERMANECERÁ,\nA MATÉRIA ENVELHECERÁ\nMAS TEU AMOR PRA SEMPRE EXISTIRÁ.\n\nA BELEZA DA TUA SANTIDADE É MAIOR\nQUE AS MARAVILHAS DA TERRA,\nPOIS AQUI CADA UMA SE ENCERRA;\nTUA BELEZA, PORÉM, \nPOR TODA A ETERNIDADE É.\n\nCÉUS E TERRA PASSARÃO,\nTUA PALAVRA PERMANECERÁ,\nA MATÉRIA ENVELHECERÁ\nMAS TEU AMOR PRA SEMPRE EXISTIRÁ.\n\nINSTRUMENTOS\n\nCÉUS E TERRA PASSARÃO...\n\nFINAL: \nTEU AMOR PRA SEMPRE EXISTIRÁ.', 'A BELEZA DA TUA SANTIDADE É MAIOR\nQUE AS MARAVILHAS DA TERRA,\nPOIS AQUI CADA UMA SE ENCERRA;\nTUA BELEZA, PORÉM, \nPOR TODA A ETERNIDADE É.\n\nCÉUS E TERRA PASSARÃO,\nTUA PALAVRA PERMANECERÁ,\nA MATÉRIA ENVELHECERÁ\nMAS TEU AMOR PRA SEMPRE EXISTIRÁ.\n\nA BELEZA DA TUA SANTIDADE É MAIOR\nQUE AS MARAVILHAS DA TERRA,\nPOIS AQUI CADA UMA SE ENCERRA;\nTUA BELEZA, PORÉM, \nPOR TODA A ETERNIDADE É.\n\nCÉUS E TERRA PASSARÃO,\nTUA PALAVRA PERMANECERÁ,\nA MATÉRIA ENVELHECERÁ\nMAS TEU AMOR PRA SEMPRE EXISTIRÁ.\n<instrumentos>\nCÉUS E TERRA PASSARÃO...\n<final>TEU AMOR PRA SEMPRE EXISTIRÁ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (623, 'EU QUERO CANTAR DE GOZO E DE PAZ', 'EU QUERO CANTAR DE GOZO E DE PAZ', 'EU QUERO CANTAR DE GOZO E DE PAZ,\nSENTIR A ALEGRIA QUE JESUS CRISTO TRAZ;\nEU QUERO SENTIR A PRESENÇA DO AMOR\nEM MEU CORAÇÃO, O SALVADOR.\n\nEU QUERO DIZER PARA O MUNDO\nQUE O SENHOR DEUS ENVIOU\nSEU FILHO A MORRER NUMA CRUZ,\nTUDO PORQUE ME AMOU;\nEU QUERO CHORAR DE ALEGRIA\nE VIVER A CANTAR,\nTUDO PORQUE MEU JESUS\nMORREU PARA ME SALVAR. \n\nINSTRUMENTOS\n\nEU QUERO CANTAR DE GOZO E DE PAZ,\nSENTIR A ALEGRIA QUE JESUS CRISTO TRAZ;\nEU QUERO SENTIR A PRESENÇA DO AMOR\nEM MEU CORAÇÃO, O SALVADOR.\n\nEU QUERO DIZER PARA O MUNDO\nQUE O SENHOR DEUS ENVIOU\nSEU FILHO A MORRER NUMA CRUZ,\nTUDO PORQUE ME AMOU;\nEU QUERO CHORAR DE ALEGRIA\nE VIVER A CANTAR,\nTUDO PORQUE MEU JESUS\nMORREU PARA ME SALVAR.', 'EU QUERO CANTAR DE GOZO E DE PAZ,\nSENTIR A ALEGRIA QUE JESUS CRISTO TRAZ;\nEU QUERO SENTIR A PRESENÇA DO AMOR\nEM MEU CORAÇÃO, O SALVADOR.\n\nEU QUERO DIZER PARA O MUNDO\nQUE O SENHOR DEUS ENVIOU\nSEU FILHO A MORRER NUMA CRUZ,\nTUDO PORQUE ME AMOU;\nEU QUERO CHORAR DE ALEGRIA\nE VIVER A CANTAR,\nTUDO PORQUE MEU JESUS\nMORREU PARA ME SALVAR. \n<instrumentos>\n\n\nEU QUERO CANTAR DE GOZO E DE PAZ,\nSENTIR A ALEGRIA QUE JESUS CRISTO TRAZ;\nEU QUERO SENTIR A PRESENÇA DO AMOR\nEM MEU CORAÇÃO, O SALVADOR.\n\nEU QUERO DIZER PARA O MUNDO<bis>\nQUE O SENHOR DEUS ENVIOU<bis>\nSEU FILHO A MORRER NUMA CRUZ,<bis>\nTUDO PORQUE ME AMOU;<bis>\nEU QUERO CHORAR DE ALEGRIA<bis>\nE VIVER A CANTAR,<bis>\nTUDO PORQUE MEU JESUS<bis>\nMORREU PARA ME SALVAR. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (624, 'A MINH''ALMA ENGRANDECE', 'A MINH''ALMA ENGRANDECE', 'A MINH''ALMA ENGRANDECE\nAO MEU SENHOR E REI. \n\nCORO\nA QUEM MAIS ENGRANDECEREI\nDO QUE A JESUS, O SENHOR?\n\nDEU-ME LÍNGUA NOVA PRA LOUVÁ-LO, \nELE É O SENHOR. \n\nCORO\nA QUEM MAIS ENGRANDECEREI \nDO QUE A JESUS, O SENHOR? \n\nSEI QUE ELE VOLTA PRA BUSCAR-ME, \nLEVAR-ME AO CÉU. \n\nCORO\nA QUEM MAIS ENGRANDECEREI \nDO QUE A JESUS, O SENHOR?', 'A MINH''ALMA ENGRANDECE<bis>\nAO MEU SENHOR E REI.<coro><bis>\nA QUEM MAIS ENGRANDECEREI\nDO QUE A JESUS, O SENHOR?<bis>\n\nDEU-ME LÍNGUA NOVA PRA LOUVÁ-LO, <bis>\nELE É O SENHOR.<coro><bis>\nA QUEM MAIS ENGRANDECEREI \nDO QUE A JESUS, O SENHOR? <bis>\n\nSEI QUE ELE VOLTA PRA BUSCAR-ME, <bis>\nLEVAR-ME AO CÉU.<coro><bis>\nA QUEM MAIS ENGRANDECEREI \nDO QUE A JESUS, O SENHOR? <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (625, 'DIGNO É JESUS', 'DIGNO É JESUS', 'DIGNO É JESUS DE TODA A GLÓRIA,\nDIGNO É DE TODO O LOUVOR;\nTODA A TERRA EXALTE O SEU NOME\nPOIS ELE É REI DOS REIS E É SENHOR.\nPROSTREMO-NOS DIANTE DO SEU TRONO\nPOIS TODO JOELHO HÁ DE SE DOBRAR\nE TODA LÍNGUA VAI CONFESSAR \nQUE ELE É SENHOR, \nO REI QUE EM TODA A TERRA VAI REINAR.\n\nA TI DAMOS O LOUVOR E A HONRA,\nSENHOR JESUS, SENHOR JESUS!\nNOS PROSTRAMOS DIANTE DA TUA GLÓRIA,\nSENHOR JESUS, SENHOR JESUS!\nSENHOR JESUS, REI DOS REIS,\nO SENHOR!', 'DIGNO É JESUS DE TODA A GLÓRIA,\nDIGNO É DE TODO O LOUVOR;\nTODA A TERRA EXALTE O SEU NOME\nPOIS ELE É REI DOS REIS E É SENHOR.\nPROSTREMO-NOS DIANTE DO SEU TRONO\nPOIS TODO JOELHO HÁ DE SE DOBRAR\nE TODA LÍNGUA VAI CONFESSAR \nQUE ELE É SENHOR, \nO REI QUE EM TODA A TERRA VAI REINAR.\n\nA TI DAMOS O LOUVOR E A HONRA,\nSENHOR JESUS, SENHOR JESUS!\nNOS PROSTRAMOS DIANTE DA TUA GLÓRIA,\nSENHOR JESUS, SENHOR JESUS!\nSENHOR JESUS, REI DOS REIS,\nO SENHOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (626, 'OH! CONTEMPLAI', 'OH! CONTEMPLAI', 'OH! CONTEMPLAI E VEDE ESTE AMOR,\nO AMOR DE JESUS CRISTO POR NÓS;\nSE DEU, SE ENTREGOU POR TI E POR MIM, \nNOS RESGATOU, COM SEU SANGUE \nNOS COMPROU.\n\nDA MORTE ELE É O VENCEDOR,\nDA VIDA ETERNA ELE É SENHOR,\nPALAVRA DE DEUS É O SEU NOME,\nREI DOS REIS, SENHOR DOS SENHORES.\n\nDIGNO É DE RECEBER A GLÓRIA \nE O LOUVOR E AÇÕES DE GRAÇAS;\nDIGNO É DE RECEBER A HONRA \nE O PODER PARA TODO O SEMPRE, JESUS.', 'OH! CONTEMPLAI E VEDE ESTE AMOR,\nO AMOR DE JESUS CRISTO POR NÓS;\nSE DEU, SE ENTREGOU POR TI E POR MIM, \nNOS RESGATOU, COM SEU SANGUE \nNOS COMPROU.\n\nDA MORTE ELE É O VENCEDOR,\nDA VIDA ETERNA ELE É SENHOR,\nPALAVRA DE DEUS É O SEU NOME,\nREI DOS REIS, SENHOR DOS SENHORES.\n\nDIGNO É DE RECEBER A GLÓRIA \nE O LOUVOR E AÇÕES DE GRAÇAS;\nDIGNO É DE RECEBER A HONRA \nE O PODER PARA TODO O SEMPRE, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (627, 'NÓS TE ADORAMOS, SENHOR', 'NÓS TE ADORAMOS, SENHOR', 'NÓS TE ADORAMOS, SENHOR, \nPOIS ÉS DIGNO DE LOUVOR, \nNOSSO REI E SALVADOR, NOSSO SENHOR.\nA TUA GLÓRIA ESTÁ NESTE LUGAR,\nA TUA PRESENÇA FAZ TRANSBORDAR\nO NOSSO CORAÇÃO DE LOUVOR.\nINSTRUMENTOS\n\nCORO \nA TUA GLÓRIA (GLÓRIA)\nSE ESTENDE SOBRE OS CÉUS\n(SE ESTENDE SOBRE OS CÉUS) \nE O TEU LOUVOR (E O TEU LOUVOR) \nAOS CONFINS DA TERRA.\n\nCORO \nA TUA GLÓRIA (GLÓRIA)\nSE ESTENDE SOBRE OS CÉUS\n(SE ESTENDE SOBRE OS CÉUS) \nE O TEU LOUVOR (E O TEU LOUVOR) \nAOS CONFINS DA TERRA.\n(SE FAZ OUVIR)\n\nINSTRUMENTOS\n\nEM SANTIDADE, Ó SENHOR,\nQUEREMOS TE ADORAR,\nEM UMA SÓ VOZ TUA GLÓRIA EXALTAR.\n\nCORO (2X)\nA TUA GLÓRIA (GLÓRIA)\nSE ESTENDE SOBRE OS CÉUS\n(SE ESTENDE SOBRE OS CÉUS) \nE O TEU LOUVOR (E O TEU LOUVOR) \nAOS CONFINS DA TERRA.\n\nFINAL:\nA TUA GLÓRIA ESTÁ NESTE LUGAR,\nA TUA PRESENÇA FAZ TRANSBORDAR\nO NOSSO CORAÇÃO DE LOUVOR.', 'NÓS TE ADORAMOS, SENHOR, \nPOIS ÉS DIGNO DE LOUVOR, \nNOSSO REI E SALVADOR, NOSSO SENHOR.\nA TUA GLÓRIA ESTÁ NESTE LUGAR,\nA TUA PRESENÇA FAZ TRANSBORDAR\nO NOSSO CORAÇÃO DE LOUVOR.\n<instrumentos>\n\n\n<coro>\nA TUA GLÓRIA (GLÓRIA)\nSE ESTENDE SOBRE OS CÉUS\n(SE ESTENDE SOBRE OS CÉUS) \nE O TEU LOUVOR (E O TEU LOUVOR) \nAOS CONFINS DA TERRA.\n\n<coro>\nA TUA GLÓRIA (GLÓRIA)\nSE ESTENDE SOBRE OS CÉUS\n(SE ESTENDE SOBRE OS CÉUS) \nE O TEU LOUVOR (E O TEU LOUVOR) \nAOS CONFINS DA TERRA.\n(SE FAZ OUVIR)\n<instrumentos>\n\n\nEM SANTIDADE, Ó SENHOR,\nQUEREMOS TE ADORAR,\nEM UMA SÓ VOZ TUA GLÓRIA EXALTAR.\n\n<coro tipo=''2X''>\nA TUA GLÓRIA (GLÓRIA)\nSE ESTENDE SOBRE OS CÉUS\n(SE ESTENDE SOBRE OS CÉUS) \nE O TEU LOUVOR (E O TEU LOUVOR) \nAOS CONFINS DA TERRA.\n\n\n<final>A TUA GLÓRIA ESTÁ NESTE LUGAR,\nA TUA PRESENÇA FAZ TRANSBORDAR\nO NOSSO CORAÇÃO DE LOUVOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (628, 'SANTO É SEU NOME', 'SANTO É SEU NOME', 'SANTO É SEU NOME,\nTAL QUAL ESSE EXCELSO \nNOME JAMAIS OUVI;\nDOCE, PURO E PERFEITO É,\nESSE NOME SE TRADUZ EM LUZ,\nEM CHORAR E EM SORRIR.\n\nCORO\nSANTO NOME DE JESUS,\nMAIS MARAVILHOSO \nQUE OUTRO QUALQUER;\nSANTO NOME DE JESUS,\nDÁ CONSOLAÇÃO E DOCE AMOR\nSEJA NO LUGAR QUE FOR,\nSANTO É O NOME DE JESUS.\n\nINSTRUMENTOS\n\nSANTO É SEU NOME,\nMAIS PRECIOSO QUE RIQUEZAS\nDO MUNDO, SIM;\nSOA EM MIM EM PERFEITO TOM\nTAL QUAL EM CELESTIAL CORO \nQUE NUNCA UM HOMEM \nPÔDE OUVIR.\n\nCORO (2X)\nSANTO NOME DE JESUS,\nMAIS MARAVILHOSO \nQUE OUTRO QUALQUER;\nSANTO NOME DE JESUS,\nDÁ CONSOLAÇÃO E DOCE AMOR\nSEJA NO LUGAR QUE FOR,\nSANTO É O NOME DE JESUS.', 'SANTO É SEU NOME,\nTAL QUAL ESSE EXCELSO \nNOME JAMAIS OUVI;\nDOCE, PURO E PERFEITO É,\nESSE NOME SE TRADUZ EM LUZ,\nEM CHORAR E EM SORRIR.\n\n<coro>\nSANTO NOME DE JESUS,\nMAIS MARAVILHOSO \nQUE OUTRO QUALQUER;\nSANTO NOME DE JESUS,\nDÁ CONSOLAÇÃO E DOCE AMOR\nSEJA NO LUGAR QUE FOR,\nSANTO É O NOME DE JESUS.\n<instrumentos>\n\n\nSANTO É SEU NOME,\nMAIS PRECIOSO QUE RIQUEZAS\nDO MUNDO, SIM;\nSOA EM MIM EM PERFEITO TOM\nTAL QUAL EM CELESTIAL<coro>\nQUE NUNCA UM HOMEM \nPÔDE OUVIR.\n\n<coro tipo=''2X''>\nSANTO NOME DE JESUS,\nMAIS MARAVILHOSO \nQUE OUTRO QUALQUER;\nSANTO NOME DE JESUS,\nDÁ CONSOLAÇÃO E DOCE AMOR\nSEJA NO LUGAR QUE FOR,\nSANTO É O NOME DE JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (629, 'QUE ALEGRIA', 'QUE ALEGRIA', 'QUE ALEGRIA É OUVIR O TEU POVO TODO CANTANDO\nDE FELICIDADE, REGOZIJANDO DIANTE DO ALTAR;\nQUE ALEGRIA VER O TEU POVO TODO ADORANDO \nA TI, Ó GRANDE DEUS, E AO TEU FILHO JESUS \nQUE NOS VEIO SALVAR.\n\nQUE ALEGRIA É ESTAR \nNA TUA CASA TODOS OS DIAS, \nCOM OS IRMÃOS REUNIDOS, \nÉ A BÊNÇÃO DO ESPÍRITO A TRANSBORDAR;\nQUE ALEGRIA É DEUS OPERANDO NA \nSUA IGREJA SALVANDO E LIBERTANDO,\nORIENTANDO E CURANDO \nTODO O QUE A ELE VEM. \n\nQUE ALEGRIA É ESTAR NA TUA CASA \nTODOS OS DIAS, COM OS IRMÃOS REUNIDOS, \nÉ A BÊNÇÃO DO ESPÍRITO A TRANSBORDAR;\nQUE ALEGRIA É DEUS OPERANDO NA SUA IGREJA\nSALVANDO E LIBERTANDO\nORIENTANDO E CURANDO\nTODO O QUE A ELE VEM.', 'QUE ALEGRIA É OUVIR O TEU POVO TODO CANTANDO\nDE FELICIDADE, REGOZIJANDO DIANTE DO ALTAR;\nQUE ALEGRIA VER O TEU POVO TODO ADORANDO \nA TI, Ó GRANDE DEUS, E AO TEU FILHO JESUS \nQUE NOS VEIO SALVAR.\n\nQUE ALEGRIA É ESTAR \nNA TUA CASA TODOS OS DIAS, \nCOM OS IRMÃOS REUNIDOS, \nÉ A BÊNÇÃO DO ESPÍRITO A TRANSBORDAR;\nQUE ALEGRIA É DEUS OPERANDO NA \nSUA IGREJA SALVANDO E LIBERTANDO,\nORIENTANDO E CURANDO \nTODO O QUE A ELE VEM. \n\nQUE ALEGRIA É ESTAR NA TUA CASA \nTODOS OS DIAS, COM OS IRMÃOS REUNIDOS, \nÉ A BÊNÇÃO DO ESPÍRITO A TRANSBORDAR;\nQUE ALEGRIA É DEUS OPERANDO NA SUA IGREJA\nSALVANDO E LIBERTANDO<bis>\nORIENTANDO E CURANDO<bis>\nTODO O QUE A ELE VEM. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (630, 'SAUDAI O NOME DE JESUS', 'SAUDAI O NOME DE JESUS', 'SAUDAI O NOME DE JESUS!\nARCANJOS VOS PROSTRAI; (BIS)\nAO FILHO DO ETERNO DEUS\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!\n\nÓ ESCOLHIDA GERAÇÃO\nDO BOM E ETERNO PAI; (BIS)\nAO GRANDE AUTOR DA SALVAÇÃO\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!\n\nÓ PERDOADOS, CUJO AMOR\nBEM TRIUNFANTE VAI; (BIS)\nAO DEUS VARÃO, CONQUISTADOR\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!\n\nÓ RAÇAS, TRIBOS E NAÇÕES,\nAO REI DIVINO HONRAI! (BIS)\nA QUEM QUEBROU VOSSOS GRILHÕES,\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!', 'SAUDAI O NOME DE JESUS!\nARCANJOS VOS PROSTRAI; <bis>\nAO FILHO DO ETERNO DEUS\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!\n\nÓ ESCOLHIDA GERAÇÃO\nDO BOM E ETERNO PAI; <bis>\nAO GRANDE AUTOR DA SALVAÇÃO\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!\n\nÓ PERDOADOS, CUJO AMOR\nBEM TRIUNFANTE VAI; <bis>\nAO DEUS VARÃO, CONQUISTADOR\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!\n\nÓ RAÇAS, TRIBOS E NAÇÕES,\nAO REI DIVINO HONRAI! <bis>\nA QUEM QUEBROU VOSSOS GRILHÕES,\nCOM GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA, \nCOM GLÓRIA COROAI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (631, 'SÊ EXALTADO, Ó DEUS', 'SÊ EXALTADO, Ó DEUS', 'CORO\nSÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,\nSEJA TUA GLÓRIA SOBRE TODA A TERRA.\n\nGRANDE E MAJESTOSO, \nTODA A TERRA E O MAR PERTENCEM SÓ A TI;\nJUSTO, TÃO PODEROSO, MESMO DIANTE \nDE TUA GLÓRIA POSSO \nDIZER QUE TU VIVES EM MIM.\n\nCORO\nSÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,\nSEJA TUA GLÓRIA SOBRE TODA A TERRA.\n\nINSTRUMENTOS\n\nTU ÉS PERFEITO, SANTO E SOBERANO DEUS, \nDE TODA A TERRA TU ÉS REI;\nETERNO E TRIUNO, SUPREMO CRIADOR,\nA TI PRA SEMPRE CANTAREI;\nLOUVAR-TE-EI, SENHOR, ENTRE OS POVOS, \nCANTAR-TE-EI LOUVORES ENTRE AS NAÇÕES.\n\nCORO\nSÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,\nSEJA TUA GLÓRIA SOBRE TODA A TERRA.', '<coro>\nSÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,\nSEJA TUA GLÓRIA SOBRE TODA A TERRA.\n\nGRANDE E MAJESTOSO, \nTODA A TERRA E O MAR PERTENCEM SÓ A TI;\nJUSTO, TÃO PODEROSO, MESMO DIANTE \nDE TUA GLÓRIA POSSO \nDIZER QUE TU VIVES EM MIM.\n\n<coro>\nSÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,\nSEJA TUA GLÓRIA SOBRE TODA A TERRA.\n<instrumentos>\n\n\nTU ÉS PERFEITO, SANTO E SOBERANO DEUS, \nDE TODA A TERRA TU ÉS REI;\nETERNO E TRIUNO, SUPREMO CRIADOR,\nA TI PRA SEMPRE CANTAREI;\nLOUVAR-TE-EI, SENHOR, ENTRE OS POVOS, \nCANTAR-TE-EI LOUVORES ENTRE AS NAÇÕES.\n\n<coro>\nSÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,\nSEJA TUA GLÓRIA SOBRE TODA A TERRA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (632, 'MUITOS ANJOS LOUVAM', 'MUITOS ANJOS LOUVAM', 'MUITOS ANJOS LOUVAM\nA JESUS, O SALVADOR,\nENTOANDO ALELUIA\nÀQUELE QUE VIVO ESTÁ.\n\nCORO\nSANTO, SANTO, SANTO,\nSANTO ÉS, JESUS.\nINSTRUMENTOS\n\nNAS MANSÕES CELESTIAIS\nONDE OS SALVOS POR JESUS\nCOM UM BRADO DE VITÓRIA\nCANTAM EM UMA SÓ VOZ.\n\nCORO\nSANTO, SANTO, SANTO,\nSANTO ÉS, JESUS.\nINSTRUMENTOS\n\nNADA PODE COMPARAR\nCOM A GLÓRIA DO SENHOR,\nPARA OS SEUS ESCOLHIDOS\nUMA MORADA PREPAROU.\n\nCORO (2X)\nSANTO, SANTO, SANTO,\nSANTO ÉS, JESUS.\n\nFINAL: SANTO ÉS, JESUS.', 'MUITOS ANJOS LOUVAM\nA JESUS, O SALVADOR,\nENTOANDO ALELUIA\nÀQUELE QUE VIVO ESTÁ.<coro>\nSANTO, SANTO, SANTO,\nSANTO ÉS, JESUS.\n<instrumentos>\n\n\nNAS MANSÕES CELESTIAIS\nONDE OS SALVOS POR JESUS\nCOM UM BRADO DE VITÓRIA\nCANTAM EM UMA SÓ VOZ.<coro>\nSANTO, SANTO, SANTO,\nSANTO ÉS, JESUS.\n<instrumentos>\n\n\nNADA PODE COMPARAR\nCOM A GLÓRIA DO SENHOR,\nPARA OS SEUS ESCOLHIDOS\nUMA MORADA PREPAROU.<coro tipo=''2X''>\nSANTO, SANTO, SANTO,\nSANTO ÉS, JESUS.\n<final>SANTO ÉS, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (633, 'TE EXALTAREMOS', 'TE EXALTAREMOS', 'TE EXALTAREMOS PARA SEMPRE, Ó DEUS,\nETERNAMENTE COM NOSSO LOUVOR;\nAGRADECIDOS PELO QUE TENS FEITO,\nPELOS LIVRAMENTOS E PROVAÇÕES.\n\nCORO\nNÓS TE ADORAMOS E ENTREGAMOS\nEM GRATIDÃO, SENHOR AS NOSSAS VIDAS\nEM SACRIFÍCIO VIVO DE LOUVOR\nOFERECEMOS SEMPRE A TI, SENHOR.\n\nCOM NOSSOS LÁBIOS EXPRESSAREMOS\nNOSSA GRATIDÃO A TI, SENHOR,\nE A NOSSA ALEGRIA SERÁ RENOVADA\nA CADA INSTANTE POR TEU LOUVOR.\n\nCORO\nNÓS TE ADORAMOS E ENTREGAMOS\nEM GRATIDÃO, SENHOR AS NOSSAS VIDAS\nEM SACRIFÍCIO VIVO DE LOUVOR\nOFERECEMOS SEMPRE A TI, SENHOR.\n\nFINAL:\nNÓS TE ADORAMOS E ENTREGAMOS\nEM GRATIDÃO, SENHOR, AS NOSSAS VIDAS,\nE A NOSSA ALEGRIA SERÁ RENOVADA\nA CADA INSTANTE POR TEU LOUVOR.', 'TE EXALTAREMOS PARA SEMPRE, Ó DEUS,\nETERNAMENTE COM NOSSO LOUVOR;\nAGRADECIDOS PELO QUE TENS FEITO,\nPELOS LIVRAMENTOS E PROVAÇÕES.\n\n<coro>\nNÓS TE ADORAMOS E ENTREGAMOS\nEM GRATIDÃO, SENHOR AS NOSSAS VIDAS\nEM SACRIFÍCIO VIVO DE LOUVOR\nOFERECEMOS SEMPRE A TI, SENHOR.\n\nCOM NOSSOS LÁBIOS EXPRESSAREMOS\nNOSSA GRATIDÃO A TI, SENHOR,\nE A NOSSA ALEGRIA SERÁ RENOVADA\nA CADA INSTANTE POR TEU LOUVOR.\n\n<coro>\nNÓS TE ADORAMOS E ENTREGAMOS\nEM GRATIDÃO, SENHOR AS NOSSAS VIDAS\nEM SACRIFÍCIO VIVO DE LOUVOR\nOFERECEMOS SEMPRE A TI, SENHOR.\n\n\n<final>NÓS TE ADORAMOS E ENTREGAMOS\nEM GRATIDÃO, SENHOR, AS NOSSAS VIDAS,\nE A NOSSA ALEGRIA SERÁ RENOVADA\nA CADA INSTANTE POR TEU LOUVOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (634, 'GLORIOSO ÉS, JESUS', 'GLORIOSO ÉS, JESUS', 'GLORIOSO ÉS, JESUS, \nDIGNO DE TODO O LOUVOR;\nSOBERANO, REI DOS REIS,\nTODA ADORAÇÃO PERTENCE A TI.\n\nCORO \nSANTO, SANTO, SANTO, \nVENCEDOR, MEU SENHOR.\n\nMAJESTOSO SALVADOR, DEUS FORTE,\nPRÍNCIPE DA PAZ, CONSELHEIRO, EMANUEL,\nTODA ADORAÇÃO PERTENCE A TI.\n\nCORO (3X)\nSANTO, SANTO, SANTO, \nVENCEDOR, MEU SENHOR.', 'GLORIOSO ÉS, JESUS, \nDIGNO DE TODO O LOUVOR;\nSOBERANO, REI DOS REIS,\nTODA ADORAÇÃO PERTENCE A TI.<coro>\nSANTO, SANTO, SANTO, \nVENCEDOR, MEU SENHOR.\n\nMAJESTOSO SALVADOR, DEUS FORTE,\nPRÍNCIPE DA PAZ, CONSELHEIRO, EMANUEL,\nTODA ADORAÇÃO PERTENCE A TI.<coro tipo=''3X''>\nSANTO, SANTO, SANTO, \nVENCEDOR, MEU SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (635, 'ENTRONIZADO ESTÁ ENTRE AS NAÇÕES', 'ENTRONIZADO ESTÁ ENTRE AS NAÇÕES', 'ENTRONIZADO ESTÁ ENTRE AS NAÇÕES (BIS)\nPROCLAMAI A JESUS, O REI, \nO LEÃO DE JUDÁ \nQUE VENCEU E O LIVRO ABRIRÁ.\n\nCORO (2X)\nAO GRANDE REI, \nJESUS SENHOR, EXALTAI.\n\nINSTRUMENTOS\n\nANUNCIAI QUE JESUS VIRÁ\nE QUEM VENCER TUDO HERDARÁ,\nUM NOVO CÉU, UMA COROA DE GLÓRIA\nE EM RUAS DE OURO ANDAR.\n\nCORO (3X)\nAO GRANDE REI, \nJESUS SENHOR, EXALTAI.\n\nFINAL: \nAO GRANDE REI, EXALTAI.', 'ENTRONIZADO ESTÁ ENTRE AS NAÇÕES <bis>\nPROCLAMAI A JESUS, O REI, \nO LEÃO DE JUDÁ \nQUE VENCEU E O LIVRO ABRIRÁ.\n\n<coro tipo=''2X''>\nAO GRANDE REI, \nJESUS SENHOR, EXALTAI.\n<instrumentos>\n\n\nANUNCIAI QUE JESUS VIRÁ\nE QUEM VENCER TUDO HERDARÁ,\nUM NOVO CÉU, UMA COROA DE GLÓRIA\nE EM RUAS DE OURO ANDAR.\n\n<coro tipo=''3X''>\nAO GRANDE REI, \nJESUS SENHOR, EXALTAI.\n<final>AO GRANDE REI, EXALTAI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (636, 'LOUVAI A JESUS', 'LOUVAI A JESUS', '''LOUVAI A JESUS, O REI DOS REIS,\nLOUVAI O REI DOS REIS'',\nDIZ O ESPÍRITO DO SENHOR;\nPELAS OBRAS QUE FEZ, \nPELO SEU GRANDE AMOR, CANTAI, CANTAI;\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI,\n\nPELOS BENEFÍCIOS, LOUVAI, POR SUAS MARAVILHAS, \nLOUVAI, PELO GRANDE AMOR, LOUVAI, \nPELA SALVAÇÃO, LOUVAI,\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI.\n\n''LOUVAI A JESUS, O REI DOS REIS,\nLOUVAI O REI DOS REIS'',\nDIZ O ESPÍRITO DO SENHOR;\nPELAS OBRAS QUE FEZ, \nPELO SEU GRANDE AMOR, CANTAI, CANTAI;\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI,\n\nPELOS BENEFÍCIOS, LOUVAI,\nPOR SUAS MARAVILHAS, LOUVAI,\nPELO GRANDE AMOR, LOUVAI,\nPELA SALVAÇÃO, LOUVAI,\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI.\n\nFINAL: (2X)\nLOUVAI A JESUS, O REI DOS REIS,\nLOUVAI O REI DOS REIS.', '''LOUVAI A JESUS, O REI DOS REIS,<bis>\nLOUVAI O REI DOS REIS'',<bis>\nDIZ O ESPÍRITO DO SENHOR;\nPELAS OBRAS QUE FEZ, \nPELO SEU GRANDE AMOR, CANTAI, CANTAI;\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI,\n\nPELOS BENEFÍCIOS, LOUVAI, POR SUAS MARAVILHAS, \nLOUVAI, PELO GRANDE AMOR, LOUVAI, \nPELA SALVAÇÃO, LOUVAI,\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI.\n\n''LOUVAI A JESUS, O REI DOS REIS,<bis>\nLOUVAI O REI DOS REIS'',<bis>\nDIZ O ESPÍRITO DO SENHOR;\nPELAS OBRAS QUE FEZ, \nPELO SEU GRANDE AMOR, CANTAI, CANTAI;\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI,\n\nPELOS BENEFÍCIOS, LOUVAI,\nPOR SUAS MARAVILHAS, LOUVAI,\nPELO GRANDE AMOR, LOUVAI,\nPELA SALVAÇÃO, LOUVAI,\nLOUVAI AO SALVADOR, LOUVAI, LOUVAI.\n<final>(<bis tipo=''2''>\nLOUVAI A JESUS, O REI DOS REIS,\nLOUVAI O REI DOS REIS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (637, 'TODA A TERRA TE EXALTA', 'TODA A TERRA TE EXALTA', 'TODA A TERRA TE EXALTA, \nENGRANDECE O TEU NOME \nPELAS GRANDES MARAVILHAS QUE TENS FEITO;\nCOM PODER DOMINAS O MUNDO, \nREINAS SOBRE CÉU E MAR, \nÉS O CORDEIRO PROMETIDO \nQUE VEIO PRA SALVAR.\n\nCORO (2X) \nENGRANDECIDO SEJA O TEU NOME\nPOIS ÉS GRANDE ENTRE AS NAÇÕES,\nTE EXALTAREI ENQUANTO EU VIVER.\n\nINSTRUMENTOS\n\nOS MEUS LÁBIOS PRONUNCIAM \nTUA VERDADE DIA E NOITE, \nÉS O GRANDE EU SOU, \nETERNO EL-SHADAI;\nPOR AMOR VERTESTE SANGUE \nPRA DAR VIDA AO PECADOR; \nLOUVAREMOS AO TEU NOME, \nPOIS ÉS DIGNO DE LOUVOR.\n\nCORO (2X) \nENGRANDECIDO SEJA O TEU NOME\nPOIS ÉS GRANDE ENTRE AS NAÇÕES,\nTE EXALTAREI ENQUANTO EU VIVER.\n\nTE EXALTAREI ENQUANTO EU VIVER!\nENGRANDECIDO SEJA O TEU NOME, \nSENHOR REI, SENHOR, REDENTOR; \nLOUVAREI PARA SEMPRE O TEU NOME \nENQUANTO EM MIM HOUVER FÔLEGO DE VIDA; ENTRONIZADO ESTÁS ENTRE OS QUERUBINS, (M) \nTE LOUVAREI ATÉ O FIM, (H)\n(SIM, EU LOUVAREI)\nTE LOUVAREI ATÉ O FIM \n(HONRA E LOUVOR)\nTE LOUVAREI, SENHOR, ATÉ O FIM.', 'TODA A TERRA TE EXALTA, \nENGRANDECE O TEU NOME \nPELAS GRANDES MARAVILHAS QUE TENS FEITO;\nCOM PODER DOMINAS O MUNDO, \nREINAS SOBRE CÉU E MAR, \nÉS O CORDEIRO PROMETIDO \nQUE VEIO PRA SALVAR.\n\n<coro tipo=''2X''>\nENGRANDECIDO SEJA O TEU NOME\nPOIS ÉS GRANDE ENTRE AS NAÇÕES,\nTE EXALTAREI ENQUANTO EU VIVER.\n<instrumentos>\n\n\nOS MEUS LÁBIOS PRONUNCIAM \nTUA VERDADE DIA E NOITE, \nÉS O GRANDE EU SOU, \nETERNO EL-SHADAI;\nPOR AMOR VERTESTE SANGUE \nPRA DAR VIDA AO PECADOR; \nLOUVAREMOS AO TEU NOME, \nPOIS ÉS DIGNO DE LOUVOR.\n\n<coro tipo=''2X''>\nENGRANDECIDO SEJA O TEU NOME\nPOIS ÉS GRANDE ENTRE AS NAÇÕES,\nTE EXALTAREI ENQUANTO EU VIVER.\n\nTE EXALTAREI ENQUANTO EU VIVER!\nENGRANDECIDO SEJA O TEU NOME, \nSENHOR REI, SENHOR, REDENTOR; \nLOUVAREI PARA SEMPRE O TEU NOME \nENQUANTO EM MIM HOUVER FÔLEGO DE VIDA; ENTRONIZADO ESTÁS ENTRE OS QUERUBINS, <m> \nTE LOUVAREI ATÉ O FIM, <h>\n(SIM, EU LOUVAREI)\nTE LOUVAREI ATÉ O FIM \n(HONRA E LOUVOR)\nTE LOUVAREI, SENHOR, ATÉ O FIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (638, 'JESUS VEIO E SALVOU-ME', 'JESUS VEIO E SALVOU-ME', 'JESUS VEIO E SALVOU-ME E ASSIM TRANSFORMOU \nO MEU VIVER, AGORA POSSO ADORÁ-LO\nE CONFIAR POIS É O MEU SALVADOR.\n\nCORO\nDIGNO, SÓ ELE É DIGNO DE RECEBER \nHONRA E LOUVOR, POIS COMIGO ELE ESTÁ, \nNUNCA VAI ME DEIXAR;\nDIGNO É O SENHOR.\n\nINSTRUMENTOS\n\nVITÓRIAS ELE CONCEDE-ME\nE COM BÊNÇÃOS ENVOLVE O MEU SER\nE EM MIM RENOVA A CADA DIA\nA CERTEZA DA ETERNA SALVAÇÃO.\n\nCORO (2X)\nDIGNO, SÓ ELE É DIGNO DE RECEBER \nHONRA E LOUVOR, POIS COMIGO ELE ESTÁ, \nNUNCA VAI ME DEIXAR;\nDIGNO É O SENHOR.\n\nFINAL: DIGNO É O SENHOR. (3X)', 'JESUS VEIO E SALVOU-ME E ASSIM TRANSFORMOU \nO MEU VIVER, AGORA POSSO ADORÁ-LO\nE CONFIAR POIS É O MEU SALVADOR.\n\n<coro>\nDIGNO, SÓ ELE É DIGNO DE RECEBER \nHONRA E LOUVOR, POIS COMIGO ELE ESTÁ, \nNUNCA VAI ME DEIXAR;\nDIGNO É O SENHOR.\n<instrumentos>\n\n\nVITÓRIAS ELE CONCEDE-ME\nE COM BÊNÇÃOS ENVOLVE O MEU SER\nE EM MIM RENOVA A CADA DIA\nA CERTEZA DA ETERNA SALVAÇÃO.\n\n<coro tipo=''2X''>\nDIGNO, SÓ ELE É DIGNO DE RECEBER \nHONRA E LOUVOR, POIS COMIGO ELE ESTÁ, \nNUNCA VAI ME DEIXAR;\nDIGNO É O SENHOR.\n<final>DIGNO É O SENHOR. <bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (639, 'MOTIVOS TENHO PRA LOUVAR-TE', 'MOTIVOS TENHO PRA LOUVAR-TE', 'MOTIVOS TENHO PRA LOUVAR-TE, Ó DEUS,\nMOTIVOS TENHO PRA DIZER: GLÓRIA A DEUS!\nMOTIVOS TENHO PRA DIZER QUE TU NÃO MUDASTE,\nMOTIVOS TENHO PRA FALAR DO TEU AMOR.\n\nPELO QUE TU FIZESTE NA TUA OBRA,\nPELO TEU POVO QUE A TI SE DEDICOU,\nNA EXISTÊNCIA VIVA DO ESPÍRITO.\n\nPOR TUA OBRA E TEU PODER, \nPELO TEU POVO SUSTENTADO AQUI.\nPOR TUA OBRA E TEU PODER, \nPELO TEU POVO SUSTENTADO AQUI.', 'MOTIVOS TENHO PRA LOUVAR-TE, Ó DEUS,\nMOTIVOS TENHO PRA DIZER: GLÓRIA A DEUS!\nMOTIVOS TENHO PRA DIZER QUE TU NÃO MUDASTE,\nMOTIVOS TENHO PRA FALAR DO TEU AMOR.\n\nPELO QUE TU FIZESTE NA TUA OBRA,\nPELO TEU POVO QUE A TI SE DEDICOU,\nNA EXISTÊNCIA VIVA DO ESPÍRITO.\n\nPOR TUA OBRA E TEU PODER, \nPELO TEU POVO SUSTENTADO AQUI.\nPOR TUA OBRA E TEU PODER, \nPELO TEU POVO SUSTENTADO AQUI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (640, 'MEU LOUVOR É SÓ PRA TI', 'MEU LOUVOR É SÓ PRA TI', 'MEU LOUVOR É SÓ PRA TI, SENHOR, \nMEU SALVADOR,\nGRANDE AUTOR DA MINHA FÉ;\nTODA A MINHA ADORAÇÃO,\nSENHOR, PERTENCE A TI,\nMEU ETERNO REDENTOR.\n\nPORQUE MUDASTE O MEU VIVER, \nE ME GUIASTE NA TUA LUZ,\nPORQUE COMPRASTE A MINHA VIDA, \nMEU SENHOR, SOU GRATO, SENHOR.\n\nMEU LOUVOR É SÓ PRA TI, SENHOR, \nMEU SALVADOR, GRANDE AUTOR DA MINHA FÉ;\nTODA A MINHA ADORAÇÃO, SENHOR, \nPERTENCE A TI, MEU ETERNO REDENTOR.\n\nPORQUE MUDASTE O MEU VIVER\nE ME GUIASTE NA TUA LUZ,\nPORQUE COMPRASTE A MINHA VIDA, \nMEU SENHOR,\nSOU GRATO, JESUS,\n(SOU GRATO, JESUS) \nSOU GRATO, JESUS,\n(SOU GRATO, JESUS) \nSOU GRATO, JESUS.', 'MEU LOUVOR É SÓ PRA TI, SENHOR, \nMEU SALVADOR,\nGRANDE AUTOR DA MINHA FÉ;\nTODA A MINHA ADORAÇÃO,\nSENHOR, PERTENCE A TI,\nMEU ETERNO REDENTOR.\n\nPORQUE MUDASTE O MEU VIVER, \nE ME GUIASTE NA TUA LUZ,\nPORQUE COMPRASTE A MINHA VIDA, \nMEU SENHOR, SOU GRATO, SENHOR.\n\nMEU LOUVOR É SÓ PRA TI, SENHOR, \nMEU SALVADOR, GRANDE AUTOR DA MINHA FÉ;\nTODA A MINHA ADORAÇÃO, SENHOR, \nPERTENCE A TI, MEU ETERNO REDENTOR.\n\nPORQUE MUDASTE O MEU VIVER\nE ME GUIASTE NA TUA LUZ,\nPORQUE COMPRASTE A MINHA VIDA, \nMEU SENHOR,\nSOU GRATO, JESUS,\n(SOU GRATO, JESUS) \nSOU GRATO, JESUS,\n(SOU GRATO, JESUS) \nSOU GRATO, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (641, 'A LUZ DO MUNDO', 'A LUZ DO MUNDO', 'A LUZ DO MUNDO, O LÍRIO DOS VALES, \nA FONTE DE ÁGUAS VIVAS, EMANUEL;\nO VERBO VIVO, RAIZ DE DAVI,\nESTRELA DA MANHÃ, REI DOS REIS.\nCOMO CANTAR O NOSSO AMOR\nE NOSSA GRATIDÃO POR TEU FAVOR?\n\nCORO\nGLÓRIA, HONRA E TODO LOUVOR\nSEJAM A CRISTO, NOSSO SENHOR;\nGLÓRIA, HONRA E TODO LOUVOR\nDAI A CRISTO, ETERNO SENHOR.\n\nVENCEU A MORTE\n(VENCEU A MORTE) VARÕES\nNOS RESGATOU,\n(NOS RESGATOU) VARÕES\nMOSTROU A TODA A TERRA\nQUE É SENHOR; NADA NO MUNDO \n(NADA NO MUNDO) VARÕES\nO IMPEDIRÁ.\n(O IMPEDIRÁ) VARÕES\nJESUS RESSUSCITOU E VAI VOLTAR.\n\nCORO (2X)\nGLÓRIA, HONRA E TODO LOUVOR\nSEJAM A CRISTO, NOSSO SENHOR;\nGLÓRIA, HONRA E TODO LOUVOR\nDAI A CRISTO, ETERNO SENHOR.\n\nFINAL: ETERNO SENHOR.', 'A LUZ DO MUNDO, O LÍRIO DOS VALES, \nA FONTE DE ÁGUAS VIVAS, EMANUEL;\nO VERBO VIVO, RAIZ DE DAVI,\nESTRELA DA MANHÃ, REI DOS REIS.\nCOMO CANTAR O NOSSO AMOR\nE NOSSA GRATIDÃO POR TEU FAVOR?\n\n<coro>\nGLÓRIA, HONRA E TODO LOUVOR\nSEJAM A CRISTO, NOSSO SENHOR;\nGLÓRIA, HONRA E TODO LOUVOR\nDAI A CRISTO, ETERNO SENHOR.\n\nVENCEU A MORTE\n(VENCEU A MORTE) <h>\nNOS RESGATOU,\n(NOS RESGATOU) <h>\nMOSTROU A TODA A TERRA\nQUE É SENHOR; NADA NO MUNDO \n(NADA NO MUNDO) <h>\nO IMPEDIRÁ.\n(O IMPEDIRÁ) <h>\nJESUS RESSUSCITOU E VAI VOLTAR.\n\n<coro tipo=''2X''>\nGLÓRIA, HONRA E TODO LOUVOR\nSEJAM A CRISTO, NOSSO SENHOR;\nGLÓRIA, HONRA E TODO LOUVOR\nDAI A CRISTO, ETERNO SENHOR.\n<final>ETERNO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (642, 'EM NOSSOS LÁBIOS', 'EM NOSSOS LÁBIOS', 'EM NOSSOS LÁBIOS \nSEMPRE HAVERÁ UM CANTO A TI, JESUS, \nPOR TUDO QUE TENS FEITO E POR TUDO \nQUE FARÁS EM NOSSAS VIDAS.\n\nQUEREMOS EXPRESSAR NOSSO AMOR E GRATIDÃO \nA TI, JESUS, PELA TUA SALVAÇÃO E PELO TEU PERDÃO, RESGATANDO-NOS PRA TUA ADORAÇÃO,\nO TEU AMOR NOS SUSTENTA, SENHOR,\nA TUA GRAÇA RENOVA OS CORAÇÕES E NOS BASTA.\n\nCORO\nTODO LOUVOR E ADORAÇÃO\nPERTENCEM A TI ETERNAMENTE,\nNOSSAS VIDAS, Ó SENHOR, \nENTREGAMOS EM TEU ALTAR \nPRA TE ADORAR, JESUS.\n\nINSTRUMENTOS\n\nFAZ DE NÓS, SENHOR, UM VASO\nEM TUAS MÃOS PARA EXPRESSAR.\n\nCORO\nTODO LOUVOR E ADORAÇÃO \nPERTENCEM A TI ETERNAMENTE,\nNOSSAS VIDAS, Ó SENHOR, \nENTREGAMOS EM TEU ALTAR \nPRA TE ADORAR, JESUS.\n\nINSTRUMENTOS\n\nEM NOSSOS LÁBIOS SEMPRE HAVERÁ \nUM CANTO A TI, JESUS, \nPOR TUDO QUE TENS FEITO \nE POR TUDO QUE FARÁS \nEM NOSSAS VIDAS.', 'EM NOSSOS LÁBIOS \nSEMPRE HAVERÁ UM CANTO A TI, JESUS, \nPOR TUDO QUE TENS FEITO E POR TUDO \nQUE FARÁS EM NOSSAS VIDAS.\n\nQUEREMOS EXPRESSAR NOSSO AMOR E GRATIDÃO \nA TI, JESUS, PELA TUA SALVAÇÃO E PELO TEU PERDÃO, RESGATANDO-NOS PRA TUA ADORAÇÃO,\nO TEU AMOR NOS SUSTENTA, SENHOR,\nA TUA GRAÇA RENOVA OS CORAÇÕES E NOS BASTA.\n\n<coro>\nTODO LOUVOR E ADORAÇÃO\nPERTENCEM A TI ETERNAMENTE,\nNOSSAS VIDAS, Ó SENHOR, \nENTREGAMOS EM TEU ALTAR \nPRA TE ADORAR, JESUS.\n<instrumentos>\nFAZ DE NÓS, SENHOR, UM VASO\nEM TUAS MÃOS PARA EXPRESSAR.\n\n<coro>\nTODO LOUVOR E ADORAÇÃO \nPERTENCEM A TI ETERNAMENTE,\nNOSSAS VIDAS, Ó SENHOR, \nENTREGAMOS EM TEU ALTAR \nPRA TE ADORAR, JESUS.\n<instrumentos>\n\n\nEM NOSSOS LÁBIOS SEMPRE HAVERÁ \nUM CANTO A TI, JESUS, \nPOR TUDO QUE TENS FEITO \nE POR TUDO QUE FARÁS \nEM NOSSAS VIDAS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (643, 'TODO LOUVOR SEJA DADO A DEUS', 'TODO LOUVOR SEJA DADO A DEUS', 'TODO LOUVOR SEJA DADO A DEUS,\nPOR TUDO QUE TEM FEITO EM NOSSAS VIDAS,\nNOSSA GRATIDÃO A JESUS O REI, \nFOI ELE QUEM NOS SUSTENTOU ATÉ AQUI.\n\nPOR ISSO RENDEMOS UM LOUVOR AO REI JESUS\nE ENTREGAMOS NOSSAS VIDAS AO SEU DISPOR.\n\nCORO\nLOUVEMOS AO SENHOR QUE É JUSTO \nE PODEROSO, É QUEM NOS GUIA,\nA SUA GRAÇA ESTÁ EM NOSSO MEIO,\nA SUA PRESENÇA É VIVA A CADA INSTANTE.\n\nINSTRUMENTOS\n\nTODO LOUVOR SEJA DADO A DEUS, \nPOR TUDO QUE TEM FEITO EM NOSSAS VIDAS,\nNOSSA GRATIDÃO A JESUS O REI, \nFOI ELE QUEM NOS SUSTENTOU ATÉ AQUI.\n\nPOR ISSO RENDEMOS UM LOUVOR AO REI JESUS\nE ENTREGAMOS NOSSAS VIDAS AO SEU DISPOR.\n\nCORO (2X)\nLOUVEMOS AO SENHOR QUE É JUSTO \nE PODEROSO, É QUEM NOS GUIA,\nA SUA GRAÇA ESTÁ EM NOSSO MEIO, \nA SUA PRESENÇA É VIVA A CADA INSTANTE.\n\nFINAL: DE NOSSAS VIDAS.', 'TODO LOUVOR SEJA DADO A DEUS,\nPOR TUDO QUE TEM FEITO EM NOSSAS VIDAS,\nNOSSA GRATIDÃO A JESUS O REI, \nFOI ELE QUEM NOS SUSTENTOU ATÉ AQUI.\n\nPOR ISSO RENDEMOS UM LOUVOR AO REI JESUS\nE ENTREGAMOS NOSSAS VIDAS AO SEU DISPOR.<coro>\nLOUVEMOS AO SENHOR QUE É JUSTO \nE PODEROSO, É QUEM NOS GUIA,\nA SUA GRAÇA ESTÁ EM NOSSO MEIO,\nA SUA PRESENÇA É VIVA A CADA INSTANTE.\n<instrumentos>\n\n\nTODO LOUVOR SEJA DADO A DEUS, \nPOR TUDO QUE TEM FEITO EM NOSSAS VIDAS,\nNOSSA GRATIDÃO A JESUS O REI, \nFOI ELE QUEM NOS SUSTENTOU ATÉ AQUI.\n\nPOR ISSO RENDEMOS UM LOUVOR AO REI JESUS\nE ENTREGAMOS NOSSAS VIDAS AO SEU DISPOR.\n\n<coro tipo=''2X''>\nLOUVEMOS AO SENHOR QUE É JUSTO \nE PODEROSO, É QUEM NOS GUIA,\nA SUA GRAÇA ESTÁ EM NOSSO MEIO, \nA SUA PRESENÇA É VIVA A CADA INSTANTE.\n<final>DE NOSSAS VIDAS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (644, 'LOUVAMOS-TE, Ó DEUS', 'LOUVAMOS-TE, Ó DEUS', 'LOUVAMOS-TE, Ó DEUS, \nPELO DOM DE JESUS,\nQUE POR NÓS, PECADORES, \nFOI MORTO NA CRUZ.\n\nCORO\nALELUIA! TODA A GLÓRIA \nTE RENDEMOS SEM FIM;\nALELUIA! TUA GRAÇA IMPLORAMOS. \nAMÉM.\n\nLOUVAMOS-TE, Ó DEUS,\nPELO ESPÍRITO E SUA LUZ,\nQUE AS TREVAS DISSIPA, \nE A CRISTO CONDUZ\n\nCORO\nALELUIA! TODA A GLÓRIA \nTE RENDEMOS SEM FIM;\nALELUIA! TUA GRAÇA IMPLORAMOS. \nAMÉM.\n\nLOUVAMOS-TE, SENHOR, \nÓ CORDEIRO DE DEUS,\nFOSTE MORTO, MAS VIVES, \nETERNO, NOS CÉUS.\n\nCORO\nALELUIA! TODA A GLÓRIA \nTE RENDEMOS SEM FIM;\nALELUIA! TUA GRAÇA IMPLORAMOS. \nAMÉM.\n\nVEM ENCHER-NOS, Ó DEUS, \nDE CELESTE ARDOR\nE FAZER-NOS SENTIR \nTEU IMENSO AMOR.', 'LOUVAMOS-TE, Ó DEUS, \nPELO DOM DE JESUS,\nQUE POR NÓS, PECADORES, \nFOI MORTO NA CRUZ.\n\n<coro>\nALELUIA! TODA A GLÓRIA \nTE RENDEMOS SEM FIM;\nALELUIA! TUA GRAÇA IMPLORAMOS. \nAMÉM.\n\nLOUVAMOS-TE, Ó DEUS,\nPELO ESPÍRITO E SUA LUZ,\nQUE AS TREVAS DISSIPA, \nE A CRISTO CONDUZ\n\n<coro>\nALELUIA! TODA A GLÓRIA \nTE RENDEMOS SEM FIM;\nALELUIA! TUA GRAÇA IMPLORAMOS. \nAMÉM.\n\nLOUVAMOS-TE, SENHOR, \nÓ CORDEIRO DE DEUS,\nFOSTE MORTO, MAS VIVES, \nETERNO, NOS CÉUS.\n\n<coro>\nALELUIA! TODA A GLÓRIA \nTE RENDEMOS SEM FIM;\nALELUIA! TUA GRAÇA IMPLORAMOS. \nAMÉM.\n\nVEM ENCHER-NOS, Ó DEUS, \nDE CELESTE ARDOR\nE FAZER-NOS SENTIR \nTEU IMENSO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (645, 'COROAI', 'COROAI', 'COROAI O QUE É DIGNO E BENDITO SOBRE A TERRA,\nEXALTAI O SEU NOME COM LOUVORES DE VITÓRIA;\nO SEU NOME ENTRE TODAS AS NAÇÕES SERÁ LOUVADO;\n(O CORDEIRO ENTRE TODAS AS NAÇÕES SERÁ LOUVADO)\nOH! JESUS, MEU SENHOR, REINARÁ.\n\nREINARÁ COM PODER E GLÓRIA SOBRE TODA A TERRA,\nTODO HOMEM DIANTE DO SEU TRONO SE ENCURVARÁ;\nCONTEMPLAI O CORDEIRO ETERNO QUE RESSUSCITOU,\n(DAI LOUVORES AO CORDEIRO ETERNO, QUE RESSUSCITOU)\nSOBRE AS NUVENS DESCERÁ E REINARÁ.\n\nINSTRUMENTOS\n\nREINARÁ COM PODER E GLÓRIA SOBRE TODA A TERRA,\nTODO HOMEM DIANTE DO SEU TRONO SE ENCURVARÁ;\nCONTEMPLAI O CORDEIRO ETERNO QUE RESSUSCITOU,\n(DAI LOUVORES AO CORDEIRO ETERNO, QUE RESSUSCITOU)\nSOBRE AS NUVENS DESCERÁ E REINARÁ.\n\nFINAL: COROAI.', 'COROAI O QUE É DIGNO E BENDITO SOBRE A TERRA,\nEXALTAI O SEU NOME COM LOUVORES DE VITÓRIA;\nO SEU NOME ENTRE TODAS AS NAÇÕES SERÁ LOUVADO;\n(O CORDEIRO ENTRE TODAS AS NAÇÕES SERÁ LOUVADO)\nOH! JESUS, MEU SENHOR, REINARÁ.\n\nREINARÁ COM PODER E GLÓRIA SOBRE TODA A TERRA,\nTODO HOMEM DIANTE DO SEU TRONO SE ENCURVARÁ;\nCONTEMPLAI O CORDEIRO ETERNO QUE RESSUSCITOU,\n(DAI LOUVORES AO CORDEIRO ETERNO, QUE RESSUSCITOU)\nSOBRE AS NUVENS DESCERÁ E REINARÁ.\n<instrumentos>\n\n\nREINARÁ COM PODER E GLÓRIA SOBRE TODA A TERRA,\nTODO HOMEM DIANTE DO SEU TRONO SE ENCURVARÁ;\nCONTEMPLAI O CORDEIRO ETERNO QUE RESSUSCITOU,\n(DAI LOUVORES AO CORDEIRO ETERNO, QUE RESSUSCITOU)\nSOBRE AS NUVENS DESCERÁ E REINARÁ.\n<final>COROAI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (646, 'AGRADECIDOS SOMOS A TI', 'AGRADECIDOS SOMOS A TI', 'AGRADECIDOS SOMOS A TI, MEU REI JESUS, \nPELA GRAÇA E PELA VIDA QUE HOJE HÁ EM NÓS;\nGRATOS SOMOS POR TÃO GRANDE AMOR\nDEMONSTRADO NO MADEIRO, \nTU ÉS MEU SALVADOR.\n\nALELUIA TE DAMOS, Ó MEU SENHOR PELA PAZ \nQUE HOJE HABITA EM NOSSOS CORAÇÕES;\nPOR NÓS JESUS MORREU, QUE DOR ELE SENTIU, \nMAS AO TERCEIRO DIA ELE RESSURGIU.\n\nALELUIA TE DAMOS, Ó MEU SENHOR,\nPELA PAZ QUE HOJE HABITA \nEM NOSSOS CORAÇÕES;\nE HOJE VIVO ESTÁ À DESTRA \nDE DEUS PAI AGUARDANDO \nA HORA CERTA PARA VIR NOS BUSCAR.\n\nALELUIA TE DAMOS, Ó MEU SENHOR,\nPELA PAZ QUE HOJE HABITA \nEM NOSSOS CORAÇÕES;\nPOR NÓS JESUS MORREU,\nMAS AO TERCEIRO DIA ELE RESSURGIU.\n\nFINAL:\nAGRADECIDOS SOMOS A TI, \nMEU REI JESUS, PELA GRAÇA \nE PELA VIDA QUE HOJE HÁ EM NÓS, \nQUE HOJE HÁ EM NÓS.', 'AGRADECIDOS SOMOS A TI, MEU REI JESUS, \nPELA GRAÇA E PELA VIDA QUE HOJE HÁ EM NÓS;\nGRATOS SOMOS POR TÃO GRANDE AMOR\nDEMONSTRADO NO MADEIRO, \nTU ÉS MEU SALVADOR.\n\nALELUIA TE DAMOS, Ó MEU SENHOR PELA PAZ \nQUE HOJE HABITA EM NOSSOS CORAÇÕES;\nPOR NÓS JESUS MORREU, QUE DOR ELE SENTIU, \nMAS AO TERCEIRO DIA ELE RESSURGIU.\n\nALELUIA TE DAMOS, Ó MEU SENHOR,\nPELA PAZ QUE HOJE HABITA \nEM NOSSOS CORAÇÕES;\nE HOJE VIVO ESTÁ À DESTRA \nDE DEUS PAI AGUARDANDO \nA HORA CERTA PARA VIR NOS BUSCAR.\n\nALELUIA TE DAMOS, Ó MEU SENHOR,\nPELA PAZ QUE HOJE HABITA \nEM NOSSOS CORAÇÕES;\nPOR NÓS JESUS MORREU,\nMAS AO TERCEIRO DIA ELE RESSURGIU.\n\n\n<final>AGRADECIDOS SOMOS A TI, \nMEU REI JESUS, PELA GRAÇA \nE PELA VIDA QUE HOJE HÁ EM NÓS, \nQUE HOJE HÁ EM NÓS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (647, 'SANTO, SANTO, SANTO É O SENHOR', 'SANTO, SANTO, SANTO É O SENHOR', 'SANTO, SANTO, SANTO É O SENHOR, \nSANTO É O SENHOR, DEUS PODEROSO. \nQUE ERA, QUE É E O QUE HÁ DE VIR,\nSANTO, SANTO, SANTO É O SENHOR.\n\nJUSTO, JUSTO, JUSTO É O SENHOR, \nJUSTO É O SENHOR, DEUS PODEROSO. \nQUE ERA, QUE É E O QUE HÁ DE VIR,\nJUSTO, JUSTO, JUSTO É O SENHOR.\n\nFORTE, FORTE, FORTE É O SENHOR, \nFORTE É O SENHOR, DEUS PODEROSO. \nQUE ERA, QUE É E O QUE HÁ DE VIR,\nFORTE, FORTE, FORTE É O SENHOR.\nFORTE, FORTE, FORTE É O SENHOR.\n\nFINAL: (3X)\nSANTO, JUSTO, FORTE É O SENHOR.', 'SANTO, SANTO, SANTO É O SENHOR, <bis>\nSANTO É O SENHOR, DEUS PODEROSO. <bis>\nQUE ERA, QUE É E O QUE HÁ DE VIR,\nSANTO, SANTO, SANTO É O SENHOR.\n\nJUSTO, JUSTO, JUSTO É O SENHOR, <bis>\nJUSTO É O SENHOR, DEUS PODEROSO. <bis>\nQUE ERA, QUE É E O QUE HÁ DE VIR,\nJUSTO, JUSTO, JUSTO É O SENHOR.\n\nFORTE, FORTE, FORTE É O SENHOR, <bis>\nFORTE É O SENHOR, DEUS PODEROSO. <bis>\nQUE ERA, QUE É E O QUE HÁ DE VIR,\nFORTE, FORTE, FORTE É O SENHOR.\nFORTE, FORTE, FORTE É O SENHOR.\n<final>(<bis tipo=''3''>\nSANTO, JUSTO, FORTE É O SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (648, 'O SENHOR É O MEU PASTOR (MINH''ALMA CANTARÁ)', 'O SENHOR É O MEU PASTOR (MINH''ALMA CANTARÁ)', 'O SENHOR É O MEU PASTOR \nE NADA ME FALTARÁ, \nO DESERTO OU O VALE \nELE OS TRANSFORMARÁ, \nEM MANANCIAIS DE ÁGUAS,\nMINHA VIDA FARTARÁ.\n\n(M)\n\n(H)\n\nCORO (2X)\nMINH''ALMA CANTARÁ,\nE ANUNCIARÁ O TEU LOUVOR,\nSENHOR, MEU REI!\n\nDAVI OROU, LUTOU, SALMODIOU, VENCEU.\nSENHOR, MEU DEUS, ESTOU AQUI\nPARA TE HONRAR.\n\nCORO (2X)\nMINH''ALMA CANTARÁ,\nE ANUNCIARÁ O TEU LOUVOR,\nSENHOR, MEU REI!\n\nJESUS, FILHO DE DEUS, \nO NOSSO BOM PASTOR,\nNOS RESGATOU PARA HERDARMOS \nA GLÓRIA ETERNA\n\nCORO (2X)\nMINH''ALMA CANTARÁ,\nE ANUNCIARÁ O TEU LOUVOR,\nSENHOR, MEU REI!\n\nFINAL: \nO TEU LOUVOR, SENHOR, MEU REI!', 'O SENHOR É O MEU PASTOR \nE NADA ME FALTARÁ, \nO DESERTO OU O VALE \nELE OS TRANSFORMARÁ, \nEM MANANCIAIS DE ÁGUAS,\nMINHA VIDA FARTARÁ.\n\n<m>\n\n<h>\n\n<coro tipo=''2X''>\nMINH''ALMA CANTARÁ,\nE ANUNCIARÁ O TEU LOUVOR,\nSENHOR, MEU REI!\n\nDAVI OROU, LUTOU, SALMODIOU, VENCEU.\nSENHOR, MEU DEUS, ESTOU AQUI\nPARA TE HONRAR.\n\n<coro tipo=''2X''>\nMINH''ALMA CANTARÁ,\nE ANUNCIARÁ O TEU LOUVOR,\nSENHOR, MEU REI!\n\nJESUS, FILHO DE DEUS, \nO NOSSO BOM PASTOR,\nNOS RESGATOU PARA HERDARMOS \nA GLÓRIA ETERNA\n\n<coro tipo=''2X''>\nMINH''ALMA CANTARÁ,\nE ANUNCIARÁ O TEU LOUVOR,\nSENHOR, MEU REI!\n<final>O TEU LOUVOR, SENHOR, MEU REI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (649, 'TE LOUVAMOS, SENHOR', 'TE LOUVAMOS, SENHOR', 'TE LOUVAMOS, SENHOR, PELO TEU AMOR\n(TE LOUVAMOS, SENHOR)\nTUA GRAÇA É REAL, NOS ACEITA COMO FILHOS.\nBENDIZEMOS, SENHOR, PELO TEU SANTO NOME\n(BENDIZEMOS, SENHOR)\nNO TEU NOME ESTÁ TODA A TUA GLÓRIA.\n\nCORO\nVAMOS TE ADORAR (TE ADORAR),\nE TE BENDIZER (TE BENDIZER),\nPELAS MUITAS MARAVILHAS QUE TENS FEITO.\nPOR NOS ALCANÇAR (NOS ALCANÇAR),\nLIVRAR-NOS DA MORTE,\nE POR DAR-NOS DE GRAÇA \nUMA VIDA ETERNA.\n\nTE LOUVAMOS, SENHOR, PELO TEU AMOR\n(TE LOUVAMOS, SENHOR)\nTUA GRAÇA É REAL, NOS ACEITA COMO FILHOS.\nBENDIZEMOS, SENHOR, PELO TEU SANTO NOME\n(BENDIZEMOS, SENHOR)\nNO TEU NOME ESTÁ TODA A TUA GLÓRIA.\n\nCORO (2X)\nVAMOS TE ADORAR (TE ADORAR),\nE TE BENDIZER (TE BENDIZER),\nPELAS MUITAS MARAVILHAS QUE TENS FEITO.\nPOR NOS ALCANÇAR (NOS ALCANÇAR),\nLIVRAR-NOS DA MORTE,\nE POR DAR-NOS DE GRAÇA \nUMA VIDA ETERNA.', 'TE LOUVAMOS, SENHOR, PELO TEU AMOR\n(TE LOUVAMOS, SENHOR)\nTUA GRAÇA É REAL, NOS ACEITA COMO FILHOS.\nBENDIZEMOS, SENHOR, PELO TEU SANTO NOME\n(BENDIZEMOS, SENHOR)\nNO TEU NOME ESTÁ TODA A TUA GLÓRIA.\n\n<coro>\nVAMOS TE ADORAR (TE ADORAR),\nE TE BENDIZER (TE BENDIZER),\nPELAS MUITAS MARAVILHAS QUE TENS FEITO.\nPOR NOS ALCANÇAR (NOS ALCANÇAR),\nLIVRAR-NOS DA MORTE,\nE POR DAR-NOS DE GRAÇA \nUMA VIDA ETERNA.\n\nTE LOUVAMOS, SENHOR, PELO TEU AMOR\n(TE LOUVAMOS, SENHOR)\nTUA GRAÇA É REAL, NOS ACEITA COMO FILHOS.\nBENDIZEMOS, SENHOR, PELO TEU SANTO NOME\n(BENDIZEMOS, SENHOR)\nNO TEU NOME ESTÁ TODA A TUA GLÓRIA.\n\n<coro tipo=''2X''>\nVAMOS TE ADORAR (TE ADORAR),\nE TE BENDIZER (TE BENDIZER),\nPELAS MUITAS MARAVILHAS QUE TENS FEITO.\nPOR NOS ALCANÇAR (NOS ALCANÇAR),\nLIVRAR-NOS DA MORTE,\nE POR DAR-NOS DE GRAÇA \nUMA VIDA ETERNA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (650, 'Ó VINDE E ADOREMOS', 'Ó VINDE E ADOREMOS', 'Ó VINDE E ADOREMOS\nE PROSTREMOS DIANTE DO SENHOR;\nSE OUVIRDES A SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES.\n\nÓ VINDE A JESUS,\nNÃO ENDUREÇAIS OS VOSSOS CORAÇÕES,\nACEITAI A CRISTO, A SALVAÇÃO.\n\nINSTRUMENTOS\n\nÓ VINDE E ADOREMOS\nE PROSTREMOS DIANTE DO SENHOR;\nSE OUVIRDES A SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES.\n\nÓ VINDE A JESUS,\nNÃO ENDUREÇAIS OS VOSSOS CORAÇÕES,\nACEITAI A CRISTO, A SALVAÇÃO.\n\nFINAL: JESUS, SÓ JESUS, O SALVADOR, JESUS.', 'Ó VINDE E ADOREMOS\nE PROSTREMOS DIANTE DO SENHOR;\nSE OUVIRDES A SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES.\n\nÓ VINDE A JESUS,<bis>\nNÃO ENDUREÇAIS OS VOSSOS CORAÇÕES,<bis>\nACEITAI A CRISTO, A SALVAÇÃO.<bis>\n<instrumentos>\n\n\nÓ VINDE E ADOREMOS\nE PROSTREMOS DIANTE DO SENHOR;\nSE OUVIRDES A SUA VOZ NÃO ENDUREÇAIS \nOS VOSSOS CORAÇÕES.\n\nÓ VINDE A JESUS,<bis>\nNÃO ENDUREÇAIS OS VOSSOS CORAÇÕES,<bis>\nACEITAI A CRISTO, A SALVAÇÃO.<bis>\n<final>JESUS, SÓ JESUS, O SALVADOR, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (651, 'AMO AO SENHOR', 'AMO AO SENHOR', 'AMO AO SENHOR, O DEUS DOS DEUSES,\nSENHOR DOS SENHORES, \nQUE OUVE A MINHA VOZ E AS MINHAS SÚPLICAS,\nMESMO NO MEIO DA ANGÚSTIA INVOCO \nO NOME DO SENHOR E SOU SALVO.\n\nQUE DAREI EU AO SENHOR\nPOR TUDO O QUE ME TEM FEITO?\nTOMAREI O CÁLICE DA SALVAÇÃO,\nOFERECEREI SACRIFÍCIOS DE LOUVOR\nNOS ÁTRIOS DA CASA DO SENHOR.\n\nLOUVAI AO SEU NOME, LOUVAI, LOUVAI,\nLOUVAI AO SEU NOME, LOUVAI, LOUVAI.\n\nINSTRUMENTOS\n\nAMO AO SENHOR, O DEUS DOS DEUSES,\nSENHOR DOS SENHORES, \nQUE OUVE A MINHA VOZ E AS MINHAS SÚPLICAS,\nMESMO NO MEIO DA ANGÚSTIA INVOCO \nO NOME DO SENHOR E SOU SALVO.\n\nFINAL: \nAO SEU NOME LOUVAI, LOUVAI, \nLOUVAI AO SEU NOME, LOUVAI, LOUVAI.', 'AMO AO SENHOR, O DEUS DOS DEUSES,\nSENHOR DOS SENHORES, \nQUE OUVE A MINHA VOZ E AS MINHAS SÚPLICAS,\nMESMO NO MEIO DA ANGÚSTIA INVOCO \nO NOME DO SENHOR E SOU SALVO.\n\nQUE DAREI EU AO SENHOR\nPOR TUDO O QUE ME TEM FEITO?\nTOMAREI O CÁLICE DA SALVAÇÃO,\nOFERECEREI SACRIFÍCIOS DE LOUVOR\nNOS ÁTRIOS DA CASA DO SENHOR.\n\nLOUVAI AO SEU NOME, LOUVAI, LOUVAI,\nLOUVAI AO SEU NOME, LOUVAI, LOUVAI.\n<instrumentos>\n\n\nAMO AO SENHOR, O DEUS DOS DEUSES,\nSENHOR DOS SENHORES, \nQUE OUVE A MINHA VOZ E AS MINHAS SÚPLICAS,\nMESMO NO MEIO DA ANGÚSTIA INVOCO \nO NOME DO SENHOR E SOU SALVO.\n<final>AO SEU NOME LOUVAI, LOUVAI, \nLOUVAI AO SEU NOME, LOUVAI, LOUVAI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (652, 'LEVANTAI-VOS, Ó PORTAIS ETERNOS', 'LEVANTAI-VOS, Ó PORTAIS ETERNOS', 'LEVANTAI-VOS, Ó PORTAIS ETERNOS,\nPRA QUE ENTRE O REI DA GLÓRIA;\nQUEM É ESSE REI DA GLÓRIA?\nO SENHOR DOS EXÉRCITOS, \nELE É O REI DA GLÓRIA, \nELE É O REI DA GLÓRIA.\n\nLEVANTAI-VOS, Ó PORTAIS ETERNOS,\nE ENTRARÁ O REI DA GLÓRIA;\nO DEUS FORTE E PODEROSO, \nPODEROSO NA BATALHA;\nELE É O REI DA GLÓRIA (2X)\n\nINSTRUMENTOS\n\nLEVANTAI-VOS, Ó PORTAIS ETERNOS,\nE ENTRARÁ O REI DA GLÓRIA;\nQUEM É ESSE REI DA GLÓRIA?\nÉ JESUS, O REI DA GLÓRIA.', 'LEVANTAI-VOS, Ó PORTAIS ETERNOS,\nPRA QUE ENTRE O REI DA GLÓRIA;\nQUEM É ESSE REI DA GLÓRIA?\nO SENHOR DOS EXÉRCITOS, \nELE É O REI DA GLÓRIA, \nELE É O REI DA GLÓRIA.\n\nLEVANTAI-VOS, Ó PORTAIS ETERNOS,\nE ENTRARÁ O REI DA GLÓRIA;\nO DEUS FORTE E PODEROSO, \nPODEROSO NA BATALHA;\nELE É O REI DA GLÓRIA <bis tipo=''2''>\n<instrumentos>\n\n\nLEVANTAI-VOS, Ó PORTAIS ETERNOS,\nE ENTRARÁ O REI DA GLÓRIA;\nQUEM É ESSE REI DA GLÓRIA?\nÉ JESUS, O REI DA GLÓRIA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (653, 'ALELUIA (SALMOS 113)', 'ALELUIA (SALMOS 113)', 'CORO\nALELUIA! LOUVAI, SERVOS DO SENHOR!\nLOUVAI O NOME DO SENHOR!\n\nBENDITO SEJA O NOME DO SENHOR\nDESDE AGORA E PARA SEMPRE,\nDO NASCER DO SOL ATÉ O OCASO,\nLOUVADO SEJA O NOME DO SENHOR!\n\nEXCELSO É O NOME DO SENHOR,\nSUA GLÓRIA ESTÁ ACIMA DOS CÉUS,\nQUEM HÁ SEMELHANTE AO SENHOR,\nO NOSSO DEUS?\nNAS ALTURAS ESTÁ SEU TRONO!\n\nCORO\nALELUIA! LOUVAI, SERVOS DO SENHOR!\nLOUVAI O NOME DO SENHOR!\n\nO SENHOR SE INCLINA DESDE O CÉU\nPARA VER O QUE HÁ NA TERRA,\nELE ERGUE DO PÓ O DESVALIDO \nPARA O ASSENTAR COM OS PRÍNCIPES \nDO SEU POVO.\n\nALELUIA! (LOUVAI!) \nLOUVAI, SERVOS DO SENHOR!\nLOUVAI O NOME DO SENHOR!\nALELUIA! (LOUVAI!)', '<coro>\nALELUIA! LOUVAI, SERVOS DO SENHOR!\nLOUVAI O NOME DO SENHOR!\n\nBENDITO SEJA O NOME DO SENHOR\nDESDE AGORA E PARA SEMPRE,\nDO NASCER DO SOL ATÉ O OCASO,\nLOUVADO SEJA O NOME DO SENHOR!\n\nEXCELSO É O NOME DO SENHOR,\nSUA GLÓRIA ESTÁ ACIMA DOS CÉUS,\nQUEM HÁ SEMELHANTE AO SENHOR,\nO NOSSO DEUS?\nNAS ALTURAS ESTÁ SEU TRONO!<coro>\nALELUIA! LOUVAI, SERVOS DO SENHOR!\nLOUVAI O NOME DO SENHOR!\n\nO SENHOR SE INCLINA DESDE O CÉU\nPARA VER O QUE HÁ NA TERRA,\nELE ERGUE DO PÓ O DESVALIDO \nPARA O ASSENTAR COM OS PRÍNCIPES \nDO SEU POVO.\n\nALELUIA! (LOUVAI!) \nLOUVAI, SERVOS DO SENHOR!\nLOUVAI O NOME DO SENHOR!\nALELUIA! (LOUVAI!)', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (654, 'GRANDE É O SENHOR E MUI DIGNO DE SER LOUVADO', 'GRANDE É O SENHOR E MUI DIGNO DE SER LOUVADO', 'GRANDE É O SENHOR E MUI DIGNO DE SER LOUVADO, \nNA CIDADE DO NOSSO DEUS, SEU SANTO MONTE, \nBELO E SOBRANCEIRO, É A ALEGRIA DE TODA A TERRA;\nO MONTE DE SIÃO PARA OS LADOS DO NORTE, \nA CIDADE DO GRANDE REI.', 'GRANDE É O SENHOR E MUI DIGNO DE SER LOUVADO, \nNA CIDADE DO NOSSO DEUS, SEU SANTO MONTE, \nBELO E SOBRANCEIRO, É A ALEGRIA DE TODA A TERRA;\nO MONTE DE SIÃO PARA OS LADOS DO NORTE, <bis>\nA CIDADE DO GRANDE REI. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (655, 'LOUVAI, SERVOS DO SENHOR', 'LOUVAI, SERVOS DO SENHOR', 'LOUVAI, SERVOS DO SENHOR,\nLOUVAI, SERVOS DO SENHOR.\n\nSEJA BENDITO O NOME DO SENHOR,\nSEJA BENDITO O NOME DO SENHOR.\n\nLOUVAI, LOUVAI, LOUVAI AO SENHOR.\n\nSEJA EXALTADO O NOME DO SENHOR,\nSEJA GRANDIOSO O NOME DO SENHOR,\nDE ETERNIDADE PARA SEMPRE, AMÉM,\nA ETERNIDADE, PARA SEMPRE, AMÉM.\n\nLOUVAI, LOUVAI, LOUVAI AO SENHOR.\n(SEJA BENDITO O NOME DO SENHOR)\n\nLOUVAI, LOUVAI, LOUVAI AO SENHOR, \nLOUVAI AO SENHOR', 'LOUVAI, SERVOS DO SENHOR,\nLOUVAI, SERVOS DO SENHOR.\n\nSEJA BENDITO O NOME DO SENHOR,\nSEJA BENDITO O NOME DO SENHOR.\n\nLOUVAI, LOUVAI, LOUVAI AO SENHOR.\n\nSEJA EXALTADO O NOME DO SENHOR,\nSEJA GRANDIOSO O NOME DO SENHOR,\nDE ETERNIDADE PARA SEMPRE, AMÉM,\nA ETERNIDADE, PARA SEMPRE, AMÉM.\n\nLOUVAI, LOUVAI, LOUVAI AO SENHOR.<bis>\n(SEJA BENDITO O NOME DO SENHOR)<bis>\n\nLOUVAI, LOUVAI, LOUVAI AO SENHOR, <bis>\nLOUVAI AO SENHOR<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (656, 'GRANDE É O SENHOR', 'GRANDE É O SENHOR', 'GRANDE É O SENHOR E MUI DIGNO DE LOUVOR, \nNA CIDADE DO NOSSO DEUS, \nSEU SANTO MONTE, ALEGRIA DE TODA A TERRA;\nGRANDE É O SENHOR EM QUEM NÓS TEMOS \nA VITÓRIA, QUE NOS AJUDA CONTRA \nO INIMIGO, POR ISSO DIANTE \nDELE NOS PROSTRAMOS.\n\nQUEREMOS O TEU NOME ENGRANDECER E AGRADECER-TE POR TUA OBRA EM NOSSA VIDA;\nCONFIAMOS EM TEU INFINITO AMOR,\nPOIS SÓ TU ÉS O DEUS ETERNO\nSOBRE TODA A TERRA E CÉU.', 'GRANDE É O SENHOR E MUI DIGNO DE LOUVOR, \nNA CIDADE DO NOSSO DEUS, \nSEU SANTO MONTE, ALEGRIA DE TODA A TERRA;\nGRANDE É O SENHOR EM QUEM NÓS TEMOS \nA VITÓRIA, QUE NOS AJUDA CONTRA \nO INIMIGO, POR ISSO DIANTE \nDELE NOS PROSTRAMOS.\n\nQUEREMOS O TEU NOME ENGRANDECER E AGRADECER-TE POR TUA OBRA EM NOSSA VIDA;<bis>\nCONFIAMOS EM TEU INFINITO AMOR,<bis>\nPOIS SÓ TU ÉS O DEUS ETERNO<bis>\nSOBRE TODA A TERRA E CÉU.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (657, 'OS CÉUS PROCLAMAM', 'OS CÉUS PROCLAMAM', 'OS CÉUS PROCLAMAM A SUA GLÓRIA \nE O FIRMAMENTO AS OBRAS DAS SUAS MÃOS;\nUM DIA PASSA, O OUTRO VEM,\nÉ ELE QUEM DÁ VITÓRIAS AO SEU POVO;\nDO ALTO VEIO A SUA MÃO\nTOCOU-ME E DEU-ME \nALEGRIA DE VIVER.\n\nCORO (2X)\nGLÓRIA AO MEU JESUS,\nPOIS DELE SOU E ELE É MEU.\n\nSE FAZ OUVIR A SUA VOZ POR TODA A TERRA \nE AOS CONFINS DO MUNDO;\nSINTO A PRESENÇA DE DEUS TÃO CALMA\nPOIS QUEM É DEUS SENÃO O NOSSO DEUS?\nCOMIGO ESTÁ, NÃO VOU DEIXAR \nQUE QUALQUER COISA\nQUEBRE ESSA COMUNHÃO.\n\nCORO (2X)\nGLÓRIA AO MEU JESUS,\nPOIS DELE SOU E ELE É MEU.', 'OS CÉUS PROCLAMAM A SUA GLÓRIA \nE O FIRMAMENTO AS OBRAS DAS SUAS MÃOS;\nUM DIA PASSA, O OUTRO VEM,\nÉ ELE QUEM DÁ VITÓRIAS AO SEU POVO;\nDO ALTO VEIO A SUA MÃO<bis>\nTOCOU-ME E DEU-ME <bis>\nALEGRIA DE VIVER.<bis>\n\n<coro tipo=''2X''>\nGLÓRIA AO MEU JESUS,\nPOIS DELE SOU E ELE É MEU.\n\nSE FAZ OUVIR A SUA VOZ POR TODA A TERRA \nE AOS CONFINS DO MUNDO;\nSINTO A PRESENÇA DE DEUS TÃO CALMA\nPOIS QUEM É DEUS SENÃO O NOSSO DEUS?\nCOMIGO ESTÁ, NÃO VOU DEIXAR <bis>\nQUE QUALQUER COISA<bis>\nQUEBRE ESSA COMUNHÃO.<bis>\n\n<coro tipo=''2X''>\nGLÓRIA AO MEU JESUS,\nPOIS DELE SOU E ELE É MEU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (658, 'MEDITAREI NAS MARAVILHAS DO SENHOR', 'MEDITAREI NAS MARAVILHAS DO SENHOR', 'MEDITAREI NAS MARAVILHAS DO SENHOR \nE FALAREI DO SEU PODER ENTRE AS NAÇÕES;\nCELEBRAREI A MAJESTADE DO SENHOR, PROCLAMAREI SUA JUSTIÇA SOBRE A TERRA.\n\nPORQUE GRANDES SÃO AS TUAS OBRAS, \nTU ÉS FIEL ETERNAMENTE.\n\nEXALTAR-TE-EI, Ó DEUS,\nPOIS TU ÉS MEU REI,\nGLORIFICAREI TEU NOME\nENQUANTO EU VIVER.\n\nPERTO ESTÁ O SENHOR\nDOS QUE O INVOCAM.4X', 'MEDITAREI NAS MARAVILHAS DO SENHOR \nE FALAREI DO SEU PODER ENTRE AS NAÇÕES;\nCELEBRAREI A MAJESTADE DO SENHOR, PROCLAMAREI SUA JUSTIÇA SOBRE A TERRA.\n\nPORQUE GRANDES SÃO AS TUAS OBRAS, \nTU ÉS FIEL ETERNAMENTE.\n\nEXALTAR-TE-EI, Ó DEUS,<bis>\nPOIS TU ÉS MEU REI,<bis>\nGLORIFICAREI TEU NOME<bis>\nENQUANTO EU VIVER.<bis>\n\nPERTO ESTÁ O SENHOR\nDOS QUE O INVOCAM.<bis tipo=''4''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (659, 'CELEBRAI COM JÚBILO AO SENHOR', 'CELEBRAI COM JÚBILO AO SENHOR', 'CELEBRAI COM JÚBILO AO SENHOR\nTODAS AS TERRAS,\nSERVI AO SENHOR COM ALEGRIA;\nAPRESENTAI-VOS DIANTE\nDELE COM CÂNTICOS,\nSABEI QUE O SENHOR É DEUS.\n\nFOI ELE QUEM NOS FEZ E DELE SOMOS, \nSOMOS O SEU POVO\nE REBANHO DO SEU PASTO.\n\nENTRAI EM SUAS PORTAS COM AÇÕES DE GRAÇAS E NOS SEUS ÁTRIOS COM HINOS DE LOUVOR;\nRENDEI-LHE GRAÇAS E BENDIZEI-LHE \nO NOME PORQUE O SENHOR É BOM.\n\nSUA MISERICÓRDIA DURA PARA SEMPRE,\nDE GERAÇÃO EM GERAÇÃO,SUA FIDELIDADE.\nSUA MISERICÓRDIA DURA PARA SEMPRE,\nDE GERAÇÃO EM GERAÇÃO, SUA FIDELIDADE.', 'CELEBRAI COM JÚBILO AO SENHOR\nTODAS AS TERRAS,\nSERVI AO SENHOR COM ALEGRIA;\nAPRESENTAI-VOS DIANTE\nDELE COM CÂNTICOS,\nSABEI QUE O SENHOR É DEUS.\n\nFOI ELE QUEM NOS FEZ E DELE SOMOS, <bis>\nSOMOS O SEU POVO<bis>\nE REBANHO DO SEU PASTO.<bis>\n\nENTRAI EM SUAS PORTAS COM AÇÕES DE GRAÇAS E NOS SEUS ÁTRIOS COM HINOS DE LOUVOR;\nRENDEI-LHE GRAÇAS E BENDIZEI-LHE \nO NOME PORQUE O SENHOR É BOM.\n\nSUA MISERICÓRDIA DURA PARA SEMPRE,\nDE GERAÇÃO EM GERAÇÃO,SUA FIDELIDADE.\nSUA MISERICÓRDIA DURA PARA SEMPRE,\nDE GERAÇÃO EM GERAÇÃO, SUA FIDELIDADE.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (660, 'O MEU CORAÇÃO', 'O MEU CORAÇÃO', 'O MEU CORAÇÃO FERVE COM PALAVRAS BOAS, \nFALO DO QUE TENHO FEITO NO TOCANTE AO REI;\nA MINHA LÍNGUA É A PENA DE UM DESTRO ESCRITOR, \nTU ÉS MAIS FORMOSO QUE OS FILHOS DOS HOMENS;\n\nA GRAÇA SE DERRAMOU EM TEUS LÁBIOS,\nPOR ISSO DEUS TE ABENÇOOU PARA SEMPRE;\nÀ COXA CINGE A TUA ESPADA, Ó VALENTE,\nCOM A TUA GLÓRIA E TUA MAJESTADE.\n\nINSTRUMENTOS\n\nE NESTE ESPLENDOR TEU CAVALGA PROSPERAMENTE, PELA VERDADE E JUSTIÇA E A MANSIDÃO;\nAS TUAS FLECHAS SÃO AGUDAS NO CORAÇÃO \nDOS INIMIGOS DO REI,\n\n\nE POR ELAS OS POVOS SE QUEDAM DIANTE DE TI; \nO TEU TRONO, Ó DEUS, É ETERNO E PERPÉTUO, \nO CETRO DO TEU REINO É DE EQUIDADE, \nTU AMAS JUSTIÇA E ODEIAS MALDADE, \nPOR ISSO O TEU DEUS TE UNGIU COM ALEGRIA.', 'O MEU CORAÇÃO FERVE COM PALAVRAS BOAS, \nFALO DO QUE TENHO FEITO NO TOCANTE AO REI;\nA MINHA LÍNGUA É A PENA DE UM DESTRO ESCRITOR, \nTU ÉS MAIS FORMOSO QUE OS FILHOS DOS HOMENS;\n\nA GRAÇA SE DERRAMOU EM TEUS LÁBIOS,\nPOR ISSO DEUS TE ABENÇOOU PARA SEMPRE;\nÀ COXA CINGE A TUA ESPADA, Ó VALENTE,\nCOM A TUA GLÓRIA E TUA MAJESTADE.\n<instrumentos>\n\n\nE NESTE ESPLENDOR TEU CAVALGA PROSPERAMENTE, PELA VERDADE E JUSTIÇA E A MANSIDÃO;\nAS TUAS FLECHAS SÃO AGUDAS NO CORAÇÃO \nDOS INIMIGOS DO REI,\n\n\nE POR ELAS OS POVOS SE QUEDAM DIANTE DE TI; \nO TEU TRONO, Ó DEUS, É ETERNO E PERPÉTUO, \nO CETRO DO TEU REINO É DE EQUIDADE, \nTU AMAS JUSTIÇA E ODEIAS MALDADE, \nPOR ISSO O TEU DEUS TE UNGIU COM ALEGRIA.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (661, 'ÉS O MAIS FORMOSO, JESUS', 'ÉS O MAIS FORMOSO, JESUS', 'ÉS O MAIS FORMOSO, JESUS,\nGRAÇA HÁ EM TEU FALAR,\nCONSAGRO-TE O QUE COMPUS,\nNESTE CANTO TE ADORAR;\nCINGE A TUA ESPADA, HERÓI,\nDE GLÓRIA E MAJESTADE,\nCOM PODER HÁS DE ENSINAR\nJUSTIÇA E VERDADE.\n\nTEUS PERFUMES SE EXALAM:\nCÁSSIA, MIRRA E ALOÉS;\nDE AMOR TEUS OLHOS BRILHAM,\nME CONDUZEM PELA FÉ.\nO TEU TRONO, Ó REI, É PODER\nPOR TODA A ETERNIDADE,\nAMAS A JUSTIÇA, PORÉM,\nODEIAS A IMPIEDADE.\n\n''OUVE, FILHA, VÊ, DÁ ATENÇÃO,\nFALA O TEU SALVADOR,\nPROSTRA-TE ANTE MIM, ENTÃO,\nADORA O DEUS DE AMOR;\nNOIVA MINHA, ALMEJAS O CÉU,\nVESTES DE OURO TE DAREI,\nTÃO FORMOSA E FIEL,\nÀ MINHA GLÓRIA A LEVAREI''.\n\n''TEUS VESTIDOS SÃO BORDADOS\nDE OURO PURO DE OFIR,\nTEU NOME FAREI LEMBRADO,\nEU TE QUERO JUNTO A MIM;\nCOM ALEGRIA E TODA GLÓRIA,\nFIÉIS TE SEGUIRÃO\nE COM CANTO DE VITÓRIA,\nPRA SEMPRE TE LOUVARÃO''.', 'ÉS O MAIS FORMOSO, JESUS,\nGRAÇA HÁ EM TEU FALAR,\nCONSAGRO-TE O QUE COMPUS,\nNESTE CANTO TE ADORAR;\nCINGE A TUA ESPADA, HERÓI,\nDE GLÓRIA E MAJESTADE,\nCOM PODER HÁS DE ENSINAR\nJUSTIÇA E VERDADE.\n\nTEUS PERFUMES SE EXALAM:\nCÁSSIA, MIRRA E ALOÉS;\nDE AMOR TEUS OLHOS BRILHAM,\nME CONDUZEM PELA FÉ.\nO TEU TRONO, Ó REI, É PODER\nPOR TODA A ETERNIDADE,\nAMAS A JUSTIÇA, PORÉM,\nODEIAS A IMPIEDADE.\n\n''OUVE, FILHA, VÊ, DÁ ATENÇÃO,\nFALA O TEU SALVADOR,\nPROSTRA-TE ANTE MIM, ENTÃO,\nADORA O DEUS DE AMOR;\nNOIVA MINHA, ALMEJAS O CÉU,\nVESTES DE OURO TE DAREI,\nTÃO FORMOSA E FIEL,\nÀ MINHA GLÓRIA A LEVAREI''.\n\n''TEUS VESTIDOS SÃO BORDADOS\nDE OURO PURO DE OFIR,\nTEU NOME FAREI LEMBRADO,\nEU TE QUERO JUNTO A MIM;\nCOM ALEGRIA E TODA GLÓRIA,\nFIÉIS TE SEGUIRÃO\nE COM CANTO DE VITÓRIA,\nPRA SEMPRE TE LOUVARÃO''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (662, 'ONIPOTENTE DEUS', 'ONIPOTENTE DEUS', 'ONIPOTENTE DEUS,\nTUAS OBRAS TE EXALTAM, SENHOR;\nONIPOTENTE DEUS,\nCÉUS E TERRA TE RENDEM LOUVOR.\nQUE É O HOMEM QUE DELE TE LEMBRES\nE O FILHO DO HOMEM PARA O VISITAR?\nPORÉM, HONRA DESTE PRA GOVERNAR.\n\nINSTRUMENTOS\n\nSENHOR JESUS CRISTO,\nMINHA VIDA VIESTE SALVAR;\nSENHOR JESUS CRISTO,\nCOM TEU SANGUE ME PURIFICAR.\nCOMO SERVO VIESTE,\nNA CRUZ TE HUMILHASTE,\nMAS VIVO NA GLÓRIA HOJE ESTÁS,\nÉS MEU REI, SENHOR E, SEI, VOLTARÁS.\n\nINSTRUMENTOS\n\nESPÍRITO SANTO, Ó VEM E HABITA EM MEU SER,\nESPÍRITO SANTO, VIVIFICA-ME COM TEU PODER;\nTAL COMO ÁGUA QUE JORRA,\nE O VENTO QUE SOPRA,\nE O FOGO ARDENTE, ENFIM,\nSANTO ESPÍRITO DE \nDEUS VIVE EM MIM.', 'ONIPOTENTE DEUS,\nTUAS OBRAS TE EXALTAM, SENHOR;\nONIPOTENTE DEUS,\nCÉUS E TERRA TE RENDEM LOUVOR.\nQUE É O HOMEM QUE DELE TE LEMBRES\nE O FILHO DO HOMEM PARA O VISITAR?\nPORÉM, HONRA DESTE PRA GOVERNAR.\n<instrumentos>\n\n\nSENHOR JESUS CRISTO,\nMINHA VIDA VIESTE SALVAR;\nSENHOR JESUS CRISTO,\nCOM TEU SANGUE ME PURIFICAR.\nCOMO SERVO VIESTE,\nNA CRUZ TE HUMILHASTE,\nMAS VIVO NA GLÓRIA HOJE ESTÁS,\nÉS MEU REI, SENHOR E, SEI, VOLTARÁS.\n<instrumentos>\n\n\nESPÍRITO SANTO, Ó VEM E HABITA EM MEU SER,\nESPÍRITO SANTO, VIVIFICA-ME COM TEU PODER;\nTAL COMO ÁGUA QUE JORRA,\nE O VENTO QUE SOPRA,\nE O FOGO ARDENTE, ENFIM,\nSANTO ESPÍRITO DE <bis>\nDEUS VIVE EM MIM.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (663, 'LOUVAI AO SENHOR TODAS AS NAÇÕES', 'LOUVAI AO SENHOR TODAS AS NAÇÕES', 'LOUVAI AO SENHOR TODAS AS NAÇÕES LOUVAI-O \nTODOS OS POVOS.\nLOUVAI AO SENHOR TODAS AS NAÇÕES LOUVAI-O \nTODOS OS POVOS.\nLOUVAI AO SENHOR, LOUVAI AO SENHOR.\n\nPORQUE A SUA BENIGNIDADE\nÉ GRANDE PARA CONOSCO,\nE A VERDADE DO SENHOR\nDURA PARA SEMPRE.\nLOUVAI AO SENHOR, \nLOUVAI AO SENHOR.', 'LOUVAI AO SENHOR TODAS AS NAÇÕES LOUVAI-O \nTODOS OS POVOS.\nLOUVAI AO SENHOR TODAS AS NAÇÕES LOUVAI-O \nTODOS OS POVOS.\nLOUVAI AO SENHOR, LOUVAI AO SENHOR.\n\nPORQUE A SUA BENIGNIDADE\nÉ GRANDE PARA CONOSCO,\nE A VERDADE DO SENHOR\nDURA PARA SEMPRE.\nLOUVAI AO SENHOR, \nLOUVAI AO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (664, 'QUÃO AMÁVEIS SÃO', 'QUÃO AMÁVEIS SÃO', 'QUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS, \nSENHOR DOS EXÉRCITOS!\nA MINH''ALMA ESTÁ ANELANTE E DESFALECE \nPELOS ÁTRIOS DO SENHOR.\n\nCORO\nO MEU CORAÇÃO E A MINHA CARNE\nCLAMAM PELO DEUS VIVO!\nQUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS \nSENHOR DOS EXÉRCITOS\n\nATÉ O PARDAL ENCONTROU CASA E A ANDORINHA ENCONTROU NINHO PARA SI JUNTO AO TEU ALTAR, \nSENHOR DOS EXÉRCITOS, REI MEU E DEUS MEU.\n\nCORO\nO MEU CORAÇÃO E A MINHA CARNE\nCLAMAM PELO DEUS VIVO!\nQUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS \nSENHOR DOS EXÉRCITOS', 'QUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS, \nSENHOR DOS EXÉRCITOS!\nA MINH''ALMA ESTÁ ANELANTE E DESFALECE \nPELOS ÁTRIOS DO SENHOR.\n\n<coro>\nO MEU CORAÇÃO E A MINHA CARNE\nCLAMAM PELO DEUS VIVO!\nQUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS \nSENHOR DOS EXÉRCITOS\n\nATÉ O PARDAL ENCONTROU CASA E A ANDORINHA ENCONTROU NINHO PARA SI JUNTO AO TEU ALTAR, \nSENHOR DOS EXÉRCITOS, REI MEU E DEUS MEU.\n\n<coro>\nO MEU CORAÇÃO E A MINHA CARNE\nCLAMAM PELO DEUS VIVO!\nQUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS \nSENHOR DOS EXÉRCITOS', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (665, 'BENDIZEI AO SENHOR', 'BENDIZEI AO SENHOR', 'BENDIZEI AO SENHOR\nVÓS TODOS, SERVOS DO SENHOR,\nQUE ASSISTIS NA CASA DO SENHOR\nNAS HORAS DA NOITE.\n\nERGUEI AS MÃOS NO SANTUÁRIO\nE BENDIZEI AO SENHOR;\nDE SIÃO TE ABENÇOE O SENHOR,\nCRIADOR DO CÉU E DA TERRA.', 'BENDIZEI AO SENHOR<bis>\nVÓS TODOS, SERVOS DO SENHOR,<bis>\nQUE ASSISTIS NA CASA DO SENHOR<bis>\nNAS HORAS DA NOITE.<bis>\n<bis>\nERGUEI AS MÃOS NO SANTUÁRIO<bis>\nE BENDIZEI AO SENHOR;<bis>\nDE SIÃO TE ABENÇOE O SENHOR,<bis>\nCRIADOR DO CÉU E DA TERRA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (666, 'TAL QUAL ESTOU', 'TAL QUAL ESTOU', 'TAL QUAL ESTOU, EIS-ME, SENHOR,\nPOIS O TEU SANGUE REMIDOR\nVERTESTE PELO PECADOR;\nÓ SALVADOR, ME ACHEGO A TI!\n\n\n\nTAL QUAL ESTOU, SEM ESPERAR\nQUE POSSA A VIDA MELHORAR,\nEM TI SÓ QUERO CONFIAR;\nÓ SALVADOR, ME ACHEGO A TI!\n\nTAL QUAL ESTOU E SEM PODER,\nAS FALTAS PODES PREENCHER\nE TUDO QUANTO ME É MISTER;\nÓ SALVADOR, ME ACHEGO A TI!\n\n\n\nTAL QUAL ESTOU ME ACEITARÁS\nE TU, MINH''ALMA LIMPARÁS,\nCOM TEU AMOR ME COBRIRÁS;\nÓ SALVADOR, ME ACHEGO A TI!', 'TAL QUAL ESTOU, EIS-ME, SENHOR,\nPOIS O TEU SANGUE REMIDOR\nVERTESTE PELO PECADOR;\nÓ SALVADOR, ME ACHEGO A TI!\n\n\n\nTAL QUAL ESTOU, SEM ESPERAR\nQUE POSSA A VIDA MELHORAR,\nEM TI SÓ QUERO CONFIAR;\nÓ SALVADOR, ME ACHEGO A TI!\n\nTAL QUAL ESTOU E SEM PODER,\nAS FALTAS PODES PREENCHER\nE TUDO QUANTO ME É MISTER;\nÓ SALVADOR, ME ACHEGO A TI!\n\n\n\nTAL QUAL ESTOU ME ACEITARÁS\nE TU, MINH''ALMA LIMPARÁS,\nCOM TEU AMOR ME COBRIRÁS;\nÓ SALVADOR, ME ACHEGO A TI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (667, 'JUSTO ÉS, SENHOR', 'JUSTO ÉS, SENHOR', 'JUSTO ÉS, SENHOR,\nNOS TEUS SANTOS CAMINHOS,\nÉS DIGNO EM TODAS AS TUAS OBRAS.\nJUSTO ÉS, SENHOR,\nNOS TEUS SANTOS CAMINHOS,\nÉS DIGNO EM TODAS AS TUAS OBRAS.\n\nBEM PERTO ESTÁS, SENHOR\nBEM PERTO ESTÁS\nDOS QUE TE INVOCAM,\nDE TODOS QUE TE INVOCAM EM VERDADE.\n\nFINAL: ALELUIA! ALELUIA!', 'JUSTO ÉS, SENHOR,\nNOS TEUS SANTOS CAMINHOS,\nÉS DIGNO EM TODAS AS TUAS OBRAS.\nJUSTO ÉS, SENHOR,\nNOS TEUS SANTOS CAMINHOS,\nÉS DIGNO EM TODAS AS TUAS OBRAS.\n\nBEM PERTO ESTÁS, SENHOR<bis>\nBEM PERTO ESTÁS<bis>\nDOS QUE TE INVOCAM,<bis>\nDE TODOS QUE TE INVOCAM EM VERDADE.<bis>\n<final>ALELUIA! ALELUIA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (668, 'UM POBRE CEGO', 'UM POBRE CEGO', 'UM POBRE CEGO À BEIRA DE UMA ESTRADA \nENVOLTO EM TRAPOS, TREVAS E DESDÉM;\nPEDIA ESMOLAS DE ALMA ANGUSTIADA,\nVEIO JESUS E TROUXE A LUZ E O BEM.\n\nCORO\nAO VIR JESUS A TEMPESTADE CESSA,\nAO VIR JESUS AS LÁGRIMAS SE VÃO;\nELE TRANSFORMA TODA NOSSA VIDA\nILUMINANDO A NEGRA ESCURIDÃO.\n\nHOJE, TAMBÉM, O PECADOR DEPARA,\nEM CRISTO, LIVRAMENTO DE AFLIÇÃO,\nEM MEIO À TENTAÇÃO QUE O DESTROÇARA,\nVEIO JESUS E TROUXE A SALVAÇÃO.\n\nCORO\nAO VIR JESUS A TEMPESTADE CESSA,\nAO VIR JESUS AS LÁGRIMAS SE VÃO;\nELE TRANSFORMA TODA NOSSA VIDA\nILUMINANDO A NEGRA ESCURIDÃO.', 'UM POBRE CEGO À BEIRA DE UMA ESTRADA \nENVOLTO EM TRAPOS, TREVAS E DESDÉM;\nPEDIA ESMOLAS DE ALMA ANGUSTIADA,\nVEIO JESUS E TROUXE A LUZ E O BEM.\n\n<coro>\nAO VIR JESUS A TEMPESTADE CESSA,\nAO VIR JESUS AS LÁGRIMAS SE VÃO;\nELE TRANSFORMA TODA NOSSA VIDA\nILUMINANDO A NEGRA ESCURIDÃO.\n\nHOJE, TAMBÉM, O PECADOR DEPARA,\nEM CRISTO, LIVRAMENTO DE AFLIÇÃO,\nEM MEIO À TENTAÇÃO QUE O DESTROÇARA,\nVEIO JESUS E TROUXE A SALVAÇÃO.\n\n<coro>\nAO VIR JESUS A TEMPESTADE CESSA,\nAO VIR JESUS AS LÁGRIMAS SE VÃO;\nELE TRANSFORMA TODA NOSSA VIDA\nILUMINANDO A NEGRA ESCURIDÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (669, 'DEUS DOS ANTIGOS', 'DEUS DOS ANTIGOS', 'DEUS DOS ANTIGOS, CUJA FORTE MÃO\nREGE E SUSTÉM OS ASTROS DA AMPLIDÃO;\nDO CINTILANTE CÉU INSPIRADOR,\nCOM GRATIDÃO CANTAMOS TEU LOUVOR.\n\nJÁ NO PASSADO FOSTE NOSSA LUZ,\nHOJE ÉS FAROL QUE À VIDA NOS CONDUZ;\nSÊ NOSSO ESTEIO, GUIA E PROTEÇÃO,\nTUA PALAVRA É LEI E DIREÇÃO.\n\nTEU POVO, Ó DEUS, RESTAURA EM SEU LABOR, \nTRANSFORMA A NOITE EM DIA DE ESPLENDOR;\nAS NOSSAS VIDAS VEM FORTALECER\nPARA TEU NOME SEMPRE ENGRANDECER. \nAMÉM.', 'DEUS DOS ANTIGOS, CUJA FORTE MÃO\nREGE E SUSTÉM OS ASTROS DA AMPLIDÃO;\nDO CINTILANTE CÉU INSPIRADOR,\nCOM GRATIDÃO CANTAMOS TEU LOUVOR.\n\nJÁ NO PASSADO FOSTE NOSSA LUZ,\nHOJE ÉS FAROL QUE À VIDA NOS CONDUZ;\nSÊ NOSSO ESTEIO, GUIA E PROTEÇÃO,\nTUA PALAVRA É LEI E DIREÇÃO.\n\nTEU POVO, Ó DEUS, RESTAURA EM SEU LABOR, \nTRANSFORMA A NOITE EM DIA DE ESPLENDOR;\nAS NOSSAS VIDAS VEM FORTALECER\nPARA TEU NOME SEMPRE ENGRANDECER. \nAMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (670, 'SE PAZ, A MAIS DOCE', 'SE PAZ, A MAIS DOCE', 'SE PAZ, A MAIS DOCE ME DERES GOZAR,\nSE DOR A MAIS FORTE SOFRER,\nOH! SEJA O QUE FOR, TU ME FAZES SABER\nQUE FELIZ COM JESUS SEMPRE SOU!\n\nCORO\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!\n\nEMBORA ME ASSALTE O CRUEL TENTADOR\nE ATAQUE COM VIS TENTAÇÕES;\nOH! CERTO ESTOU, APESAR DE AFLIÇÕES,\nQUE FELIZ EU SEREI COM JESUS!\n\nCORO\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!\n\nMEU TRISTE PECADO, POR MEU SALVADOR, \nFOI PAGO DE UM MODO CABAL;\nVALEU-ME O SENHOR, OH! MERCÊ SEM IGUAL! \nSOU FELIZ! GRAÇAS DOU A JESUS!\n\nCORO\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!\n\nA VINDA EU ANSEIO DO MEU SALVADOR;\nEM BREVE VIRÁ ME LEVAR\nAO CÉU, ONDE VOU PARA SEMPRE MORAR\nCOM REMIDOS NA LUZ DO SENHOR!\n\nCORO\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!', 'SE PAZ, A MAIS DOCE ME DERES GOZAR,\nSE DOR A MAIS FORTE SOFRER,\nOH! SEJA O QUE FOR, TU ME FAZES SABER\nQUE FELIZ COM JESUS SEMPRE SOU!\n\n<coro>\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!\n\nEMBORA ME ASSALTE O CRUEL TENTADOR\nE ATAQUE COM VIS TENTAÇÕES;\nOH! CERTO ESTOU, APESAR DE AFLIÇÕES,\nQUE FELIZ EU SEREI COM JESUS!\n\n<coro>\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!\n\nMEU TRISTE PECADO, POR MEU SALVADOR, \nFOI PAGO DE UM MODO CABAL;\nVALEU-ME O SENHOR, OH! MERCÊ SEM IGUAL! \nSOU FELIZ! GRAÇAS DOU A JESUS!\n\n<coro>\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!\n\nA VINDA EU ANSEIO DO MEU SALVADOR;\nEM BREVE VIRÁ ME LEVAR\nAO CÉU, ONDE VOU PARA SEMPRE MORAR\nCOM REMIDOS NA LUZ DO SENHOR!\n\n<coro>\nSOU FELIZ, (SOU FELIZ)\nCOM JESUS, (COM JESUS) \nSOU FELIZ, COM JESUS, MEU SENHOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (671, 'OUVE, POIS ISRAEL', 'OUVE, POIS ISRAEL', 'OUVE, POIS, ISRAEL!\nO SENHOR É O TEU DEUS, \nELE É O ÚNICO SENHOR,\n''AMARÁS O SENHOR TEU DEUS\nDE TODA A TUA ALMA,''\nESTAS PALAVRAS TE ORDENO.\n\nATA-AS EM TEU CORAÇÃO,\nAOS TEUS FILHOS FALARÁS\nE SERÁ POR SINAL NAS TUAS MÃOS\nE NOS UMBRAIS DE TUA CASA.\nE ASSIM VOSSAS CASAS \nESTARÃO CHEIAS DE TODO BEM,\nDOS POÇOS TIRAREIS ÁGUAS DE SALVAÇÃO.\n\nCOMEREIS E VOS FARTAREIS DAS VINHAS, \nCOMEREIS E VOS FARTAREIS\nINSTRUMENTOS\n\n\nGUARDA AS MINHAS PALAVRAS \nNÃO ESQUEÇAS DO SENHOR \nTEU DEUS QUE TE TIROU DA SERVIDÃO \nE HOJE LIVRE ESTÁS,\nAO TEU DEUS TEMERÁS \nE SÓ A ELE SERVIRÁS.\nPOIS EM BREVE VIRÁ. (4X)', 'OUVE, POIS, ISRAEL!\nO SENHOR É O TEU DEUS, \nELE É O ÚNICO SENHOR,\n''AMARÁS O SENHOR TEU DEUS\nDE TODA A TUA ALMA,''\nESTAS PALAVRAS TE ORDENO.\n\nATA-AS EM TEU CORAÇÃO,\nAOS TEUS FILHOS FALARÁS\nE SERÁ POR SINAL NAS TUAS MÃOS\nE NOS UMBRAIS DE TUA CASA.\nE ASSIM VOSSAS CASAS \nESTARÃO CHEIAS DE TODO BEM,\nDOS POÇOS TIRAREIS ÁGUAS DE SALVAÇÃO.\n\nCOMEREIS E VOS FARTAREIS DAS VINHAS, <bis>\nCOMEREIS E VOS FARTAREIS<bis>\n<instrumentos><bis>\nGUARDA AS MINHAS PALAVRAS \nNÃO ESQUEÇAS DO SENHOR \nTEU DEUS QUE TE TIROU DA SERVIDÃO \nE HOJE LIVRE ESTÁS,\nAO TEU DEUS TEMERÁS \nE SÓ A ELE SERVIRÁS.\nPOIS EM BREVE VIRÁ. <bis tipo=''4''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (672, 'MEU SERVO, NÃO TEMAS', 'MEU SERVO, NÃO TEMAS', 'MEU SERVO, NÃO TEMAS,\nNÃO TEMAS POIS TE ESCOLHI\nPRA FAZER A MINHA OBRA,\nSERVO, TU ÉS MEU.\n\nQUANDO EU TE ENVIAR, TU FALARÁS,\nQUANDO EU MANDAR, TU CALARÁS,\nE ASSIM FARÁS MINHA OBRA \nE TE ALEGRARÁS.\n\nQUANDO A OBRA FIZERES \nE TUDO SE COMPLETAR,\nTE TRAREI À MINHA PRESENÇA\nE TE ALEGRARÁS. \n\n3X', 'MEU SERVO, NÃO TEMAS,<bis>\nNÃO TEMAS POIS TE ESCOLHI<bis>\nPRA FAZER A MINHA OBRA,<bis>\nSERVO, TU ÉS MEU.<bis>\n\nQUANDO EU TE ENVIAR, TU FALARÁS,\nQUANDO EU MANDAR, TU CALARÁS,\nE ASSIM FARÁS MINHA OBRA \nE TE ALEGRARÁS.\n\nQUANDO A OBRA FIZERES \nE TUDO SE COMPLETAR,\nTE TRAREI À MINHA PRESENÇA\nE TE ALEGRARÁS. \n\n<bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (673, 'Ó PAI, EU QUERIA TANTO VER (AUTOR DA MINHA FÉ)', 'Ó PAI, EU QUERIA TANTO VER (AUTOR DA MINHA FÉ)', 'Ó PAI, EU QUERIA TANTO VER O MEU SENHOR \nDESCER VINDO ME ENCONTRAR,\nEU POSSO ATÉ IMAGINAR A REFULGENTE \nGLÓRIA DO SENHOR JESUS,\nTRANSPONDO AS BRANCAS NUVENS\nNO MAIS PURO AZUL ONDE NEM SUL, \nNEM NORTE EXISTIRÁ.\n\nE EM MEIO A LÁGRIMAS,\nSORRISOS DE ALEGRIA E DE PRAZER,\nEU QUE ERA CEGO AGORA POSSO VER,\nCONTEMPLAR, CONTEMPLAR, ENFIM,\nPOR ISSO EU CANTO GLÓRIA.\nCORO (2X)\nGLÓRIA, GLÓRIA\nAO AUTOR DA MINHA FÉ. \n\nÓ PAI, EU QUERIA TANTO OUVIR\nO SOM QUE VAI ABRIR O ENCONTRO TRIUNFAL,\nREVER AMIGOS QUE UM DIA EM CRISTO \nFORAM FEITOS MEUS IRMÃOS,\nE AGORA, SIM, PODEMOS DAR AS MÃOS\nPOIS TEMOS TODOS UM, SOMENTE UM,\nUM SÓ SENHOR;\n\nE EIS O CONSOLO QUE ENVOLVE A MINHA VIDA, \nO MEU SENHOR JESUS QUE FOI MORTO, SIM, \nNAQUELA CRUZ, VOLTARÁ, VOLTARÁ, ENFIM,\nPOR ISSO EU CANTO GLÓRIA.\nCORO (2X)\nGLÓRIA, GLÓRIA\nAO AUTOR DA MINHA FÉ. \n\nFINAL:\n(ALELUIA) GLÓRIA AO SENHOR, (3X)\n(ALELUIA) O AUTOR DA MINHA FÉ;\n(ALELUIA) GLÓRIA AO SENHOR, (2X)\n(ALELUIA) O AUTOR DA MINHA FÉ.', 'Ó PAI, EU QUERIA TANTO VER O MEU SENHOR \nDESCER VINDO ME ENCONTRAR,\nEU POSSO ATÉ IMAGINAR A REFULGENTE \nGLÓRIA DO SENHOR JESUS,\nTRANSPONDO AS BRANCAS NUVENS\nNO MAIS PURO AZUL ONDE NEM SUL, \nNEM NORTE EXISTIRÁ.\n\nE EM MEIO A LÁGRIMAS,\nSORRISOS DE ALEGRIA E DE PRAZER,\nEU QUE ERA CEGO AGORA POSSO VER,\nCONTEMPLAR, CONTEMPLAR, ENFIM,\nPOR ISSO EU CANTO GLÓRIA.<coro tipo=''2X''>\nGLÓRIA, GLÓRIA\nAO AUTOR DA MINHA FÉ. \n\nÓ PAI, EU QUERIA TANTO OUVIR\nO SOM QUE VAI ABRIR O ENCONTRO TRIUNFAL,\nREVER AMIGOS QUE UM DIA EM CRISTO \nFORAM FEITOS MEUS IRMÃOS,\nE AGORA, SIM, PODEMOS DAR AS MÃOS\nPOIS TEMOS TODOS UM, SOMENTE UM,\nUM SÓ SENHOR;\n\nE EIS O CONSOLO QUE ENVOLVE A MINHA VIDA, \nO MEU SENHOR JESUS QUE FOI MORTO, SIM, \nNAQUELA CRUZ, VOLTARÁ, VOLTARÁ, ENFIM,\nPOR ISSO EU CANTO GLÓRIA.<coro tipo=''2X''>\nGLÓRIA, GLÓRIA\nAO AUTOR DA MINHA FÉ. \n\n\n<final>(ALELUIA) GLÓRIA AO SENHOR, <bis tipo=''3''>\n(ALELUIA) O AUTOR DA MINHA FÉ;\n(ALELUIA) GLÓRIA AO SENHOR, <bis tipo=''2''><bis>\n(ALELUIA) O AUTOR DA MINHA FÉ. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (674, 'EU NÃO SEI QUAL SERÁ O LOUVOR', 'EU NÃO SEI QUAL SERÁ O LOUVOR', 'EU NÃO SEI QUAL SERÁ MEU LOUVOR\nAO OUVIR A VOZ DO SENHOR:\n''VINDE, BENDITOS DE MEU PAI,\nPOSSUÍ O REINO DE AMOR E PAZ;\nREDIMIDOS DO SENHOR!''\n\nO QUE DEUS TEM PREPARADO PARA NÓS,\nUM LINDO CÉU DE AMOR E PAZ!\nVIVEREMOS PARA SEMPRE COM O SENHOR!\nOLHO HUMANO NUNCA VIU, SOM ALGUM \nJAMAIS SE OUVIU DAS MORADAS DO SENHOR.\n\nINSTRUMENTOS\n\nO QUE DEUS TEM PREPARADO PARA NÓS,\nUM LINDO CÉU DE AMOR E PAZ!\nVIVEREMOS PARA SEMPRE COM O SENHOR!\nOLHO HUMANO NUNCA VIU, SOM ALGUM \nJAMAIS SE OUVIU DAS MORADAS DO SENHOR.\n\nFINAL: \n''VINDE, BENDITOS DE MEU PAI,\nPOSSUÍ O REINO DE AMOR E PAZ''.', 'EU NÃO SEI QUAL SERÁ MEU LOUVOR\nAO OUVIR A VOZ DO SENHOR:\n''VINDE, BENDITOS DE MEU PAI,\nPOSSUÍ O REINO DE AMOR E PAZ;\nREDIMIDOS DO SENHOR!''\n\nO QUE DEUS TEM PREPARADO PARA NÓS,\nUM LINDO CÉU DE AMOR E PAZ!\nVIVEREMOS PARA SEMPRE COM O SENHOR!\nOLHO HUMANO NUNCA VIU, SOM ALGUM \nJAMAIS SE OUVIU DAS MORADAS DO SENHOR.\n<instrumentos>\n\n\nO QUE DEUS TEM PREPARADO PARA NÓS,\nUM LINDO CÉU DE AMOR E PAZ!\nVIVEREMOS PARA SEMPRE COM O SENHOR!\nOLHO HUMANO NUNCA VIU, SOM ALGUM \nJAMAIS SE OUVIU DAS MORADAS DO SENHOR.\n<final>''VINDE, BENDITOS DE MEU PAI,\nPOSSUÍ O REINO DE AMOR E PAZ''.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (675, 'NA ETERNIDADE', 'NA ETERNIDADE', 'NA ETERNIDADE, AO LADO DE JESUS,\nANSEIO LOGO ESTAR E ESTE MUNDO DEIXAR;\nQUERO COM OS ANJOS FORMAR UM GRANDE \nCORO E CANTAR LOUVORES \nDE ADORAÇÃO AO SENHOR.\nO CORO DOS ANJOS E AS VOZES \nDOS ARCANJOS JÁ LOUVAM A JESUS.\n\nCORO\nBREVE OS REMIDOS NA GLÓRIA ESTARÃO\nE JUNTO COM OS ANJOS \nE ARCANJOS VÃO PARA SEMPRE LOUVAR,\nLOUVAR A JESUS.\n\nINSTRUMENTOS\n\nO MEU CORAÇÃO TRANSBORDA DE ALEGRIA \nAO IMAGINAR QUE GRANDE DIA SERÁ;\nO CORDEIRO SANTO VIRÁ SOBRE \nAS NUVENS E A SUA IGREJA \nAO SEU ENCONTRO SUBIRÁ.\nSAUDAI A JESUS! ELE É O REI \nDA GLÓRIA QUE VIRÁ NOS BUSCAR.\n\nCORO\nBREVE OS REMIDOS NA GLÓRIA ESTARÃO\nE JUNTO COM OS ANJOS \nE ARCANJOS VÃO PARA SEMPRE LOUVAR,\nLOUVAR A JESUS.\n\nSAUDAI A JESUS! ELE É O REI DA GLÓRIA \nQUE VIRÁ NOS BUSCAR.\nCORO\nBREVE OS REMIDOS NA GLÓRIA ESTARÃO\nE JUNTO COM OS ANJOS \nE ARCANJOS VÃO PARA SEMPRE LOUVAR, \nLOUVAR A JESUS.\n\nFINAL: LOUVAR A JESUS!', 'NA ETERNIDADE, AO LADO DE JESUS,\nANSEIO LOGO ESTAR E ESTE MUNDO DEIXAR;\nQUERO COM OS ANJOS FORMAR UM GRANDE \nCORO E CANTAR LOUVORES \nDE ADORAÇÃO AO SENHOR.\nO CORO DOS ANJOS E AS VOZES \nDOS ARCANJOS JÁ LOUVAM A JESUS.\n\n<coro>\nBREVE OS REMIDOS NA GLÓRIA ESTARÃO\nE JUNTO COM OS ANJOS \nE ARCANJOS VÃO PARA SEMPRE LOUVAR,\nLOUVAR A JESUS.\n<instrumentos>\n\n\nO MEU CORAÇÃO TRANSBORDA DE ALEGRIA \nAO IMAGINAR QUE GRANDE DIA SERÁ;\nO CORDEIRO SANTO VIRÁ SOBRE \nAS NUVENS E A SUA IGREJA \nAO SEU ENCONTRO SUBIRÁ.\nSAUDAI A JESUS! ELE É O REI \nDA GLÓRIA QUE VIRÁ NOS BUSCAR.\n\n<coro>\nBREVE OS REMIDOS NA GLÓRIA ESTARÃO\nE JUNTO COM OS ANJOS \nE ARCANJOS VÃO PARA SEMPRE LOUVAR,\nLOUVAR A JESUS.\n\nSAUDAI A JESUS! ELE É O REI DA GLÓRIA \nQUE VIRÁ NOS BUSCAR.<coro>\nBREVE OS REMIDOS NA GLÓRIA ESTARÃO\nE JUNTO COM OS ANJOS \nE ARCANJOS VÃO PARA SEMPRE LOUVAR, \nLOUVAR A JESUS.\n<final>LOUVAR A JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (676, 'Ó VINDE ADORAR', 'Ó VINDE ADORAR', 'Ó VINDE ADORAR AO DEUS CRIADOR,\nDA TERRA E DOS CÉUS, ETERNO SENHOR;\nAO DEUS QUE, HABITANDO NO REINO DA LUZ,\nA NÓS SE REVELA POR CRISTO JESUS.\n\nSEU GRANDE PODER DEVEIS CONTEMPLAR,\nNO CÉU ESTRELADO, NO AMPLO MAR;\nA GOTA DE ORVALHO, A MÍNIMA FLOR\nPROCLAMAM CONSTANTES SER DEUS SEU AUTOR.\n\nÓ VINDE ADORAR AO DEUS SALVADOR,\nQUE EM CRISTO JESUS NOS MOSTRA FAVOR;\nAO DEUS QUE, BENIGNO, COM GRAÇA \nE PERDÃO, PECADOS COBRINDO, \nNOS DÁ REDENÇÃO.', 'Ó VINDE ADORAR AO DEUS CRIADOR,\nDA TERRA E DOS CÉUS, ETERNO SENHOR;\nAO DEUS QUE, HABITANDO NO REINO DA LUZ,\nA NÓS SE REVELA POR CRISTO JESUS.\n\nSEU GRANDE PODER DEVEIS CONTEMPLAR,\nNO CÉU ESTRELADO, NO AMPLO MAR;\nA GOTA DE ORVALHO, A MÍNIMA FLOR\nPROCLAMAM CONSTANTES SER DEUS SEU AUTOR.\n\nÓ VINDE ADORAR AO DEUS SALVADOR,\nQUE EM CRISTO JESUS NOS MOSTRA FAVOR;\nAO DEUS QUE, BENIGNO, COM GRAÇA \nE PERDÃO, PECADOS COBRINDO, \nNOS DÁ REDENÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (677, 'A TI, QUE HABITAS ENTRE OS QUERUBINS', 'A TI, QUE HABITAS ENTRE OS QUERUBINS', 'A TI, QUE HABITAS ENTRE OS QUERUBINS,\nE ÉS DEUS DA ETERNIDADE, \nA TI, COMPASSIVO, PAI DE AMOR,\nPROSTRADO EU ADORO.\n\nA TI, QUE ÉS TÃO PURO E PERFEITO, TEU ROSTO NINGUÉM PODE CONTEMPLAR;\nLOUVORES E HONRA, GLÓRIA E PODER,\nPRA SEMPRE, SEMPRE, AMÉM.\n\nA TI, QUE PASSEIAS ENTRE OS CASTIÇAIS,\nVESTIDO COM VESTES BRANCAS,\nA TI, CUJO ROSTO BRILHA COMO O SOL,\nPROSTRADO EU ADORO.\n\nA TI, O PRIMEIRO E O ÚLTIMO,\nA TI, QUE MORRESTE MAS VIVO ESTÁS,\nLOUVORES E HONRA, GLÓRIA E PODER,\nPRA SEMPRE, SEMPRE, AMÉM.', 'A TI, QUE HABITAS ENTRE OS QUERUBINS,\nE ÉS DEUS DA ETERNIDADE, \nA TI, COMPASSIVO, PAI DE AMOR,\nPROSTRADO EU ADORO.\n\nA TI, QUE ÉS TÃO PURO E PERFEITO, TEU ROSTO NINGUÉM PODE CONTEMPLAR;\nLOUVORES E HONRA, GLÓRIA E PODER,\nPRA SEMPRE, SEMPRE, AMÉM.\n\nA TI, QUE PASSEIAS ENTRE OS CASTIÇAIS,\nVESTIDO COM VESTES BRANCAS,\nA TI, CUJO ROSTO BRILHA COMO O SOL,\nPROSTRADO EU ADORO.\n\nA TI, O PRIMEIRO E O ÚLTIMO,\nA TI, QUE MORRESTE MAS VIVO ESTÁS,\nLOUVORES E HONRA, GLÓRIA E PODER,\nPRA SEMPRE, SEMPRE, AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (678, 'TUA GLÓRIA ENCHE TODA A TERRA', 'TUA GLÓRIA ENCHE TODA A TERRA', 'TUA GLÓRIA ENCHE TODA A TERRA,\nTEU NOME É SOBRE TODO NOME,\nTU ÉS O DONO DA MINHA VIDA,\nÉ SÓ EM TI QUE TENHO SALVAÇÃO!\nTU ÉS O DONO DO MEU QUERER\nE OS MEUS LÁBIOS\nPRA SEMPRE TE ADORARÃO.\n\nE COM OS ANJOS TE ADORAREI\nE AOS TEUS PÉS ME PROSTRAREI;\nTU ÉS MINHA VIDA E O MEU LOUVOR\nE AO TEU NOME EXALTAREI.\n\nTUA GLÓRIA ENCHE TODA A TERRA,\nTEU NOME É SOBRE TODO NOME,\nTU ÉS O DONO DA MINHA VIDA,\nÉ SÓ EM TI QUE TENHO SALVAÇÃO!\nTU ÉS O DONO DO MEU QUERER\nE OS MEUS LÁBIOS\nPRA SEMPRE TE ADORARÃO. (3X)\n\nAQUELE QUE MORREU\nMAS A MORTE VENCEU (BIS)\nAQUELE QUE RESSUSCITOU,\nSOBRE A MORTE TRIUNFOU. (BIS)\n\nE AGORA ASSENTADO ESTÁ \nÀ DIREITA DE DEUS PAI,\nTEM O PODER SOBRE TERRA E CÉU,\nTEM O NOME SOBRE TODO NOME,\nELE É O CORDEIRO, JESUS CRISTO, SENHOR.\n\nAQUELE QUE NOS AMA E COM SEU SANGUE \nNOS LIBERTOU DO PECADO\nE NOS CONSTITUIU REINO E SACERDOTES\nPARA NOSSO DEUS E PAI, A ELE A GLÓRIA\nE O DOMÍNIO PELOS SÉCULOS DOS SÉCULOS, AMÉM.\n\nA ELE A GLÓRIA E O DOMÍNIO,\nPELOS SÉCULOS DOS SÉCULOS,\nAMÉM, AMÉM, AMÉM.', 'TUA GLÓRIA ENCHE TODA A TERRA,<bis>\nTEU NOME É SOBRE TODO NOME,<bis>\nTU ÉS O DONO DA MINHA VIDA,<bis>\nÉ SÓ EM TI QUE TENHO SALVAÇÃO!<bis>\nTU ÉS O DONO DO MEU QUERER<bis>\nE OS MEUS LÁBIOS<bis>\nPRA SEMPRE TE ADORARÃO.<bis>\n\nE COM OS ANJOS TE ADORAREI\nE AOS TEUS PÉS ME PROSTRAREI;\nTU ÉS MINHA VIDA E O MEU LOUVOR\nE AO TEU NOME EXALTAREI.\n\nTUA GLÓRIA ENCHE TODA A TERRA,\nTEU NOME É SOBRE TODO NOME,\nTU ÉS O DONO DA MINHA VIDA,\nÉ SÓ EM TI QUE TENHO SALVAÇÃO!\nTU ÉS O DONO DO MEU QUERER\nE OS MEUS LÁBIOS\nPRA SEMPRE TE ADORARÃO. <bis tipo=''3''>\n\nAQUELE QUE MORREU\nMAS A MORTE VENCEU <bis>\nAQUELE QUE RESSUSCITOU,\nSOBRE A MORTE TRIUNFOU. <bis>\n\nE AGORA ASSENTADO ESTÁ \nÀ DIREITA DE DEUS PAI,\nTEM O PODER SOBRE TERRA E CÉU,<bis>\nTEM O NOME SOBRE TODO NOME,<bis>\nELE É O CORDEIRO, JESUS CRISTO, SENHOR.<bis>\n\nAQUELE QUE NOS AMA E COM SEU SANGUE \nNOS LIBERTOU DO PECADO\nE NOS CONSTITUIU REINO E SACERDOTES\nPARA NOSSO DEUS E PAI, A ELE A GLÓRIA\nE O DOMÍNIO PELOS SÉCULOS DOS SÉCULOS, AMÉM.\n\nA ELE A GLÓRIA E O DOMÍNIO,\nPELOS SÉCULOS DOS SÉCULOS,\nAMÉM, AMÉM, AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (679, 'EIS A ESCRAVA RESGATADA', 'EIS A ESCRAVA RESGATADA', 'EIS A ESCRAVA RESGATADA!\nGRANDE PREÇO CRISTO DEU;\nNÃO FOI OURO, NEM FOI PRATA,\nPRÓPRIO SANGUE ELE VERTEU.\n\nCORO\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nJÁ AGORA QUE SOU TUA,\nSEM JAMAIS A TI PERDER,\nQUERO, MEU SENHOR, SERVIR-TE\nGRATA, E SÓ PARA TI VIVER.\n\nCORO\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nQUERO RECEBER TEU JUGO,\nE EM TEUS PASSOS CAMINHAR;\nSE POR TI EU SOFRO TUDO,\nVOU CONTIGO EM PAZ REINAR.\n\nCORO\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nESTÁS NO CÉU! VIVO EU NA TERRA,\nESPERANDO O TEU VOLTAR;\nLEVARÁS ENTÃO A ESCRAVA\nPRA CONTIGO ALI FICAR.\n\nCORO\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nTODO O AMOR POR MIM SENTIAS,\nPADECENDO A DOR DA CRUZ,\nVESTE-ME DA TUA GLÓRIA!\nVEM, Ó VEM, SENHOR JESUS.\n\nCORO\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!', 'EIS A ESCRAVA RESGATADA!\nGRANDE PREÇO CRISTO DEU;\nNÃO FOI OURO, NEM FOI PRATA,\nPRÓPRIO SANGUE ELE VERTEU.\n\n<coro>\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nJÁ AGORA QUE SOU TUA,\nSEM JAMAIS A TI PERDER,\nQUERO, MEU SENHOR, SERVIR-TE\nGRATA, E SÓ PARA TI VIVER.\n\n<coro>\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nQUERO RECEBER TEU JUGO,\nE EM TEUS PASSOS CAMINHAR;\nSE POR TI EU SOFRO TUDO,\nVOU CONTIGO EM PAZ REINAR.\n\n<coro>\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nESTÁS NO CÉU! VIVO EU NA TERRA,\nESPERANDO O TEU VOLTAR;\nLEVARÁS ENTÃO A ESCRAVA\nPRA CONTIGO ALI FICAR.\n\n<coro>\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!\n\nTODO O AMOR POR MIM SENTIAS,\nPADECENDO A DOR DA CRUZ,\nVESTE-ME DA TUA GLÓRIA!\nVEM, Ó VEM, SENHOR JESUS.\n\n<coro>\nTANTO FOI O TEU AMOR\nQUE POR MIM ASSIM MOSTRASTE;\nPRA REMIR MEU CATIVEIRO\nTUA VIDA NÃO POUPASTE!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (680, 'TEU NOME É PRA MIM, SENHOR', 'TEU NOME É PRA MIM, SENHOR', 'TEU NOME É PRA MIM, SENHOR \nMARAVILHOSO, DEUS FORTE;\nTEU NOME É PRA MIM, SENHOR \nMARAVILHOSO, PRÍNCIPE DA PAZ.\n\nCORO (2X)\nEMANUEL É DEUS CONOSCO,\nCONOSCO ESTÁ, PRA SEMPRE VIVERÁ.\n\nTEU NOME É PRA MIM, SENHOR \nCONSELHEIRO, PAI DA ETERNIDADE;\nTEU NOME É PRA MIM, SENHOR \nCONSELHEIRO, PAI DA ETERNIDADE.\n\nCORO (3X)\nEMANUEL É DEUS CONOSCO,\nCONOSCO ESTÁ, PRA SEMPRE VIVERÁ.\n \nFINAL: \nTEU NOME É PRA MIM, \nSENHOR, JESUS.', 'TEU NOME É PRA MIM, SENHOR \nMARAVILHOSO, DEUS FORTE;\nTEU NOME É PRA MIM, SENHOR \nMARAVILHOSO, PRÍNCIPE DA PAZ.\n\n<coro tipo=''2X''>\nEMANUEL É DEUS CONOSCO,\nCONOSCO ESTÁ, PRA SEMPRE VIVERÁ.\n\nTEU NOME É PRA MIM, SENHOR \nCONSELHEIRO, PAI DA ETERNIDADE;\nTEU NOME É PRA MIM, SENHOR \nCONSELHEIRO, PAI DA ETERNIDADE.\n\n<coro tipo=''3X''>\nEMANUEL É DEUS CONOSCO,\nCONOSCO ESTÁ, PRA SEMPRE VIVERÁ.\n<final>TEU NOME É PRA MIM, \nSENHOR, JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (681, 'NOSSO LOUVOR', 'NOSSO LOUVOR', 'NOSSO LOUVOR VAMOS TE OFERTAR\nPELO QUE ÉS, PELO QUE FARÁS;\nNÃO HÁ PALAVRAS QUE POSSAM \nEXPRESSAR NOSSA ADORAÇÃO A TI, \nSENHOR.\n\nINSTRUMENTOS\n\nCOM GRATIDÃO (COM GRATIDÃO)\nVAMOS TE ADORAR (ADORAR)\nPELO QUE ÉS, PELO QUE FARÁS, (EXPRESSAR)\nNÃO HÁ PALAVRAS QUE POSSAM EXPRESSAR \nNOSSO AMOR A TI, SENHOR.\n\nCORO\nMAJESTOSO (MAJESTOSO)\nPODEROSO ÉS, GRAÇAS TE DAMOS \nPOR TUA MISERICÓRDIA,\nA TI PERTENCE TODO O LOUVOR.\n\nINSTRUMENTOS\n\nNOSSO REFÚGIO E DIREÇÃO, (ÉS TU, SENHOR)\nNOSSO AMPARO E PROTEÇÃO, \nNOSSO ABRIGO NO TEMPORAL ÉS TU, SENHOR.\nCOM GRATIDÃO VAMOS TE ADORAR, \nEM TEU ALTAR VAMOS OFERTAR NOSSO LOUVOR, \nQUE É FRUTO DO TEU AMOR.\n\nCORO\nMAJESTOSO (MAJESTOSO)\nPODEROSO ÉS, GRAÇAS TE DAMOS \nPOR TUA MISERICÓRDIA,\nA TI PERTENCE TODO O LOUVOR.\n\nFINAL: \nMAJESTOSO (MAJESTOSO)\nPODEROSO ÉS, GRAÇAS TE DAMOS\nA TI PERTENCE TODO O LOUVOR. (2X)', 'NOSSO LOUVOR VAMOS TE OFERTAR\nPELO QUE ÉS, PELO QUE FARÁS;\nNÃO HÁ PALAVRAS QUE POSSAM \nEXPRESSAR NOSSA ADORAÇÃO A TI, \nSENHOR.\n<instrumentos>\n\n\nCOM GRATIDÃO (COM GRATIDÃO)\nVAMOS TE ADORAR (ADORAR)\nPELO QUE ÉS, PELO QUE FARÁS, (EXPRESSAR)\nNÃO HÁ PALAVRAS QUE POSSAM EXPRESSAR \nNOSSO AMOR A TI, SENHOR.\n\n<coro>\nMAJESTOSO (MAJESTOSO)\nPODEROSO ÉS, GRAÇAS TE DAMOS \nPOR TUA MISERICÓRDIA,\nA TI PERTENCE TODO O LOUVOR.\n<instrumentos>\n\n\nNOSSO REFÚGIO E DIREÇÃO, (ÉS TU, SENHOR)\nNOSSO AMPARO E PROTEÇÃO, \nNOSSO ABRIGO NO TEMPORAL ÉS TU, SENHOR.\nCOM GRATIDÃO VAMOS TE ADORAR, \nEM TEU ALTAR VAMOS OFERTAR NOSSO LOUVOR, \nQUE É FRUTO DO TEU AMOR.\n\n<coro>\nMAJESTOSO (MAJESTOSO)\nPODEROSO ÉS, GRAÇAS TE DAMOS \nPOR TUA MISERICÓRDIA,\nA TI PERTENCE TODO O LOUVOR.\n\n\n<final>MAJESTOSO (MAJESTOSO)\nPODEROSO ÉS, GRAÇAS TE DAMOS\nA TI PERTENCE TODO O LOUVOR. <bis tipo=''2''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (682, 'A JESUS SEJA DADA TODA GLÓRIA', 'A JESUS SEJA DADA TODA GLÓRIA', 'CORO \nA JESUS SEJA DADA TODA GLÓRIA E LOUVOR, \nA JESUS SEJA DADA\nTODA GLÓRIA, HONRA E LOUVOR.\n\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\n\nCORO \nA JESUS SEJA DADA TODA GLÓRIA E LOUVOR, \nA JESUS SEJA DADA\nTODA GLÓRIA, HONRA E LOUVOR.\n\nQUEREMOS TE ADORAR EM ESPÍRITO \nE EM VERDADE, A VERDADEIRA ADORAÇÃO \nÉ A QUE PROCEDE DO CORAÇÃO, DO CORAÇÃO\nDOS QUE LOUVAM AO SENHOR.\n\nCORO (2X)\nA JESUS SEJA DADA TODA GLÓRIA E LOUVOR, \nA JESUS SEJA DADA\nTODA GLÓRIA, HONRA E LOUVOR.', '<coro>\nA JESUS SEJA DADA TODA GLÓRIA E LOUVOR, \nA JESUS SEJA DADA\nTODA GLÓRIA, HONRA E LOUVOR.\n\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\nESTÁ ASSENTADO NO TRONO,\nÀ DIREITA DE DEUS PAI.\n\n<coro>\nA JESUS SEJA DADA TODA GLÓRIA E LOUVOR, \nA JESUS SEJA DADA\nTODA GLÓRIA, HONRA E LOUVOR.\n\nQUEREMOS TE ADORAR EM ESPÍRITO \nE EM VERDADE, A VERDADEIRA ADORAÇÃO \nÉ A QUE PROCEDE DO CORAÇÃO, DO CORAÇÃO\nDOS QUE LOUVAM AO SENHOR.\n\n<coro tipo=''2X''>\nA JESUS SEJA DADA TODA GLÓRIA E LOUVOR, \nA JESUS SEJA DADA\nTODA GLÓRIA, HONRA E LOUVOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (683, 'JESUS CRISTO VOLTARÁ', 'JESUS CRISTO VOLTARÁ', 'JESUS CRISTO VOLTARÁ PRA NOS LEVAR,\nSUA IGREJA FIEL SUBIRÁ PRA GLÓRIA;\nDEIXAREMOS ESTE MUNDO DE TRISTEZA,\nPARA ESTAR COM NOSSO AMADO SALVADOR.\n\nCORO\nLOUVAREMOS A JESUS, O REI,\nCANTAREMOS UM HINO DE VITÓRIA,\nCOM OS ANJOS ESTAREMOS\nNAS MAIS BELAS MANSÕES CELESTIAIS.\n\nALELUIA, VAMOS TODOS ADORAR\nA JESUS, O LEÃO DA TRIBO DE JUDÁ,\nQUE FOI MORTO MAS RESSUSCITOU,\nVAMOS CANTAR (VAMOS CANTAR)\nESTE GRANDE AMOR DO NOSSO SALVADOR.\n\nCORO\nLOUVAREMOS A JESUS, O REI,\nCANTAREMOS UM HINO DE VITÓRIA,\nCOM OS ANJOS ESTAREMOS\nNAS MAIS BELAS MANSÕES CELESTIAIS.\n\nALELUIA, VAMOS TODOS ADORAR\nA JESUS, O LEÃO DA TRIBO DE JUDÁ,\nQUE FOI MORTO MAS RESSUSCITOU,\nVAMOS CANTAR (VAMOS CANTAR)\nESTE GRANDE AMOR DO NOSSO SALVADOR.\n\nCORO\nLOUVAREMOS A JESUS, O REI,\nCANTAREMOS UM HINO DE VITÓRIA,\nCOM OS ANJOS ESTAREMOS\nNAS MAIS BELAS MANSÕES CELESTIAIS.', 'JESUS CRISTO VOLTARÁ PRA NOS LEVAR,\nSUA IGREJA FIEL SUBIRÁ PRA GLÓRIA;\nDEIXAREMOS ESTE MUNDO DE TRISTEZA,\nPARA ESTAR COM NOSSO AMADO SALVADOR.\n\n<coro>\nLOUVAREMOS A JESUS, O REI,\nCANTAREMOS UM HINO DE VITÓRIA,\nCOM OS ANJOS ESTAREMOS\nNAS MAIS BELAS MANSÕES CELESTIAIS.\n\nALELUIA, VAMOS TODOS ADORAR\nA JESUS, O LEÃO DA TRIBO DE JUDÁ,\nQUE FOI MORTO MAS RESSUSCITOU,\nVAMOS CANTAR (VAMOS CANTAR)\nESTE GRANDE AMOR DO NOSSO SALVADOR.\n\n<coro>\nLOUVAREMOS A JESUS, O REI,\nCANTAREMOS UM HINO DE VITÓRIA,\nCOM OS ANJOS ESTAREMOS\nNAS MAIS BELAS MANSÕES CELESTIAIS.\n\nALELUIA, VAMOS TODOS ADORAR\nA JESUS, O LEÃO DA TRIBO DE JUDÁ,\nQUE FOI MORTO MAS RESSUSCITOU,\nVAMOS CANTAR (VAMOS CANTAR)\nESTE GRANDE AMOR DO NOSSO SALVADOR.\n\n<coro>\nLOUVAREMOS A JESUS, O REI,\nCANTAREMOS UM HINO DE VITÓRIA,\nCOM OS ANJOS ESTAREMOS\nNAS MAIS BELAS MANSÕES CELESTIAIS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (684, 'ELE É O REI DOS REIS', 'ELE É O REI DOS REIS', 'ELE É O REI DOS REIS,\nA RAIZ DE DAVI, ELE É JESUS.\n\nINSTRUMENTOS\n\nAO QUE ESTÁ NO TRONO SEJA O LOUVOR,\nAO CORDEIRO MORTO QUE RESSUSCITOU,\nÀ RESPLANDECENTE ESTRELA DA MANHÃ,\nSEJA DADA A GLÓRIA E TODO LOUVOR,\nSEJA DADA A GLÓRIA E TODO LOUVOR.\n\nCORO\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O CORDEIRO QUE VENCEU;\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O REI DOS REIS, A RAIZ DE DAVI, \nELE É JESUS.\n\nINSTRUMENTOS\n\nLOUVEMOS A GLÓRIA \n(DO REI DOS REIS)\nDAQUELE QUE É VENCEDOR, \n(JESUS VOLTARÁ)\nPORQUE SÃO CHEGADAS \n(JESUS VOLTARÁ)\nAS BODAS DO CORDEIRO.\n\nCORO\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O CORDEIRO QUE VENCEU;\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O REI DOS REIS, A RAIZ DE DAVI, \nELE É JESUS.\n\nFINAL: \nELE É O REI DOS REIS, \nA RAIZ DE DAVI, ELE É JESUS.', 'ELE É O REI DOS REIS,\nA RAIZ DE DAVI, ELE É JESUS.\n<instrumentos>\n\n\nAO QUE ESTÁ NO TRONO SEJA O LOUVOR,\nAO CORDEIRO MORTO QUE RESSUSCITOU,\nÀ RESPLANDECENTE ESTRELA DA MANHÃ,\nSEJA DADA A GLÓRIA E TODO LOUVOR,\nSEJA DADA A GLÓRIA E TODO LOUVOR.\n\n<coro>\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O CORDEIRO QUE VENCEU;\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O REI DOS REIS, A RAIZ DE DAVI, \nELE É JESUS.\n<instrumentos>\n\n\nLOUVEMOS A GLÓRIA \n(DO REI DOS REIS)\nDAQUELE QUE É VENCEDOR, \n(JESUS VOLTARÁ)\nPORQUE SÃO CHEGADAS \n(JESUS VOLTARÁ)\nAS BODAS DO CORDEIRO.\n\n<coro>\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O CORDEIRO QUE VENCEU;\nO LEÃO DA TRIBO DE JUDÁ ESTÁ NO \nTRONO ELE É O REI DOS REIS, A RAIZ DE DAVI, \nELE É JESUS.\n<final>ELE É O REI DOS REIS, \nA RAIZ DE DAVI, ELE É JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (685, 'PERFEITO AMOR EU CONHECI', 'PERFEITO AMOR EU CONHECI', 'PERFEITO AMOR EU CONHECI, \nNÃO IMAGINEI QUE ELE PODERIA EXISTIR;\nAMOR FIEL E VERDADEIRO AMOR, \nTUDO ELE SUPORTOU, ME AMOU ATÉ O FIM.\n\nFOI, ENTÃO, QUE EU SENTI\nCOMO É FORTE O AMOR QUE RECEBI;\nAMOR FIEL E VERDADEIRO AMOR\nÉ JESUS, O MEU SENHOR.\nTENHO EM MIM O SEU AMOR.\n\nDIFERENTE DO AMOR \nQUE NO MUNDO ESTÁ, AMOR PERFEITO \nÉ DOM DE DEUS E SÓ ELE PODE DAR;\nCOM ESTE AMOR EU POSSO CRER, \nTUDO SUPERAR, SEI QUE EM TODA \nA MINHA VIDA ELE NÃO FALHARÁ.\n\nDIFERENTE DO AMOR (DIFERENTE DO AMOR)\nQUE NO MUNDO ESTÁ, AMOR PERFEITO \nÉ DOM DE DEUS E SÓ ELE PODE DAR;\nCOM ESTE AMOR EU POSSO CRER, \n(COM ESTE AMOR EU POSSO CRER) \nTUDO SUPERAR, SEI QUE EM TODA \nA MINHA VIDA ELE NÃO FALHARÁ.\n\nINSTRUMENTOS\n\nFINAL: \nAMOR FIEL E VERDADEIRO AMOR,\nRECEBI DO MEU SENHOR,\nQUE ME AMOU COM ETERNO AMOR.', 'PERFEITO AMOR EU CONHECI, \nNÃO IMAGINEI QUE ELE PODERIA EXISTIR;\nAMOR FIEL E VERDADEIRO AMOR, \nTUDO ELE SUPORTOU, ME AMOU ATÉ O FIM.\n\nFOI, ENTÃO, QUE EU SENTI\nCOMO É FORTE O AMOR QUE RECEBI;\nAMOR FIEL E VERDADEIRO AMOR\nÉ JESUS, O MEU SENHOR.\nTENHO EM MIM O SEU AMOR.\n\nDIFERENTE DO AMOR \nQUE NO MUNDO ESTÁ, AMOR PERFEITO \nÉ DOM DE DEUS E SÓ ELE PODE DAR;\nCOM ESTE AMOR EU POSSO CRER, \nTUDO SUPERAR, SEI QUE EM TODA \nA MINHA VIDA ELE NÃO FALHARÁ.\n\nDIFERENTE DO AMOR (DIFERENTE DO AMOR)\nQUE NO MUNDO ESTÁ, AMOR PERFEITO \nÉ DOM DE DEUS E SÓ ELE PODE DAR;\nCOM ESTE AMOR EU POSSO CRER, \n(COM ESTE AMOR EU POSSO CRER) \nTUDO SUPERAR, SEI QUE EM TODA \nA MINHA VIDA ELE NÃO FALHARÁ.\n<instrumentos>\n\n\n\n<final>AMOR FIEL E VERDADEIRO AMOR,\nRECEBI DO MEU SENHOR,\nQUE ME AMOU COM ETERNO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (686, 'QUANDO JESUS PROVOU O SEU AMOR POR MIM', 'QUANDO JESUS PROVOU O SEU AMOR POR MIM', 'QUANDO JESUS PROVOU \nO SEU AMOR POR MIM,\nSOFRENDO NA CRUZ, \nDERRAMANDO SEU SANGUE PURO,\nESTAVA COM ELE O AMOR DO PAI.\nQUÃO IMENSURÁVEL ESTE AMOR!\n\nCORO (2X)\nEMBORA EU NÃO MEREÇA,\nFOI A SUA COMPAIXÃO\nQUE ME DEU ETERNA SALVAÇÃO.\n\nINSTRUMENTOS\n\nTODO O MEU LOUVOR, MINHA ADORAÇÃO,\nENTREGO A CRISTO, DONO DO MEU VIVER;\nGLÓRIA E HONRA AO CORDEIRO ETERNO,\nQUE DEU SUA VIDA POR ME AMAR.\n\nCORO (2X)\nEMBORA EU NÃO MEREÇA,\nFOI A SUA COMPAIXÃO\nQUE ME DEU ETERNA SALVAÇÃO.', 'QUANDO JESUS PROVOU \nO SEU AMOR POR MIM,\nSOFRENDO NA CRUZ, \nDERRAMANDO SEU SANGUE PURO,\nESTAVA COM ELE O AMOR DO PAI.\nQUÃO IMENSURÁVEL ESTE AMOR!\n\n<coro tipo=''2X''>\nEMBORA EU NÃO MEREÇA,\nFOI A SUA COMPAIXÃO\nQUE ME DEU ETERNA SALVAÇÃO.\n<instrumentos>\n\n\nTODO O MEU LOUVOR, MINHA ADORAÇÃO,\nENTREGO A CRISTO, DONO DO MEU VIVER;\nGLÓRIA E HONRA AO CORDEIRO ETERNO,\nQUE DEU SUA VIDA POR ME AMAR.\n\n<coro tipo=''2X''>\nEMBORA EU NÃO MEREÇA,\nFOI A SUA COMPAIXÃO\nQUE ME DEU ETERNA SALVAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (687, 'QUEM É COMO TU?', 'QUEM É COMO TU?', 'QUEM É COMO TU?\nFORTE COMO TU, SENHOR,\nCOM TUA FIDELIDADE AO REDOR DE TI?\nQUEM É COMO TU?\nQUE DOMINAS O ÍMPETO DO MAR;\nQUANDO SUAS ONDAS SE LEVANTAM,\nTU FAZES ACALMAR.\n\nCORO\nTEU É O CÉU, TUA A TERRA, \nO MUNDO E A SUA PLENITUDE;\nNORTE E SUL CRIASTE; MISERICÓRDIA \nE VERDADE VÃO PERANTE TUA FACE, \nOH! SENHOR!\n\nCOM TUA PRESENÇA \nOS MEUS PASSOS SE FIRMARÃO,\nMEU PEQUENO BRAÇO SE FORTALECERÁ\nE OS MEUS PENSAMENTOS\nDESCANSARÃO EM TEU ALTAR;\nNENHUMA TEMPESTADE ME ABALARÁ!\n\nCORO\nTEU É O CÉU, TUA A TERRA, \nO MUNDO E A SUA PLENITUDE;\nNORTE E SUL CRIASTE; MISERICÓRDIA \nE VERDADE VÃO PERANTE TUA FACE, \nOH! SENHOR!\n\nFINAL: \nQUEM É COMO TU? \n(Ó SENHOR)', 'QUEM É COMO TU?\nFORTE COMO TU, SENHOR,\nCOM TUA FIDELIDADE AO REDOR DE TI?\nQUEM É COMO TU?\nQUE DOMINAS O ÍMPETO DO MAR;\nQUANDO SUAS ONDAS SE LEVANTAM,\nTU FAZES ACALMAR.\n\n<coro>\nTEU É O CÉU, TUA A TERRA, \nO MUNDO E A SUA PLENITUDE;\nNORTE E SUL CRIASTE; MISERICÓRDIA \nE VERDADE VÃO PERANTE TUA FACE, \nOH! SENHOR!\n\nCOM TUA PRESENÇA \nOS MEUS PASSOS SE FIRMARÃO,\nMEU PEQUENO BRAÇO SE FORTALECERÁ\nE OS MEUS PENSAMENTOS\nDESCANSARÃO EM TEU ALTAR;\nNENHUMA TEMPESTADE ME ABALARÁ!\n\n<coro>\nTEU É O CÉU, TUA A TERRA, \nO MUNDO E A SUA PLENITUDE;\nNORTE E SUL CRIASTE; MISERICÓRDIA \nE VERDADE VÃO PERANTE TUA FACE, \nOH! SENHOR!\n<final>QUEM É COMO TU? \n(Ó SENHOR)', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (688, 'CRISTO JÁ RESSUSCITOU', 'CRISTO JÁ RESSUSCITOU', 'CRISTO JÁ RESSUSCITOU: ALELUIA!\nSOBRE A MORTE TRIUNFOU: ALELUIA!\nTUDO CONSUMADO ESTÁ! ALELUIA!\nSALVAÇÃO DE GRAÇA DÁ! ALELUIA!\n\nUMA VEZ NA CRUZ SOFREU: ALELUIA!\nUMA VEZ POR NÓS MORREU: ALELUIA!\nMAS AGORA VIVO ESTÁ, ALELUIA!\nE PRA SEMPRE REINARÁ, ALELUIA!\n\nINSTRUMENTOS\n\nGRATOS HINOS ENTOAI, ALELUIA!\nA JESUS O GRANDE REI, ALELUIA!\nPOIS À MORTE QUIS BAIXAR, ALELUIA!\nPECADORES PRA SALVAR! ALELUIA!', 'CRISTO JÁ RESSUSCITOU: ALELUIA!\nSOBRE A MORTE TRIUNFOU: ALELUIA!\nTUDO CONSUMADO ESTÁ! ALELUIA!\nSALVAÇÃO DE GRAÇA DÁ! ALELUIA!\n\nUMA VEZ NA CRUZ SOFREU: ALELUIA!\nUMA VEZ POR NÓS MORREU: ALELUIA!\nMAS AGORA VIVO ESTÁ, ALELUIA!\nE PRA SEMPRE REINARÁ, ALELUIA!\n<instrumentos>\nGRATOS HINOS ENTOAI, ALELUIA!\nA JESUS O GRANDE REI, ALELUIA!\nPOIS À MORTE QUIS BAIXAR, ALELUIA!\nPECADORES PRA SALVAR! ALELUIA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (689, 'AMOR, QUE POR AMOR DESCESTE!', 'AMOR, QUE POR AMOR DESCESTE!', 'AMOR, QUE POR AMOR DESCESTE!\nAMOR, QUE POR AMOR MORRESTE!\nAH! QUANTA DOR NÃO PADECESTE,\nMEU CORAÇÃO PRA CONQUISTAR\nE MEU AMOR GANHAR!\n\nAMOR, QUE COM AMOR SEGUIAS \nA MIM, QUE SEM AMOR TU VIAS!\nOH! QUANTO AMOR POR MIM SENTIAS,\nMEU SALVADOR, MEU BOM JESUS,\nSOFRENDO SOBRE A CRUZ!\n\nINSTRUMENTOS\n\nAMOR, QUE TUDO ME PERDOAS!\nAMOR, QUE ATÉ MESMO ABENÇOAS\nUM RÉU A QUEM TU TE AFEIÇOAS!\nPOR TI VENCIDO, Ó SALVADOR,\nEIS-ME AOS TEUS PÉS, SENHOR.\n\nAMOR QUE NUNCA, NUNCA MUDA,\nQUE EM TUA GRAÇA ME SEGURA,\nCERCANDO-ME DE MIL VENTURAS;\nACEITA AGORA, Ó SALVADOR,\nO MEU HUMILDE AMOR!', 'AMOR, QUE POR AMOR DESCESTE!\nAMOR, QUE POR AMOR MORRESTE!\nAH! QUANTA DOR NÃO PADECESTE,\nMEU CORAÇÃO PRA CONQUISTAR\nE MEU AMOR GANHAR!\n\nAMOR, QUE COM AMOR SEGUIAS \nA MIM, QUE SEM AMOR TU VIAS!\nOH! QUANTO AMOR POR MIM SENTIAS,\nMEU SALVADOR, MEU BOM JESUS,\nSOFRENDO SOBRE A CRUZ!\n<instrumentos>\n\n\nAMOR, QUE TUDO ME PERDOAS!\nAMOR, QUE ATÉ MESMO ABENÇOAS\nUM RÉU A QUEM TU TE AFEIÇOAS!\nPOR TI VENCIDO, Ó SALVADOR,\nEIS-ME AOS TEUS PÉS, SENHOR.\n\nAMOR QUE NUNCA, NUNCA MUDA,\nQUE EM TUA GRAÇA ME SEGURA,\nCERCANDO-ME DE MIL VENTURAS;\nACEITA AGORA, Ó SALVADOR,\nO MEU HUMILDE AMOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (690, 'DA IGREJA O FUNDAMENTO (A PEDRA FUNDAMENTAL)', 'DA IGREJA O FUNDAMENTO (A PEDRA FUNDAMENTAL)', 'DA IGREJA O FUNDAMENTO É CRISTO, O SALVADOR;\nEM SEU PODER DESCANSA E É FORTE EM SEU AMOR.\nEM CRISTO BEM FIRMADA, SEGURA SEMPRE ESTÁ,\nE, SOBRE A ROCHA ETERNA JAMAIS SE ABALARÁ.\n\nA PEDRA PRECIOSA QUE DEUS PREDESTINOU \nSUSTENTA PEDRAS VIVAS, QUE A GRAÇA TRABALHOU.\nE, QUANDO O MONUMENTO SURGIR EM PLENA LUZ,\nA GLÓRIA DO EDIFÍCIO SERÁ DO REI JESUS!\n\nSENHOR, NÓS TE ROGAMOS QUE, \nERGUIDO POR AMOR, \nO TEMPLO CONSAGRADO \nREDUNDE EM TEU LOUVOR;\nE QUE ALMAS REDIMIDAS AQUI, \nEM COMUNHÃO, SE TORNEM TEMPLO \nSANTO DA TUA HABITAÇÃO. \n\nFINAL: AMÉM!', 'DA IGREJA O FUNDAMENTO É CRISTO, O SALVADOR;\nEM SEU PODER DESCANSA E É FORTE EM SEU AMOR.\nEM CRISTO BEM FIRMADA, SEGURA SEMPRE ESTÁ,\nE, SOBRE A ROCHA ETERNA JAMAIS SE ABALARÁ.\n\nA PEDRA PRECIOSA QUE DEUS PREDESTINOU \nSUSTENTA PEDRAS VIVAS, QUE A GRAÇA TRABALHOU.\nE, QUANDO O MONUMENTO SURGIR EM PLENA LUZ,\nA GLÓRIA DO EDIFÍCIO SERÁ DO REI JESUS!\n\nSENHOR, NÓS TE ROGAMOS QUE, \nERGUIDO POR AMOR, \nO TEMPLO CONSAGRADO \nREDUNDE EM TEU LOUVOR;\nE QUE ALMAS REDIMIDAS AQUI, \nEM COMUNHÃO, SE TORNEM TEMPLO \nSANTO DA TUA HABITAÇÃO. \n<final>AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (691, 'AO DEUS DE ABRAÃO', 'AO DEUS DE ABRAÃO', 'AO DEUS DE ABRAÃO LOUVAI; \nDO VASTO CÉU SENHOR; \nETERNO E PODEROSO PAIE DEUS DE AMOR.\nAUGUSTO DEUS JEOVÁ, \nQUE TERRA E CÉU CRIOU; \nMINH'' ALMA O NOME ABENÇOARÁ\nDO GRANDE EU SOU.\n\nAO DEUS DE ABRAÃO LOUVAI; \nEIS, POR MANDADO SEU, \nMINH'' ALMA DEIXA A TERRA, \n E VAI GOZAR NO CÉU.\nO MUNDO DESPREZEI, \nSEU LUCRO E SEU LOUVOR, \nE DEUS POR MEU SENHOR \nTOMEI E PROTETOR.\n\nMEU GUIA DEUS SERÁ SEU INFINITO \nAMOR FELIZ EM TUDO ME FARÁ \nPOR ONDE EU FOR TOMOU-ME PELA MÃO, \nEM TREVAS DEU-ME LUZ, \nE DÁ-ME ETERNA SALVAÇÃO,\nPOR MEU JESUS.\n\nMEU DEUS POR SI JUROU, E NELE CONFIEI, \nE PARA O CÉU QUE PREPAROU EU SUBIREI.\nSUA FACE EU HEI DE VER, CONFIADO EM SEU AMOR, \nE EU HEI DE SEMPRE ENGRANDECER MEU REDENTOR.', 'AO DEUS DE ABRAÃO LOUVAI; \nDO VASTO CÉU SENHOR; \nETERNO E PODEROSO PAIE DEUS DE AMOR.\nAUGUSTO DEUS JEOVÁ, \nQUE TERRA E CÉU CRIOU; \nMINH'' ALMA O NOME ABENÇOARÁ\nDO GRANDE EU SOU.\n\nAO DEUS DE ABRAÃO LOUVAI; \nEIS, POR MANDADO SEU, \nMINH'' ALMA DEIXA A TERRA, \n E VAI GOZAR NO CÉU.\nO MUNDO DESPREZEI, \nSEU LUCRO E SEU LOUVOR, \nE DEUS POR MEU SENHOR \nTOMEI E PROTETOR.\n\nMEU GUIA DEUS SERÁ SEU INFINITO \nAMOR FELIZ EM TUDO ME FARÁ \nPOR ONDE EU FOR TOMOU-ME PELA MÃO, \nEM TREVAS DEU-ME LUZ, \nE DÁ-ME ETERNA SALVAÇÃO,\nPOR MEU JESUS.\n\nMEU DEUS POR SI JUROU, E NELE CONFIEI, \nE PARA O CÉU QUE PREPAROU EU SUBIREI.\nSUA FACE EU HEI DE VER, CONFIADO EM SEU AMOR, \nE EU HEI DE SEMPRE ENGRANDECER MEU REDENTOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (692, 'COMIGO HABITA, Ó DEUS!', 'COMIGO HABITA, Ó DEUS!', 'COMIGO HABITA, Ó DEUS!\nA NOITE VEM, AS TREVAS CRESCEM;\nEIS, SENHOR, CONVÉM\nQUE ME SOCORRA A TUA PROTEÇÃO;\nOH! VEM FAZER COMIGO HABITAÇÃO!\n\nVEM REVELAR-TE A MIM, JESUS, SENHOR!\nMESTRE DIVINO! REI! CONSOLADOR!\nÉ QUEM ME GUIA! AMPARO EM PROVAÇÃO!\nVEM, VEM FAZER COMIGO HABITAÇÃO.\n\nPRESENTE ESTÁS NAS TREVAS OU NA LUZ!\nNÃO HÁ PERIGO, ANDANDO COM JESUS!\nPARTIR COM CRISTO, ETERNA REDENÇÃO,\nONDE MEU DEUS FIZER HABITAÇÃO.\n\nQUE ALEGRIA, QUE SATISFAÇÃO\nVER O SENHOR, A GRANDE SALVAÇÃO!\nEXULTAREMOS NA RESSURREIÇÃO;\nTENHO COM DEUS ETERNA HABITAÇÃO.', 'COMIGO HABITA, Ó DEUS!\nA NOITE VEM, AS TREVAS CRESCEM;\nEIS, SENHOR, CONVÉM\nQUE ME SOCORRA A TUA PROTEÇÃO;\nOH! VEM FAZER COMIGO HABITAÇÃO!\n\nVEM REVELAR-TE A MIM, JESUS, SENHOR!\nMESTRE DIVINO! REI! CONSOLADOR!\nÉ QUEM ME GUIA! AMPARO EM PROVAÇÃO!\nVEM, VEM FAZER COMIGO HABITAÇÃO.\n\nPRESENTE ESTÁS NAS TREVAS OU NA LUZ!\nNÃO HÁ PERIGO, ANDANDO COM JESUS!\nPARTIR COM CRISTO, ETERNA REDENÇÃO,\nONDE MEU DEUS FIZER HABITAÇÃO.\n\nQUE ALEGRIA, QUE SATISFAÇÃO\nVER O SENHOR, A GRANDE SALVAÇÃO!\nEXULTAREMOS NA RESSURREIÇÃO;\nTENHO COM DEUS ETERNA HABITAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (693, 'DORMINDO NO MEU LEITO (JERUSALÉM, CIDADE SANTA)', 'DORMINDO NO MEU LEITO (JERUSALÉM, CIDADE SANTA)', 'DORMINDO NO MEU LEITO,\nEM SONHO ENCANTADOR,\nUM DIA EU VI JERUSALÉM\nE O TEMPLO DO SENHOR.\nOUVI CANTAR CRIANÇAS\nE EM MEIO AO SEU CANTAR.\n\nROMPEU A VOZ DOS ANJOS,\nDO CÉU A PROCLAMAR:\n''JERUSALÉM! JERUSALÉM!\nCANTAI, Ó SANTA GREI!\nHOSANA! HOSANA!\nHOSANA AO VOSSO REI!''\n\nINSTRUMENTOS\n\nENTÃO O SONHO SE ALTEROU,\nNÃO MAIS O SOM FELIZ\nOUVIA DAS HOSANAS \nDOS COROS INFANTIS.\nO AR EM TORNO SE ESFRIOU,\nDO SOL FALTAVA A LUZ;\n\nE NUM ALTO E TOSCO MONTE \nVI O VULTO DE UMA CRUZ.\n''JERUSALÉM! JERUSALÉM!\n(AOS ANJOS ESCUTEI)\nHOSANA! HOSANA!\nHOSANA AO VOSSO REI!''\n\nINSTRUMENTOS\n\nAINDA A CENA SE MUDOU;\nSURGIA EM RESPLENDOR\nA DIVINAL CIDADE, \nMORADA DO SENHOR.\nDA LUA NÃO BRILHAVA A LUZ,\nNEM SOL NASCIA LÁ,\nMAS SÓ FULGIA A LUZ DE DEUS,\nMUI PURA EM SEU BRILHAR,\n\nE TODOS QUE QUERIAM, SIM,\nPODIAM LOGO ENTRAR\nNA MUI FELIZ JERUSALÉM,\nQUE NUNCA PASSARÁ.\n''JERUSALÉM! JERUSALÉM!\nTEU DIA VAI RAIAR!\nHOSANA! HOSANA!\nHOSANA SEM CESSAR!\nHOSANA! HOSANA! \nHOSANA SEM CESSAR!''', 'DORMINDO NO MEU LEITO,\nEM SONHO ENCANTADOR,\nUM DIA EU VI JERUSALÉM\nE O TEMPLO DO SENHOR.\nOUVI CANTAR CRIANÇAS\nE EM MEIO AO SEU CANTAR.\n\nROMPEU A VOZ DOS ANJOS,<bis>\nDO CÉU A PROCLAMAR:<bis>\n''JERUSALÉM! JERUSALÉM!\nCANTAI, Ó SANTA GREI!\nHOSANA! HOSANA!\nHOSANA AO VOSSO REI!''\n<instrumentos>\n\n\nENTÃO O SONHO SE ALTEROU,\nNÃO MAIS O SOM FELIZ\nOUVIA DAS HOSANAS \nDOS COROS INFANTIS.\nO AR EM TORNO SE ESFRIOU,\nDO SOL FALTAVA A LUZ;\n\nE NUM ALTO E TOSCO MONTE <bis>\nVI O VULTO DE UMA CRUZ.<bis>\n''JERUSALÉM! JERUSALÉM!\n(AOS ANJOS ESCUTEI)\nHOSANA! HOSANA!\nHOSANA AO VOSSO REI!''\n<instrumentos>\n\n\nAINDA A CENA SE MUDOU;\nSURGIA EM RESPLENDOR\nA DIVINAL CIDADE, \nMORADA DO SENHOR.\nDA LUA NÃO BRILHAVA A LUZ,\nNEM SOL NASCIA LÁ,\nMAS SÓ FULGIA A LUZ DE DEUS,\nMUI PURA EM SEU BRILHAR,\n\nE TODOS QUE QUERIAM, SIM,\nPODIAM LOGO ENTRAR\nNA MUI FELIZ JERUSALÉM,<bis>\nQUE NUNCA PASSARÁ.<bis>\n''JERUSALÉM! JERUSALÉM!\nTEU DIA VAI RAIAR!\nHOSANA! HOSANA!\nHOSANA SEM CESSAR!\nHOSANA! HOSANA! \nHOSANA SEM CESSAR!''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (694, 'JERUSALÉM ETERNA', 'JERUSALÉM ETERNA', 'JERUSALÉM ETERNA, EM BREVE TU VIRÁS, \nDESCENDO COMO NOIVA\nATAVIADA PARA O SEU MARIDO.\n\nJERUSALÉM, MINHA CIDADE, \nCOMO ANSEIO ENTRAR \nE ANDAR POR TUAS RUAS,\nSAUDAR OS TEUS REMIDOS\nE ADORAR TEU REI.\n\nINSTRUMENTOS\n\nJERUSALÉM ETERNA, ESPOSA DO CORDEIRO,\nEM TI HABITARÁ DEUS COM OS HOMENS\nPARA TODO SEMPRE.\nNAÇÕES VIRÃO PARA ADORAR E REIS \nTRARÃO SUA GLÓRIA\nAO FILHO DE DAVI, AO PRÍNCIPE DA PAZ,\nTEU REI, JERUSALÉM. JERUSALÉM.', 'JERUSALÉM ETERNA, EM BREVE TU VIRÁS, \nDESCENDO COMO NOIVA\nATAVIADA PARA O SEU MARIDO.\n\nJERUSALÉM, MINHA CIDADE, \nCOMO ANSEIO ENTRAR \nE ANDAR POR TUAS RUAS,<bis>\nSAUDAR OS TEUS REMIDOS<bis>\nE ADORAR TEU REI.<bis>\n<instrumentos>\n\n\nJERUSALÉM ETERNA, ESPOSA DO CORDEIRO,\nEM TI HABITARÁ DEUS COM OS HOMENS\nPARA TODO SEMPRE.\nNAÇÕES VIRÃO PARA ADORAR E REIS \nTRARÃO SUA GLÓRIA\nAO FILHO DE DAVI, AO PRÍNCIPE DA PAZ,<bis>\nTEU REI, JERUSALÉM. JERUSALÉM.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (695, 'JERUSALÉM EXCELSA', 'JERUSALÉM EXCELSA', 'JERUSALÉM EXCELSA,\nGLORIAMO-NOS EM TI;\nCONSOLADORA ESPERANÇA \nDO TEU REBANHO AQUI;\nRADIANTE, BELOS MUROS, \nELE JÁ DE LONGE VÊ\nE A GLÓRIA DA CIDADE \nCONTEMPLA PELA FÉ.\n\nÉ A CRUZ QUE TE ALUMIA; \nE AO GRANDE REDENTOR,\nCORDEIRO, TEU ESPOSO, \nTRIBUTAS-LHE LOUVOR.\nQUE GOZO QUE ME INSPIRA, \nETERNA HABITAÇÃO,\nSABER QUE EM TI \nTERMINO A PEREGRINAÇÃO!\n\nÓ DOCE PÁTRIA AMADA, \nTEU GOZO SERÁ MEU!\nÓ PÁTRIA DESEJADA, \nQUE ENCANTO É ESSE TEU;\nEXULTA, TU QUE GEMES \nNA DOR QUE SE DESFAZ;\nCOM DEUS, QUE TE REDIME, \nFELIZ SEMPRE SERÁS.', 'JERUSALÉM EXCELSA,\nGLORIAMO-NOS EM TI;\nCONSOLADORA ESPERANÇA \nDO TEU REBANHO AQUI;\nRADIANTE, BELOS MUROS, \nELE JÁ DE LONGE VÊ\nE A GLÓRIA DA CIDADE \nCONTEMPLA PELA FÉ.\n\nÉ A CRUZ QUE TE ALUMIA; \nE AO GRANDE REDENTOR,\nCORDEIRO, TEU ESPOSO, \nTRIBUTAS-LHE LOUVOR.\nQUE GOZO QUE ME INSPIRA, \nETERNA HABITAÇÃO,\nSABER QUE EM TI \nTERMINO A PEREGRINAÇÃO!\n\nÓ DOCE PÁTRIA AMADA, \nTEU GOZO SERÁ MEU!\nÓ PÁTRIA DESEJADA, \nQUE ENCANTO É ESSE TEU;\nEXULTA, TU QUE GEMES \nNA DOR QUE SE DESFAZ;\nCOM DEUS, QUE TE REDIME, \nFELIZ SEMPRE SERÁS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (696, 'NA TERRA ABENÇOADA', 'NA TERRA ABENÇOADA', 'NA TERRA ABENÇOADA ESTOU;\nE NELA PEREGRINO SOU;\nDELÍCIAS ABUNDANTES SÃO;\nE SÓ DOS CÉUS SAUDADES DÃO.\n\nCORO\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.\n\nCOMIGO ANDA O SALVADOR;\nCONVERSA EM TONS DE SANTO AMOR,\nME GUIA SEMPRE PELA MÃO,\nE RUMO AO CÉU MEUS PASSOS VÃO.\n\nCORO\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.\n\nSENTIR A BRISA, OH! QUE PRAZER,\nDOCE PERFUME VEM TRAZER\nDAS FLORES QUE NÃO MURCHARÃO,\nDOS FRUTOS QUE SUPERNOS SÃO.\n\nCORO\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.\n\nNA DOCE ARAGEM CELESTIAL\nFLUTUA O CANTO ANGELICAL\nDA TRIUNFANTE MULTIDÃO\nQUE ENTOA A GRANDE REDENÇÃO.\n\nCORO\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.', 'NA TERRA ABENÇOADA ESTOU;\nE NELA PEREGRINO SOU;\nDELÍCIAS ABUNDANTES SÃO;\nE SÓ DOS CÉUS SAUDADES DÃO.\n\n<coro>\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.\n\nCOMIGO ANDA O SALVADOR;\nCONVERSA EM TONS DE SANTO AMOR,\nME GUIA SEMPRE PELA MÃO,\nE RUMO AO CÉU MEUS PASSOS VÃO.\n\n<coro>\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.\n\nSENTIR A BRISA, OH! QUE PRAZER,\nDOCE PERFUME VEM TRAZER\nDAS FLORES QUE NÃO MURCHARÃO,\nDOS FRUTOS QUE SUPERNOS SÃO.\n\n<coro>\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.\n\nNA DOCE ARAGEM CELESTIAL\nFLUTUA O CANTO ANGELICAL\nDA TRIUNFANTE MULTIDÃO\nQUE ENTOA A GRANDE REDENÇÃO.\n\n<coro>\nOH! BELA TERRA DE AMOR!\nDO ALTO MONTE ENCANTADOR\nOLHANDO, VEJO ALÉM DO MAR,\n(QUE BREVE HEI DE ATRAVESSAR) \nA PRAIA ÁUREA, ETERNAL,\nQUERIDO LAR CELESTIAL.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (697, 'OUVI O SALVADOR DIZER', 'OUVI O SALVADOR DIZER', 'OUVI O SALVADOR DIZER:\n''VEM DESCANSAR EM MIM\nE CONFIANTE RECEBER\nCONFORTO E PAZ SEM FIM''.\nFUI A JESUS E LHE ENTREGUEI\nMEU TRISTE CORAÇÃO;\nABRIGO E PAZ E GOZO ACHEI,\nACHEI CONSOLAÇÃO.\n\nOUVI O SALVADOR DIZER:\n''DE GRAÇA É O MEU AMOR.\nAS ÁGUAS VIVAS VEM BEBER;\nDA VIDA A FONTE SOU''.\nFUI A JESUS E ME PROSTREI,\nDA FONTE ENFIM BEBI;\nJAMAIS A SEDE SENTIREI,\nESTANDO SEMPRE ALI.\n\nOUVI O SALVADOR DIZER:\n''DO MUNDO EU SOU A LUZ;\nOH! VEM A MIM, POIS SENTIRÁS\nQUE TE AMO DESDE A CRUZ''.\nFUI A JESUS E NELE ACHEI\nO SOL QUE BRILHA EM MIM;\nE NESSA LUZ EU ANDAREI\nATÉ DA VIDA O FIM. \n\nFINAL: AMÉM.', 'OUVI O SALVADOR DIZER:\n''VEM DESCANSAR EM MIM\nE CONFIANTE RECEBER\nCONFORTO E PAZ SEM FIM''.\nFUI A JESUS E LHE ENTREGUEI\nMEU TRISTE CORAÇÃO;\nABRIGO E PAZ E GOZO ACHEI,\nACHEI CONSOLAÇÃO.\n\nOUVI O SALVADOR DIZER:\n''DE GRAÇA É O MEU AMOR.\nAS ÁGUAS VIVAS VEM BEBER;\nDA VIDA A FONTE SOU''.\nFUI A JESUS E ME PROSTREI,\nDA FONTE ENFIM BEBI;\nJAMAIS A SEDE SENTIREI,\nESTANDO SEMPRE ALI.\n\nOUVI O SALVADOR DIZER:\n''DO MUNDO EU SOU A LUZ;\nOH! VEM A MIM, POIS SENTIRÁS\nQUE TE AMO DESDE A CRUZ''.\nFUI A JESUS E NELE ACHEI\nO SOL QUE BRILHA EM MIM;\nE NESSA LUZ EU ANDAREI\nATÉ DA VIDA O FIM. \n<final>AMÉM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (698, 'TUA, Ó DEUS, É TODA A GRANDEZA', 'TUA, Ó DEUS, É TODA A GRANDEZA', 'TUA, Ó DEUS, É TODA A GRANDEZA,\nTUA, Ó DEUS, É TODA A GRANDEZA,\nTUA, Ó DEUS, É TODA A GRANDEZA,\nE O PODER, E A GLÓRIA, E A VITÓRIA,\nE OS LOUVORES. VITÓRIA E LOUVORES.\n\nTUA, Ó DEUS; TUA, Ó DEUS,\nÉ A GRANDEZA, E O PODER,\n(A GRANDEZA E O PODER),\nE A GLÓRIA, E A VITÓRIA, \nE OS LOUVORES ETERNOS;\n\nPOIS TUDO O QUE ESTÁ NO MAR, \nE ESTÁ NO CÉU E NA TERRA É TEU!\nTEU É O IMPÉRIO. \nTEU É O IMPÉRIO, Ó SENHOR!\nE TU ÉS ACIMA DE TODOS OS REIS, \nDE TODOS OS REIS, AMÉM ALELUIA!\n\nTUA, Ó DEUS; TUA, Ó DEUS,\nÉ A GRANDEZA, E O PODER,\n(A GRANDEZA E O PODER),\nE A GLÓRIA, E A VITÓRIA, \nE OS LOUVORES ETERNOS;', 'TUA, Ó DEUS, É TODA A GRANDEZA,\nTUA, Ó DEUS, É TODA A GRANDEZA,\nTUA, Ó DEUS, É TODA A GRANDEZA,\nE O PODER, E A GLÓRIA, E A VITÓRIA,\nE OS LOUVORES. VITÓRIA E LOUVORES.\n\nTUA, Ó DEUS; TUA, Ó DEUS,\nÉ A GRANDEZA, E O PODER,\n(A GRANDEZA E O PODER),\nE A GLÓRIA, E A VITÓRIA, \nE OS LOUVORES ETERNOS;\n\nPOIS TUDO O QUE ESTÁ NO MAR, \nE ESTÁ NO CÉU E NA TERRA É TEU!\nTEU É O IMPÉRIO. \nTEU É O IMPÉRIO, Ó SENHOR!\nE TU ÉS ACIMA DE TODOS OS REIS, \nDE TODOS OS REIS, AMÉM ALELUIA!\n\nTUA, Ó DEUS; TUA, Ó DEUS,\nÉ A GRANDEZA, E O PODER,\n(A GRANDEZA E O PODER),\nE A GLÓRIA, E A VITÓRIA, \nE OS LOUVORES ETERNOS;', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (699, 'QUE GRANDE REUNIÃO (JESUS DE NAZARÉ)', 'QUE GRANDE REUNIÃO (JESUS DE NAZARÉ)', 'QUE GRANDE REUNIÃO CONVOCADA ALI,\nDA COLINA SE ACHAVA AO PÉ.\nOLHANDO MELHOR ENTRE ELES \nVI A JESUS DE NAZARÉ.\nVI CEGO EM MOMENTOS TORNAR A VER,\nENTREVADO FICAR DE PÉ, \nE TODOS GOZAVAM REAL \nPRAZER EM JESUS DE NAZARÉ.\n\nCORO\nJESUS CRISTO, MEU MESTRE DIVINO,\nPRA SEMPRE POR TI VIVEREI.\nA VIDA SERÁ QUAL UM HINO\nEM TI, MEU AMADO REI.\n\nINDAGAM OS PRÍNCIPES ENTRE SI, \nTODOS QUEREM SABER \nQUEM É O HOMEM HUMILDE \nQUE ESTÁ ALI. É JESUS DE NAZARÉ.\nO MAR SE AQUIETA AO MANDO SEU,\nPODEROSO E GRANDIOSO ELE É, \nÉ O NOSSO PÃO QUE DESCEU DO CÉU, \nJESUS DE NAZARÉ.\n\nCORO\nJESUS CRISTO, MEU MESTRE DIVINO,\nPRA SEMPRE POR TI VIVEREI.\nA VIDA SERÁ QUAL UM HINO\nEM TI, MEU AMADO REI.\n\nSE GRANDES, QUAIS ONDAS, \nAS LUTAS SÃO, SE JÁ QUASE VACILA \nA FÉ, ACALMA A TORMENTA NO CORAÇÃO, \nJESUS DE NAZARÉ.\nA ÁGUA DA VIDA A TODOS \nDÁ AO CONTRITO ELE SALVARÁ!\nMEU DÚBIO CAMINHO EM SUA \nMÃO ESTÁ, JESUS DE NAZARÉ.\n\nCORO\nJESUS CRISTO, MEU MESTRE DIVINO,\nPRA SEMPRE POR TI VIVEREI.\nA VIDA SERÁ QUAL UM HINO\nEM TI, MEU AMADO REI.', 'QUE GRANDE REUNIÃO CONVOCADA ALI,\nDA COLINA SE ACHAVA AO PÉ.\nOLHANDO MELHOR ENTRE ELES \nVI A JESUS DE NAZARÉ.\nVI CEGO EM MOMENTOS TORNAR A VER,\nENTREVADO FICAR DE PÉ, \nE TODOS GOZAVAM REAL \nPRAZER EM JESUS DE NAZARÉ.\n\n<coro>\nJESUS CRISTO, MEU MESTRE DIVINO,\nPRA SEMPRE POR TI VIVEREI.\nA VIDA SERÁ QUAL UM HINO\nEM TI, MEU AMADO REI.\n\nINDAGAM OS PRÍNCIPES ENTRE SI, \nTODOS QUEREM SABER \nQUEM É O HOMEM HUMILDE \nQUE ESTÁ ALI. É JESUS DE NAZARÉ.\nO MAR SE AQUIETA AO MANDO SEU,\nPODEROSO E GRANDIOSO ELE É, \nÉ O NOSSO PÃO QUE DESCEU DO CÉU, \nJESUS DE NAZARÉ.\n\n<coro>\nJESUS CRISTO, MEU MESTRE DIVINO,\nPRA SEMPRE POR TI VIVEREI.\nA VIDA SERÁ QUAL UM HINO\nEM TI, MEU AMADO REI.\n\nSE GRANDES, QUAIS ONDAS, \nAS LUTAS SÃO, SE JÁ QUASE VACILA \nA FÉ, ACALMA A TORMENTA NO CORAÇÃO, \nJESUS DE NAZARÉ.\nA ÁGUA DA VIDA A TODOS \nDÁ AO CONTRITO ELE SALVARÁ!\nMEU DÚBIO CAMINHO EM SUA \nMÃO ESTÁ, JESUS DE NAZARÉ.\n\n<coro>\nJESUS CRISTO, MEU MESTRE DIVINO,\nPRA SEMPRE POR TI VIVEREI.\nA VIDA SERÁ QUAL UM HINO\nEM TI, MEU AMADO REI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (700, 'ESTEVÃO AVISTOU (EU TAMBÉM QUERO VER)', 'ESTEVÃO AVISTOU (EU TAMBÉM QUERO VER)', 'ESTEVÃO AVISTOU OS CÉUS ABERTOS:\nO FILHO DO DEUS PAI; VIU BEM DE PERTO, \nCORAL ANGELICAL\nCANTANDO AO REI DOS REIS,\nSALMODIANDO AO GRANDE DEUS!\n\nCORO\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n\nJOÃO TAMBÉM OLHOU OS CÉUS ABERTOS,\nA GLÓRIA DO SENHOR, SIM, MANIFESTOS:\nUMA CIDADE REAL, UM RIO DE CRISTAL!\nNUNCA, JAMAIS SE VIU BELEZAS MIL!\n\nCORO\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n\nELIAS CONTEMPLOU, NO FIRMAMENTO:\nCARRO DE FOGO QUE BRILHAVA AO VENTO; \nE PARA O CÉU HOMEM DE DEUS SUBIU \nROMPENDO AS NUVENS CELESTIAIS!\n\nCORO\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n\nINSTRUMENTOS\n\nCORO\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n\nFINAL: EU TAMBÉM QUERO VER!', 'ESTEVÃO AVISTOU OS CÉUS ABERTOS:\nO FILHO DO DEUS PAI; VIU BEM DE PERTO, \nCORAL ANGELICAL\nCANTANDO AO REI DOS REIS,\nSALMODIANDO AO GRANDE DEUS!\n\n<coro>\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n\nJOÃO TAMBÉM OLHOU OS CÉUS ABERTOS,\nA GLÓRIA DO SENHOR, SIM, MANIFESTOS:\nUMA CIDADE REAL, UM RIO DE CRISTAL!\nNUNCA, JAMAIS SE VIU BELEZAS MIL!\n\n<coro>\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n\nELIAS CONTEMPLOU, NO FIRMAMENTO:\nCARRO DE FOGO QUE BRILHAVA AO VENTO; \nE PARA O CÉU HOMEM DE DEUS SUBIU \nROMPENDO AS NUVENS CELESTIAIS!\n\n<coro>\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n<instrumentos>\n\n\n<coro>\nEU TAMBÉM QUERO VER A GLÓRIA DO SENHOR \nQUE PREPARADA ESTÁ PARA OS SANTOS ALI MORAREM! \nEU TAMBÉM QUERO VER (EU TAMBÉM QUERO VER) \nA GLÓRIA DO SENHOR!\n<final>EU TAMBÉM QUERO VER!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (701, 'AS TUAS MÃOS', 'AS TUAS MÃOS', 'AS TUAS MÃOS DIRIGEM MEU DESTINO\nOH! DEUS DE AMOR! FOLGO QUE SEJA ASSIM! \nTEUS SÃO OS MEUS PODERES, \nMINHA VIDA; EM TUDO, ETERNO PAI, \nDISPÕE DE MIM!\n\nMEUS DIAS SEJAM CURTOS OU COMPRIDOS, \nPASSADOS EM TRISTEZAS OU PRAZER, \nEM SOMBRA OU LUZ DE ACORDO COM TEU PLANO!\nE É TUDO BOM SE VEM DO TEU QUERER.\n\nAS TUAS MÃOS DIRIGEM MEU DESTINO,\nDANTES CRAVADAS NA SANGRENTA CRUZ.\nPOR MEUS PECADOS FORAM TRASPASSADAS\nBEM POSSO NELAS DESCANSAR, JESUS!\n\nNOS CÉUS ERGUIDAS SEMPRE INTERCEDENDO\nAS SANTAS MÃOS NÃO PEDIRÃO EM VÃO!\nAO SEU CUIDADO, EM PLENA CONFIANÇA,\nENTREGO A MINHA ETERNA SALVAÇÃO.\n\nAS TUAS MÃOS DIRIGEM MEU DESTINO;\nO ACASO, PARA MIM, NÃO HAVERÁ!\nO GRANDE PAI VIGIA O MEU CAMINHO,\nE SEM MOTIVO NÃO ME AFLIGIRÁ.\n\nTENHO NO SEU PODER CONSTANTE APOIO,\nFORTE É SEU BRAÇO, INSONE O SEU AMOR;\nE EM BREVE, ENTRANDO NA CIDADE ETERNA \nEU LOUVAREI MEU REI E SALVADOR!', 'AS TUAS MÃOS DIRIGEM MEU DESTINO\nOH! DEUS DE AMOR! FOLGO QUE SEJA ASSIM! \nTEUS SÃO OS MEUS PODERES, \nMINHA VIDA; EM TUDO, ETERNO PAI, \nDISPÕE DE MIM!\n\nMEUS DIAS SEJAM CURTOS OU COMPRIDOS, \nPASSADOS EM TRISTEZAS OU PRAZER, \nEM SOMBRA OU LUZ DE ACORDO COM TEU PLANO!\nE É TUDO BOM SE VEM DO TEU QUERER.\n\nAS TUAS MÃOS DIRIGEM MEU DESTINO,\nDANTES CRAVADAS NA SANGRENTA CRUZ.\nPOR MEUS PECADOS FORAM TRASPASSADAS\nBEM POSSO NELAS DESCANSAR, JESUS!\n\nNOS CÉUS ERGUIDAS SEMPRE INTERCEDENDO\nAS SANTAS MÃOS NÃO PEDIRÃO EM VÃO!\nAO SEU CUIDADO, EM PLENA CONFIANÇA,\nENTREGO A MINHA ETERNA SALVAÇÃO.\n\nAS TUAS MÃOS DIRIGEM MEU DESTINO;\nO ACASO, PARA MIM, NÃO HAVERÁ!\nO GRANDE PAI VIGIA O MEU CAMINHO,\nE SEM MOTIVO NÃO ME AFLIGIRÁ.\n\nTENHO NO SEU PODER CONSTANTE APOIO,\nFORTE É SEU BRAÇO, INSONE O SEU AMOR;\nE EM BREVE, ENTRANDO NA CIDADE ETERNA \nEU LOUVAREI MEU REI E SALVADOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (702, 'OS CÉUS EM BREVE SE ABRIRÃO', 'OS CÉUS EM BREVE SE ABRIRÃO', 'OS CÉUS EM BREVE SE ABRIRÃO E TODOS TE VERÃO, \nÓ FILHO DE DAVI; OS REIS VIRÃO A TI, DE JOELHOS ADORAR AQUELE QUE PRA SEMPRE IRÁ REINAR.\n\nENTÃO TODOS VERÃO QUEM ÉS,\nPROSTRADOS A TEUS PÉS ENTENDERÃO \nO AMOR, O VERDADEIRO AMOR QUE TE LEVOU, \nJESUS, A DAR-ME A TUA VIDA NAQUELA CRUZ.\n\nCORO\nNÓS TE SAUDAMOS;\nHOSANA AO FILHO DE DAVI!\nBENDITO AQUELE QUE VEM \nEM NOME DO SENHOR, \nHOSANA, HOSANA!\n\nOS CÉUS, DE GOZO, TREMERÃO, \nE TODA CRIAÇÃO SE ALEGRARÁ EM TI,\nÓ FILHO DE DAVI, POIS NA VIDA E PAZ\nAO NOSSO MUNDO ENFIM TU NOS TRARÁS.\n\nCORO\nNÓS TE SAUDAMOS;\nHOSANA AO FILHO DE DAVI!\nBENDITO AQUELE QUE VEM \nEM NOME DO SENHOR, \nHOSANA, HOSANA!\n\nFINAL: HOSANA!', 'OS CÉUS EM BREVE SE ABRIRÃO E TODOS TE VERÃO, \nÓ FILHO DE DAVI; OS REIS VIRÃO A TI, DE JOELHOS ADORAR AQUELE QUE PRA SEMPRE IRÁ REINAR.\n\nENTÃO TODOS VERÃO QUEM ÉS,\nPROSTRADOS A TEUS PÉS ENTENDERÃO \nO AMOR, O VERDADEIRO AMOR QUE TE LEVOU, \nJESUS, A DAR-ME A TUA VIDA NAQUELA CRUZ.\n\n<coro>\nNÓS TE SAUDAMOS;\nHOSANA AO FILHO DE DAVI!\nBENDITO AQUELE QUE VEM \nEM NOME DO SENHOR, \nHOSANA, HOSANA!\n\nOS CÉUS, DE GOZO, TREMERÃO, \nE TODA CRIAÇÃO SE ALEGRARÁ EM TI,\nÓ FILHO DE DAVI, POIS NA VIDA E PAZ\nAO NOSSO MUNDO ENFIM TU NOS TRARÁS.\n\n<coro>\nNÓS TE SAUDAMOS;\nHOSANA AO FILHO DE DAVI!\nBENDITO AQUELE QUE VEM \nEM NOME DO SENHOR, \nHOSANA, HOSANA!\n<final>HOSANA!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (703, 'SERÁ DE MANHÃ', 'SERÁ DE MANHÃ', 'SERÁ DE MANHÃ, NO COMEÇO DO DIA?\nSERÁ QUANDO A LUZ PELAS TREVAS PENETRA,\nQUE CRISTO HÁ DE VIR COM OS ANJOS DA GLÓRIA,\nRECEBER DESTE MUNDO OS SEUS?\n\nCORO\nOH! JESUS, SALVADOR, SENHOR!\nQUANDO VAMOS CANTAR:\nCRISTO VOLTA, ALELUIA, ALELUIA, AMÉM!\nALELUIA, AMÉM!\n\nSERÁ NA AURORA, SERÁ PELA TARDE?\nSIM, PODERÁ SER QUE AS TREVAS DA NOITE\nSE TORNEM NA LUZ DESSE BRILHO DE GLÓRIA,\nQUANDO CRISTO OS SEUS RECEBER.\n\nCORO\nOH! JESUS, SALVADOR, SENHOR!\nQUANDO VAMOS CANTAR:\nCRISTO VOLTA, ALELUIA, ALELUIA, AMÉM!\nALELUIA, AMÉM!\n\nOH! GOZO SEM FIM, QUANDO A MORTE VENCIDA,\nJESUS REVESTIR-NOS DE PERPÉTUA VIDA,\nE TODOS NÓS FORMOS MORAR LÁ NA GLÓRIA,\nNESSE LAR QUE JESUS PREPAROU!\n\nCORO\nOH! JESUS, SALVADOR, SENHOR!\nQUANDO VAMOS CANTAR:\nCRISTO VOLTA, ALELUIA, ALELUIA, AMÉM!\nALELUIA, AMÉM!', 'SERÁ DE MANHÃ, NO COMEÇO DO DIA?\nSERÁ QUANDO A LUZ PELAS TREVAS PENETRA,\nQUE CRISTO HÁ DE VIR COM OS ANJOS DA GLÓRIA,\nRECEBER DESTE MUNDO OS SEUS?\n\n<coro>\nOH! JESUS, SALVADOR, SENHOR!\nQUANDO VAMOS CANTAR:\nCRISTO VOLTA, ALELUIA, ALELUIA, AMÉM!\nALELUIA, AMÉM!\n\nSERÁ NA AURORA, SERÁ PELA TARDE?\nSIM, PODERÁ SER QUE AS TREVAS DA NOITE\nSE TORNEM NA LUZ DESSE BRILHO DE GLÓRIA,\nQUANDO CRISTO OS SEUS RECEBER.\n\n<coro>\nOH! JESUS, SALVADOR, SENHOR!\nQUANDO VAMOS CANTAR:\nCRISTO VOLTA, ALELUIA, ALELUIA, AMÉM!\nALELUIA, AMÉM!\n\nOH! GOZO SEM FIM, QUANDO A MORTE VENCIDA,\nJESUS REVESTIR-NOS DE PERPÉTUA VIDA,\nE TODOS NÓS FORMOS MORAR LÁ NA GLÓRIA,\nNESSE LAR QUE JESUS PREPAROU!\n\n<coro>\nOH! JESUS, SALVADOR, SENHOR!\nQUANDO VAMOS CANTAR:\nCRISTO VOLTA, ALELUIA, ALELUIA, AMÉM!\nALELUIA, AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (704, 'SENHOR, SE ESTIVESSES AQUI (LÁZARO)', 'SENHOR, SE ESTIVESSES AQUI (LÁZARO)', 'SENHOR, SE ESTIVESSES AQUI \nO MEU IRMÃO NÃO TERIA MORRIDO,\nFOI O QUE DISSE AQUELA MULHER, \nLANÇANDO-SE AOS PÉS DE JESUS\nQUE AO OUVIR O CHORO QUE HAVIA NAQUELE LUGAR, MOVEU-SE EM ESPÍRITO, \nJESUS CHOROU.\n\nCORO\nTIRAI A PEDRA DISSE JESUS \nE NÃO PODIAM COMPREENDER O\nQUE IRIA FAZER, ENTÃO A LÁZARO \nELE CHAMOU E O RESSUSCITOU,\nTODOS VIRAM A GLÓRIA DE DEUS.\nELE TROUXE A ESPERANÇA, \nELE TROUXE A VIDA,\nPOIS ELE É O AUTOR DA VIDA.\nINSTRUMENTOS\n\nSE ESTÁS COMO AQUELA MULHER,\nSE PARA O TEU PROBLEMA NÃO TEM SOLUÇÃO,\nCHORA AOS PÉS DE JESUS,\nE ELE ENXUGARÁ AS TUAS LÁGRIMAS.\nVERÁS A GLÓRIA DE DEUS.\n\nCORO (2X)\nTIRAI A PEDRA DISSE JESUS \nE NÃO PODIAM COMPREENDER O\nQUE IRIA FAZER, ENTÃO A LÁZARO \nELE CHAMOU E O RESSUSCITOU,\nTODOS VIRAM A GLÓRIA DE DEUS.\nELE TROUXE A ESPERANÇA, \nELE TROUXE A VIDA,\nPOIS ELE É O AUTOR DA VIDA.', 'SENHOR, SE ESTIVESSES AQUI \nO MEU IRMÃO NÃO TERIA MORRIDO,\nFOI O QUE DISSE AQUELA MULHER, \nLANÇANDO-SE AOS PÉS DE JESUS\nQUE AO OUVIR O CHORO QUE HAVIA NAQUELE LUGAR, MOVEU-SE EM ESPÍRITO, \nJESUS CHOROU.\n\n<coro>\nTIRAI A PEDRA DISSE JESUS \nE NÃO PODIAM COMPREENDER O\nQUE IRIA FAZER, ENTÃO A LÁZARO \nELE CHAMOU E O RESSUSCITOU,\nTODOS VIRAM A GLÓRIA DE DEUS.\nELE TROUXE A ESPERANÇA, \nELE TROUXE A VIDA,<bis>\nPOIS ELE É O AUTOR DA VIDA.<bis>\n<instrumentos><bis>\n<bis>\n\nSE ESTÁS COMO AQUELA MULHER,\nSE PARA O TEU PROBLEMA NÃO TEM SOLUÇÃO,\nCHORA AOS PÉS DE JESUS,\nE ELE ENXUGARÁ AS TUAS LÁGRIMAS.\nVERÁS A GLÓRIA DE DEUS.\n\n<coro tipo=''2X''>\nTIRAI A PEDRA DISSE JESUS \nE NÃO PODIAM COMPREENDER O\nQUE IRIA FAZER, ENTÃO A LÁZARO \nELE CHAMOU E O RESSUSCITOU,\nTODOS VIRAM A GLÓRIA DE DEUS.\nELE TROUXE A ESPERANÇA, <bis>\nELE TROUXE A VIDA,<bis>\nPOIS ELE É O AUTOR DA VIDA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (705, 'GRANDES SÃO, SENHOR, OS TEUS FEITOS (GRATIDÃO)', 'GRANDES SÃO, SENHOR, OS TEUS FEITOS (GRATIDÃO)', 'GRANDES SÃO, SENHOR, OS TEUS FEITOS!\nA TI DEVO TODO O MEU LOUVOR.\nO TEU NOME É PODEROSO,\nE A TUA GRAÇA É TUDO PARA MIM! (PARA MIM)\n\nTU, Ó DEUS, ÉS ONIPOTENTE!\nTUA MORADA É ETERNA, SENHOR\nMINHA VIDA SE ENCHE DE ALEGRIA,\nA MINH''ALMA TE ENGRANDECE POR TE SERVIR.\n\nA TI EU DEVO TODA HONRA \nE TODA GLÓRIA! (TODA GLÓRIA) \nNO TEU NOME ENCONTRO PAZ E VITÓRIA, \nMINHA VIDA É FRUTO DO TEU GRANDE AMOR, \nPOR ISSO DIGO QUE ÉS \nMEU REI E MEU SENHOR!\n\nINSTRUMENTOS\n\nFINAL: \nGRANDES SÃO SENHOR OS TEUS FEITOS!\n(GRANDES SÃO).', 'GRANDES SÃO, SENHOR, OS TEUS FEITOS!\nA TI DEVO TODO O MEU LOUVOR.\nO TEU NOME É PODEROSO,\nE A TUA GRAÇA É TUDO PARA MIM! (PARA MIM)\n\nTU, Ó DEUS, ÉS ONIPOTENTE!\nTUA MORADA É ETERNA, SENHOR\nMINHA VIDA SE ENCHE DE ALEGRIA,\nA MINH''ALMA TE ENGRANDECE POR TE SERVIR.\n\nA TI EU DEVO TODA HONRA <bis>\nE TODA GLÓRIA! (TODA GLÓRIA) <bis>\nNO TEU NOME ENCONTRO PAZ E VITÓRIA, <bis>\nMINHA VIDA É FRUTO DO TEU GRANDE AMOR, <bis>\nPOR ISSO DIGO QUE ÉS <bis>\nMEU REI E MEU SENHOR!<bis>\n<instrumentos>\n\n\n\n<final>GRANDES SÃO SENHOR OS TEUS FEITOS!\n(GRANDES SÃO).', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (706, 'DESTE MUNDO ESCRAVO FUI (GRANDES COISAS FEZ O SENHOR POR NÓS)', 'DESTE MUNDO ESCRAVO FUI (GRANDES COISAS FEZ O SENHOR POR NÓS)', 'DESTE MUNDO ESCRAVO FUI,\nPRESO EM ILUSÕES SEM FIM.\nE ME VIA A PERGUNTAR:\nQUANDO VIRÁ O SENHOR POR MIM?\nCOMO QUANDO EM CATIVEIRO\nO SENHOR TROUXE A SIÃO,\nO SEU POVO AMADO.\n\nFOI COMO UM SONHO,\nNOSSA BOCA SE ENCHEU DE RISO E CANTO. \nE DIZIA ENTRE AS NAÇÕES:\nGRANDES COISAS FEZ O SENHOR!\nGRANDES COISAS FEZ O SENHOR POR NÓS\nGRANDES COISAS FEZ O SENHOR POR NÓS\nJÁ PLANTEI AS MINHAS LÁGRIMAS, \nCOLHEREI OS FRUTOS DE JUSTIÇA. \n\nCOMO QUANDO EM CATIVEIRO,\nME TROUXE O SENHOR. FOI COMO UM SONHO, \nMINHA BOCA SE ENCHEU DE RISO E CANTO \nE DIREI ENTRE AS NAÇÕES:\nQUE GRANDES COISAS FEZ O SENHOR!\nGRANDES COISAS FEZ O SENHOR POR NÓS\nGRANDES COISAS FEZ O SENHOR POR NÓS\nVIVO AGORA A ESPERANÇA DE COM ELE\nUM DIA ME ENCONTRAR NO CÉU.\n\nFINAL: \nVIVO AGORA A ESPERANÇA DE COM ELE\nUM DIA ME ENCONTRAR NO CÉU, NO CÉU.', 'DESTE MUNDO ESCRAVO FUI,\nPRESO EM ILUSÕES SEM FIM.\nE ME VIA A PERGUNTAR:\nQUANDO VIRÁ O SENHOR POR MIM?\nCOMO QUANDO EM CATIVEIRO\nO SENHOR TROUXE A SIÃO,\nO SEU POVO AMADO.\n\nFOI COMO UM SONHO,\nNOSSA BOCA SE ENCHEU DE RISO E CANTO. \nE DIZIA ENTRE AS NAÇÕES:\nGRANDES COISAS FEZ O SENHOR!\nGRANDES COISAS FEZ O SENHOR POR NÓS\nGRANDES COISAS FEZ O SENHOR POR NÓS\nJÁ PLANTEI AS MINHAS LÁGRIMAS, <bis>\nCOLHEREI OS FRUTOS DE JUSTIÇA. <bis>\n\nCOMO QUANDO EM CATIVEIRO,\nME TROUXE O SENHOR. FOI COMO UM SONHO, \nMINHA BOCA SE ENCHEU DE RISO E CANTO \nE DIREI ENTRE AS NAÇÕES:\nQUE GRANDES COISAS FEZ O SENHOR!\nGRANDES COISAS FEZ O SENHOR POR NÓS\nGRANDES COISAS FEZ O SENHOR POR NÓS\nVIVO AGORA A ESPERANÇA DE COM ELE\nUM DIA ME ENCONTRAR NO CÉU.\n\n\n<final>VIVO AGORA A ESPERANÇA DE COM ELE\nUM DIA ME ENCONTRAR NO CÉU, NO CÉU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (707, 'EU CONFIO EM TI, SENHOR', 'EU CONFIO EM TI, SENHOR', 'EU CONFIO EM TI, SENHOR!\nMESMO QUANDO TUDO NÃO VAI BEM,\nE A ESPERANÇA FUGIR, EU OLHAREI SÓ PRA TI.\nACALMA O MEU CORAÇÃO, SEGURA MINHA MÃO\nE ME FAZ UM VENCEDOR, SIM, ME FAZ UM VENCEDOR.\n\nPORQUE NUNCA SE OUVIU, \nE NUNCA SE VIU UM DEUS ALÉM DE TI. \nE EU APRENDI A CONFIAR NO DEUS \nPROVEDOR QUE NÃO FALHARÁ.\nROCHA INABALÁVEL, MEU ABRIGO E BOM PASTOR. \nSOCORRO BEM PRESENTE, \nMESMO NA TRISTEZA E DOR.\nEU CONFIO EM TI, SENHOR! JESUS! (BIS)\n\nINSTRUMENTOS\n\nEU CONFIO EM TI, SENHOR!\nMEU CAMINHO PONHO EM TEU ALTAR.\nTUA VOZ EU QUERO OUVIR,\nTUA PRESENÇA, SIM, QUERO SENTIR.\nENSINA-ME A CAMINHAR E A TE HONRAR, \nSENHOR, E ME FAZ UM VENCEDOR,\nSIM, ME FAZ UM VENCEDOR.\n\nPORQUE NUNCA SE OUVIU, \nE NUNCA SE VIU UM DEUS ALÉM DE TI. \nE EU APRENDI A CONFIAR NO DEUS \nPROVEDOR QUE NÃO FALHARÁ.\nROCHA INABALÁVEL, MEU ABRIGO E BOM PASTOR. \nSOCORRO BEM PRESENTE, \nMESMO NA TRISTEZA E DOR.\nEU CONFIO EM TI, SENHOR! (BIS)\n\nACALMA O MEU CORAÇÃO, \nSEGURA MINHA MÃO E ME FAZ UM VENCEDOR,\nSIM, ME FAZ UM VENCEDOR.\n\nROCHA INABALÁVEL, MEU ABRIGO E BOM PASTOR. \nSOCORRO BEM PRESENTE, MESMO NA TRISTEZA E DOR. \nEU CONFIO EM TI, SENHOR! (2X)\nJESUS!\n\nFINAL: ABRIGO SEGURO, JESUS!', 'EU CONFIO EM TI, SENHOR!\nMESMO QUANDO TUDO NÃO VAI BEM,\nE A ESPERANÇA FUGIR, EU OLHAREI SÓ PRA TI.\nACALMA O MEU CORAÇÃO, SEGURA MINHA MÃO\nE ME FAZ UM VENCEDOR, SIM, ME FAZ UM VENCEDOR.\n\nPORQUE NUNCA SE OUVIU, \nE NUNCA SE VIU UM DEUS ALÉM DE TI. \nE EU APRENDI A CONFIAR NO DEUS \nPROVEDOR QUE NÃO FALHARÁ.\nROCHA INABALÁVEL, MEU ABRIGO E BOM PASTOR. \nSOCORRO BEM PRESENTE, \nMESMO NA TRISTEZA E DOR.\nEU CONFIO EM TI, SENHOR! JESUS! <bis>\n<instrumentos>\n\n\nEU CONFIO EM TI, SENHOR!\nMEU CAMINHO PONHO EM TEU ALTAR.\nTUA VOZ EU QUERO OUVIR,\nTUA PRESENÇA, SIM, QUERO SENTIR.\nENSINA-ME A CAMINHAR E A TE HONRAR, \nSENHOR, E ME FAZ UM VENCEDOR,\nSIM, ME FAZ UM VENCEDOR.\n\nPORQUE NUNCA SE OUVIU, \nE NUNCA SE VIU UM DEUS ALÉM DE TI. \nE EU APRENDI A CONFIAR NO DEUS \nPROVEDOR QUE NÃO FALHARÁ.\nROCHA INABALÁVEL, MEU ABRIGO E BOM PASTOR. \nSOCORRO BEM PRESENTE, \nMESMO NA TRISTEZA E DOR.\nEU CONFIO EM TI, SENHOR! <bis>\n\nACALMA O MEU CORAÇÃO, \nSEGURA MINHA MÃO E ME FAZ UM VENCEDOR,\nSIM, ME FAZ UM VENCEDOR.\n\nROCHA INABALÁVEL, MEU ABRIGO E BOM PASTOR. \nSOCORRO BEM PRESENTE, MESMO NA TRISTEZA E DOR. \nEU CONFIO EM TI, SENHOR! <bis tipo=''2''>\nJESUS!\n<final>ABRIGO SEGURO, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (708, 'OUVI NO CÉU (BODAS DO CORDEIRO)', 'OUVI NO CÉU (BODAS DO CORDEIRO)', 'OUVI NO CÉU A VOZ DE UMA MULTIDÃO\nE VI OS ANCIÃOS E OS SERES QUE SE PROSTRARAM \nEM ADORAÇÃO AO NOSSO DEUS.\nQUE NO TRONO ASSENTADO ESTÁ\nDIZENDO AMÉM, ALELUIA! \n\nALEGREMOS E DEMOS-LHE GLÓRIA, GLÓRIA\nPORQUE SÃO CHEGADAS AS BODAS DO CORDEIRO\nE SUA ESPOSA PRONTA ESTÁ REVESTIDA \nDE UM LINHO FINO QUE RESPLANDECE\nPORQUE O LINHO SÃO AS JUSTIÇAS DOS SANTOS.\n\nINSTRUMENTOS\n\nBEM AVENTURADOS SÃO AQUELES CONVIDADOS\nPORQUE DERAM TUDO O QUE TINHAM A JESUS\nO CORDEIRO, FILHO DE DEUS!\nQUE VIGIARAM E ORARAM E VENCERAM\nESTÃO CHEIOS DO ESPÍRITO \nLOUVANDO AO SENHOR.\n\nSÃO PALAVRAS DE DEUS.\n\nINSTRUMENTOS\n \nFINAL: \nSÃO PALAVRAS DE DEUS.', 'OUVI NO CÉU A VOZ DE UMA MULTIDÃO\nE VI OS ANCIÃOS E OS SERES QUE SE PROSTRARAM \nEM ADORAÇÃO AO NOSSO DEUS.\nQUE NO TRONO ASSENTADO ESTÁ\nDIZENDO AMÉM, ALELUIA! \n\nALEGREMOS E DEMOS-LHE GLÓRIA, GLÓRIA\nPORQUE SÃO CHEGADAS AS BODAS DO CORDEIRO\nE SUA ESPOSA PRONTA ESTÁ REVESTIDA \nDE UM LINHO FINO QUE RESPLANDECE\nPORQUE O LINHO SÃO AS JUSTIÇAS DOS SANTOS.\n<instrumentos>\n\n\nBEM AVENTURADOS SÃO AQUELES CONVIDADOS<bis>\nPORQUE DERAM TUDO O QUE TINHAM A JESUS<bis>\nO CORDEIRO, FILHO DE DEUS!<bis>\nQUE VIGIARAM E ORARAM E VENCERAM<bis>\nESTÃO CHEIOS DO ESPÍRITO <bis>\nLOUVANDO AO SENHOR.<bis>\n\nSÃO PALAVRAS DE DEUS.\n<instrumentos>\n<final>SÃO PALAVRAS DE DEUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (709, 'RESPLANDECE, Ó JERUSALÉM', 'RESPLANDECE, Ó JERUSALÉM', 'RESPLANDECE Ó JERUSALÉM!\nPORQUE NASCE SOBRE TI A TUA LUZ.\nJERUSALÉM, ÉS ILUMINADA PELA GLÓRIA \nDO SENHOR, AS TUAS RUAS SÃO DE OURO, \nÓ QUANTO ALMEJO NELAS ANDAR.\n\nJERUSALÉM, Ó QUANTO ALMEJO\nESTAR AO LADO DO MEU SENHOR\nPRA SEMPRE O ADORAR.\nJERUSALÉM, POR SUAS PORTAS\nVOU ENTRAR E EM CORO CELESTIAL,\nA JESUS ADORAR.\n\nINSTRUMENTOS\n\nDENTRO DOS TEUS MUROS,\n(Ó JERUSALÉM) \nASSENTA-SE NO TRONO\nÀ DESTRA DE DEUS PAI,\nO NOSSO REI, O CORDEIRO \nQUE VENCEU.\n\nJERUSALÉM, QUERO CONTEMPLAR,\nA TUA GLÓRIA COM A GLÓRIA DO\nSENHOR, QUERO HABITAR DENTRO\nDOS TEUS MUROS.\n\nFINAL:\nÓ JERUSALÉM. (JERUSALÉM)\n\n3X', 'RESPLANDECE Ó JERUSALÉM!\nPORQUE NASCE SOBRE TI A TUA LUZ.\nJERUSALÉM, ÉS ILUMINADA PELA GLÓRIA \nDO SENHOR, AS TUAS RUAS SÃO DE OURO, \nÓ QUANTO ALMEJO NELAS ANDAR.\n\nJERUSALÉM, Ó QUANTO ALMEJO\nESTAR AO LADO DO MEU SENHOR\nPRA SEMPRE O ADORAR.\nJERUSALÉM, POR SUAS PORTAS\nVOU ENTRAR E EM CORO CELESTIAL,\nA JESUS ADORAR.\n<instrumentos>\n\n\nDENTRO DOS TEUS MUROS,\n(Ó JERUSALÉM) \nASSENTA-SE NO TRONO\nÀ DESTRA DE DEUS PAI,\nO NOSSO REI, O CORDEIRO \nQUE VENCEU.\n\nJERUSALÉM, QUERO CONTEMPLAR,\nA TUA GLÓRIA COM A GLÓRIA DO\nSENHOR, QUERO HABITAR DENTRO\nDOS TEUS MUROS.\n<final>Ó JERUSALÉM. (JERUSALÉM)\n\n<bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (710, 'O MEU VIVER É CRISTO', 'O MEU VIVER É CRISTO', 'O MEU VIVER É CRISTO, MEU SALVADOR,\nPOIS SE ENTREGOU PARA A VIDA ETERNA ME DAR.\nHOJE VENHO A TI PARA EXPRESSAR.\n\nCORO\nTODA GRATIDÃO A TI JESUS,\nPORQUE TU ÉS MARAVILHOSO.\nPRA SEMPRE CANTAREI A TI,\nMEU REI, POIS TU ME FIZESTE BEM.\n\nMEU VERDADEIRO AMIGO SEMPRE FIEL.\nESCONDERIJO MEU, PARA SEMPRE EMANUEL.\nÉS O MEU SENHOR, A RAZÃO DO MEU VIVER!\nHOJE VENHO A TI PARA EXPRESSAR.\n\nCORO (2X)\nTODA GRATIDÃO A TI JESUS,\nPORQUE TU ÉS MARAVILHOSO.\nPRA SEMPRE CANTAREI A TI,\nMEU REI, POIS TU ME FIZESTE BEM.\n\nFINAL: \nPOIS TU ME FIZESTE BEM.', 'O MEU VIVER É CRISTO, MEU SALVADOR,\nPOIS SE ENTREGOU PARA A VIDA ETERNA ME DAR.\nHOJE VENHO A TI PARA EXPRESSAR.\n\n<coro>\nTODA GRATIDÃO A TI JESUS,\nPORQUE TU ÉS MARAVILHOSO.\nPRA SEMPRE CANTAREI A TI,\nMEU REI, POIS TU ME FIZESTE BEM.\n\nMEU VERDADEIRO AMIGO SEMPRE FIEL.\nESCONDERIJO MEU, PARA SEMPRE EMANUEL.\nÉS O MEU SENHOR, A RAZÃO DO MEU VIVER!\nHOJE VENHO A TI PARA EXPRESSAR.\n\n<coro tipo=''2X''>\nTODA GRATIDÃO A TI JESUS,\nPORQUE TU ÉS MARAVILHOSO.\nPRA SEMPRE CANTAREI A TI,\nMEU REI, POIS TU ME FIZESTE BEM.\n<final>POIS TU ME FIZESTE BEM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (711, 'TUA GRAÇA ME BASTA, Ó SENHOR', 'TUA GRAÇA ME BASTA, Ó SENHOR', 'TUA GRAÇA ME BASTA, Ó SENHOR,\nESTA GRAÇA QUE UM DIA ME ALCANÇOU.\nTEU ESPÍRITO ALEGRA O MEU CORAÇÃO,\nME FAZENDO VIVER A REVELAÇÃO,\nRENOVANDO A SALVAÇÃO EM MINHA VIDA.\n\nCORO\nDERRAMA SOBRE NÓS A TUA GRAÇA \n(DERRAMA TUA GRAÇA),\nDERRAMA SOBRE NÓS O TEU PODER,\nPREPARANDO NOSSOS CORAÇÕES,\nPARA O GRANDE DIA DO SENHOR,\nMARANATA! ORA VEM, SENHOR JESUS.\n\nTUA GRAÇA NOS LIVRA DO MUNDO,\n(TUA GRAÇA NOS LIVRA DO MUNDO)\nTRAZENDO VIDA NOVA A CADA DIA.\nTEU ESPÍRITO HABITA ENTRE NÓS,\nE NÓS TEMOS A CERTEZA DA SALVAÇÃO,\nANSIANDO EM BREVE ESTAR NA TUA GLÓRIA.\n\nCORO (2X)\nDERRAMA SOBRE NÓS A TUA GRAÇA \n(DERRAMA TUA GRAÇA),\nDERRAMA SOBRE NÓS O TEU PODER,\nPREPARANDO NOSSOS CORAÇÕES,\nPARA O GRANDE DIA DO SENHOR,\nMARANATA! ORA VEM, SENHOR JESUS.\n\nFINAL:\nPREPARANDO NOSSOS CORAÇÕES,\nPARA O GRANDE DIA DO SENHOR,\nMARANATA! ORA VEM, SENHOR JESUS!\n(MARANATA! ORA VEM)\nVEM, JESUS!', 'TUA GRAÇA ME BASTA, Ó SENHOR,\nESTA GRAÇA QUE UM DIA ME ALCANÇOU.\nTEU ESPÍRITO ALEGRA O MEU CORAÇÃO,\nME FAZENDO VIVER A REVELAÇÃO,\nRENOVANDO A SALVAÇÃO EM MINHA VIDA.\n\n<coro>\nDERRAMA SOBRE NÓS A TUA GRAÇA \n(DERRAMA TUA GRAÇA),\nDERRAMA SOBRE NÓS O TEU PODER,\nPREPARANDO NOSSOS CORAÇÕES,\nPARA O GRANDE DIA DO SENHOR,\nMARANATA! ORA VEM, SENHOR JESUS.\n\nTUA GRAÇA NOS LIVRA DO MUNDO,\n(TUA GRAÇA NOS LIVRA DO MUNDO)\nTRAZENDO VIDA NOVA A CADA DIA.\nTEU ESPÍRITO HABITA ENTRE NÓS,\nE NÓS TEMOS A CERTEZA DA SALVAÇÃO,\nANSIANDO EM BREVE ESTAR NA TUA GLÓRIA.\n\n<coro tipo=''2X''>\nDERRAMA SOBRE NÓS A TUA GRAÇA \n(DERRAMA TUA GRAÇA),\nDERRAMA SOBRE NÓS O TEU PODER,\nPREPARANDO NOSSOS CORAÇÕES,\nPARA O GRANDE DIA DO SENHOR,\nMARANATA! ORA VEM, SENHOR JESUS.\n\n\n<final>PREPARANDO NOSSOS CORAÇÕES,\nPARA O GRANDE DIA DO SENHOR,\nMARANATA! ORA VEM, SENHOR JESUS!\n(MARANATA! ORA VEM)\nVEM, JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (712, 'AO FINDAR O LABOR DESTA VIDA (A ÚLTIMA HORA)', 'AO FINDAR O LABOR DESTA VIDA (A ÚLTIMA HORA)', 'AO FINDAR O LABOR DESTA VIDA,\nQUANDO A MORTE A TEU LADO CHEGAR,\nQUE DESTINO HÁ DE TER A TUA ALMA?\nQUAL SERÁ NO FUTURO TEU LAR?\n\nCORO\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.\n\nTU PROCURAS A PAZ NESTE MUNDO,\nEM PRAZERES QUE PASSAM EM VÃO,\nMAS NA ÚLTIMA HORA DA VIDA,\nELES NUNCA TE SATISFARÃO.\n\nCORO\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.\n\nCOM TUA ALMA MANCHADA NÃO PODES\nNUNCA VER O SEMBLANTE DE DEUS;\nSÓ OS CRENTES COM CORAÇÃO LIMPO\nPODERÃO TER O GOZO DOS CÉUS.\n\nCORO\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.\n\nSE TU QUERES DEIXAR TEUS PECADOS,\nENTREGAR TUA VIDA A JESUS,\nTU TERÁS, SIM, NA ÚLTIMA HORA\nUM CAMINHO BRILHANTE DE LUZ.\n\nCORO\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.', 'AO FINDAR O LABOR DESTA VIDA,\nQUANDO A MORTE A TEU LADO CHEGAR,\nQUE DESTINO HÁ DE TER A TUA ALMA?\nQUAL SERÁ NO FUTURO TEU LAR?\n\n<coro>\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.\n\nTU PROCURAS A PAZ NESTE MUNDO,\nEM PRAZERES QUE PASSAM EM VÃO,\nMAS NA ÚLTIMA HORA DA VIDA,\nELES NUNCA TE SATISFARÃO.\n\n<coro>\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.\n\nCOM TUA ALMA MANCHADA NÃO PODES\nNUNCA VER O SEMBLANTE DE DEUS;\nSÓ OS CRENTES COM CORAÇÃO LIMPO\nPODERÃO TER O GOZO DOS CÉUS.\n\n<coro>\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.\n\nSE TU QUERES DEIXAR TEUS PECADOS,\nENTREGAR TUA VIDA A JESUS,\nTU TERÁS, SIM, NA ÚLTIMA HORA\nUM CAMINHO BRILHANTE DE LUZ.\n\n<coro>\nMEU AMIGO, HOJE TU TENS A ESCOLHA:\nVIDA OU MORTE QUAL VAIS ACEITAR?\nAMANHÃ PODE SER MUITO TARDE;\nHOJE CRISTO TE QUER LIBERTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (713, 'CAREÇO DE JESUS!', 'CAREÇO DE JESUS!', 'CAREÇO DE JESUS!\nSEMPRE DE TI, SENHOR!\nSOMENTE A TUA VOZ\nTEM PARA MIM VALOR!\n\nCORO\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!\n\nCAREÇO DE JESUS!\nUNIDO A TI, SENHOR,\nPECADO E TENTAÇÃO\nPERDEM O SEU VIGOR.\n\nCORO\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!\n\nCAREÇO DE JESUS!\nREGE MEU CORAÇÃO!\nENSINA-ME A VIVER\nEM SANTA RETIDÃO!\n\nCORO\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!\n\nCAREÇO DE JESUS!\nNAS TREVAS E NA LUZ!\nSEM TI A VIDA É VÃ;\nSOU POBRE SEM JESUS.\n\nCORO\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!', 'CAREÇO DE JESUS!\nSEMPRE DE TI, SENHOR!\nSOMENTE A TUA VOZ\nTEM PARA MIM VALOR!\n\n<coro>\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!\n\nCAREÇO DE JESUS!\nUNIDO A TI, SENHOR,\nPECADO E TENTAÇÃO\nPERDEM O SEU VIGOR.\n\n<coro>\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!\n\nCAREÇO DE JESUS!\nREGE MEU CORAÇÃO!\nENSINA-ME A VIVER\nEM SANTA RETIDÃO!\n\n<coro>\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!\n\nCAREÇO DE JESUS!\nNAS TREVAS E NA LUZ!\nSEM TI A VIDA É VÃ;\nSOU POBRE SEM JESUS.\n\n<coro>\nDE TI, SENHOR, CAREÇO,\nSEMPRE DE TI CAREÇO!\nOH! DÁ-ME A TUA BÊNÇÃO,\nASPIRO A TI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (714, 'COM TUA MÃO SEGURA BEM A MINHA (AMPARO DIVINO)', 'COM TUA MÃO SEGURA BEM A MINHA (AMPARO DIVINO)', 'COM TUA MÃO SEGURA BEM A MINHA,\nPOIS EU TÃO FRÁGIL SOU, Ó SALVADOR,\nQUE NÃO ME ATREVO A DAR JAMAIS UM PASSO\nSEM TEU AMPARO, CRISTO, MEU SENHOR!\n\nINSTRUMENTOS\n\nCOM TUA MÃO SEGURA BEM A MINHA,\nE PELO MUNDO, ALEGRE, SEGUIREI.\nMESMO ONDE AS SOMBRAS CAEM MAIS ESCURAS,\nTEU ROSTO VENDO, NADA TEMEREI.\n\nINSTRUMENTOS\n\nQUANDO EU CHEGAR À BEIRA DESSE RIO\nQUE TU, POR MIM, QUISESTE ATRAVESSAR,\nCOM TUA MÃO SEGURA BEM A MINHA,\nE SOBRE A MORTE EU HEI DE TRIUNFAR.\n\nINSTRUMENTOS\n\nAO REGRESSARES, LÁ DOS CÉUS DESCENDO,\nA MINHA MÃO SEGURA BEM, SENHOR,\nPOIS, MEU JESUS, EU QUERO ENTRAR CONTIGO\nLÁ ONDE EU GOZE O TEU ETERNO AMOR.', 'COM TUA MÃO SEGURA BEM A MINHA,\nPOIS EU TÃO FRÁGIL SOU, Ó SALVADOR,\nQUE NÃO ME ATREVO A DAR JAMAIS UM PASSO\nSEM TEU AMPARO, CRISTO, MEU SENHOR!\n<instrumentos>\n\n\nCOM TUA MÃO SEGURA BEM A MINHA,\nE PELO MUNDO, ALEGRE, SEGUIREI.\nMESMO ONDE AS SOMBRAS CAEM MAIS ESCURAS,\nTEU ROSTO VENDO, NADA TEMEREI.\n<instrumentos>\n\n\nQUANDO EU CHEGAR À BEIRA DESSE RIO\nQUE TU, POR MIM, QUISESTE ATRAVESSAR,\nCOM TUA MÃO SEGURA BEM A MINHA,\nE SOBRE A MORTE EU HEI DE TRIUNFAR.\n<instrumentos>\n\n\nAO REGRESSARES, LÁ DOS CÉUS DESCENDO,\nA MINHA MÃO SEGURA BEM, SENHOR,\nPOIS, MEU JESUS, EU QUERO ENTRAR CONTIGO\nLÁ ONDE EU GOZE O TEU ETERNO AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (715, 'DEUS VOS GUARDE PELO SEU PODER', 'DEUS VOS GUARDE PELO SEU PODER', 'DEUS VOS GUARDE PELO SEU PODER,\nSEMPRE ESTEJA AO VOSSO LADO;\nVOS DISPENSE O SEU CUIDADO,\nDEUS VOS GUARDE PELO SEU PODER.\n\nCORO\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.\n\nDEUS VOS GUARDE BEM NO SEU AMOR,\nCONSOLADOS E CONTENTES;\nACHEGADOS PARA OS CRENTES,\nDEUS VOS GUARDE BEM NO SEU AMOR.\n\nCORO\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.\n\nDEUS VOS GUARDE DO PODER DO MAL,\nDA RUÍNA, DO PECADO;\nDOS MOTINS DE QUALQUER LADO,\nDEUS VOS GUARDE DO PODER DO MAL,\n\nCORO\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.\n\nDEUS VOS GUARDE PARA SEU LOUVOR,\nPARA O SEU PRESENTE GOZO;\nSEU SERVIÇO GLORIOSO,\nDEUS VOS GUARDE PARA SEU LOUVOR.\n\nCORO\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.', 'DEUS VOS GUARDE PELO SEU PODER,\nSEMPRE ESTEJA AO VOSSO LADO;\nVOS DISPENSE O SEU CUIDADO,\nDEUS VOS GUARDE PELO SEU PODER.\n\n<coro>\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.\n\nDEUS VOS GUARDE BEM NO SEU AMOR,\nCONSOLADOS E CONTENTES;\nACHEGADOS PARA OS CRENTES,\nDEUS VOS GUARDE BEM NO SEU AMOR.\n\n<coro>\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.\n\nDEUS VOS GUARDE DO PODER DO MAL,\nDA RUÍNA, DO PECADO;\nDOS MOTINS DE QUALQUER LADO,\nDEUS VOS GUARDE DO PODER DO MAL,\n\n<coro>\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.\n\nDEUS VOS GUARDE PARA SEU LOUVOR,\nPARA O SEU PRESENTE GOZO;\nSEU SERVIÇO GLORIOSO,\nDEUS VOS GUARDE PARA SEU LOUVOR.\n\n<coro>\nPELO SEU PODER E NO SEU AMOR,\nTÉ NOS ENCONTRARMOS COM JESUS;\nPELO SEU PODER E NO SEU AMOR,\nOH! QUE DEUS VOS GUARDE EM SUA LUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (716, 'ENQUANTO, Ó SALVADOR, TEU LIVRO LER', 'ENQUANTO, Ó SALVADOR, TEU LIVRO LER', 'ENQUANTO, Ó SALVADOR, TEU LIVRO LER,\nMEUS OLHOS VÊM ABRIR, TE QUERO VER;\nDA MERA LETRA ALÉM, A TI, SENHOR,\nEU BUSCO A TI, JESUS, MEU REDENTOR.\n\nÀ BEIRA MAR, JESUS, PARTISTE O PÃO,\nSATISFAZENDO ALI A MULTIDÃO;\nDA VIDA O PÃO ÉS TU; VEM, POIS, ASSIM,\nSATISFAZER, SENHOR, A MIM, A MIM!', 'ENQUANTO, Ó SALVADOR, TEU LIVRO LER,\nMEUS OLHOS VÊM ABRIR, TE QUERO VER;\nDA MERA LETRA ALÉM, A TI, SENHOR,\nEU BUSCO A TI, JESUS, MEU REDENTOR.\n\nÀ BEIRA MAR, JESUS, PARTISTE O PÃO,\nSATISFAZENDO ALI A MULTIDÃO;\nDA VIDA O PÃO ÉS TU; VEM, POIS, ASSIM,\nSATISFAZER, SENHOR, A MIM, A MIM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (717, 'A TERRA SEMEAMOS', 'A TERRA SEMEAMOS', 'A TERRA SEMEAMOS \nA FIM DE NOS DAR PÃO,\nMAS DEUS É QUEM A NUTRE\nCOM BENFAZEJA MÃO.\nÉ DEUS QUEM MANDA O FRIO,\nA CHUVA E O BOM CALOR\nE FAZ SURGIR DA TERRA \nO FRUTO APÓS A FLOR.\n\nCORO\nDE TODO BEM A FONTE\nÉ NOSSO BOM SENHOR!\nLOUVAI A DEUS, LOUVAI A DEUS\nPOR TODO O SEU AMOR!\n\nO CRIADOR DE TUDO, \nQUE PERTO OU LONGE ESTÁ\nCOLORE A FLOR SILVESTRE\nE À ESTRELA O BRILHO DÁ.\nOS VENTOS LHE OBEDECEM,\nO BRAVO MAR TAMBÉM;\nAS FRÁGEIS AVEZINHAS \nO SEU CUIDADO TÊM!\n\nCORO\nDE TODO BEM A FONTE\nÉ NOSSO BOM SENHOR!\nLOUVAI A DEUS, LOUVAI A DEUS\nPOR TODO O SEU AMOR!\n\nINSTRTUMENTOS\n\nA NÓS, PORÉM, SEUS FILHOS, \nREVELA MAIS AMOR;\nO FILHO ETERNO DEU-NOS,\nJESUS, O SALVADOR,\nA NÓS FAZENDO HERDEIROS\nDE TUDO QUANTO TEM,\nNA REDENÇÃO PERFEITA \nQUE DELE NOS PROVÉM.\n\nCORO\nDE TODO BEM A FONTE\nÉ NOSSO BOM SENHOR!\nLOUVAI A DEUS, LOUVAI A DEUS\nPOR TODO O SEU AMOR!', 'A TERRA SEMEAMOS \nA FIM DE NOS DAR PÃO,\nMAS DEUS É QUEM A NUTRE\nCOM BENFAZEJA MÃO.\nÉ DEUS QUEM MANDA O FRIO,\nA CHUVA E O BOM CALOR\nE FAZ SURGIR DA TERRA \nO FRUTO APÓS A FLOR.\n\n<coro>\nDE TODO BEM A FONTE\nÉ NOSSO BOM SENHOR!\nLOUVAI A DEUS, LOUVAI A DEUS\nPOR TODO O SEU AMOR!\n\nO CRIADOR DE TUDO, \nQUE PERTO OU LONGE ESTÁ\nCOLORE A FLOR SILVESTRE\nE À ESTRELA O BRILHO DÁ.\nOS VENTOS LHE OBEDECEM,\nO BRAVO MAR TAMBÉM;\nAS FRÁGEIS AVEZINHAS \nO SEU CUIDADO TÊM!\n\n<coro>\nDE TODO BEM A FONTE\nÉ NOSSO BOM SENHOR!\nLOUVAI A DEUS, LOUVAI A DEUS\nPOR TODO O SEU AMOR!\n\nINSTRTUMENTOS\n\nA NÓS, PORÉM, SEUS FILHOS, \nREVELA MAIS AMOR;\nO FILHO ETERNO DEU-NOS,\nJESUS, O SALVADOR,\nA NÓS FAZENDO HERDEIROS\nDE TUDO QUANTO TEM,\nNA REDENÇÃO PERFEITA \nQUE DELE NOS PROVÉM.\n\n<coro>\nDE TODO BEM A FONTE\nÉ NOSSO BOM SENHOR!\nLOUVAI A DEUS, LOUVAI A DEUS\nPOR TODO O SEU AMOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (718, 'GUIA, Ó CRISTO, A MINHA NAU', 'GUIA, Ó CRISTO, A MINHA NAU', 'GUIA, Ó CRISTO, A MINHA NAU\nSOBRE O REVOLTOSO MAR.\nTÃO ENFURECIDO E MAU;\nQUER FAZÊ-LA NAUFRAGAR\nVEM JESUS, Ó VEM GUIAR\nMINHA NAU VEM PILOTAR.\n\nSE, NO PORTO QUANDO ENTRAR,\nMAIS O MAR SE ENFURECER,\nQUE ME POSSA DELEITAR\nEM OUVIR JESUS DIZER:\n''ENTRA POBRE VIAJOR\nNO DESCANSO DO SENHOR!''', 'GUIA, Ó CRISTO, A MINHA NAU\nSOBRE O REVOLTOSO MAR.\nTÃO ENFURECIDO E MAU;\nQUER FAZÊ-LA NAUFRAGAR\nVEM JESUS, Ó VEM GUIAR\nMINHA NAU VEM PILOTAR.\n\nSE, NO PORTO QUANDO ENTRAR,\nMAIS O MAR SE ENFURECER,\nQUE ME POSSA DELEITAR\nEM OUVIR JESUS DIZER:\n''ENTRA POBRE VIAJOR\nNO DESCANSO DO SENHOR!''', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (719, 'AVANTE, AVANTE, Ó CRENTES', 'AVANTE, AVANTE, Ó CRENTES', 'AVANTE, AVANTE, Ó CRENTES,\nSOLDADOS DE JESUS!\nERGUEI SEU ESTANDARTE,\nLUTAI POR SUA CRUZ!\nE CONTRA OS INIMIGOS,\nEM GRANDES MULTIDÕES\nO EXCELSO COMANDANTE\nDIRIGE OS BATALHÕES.\n\nAVANTE, AVANTE, Ó CRENTES,\nPOR CRISTO PELEJAI!\nVESTI SUA ARMADURA,\nEM SEU PODER MARCHAI!\nNO POSTO SEMPRE ACHADOS,\nVELANDO EM ORAÇÃO,\nEM MEIO AOS PERIGOS\nSEGUINDO O CAPITÃO!\n\nINSTRTUMENTOS\n\nAVANTE, AVANTE, Ó CRENTES,\nA PASSO TRIUNFAL!\nAPÓS COMBATE HORRENDO;\nVIRÁ A PAZ FINAL!\nENTÃO, ETERNAMENTE,\nSERÁ O VENCEDOR,\nNO CÉU GLORIFICADO\nCOM CRISTO, O SALVADOR!', 'AVANTE, AVANTE, Ó CRENTES,\nSOLDADOS DE JESUS!\nERGUEI SEU ESTANDARTE,\nLUTAI POR SUA CRUZ!\nE CONTRA OS INIMIGOS,\nEM GRANDES MULTIDÕES\nO EXCELSO COMANDANTE\nDIRIGE OS BATALHÕES.\n\nAVANTE, AVANTE, Ó CRENTES,\nPOR CRISTO PELEJAI!\nVESTI SUA ARMADURA,\nEM SEU PODER MARCHAI!\nNO POSTO SEMPRE ACHADOS,\nVELANDO EM ORAÇÃO,\nEM MEIO AOS PERIGOS\nSEGUINDO O CAPITÃO!\n\nINSTRTUMENTOS\n\nAVANTE, AVANTE, Ó CRENTES,\nA PASSO TRIUNFAL!\nAPÓS COMBATE HORRENDO;\nVIRÁ A PAZ FINAL!\nENTÃO, ETERNAMENTE,\nSERÁ O VENCEDOR,\nNO CÉU GLORIFICADO\nCOM CRISTO, O SALVADOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (720, 'AS GRUTAS, AS ROCHAS IMENSAS (UM HINO AO SENHOR)', 'AS GRUTAS, AS ROCHAS IMENSAS (UM HINO AO SENHOR)', 'AS GRUTAS, AS ROCHAS IMENSAS,\nDOS MUNDOS O GRANDE ESPLENDOR,\nPROCLAMAM, BEM ALTO, CONSTANTES,\nUM HINO AO TEU NOME, SENHOR!\n\nCORO\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n\nNOS CÉU, AS ESTRELAS BRILHANTES,\nDOS MARES O GRANDE FRAGOR,\nE AS BRISAS ENTOAM, RIDENTES,\nUM HINO AO TEU NOME, SENHOR!\n\nCORO\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n\nAS AVES ALEGRES NA MATA,\nPOR ENTRE AS RAMAGENS EM FLOR,\nEXULTAM EM CORO, CANTANDO\nUM HINO AO TEU NOME, SENHOR!\n\nCORO\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n\nINSTRUMENTOS\n\nE TU, PECADOR, QUE VAGUEIAS,\nQUE FAZES AO TEU CRIADOR?\nNÃO ACHAS MOMENTO EM QUE CANTES\nUM HINO DE GLÓRIA AO SENHOR?\n\nCORO\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n\nFINAL: AMÉM!', 'AS GRUTAS, AS ROCHAS IMENSAS,\nDOS MUNDOS O GRANDE ESPLENDOR,\nPROCLAMAM, BEM ALTO, CONSTANTES,\nUM HINO AO TEU NOME, SENHOR!\n\n<coro>\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n\nNOS CÉU, AS ESTRELAS BRILHANTES,\nDOS MARES O GRANDE FRAGOR,\nE AS BRISAS ENTOAM, RIDENTES,\nUM HINO AO TEU NOME, SENHOR!\n\n<coro>\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n\nAS AVES ALEGRES NA MATA,\nPOR ENTRE AS RAMAGENS EM FLOR,\nEXULTAM EM CORO, CANTANDO\nUM HINO AO TEU NOME, SENHOR!\n\n<coro>\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n<instrumentos>\n\n\nE TU, PECADOR, QUE VAGUEIAS,\nQUE FAZES AO TEU CRIADOR?\nNÃO ACHAS MOMENTO EM QUE CANTES\nUM HINO DE GLÓRIA AO SENHOR?\n\n<coro>\nNOS CÉUS E NO MAR, E NA TERRA,\nNOS BOSQUES, NOS PRADOS EM FLOR,\nNO FRAGOSO ALCANTIL, \nNA AMPLITUDE CELESTE,\nUM HINO RESSOA AO SENHOR.\n<final>AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (721, 'PROCLAMAI A TODO O MUNDO QUE O SENHOR É REI', 'PROCLAMAI A TODO O MUNDO QUE O SENHOR É REI', 'CORO\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!\n\nPROCLAMAI COMO ELE SE CHAMA\nO SALVADOR JESUS,\nCOMO ELE POR NÓS MORREU\nNA ENSANGUENTADA CRUZ;\nCOMO ELE, O CORDEIRO, \nSOBRE O TRONO ESTÁ,\nO DEUS DE TODA A GRAÇA\nQUE MORREU EM MEU LUGAR.\n\nCORO\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!\n\nPROCLAMAI QUE REINA EM GRAÇA\nNOSSO SALVADOR!\nQUE POR CETRO DE SEU REINO\nELE TEM O AMOR!\nANUNCIAI AOS TRISTES QUE ELE VIVO ESTÁ,\nE A TODOS OS CANSADOS\nQUE DESCANSO ELE DÁ.\n\nCORO\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!\n\nPROCLAMAI QUE ELE DO CÉU EM BREVE DESCERÁ!\nE COM TODOS OS SEUS SANTOS APARECERÁ!\nQUE SEM DEMORA VENHAM TODOS SE RENDER,\nE COM AMOR, EM TUDO A CRISTO OBEDECER.\n\nCORO\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!', '<coro>\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!\n\nPROCLAMAI COMO ELE SE CHAMA\nO SALVADOR JESUS,\nCOMO ELE POR NÓS MORREU\nNA ENSANGUENTADA CRUZ;\nCOMO ELE, O CORDEIRO, \nSOBRE O TRONO ESTÁ,\nO DEUS DE TODA A GRAÇA\nQUE MORREU EM MEU LUGAR.\n\n<coro>\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!\n\nPROCLAMAI QUE REINA EM GRAÇA\nNOSSO SALVADOR!\nQUE POR CETRO DE SEU REINO\nELE TEM O AMOR!\nANUNCIAI AOS TRISTES QUE ELE VIVO ESTÁ,\nE A TODOS OS CANSADOS\nQUE DESCANSO ELE DÁ.\n\n<coro>\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!\n\nPROCLAMAI QUE ELE DO CÉU EM BREVE DESCERÁ!\nE COM TODOS OS SEUS SANTOS APARECERÁ!\nQUE SEM DEMORA VENHAM TODOS SE RENDER,\nE COM AMOR, EM TUDO A CRISTO OBEDECER.\n\n<coro>\nPROCLAMAI A TODO O MUNDO\nQUE O SENHOR É REI!\nPROCLAMAI! PROCLAMAI!\nPROCLAMAI QUE SUAVE E DOCE\nÉ SUA SANTA LEI!\nPROCLAMAI! PROCLAMAI!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (722, 'A DEUS, SUPREMO BENFEITOR', 'A DEUS, SUPREMO BENFEITOR', 'A DEUS, SUPREMO BENFEITOR;\nVÓS ANJOS E HOMENS DAI LOUVOR.\nA DEUS, O FILHO, A DEUS, O PAI\nA DEUS ESPÍRITO, GLÓRIA DAI.', 'A DEUS, SUPREMO BENFEITOR;\nVÓS ANJOS E HOMENS DAI LOUVOR.\nA DEUS, O FILHO, A DEUS, O PAI\nA DEUS ESPÍRITO, GLÓRIA DAI.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (723, 'CRISTO PODE HOJE VIR (OH! DIA ALEGRE!)', 'CRISTO PODE HOJE VIR (OH! DIA ALEGRE!)', 'CRISTO PODE HOJE VIR,\nOH! DIA ALEGRE! IREI AMIGOS VER;\nO MAL TERÁ O SEU FIM.\nSE CRISTO DO CÉU DESCER!\n\nCORO\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!\n\nINSTRUMENTOS\n\nSE HOJE FOR PRA MEU LAR,\nOH! DIA ALEGRE! PARECE-ME OUVIR\nOS SALVOS CANTANDO: ''VEM!''\nQUEM DERA PRA O CÉU PARTIR!\n\nCORO\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!\n\nINSTRUMENTOS\n\nPOR QUE ANSIOSO ESTAR?\nOH! DIA ALEGRE! \nHÁ LUZ NA MARGEM ALÉM;\nTEMPORAL NUNCA HAVERÁ;\nDO CÉU BREVE CRISTO VEM!\n\nCORO\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!\n\nINSTRUMENTOS\n\nFIEL A JESUS ESTOU,\nOH! DIA ALEGRE! \nLIVRE ESTOU PRA DIZER:\n''CRISTO É TUDO PRA MIM'';\nDO CÉU VIRÁ COM PODER!\n\nCORO\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!', 'CRISTO PODE HOJE VIR,\nOH! DIA ALEGRE! IREI AMIGOS VER;\nO MAL TERÁ O SEU FIM.\nSE CRISTO DO CÉU DESCER!\n\n<coro>\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!\n<instrumentos>\n\n\nSE HOJE FOR PRA MEU LAR,\nOH! DIA ALEGRE! PARECE-ME OUVIR\nOS SALVOS CANTANDO: ''VEM!''\nQUEM DERA PRA O CÉU PARTIR!\n\n<coro>\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!\n<instrumentos>\n\n\nPOR QUE ANSIOSO ESTAR?\nOH! DIA ALEGRE! \nHÁ LUZ NA MARGEM ALÉM;\nTEMPORAL NUNCA HAVERÁ;\nDO CÉU BREVE CRISTO VEM!\n\n<coro>\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!\n<instrumentos>\n\n\nFIEL A JESUS ESTOU,\nOH! DIA ALEGRE! \nLIVRE ESTOU PRA DIZER:\n''CRISTO É TUDO PRA MIM'';\nDO CÉU VIRÁ COM PODER!\n\n<coro>\nOH! DIA ALEGRE, DA VINDA DE JESUS!\nJESUS VEM BUSCAR-ME PARA OS CÉUS;\nELE VEM BREVE PARA OS SEUS;\nOH! DIA ALEGRE! DA VINDA DE JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (724, 'EIS OS MILHÕES', 'EIS OS MILHÕES', 'EIS OS MILHÕES QUE EM TREVAS TÃO MEDONHAS\nJAZEM PERDIDOS, SEM O SALVADOR!\nOH! QUEM IRÁ AS NOVAS PROCLAMANDO\nQUE DEUS EM CRISTO SALVA O PECADOR?\n\nCORO\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!\n\nPORTAS ABERTAS EIS POR TODO O MUNDO!\nCRENTES EM CRISTO, SEMPRE AVANTE ANDAI!\nE, NA PELEJA UNINDO AS VOSSAS FORÇAS,\nDA ESCRAVIDÃO OS POVOS LIBERTAI.\n\nCORO\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!\n\n''OH! VINDE A MIM'', A VOZ DIVINA CHAMA.\n''VINDE'', CLAMAI EM NOME DE JESUS.\nPOR NOS SALVAR DA MALDIÇÃO ETERNA,\nSEU SANGUE DERRAMOU POR NÓS NA CRUZ.\n\nCORO\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!\n\nÓ DEUS! APRESSA O GLORIOSO DIA\nEM QUE OS REMIDOS TODOS SE UNIRÃO,\nE EM CORO SANTO, EXCELSO, JUBILOSO,\nPOR TODO O SEMPRE GLÓRIA A TI DARÃO!\n\nCORO\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!', 'EIS OS MILHÕES QUE EM TREVAS TÃO MEDONHAS\nJAZEM PERDIDOS, SEM O SALVADOR!\nOH! QUEM IRÁ AS NOVAS PROCLAMANDO\nQUE DEUS EM CRISTO SALVA O PECADOR?\n\n<coro>\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!\n\nPORTAS ABERTAS EIS POR TODO O MUNDO!\nCRENTES EM CRISTO, SEMPRE AVANTE ANDAI!\nE, NA PELEJA UNINDO AS VOSSAS FORÇAS,\nDA ESCRAVIDÃO OS POVOS LIBERTAI.\n\n<coro>\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!\n\n''OH! VINDE A MIM'', A VOZ DIVINA CHAMA.\n''VINDE'', CLAMAI EM NOME DE JESUS.\nPOR NOS SALVAR DA MALDIÇÃO ETERNA,\nSEU SANGUE DERRAMOU POR NÓS NA CRUZ.\n\n<coro>\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!\n\nÓ DEUS! APRESSA O GLORIOSO DIA\nEM QUE OS REMIDOS TODOS SE UNIRÃO,\nE EM CORO SANTO, EXCELSO, JUBILOSO,\nPOR TODO O SEMPRE GLÓRIA A TI DARÃO!\n\n<coro>\nTODO PODER O PAI MEU DEU,\nNA TERRA COMO LÁ NO CÉU!\nIDE, POIS, ANUNCIAI O EVANGELHO,\nE EIS-ME CONVOSCO SEMPRE!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (725, 'EU PERDIDO PECADOR', 'EU PERDIDO PECADOR', 'EU PERDIDO PECADOR, LONGE DO MEU JESUS,\nJÁ ME ACHAVA SEM VIGOR A PERECER SEM LUZ;\nMEU ESTADO CRISTO VI\n\n\nDANDO-ME SUA MÃO,\nE SALVAR-ME CONSEGUIU DA PERDIÇÃO.\n\nCORO\nCRISTO ME AMOU, E ME LIVROU;\nO SEU IMENSO AMOR ME TRANSFORMOU.\nFOI SEU PODER, O SEU QUERER.\nSIM, CRISTO O SALVADOR ME TRANSFORMOU.\n\nINSTRUMENTOS\n\nMINHA VIDA, TODO O SER, QUERO-LHE CONSAGRAR;\nA SEU LADO VOU VIVER, O SEU AMOR CANTAR;\nA MENSAGEM TRANSMITIR AOS QUE PERDIDOS SÃO. \nVENHAM TODOS JÁ FRUIR A SALVAÇÃO.\n\nCORO\nCRISTO ME AMOU, E ME LIVROU;\nO SEU IMENSO AMOR ME TRANSFORMOU.\nFOI SEU PODER, O SEU QUERER.\nSIM, CRISTO O SALVADOR ME TRANSFORMOU.', 'EU PERDIDO PECADOR, LONGE DO MEU JESUS,\nJÁ ME ACHAVA SEM VIGOR A PERECER SEM LUZ;\nMEU ESTADO CRISTO VI\n\n\nDANDO-ME SUA MÃO,\nE SALVAR-ME CONSEGUIU DA PERDIÇÃO.\n\n<coro>\nCRISTO ME AMOU, E ME LIVROU;\nO SEU IMENSO AMOR ME TRANSFORMOU.\nFOI SEU PODER, O SEU QUERER.\nSIM, CRISTO O SALVADOR ME TRANSFORMOU.\n<instrumentos>\n\n\nMINHA VIDA, TODO O SER, QUERO-LHE CONSAGRAR;\nA SEU LADO VOU VIVER, O SEU AMOR CANTAR;\nA MENSAGEM TRANSMITIR AOS QUE PERDIDOS SÃO. \nVENHAM TODOS JÁ FRUIR A SALVAÇÃO.\n\n<coro>\nCRISTO ME AMOU, E ME LIVROU;\nO SEU IMENSO AMOR ME TRANSFORMOU.\nFOI SEU PODER, O SEU QUERER.\nSIM, CRISTO O SALVADOR ME TRANSFORMOU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (726, 'QUANDO A TEMPESTADE RUGE', 'QUANDO A TEMPESTADE RUGE', 'QUANDO A TEMPESTADE RUGE\nCOM O SEU FEROZ BRAMIR,\nQUANDO AS NUVENS SE ACUMULAM,\nRAIOS MIL A DESPEDIR,\nDO TROVÃO O SOM TREMENDO\nOUVE-SE ENTÃO COM PAVOR;\nMAS, NA VOZ DA TEMPESTADE,\nSOA A TUA VOZ, SENHOR!\n\nCORO\nTUA VOZ OUVIMOS NÓS\nA ANIMAR OS QUE ANDAM SÓS,\nMAS SEMPRE EM TI CONFIADOS\nE POR TI SEMPRE A LUTAR,\nNA ARIDEZ DE IMENSAS PLAGAS,\nNAS SOLIDÕES DO VASTO MAR!\n\nQUANDO O MAR VEM MANSAMENTE\nNA PRAIA SE ESPREGUIÇAR,\nQUANDO A BRISA SUSSURRANTE\nNOS SEGREDA AO PERPASSAR,\nSOA DOCE HARMONIA,\nOUVE-SE UM FELIZ RUMOR,\nSOBRE O CORO VEM DAS ONDAS\nTUA DOCE VOZ, SENHOR!\n\nCORO\nTUA VOZ OUVIMOS NÓS\nA ANIMAR OS QUE ANDAM SÓS,\nMAS SEMPRE EM TI CONFIADOS\nE POR TI SEMPRE A LUTAR,\nNA ARIDEZ DE IMENSAS PLAGAS,\nNAS SOLIDÕES DO VASTO MAR!\n\nQUANDO O CORAÇÃO AFLITO\nQUER À DOR, AO MAL FUGIR,\nE SE AGITA E LUTA E RUGE,\nSEM A DOCE PAZ SENTIR,\nENTÃO, QUAL ECO AFASTADO\nNAS QUEBRADAS A ROLAR,\nAO AFLITO E CONTRISTADO\nTUA VOZ VEM CONSOLAR.\n\nCORO\nTUA VOZ OUVIMOS NÓS\nA ANIMAR OS QUE ANDAM SÓS,\nMAS SEMPRE EM TI CONFIADOS\nE POR TI SEMPRE A LUTAR,\nNA ARIDEZ DE IMENSAS PLAGAS,\nNAS SOLIDÕES DO VASTO MAR!', 'QUANDO A TEMPESTADE RUGE\nCOM O SEU FEROZ BRAMIR,\nQUANDO AS NUVENS SE ACUMULAM,\nRAIOS MIL A DESPEDIR,\nDO TROVÃO O SOM TREMENDO\nOUVE-SE ENTÃO COM PAVOR;\nMAS, NA VOZ DA TEMPESTADE,\nSOA A TUA VOZ, SENHOR!\n\n<coro>\nTUA VOZ OUVIMOS NÓS\nA ANIMAR OS QUE ANDAM SÓS,\nMAS SEMPRE EM TI CONFIADOS\nE POR TI SEMPRE A LUTAR,\nNA ARIDEZ DE IMENSAS PLAGAS,\nNAS SOLIDÕES DO VASTO MAR!\n\nQUANDO O MAR VEM MANSAMENTE\nNA PRAIA SE ESPREGUIÇAR,\nQUANDO A BRISA SUSSURRANTE\nNOS SEGREDA AO PERPASSAR,\nSOA DOCE HARMONIA,\nOUVE-SE UM FELIZ RUMOR,\nSOBRE O CORO VEM DAS ONDAS\nTUA DOCE VOZ, SENHOR!\n\n<coro>\nTUA VOZ OUVIMOS NÓS\nA ANIMAR OS QUE ANDAM SÓS,\nMAS SEMPRE EM TI CONFIADOS\nE POR TI SEMPRE A LUTAR,\nNA ARIDEZ DE IMENSAS PLAGAS,\nNAS SOLIDÕES DO VASTO MAR!\n\nQUANDO O CORAÇÃO AFLITO\nQUER À DOR, AO MAL FUGIR,\nE SE AGITA E LUTA E RUGE,\nSEM A DOCE PAZ SENTIR,\nENTÃO, QUAL ECO AFASTADO\nNAS QUEBRADAS A ROLAR,\nAO AFLITO E CONTRISTADO\nTUA VOZ VEM CONSOLAR.\n\n<coro>\nTUA VOZ OUVIMOS NÓS\nA ANIMAR OS QUE ANDAM SÓS,\nMAS SEMPRE EM TI CONFIADOS\nE POR TI SEMPRE A LUTAR,\nNA ARIDEZ DE IMENSAS PLAGAS,\nNAS SOLIDÕES DO VASTO MAR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (727, 'EIS QUE ABRO A PORTA', 'EIS QUE ABRO A PORTA', 'EIS QUE ABRO A PORTA \nPRA DIZER AO POVO MEU: \nENTRA E VEM CEAR COM O VOSSO DEUS.\nANTES DAREI-VOS NOVOS CORPOS,\nPOVO QUE TANTO SOFREU.\nSERÃO GLORIFICADOS \nPARA VEREM O VOSSO DEUS.\n\nSERÁ UMA LINDA FESTA, \nELA NUNCA FINDARÁ,\nNUNCA MAIS VAMOS SOFRER, \nNUNCA MAIS VAMOS CHORAR.\nPOIS ALI CONOSCO ESTARÁ \nE O VEREMOS FACE A FACE,\nE PARA SEMPRE VAMOS ADORAR\nO DEUS QUE AQUI TANTO BUSCAMOS.\nINSTRUMENTOS\n\nEIS QUE ABRO A PORTA \nPRA DIZER AO POVO MEU: \nENTRA E VEM CEAR COM O VOSSO DEUS.\nANTES DAREI-VOS NOVOS CORPOS,\nPOVO QUE TANTO SOFREU.\nSERÃO GLORIFICADOS \nPARA VEREM O VOSSO DEUS.\n\nSERÁ UMA LINDA FESTA, \nELA NUNCA FINDARÁ,\nNUNCA MAIS VAMOS SOFRER, \nNUNCA MAIS VAMOS CHORAR.\nPOIS ALI CONOSCO ESTARÁ \nE O VEREMOS FACE A FACE,\nE PARA SEMPRE VAMOS ADORAR\nO DEUS QUE AQUI TANTO BUSCAMOS.\n\nFINAL:\nE PARA SEMPRE VAMOS ADORAR\nO DEUS QUE AQUI TANTO BUSCAMOS.', 'EIS QUE ABRO A PORTA \nPRA DIZER AO POVO MEU: \nENTRA E VEM CEAR COM O VOSSO DEUS.\nANTES DAREI-VOS NOVOS CORPOS,\nPOVO QUE TANTO SOFREU.\nSERÃO GLORIFICADOS \nPARA VEREM O VOSSO DEUS.\n\nSERÁ UMA LINDA FESTA, \nELA NUNCA FINDARÁ,\nNUNCA MAIS VAMOS SOFRER, \nNUNCA MAIS VAMOS CHORAR.\nPOIS ALI CONOSCO ESTARÁ \nE O VEREMOS FACE A FACE,\nE PARA SEMPRE VAMOS ADORAR\nO DEUS QUE AQUI TANTO BUSCAMOS.\n<instrumentos>\n\n\nEIS QUE ABRO A PORTA \nPRA DIZER AO POVO MEU: \nENTRA E VEM CEAR COM O VOSSO DEUS.\nANTES DAREI-VOS NOVOS CORPOS,\nPOVO QUE TANTO SOFREU.\nSERÃO GLORIFICADOS \nPARA VEREM O VOSSO DEUS.\n\nSERÁ UMA LINDA FESTA, \nELA NUNCA FINDARÁ,\nNUNCA MAIS VAMOS SOFRER, \nNUNCA MAIS VAMOS CHORAR.\nPOIS ALI CONOSCO ESTARÁ \nE O VEREMOS FACE A FACE,\nE PARA SEMPRE VAMOS ADORAR\nO DEUS QUE AQUI TANTO BUSCAMOS.\n<final>E PARA SEMPRE VAMOS ADORAR\nO DEUS QUE AQUI TANTO BUSCAMOS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (728, 'NOSSA GRATIDÃO', 'NOSSA GRATIDÃO', 'NOSSA GRATIDÃO E NOSSO LOUVOR \nIREMOS DEIXAR NO TEU ALTAR.\nQUE DAREMOS A TI, SENHOR, \nPELOS TEUS FEITOS E POR TUA OBRA\nAQUI NESTE LUGAR?\n\nGLÓRIA, SEMPRE GLÓRIA,\nCOM TEUS ANJOS PARA SEMPRE ADORAR.\nGLÓRIA, SEMPRE GLÓRIA,\nA TEUS PÉS, SENHOR, IREMOS EXALTAR.\n\nO SENHOR É JUSTO, É FIEL, \nSUA MISERICÓRDIA NÃO TEM FIM.\nTODAS AS TUAS OBRAS, SENHOR, TE LOUVARÃO \nE OS TEUS SANTOS TE BENDIRÃO.\n\nGLÓRIA (OS CÉUS MANIFESTAM), \nSEMPRE GLÓRIA (SUA GLÓRIA E PODER). \nOS ANJOS TE LOUVAM SEM CESSAR (GLÓRIA).\nGLÓRIA (EM NOSSOS LÁBIOS),\nSEMPRE GLÓRIA (HÁ SEMPRE UM LOUVOR), \nDE EXALTAÇÃO POR TUA GLÓRIA, SENHOR. \n\nFINAL: \nGLÓRIA (GLÓRIA) PARA SEMPRE AO SENHOR, GLÓRIA (GLÓRIA), O TEU NOME EXALTAR.', 'NOSSA GRATIDÃO E NOSSO LOUVOR \nIREMOS DEIXAR NO TEU ALTAR.\nQUE DAREMOS A TI, SENHOR, \nPELOS TEUS FEITOS E POR TUA OBRA\nAQUI NESTE LUGAR?\n\nGLÓRIA, SEMPRE GLÓRIA,\nCOM TEUS ANJOS PARA SEMPRE ADORAR.\nGLÓRIA, SEMPRE GLÓRIA,\nA TEUS PÉS, SENHOR, IREMOS EXALTAR.\n\nO SENHOR É JUSTO, É FIEL, \nSUA MISERICÓRDIA NÃO TEM FIM.\nTODAS AS TUAS OBRAS, SENHOR, TE LOUVARÃO \nE OS TEUS SANTOS TE BENDIRÃO.\n\nGLÓRIA (OS CÉUS MANIFESTAM),<bis>\nSEMPRE GLÓRIA (SUA GLÓRIA E PODER).<bis>\nOS ANJOS TE LOUVAM SEM CESSAR (GLÓRIA).<bis>\nGLÓRIA (EM NOSSOS LÁBIOS),<bis>\nSEMPRE GLÓRIA (HÁ SEMPRE UM LOUVOR),<bis>\nDE EXALTAÇÃO POR TUA GLÓRIA, SENHOR.<bis>\n<bis>\n\n\n<final>GLÓRIA (GLÓRIA) PARA SEMPRE AO SENHOR, GLÓRIA (GLÓRIA), O TEU NOME EXALTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (729, 'OS TEUS ANJOS TE EXALTAM', 'OS TEUS ANJOS TE EXALTAM', 'OS TEUS ANJOS TE EXALTAM, \nMEU SENHOR E REI,\nCOMO ALMEJO ESTAR NA TUA GLÓRIA.\nDEIXAR ESTE MUNDO DE TREVAS, \nCHEIO DE TRIBULAÇÕES,\nE SOMENTE TE LOUVAR, MEU SENHOR.\n\nSENHOR, TU PASSASTE UM DIA POR AFLIÇÕES\nE SABES QUE NÃO É FÁCIL VIVER AQUI.\nMAS, COMO TU VENCESTE O MUNDO,\nEU TAMBÉM POSSO VENCER,\nPOIS, NÃO HÁ NADA QUE SEJA \nIMPOSSÍVEL PARA TI.\n\nSINTO-ME FELIZ QUANDO OUÇO TUA VOZ\nA FALAR A MEU CORAÇÃO: \n''NÃO TARDAREI, EM BREVE VOLTAREI (VOLTAREI),\nPARA VOS LEVAR (SIM, VOLTAREI),\nEM BREVE VOLTAREI.''\n\nFINAL: E NÓS TE ESPERAMOS, SENHOR.', 'OS TEUS ANJOS TE EXALTAM, \nMEU SENHOR E REI,\nCOMO ALMEJO ESTAR NA TUA GLÓRIA.\nDEIXAR ESTE MUNDO DE TREVAS, \nCHEIO DE TRIBULAÇÕES,\nE SOMENTE TE LOUVAR, MEU SENHOR.\n\nSENHOR, TU PASSASTE UM DIA POR AFLIÇÕES\nE SABES QUE NÃO É FÁCIL VIVER AQUI.\nMAS, COMO TU VENCESTE O MUNDO,\nEU TAMBÉM POSSO VENCER,\nPOIS, NÃO HÁ NADA QUE SEJA \nIMPOSSÍVEL PARA TI.\n\nSINTO-ME FELIZ QUANDO OUÇO TUA VOZ\nA FALAR A MEU CORAÇÃO: \n''NÃO TARDAREI, EM BREVE VOLTAREI (VOLTAREI),\nPARA VOS LEVAR (SIM, VOLTAREI),\nEM BREVE VOLTAREI.''\n<final>E NÓS TE ESPERAMOS, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (730, 'SÓ TU NOS FAZES VENCEDORES', 'SÓ TU NOS FAZES VENCEDORES', 'SÓ TU NOS FAZES VENCEDORES,\nEM TI TEMOS FORÇAS PRA JORNADA;\nSACIA A FOME COM TEU SUBLIME \nAMOR, DOCE AMOR.\n\nPOIS NÓS TE LOUVAMOS,\nDIZEMOS: ÉS NOSSA ROCHA ETERNA,\nÉS NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.\n\n\nSÓ TU NOS FAZES VENCEDORES,\nEM TI TEMOS FORÇAS PRA JORNADA;\nSACIA A FOME COM TEU SUBLIME \nAMOR, DOCE AMOR.\n\nPOIS NÓS TE LOUVAMOS,\nDIZEMOS: ÉS NOSSA ROCHA ETERNA,\nÉS NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.\nINSTRUMENTOS\n\n\nNÓS TE LOUVAMOS,\nDIZEMOS: ÉS NOSSA ROCHA ETERNA,\nÉS NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.\n \nFINAL:\nNOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.', 'SÓ TU NOS FAZES VENCEDORES,\nEM TI TEMOS FORÇAS PRA JORNADA;\nSACIA A FOME COM TEU SUBLIME \nAMOR, DOCE AMOR.\n\nPOIS NÓS TE LOUVAMOS,\nDIZEMOS: ÉS NOSSA ROCHA ETERNA,\nÉS NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.\n\n\nSÓ TU NOS FAZES VENCEDORES,\nEM TI TEMOS FORÇAS PRA JORNADA;\nSACIA A FOME COM TEU SUBLIME \nAMOR, DOCE AMOR.\n\nPOIS NÓS TE LOUVAMOS,\nDIZEMOS: ÉS NOSSA ROCHA ETERNA,\nÉS NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.\n<instrumentos>\n\n\nNÓS TE LOUVAMOS,\nDIZEMOS: ÉS NOSSA ROCHA ETERNA,\nÉS NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.\n<final>NOSSO PASTOR, NOSSO JESUS, \nNOSSO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (731, 'SEQUÊNCIA DE LOUVORES NO 1', 'SEQUÊNCIA DE LOUVORES NO 1', 'A\nDESDE O DIA EM QUE ACEITEI JESUS,\nA MINHA VIDA SE TRANSFORMOU.\nAGORA SOU FELIZ, AGORA VIVO BEM,\nJESUS SALVOU A MIM E SALVA A TI TAMBÉM;\nAGORA SOU FELIZ, AGORA VIVO BEM\nCOM JESUS E MAIS NINGUÉM.\n\nB\nCORO\nA MINH''ALMA ESTÁ CHEIA DE PAZ, (BIS)\nTENHO GOZO CELESTE E PRAZER EM DIZER\nQUE A MINH''ALMA ESTÁ CHEIA DE PAZ.\n\nEU CAMINHANDO VOU, (BIS)\nPARA A CIDADE SANTA\nEU CAMINHANDO VOU.\n\nCORO\nA MINH''ALMA ESTÁ CHEIA DE PAZ, (BIS)\nTENHO GOZO CELESTE E PRAZER EM DIZER\nQUE A MINH''ALMA ESTÁ CHEIA DE PAZ.\n\nEU VOU CANTAR NO CÉU, (BIS)\nUM HINO DE VITÓRIA\nEU VOU CANTAR NO CÉU.\n\nCORO\nA MINH''ALMA ESTÁ CHEIA DE PAZ, (BIS)\nTENHO GOZO CELESTE E PRAZER EM DIZER\nQUE A MINH''ALMA ESTÁ CHEIA DE PAZ.\nC\nSOU FELIZ PORQUE SOU DE CRISTO (3X)\nALELUIA, GLÓRIA A DEUS.\nALELUIA, AMÉM, AMÉM, (BIS)\nALELUIA, GLÓRIA A DEUS.\n\nD\nNA CASA DE MEU PAI NÃO HÁ TRISTEZA, NÃO,\nNA CASA DE MEU PAI NÃO HÁ TRISTEZA, NÃO,\nÉ UM LUGAR MUI BELO E DE CONSAGRAÇÃO,\nNA CASA DE MEU PAI NÃO HÁ TRISTEZA, NÃO.\n\nE\nÉ ISTO QUE ME FAZ CANTAR, (BIS)\nDOS MEUS PECADOS LIVRE ESTOU\nE PARA O CÉU EU VOU,\nÉ ISTO QUE ME FAZ CANTAR.\n\nAO MUNDO VOU ANUNCIAR, (BIS)\nQUE CRISTO SALVA O POBRE PECADOR,\nPOR SEU AMOR;\nÉ ISTO QUE ME FAZ CANTAR.\n\nF\nGOZO EU TENHO EM JESUS,\nGOZO EU TENHO EM JESUS;\nMEU CORAÇÃO ALEGRE ESTÁ\nPORQUE JESUS ME VALERÁ.\nG\nJESUS É MARAVILHOSO! (BIS)\nELE SALVA, ELE CURA,\nELE FAZ FELIZ,\nSIM, JESUS É MARAVILHOSO!', 'A\nDESDE O DIA EM QUE ACEITEI JESUS,<bis>\nA MINHA VIDA SE TRANSFORMOU.<bis>\nAGORA SOU FELIZ, AGORA VIVO BEM,\nJESUS SALVOU A MIM E SALVA A TI TAMBÉM;\nAGORA SOU FELIZ, AGORA VIVO BEM\nCOM JESUS E MAIS NINGUÉM.\n\nB<coro>\nA MINH''ALMA ESTÁ CHEIA DE PAZ, <bis>\nTENHO GOZO CELESTE E PRAZER EM DIZER\nQUE A MINH''ALMA ESTÁ CHEIA DE PAZ.\n\nEU CAMINHANDO VOU, <bis>\nPARA A CIDADE SANTA<bis>\nEU CAMINHANDO VOU.<bis>\n\n<coro>\nA MINH''ALMA ESTÁ CHEIA DE PAZ, <bis>\nTENHO GOZO CELESTE E PRAZER EM DIZER\nQUE A MINH''ALMA ESTÁ CHEIA DE PAZ.\n\nEU VOU CANTAR NO CÉU, <bis>\nUM HINO DE VITÓRIA<bis>\nEU VOU CANTAR NO CÉU.<bis>\n\n<coro>\nA MINH''ALMA ESTÁ CHEIA DE PAZ, <bis>\nTENHO GOZO CELESTE E PRAZER EM DIZER\nQUE A MINH''ALMA ESTÁ CHEIA DE PAZ.\nC\nSOU FELIZ PORQUE SOU DE CRISTO <bis tipo=''3''>\nALELUIA, GLÓRIA A DEUS.\nALELUIA, AMÉM, AMÉM, <bis>\nALELUIA, GLÓRIA A DEUS.\n\nD\nNA CASA DE MEU PAI NÃO HÁ TRISTEZA, NÃO,\nNA CASA DE MEU PAI NÃO HÁ TRISTEZA, NÃO,\nÉ UM LUGAR MUI BELO E DE CONSAGRAÇÃO,\nNA CASA DE MEU PAI NÃO HÁ TRISTEZA, NÃO.\n\nE\nÉ ISTO QUE ME FAZ CANTAR, <bis>\nDOS MEUS PECADOS LIVRE ESTOU\nE PARA O CÉU EU VOU,\nÉ ISTO QUE ME FAZ CANTAR.\n\nAO MUNDO VOU ANUNCIAR, <bis>\nQUE CRISTO SALVA O POBRE PECADOR,\nPOR SEU AMOR;\nÉ ISTO QUE ME FAZ CANTAR.\n\nF\nGOZO EU TENHO EM JESUS,\nGOZO EU TENHO EM JESUS;\nMEU CORAÇÃO ALEGRE ESTÁ<bis>\nPORQUE JESUS ME VALERÁ.<bis>\nG\nJESUS É MARAVILHOSO! <bis>\nELE SALVA, ELE CURA,\nELE FAZ FELIZ,\nSIM, JESUS É MARAVILHOSO!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (732, 'SEQUÊNCIA DE LOUVORES NO 2', 'SEQUÊNCIA DE LOUVORES NO 2', 'A\nESTAMOS MUITO ALEGRES,\nJESUS ESTÁ AQUI, SENTIMOS MUITO AMOR,\nSENTIMOS UNIÃO;\nSENTIMOS QUE JESUS\nESTÁ AQUI EM NOSSO MEIO\nPOR ISSO TEMOS PAZ NO CORAÇÃO. \n\nB\nEU QUERO ANDAR NAS RUAS DE OURO COM JESUS,\nEU QUERO ANDAR NAS RUAS DE OURO COM JESUS,\nEU QUERO ANDAR NAS RUAS DE OURO (BIS) \nEU QUERO ANDAR NAS RUAS DE OURO COM JESUS.\n\nE LÁ NA NOVA JERUSALÉM (3X)\nEU QUERO ANDAR NAS RUAS DE OURO \nCOM JESUS.\n\nC\nEU TENHO UMA COROA LÁ NO CÉU,\nJESUS FOI PREPARÁ-LA PARA MIM, OUVI A VOZ DE CRISTO QUE DIZIA: ''MEU FILHO, NÃO TARDES VIR A MIM''; EU NÃO ENDURECI MEU CORAÇÃO, A VOZ DE CRISTO EU ACEITEI,\nELE ME DISSE: ''LEVANTA-TE, MEU FILHO, \nPORQUE OS TEUS PECADOS\nNO MEU SANGUE, EU JÁ LAVEI''.\n\nD\nEU SOU FELIZ PORQUE A BÍBLIA DIZ, \nVOU PARA O CÉU O MEU LINDO PAÍS\n\nALELUIA, ALELUIA,\nALELUIA, AMÉM.\n\nE\nO NOME DE JESUS É DOCE, TRAZ GOZO, \nPAZ E ALEGRIA, CANTANDO ESTA MELODIA: \nJESUS, JESUS, JESUS.\nF\nCOMO É BOM DEIXAR ESTE MUNDO (3X)\nE SEGUIR AO MEU SALVADOR.', 'A\nESTAMOS MUITO ALEGRES,\nJESUS ESTÁ AQUI, SENTIMOS MUITO AMOR,\nSENTIMOS UNIÃO;\nSENTIMOS QUE JESUS<bis>\nESTÁ AQUI EM NOSSO MEIO<bis>\nPOR ISSO TEMOS PAZ NO CORAÇÃO. <bis>\n\nB\nEU QUERO ANDAR NAS RUAS DE OURO COM JESUS,\nEU QUERO ANDAR NAS RUAS DE OURO COM JESUS,\nEU QUERO ANDAR NAS RUAS DE OURO <bis>\nEU QUERO ANDAR NAS RUAS DE OURO COM JESUS.\n\nE LÁ NA NOVA JERUSALÉM <bis tipo=''3''>\nEU QUERO ANDAR NAS RUAS DE OURO \nCOM JESUS.\n\nC\nEU TENHO UMA COROA LÁ NO CÉU,\nJESUS FOI PREPARÁ-LA PARA MIM, OUVI A VOZ DE CRISTO QUE DIZIA: ''MEU FILHO, NÃO TARDES VIR A MIM''; EU NÃO ENDURECI MEU CORAÇÃO, A VOZ DE CRISTO EU ACEITEI,\nELE ME DISSE: ''LEVANTA-TE, MEU FILHO, \nPORQUE OS TEUS PECADOS<bis>\nNO MEU SANGUE, EU JÁ LAVEI''.<bis>\n\nD\nEU SOU FELIZ PORQUE A BÍBLIA DIZ, <bis>\nVOU PARA O CÉU O MEU LINDO PAÍS<bis>\n\nALELUIA, ALELUIA,<bis>\nALELUIA, AMÉM.<bis>\n\nE\nO NOME DE JESUS É DOCE, TRAZ GOZO, \nPAZ E ALEGRIA, CANTANDO ESTA MELODIA: \nJESUS, JESUS, JESUS.\nF\nCOMO É BOM DEIXAR ESTE MUNDO <bis tipo=''3''>\nE SEGUIR AO MEU SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (733, 'SEQUÊNCIA DE LOUVORES NO 3', 'SEQUÊNCIA DE LOUVORES NO 3', 'A\nEU TENHO UM AMIGO QUE ME AMA,\nME AMA, ME AMA,\nEU TENHO UM AMIGO QUE ME AMA,\nSEU NOME É JESUS.\nJESUS, JESUS, SEU NOME É JESUS. (BIS)\n\nB\nA VIDA, A VIDA É JESUS, (BIS)\nEU VOU MORAR LÁ NO CÉU\nPORQUE A VIDA, A VIDA É JESUS.\n\nC\nMEU CORAÇÃO CONTENTE ESTÁ,\nMEU CORAÇÃO CONTENTE ESTÁ\nPORQUE O SENHOR JÁ ME SALVOU.\n\nOH! QUÃO FELIZ, FELIZ, FELIZ\nSE SENTE A ALMA COM JESUS\nCOM A PAZ QUE NENHUM \nOUTRO PODE DAR.\n\nD\nEU SÓ CONFIO NO SENHOR QUE NÃO VAI\nFALHAR, EU SÓ CONFIO NO SENHOR, SIGO A CANTAR;\nSE O SOL CHEGAR A ESCURECER E O CÉU\nTOLDAR, EU SÓ CONFIO NO SENHOR\nQUE NÃO VAI FALHAR.\n\nPOSSO CONFIAR, POSSO CONFIAR \nQUE UM LAR NO CÉU CRISTO VAI ME DAR;\nSE O SOL CHEGAR A ESCURECER \nE O CÉU TOLDAR, \nEU SÓ CONFIO NO SENHOR\nQUE NÃO VAI FALHAR.', 'A\nEU TENHO UM AMIGO QUE ME AMA,\nME AMA, ME AMA,\nEU TENHO UM AMIGO QUE ME AMA,\nSEU NOME É JESUS.\nJESUS, JESUS, SEU NOME É JESUS. <bis>\n\nB\nA VIDA, A VIDA É JESUS, <bis>\nEU VOU MORAR LÁ NO CÉU\nPORQUE A VIDA, A VIDA É JESUS.\n\nC\nMEU CORAÇÃO CONTENTE ESTÁ,<bis>\nMEU CORAÇÃO CONTENTE ESTÁ<bis>\nPORQUE O SENHOR JÁ ME SALVOU.<bis>\n\nOH! QUÃO FELIZ, FELIZ, FELIZ<bis>\nSE SENTE A ALMA COM JESUS<bis>\nCOM A PAZ QUE NENHUM <bis>\nOUTRO PODE DAR.<bis>\n\nD\nEU SÓ CONFIO NO SENHOR QUE NÃO VAI\nFALHAR, EU SÓ CONFIO NO SENHOR, SIGO A CANTAR;\nSE O SOL CHEGAR A ESCURECER E O CÉU\nTOLDAR, EU SÓ CONFIO NO SENHOR\nQUE NÃO VAI FALHAR.\n\nPOSSO CONFIAR, POSSO CONFIAR \nQUE UM LAR NO CÉU CRISTO VAI ME DAR;\nSE O SOL CHEGAR A ESCURECER \nE O CÉU TOLDAR, \nEU SÓ CONFIO NO SENHOR\nQUE NÃO VAI FALHAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (734, 'A VIDA DE MINH''ALMA', 'A VIDA DE MINH''ALMA', 'A VIDA DE MINH''ALMA \nÉ CRISTO, MEU CRISTO,\nA VIDA DE MINH''ALMA É JESUS,\nMEU SALVADOR.\n\nCRISTO, CRISTO, CRISTO, CRISTO\nA VIDA DE MINH''ALMA É JESUS,\nMEU SALVADOR.', 'A VIDA DE MINH''ALMA \nÉ CRISTO, MEU CRISTO,\nA VIDA DE MINH''ALMA É JESUS,\nMEU SALVADOR.\n\nCRISTO, CRISTO, CRISTO, CRISTO<bis>\nA VIDA DE MINH''ALMA É JESUS,<bis>\nMEU SALVADOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (735, 'SEU NOME É JESUS', 'SEU NOME É JESUS', 'SEU NOME É JESUS, (3X)\nEU O AMO SIM.\n\nOH! QUANTO O ADORO! \nA ELE ME RENDO,\nSEU NOME É JESUS, \nEU O AMO SIM.', 'SEU NOME É JESUS, <bis tipo=''3''>\nEU O AMO SIM.\n\nOH! QUANTO O ADORO! \nA ELE ME RENDO,\nSEU NOME É JESUS, \nEU O AMO SIM.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (736, 'CRISTO É A RESPOSTA', 'CRISTO É A RESPOSTA', 'CRISTO É A RESPOSTA AO PECADOR,\nCRISTO É A RESPOSTA À NOSSA DOR;\nSALVA E BATIZA E TAMBÉM CURA;\nOH! ALELUIA, DAI GLÓRIA A DEUS.', 'CRISTO É A RESPOSTA AO PECADOR,<bis>\nCRISTO É A RESPOSTA À NOSSA DOR;<bis>\nSALVA E BATIZA E TAMBÉM CURA;<bis>\nOH! ALELUIA, DAI GLÓRIA A DEUS.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (737, 'SE ESTÁS CANSADO', 'SE ESTÁS CANSADO', 'SE ESTÁS CANSADO E DESANIMADO,\nDEIXA TUDO AO LADO, VEM A JESUS.\nVEM A JESUS, VEM A JESUS,\nDEIXA TUDO AO LADO, VEM A JESUS.\n\nSE ARREPENDIDO JÁ TIVERES CRIDO,\nÉS UM REDIMIDO, GLÓRIA A JESUS.\nGLÓRIA A JESUS, GLÓRIA A JESUS,\nÉS UM REDIMIDO, GLÓRIA A JESUS.', 'SE ESTÁS CANSADO E DESANIMADO,\nDEIXA TUDO AO LADO, VEM A JESUS.\nVEM A JESUS, VEM A JESUS,\nDEIXA TUDO AO LADO, VEM A JESUS.\n\nSE ARREPENDIDO JÁ TIVERES CRIDO,\nÉS UM REDIMIDO, GLÓRIA A JESUS.\nGLÓRIA A JESUS, GLÓRIA A JESUS,\nÉS UM REDIMIDO, GLÓRIA A JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (738, 'GLÓRIA, GLÓRIA', 'GLÓRIA, GLÓRIA', 'GLÓRIA, GLÓRIA, GLÓRIA \nAO SENHOR JESUS.\nDELE É A GLÓRIA,\nDELE É O PODER, \nPARA TODO SEMPRE, AMÉM.\n\nREPETIR O LOUVOR', 'GLÓRIA, GLÓRIA, GLÓRIA <bis>\nAO SENHOR JESUS.<bis>\nDELE É A GLÓRIA,\nDELE É O PODER, \nPARA TODO SEMPRE, AMÉM.\n\n<repetir tipo=''O LOUVOR''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (739, 'EU TENHO UM TESOURO', 'EU TENHO UM TESOURO', 'EU TENHO UM TESOURO, \nEU TENHO, SIM, EU TENHO TESOURO DENTRO DE MIM; ESTE MEU TESOURO TEM MUITO VALOR, ESTE MEU TESOURO É JESUS CRISTO, \nMEU SALVADOR.\n\nVALE MAIS QUE O CÉU,\nVALE MAIS QUE O MAR,\nVALE MAIS QUE O MUNDO,\nVALE MAIS QUE EU.\nOH! QUE GLORIOSO, \nQUE GLÓRIA SEM FIM!\nESTE MEU TESOURO\nÉ JESUS CRISTO QUE VIVE EM MIM.', 'EU TENHO UM TESOURO, \nEU TENHO, SIM, EU TENHO TESOURO DENTRO DE MIM; ESTE MEU TESOURO TEM MUITO VALOR, ESTE MEU TESOURO É JESUS CRISTO, \nMEU SALVADOR.\n\nVALE MAIS QUE O CÉU,\nVALE MAIS QUE O MAR,<bis>\nVALE MAIS QUE O MUNDO,<bis>\nVALE MAIS QUE EU.<bis>\nOH! QUE GLORIOSO, <bis>\nQUE GLÓRIA SEM FIM!<bis>\nESTE MEU TESOURO<bis>\nÉ JESUS CRISTO QUE VIVE EM MIM.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (740, 'EU TENHO UM DEUS MUI, MUI, MUI GRANDE', 'EU TENHO UM DEUS MUI, MUI, MUI GRANDE', 'EU TENHO UM DEUS\nMUI, MUI, MUI GRANDE,\nMARAVILHOSO ELE É,\nSEMPRE AMOROSO, \nSEMPRE VITORIOSO,\nMARAVILHOSO ELE É.\n\nE QUANDO NAS LUTAS OU PROVAS,\nSEMPRE CONOSCO ESTÁ,\nNOS LEVANTA QUANDO CAÍMOS,\nSUA MÃO NOS SUSTERÁ.\n\nEU TENHO UM DEUS MUI, MUI, MUI GRANDE \nMARAVILHOSO ELE É, SEMPRE AMOROSO, \nSEMPRE VITORIOSO, MARAVILHOSO ELE É.\n\nMARAVILHOSO, MARAVILHOSO,\nMARAVILHOSO ELE É.', 'EU TENHO UM DEUS<bis>\nMUI, MUI, MUI GRANDE,<bis>\nMARAVILHOSO ELE É,<bis>\nSEMPRE AMOROSO, <bis>\nSEMPRE VITORIOSO,<bis>\nMARAVILHOSO ELE É.<bis>\n\nE QUANDO NAS LUTAS OU PROVAS,\nSEMPRE CONOSCO ESTÁ,\nNOS LEVANTA QUANDO CAÍMOS,\nSUA MÃO NOS SUSTERÁ.\n\nEU TENHO UM DEUS MUI, MUI, MUI GRANDE \nMARAVILHOSO ELE É, SEMPRE AMOROSO, \nSEMPRE VITORIOSO, MARAVILHOSO ELE É.\n\nMARAVILHOSO, MARAVILHOSO,\nMARAVILHOSO ELE É.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (741, 'NÃO HÁ DEUS TÃO GRANDE COMO TU', 'NÃO HÁ DEUS TÃO GRANDE COMO TU', 'NÃO HÁ DEUS TÃO GRANDE COMO TU,\nNEM UM SÓ, NEM UM SÓ.\n\nNÃO HÁ DEUS\nQUE FAZ AS MESMAS OBRAS,\nCOMO AS QUE FAZES TU.\n\nJESUS DISSE: ''SE TU CRERES,\nTU VERÁS A GLÓRIA DE DEUS''.\n\nVERÁS A GLÓRIA DE DEUS, (BIS)\nJESUS DISSE: ''SE TU CRERES,\nTU VERÁS A GLÓRIA DE DEUS''.', 'NÃO HÁ DEUS TÃO GRANDE COMO TU,<bis>\nNEM UM SÓ, NEM UM SÓ.<bis>\n\nNÃO HÁ DEUS<bis>\nQUE FAZ AS MESMAS OBRAS,<bis>\nCOMO AS QUE FAZES TU.<bis>\n\nJESUS DISSE: ''SE TU CRERES,<bis>\nTU VERÁS A GLÓRIA DE DEUS''.<bis>\n\nVERÁS A GLÓRIA DE DEUS, <bis>\nJESUS DISSE: ''SE TU CRERES,<bis>\nTU VERÁS A GLÓRIA DE DEUS''.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (742, 'NO CÉU HÁ JANELAS ABERTAS', 'NO CÉU HÁ JANELAS ABERTAS', 'NO CÉU HÁ JANELAS ABERTAS,\nAS BÊNÇÃOS JÁ DESCEM DE LÁ;\nO MEU CORAÇÃO REJUBILA\nPORQUE JESUS NELE ESTÁ.\nTIREI OS ANDRAJOS IMUNDOS,\nDE BRANCO VESTIU-ME O SENHOR,\nDO PÃO DIVINAL EU ME NUTRO,\nBANQUETE DO SEU GRANDE AMOR.', 'NO CÉU HÁ JANELAS ABERTAS,\nAS BÊNÇÃOS JÁ DESCEM DE LÁ;\nO MEU CORAÇÃO REJUBILA\nPORQUE JESUS NELE ESTÁ.\nTIREI OS ANDRAJOS IMUNDOS,\nDE BRANCO VESTIU-ME O SENHOR,\nDO PÃO DIVINAL EU ME NUTRO,\nBANQUETE DO SEU GRANDE AMOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
