INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (747, 'SENHOR, MANDA PODER', 'SENHOR, MANDA PODER', 'SENHOR, MANDA PODER, SENHOR, MANDA PODER,\nOPERA MARAVILHAS, FAZ SINAIS APARECER, \nREPREENDE O INIMIGO, BATIZA O QUE CRER, \nDERRAMA FOGO SANTO, Ó SENHOR, \nMANDA PODER.\n\nMANDA PODER Ó SENHOR MANDA PODER\nMANDA PODER Ó SENHOR MANDA PODER\nMANDA PODER Ó SENHOR, PRA NÓS AQUI\nPRA RESISTIR AO TEMPORAL QUE HÁ DE VIR.\n\nREMOVE AS ÁGUAS, RETIRA AS PEDRAS,\nE MANDA FOGO LÁ DO CÉU,\nREMOVE AS ÁGUAS, RETIRA AS PEDRAS,\nE MANDA FOGO LÁ DO CÉU.', 'SENHOR, MANDA PODER, SENHOR, MANDA PODER,\nOPERA MARAVILHAS, FAZ SINAIS APARECER, \nREPREENDE O INIMIGO, BATIZA O QUE CRER, \nDERRAMA FOGO SANTO, Ó SENHOR, \nMANDA PODER.\n\nMANDA PODER Ó SENHOR MANDA PODER\nMANDA PODER Ó SENHOR MANDA PODER\nMANDA PODER Ó SENHOR, PRA NÓS AQUI\nPRA RESISTIR AO TEMPORAL QUE HÁ DE VIR.\n\nREMOVE AS ÁGUAS, RETIRA AS PEDRAS,\nE MANDA FOGO LÁ DO CÉU,\nREMOVE AS ÁGUAS, RETIRA AS PEDRAS,\nE MANDA FOGO LÁ DO CÉU.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (748, 'QUE CALOR É ESTE EM VOLTA DO ALTAR?', 'QUE CALOR É ESTE EM VOLTA DO ALTAR?', 'QUE CALOR É ESTE EM VOLTA DO ALTAR?\nQUE CALOR É ESTE EM VOLTA DO ALTAR?\nQUE CALOR É ESTE EM VOLTA DO ALTAR?\nÉ O PODER DE DEUS QUE ESTÁ NESTE LUGAR,\nÉ O PODER DE DEUS QUE ESTÁ NESTE LUGAR.\n\nQUEIMA, QUEIMA, QUEIMA COM FOGO DA GLÓRIA,\nQUEIMA, QUEIMA, QUEIMA POR DENTRO E POR FORA,\nQUEIMA, QUEIMA, QUEIMA OS PECADOS DE AGORA,\nQUEIMA COM FOGO DIVINO\nPOIS SÓ TEU PODER NOS DÁ A VITÓRIA.', 'QUE CALOR É ESTE EM VOLTA DO ALTAR?\nQUE CALOR É ESTE EM VOLTA DO ALTAR?\nQUE CALOR É ESTE EM VOLTA DO ALTAR?\nÉ O PODER DE DEUS QUE ESTÁ NESTE LUGAR,\nÉ O PODER DE DEUS QUE ESTÁ NESTE LUGAR.\n\nQUEIMA, QUEIMA, QUEIMA COM FOGO DA GLÓRIA,\nQUEIMA, QUEIMA, QUEIMA POR DENTRO E POR FORA,\nQUEIMA, QUEIMA, QUEIMA OS PECADOS DE AGORA,\nQUEIMA COM FOGO DIVINO<bis>\nPOIS SÓ TEU PODER NOS DÁ A VITÓRIA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
