INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (750, 'DEIXA A GLÓRIA DE DEUS BRILHAR', 'DEIXA A GLÓRIA DE DEUS BRILHAR', 'DEIXA A GLÓRIA DE DEUS BRILHAR (5X)\nDEIXA A GLÓRIA EM TEU ROSTO BRILHAR,\nDEIXA A GLÓRIA DE DEUS BRILHAR EM TEU ROSTO, \nDEIXA A GLÓRIA DE DEUS BRILHAR.\n\nFOI LÁ NO CUME DO MONTE QUE O \nNOSSO DEUS COM MOISÉS FALAVA;\nQUANDO ELE DESCEU DO MONTE \nNÃO SABIA QUE SEU ROSTO BRILHAVA,\nBRILHAVA, BRILHAVA, O SEU ROSTO BRILHAVA;\nFOI LÁ NO CUME DO MONTE \nSINAI QUE O NOSSO DEUS\nCOM MOISÉS FALAVA.', 'DEIXA A GLÓRIA DE DEUS BRILHAR <bis tipo=''5''>\nDEIXA A GLÓRIA EM TEU ROSTO BRILHAR,\nDEIXA A GLÓRIA DE DEUS BRILHAR EM TEU ROSTO, \nDEIXA A GLÓRIA DE DEUS BRILHAR.\n\nFOI LÁ NO CUME DO MONTE QUE O \nNOSSO DEUS COM MOISÉS FALAVA;\nQUANDO ELE DESCEU DO MONTE \nNÃO SABIA QUE SEU ROSTO BRILHAVA,\nBRILHAVA, BRILHAVA, O SEU ROSTO BRILHAVA;\nFOI LÁ NO CUME DO MONTE <bis>\nSINAI QUE O NOSSO DEUS<bis>\nCOM MOISÉS FALAVA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (751, 'EU LOUVAREI, EU LOUVAREI', 'EU LOUVAREI, EU LOUVAREI', 'EU LOUVAREI, EU LOUVAREI,\nEU LOUVAREI AO MEU SENHOR. \n\nJOÃO VIU O NÚMERO DOS REDIMIDOS\nE TODOS LOUVAVAM AO SENHOR;\nUNS CANTAVAM, OUTROS ORAVAM\nE TODOS LOUVAVAM AO SENHOR.\n\nEU LOUVAREI, EU LOUVAREI, EU LOUVAREI AO MEU SENHOR', 'EU LOUVAREI, EU LOUVAREI,<bis>\nEU LOUVAREI AO MEU SENHOR. <bis>\n\nJOÃO VIU O NÚMERO DOS REDIMIDOS\nE TODOS LOUVAVAM AO SENHOR;\nUNS CANTAVAM, OUTROS ORAVAM\nE TODOS LOUVAVAM AO SENHOR.\n\nEU LOUVAREI, EU LOUVAREI, EU LOUVAREI AO MEU SENHOR', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (752, 'ESTOU ALEGRE', 'ESTOU ALEGRE', 'ESTOU ALEGRE, ALEGRE, MUI ALEGRE,\nESTOU ALEGRE, ALEGRE EU ESTOU,\nESTOU ALEGRE, ALEGRE, MUI ALEGRE,\nESTOU ALEGRE PORQUE CRISTO ME SALVOU.\n\nPOR ISSO EU CANTO, EU CANTO ALELUIA,\nPOR ISSO EU CANTO, EU CANTO GLÓRIA A DEUS,\nPOR ISSO EU CANTO, EU CANTO ALELUIA,\nPOR ISSO EU CANTO PORQUE CRISTO ME SALVOU.\n\nNÃO SOU DO MUNDO, \nDO MUNDO EU NÃO SOU,\nNÃO SOU DO MUNDO PORQUE \nCRISTO ME SALVOU.\n\nVOU PARA O CÉU E PARA O CÉU EU VOU,\nVOU PARA O CÉU E PARA O CÉU EU VOU,\nVOU PARA O CÉU E PARA O CÉU EU VOU,\nVOU PARA O CÉU PORQUE \nCRISTO ME SALVOU.\n\n3X', 'ESTOU ALEGRE, ALEGRE, MUI ALEGRE,\nESTOU ALEGRE, ALEGRE EU ESTOU,\nESTOU ALEGRE, ALEGRE, MUI ALEGRE,\nESTOU ALEGRE PORQUE CRISTO ME SALVOU.\n\nPOR ISSO EU CANTO, EU CANTO ALELUIA,\nPOR ISSO EU CANTO, EU CANTO GLÓRIA A DEUS,\nPOR ISSO EU CANTO, EU CANTO ALELUIA,\nPOR ISSO EU CANTO PORQUE CRISTO ME SALVOU.\n\nNÃO SOU DO MUNDO, \nDO MUNDO EU NÃO SOU,\nNÃO SOU DO MUNDO PORQUE \nCRISTO ME SALVOU.\n\nVOU PARA O CÉU E PARA O CÉU EU VOU,\nVOU PARA O CÉU E PARA O CÉU EU VOU,\nVOU PARA O CÉU E PARA O CÉU EU VOU,\nVOU PARA O CÉU PORQUE \nCRISTO ME SALVOU.\n\n<bis tipo=''3''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (753, 'A NOIVA É A IGREJA', 'A NOIVA É A IGREJA', 'A NOIVA É A IGREJA, \nO NOIVO É JESUS \n\nA NOIVA VAI SUBIR\nREVESTIDA DE PODER,\nDE PUREZA E SANTIDADE, \nDE AMOR E ESPLENDOR.', 'A NOIVA É A IGREJA, <bis>\nO NOIVO É JESUS <bis>\n\nA NOIVA VAI SUBIR<bis>\nREVESTIDA DE PODER,<bis>\nDE PUREZA E SANTIDADE, <bis>\nDE AMOR E ESPLENDOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (754, 'EU VEREI A ÁRVORE DA VIDA', 'EU VEREI A ÁRVORE DA VIDA', 'EU VEREI A ÁRVORE DA VIDA,\nEU VEREI O MEU LINDO PAÍS,\nEU VEREI AS PEDRAS PRECIOSAS,\nEU VEREI AS MAIS BELAS MANSÕES,\nEU VEREI MILHÕES DE ANJOS CANTANDO,\nEU VEREI O MEU AMADO JESUS,\nEU VEREI O LINDO CORO CELESTIAL\nLOUVANDO O GRANDE REI JESUS.\n\nEU VEREI A ÁRVORE DA VIDA,\nEU VEREI O MEU LINDO PAÍS,\nEU VEREI AS PEDRAS PRECIOSAS,\nEU VEREI AS MAIS BELAS MANSÕES,\nEU VEREI MILHÕES DE ANJOS CANTANDO,\nEU VEREI O MEU AMADO JESUS,\nEU VEREI O LINDO CORO CELESTIAL\nLOUVANDO O GRANDE REI JESUS.\n\n\n\n\nFINAL: \nEU VEREI O LINDO CORO CELESTIAL\nLOUVANDO O GRANDE REI JESUS.', 'EU VEREI A ÁRVORE DA VIDA,\nEU VEREI O MEU LINDO PAÍS,\nEU VEREI AS PEDRAS PRECIOSAS,\nEU VEREI AS MAIS BELAS MANSÕES,\nEU VEREI MILHÕES DE ANJOS CANTANDO,\nEU VEREI O MEU AMADO JESUS,\nEU VEREI O LINDO CORO CELESTIAL\nLOUVANDO O GRANDE REI JESUS.\n\nEU VEREI A ÁRVORE DA VIDA,\nEU VEREI O MEU LINDO PAÍS,\nEU VEREI AS PEDRAS PRECIOSAS,\nEU VEREI AS MAIS BELAS MANSÕES,\nEU VEREI MILHÕES DE ANJOS CANTANDO,\nEU VEREI O MEU AMADO JESUS,\nEU VEREI O LINDO CORO CELESTIAL\nLOUVANDO O GRANDE REI JESUS.\n\n\n\n\n<final>EU VEREI O LINDO CORO CELESTIAL\nLOUVANDO O GRANDE REI JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (755, 'SOMENTE PELA FÉ A OBRA DE DEUS', 'SOMENTE PELA FÉ A OBRA DE DEUS', 'CORO\nSOMENTE PELA FÉ, SOMENTE PELA FÉ\nA OBRA DE DEUS VAI CRESCENDO\nSOMENTE PELA FÉ.\n\nOS ENFERMOS SÃO CURADOS, \nSOMENTE PELA FÉ;\nOS MORTOS RESSUSCITADOS,\nSOMENTE PELA FÉ.\n\nCORO\nSOMENTE PELA FÉ, SOMENTE PELA FÉ\nA OBRA DE DEUS VAI CRESCENDO\nSOMENTE PELA FÉ.\n\nATÉ OS CEGOS JÁ VÊEM, \nSOMENTE PELA FÉ;\nPELO PODER DE JESUS,\nSOMENTE PELA FÉ.\n\nCORO\nSOMENTE PELA FÉ, SOMENTE PELA FÉ\nA OBRA DE DEUS VAI CRESCENDO\nSOMENTE PELA FÉ.', '<coro>\nSOMENTE PELA FÉ, SOMENTE PELA FÉ<bis>\nA OBRA DE DEUS VAI CRESCENDO<bis>\nSOMENTE PELA FÉ.<bis>\n\nOS ENFERMOS SÃO CURADOS, \nSOMENTE PELA FÉ;\nOS MORTOS RESSUSCITADOS,\nSOMENTE PELA FÉ.\n\n<coro>\nSOMENTE PELA FÉ, SOMENTE PELA FÉ\nA OBRA DE DEUS VAI CRESCENDO\nSOMENTE PELA FÉ.\n\nATÉ OS CEGOS JÁ VÊEM, \nSOMENTE PELA FÉ;\nPELO PODER DE JESUS,\nSOMENTE PELA FÉ.\n\n<coro>\nSOMENTE PELA FÉ, SOMENTE PELA FÉ\nA OBRA DE DEUS VAI CRESCENDO\nSOMENTE PELA FÉ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (756, 'QUEM CANTAR AQUI SE ALEGRARÁ', 'QUEM CANTAR AQUI SE ALEGRARÁ', 'QUEM CANTAR AQUI SE ALEGRARÁ! (BIS)\nQUEM CANTAR GLÓRIA A JESUS\nSUA VIDA ELE CONDUZ,\nCANTAREI EM SEU LOUVOR,\nE OS ENFERMOS SÃO CURADOS\nNA PRESENÇA DO SENHOR.', 'QUEM CANTAR AQUI SE ALEGRARÁ! <bis>\nQUEM CANTAR GLÓRIA A JESUS\nSUA VIDA ELE CONDUZ,\nCANTAREI EM SEU LOUVOR,<bis>\nE OS ENFERMOS SÃO CURADOS<bis>\nNA PRESENÇA DO SENHOR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (757, 'COMO ACONTECEU EM JERUSALÉM', 'COMO ACONTECEU EM JERUSALÉM', 'COMO ACONTECEU EM JERUSALÉM, \nAOS SEUS DISCÍPULOS DEUS MANDOU PODER,\nOH! MANDA JÁ PODER A NÓS TAMBÉM \nPOR ISSO DAMOS GLÓRIA, GLÓRIA COM PODER.\n\nCORO\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS (BIS)\nGLÓRIA, GLÓRIA, GLÓRIA COM PODER\nGLÓRIA, GLÓRIA, O FOGO VAI DESCER.\n\nA NOSSA IGREJA VAI ESTREMECER\nQUANDO O PODER DE DEUS AQUI DESCER;\nE QUANDO O FOGO SANTO AQUI CAIR,\nA VOZ DE CRISTO TODOS VÃO OUVIR.\n\nCORO\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS (BIS)\nGLÓRIA, GLÓRIA, GLÓRIA COM PODER\nGLÓRIA, GLÓRIA, O FOGO VAI DESCER.\n\nINSTRUMENTOS\n\nCORO\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS (BIS)\nGLÓRIA, GLÓRIA, GLÓRIA COM PODER\nGLÓRIA, GLÓRIA, O FOGO VAI DESCER.', 'COMO ACONTECEU EM JERUSALÉM, \nAOS SEUS DISCÍPULOS DEUS MANDOU PODER,\nOH! MANDA JÁ PODER A NÓS TAMBÉM \nPOR ISSO DAMOS GLÓRIA, GLÓRIA COM PODER.\n\n<coro>\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS <bis>\nGLÓRIA, GLÓRIA, GLÓRIA COM PODER\nGLÓRIA, GLÓRIA, O FOGO VAI DESCER.\n\nA NOSSA IGREJA VAI ESTREMECER\nQUANDO O PODER DE DEUS AQUI DESCER;\nE QUANDO O FOGO SANTO AQUI CAIR,\nA VOZ DE CRISTO TODOS VÃO OUVIR.\n\n<coro>\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS <bis>\nGLÓRIA, GLÓRIA, GLÓRIA COM PODER\nGLÓRIA, GLÓRIA, O FOGO VAI DESCER.\n<instrumentos>\n\n\n<coro>\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS <bis>\nGLÓRIA, GLÓRIA, GLÓRIA COM PODER\nGLÓRIA, GLÓRIA, O FOGO VAI DESCER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (758, 'ESTA ALEGRIA NÃO VAI MAIS SAIR', 'ESTA ALEGRIA NÃO VAI MAIS SAIR', 'ESTA ALEGRIA NÃO VAI MAIS SAIR (3X)\nDE DENTRO DO MEU CORAÇÃO.\n\nO FOGO CAI, O FOGO CAI,\nO SALVO EM CRISTO SABE \nPARA ONDE VAI.\n\nREPETIR O HINO', 'ESTA ALEGRIA NÃO VAI MAIS SAIR <bis tipo=''3''>\nDE DENTRO DO MEU CORAÇÃO.\n\nO FOGO CAI, O FOGO CAI,<bis>\nO SALVO EM CRISTO SABE <bis>\nPARA ONDE VAI.<bis>\n\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (759, 'NUNCA MAIS, NUNCA MAIS', 'NUNCA MAIS, NUNCA MAIS', 'NUNCA MAIS, NUNCA MAIS DEIXAREI JESUS;\nNUNCA MAIS, NUNCA MAIS DEIXAREI A CRUZ.\nEU TENHO A CERTEZA EM MEU CORAÇÃO\nDE AO CHEGAR AO CÉU RECEBER MEU GALARDÃO.\n\nREPETIR O HINO', 'NUNCA MAIS, NUNCA MAIS DEIXAREI JESUS;\nNUNCA MAIS, NUNCA MAIS DEIXAREI A CRUZ.\nEU TENHO A CERTEZA EM MEU CORAÇÃO\nDE AO CHEGAR AO CÉU RECEBER MEU GALARDÃO.\n\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (760, 'DO CÉU VIRÁ', 'DO CÉU VIRÁ', 'DO CÉU VIRÁ, SIM, SIM, DO CÉU VIRÁ.\nSIM, A BÊNÇÃO DO SENHOR DO CÉU VIRÁ;\nQUANDO OS CRENTES REUNIDOS \nSEUNIREM PARA ORAR.\nSIM, A BÊNÇÃO DO SENHOR DO CÉU VIRÁ.\n\nREPETIR O HINO', 'DO CÉU VIRÁ, SIM, SIM, DO CÉU VIRÁ.\nSIM, A BÊNÇÃO DO SENHOR DO CÉU VIRÁ;\nQUANDO OS CRENTES REUNIDOS \nSEUNIREM PARA ORAR.\nSIM, A BÊNÇÃO DO SENHOR DO CÉU VIRÁ.\n\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (761, 'CADA PASSO QUE DÁS', 'CADA PASSO QUE DÁS', 'CADA PASSO QUE DÁS, \nPELAS SENDAS ONDE VAIS,\nHÁ UM DEUS QUE TE VÊ.\n\nDEUS TE VÊ, DEUS TE VÊ.\nOLHA BEM PELAS SENDAS ONDE VAIS.\nDEUS TE VÊ, DEUS TE VÊ.\nENGANÁ-LO JAMAIS PODERÁS.', 'CADA PASSO QUE DÁS, <bis>\nPELAS SENDAS ONDE VAIS,<bis>\nHÁ UM DEUS QUE TE VÊ.<bis>\n<bis>\nDEUS TE VÊ, DEUS TE VÊ.\nOLHA BEM PELAS SENDAS ONDE VAIS.\nDEUS TE VÊ, DEUS TE VÊ.\nENGANÁ-LO JAMAIS PODERÁS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (762, 'O CÉU É UM LUGAR MARAVILHOSO', 'O CÉU É UM LUGAR MARAVILHOSO', 'O CÉU É UM LUGAR MARAVILHOSO,\nCHEIO DE GLÓRIA E GOZO!\nEU QUERO VER O MEU SALVADOR:\nO CÉU É UM LUGAR MARAVILHOSO.\n\nO CÉU É UM LUGAR MARAVILHOSO,\nCHEIO DE GLÓRIA E GOZO!\nEU QUERO VER O MEU SALVADOR:\nO CÉU É UM LUGAR, \nLUGAR PRA ONDE VOU;\nO CÉU É UM LUGAR MARAVILHOSO.', 'O CÉU É UM LUGAR MARAVILHOSO,\nCHEIO DE GLÓRIA E GOZO!\nEU QUERO VER O MEU SALVADOR:\nO CÉU É UM LUGAR MARAVILHOSO.\n\nO CÉU É UM LUGAR MARAVILHOSO,\nCHEIO DE GLÓRIA E GOZO!\nEU QUERO VER O MEU SALVADOR:\nO CÉU É UM LUGAR, \nLUGAR PRA ONDE VOU;\nO CÉU É UM LUGAR MARAVILHOSO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (763, 'JESUS É TUDO PRA MIM', 'JESUS É TUDO PRA MIM', 'JESUS É TUDO PRA MIM. \nELE É TUDO PRA MIM.\nJESUS É O TESOURO QUE EU \nTENHO GUARDADO NO PEITO,\nELE É TUDO PRA MIM.\n\nREPETIR O HINO', 'JESUS É TUDO PRA MIM.\nELE É TUDO PRA MIM.\nJESUS É O TESOURO QUE EU <bis>\nTENHO GUARDADO NO PEITO,<bis>\nELE É TUDO PRA MIM.<bis>\n\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (764, 'NÓS VAMOS LÁ, IRMÃOS', 'NÓS VAMOS LÁ, IRMÃOS', 'NÓS VAMOS LÁ IRMÃOS, \nNÓS VAMOS LÁ \nA JERUSALÉM DE DEUS.\nMAS É COM GLÓRIA E ALELUIA\nQUE NÓS VAMOS ALI CHEGAR.\n\nMAS É COM GLÓRIA, GLÓRIA,\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS.\nMAS É COM GLÓRIA E ALELUIA\nQUE NÓS VAMOS ALI CHEGAR.', 'NÓS VAMOS LÁ IRMÃOS, \nNÓS VAMOS LÁ \nA JERUSALÉM DE DEUS.\nMAS É COM GLÓRIA E ALELUIA<bis>\nQUE NÓS VAMOS ALI CHEGAR.<bis>\n\nMAS É COM GLÓRIA, GLÓRIA,\nGLÓRIA, GLÓRIA, GLÓRIA A JESUS.\nMAS É COM GLÓRIA E ALELUIA<bis>\nQUE NÓS VAMOS ALI CHEGAR.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (765, 'LÁ NO CÉU TODOS CANTAM ALELUIA!', 'LÁ NO CÉU TODOS CANTAM ALELUIA!', 'LÁ NO CÉU TODOS CANTAM ALELUIA!\nLÁ NO CÉU TODOS CANTAM ALELUIA!\nLÁ NO CÉU TODOS CANTAM ALELUIA!\nEU TAMBÉM VOU PRA LÁ CANTAR.\n\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.\n\nLÁ NO CÉU TODOS CANTAM ALELUIA!\nLÁ NO CÉU TODOS CANTAM ALELUIA!\nLÁ NO CÉU TODOS CANTAM ALELUIA!\nEU TAMBÉM VOU PRA LÁ CANTAR.\n\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.', 'LÁ NO CÉU TODOS CANTAM ALELUIA!<bis>\nLÁ NO CÉU TODOS CANTAM ALELUIA!<bis>\nLÁ NO CÉU TODOS CANTAM ALELUIA!<bis>\nEU TAMBÉM VOU PRA LÁ CANTAR.<bis>\n\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.\n\nLÁ NO CÉU TODOS CANTAM ALELUIA!<bis>\nLÁ NO CÉU TODOS CANTAM ALELUIA!<bis>\nLÁ NO CÉU TODOS CANTAM ALELUIA!<bis>\nEU TAMBÉM VOU PRA LÁ CANTAR.<bis>\n\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.\nALELUIA, VOU PARA O CÉU \nCOM JESUS CANTAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (766, 'NO DIA DA GRANDE GLÓRIA', 'NO DIA DA GRANDE GLÓRIA', 'NO DIA DA GRANDE GLÓRIA\nHAVEMOS DE IR CANTAR LÁ NO CÉU.\nHAVEMOS DE ENCONTRAR-NOS\nALÉM DO JORDÃO, QUE ALEGRIA, \nQUE BOM!\n\nSE TU CHEGARES PRIMEIRO QUE EU\nAVISA QUE EU TAMBÉM CHEGO LÁ.\nHAVEMOS DE ENCONTRAR-NOS\nALÉM DO JORDÃO, \nQUE ALEGRIA SERÁ!\n\nHAVEMOS DE ENCONTRAR-NOS\nALÉM DO JORDÃO, QUE BELO SERÁ!\nHAVEMOS DE ENCONTRAR-NOS\nTAMBÉM COM JESUS \nQUE ALEGRIA SERÁ!\n\nLÁ NÃO VAI HAVER TRISTEZA;\nO PRANTO E A DOR LÁ NÃO TEM LUGAR!\nHAVEMOS DE ENCONTRAR-NOS\nCOM CRISTO NO CÉU \nQUE ALEGRIA SERÁ!', 'NO DIA DA GRANDE GLÓRIA\nHAVEMOS DE IR CANTAR LÁ NO CÉU.\nHAVEMOS DE ENCONTRAR-NOS\nALÉM DO JORDÃO, QUE ALEGRIA, \nQUE BOM!\n\nSE TU CHEGARES PRIMEIRO QUE EU\nAVISA QUE EU TAMBÉM CHEGO LÁ.\nHAVEMOS DE ENCONTRAR-NOS\nALÉM DO JORDÃO, \nQUE ALEGRIA SERÁ!\n\nHAVEMOS DE ENCONTRAR-NOS\nALÉM DO JORDÃO, QUE BELO SERÁ!\nHAVEMOS DE ENCONTRAR-NOS\nTAMBÉM COM JESUS \nQUE ALEGRIA SERÁ!\n\nLÁ NÃO VAI HAVER TRISTEZA;\nO PRANTO E A DOR LÁ NÃO TEM LUGAR!\nHAVEMOS DE ENCONTRAR-NOS\nCOM CRISTO NO CÉU \nQUE ALEGRIA SERÁ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (767, 'CONTA PRA JESUS ONDE É A TUA DOR', 'CONTA PRA JESUS ONDE É A TUA DOR', 'CONTA PRA JESUS ONDE É A TUA DOR.\nELE TE AJUDA A CARREGAR A CRUZ.\nCOM INSISTÊNCIA ORA, \nQUE TU VAIS VENCER:\nO QUE TU PRECISAS CONTA PRA JESUS!\n\nSE DESANIMARES COM A TUA CRUZ\nLEMBRA QUE MAIOR LEVOU O MEU JESUS.\nCOM INSISTÊNCIA ORA, ELE VAI TE OUVIR:\nO QUE TU PRECISAS CONTA PRA JESUS!\n\nSE EM LÍNGUA ESTRANHA AINDA\nNÃO FALASTE, COM DEUS EM \nMISTÉRIOS PODES CONVERSAR.\nE O ESPÍRITO SANTO, TOMARÁ TEU SER:\nO QUE TU PRECISAS CONTA PRA JESUS!', 'CONTA PRA JESUS ONDE É A TUA DOR.\nELE TE AJUDA A CARREGAR A CRUZ.\nCOM INSISTÊNCIA ORA, \nQUE TU VAIS VENCER:\nO QUE TU PRECISAS CONTA PRA JESUS!\n\nSE DESANIMARES COM A TUA CRUZ\nLEMBRA QUE MAIOR LEVOU O MEU JESUS.\nCOM INSISTÊNCIA ORA, ELE VAI TE OUVIR:\nO QUE TU PRECISAS CONTA PRA JESUS!\n\nSE EM LÍNGUA ESTRANHA AINDA\nNÃO FALASTE, COM DEUS EM \nMISTÉRIOS PODES CONVERSAR.\nE O ESPÍRITO SANTO, TOMARÁ TEU SER:\nO QUE TU PRECISAS CONTA PRA JESUS!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (768, 'A VITÓRIA DESTA IGREJA É ORAÇÃO', 'A VITÓRIA DESTA IGREJA É ORAÇÃO', 'A VITÓRIA DESTA IGREJA É ORAÇÃO.\nA VITÓRIA DESTA IGREJA É ORAÇÃO.\nJESUS ATENDE TODA NOSSA PETIÇÃO;\nDESPERTA AGORA TU QUE DORMES\nMEU IRMÃO.\n\nVAMOS ORAR TODOS CRENTES DESTA IGREJA\nPARA QUE JESUS AO NOSSO LADO SEMPRE ESTEJA.\n\nJESUS EM BREVE VEM BUSCAR A SUA IGREJA, \nPOIS QUEM NÃO ORA JÁ ESTÁ FORA DA PELEJA.', 'A VITÓRIA DESTA IGREJA É ORAÇÃO.\nA VITÓRIA DESTA IGREJA É ORAÇÃO.\nJESUS ATENDE TODA NOSSA PETIÇÃO;\nDESPERTA AGORA TU QUE DORMES\nMEU IRMÃO.\n\nVAMOS ORAR TODOS CRENTES DESTA IGREJA\nPARA QUE JESUS AO NOSSO LADO SEMPRE ESTEJA.\n\nJESUS EM BREVE VEM BUSCAR A SUA IGREJA, <bis>\nPOIS QUEM NÃO ORA JÁ ESTÁ FORA DA PELEJA.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (769, 'O GRANDE RELÓGIO', 'O GRANDE RELÓGIO', 'O GRANDE RELÓGIO JÁ DEU O SINAL:\nDESPERTA QUE É HORA, \nVAMOS TRABALHAR EM BUSCA \nDAS ALMAS PERDIDAS QUE \nESTÃO FALANDO BEM ALTO \nAO SEU CORAÇÃO.\n\nCORO (2X)\nDESPERTA QUE É HORA, \nO MESTRE JÁ VEM, JÁ VEM \nEM CAMINHO DE JERUSALÉM!\n\nA LUZ SE APAGA O DIA FINAL\nNÃO OLHES ATRÁS, POIS É TEMPO AINDA.\nNÃO TE DETENHAS, POIS JESUS TE CHAMA.\nELE TE QUER E AINDA TE AMA.\n\nCORO (2X)\nDESPERTA QUE É HORA, \nO MESTRE JÁ VEM, JÁ VEM \nEM CAMINHO DE JERUSALÉM!\n\nJESUS É O CAMINHO, A VERDADE E A VIDA.\nNINGUÉM VAI AO PAI A NÃO SER POR JESUS.\nLÁ NO CÉU SÓ ENTRA QUEM FOR\nENCONTRADO, LAVADO NO SANGUE\nVERTIDO NA CRUZ.\n\nCORO (2X)\nDESPERTA QUE É HORA, \nO MESTRE JÁ VEM, JÁ VEM \nEM CAMINHO DE JERUSALÉM!', 'O GRANDE RELÓGIO JÁ DEU O SINAL:\nDESPERTA QUE É HORA, \nVAMOS TRABALHAR EM BUSCA \nDAS ALMAS PERDIDAS QUE \nESTÃO FALANDO BEM ALTO \nAO SEU CORAÇÃO.\n\n<coro tipo=''2X''>\nDESPERTA QUE É HORA, \nO MESTRE JÁ VEM, JÁ VEM \nEM CAMINHO DE JERUSALÉM!\n\nA LUZ SE APAGA O DIA FINAL\nNÃO OLHES ATRÁS, POIS É TEMPO AINDA.\nNÃO TE DETENHAS, POIS JESUS TE CHAMA.\nELE TE QUER E AINDA TE AMA.\n\n<coro tipo=''2X''>\nDESPERTA QUE É HORA, \nO MESTRE JÁ VEM, JÁ VEM \nEM CAMINHO DE JERUSALÉM!\n\nJESUS É O CAMINHO, A VERDADE E A VIDA.\nNINGUÉM VAI AO PAI A NÃO SER POR JESUS.\nLÁ NO CÉU SÓ ENTRA QUEM FOR\nENCONTRADO, LAVADO NO SANGUE\nVERTIDO NA CRUZ.\n\n<coro tipo=''2X''>\nDESPERTA QUE É HORA, \nO MESTRE JÁ VEM, JÁ VEM \nEM CAMINHO DE JERUSALÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (770, 'POR QUE DEIXAR QUE AS ÂNSIAS', 'POR QUE DEIXAR QUE AS ÂNSIAS', 'POR QUE DEIXAR QUE AS ÂNSIAS \nDO FUTURO PERTURBEM HOJE A \nPAZ DO CORAÇÃO?\nO PAI QUE NUTRE OS FRÁGEIS PASSARINHOS, \nGARANTE A TUA PROVISÃO.\n\nPOIS SABE E CUIDA E SEMPRE TE AJUDA;\nO PAI QUE NUTRE OS FRÁGEIS PASSARINHOS, \nGARANTE A TUA PROVISÃO.', 'POR QUE DEIXAR QUE AS ÂNSIAS \nDO FUTURO PERTURBEM HOJE A \nPAZ DO CORAÇÃO?\nO PAI QUE NUTRE OS FRÁGEIS PASSARINHOS, \nGARANTE A TUA PROVISÃO.\n\nPOIS SABE E CUIDA E SEMPRE TE AJUDA;\nO PAI QUE NUTRE OS FRÁGEIS PASSARINHOS, \nGARANTE A TUA PROVISÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (771, 'CAMINHANDO VOU PARA CANAÃ', 'CAMINHANDO VOU PARA CANAÃ', 'CAMINHANDO VOU PARA CANAÃ.\nCAMINHANDO VOU PARA CANAÃ.\nCAMINHANDO VOU PARA CANAÃ.\nGLÓRIA A DEUS,\nCAMINHANDO VOU PARA CANAÃ.\n\nCORO\nSE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM;\nSE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM;\nSE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM; \nGLÓRIA A DEUS,\nCAMINHANDO VOU PARA CANAÃ.\n\nCAMINHANDO VOU ABRAÇAR JESUS.\nCAMINHANDO VOU ABRAÇAR JESUS.\nCAMINHANDO VOU ABRAÇAR JESUS.\nGLÓRIA A DEUS,\nCAMINHANDO VOU ABRAÇAR JESUS.', 'CAMINHANDO VOU PARA CANAÃ.\nCAMINHANDO VOU PARA CANAÃ.\nCAMINHANDO VOU PARA CANAÃ.\nGLÓRIA A DEUS,\nCAMINHANDO VOU PARA CANAÃ.\n\n<coro>\nSE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM;\nSE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM;\nSE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM; \nGLÓRIA A DEUS,\nCAMINHANDO VOU PARA CANAÃ.\n\nCAMINHANDO VOU ABRAÇAR JESUS.\nCAMINHANDO VOU ABRAÇAR JESUS.\nCAMINHANDO VOU ABRAÇAR JESUS.\nGLÓRIA A DEUS,\nCAMINHANDO VOU ABRAÇAR JESUS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (772, 'CADA DIA ME DIRIGE', 'CADA DIA ME DIRIGE', 'CADA DIA ME DIRIGE, \nCADA DIA ME PROTEGE. \nCADA DIA, SINTO SEU AMOR \nPOR MIM, ALELUIA!\nCADA DIA BOAS NOVAS,\nCADA DIA VEJO A PROVA\nDO PODER DO GRANDE AMOR\nDO MEU SENHOR E REI.', 'CADA DIA ME DIRIGE, <bis>\nCADA DIA ME PROTEGE. <bis>\nCADA DIA, SINTO SEU AMOR <bis>\nPOR MIM, ALELUIA!<bis>\nCADA DIA BOAS NOVAS,<bis>\nCADA DIA VEJO A PROVA<bis>\nDO PODER DO GRANDE AMOR<bis>\nDO MEU SENHOR E REI.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (773, 'ABRA A PORTA, VENHA VER!', 'ABRA A PORTA, VENHA VER!', 'ABRA A PORTA, VENHA VER\nOS MENSAGEIROS DO SENHOR\nQUE ANUNCIAM A PALAVRA, \nDE DEUS E SEU AMOR!\n\nABRA A PORTA E TAMBÉM O CORAÇÃO,\nPORQUE ENTRE NÓS ESTÁ JESUS,\nQUE OUTORGA A SALVAÇÃO.\nGLÓRIA A JESUS!', 'ABRA A PORTA, VENHA VER<bis>\nOS MENSAGEIROS DO SENHOR<bis>\nQUE ANUNCIAM A PALAVRA, <bis>\nDE DEUS E SEU AMOR!<bis>\n<bis>\nABRA A PORTA E TAMBÉM O CORAÇÃO,<bis>\nPORQUE ENTRE NÓS ESTÁ JESUS,<bis>\nQUE OUTORGA A SALVAÇÃO.<bis>\nGLÓRIA A JESUS!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (774, 'CHEGADO A CRUZ DO MEU SALVADOR', 'CHEGADO A CRUZ DO MEU SALVADOR', 'CHEGADO A CRUZ DO MEU SALVADOR,\nPROSTRADO AOS PÉS DO MEU REDENTOR.\nELE ATENDEU AO MEU CLAMOR:\nGLÓRIA AO SALVADOR!\n\nCORO\nGLÓRIA AO SALVADOR, \nGLÓRIA AO SALVADOR!\nAGORA SEI QUE ELE ME SALVOU:\nGLÓRIA AO SALVADOR!\n\nQUE MARAVILHA, JESUS ME AMOU!\nTUDO DE GRAÇA ME PERDOOU.\nQUEBROU MEUS LAÇOS E ME \nLIVROU: GLÓRIA AO SALVADOR!', 'CHEGADO A CRUZ DO MEU SALVADOR,\nPROSTRADO AOS PÉS DO MEU REDENTOR.\nELE ATENDEU AO MEU CLAMOR:\nGLÓRIA AO SALVADOR!\n\n<coro>\nGLÓRIA AO SALVADOR, \nGLÓRIA AO SALVADOR!\nAGORA SEI QUE ELE ME SALVOU:\nGLÓRIA AO SALVADOR!\n\nQUE MARAVILHA, JESUS ME AMOU!\nTUDO DE GRAÇA ME PERDOOU.\nQUEBROU MEUS LAÇOS E ME \nLIVROU: GLÓRIA AO SALVADOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (775, 'SUBINDO PARA O CÉU EU VOU', 'SUBINDO PARA O CÉU EU VOU', 'SUBINDO, SUBINDO, \nSUBINDO PARA O CÉU EU VOU.\nSUBINDO, SUBINDO,\nSUBINDO PARA O CÉU EU VOU.\nTRISTEZA NÃO VAI COMIGO\nPORQUE JESUS CRISTO ME SALVOU.\nJOGUEI A TRISTEZA FORA E COM\nJESUS PARA O CÉU EU VOU!\n\nREPETIR O HINO', 'SUBINDO, SUBINDO, \nSUBINDO PARA O CÉU EU VOU.\nSUBINDO, SUBINDO,\nSUBINDO PARA O CÉU EU VOU.\nTRISTEZA NÃO VAI COMIGO\nPORQUE JESUS CRISTO ME SALVOU.\nJOGUEI A TRISTEZA FORA E COM\nJESUS PARA O CÉU EU VOU!\n\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (776, 'CERTA VEZ EU ORANDO', 'CERTA VEZ EU ORANDO', 'CERTA VEZ EU ORANDO, OUVI UMA VOZ,\nESTA VOZ ME DIZIA: ''NÃO PEQUES MAIS.''\nJESUS CRISTO JÁ VEM EM UMA NUVEM BRANCA,\nJESUS CRISTO JÁ VEM, JESUS CRISTO JÁ VEM,\nNÃO PEQUES MAIS.', 'CERTA VEZ EU ORANDO, OUVI UMA VOZ,\nESTA VOZ ME DIZIA: ''NÃO PEQUES MAIS.''\nJESUS CRISTO JÁ VEM EM UMA NUVEM BRANCA,\nJESUS CRISTO JÁ VEM, JESUS CRISTO JÁ VEM,\nNÃO PEQUES MAIS.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (777, 'COMO AS ÁGUAS', 'COMO AS ÁGUAS', '''COMO AS ÁGUAS COBREM O MAR,\nO CONHECIMENTO DA MINHA GLÓRIA\nHÁ DE ENCHER TODA A TERRA'',\nDIZ O SENHOR, DIZ O SENHOR.\nREPETIR O HINO', '''COMO AS ÁGUAS COBREM O MAR,\nO CONHECIMENTO DA MINHA GLÓRIA\nHÁ DE ENCHER TODA A TERRA'',\nDIZ O SENHOR, DIZ O SENHOR.\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (778, 'DEUS ESTÁ AQUI', 'DEUS ESTÁ AQUI', 'DEUS ESTÁ AQUI, QUÃO GLORIOSO É!\nELE PROMETEU, ONDE HÁ DOIS OU TRÊS.\nFICA, SENHOR, FICA, SENHOR,\nFICA, SENHOR, AQUI.\n\n\nÓ CRISTO MEU, FAZE DE MIM UM ALTAR,\nPARA ADORAR-TE COM DEVOÇÃO,\nPARA BEBER DA ÁGUA DA VIDA\nE SACIAR, SENHOR, MEU CORAÇÃO.\n\n\nFICA, SENHOR, FICA, SENHOR, \nFICA, SENHOR, AQUI.', 'DEUS ESTÁ AQUI, QUÃO GLORIOSO É!\nELE PROMETEU, ONDE HÁ DOIS OU TRÊS.\nFICA, SENHOR, FICA, SENHOR,\nFICA, SENHOR, AQUI.\n\n\nÓ CRISTO MEU, FAZE DE MIM UM ALTAR,\nPARA ADORAR-TE COM DEVOÇÃO,\nPARA BEBER DA ÁGUA DA VIDA\nE SACIAR, SENHOR, MEU CORAÇÃO.\n\n\nFICA, SENHOR, FICA, SENHOR, <bis>\nFICA, SENHOR, AQUI. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (779, 'ABRE A PORTA DO TEU CORAÇÃO', 'ABRE A PORTA DO TEU CORAÇÃO', 'ABRE A PORTA DO TEU CORAÇÃO\nE DEIXA CRISTO ENTRAR, ELE TE DARÁ \nSALVAÇÃO, AO CÉU TE LEVARÁ;\nABRE A PORTA DO TEU CORAÇÃO\nE DEIXA CRISTO EM TI HABITAR,\nABRE A PORTA DO TEU CORAÇÃO\nQUE JESUS TE ABENÇOARÁ.\n\nABRE A PORTA, ABRE A PORTA,\nABRE A PORTA DO TEU CORAÇÃO;\nABRE A PORTA, ABRE A PORTA,\nQUE JESUS TE DARÁ SALVAÇÃO.', 'ABRE A PORTA DO TEU CORAÇÃO\nE DEIXA CRISTO ENTRAR, ELE TE DARÁ \nSALVAÇÃO, AO CÉU TE LEVARÁ;\nABRE A PORTA DO TEU CORAÇÃO\nE DEIXA CRISTO EM TI HABITAR,\nABRE A PORTA DO TEU CORAÇÃO\nQUE JESUS TE ABENÇOARÁ.\n\nABRE A PORTA, ABRE A PORTA,\nABRE A PORTA DO TEU CORAÇÃO;\nABRE A PORTA, ABRE A PORTA,\nQUE JESUS TE DARÁ SALVAÇÃO.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (780, 'CANTAREI, CANTAREI AS MISERICÓRDIAS', 'CANTAREI, CANTAREI AS MISERICÓRDIAS', 'CANTAREI, CANTAREI AS MISERICÓRDIAS DO SENHOR,\nCANTAREI, CANTAREI AS MISERICÓRDIAS DO SENHOR;\nREVELADAS EM JESUS, CUJA MORTE LÁ NA CRUZ\nNOS TIROU DA PERDIÇÃO COM ETERNA SALVAÇÃO;\nCANTAREI, CANTAREI AS MISERICÓRDIAS DO SENHOR.', 'CANTAREI, CANTAREI AS MISERICÓRDIAS DO SENHOR,\nCANTAREI, CANTAREI AS MISERICÓRDIAS DO SENHOR;\nREVELADAS EM JESUS, CUJA MORTE LÁ NA CRUZ\nNOS TIROU DA PERDIÇÃO COM ETERNA SALVAÇÃO;\nCANTAREI, CANTAREI AS MISERICÓRDIAS DO SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (781, 'SÓ O PODER DE DEUS', 'SÓ O PODER DE DEUS', 'SÓ O PODER DE DEUS PODE MUDAR TEU SER,\nA PROVA QUE EU TE DOU: ELE MUDOU O MEU;\nNÃO VÊS QUE SOU FELIZ SEGUINDO AO SENHOR?\nNOVA CRIATURA SOU, NOVA SOU!', 'SÓ O PODER DE DEUS PODE MUDAR TEU SER,<bis>\nA PROVA QUE EU TE DOU: ELE MUDOU O MEU;<bis>\nNÃO VÊS QUE SOU FELIZ SEGUINDO AO SENHOR?<bis>\nNOVA CRIATURA SOU, NOVA SOU!<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (782, 'TENHO NOVA VIDA', 'TENHO NOVA VIDA', 'TENHO NOVA VIDA, AGORA SOU FELIZ,\nNUNCA ESTOU SOZINHO, CRISTO MORA EM MIM;\nCANTO COM AMOR, CANTO COM ALEGRIA,\nLOUVANDO SEMPRE A JESUS QUE VIRÁ UM DIA.\n\nTUDO É NOVO EM MIM, TUDO É TÃO BELO,\nSER IGUAL A CRISTO É O QUE MAIS ANELO;\nCANTO COM ALEGRIA, CANTO COM AMOR,\nLOUVANDO SEMPRE A JESUS, \nO MEU SALVADOR.', 'TENHO NOVA VIDA, AGORA SOU FELIZ,\nNUNCA ESTOU SOZINHO, CRISTO MORA EM MIM;\nCANTO COM AMOR, CANTO COM ALEGRIA,\nLOUVANDO SEMPRE A JESUS QUE VIRÁ UM DIA.\n\nTUDO É NOVO EM MIM, TUDO É TÃO BELO,\nSER IGUAL A CRISTO É O QUE MAIS ANELO;\nCANTO COM ALEGRIA, CANTO COM AMOR,\nLOUVANDO SEMPRE A JESUS, \nO MEU SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (783, 'FELIZ, FELIZ EU SOU', 'FELIZ, FELIZ EU SOU', 'FELIZ, FELIZ, EU SOU.\nTÃO LONGE DO SENHOR ANDAVA, NÃO TINHA PAZ;\nO MUNDO ALVOROÇAVA AO MEU REDOR\nATÉ AS BELAS FLORES NÃO TINHAM BELEZA PRA MIM, \nVIVIA TRISTE, ERA INFELIZ.(ERA INFELIZ).\n\nMAS UM DIA A LUZ RAIOU,\nJESUS CRISTO ME ALCANÇOU;\nE AGORA, FELIZ,\nAO LADO DO MEU SENHOR,\nQUERO ANDAR SEGURO\nPOR ONDE EU FOR \n(POR ONDE EU FOR).', 'FELIZ, FELIZ, EU SOU.\nTÃO LONGE DO SENHOR ANDAVA, NÃO TINHA PAZ;\nO MUNDO ALVOROÇAVA AO MEU REDOR\nATÉ AS BELAS FLORES NÃO TINHAM BELEZA PRA MIM, \nVIVIA TRISTE, ERA INFELIZ.(ERA INFELIZ).\n\nMAS UM DIA A LUZ RAIOU,<bis>\nJESUS CRISTO ME ALCANÇOU;<bis>\nE AGORA, FELIZ,<bis>\nAO LADO DO MEU SENHOR,<bis>\nQUERO ANDAR SEGURO<bis>\nPOR ONDE EU FOR <bis>\n(POR ONDE EU FOR).<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (784, 'CANTAI AO SENHOR UM CÂNTICO NOVO', 'CANTAI AO SENHOR UM CÂNTICO NOVO', 'CANTAI AO SENHOR UM CÂNTICO NOVO (3X)\nCANTAI AO SENHOR, CANTAI AO SENHOR!\n\nPORQUE ELE FEZ, ELE FAZ MARAVILHAS (3X)\nCANTAI AO SENHOR, CANTAI AO SENHOR!', 'CANTAI AO SENHOR UM CÂNTICO NOVO <bis tipo=''3''>\nCANTAI AO SENHOR, CANTAI AO SENHOR!\n\nPORQUE ELE FEZ, ELE FAZ MARAVILHAS <bis tipo=''3''>\nCANTAI AO SENHOR, CANTAI AO SENHOR!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (785, 'ESTOU CONFIANDO', 'ESTOU CONFIANDO', 'ESTOU CONFIANDO, SENHOR, EM TI,\nPORQUE SEI QUE TU, MEU PAI, CUIDAS DE MIM;\nAINDA QUE AS LUTAS AUMENTEM O FUROR,\nESTOU CONFIANDO EM TI, SENHOR.', 'ESTOU CONFIANDO, SENHOR, EM TI,\nPORQUE SEI QUE TU, MEU PAI, CUIDAS DE MIM;\nAINDA QUE AS LUTAS AUMENTEM O FUROR,\nESTOU CONFIANDO EM TI, SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (786, 'QUE AS PALAVRAS DA MINHA BOCA', 'QUE AS PALAVRAS DA MINHA BOCA', 'QUE AS PALAVRAS DA MINHA BOCA\nE A MEDITAÇÃO DO MEU CORAÇÃO,\nSEJAM GRATAS DIANTE DE TI, Ó SENHOR. \n\nÓ SENHOR, Ó SENHOR!\nÓ SENHOR, Ó SENHOR!\n\nQUE AS PALAVRAS DA MINHA BOCA\nE A MEDITAÇÃO DO MEU CORAÇÃO,\nSEJAM GRATAS DIANTE DE TI, Ó SENHOR.', 'QUE AS PALAVRAS DA MINHA BOCA<bis>\nE A MEDITAÇÃO DO MEU CORAÇÃO,<bis>\nSEJAM GRATAS DIANTE DE TI, Ó SENHOR. <bis>\n\nÓ SENHOR, Ó SENHOR!\nÓ SENHOR, Ó SENHOR!\n\nQUE AS PALAVRAS DA MINHA BOCA\nE A MEDITAÇÃO DO MEU CORAÇÃO,\nSEJAM GRATAS DIANTE DE TI, Ó SENHOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (787, 'ARDENDO EM FOGO MINH''ALMA ESTÁ', 'ARDENDO EM FOGO MINH''ALMA ESTÁ', 'ARDENDO EM FOGO MINH''ALMA ESTÁ \nARDENDO EM FOGO MINH''ALMA ESTÁ\nGLORIOSA CHAMA ME LIMPARÁ.\nOH! ALELUIA! MINH''ALMA ARDENDO ESTÁ!\n\nOH! SENHOR, QUERO QUE ARDAS EM MEU SER,\nE COMO A SARÇA QUERO ARDER COM TEU PODER, \nEM NOVAS LÍNGUAS VOU FALAR COMO SINAL, \nESTOU ARDENDO COM O FOGO CELESTIAL.\n\nQUERO ADORAR-TE E AMAR-TE SÓ A TI\nCOMO SE ADORA EM ESPÍRITO E EM VERDADE;\nOH! SENHOR, QUERO QUE ARDAS EM MEU SER, \nE COMO A SARÇA QUERO ARDER COM TEU PODER.\n\nARDENDO EM FOGO MINH''ALMA ESTÁ\nARDENDO EM FOGO MINH''ALMA ESTÁ\nGLORIOSA CHAMA ME LIMPARÁ.\nOH! ALELUIA! MINH''ALMA ARDENDO ESTÁ!', 'ARDENDO EM FOGO MINH''ALMA ESTÁ \nARDENDO EM FOGO MINH''ALMA ESTÁ\nGLORIOSA CHAMA ME LIMPARÁ.\nOH! ALELUIA! MINH''ALMA ARDENDO ESTÁ!\n\nOH! SENHOR, QUERO QUE ARDAS EM MEU SER,\nE COMO A SARÇA QUERO ARDER COM TEU PODER, \nEM NOVAS LÍNGUAS VOU FALAR COMO SINAL, \nESTOU ARDENDO COM O FOGO CELESTIAL.\n\nQUERO ADORAR-TE E AMAR-TE SÓ A TI\nCOMO SE ADORA EM ESPÍRITO E EM VERDADE;\nOH! SENHOR, QUERO QUE ARDAS EM MEU SER, \nE COMO A SARÇA QUERO ARDER COM TEU PODER.\n\nARDENDO EM FOGO MINH''ALMA ESTÁ\nARDENDO EM FOGO MINH''ALMA ESTÁ\nGLORIOSA CHAMA ME LIMPARÁ.\nOH! ALELUIA! MINH''ALMA ARDENDO ESTÁ!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (788, 'IGREJA, TU VAIS SUBIR', 'IGREJA, TU VAIS SUBIR', 'IGREJA, TU VAIS SUBIR, (BIS)\nESPERA MAIS UM POUQUINHO,\nQUE O NOIVO HÁ DE VIR.\n\nIGREJA, FOSTE COMPRADA\nCOM O SANGUE DE JESUS;\nIGREJA, FOSTE SELADA\nCOM O SANGUE DESSA CRUZ.', 'IGREJA, TU VAIS SUBIR, <bis>\nESPERA MAIS UM POUQUINHO,\nQUE O NOIVO HÁ DE VIR.\n\nIGREJA, FOSTE COMPRADA\nCOM O SANGUE DE JESUS;\nIGREJA, FOSTE SELADA<bis>\nCOM O SANGUE DESSA CRUZ.<bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (789, 'NA PRESENÇA DE JESUS', 'NA PRESENÇA DE JESUS', 'NA PRESENÇA DE JESUS\nNÃO HÁ DOR NEM PRANTO:\nFICO CHEIO DE ALEGRIA,\nCHEIO DO ESPÍRITO SANTO!\n\nCORO\nCRISTO VEM NA SUA GLÓRIA;\nQUERO IR TAMBÉM, QUERO IR TAMBÉM.\nQUERO PERTENCER À GLÓRIA\nQUE OS REMIDOS TEM.\nQUERO SUBIR COM JESUS\nPARA A MANSÃO DE ALÉM.\nVOU MORAR NA GLÓRIA .\nPARA SEMPRE, AMÉM. \n\nO DEVER DE TODO CRENTE\nÉ VIGIAR E ORAR.\nCRISTO VEM BUSCAR A IGREJA,\nOLHA QUE TU VAIS FICAR.\n\nCORO\nCRISTO VEM NA SUA GLÓRIA;\nQUERO IR TAMBÉM, QUERO IR TAMBÉM.\nQUERO PERTENCER À GLÓRIA\nQUE OS REMIDOS TEM.\nQUERO SUBIR COM JESUS\nPARA A MANSÃO DE ALÉM.\nVOU MORAR NA GLÓRIA .\nPARA SEMPRE, AMÉM. \n\nTODO CRENTE QUE VIGIA\nVIVE COM JESUS,\nFICA CHEIO DE ALEGRIA\nQUANDO MANIFESTA A LUZ.\n\nCORO\nCRISTO VEM NA SUA GLÓRIA;\nQUERO IR TAMBÉM, QUERO IR TAMBÉM.\nQUERO PERTENCER À GLÓRIA\nQUE OS REMIDOS TEM.\nQUERO SUBIR COM JESUS\nPARA A MANSÃO DE ALÉM.\nVOU MORAR NA GLÓRIA.\nPARA SEMPRE, AMÉM.', 'NA PRESENÇA DE JESUS<bis>\nNÃO HÁ DOR NEM PRANTO:<bis>\nFICO CHEIO DE ALEGRIA,<bis>\nCHEIO DO ESPÍRITO SANTO!<bis>\n\n<coro>\nCRISTO VEM NA SUA GLÓRIA;\nQUERO IR TAMBÉM, QUERO IR TAMBÉM.\nQUERO PERTENCER À GLÓRIA\nQUE OS REMIDOS TEM.\nQUERO SUBIR COM JESUS\nPARA A MANSÃO DE ALÉM.\nVOU MORAR NA GLÓRIA .\nPARA SEMPRE, AMÉM. \n\nO DEVER DE TODO CRENTE<bis>\nÉ VIGIAR E ORAR.<bis>\nCRISTO VEM BUSCAR A IGREJA,<bis>\nOLHA QUE TU VAIS FICAR.<bis>\n\n<coro>\nCRISTO VEM NA SUA GLÓRIA;\nQUERO IR TAMBÉM, QUERO IR TAMBÉM.\nQUERO PERTENCER À GLÓRIA\nQUE OS REMIDOS TEM.\nQUERO SUBIR COM JESUS\nPARA A MANSÃO DE ALÉM.\nVOU MORAR NA GLÓRIA .\nPARA SEMPRE, AMÉM. \n\nTODO CRENTE QUE VIGIA<bis>\nVIVE COM JESUS,<bis>\nFICA CHEIO DE ALEGRIA<bis>\nQUANDO MANIFESTA A LUZ.<bis>\n\n<coro>\nCRISTO VEM NA SUA GLÓRIA;\nQUERO IR TAMBÉM, QUERO IR TAMBÉM.\nQUERO PERTENCER À GLÓRIA\nQUE OS REMIDOS TEM.\nQUERO SUBIR COM JESUS\nPARA A MANSÃO DE ALÉM.\nVOU MORAR NA GLÓRIA.<bis>\nPARA SEMPRE, AMÉM. <bis>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (790, 'AQUELE QUE HABITA NO ESCONDERIJO', 'AQUELE QUE HABITA NO ESCONDERIJO', 'AQUELE QUE HABITA\nNO ESCONDERIJO DO ALTÍSSIMO\nÀ SOMBRA DO SENHOR, \nONIPOTENTE DESCANSARÁ.\n\nDIREI DO SENHOR, DIREI DO SENHOR,\nDIREI DO SENHOR: ELE É O MEU DEUS.\nDIREI DO SENHOR, DIREI DO SENHOR,\nDIREI DO SENHOR: ELE É O MEU DEUS.\n\nFINAL: AMÉM! AMÉM!', 'AQUELE QUE HABITA\nNO ESCONDERIJO DO ALTÍSSIMO\nÀ SOMBRA DO SENHOR, \nONIPOTENTE DESCANSARÁ.\n\nDIREI DO SENHOR, DIREI DO SENHOR,\nDIREI DO SENHOR: ELE É O MEU DEUS.\nDIREI DO SENHOR, DIREI DO SENHOR,\nDIREI DO SENHOR: ELE É O MEU DEUS.\n<final>AMÉM! AMÉM!', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (791, 'EU QUERO MAIS E MAIS DE CRISTO', 'EU QUERO MAIS E MAIS DE CRISTO', 'EU QUERO MAIS E MAIS DE CRISTO. \nEU QUERO MAIS DO SEU PODER. \nEU QUERO MAIS DA SUA PRESENÇA. \nEU QUERO MAIS DO SEU VIVER.\n\nMAIS, MAIS DE CRISTO,\nMAIS, MAIS DE CRISTO,\nMAIS DO SEU PURO E SANTO AMOR,\nMAIS DE TI MESMO, Ó SALVADOR.', 'EU QUERO MAIS E MAIS DE CRISTO. <bis>\nEU QUERO MAIS DO SEU PODER. <bis>\nEU QUERO MAIS DA SUA PRESENÇA. <bis>\nEU QUERO MAIS DO SEU VIVER.<bis>\n\nMAIS, MAIS DE CRISTO,\nMAIS, MAIS DE CRISTO,\nMAIS DO SEU PURO E SANTO AMOR,\nMAIS DE TI MESMO, Ó SALVADOR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (792, 'LOUVANDO A DEUS', 'LOUVANDO A DEUS', 'LOUVANDO A DEUS \nE CAINDO NA GRAÇA DE TODO O POVO.\n\nE TODOS OS DIAS ACRESCENTAVA O SENHOR\nÀ IGREJA AQUELES QUE SE HAVIAM DE SALVAR.\n\nREPETIR O HINO', 'LOUVANDO A DEUS <bis>\nE CAINDO NA GRAÇA DE TODO O POVO.<bis>\n\nE TODOS OS DIAS ACRESCENTAVA O SENHOR\nÀ IGREJA AQUELES QUE SE HAVIAM DE SALVAR.\n\n<repetir tipo=''O HINO''>', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (793, 'MESA PREPARADA', 'MESA PREPARADA', 'MESA PREPARADA, CABEÇA UNGIDA,\nCÁLICE TRANSBORDANDO,\nISTO É QUE É VIDA.\n\nCORO (2X)\nISTO É QUE É VIDA, VIDA COM JESUS.\nISTO É QUE É VIDA, CARREGANDO A CRUZ.\n\nJESUS CRISTO SALVA, CURA E BATIZA,\nCOM O ESPÍRITO SANTO,\nISTO É QUE É VIDA.\n\nCORO (2X)\nISTO É QUE É VIDA, VIDA COM JESUS.\nISTO É QUE É VIDA, CARREGANDO A CRUZ. \n\nCORAÇÃO ALEGRE, ESPADA ERGUIDA,\nPOR CRISTO LUTANDO,\nISTO É QUE É VIDA.\n\nCORO (2X)\nISTO É QUE É VIDA, VIDA COM JESUS.\nISTO É QUE É VIDA, CARREGANDO A CRUZ.', 'MESA PREPARADA, CABEÇA UNGIDA,\nCÁLICE TRANSBORDANDO,\nISTO É QUE É VIDA.<coro tipo=''2X''>\nISTO É QUE É VIDA, VIDA COM JESUS.\nISTO É QUE É VIDA, CARREGANDO A CRUZ.\n\nJESUS CRISTO SALVA, CURA E BATIZA,\nCOM O ESPÍRITO SANTO,\nISTO É QUE É VIDA.<coro tipo=''2X''>\nISTO É QUE É VIDA, VIDA COM JESUS.\nISTO É QUE É VIDA, CARREGANDO A CRUZ. \n\nCORAÇÃO ALEGRE, ESPADA ERGUIDA,\nPOR CRISTO LUTANDO,\nISTO É QUE É VIDA.<coro tipo=''2X''>\nISTO É QUE É VIDA, VIDA COM JESUS.\nISTO É QUE É VIDA, CARREGANDO A CRUZ.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (794, 'JESUS LIBERTOU', 'JESUS LIBERTOU', 'JESUS LIBERTOU MINH''ALMA DO MEU VIL PECADO.\nELE ESTÁ FALANDO A TI, QUER SALVAR, \nQUER TE PERDOAR.\n\nELE SE FEZ CARNE AQUI E NA CRUZ, \nPURO SE ENTREGOU; E VENCEU A MORTE \nPOR NÓS. PIEDOSO, VAI TE LIBERTAR, \nBASTA NO SEU NOME CRER E A ELE RECEBER.', 'JESUS LIBERTOU MINH''ALMA DO MEU VIL PECADO.\nELE ESTÁ FALANDO A TI, QUER SALVAR, \nQUER TE PERDOAR.\n\nELE SE FEZ CARNE AQUI E NA CRUZ, \nPURO SE ENTREGOU; E VENCEU A MORTE \nPOR NÓS. PIEDOSO, VAI TE LIBERTAR, \nBASTA NO SEU NOME CRER E A ELE RECEBER.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO hino (numero, nome, nome_pt, texto, texto_processado, coletanea_id, idioma, date_insert, date_update) VALUES (NULL, 'AQUILO QUE FUI NÃO SOU MAIS', 'AQUILO QUE FUI NÃO SOU MAIS', 'AQUILO QUE FUI NÃO SOU MAIS,\nNEM SOU TUDO O QUE DEVO SER;\nJÁ SOU PELA GRAÇA O QUE SOU\nE AO VÊ-LO ESTOU CERTO QUE VOU\nNA GLÓRIA DE CRISTO VIVER\n\nCORO\nMARANATA, MARANATA\nEM BREVE O SENHOR VOLTARÁ;\nMARANATA, MARANATA,\nELE MESMO VIRÁ NOS BUSCAR.\n\nEU MORTO PENSEI QUE VIVIA,\nJÁ VIVO E COM CRISTO MORRI;\nPARA ELE, ESTOU RESSUSCITADO,\nPARA O MUNDO, ESTOU CRUCIFICADO;\nMINHA VIDA EM JESUS ESCONDI. \n\nCORO\nMARANATA, MARANATA\nEM BREVE O SENHOR VOLTARÁ;\nMARANATA, MARANATA,\nELE MESMO VIRÁ NOS BUSCAR.\n\nMINH''ALMA GOZANDO RIQUEZAS,\nTESOUROS QUE O MUNDO NÃO DÁ,\nCAMINHA NA DOCE ESPERANÇA,\nDÁ VIDA EM ETERNA BONANÇA,\nNA GLÓRIA ONDE JESUS ESTÁ.\n\nCORO\nMARANATA, MARANATA\nEM BREVE O SENHOR VOLTARÁ;\nMARANATA, MARANATA,\nELE MESMO VIRÁ NOS BUSCAR.', 'AQUILO QUE FUI NÃO SOU MAIS,\nNEM SOU TUDO O QUE DEVO SER;\nJÁ SOU PELA GRAÇA O QUE SOU\nE AO VÊ-LO ESTOU CERTO QUE VOU\nNA GLÓRIA DE CRISTO VIVER\n\n<coro>\nMARANATA, MARANATA\nEM BREVE O SENHOR VOLTARÁ;\nMARANATA, MARANATA,\nELE MESMO VIRÁ NOS BUSCAR.\n\nEU MORTO PENSEI QUE VIVIA,\nJÁ VIVO E COM CRISTO MORRI;\nPARA ELE, ESTOU RESSUSCITADO,\nPARA O MUNDO, ESTOU CRUCIFICADO;\nMINHA VIDA EM JESUS ESCONDI. \n\n<coro>\nMARANATA, MARANATA\nEM BREVE O SENHOR VOLTARÁ;\nMARANATA, MARANATA,\nELE MESMO VIRÁ NOS BUSCAR.\n\nMINH''ALMA GOZANDO RIQUEZAS,\nTESOUROS QUE O MUNDO NÃO DÁ,\nCAMINHA NA DOCE ESPERANÇA,\nDÁ VIDA EM ETERNA BONANÇA,\nNA GLÓRIA ONDE JESUS ESTÁ.\n\n<coro>\nMARANATA, MARANATA\nEM BREVE O SENHOR VOLTARÁ;\nMARANATA, MARANATA,\nELE MESMO VIRÁ NOS BUSCAR.', 1, 'PT-BR', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
